# Lista ordenada de países para el UI: Chile PRIMERO, resto alfabético.
def paises_ordenados() -> list[tuple[str, str]]:
    """Devuelve [(codigo, nombre), ...] con Chile primero, luego el
    resto alfabéticamente. Al final "Otro país" como catch-all."""
    resto = sorted(
        [(k, v["nombre"]) for k, v in PAISES.items()
         if k not in ("CL", "OT")],
        key=lambda kv: kv[1])
    return [("CL", "Chile")] + resto + [("OT", "Otro país")]


def pais_por_defecto() -> str:
    """Código ISO del país por defecto guardado en QSettings, o Chile."""
    try:
        return settings_app().value("pais_default", "CL", type=str) or "CL"
    except Exception:
        return "CL"


def set_pais_por_defecto(codigo: str) -> None:
    try:
        settings_app().setValue("pais_default", codigo)
    except Exception:
        pass


def regiones_de_pais(codigo_pais: str) -> dict[str, list[tuple[str, float, float]]]:
    """Devuelve el dict de regiones para un país dado. Si no existe,
    devuelve las de Chile (por defecto)."""
    p = PAISES.get(codigo_pais)
    if p is None:
        p = PAISES["CL"]
    return p.get("regiones", {}) or {}


def ciudad_gps(region: str, ciudad: str,
               pais: str = "CL") -> Optional[tuple[float, float]]:
    """Devuelve (lat, lon) de una ciudad dentro de una región del país
    dado, o None si no la encuentra. Por defecto busca en Chile."""
    ciudades = regiones_de_pais(pais).get(region, [])
    for nombre, lat, lon in ciudades:
        if nombre.lower() == ciudad.lower():
            return (lat, lon)
    return None


# ─── Cliente Open-Meteo (pronóstico del clima) ────────────────────
# Los datos de Open-Meteo son CC BY 4.0: donde se muestren, va la
# atribución con enlace. Su API gratuita es para uso no comercial.
ATRIBUCION_CLIMA = "Datos del clima: Open-Meteo.com (CC BY 4.0)"
ATRIBUCION_CLIMA_HTML = ("Datos del clima: <a href='https://open-meteo.com/'>Open-Meteo.com</a> "
                         "(<a href='https://creativecommons.org/licenses/by/4.0/deed.es'>CC BY 4.0</a>)")
# (la misma, con los enlaces legibles sobre el fondo oscuro de las ventanas)
ATRIBUCION_CLIMA_HTML_OSCURO = ATRIBUCION_CLIMA_HTML.replace("<a ", "<a style='color:#8fb3d9;' ")
# Open-Meteo es gratis, sin registro, sin API key. Hasta 16 días de
# pronóstico. Se accede solo con urllib.request (sin dependencias).
# Documentación: https://open-meteo.com/en/docs

# Weather codes de Open-Meteo → (emoji, descripción)
WEATHER_CODES: dict[int, tuple[str, str]] = {
    0:  ("☀",  "Despejado"),
    1:  ("🌤",  "Mayormente despejado"),
    2:  ("⛅", "Parcialmente nublado"),
    3:  ("☁",  "Nublado"),
    45: ("🌫", "Niebla"),
    48: ("🌫", "Niebla con escarcha"),
    51: ("🌦", "Llovizna ligera"),
    53: ("🌦", "Llovizna moderada"),
    55: ("🌧", "Llovizna densa"),
    56: ("🌨", "Llovizna helada ligera"),
    57: ("🌨", "Llovizna helada densa"),
    61: ("🌧", "Lluvia ligera"),
    63: ("🌧", "Lluvia moderada"),
    65: ("🌧", "Lluvia intensa"),
    66: ("🌨", "Lluvia helada ligera"),
    67: ("🌨", "Lluvia helada intensa"),
    71: ("🌨", "Nieve ligera"),
    73: ("🌨", "Nieve moderada"),
    75: ("❄",  "Nieve intensa"),
    77: ("❄",  "Granos de nieve"),
    80: ("🌦", "Chubascos ligeros"),
    81: ("🌧", "Chubascos moderados"),
    82: ("⛈",  "Chubascos intensos"),
    85: ("🌨", "Chubascos de nieve ligeros"),
    86: ("❄",  "Chubascos de nieve intensos"),
    95: ("⛈",  "Tormenta"),
    96: ("⛈",  "Tormenta con granizo ligero"),
    99: ("⛈",  "Tormenta con granizo intenso"),
}


def clima_descripcion(codigo: int) -> tuple[str, str]:
    """Devuelve (emoji, descripción) para un weathercode de Open-Meteo."""
    return WEATHER_CODES.get(int(codigo), ("❓", "Sin datos"))


def clima_advertencias(clima: dict) -> list[str]:
    """Genera advertencias meteorológicas para una filmación según los
    datos del clima. Devuelve una lista de strings, vacía si no hay
    fenómenos preocupantes.

    Fenómenos considerados:
    - Lluvia / llovizna (weathercode 51-67, 80-82).
    - Nieve (71-77, 85-86).
    - Tormenta / granizo (95-99).
    - Ola de calor: temp_max > 32°C (crítica > 35°C).
    - Frío extremo: temp_min < 2°C.
    - Viento fuerte: > 30 km/h (problema para sonido, grúas).
    - Alta probabilidad de precipitación (> 60%).
    """
    if not clima or not isinstance(clima, dict):
        return []
    advertencias: list[str] = []
    codigo = int(clima.get("codigo", 0))
    temp_max = clima.get("temp_max", None)
    temp_min = clima.get("temp_min", None)
    prob_lluvia = clima.get("prob_lluvia", 0)
    viento_max = clima.get("viento_max", 0)

    # Precipitación (lluvia)
    if codigo in (51, 53, 55, 56, 57, 61, 63, 65, 66, 67,
                   80, 81, 82):
        if codigo >= 65 or codigo == 82:
            advertencias.append(
                "🌧 LLUVIA INTENSA — Considerá suspender exteriores. "
                "Protegé equipos y sonido.")
        else:
            advertencias.append(
                "🌧 Se espera lluvia — Lleva cubiertas para cámaras "
                "y micrófonos. Considerar plan B para exteriores.")

    # Nieve
    if codigo in (71, 73, 75, 77, 85, 86):
        advertencias.append(
            "❄ NIEVE — Complicaciones para movimiento del equipo, "
            "sonido y continuidad visual.")

    # Tormenta
    if codigo in (95, 96, 99):
        advertencias.append(
            "⛈ TORMENTA ELÉCTRICA — Peligro para equipo y personas. "
            "Suspender exteriores.")

    # Ola de calor
    if temp_max is not None:
        try:
            tmax = float(temp_max)
            if tmax >= 35:
                advertencias.append(
                    f"🔥 CALOR EXTREMO ({int(tmax)}°C) — Riesgo para "
                    "el equipo humano. Coordinar hidratación, sombra "
                    "y descansos frecuentes.")
            elif tmax >= 32:
                advertencias.append(
                    f"☀ Ola de calor ({int(tmax)}°C) — Prevé "
                    "hidratación, protección solar y cambios de "
                    "vestuario.")
        except (ValueError, TypeError):
            pass

    # Frío
    if temp_min is not None:
        try:
            tmin = float(temp_min)
            if tmin <= -5:
                advertencias.append(
                    f"🧊 FRÍO EXTREMO ({int(tmin)}°C mínimo) — "
                    "Riesgo de hipotermia. Ropa térmica obligatoria.")
            elif tmin <= 2:
                advertencias.append(
                    f"🥶 Frío intenso ({int(tmin)}°C mínimo) — "
                    "Considerar guantes, mantas y calefactores.")
        except (ValueError, TypeError):
            pass

    # Viento
    try:
        v = float(viento_max or 0)
        if v >= 60:
            advertencias.append(
                f"💨 VIENTO PELIGROSO ({int(v)} km/h) — Suspender "
                "vuelos de drone, evitar estructuras altas y grúas.")
        elif v >= 30:
            advertencias.append(
                f"💨 Viento fuerte ({int(v)} km/h) — Problemas para "
                "el sonido y trípodes. Considerar wind protection.")
    except (ValueError, TypeError):
        pass

    # Alta probabilidad de precipitación (aunque no llueva hoy)
    try:
        p = float(prob_lluvia or 0)
        if p >= 70 and codigo not in (51, 53, 55, 61, 63, 65, 80, 81,
                                        82, 95, 96, 99):
            advertencias.append(
                f"🌂 Alta probabilidad de lluvia ({int(p)}%) — "
                "Prepará plan B por si cambia el pronóstico.")
    except (ValueError, TypeError):
        pass

    return advertencias


def obtener_clima_open_meteo(lat: float, lon: float,
                              fecha_iso: str) -> Optional[dict]:
    """Consulta el clima para una coordenada y fecha específica en
    Open-Meteo. Devuelve un dict con:
      - temp_max, temp_min (°C)
      - codigo (weathercode)
      - prob_lluvia (0-100 %)
      - viento_max (km/h)
      - precipitacion (mm)

    Timeout corto (6 segundos) para no bloquear la UI si hay
    problemas de red. Devuelve None si falla.

    Solo devuelve datos si la fecha está dentro del rango de
    pronóstico (hasta 16 días adelante) o dentro de los pasados 90
    días (para consulta retrospectiva).
    """
    import urllib.request
    import urllib.parse
    import json as _json
    from datetime import date as _date, timedelta as _td

    try:
        fecha = _date.fromisoformat(fecha_iso)
    except Exception:
        return None
    hoy = _date.today()
    dias_dif = (fecha - hoy).days

    # Endpoint según si es futuro o pasado
    if dias_dif >= 0 and dias_dif <= 16:
        base = "https://api.open-meteo.com/v1/forecast"
    elif dias_dif < 0 and abs(dias_dif) <= 90:
        base = "https://archive-api.open-meteo.com/v1/archive"
    else:
        # Fuera de rango: no hay datos confiables
        return None

    params = {
        "latitude":  f"{lat:.4f}",
        "longitude": f"{lon:.4f}",
        "daily":     ("temperature_2m_max,temperature_2m_min,"
                       "weathercode,precipitation_probability_max,"
                       "windspeed_10m_max,precipitation_sum"),
        "timezone":  "auto",
        "start_date": fecha_iso,
        "end_date":   fecha_iso,
    }
    url = base + "?" + urllib.parse.urlencode(params)

    try:
        req = urllib.request.Request(
            url, headers={"User-Agent": "¡Acción! (guion audiovisual)"})
        with urllib.request.urlopen(req, timeout=6) as resp:
            data = _json.loads(resp.read().decode("utf-8"))
    except Exception:
        return None

    daily = data.get("daily", {})
    if not daily:
        return None

    def _first(k, default=None):
        arr = daily.get(k, [])
        if isinstance(arr, list) and arr:
            v = arr[0]
            return v if v is not None else default
        return default

    return {
        "temp_max":     _first("temperature_2m_max"),
        "temp_min":     _first("temperature_2m_min"),
        "codigo":       int(_first("weathercode", 0) or 0),
        "prob_lluvia":  _first("precipitation_probability_max", 0),
        "viento_max":   _first("windspeed_10m_max", 0),
        "precipitacion": _first("precipitation_sum", 0),
        "consultado":   _date.today().isoformat(),
    }


def clima_key(lat: float, lon: float, fecha_iso: str) -> str:
    """Clave de cache para el clima. Se redondea a 2 decimales para
    permitir que ubicaciones muy cercanas compartan cache."""
    return f"{lat:.2f},{lon:.2f}|{fecha_iso}"


def obtener_clima_con_cache(doc, locacion, fecha_iso: str,
                             forzar_refresh: bool = False) -> Optional[dict]:
    """Consulta el clima de una locación (con país/región/ciudad)
    para una fecha, usando el cache del documento para no golpear la
    API repetidamente.

    - Si la locación no tiene región y ciudad, devuelve None (no
      podemos determinar GPS).
    - Si hay cache <24h de antigüedad y no se pide forzar, devuelve
      el cache.
    - Sino consulta Open-Meteo y guarda en cache.
    """
    if not locacion:
        return None
    pais = getattr(locacion, "pais", "") or pais_por_defecto()
    reg = getattr(locacion, "region", "") or ""
    ciu = getattr(locacion, "ciudad", "") or ""
    gps = ciudad_gps(reg, ciu, pais)
    if gps is None:
        # Intentar parsear el campo gps si tiene "lat, lon"
        raw_gps = (getattr(locacion, "gps", "") or "").strip()
        if raw_gps:
            try:
                partes = raw_gps.replace(";", ",").split(",")
                if len(partes) >= 2:
                    gps = (float(partes[0].strip()),
                           float(partes[1].strip()))
            except (ValueError, TypeError):
                gps = None
    if gps is None:
        return None

    lat, lon = gps
    key = clima_key(lat, lon, fecha_iso)
    cache = getattr(doc, "clima_cache", None)
    if cache is None:
        doc.clima_cache = {}
        cache = doc.clima_cache

    # Chequear cache reciente
    if not forzar_refresh and key in cache:
        entry = cache[key]
        try:
            from datetime import date as _date
            consultado = _date.fromisoformat(
                entry.get("consultado", "1970-01-01"))
            antigüedad = (_date.today() - consultado).days
            if antigüedad <= 1:
                return entry
        except Exception:
            pass

    # Consultar API
    clima = obtener_clima_open_meteo(lat, lon, fecha_iso)
    if clima is not None:
        cache[key] = clima
    return clima


def resumen_clima(clima: dict) -> str:
    """Genera un resumen corto del clima estilo '☀ 24°/15° · 10% lluvia'."""
    if not clima or not isinstance(clima, dict):
        return ""
    emoji, _desc = clima_descripcion(int(clima.get("codigo", 0)))
    tmax = clima.get("temp_max")
    tmin = clima.get("temp_min")
    prob = clima.get("prob_lluvia", 0)
    partes = [emoji]
    if tmax is not None and tmin is not None:
        try:
            partes.append(f"{int(round(float(tmax)))}°/"
                          f"{int(round(float(tmin)))}°")
        except (ValueError, TypeError):
            pass
    try:
        p = int(float(prob or 0))
        if p > 0:
            partes.append(f"💧{p}%")
    except (ValueError, TypeError):
        pass
    return " ".join(partes)


def px(n: float) -> int:
    """Escala un tamaño de diseño (en pixeles lógicos) a la densidad
    de la pantalla actual (ver §0.5). En pantallas amplias devuelve n;
    en una HD 1366×768 devuelve ~0.8·n.
    Úsalo en CÓDIGO (setFixedSize, márgenes de layouts, íconos). En
    hojas de estilo escribe el valor literal: escalar_qss() lo ajusta."""
    if n <= 0:
        return 0 if n == 0 else int(round(n * densidad_ui()))
    return max(1, int(round(n * densidad_ui())))


def es_modo_invitado(widget) -> bool:
    """Sube por la jerarquía de padres buscando una VentanaPrincipal
    y devuelve su flag _modo_invitado: True cuando está en una sesión de
    colaboración con permiso de solo ver o de solo dejar notas (con
    permiso de edición, los diálogos se usan como siempre)."""
    w = widget
    while w is not None:
        if hasattr(w, "_modo_invitado"):
            return bool(w._modo_invitado)
        w = w.parent() if hasattr(w, "parent") else None
    return False


def es_modo_solo_lectura(widget) -> bool:
    """Sube por la jerarquía de padres buscando una VentanaPrincipal
    y devuelve su flag _modo_solo_lectura. Es True cuando el archivo
    tiene PIN y el usuario eligió abrirlo sin ingresarlo — puede ver
    todo, pero no editar ni ver los datos personales protegidos."""
    w = widget
    while w is not None:
        if hasattr(w, "_modo_solo_lectura"):
            return bool(w._modo_solo_lectura)
        w = w.parent() if hasattr(w, "parent") else None
    return False


def modo_readonly_activo(widget) -> tuple[bool, str]:
    """Devuelve (activo, motivo) según los flags del padre VP.
    - Invitado tiene prioridad sobre solo lectura.
    - motivo es un texto listo para mostrar al usuario."""
    if es_modo_invitado(widget):
        return True, "sesión de colaboración: tu permiso es solo ver o dejar notas"
    if es_modo_solo_lectura(widget):
        return True, "modo solo lectura (archivo protegido con PIN)"
    return False, ""


def aplicar_readonly_a_dialogo(dialogo) -> None:
    """Recorre todos los widgets del diálogo y los pone en solo lectura:
    - QLineEdit, QPlainTextEdit, QTextEdit → setReadOnly(True)
    - QSpinBox, QDoubleSpinBox, QComboBox → setEnabled(False)
    - QPushButton → deshabilitados salvo 'Cerrar', 'Cancelar', 'OK'
      (no 'Guardar', 'Agregar', 'Eliminar', 'Nuevo', etc.)
    - QCheckBox, QRadioButton → setEnabled(False)

    Agrega un banner arriba del diálogo indicando el modo lectura.

    Uso:
        if es_modo_invitado(self):
            aplicar_readonly_a_dialogo(self)
    """
    # Textos permitidos (los botones que sí quedan clickeables)
    OK_BOTONES = {
        "cerrar", "cancelar", "ok", "aceptar", "cancel", "close",
        "🔍", "ver", "abrir", "descargar",
        # emojis de acción "safe"
    }
    for w in dialogo.findChildren(QLineEdit):
        w.setReadOnly(True)
        # Feedback visual: fondo gris claro
        try:
            w.setStyleSheet(w.styleSheet() +
                            " QLineEdit { background: #131d2b; }")
        except Exception:
            pass
    for w in dialogo.findChildren(QPlainTextEdit):
        w.setReadOnly(True)
        try:
            w.setStyleSheet(w.styleSheet() +
                            " QPlainTextEdit { background: #131d2b; }")
        except Exception:
            pass
    try:
        for w in dialogo.findChildren(QTextEdit):
            w.setReadOnly(True)
    except Exception:
        pass
    for w in dialogo.findChildren(QSpinBox):
        w.setEnabled(False)
    try:
        for w in dialogo.findChildren(QDoubleSpinBox):
            w.setEnabled(False)
    except Exception:
        pass
    for w in dialogo.findChildren(QComboBox):
        w.setEnabled(False)
    for w in dialogo.findChildren(QCheckBox):
        w.setEnabled(False)
    try:
        for w in dialogo.findChildren(QRadioButton):
            w.setEnabled(False)
    except Exception:
        pass
    for w in dialogo.findChildren(QPushButton):
        # Botones "seguros" quedan habilitados
        texto = w.text().lower().strip()
        # Quitar emojis del texto para comparar mejor
        texto_limpio = "".join(c for c in texto if c.isalpha() or c.isspace()).strip()
        if not any(safe in texto_limpio for safe in OK_BOTONES):
            w.setEnabled(False)


def estilo_menu_claro(min_width: int = 140) -> str:
    """Fuente ÚNICA de verdad para el estilo de los menús claros.
    Garantiza que el texto SIEMPRE tenga color oscuro, evitando el bug
    de menús invisibles cuando un estilo local pisa al tema global sin
    declarar color. Cualquier QMenu claro debe usar esta función."""
    return f"""
        QMenu {{
            background: #1a2636; color: #e8edf4;
            border: 1px solid #26344a; padding: 4px; font-size: 10pt;
        }}
        QMenu::item {{
            background: transparent; color: #e8edf4;
            padding: 6px 18px 6px 10px;
            min-width: {min_width}px; border-radius: 3px;
        }}
        QMenu::item:selected {{ background: #ff8c1a; color: #241203; }}
        QMenu::item:disabled {{ color: #5a6b84; }}
        QMenu::separator {{
            height: 1px; background: #26344a; margin: 4px 8px;
        }}
    """


