def settings_app() -> QSettings:
    """Devuelve el QSettings de la app (recuerda preferencias del usuario)."""
    return QSettings("AccionFilmtools", "Accion")


def carpeta_documentos() -> str:
    """La carpeta Documentos del usuario (en Windows, también si OneDrive la
    movió). Si no se puede saber, la carpeta personal."""
    try:
        from PySide6.QtCore import QStandardPaths
        d = QStandardPaths.writableLocation(
            QStandardPaths.StandardLocation.DocumentsLocation)
        if d and Path(d).is_dir():
            return d
    except Exception:
        pass
    return str(Path.home())


def ruta_ultima_carpeta() -> str:
    """Última carpeta donde el usuario abrió o guardó un archivo (si ya no
    existe, o es la primera vez: Documentos)."""
    c = str(settings_app().value("ultima_carpeta", "") or "")
    try:
        if c and Path(c).is_dir():
            return c
    except OSError:
        pass
    return carpeta_documentos()


# ── 📁 La carpeta de los archivos de cada proyecto ──
# Al subir fotos, documentos o imágenes, el «Abrir» parte en Documentos;
# después, en la última carpeta que se usó EN ESE PROYECTO (se guarda en
# el .accion, como «~/…» si está dentro de la carpeta personal: así sirve
# también en otro computador y no lleva el nombre de usuario de Windows).
# Antes, las fotos de las fichas partían donde estuviera parado el programa
# (en Windows, a veces C:\Windows\System32).

def _ruta_compacta(ruta: str) -> str:
    try:
        p = Path(ruta).resolve()
        casa = Path.home().resolve()
        return "~/" + p.relative_to(casa).as_posix()
    except (ValueError, OSError, RuntimeError):
        return str(ruta)


def _ruta_expandida(texto: str) -> str:
    texto = (texto or "").strip()
    if texto == "~":
        return str(Path.home())
    if texto.startswith("~/"):
        return str(Path.home() / texto[2:])
    return texto


def _documento_de(obj) -> "Optional[Documento]":
    """El proyecto al que pertenece una ventana o un control."""
    w, vueltas = obj, 0
    while w is not None and vueltas < 40:
        if isinstance(w, Documento):
            return w
        for attr in ("documento", "doc", "_doc", "_documento"):
            d = getattr(w, attr, None)
            if isinstance(d, Documento):
                return d
        ed = getattr(w, "editor", None)
        if isinstance(getattr(ed, "documento", None), Documento):
            return ed.documento
        vp = getattr(w, "_vp", None)
        if vp is not None and vp is not w and isinstance(
                getattr(getattr(vp, "editor", None), "documento", None), Documento):
            return vp.editor.documento
        try:
            w = w.parentWidget() if hasattr(w, "parentWidget") else None
        except RuntimeError:
            return None
        vueltas += 1
    try:
        for top in QApplication.topLevelWidgets():
            if type(top).__name__ == "VentanaPrincipal":
                return top.editor.documento
    except Exception:
        pass
    return None


def carpeta_para_adjuntar(obj) -> str:
    """Dónde parte «adjuntar» (fotos, documentos, imágenes): la última carpeta
    usada en este proyecto; si todavía no hay, Documentos."""
    doc = _documento_de(obj)
    c = _ruta_expandida(getattr(doc, "carpeta_archivos", "") or "") if doc is not None else ""
    try:
        if c and Path(c).is_dir():
            return c
    except OSError:
        pass
    return carpeta_documentos()


def recordar_carpeta_adjuntos(obj, rutas) -> None:
    """Después de adjuntar: esa carpeta queda para la próxima vez, en este
    proyecto."""
    if isinstance(rutas, str):
        rutas = [rutas]
    rutas = [r for r in (rutas or []) if r]
    if not rutas:
        return
    p = Path(rutas[0])
    carpeta = p if p.is_dir() else p.parent
    doc = _documento_de(obj)
    if doc is not None:
        doc.carpeta_archivos = _ruta_compacta(str(carpeta))


def set_ruta_ultima_carpeta(ruta: str) -> None:
    """Guarda la carpeta para la próxima vez. Acepta tanto ruta de
    archivo como ruta de carpeta — siempre guarda la carpeta padre.
    """
    p = Path(ruta)
    # Si tiene extensión, asumimos que es un archivo y tomamos su carpeta
    if p.suffix or (p.exists() and p.is_file()):
        p = p.parent
    settings_app().setValue("ultima_carpeta", str(p))


