CLAVE_HOJA_OSCURA = "hoja_negra_modo_oscuro"     # 🌙 hoja negra y letra blanca (con «Modo oscuro»)
HOJA_OSCURA_BG, HOJA_OSCURA_FG = "#000000", "#ffffff"


def tema_es_oscuro(tema: str) -> bool:
    """¿El tema visual es oscuro? (su fondo principal es oscuro)."""
    pal = PALETAS.get(tema)
    if not pal:
        return tema in ("nova", "oscuro", "distraction")
    bg = pal.get("bg") or ("#0d1520" if tema == "nova" else "")
    if not bg:
        return tema in ("nova", "oscuro")
    return QColor(bg).lightness() < 110


def hoja_oscura_activa(tema: str = "") -> bool:
    """🌙 ¿La hoja del guion va negra con letra blanca? Se enciende con
    «🌙 Modo oscuro» (Estilo, o Configuración → Tema) y se apaga con «☀ Modo
    claro»; también en Configuración → Hoja del guion. Al imprimir y
    exportar, el guion sale siempre en papel blanco."""
    return str(settings_app().value(CLAVE_HOJA_OSCURA, "false")).lower() in ("true", "1", "si", "sí")


_CACHE_ICONOS: dict = {}


def icono_emoji(emoji: str) -> "QIcon":
    """Genera un QIcon dibujando un emoji — cada ventana con un
    ícono que dice qué es, sin archivos externos."""
    if emoji in _CACHE_ICONOS:
        return _CACHE_ICONOS[emoji]
    from PySide6.QtGui import (QIcon, QPixmap, QPainter, QFont,
                               QColor)
    pm = QPixmap(64, 64)
    pm.fill(QColor(0, 0, 0, 0))
    p = QPainter(pm)
    f = QFont("Segoe UI Emoji")
    f.setPixelSize(52)
    p.setFont(f)
    p.drawText(pm.rect(), Qt.AlignmentFlag.AlignCenter, emoji)
    p.end()
    ic = QIcon(pm)
    _CACHE_ICONOS[emoji] = ic
    return ic


def pintar_claqueta(p, x, y, lado) -> None:
    """La claqueta de ¡Acción!: un dibujo propio, hecho con trazos (sin
    fuentes ni emojis), de lado×lado px a partir de (x, y)."""
    from PySide6.QtCore import QPointF, QRectF, Qt
    from PySide6.QtGui import QColor, QPainter, QPainterPath, QPen, QPolygonF
    p.save()
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    p.translate(x, y)
    p.scale(lado / 64.0, lado / 64.0)
    p.setPen(Qt.PenStyle.NoPen)
    naranjo, blanco, cuerpo = QColor("#ff8c1a"), QColor("#f4f6f8"), QColor("#1f2b38")

    def franjas(caja: QRectF, forma: QPainterPath, inclinacion: float) -> None:
        p.save()
        p.setClipPath(forma)
        p.fillRect(caja, blanco)
        p.setBrush(naranjo)
        h, ancho = caja.height(), 7.5
        xi = caja.left() - h - ancho
        while xi < caja.right() + h:
            d = h * inclinacion
            p.drawPolygon(QPolygonF([QPointF(xi, caja.bottom()), QPointF(xi + d, caja.top()),
                                     QPointF(xi + d + ancho, caja.top()), QPointF(xi + ancho, caja.bottom())]))
            xi += 2 * ancho
        p.restore()

    # el cuerpo (la pizarra)
    p.setBrush(cuerpo)
    p.drawRoundedRect(QRectF(5, 27, 54, 32), 5, 5)
    # la franja fija, arriba del cuerpo
    caja = QRectF(5, 27, 54, 8.5)
    forma = QPainterPath()
    forma.addRoundedRect(QRectF(5, 27, 54, 32), 5, 5)
    banda = QPainterPath()
    banda.addRect(caja)
    franjas(caja, forma.intersected(banda), 0.75)
    p.setBrush(Qt.BrushStyle.NoBrush)
    p.setPen(QPen(QColor("#3b4a5c") if lado >= 30 else cuerpo, max(1.2, 0.9 * 64.0 / lado)))
    p.drawRoundedRect(QRectF(5, 27, 54, 32), 5, 5)
    p.setPen(Qt.PenStyle.NoPen)
    # el brazo, entreabierto (gira en la bisagra de la izquierda)
    p.save()
    p.translate(7, 25.5)
    p.rotate(-17)
    p.translate(-7, -25.5)
    brazo = QRectF(5, 16.5, 54, 8.5)
    forma_b = QPainterPath()
    forma_b.addRoundedRect(brazo, 2.2, 2.2)
    franjas(brazo, forma_b, -0.75)
    p.setBrush(Qt.BrushStyle.NoBrush)
    p.setPen(QPen(cuerpo, max(1.2, 0.9 * 64.0 / lado)))     # (borde: que se vea sobre fondo blanco)
    p.drawRoundedRect(brazo, 2.2, 2.2)
    p.setPen(Qt.PenStyle.NoPen)
    p.restore()
    # la bisagra
    p.setBrush(QColor("#9aa8b6"))
    p.drawEllipse(QPointF(7.6, 26.2), 2.9, 2.9)
    # «¡Acción!»: el triángulo de reproducir
    p.setBrush(naranjo)
    p.drawPolygon(QPolygonF([QPointF(42.5, 40.5), QPointF(42.5, 54.5), QPointF(54, 47.5)]))
    if lado >= 30:                                   # (los renglones de la pizarra, si se alcanzan a ver)
        p.setBrush(QColor("#4c5d71"))
        p.drawRoundedRect(QRectF(11, 41, 25, 3), 1.5, 1.5)
        p.drawRoundedRect(QRectF(11, 48.5, 17, 3), 1.5, 1.5)
    p.restore()


def icono_app() -> "QIcon":
    """Ícono principal: la claqueta de ¡Acción! (dibujo propio, igual al
    del .exe y del instalador) — el logo completo es un banner ancho y
    se aplasta ilegible en 16×16 px. Cada tamaño se dibuja a su medida."""
    if "__app__" in _CACHE_ICONOS:
        return _CACHE_ICONOS["__app__"]
    from PySide6.QtGui import QIcon, QImage, QPainter, QPixmap, QColor
    ic = QIcon()
    for lado in (16, 20, 24, 32, 40, 48, 64, 128, 256):
        img = QImage(lado, lado, QImage.Format.Format_ARGB32_Premultiplied)
        img.fill(QColor(0, 0, 0, 0))
        p = QPainter(img)
        pintar_claqueta(p, 0, 0, lado)
        p.end()
        ic.addPixmap(QPixmap.fromImage(img))
    _CACHE_ICONOS["__app__"] = ic
    return ic


class _AjusteBarraDesplazable(QObject):
    """Mantiene una barra de botones a su ancho natural dentro de un
    QScrollArea: si no cabe, aparece desplazamiento horizontal en vez
    de apretar (y cortar) los textos de los botones."""

    def __init__(self, sc, barra):
        super().__init__(sc)
        self._sc, self._barra = sc, barra
        sc.installEventFilter(self)
        QTimer.singleShot(0, self.ajustar)

    def ajustar(self) -> None:
        try:
            lay = self._barra.layout()
            if lay is not None:
                self._barra.setMinimumWidth(lay.sizeHint().width())
            alto = self._barra.sizeHint().height()
            if self._barra.minimumWidth() > self._sc.viewport().width() + 1:
                alto += self._sc.horizontalScrollBar().sizeHint().height()
            if self._sc.height() != alto:
                self._sc.setFixedHeight(alto)
        except RuntimeError:
            pass                       # widget ya destruido

    def eventFilter(self, obj, ev) -> bool:
        if ev.type() in (QEvent.Type.Resize, QEvent.Type.Show,
                         QEvent.Type.StyleChange, QEvent.Type.FontChange):
            QTimer.singleShot(0, self.ajustar)
        return False


def barra_desplazable(barra: "QWidget", fondo: str = "") -> "QScrollArea":
    """Envuelve una barra de botones para que nunca se apriete."""
    sc = QScrollArea()
    sc.setWidget(barra)
    sc.setWidgetResizable(True)
    sc.setFrameShape(QFrame.Shape.NoFrame)
    sc.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
    sc.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
    sc.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
    if fondo:
        sc.setStyleSheet(f"QScrollArea {{ background: {fondo}; border: none; }}")
    if fondo in ("", "transparent"):
        sc.viewport().setAutoFillBackground(False)
        barra.setAutoFillBackground(False)
    sc._ajuste_barra = _AjusteBarraDesplazable(sc, barra)
    return sc


def habilitar_snap(w, emoji: str = "") -> None:
    """Convierte un diálogo grande en ventana normal con botones de
    minimizar/maximizar. Windows solo permite anclar con Win+←/→
    (media pantalla) a ventanas con esos botones."""
    try:
        w.setWindowFlags(
            Qt.WindowType.Window
            | Qt.WindowType.WindowMinimizeButtonHint
            | Qt.WindowType.WindowMaximizeButtonHint
            | Qt.WindowType.WindowCloseButtonHint)
        if emoji:
            w.setWindowIcon(icono_emoji(emoji))
    except Exception:
        pass


def _traduccion_tema(tema: str) -> dict[str, str]:
    pal = PALETAS.get(tema, PALETAS["nova"])
    return {hexn: pal.get(sem, hexn)
            for hexn, sem in TOKENS_NOVA.items()}


_PATRONES_TEMA: dict = {}


def traducir_qss(qss: str, tema: str) -> str:
    """Traduce un stylesheet escrito en paleta Nova al tema dado."""
    if tema == "nova" or not qss:
        return qss
    if tema not in _PATRONES_TEMA:             # (se arma una vez por tema, no una vez por widget)
        tabla = _traduccion_tema(tema)
        _PATRONES_TEMA[tema] = (tabla, re.compile("|".join(re.escape(k) for k in sorted(tabla, reverse=True)),
                                                  re.IGNORECASE))
    tabla, patron = _PATRONES_TEMA[tema]
    return patron.sub(lambda m: tabla[m.group(0).lower()], qss)


def aplicar_qss_tematizado(w, qss: str) -> None:
    """setStyleSheet() que respeta el tema activo: guarda la versión
    canónica (Nova) y aplica la traducida. Útil para widgets que
    cambian su estilo después de creados."""
    w.setProperty("_qss_nova", qss)
    w.setStyleSheet(traducir_qss(qss, TEMA_ACTUAL)
                    if TEMA_ACTUAL != "nova" else qss)


def retematizar_widgets(tema: str) -> int:
    """Traduce el stylesheet de TODOS los widgets vivos. Guarda la
    versión canónica (Nova) en una propiedad para que los cambios
    de tema sean siempre exactos e reversibles."""
    app = QApplication.instance()
    if app is None:
        return 0
    n = 0
    for w in app.allWidgets():
        try:
            canon = w.property("_qss_nova")
            ss = w.styleSheet()
            if canon is None:
                if not ss:
                    continue
                bajo = ss.lower()
                if not any(t in bajo for t in TOKENS_NOVA):
                    continue      # no usa la paleta (ej: hoja)
                canon = ss
                w.setProperty("_qss_nova", canon)
            # (ya escalada a la pantalla: así no se aplica dos veces, una al traducir y otra al escalar)
            nuevo = escalar_qss(traducir_qss(str(canon), tema))
            if nuevo != ss:
                w.setStyleSheet(nuevo)
                n += 1
        except Exception:
            continue
    return n


_EXEC_DIALOGO_QT = QDialog.exec


def _exec_y_soltar(self, *args, **kwargs):
    """QDialog.exec() de las ventanas de ¡Acción!: al cerrarse, la ventana
    se borra (cuando termina lo que la abrió). Antes quedaban vivas,
    escondidas, y cada cambio de tema las volvía a pintar todas."""
    r = _EXEC_DIALOGO_QT(self, *args, **kwargs)
    try:
        if (type(self).__module__ == __name__ and self.parent() is not None
                and not self.testAttribute(Qt.WidgetAttribute.WA_DeleteOnClose)
                and not any(h.isRunning() for h in self.findChildren(QThread))):
            self.deleteLater()                     # (diferido: quien la abrió todavía puede leerla)
    except RuntimeError:
        pass
    return r


QDialog.exec = _exec_y_soltar


def limpiar_ventanas_cerradas(padre=None) -> int:
    """Borra los diálogos que ya se cerraron y que nadie va a volver a usar
    (ningún pedazo del programa los guarda). Quedaban vivos, escondidos, y
    cada cambio de tema los volvía a pintar: después de abrir y cerrar
    unas cuantas ventanas, cambiar de tema tardaba diez segundos o más."""
    import sys as _sys
    app = QApplication.instance()
    if app is None:
        return 0
    sonda = QDialog(padre) if padre is not None else None
    candidatos = [w for w in app.topLevelWidgets()
                  if isinstance(w, QDialog) and not w.isVisible() and w.parent() is not None]
    base = None
    for w in candidatos:
        if w is sonda:
            base = _sys.getrefcount(w) - 1        # (lo que cuenta uno que nadie guarda)
    n = 0
    if base is not None:
        for w in candidatos:
            if w is sonda or _sys.getrefcount(w) > base:
                continue
            if w.testAttribute(Qt.WidgetAttribute.WA_DeleteOnClose):
                continue
            if any(h.isRunning() for h in w.findChildren(QThread)):
                continue
            w.setParent(None)                     # (sin padre ni referencias: se va ahora mismo)
            n += 1
    del candidatos
    if sonda is not None:
        sonda.setParent(None)
        del sonda
    return n


class TraductorTemas(QObject):
    """Al mostrarse un widget nuevo con estilo Nova incrustado y el
    tema activo NO es Nova, lo traduce al vuelo. Cubre diálogos y
    ventanas creados después del cambio de tema."""

    def eventFilter(self, obj, event) -> bool:
        if (event.type() == QEvent.Type.Show
                and TEMA_ACTUAL != "nova"
                and isinstance(obj, QWidget)):
            try:
                if obj.property("_qss_nova") is None:
                    ss = obj.styleSheet()
                    if ss and any(t in ss.lower()
                                  for t in TOKENS_NOVA):
                        obj.setProperty("_qss_nova", ss)
                        obj.setStyleSheet(
                            traducir_qss(ss, TEMA_ACTUAL))
            except Exception:
                pass
        return super().eventFilter(obj, event)


