# ═══════════════════════════════════════════════════════════════════════
# §3  TRANSFORMACIÓN DE CASO
# ═══════════════════════════════════════════════════════════════════════

def aplicar_caso_a_texto(elem: Elem, texto: str) -> str:
    caso = CASO[elem]
    if caso == Caso.MAYUSCULAS:
        return texto.upper()
    if caso == Caso.MINUSCULAS:
        return texto.lower()
    if caso == Caso.FRASE:
        return _capitalizar_frase(texto)
    return texto


def _capitalizar_frase(texto: str) -> str:
    """Inicio de oración en mayúscula. Si el texto viene TODO en mayúsculas
    (era un encabezado o un personaje), el resto pasa a minúscula; si no, se
    respeta lo escrito: nombres propios («Nadie vino, Ana»), siglas y un
    cartel en mayúsculas dentro de la acción («TALLER CERRADO»)."""
    if not texto:
        return texto
    letras = [c for c in texto if c.isalpha()]
    todo_mayus = bool(letras) and all(c.isupper() for c in letras)
    out: list[str] = []
    cap_next = True
    for c in texto:
        if c.isalpha():
            out.append(c.upper() if cap_next else (c.lower() if todo_mayus else c))
            cap_next = False
        else:
            out.append(c)
            if c in ".!?":
                cap_next = True
    return "".join(out)


def transformar_caracter(elem: Elem, texto_previo: str, caracter: str) -> str:
    """Transforma un carácter al ser tipeado, según el caso del elemento."""
    if not caracter:
        return caracter

    caso = CASO[elem]

    if caso == Caso.MAYUSCULAS:
        return caracter.upper()
    if caso == Caso.MINUSCULAS:
        return caracter.lower()

    # FRASE
    if not caracter.isalpha():
        return caracter
    stripped = texto_previo.rstrip()
    if not stripped:
        return caracter.upper()
    if stripped[-1] in ".!?":
        return caracter.upper()
    return caracter


