def ruta_diccionario() -> Path:
    """Busca el diccionario español en la carpeta del ejecutable
    (o del script accion.py). Prueba varios nombres típicos y
    subcarpetas típicas: raíz, `sistema/`, `diccionarios/`,
    `recursos/`, `data/`."""
    # Base del script/ejecutable (instalado: la carpeta del programa y la
    # de sus archivos internos, «_internal», donde lo deja PyInstaller)
    import sys as _sys
    bases: list[Path] = []
    if getattr(_sys, "frozen", False):
        bases.append(Path(_sys.executable).resolve().parent)     # (instalado: …\Accion\sistema)
        if getattr(_sys, "_MEIPASS", ""):
            bases.append(Path(_sys._MEIPASS))
    if "__file__" in globals():
        bases.append(Path(__file__).resolve().parent)
    if not bases:
        bases.append(Path.cwd())
    base = bases[0]
    # Todos los nombres que hemos usado o que el usuario puede tener
    nombres = [
        "es_palabras.txt.gz",   # el más común (nombre real del archivo)
        "es_palabras_txt.gz",   # formato viejo (legado)
        "es_palabras.txt",      # sin comprimir
        "es_palabras.gz",
    ]
    subcarpetas = [
        "",              # raíz
        "sistema",       # nueva convención
        "diccionario",   # (la carpeta con el diccionario RLA-ES y su licencia)
        "diccionarios",  # convención vieja
        "recursos",
        "data",
        "resources",
    ]
    candidatos: list[Path] = []
    for base_ in bases:
        for sub in subcarpetas:
            carpeta = base_ / sub if sub else base_
            for nom in nombres:
                candidatos.append(carpeta / nom)
    existentes = [p for p in candidatos if p.exists()]
    # Si hay varios, el nuevo (RLA-ES, con tildes: empieza con «# ¡Acción!») gana al antiguo
    for p in existentes:
        if _es_diccionario_nuevo(p):
            return p
    if existentes:
        return existentes[0]
    # Ninguno encontrado: devolver la ruta que esperamos (para el
    # mensaje de error) — priorizar la nueva convención (sistema/).
    return base / "sistema" / "es_palabras.txt.gz"


def _es_diccionario_nuevo(ruta: Path) -> bool:
    """¿Es el diccionario RLA-ES (con tildes y eñes)? Empieza con «# ¡Acción!»."""
    try:
        if str(ruta).endswith(".gz"):
            with gzip.open(ruta, "rt", encoding="utf-8") as f:
                return f.readline().startswith("# ¡Acción!")
        with open(ruta, encoding="utf-8") as f:
            return f.readline().startswith("# ¡Acción!")
    except Exception:
        return False


