# ── Utilidades de imagen ───────────────────────────────────────────────

def comprimir_imagen_a_b64(ruta: str, max_lado: int = 1600,
                           calidad: int = 85) -> str:
    """Lee imagen del disco, la escala si excede max_lado, y la devuelve
    como JPEG base64. Sin dependencias externas (usa QImage).
    """
    img = QImage(ruta)
    if img.isNull():
        return ""
    w, h = img.width(), img.height()
    if max(w, h) > max_lado:
        if w >= h:
            img = img.scaledToWidth(max_lado, Qt.TransformationMode.SmoothTransformation)
        else:
            img = img.scaledToHeight(max_lado, Qt.TransformationMode.SmoothTransformation)
    buf = QByteArray()
    qbuf = QBuffer(buf)
    qbuf.open(QBuffer.OpenModeFlag.WriteOnly)
    img.save(qbuf, "JPEG", calidad)
    return base64.b64encode(buf.data()).decode("ascii")


def b64_a_qpixmap(b64: str, max_lado: int = 0) -> QPixmap:
    """Decodifica un base64 (JPEG/PNG) a QPixmap, redimensionando si max_lado > 0."""
    if not b64:
        return QPixmap()
    try:
        data = base64.b64decode(b64.encode("ascii"))
    except Exception:
        return QPixmap()
    img = QImage.fromData(data)
    if img.isNull():
        return QPixmap()
    if max_lado > 0 and max(img.width(), img.height()) > max_lado:
        if img.width() >= img.height():
            img = img.scaledToWidth(max_lado, Qt.TransformationMode.SmoothTransformation)
        else:
            img = img.scaledToHeight(max_lado, Qt.TransformationMode.SmoothTransformation)
    return QPixmap.fromImage(img)


