@dataclass
class Foto:
    """Una foto en una ficha: imagen en base64 + título + comentario libre."""
    datos: str = ""        # base64 JPEG
    comentario: str = ""
    titulo: str = ""       # Nombre/título de la foto (ej: "Carnet de identidad")


@dataclass
class Disponibilidad:
    """Días marcados como hábiles/inhábiles. Fechas en formato ISO (YYYY-MM-DD)."""
    habiles: list[str] = field(default_factory=list)
    inhabiles: list[str] = field(default_factory=list)


@dataclass
class Ficha:
    """Personaje + actor que lo interpreta."""
    # ── Datos del PERSONAJE ──
    personaje: str = ""
    genero: str = ""
    orientacion: str = ""
    nacionalidad: str = ""
    profesion: str = ""
    religion: str = ""
    edad: str = ""
    etnia: str = ""
    biografia: str = ""
    # ── Datos del ACTOR / ACTRIZ ──
    actor_nombre: str = ""
    actor_telefono: str = ""
    actor_correo: str = ""
    actor_notas: str = ""
    actor_valor_dia: str = ""
    emergencia_telefono: str = ""   # N° de contacto de emergencia
    actor_dias: str = ""
    # ── Salud / dietéticos ──
    alergias: bool = False
    alergias_detalle: str = ""
    movilidad_reducida: bool = False
    movilidad_detalle: str = ""
    alimentacion: str = "Omnívoro"      # Omnívoro / Vegetariano / Vegano / Otro
    # ── Voz TTS para lectura de diálogos ──
    # Se asigna una voz al personaje para que al usar «Leer escena
    # en voz alta» cada uno hable con su timbre. Valores:
    # "auto" (usa la del sistema), "femenina", "masculina", o el
    # nombre exacto de la voz instalada.
    voz_tts: str = "auto"
    # Apariencia en pantalla: guía para casting, maquillaje y
    # continuidad de vestuario entre jornadas
    descripcion_fisica: str = ""
    vestuario: str = ""
    # ── Documentos adjuntos (PDF/JPG/PNG en base64) ──
    contrato_nombre: str = ""
    contrato_datos: str = ""
    boleta_nombre: str = ""
    boleta_datos: str = ""
    documentos: list[DocumentoAdjunto] = field(default_factory=list)
    boletas: list[DocumentoAdjunto] = field(default_factory=list)
    transporte_dia: str = ""      # costo transporte $/día
    alimentacion_dia: str = ""    # costo alimentación $/día
    # ── Fotos + disponibilidad ──
    fotos: list[Foto] = field(default_factory=list)
    disponibilidad: Disponibilidad = field(default_factory=Disponibilidad)


@dataclass
class FichaEscena:
    """Ficha de análisis dramático para una escena. Ayuda al guionista
    a pensar cada escena en profundidad: qué quiere el protagonista,
    qué obstáculo enfrenta, qué se dice en el subtexto vs lo verbal,
    qué referencias visuales inspiran el rodaje."""
    numero: int = 0                        # Número de la escena (1-indexed)
    encabezado: str = ""                   # Copia del encabezado para referencia
    proposito: str = ""                    # ¿Para qué está esta escena en el guion?
    objetivo_protagonista: str = ""        # ¿Qué quiere lograr el personaje?
    obstaculo: str = ""                    # ¿Qué se lo impide?
    subtexto: str = ""                     # ¿Qué se dice sin decir?
    tono: str = ""                         # Cómico, dramático, tenso, íntimo...
    referencias: str = ""                  # Películas, fotos, canciones que inspiran
    notas_direccion: str = ""              # Anotaciones para el director


@dataclass
class DocumentoAdjunto:
    """Documento adjunto genérico de una ficha: seguro, permiso
    municipal, autorización de menores, cesión de derechos — lo
    que el productor necesite. Se guarda en base64 dentro del
    .accion para que viaje con el proyecto."""
    nombre: str = ""      # nombre del archivo (ej: seguro.pdf)
    etiqueta: str = ""    # descripción (ej: "Seguro de equipo")
    datos: str = ""       # contenido en base64


@dataclass
class Locacion:
    nombre: str = ""
    ubicacion: str = ""
    gps: str = ""
    detalles: str = ""
    # 🏥 Hospital o centro de salud más cercano (nombre, dirección, teléfono
    # de urgencias): va en la Call Sheet de cada jornada en esta locación.
    hospital: str = ""
    precio_dia: str = ""
    dias: str = ""
    # País, Región y Ciudad. Con estos tres campos se consulta el
    # clima automáticamente. `pais` es código ISO ("CL", "AR", etc.).
    # Por defecto: código de país configurado por el usuario (Chile
    # sale primero en todos los selectores).
    pais: str = ""
    region: str = ""
    ciudad: str = ""
    # ── Documentos adjuntos (PDF/JPG/PNG en base64) ──
    contrato_nombre: str = ""
    contrato_datos: str = ""
    boleta_nombre: str = ""
    boleta_datos: str = ""
    documentos: list[DocumentoAdjunto] = field(default_factory=list)
    boletas: list[DocumentoAdjunto] = field(default_factory=list)
    transporte_dia: str = ""      # costo transporte $/día
    alimentacion_dia: str = ""    # costo alimentación $/día
    fotos: list[Foto] = field(default_factory=list)
    disponibilidad: Disponibilidad = field(default_factory=Disponibilidad)


@dataclass
class Equipamiento:
    nombre: str = ""
    modelo: str = ""
    proveedor: str = ""
    contacto: str = ""
    cantidad: str = ""
    precio_dia: str = ""
    dias: str = ""
    notas: str = ""
    # ── Documentos adjuntos (PDF/JPG/PNG en base64) ──
    contrato_nombre: str = ""
    contrato_datos: str = ""
    boleta_nombre: str = ""
    boleta_datos: str = ""
    documentos: list[DocumentoAdjunto] = field(default_factory=list)
    boletas: list[DocumentoAdjunto] = field(default_factory=list)
    transporte_dia: str = ""      # costo transporte $/día
    alimentacion_dia: str = ""    # costo alimentación $/día
    fotos: list[Foto] = field(default_factory=list)
    disponibilidad: Disponibilidad = field(default_factory=Disponibilidad)


@dataclass
class Tecnico:
    nombre: str = ""
    rol: str = ""
    contacto: str = ""            # legado — reemplazado por telefono/correo
    telefono: str = ""
    correo: str = ""
    emergencia_telefono: str = ""   # N° contacto de emergencia
    precio_dia: str = ""
    dias: str = ""
    alimentacion: str = ""
    notas: str = ""
    # ── Documentos adjuntos (PDF/JPG/PNG en base64) ──
    contrato_nombre: str = ""
    contrato_datos: str = ""
    boleta_nombre: str = ""
    boleta_datos: str = ""
    documentos: list[DocumentoAdjunto] = field(default_factory=list)
    boletas: list[DocumentoAdjunto] = field(default_factory=list)
    transporte_dia: str = ""      # costo transporte $/día
    alimentacion_dia: str = ""    # costo alimentación $/día
    fotos: list[Foto] = field(default_factory=list)
    disponibilidad: Disponibilidad = field(default_factory=Disponibilidad)


def tel_correo_de_tecnico(tec) -> tuple[str, str]:
    """Devuelve (teléfono, correo) de un técnico, con compatibilidad
    hacia atrás: si el proyecto es antiguo y solo tiene el campo
    `contacto`, lo clasifica según contenga '@' o no."""
    if tec is None:
        return "", ""
    tel = (getattr(tec, "telefono", "") or "").strip()
    cor = (getattr(tec, "correo", "") or "").strip()
    legado = (getattr(tec, "contacto", "") or "").strip()
    if legado and not tel and not cor:
        if "@" in legado:
            cor = legado
        else:
            tel = legado
    return tel, cor


