# ── Bloques y Documento ────────────────────────────────────────────────

@dataclass
class Bloque:
    elem: Elem
    texto: str = ""
    tags: list[dict] = field(default_factory=list)
    # Formatos por-carácter aplicados manualmente por el usuario:
    # negrita, subrayado, color de texto, color de fondo (destacado).
    # Cada elemento es un dict con las claves:
    #   {"desde": int, "hasta": int,
    #    "negrita": bool, "subrayado": bool,
    #    "color": str (hex "#rrggbb"), "fondo": str (hex "#rrggbb")}
    # Solo se guardan los que difieren del default del tipo de bloque.
    formatos: list[dict] = field(default_factory=list)
    # Número de escena fijado cuando la numeración está BLOQUEADA
    # (solo en encabezados). "" = se numera en orden. Ej: "12", "12A".
    numero: str = ""
    # Diálogo doble: en un bloque PERSONAJE, True = este personaje habla
    # AL MISMO TIEMPO que el anterior (se imprime en dos columnas).
    doble: bool = False

    def copy(self) -> "Bloque":
        return Bloque(self.elem, self.texto,
                      [dict(t) for t in self.tags],
                      [dict(f) for f in self.formatos],
                      self.numero, self.doble)


@dataclass
class Beat:
    """Tarjeta de la Pizarra de beats (pizarra de planificación narrativa).
    Cada tarjeta tiene posición y dimensión libre en la pizarra,
    color para agrupar visualmente, título corto y descripción larga.
    Las conexiones (lista de índices de otras tarjetas) representan el
    orden o relación que el guionista quiere mostrar con flechas.
    """
    titulo: str = "Nueva tarjeta"
    descripcion: str = ""
    color: str = "#5b6ef5"     # azul por defecto (paleta cinematográfica)
    x: float = 50.0            # posición x en la pizarra (coords de scene)
    y: float = 50.0
    w: float = 180.0
    h: float = 120.0
    conexiones: list[int] = field(default_factory=list)  # legacy (índices)
    # Conexiones nuevas con lados origen→destino. Formato:
    # [{"destino": int, "lado_origen": "top|right|bot|left",
    #   "lado_destino": "top|right|bot|left"}]
    conexiones_lados: list[dict] = field(default_factory=list)


@dataclass
class FotoBeat:
    """Imagen colocada en la Pizarra de beats, escalable desde la esquina
    inferior izquierda y con un comentario que aparece debajo.
    Puede tener conexiones de flecha hacia tarjetas u otras fotos.

    Para que la foto viaje al invitado en colaboración, se guardan
    los datos base64 embebidos en `datos_b64`. El `path` se mantiene
    para retrocompatibilidad con archivos viejos que solo tenían la
    ruta local (esas fotos no viajarán al invitado hasta que se
    re-agreguen)."""
    path: str = ""             # ruta absoluta a la imagen en disco (legacy)
    datos_b64: str = ""        # foto embebida en base64 JPEG (viaja al invitado)
    x: float = 60.0
    y: float = 60.0
    w: float = 220.0
    h: float = 160.0
    comentario: str = ""
    # Conexiones salientes. Formato igual que Beat.conexiones_lados pero
    # con destino_tipo para saber si apunta a tarjeta o a foto:
    # [{"destino": int, "destino_tipo": "tarjeta"|"foto",
    #   "lado_origen": str, "lado_destino": str}]
    conexiones_lados: list[dict] = field(default_factory=list)


@dataclass
class Documento:
    bloques: list[Bloque] = field(
        default_factory=lambda: [Bloque(Elem.ACCION)]
    )
    # ── Fichas de producción ──────────────────────────────────────────
    fichas:       dict[str, Ficha]      = field(default_factory=dict)
    locaciones:   dict[str, Locacion]   = field(default_factory=dict)
    equipamiento: list[Equipamiento]    = field(default_factory=list)
    tecnicos:     list[Tecnico]         = field(default_factory=list)
    jornadas:     list[Jornada]         = field(default_factory=list)
    # ── Preproducción narrativa ───────────────────────────────────────
    escaleta:     list[str]             = field(default_factory=list)
    premisa:      str                   = ""
    # Orientación del papel para la EXPORTACIÓN/IMPRESIÓN. La hoja
    # del editor siempre es vertical (formato profesional de guion);
    # esto define cómo se genera el PDF/impresión.
    orientacion_general: str = "vertical"   # "vertical" | "horizontal"
    # Páginas específicas en horizontal (1-based), útil para
    # storyboards, plantas de cámara, tablas de callsheet, etc.
    paginas_horizontales: list[int] = field(default_factory=list)
    beats:        list["Beat"]          = field(default_factory=list)
    fotos_beatboard: list["FotoBeat"]   = field(default_factory=list)
    # ── Colaboración (metadatos del proyecto) ─────────────────────────
    autor_id:     str = ""               # nombre del guionista actual
    coautores:    str = ""               # nombres separados por coma
    comentarios:  str = ""               # notas del equipo (firmadas)
    colab_max_invitados: int = 8         # máximo en sesión local
    colab_permisos: dict[str, bool] = field(default_factory=lambda: {
        "escribir":         True,
        "fichas":           True,
        "etiquetar":        True,
        "formato":          False,
        "exportar":         True,
        "produccion":       False,
    })
    # ── Protección con PIN ────────────────────────────────────────────
    # Hash SHA-256 del PIN (o cadena vacía si no hay PIN). Cuando está
    # presente, se pide al abrir el archivo y al conectarse por colab.
    pin_hash:     str = ""
    # Cache de clima consultado a Open-Meteo. Estructura:
    # { "lat,lon|YYYY-MM-DD": {temp_max, temp_min, codigo, prob_lluvia,
    #                          viento_max, precipitacion, consultado} }
    clima_cache:  dict = field(default_factory=dict)
    # Moneda del proyecto (código ISO 4217). Todos los costos se
    # muestran en esta moneda. Por defecto: CLP (peso chileno).
    moneda:       str  = "CLP"
    # País por defecto para nuevas locaciones de este proyecto.
    pais_default: str  = "CL"
    # Categorías de tags CUSTOM creadas por el usuario para este proyecto.
    # Cada elemento es un dict {"id", "nombre", "emoji"}. Se persisten
    # en el .accion para que cada proyecto tenga sus propias categorías.
    categorias_custom: list[dict] = field(default_factory=list)
    # Flujo de ENTER personalizado por proyecto: {id_elem: id_elem}.
    # Solo guarda las diferencias respecto del flujo estándar
    # (SIGUIENTE_ENTER). Se persiste dentro del archivo .accion.
    flujo_enter: dict = field(default_factory=dict)
    # Estado de producción por escena: clave = índice 1-based de la
    # escena (ordenada por aparición). Valor: dict con "estado" (str)
    # y "porcentaje" (int 0-100).
    # Estados posibles:
    #   "sin_grabar", "parcialmente_grabada", "grabada",
    #   "sin_editar", "parcialmente_editada", "editada",
    #   "en_post", "post_producida", "terminada"
    estados_produccion: dict = field(default_factory=dict)
    # Configuración visual del documento (tamaño de hoja).
    # Se guarda en el .accion y viaja al invitado en colaboración
    # para que ambos vean la misma paginación.
    tamano_hoja: int = 1  # TamañoHoja.CARTA = 1 (ver enum TamañoHoja)
    # ── Rutas personalizadas del proyecto ────────────────────
    # Si están vacías, se usan las por defecto (Documents del sistema
    # para guion, Documents/accion/ para backups). Si el usuario las
    # define desde Configuración → Rutas y archivos, cada proyecto
    # recuerda su carpeta preferida al guardar y al hacer backup.
    ruta_guardado_personalizada: str = ""   # carpeta para guardar el .accion
    ruta_backups_personalizada:   str = ""   # carpeta para backups históricos
    # ── Diccionario del proyecto ─────────────────────────────────────
    # Palabras que el usuario marcó como «aprender» con el corrector
    # ortográfico. Se guardan EN el archivo .accion (no en el equipo)
    # para que viajen con el proyecto cuando se comparte. Todas se
    # almacenan en minúsculas y sin acentos para la comparación.
    palabras_aprendidas: list[str] = field(default_factory=list)
    # ── Fichas de análisis dramático por escena ──
    # Clave = número de escena (str, 1-indexed). Valor = FichaEscena
    # con motivación del protagonista, obstáculo, subtexto, tono,
    # referencias visuales y notas de dirección. Se serializa dentro
    # del .accion — viaja con el proyecto.
    fichas_escenas: dict = field(default_factory=dict)
    # ── Portada (title page) ── (autor_id está arriba, en colaboración)
    titulo:        str = ""
    basado_en:     str = ""
    borrador:      str = ""
    fecha_portada: str = ""
    contacto:      str = ""
    # ── Numeración de escenas bloqueada (Formato → Numeración) ──
    # True = cada encabezado conserva su número (Bloque.numero) y las
    # escenas nuevas se numeran 12A, 12B… como en un guion de rodaje.
    numeracion_bloqueada: bool = False
    # Qué números se ven en el margen del editor: "escena" | "bloque" |
    # "ninguna" (Formato → Numeración).
    numeracion: str = "escena"
    # ── Lista de planos (shot list). Cada plano es un dict con:
    # escena (int, 1-based), numero, tamano, angulo, movimiento, lente,
    # descripcion, duracion, notas, hecho (bool).
    planos: list[dict] = field(default_factory=list)
    # ── Versión corta: números de escena (1-based, en orden) elegidos
    # para la versión reducida del guion.
    version_corta: list[int] = field(default_factory=list)
    # ── Storyboard: formato de los cuadros ("16:9", "2.39:1", "9:16"…).
    # Los cuadros son los mismos planos de `planos` (con su dibujo).
    storyboard_formato: str = "16:9"
    # Hojas para dibujar impresas (qué cuadro va en cada página), para leer
    # las fotos de vuelta: {"n.º": {fecha, por_pagina, formato, paginas}}
    storyboard_hojas: dict = field(default_factory=dict)
    # Planta (vista desde arriba) de cada escena: {"n.º escena": planta}
    storyboard_plantas: dict = field(default_factory=dict)
    # Escenas que existen solo en el storyboard (para trabajar sin guion):
    # [{"n": 1001, "nombre": "PARQUE - DÍA"}] (n desde 1001: no chocan con
    # las del guion)
    storyboard_escenas: list = field(default_factory=list)
    # Cómo se ven las personas en 3D (ver MODELOS_PERSONA_3D)
    sb_modelo_persona: str = "persona"
    # 🖼 Las imágenes puestas en la maqueta 3D: {clave: imagen en base64}.
    # Cada elemento «imagen» de una planta guarda solo la clave.
    sb_imagenes_3d: dict = field(default_factory=dict)
    # ── PRESUPUESTO (Centro de Producción → Presupuesto) ──
    # Fondos disponibles (subvención, aporte, etc.) para calcular saldo.
    presupuesto_fondos: str = ""
    # Gastos que se ingresan a mano (catering, transporte, permisos…):
    # {id, categoria, concepto, proveedor, cantidad, valor}
    gastos: list[dict] = field(default_factory=list)
    # Estado de CADA línea del presupuesto (automática o manual), por
    # clave estable ("actor:ANA", "loc:Liceo", "gasto:3f2a…"):
    # {pagado: bool, fecha_pago: "AAAA-MM-DD", notas: str}
    pagos: dict = field(default_factory=dict)
    # 💲 IVA del presupuesto: cómo se escriben los valores
    # ("" sin IVA · "incluido" ya lo traen · "aparte" son netos), la tasa
    # en % («19») y lo que no lleva IVA: claves de línea ("actor:ANA"),
    # categorías enteras ("cat:Elenco") y excepciones ("+actor:ANA").
    iva_modo: str = ""
    iva_tasa: str = ""
    iva_exentos: list = field(default_factory=list)
    # 🗂 Categorías propias del presupuesto ([{nombre, icono}]), los grupos
    # de categorías, en orden ([{nombre, categorias: [...]}]) y las líneas
    # automáticas movidas a otra categoría ({"actor:ANA": "Elenco principal"}).
    categorias_propias: list = field(default_factory=list)
    grupos_categorias: list = field(default_factory=list)
    categoria_lineas: dict = field(default_factory=dict)
    # ── CONTRATOS Y SEGUROS ──
    # Documentos del PROYECTO (no de una ficha): permisos municipales,
    # seguros, catering, autorizaciones… Cada uno:
    # {id, tipo, titulo, contraparte, estado, firma, vence, monto,
    #  archivo_nombre, archivo_datos (base64), notas}
    documentos_legales: list[dict] = field(default_factory=list)
    # Estado/fechas de los documentos que viven en las fichas (contrato
    # de un actor, de una locación…), por clave estable:
    # {estado, firma, vence, notas}
    docs_meta: dict = field(default_factory=dict)
    # 🎬 Guion de ejemplo (1.8.9): la fecha (ISO) a la que están escritas sus
    # fechas. Al abrirlo, todas se corren al presente (ver poner_ejemplo_al_dia):
    # la Carta Gantt nunca queda en el pasado. Al guardarlo como guion propio
    # se borra, y desde ahí las fechas quedan fijas.
    ejemplo_fecha_base: str = ""
    # 📁 la última carpeta desde donde se subieron archivos a este proyecto
    carpeta_archivos: str = ""

    def __len__(self) -> int:
        return len(self.bloques)

    def __getitem__(self, i: int) -> Bloque:
        return self.bloques[i]

    def __iter__(self) -> Iterator[Bloque]:
        return iter(self.bloques)

    def cargar(self, bloques: list[Bloque]) -> None:
        self.bloques = list(bloques) if bloques else [Bloque(Elem.ACCION)]

    # ── ENTER ──────────────────────────────────────────────────────────

    def enter(self, idx: int, offset: int) -> tuple[int, int]:
        """ENTER en (idx, offset). Devuelve nueva posición (idx, offset).

        Regla (estilo estándar de la industria):
        - Si el cursor está al FINAL del bloque, el nuevo bloque adopta
          el tipo que corresponde según el flujo de guion
          (SIGUIENTE_ENTER): Personaje→Diálogo→Personaje, Acción→
          Personaje, Escena→Acción, etc.
        - Si se parte el bloque por el MEDIO, ambas mitades mantienen el
          mismo tipo (partir un diálogo en dos no lo convierte en otra
          cosa). El cambio de flujo solo ocurre al continuar escribiendo.
        """
        bloque = self.bloques[idx]
        elem_actual = bloque.elem
        texto = bloque.texto

        # Atómicos (Escena, Personaje, Transición, Plano, Actos): no se
        # "parten" por el medio. Con Enter al final avanzan el flujo de
        # guion igual que los demás; con el cursor al inicio y texto
        # presente, se empuja el bloque hacia abajo.
        if elem_actual in ATOMICOS:
            if offset == 0 and texto:
                # Cursor al inicio del atómico con texto → empujar abajo
                self.bloques.insert(idx, Bloque(elem_actual))
                return (idx + 1, 0)
            # Enter al final (o en atómico vacío) → avanzar según flujo.
            # Los actos vacíos siguen creando otro acto (su SIGUIENTE es
            # ESCENA, lo cual es correcto).
            elem_nuevo = self.siguiente_tras_enter(elem_actual)
            nuevo = Bloque(elem_nuevo)
            self.bloques.insert(idx + 1, nuevo)
            return (idx + 1, 0)

        # Bloques de texto
        izq = texto[:offset]
        der = texto[offset:]
        bloque.texto = izq

        # ¿Enter al final del bloque? → avanzar tipo según el flujo.
        # ¿Enter en medio (queda texto a la derecha)? → mantener tipo.
        if der:
            elem_nuevo = elem_actual
        else:
            elem_nuevo = self.siguiente_tras_enter(elem_actual)

        nuevo = Bloque(elem_nuevo, texto=der)
        self.bloques.insert(idx + 1, nuevo)
        return (idx + 1, 0)

    def siguiente_tras_enter(self, elem: "Elem") -> "Elem":
        """Qué elemento viene tras ENTER. Respeta el flujo
        personalizado del proyecto (Configuración → Flujo de ENTER,
        guardado en el .accion); si no hay override para este
        elemento, usa el flujo estándar SIGUIENTE_ENTER."""
        overrides = getattr(self, "flujo_enter", None) or {}
        destino_id = overrides.get(ID_INTERNO.get(elem, ""))
        if destino_id and destino_id in DESDE_ID:
            return DESDE_ID[destino_id]
        return SIGUIENTE_ENTER.get(elem, elem)

    def tab(self, idx: int, reverse: bool = False) -> Elem:
        bloque = self.bloques[idx]
        try:
            pos = CICLO_TAB.index(bloque.elem)
        except ValueError:
            pos = 0
        delta = -1 if reverse else 1
        nuevo = CICLO_TAB[(pos + delta) % len(CICLO_TAB)]
        bloque.elem = nuevo
        bloque.texto = aplicar_caso_a_texto(nuevo, bloque.texto)
        return nuevo

    def cambiar_tipo(self, idx: int, elem: Elem) -> None:
        bloque = self.bloques[idx]
        bloque.elem = elem
        bloque.texto = aplicar_caso_a_texto(elem, bloque.texto)

    def backspace(self, idx: int, offset: int) -> tuple[int, int]:
        bloque = self.bloques[idx]

        if offset > 0:
            bloque.texto = bloque.texto[:offset - 1] + bloque.texto[offset:]
            return (idx, offset - 1)

        if idx == 0:
            return (idx, 0)

        prev = self.bloques[idx - 1]
        nuevo_offset = len(prev.texto)
        prev.texto = prev.texto + bloque.texto
        del self.bloques[idx]
        return (idx - 1, nuevo_offset)

    def actualizar_texto(self, idx: int, texto: str) -> None:
        self.bloques[idx].texto = texto

    def insertar_caracter(self, idx: int, offset: int, caracter: str) -> tuple[int, int]:
        bloque = self.bloques[idx]
        bloque.texto = bloque.texto[:offset] + caracter + bloque.texto[offset:]
        return (idx, offset + len(caracter))

    def borrar_bloque(self, idx: int) -> None:
        if len(self.bloques) == 1:
            self.bloques[0] = Bloque(Elem.ACCION)
            return
        del self.bloques[idx]

    def numerar_escenas(self) -> dict[int, int]:
        """Devuelve un dict idx_bloque → número de escena (1-based)."""
        result: dict[int, int] = {}
        n = 0
        for i, b in enumerate(self.bloques):
            if b.elem == Elem.ESCENA:
                n += 1
                result[i] = n
        return result


# ═══════════════════════════════════════════════════════════════════════
# §4.5  PERSISTENCIA: .accion (JSON) + exportadores PDF/TXT/RTF
# ═══════════════════════════════════════════════════════════════════════

# Campos de la portada del guion (en el orden en que se imprimen).
CAMPOS_PORTADA: tuple[str, ...] = (
    "titulo", "autor_id", "basado_en", "borrador", "fecha_portada",
    "contacto")


def _serializar_dataclass(obj):
    """Convierte una dataclass anidada a dict para JSON."""
    if is_dataclass(obj):
        return {f.name: _serializar_dataclass(getattr(obj, f.name)) for f in fields(obj)}
    if isinstance(obj, list):
        return [_serializar_dataclass(x) for x in obj]
    if isinstance(obj, dict):
        return {k: _serializar_dataclass(v) for k, v in obj.items()}
    if isinstance(obj, IntEnum):
        return int(obj)
    return obj


def _dataclass_desde_dict(cls, data: dict):
    """Reconstruye una instancia de un dataclass a partir de un dict,
    ignorando campos que ya no existen y usando defaults para los
    campos faltantes. Sirve para deserializar mensajes de colaboración
    entre versiones del programa que difieran ligeramente."""
    if data is None:
        return cls()
    if not isinstance(data, dict):
        return cls()
    validos = {f.name for f in fields(cls)}
    limpio = {k: v for k, v in data.items() if k in validos}
    return cls(**limpio)


def _cifrar_ficha_para_serializar(ficha_dict: dict, pin: str) -> dict:
    """Cifra los campos sensibles de una ficha de personaje.
    Modifica una COPIA del dict, no el original. Si el campo ya está
    cifrado, lo deja como está. Cifra también las fotos (datos y
    comentarios)."""
    resultado = dict(ficha_dict)
    for campo in CAMPOS_SENSIBLES_PERSONAJE:
        valor = resultado.get(campo, "")
        if valor and not esta_cifrado(valor):
            resultado[campo] = cifrar_texto(str(valor), pin)
    # Fotos: cifrar tanto los datos base64 como los comentarios/títulos
    fotos = resultado.get("fotos", [])
    if isinstance(fotos, list):
        fotos_cifradas = []
        for f in fotos:
            if not isinstance(f, dict):
                fotos_cifradas.append(f)
                continue
            fc = dict(f)
            for campo_foto in ("datos", "comentario", "titulo"):
                v = fc.get(campo_foto, "")
                if v and not esta_cifrado(v):
                    fc[campo_foto] = cifrar_texto(str(v), pin)
            fotos_cifradas.append(fc)
        resultado["fotos"] = fotos_cifradas
    return resultado


def _bloque_a_dict(b: "Bloque") -> dict:
    d = {"elem": int(b.elem), "texto": b.texto, "tags": list(b.tags)}
    if b.formatos:
        d["formatos"] = [dict(f) for f in b.formatos]
    if getattr(b, "numero", ""):
        d["numero"] = str(b.numero)
    if getattr(b, "doble", False):
        d["doble"] = True
    return d


def documento_a_json(doc: "Documento", pin_para_cifrar: str = "") -> str:
    """Serializa el documento a JSON. Si el documento tiene pin_hash y
    se pasa `pin_para_cifrar`, los campos sensibles de las fichas de
    personaje (nombre real del actor, teléfono, correo, valor por día,
    alergias, alimentación, fotos) se cifran con ese PIN. Si no se
    pasa el PIN, los campos se guardan como estén en memoria (que
    puede ser texto plano o ya cifrado)."""
    tiene_pin = bool(getattr(doc, "pin_hash", ""))
    debe_cifrar = tiene_pin and bool(pin_para_cifrar)

    def serializar_ficha(v):
        d = _serializar_dataclass(v)
        if debe_cifrar and isinstance(d, dict):
            return _cifrar_ficha_para_serializar(d, pin_para_cifrar)
        return d

    def serializar_tecnico(t):
        d = _serializar_dataclass(t)
        if debe_cifrar and isinstance(d, dict):
            # Reutilizar la misma lógica de cifrado pero para los
            # campos sensibles de Técnico
            resultado = dict(d)
            for campo in CAMPOS_SENSIBLES_TECNICO:
                valor = resultado.get(campo, "")
                if valor and not esta_cifrado(valor):
                    resultado[campo] = cifrar_texto(str(valor),
                                                     pin_para_cifrar)
            return resultado
        return d

    payload = {
        "version": __version__,
        "bloques": [_bloque_a_dict(b) for b in doc.bloques],
        # (Antes NO se guardaban: portada, negritas/colores de cada
        # bloque ni fichas de escenas — se perdían al reabrir.)
        "portada": {k: str(getattr(doc, k, "") or "")
                    for k in CAMPOS_PORTADA if k != "autor_id"},
        "fichas_escenas": {
            str(k): _serializar_dataclass(v)
            for k, v in (getattr(doc, "fichas_escenas", {}) or {}).items()},
        "numeracion_bloqueada": bool(
            getattr(doc, "numeracion_bloqueada", False)),
        "numeracion": str(getattr(doc, "numeracion", "escena") or "escena"),
        "planos": [dict(pl) for pl in (getattr(doc, "planos", []) or [])
                   if isinstance(pl, dict)],
        "version_corta": [int(n) for n in
                          (getattr(doc, "version_corta", []) or [])],
        "storyboard_formato": str(getattr(doc, "storyboard_formato", "16:9") or "16:9"),
        "storyboard_hojas": {str(k): dict(v) for k, v in
                             (getattr(doc, "storyboard_hojas", {}) or {}).items()
                             if isinstance(v, dict)},
        "storyboard_plantas": {str(k): dict(v) for k, v in
                               (getattr(doc, "storyboard_plantas", {}) or {}).items()
                               if isinstance(v, dict)},
        "storyboard_escenas": [dict(e) for e in (getattr(doc, "storyboard_escenas", []) or [])
                               if isinstance(e, dict)],
        "sb_modelo_persona": str(getattr(doc, "sb_modelo_persona", "persona") or "persona"),
        "sb_imagenes_3d": imagenes_3d_en_uso(doc),
        "presupuesto_fondos": str(getattr(doc, "presupuesto_fondos", "") or ""),
        "gastos": [dict(g) for g in (getattr(doc, "gastos", []) or [])
                   if isinstance(g, dict)],
        "pagos": {str(k): dict(v) for k, v in
                  (getattr(doc, "pagos", {}) or {}).items()
                  if isinstance(v, dict)},
        "iva_modo": str(getattr(doc, "iva_modo", "") or ""),
        "iva_tasa": str(getattr(doc, "iva_tasa", "") or ""),
        "iva_exentos": [str(x) for x in (getattr(doc, "iva_exentos", []) or [])],
        "categorias_propias": [
            {"nombre": str(c.get("nombre", "")), "icono": str(c.get("icono", "") or "")}
            for c in (getattr(doc, "categorias_propias", []) or [])
            if isinstance(c, dict) and str(c.get("nombre", "")).strip()],
        "grupos_categorias": [
            {"nombre": str(g.get("nombre", "")),
             "categorias": [str(c) for c in (g.get("categorias") or []) if str(c).strip()]}
            for g in (getattr(doc, "grupos_categorias", []) or [])
            if isinstance(g, dict) and str(g.get("nombre", "")).strip()],
        "categoria_lineas": {str(k): str(v) for k, v in
                             (getattr(doc, "categoria_lineas", {}) or {}).items() if str(v).strip()},
        "documentos_legales": [
            dict(d) for d in (getattr(doc, "documentos_legales", []) or [])
            if isinstance(d, dict)],
        "docs_meta": {str(k): dict(v) for k, v in
                      (getattr(doc, "docs_meta", {}) or {}).items()
                      if isinstance(v, dict)},
        "ejemplo_fecha_base": str(getattr(doc, "ejemplo_fecha_base", "") or ""),
        "carpeta_archivos": str(getattr(doc, "carpeta_archivos", "") or ""),
        "fichas":       {k: serializar_ficha(v) for k, v in doc.fichas.items()},
        "locaciones":   {k: _serializar_dataclass(v) for k, v in doc.locaciones.items()},
        "equipamiento": [_serializar_dataclass(e) for e in doc.equipamiento],
        "tecnicos":     [serializar_tecnico(t) for t in doc.tecnicos],
        "jornadas":     [_serializar_dataclass(j) for j in doc.jornadas],
        "escaleta":     list(doc.escaleta),
        "premisa":      str(getattr(doc, "premisa", "") or ""),
        "orientacion_general": str(
            getattr(doc, "orientacion_general", "vertical")
            or "vertical"),
        "paginas_horizontales": list(
            getattr(doc, "paginas_horizontales", []) or []),
        "beats":        [_serializar_dataclass(b) for b in doc.beats],
        "fotos_beatboard": [_serializar_dataclass(f) for f in doc.fotos_beatboard],
        "colaboracion": {
            "autor_id":            doc.autor_id,
            "coautores":           doc.coautores,
            "comentarios":         doc.comentarios,
            "colab_max_invitados": doc.colab_max_invitados,
            "colab_permisos":      dict(doc.colab_permisos),
            "pin_hash":            getattr(doc, "pin_hash", ""),
        },
        "categorias_custom": [dict(c) for c in (doc.categorias_custom or [])],
        "flujo_enter": {str(k): str(v)
                        for k, v in (doc.flujo_enter or {}).items()},
        "estados_produccion": {
            str(k): dict(v) for k, v in
            (doc.estados_produccion or {}).items()
        },
        "tamano_hoja": int(getattr(doc, "tamano_hoja", 1) or 1),
        "clima_cache": dict(getattr(doc, "clima_cache", {}) or {}),
        "moneda":      str(getattr(doc, "moneda", "CLP") or "CLP"),
        "pais_default": str(getattr(doc, "pais_default", "CL") or "CL"),
        "ruta_guardado_personalizada": str(
            getattr(doc, "ruta_guardado_personalizada", "") or ""),
        "ruta_backups_personalizada": str(
            getattr(doc, "ruta_backups_personalizada", "") or ""),
        "palabras_aprendidas": [
            str(p) for p in (getattr(doc, "palabras_aprendidas", None)
                              or [])],
        "_tags_presentado": bool(getattr(doc, "_tags_presentado", False)),
    }
    return json.dumps(payload, ensure_ascii=False, indent=2)


def _foto_from_dict(d) -> "Foto":
    if isinstance(d, dict):
        return Foto(datos=d.get("datos", ""),
                    comentario=d.get("comentario", ""),
                    titulo=d.get("titulo", ""))
    return Foto()


def _disp_from_dict(d) -> "Disponibilidad":
    if isinstance(d, dict):
        return Disponibilidad(
            habiles=list(d.get("habiles", [])),
            inhabiles=list(d.get("inhabiles", [])),
        )
    return Disponibilidad()


def _dataclass_from_dict(cls, d: dict):
    """Reconstruye una dataclass desde un dict, ignorando claves desconocidas."""
    if not isinstance(d, dict):
        return cls()
    kwargs = {}
    for f in fields(cls):
        if f.name not in d:
            continue
        val = d[f.name]
        if f.name == "fotos":
            kwargs[f.name] = [_foto_from_dict(x) for x in (val or [])]
        elif f.name in ("documentos", "boletas"):
            kwargs[f.name] = [
                DocumentoAdjunto(
                    nombre=str((x or {}).get("nombre", "")),
                    etiqueta=str((x or {}).get("etiqueta", "")),
                    datos=str((x or {}).get("datos", "")))
                for x in (val or []) if isinstance(x, dict)]
        elif f.name == "disponibilidad":
            kwargs[f.name] = _disp_from_dict(val)
        else:
            kwargs[f.name] = val
    return cls(**kwargs)


def documento_desde_json(s: str) -> "Documento":
    payload = json.loads(s)
    doc = Documento()
    doc.bloques = []
    for bd in payload.get("bloques", []):
        try:
            elem = Elem(int(bd.get("elem", 0)))
        except (ValueError, TypeError):
            elem = Elem.ACCION
        texto = bd.get("texto", "")
        # Normalizar caso por si el archivo viene de otra versión
        texto = aplicar_caso_a_texto(elem, texto)
        formatos = [dict(f) for f in (bd.get("formatos") or [])
                    if isinstance(f, dict)]
        doc.bloques.append(Bloque(
            elem=elem,
            texto=texto,
            tags=list(bd.get("tags", [])),
            formatos=formatos,
            numero=str(bd.get("numero", "") or ""),
            doble=bool(bd.get("doble", False)),
        ))
    if not doc.bloques:
        doc.bloques = [Bloque(Elem.ACCION)]
    portada = payload.get("portada", {}) or {}
    if isinstance(portada, dict):
        for k in CAMPOS_PORTADA:
            if k != "autor_id" and k in portada:
                setattr(doc, k, str(portada.get(k) or ""))
    fe = payload.get("fichas_escenas", {}) or {}
    if isinstance(fe, dict):
        doc.fichas_escenas = {
            str(k): _dataclass_from_dict(FichaEscena, v)
            for k, v in fe.items() if isinstance(v, dict)}
    doc.numeracion_bloqueada = bool(
        payload.get("numeracion_bloqueada", False))
    doc.numeracion = str(payload.get("numeracion", "escena") or "escena")
    if doc.numeracion not in ("escena", "bloque", "ninguna"):
        doc.numeracion = "escena"
    doc.planos = [dict(pl) for pl in (payload.get("planos", []) or [])
                  if isinstance(pl, dict)]
    doc.version_corta = []
    for n in (payload.get("version_corta", []) or []):
        try:
            doc.version_corta.append(int(n))
        except (TypeError, ValueError):
            pass
    doc.storyboard_formato = str(payload.get("storyboard_formato", "16:9") or "16:9")
    doc.storyboard_hojas = {str(k): dict(v) for k, v in
                            (payload.get("storyboard_hojas", {}) or {}).items()
                            if isinstance(v, dict)}
    doc.storyboard_plantas = {str(k): dict(v) for k, v in
                              (payload.get("storyboard_plantas", {}) or {}).items()
                              if isinstance(v, dict)}
    doc.storyboard_escenas = [dict(e) for e in (payload.get("storyboard_escenas", []) or [])
                              if isinstance(e, dict)]
    doc.sb_modelo_persona = str(payload.get("sb_modelo_persona", "persona") or "persona")
    doc.sb_imagenes_3d = {str(k): str(v) for k, v in (payload.get("sb_imagenes_3d", {}) or {}).items()
                          if isinstance(v, str) and v}
    _ALMACEN_IMG_3D.update(doc.sb_imagenes_3d)
    doc.presupuesto_fondos = str(payload.get("presupuesto_fondos", "") or "")
    doc.gastos = [dict(g) for g in (payload.get("gastos", []) or [])
                  if isinstance(g, dict)]
    doc.pagos = {str(k): dict(v) for k, v in
                 (payload.get("pagos", {}) or {}).items() if isinstance(v, dict)}
    doc.iva_modo = str(payload.get("iva_modo", "") or "")
    if doc.iva_modo not in ("", "incluido", "aparte"):
        doc.iva_modo = ""
    doc.iva_tasa = str(payload.get("iva_tasa", "") or "")
    doc.iva_exentos = [str(x) for x in (payload.get("iva_exentos", []) or []) if str(x)]
    doc.categorias_propias = [
        {"nombre": str(c.get("nombre", "")).strip(), "icono": str(c.get("icono", "") or "")}
        for c in (payload.get("categorias_propias", []) or [])
        if isinstance(c, dict) and str(c.get("nombre", "")).strip()]
    doc.grupos_categorias = [
        {"nombre": str(g.get("nombre", "")).strip(),
         "categorias": [str(c).strip() for c in (g.get("categorias") or []) if str(c).strip()]}
        for g in (payload.get("grupos_categorias", []) or [])
        if isinstance(g, dict) and str(g.get("nombre", "")).strip()]
    cl = payload.get("categoria_lineas", {}) or {}
    doc.categoria_lineas = ({str(k): str(v).strip() for k, v in cl.items() if str(v).strip()}
                            if isinstance(cl, dict) else {})
    doc.documentos_legales = [
        dict(d) for d in (payload.get("documentos_legales", []) or [])
        if isinstance(d, dict)]
    doc.docs_meta = {str(k): dict(v) for k, v in
                     (payload.get("docs_meta", {}) or {}).items()
                     if isinstance(v, dict)}
    doc.ejemplo_fecha_base = str(payload.get("ejemplo_fecha_base", "") or "")
    doc.carpeta_archivos = str(payload.get("carpeta_archivos", "") or "")
    doc.fichas = {
        k: _dataclass_from_dict(Ficha, v)
        for k, v in payload.get("fichas", {}).items()
    }
    doc.locaciones = {
        k: _dataclass_from_dict(Locacion, v)
        for k, v in payload.get("locaciones", {}).items()
    }
    doc.equipamiento = [
        _dataclass_from_dict(Equipamiento, e) for e in payload.get("equipamiento", [])
    ]
    doc.tecnicos = [
        _dataclass_from_dict(Tecnico, t) for t in payload.get("tecnicos", [])
    ]
    doc.jornadas = [
        _dataclass_from_dict(Jornada, j) for j in payload.get("jornadas", [])
    ]
    doc.escaleta = [
        str(p) for p in payload.get("escaleta", []) if str(p).strip()
    ]
    doc.premisa = str(payload.get("premisa", "") or "")
    doc.orientacion_general = str(
        payload.get("orientacion_general", "vertical") or "vertical")
    doc.paginas_horizontales = [
        int(p) for p in payload.get("paginas_horizontales", [])
        if str(p).strip().isdigit()
    ]
    doc.beats = [
        _dataclass_from_dict(Beat, b) for b in payload.get("beats", [])
    ]
    doc.fotos_beatboard = [
        _dataclass_from_dict(FotoBeat, f)
        for f in payload.get("fotos_beatboard", [])
    ]
    # Colaboración (estructura nueva agrupada)
    colab = payload.get("colaboracion", {}) or {}
    doc.autor_id            = str(colab.get("autor_id", "") or "")
    doc.coautores           = str(colab.get("coautores", "") or "")
    doc.comentarios         = str(colab.get("comentarios", "") or "")
    try:
        doc.colab_max_invitados = int(colab.get("colab_max_invitados", 8) or 8)
    except (TypeError, ValueError):
        doc.colab_max_invitados = 8
    permisos_raw = colab.get("colab_permisos", {}) or {}
    if isinstance(permisos_raw, dict):
        doc.colab_permisos.update(
            {k: bool(v) for k, v in permisos_raw.items()
             if k in doc.colab_permisos}
        )
    doc.pin_hash = str(colab.get("pin_hash", "") or "")
    # Categorías custom del proyecto (guardadas en el .accion)
    fe_raw = payload.get("flujo_enter", {}) or {}
    doc.flujo_enter = {str(k): str(v) for k, v in fe_raw.items()
                       if str(k) in DESDE_ID and str(v) in DESDE_ID}
    cats_raw = payload.get("categorias_custom", []) or []
    if isinstance(cats_raw, list):
        doc.categorias_custom = [
            {
                "id":     str(c.get("id", "")).strip(),
                "nombre": str(c.get("nombre", "")).strip(),
                "emoji":  str(c.get("emoji", "🏷")).strip() or "🏷",
            }
            for c in cats_raw
            if isinstance(c, dict) and c.get("id") and c.get("nombre")
        ]
    doc._tags_presentado = bool(payload.get("_tags_presentado", False))
    # Estados de producción por escena
    ep_raw = payload.get("estados_produccion", {}) or {}
    if isinstance(ep_raw, dict):
        doc.estados_produccion = {}
        for k, v in ep_raw.items():
            try:
                idx = int(k)
                if isinstance(v, dict):
                    doc.estados_produccion[idx] = {
                        "estado": str(v.get("estado", "sin_grabar")),
                        "porcentaje": int(v.get("porcentaje", 0) or 0),
                    }
            except (ValueError, TypeError):
                continue
    try:
        doc.tamano_hoja = int(payload.get("tamano_hoja", 1) or 1)
        if doc.tamano_hoja not in (1, 2, 3):  # CARTA, A4, OFICIO
            doc.tamano_hoja = 1
    except (ValueError, TypeError):
        doc.tamano_hoja = 1
    # Cache de clima consultado
    cc_raw = payload.get("clima_cache", {}) or {}
    if isinstance(cc_raw, dict):
        doc.clima_cache = {}
        for k, v in cc_raw.items():
            if isinstance(v, dict) and isinstance(k, str):
                doc.clima_cache[k] = dict(v)
    # Moneda del proyecto
    doc.moneda = str(payload.get("moneda", "CLP") or "CLP")
    doc.pais_default = str(payload.get("pais_default", "CL") or "CL")
    doc.ruta_guardado_personalizada = str(
        payload.get("ruta_guardado_personalizada", "") or "")
    doc.ruta_backups_personalizada = str(
        payload.get("ruta_backups_personalizada", "") or "")
    doc.palabras_aprendidas = [
        str(p) for p in (payload.get("palabras_aprendidas", []) or [])
        if str(p).strip()]
    return doc


# ═══════════════════════════════════════════════════════════════════════
# §4.6  MAQUETACIÓN DE PÁGINAS (motor del PDF, la duración y el índice)
# ═══════════════════════════════════════════════════════════════════════
#
# Convierte los bloques del guion en páginas de LÍNEAS, sin dibujar
# nada. Todo se mide en caracteres y líneas: el guion usa Courier
# (ancho fijo), así que «cabe o no cabe» se decide contando letras,
# exactamente igual que en una máquina de escribir. El PDF solo
# convierte (columna, fila) en pixeles.
#
# Reglas profesionales que aplica:
#   • Un encabezado de escena (o de acto) nunca queda solo al pie de
#     la página: viaja con las primeras líneas de lo que sigue.
#   • Un personaje nunca queda separado de su diálogo.
#   • Si un diálogo no cabe, se corta con «(MÁS)» y sigue en la página
#     siguiente con «NOMBRE (CONT.)». Nunca deja menos de 2 líneas a
#     cada lado ni corta un paréntesis por la mitad.
#   • Opcional: «(CONT.)» cuando un personaje vuelve a hablar después
#     de una acción, dentro de la misma escena.
#   • Diálogo doble: dos personajes que hablan a la vez, en dos
#     columnas (Bloque.doble en el segundo personaje).
#   • La acción larga se corta entre líneas (mínimo 2 a cada lado),
#     preferentemente al final de una oración.

# Página estándar: Carta, Courier 12 pt a 6 líneas por pulgada, 1"
# arriba y abajo → 54 líneas ≈ 1 minuto en pantalla.
LINEAS_PAGINA_ESTANDAR = 54
TXT_MAS = "(MÁS)"
TXT_CONT = "(CONT.)"
_RE_CONT_FINAL = re.compile(
    r"\s*\((?:CONT\.?|CONT'D|CONT’D|CONTINÚA|CONTINUA|SIGUE)\)\s*$",
    re.IGNORECASE)
_RE_FIN_ORACION = re.compile(r"[.!?…»\"”)]\s*$")

OPCIONES_PDF_DEFECTO: dict[str, bool] = {
    "numeros_escena": True,     # números a ambos lados del encabezado
    "mas_cont": True,           # (MÁS) / (CONT.) en diálogos cortados
    "cont_tras_accion": False,  # (CONT.) si vuelve a hablar tras acción
    "marcadores": True,         # índice de escenas en el PDF
    "portada": True,            # imprimir la portada (si tiene datos)
    "pagina_tecnica": True,     # hoja final de información técnica
}


@dataclass
class LineaPDF:
    """Una línea ya ubicada en la página (fila y columna en Courier)."""
    fila: int
    col: int
    ancho: int
    texto: str
    alinear: str = "L"            # "L" | "R" | "C"
    negrita: bool = False
    subrayado: bool = False
    # Formatos del usuario que caen en esta línea:
    # [(desde, hasta, dict_formato)] en coordenadas de `texto`.
    fmt: list = field(default_factory=list)


@dataclass
class PaginaPDF:
    lineas: list = field(default_factory=list)
    # Índice del PDF: [(titulo, nivel, fila)] — nivel 0 = acto, 1 = escena
    marcadores: list = field(default_factory=list)


@dataclass
class _Unidad:
    """Bloque (o grupo de bloques) que se pagina como un todo."""
    tipo: str                    # escena | accion | dialogo | doble | otro
    aire: int = 0                # líneas en blanco antes
    lineas: list = field(default_factory=list)   # LineaPDF (fila relativa)
    partible: bool = False
    pegar_siguiente: bool = False
    marcador: Optional[tuple] = None     # (titulo, nivel)
    escena: int = 0              # nº de orden de la escena a la que pertenece
    # Solo diálogos:
    cue: list = field(default_factory=list)
    cuerpo: list = field(default_factory=list)
    grupo: list = field(default_factory=list)    # id de bloque por línea del cuerpo
    paren: list = field(default_factory=list)    # True si la línea es paréntesis
    nombre: str = ""
    col_cue: int = 0
    ancho_cue: int = 0

    @property
    def alto(self) -> int:
        if self.tipo == "dialogo":
            return len(self.cue) + len(self.cuerpo)
        return 1 + max((l.fila for l in self.lineas), default=-1)

    def minimo(self, con_marcas: bool = True) -> int:
        """Líneas que deben caber para EMPEZARLA en una página (si no se
        puede cortar, la unidad completa)."""
        if self.tipo == "dialogo":
            if con_marcas and len(self.cuerpo) >= 4:
                return len(self.cue) + 2 + 1          # + «(MÁS)»
            return self.alto
        if self.partible and self.alto >= 4:
            return 2
        return self.alto


def envolver_texto(texto: str, ancho: int) -> list[tuple[str, int]]:
    """Corta `texto` en líneas de hasta `ancho` caracteres, por
    palabras. Devuelve [(línea, posición_en_texto)] para poder ubicar
    negritas/colores. Respeta los saltos de línea del usuario."""
    ancho = max(1, int(ancho))
    res: list[tuple[str, int]] = []
    base = 0
    for parrafo in re.split(r"\n| ", texto or ""):
        if not parrafo.strip():
            res.append(("", base))
            base += len(parrafo) + 1
            continue
        i = 0
        n = len(parrafo)
        while i < n:
            if res and res[-1][1] >= base:   # línea de continuación
                while i < n and parrafo[i] == " ":
                    i += 1
                if i >= n:
                    break
            if n - i <= ancho:
                res.append((parrafo[i:].rstrip(), base + i))
                break
            corte = parrafo.rfind(" ", i, i + ancho + 1)
            if corte <= i:
                res.append((parrafo[i:i + ancho], base + i))
                i += ancho
            else:
                res.append((parrafo[i:corte].rstrip(), base + i))
                i = corte + 1
        base += len(parrafo) + 1
    return res or [("", 0)]


def _formatos_en(formatos: list, desde: int, largo: int,
                 corrimiento: int = 0) -> list:
    out = []
    for f in formatos or []:
        try:
            a = int(f.get("desde", 0)) + corrimiento
            z = int(f.get("hasta", 0)) + corrimiento
        except (TypeError, ValueError, AttributeError):
            continue
        a, z = max(a, desde), min(z, desde + largo)
        if a < z:
            out.append((a - desde, z - desde, f))
    return out


def _nombre_personaje(texto: str) -> str:
    """«ANA (V.O.) (CONT.)» → «ANA» (para comparar quién habla)."""
    t = _RE_CONT_FINAL.sub("", texto or "")
    return re.sub(r"\s*\([^)]*\)", "", t).strip().upper()


class MaquetaGuion:
    """Pagina bloques de guion. Geometría en caracteres (Courier).

    ancho_hoja: caracteres a lo ancho de la hoja vertical (85 en Carta).
    mizq/mder:  márgenes en caracteres (15 y 10 = 1.5" y 1").
    capacidad:  función n_página(1-based) → líneas útiles de esa hoja
                (las hojas apaisadas tienen menos)."""

    def __init__(self, ancho_hoja: int = 85, mizq: int = 15,
                 mder: int = 10, capacidad=None,
                 opciones: Optional[dict] = None):
        self.ancho_hoja = int(ancho_hoja)
        self.mizq = int(mizq)
        self.mder = int(mder)
        self.util = max(30, self.ancho_hoja - self.mizq - self.mder)
        self.capacidad = capacidad or (lambda _n: LINEAS_PAGINA_ESTANDAR)
        self.op = dict(OPCIONES_PDF_DEFECTO)
        self.op.update(opciones or {})

    # ── Geometría de cada tipo ──────────────────────────────────────
    def _caja(self, elem: "Elem") -> tuple[int, int]:
        si, sd = SANGRIA.get(elem, (0, 0))
        return self.mizq + si, max(8, self.util - si - sd)

    def _lineas_de(self, b: "Bloque", col: int, ancho: int,
                   alinear: str = "L", negrita: bool = False,
                   subrayado: bool = False, texto: Optional[str] = None,
                   fila0: int = 0) -> list:
        corr = 0
        if texto is None:
            texto = b.texto or ""
            if b.elem in (Elem.ESCENA, Elem.PERSONAJE, Elem.TRANSICION,
                          Elem.PLANO, Elem.ACTO_INICIO, Elem.ACTO_FIN):
                texto = texto.upper()
            if b.elem == Elem.PARENTESIS:
                t = texto.strip()
                if t and not t.startswith("("):
                    corr = 1 - (len(texto) - len(texto.lstrip()))
                    texto = f"({t})"
        out = []
        for k, (t, pos) in enumerate(envolver_texto(texto, ancho)):
            out.append(LineaPDF(
                fila=fila0 + k, col=col, ancho=ancho, texto=t,
                alinear=alinear, negrita=negrita, subrayado=subrayado,
                fmt=_formatos_en(getattr(b, "formatos", []), pos, len(t),
                                 corr)))
        return out

    # ── Bloques → unidades ──────────────────────────────────────────
    def unidades(self, entradas: list) -> list:
        """entradas: [(Bloque, número_de_escena_visible | None)]."""
        uds: list[_Unidad] = []
        i = 0
        n_esc = 0
        ultimo_hablante = ""
        hubo_no_dialogo = False
        en_acto = False
        while i < len(entradas):
            b, num = entradas[i]
            e = b.elem
            if e == Elem.PERSONAJE:
                j = i + 1
                while j < len(entradas) and entradas[j][0].elem in (
                        Elem.DIALOGO, Elem.PARENTESIS):
                    j += 1
                u = self._unidad_dialogo([x[0] for x in entradas[i:j]])
                u.escena = n_esc
                if (self.op.get("cont_tras_accion") and hubo_no_dialogo
                        and u.nombre and u.nombre == ultimo_hablante
                        and not _RE_CONT_FINAL.search(b.texto or "")):
                    u = self._unidad_dialogo(
                        [x[0] for x in entradas[i:j]], cont=True)
                    u.escena = n_esc
                # Diálogo doble: el siguiente personaje marcado «doble»
                if (j < len(entradas) and entradas[j][0].elem
                        == Elem.PERSONAJE and getattr(entradas[j][0],
                                                      "doble", False)):
                    k = j + 1
                    while k < len(entradas) and entradas[k][0].elem in (
                            Elem.DIALOGO, Elem.PARENTESIS):
                        k += 1
                    d = self._unidad_doble(
                        [x[0] for x in entradas[i:j]],
                        [x[0] for x in entradas[j:k]])
                    if d.alto <= self.capacidad(1):
                        d.escena = n_esc
                        uds.append(d)
                        ultimo_hablante = _nombre_personaje(
                            entradas[j][0].texto)
                        hubo_no_dialogo = False
                        i = k
                        continue
                uds.append(u)
                ultimo_hablante = u.nombre
                hubo_no_dialogo = False
                i = j
                continue
            if e in (Elem.DIALOGO, Elem.PARENTESIS):
                # Diálogo sin personaje delante: se imprime igual.
                col, ancho = self._caja(e)
                uds.append(_Unidad("otro", AIRE_ARRIBA.get(e, 0),
                                   self._lineas_de(b, col, ancho),
                                   partible=True, escena=n_esc))
                i += 1
                continue
            if e == Elem.ESCENA:
                n_esc += 1
                ultimo_hablante = ""
                hubo_no_dialogo = False
                col, ancho = self._caja(e)
                ls = self._lineas_de(b, col, ancho)
                if num and self.op.get("numeros_escena", True):
                    ls.append(LineaPDF(0, max(0, col - 7), 6, str(num), "R"))
                    ls.append(LineaPDF(0, col + ancho + 2, 6, str(num), "L"))
                txt = (b.texto or "").strip().upper()
                titulo = f"{num}. {txt}" if num else txt
                uds.append(_Unidad("escena", AIRE_ARRIBA.get(e, 2), ls,
                                   pegar_siguiente=True,
                                   marcador=(titulo, 1 if en_acto else 0),
                                   escena=n_esc))
                i += 1
                continue
            hubo_no_dialogo = True
            col, ancho = self._caja(e)
            if e in (Elem.ACTO_INICIO, Elem.ACTO_FIN):
                ls = self._lineas_de(b, self.mizq, self.util, "C",
                                     negrita=True, subrayado=True)
                marc = None
                if e == Elem.ACTO_INICIO:
                    en_acto = True
                    marc = ((b.texto or "").strip().upper() or "ACTO", 0)
                uds.append(_Unidad("otro", AIRE_ARRIBA.get(e, 2), ls,
                                   pegar_siguiente=(e == Elem.ACTO_INICIO),
                                   marcador=marc, escena=n_esc))
            elif e == Elem.TRANSICION:
                uds.append(_Unidad("otro", AIRE_ARRIBA.get(e, 1),
                                   self._lineas_de(b, self.mizq, self.util,
                                                   "R"), escena=n_esc))
            else:   # ACCION, PLANO
                uds.append(_Unidad("accion", AIRE_ARRIBA.get(e, 1),
                                   self._lineas_de(b, col, ancho),
                                   partible=True,
                                   pegar_siguiente=(e == Elem.PLANO),
                                   escena=n_esc))
            i += 1
        return uds

    def _unidad_dialogo(self, bloques: list, cont: bool = False,
                        col_base: Optional[int] = None,
                        ancho_col: Optional[int] = None) -> _Unidad:
        cue_b = bloques[0]
        nombre_txt = (cue_b.texto or "").strip().upper()
        if cont and not _RE_CONT_FINAL.search(nombre_txt):
            nombre_txt = f"{nombre_txt} {TXT_CONT}"
        if col_base is None:
            col_cue, ancho_cue = self._caja(Elem.PERSONAJE)
        else:   # columna de diálogo doble
            col_cue, ancho_cue = col_base + 4, max(10, ancho_col - 4)
        u = _Unidad("dialogo", AIRE_ARRIBA.get(Elem.PERSONAJE, 1),
                    partible=True)
        u.nombre = _nombre_personaje(nombre_txt)
        u.col_cue, u.ancho_cue = col_cue, ancho_cue
        u.cue = self._lineas_de(cue_b, col_cue, ancho_cue,
                                texto=nombre_txt)
        if nombre_txt != (cue_b.texto or "").strip().upper():
            for l in u.cue:
                l.fmt = []
        for gid, b in enumerate(bloques[1:], start=1):
            if col_base is None:
                col, ancho = self._caja(b.elem)
            elif b.elem == Elem.PARENTESIS:
                col, ancho = col_base + 2, max(8, ancho_col - 4)
            else:
                col, ancho = col_base, ancho_col
            for l in self._lineas_de(b, col, ancho):
                u.cuerpo.append(l)
                u.grupo.append(gid)
                u.paren.append(b.elem == Elem.PARENTESIS)
        self._refilar_dialogo(u)
        return u

    @staticmethod
    def _refilar_dialogo(u: _Unidad) -> None:
        f = 0
        for l in u.cue + u.cuerpo:
            l.fila = f
            f += 1

    def _unidad_doble(self, izq: list, der: list) -> _Unidad:
        """Dos diálogos simultáneos en dos columnas."""
        ancho_col = (self.util - 3) // 2
        a = self._unidad_dialogo(izq, col_base=self.mizq,
                                 ancho_col=ancho_col)
        b = self._unidad_dialogo(der, col_base=self.mizq + ancho_col + 3,
                                 ancho_col=ancho_col)
        u = _Unidad("doble", AIRE_ARRIBA.get(Elem.PERSONAJE, 1),
                    lineas=a.cue + a.cuerpo + b.cue + b.cuerpo)
        return u

    # ── Cortes ──────────────────────────────────────────────────────
    def _partir_accion(self, u: _Unidad, disponible: int,
                       forzar: bool) -> Optional[tuple]:
        n = u.alto
        minimo = 1 if forzar else 2
        k = min(disponible, n - minimo)
        if k < minimo:
            return None
        # Preferir terminar en una oración completa (hasta 3 líneas antes)
        for kk in range(k, max(minimo, k - 3) - 1, -1):
            if _RE_FIN_ORACION.search(u.lineas[kk - 1].texto):
                k = kk
                break
        a = [l for l in u.lineas if l.fila < k]
        resto = _Unidad(u.tipo, 0, [], partible=True, escena=u.escena)
        for l in u.lineas:
            if l.fila >= k:
                l.fila -= k
                resto.lineas.append(l)
        return a, k, resto

    def _partir_dialogo(self, u: _Unidad, disponible: int,
                        forzar: bool) -> Optional[tuple]:
        c, nb = len(u.cue), len(u.cuerpo)
        con_marcas = bool(self.op.get("mas_cont", True))
        if not con_marcas and not forzar:
            return None
        minimo = 1 if forzar else 2
        extra = 1 if con_marcas else 0
        mejor = None
        for k in range(min(nb - minimo, disponible - c - extra),
                       minimo - 1, -1):
            if u.paren[k - 1]:
                continue                      # no terminar en paréntesis
            if k < nb and u.grupo[k] == u.grupo[k - 1] and u.paren[k]:
                continue                      # no cortar un paréntesis
            if mejor is None:
                mejor = k
            if _RE_FIN_ORACION.search(u.cuerpo[k - 1].texto):
                if k >= mejor - 2:
                    mejor = k
                break
        if mejor is None:
            return None
        k = mejor
        a = list(u.cue) + list(u.cuerpo[:k])
        alto_a = c + k
        if con_marcas:
            a.append(LineaPDF(alto_a, u.col_cue, u.ancho_cue, TXT_MAS))
            alto_a += 1
        # Resto: «NOMBRE (CONT.)» + lo que falta
        resto = _Unidad("dialogo", 0, partible=True, escena=u.escena)
        resto.nombre, resto.col_cue, resto.ancho_cue = (
            u.nombre, u.col_cue, u.ancho_cue)
        base = _RE_CONT_FINAL.sub("", " ".join(l.texto for l in u.cue))
        txt = f"{base.strip()} {TXT_CONT}" if con_marcas else base.strip()
        resto.cue = [LineaPDF(0, u.col_cue, u.ancho_cue, t)
                     for t, _ in envolver_texto(txt, u.ancho_cue)]
        resto.cuerpo = list(u.cuerpo[k:])
        resto.grupo = list(u.grupo[k:])
        resto.paren = list(u.paren[k:])
        self._refilar_dialogo(resto)
        return a, alto_a, resto

    # ── Paginación ──────────────────────────────────────────────────
    def paginar(self, entradas: list) -> list:
        uds = self.unidades(entradas)
        paginas = [PaginaPDF()]
        fila = 0

        def cap() -> int:
            return max(10, int(self.capacidad(len(paginas))))

        def salto():
            nonlocal fila
            paginas.append(PaginaPDF())
            fila = 0

        def colocar(u: _Unidad, lineas: list, alto: int, aire: int):
            nonlocal fila
            fila += aire
            if u.marcador and self.op.get("marcadores", True):
                paginas[-1].marcadores.append(
                    (u.marcador[0], u.marcador[1], fila))
                u.marcador = None
            for l in lineas:
                l.fila += fila
                paginas[-1].lineas.append(l)
            fila += alto

        i = 0
        while i < len(uds):
            u = uds[i]
            aire = u.aire if fila > 0 else 0
            disponible = cap() - fila - aire
            necesita = u.alto
            if u.pegar_siguiente and i + 1 < len(uds):
                sig = uds[i + 1]
                necesita = u.alto + sig.aire + sig.minimo(
                    bool(self.op.get("mas_cont", True)))
            if necesita <= disponible:
                lineas = (u.cue + u.cuerpo) if u.tipo == "dialogo" \
                    else u.lineas
                colocar(u, lineas, u.alto, aire)
                i += 1
                continue
            # No cabe completa: ¿se puede cortar?
            forzar = u.alto > cap()
            corte = None
            if u.partible and (fila > 0 or forzar) and disponible > 0:
                if u.tipo == "dialogo":
                    corte = self._partir_dialogo(u, disponible, forzar)
                else:
                    corte = self._partir_accion(u, disponible, forzar)
            if corte is not None:
                lineas_a, alto_a, resto = corte
                colocar(u, lineas_a, alto_a, aire)
                salto()
                uds[i] = resto
                continue
            if fila == 0:
                # Ni en una hoja vacía cabe y no se puede cortar: va igual.
                lineas = (u.cue + u.cuerpo) if u.tipo == "dialogo" \
                    else u.lineas
                colocar(u, lineas, u.alto, 0)
                i += 1
                continue
            salto()
        if len(paginas) > 1 and not paginas[-1].lineas:
            paginas.pop()
        return paginas

    def lineas_por_escena(self, entradas: list) -> dict[int, int]:
        """Líneas que ocupa cada escena (nº de orden → líneas), sin
        contar los saltos de página. Base del cálculo de duración."""
        res: dict[int, int] = {}
        for u in self.unidades(entradas):
            res[u.escena] = res.get(u.escena, 0) + u.aire + u.alto
        return res


def numeros_de_escena(bloques: list, bloqueada: bool = False) -> dict[int, str]:
    """idx_bloque → número visible de cada escena.

    Sin bloquear: 1, 2, 3… en orden. Con la numeración BLOQUEADA, cada
    encabezado conserva su número (Bloque.numero) y las escenas nuevas
    reciben el del anterior + letra: 12 → 12A → 12B (antes de la
    primera: A1, B1…), como en un guion de rodaje."""
    res: dict[int, str] = {}
    escenas = [(i, b) for i, b in enumerate(bloques) if b.elem == Elem.ESCENA]
    if not bloqueada:
        for n, (i, _) in enumerate(escenas, start=1):
            res[i] = str(n)
        return res
    usados = {str(b.numero) for _, b in escenas if getattr(b, "numero", "")}

    def letras_sig(s: str) -> str:
        if not s:
            return "A"
        s = list(s)
        k = len(s) - 1
        while k >= 0:
            if s[k] != "Z":
                s[k] = chr(ord(s[k]) + 1)
                return "".join(s)
            s[k] = "A"
            k -= 1
        return "A" + "".join(s)

    previo = ""
    for pos, (i, b) in enumerate(escenas):
        if getattr(b, "numero", ""):
            res[i] = str(b.numero)
            previo = res[i]
            continue
        if not previo:
            sig = next((str(x.numero) for _, x in escenas[pos + 1:]
                        if getattr(x, "numero", "")), "1")
            m = re.match(r"^([A-Z]*)(.*)$", sig)
            cand = "A" + (m.group(2) if m else sig)
            while cand in usados:
                m = re.match(r"^([A-Z]+)(.*)$", cand)
                cand = letras_sig(m.group(1)) + m.group(2)
        else:
            m_pref = re.match(r"^([A-Z]+)(\d.*)$", previo)
            if m_pref:      # «A1» → «B1»
                cand = letras_sig(m_pref.group(1)) + m_pref.group(2)
            else:
                m = re.match(r"^(.*?\d)([A-Z]*)$", previo)
                cand = (m.group(1) + letras_sig(m.group(2))) if m \
                    else previo + "A"
            while cand in usados:
                m = re.match(r"^(.*?\d)([A-Z]*)$", cand)
                cand = (m.group(1) + letras_sig(m.group(2))) if m \
                    else cand + "A"
        usados.add(cand)
        res[i] = cand
        previo = cand
    return res


def entradas_de_documento(doc: "Documento") -> list:
    """[(bloque, número visible de escena | None)] de todo el guion."""
    nums = numeros_de_escena(doc.bloques,
                             bool(getattr(doc, "numeracion_bloqueada", False)))
    return [(b, nums.get(i)) for i, b in enumerate(doc.bloques)]


# ── Duración estimada (1 página estándar ≈ 1 minuto) ─────────────────
def escenas_con_bloques(bloques: list) -> list[dict]:
    """Escenas del guion: [{n, desde, hasta, encabezado}] donde
    bloques[desde:hasta] es la escena completa (encabezado incluido,
    sin los marcadores de acto). n = orden 1, 2, 3…"""
    res: list[dict] = []
    for i, b in enumerate(bloques):
        if b.elem == Elem.ESCENA:
            if res:
                res[-1]["hasta"] = i
            res.append({"n": len(res) + 1, "desde": i, "hasta": len(bloques),
                        "encabezado": (b.texto or "").strip()})
    for e in res:     # no arrastrar los «ACTO» que cierran/abren
        h = e["hasta"]
        while h > e["desde"] + 1 and bloques[h - 1].elem in (
                Elem.ACTO_INICIO, Elem.ACTO_FIN):
            h -= 1
        e["hasta"] = h
    return res


def lineas_de_bloques(bloques: list) -> int:
    """Líneas que ocupan estos bloques en una página estándar."""
    mq = MaquetaGuion(85, 15, 10)
    return sum(u.aire + u.alto for u in mq.unidades([(b, None) for b in bloques]))


def duracion_minutos(lineas: int) -> float:
    return lineas / float(LINEAS_PAGINA_ESTANDAR)


def formato_duracion(lineas: int) -> str:
    """«3:45» (minutos:segundos) a partir de líneas."""
    seg = int(round(duracion_minutos(lineas) * 60))
    return f"{seg // 60}:{seg % 60:02d}"


def formato_octavos(lineas: int) -> str:
    """Páginas en octavos, como en los desgloses de producción: «1 3/8»."""
    oct_ = max(1, int(round(lineas * 8 / LINEAS_PAGINA_ESTANDAR)))
    ent, resto = divmod(oct_, 8)
    if not ent:
        return f"{resto}/8"
    return f"{ent} {resto}/8" if resto else str(ent)


# ── Índice (marcadores) dentro del PDF ───────────────────────────────
def _texto_pdf(s: str) -> bytes:
    """Cadena PDF en UTF-16BE (acentos y ñ correctos en el índice)."""
    return b"<FEFF" + (s or "").encode("utf-16-be").hex().upper().encode() \
        + b">"


def agregar_indice_pdf(ruta, entradas: list) -> bool:
    """Agrega el índice de escenas (los «marcadores» del panel lateral
    del lector de PDF) a un PDF recién creado por Qt, como
    actualización incremental: no reescribe el archivo, solo le añade
    al final el índice y un catálogo nuevo que lo apunta.

    entradas: [(titulo, nivel, n_pagina_0based, y_desde_arriba_en_pt)]
    nivel 0 = acto o escena suelta; nivel 1 = escena dentro de un acto.
    Devuelve False (y deja el PDF intacto) si algo no se reconoce."""
    if not entradas:
        return False
    ruta = Path(ruta)
    datos = ruta.read_bytes()
    try:
        m_sx = list(re.finditer(rb"startxref\s+(\d+)", datos))[-1]
        prev = int(m_sx.group(1))
        trailer = datos[datos.rfind(b"trailer"):m_sx.start()]
        size = int(re.search(rb"/Size\s+(\d+)", trailer).group(1))
        root = int(re.search(rb"/Root\s+(\d+)\s+0\s+R", trailer).group(1))
        m_info = re.search(rb"/Info\s+(\d+)\s+0\s+R", trailer)
        m_id = re.search(rb"/ID\s*(\[[^\]]*\])", trailer)

        def cuerpo_obj(n: int) -> bytes:
            m = list(re.finditer(rb"(?<!\d)" + str(n).encode()
                                 + rb"\s+0\s+obj(.*?)endobj", datos, re.S))
            return m[-1].group(1).strip()

        cat = cuerpo_obj(root)
        if b"/Outlines" in cat:
            return False
        pages_ref = int(re.search(rb"/Pages\s+(\d+)\s+0\s+R", cat).group(1))

        def hojas(n: int) -> list:
            o = cuerpo_obj(n)
            if re.search(rb"/Type\s*/Pages", o):
                kids = re.search(rb"/Kids\s*\[(.*?)\]", o, re.S).group(1)
                out = []
                for k in re.findall(rb"(\d+)\s+0\s+R", kids):
                    out += hojas(int(k))
                return out
            mb = re.search(rb"/MediaBox\s*\[\s*([\d.]+)\s+([\d.]+)\s+"
                           rb"([\d.]+)\s+([\d.]+)", o)
            alto = float(mb.group(4)) - float(mb.group(2)) if mb else 792.0
            return [(n, alto)]

        paginas = hojas(pages_ref)
    except Exception:
        return False

    # Árbol: nivel 0 cuelga de la raíz; nivel 1 del último nivel 0.
    raiz = size
    nodos: list[dict] = []
    for titulo, nivel, pag, y in entradas:
        if not (0 <= pag < len(paginas)):
            continue
        padre = None
        if nivel >= 1:
            padre = next((k for k in range(len(nodos) - 1, -1, -1)
                          if nodos[k]["nivel"] == 0), None)
        nodos.append({"titulo": titulo, "nivel": 0 if padre is None else 1,
                      "pagina": pag, "y": y, "padre": padre, "hijos": []})
    if not nodos:
        return False
    for k, nd in enumerate(nodos):
        nd["num"] = raiz + 1 + k
        if nd["padre"] is not None:
            nodos[nd["padre"]]["hijos"].append(k)
    tope = [k for k, nd in enumerate(nodos) if nd["padre"] is None]

    objs: dict[int, bytes] = {}
    objs[raiz] = (f"<< /Type /Outlines /First {nodos[tope[0]]['num']} 0 R "
                  f"/Last {nodos[tope[-1]]['num']} 0 R "
                  f"/Count {len(nodos)} >>").encode()
    for k, nd in enumerate(nodos):
        hermanos = tope if nd["padre"] is None \
            else nodos[nd["padre"]]["hijos"]
        pos = hermanos.index(k)
        pnum, alto = paginas[nd["pagina"]]
        top = max(0.0, alto - float(nd["y"]) + 6)
        partes = [b"<< /Title " + _texto_pdf(nd["titulo"]),
                  f" /Parent {raiz if nd['padre'] is None else nodos[nd['padre']]['num']} 0 R".encode(),
                  f" /Dest [{pnum} 0 R /XYZ 0 {top:.1f} 0]".encode()]
        if pos > 0:
            partes.append(f" /Prev {nodos[hermanos[pos - 1]]['num']} 0 R".encode())
        if pos < len(hermanos) - 1:
            partes.append(f" /Next {nodos[hermanos[pos + 1]]['num']} 0 R".encode())
        if nd["hijos"]:
            partes.append(f" /First {nodos[nd['hijos'][0]]['num']} 0 R"
                          f" /Last {nodos[nd['hijos'][-1]]['num']} 0 R"
                          f" /Count {len(nd['hijos'])}".encode())
        partes.append(b" >>")
        objs[nd["num"]] = b"".join(partes)
    # Catálogo nuevo (mismo número): + índice abierto al abrir el PDF
    cat_nuevo = cat.rstrip()
    if cat_nuevo.endswith(b">>"):
        cat_nuevo = cat_nuevo[:-2]
    cat_nuevo += (f"\n/Outlines {raiz} 0 R\n/PageMode /UseOutlines\n>>").encode()
    objs[root] = cat_nuevo

    salida = bytearray(datos)
    if not salida.endswith(b"\n"):
        salida += b"\n"
    offsets: dict[int, int] = {}
    for num in sorted(objs):
        offsets[num] = len(salida)
        salida += f"{num} 0 obj\n".encode() + objs[num] + b"\nendobj\n"
    xref_pos = len(salida)
    salida += b"xref\n"
    nums = sorted(offsets)
    grupos: list[list[int]] = []
    for num in nums:
        if grupos and num == grupos[-1][-1] + 1:
            grupos[-1].append(num)
        else:
            grupos.append([num])
    for g in grupos:
        salida += f"{g[0]} {len(g)}\n".encode()
        for num in g:
            salida += f"{offsets[num]:010d} 00000 n \n".encode()
    nuevo_size = max(size, max(nums) + 1)
    tr = f"trailer\n<< /Size {nuevo_size} /Root {root} 0 R /Prev {prev}"
    if m_info:
        tr += f" /Info {int(m_info.group(1))} 0 R"
    salida += tr.encode()
    if m_id:
        salida += b" /ID " + m_id.group(1)
    salida += f" >>\nstartxref\n{xref_pos}\n%%EOF\n".encode()
    ruta.write_bytes(bytes(salida))
    return True


def documento_a_txt(doc: "Documento") -> str:
    """Volcado del guion como texto con LAYOUT de guion cinematográfico
    (sangrías y alineación estándar de la industria).
    Margen útil base: 15 izq · 10 der · 60 chars ancho ⇒ línea 75 cols.

    Se pagina cada 55 líneas (estándar de guion) con número de página
    en la esquina superior derecha. Si hay portada, ocupa una página
    y NO se numera; la numeración empieza en 1 en la primera página
    de contenido.
    """
    import textwrap as _tw
    MARGEN_IZQ = 15
    ANCHO_UTIL = 60       # 60 chars ancho de cuerpo
    LINEA_TOTAL = MARGEN_IZQ + ANCHO_UTIL
    LINEAS_PAGINA = 55    # estándar guion

    def envolver(texto: str, sangria_izq: int, sangria_der: int = 0) -> list[str]:
        """Envuelve texto a `ANCHO_UTIL − sangrías` y le pone el margen."""
        ancho = ANCHO_UTIL - sangria_izq - sangria_der
        if ancho < 5:
            ancho = 5
        prefijo = " " * (MARGEN_IZQ + sangria_izq)
        lineas = _tw.wrap(texto, width=ancho) or [""]
        return [prefijo + l for l in lineas]

    # Determinar si hay portada (título/autor/etc)
    titulo    = (getattr(doc, "titulo", "") or "").strip()
    autor     = (getattr(doc, "autor_id", "") or "").strip()
    basado    = (getattr(doc, "basado_en", "") or "").strip()
    borrador  = (getattr(doc, "borrador", "") or "").strip()
    fecha_p   = (getattr(doc, "fecha_portada", "") or "").strip()
    contacto  = (getattr(doc, "contacto", "") or "").strip()
    hay_portada = any([titulo, autor, basado, borrador, fecha_p, contacto])

    portada_txt: list[str] = []
    if hay_portada:
        # Layout simple, centrado en el ancho útil
        portada_txt.append("")
        for _ in range(15):
            portada_txt.append("")
        if titulo:
            pad = max(0, (LINEA_TOTAL - len(titulo)) // 2)
            portada_txt.append(" " * pad + titulo.upper())
            portada_txt.append("")
            portada_txt.append("")
        if autor:
            escrito = "escrito por"
            pad = max(0, (LINEA_TOTAL - len(escrito)) // 2)
            portada_txt.append(" " * pad + escrito)
            portada_txt.append("")
            pad = max(0, (LINEA_TOTAL - len(autor)) // 2)
            portada_txt.append(" " * pad + autor)
            portada_txt.append("")
            portada_txt.append("")
        if basado:
            t = f"Basado en {basado}"
            pad = max(0, (LINEA_TOTAL - len(t)) // 2)
            portada_txt.append(" " * pad + t)
            portada_txt.append("")
        if borrador:
            pad = max(0, (LINEA_TOTAL - len(borrador)) // 2)
            portada_txt.append(" " * pad + borrador)
            portada_txt.append("")
        # Contacto al pie
        while len(portada_txt) < LINEAS_PAGINA - 8:
            portada_txt.append("")
        for linea in contacto.splitlines():
            portada_txt.append(" " * MARGEN_IZQ + linea)
        if fecha_p:
            portada_txt.append(" " * MARGEN_IZQ + fecha_p)
        # Rellenar hasta el fin de página
        while len(portada_txt) < LINEAS_PAGINA:
            portada_txt.append("")

    # Generar todas las líneas del cuerpo
    cuerpo: list[str] = []
    for b in doc.bloques:
        izq, der = SANGRIA[b.elem]
        caso = CASO.get(b.elem, Caso.FRASE)
        texto = b.texto or ""
        if caso == Caso.MAYUSCULAS:
            texto = texto.upper()
        elif caso == Caso.MINUSCULAS:
            texto = texto.lower()

        if b.elem == Elem.TRANSICION:
            for linea in (texto or "").split("\n"):
                pad = max(0, LINEA_TOTAL - len(linea))
                cuerpo.append(" " * pad + linea)
        elif b.elem in (Elem.ACTO_INICIO, Elem.ACTO_FIN):
            for linea in (texto or "").split("\n"):
                pad = max(0, (LINEA_TOTAL - len(linea)) // 2)
                cuerpo.append(" " * pad + linea)
        elif b.elem == Elem.PARENTESIS:
            txt = texto.strip()
            if not txt.startswith("("):
                txt = f"({txt})"
            cuerpo.extend(envolver(txt, izq, der))
        else:
            cuerpo.extend(envolver(texto, izq, der))
        cuerpo.append("")  # línea en blanco entre bloques

    # Paginar el cuerpo agregando encabezado con número de página
    out: list[str] = []
    if portada_txt:
        out.extend(portada_txt)
        out.append("\f")  # form feed = separador de página

    n_pag = 1
    i = 0
    while i < len(cuerpo):
        # Encabezado con número de página (esquina sup. derecha)
        num_txt = f"{n_pag}."
        pad = max(0, LINEA_TOTAL - len(num_txt))
        out.append(" " * pad + num_txt)
        out.append("")  # línea en blanco después del número

        # Volcar LINEAS_PAGINA - 2 líneas de contenido
        lineas_disponibles = LINEAS_PAGINA - 2
        fin = min(i + lineas_disponibles, len(cuerpo))
        out.extend(cuerpo[i:fin])
        i = fin

        # Separador de página
        if i < len(cuerpo):
            out.append("\f")
            n_pag += 1

    return "\n".join(out)


def documento_a_docx(doc: "Documento", ruta: Path) -> None:
    """Escribe un .docx mínimo a partir del documento. Implementación
    manual via zipfile (Office Open XML) — no requiere python-docx."""
    import zipfile as _zip
    import xml.sax.saxutils as _sx

    # Plantilla del estilo principal: Courier 12pt
    estilos = {
        Elem.ESCENA:      ("scene",  "1.5in", "0in",  True,  False, True),
        Elem.ACCION:      ("action", "1.5in", "0in",  False, False, False),
        Elem.PERSONAJE:   ("char",   "3.7in", "0in",  False, False, True),
        Elem.DIALOGO:     ("dia",    "2.5in", "2.5in",False, False, False),
        Elem.PARENTESIS:  ("paren",  "3.1in", "2.9in",False, True,  False),
        Elem.TRANSICION:  ("trans",  "0in",  "0in",  False, False, True),
        Elem.PLANO:       ("plano",  "1.5in", "0in",  True,  False, True),
        Elem.ACTO_INICIO: ("acto",   "0in",  "0in",  True,  False, True),
        Elem.ACTO_FIN:    ("acto",   "0in",  "0in",  True,  False, True),
    }

    parrafos = []
    for b in doc.bloques:
        nombre, izq, der, bold, italic, caps = estilos[b.elem]
        texto = b.texto or ""
        if caps:
            texto = texto.upper()
        align = (
            "right"  if b.elem == Elem.TRANSICION else
            "center" if b.elem in (Elem.ACTO_INICIO, Elem.ACTO_FIN) else
            "left"
        )
        if b.elem == Elem.PARENTESIS and not texto.strip().startswith("("):
            texto = f"({texto.strip()})"

        # Twentieths of a point: 1 inch = 1440 twips
        def _twips(pulg: str) -> int:
            return int(float(pulg.rstrip("in")) * 1440)
        ind = (f'<w:ind w:left="{_twips(izq)}" w:right="{_twips(der)}"/>')
        rPr = []
        if bold:   rPr.append('<w:b/>')
        if italic: rPr.append('<w:i/>')
        rPr_xml = '<w:rPr><w:rFonts w:ascii="Courier New" w:hAnsi="Courier New"/>' \
                  '<w:sz w:val="24"/>' + "".join(rPr) + '</w:rPr>'
        run = f'<w:r>{rPr_xml}<w:t xml:space="preserve">{_sx.escape(texto)}</w:t></w:r>'
        pPr = (f'<w:pPr>{ind}<w:jc w:val="{align}"/>'
               f'<w:spacing w:after="200"/></w:pPr>')
        parrafos.append(f'<w:p>{pPr}{run}</w:p>')

    # Sección de página: Letter (12240x15840 twips) sin márgenes
    # del documento, porque los márgenes de la industria del guion ya
    # están aplicados como sangrías por párrafo. Sin esto, Word combina
    # ambos y los parentéticos se cortan a 0.5" de ancho útil.
    # w:header="720" (0.5") deja espacio para el número de página.
    sect_pr = (
        '<w:sectPr>'
        '<w:headerReference w:type="default" r:id="rIdHdr"/>'
        '<w:pgSz w:w="12240" w:h="15840"/>'
        '<w:pgMar w:top="0" w:right="0" w:bottom="0" w:left="0" '
        'w:header="720" w:footer="0" w:gutter="0"/>'
        '<w:titlePg/>'   # primera página (portada) sin encabezado
        '</w:sectPr>'
    )
    document_xml = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n'
        '<w:document xmlns:w="http://schemas.openxmlformats.org/'
        'wordprocessingml/2006/main" '
        'xmlns:r="http://schemas.openxmlformats.org/officeDocument/'
        '2006/relationships">'
        '<w:body>' + "".join(parrafos) + sect_pr + '</w:body></w:document>'
    )
    # header1.xml: número de página alineado a la derecha con tabs
    header_xml = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n'
        '<w:hdr xmlns:w="http://schemas.openxmlformats.org/'
        'wordprocessingml/2006/main">'
        '<w:p>'
        '<w:pPr>'
        '<w:tabs><w:tab w:val="right" w:pos="10800"/></w:tabs>'
        '<w:jc w:val="right"/>'
        '</w:pPr>'
        '<w:r><w:rPr><w:rFonts w:ascii="Courier New" '
        'w:hAnsi="Courier New"/><w:sz w:val="24"/></w:rPr>'
        '<w:tab/>'
        '<w:fldChar w:fldCharType="begin"/>'
        '</w:r>'
        '<w:r><w:instrText xml:space="preserve"> PAGE </w:instrText></w:r>'
        '<w:r><w:fldChar w:fldCharType="end"/></w:r>'
        '<w:r><w:rPr><w:rFonts w:ascii="Courier New" '
        'w:hAnsi="Courier New"/><w:sz w:val="24"/></w:rPr>'
        '<w:t>.</w:t></w:r>'
        '</w:p>'
        '</w:hdr>'
    )
    content_types = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n'
        '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
        '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
        '<Default Extension="xml" ContentType="application/xml"/>'
        '<Override PartName="/word/document.xml" '
        'ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>'
        '<Override PartName="/word/header1.xml" '
        'ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.header+xml"/>'
        '</Types>'
    )
    rels = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n'
        '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
        '<Relationship Id="rId1" Target="word/document.xml" '
        'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument"/>'
        '</Relationships>'
    )
    # Rels del documento — apunta al header
    document_rels = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n'
        '<Relationships xmlns="http://schemas.openxmlformats.org/'
        'package/2006/relationships">'
        '<Relationship Id="rIdHdr" Target="header1.xml" '
        'Type="http://schemas.openxmlformats.org/officeDocument/2006/'
        'relationships/header"/>'
        '</Relationships>'
    )
    with _zip.ZipFile(ruta, "w", _zip.ZIP_DEFLATED) as z:
        z.writestr("[Content_Types].xml", content_types)
        z.writestr("_rels/.rels", rels)
        z.writestr("word/document.xml", document_xml)
        z.writestr("word/header1.xml", header_xml)
        z.writestr("word/_rels/document.xml.rels", document_rels)


def escribir_docx(ruta, bloques: list, titulo: str = "",
                  autor: str = "") -> None:
    """Escribe un .docx con una lista suelta de bloques (sin un
    Documento completo). Lo usan «Audiodrama → Word» y «Sides por
    actor → Word». Reutiliza documento_a_docx(), que solo necesita
    el atributo .bloques; titulo y autor quedan por compatibilidad
    (esos bloques ya traen su propio encabezado)."""
    from types import SimpleNamespace
    documento_a_docx(SimpleNamespace(bloques=list(bloques),
                                     titulo=titulo, autor=autor),
                     Path(ruta))


def documento_a_rtf(doc: "Documento") -> str:
    """RTF básico con tipografía Courier. Soporta los 9 elementos
    aplicando sangrías y alineación aproximadas. ACTO_INICIO/FIN en bold.
    Incluye header con número de página en la esquina superior derecha.
    """
    def esc(s: str) -> str:
        # Caracteres no-ASCII como \uNNN?
        out = []
        for ch in s:
            n = ord(ch)
            if ch == "\\": out.append("\\\\")
            elif ch == "{": out.append("\\{")
            elif ch == "}": out.append("\\}")
            elif n < 128: out.append(ch)
            else: out.append(f"\\u{n}?")
        return "".join(out)

    # \header = encabezado en todas las páginas; \qr = alineado derecha
    # \chpgn = número de página actual. Formato "N."
    header_rtf = (r"{\header\pard\qr\f0\fs24 "
                  r"\chpgn .\par}")
    partes = [r"{\rtf1\ansi\deff0",
              r"{\fonttbl{\f0 Courier New;}}",
              header_rtf,
              r"\f0\fs24"]   # 12pt = 24 half-points

    for b in doc.bloques:
        izq, der = SANGRIA[b.elem]
        cw_twips = 120  # un caracter Courier 12pt ≈ 120 twips
        margen_izq = (15 + izq) * cw_twips
        margen_der = (10 + der) * cw_twips
        if b.elem == Elem.TRANSICION:
            alineacion = r"\qr"
        elif b.elem in (Elem.ACTO_INICIO, Elem.ACTO_FIN):
            alineacion = r"\qc"
        else:
            alineacion = r"\ql"
        bold_open  = r"\b\ul " if b.elem in (Elem.ACTO_INICIO, Elem.ACTO_FIN) else ""
        bold_close = r"\b0\ulnone" if b.elem in (Elem.ACTO_INICIO, Elem.ACTO_FIN) else ""
        partes.append(
            f"\\pard{alineacion}\\li{margen_izq}\\ri{margen_der}"
            f"\\sa120 {bold_open}{esc(b.texto)}{bold_close}\\par"
        )
    partes.append("}")
    return "\n".join(partes)


def guardar_documento_qt_para_export(doc: "Documento",
                                     margen_izq_chars: int = 15,
                                     margen_der_chars: int = 10) -> QTextDocument:
    """Construye un QTextDocument con el formato del guion (para PDF/print).
    No usa el editor (más rápido y sin dependencias de UI).
    """
    qdoc = QTextDocument()
    font = QFont(FONT_FAMILY, FONT_SIZE_PT)
    font.setStyleHint(QFont.StyleHint.TypeWriter)
    qdoc.setDefaultFont(font)
    fm = QFontMetricsF(font)
    cw = fm.horizontalAdvance("M")

    cursor = QTextCursor(qdoc)
    cursor.beginEditBlock()
    cursor.movePosition(QTextCursor.MoveOperation.Start)

    primer = True
    for b in doc.bloques:
        if not primer:
            cursor.insertBlock()
        primer = False

        bf = QTextBlockFormat()
        sangria_izq, sangria_der = SANGRIA[b.elem]
        bf.setLeftMargin((margen_izq_chars + sangria_izq) * cw)
        bf.setRightMargin((margen_der_chars + sangria_der) * cw)
        bf.setTopMargin(AIRE_ARRIBA[b.elem] * 7)
        if b.elem == Elem.TRANSICION:
            bf.setAlignment(Qt.AlignmentFlag.AlignRight)
        elif b.elem in (Elem.ACTO_INICIO, Elem.ACTO_FIN):
            bf.setAlignment(Qt.AlignmentFlag.AlignCenter)
        else:
            bf.setAlignment(Qt.AlignmentFlag.AlignLeft)

        cf = QTextCharFormat()
        font_b = QFont(font)
        if b.elem in (Elem.ACTO_INICIO, Elem.ACTO_FIN):
            font_b.setBold(True)
            font_b.setUnderline(True)
        cf.setFont(font_b)

        cursor.setBlockFormat(bf)
        cursor.insertText(b.texto, cf)

    cursor.endEditBlock()
    return qdoc


# ═══════════════════════════════════════════════════════════════════════
# §5  IMPORTACIÓN FDX
# ═══════════════════════════════════════════════════════════════════════

FDX_A_ELEM: dict[str, Elem] = {
    "Scene Heading": Elem.ESCENA,
    "Action":        Elem.ACCION,
    "Character":     Elem.PERSONAJE,
    "Dialogue":      Elem.DIALOGO,
    "Parenthetical": Elem.PARENTESIS,
    "Transition":    Elem.TRANSICION,
    "Shot":          Elem.PLANO,
    "General":       Elem.ACCION,
    "Cast List":     Elem.ACCION,
    "Singing":       Elem.DIALOGO,
    "New Act":       Elem.ACTO_INICIO,
    "End of Act":    Elem.ACTO_FIN,
}

ELEM_A_FDX: dict[Elem, str] = {
    Elem.ESCENA:      "Scene Heading",
    Elem.ACCION:      "Action",
    Elem.PERSONAJE:   "Character",
    Elem.DIALOGO:     "Dialogue",
    Elem.PARENTESIS:  "Parenthetical",
    Elem.TRANSICION:  "Transition",
    Elem.PLANO:       "Shot",
    Elem.ACTO_INICIO: "New Act",
    Elem.ACTO_FIN:    "End of Act",
}


def detectar_bloques_texto_plano(texto: str) -> list["Bloque"]:
    """Analiza texto plano y devuelve una lista de Bloques
    intentando detectar la estructura clásica de un guion.

    Reglas heurísticas:
    • ESCENA: línea que empieza con INT., EXT., I/E., INT/EXT.
    • TRANSICIÓN: línea corta terminada en ':' o '.' con palabras
      típicas (CORTE A, FUNDIDO A NEGRO, FADE OUT, DISOLVENCIA…).
    • PERSONAJE: línea en MAYÚSCULAS corta (<40 chars), seguida de
      diálogo. Puede llevar acotación entre paréntesis.
    • PARÉNTESIS: línea que empieza con '(' y termina con ')', viene
      después de un PERSONAJE.
    • DIÁLOGO: texto que viene después de PERSONAJE / PARÉNTESIS.
    • PLANO: palabras clave (PRIMER PLANO, TRAVELLING, ZOOM…).
    • ACTO_INICIO / ACTO_FIN: "PRIMER ACTO", "FIN DEL PRIMER ACTO"…
    • ACCIÓN: todo lo demás.

    Pre-filtrado: números de página sueltos y headers de PDF con
    formato «Título ... 3» se descartan.

    No es 100% preciso — el usuario puede corregir con TAB o Ctrl+1-9.
    """
    if not texto:
        return []
    lineas_raw = texto.replace("\r\n", "\n").split("\n")

    # Pre-filtrado: descartar líneas que son:
    #  1. Solo un número (número de página suelto).
    #  2. Header de PDF con formato «Título   3» — mucho espacio en
    #     medio y termina en número corto.
    lineas: list[str] = []
    re_num_solo = re.compile(r"^\s*\d{1,4}\s*[.]?\s*$")
    re_header_pag = re.compile(r"^(.+?)\s{5,}\d{1,4}\s*$")
    for raw in lineas_raw:
        if re_num_solo.match(raw):
            # Número de página suelto: descartar
            continue
        m = re_header_pag.match(raw)
        if m:
            # Header con número al final. Conservar solo si el título
            # está en MAYÚSCULAS (podría ser un encabezado real, no
            # un header/footer). Los headers de PDF suelen ser mixed
            # case.
            titulo = m.group(1).strip()
            if titulo == titulo.upper() and len(titulo) < 40:
                # Podría ser un encabezado — conservar sin el número
                lineas.append(titulo)
            # Si no, descartar la línea completa (era header)
            continue
        lineas.append(raw)

    bloques: list[Bloque] = []
    prev_elem: Elem | None = None

    re_escena = re.compile(
        r"^\s*(INT\.?/?EXT\.?|EXT\.?/?INT\.?|INT\.|EXT\.|I/E\.?)\s+",
        re.IGNORECASE)
    palabras_transicion = {
        "CORTE A", "CORTA A", "FUNDIDO A NEGRO", "FUNDIDO A BLANCO",
        "FUNDIDO ENCADENADO", "DISOLVENCIA", "SMASH CUT", "MATCH CUT",
        "FADE IN", "FADE OUT", "FADE TO BLACK", "FADE TO WHITE",
        "FUNDE A", "CORTE", "DISSOLVE TO", "CUT TO", "IRIS IN",
        "IRIS OUT", "WIPE TO", "TIME CUT", "JUMP CUT"}
    palabras_plano = {
        "PRIMER PLANO", "PLANO GENERAL", "PLANO MEDIO",
        "PLANO AMERICANO", "PLANO DETALLE", "GRAN ANGULAR",
        "TRAVELLING", "ZOOM IN", "ZOOM OUT", "CONTRAPICADO",
        "PICADO", "PANORÁMICA", "STEADYCAM", "CÁMARA EN MANO",
        "POV", "OVER SHOULDER", "DOLLY", "TILT"}
    re_acto = re.compile(
        r"^\s*(PRIMER|SEGUNDO|TERCER|CUARTO|QUINTO)\s+ACTO\s*$",
        re.IGNORECASE)
    re_fin_acto = re.compile(
        r"^\s*FIN\s+DEL\s+(PRIMER|SEGUNDO|TERCER|CUARTO|QUINTO)"
        r"\s+ACTO\s*$", re.IGNORECASE)

    i = 0
    while i < len(lineas):
        raw = lineas[i]
        line = raw.strip()
        if not line:
            i += 1
            continue

        # ACTO_INICIO / ACTO_FIN
        if re_acto.match(line):
            bloques.append(Bloque(Elem.ACTO_INICIO, line.upper()))
            prev_elem = Elem.ACTO_INICIO
            i += 1
            continue
        if re_fin_acto.match(line) or line.upper().startswith("FIN DEL"):
            bloques.append(Bloque(Elem.ACTO_FIN, line.upper()))
            prev_elem = Elem.ACTO_FIN
            i += 1
            continue

        # ESCENA
        if re_escena.match(line):
            bloques.append(Bloque(Elem.ESCENA, line.upper()))
            prev_elem = Elem.ESCENA
            i += 1
            continue

        # TRANSICIÓN — reconoce tanto ':' como '.' al final si la
        # línea es corta y contiene palabras clave. También permite
        # transiciones sin puntuación pero muy cortas y en mayúsculas.
        upper = line.upper()
        line_sin_final = line.rstrip(":.").strip()
        upper_sin_final = line_sin_final.upper()
        termina_bien = upper.endswith(":") or upper.endswith(".")
        contiene_transicion = any(
            p in upper for p in palabras_transicion)
        es_transicion = (
            (termina_bien and len(line) < 30 and
             contiene_transicion) or
            (upper.endswith(":") and upper == line and
             len(line) < 20) or
            # FADE OUT / FADE IN sin nada al final
            (upper == line and len(line) < 20 and
             upper_sin_final in palabras_transicion))
        if es_transicion:
            bloques.append(Bloque(Elem.TRANSICION, line.upper()))
            prev_elem = Elem.TRANSICION
            i += 1
            continue

        # PLANO
        if any(p in upper for p in palabras_plano) and len(line) < 40:
            bloques.append(Bloque(Elem.PLANO, line.upper()))
            prev_elem = Elem.PLANO
            i += 1
            continue

        # PARÉNTESIS después de personaje
        if (prev_elem == Elem.PERSONAJE and
                line.startswith("(") and line.endswith(")")):
            bloques.append(Bloque(Elem.PARENTESIS, line))
            prev_elem = Elem.PARENTESIS
            i += 1
            continue

        # PERSONAJE: línea corta en mayúsculas
        nombre_test = re.sub(r"\s*\([^)]+\)\s*", " ", line).strip()
        es_mayus = (nombre_test == nombre_test.upper() and
                     2 < len(nombre_test) < 40 and
                     any(c.isalpha() for c in nombre_test) and
                     not upper.endswith(":") and
                     not upper.endswith(".") and
                     len(nombre_test.split()) <= 5)
        indent = len(raw) - len(raw.lstrip())
        # Buscar próxima línea no vacía
        proxima_no_vacia = ""
        j = i + 1
        while j < len(lineas):
            if lineas[j].strip():
                proxima_no_vacia = lineas[j].strip()
                break
            j += 1
        proxima_upper = proxima_no_vacia.upper()
        proxima_es_dialogo = (
            proxima_no_vacia and
            not re_escena.match(proxima_no_vacia) and
            not re_acto.match(proxima_no_vacia) and
            not (proxima_upper == proxima_no_vacia and
                  len(proxima_no_vacia) < 40))
        if es_mayus and (indent >= 10 or proxima_es_dialogo):
            bloques.append(Bloque(Elem.PERSONAJE,
                                    nombre_test.upper()))
            prev_elem = Elem.PERSONAJE
            i += 1
            continue

        # DIÁLOGO después de PERSONAJE o PARÉNTESIS
        if prev_elem in (Elem.PERSONAJE, Elem.PARENTESIS):
            texto_dial = [line]
            j = i + 1
            while j < len(lineas):
                l = lineas[j].strip()
                if not l:
                    break
                if re_escena.match(l) or re_acto.match(l):
                    break
                nombre_j = re.sub(
                    r"\s*\([^)]+\)\s*", " ", l).strip()
                if (nombre_j == nombre_j.upper() and
                        2 < len(nombre_j) < 40 and
                        len(nombre_j.split()) <= 5):
                    break
                texto_dial.append(l)
                j += 1
            bloques.append(Bloque(Elem.DIALOGO, " ".join(texto_dial)))
            prev_elem = Elem.DIALOGO
            i = j
            continue

        # ACCIÓN
        texto_acc = [line]
        j = i + 1
        while j < len(lineas):
            l = lineas[j].strip()
            if not l:
                break
            if re_escena.match(l) or re_acto.match(l):
                break
            nombre_j = re.sub(r"\s*\([^)]+\)\s*", " ", l).strip()
            if (nombre_j == nombre_j.upper() and
                    2 < len(nombre_j) < 40 and
                    len(nombre_j.split()) <= 5):
                break
            texto_acc.append(l)
            j += 1
        bloques.append(Bloque(Elem.ACCION, " ".join(texto_acc)))
        prev_elem = Elem.ACCION
        i = j

    return bloques


def _fdx_texto_y_formatos(paragraph) -> tuple[str, list]:
    """Texto de un <Paragraph> y sus negritas/subrayados (<Text Style>)."""
    partes: list[str] = []
    formatos: list[dict] = []
    pos = 0
    for text_el in paragraph.findall("Text"):
        t = text_el.text or ""
        estilo = (text_el.get("Style") or "").lower()
        if t and ("bold" in estilo or "underline" in estilo):
            f = {"desde": pos, "hasta": pos + len(t)}
            if "bold" in estilo:
                f["negrita"] = True
            if "underline" in estilo:
                f["subrayado"] = True
            formatos.append(f)
        partes.append(t)
        pos += len(t)
    texto = "".join(partes)
    izq = len(texto) - len(texto.lstrip())
    texto = texto.strip()
    if izq:
        for f in formatos:
            f["desde"] = max(0, f["desde"] - izq)
            f["hasta"] = max(0, f["hasta"] - izq)
    formatos = [f for f in formatos if f["hasta"] > f["desde"]]
    return texto, formatos


def leer_fdx(ruta: str | Path) -> list[Bloque]:
    """Lee un archivo .fdx (formato XML estándar de la industria) y devuelve la lista de
    bloques. Este importador es LIMPIO: no arrastra fichas de
    personajes ni locaciones de otros archivos — solo lee el guion
    del XML.

    Formato .fdx: XML con <FinalDraft> como raíz. Los bloques
    son <Paragraph Type="..."> y adentro <Text>texto</Text>. Lee
    también diálogos dobles (<DualDialogue>), números de escena fijos
    (Number="12A") y negritas/subrayados. La portada (<TitlePage>) NO
    se mezcla con el guion: se lee aparte con leer_fdx_portada().
    """
    tree = ET.parse(str(ruta))
    root = tree.getroot()
    contenido = root.find("Content")
    if contenido is None:
        contenido = root
    bloques: list[Bloque] = []

    def agregar(paragraph, doble_pendiente: list) -> None:
        tipo_str = paragraph.get("Type", "Action")
        elem = FDX_A_ELEM.get(tipo_str, Elem.ACCION)
        texto, formatos = _fdx_texto_y_formatos(paragraph)
        if not texto:
            return
        texto = aplicar_caso_a_texto(elem, texto)
        b = Bloque(elem, texto, formatos=formatos)
        if elem == Elem.ESCENA and paragraph.get("Number"):
            b.numero = str(paragraph.get("Number")).strip()
        if elem == Elem.PERSONAJE and doble_pendiente:
            if doble_pendiente[0] > 0:
                b.doble = True
            doble_pendiente[0] += 1
        bloques.append(b)

    for paragraph in contenido.findall("Paragraph"):
        dual = paragraph.find("DualDialogue")
        if dual is not None:
            contador = [0]
            for interno in dual.findall("Paragraph"):
                agregar(interno, contador)
            continue
        agregar(paragraph, [])
    return bloques


def leer_fdx_portada(ruta: str | Path) -> dict:
    """Lee la portada (<TitlePage>) de un .fdx, si tiene. Heurística:
    1ª línea = título; la que sigue a «escrito por / written by» =
    autor; «basado en…»; las últimas líneas alineadas a la izquierda =
    contacto."""
    try:
        root = ET.parse(str(ruta)).getroot()
    except Exception:
        return {}
    tp = root.find("TitlePage")
    if tp is None:
        return {}
    lineas = []
    for par in tp.iter("Paragraph"):
        t, _ = _fdx_texto_y_formatos(par)
        lineas.append((t, (par.get("Alignment") or "").lower()))
    textos = [t for t, _ in lineas if t]
    if not textos:
        return {}
    res: dict = {"titulo": textos[0]}
    contacto = []
    for k, (t, al) in enumerate(lineas):
        tl = t.lower()
        if not t or t == textos[0]:
            continue
        if tl in ("escrito por", "written by", "por", "by", "guion de"):
            sig = next((x for x, _ in lineas[k + 1:] if x), "")
            if sig:
                res["autor_id"] = sig
            continue
        if res.get("autor_id") == t:
            continue
        if tl.startswith(("basado en", "based on")):
            res["basado_en"] = re.sub(r"^(basado en|based on)\s*", "", t,
                                      flags=re.I)
        elif al in ("left", "") and k > len(lineas) // 2:
            contacto.append(t)
    if contacto:
        res["contacto"] = "\n".join(contacto)
    return res


def leer_celtx(ruta: str | Path) -> list[Bloque]:
    """Lee un archivo .celtx.

    Los archivos .celtx son ZIP que contienen múltiples archivos. El guion
    principal suele estar en un HTML dentro del ZIP con clases CSS
    específicas por tipo de bloque:
    - .sceneheading  → ESCENA
    - .action        → ACCIÓN
    - .character     → PERSONAJE
    - .dialog        → DIÁLOGO
    - .parenthetical → PARÉNTESIS
    - .transition    → TRANSICIÓN
    - .shot          → PLANO

    Este importador es simple: extrae del ZIP el HTML, parsea las
    clases CSS y devuelve los bloques limpios. NO arrastra fichas
    de personajes ni locaciones — solo el guion.
    """
    import zipfile as _zip
    import re as _re
    from html import unescape as _unescape

    ruta_p = Path(ruta)
    bloques: list[Bloque] = []

    # Mapa clase CSS del .celtx → nuestro Elem
    CELTX_A_ELEM = {
        "sceneheading":  Elem.ESCENA,
        "scene":         Elem.ESCENA,
        "sceneHeading":  Elem.ESCENA,
        "action":        Elem.ACCION,
        "character":     Elem.PERSONAJE,
        "dialog":        Elem.DIALOGO,
        "dialogue":      Elem.DIALOGO,
        "parenthetical": Elem.PARENTESIS,
        "transition":    Elem.TRANSICION,
        "shot":          Elem.PLANO,
        "general":       Elem.ACCION,
    }

    # ── Extraer HTML del ZIP ──────────────────────────────────
    contenido_html = ""
    try:
        with _zip.ZipFile(ruta_p) as z:
            # Buscar el HTML principal del guion
            candidatos = [n for n in z.namelist()
                          if n.endswith(".html")
                          and "script" in n.lower()]
            if not candidatos:
                candidatos = [n for n in z.namelist()
                              if n.endswith(".html")]
            if not candidatos:
                raise ValueError(
                    "El archivo .celtx no contiene ningún .html (¿archivo dañado?)")
            # El más grande suele ser el guion completo
            candidatos.sort(
                key=lambda n: z.getinfo(n).file_size, reverse=True)
            with z.open(candidatos[0]) as f:
                contenido_html = f.read().decode("utf-8", errors="replace")
    except _zip.BadZipFile:
        # Puede ser un archivo .celtx antiguo que es solo HTML plano
        try:
            contenido_html = ruta_p.read_text(
                encoding="utf-8", errors="replace")
        except Exception as e:
            raise ValueError(f"No se pudo leer el archivo .celtx: {e}")

    # ── Parsear el HTML: buscar bloques por clase CSS ─────────
    # Regex flexible: <p class="X" ...>contenido</p> o
    # <div class="X" ...>contenido</div>. Los .celtx usan ambos.
    patron = _re.compile(
        r'<(?:p|div)[^>]*\bclass\s*=\s*["\']([^"\']+)["\'][^>]*>'
        r'(.*?)</(?:p|div)>',
        _re.DOTALL | _re.IGNORECASE)

    for m in patron.finditer(contenido_html):
        clases = m.group(1).split()
        contenido = m.group(2)
        # Limpiar tags HTML internos
        contenido = _re.sub(r"<br\s*/?>", "\n", contenido,
                             flags=_re.IGNORECASE)
        contenido = _re.sub(r"<[^>]+>", "", contenido)
        contenido = _unescape(contenido).strip()
        if not contenido:
            continue
        # Determinar el Elem por la primera clase reconocida
        elem: Optional[Elem] = None
        for cls in clases:
            cls_lower = cls.lower()
            if cls_lower in CELTX_A_ELEM:
                elem = CELTX_A_ELEM[cls_lower]
                break
        if elem is None:
            continue
        texto = aplicar_caso_a_texto(elem, contenido)
        bloques.append(Bloque(elem, texto))

    return bloques


def _valor_int_de_tag(tag: dict) -> int:
    """Extrae el valor numérico del tag como int. Ignora símbolos
    de moneda, separadores, etc. Si no es numérico, devuelve 0."""
    valor = tag.get("valor", "")
    if not valor:
        return 0
    # Quitar todo lo que no sea dígito
    digitos = "".join(c for c in str(valor) if c.isdigit())
    try:
        return int(digitos) if digitos else 0
    except (ValueError, TypeError):
        return 0


def calcular_costo_tag(tag: dict, dias_uso: int = 1) -> int:
    """Calcula el costo total de un tag según su tipo de compra:

    - "unica"    → valor × 1
    - "cantidad" → valor × cantidad
    - "diaria"   → valor × dias_uso (cuántos días de rodaje aparece
                   la escena que contiene este tag)

    Devuelve el monto en pesos (int).
    """
    valor = _valor_int_de_tag(tag)
    if valor <= 0:
        return 0
    tipo = tag.get("tipo_compra", "unica")
    if tipo == "cantidad":
        try:
            cant = int(tag.get("cantidad", 1) or 1)
        except (ValueError, TypeError):
            cant = 1
        return valor * max(1, cant)
    if tipo == "diaria":
        return valor * max(1, int(dias_uso))
    # "unica" (o cualquier valor desconocido)
    return valor


def dias_rodaje_por_escena(doc) -> dict[int, int]:
    """Cuenta cuántos días de rodaje diferentes utilizan cada escena.
    Devuelve dict {num_escena: n_dias}.

    Un mismo día que grabe 3 escenas cuenta como 1 día por cada
    escena. Si una jornada abarca 3 días (fecha..fecha_fin) y graba
    la escena N, la escena N cuenta como 3 días.
    """
    from datetime import date as _date, timedelta as _td
    resultado: dict[int, int] = {}
    for j in getattr(doc, "jornadas", []) or []:
        if not j.escenas:
            continue
        # Días de rodaje que abarca esta jornada
        try:
            fi = _date.fromisoformat(j.fecha) if j.fecha else None
            ff = (_date.fromisoformat(j.fecha_fin)
                  if j.fecha_fin else fi)
        except Exception:
            fi = ff = None
        if fi is None:
            n_dias = 1
        else:
            n_dias = (ff - fi).days + 1 if ff else 1
            if n_dias < 1:
                n_dias = 1
        # Números de escena
        for s in (j.escenas or "").split(","):
            s = s.strip()
            if s.isdigit():
                num = int(s)
                resultado[num] = resultado.get(num, 0) + n_dias
    return resultado


def costo_dia_recurso(obj, clave_precio: str = "precio_dia") -> float:
    """Costo total por día de un recurso: su precio/valor diario
    MÁS transporte y alimentación diarios (si están definidos).
    Así la Carta Gantt y los informes reflejan el costo real."""
    base = parse_precio(getattr(obj, clave_precio, "") or "0")
    trans = parse_precio(getattr(obj, "transporte_dia", "") or "0")
    alim = parse_precio(getattr(obj, "alimentacion_dia", "") or "0")
    return base + trans + alim


def calcular_costo_tags_totales(doc) -> dict:
    """Calcula el costo total de todos los tags del documento.
    Devuelve un dict con:
      - total: int  (suma de todos)
      - por_categoria: dict[str, int]
      - por_escena: dict[int, int]
      - desglose: list[dict]  (uno por tag con costo > 0)
    """
    dias_por_esc = dias_rodaje_por_escena(doc)
    resultado = {
        "total": 0,
        "por_categoria": {},
        "por_escena": {},
        "desglose": [],
    }
    esc_num = 0
    for i_b, b in enumerate(getattr(doc, "bloques", []) or []):
        if b.elem == Elem.ESCENA:
            esc_num += 1
        for i_t, t in enumerate(b.tags or []):
            if t.get("categoria") == "nota":
                continue
            dias_uso = dias_por_esc.get(esc_num, 1) if esc_num > 0 else 1
            costo = calcular_costo_tag(t, dias_uso)
            if costo <= 0:
                continue
            cat = t.get("categoria", "?")
            resultado["total"] += costo
            resultado["por_categoria"][cat] = (
                resultado["por_categoria"].get(cat, 0) + costo)
            resultado["por_escena"][esc_num] = (
                resultado["por_escena"].get(esc_num, 0) + costo)
            resultado["desglose"].append({
                "escena": esc_num,
                "categoria": cat,
                "contenido": t.get("contenido", ""),
                "icono": t.get("icono", ""),
                "valor_unitario": _valor_int_de_tag(t),
                "tipo_compra": t.get("tipo_compra", "unica"),
                "cantidad": int(t.get("cantidad", 1) or 1),
                "dias_uso": dias_uso,
                "costo_total": costo,
                "idx_bloque": i_b,
                "idx_tag": i_t,
            })
    return resultado


def extraer_locaciones_de_bloques(bloques: list[Bloque]) -> dict[str, "Locacion"]:
    """Recorre los encabezados de escena y devuelve un dict
    {nombre_locacion: Locacion}. Útil al abrir un FDX que no trae
    fichas de producción.
    """
    out: dict[str, Locacion] = {}
    for b in bloques:
        if b.elem != Elem.ESCENA:
            continue
        nombre = _locacion_desde_encabezado(b.texto)
        if nombre and nombre != "SIN LOCACIÓN" and nombre not in out:
            out[nombre] = Locacion(nombre=nombre)
    return out


def escribir_fdx(ruta: str | Path, bloques: list[Bloque],
                 portada: Optional[dict] = None,
                 numeros: Optional[dict] = None) -> None:
    """Guarda los bloques como un archivo .fdx (formato XML estándar).

    Genera un XML válido según el esquema estándar del formato .fdx:
    - Raíz <FinalDraft> con DocumentType="Script".
    - <Content> contiene los <Paragraph Type="...">.
    - Cada Paragraph tiene <Text> (con Style="Bold"/"Underline" donde
      el usuario puso negrita o subrayado).
    - Diálogo doble → <DualDialogue>; números de escena fijos (si se
      pasan en `numeros`: idx → "12A") → Number="…"; portada →
      <TitlePage>.

    El archivo resultante abre en cualquier app profesional de guion
    compatible con formato .fdx estándar.
    """
    def esc_xml(s: str) -> str:
        return (s.replace("&", "&amp;")
                 .replace("<", "&lt;")
                 .replace(">", "&gt;")
                 .replace('"', "&quot;")
                 .replace("'", "&apos;"))

    def textos(b: Bloque) -> str:
        t = b.texto or ""
        cortes = {0, len(t)}
        for f in b.formatos or []:
            try:
                cortes.update((max(0, int(f["desde"])),
                               min(len(t), int(f["hasta"]))))
            except (KeyError, TypeError, ValueError):
                pass
        cortes = sorted(c for c in cortes if 0 <= c <= len(t))
        out = []
        for a, z in zip(cortes, cortes[1:]):
            if a >= z:
                continue
            estilos = []
            for f in b.formatos or []:
                try:
                    if int(f["desde"]) <= a and z <= int(f["hasta"]):
                        if f.get("negrita") and "Bold" not in estilos:
                            estilos.append("Bold")
                        if f.get("subrayado") and "Underline" not in estilos:
                            estilos.append("Underline")
                except (KeyError, TypeError, ValueError):
                    pass
            st = f' Style="{"+".join(estilos)}"' if estilos else ""
            out.append(f"<Text{st}>{esc_xml(t[a:z])}</Text>")
        return "".join(out) or "<Text></Text>"

    def parrafo(i: int, b: Bloque) -> str:
        tipo_fdx = ELEM_A_FDX.get(b.elem, "Action")
        attrs = f'Type="{tipo_fdx}"'
        if b.elem == Elem.ESCENA and numeros and numeros.get(i):
            attrs += f' Number="{esc_xml(str(numeros[i]))}"'
        return f"<Paragraph {attrs}>\n{textos(b)}\n</Paragraph>"

    lineas: list[str] = []
    lineas.append('<?xml version="1.0" encoding="UTF-8" standalone="no" ?>')
    lineas.append('<FinalDraft DocumentType="Script" Template="No" '
                  'Version="5">')
    lineas.append('<Content>')
    i = 0
    n = len(bloques)
    while i < n:
        b = bloques[i]
        # ¿Empieza un diálogo doble? (este personaje + el siguiente «doble»)
        if b.elem == Elem.PERSONAJE:
            j = i + 1
            while j < n and bloques[j].elem in (Elem.DIALOGO, Elem.PARENTESIS):
                j += 1
            if j < n and bloques[j].elem == Elem.PERSONAJE and \
                    getattr(bloques[j], "doble", False):
                k = j + 1
                while k < n and bloques[k].elem in (Elem.DIALOGO,
                                                    Elem.PARENTESIS):
                    k += 1
                lineas.append("<Paragraph>\n<DualDialogue>")
                for x in range(i, k):
                    lineas.append(parrafo(x, bloques[x]))
                lineas.append("</DualDialogue>\n</Paragraph>")
                i = k
                continue
        lineas.append(parrafo(i, b))
        i += 1
    lineas.append('</Content>')
    if portada and any((portada.get(k) or "").strip() for k in portada):
        tp = ['<TitlePage>', '<Content>']

        def p_tp(texto: str, alin: str = "Center") -> None:
            tp.append(f'<Paragraph Alignment="{alin}" Type="Action">'
                      f'<Text>{esc_xml(texto)}</Text></Paragraph>')
        for _ in range(12):
            p_tp("")
        if portada.get("titulo"):
            p_tp(str(portada["titulo"]).upper())
            p_tp("")
        if portada.get("autor_id"):
            p_tp("escrito por")
            p_tp(str(portada["autor_id"]))
            p_tp("")
        if portada.get("basado_en"):
            p_tp(f"Basado en {portada['basado_en']}")
        if portada.get("borrador"):
            p_tp(str(portada["borrador"]))
        for _ in range(14):
            p_tp("", "Left")
        for linea in str(portada.get("contacto") or "").splitlines():
            p_tp(linea, "Left")
        if portada.get("fecha_portada"):
            p_tp(str(portada["fecha_portada"]), "Left")
        tp += ['</Content>', '</TitlePage>']
        lineas += tp
    lineas.append('</FinalDraft>')
    Path(ruta).write_text("\n".join(lineas), encoding="utf-8")


# ── FOUNTAIN (.fountain) ──────────────────────────────────────────────
# Formato de texto plano estándar para guiones (fountain.io): lo usan
# Highland, Beat, WriterSolo, Slugline, Trelby y muchos más, y se puede
# escribir desde el celular con cualquier app de notas.
#
# Mapeo con ¡Acción!:
#   Encabezado → «INT./EXT. …» (o «.ENCABEZADO» forzado) + «#12A#» si la
#                numeración está bloqueada.
#   Personaje  → MAYÚSCULAS (o «@Nombre»); diálogo doble → «NOMBRE ^».
#   Transición → «> CORTE A:»   ·   Acto → «> PRIMER ACTO <» (centrado)
#   Plano      → «!PRIMER PLANO DE ANA» (acción forzada en mayúsculas;
#                al importar se reconoce por sus palabras clave).
#   Negrita **así** · Subrayado _así_ (los colores no existen en Fountain).

_RE_ESCENA_FOUNTAIN = re.compile(
    r"^(INT|EXT|EST|INT\.?/EXT|EXT\.?/INT|I/E|INT/EXT)[.\s]", re.IGNORECASE)
_RE_NUM_ESCENA_FOUNTAIN = re.compile(r"\s*#([\w.\-]+)#\s*$")
PALABRAS_PLANO = (
    "PRIMER PLANO", "PRIMERÍSIMO PRIMER PLANO", "PLANO GENERAL",
    "PLANO MEDIO", "PLANO AMERICANO", "PLANO DETALLE", "PLANO ENTERO",
    "PLANO SECUENCIA", "PLANO CONTRAPLANO", "GRAN PLANO GENERAL",
    "GRAN ANGULAR", "TRAVELLING", "ZOOM IN", "ZOOM OUT", "CONTRAPICADO",
    "PICADO", "CENITAL", "PANORÁMICA", "PANEO", "STEADYCAM", "STEADICAM",
    "CÁMARA EN MANO", "POV", "OVER SHOULDER", "DOLLY", "TILT", "INSERTO",
    "INSERT", "CLOSE UP", "SOBRE EL HOMBRO", "NUEVO ÁNGULO", "CONTRAPLANO",
    "DE VUELTA A LA ESCENA", "PLANO ")
_TRANSICIONES_ES = ("CORTE", "CORTA A", "FUNDIDO", "FUNDE A", "DISOLVENCIA",
                    "ENCADENADO", "BARRIDO", "SMASH CUT", "MATCH CUT",
                    "JUMP CUT")


def _es_plano(texto: str) -> bool:
    t = (texto or "").strip()
    if not t or t != t.upper():
        return False
    return any(t.startswith(p) or f" {p}" in f" {t}" for p in PALABRAS_PLANO)


def _fountain_marcar(b: "Bloque", texto: str) -> str:
    """Texto con **negrita** y _subrayado_ (escapando * y _ literales)."""
    marcas: dict[int, list[str]] = {}
    for f in b.formatos or []:
        try:
            a, z = int(f["desde"]), int(f["hasta"])
        except (KeyError, TypeError, ValueError):
            continue
        a, z = max(0, a), min(len(texto), z)
        if a >= z:
            continue
        if f.get("negrita"):
            marcas.setdefault(a, []).append("**")
            marcas.setdefault(z, []).insert(0, "**")
        if f.get("subrayado"):
            marcas.setdefault(a, []).append("_")
            marcas.setdefault(z, []).insert(0, "_")
    out = []
    for k, ch in enumerate(texto):
        out.extend(marcas.get(k, []))
        out.append("\\" + ch if ch in "*_\\" else ch)
    out.extend(marcas.get(len(texto), []))
    return "".join(out)


def _fountain_desmarcar(texto: str) -> tuple[str, list]:
    """Quita **, * y _ de Fountain y devuelve (texto, formatos)."""
    out: list[str] = []
    formatos: list[dict] = []
    abiertos: dict[str, int] = {}
    i = 0
    n = len(texto)
    while i < n:
        ch = texto[i]
        if ch == "\\" and i + 1 < n:
            out.append(texto[i + 1])
            i += 2
            continue
        token = None
        if texto.startswith("***", i):
            token = "***"
        elif texto.startswith("**", i):
            token = "**"
        elif ch in "*_":
            token = ch
        if token:
            claves = {"***": ("negrita",), "**": ("negrita",), "*": (),
                      "_": ("subrayado",)}[token]
            pos = len("".join(out))
            if token in abiertos:
                ini = abiertos.pop(token)
                if claves and pos > ini:
                    f = {"desde": ini, "hasta": pos}
                    for c in claves:
                        f[c] = True
                    formatos.append(f)
            elif texto.find(token, i + len(token)) > i:
                abiertos[token] = pos
            else:
                out.append(token)       # sin cierre: es texto literal
            i += len(token)
            continue
        out.append(ch)
        i += 1
    return "".join(out), formatos


def escribir_fountain(ruta, bloques: list, portada: Optional[dict] = None,
                      numeros: Optional[dict] = None) -> None:
    """Guarda el guion como .fountain (UTF-8)."""
    out: list[str] = []
    portada = portada or {}
    claves = [("Title", "titulo"), ("Credit", None), ("Author", "autor_id"),
              ("Source", "basado_en"), ("Revision", "borrador"),
              ("Draft date", "fecha_portada"), ("Contact", "contacto")]
    if any((portada.get(k) or "").strip() for _, k in claves if k):
        for etq, k in claves:
            if k is None:
                if portada.get("autor_id"):
                    out.append("Credit: escrito por")
                continue
            v = str(portada.get(k) or "").strip()
            if not v:
                continue
            if "\n" in v:
                out.append(f"{etq}:")
                out += [f"    {x}" for x in v.splitlines()]
            else:
                out.append(f"{etq}: {v}")
        out.append("")

    def bloque_txt(b) -> str:
        return _fountain_marcar(b, b.texto or "")

    previo = None
    for i, b in enumerate(bloques):
        e = b.elem
        t = (b.texto or "").strip()
        if not t and e != Elem.ACCION:
            continue
        pegado = e in (Elem.DIALOGO, Elem.PARENTESIS) and previo in (
            Elem.PERSONAJE, Elem.DIALOGO, Elem.PARENTESIS)
        if not pegado and out and out[-1] != "":
            out.append("")
        if e == Elem.ESCENA:
            linea = bloque_txt(b).strip()
            if not _RE_ESCENA_FOUNTAIN.match(t):
                linea = "." + linea
            if numeros and numeros.get(i):
                linea += f" #{numeros[i]}#"
            out.append(linea)
        elif e == Elem.PERSONAJE:
            nombre = t.upper()
            linea = nombre if nombre == t and re.search(r"[A-ZÁÉÍÓÚÑ]", t) \
                else "@" + t
            if getattr(b, "doble", False):
                linea += " ^"
            out.append(linea)
        elif e == Elem.PARENTESIS:
            out.append(t if t.startswith("(") else f"({t})")
        elif e == Elem.DIALOGO:
            for linea in bloque_txt(b).split("\n"):
                out.append(linea if linea.strip() else "  ")
        elif e == Elem.TRANSICION:
            out.append(t.upper() if (t.upper().endswith("TO:")
                                     and t == t.upper()) else f"> {t.upper()}")
        elif e in (Elem.ACTO_INICIO, Elem.ACTO_FIN):
            out.append(f"> {t.upper()} <")
        elif e == Elem.PLANO:
            out.append("!" + t.upper())
        else:   # ACCION
            txt = bloque_txt(b)
            lineas = txt.split("\n") if txt else [""]
            for k, linea in enumerate(lineas):
                forzar = (k == 0 and (
                    (linea.strip() and linea.strip() == linea.strip().upper()
                     and re.search(r"[A-ZÁÉÍÓÚÑ]", linea))
                    or linea[:1] in ".!@~>#=[" or
                    _RE_ESCENA_FOUNTAIN.match(linea.strip())))
                out.append(("!" if forzar else "") + linea)
        previo = e
    Path(ruta).write_text("\n".join(out).rstrip() + "\n", encoding="utf-8")


def piezas_desde_texto_guion(texto: str) -> list[dict]:
    """Un texto pegado de otro programa, repartido en bloques del guion.
    Una sola línea se pega tal cual (dentro del bloque). Con líneas en
    blanco entre párrafos se lee como Fountain; sin ellas, cada línea es un
    bloque: encabezados (INT./EXT.), transiciones, personajes (en
    mayúsculas, antes de un diálogo), paréntesis, diálogos y acción."""
    texto = (texto or "").replace("\r\n", "\n").replace("\r", "\n").replace("\u2029", "\n") \
        .replace("\u2028", "\n").replace("\t", "    ")
    if "\n" not in texto.strip("\n"):
        return [{"elem": int(Elem.ACCION), "texto": texto.strip("\n")}] if texto.strip("\n") else []
    lineas = texto.strip("\n").split("\n")
    if any(not l.strip() for l in lineas):
        try:
            import tempfile as _tf
            with _tf.NamedTemporaryFile("w", suffix=".fountain", delete=False, encoding="utf-8") as f_:
                f_.write("\n" + texto)           # (sin portada)
                ruta_ = f_.name
            try:
                bloques, _portada = leer_fountain(ruta_)
            finally:
                Path(ruta_).unlink(missing_ok=True)
            if bloques:
                return [{"elem": int(b.elem), "texto": b.texto.replace("\n", " "), "formatos": b.formatos}
                        for b in bloques]
        except Exception:
            pass
    piezas: list[dict] = []
    previo = None
    for k, l in enumerate(lineas):
        t = l.strip()
        if not t:
            continue
        tu = t.upper()
        siguiente = next((x.strip() for x in lineas[k + 1:] if x.strip()), "")
        if _RE_ESCENA_FOUNTAIN.match(t):
            elem = Elem.ESCENA
        elif t == tu and tu.endswith(":") and (tu.endswith("TO:") or tu.startswith(_TRANSICIONES_ES)):
            elem = Elem.TRANSICION
        elif t.startswith("(") and t.endswith(")") and previo in (Elem.PERSONAJE, Elem.DIALOGO):
            elem = Elem.PARENTESIS
        elif (re.search(r"[A-ZÁÉÍÓÚÑ]", t) and t == tu and len(t) <= 40 and siguiente
              and siguiente != siguiente.upper()):
            elem = Elem.PERSONAJE
        elif previo in (Elem.PERSONAJE, Elem.PARENTESIS):
            elem = Elem.DIALOGO
        else:
            elem = Elem.ACCION
        piezas.append({"elem": int(elem), "texto": aplicar_caso_a_texto(elem, t)})
        previo = elem
    return piezas


def leer_fountain(ruta) -> tuple[list, dict]:
    """Lee un .fountain. Devuelve (bloques, portada)."""
    texto = Path(ruta).read_text(encoding="utf-8-sig", errors="replace")
    texto = texto.replace("\r\n", "\n").replace("\r", "\n")
    texto = re.sub(r"/\*.*?\*/", "", texto, flags=re.S)      # boneyard
    texto = re.sub(r"\[\[.*?\]\]", "", texto, flags=re.S)    # notas
    lineas = texto.split("\n")

    # ── Portada ──
    portada: dict = {}
    mapa = {"title": "titulo", "author": "autor_id", "authors": "autor_id",
            "source": "basado_en", "revision": "borrador",
            "draft date": "fecha_portada", "date": "fecha_portada",
            "contact": "contacto"}
    i = 0
    if lineas and re.match(r"^[A-Za-z][A-Za-z ]*:", lineas[0] or ""):
        clave = None
        while i < len(lineas) and lineas[i].strip():
            l = lineas[i]
            m = re.match(r"^([A-Za-z][A-Za-z ]*):\s*(.*)$", l)
            if m and not l.startswith((" ", "\t")):
                clave = mapa.get(m.group(1).strip().lower())
                if clave and m.group(2).strip():
                    portada[clave] = m.group(2).strip()
            elif clave:
                previo = portada.get(clave, "")
                portada[clave] = (previo + "\n" if previo else "") + l.strip()
            i += 1
    for k in list(portada):
        portada[k] = _fountain_desmarcar(portada[k])[0]

    bloques: list = []

    def agregar(elem, t: str, **kw):
        t2, fmts = _fountain_desmarcar(t)
        t2 = aplicar_caso_a_texto(elem, t2.strip("\n"))
        b = Bloque(elem, t2, formatos=fmts)
        for k, v in kw.items():
            setattr(b, k, v)
        bloques.append(b)

    def vacia(k: int) -> bool:
        return k < 0 or k >= len(lineas) or not lineas[k].strip()

    accion: list[str] = []

    def cerrar_accion():
        if accion:
            t = "\n".join(accion).strip("\n")
            if t.strip():
                elem = Elem.PLANO if _es_plano(t) and "\n" not in t \
                    else Elem.ACCION
                agregar(elem, t)
            accion.clear()

    while i < len(lineas):
        raw = lineas[i]
        l = raw.strip()
        if not l:
            cerrar_accion()
            i += 1
            continue
        if re.match(r"^={3,}$", l) or l.startswith("#") or (
                l.startswith("=") and not l.startswith("==")):
            cerrar_accion()             # salto de página, sección, sinopsis
            i += 1
            continue
        if l.startswith("!"):
            accion.append(l[1:])
            i += 1
            continue
        # Centrado → acto
        if l.startswith(">") and l.endswith("<"):
            cerrar_accion()
            t = l[1:-1].strip()
            agregar(Elem.ACTO_FIN if t.upper().startswith("FIN")
                    else Elem.ACTO_INICIO, t)
            i += 1
            continue
        # Transición
        tu = l.upper()
        if l.startswith(">") or (vacia(i - 1) and vacia(i + 1) and l == tu and (
                tu.endswith("TO:") or (tu.endswith(":")
                                       and tu.startswith(_TRANSICIONES_ES)))):
            cerrar_accion()
            agregar(Elem.TRANSICION, l.lstrip(">").strip())
            i += 1
            continue
        # Encabezado de escena
        if vacia(i - 1) and ((l.startswith(".") and not l.startswith(".."))
                             or _RE_ESCENA_FOUNTAIN.match(l)):
            cerrar_accion()
            t = l[1:] if l.startswith(".") else l
            numero = ""
            m = _RE_NUM_ESCENA_FOUNTAIN.search(t)
            if m:
                numero = m.group(1)
                t = t[:m.start()]
            agregar(Elem.ESCENA, t.strip(), numero=numero)
            i += 1
            continue
        # Personaje + diálogo
        es_personaje = vacia(i - 1) and not vacia(i + 1) and (
            l.startswith("@") or (
                re.search(r"[A-ZÁÉÍÓÚÑ]", l)
                and re.sub(r"\([^)]*\)", "", l).replace("^", "").strip()
                == re.sub(r"\([^)]*\)", "", l).replace("^", "").strip().upper()))
        if es_personaje:
            cerrar_accion()
            nombre = l[1:] if l.startswith("@") else l
            doble = nombre.rstrip().endswith("^")
            nombre = nombre.rstrip().rstrip("^").strip()
            agregar(Elem.PERSONAJE, nombre, doble=doble)
            i += 1
            dialogo: list[str] = []
            while i < len(lineas) and (lineas[i].strip() or lineas[i] == "  "):
                d = lineas[i].strip()
                if d.startswith("(") and d.endswith(")"):
                    if dialogo:
                        agregar(Elem.DIALOGO, "\n".join(dialogo))
                        dialogo = []
                    agregar(Elem.PARENTESIS, d)
                else:
                    dialogo.append(d.lstrip("~").strip())
                i += 1
            if dialogo:
                agregar(Elem.DIALOGO, "\n".join(dialogo))
            continue
        accion.append(raw.rstrip())
        i += 1
    cerrar_accion()
    return bloques, portada


# ── Comparar dos versiones del guion ─────────────────────────────────
def _escenas_para_comparar(bloques: list) -> list[dict]:
    """Escenas (con el «inicio» antes de la primera, si hay) como
    listas de líneas «TIPO|texto» para comparar."""
    res: list[dict] = []
    actual = {"encabezado": "(inicio del guion)", "bloques": []}
    for b in bloques:
        if b.elem == Elem.ESCENA:
            if actual["bloques"] or res:
                res.append(actual)
            actual = {"encabezado": (b.texto or "").strip(), "bloques": []}
        if (b.texto or "").strip():
            actual["bloques"].append(b)
    res.append(actual)
    if res and res[0]["encabezado"] == "(inicio del guion)" and \
            not res[0]["bloques"]:
        res.pop(0)
    k = 0
    for e in res:
        if e["encabezado"] == "(inicio del guion)" and e is res[0]:
            e["n"] = 0              # lo que va antes de la 1ª escena
        else:
            k += 1
            e["n"] = k
        e["lineas"] = [f"{int(b.elem)}|{(b.texto or '').strip()}"
                       for b in e["bloques"]]
    return res


def comparar_guiones(anterior: list, actual: list) -> list[dict]:
    """Compara dos guiones escena por escena.

    Devuelve, en el orden del guion ACTUAL (con las borradas
    intercaladas donde estaban), dicts:
      estado:     "igual" | "modificada" | "nueva" | "borrada"
      movida:     True si cambió de lugar respecto de las demás
      encabezado: texto del encabezado (del actual; del anterior si borrada)
      n_antes / n_ahora: número de orden en cada versión (o None)
      cambios:    [(op, tipo, texto)] op ∈ "=", "+", "-" (por bloque)
      palabras:   +/− palabras (para el resumen)"""
    import difflib
    A = _escenas_para_comparar(anterior)
    B = _escenas_para_comparar(actual)
    usados: set[int] = set()
    pareja: dict[int, int] = {}          # índice en B → índice en A
    # 1) Idénticas (mismo contenido)
    por_contenido: dict[tuple, list[int]] = {}
    for ia, a in enumerate(A):
        por_contenido.setdefault(tuple(a["lineas"]), []).append(ia)
    for ib, b in enumerate(B):
        cand = [x for x in por_contenido.get(tuple(b["lineas"]), [])
                if x not in usados]
        if cand:
            pareja[ib] = cand[0]
            usados.add(cand[0])
    # 2) Parecidas (encabezado + contenido)
    for ib, b in enumerate(B):
        if ib in pareja:
            continue
        mejor, mejor_p = None, 0.0
        for ia, a in enumerate(A):
            if ia in usados:
                continue
            p_enc = difflib.SequenceMatcher(
                None, a["encabezado"].upper(), b["encabezado"].upper()).ratio()
            p_cont = difflib.SequenceMatcher(
                None, a["lineas"], b["lineas"]).ratio()
            p = 0.45 * p_enc + 0.55 * p_cont
            if p > mejor_p:
                mejor, mejor_p = ia, p
        if mejor is not None and mejor_p >= 0.5:
            pareja[ib] = mejor
            usados.add(mejor)
    # 3) Movidas: las que no están en la subsecuencia creciente más larga
    orden = [(ib, pareja[ib]) for ib in range(len(B)) if ib in pareja]
    seq = [ia for _, ia in orden]
    lis_idx: set[int] = set()
    if seq:
        import bisect
        colas: list[int] = []
        ind: list[int] = []
        previo = [-1] * len(seq)
        for k, x in enumerate(seq):
            j = bisect.bisect_left(colas, x)
            if j == len(colas):
                colas.append(x)
                ind.append(k)
            else:
                colas[j] = x
                ind[j] = k
            previo[k] = ind[j - 1] if j > 0 else -1
        k = ind[-1]
        while k >= 0:
            lis_idx.add(orden[k][0])
            k = previo[k]

    def detalle(a_bl: list, b_bl: list) -> tuple[list, int, int]:
        la = [(int(x.elem), (x.texto or "").strip()) for x in a_bl]
        lb = [(int(x.elem), (x.texto or "").strip()) for x in b_bl]
        cambios, mas, menos = [], 0, 0
        sm = difflib.SequenceMatcher(None, la, lb)
        for op, i1, i2, j1, j2 in sm.get_opcodes():
            if op == "equal":
                cambios += [("=", t, x) for t, x in la[i1:i2]]
                continue
            for t, x in la[i1:i2]:
                cambios.append(("-", t, x))
            for t, x in lb[j1:j2]:
                cambios.append(("+", t, x))
            if op == "replace" and (i2 - i1) == (j2 - j1):
                # Cuenta solo las palabras que realmente cambiaron
                for (_, xa), (_, xb) in zip(la[i1:i2], lb[j1:j2]):
                    wa, wb = xa.split(), xb.split()
                    for o2, a1, a2, b1, b2 in difflib.SequenceMatcher(
                            None, wa, wb).get_opcodes():
                        if o2 != "equal":
                            menos += a2 - a1
                            mas += b2 - b1
            else:
                menos += sum(len(x.split()) for _, x in la[i1:i2])
                mas += sum(len(x.split()) for _, x in lb[j1:j2])
        return cambios, mas, menos

    res: list[dict] = []
    pendientes_borradas = [ia for ia in range(len(A)) if ia not in usados]

    def volcar_borradas(hasta_ia: int):
        while pendientes_borradas and pendientes_borradas[0] < hasta_ia:
            ia = pendientes_borradas.pop(0)
            c, mas, menos = detalle(A[ia]["bloques"], [])
            res.append({"estado": "borrada", "movida": False,
                        "encabezado": A[ia]["encabezado"],
                        "n_antes": A[ia]["n"], "n_ahora": None,
                        "cambios": c, "palabras": (0, menos)})

    for ib, b in enumerate(B):
        if ib in pareja:
            ia = pareja[ib]
            if ib in lis_idx:
                volcar_borradas(ia)
            c, mas, menos = detalle(A[ia]["bloques"], b["bloques"])
            igual = A[ia]["lineas"] == b["lineas"]
            res.append({"estado": "igual" if igual else "modificada",
                        "movida": ib not in lis_idx,
                        "encabezado": b["encabezado"],
                        "n_antes": A[ia]["n"], "n_ahora": b["n"],
                        "cambios": c, "palabras": (mas, menos)})
        else:
            c, mas, menos = detalle([], b["bloques"])
            res.append({"estado": "nueva", "movida": False,
                        "encabezado": b["encabezado"], "n_antes": None,
                        "n_ahora": b["n"], "cambios": c,
                        "palabras": (mas, 0)})
    volcar_borradas(10 ** 9)
    return res


def resumen_comparacion(res: list[dict]) -> dict:
    r = {"nueva": 0, "borrada": 0, "modificada": 0, "igual": 0, "movida": 0,
         "mas": 0, "menos": 0}
    for x in res:
        r[x["estado"]] += 1
        r["movida"] += 1 if x.get("movida") else 0
        r["mas"] += x["palabras"][0]
        r["menos"] += x["palabras"][1]
    return r


def _html_palabras(a: str, b: str) -> tuple[str, str]:
    """Resalta palabra por palabra lo que cambió entre a y b."""
    import difflib
    wa, wb = a.split(" "), b.split(" ")
    oa, ob = [], []
    for op, i1, i2, j1, j2 in difflib.SequenceMatcher(None, wa, wb).get_opcodes():
        ta = html.escape(" ".join(wa[i1:i2]))
        tb = html.escape(" ".join(wb[j1:j2]))
        if op == "equal":
            oa.append(ta)
            ob.append(tb)
        else:
            if ta:
                oa.append(f"<span style='background:#f8c4c4;'>{ta}</span>")
            if tb:
                ob.append(f"<span style='background:#bfe8c8;'>{tb}</span>")
    return " ".join(oa), " ".join(ob)


def html_comparacion(res: list[dict], titulo: str = "",
                     mostrar_iguales: bool = False,
                     solo: Optional[int] = None) -> str:
    """Informe HTML imprimible de la comparación."""
    colores = {"nueva": ("#1f7a3e", "#e7f6ec", "NUEVA"),
               "borrada": ("#b42318", "#fdecec", "BORRADA"),
               "modificada": ("#b45309", "#fff4e5", "MODIFICADA"),
               "igual": ("#5b6474", "#f3f4f6", "SIN CAMBIOS")}
    r = resumen_comparacion(res)
    out = ["<html><head><meta charset='utf-8'><style>"
           "body{font-family:'Segoe UI',Arial,sans-serif;color:#1a1a1a;}"
           "h2{margin:0 0 4px 0;} .res{color:#5b6474;margin-bottom:12px;}"
           ".esc{border:1px solid #d6d9de;border-radius:8px;margin:10px 0;"
           "padding:8px 10px;} .cab{font-weight:700;}"
           ".b{font-family:'Courier New',monospace;font-size:10pt;"
           "margin:2px 0;padding:1px 4px;white-space:pre-wrap;}"
           ".mas{background:#e7f6ec;} .menos{background:#fdecec;"
           "text-decoration:line-through;color:#7a1b13;}"
           "</style></head><body>"]
    if solo is None:
        out.append(f"<h2>🔀 Comparación de versiones {html.escape(titulo)}</h2>")
        out.append(
            f"<div class='res'>{r['nueva']} nuevas · {r['borrada']} borradas · "
            f"{r['modificada']} modificadas · {r['movida']} movidas · "
            f"{r['igual']} sin cambios — +{r['mas']} / −{r['menos']} "
            "palabras</div>")
    tipos = {int(e): NOMBRE[e] for e in Elem}
    for k, x in enumerate(res):
        if solo is not None and k != solo:
            continue
        if solo is None and x["estado"] == "igual" and not x.get("movida") \
                and not mostrar_iguales:
            continue
        fg, bg, etq = colores[x["estado"]]
        nums = []
        if x["n_antes"]:
            nums.append(f"antes escena {x['n_antes']}")
        if x["n_ahora"]:
            nums.append(f"ahora escena {x['n_ahora']}")
        if not nums:
            nums.append("antes de la primera escena")
        mov = " · <b>MOVIDA</b>" if x.get("movida") else ""
        out.append(
            f"<div class='esc' style='background:{bg};'>"
            f"<div class='cab' style='color:{fg};'>{etq}{mov} — "
            f"{html.escape(x['encabezado'])} "
            f"<span style='color:#5b6474;font-weight:400;'>"
            f"({', '.join(nums)})</span></div>")
        cambios = x["cambios"]
        i = 0
        while i < len(cambios):
            op, t, texto = cambios[i]
            etiqueta = f"<span style='color:#8a8f98;'>{tipos.get(t, '')}:</span> "
            # «−» seguido de «+» del mismo tipo → resaltar palabras
            if op == "-" and i + 1 < len(cambios) and cambios[i + 1][0] == "+" \
                    and cambios[i + 1][1] == t:
                ha, hb = _html_palabras(texto, cambios[i + 1][2])
                out.append(f"<div class='b menos' style='text-decoration:none;"
                           f"color:#1a1a1a;'>− {etiqueta}{ha}</div>")
                out.append(f"<div class='b mas'>+ {etiqueta}{hb}</div>")
                i += 2
                continue
            if op == "=":
                if x["estado"] in ("igual",) or solo is not None:
                    out.append(f"<div class='b'>&nbsp; {etiqueta}"
                               f"{html.escape(texto)}</div>")
            elif op == "+":
                out.append(f"<div class='b mas'>+ {etiqueta}"
                           f"{html.escape(texto)}</div>")
            else:
                out.append(f"<div class='b menos'>− {etiqueta}"
                           f"{html.escape(texto)}</div>")
            i += 1
        out.append("</div>")
    out.append("</body></html>")
    return "".join(out)


def bloques_de_archivo(ruta) -> list:
    """Bloques de un guion en disco (.accion, .fdx o .fountain)."""
    ruta = Path(ruta)
    suf = ruta.suffix.lower()
    if suf == ".fdx":
        return leer_fdx(ruta)
    if suf in (".fountain", ".spmd"):
        return leer_fountain(ruta)[0]
    return documento_desde_json(ruta.read_text(encoding="utf-8")).bloques


# ── Excel (.xlsx) sin librerías externas ─────────────────────────────
def _col_xlsx(n: int) -> str:
    s = ""
    n += 1
    while n:
        n, r = divmod(n - 1, 26)
        s = chr(65 + r) + s
    return s


def escribir_xlsx_simple(ruta, hojas: list, horizontal: bool = True,
                         papel: str = "carta") -> None:
    """Escribe un .xlsx (Office Open XML) con zipfile — NO necesita
    openpyxl. hojas: [(nombre, filas, anchos | None)]; la primera fila
    de cada hoja es el encabezado (negrita, fondo, se repite al
    imprimir). Listo para imprimir: horizontal, ajustado a UNA página
    de ancho, en Carta u Oficio.

    Un 4° elemento opcional de la hoja es un dict de opciones:
      · "miles": True  → los números se muestran como 1.234.567
      · "negrita": {índices de fila} → filas en negrita (totales)."""
    import zipfile as _zip
    from xml.sax.saxutils import escape as _x

    def celda(ref: str, v, estilo: int, miles: bool = False,
              negrita: bool = False) -> str:
        if isinstance(v, bool):
            v = "✓" if v else ""
        if isinstance(v, (int, float)) and not isinstance(v, bool):
            if estilo == 2 and (miles or negrita):
                estilo = (5 if miles else 4) if negrita else 3
            return f'<c r="{ref}" s="{estilo}"><v>{v}</v></c>'
        if estilo == 2 and negrita:
            estilo = 4
        t = _x(str(v if v is not None else ""))
        return (f'<c r="{ref}" s="{estilo}" t="inlineStr"><is><t '
                f'xml:space="preserve">{t}</t></is></c>')

    sheets_xml = []
    nombres = []
    for k, hoja in enumerate(hojas):
        nombre, filas = hoja[0], hoja[1]
        anchos = hoja[2] if len(hoja) > 2 else None
        opciones = hoja[3] if len(hoja) > 3 and isinstance(hoja[3], dict) else {}
        miles = bool(opciones.get("miles"))
        negritas = set(opciones.get("negrita", ()) or ())
        nombre = re.sub(r"[\[\]:*?/\\\\]", " ", str(nombre))[:31] or f"Hoja{k+1}"
        nombres.append(nombre)
        ncols = max((len(f) for f in filas), default=1)
        cols = ""
        if anchos:
            cols = "<cols>" + "".join(
                f'<col min="{i+1}" max="{i+1}" width="{w}" customWidth="1"/>'
                for i, w in enumerate(anchos)) + "</cols>"
        filas_xml = []
        for r, fila in enumerate(filas):
            estilo = 1 if r == 0 else 2
            cs = "".join(celda(f"{_col_xlsx(c)}{r+1}", v, estilo,
                               miles, r in negritas)
                         for c, v in enumerate(fila))
            filas_xml.append(f'<row r="{r+1}">{cs}</row>')
        ultima = f"{_col_xlsx(ncols - 1)}{max(1, len(filas))}"
        sheets_xml.append(
            '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            '<worksheet xmlns="http://schemas.openxmlformats.org/'
            'spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats'
            '.org/officeDocument/2006/relationships">'
            '<sheetPr><pageSetUpPr fitToPage="1"/></sheetPr>'
            f'<dimension ref="A1:{ultima}"/>'
            '<sheetViews><sheetView workbookViewId="0"><pane ySplit="1" '
            'topLeftCell="A2" activePane="bottomLeft" state="frozen"/>'
            '</sheetView></sheetViews>'
            f'{cols}<sheetData>{"".join(filas_xml)}</sheetData>'
            '<printOptions gridLines="0"/>'
            '<pageMargins left="0.4" right="0.4" top="0.5" bottom="0.5" '
            'header="0.3" footer="0.3"/>'
            f'<pageSetup paperSize="{5 if papel == "oficio" else 1}" '
            f'orientation="{"landscape" if horizontal else "portrait"}" '
            'fitToWidth="1" fitToHeight="0"/>'
            '</worksheet>')
    estilos = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/'
        '2006/main"><fonts count="3"><font><sz val="10"/><name val="Calibri"/>'
        '</font><font><b/><sz val="10"/><color rgb="FFFFFFFF"/><name '
        'val="Calibri"/></font><font><b/><sz val="10"/><name val="Calibri"/>'
        '</font></fonts><fills count="3"><fill><patternFill '
        'patternType="none"/></fill><fill><patternFill patternType="gray125"/>'
        '</fill><fill><patternFill patternType="solid"><fgColor '
        'rgb="FF243358"/></patternFill></fill></fills><borders count="2">'
        '<border/><border><left style="thin"><color rgb="FFB7BCC6"/></left>'
        '<right style="thin"><color rgb="FFB7BCC6"/></right><top style="thin">'
        '<color rgb="FFB7BCC6"/></top><bottom style="thin"><color '
        'rgb="FFB7BCC6"/></bottom></border></borders><cellStyleXfs count="1">'
        '<xf/></cellStyleXfs><cellXfs count="6"><xf/>'
        '<xf fontId="1" fillId="2" borderId="1" applyFont="1" applyFill="1" '
        'applyBorder="1" applyAlignment="1"><alignment vertical="center" '
        'wrapText="1"/></xf><xf fontId="0" fillId="0" borderId="1" '
        'applyBorder="1" applyAlignment="1"><alignment vertical="top" '
        'wrapText="1"/></xf>'
        # 3: número con separador de miles · 4: negrita · 5: negrita + miles
        '<xf numFmtId="3" fontId="0" fillId="0" borderId="1" '
        'applyNumberFormat="1" applyBorder="1" applyAlignment="1">'
        '<alignment vertical="top"/></xf>'
        '<xf fontId="2" fillId="0" borderId="1" applyFont="1" '
        'applyBorder="1" applyAlignment="1"><alignment vertical="top" '
        'wrapText="1"/></xf>'
        '<xf numFmtId="3" fontId="2" fillId="0" borderId="1" '
        'applyNumberFormat="1" applyFont="1" applyBorder="1" '
        'applyAlignment="1"><alignment vertical="top"/></xf>'
        '</cellXfs></styleSheet>')
    libro = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/'
        '2006/main" xmlns:r="http://schemas.openxmlformats.org/'
        'officeDocument/2006/relationships"><sheets>'
        + "".join(f'<sheet name="{_x(n)}" sheetId="{i+1}" r:id="rId{i+1}"/>'
                  for i, n in enumerate(nombres))
        + '</sheets><definedNames>'
        + "".join(f'<definedName name="_xlnm.Print_Titles" '
                  f'localSheetId="{i}">\'{_x(n)}\'!$1:$1</definedName>'
                  for i, n in enumerate(nombres))
        + '</definedNames></workbook>')
    rels_libro = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<Relationships xmlns="http://schemas.openxmlformats.org/package/'
        '2006/relationships">'
        + "".join(f'<Relationship Id="rId{i+1}" Type="http://schemas.'
                  'openxmlformats.org/officeDocument/2006/relationships/'
                  f'worksheet" Target="worksheets/sheet{i+1}.xml"/>'
                  for i in range(len(nombres)))
        + f'<Relationship Id="rId{len(nombres)+1}" Type="http://schemas.'
        'openxmlformats.org/officeDocument/2006/relationships/styles" '
        'Target="styles.xml"/></Relationships>')
    tipos = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<Types xmlns="http://schemas.openxmlformats.org/package/2006/'
        'content-types"><Default Extension="rels" ContentType="application/'
        'vnd.openxmlformats-package.relationships+xml"/><Default '
        'Extension="xml" ContentType="application/xml"/><Override '
        'PartName="/xl/workbook.xml" ContentType="application/vnd.'
        'openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>'
        '<Override PartName="/xl/styles.xml" ContentType="application/vnd.'
        'openxmlformats-officedocument.spreadsheetml.styles+xml"/>'
        + "".join(f'<Override PartName="/xl/worksheets/sheet{i+1}.xml" '
                  'ContentType="application/vnd.openxmlformats-'
                  'officedocument.spreadsheetml.worksheet+xml"/>'
                  for i in range(len(nombres)))
        + '</Types>')
    rels = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<Relationships xmlns="http://schemas.openxmlformats.org/package/'
        '2006/relationships"><Relationship Id="rId1" Type="http://schemas.'
        'openxmlformats.org/officeDocument/2006/relationships/'
        'officeDocument" Target="xl/workbook.xml"/></Relationships>')
    with _zip.ZipFile(str(ruta), "w", _zip.ZIP_DEFLATED) as z:
        z.writestr("[Content_Types].xml", tipos)
        z.writestr("_rels/.rels", rels)
        z.writestr("xl/workbook.xml", libro)
        z.writestr("xl/_rels/workbook.xml.rels", rels_libro)
        z.writestr("xl/styles.xml", estilos)
        for i, sx in enumerate(sheets_xml):
            z.writestr(f"xl/worksheets/sheet{i+1}.xml", sx)


