def numero_base_plano(numero) -> int:
    """El número de un plano sin su letra («3B» → 3; «12» → 12; sin número → 0)."""
    m_ = re.match(r"\s*(\d+)", str(numero or ""))
    return int(m_.group(1)) if m_ else 0


def tomas_multicamara(doc, pl: Optional[dict]) -> list:
    """Los planos de la misma toma multicámara (A, B, C…), en orden."""
    mc = (pl or {}).get("multicam")
    if not mc:
        return [pl] if pl else []
    return [q for q in (getattr(doc, "planos", []) or []) if isinstance(q, dict) and q.get("multicam") == mc]


def sincronizar_multicamara(doc, pl: Optional[dict]) -> int:
    """🎥🎥 En una toma con varias cámaras los actores hacen lo mismo: sus
    poses, lo articulado a mano, su animación y la duración pasan de «pl» a
    las otras cámaras de la toma (cada una conserva su cámara y su lente)."""
    if not pl or not pl.get("multicam"):
        return 0
    n = 0
    for q in tomas_multicamara(doc, pl):
        if q is pl:
            continue
        for k in ("sb_3d_poses", "sb_3d_art"):
            if isinstance(pl.get(k), dict) and pl[k]:
                q[k] = _copy.deepcopy(pl[k])
            else:
                q.pop(k, None)
        cl = pl.get("sb_3d_claves") if isinstance(pl.get("sb_3d_claves"), dict) else {}
        nuevo = {k: _copy.deepcopy(v) for k, v in cl.items() if k != "camara"}
        cam_q = (q.get("sb_3d_claves") or {}).get("camara") if isinstance(q.get("sb_3d_claves"), dict) else None
        if cam_q:
            nuevo["camara"] = cam_q
        if nuevo:
            q["sb_3d_claves"] = nuevo
        else:
            q.pop("sb_3d_claves", None)
        if str(pl.get("duracion") or "").strip():
            q["duracion"] = pl["duracion"]
        n += 1
    return n


def plano_desde_texto(texto: str) -> dict:
    """Deduce tamaño, ángulo y movimiento de un bloque PLANO («PRIMER
    PLANO DE ANA — TRAVELLING»)."""
    t = (texto or "").upper()
    pl = {k: "" for k in CAMPOS_PLANO}
    pl["hecho"] = False
    pl["descripcion"] = (texto or "").strip()
    for clave, valor in (("PRIMERÍSIMO PRIMER PLANO", "Primerísimo primer plano (PPP)"),
                         ("PPP", "Primerísimo primer plano (PPP)"),
                         ("PRIMER PLANO", "Primer plano (PP)"),
                         ("PLANO DETALLE", "Plano detalle (PD)"),
                         ("DETALLE", "Plano detalle (PD)"),
                         ("INSERTO", "Inserto"),
                         ("GRAN PLANO GENERAL", "Gran plano general (GPG)"),
                         ("PLANO GENERAL", "Plano general (PG)"),
                         ("PLANO MEDIO CORTO", "Plano medio corto (PMC)"),
                         ("PLANO MEDIO", "Plano medio (PM)"),
                         ("PLANO AMERICANO", "Plano americano (PA)"),
                         ("PLANO ENTERO", "Plano entero (PE)"),
                         ("SOBRE HOMBRO", "Sobre hombro"),
                         ("OVER SHOULDER", "Sobre hombro")):
        if clave in t:
            pl["tamano"] = valor
            break
    for clave, valor in (("CONTRAPICADO", "Contrapicado"), ("PICADO", "Picado"),
                         ("CENITAL", "Cenital"), ("NADIR", "Nadir"),
                         ("HOLANDÉS", "Holandés"), ("POV", "Subjetivo (POV)"),
                         ("SUBJETIV", "Subjetivo (POV)")):
        if clave in t:
            pl["angulo"] = valor
            break
    for clave, valor in (("TRAVELLING", "Travelling"), ("DOLLY", "Dolly"),
                         ("STEADICAM", "Steadicam"), ("STEADYCAM", "Steadicam"),
                         ("CÁMARA EN MANO", "Cámara en mano"),
                         ("PANEO", "Paneo"), ("PANORÁMICA", "Paneo"),
                         ("TILT", "Tilt"), ("GRÚA", "Grúa"), ("ZOOM", "Zoom"),
                         ("DRON", "Dron")):
        if clave in t:
            pl["movimiento"] = valor
            break
    return pl


def jornadas_de_escena(doc, n: int) -> list:
    """Jornadas de la Carta Gantt que incluyen la escena nº n."""
    out = []
    for j in getattr(doc, "jornadas", []) or []:
        nums = [x.strip() for x in (j.escenas or "").split(",")]
        if str(n) in nums:
            out.append(j)
    return out


# ═══════════════════════════════════════════════════════════════════════
# §6  EDITOR DE GUION
# ═══════════════════════════════════════════════════════════════════════

class OrtografiaHighlighter(QSyntaxHighlighter):
    """Resaltador de sintaxis que subraya en rojo ondulado las palabras
    que no están en el diccionario español. Se aplica al QTextDocument
    del editor sin interferir con otros estilos (color, negrita,
    subrayado semántico de ACTOS, etc.) porque usa `SpellCheckUnderline`
    en lugar de un color de fondo o foreground.

    El resaltador se re-ejecuta automáticamente cuando el texto
    cambia. Puede activarse/desactivarse con `activar_corrector()`.
    """

    def __init__(self, documento, doc_proyecto=None):
        super().__init__(documento)
        self._doc_proyecto = doc_proyecto   # Documento del proyecto
        # Formato para palabras mal escritas
        self._fmt_error = QTextCharFormat()
        self._fmt_error.setUnderlineColor(QColor("#e11d48"))  # rojo
        self._fmt_error.setUnderlineStyle(
            QTextCharFormat.UnderlineStyle.SpellCheckUnderline)
        # Regex de palabras: letras (con acentos españoles) y apóstrofos.
        # Excluye números y símbolos.
        self._re_palabras = re.compile(
            r"[A-Za-záéíóúüñÁÉÍÓÚÜÑ']{3,}")

    def set_documento_proyecto(self, doc):
        """Actualiza la referencia al Documento del proyecto cuando el
        usuario abre otro archivo. Así consulta las palabras aprendidas
        del proyecto correcto."""
        self._doc_proyecto = doc
        self.rehighlight()

    def highlightBlock(self, texto: str) -> None:
        # Skip rápido si corrector desactivado
        if not corrector_activo():
            return
        # Skip si el diccionario está vacío (no cargado)
        dic = cargar_diccionario_es()
        if not dic:
            return
        # Como el corrector (F7): no revisa encabezados, personajes,
        # transiciones, planos ni actos (nombres propios y mayúsculas técnicas)
        try:
            if Elem(self.currentBlock().userState()) in (Elem.PERSONAJE, Elem.TRANSICION, Elem.PLANO,
                                                          Elem.ACTO_INICIO, Elem.ACTO_FIN, Elem.ESCENA):
                return
        except ValueError:
            pass
        # Palabras aprendidas del PROYECTO (viajan con el .accion)
        aprendidas = _palabras_aprendidas_proyecto(self._doc_proyecto)
        # Buscar todas las palabras y validar cada una
        for m in self._re_palabras.finditer(texto):
            palabra = m.group()
            if palabra_correcta(palabra):
                continue
            if _quitar_acentos(palabra.lower()) in aprendidas:
                continue
            self.setFormat(m.start(), len(palabra), self._fmt_error)


class EditorGuion(QTextEdit):
    """Editor con motor sincronizado a un Documento.

    - Paginación visual: hojas separadas con sombra; número de hoja arriba a la derecha.
    - Numeración automática de escenas en el margen izquierdo.
    - Paréntesis: inserta `()` al entrar, cierra automáticamente al hacer Enter.
    - Encabezado: autocompleta `INT. `, `EXT. ` o `I/E. ` al tipear i/e/`/`.
    - Centrado horizontal en su contenedor (ver VentanaPrincipal).
    """

    tipo_cambiado          = Signal(Elem)
    posicion_cambiada      = Signal(int, int)
    # Presencia: se emite (con throttle) cuando el cursor local se mueve.
    # Payload: (bloque_idx, offset_dentro_del_bloque).
    cursor_local_movido    = Signal(int, int)
    tamaño_hoja_cambiado   = Signal(int)  # TamañoHoja como int
    zoom_cambiado          = Signal(float)  # 1.0 = 100%
    personaje_nuevo_detectado = Signal(str)  # nombre normalizado
    icono_clickeado        = Signal(int, str)  # (idx_bloque, categoria)
    # Sync en vivo: se emite cuando el cursor sale de un bloque que
    # fue modificado, llevando el índice del bloque que se acaba de
    # dejar de editar. La VentanaPrincipal lo usa para hacer broadcast
    # a los pares conectados.
    bloque_terminado_de_editar = Signal(int)
    # Se emite cuando cambia algo del documento que NO es texto puro
    # (cambio de tipo de bloque, agregar bloque, borrar bloque). Sirve
    # para que la colaboración sincronice cambios estructurales sin
    # depender del "cursor sale del bloque".
    estructura_cambiada        = Signal()
    # Se emite al presionar Enter — útil para forzar flush del buffer
    # de colaboración en el host (más responsivo para los invitados).
    enter_presionado           = Signal()
    # Se emite al aplicar un formato puntual (destacado, negrita, etc.)
    # También fuerza flush inmediato del buffer colab.
    flush_colab_solicitado     = Signal()
    # Se emite cada vez que el cursor local se mueve, con (bloque_idx,
    # offset). Sirve para presencia colaborativa (mostrar dónde está el
    # cursor de cada participante en los otros peers).
    cursor_local_movido        = Signal(int, int)

    def __init__(self, parent=None):
        super().__init__(parent)

        # ── Modelo ─────────────────────────────────────────────────────
        self.documento = Documento()
        self._tamaño_hoja: TamañoHoja = TamañoHoja.CARTA
        # Zoom de la hoja: 1.0 = tamaño físico real (8.5×11" en Carta).
        # Recuperamos lo guardado en QSettings para que persista.
        try:
            z = float(settings_app().value("zoom_hoja", 1.0))
            self._zoom_hoja: float = max(0.5, min(z, 3.0))
        except (TypeError, ValueError):
            self._zoom_hoja = 1.0

        # ── Estado de paginación real ──────────────────────────────────
        self._pagina_starts: list[int] = [0]
        self._en_paginacion = False

        # ── Márgenes de hoja (configurables) ───────────────────────────
        self._margen_izq_chars: int = MARGEN_IZQ_CHARS_DEFAULT
        self._margen_der_chars: int = MARGEN_DER_CHARS_DEFAULT

        # ── Personajes ya anunciados (para no abrir la ventana 2 veces) ─
        self._personajes_anunciados: set[str] = set()

        # ── Marca de agua + íconos clickeables ─────────────────────────
        self._marca_agua: str = ""
        # Rects (en coords del viewport) de los íconos pintados, con su
        # idx_bloque y categoría → para detectar clicks.
        self._rects_iconos: list[tuple[QRectF, int, str]] = []

        # ── Fuente Courier (tamaño multiplicado por zoom) ──────────────
        font = QFont(fuente_editor_familia(),
                     int(round(FONT_SIZE_PT * self._zoom_hoja)))
        font.setStyleHint(QFont.StyleHint.TypeWriter)
        self.setFont(font)
        self.document().setDefaultFont(font)

        # ── Geometría de la hoja (escala con _zoom_hoja vía font) ──────
        cw = self._ancho_caracter()
        lh = self._alto_linea()

        self._page_w = HOJA_W_CHARS * cw
        self._page_h = TAMAÑO_LINEAS[self._tamaño_hoja] * lh

        self.document().setDocumentMargin(DOC_MARGIN_PX)

        # Ancho fijo = ancho de hoja (el centrado lo hace la ventana)
        self.setFixedWidth(int(self._page_w))

        # ── Aspecto ────────────────────────────────────────────────────
        self.setLineWrapMode(QTextEdit.LineWrapMode.WidgetWidth)

        # ── Tracking para sync en vivo ────────────────────────────────
        # Cuando el cursor sale de un bloque que se modificó, emitimos
        # `bloque_terminado_de_editar(idx)` para que VentanaPrincipal
        # haga broadcast a los pares conectados.
        self._ultimo_bloque_idx: int = 0
        self._bloques_modificados: set[int] = set()
        self._aplicando_remoto: bool = False  # evita re-broadcast
        self.document().contentsChanged.connect(self._track_bloque_modificado)
        self.cursorPositionChanged.connect(self._track_bloque_cursor)
        _s = settings_app()
        _bg = str(_s.value("hoja_bg", "#ffffff"))
        _fg = str(_s.value("hoja_fg", "#1a1a1a"))
        self.setStyleSheet(f"""
            QTextEdit {{
                background: {_bg};
                color: {_fg};
                border: none;
                selection-background-color: #ff8c1a;
                selection-color: #241203;
            }}
        """)

        # ── Render inicial ─────────────────────────────────────────────
        self._rerender_completo()

        # ── Corrector ortográfico ─────────────────────────────────────
        # Highlighter que subraya en rojo palabras fuera del diccionario.
        # Se aplica al QTextDocument y se re-ejecuta automáticamente
        # cuando el texto cambia. Puede desactivarse con corrector_activo.
        self._ortografia_hl = OrtografiaHighlighter(
            self.document(), self.documento)

        # ── Debounce para re-paginar tras ediciones ────────────────────
        self._timer_paginacion = QTimer(self)
        self._timer_paginacion.setSingleShot(True)
        self._timer_paginacion.setInterval(60)
        self._timer_paginacion.timeout.connect(self._recalcular_paginacion)

        # ── Throttle para presencia (colaboración) ─────────────────────
        # Al mover el cursor, disparamos como máximo cada 200 ms para
        # no saturar la red con actualizaciones de posición.
        self._timer_presencia = QTimer(self)
        self._timer_presencia.setSingleShot(True)
        self._timer_presencia.setInterval(200)
        self._timer_presencia.timeout.connect(self._emitir_posicion_cursor)
        self._ultima_pos_emitida: tuple[int, int] = (-1, -1)

        self.cursorPositionChanged.connect(self._on_cursor_movido)
        self.document().contentsChanged.connect(self._programar_paginacion)
        self.document().contentsChanged.connect(self.viewport().update)

        # Paginación inicial
        QTimer.singleShot(0, self._recalcular_paginacion)

        # ── Deshacer / rehacer propio (Ctrl+Z / Ctrl+Y) ───────────────
        # El de Qt cambiaba el texto de la hoja sin el guion de verdad
        # (los bloques): quedaban desincronizados. Este guarda fotos del
        # guion y las agrupa al escribir de corrido.
        self.setUndoRedoEnabled(False)
        self._iniciar_historial()

        # ── Actos como los paréntesis de Excel: un FIN DE ACTO sin su
        #    INICIO (o un acto que no se cerró antes del siguiente) se ve
        #    en rojo y al pasar el mouse dice qué le falta. Con el cursor
        #    en un INICIO o un FIN, su par se ilumina. No impide nada. ──
        self._actos_estado: dict = {}
        self._sel_actos_rojo: list = []
        self._par_resaltado = None
        self._timer_actos = QTimer(self)
        self._timer_actos.setSingleShot(True)
        self._timer_actos.setInterval(120)
        self._timer_actos.timeout.connect(self._revisar_actos)
        self.document().contentsChanged.connect(self._programar_revision_actos)
        self.cursorPositionChanged.connect(self._resaltar_par_acto)
        QTimer.singleShot(0, self._revisar_actos)

    # ── Actos como los paréntesis de Excel ─────────────────────────────
    def _programar_revision_actos(self) -> None:
        t = getattr(self, "_timer_actos", None)
        if t is not None:
            t.start()

    def _pagina_de_bloque(self, i: int) -> int:
        return max(1, _bisect_right(list(self._pagina_starts or [0]), i))

    def _sel_bloque_acto(self, i: int, color_texto, fondo) -> list:
        """La marca (que no es parte del guion) del texto de un bloque de
        acto: fondo y, si hay color, el texto con subrayado ondulado."""
        qb = self.document().findBlockByNumber(i)
        if not qb.isValid() or qb.length() <= 1:
            return []
        sel = QTextEdit.ExtraSelection()
        c = QTextCursor(qb)
        c.movePosition(QTextCursor.MoveOperation.EndOfBlock, QTextCursor.MoveMode.KeepAnchor)
        sel.cursor = c
        f = QTextCharFormat()
        f.setBackground(fondo)
        if color_texto is not None:
            f.setForeground(color_texto)
            f.setUnderlineColor(color_texto)
            f.setUnderlineStyle(QTextCharFormat.UnderlineStyle.WaveUnderline)
        sel.format = f
        return [sel]

    def _revisar_actos(self) -> None:
        """Rojo para los actos sin su par (lo pintado no es parte del guion:
        no se imprime ni se guarda)."""
        try:
            est = estado_actos(self.documento.bloques)
        except Exception:
            est = {}
        self._actos_estado = est
        n_qb = self.document().blockCount()
        rojo = QColor(COLOR_ACTO_SIN_PAR)
        fondo = QColor(229, 57, 53, 40)
        sels = []
        for i in sorted(est):
            if i < n_qb and acto_sin_par(est[i]):
                sels.extend(self._sel_bloque_acto(i, rojo, fondo))
        self._sel_actos_rojo = sels
        self._par_resaltado = ("forzar",)
        self._resaltar_par_acto()

    def actos_sin_par(self) -> list[int]:
        """Índices de los bloques de acto que están en rojo."""
        return [i for i, d in sorted(self._actos_estado.items()) if acto_sin_par(d)]

    def _resaltar_par_acto(self) -> None:
        """Como Excel con los paréntesis: con el cursor en un INICIO o un
        FIN DE ACTO, se iluminan los dos del par."""
        try:
            i = self.textCursor().blockNumber()
        except RuntimeError:
            return
        d = self._actos_estado.get(i)
        par = d.get("par") if d else None
        clave = (i, par) if par is not None else None
        if clave == self._par_resaltado:
            return
        self._par_resaltado = clave
        sels = list(self._sel_actos_rojo)
        if par is not None:
            tinte = QColor(255, 140, 26, 90)
            for k in (i, par):
                sels.extend(self._sel_bloque_acto(k, None, tinte))
        self.setExtraSelections(sels)

    def _tooltip_acto_en(self, pos) -> str:
        cur = self.cursorForPosition(pos)
        i = cur.blockNumber()
        if i not in self._actos_estado:
            return ""
        qb = cur.block()
        r = self.document().documentLayout().blockBoundingRect(qb)
        y = pos.y() + self.verticalScrollBar().value()
        if not (r.top() - 3 <= y <= r.bottom() + 3):          # (en la línea, no en el aire de arriba)
            return ""
        return texto_estado_acto(self.documento.bloques, i, self._actos_estado,
                                 pagina=self._pagina_de_bloque)

    def viewportEvent(self, event) -> bool:
        if event.type() == QEvent.Type.ToolTip and getattr(self, "_actos_estado", None):
            try:
                txt = self._tooltip_acto_en(event.pos())
            except Exception:
                txt = ""
            if txt:
                from PySide6.QtWidgets import QToolTip
                QToolTip.showText(event.globalPos(), txt, self.viewport())
                return True
        return super().viewportEvent(event)

    # ── Métricas ───────────────────────────────────────────────────────

    def _track_bloque_modificado(self) -> None:
        """Marca el bloque del cursor como modificado (solo si el cambio
        es local, no si viene de un peer)."""
        if self._aplicando_remoto:
            return
        self._bloques_modificados.add(self.textCursor().blockNumber())

    def _track_bloque_cursor(self) -> None:
        """Si el cursor cambió a otro bloque y el bloque anterior estaba
        modificado, emite la señal para que se haga broadcast."""
        if self._aplicando_remoto:
            return
        cur_idx = self.textCursor().blockNumber()
        if cur_idx != self._ultimo_bloque_idx:
            if self._ultimo_bloque_idx in self._bloques_modificados:
                self.bloque_terminado_de_editar.emit(self._ultimo_bloque_idx)
                self._bloques_modificados.discard(self._ultimo_bloque_idx)
            self._ultimo_bloque_idx = cur_idx

    def _ancho_caracter(self) -> float:
        return QFontMetricsF(self.font()).horizontalAdvance("M")

    def _alto_linea(self) -> float:
        return QFontMetricsF(self.font()).lineSpacing()

    # ── Zoom de hoja ───────────────────────────────────────────────────

    def set_zoom_hoja(self, zoom: float, guardar: bool = True) -> None:
        """Cambia el zoom de la hoja (rango 0.5 a 3.0). Recalcula font,
        ancho de página y altura, y emite la señal `zoom_cambiado`.
        Persiste el valor en QSettings (salvo «guardar=False»)."""
        nuevo = max(0.5, min(zoom, 3.0))
        if abs(nuevo - self._zoom_hoja) < 0.005:
            return  # cambio insignificante, no recalcular
        self._zoom_hoja = nuevo

        # Reaplicar font con el nuevo tamaño en puntos
        font = QFont(fuente_editor_familia(),
                     int(round(FONT_SIZE_PT * self._zoom_hoja)))
        font.setStyleHint(QFont.StyleHint.TypeWriter)
        self.setFont(font)
        self.document().setDefaultFont(font)

        # Recalcular geometría
        cw = self._ancho_caracter()
        lh = self._alto_linea()
        self._page_w = HOJA_W_CHARS * cw
        self._page_h = TAMAÑO_LINEAS[self._tamaño_hoja] * lh
        self.setFixedWidth(int(self._page_w))

        # Repaginar y repintar (sin perder el lugar)
        try:
            idx_, off_ = self._posicion_logica()
        except Exception:
            idx_, off_ = 0, 0
        frac = self.verticalScrollBar().value() / max(1, self.verticalScrollBar().maximum())
        # (el zoom no cambia el guion: no debe marcarlo como modificado)
        self.document().blockSignals(True)
        try:
            self._rerender_completo()
            self._mover_cursor_a(idx_, off_)
            self._recalcular_paginacion()
        finally:
            self.document().blockSignals(False)
        self.verticalScrollBar().setValue(int(frac * self.verticalScrollBar().maximum()))
        self.viewport().update()

        # Persistir y notificar
        if guardar:
            settings_app().setValue("zoom_hoja", self._zoom_hoja)
        self.zoom_cambiado.emit(self._zoom_hoja)

    def get_zoom_hoja(self) -> float:
        return self._zoom_hoja

    def zoom_in_hoja(self) -> None:
        """Aumenta el zoom en pasos de 10%."""
        self.set_zoom_hoja(self._zoom_hoja + 0.1)

    def zoom_out_hoja(self) -> None:
        """Reduce el zoom en pasos de 10%."""
        self.set_zoom_hoja(self._zoom_hoja - 0.1)

    def zoom_reset_hoja(self) -> None:
        """Restaura el zoom al tamaño físico (1.0 = 100%)."""
        self.set_zoom_hoja(1.0)

    # ── Posición lógica ────────────────────────────────────────────────

    def _posicion_logica(self) -> tuple[int, int]:
        cur = self.textCursor()
        return (cur.blockNumber(), cur.positionInBlock())

    def _mover_cursor_a(self, idx: int, offset: int) -> None:
        doc = self.document()
        qblock = doc.findBlockByNumber(idx)
        if not qblock.isValid():
            return
        cur = QTextCursor(self.document())
        max_off = qblock.length() - 1
        cur.setPosition(qblock.position() + max(0, min(offset, max_off)))
        self.setTextCursor(cur)

    def tipo_actual(self) -> Elem:
        idx, _ = self._posicion_logica()
        if 0 <= idx < len(self.documento):
            return self.documento[idx].elem
        return Elem.ACCION

    # ── Formato visual por tipo ────────────────────────────────────────

    def _formato_para(self, elem: Elem) -> tuple[QTextBlockFormat, QTextCharFormat]:
        cw = self._ancho_caracter()
        sangria_izq, sangria_der = SANGRIA[elem]
        aire = AIRE_ARRIBA[elem]

        # Margen de hoja (asimétrico estilo estándar de la industria) + sangría del elemento
        margen_izq_total = (self._margen_izq_chars + sangria_izq) * cw
        margen_der_total = (self._margen_der_chars + sangria_der) * cw

        bf = QTextBlockFormat()

        if elem == Elem.TRANSICION:
            bf.setAlignment(Qt.AlignmentFlag.AlignRight)
        elif elem in (Elem.ACTO_INICIO, Elem.ACTO_FIN):
            bf.setAlignment(Qt.AlignmentFlag.AlignCenter)
        else:
            bf.setAlignment(Qt.AlignmentFlag.AlignLeft)

        bf.setLeftMargin(margen_izq_total)
        bf.setRightMargin(margen_der_total)
        bf.setTopMargin(aire * 7)
        bf.setBottomMargin(0)

        cf = QTextCharFormat()
        # IMPORTANTE: aplicar el zoom actual también al cf, sino los
        # bloques quedan con tamaño de fuente inconsistente cuando el
        # usuario tiene zoom != 100% (visual desalineado, bold que no
        # se ve, etc.)
        font_size = int(round(FONT_SIZE_PT * self._zoom_hoja))
        font = QFont(FONT_FAMILY, font_size)
        if elem in (Elem.ACTO_INICIO, Elem.ACTO_FIN):
            font.setBold(True)
            font.setUnderline(True)
        cf.setFont(font)

        return bf, cf

    # ── Sincronización modelo → vista ──────────────────────────────────

    def refrescar_fuente(self) -> None:
        """Reaplica la familia guardada en QSettings y recalcula
        toda la geometría de la hoja (ancho de página, alto de
        línea, márgenes). Usar tras cambiar 🅰 Fuente."""
        font = QFont(fuente_editor_familia(),
                     int(round(FONT_SIZE_PT * self._zoom_hoja)))
        font.setStyleHint(QFont.StyleHint.TypeWriter)
        self.setFont(font)
        self.document().setDefaultFont(font)
        cw = self._ancho_caracter()
        lh = self._alto_linea()
        self._page_w = HOJA_W_CHARS * cw
        self._page_h = TAMAÑO_LINEAS[self._tamaño_hoja] * lh
        self.setFixedWidth(int(self._page_w))
        self._rerender_completo()
        self.viewport().update()

    def _rerender_completo(self) -> None:
        self.blockSignals(True)
        self.clear()
        cursor = self.textCursor()
        cursor.beginEditBlock()
        for i, bloque in enumerate(self.documento.bloques):
            bf, cf = self._formato_para(bloque.elem)
            if i == 0:
                cursor.setBlockFormat(bf)
                cursor.setCharFormat(cf)
            else:
                cursor.insertBlock(bf, cf)
            cursor.block().setUserState(int(bloque.elem))
            if bloque.texto:
                # (un salto de línea dentro del bloque no es otro bloque)
                cursor.insertText(bloque.texto.replace("\n", "\u2028"), cf)
            # Aplicar formatos guardados (negrita, subrayado, colores)
            if bloque.formatos:
                self._aplicar_formatos_guardados(cursor.block(), bloque, cf)
        cursor.endEditBlock()
        cursor.movePosition(QTextCursor.MoveOperation.Start)
        self.setTextCursor(cursor)
        self.blockSignals(False)
        self.tipo_cambiado.emit(self.tipo_actual())
        self.posicion_cambiada.emit(1, len(self.documento))
        self._programar_revision_actos()
        self.viewport().update()

    def _reformatear_bloque(self, idx: int) -> None:
        if not (0 <= idx < len(self.documento)):
            return
        bloque = self.documento[idx]
        # Asegurar caso normalizado en el modelo (idempotente)
        texto_normalizado = aplicar_caso_a_texto(bloque.elem, bloque.texto)
        if texto_normalizado != bloque.texto:
            bloque.texto = texto_normalizado

        bf, cf = self._formato_para(bloque.elem)

        qblock = self.document().findBlockByNumber(idx)
        if not qblock.isValid():
            return

        cursor = QTextCursor(qblock)
        cursor.beginEditBlock()
        cursor.movePosition(QTextCursor.MoveOperation.StartOfBlock)
        cursor.movePosition(QTextCursor.MoveOperation.EndOfBlock,
                            QTextCursor.MoveMode.KeepAnchor)
        cursor.insertText(bloque.texto.replace("\n", "\u2028"), cf)
        cursor.setBlockFormat(bf)
        # Aplicar formatos por-carácter guardados (negrita, subrayado,
        # color de texto, destacado). Cada rango se aplica sobre el cf
        # base del tipo de bloque.
        self._aplicar_formatos_guardados(qblock, bloque, cf)
        cursor.endEditBlock()
        qblock.setUserState(int(bloque.elem))
        self.viewport().update()

    # ── ✍ La IA escribiendo en vivo (siempre al final del guion) ──
    def ia_bloque_nuevo(self, elem: "Elem", texto: str = "") -> int:
        """Un bloque nuevo al final (o el primero, si la hoja está vacía)."""
        doc = self.documento
        if len(doc.bloques) == 1 and not doc.bloques[0].texto.strip():
            doc.bloques[0].elem, doc.bloques[0].texto = elem, texto
            idx = 0
        else:
            doc.bloques.append(Bloque(elem, texto))
            idx = len(doc.bloques) - 1
            bf, cf = self._formato_para(elem)
            cur = QTextCursor(self.document())
            cur.movePosition(QTextCursor.MoveOperation.End)
            cur.beginEditBlock()
            cur.insertBlock(bf, cf)
            cur.endEditBlock()
        self._reformatear_bloque(idx)
        self._ia_mostrar(idx)
        return idx

    def ia_quitar_ultimo(self) -> None:
        """Quita el último bloque (uno que la IA dejó vacío) sin volver a
        armar toda la hoja: antes se rearmaba entera, la vista saltaba al
        comienzo del guion y volvía, como un obturador."""
        doc = self.documento
        if len(doc.bloques) <= 1:
            return
        doc.bloques.pop()
        qdoc = self.document()
        ultimo = qdoc.lastBlock()
        if ultimo.blockNumber() == 0:
            return
        barra = self.verticalScrollBar()
        v = barra.value()
        cur = QTextCursor(qdoc)
        cur.setPosition(ultimo.position() - 1)            # (el fin del bloque anterior)
        cur.movePosition(QTextCursor.MoveOperation.End, QTextCursor.MoveMode.KeepAnchor)
        cur.beginEditBlock()
        cur.removeSelectedText()
        cur.endEditBlock()
        barra.setValue(min(v, barra.maximum()))
        self._programar_paginacion()

    def ia_texto(self, idx: int, texto: str, elem: Optional["Elem"] = None) -> None:
        """Cambia el texto (y el tipo) de un bloque que escribe la IA."""
        if not (0 <= idx < len(self.documento)):
            return
        b = self.documento[idx]
        if elem is not None:
            b.elem = elem
        b.texto = texto
        self._reformatear_bloque(idx)
        self._ia_mostrar(idx)

    def insertar_bloques_dictados(self, bloques: list) -> int:
        """🎙 Lo dictado por voz, debajo del bloque donde está el cursor (o
        en él, si está vacío), como un solo paso de Ctrl+Z. Los personajes
        nuevos quedan con su ficha, sin preguntar (quien dicta no ve la
        ventana). Devuelve el índice del último bloque escrito."""
        if not bloques or self.isReadOnly():
            return -1
        self._hist_flush()
        doc = self.documento
        try:
            idx, _o = self._posicion_logica()
        except Exception:
            idx = len(doc.bloques) - 1
        idx = max(0, min(idx, len(doc.bloques) - 1))
        while (idx + 1 < len(doc.bloques) and doc.bloques[idx].elem in (Elem.PERSONAJE, Elem.PARENTESIS)
               and (doc.bloques[idx].texto or "").strip()
               and doc.bloques[idx + 1].elem in (Elem.PARENTESIS, Elem.DIALOGO)):
            idx += 1                              # (no se mete entre un personaje y lo que dice)
        resto = list(bloques)
        ultimo = idx
        if not (doc.bloques[idx].texto or "").strip():
            el, tx = resto.pop(0)
            doc.bloques[idx].elem, doc.bloques[idx].texto = el, tx
            self._reformatear_bloque(idx)
        for el, tx in resto:
            doc.bloques.insert(ultimo + 1, Bloque(el, tx))
            bf, cf = self._formato_para(el)
            cur = QTextCursor(self.document().findBlockByNumber(ultimo))
            cur.movePosition(QTextCursor.MoveOperation.EndOfBlock)
            cur.beginEditBlock()
            cur.insertBlock(bf, cf)
            cur.endEditBlock()
            ultimo += 1
            self._reformatear_bloque(ultimo)
        for el, tx in bloques:
            if el == Elem.PERSONAJE:
                k = (tx or "").strip().upper().split("(")[0].strip()
                if k and k not in doc.fichas:
                    doc.fichas[k] = Ficha(personaje=k)
                    try:
                        self._personajes_anunciados.add(k)
                    except Exception:
                        pass
        self._mover_cursor_a(ultimo, len(doc.bloques[ultimo].texto))
        self._registrar_cambio_guion()
        self.ensureCursorVisible()
        QTimer.singleShot(0, self._recalcular_paginacion)
        self.viewport().update()
        try:
            self.tipo_cambiado.emit(doc.bloques[ultimo].elem)
            self.estructura_cambiada.emit()
            self.enter_presionado.emit()
        except Exception:
            pass
        return ultimo

    def _ia_mostrar(self, idx: int) -> None:
        """La vista sigue lo que escribe la IA solo mientras lo estás mirando:
        si subiste a leer otra parte, se queda ahí (y vuelve a seguirla
        cuando bajas hasta donde escribe)."""
        barra = self.verticalScrollBar()
        v = barra.value()
        try:
            r = self.cursorRect()
            lh = self._alto_linea()
            seguir = r.bottom() >= -lh and r.top() <= self.viewport().height() + 4 * lh
        except Exception:
            seguir = True
        try:
            self._mover_cursor_a(idx, len(self.documento[idx].texto))
            if seguir:
                self.ensureCursorVisible()
            else:
                barra.setValue(v)
        except Exception:
            pass
        self._programar_paginacion()

    def _aplicar_formatos_guardados(self, qblock, bloque, cf_base):
        """Aplica al QTextDocument los formatos guardados en
        bloque.formatos. Se llama al final de _reformatear_bloque para
        restaurar negrita, subrayado, colores tras un re-render.

        IMPORTANTE: cuando el formato guardado dice "negrita: False"
        explícitamente, se FUERZA sin negrita (no se hereda el bold
        del cf_base). Esto era el bug donde ACTO_INICIO/ACTO_FIN se
        veían siempre en negrita en el invitado — heredaban el bold
        del cf_base porque el formato "quitar negrita" no lo tocaba.
        Lo mismo aplica para subrayado."""
        if not bloque.formatos:
            return
        n = len(bloque.texto)
        for f in bloque.formatos:
            desde = max(0, int(f.get("desde", 0)))
            hasta = min(n, int(f.get("hasta", 0)))
            if hasta <= desde:
                continue
            cursor = QTextCursor(qblock)
            cursor.setPosition(qblock.position() + desde)
            cursor.setPosition(qblock.position() + hasta,
                               QTextCursor.MoveMode.KeepAnchor)
            nuevo = QTextCharFormat(cf_base)
            # Negrita: respetar valor explícito (True o False)
            if "negrita" in f:
                nuevo.setFontWeight(
                    QFont.Weight.Bold if f["negrita"]
                    else QFont.Weight.Normal)
            # Subrayado: respetar valor explícito
            if "subrayado" in f:
                nuevo.setFontUnderline(bool(f["subrayado"]))
            col = self.color_de_formato(f.get("color"), f.get("fondo"))
            if col:
                nuevo.setForeground(QColor(col))
            if f.get("fondo"):
                nuevo.setBackground(QColor(f["fondo"]))
            cursor.mergeCharFormat(nuevo)

    # ── 🌙 La hoja negra (modo oscuro) ──
    def color_texto_hoja(self) -> QColor:
        if getattr(self, "hoja_oscura", False):
            return QColor(HOJA_OSCURA_FG)
        return QColor(str(settings_app().value("hoja_fg", "#1a1a1a")))

    def color_de_formato(self, color, fondo=None):
        """El color con que se ve un texto con formato. En la hoja negra,
        todo el texto es blanco (y negro sobre un resaltado claro, para que
        se lea); el color elegido se guarda igual y vuelve en la hoja clara."""
        if not getattr(self, "hoja_oscura", False):
            return color or None
        if fondo and QColor(fondo).lightness() > 150:
            return "#000000"
        return HOJA_OSCURA_FG if color else None

    def poner_hoja_oscura(self, oscura: bool, bg: str, fg: str) -> None:
        cambio = bool(oscura) != bool(getattr(self, "hoja_oscura", False))
        self.hoja_oscura = bool(oscura)
        self.setStyleSheet(
            f"QTextEdit {{ background: {bg}; color: {fg}; border: none; "
            f"selection-background-color: #ff8c1a; "
            f"selection-color: #241203; }}")
        if cambio:
            try:
                self._rerender_completo()
            except Exception:
                pass
        self.viewport().update()

    # ── API pública ────────────────────────────────────────────────────

    def _validar_cambio_a_acto(self, idx: int, elem: Elem) -> tuple[bool, str]:
        """Dice si el bloque `idx` cambiado a `elem` (ACTO_INICIO o
        ACTO_FIN) quedaría con su par. Devuelve (ok, mensaje). Ya no se usa
        para impedir el cambio: los actos sin su par se ven en rojo.

        Reglas:
        - ACTO_INICIO: solo se permite si NO hay un acto abierto antes
          de este bloque.
        - ACTO_FIN: solo se permite si HAY un acto abierto antes de
          este bloque (que este mismo no cierra).
        """
        # Recorrer desde el inicio hasta el bloque anterior al actual
        # ignorando el propio bloque idx (que estamos cambiando).
        dentro = False
        for i, b in enumerate(self.documento.bloques):
            if i == idx:
                break
            if b.elem == Elem.ACTO_INICIO:
                dentro = True
            elif b.elem == Elem.ACTO_FIN:
                dentro = False
        if elem == Elem.ACTO_INICIO:
            if dentro:
                return (False,
                        "No se puede abrir un ACTO_INICIO porque hay "
                        "un acto anterior sin cerrar. Cerralo primero "
                        "con ACTO_FIN.")
            return (True, "")
        elif elem == Elem.ACTO_FIN:
            if not dentro:
                return (False,
                        "No se puede cerrar un ACTO_FIN porque no hay "
                        "ningún acto abierto. Abre uno primero con "
                        "ACTO_INICIO.")
            return (True, "")
        return (True, "")

    def cambiar_tipo(self, elem: Elem) -> None:
        """Cambia el tipo del bloque actual. Comportamiento especial para Paréntesis:
        si el bloque está vacío, se inicializa con `()` y el cursor queda entre ellos.

        INICIO / FIN DE ACTO funcionan como los paréntesis de Excel: se
        pueden poner siempre (los actos muchas veces se marcan al final).
        Un FIN sin su INICIO, o un acto que no se cerró, se ve en rojo y
        al pasar el mouse dice qué le falta.
        """
        self._hist_flush()
        idx, off = self._posicion_logica()

        bloque = self.documento[idx]
        estaba_vacio = not bloque.texto.strip()

        self.documento.cambiar_tipo(idx, elem)

        # Paréntesis vacío → "(" + cursor + ")"
        if elem == Elem.PARENTESIS and estaba_vacio:
            self.documento.actualizar_texto(idx, "()")
            self._reformatear_bloque(idx)
            self._mover_cursor_a(idx, 1)  # entre paréntesis
        else:
            self._reformatear_bloque(idx)
            nuevo_off = min(off, len(self.documento[idx].texto))
            self._mover_cursor_a(idx, nuevo_off)

        self.tipo_cambiado.emit(elem)
        # Notificar al sistema de colaboración que hay un cambio no-texto
        self.estructura_cambiada.emit()
        self._revisar_actos()            # (el rojo de los actos sin su par, al tiro)

        # ── Encabezado vacío → menú INT/EXT/I/E ──
        if elem == Elem.ESCENA and estaba_vacio:
            QTimer.singleShot(0, self._mostrar_menu_encabezado_intext)

        # ── Transición vacía → menú de transiciones estándar ──
        if elem == Elem.TRANSICION and estaba_vacio:
            QTimer.singleShot(0, self._mostrar_menu_transicion)

        # ── Plano vacío → la lista completa de planos (o escribir otro) ──
        if elem == Elem.PLANO and estaba_vacio:
            QTimer.singleShot(0, self._mostrar_menu_plano)

    def aplicar_reorden_escenas(self, nuevo_orden: list[int],
                                  eliminadas: set[int]) -> None:
        """Reorganiza los bloques del documento según un nuevo orden de
        escenas. Además remapea:

          • Los estados de producción (dict {num_escena: {...}}) para
            que sigan apuntando a la escena correcta.
          • Las jornadas (que guardan escenas como "1,2,3" en texto)
            para que apunten a los nuevos números.

        Args:
            nuevo_orden: lista de números de escena ORIGINALES en el
                nuevo orden deseado. Ej: [3, 1, 2] mueve la escena 3
                al primer lugar.
            eliminadas: set de números de escena ORIGINALES que deben
                ser eliminadas del documento.
        """
        doc = self.documento
        escenas = segmentar_escenas(doc)
        n_escenas = len(escenas)
        if n_escenas == 0:
            return

        # Índice rápido: numero_original → dict de la escena
        por_numero = {e["numero"]: e for e in escenas}

        # Bloques ANTES de la primera escena (por ejemplo, un
        # ACTO_INICIO al inicio del documento). Los preservamos como
        # "prefijo" y no los tocamos.
        idx_primera = escenas[0]["idx_inicio"]
        prefijo = list(doc.bloques[:idx_primera])

        # Extraer bloques de cada escena original + los "puentes"
        # (bloques que están ENTRE escenas — normalmente ACTO_INICIO
        # y ACTO_FIN). Estos separadores se mantienen fijos: no viajan
        # con las escenas al reordenar.
        # Estrategia: reconstruir el documento así:
        #   prefijo + [escenas en nuevo_orden] + separadores originales
        # Pero los ACTO_INICIO/ACTO_FIN se preservan en las posiciones
        # donde estaban (entre escenas específicas). Si el usuario mueve
        # escenas cruzando actos, los separadores quedan en su lugar
        # y las escenas cambian de acto.

        # Recolectar separadores (ACTO_INICIO/ACTO_FIN) en el orden
        # original del documento
        separadores_por_pos: dict[int, list["Bloque"]] = {}
        for i, esc in enumerate(escenas):
            # Bloques entre idx_fin de esta escena e idx_inicio de la
            # siguiente (o fin del doc)
            fin_esta = esc["idx_fin"]
            inicio_siguiente = (escenas[i + 1]["idx_inicio"]
                                  if i + 1 < n_escenas
                                  else len(doc.bloques))
            entre = list(doc.bloques[fin_esta:inicio_siguiente])
            if entre:
                separadores_por_pos[i] = entre

        # Filtrar el nuevo orden: quitar las eliminadas
        orden_filtrado = [n for n in nuevo_orden if n not in eliminadas
                          and n in por_numero]

        # Construir el nuevo documento
        nuevos_bloques = list(prefijo)
        # Mapeo viejo→nuevo para remapear estados y jornadas después
        mapa_viejo_a_nuevo: dict[int, int] = {}
        for pos_nueva, num_viejo in enumerate(orden_filtrado, start=1):
            esc = por_numero[num_viejo]
            # Bloques de la escena
            for i_b in range(esc["idx_inicio"], esc["idx_fin"]):
                nuevos_bloques.append(doc.bloques[i_b])
            mapa_viejo_a_nuevo[num_viejo] = pos_nueva
            # Después de esta escena, ¿había un separador
            # (ACTO_INICIO/ACTO_FIN) en el documento original?
            # Los preservamos en su lugar SI la escena original estaba
            # en esa posición. Si el usuario mueve la escena, el
            # separador queda huérfano; lo mantenemos igualmente al
            # final para no perder información.
            # Estrategia simple: al final del reordenamiento, agregar
            # los separadores restantes (los que no viajaron).

        # Agregar los separadores que quedaron colgando al final,
        # en el orden original (evita perder ACTO_FIN o similares).
        for i in sorted(separadores_por_pos.keys()):
            seps = separadores_por_pos[i]
            # ¿La escena que estaba en esta posición fue eliminada?
            # Si sí, sigamos igual añadiendo el separador; si el
            # separador ya fue usado en otro momento, no lo agregamos
            # dos veces. Como el orden puede cambiar, los colocamos
            # al final del documento.
            pass  # No los agregamos duplicados. Ver nota abajo.

        # Nota práctica: como los ACTO_INICIO/ACTO_FIN aparecen entre
        # escenas específicas y el usuario puede reordenar cualquier
        # cosa, la única solución consistente es agregar los
        # separadores al final si tras el reordenamiento no quedaron
        # dentro del flujo. En la práctica, si el usuario mueve toda
        # una escena a otro acto, el ACTO_FIN correspondiente queda
        # implícito en la posición original — lo respetamos igual
        # agregándolo aquí para no perder la marca:
        for i in sorted(separadores_por_pos.keys()):
            for b_sep in separadores_por_pos[i]:
                nuevos_bloques.append(b_sep)

        # ── Remapear estados de producción ────
        estados_viejos = getattr(doc, "estados_produccion", {}) or {}
        estados_nuevos: dict = {}
        for num_viejo, estado in estados_viejos.items():
            try:
                nv = int(num_viejo)
            except (ValueError, TypeError):
                continue
            if nv in eliminadas:
                continue
            if nv in mapa_viejo_a_nuevo:
                estados_nuevos[str(mapa_viejo_a_nuevo[nv])] = estado
        doc.estados_produccion = estados_nuevos

        # ── Remapear jornadas ────
        for j in getattr(doc, "jornadas", []) or []:
            if not j.escenas:
                continue
            nums_nuevos: list[str] = []
            for s in j.escenas.split(","):
                s = s.strip()
                if s.isdigit():
                    n_viejo = int(s)
                    if n_viejo in eliminadas:
                        continue
                    if n_viejo in mapa_viejo_a_nuevo:
                        nums_nuevos.append(str(mapa_viejo_a_nuevo[n_viejo]))
            j.escenas = ",".join(nums_nuevos)

        # ── Remapear planos, versión corta y fichas de escena ────
        planos_nuevos = []
        for pl in getattr(doc, "planos", []) or []:
            try:
                nv = int(pl.get("escena", 0) or 0)
            except (TypeError, ValueError):
                continue
            if nv in eliminadas or nv not in mapa_viejo_a_nuevo:
                continue
            pl["escena"] = mapa_viejo_a_nuevo[nv]
            planos_nuevos.append(pl)
        doc.planos = planos_nuevos
        doc.version_corta = sorted(
            mapa_viejo_a_nuevo[n] for n in (getattr(doc, "version_corta", [])
                                            or [])
            if n in mapa_viejo_a_nuevo and n not in eliminadas)
        fe_nuevas = {}
        for k, v in (getattr(doc, "fichas_escenas", {}) or {}).items():
            try:
                nv = int(k)
            except (TypeError, ValueError):
                continue
            if nv in mapa_viejo_a_nuevo and nv not in eliminadas:
                n2 = mapa_viejo_a_nuevo[nv]
                if hasattr(v, "numero"):
                    v.numero = n2
                fe_nuevas[str(n2)] = v
        doc.fichas_escenas = fe_nuevas

        # Reemplazar bloques y recargar (sin borrar el historial: se deshace)
        doc.bloques = nuevos_bloques
        self.cargar_documento(doc, historial=False)
        # Notificar cambio estructural
        try:
            self.estructura_cambiada.emit()
        except Exception:
            pass

    def cargar_documento(self, documento: Documento, historial: bool = True) -> None:
        self.documento = documento
        # Actualizar la referencia del corrector ortográfico al
        # documento actual: así usa las palabras aprendidas del
        # proyecto correcto (viajan dentro del .accion).
        if hasattr(self, "_ortografia_hl"):
            self._ortografia_hl.set_documento_proyecto(documento)
        # Aplicar el tamaño de hoja guardado en el documento
        # (sincroniza el invitado con el host en colaboración).
        try:
            tam_int = int(getattr(documento, "tamano_hoja", 1) or 1)
            if tam_int in (1, 2, 3):
                tam_nuevo = TamañoHoja(tam_int)
                if tam_nuevo != self._tamaño_hoja:
                    self._tamaño_hoja = tam_nuevo
                    lh = self._alto_linea()
                    self._page_h = TAMAÑO_LINEAS[tam_nuevo] * lh
                    self.tamaño_hoja_cambiado.emit(int(tam_nuevo))
        except Exception:
            pass
        self._rerender_completo()
        if historial:
            self._reiniciar_historial()

    def cargar_bloques(self, bloques: list[Bloque]) -> None:
        self.documento.cargar(bloques)
        self._rerender_completo()
        self._reiniciar_historial()

    def nuevo(self) -> None:
        self.documento = Documento()
        self._rerender_completo()
        self._reiniciar_historial()

    # ── Deshacer / rehacer (sobre el guion, no sobre la hoja) ──────────
    _MIME_BLOQUES = "application/x-accion-bloques"
    HISTORIAL_MAX = 300

    def _iniciar_historial(self) -> None:
        self._hist_atras: list[dict] = []
        self._hist_adelante: list[dict] = []
        self._hist_restaurando = False
        self._hist_racha = 0
        self._hist_estado = self._foto_guion()
        self._hist_tipo_tecla = ""
        # (la foto se toma al hacer una pausa, o al cambiar de tipo de
        # cambio: escribir, borrar, Enter, pegar…; así escribir rápido no
        # cuesta nada aunque el guion sea largo)
        self._t_hist = QTimer(self)
        self._t_hist.setSingleShot(True)
        self._t_hist.setInterval(700)
        self._t_hist.timeout.connect(self._registrar_cambio_guion)
        self.document().contentsChanged.connect(self._al_cambiar_hoja)
        self.cursorPositionChanged.connect(self._al_mover_cursor_hist)

    def _reiniciar_historial(self) -> None:
        if not hasattr(self, "_hist_atras"):
            return
        self._t_hist.stop()
        self._hist_atras.clear()
        self._hist_adelante.clear()
        self._hist_racha = 0
        self._hist_tipo_tecla = ""
        self._hist_estado = self._foto_guion()

    def _foto_guion(self) -> dict:
        try:
            idx, off = self._posicion_logica()
        except Exception:
            idx, off = 0, 0
        return {"bloques": [b.copy() for b in self.documento.bloques], "cursor": (idx, off),
                "scroll": self.verticalScrollBar().value()}

    def _al_cambiar_hoja(self) -> None:
        if not self._hist_restaurando and not self._aplicando_remoto:
            self._t_hist.start()

    def _hist_flush(self) -> None:
        """Lo pendiente queda como un paso (antes de otro tipo de cambio)."""
        if hasattr(self, "_t_hist") and self._t_hist.isActive():
            self._t_hist.stop()
            self._registrar_cambio_guion()

    def _hist_antes_de_tecla(self, event) -> None:
        """Escribir de corrido o borrar de corrido es un solo paso; Enter,
        Tab, pegar, cortar… son pasos aparte."""
        texto = event.text()
        mods = event.modifiers()
        ctrl = bool(mods & (Qt.KeyboardModifier.ControlModifier | Qt.KeyboardModifier.MetaModifier))
        if texto and len(texto) == 1 and texto.isprintable() and not ctrl:
            tipo = "tipeo"
        elif event.key() in (Qt.Key.Key_Backspace, Qt.Key.Key_Delete) and not ctrl:
            tipo = "borrar"
        elif event.key() in (Qt.Key.Key_Shift, Qt.Key.Key_Control, Qt.Key.Key_Alt, Qt.Key.Key_Meta,
                             Qt.Key.Key_Left, Qt.Key.Key_Right, Qt.Key.Key_Up, Qt.Key.Key_Down,
                             Qt.Key.Key_Home, Qt.Key.Key_End, Qt.Key.Key_PageUp, Qt.Key.Key_PageDown):
            if event.key() not in (Qt.Key.Key_Shift, Qt.Key.Key_Control, Qt.Key.Key_Alt, Qt.Key.Key_Meta):
                self._hist_flush()
                self._hist_tipo_tecla = ""
            return
        else:
            tipo = "otro"
        if tipo != self._hist_tipo_tecla or tipo == "otro" or self._hist_racha >= 40:
            self._hist_flush()
            self._hist_racha = 0
        self._hist_racha += 1
        self._hist_tipo_tecla = tipo

    def _al_mover_cursor_hist(self) -> None:
        """Si solo se movió el cursor (sin escribir), deshacer vuelve ahí."""
        if not self._hist_restaurando and not self._t_hist.isActive() and hasattr(self, "_hist_estado"):
            try:
                self._hist_estado["cursor"] = self._posicion_logica()
                self._hist_estado["scroll"] = self.verticalScrollBar().value()
            except Exception:
                pass

    def _reconciliar_modelo(self) -> bool:
        """Red de seguridad: si la hoja cambió por un camino que no pasó por
        el guion (un acento compuesto, Mayús+Enter, arrastrar texto…), el
        guion se pone al día con la hoja. True = había diferencias."""
        doc = self.document()
        bl = self.documento.bloques
        textos = []
        qb = doc.begin()
        while qb.isValid():
            textos.append(qb.text().replace("\u2028", "\n"))
            qb = qb.next()
        if len(textos) == len(bl):
            cambio = False
            for i, t in enumerate(textos):
                if t != bl[i].texto:
                    self._sync_texto_de(i)
                    cambio = True
            return cambio
        import difflib as _difflib
        sm = _difflib.SequenceMatcher(None, [b.texto for b in bl], textos, autojunk=False)
        nuevos: list = []
        for tag, i1, i2, j1, j2 in sm.get_opcodes():
            if tag == "equal":
                nuevos.extend(bl[i1:i2])
                continue
            for j in range(j1, j2):
                k = i1 + (j - j1)
                viejo = bl[k] if tag == "replace" and k < i2 else None
                estado_qt = doc.findBlockByNumber(j).userState()
                if viejo is not None:
                    elem = viejo.elem
                elif estado_qt in [int(e) for e in Elem]:
                    elem = Elem(estado_qt)
                else:
                    elem = nuevos[-1].elem if nuevos else Elem.ACCION
                b = Bloque(elem, textos[j])
                if viejo is not None:
                    b.tags, b.numero, b.doble = [dict(t) for t in viejo.tags], viejo.numero, viejo.doble
                nuevos.append(b)
        self.documento.cargar(nuevos)
        return True

    def _registrar_cambio_guion(self) -> None:
        """Después de un cambio (al hacer una pausa o antes de otro tipo de
        cambio): la foto de antes queda para Ctrl+Z."""
        if self._hist_restaurando:
            return
        try:
            self._reconciliar_modelo()
        except Exception:
            pass
        nueva = self._foto_guion()
        previa = self._hist_estado
        if nueva["bloques"] == previa["bloques"]:
            previa["cursor"], previa["scroll"] = nueva["cursor"], nueva["scroll"]
            return
        self._hist_atras.append(previa)
        if len(self._hist_atras) > self.HISTORIAL_MAX:
            del self._hist_atras[0]
        self._hist_adelante.clear()
        self._hist_estado = nueva

    def registrar_paso_documento(self, antes_json: str) -> None:
        """Un cambio grande hecho desde afuera (mover o borrar escenas, con
        planos, fichas y jornadas remapeados) queda como un paso de Ctrl+Z
        con el documento entero."""
        self._t_hist.stop()
        previa = dict(self._hist_estado)
        previa["doc"] = antes_json
        self._hist_atras.append(previa)
        if len(self._hist_atras) > self.HISTORIAL_MAX:
            del self._hist_atras[0]
        self._hist_adelante.clear()
        self._hist_estado = self._foto_guion()
        try:
            self._hist_estado["doc"] = documento_a_json(self.documento)
        except Exception:
            pass

    # (👥 en una sesión de colaboración, Ctrl+Z / Ctrl+Y deshacen solo lo
    # propio, sin tocar lo que escribieron los demás: lo hace la sesión)
    _deshacer_externo = None
    _rehacer_externo = None

    def puede_deshacer(self) -> bool:
        if self._deshacer_externo is not None:
            g = getattr(getattr(self.window(), "_colab", None), "guion", None)
            return bool(g is not None and g.puede_deshacer())
        self._hist_flush()
        return bool(self._hist_atras)

    def puede_rehacer(self) -> bool:
        if self._rehacer_externo is not None:
            g = getattr(getattr(self.window(), "_colab", None), "guion", None)
            return bool(g is not None and g.puede_rehacer())
        return bool(self._hist_adelante)

    def deshacer(self) -> bool:
        """Ctrl+Z: el guion vuelve a como estaba antes del último cambio."""
        if self._deshacer_externo is not None:
            return False if self.isReadOnly() else bool(self._deshacer_externo())
        if self.isReadOnly() or not self.puede_deshacer():
            return False
        self._hist_adelante.append(self._hist_estado)
        self._restaurar_foto(self._hist_atras.pop())
        return True

    def rehacer(self) -> bool:
        """Ctrl+Y (o Ctrl+Mayús+Z): vuelve a hacer lo deshecho."""
        if self._rehacer_externo is not None:
            return False if self.isReadOnly() else bool(self._rehacer_externo())
        if self.isReadOnly():
            return False
        self._hist_flush()
        if not self._hist_adelante:
            return False
        self._hist_atras.append(self._hist_estado)
        self._restaurar_foto(self._hist_adelante.pop())
        return True

    # (lo que llame a undo()/redo() de Qt pasa por el historial del guion)
    def undo(self) -> None:
        self.deshacer()

    def redo(self) -> None:
        self.rehacer()

    def _restaurar_foto(self, foto: dict) -> None:
        self._hist_restaurando = True
        con_doc = bool(foto.get("doc"))
        try:
            if con_doc:
                # (todo el documento: el mismo objeto, con lo de esa foto)
                try:
                    viejo = documento_desde_json(foto["doc"])
                    for k_, v_ in vars(viejo).items():
                        setattr(self.documento, k_, v_)
                except Exception:
                    pass
            self.documento.cargar([b.copy() for b in foto["bloques"]])
            self._rerender_conservando(*foto.get("cursor", (0, 0)), scroll=foto.get("scroll"))
        finally:
            self._t_hist.stop()
            self._hist_restaurando = False
        self._hist_estado = self._foto_guion()
        if con_doc:
            try:
                self._hist_estado["doc"] = documento_a_json(self.documento)
            except Exception:
                pass
        self._hist_racha = 0
        self._hist_tipo_tecla = ""
        try:
            self.estructura_cambiada.emit()
        except Exception:
            pass

    def _rerender_conservando(self, idx: int, off: int, scroll: Optional[int] = None) -> None:
        """Vuelve a dibujar la hoja entera sin perder el lugar: el cursor en
        (idx, off) y la vista donde estaba."""
        sb = self.verticalScrollBar()
        valor = sb.value() if scroll is None else scroll
        self._rerender_completo()
        idx = max(0, min(int(idx), len(self.documento) - 1))
        self._mover_cursor_a(idx, int(off))
        self._recalcular_paginacion()
        sb.setValue(max(sb.minimum(), min(sb.maximum(), int(valor))))
        self.ensureCursorVisible()
        self.tipo_cambiado.emit(self.tipo_actual())

    # ── Copiar, cortar y pegar (sin desincronizar la hoja del guion) ──
    def _piezas_de_seleccion(self) -> list[dict]:
        cur = self.textCursor()
        if not cur.hasSelection():
            return []
        a, b = cur.selectionStart(), cur.selectionEnd()
        qa, qb = self.document().findBlock(a), self.document().findBlock(b)
        i1, o1 = qa.blockNumber(), a - qa.position()
        i2, o2 = qb.blockNumber(), b - qb.position()
        piezas = []
        for i in range(i1, min(i2, len(self.documento) - 1) + 1):
            bl = self.documento[i]
            d = o1 if i == i1 else 0
            h = o2 if i == i2 else len(bl.texto)
            fm = []
            for f in bl.formatos:
                x0, x1 = max(d, int(f.get("desde", 0))), min(h, int(f.get("hasta", 0)))
                if x1 > x0:
                    nf = dict(f)
                    nf["desde"], nf["hasta"] = x0 - d, x1 - d
                    fm.append(nf)
            piezas.append({"elem": int(bl.elem), "texto": bl.texto[d:h], "formatos": fm})
        return piezas

    def createMimeDataFromSelection(self):
        md = super().createMimeDataFromSelection()
        try:
            piezas = self._piezas_de_seleccion()
            if piezas:
                # (la de Qt no acepta formatos nuevos: se arma una aparte)
                from PySide6.QtCore import QMimeData
                nuevo = QMimeData()
                nuevo.setText("\n".join(p_["texto"] for p_ in piezas))
                if md.hasHtml():
                    nuevo.setHtml(md.html())
                nuevo.setData(self._MIME_BLOQUES, QByteArray(json.dumps(piezas).encode("utf-8")))
                return nuevo
        except Exception:
            pass
        return md

    def canInsertFromMimeData(self, source) -> bool:
        return bool(source.hasFormat(self._MIME_BLOQUES) or source.hasText())

    def insertFromMimeData(self, source) -> None:
        """Pegar (Ctrl+V, el menú o soltar texto): entre guiones de ¡Acción!
        cada bloque conserva su tipo; un texto de otro programa se reparte en
        bloques (escenas, personajes, diálogos y acción)."""
        if self.isReadOnly():
            return
        piezas = None
        if source.hasFormat(self._MIME_BLOQUES):
            try:
                piezas = json.loads(bytes(source.data(self._MIME_BLOQUES)).decode("utf-8"))
            except (ValueError, TypeError):
                piezas = None
        if not piezas:
            texto = source.text() if source.hasText() else ""
            if not texto:
                return
            piezas = piezas_desde_texto_guion(texto)
        if piezas:
            self.pegar_piezas(piezas)

    def pegar_piezas(self, piezas: list[dict]) -> None:
        self._hist_flush()
        if self.textCursor().hasSelection():
            self._borrar_seleccion_multiple()
        idx, off = self._posicion_logica()
        if not (0 <= idx < len(self.documento)):
            return
        bl = self.documento[idx]
        cabeza, cola = bl.texto[:off], bl.texto[off:]
        if len(piezas) == 1:
            t = str(piezas[0].get("texto", ""))
            nuevo = cabeza + t + cola
            if bl.formatos:
                self._ajustar_formatos_por_diff_texto(idx, bl.texto, nuevo)
            self.documento.actualizar_texto(idx, nuevo)
            self._reformatear_bloque(idx)
            self._mover_cursor_a(idx, off + len(t))
            self.ensureCursorVisible()
            return
        nuevos: list = []
        for p_ in piezas:
            try:
                elem = Elem(int(p_.get("elem", int(Elem.ACCION))))
            except (TypeError, ValueError):
                elem = Elem.ACCION
            b = Bloque(elem, aplicar_caso_a_texto(elem, str(p_.get("texto", ""))),
                       formatos=[dict(f) for f in p_.get("formatos", []) or []])
            nuevos.append(b)
        # El bloque se parte en el cursor: lo de antes queda como estaba, lo
        # pegado sigue con sus tipos y lo de después vuelve a su tipo
        antes, despues = [], []
        if cabeza.strip():
            antes = [Bloque(bl.elem, cabeza, [dict(t) for t in bl.tags],
                            [dict(f) for f in bl.formatos if int(f.get("hasta", 0)) <= len(cabeza)],
                            bl.numero, bl.doble)]
        if cola.strip():
            despues = [Bloque(bl.elem, cola.lstrip(), [] if antes else [dict(t) for t in bl.tags])]
        self.documento.bloques[idx:idx + 1] = antes + nuevos + despues
        ultimo = idx + len(antes) + len(nuevos) - 1
        self._rerender_conservando(ultimo, len(self.documento[ultimo].texto))
        try:
            self.estructura_cambiada.emit()
        except Exception:
            pass

    def dropEvent(self, event) -> None:
        # Arrastrar texto dentro de la hoja lo copia (moverlo lo borraba de
        # la hoja sin borrarlo del guion)
        if isinstance(event.source(), EditorGuion):
            event.setDropAction(Qt.DropAction.CopyAction)
        super().dropEvent(event)

    # ── Marca de agua ──────────────────────────────────────────────────

    def set_marca_agua(self, texto: str) -> None:
        self._marca_agua = (texto or "").strip()
        self.viewport().update()

    def marca_agua(self) -> str:
        return self._marca_agua

    # ── Mouse: detectar clicks sobre íconos de notas/tags ──────────────

    def mousePressEvent(self, event) -> None:
        self._hist_flush()                       # (escribir en otro lugar es otro paso)
        self._hist_tipo_tecla = ""
        pos = event.position() if hasattr(event, "position") else event.pos()
        px_, py = pos.x(), pos.y()
        # Buscar si el click cae sobre un ícono pintado
        for rect, idx_bloque, categoria in self._rects_iconos:
            if rect.contains(px_, py):
                self.icono_clickeado.emit(idx_bloque, categoria)
                return  # consume el evento; no posicionar el cursor
        # ── Clic sobre marcador [📷 Foto N: ...] → abre preview modal ──
        cursor = self.cursorForPosition(pos.toPoint()
                                        if hasattr(pos, "toPoint") else pos)
        texto_bloque = cursor.block().text()
        pos_en_bloque = cursor.positionInBlock()
        import re as _re
        for m in _re.finditer(r"\[📷 Foto (\d+):[^\]]*\]", texto_bloque):
            if m.start() <= pos_en_bloque <= m.end():
                indice = int(m.group(1)) - 1
                self._abrir_preview_foto(indice)
                event.accept()
                return
        super().mousePressEvent(event)

    def _abrir_preview_foto(self, indice: int) -> None:
        """Abre una vista previa modal de la foto. Si el usuario elige
        'Ir a la Pizarra de beats', se abre la pizarra centrada en esa foto."""
        w = self.window()
        dlg = DialogoPreviewFoto(self.documento, indice, parent=w)
        dlg.ir_al_beatboard.connect(self._abrir_beatboard_en_foto)
        dlg.exec()

    def mouseDoubleClickEvent(self, event) -> None:
        """Doble clic sobre un marcador [📷 Foto N: ...] abre el Beat
        Board y centra la vista en esa foto."""
        pos = event.position().toPoint() if hasattr(event, "position") \
            else event.pos()
        cursor = self.cursorForPosition(pos)
        texto_bloque = cursor.block().text()
        pos_en_bloque = cursor.positionInBlock()
        # Buscar un marcador que abarque la posición del doble clic
        import re as _re
        for m in _re.finditer(r"\[📷 Foto (\d+):[^\]]*\]", texto_bloque):
            if m.start() <= pos_en_bloque <= m.end():
                indice = int(m.group(1)) - 1  # 1-indexed en el texto
                self._abrir_beatboard_en_foto(indice)
                event.accept()
                return
        super().mouseDoubleClickEvent(event)

    def _abrir_beatboard_en_foto(self, indice: int) -> None:
        """Abre la Pizarra de beats y centra la vista en la foto indicada."""
        if not (0 <= indice < len(self.documento.fotos_beatboard)):
            QMessageBox.information(
                self.window(), "Foto no encontrada",
                f"La foto {indice + 1} ya no existe en la Pizarra de beats.\n"
                "Puede que haya sido eliminada.")
            return
        w = self.window()
        dlg = VentanaBeatBoard(self.documento, parent=w)
        # Conectar «enviar al guion» como hace VentanaPrincipal
        if hasattr(w, "_insertar_beats_en_guion"):
            dlg.enviar_solicitado.connect(w._insertar_beats_en_guion)
        # Centrar en la foto tras un tick (necesita que la vista se muestre)
        QTimer.singleShot(50, dlg, lambda: dlg.centrar_en_foto(indice))
        dlg.exec()

    # ── Manejo de teclas ───────────────────────────────────────────────

    def keyPressEvent(self, event) -> None:
        key = event.key()
        mods = event.modifiers()

        # Si el editor está en modo solo lectura (invitado en sesión),
        # bloqueamos TODA edición. Solo dejamos pasar teclas de
        # navegación (flechas, PageUp/Down, Home/End, Ctrl+C copiar).
        if self.isReadOnly():
            teclas_permitidas = {
                Qt.Key.Key_Left, Qt.Key.Key_Right, Qt.Key.Key_Up, Qt.Key.Key_Down,
                Qt.Key.Key_PageUp, Qt.Key.Key_PageDown,
                Qt.Key.Key_Home, Qt.Key.Key_End,
            }
            if key in teclas_permitidas:
                super().keyPressEvent(event)
                return
            # Ctrl+C (copiar) y Ctrl+A (seleccionar todo) están permitidos
            if mods & Qt.KeyboardModifier.ControlModifier:
                if key in (Qt.Key.Key_C, Qt.Key.Key_A, Qt.Key.Key_Insert):
                    super().keyPressEvent(event)
                    return
            # El resto: ignorar silenciosamente
            return

        self._hist_antes_de_tecla(event)
        if event.matches(QKeySequence.StandardKey.Undo):
            self.deshacer()
            return
        if event.matches(QKeySequence.StandardKey.Redo) or (
                key == Qt.Key.Key_Y and mods & Qt.KeyboardModifier.ControlModifier):
            self.rehacer()
            return

        if key in (Qt.Key.Key_Return, Qt.Key.Key_Enter):
            if mods & Qt.KeyboardModifier.ShiftModifier:
                super().keyPressEvent(event)
                return
            self._on_enter()
            return

        if key == Qt.Key.Key_Tab:
            self._on_tab(reverse=False)
            return
        if key == Qt.Key.Key_Backtab:
            self._on_tab(reverse=True)
            return

        if key == Qt.Key.Key_Backspace and not (mods & Qt.KeyboardModifier.ControlModifier):
            if self._on_backspace():
                return

        if key == Qt.Key.Key_Delete and not (mods & Qt.KeyboardModifier.ControlModifier):
            if self._on_delete():
                return

        # Ctrl+X (cortar): copiar al portapapeles y luego borrar la
        # selección usando nuestro handler multi-bloque.
        if (key == Qt.Key.Key_X and (mods & Qt.KeyboardModifier.ControlModifier)
                and not (mods & Qt.KeyboardModifier.ShiftModifier)):
            cur = self.textCursor()
            if cur.hasSelection():
                # Copiar al portapapeles primero
                from PySide6.QtGui import QGuiApplication
                clip = QGuiApplication.clipboard()
                clip.setMimeData(self.createMimeDataFromSelection())
                # Borrar con nuestro handler que maneja multi-bloque
                self._borrar_seleccion_multiple()
                return

        # Ctrl+V (pegar): si hay selección múltiple, la borramos antes
        # de que Qt haga el paste (así no se rompen los bloques).
        if (key == Qt.Key.Key_V and (mods & Qt.KeyboardModifier.ControlModifier)
                and not (mods & Qt.KeyboardModifier.ShiftModifier)):
            cur = self.textCursor()
            if cur.hasSelection():
                self._borrar_seleccion_multiple()
            # Dejar que Qt haga el paste
            super().keyPressEvent(event)
            return

        # Tipeo normal con transformación de caso y autocompletado
        texto = event.text()
        if (
            texto and len(texto) == 1 and texto.isprintable()
            and not (mods & (Qt.KeyboardModifier.ControlModifier
                             | Qt.KeyboardModifier.AltModifier
                             | Qt.KeyboardModifier.MetaModifier))
        ):
            self._on_tipeo(texto)
            return

        super().keyPressEvent(event)

    # ── Manejadores ────────────────────────────────────────────────────

    def _scroll_a_cursor_con_margen(self) -> None:
        """Asegura que el cursor esté visible. Si está muy cerca del
        borde inferior o superior del viewport, agrega un poco de
        margen para que no quede pegado.

        Comportamiento estilo Word: al presionar Enter, la línea nueva
        se ve, pero la línea anterior TAMBIÉN queda visible arriba
        (no cae fuera de vista por un solo pixel)."""
        try:
            self.ensureCursorVisible()
            # Luego chequear si el cursor quedó pegado al borde inferior
            cursor_rect = self.cursorRect()
            vp_h = self.viewport().height()
            y_cursor = cursor_rect.y()
            # Si el cursor está en el último 15% del viewport, subir un poco
            margen = int(vp_h * 0.15)
            if y_cursor > vp_h - margen:
                # Scrollear hacia abajo `margen` px extra para dar aire
                scrollbar = self.verticalScrollBar()
                delta = (y_cursor + margen) - vp_h
                nuevo = scrollbar.value() + delta
                nuevo = max(scrollbar.minimum(),
                            min(scrollbar.maximum(), nuevo))
                scrollbar.setValue(nuevo)
        except Exception:
            pass

    def _on_enter(self) -> None:
        idx, offset = self._posicion_logica()
        bloque = self.documento[idx]

        # Línea vacía → menú flotante para elegir el tipo
        if not bloque.texto.strip():
            self._abrir_menu_elementos()
            return

        # ── Fix paréntesis: si el cursor está DENTRO de "(...)",
        # mover al final del texto antes de partir. Esto evita que
        # el paréntesis se rompa y el ")" caiga en un bloque nuevo.
        if (bloque.elem == Elem.PARENTESIS
                and bloque.texto.startswith("(")
                and bloque.texto.endswith(")")
                and 0 < offset < len(bloque.texto)):
            offset = len(bloque.texto)
            self._mover_cursor_a(idx, offset)

        # Detectar personaje nuevo (sin cambiar formato)
        if bloque.elem == Elem.PERSONAJE and offset == len(bloque.texto):
            nombre_norm = bloque.texto.strip().upper().split("(")[0].strip()
            if (nombre_norm
                    and nombre_norm not in self.documento.fichas
                    and nombre_norm not in self._personajes_anunciados):
                self.documento.fichas[nombre_norm] = Ficha(personaje=nombre_norm)
                self._personajes_anunciados.add(nombre_norm)
                self.personaje_nuevo_detectado.emit(nombre_norm)

        # ──────────────────────────────────────────────────────────────
        # ENTER FLUIDO:
        # - Actualiza el modelo (divide el bloque o crea uno nuevo abajo).
        #   El modelo decide el tipo del bloque nuevo: si el Enter fue al
        #   final, avanza según el flujo de guion (SIGUIENTE_ENTER); si se
        #   partió por el medio, mantiene el tipo.
        # - En lugar de _rerender_completo (que redibuja todo y "salta"),
        #   usa cursor.insertBlock(): Qt reflowa incrementalmente y se
        #   ve el texto/imagen bajar de manera natural.
        # ──────────────────────────────────────────────────────────────
        nidx, _ = self.documento.enter(idx, offset)
        nuevo_elem = self.documento[nidx].elem  # tipo decidido por el modelo
        bf_nuevo, cf_nuevo = self._formato_para(nuevo_elem)

        cursor = self.textCursor()
        cursor.beginEditBlock()
        cursor.insertBlock(bf_nuevo, cf_nuevo)
        cursor.endEditBlock()

        # Sincronizar userState (Qt usa esto para mantener el tipo de cada
        # bloque del QTextDocument coincidente con el modelo)
        qblock = self.document().findBlockByNumber(nidx)
        if qblock.isValid():
            qblock.setUserState(int(nuevo_elem))

        # Notificar al ribbon el nuevo tipo activo
        self.tipo_cambiado.emit(nuevo_elem)

        # Recalcular paginación en el próximo tick (no bloquea la animación)
        QTimer.singleShot(0, self._recalcular_paginacion)
        self.viewport().update()
        # Mantener el cursor visible tras Enter (comportamiento tipo
        # Word: el texto sigue a la vista, no se pierde). Se hace en el
        # próximo tick, después del recálculo de paginación, para que
        # apunte a la posición final estable. Con margen extra para
        # que no quede pegado al borde inferior.
        QTimer.singleShot(0, self._scroll_a_cursor_con_margen)
        # Notificar al sistema de colaboración: se agregó un bloque
        self.estructura_cambiada.emit()
        # Notificar Enter para forzar flush inmediato del buffer colab
        self.enter_presionado.emit()

    def _on_tab(self, reverse: bool = False) -> None:
        idx, _ = self._posicion_logica()
        self.documento.tab(idx, reverse=reverse)
        self._reformatear_bloque(idx)
        self.tipo_cambiado.emit(self.tipo_actual())
        # Notificar al sistema de colaboración: cambió el tipo
        self.estructura_cambiada.emit()

    def _borrar_seleccion_multiple(self) -> bool:
        """Si hay una selección que abarca uno o más bloques, la borra
        completamente actualizando el modelo lógico y re-renderizando.
        Devuelve True si borró algo, False si no había selección.

        Cubre TODOS los casos:
          • Selección dentro de un solo bloque.
          • Selección que cruza varios bloques (Shift+arrow, drag,
            Ctrl+A, triple clic, etc.).
        """
        cur = self.textCursor()
        if not cur.hasSelection():
            return False

        # Rango de bloques que toca la selección
        start = cur.selectionStart()
        end = cur.selectionEnd()
        qdoc = self.document()
        qb_start = qdoc.findBlock(start)
        qb_end = qdoc.findBlock(end)
        idx_start = qb_start.blockNumber()
        idx_end = qb_end.blockNumber()
        # Offset dentro del bloque inicial y final
        off_start = start - qb_start.position()
        off_end = end - qb_end.position()

        # ── Caso 1: selección dentro de UN solo bloque ──
        if idx_start == idx_end:
            bloque = self.documento[idx_start]
            nuevo_texto = bloque.texto[:off_start] + bloque.texto[off_end:]
            self.documento.actualizar_texto(idx_start, nuevo_texto)
            self._rerender_completo()
            self._mover_cursor_a(idx_start, off_start)
            self.estructura_cambiada.emit()
            return True

        # ── Caso 2: selección abarca varios bloques ──
        # Estrategia:
        #   1. Bloque inicial: conservar solo el texto antes de off_start.
        #   2. Bloque final: conservar solo el texto después de off_end.
        #   3. Fusionar bloque inicial + bloque final (heredando tipo
        #      del bloque inicial).
        #   4. Eliminar bloques intermedios y el final.
        bloque_inicial = self.documento[idx_start]
        bloque_final = self.documento[idx_end]

        texto_pre = bloque_inicial.texto[:off_start]
        texto_pos = bloque_final.texto[off_end:]
        texto_fusion = texto_pre + texto_pos

        # Actualizar el bloque inicial con el texto fusionado
        self.documento.actualizar_texto(idx_start, texto_fusion)

        # Eliminar bloques desde idx_start+1 hasta idx_end (inclusive)
        # de mayor a menor para no descolocar índices
        for i in range(idx_end, idx_start, -1):
            try:
                self.documento.bloques.pop(i)
            except (IndexError, AttributeError):
                pass

        # Si quedó vacío el documento, dejar al menos un bloque
        if not self.documento.bloques:
            self.documento.bloques.append(
                Bloque(Elem.ACCION, ""))

        self._rerender_completo()
        self._mover_cursor_a(idx_start, off_start)
        self.estructura_cambiada.emit()
        return True

    def _on_backspace(self) -> bool:
        # Si hay selección múltiple, borrarla toda (esto cubre el caso
        # de seleccionar varios bloques y presionar Backspace/Delete).
        if self._borrar_seleccion_multiple():
            return True

        idx, offset = self._posicion_logica()

        if offset > 0:
            cursor = self.textCursor()
            cursor.deletePreviousChar()
            self._sync_texto_de(idx)
            self.viewport().update()
            return True

        if idx == 0:
            return True

        nidx, noff = self.documento.backspace(idx, offset)
        self._rerender_completo()
        self._mover_cursor_a(nidx, noff)
        # Notificar al sistema de colaboración: se borró un bloque
        self.estructura_cambiada.emit()
        return True

    def _on_delete(self) -> bool:
        # Si hay selección múltiple, borrarla toda.
        if self._borrar_seleccion_multiple():
            return True

        idx, offset = self._posicion_logica()
        bloque = self.documento[idx]
        if offset < len(bloque.texto):
            cursor = self.textCursor()
            cursor.deleteChar()
            self._sync_texto_de(idx)
            self.viewport().update()
            return True

        if idx + 1 >= len(self.documento):
            return True

        self.documento.backspace(idx + 1, 0)
        self._rerender_completo()
        self._mover_cursor_a(idx, offset)
        # Notificar al sistema de colaboración: se borró un bloque
        self.estructura_cambiada.emit()
        return True

    def _on_tipeo(self, texto: str) -> None:
        # Si hay una selección múltiple, primero la borramos: luego el
        # tipeo cae en la posición donde empezaba la selección. Es el
        # comportamiento estándar en cualquier editor.
        cur_check = self.textCursor()
        if cur_check.hasSelection():
            self._borrar_seleccion_multiple()
        idx, offset = self._posicion_logica()
        bloque = self.documento[idx]

        # Autocompletado en ESCENA vacía: I/E/i/e/'/' → "INT. " / "EXT. " / "I/E. "
        if bloque.elem == Elem.ESCENA and not bloque.texto and texto in PREFIJOS_ESCENA:
            prefijo = PREFIJOS_ESCENA[texto]
            self.documento.actualizar_texto(idx, prefijo)
            self._reformatear_bloque(idx)
            self._mover_cursor_a(idx, len(prefijo))
            return

        # En ESCENA con texto: al escribir "-" ofrecer menú DÍA/NOCHE/etc.
        # Solo si el cursor está al FINAL del texto y aún no hay " - " escrito
        if (bloque.elem == Elem.ESCENA and texto == "-"
                and offset == len(bloque.texto)
                and " - " not in bloque.texto
                and bloque.texto.strip()):
            # Insertar " - " (con espacio antes si no lo tiene)
            anterior = bloque.texto.rstrip()
            nuevo = anterior + " - "
            self.documento.actualizar_texto(idx, nuevo)
            self._reformatear_bloque(idx)
            self._mover_cursor_a(idx, len(nuevo))
            # Mostrar menú de tiempos
            QTimer.singleShot(0, self._mostrar_menu_tiempo_encabezado)
            return

        # Tipeo normal con transformación de caso
        texto_previo = bloque.texto[:offset]
        c = transformar_caracter(bloque.elem, texto_previo, texto)
        self.documento.insertar_caracter(idx, offset, c)

        cursor = self.textCursor()
        cursor.insertText(c)
        self.viewport().update()

    def _sync_texto_de(self, idx: int) -> None:
        qblock = self.document().findBlockByNumber(idx)
        if qblock.isValid() and 0 <= idx < len(self.documento):
            texto_nuevo = qblock.text().replace("\u2028", "\n")
            texto_previo = self.documento[idx].texto
            # Antes de actualizar el texto, ajustar los offsets de los
            # formatos guardados si cambió la longitud del texto.
            if texto_previo != texto_nuevo and self.documento[idx].formatos:
                self._ajustar_formatos_por_diff_texto(
                    idx, texto_previo, texto_nuevo)
            self.documento.actualizar_texto(idx, texto_nuevo)

    def _ajustar_formatos_por_diff_texto(self, idx: int,
                                          previo: str, nuevo: str) -> None:
        """Cuando el usuario inserta o borra caracteres, ajusta los
        offsets `desde`/`hasta` de los formatos guardados para que
        sigan apuntando al mismo texto lógico. Estrategia: prefijo/
        sufijo común + delta de longitud aplicado a las posiciones que
        caen a la derecha del cambio."""
        # Localizar el rango cambiado (prefijo/sufijo común)
        i = 0
        n_min = min(len(previo), len(nuevo))
        while i < n_min and previo[i] == nuevo[i]:
            i += 1
        j = 0
        while (j < n_min - i and
               previo[len(previo) - 1 - j] == nuevo[len(nuevo) - 1 - j]):
            j += 1
        cambio_ini = i
        cambio_fin_previo = len(previo) - j
        delta = len(nuevo) - len(previo)

        formatos_ajustados = []
        for f in self.documento[idx].formatos:
            desde, hasta = int(f.get("desde", 0)), int(f.get("hasta", 0))
            # Cuatro casos según dónde cae el rango vs el cambio:
            if hasta <= cambio_ini:
                # Antes del cambio: sin cambios
                formatos_ajustados.append(dict(f))
            elif desde >= cambio_fin_previo:
                # Después del cambio: mover por delta
                nf = dict(f)
                nf["desde"] = desde + delta
                nf["hasta"] = hasta + delta
                if nf["hasta"] > nf["desde"]:
                    formatos_ajustados.append(nf)
            else:
                # Se superpone con el cambio: recortar
                nf = dict(f)
                nf["desde"] = min(desde, cambio_ini)
                # Si empezaba dentro del cambio, empieza al inicio del cambio
                if nf["desde"] > cambio_ini:
                    nf["desde"] = cambio_ini
                # El final se mueve por delta si estaba después del cambio
                if hasta >= cambio_fin_previo:
                    nf["hasta"] = hasta + delta
                else:
                    nf["hasta"] = cambio_ini
                if nf["hasta"] > nf["desde"]:
                    formatos_ajustados.append(nf)
        self.documento[idx].formatos = formatos_ajustados

    # ── Menús de Encabezado: INT/EXT y DÍA/NOCHE ──────────────────────

    def _mostrar_menu_encabezado_intext(self) -> None:
        """Muestra menú flotante para elegir INT./EXT./I/E. en el bloque
        de Encabezado actual. Si elige una opción, inserta el prefijo y
        deja el cursor listo para escribir el nombre de la locación.
        """
        idx, _ = self._posicion_logica()
        if idx >= len(self.documento):
            return
        if self.documento[idx].elem != Elem.ESCENA:
            return
        if self.documento[idx].texto.strip():
            return  # ya tiene contenido, no molestar

        menu = QMenu(self)
        menu.setStyleSheet(estilo_menu_claro(min_width=120))
        for prefijo, descripcion in [
            ("INT. ",  "Interior"),
            ("EXT. ",  "Exterior"),
            ("I/E. ",  "Interior / Exterior"),
        ]:
            act = QAction(f"  {prefijo}    — {descripcion}", self)
            act.triggered.connect(lambda _, p=prefijo: self._insertar_prefijo_encabezado(p))
            menu.addAction(act)

        rect = self.cursorRect()
        pos = self.viewport().mapToGlobal(rect.bottomLeft())
        menu.popup(pos)

    def _insertar_prefijo_encabezado(self, prefijo: str) -> None:
        idx, _ = self._posicion_logica()
        if idx >= len(self.documento):
            return
        self.documento.actualizar_texto(idx, prefijo)
        self._reformatear_bloque(idx)
        self._mover_cursor_a(idx, len(prefijo))
        self.setFocus()

    # ── Menú de transiciones estándar de la industria ─────────────
