    cmd_modo_visual     = Signal()   # ♿ modo discapacidad visual (todo por voz)

    # Producción (fichas)
    fichas_personajes_solicitadas    = Signal()
    fichas_locaciones_solicitadas    = Signal()
    fichas_equipamiento_solicitadas  = Signal()
    fichas_tecnicos_solicitados      = Signal()
