    tutorial_iniciar                 = Signal()
    tutorial_ruta_solicitada         = Signal(str)  # basico/guionista/productor
    tutorial_voz_solicitado          = Signal()     # ♿ el tutorial por voz
    tutorial_desactivar              = Signal()

    # Archivo
    archivo_guardar      = Signal()
    archivo_guardar_como = Signal()
    archivo_abrir        = Signal()
    archivo_ejemplos     = Signal()          # 🎬 los guiones de ejemplo
    archivo_exportar_pdf = Signal()
    archivo_exportar_txt = Signal()
    archivo_exportar_rtf = Signal()
