    archivo_exportar_audio = Signal()   # export audiodrama
    archivo_exportar_fountain = Signal()  # .fountain (Highland, Beat…)
    archivo_imprimir     = Signal()

    # Formato / estilo / revisión
    marca_agua_solicitada     = Signal()
    orientacion_solicitada    = Signal()
    corrector_solicitado      = Signal()
    autor_solicitado          = Signal()
    tema_solicitado           = Signal(str)   # "claro" / "oscuro" / "sepia"
    tema_colores_solicitado   = Signal()      # 🖌 Tema y colores (con la hoja)
    modo_oscuro_solicitado    = Signal(bool)  # 🌙 Modo oscuro (hoja negra) / ☀ Modo claro

    # ── Niveles de densidad del ribbon ─────────────────────────────
    # El ribbon elige SOLO el nivel más amplio cuyo contenido cabe en
    # el ancho de la ventana (ver _elegir_nivel). Así, en 4K se ve
    # igual que siempre (nivel 0) y en un notebook HD pasa a "medio" o
    # "compacto" sin cortar ningún texto. Si ni el compacto cabe (por
    # ejemplo, con la ventana achicada a mano), la fila de botones se
    # puede desplazar horizontalmente: nunca se recorta un botón.
    # Los valores van en pixeles de diseño: escalar_qss() además los
    # ajusta a la densidad de la pantalla (§0.5).
    NIVELES = (
        # 0 · amplio (diseño original)
        dict(tab_pv=14, tab_ph=22, tab_fs=11, tab_minw=78,
             b_pv=6, b_ph=12, b_minw=70, b_minh=36, b_fs=10, t_minw=34,
             enc_ph=10, enc_minh=38, v_ph=12, v_minw=110, nar_minw=90,
             pane_pb=8, espacio=6, marg_h=10, marg_v=8, logo=40,
             logo_pad=12, sep_m=6, cap_conexion=True),
        # 1 · medio (Full HD al 125 %, ventanas medianas)
        dict(tab_pv=12, tab_ph=14, tab_fs=10.5, tab_minw=56,
             b_pv=6, b_ph=8, b_minw=0, b_minh=34, b_fs=10, t_minw=30,
             enc_ph=9, enc_minh=36, v_ph=10, v_minw=0, nar_minw=0,
             pane_pb=6, espacio=4, marg_h=8, marg_v=6, logo=36,
             logo_pad=10, sep_m=4, cap_conexion=True),
        # 2 · compacto (HD 1366×768, SD, ventanas chicas)
        dict(tab_pv=10, tab_ph=9, tab_fs=10, tab_minw=0,
             b_pv=5, b_ph=6, b_minw=0, b_minh=32, b_fs=9.5, t_minw=28,
             enc_ph=7, enc_minh=34, v_ph=8, v_minw=0, nar_minw=0,
             pane_pb=4, espacio=2, marg_h=6, marg_v=5, logo=30,
             logo_pad=8, sep_m=3, cap_conexion=False),
    )

    def __init__(self):
        super().__init__()
        self._nivel: int = 0
        self._anchos_nivel: dict[int, int] = {}
        self._paneles: list[QWidget] = []
        self._layouts_panel: list[QHBoxLayout] = []
        self._separadores: list[QFrame] = []
        self._logo_label: Optional[QLabel] = None
        self._eligiendo_nivel = False
        # Botones reubicables: cada botón tiene un id («inicio.nota»); la
        # disposición dice en qué pestaña y grupo va cada uno.
        self._rb_widgets: dict = {}                 # id → botón
        self._rb_nombres: dict = {}                 # id → nombre para mostrar
        self._rb_original: list = []                # [{"nombre", "grupos": [[ids]]}] (la de ¡Acción!)
        self._rb_tab_actual = ""
        self._rb_guardados = QWidget()              # (los botones que no están en el ribbon)
        self._rb_guardados.hide()
        self._modo_mover = False
        self._arrastre: Optional[dict] = None
        self._presion: Optional[dict] = None          # (un botón apretado: si se mantiene, se levanta)
        self._t_presion = QTimer(self)
        self._t_presion.setSingleShot(True)
        self._t_presion.setInterval(MS_MANTENER_RIBBON)
        self._t_presion.timeout.connect(self._presion_larga)
        self.setTabBar(_BarraPestanasRibbon(self))
        self.tabBar().setExpanding(False)          # (setTabBar la vuelve a estirar: el «+» necesita su espacio)
        self._aplicar_estilo(0)
        self._construir_pestanas()
        self._fijar_ancho_encabezado()
        self._ajustar_alto()
        # Re-evaluar el nivel cuando cambia el ancho (agrupado: un
        # solo cálculo por ráfaga de resizes).
        self._timer_nivel = QTimer(self)
        self._timer_nivel.setSingleShot(True)
        self._timer_nivel.setInterval(0)
        self._timer_nivel.timeout.connect(self._elegir_nivel)
        # (El botón ⚙ de configuración vive ahora en la pestaña
        # Inicio, no en la esquina superior derecha. Antes tapaba
        # otros botones importantes.)

    # ── Adaptación al ancho disponible ───────────────────────────────

    def resizeEvent(self, ev) -> None:
        super().resizeEvent(ev)
        if ev.oldSize().width() != ev.size().width():
            self._timer_nivel.start()
        self._colocar_aviso_mover()

    def showEvent(self, ev) -> None:
        super().showEvent(ev)
        self._timer_nivel.start()

    def nivel_densidad(self) -> int:
        """0 = amplio, 1 = medio, 2 = compacto."""
        return self._nivel

    def _ancho_necesario(self, nivel: int) -> int:
        """Ancho (px) que necesita el ribbon en un nivel: el panel de
        botones más ancho o la fila de pestañas + logo + esquina."""
        if nivel in self._anchos_nivel:
            return self._anchos_nivel[nivel]
        if nivel != self._nivel:
            self._aplicar_nivel(nivel, medir=True)
        ancho_paneles = 0
        for lay in self._layouts_panel:
            lay.invalidate()
            ancho_paneles = max(ancho_paneles, lay.sizeHint().width())
        tb = self.tabBar()
        ancho_tabs = sum(tb.tabSizeHint(i).width()
                         for i in range(tb.count()))
        for esquina in (Qt.Corner.TopLeftCorner,
                        Qt.Corner.TopRightCorner):
            cw = self.cornerWidget(esquina)
            if cw is not None and cw.isVisibleTo(self):
                ancho_tabs += cw.sizeHint().width()
        necesario = max(ancho_paneles, ancho_tabs) + 8
        self._anchos_nivel[nivel] = necesario
        return necesario

    def _elegir_nivel(self) -> None:
        """Elige el nivel más amplio cuyo contenido cabe completo."""
        if self._eligiendo_nivel or self.width() <= 0:
            return
        self._eligiendo_nivel = True
        try:
            disponible = self.width()
            elegido = len(self.NIVELES) - 1
            for nivel in range(len(self.NIVELES)):
                if self._ancho_necesario(nivel) <= disponible:
                    elegido = nivel
                    break
            if elegido != self._nivel:
                self._aplicar_nivel(elegido)
            else:
                self._aplicar_nivel(elegido, solo_si_distinto=True)
                if elegido == len(self.NIVELES) - 1:
                    self._ajustar_alto()   # ¿aparece/desaparece barrita?
        finally:
            self._eligiendo_nivel = False

    def invalidar_anchos(self) -> None:
        """Llamar si cambian textos de botones del ribbon."""
        self._anchos_nivel.clear()
        if self.isVisible():
            self._timer_nivel.start()

    def _aplicar_nivel(self, nivel: int, medir: bool = False,
                       solo_si_distinto: bool = False) -> None:
        if solo_si_distinto and getattr(self, "_nivel_aplicado",
                                        None) == nivel:
            return
        nv = self.NIVELES[nivel]
        self._aplicar_estilo(nivel)
        for lay in self._layouts_panel:
            lay.setSpacing(px(nv["espacio"]))
            lay.setContentsMargins(px(nv["marg_h"]), px(nv["marg_v"]),
                                   px(nv["marg_h"]), px(nv["marg_v"]))
        for sep in self._separadores:
            aplicar_qss_tematizado(
                sep, f"color: #3c5793; max-width: 1px; "
                     f"margin: {nv['sep_m'] + 2}px {nv['sep_m']}px;")
        if self._logo_label is not None:
            self._logo_label.setPixmap(
                cargar_logo_pixmap(alto_px=px(nv["logo"])))
            aplicar_qss_tematizado(
                self._logo_label,
                f"background: #1a2742; padding: 0 {nv['logo_pad']}px;")
        esquina = self.cornerWidget(Qt.Corner.TopRightCorner)
        if esquina is not None:
            for lbl in esquina.findChildren(QLabel):
                if lbl.text() == "Conexión":
                    lbl.setVisible(bool(nv["cap_conexion"]))
        self._fijar_ancho_encabezado()
        # El panel nunca se angosta más que la suma de sus botones: si
        # no cabe, aparece la barrita de desplazamiento en vez de
        # apretar los botones (un min-width de QSS los dejaría
        # encogerse unos pixeles y cortar el texto).
        for pan, lay in zip(self._paneles, self._layouts_panel):
            pan.setMinimumWidth(0)
            lay.invalidate()
            if not medir:
                pan.setMinimumWidth(lay.sizeHint().width())
        if not medir:
            self._nivel_aplicado = nivel
            self._ajustar_alto()

    def _fijar_ancho_encabezado(self) -> None:
        """El botón naranjo cambia de texto con cada bloque («ACCIÓN»,
        «INICIO DE ACTO»…). Se fija al ancho del texto más largo para
        que no salte ni empuje al resto del ribbon."""
        btn = getattr(self, "_btn_encabezado", None)
        if btn is None:
            return
        actual = btn.text()
        btn.setMinimumWidth(0)
        btn.setMaximumWidth(16777215)
        ancho = 0
        for nombre in NOMBRE.values():
            btn.setText(f"🎬  {nombre.upper()}  ▾")
            ancho = max(ancho, btn.sizeHint().width())
        btn.setText(actual)
        btn.setFixedWidth(ancho)

    def _ajustar_alto(self) -> None:
        """Alto natural del ribbon (pestañas + fila de botones), igual
        que el diseño original. Si la fila no cabe ni en el nivel
        compacto, suma el alto de la barrita de desplazamiento para
        que los botones no queden tapados."""
        for lay in self._layouts_panel:
            lay.invalidate()
        self.setMinimumHeight(0)
        self.setMaximumHeight(16777215)
        alto = self.sizeHint().height()
        ultimo = len(self.NIVELES) - 1
        if (self._nivel == ultimo and self.width() > 0
                and self._anchos_nivel.get(ultimo, 0) > self.width()):
            alto += px(6)
        self.setFixedHeight(max(px(70), alto))

    def _aplicar_estilo(self, nivel: int = 0) -> None:
        self._nivel = nivel
        nv = self.NIVELES[nivel]
        if isinstance(self.tabBar(), _BarraPestanasRibbon):
            self.tabBar().pt = float(nv["tab_fs"])
        # El ribbon mantiene su paleta cinematográfica fija (Studio)
        # independientemente del tema del editor, porque es la "marca"
        # visual del programa. Los valores dependen del nivel de
        # densidad (ver NIVELES).
        qss = f"""
            /* Contenedor del ribbon: el "pane" es la zona DEBAJO de
               las tabs (la fila de botones del panel actual). Tiene
               fondo azul submenú y una línea ámbar gruesa al final
               que cierra visualmente la franja del ribbon contra el
               editor. El padding-bottom da aire entre los botones y
               la línea ámbar para que no quede pegada. */
            QTabWidget::pane {{
                background: #243358;
                border: none;
                border-top: 1px solid #0d1626;
                border-bottom: 3px solid #ff8c1a;
                padding-bottom: {nv["pane_pb"]}px;
            }}

            /* Barra de pestañas — azul medianoche, tabs planas.
               La tab activa tiene un azul más claro (más vivo). */
            QTabBar {{
                background: #1a2742;
                border: none;
            }}
            QTabBar::tab {{
                background: #1a2742;
                color: #a8b4cc;
                padding: {nv["tab_pv"]}px {nv["tab_ph"]}px;
                font-size: {nv["tab_fs"]}pt;
                font-weight: 500;
                border: none;
                min-width: {nv["tab_minw"]}px;
            }}
            QTabBar::tab:hover:!selected {{
                background: #243358;
                color: #e8edf4;
            }}
            QTabBar::tab:selected {{
                background: #3c5793;
                color: #e8edf4;
                font-weight: 700;
            }}

            /* ─── BOTONES DEL PANEL ──────────────────────────────────
               Estilo SUBMENÚ del ribbon: tan planos como las tabs
               (sin border), solo distinguidos por un tono ligeramente
               más claro que las tabs (#243358 vs #1a2742). Eso hace
               que se sienta que pertenecen al mismo bloque visual
               pero como un nivel inferior. Hover prende ámbar abajo. */

            /* Botón tile estándar (Nota, Etiquetar, Imagen, Buscar...) */
            QToolButton {{
                background: #243358;
                color: #e8ecf5;
                border: none;
                border-bottom: 2px solid transparent;
                padding: {nv["b_pv"]}px {nv["b_ph"]}px;
                min-width: {nv["b_minw"]}px;
                min-height: {nv["b_minh"]}px;
                font-size: {nv["b_fs"]}pt;
            }}
            QToolButton:hover {{
                background: #2c3e6a;
                color: #e8edf4;
                border-bottom: 2px solid #ff8c1a;
            }}
            QToolButton:pressed {{
                background: #ff8c1a;
                color: #0d1626;
                border-bottom: 2px solid #c46900;
            }}
            QToolButton:disabled {{
                background: #1f2a48;
                color: #6a7593;
            }}

            /* Botones toggle N / T — cuadraditos, mismo estilo plano */
            QToolButton[clase="toggle"] {{
                background: #243358;
                color: #e8ecf5;
                border: none;
                border-bottom: 2px solid transparent;
                padding: 4px;
                min-width: {nv["t_minw"]}px;
                max-width: 40px;
                min-height: {nv["b_minh"]}px;
                font-size: 12pt;
                font-weight: bold;
                font-family: "Georgia", serif;
            }}
            QToolButton[clase="toggle"]:hover {{
                background: #2c3e6a;
                color: #e8edf4;
                border-bottom: 2px solid #ff8c1a;
            }}
            QToolButton[clase="toggle"]:pressed {{
                background: #ff8c1a;
                color: #0d1626;
            }}

            /* Botón del tipo de elemento (selector de bloque).
               Solo un poco más grande que el resto, naranja saturado.
               Es el ÚNICO con borde para resaltar como protagonista. */
            QToolButton[clase="encabezado"] {{
                background: #ff8c1a;
                color: #241203;
                border: 1px solid #c46900;
                border-radius: 2px;
                padding: 4px {nv["enc_ph"]}px;
                min-height: {nv["enc_minh"]}px;
                font-size: {nv["b_fs"]}pt;
                font-weight: bold;
            }}
            QToolButton[clase="encabezado"]:hover {{
                background: #ffa040;
                border-color: #ff8c1a;
            }}
            QToolButton[clase="encabezado"]:pressed {{
                background: #e87a00;
            }}

            /* Botón VERDE — Terminé mi guion */
            QToolButton[clase="verde"] {{
                background: #e8760a;
                color: #e8edf4;
                border: 1px solid #1f7341;
                border-radius: 2px;
                padding: 5px {nv["v_ph"]}px;
                min-width: {nv["v_minw"]}px;
                min-height: {nv["b_minh"]}px;
                font-size: {nv["b_fs"]}pt;
                font-weight: bold;
            }}
            QToolButton[clase="verde"]:hover {{
                background: #36b46a;
                border-color: #e8760a;
            }}
            QToolButton[clase="verde"]:pressed {{ background: #1f7341; }}

            /* (compatibilidad con el atributo legacy 'especial=naranja') */
            QToolButton[especial="naranja"] {{
                background: #ff8c1a;
                color: #241203;
                font-weight: 700;
                min-width: {nv["nar_minw"]}px;
                border: 1px solid #ffb43a;
                border-radius: 2px;
            }}
            QToolButton[especial="naranja"]:hover {{
                background: #ffa040;
            }}

            /* Botones con menú partido (Buscar, Planificación…): la
               zona de la flechita integrada al botón, sin bloque gris. */
            QToolButton[popupMode="1"] {{
                padding-right: 18px;
            }}
            QToolButton::menu-button {{
                border: none;
                border-left: 1px solid #3c5793;
                background: transparent;
                width: 16px;
            }}
            QToolButton::menu-button:hover {{
                background: #2c3e6a;
                border-left: 1px solid #ff8c1a;
            }}
            QToolButton::menu-arrow {{
                width: 8px; height: 8px;
            }}

            /* Fila de botones desplazable: solo aparece la barrita si
               ni el nivel compacto cabe (ventana muy angosta). */
            QScrollArea#scrollRibbon {{
                background: #243358; border: none;
            }}
            QScrollArea#scrollRibbon > QWidget {{
                background: #243358;
            }}
            QScrollArea#scrollRibbon QScrollBar:horizontal {{
                height: 6px; background: #1f2a48; margin: 0; border: none;
            }}
            QScrollArea#scrollRibbon QScrollBar::handle:horizontal {{
                background: #4a6aa8; border-radius: 3px; min-width: 40px;
            }}
            QScrollArea#scrollRibbon QScrollBar::handle:horizontal:hover {{
                background: #ff8c1a;
            }}
            QScrollArea#scrollRibbon QScrollBar::add-line:horizontal,
            QScrollArea#scrollRibbon QScrollBar::sub-line:horizontal {{
                width: 0px; border: none;
            }}
        """
        if getattr(self, "_modo_mover", False):            # (✋ mover botones: se ven «sueltos»)
            qss += """
            QToolButton { border: 1px dashed #ffb066; }
            QToolButton:hover { background: #3a4f80; }
            """
        # Guardar la versión canónica (Nova) para que los cambios de
        # tema sigan funcionando aunque el nivel de densidad cambie
        # después (ver retematizar_widgets / TraductorTemas).
        aplicar_qss_tematizado(self, qss)

    def _boton(self, texto: str, habilitado: bool = False,
               on_click: Optional[Callable] = None,
               especial: Optional[str] = None,
               clase: Optional[str] = None,
               tooltip: str = "") -> QToolButton:
        """Crea un QToolButton estilo tile/chunky.
        clase ∈ {None, 'toggle', 'encabezado', 'verde'}."""
        btn = QToolButton()
        btn.setText(texto)
        btn.setToolButtonStyle(Qt.ToolButtonStyle.ToolButtonTextOnly)
        btn.setEnabled(habilitado)
        btn.setToolTip(
            tooltip or ("Próximamente" if not habilitado
                        else texto.replace("\n", " "))
        )
        if especial:
            btn.setProperty("especial", especial)
        if clase:
            btn.setProperty("clase", clase)
        if on_click and habilitado:
            btn.clicked.connect(on_click)
        return btn

    def _separador(self) -> QFrame:
        f = QFrame()
        f.setFrameShape(QFrame.Shape.VLine)
        # Línea vertical sutil sobre fondo azul submenú: usa un azul
        # más claro para que se vea sin gritar.
        f.setStyleSheet(
            f"color: #3c5793; max-width: 1px; "
            f"margin: 6px 4px;"
        )
        f.setFixedWidth(2)
        self._separadores.append(f)
        return f

    def _ensamblar_tab(self, grupos: list[list[QWidget]]) -> list:
        """Registra los botones de una pestaña (cada uno con su id) y
        devuelve sus grupos como listas de ids: la disposición original."""
        tab = _slug_ribbon(self._rb_tab_actual) or "pestana"
        ids = []
        for grupo in grupos:
            g_ids = []
            for widget in grupo:
                texto = widget.text() if hasattr(widget, "text") else ""
                base = _slug_ribbon(texto) or _slug_ribbon((widget.toolTip() or "").split(":")[0]) or "boton"
                rid = f"{tab}.{base}"
                n = 2
                while rid in self._rb_widgets:
                    rid = f"{tab}.{base}_{n}"
                    n += 1
                widget.setProperty("rb_id", rid)
                widget.installEventFilter(self)
                self._rb_widgets[rid] = widget
                nombre = " ".join(str(texto).replace("▾", "").split()) or (widget.toolTip() or "").split(":")[0]
                if nombre.strip() in ("⚙",):
                    nombre = "⚙ Configuración"
                self._rb_nombres[rid] = nombre
                g_ids.append(rid)
            if g_ids:
                ids.append(g_ids)
        return ids

    def _armar_panel(self, grupos: list[list[QWidget]]) -> QWidget:
        w = _PanelRibbon(self)
        w.grupos = [list(g) for g in grupos]
        # Fondo del panel: azul submenú que cubre todo el ancho del
        # ribbon (no solo lo que ocupan los botones), para que no
        # se vea un "corte" blanco a la derecha cuando addStretch()
        # deja espacio sobrante. El objectName aísla el selector para
        # no afectar widgets internos.
        w.setObjectName("panelRibbon")
        w.setStyleSheet(
            "QWidget#panelRibbon { background: #243358; }"
        )
        layout = QHBoxLayout(w)
        nv = self.NIVELES[self._nivel]
        layout.setContentsMargins(px(nv["marg_h"]), px(nv["marg_v"]),
                                  px(nv["marg_h"]), px(nv["marg_v"]))
        layout.setSpacing(px(nv["espacio"]))
        for i, grupo in enumerate(grupos):
            for widget in grupo:
                # Ancho = el que pide su texto: el layout nunca lo
                # recorta (antes quedaba «De...ar», «Gu...como»).
                if isinstance(widget, (QToolButton, QPushButton)):
                    widget.setSizePolicy(
                        QSizePolicy.Policy.Fixed,
                        widget.sizePolicy().verticalPolicy())
                layout.addWidget(widget)
                widget.show()
            if i < len(grupos) - 1:
                layout.addWidget(self._separador())
        if not grupos:
            vacio = QLabel("Categoría vacía. Mantén apretado un botón de otra pestaña medio segundo, llévalo hasta "
                           "el nombre de esta pestaña y suéltalo aquí. O usa 🧩 Personalizar ribbon (en Estilo).")
            vacio.setObjectName("vacioRibbon")
            vacio.setStyleSheet("QLabel#vacioRibbon { color: #b8c7dc; font-style: italic; background: transparent; }")
            vacio.setWordWrap(True)
            layout.addWidget(vacio, 1)
        layout.addStretch()
        self._paneles.append(w)
        self._layouts_panel.append(layout)
        # Contenedor desplazable: si ni el nivel compacto cabe, se
        # puede deslizar la fila (rueda del mouse o barrita) en vez
        # de recortar botones.
        scroll = QScrollArea()
        scroll.setObjectName("scrollRibbon")
        scroll.setWidget(w)
        scroll.setWidgetResizable(True)
        scroll.setFrameShape(QFrame.Shape.NoFrame)
        scroll.setHorizontalScrollBarPolicy(
            Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        scroll.setVerticalScrollBarPolicy(
            Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        scroll.viewport().installEventFilter(self)
        return scroll

    def eventFilter(self, obj, ev) -> bool:
        # ✋ Modo «mover botones»: el clic no aprieta el botón, lo arrastra
        if self._modo_mover and isinstance(obj, QWidget) and obj.property("rb_id"):
            t = ev.type()
            if t == QEvent.Type.MouseButtonPress and ev.button() == Qt.MouseButton.LeftButton:
                self._arrastre = {"id": obj.property("rb_id"), "pos": ev.position().toPoint(), "w": obj}
                return True
            if t == QEvent.Type.MouseMove and self._arrastre and self._arrastre["w"] is obj:
                if (ev.position().toPoint() - self._arrastre["pos"]).manhattanLength() >= \
                        QApplication.startDragDistance():
                    self._arrastrar(obj)
                return True
            if t in (QEvent.Type.MouseButtonRelease, QEvent.Type.MouseButtonDblClick, QEvent.Type.ContextMenu):
                self._arrastre = None
                return True
        # ✋ Mantener apretado un botón (algo más de medio segundo) lo levanta para moverlo
        if isinstance(obj, QWidget) and obj.property("rb_id"):
            t = ev.type()
            if t == QEvent.Type.MouseButtonPress and ev.button() == Qt.MouseButton.LeftButton:
                instantaneo = (isinstance(obj, QToolButton) and obj.menu() is not None
                               and obj.popupMode() == QToolButton.ToolButtonPopupMode.InstantPopup)
                self._presion = {"w": obj, "pos": ev.globalPosition().toPoint(), "instantaneo": instantaneo}
                self._t_presion.start()
                return instantaneo                 # (un botón con menú: el menú se abre al soltar)
            if t == QEvent.Type.MouseMove and self._presion and self._presion["w"] is obj:
                if (ev.globalPosition().toPoint() - self._presion["pos"]).manhattanLength() > px(14):
                    self._t_presion.stop()          # (se movió: no era «mantener apretado»)
                    self._presion = None
                return False
            if t == QEvent.Type.MouseButtonRelease and self._presion and self._presion["w"] is obj:
                pendiente = self._t_presion.isActive()
                self._t_presion.stop()
                p_, self._presion = self._presion, None
                if pendiente and p_["instantaneo"]:
                    QTimer.singleShot(0, obj.showMenu)
                    return True
                return False
        # Rueda vertical sobre la fila de botones → desplaza en
        # horizontal (solo tiene efecto si la fila no cabe).
        if ev.type() == QEvent.Type.Wheel:
            area = obj.parent()
            if isinstance(area, QScrollArea):
                barra = area.horizontalScrollBar()
                if barra.maximum() > 0:
                    delta = ev.angleDelta().y() or ev.angleDelta().x()
                    barra.setValue(barra.value() - delta // 2)
                    return True
        return super().eventFilter(obj, ev)

    # ── 🧩 Ribbon personalizable: disposición, configuraciones, mover ──

    @staticmethod
    def _leer_json_ajuste(clave: str):
        try:
            v = settings_app().value(clave, "")
            return json.loads(v) if v else None
        except (ValueError, TypeError):
            return None

    def disposicion_original(self) -> dict:
        """La de ¡Acción! (como viene de fábrica)."""
        return {"pestanas": [{"nombre": t["nombre"], "grupos": [list(g) for g in t["grupos"]]}
                             for t in self._rb_original],
                "conocidos": list(self._rb_widgets)}

    def disposicion_actual(self) -> dict:
        pestanas = []
        for i in range(self.count()):
            area = self.widget(i)
            pan = area.widget() if isinstance(area, QScrollArea) else area
            grupos = [[w.property("rb_id") for w in g] for g in getattr(pan, "grupos", [])]
            pestanas.append({"nombre": self.tabText(i), "grupos": [g for g in grupos if g]})
        return {"pestanas": pestanas, "conocidos": list(self._rb_widgets)}

    def normalizar_disposicion(self, disp: dict) -> dict:
        """Quita ids que ya no existen y agrega los botones nuevos de esta
        versión (los que la disposición guardada no conocía) donde van de
        fábrica. Un botón que la persona sacó del ribbon queda fuera."""
        pestanas = []
        usados = set()
        for t in (disp or {}).get("pestanas") or []:
            nombre = str(t.get("nombre", "")).strip() or "Pestaña"
            grupos = []
            for g in t.get("grupos") or []:
                g2 = [i for i in g if i in self._rb_widgets and i not in usados]
                usados.update(g2)
                if g2:
                    grupos.append(g2)
            pestanas.append({"nombre": nombre, "grupos": grupos})
        if not pestanas:
            return self.disposicion_original()
        conocidos = set((disp or {}).get("conocidos") or [])
        for t0 in self._rb_original:
            for gi, g in enumerate(t0["grupos"]):
                for rid in g:
                    if rid in usados or rid in conocidos:
                        continue
                    destino = next((t for t in pestanas if t["nombre"] == t0["nombre"]), None)
                    if destino is None:
                        destino = {"nombre": t0["nombre"], "grupos": []}
                        pestanas.append(destino)
                    if gi < len(destino["grupos"]):
                        destino["grupos"][gi].append(rid)
                    else:
                        destino["grupos"].append([rid])
                    usados.add(rid)
        return {"pestanas": pestanas, "conocidos": list(self._rb_widgets)}

    def aplicar_disposicion(self, disp: dict, guardar: bool = True) -> None:
        """Arma las pestañas con la disposición dada (los mismos botones,
        en otro lugar)."""
        disp = self.normalizar_disposicion(disp)
        anterior = self.tabText(self.currentIndex()) if self.currentIndex() >= 0 else ""
        for w in self._rb_widgets.values():
            w.setParent(self._rb_guardados)
        while self.count():
            area = self.widget(0)
            self.removeTab(0)
            area.deleteLater()
        self._paneles.clear()
        self._layouts_panel.clear()
        self._separadores.clear()
        for t in disp["pestanas"]:
            grupos_w = [[self._rb_widgets[i] for i in g] for g in t["grupos"]]
            self.addTab(self._armar_panel(grupos_w), t["nombre"])
        for i in range(self.count()):
            if self.tabText(i) == anterior:
                self.setCurrentIndex(i)
                break
        self._anchos_nivel.clear()
        if getattr(self, "_timer_nivel", None) is not None:     # (al construir, todavía no)
            self._aplicar_nivel(self._nivel)
            self._timer_nivel.start()
        if guardar:
            settings_app().setValue(CLAVE_RIBBON_ACTUAL, json.dumps(disp, ensure_ascii=False))

    def configuraciones(self) -> dict:
        d = self._leer_json_ajuste(CLAVE_RIBBON_CONFIGS)
        return d if isinstance(d, dict) else {}

    def guardar_configuracion(self, nombre: str, disp: Optional[dict] = None) -> None:
        cfg = self.configuraciones()
        cfg[nombre] = self.normalizar_disposicion(disp or self.disposicion_actual())
        settings_app().setValue(CLAVE_RIBBON_CONFIGS, json.dumps(cfg, ensure_ascii=False))

    def cargar_configuracion(self, nombre: str) -> bool:
        cfg = self.configuraciones()
        if nombre not in cfg:
            return False
        self.aplicar_disposicion(cfg[nombre])
        return True

    def borrar_configuracion(self, nombre: str) -> None:
        cfg = self.configuraciones()
        cfg.pop(nombre, None)
        settings_app().setValue(CLAVE_RIBBON_CONFIGS, json.dumps(cfg, ensure_ascii=False))

    def restaurar_original(self) -> None:
        self.aplicar_disposicion(self.disposicion_original())

    def indice_de_panel(self, panel) -> int:
        for i in range(self.count()):
            area = self.widget(i)
            if (area.widget() if isinstance(area, QScrollArea) else area) is panel:
                return i
        return -1

    def mover_boton(self, rid: str, pestana: int, grupo: Optional[int], pos: Optional[int]) -> None:
        """Lleva un botón a otra pestaña/grupo/posición (grupo None: al
        final de la pestaña; grupo = cantidad de grupos: un grupo nuevo)."""
        if rid not in self._rb_widgets or not (0 <= pestana < self.count()):
            return
        disp = self.disposicion_actual()
        origen = None
        for ti, t in enumerate(disp["pestanas"]):
            for gi, g in enumerate(t["grupos"]):
                if rid in g:
                    origen = (ti, gi, g.index(rid))
        destino = disp["pestanas"][pestana]["grupos"]
        if grupo is None:
            grupo, pos = (max(0, len(destino) - 1), None) if destino else (0, 0)
        if origen is not None:
            ti, gi, k = origen
            if ti == pestana and gi == grupo and pos is not None and k < pos:
                pos -= 1                                  # (se saca antes de volver a ponerlo)
            disp["pestanas"][ti]["grupos"][gi].remove(rid)
        if grupo >= len(destino):
            destino.append([rid])
        else:
            g = destino[grupo]
            g.insert(len(g) if pos is None else max(0, min(pos, len(g))), rid)
        for t in disp["pestanas"]:
            t["grupos"] = [g for g in t["grupos"] if g]
        self.aplicar_disposicion(disp)
        self.setCurrentIndex(pestana)

    def _presion_larga(self) -> None:
        """Se mantuvo apretado un botón: se levanta y se arrastra. Soltado
        fuera del ribbon, queda donde estaba."""
        p_, self._presion = self._presion, None
        if not p_ or QApplication.activePopupWidget() is not None:
            return
        if not (QApplication.mouseButtons() & Qt.MouseButton.LeftButton):
            return
        w = p_["w"]
        try:
            if hasattr(w, "setDown") and not p_["instantaneo"] and w.isDown():
                # (se suelta el botón lejos de él: no hace clic)
                fuera = QPointF(-50, -50)
                QApplication.sendEvent(w, QMouseEvent(QEvent.Type.MouseButtonRelease, fuera,
                                                      QPointF(w.mapToGlobal(QPoint(-50, -50))),
                                                      Qt.MouseButton.LeftButton, Qt.MouseButton.NoButton,
                                                      Qt.KeyboardModifier.NoModifier))
                w.setDown(False)
        except RuntimeError:
            return
        self._arrastrar(w)

    def _arrastrar(self, boton: QWidget) -> None:
        rid = boton.property("rb_id")
        self._arrastre = None
        md = QMimeData()
        md.setData(MIME_BOTON_RIBBON, QByteArray(str(rid).encode("utf-8")))
        drag = QDrag(boton)
        drag.setMimeData(md)
        try:
            drag.setPixmap(boton.grab())
            drag.setHotSpot(boton.mapFromGlobal(QCursor.pos()))
        except Exception:
            pass
        self._atenuar([boton], True)               # (mientras se mueve, su lugar queda tenue)
        try:
            drag.exec(Qt.DropAction.MoveAction)
        finally:
            self._atenuar([boton], False)

    @staticmethod
    def _atenuar(widgets: list, si: bool) -> None:
        from PySide6.QtWidgets import QGraphicsOpacityEffect
        for w in widgets:
            try:
                if si:
                    ef = QGraphicsOpacityEffect(w)
                    ef.setOpacity(0.3)
                    w.setGraphicsEffect(ef)
                else:
                    w.setGraphicsEffect(None)
            except RuntimeError:
                pass

    def arrastrar_grupo(self, panel, gi: int) -> None:
        """Arrastra un grupo entero (lo que está entre dos líneas separadoras)."""
        ws = list(panel.grupos[gi])
        ids = [str(w.property("rb_id")) for w in ws]
        md = QMimeData()
        md.setData(MIME_GRUPO_RIBBON, QByteArray(",".join(ids).encode("utf-8")))
        drag = QDrag(panel)
        drag.setMimeData(md)
        try:
            izq = max(0, ws[0].geometry().left() - px(4))
            der = min(panel.width(), ws[-1].geometry().right() + px(4))
            pix = panel.grab(QRect(izq, 0, der - izq, panel.height()))
            drag.setPixmap(pix)
            drag.setHotSpot(panel.mapFromGlobal(QCursor.pos()) - QPoint(izq, 0))
        except Exception:
            pass
        self._atenuar(ws, True)
        try:
            drag.exec(Qt.DropAction.MoveAction)
        finally:
            self._atenuar(ws, False)

    def mover_grupo(self, ids: list, pestana: int, pos: Optional[int]) -> None:
        """Lleva un grupo entero a otra posición (pos = entre qué grupos; None:
        al final de la pestaña)."""
        ids = [i for i in ids if i in self._rb_widgets]
        if not ids or not (0 <= pestana < self.count()):
            return
        disp = self.disposicion_actual()
        destino = disp["pestanas"][pestana]["grupos"]
        if pos is None:
            pos = len(destino)
        origen = next(((ti, gi) for ti, t in enumerate(disp["pestanas"]) for gi, g in enumerate(t["grupos"])
                       if g == ids), None)
        if origen is not None:
            ti, gi = origen
            if ti == pestana and pos in (gi, gi + 1):
                return                                    # (en su mismo lugar)
            disp["pestanas"][ti]["grupos"].pop(gi)
            if ti == pestana and gi < pos:
                pos -= 1
        else:
            for t in disp["pestanas"]:
                t["grupos"] = [[i for i in g if i not in ids] for g in t["grupos"]]
        destino.insert(max(0, min(pos, len(destino))), list(ids))
        for t in disp["pestanas"]:
            t["grupos"] = [g for g in t["grupos"] if g]
        self.aplicar_disposicion(disp)
        self.setCurrentIndex(pestana)

    def modo_mover(self) -> bool:
        return self._modo_mover

    def poner_modo_mover(self, si: bool) -> None:
        """✋ Arrastrar los botones directo en el ribbon (a otro lugar, a otro
        grupo o, pasando por arriba de una pestaña, a otra pestaña)."""
        self._modo_mover = bool(si)
        self._arrastre = None
        if si and getattr(self, "_aviso_mover", None) is None:
            av = QFrame(self)
            av.setObjectName("avisoMover")
            av.setStyleSheet("QFrame#avisoMover { background: #ff8c1a; border-radius: 6px; }"
                             "QLabel { color: #241203; font-weight: 700; }"
                             "QPushButton { background: #241203; color: #ffffff; border-radius: 4px; "
                             "padding: 3px 10px; font-weight: 700; }")
            h = QHBoxLayout(av)
            h.setContentsMargins(px(10), px(3), px(4), px(3))
            lbl_av = QLabel("✋ Arrastra un botón, o un grupo desde su borde punteado")
            lbl_av.setToolTip("Suéltalo en otro lugar, o sobre el nombre de otra pestaña para llevarlo allá. "
                              "Fuera del ribbon, vuelve a su lugar.")
            h.addWidget(lbl_av)
            b = QPushButton("✓ Listo")
            b.clicked.connect(lambda: self.poner_modo_mover(False))
            h.addWidget(b)
            self._aviso_mover = av
            self._atajo_mover = QShortcut(QKeySequence("Esc"), self.window())
            self._atajo_mover.activated.connect(lambda: self.poner_modo_mover(False))
        av = getattr(self, "_aviso_mover", None)
        if av is not None:
            av.setVisible(self._modo_mover)
            self._atajo_mover.setEnabled(self._modo_mover)
            self._colocar_aviso_mover()
        self._aplicar_estilo(self._nivel)
        for pan in getattr(self, "_paneles", []):
            try:
                pan.update()
            except RuntimeError:
                pass

    def _colocar_aviso_mover(self) -> None:
        av = getattr(self, "_aviso_mover", None)
        if av is None or not av.isVisible():
            return
        av.adjustSize()
        alto_tabs = self.tabBar().height()
        av.move(max(0, self.width() - av.width() - px(8)), max(0, (alto_tabs - av.height()) // 2))
        av.raise_()

    def menu_personalizar(self, indice: Optional[int] = None) -> QMenu:
        """El menú del clic derecho sobre las pestañas (y del botón
        «📂 Configuraciones»). Sobre una pestaña: también cambiarle el
        nombre o quitarla."""
        menu = QMenu(self)
        menu.setStyleSheet(self._menu_style())
        menu.addAction("➕  Nueva categoría…", lambda: self.nueva_categoria())
        if indice is not None and 0 <= indice < self.count():
            nom = self.tabText(indice).strip()
            menu.addAction(f"✎  Cambiar el nombre de «{nom}»…", lambda i=indice: self.renombrar_categoria(i))
            a = menu.addAction(f"🗑  Quitar la categoría «{nom}»", lambda i=indice: self.quitar_categoria(i))
            a.setEnabled(self.count() > 1)
        menu.addSeparator()
        menu.addAction("🧩  Personalizar el ribbon…", self.abrir_personalizar)
        a = menu.addAction("✋  Mover botones arrastrando")
        a.setCheckable(True)
        a.setChecked(self._modo_mover)
        a.triggered.connect(self.poner_modo_mover)
        menu.addAction("💾  Guardar esta configuración…", self.guardar_configuracion_con_nombre)
        cfg = self.configuraciones()
        if cfg:
            menu.addSeparator()
            for nombre in sorted(cfg, key=str.lower):
                menu.addAction(f"📂  {nombre}", lambda n=nombre: self.cargar_configuracion(n))
        menu.addSeparator()
        menu.addAction("↺  Volver al ribbon original de ¡Acción!", self.restaurar_original)
        return menu

    # ── ➕ categorías (pestañas) propias ──
    def _nombre_libre(self, nombre: str, salvo: Optional[int] = None) -> str:
        usados = {_norm_voz(self.tabText(i).strip()) for i in range(self.count()) if i != salvo}
        base, k = nombre, 2
        while _norm_voz(nombre) in usados:
            nombre = f"{base} {k}"
            k += 1
        return nombre

    def nueva_categoria(self, ids: Optional[list] = None, nombre: Optional[str] = None) -> int:
        """➕ Una categoría (pestaña) nueva al final del ribbon; con «ids», ya
        con esos botones (los que se soltaron sobre el «+»). Devuelve su
        posición, o -1 si se canceló."""
        if nombre is None:
            nombre, ok = QInputDialog.getText(self.window(), "Nueva categoría",
                                              "Nombre de la categoría (por ejemplo «Mis botones», «Rodaje», "
                                              "«Clase»):")
            if not ok:
                return -1
        nombre = " ".join(str(nombre or "").split())
        if not nombre:
            return -1
        nombre = self._nombre_libre(nombre)
        ids = [i for i in (ids or []) if i in self._rb_widgets]
        disp = self.disposicion_actual()
        if ids:
            for t in disp["pestanas"]:
                t["grupos"] = [[x for x in g if x not in ids] for g in t["grupos"]]
                t["grupos"] = [g for g in t["grupos"] if g]
        disp["pestanas"].append({"nombre": nombre, "grupos": [ids] if ids else []})
        self.aplicar_disposicion(disp)
        i = self.count() - 1
        self.setCurrentIndex(i)
        try:
            self.window().statusBar().showMessage(
                f"➕ Categoría «{nombre}» creada" + ("." if ids else ": mantén apretado un botón de otra pestaña, "
                                                     "llévalo hasta «" + nombre + "» y suéltalo."), 7000)
        except Exception:
            pass
        return i

    def renombrar_categoria(self, i: int, nombre: Optional[str] = None) -> bool:
        if not (0 <= i < self.count()):
            return False
        if nombre is None:
            nombre, ok = QInputDialog.getText(self.window(), "Cambiar el nombre", "Nuevo nombre de la categoría:",
                                              text=self.tabText(i).strip())
            if not ok:
                return False
        nombre = " ".join(str(nombre or "").split())
        if not nombre:
            return False
        disp = self.disposicion_actual()
        disp["pestanas"][i]["nombre"] = self._nombre_libre(nombre, salvo=i)
        self.aplicar_disposicion(disp)
        self.setCurrentIndex(i)
        return True

    def quitar_categoria(self, i: int, preguntar: bool = True) -> bool:
        """Quita una pestaña. Sus botones no se pierden: quedan en «No están
        en el ribbon» (🧩 Personalizar ribbon) para volver a ponerlos."""
        if not (0 <= i < self.count()) or self.count() <= 1:
            return False
        disp = self.disposicion_actual()
        t = disp["pestanas"][i]
        n = sum(len(g) for g in t["grupos"])
        if n and preguntar:
            r = QMessageBox.question(
                self.window(), "Quitar la categoría",
                f"La categoría «{t['nombre']}» tiene {n} botón{'es' if n != 1 else ''}. ¿Quitarla?\n\n"
                "Sus botones no se pierden: quedan en 🧩 Personalizar ribbon → «No están en el ribbon», para "
                "volver a ponerlos donde quieras.")
            if r != QMessageBox.StandardButton.Yes:
                return False
        actual = self.currentIndex()
        disp["pestanas"].pop(i)
        self.aplicar_disposicion(disp)
        self.setCurrentIndex(max(0, min(actual if actual < i else actual - 1, self.count() - 1)))
        return True

    def guardar_configuracion_con_nombre(self) -> str:
        nombre, ok = QInputDialog.getText(self.window(), "Guardar configuración del ribbon",
                                          "Nombre (por ejemplo «Escribir», «Rodaje», «Clase»):")
        nombre = str(nombre or "").strip()
        if not ok or not nombre:
            return ""
        self.guardar_configuracion(nombre)
        try:
            self.window().statusBar().showMessage(f"💾 Configuración del ribbon guardada: {nombre}", 4000)
        except Exception:
            pass
        return nombre

    def abrir_personalizar(self) -> None:
        DialogoPersonalizarRibbon(self, parent=self.window()).exec()

    def _menu_elementos(self) -> QMenu:
        menu = QMenu(self)
        menu.setStyleSheet(f"""
            QMenu {{
                background: #1a2636;
                color: #e8edf4;
                border: 1px solid #1a2742;
                padding: 4px;
                font-size: 10pt;
                font-weight: bold;
            }}
            QMenu::item {{
                background: transparent;
                color: #e8edf4;
                padding: 7px 20px 7px 12px;
                min-width: 160px;
                font-weight: bold;
            }}
            QMenu::item:selected {{
                background: #ff8c1a;
                color: #241203;
            }}
        """)
        for num, elem in ATAJO_NUMERO.items():
            act = menu.addAction(f"  {num}.  {NOMBRE[elem]}")
            act.triggered.connect(
                lambda _, e=elem: self.elemento_solicitado.emit(e)
            )
        return menu

    def _construir_pestanas(self) -> None:
        fabricas = [("Inicio", self._pestaña_inicio), ("IA", self._pestaña_ia),
                    ("Archivo", self._pestaña_archivo), ("Formato", self._pestaña_formato),
                    ("Escaleta", self._pestaña_escaleta), ("Estilo", self._pestaña_estilo),
                    ("Seguridad", self._pestaña_seguridad), ("Colaboración", self._pestaña_colaboracion),
                    ("Producción", self._pestaña_produccion), ("Informes", self._pestaña_informes),
                    ("Tutorial", self._pestaña_tutorial)]
        for nombre, fabrica in fabricas:
            self._rb_tab_actual = nombre
            self._rb_original.append({"nombre": nombre, "grupos": fabrica()})
        self._rb_tab_actual = ""
        guardada = self._leer_json_ajuste(CLAVE_RIBBON_ACTUAL)
        self.aplicar_disposicion(guardada if isinstance(guardada, dict) else self.disposicion_original(),
                                 guardar=False)
        # LOGO grande a la izquierda del ribbon (corner widget).
        # Es el protagonista visual, no un detalle pequeño.
        logo_label = LogoInicio()
        logo_label.presionado.connect(self.inicio_solicitado.emit)
        logo_label.setPixmap(cargar_logo_pixmap(alto_px=px(40)))
        logo_label.setStyleSheet(
            f"background: #1a2742; padding: 0 12px;")
        logo_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.setCornerWidget(logo_label, Qt.Corner.TopLeftCorner)
        self._logo_label = logo_label

    def _pestaña_inicio(self) -> QWidget:
        # ── Botón NARANJO del tipo de elemento ──
        # Texto dinámico: muestra el tipo del bloque actual. Click → menú.
        # La ventana principal actualiza el texto al cambiar el tipo.
        btn_encabezado = self._boton(
            "🎬 ACCIÓN ▾",
            habilitado=True, clase="encabezado",
            tooltip="Cambiar tipo de elemento del bloque actual "
                    "(TAB también lo cicla, Ctrl+1-9 directo)",
        )
        btn_encabezado.setPopupMode(QToolButton.ToolButtonPopupMode.InstantPopup)
        btn_encabezado.setMenu(self._menu_elementos())
        self._btn_encabezado = btn_encabezado  # expuesto para que la
        # ventana principal lo mute según el elemento actual.

        # ── Botón VERDE: cerrar el guion ──
        btn_terminar = self._boton(
            "✓ Terminé mi guion", habilitado=True, clase="verde",
            on_click=self.archivo_terminar.emit,
            tooltip="Resumen y celebración del guion terminado",
        )

        # ── Botones toggle N / T (negrita / subrayado) ──
        btn_n = self._boton("N", habilitado=True, clase="toggle",
                            on_click=self.cmd_negrita.emit,
                            tooltip="Negrita (Ctrl+B)")
        btn_t = self._boton("T̲", habilitado=True, clase="toggle",
                            on_click=self.cmd_subrayado.emit,
                            tooltip="Subrayado (Ctrl+U)")

        # ── Botón Destacar con menú de colores ──
        btn_destacar = self._boton(
            "🟡 Destacar ▾", habilitado=True,
            tooltip="Resaltar selección con color",
        )
        btn_destacar.setPopupMode(QToolButton.ToolButtonPopupMode.InstantPopup)
        btn_destacar.setMenu(self._menu_destacar())

        # ── Botón Color de texto con menú de colores ──
        btn_color_texto = self._boton(
            "🎨 Color texto ▾", habilitado=True,
            tooltip="Cambiar el color del texto seleccionado",
        )
        btn_color_texto.setPopupMode(QToolButton.ToolButtonPopupMode.InstantPopup)
        btn_color_texto.setMenu(self._menu_color_texto())

        # ── Botón Guía ──
        btn_guia = self._boton(
            "📖 Guía", habilitado=True,
            on_click=self.guia_solicitada.emit,
            tooltip="Ayuda y guía de uso del programa",
        )

        # ── Botón Configuración ──
        # Antes estaba en la esquina superior derecha, pero tapaba
        # otros botones. Ahora vive en la pestaña Inicio con el
        # resto de las herramientas.
        btn_config = self._boton(
            "⚙", habilitado=True,
            on_click=self.configuracion_solicitada.emit,
            tooltip="Configuración: tema, formato, país/moneda, "
                     "corrector, PIN, backup, clima, colaboración",
        )
        # ⚙ y Guía compactos: liberan espacio horizontal para que
        # «Terminé mi guion» respire y no se corte.
        for _b in (btn_config, btn_guia):
            _b.setStyleSheet(
                f"QToolButton {{ padding: 6px 7px; }}")

        return self._ensamblar_tab([
            # Grupo 1: estilo de texto
            [btn_n, btn_t],
            # Grupo 2: destacar + color de texto
            [btn_destacar, btn_color_texto],
            # Grupo 3: EL BOTÓN GIGANTE
            [btn_encabezado],
            # Grupo 4: utilidades del bloque
            [self._boton("📝 Nota", habilitado=True,
                         on_click=self.cmd_nota.emit,
                         tooltip="Agregar nota al bloque actual"),
             self._boton("🏷 Etiquetar", habilitado=True,
                         on_click=self.cmd_etiquetar.emit,
                         tooltip="Etiquetar el bloque actual"),
             self._btn_copiar_pegar(),
             self._btn_buscar_desplegable()],
            # Grupo 4.5: herramientas de escritura
            [self._boton("⏱ Timer", habilitado=True,
                         on_click=self.cmd_timer_escritura.emit,
                         tooltip="Sesión de escritura con tiempo "
                                 "definido (5-90 min o custom)"),
             self._boton("🔊 Voz alta", habilitado=True,
                         on_click=self.cmd_leer_voz_alta.emit,
                         tooltip="Lee el guion en voz alta. Cada "
                                 "personaje habla con la voz de su "
                                 "ficha; las acciones, con la del "
                                 "narrador."),
             self._btn_modo_visual(),
             ],
            # Grupo 5: configuración + ayuda + terminar
            [btn_config, btn_guia, btn_terminar],
        ])

    def _menu_destacar(self) -> QMenu:
        """Menú con la paleta de colores + opción quitar."""
        menu = QMenu(self)
        menu.setStyleSheet(estilo_menu_claro(min_width=160))
        for nombre, color_hex in COLORES_DESTACADO:
            act = menu.addAction(self._icono_color(color_hex), f"  {nombre}")
            act.triggered.connect(
                lambda _, c=color_hex: self.cmd_destacar_color.emit(c)
            )
        menu.addSeparator()
        act_quitar = menu.addAction("✕  Quitar destacado")
        act_quitar.triggered.connect(self.cmd_destacar_quitar.emit)
        return menu

    def _menu_color_texto(self) -> QMenu:
        """Menú con la paleta de colores del texto + opción quitar."""
        menu = QMenu(self)
        menu.setStyleSheet(estilo_menu_claro(min_width=160))
        for nombre, color_hex in COLORES_TEXTO:
            act = menu.addAction(self._icono_color(color_hex), f"  {nombre}")
            act.triggered.connect(
                lambda _, c=color_hex: self.cmd_color_texto.emit(c)
            )
        menu.addSeparator()
        act_quitar = menu.addAction("✕  Volver a negro")
        act_quitar.triggered.connect(self.cmd_color_texto_quitar.emit)
        return menu

    def _icono_color(self, color_hex: str) -> QIcon:
        """Crea un cuadrito de color con borde para el menú."""
        pix = QPixmap(16, 16)
        pix.fill(Qt.GlobalColor.transparent)
        p = QPainter(pix)
        p.fillRect(1, 1, 14, 14, QColor(color_hex))
        p.setPen(QColor("#888"))
        p.drawRect(0, 0, 15, 15)
        p.end()
        return QIcon(pix)

    def _btn_copiar_pegar(self) -> QToolButton:
        """📋 Copiar y pegar en un solo botón: un menú chico que recuerda
        que lo más rápido es Ctrl+C y Ctrl+V."""
        btn = self._boton("📋 Copiar / Pegar ▾", habilitado=True,
                          tooltip="Copiar y pegar. Lo más rápido: Ctrl+C copia y Ctrl+V pega")
        menu = QMenu(btn)
        menu.setStyleSheet(self._menu_style() + """
            QMenu::item:disabled { color: #ffb066; background: transparent; }""")
        nota = menu.addAction("⌨  Más rápido:  Ctrl+C  copia  ·  Ctrl+V  pega")
        nota.setEnabled(False)
        menu.addSeparator()
        a = menu.addAction("📋  Copiar")
        a.setShortcut(QKeySequence("Ctrl+C"))
        a.setShortcutContext(Qt.ShortcutContext.WidgetShortcut)   # (solo se muestra: el atajo es el del editor)
        a.triggered.connect(self.copiar_bloque_solicitado.emit)
        b = menu.addAction("📄  Pegar")
        b.setShortcut(QKeySequence("Ctrl+V"))
        b.setShortcutContext(Qt.ShortcutContext.WidgetShortcut)
        b.triggered.connect(self.pegar_bloque_solicitado.emit)
        btn.setMenu(menu)
        btn.setPopupMode(QToolButton.ToolButtonPopupMode.InstantPopup)
        return btn

    def _btn_modo_visual(self) -> QToolButton:
        """♿ Modo discapacidad visual (en Inicio y en la pestaña IA)."""
        btn = self._boton("♿ Discapacidad visual", habilitado=True,
                          on_click=self.cmd_modo_visual.emit,
                          tooltip="Todo el programa por voz (menos el storyboard y las fotos): "
                                  "F2 y dices qué hacer — escribir, revisar, abrir fichas, tags, "
                                  "escaleta, informes leídos en voz alta, guardar, exportar, imprimir. "
                                  "Se activa y desactiva también con Ctrl+F2 o diciendo «activa el modo "
                                  "discapacidad visual»")
        btn.setCheckable(True)
        btn.setAccessibleName("Modo discapacidad visual (Ctrl+F2)")
        btn.setProperty("modo_visual", True)
        return btn

    def marcar_modo_visual(self, si: bool) -> None:
        for w in self._rb_widgets.values():
            if w.property("modo_visual"):
                w.blockSignals(True)
                w.setChecked(bool(si))
                w.blockSignals(False)

    def _pestaña_ia(self) -> QWidget:
        """✨ Todo lo de la IA, en su propia pestaña (destacada)."""
        def ia(clave):
            return lambda: self.cmd_ia.emit(clave)
        btn_prof = self._boton("🤖 Prof. Claqueta", habilitado=True, clase="encabezado",
                               on_click=self.cmd_asesor.emit,
                               tooltip="Conversa con el Profesor Claqueta: una IA que vive en tu "
                                       "computador (con Ollama). Tu guion no sale del computador.")
        btn_pers = self._boton("🧍 Personaje ▾", habilitado=True,
                               tooltip="Consejos sobre un personaje (elige cuál)")
        menu_p = QMenu(btn_pers)
        menu_p.setStyleSheet(self._menu_style())

        def llenar_personajes():
            menu_p.clear()
            vp = self.window()
            nombres = []
            try:
                doc = vp.editor.documento
                nombres = list((doc.fichas or {}).keys())
                for b in doc.bloques:
                    k = (b.texto or "").strip().upper().split("(")[0].strip()
                    if b.elem == Elem.PERSONAJE and k and k not in nombres:
                        nombres.append(k)
            except Exception:
                pass
            if not nombres:
                a_ = menu_p.addAction("(todavía no hay personajes)")
                a_.setEnabled(False)
            for n in nombres[:40]:
                menu_p.addAction(f"🧍  {n}", lambda n=n: self.cmd_ia.emit("personaje:" + n))
        menu_p.aboutToShow.connect(llenar_personajes)
        btn_pers.setMenu(menu_p)
        btn_pers.setPopupMode(QToolButton.ToolButtonPopupMode.InstantPopup)

        btn_escr = self._boton("✍ Escribir con IA ▾", habilitado=True,
                               tooltip="Que la IA escriba: en este guion (le dices qué y, según lo que "
                                       "elijas, lo escribe directo o te pregunta antes) o un guion nuevo")
        menu_e = QMenu(btn_escr)
        menu_e.setStyleSheet(self._menu_style())
        menu_e.addAction("✍  En este guion (le dices qué escribir)", ia("escribir_aqui"))
        menu_e.addAction("📄  Un guion nuevo a partir de una idea…", ia("escribir_nuevo"))
        btn_escr.setMenu(menu_e)
        btn_escr.setPopupMode(QToolButton.ToolButtonPopupMode.InstantPopup)

        btn_inj = self._boton("🎚 Injerencia ▾", habilitado=True,
                              tooltip="Cuánto puede tocar la IA tu guion (solo aconsejar, proponer y esperar tu "
                                      "«sí», o escribir directo) y tu proyecto: fichas, Carta Gantt, presupuesto, "
                                      "contratos y planos (pedirte confirmación, avanzar solo o nunca)")
        menu_i = QMenu(btn_inj)
        menu_i.setStyleSheet(self._menu_style())

        def llenar_injerencia():
            menu_i.clear()
            actual = injerencia_ia()
            for clave, texto in NIVELES_INJERENCIA_IA:
                a_ = menu_i.addAction(texto, lambda c=clave: self.cmd_ia.emit("injerencia:" + c))
                a_.setCheckable(True)
                a_.setChecked(clave == actual)
            menu_i.addSeparator()
            t_ = menu_i.addAction("Cuando le pido cambiar algo (fichas, Carta Gantt, presupuesto…):")
            t_.setEnabled(False)
            actual_c = modo_cambios_ia() or "confirmar"
            for clave, texto in MODOS_CAMBIOS_IA:
                a_ = menu_i.addAction(texto, lambda c=clave: self.cmd_ia.emit("cambios:" + c))
                a_.setCheckable(True)
                a_.setChecked(clave == actual_c)
        menu_i.aboutToShow.connect(llenar_injerencia)
        btn_inj.setMenu(menu_i)
        btn_inj.setPopupMode(QToolButton.ToolButtonPopupMode.InstantPopup)

        btn_aj = self._boton("⚙ Ajustes de IA ▾", habilitado=True,
                             tooltip="Configurar el Profesor Claqueta y el dictado por voz")
        menu_a = QMenu(btn_aj)
        menu_a.setStyleSheet(self._menu_style())
        menu_a.addAction("🤖  Profesor Claqueta (configuración)", ia("config_ia"))
        menu_a.addAction("🎙  Dictado por voz (configuración)", ia("config_voz"))
        btn_aj.setMenu(menu_a)
        btn_aj.setPopupMode(QToolButton.ToolButtonPopupMode.InstantPopup)

        return self._ensamblar_tab([
            [btn_prof],
            [self._boton("📖 Mi historia", habilitado=True, on_click=ia("historia"),
                         tooltip="¿Cómo va mi historia? Una lectura de la estructura: qué funciona, "
                                 "dónde decae y qué preguntarte"),
             self._boton("🎬 Esta escena", habilitado=True, on_click=ia("escena"),
                         tooltip="Revisa la escena donde está el cursor"),
             btn_pers,
             self._boton("📋 ¿Qué me falta?", habilitado=True, on_click=ia("pendientes"),
                         tooltip="Qué te falta completar o usar del programa")],
            [btn_escr,
             self._boton("🎙 Dictar", habilitado=True, on_click=self.cmd_dictar.emit,
                         tooltip="Escribe el guion hablando (F2): mantén F2 mientras hablas, o "
                                 "tócala una vez. Funciona sin internet.")],
            [self._btn_modo_visual()],
            [btn_inj,
             self._boton("🧠 Modelos de IA", habilitado=True, on_click=ia("modelos"),
                         tooltip="Ver los modelos de IA (Méliès, Eisenstein, Hitchcock, Tarantino), "
                                 "cuál te conviene, bajarlos y elegir cuánto puede tocar tu guion"),
             btn_aj],
            [self._boton("🎓 Tutorial de IA", habilitado=True, on_click=ia("tutorial"),
                         tooltip="El tutorial de la IA: empieza en la ventana del Profesor Claqueta y después "
                                 "te lleva por cada lugar donde la IA puede cambiar cosas")],
        ])

    def _btn_buscar_desplegable(self) -> QToolButton:
        """Botón «Buscar» con menú desplegable: al hacer clic, ofrece
        buscar en el guion actual o hacer una búsqueda global en todo
        el proyecto."""
        btn = self._boton(
            "🔍 Buscar", habilitado=True,
            on_click=self.cmd_buscar.emit,
            tooltip="Buscar (Ctrl+F) — haz clic en la flechita "
                     "para elegir entre buscar en el guion o en "
                     "todo el proyecto")
        menu = QMenu(btn)
        menu.setStyleSheet(
            "QMenu { background: #2a3548; color: #e8edf4; "
            "border: 1px solid #3d4863; padding: 4px; }"
            "QMenu::item { padding: 8px 20px; }"
            "QMenu::item:selected { background: #ff8c1a; "
            "color: #241203; }")
        act_local = menu.addAction("🔍  En el guion  (Ctrl+F)")
