    def _menu_style(self) -> str:
        return f"""
            QMenu {{
                background: #1a2636;
                color: #e8edf4;
                border: 1px solid #1a2742;
                padding: 4px;
                font-size: 10pt;
                font-weight: bold;
            }}
            QMenu::item {{
                background: transparent;
                color: #e8edf4;
                padding: 6px 18px 6px 10px;
                min-width: 180px;
                font-weight: bold;
            }}
            QMenu::item:selected {{
                background: #ff8c1a;
                color: #241203;
            }}
            QMenu::separator {{
                height: 1px;
                background: #26344a;
                margin: 4px 0;
            }}
        """

    def _pestaña_formato(self) -> QWidget:
        # Botón Tamaño de hoja con menú desplegable
        btn_tamaño = self._boton(
            "📐 Tamaño de hoja ▾", habilitado=True,
            tooltip="Carta, A4 u Oficio",
        )
        btn_tamaño.setPopupMode(QToolButton.ToolButtonPopupMode.InstantPopup)
        btn_tamaño.setMenu(self._menu_tamaño_hoja())

        # Botón Márgenes con menú de presets
        btn_margenes = self._boton(
            "↔ Márgenes ▾", habilitado=True,
            tooltip="Configurar márgenes izq/der de la hoja",
        )
        btn_margenes.setPopupMode(QToolButton.ToolButtonPopupMode.InstantPopup)
        btn_margenes.setMenu(self._menu_margenes())

        # Botón Numeración con menú de opciones
        btn_numeracion = self._boton(
            "🔢 Numeración ▾", habilitado=True,
            tooltip="Numeración de escenas / bloques",
        )
        btn_numeracion.setPopupMode(QToolButton.ToolButtonPopupMode.InstantPopup)
        btn_numeracion.setMenu(self._menu_numeracion())

        # Botón Párrafo con menú de opciones (alineación e interlineado)
        btn_parrafo = self._boton(
            "¶ Párrafo ▾", habilitado=True,
            tooltip="Alineación e interlineado del bloque actual",
        )
        btn_parrafo.setPopupMode(QToolButton.ToolButtonPopupMode.InstantPopup)
        btn_parrafo.setMenu(self._menu_parrafo())

        return self._ensamblar_tab([
            [self._boton("🅰 Fuente", habilitado=True,
                         on_click=self.fuente_solicitada.emit,
                         tooltip="Cambiar fuente del editor"),
             btn_parrafo],
            [btn_tamaño, btn_margenes],
            [self._boton("💧 Marca de agua", habilitado=True,
                         on_click=self.marca_agua_solicitada.emit,
                         tooltip="Texto de marca de agua sobre el documento"),
             self._boton("📐 Orientación", habilitado=True,
                         on_click=self.orientacion_solicitada.emit,
                         tooltip="Poner TODO el documento en "
                                 "horizontal, o solo algunas "
                                 "páginas (para storyboards, "
                                 "plantas de cámara, etc.)")],
            [self._boton("✓ Corrector ortográfico", habilitado=True,
                         on_click=self.corrector_solicitado.emit,
                         tooltip="Abrir corrector ortográfico interactivo (F7). "
                                 "Recorre las palabras del guion una a una y "
                                 "sugiere correcciones.")],
            [btn_numeracion,
             self._boton("⇄ Diálogo doble", habilitado=True,
                         on_click=self.cmd_dialogo_doble.emit,
                         tooltip="Diálogo doble: el personaje donde "
                                 "está el cursor habla AL MISMO TIEMPO "
                                 "que el anterior (en el PDF van en dos "
                                 "columnas). Clic de nuevo para quitarlo.")],
        ])

    def _menu_numeracion(self) -> QMenu:
        menu = QMenu(self)
        menu.setStyleSheet(self._menu_style())
        for clave, etq in [
            ("escena",  "🎬  Numerar por ESCENA"),
            ("bloque",  "📝  Numerar por BLOQUE"),
            ("ninguna", "∅   Sin numeración"),
        ]:
            act = menu.addAction(etq)
            act.triggered.connect(lambda _, c=clave: self.numeracion_solicitada.emit(c))
        menu.addSeparator()
        for clave, etq in [
            ("bloquear",    "🔒  Bloquear números de escena (12A, 12B…)"),
            ("desbloquear", "🔓  Desbloquear y renumerar 1, 2, 3…"),
        ]:
            act = menu.addAction(etq)
            act.triggered.connect(lambda _, c=clave: self.numeracion_solicitada.emit(c))
        return menu

    def _menu_parrafo(self) -> QMenu:
        menu = QMenu(self)
        menu.setStyleSheet(self._menu_style())
        for clave, etq in [
            ("izq",     "⬅   Alinear a la izquierda"),
            ("centro",  "⬌   Centrar"),
            ("der",     "➡   Alinear a la derecha"),
            ("reset",   "♻   Restaurar formato del bloque"),
        ]:
            act = menu.addAction(etq)
            act.triggered.connect(lambda _, c=clave: self.parrafo_solicitado.emit(c))
        return menu

    def _menu_margenes(self) -> QMenu:
        menu = QMenu(self)
        menu.setStyleSheet(estilo_menu_claro(min_width=220))
        for nombre, (izq, der) in MARGENES_PRESETS.items():
            act = menu.addAction(nombre)
            act.triggered.connect(
                lambda _, i=izq, d=der: self.margenes_solicitados.emit(i, d)
            )
        return menu

    def _menu_tamaño_hoja(self) -> QMenu:
        menu = QMenu(self)
