    def _grupo_personalizar(self) -> list:
        """🧩 Reorganizar el ribbon: ventana Personalizar, arrastrar en el
        ribbon, y guardar/cargar configuraciones con nombre."""
        b_mover = self._boton("✋ Mover botones", habilitado=True,
                              on_click=lambda: self.poner_modo_mover(not self._modo_mover),
                              tooltip="Arrastra los botones (o un grupo entero) directo en el ribbon: a otro "
                                      "lugar, a otro grupo o (pasando por arriba de una pestaña) a otra "
                                      "pestaña. Esc o «✓ Listo» para terminar. Sin este modo: mantén apretado "
                                      "un botón, o el espacio libre de un grupo, medio segundo y arrástralo; "
                                      "si lo sueltas fuera del ribbon, vuelve a su lugar")
        b_cfg = self._boton("📂 Configuraciones ▾", habilitado=True,
                            tooltip="Cargar una configuración del ribbon guardada, o volver a la original")
        b_cfg.setPopupMode(QToolButton.ToolButtonPopupMode.InstantPopup)
        menu = QMenu(b_cfg)
        menu.setStyleSheet(self._menu_style())

        def llenar():
            menu.clear()
            cfg = self.configuraciones()
            if not cfg:
                a_ = menu.addAction("(todavía no hay configuraciones guardadas)")
                a_.setEnabled(False)
            for nombre in sorted(cfg, key=str.lower):
                menu.addAction(f"📂  {nombre}", lambda n=nombre: self.cargar_configuracion(n))
            menu.addSeparator()
            menu.addAction("↺  Volver al ribbon original de ¡Acción!", self.restaurar_original)
        menu.aboutToShow.connect(llenar)
        b_cfg.setMenu(menu)
        return [self._boton("🧩 Personalizar ribbon", habilitado=True, on_click=self.abrir_personalizar,
                            tooltip="Reorganiza el ribbon: crea pestañas nuevas, mueve botones entre "
                                    "pestañas y grupos, saca los que no usas y guarda configuraciones"),
                b_mover,
                self._boton("💾 Guardar configuración", habilitado=True,
                            on_click=self.guardar_configuracion_con_nombre,
                            tooltip="Guarda cómo está ordenado el ribbon ahora, con un nombre, para "
                                    "volver a él cuando quieras"),
                b_cfg]

    def _menu_temas(self) -> QMenu:
        menu = QMenu(self)
        menu.setStyleSheet(self._menu_style())
        a = menu.addAction("🖌  Tema y colores (con vista previa y el color de la hoja)…")
        a.triggered.connect(lambda _=False: self.tema_colores_solicitado.emit())
        menu.addSeparator()
        for tema, emoji, nombre, desc in TEMAS_ETIQUETAS:
            if tema == "claro":
                menu.addSeparator()
            act = menu.addAction(f"{emoji}  {nombre} ({desc})")
            act.triggered.connect(lambda _, t=tema: self.tema_solicitado.emit(t))
        return menu

