class _ListaPestanasRb(QListWidget):
    """Las pestañas en «Personalizar el ribbon»: se ordenan arrastrando, y
    se les puede soltar encima botones de la lista del medio."""

    def __init__(self, dlg):
        super().__init__()
        self._dlg = dlg
        self.setDragDropMode(QListWidget.DragDropMode.DragDrop)
        self.setDefaultDropAction(Qt.DropAction.MoveAction)
        self.setAcceptDrops(True)

    def dragEnterEvent(self, ev) -> None:
        ev.accept() if ev.source() in (self, self._dlg.lst_items, self._dlg.lst_disp) else ev.ignore()

    def dragMoveEvent(self, ev) -> None:
        if ev.source() is self:
            super().dragMoveEvent(ev)
        else:
            ev.setDropAction(Qt.DropAction.CopyAction)
            ev.accept()

    def dropEvent(self, ev) -> None:
        if ev.source() is self:                         # (reordenar pestañas)
            super().dropEvent(ev)
            QTimer.singleShot(0, self._dlg.orden_pestanas_cambio)
            return
        it = self.itemAt(ev.position().toPoint())
        if it is None:
            ev.ignore()
            return
        self._dlg.llevar_a_pestana(ev.source(), self.row(it))
        ev.setDropAction(Qt.DropAction.CopyAction)       # (la lista de origen no borra nada: ya se movió)
        ev.accept()


class DialogoPersonalizarRibbon(QDialog):
    """🧩 Reorganizar el ribbon: pestañas nuevas (y renombrarlas o
    quitarlas), botones entre pestañas y grupos (arrastrando), sacar los
    que no se usan, y guardar/cargar configuraciones con nombre."""
    SEP = ""                                            # (en la lista: un separador de grupo)

    def __init__(self, ribbon, parent=None):
        super().__init__(parent)
        self.rb = ribbon
        self.setWindowTitle("🧩  Personalizar el ribbon")
        self.resize(px(1000), px(620))
        self._tabs: list = []                           # [[nombre, [id | SEP, …]], …]
        self._actual = -1
        v = QVBoxLayout(self)
        intro = QLabel("Arrastra los botones para ordenarlos. Las líneas «── nuevo grupo ──» separan los grupos "
                       "de una pestaña. Para llevar un botón a otra pestaña, suéltalo sobre su nombre (a la "
                       "izquierda). Lo que pongas en «No están en el ribbon» desaparece de arriba (y puedes "
                       "volver a ponerlo cuando quieras). También en el mismo ribbon: mantén apretado un botón, "
                       "o el espacio libre de un grupo, medio segundo y arrástralo; y el «+» después de la última "
                       "pestaña crea una categoría nueva.")
        intro.setWordWrap(True)
        v.addWidget(intro)
        h = QHBoxLayout()
        # 1) pestañas
        c1 = QVBoxLayout()
        c1.addWidget(QLabel("<b>Pestañas</b>"))
        self.lst_tabs = _ListaPestanasRb(self)
        self.lst_tabs.currentRowChanged.connect(self._pestana_elegida)
        c1.addWidget(self.lst_tabs, 1)
        for texto, fn in (("＋ Pestaña nueva", self._nueva_pestana), ("✎ Renombrar", self._renombrar),
                          ("🗑 Quitar pestaña", self._quitar_pestana)):
            b = QPushButton(texto)
            b.clicked.connect(fn)
            c1.addWidget(b)
        h.addLayout(c1, 2)
        # 2) botones de la pestaña
        c2 = QVBoxLayout()
        self.lbl_items = QLabel("<b>Botones de la pestaña</b>")
        c2.addWidget(self.lbl_items)
        self.lst_items = QListWidget()
        self.lst_items.setDragDropMode(QListWidget.DragDropMode.DragDrop)
        self.lst_items.setDefaultDropAction(Qt.DropAction.MoveAction)
        self.lst_items.setSelectionMode(QListWidget.SelectionMode.ExtendedSelection)
        c2.addWidget(self.lst_items, 1)
        fila = QHBoxLayout()
        b_sep = QPushButton("＋ Nuevo grupo")
        b_sep.setToolTip("Agrega una línea que separa un grupo de botones del siguiente")
        b_sep.clicked.connect(self._agregar_separador)
        b_fuera = QPushButton("→ Sacar del ribbon")
        b_fuera.clicked.connect(lambda: self._mover_seleccion(self.lst_items, self.lst_disp))
        fila.addWidget(b_sep)
        fila.addWidget(b_fuera)
        c2.addLayout(fila)
        h.addLayout(c2, 3)
        # 3) botones fuera del ribbon
        c3 = QVBoxLayout()
        c3.addWidget(QLabel("<b>No están en el ribbon</b>"))
        self.lst_disp = QListWidget()
        self.lst_disp.setDragDropMode(QListWidget.DragDropMode.DragDrop)
        self.lst_disp.setDefaultDropAction(Qt.DropAction.MoveAction)
        self.lst_disp.setSelectionMode(QListWidget.SelectionMode.ExtendedSelection)
        self.lst_disp.setSortingEnabled(True)
        c3.addWidget(self.lst_disp, 1)
        b_dentro = QPushButton("← Poner en esta pestaña")
        b_dentro.clicked.connect(lambda: self._mover_seleccion(self.lst_disp, self.lst_items))
        c3.addWidget(b_dentro)
        h.addLayout(c3, 3)
        v.addLayout(h, 1)
        # configuraciones guardadas
        fc = QHBoxLayout()
        fc.addWidget(QLabel("Configuraciones guardadas:"))
        self.cmb_cfg = QComboBox()
        self.cmb_cfg.setMinimumWidth(px(200))
        fc.addWidget(self.cmb_cfg, 1)
        for texto, fn in (("📂 Cargar", self._cargar_cfg), ("💾 Guardar como…", self._guardar_cfg),
                          ("🗑 Borrar", self._borrar_cfg), ("↺ La original de ¡Acción!", self._original)):
            b = QPushButton(texto)
            b.clicked.connect(fn)
            fc.addWidget(b)
        v.addLayout(fc)
        bb = QDialogButtonBox(QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel |
                              QDialogButtonBox.StandardButton.Apply)
        bb.button(QDialogButtonBox.StandardButton.Ok).setText("Aceptar")
        bb.button(QDialogButtonBox.StandardButton.Cancel).setText("Cancelar")
        bb.button(QDialogButtonBox.StandardButton.Apply).setText("Aplicar")
        bb.accepted.connect(self.aceptar)
        bb.rejected.connect(self.reject)
        bb.button(QDialogButtonBox.StandardButton.Apply).clicked.connect(self.aplicar)
        v.addWidget(bb)
        self._cargar_disposicion(ribbon.disposicion_actual())
        self._llenar_cfg()

    # ── modelo ↔ listas ──
    def _item(self, rid: str) -> QListWidgetItem:
        if rid == self.SEP:
            it = QListWidgetItem("──────  nuevo grupo  ──────")
            it.setForeground(QColor("#ff8c1a"))
        else:
            it = QListWidgetItem(self.rb._rb_nombres.get(rid, rid))
            it.setToolTip(self.rb._rb_widgets[rid].toolTip() if rid in self.rb._rb_widgets else "")
        it.setData(Qt.ItemDataRole.UserRole, rid)
        return it

    def _cargar_disposicion(self, disp: dict) -> None:
        disp = self.rb.normalizar_disposicion(disp)
        self._tabs = []
        for t in disp["pestanas"]:
            items = []
            for gi, g in enumerate(t["grupos"]):
                if gi:
                    items.append(self.SEP)
                items.extend(g)
            self._tabs.append([t["nombre"], items])
        self._actual = -1
        self.lst_tabs.blockSignals(True)
        self.lst_tabs.clear()
        for k, (nombre, _i) in enumerate(self._tabs):
            it = QListWidgetItem(nombre)
            it.setData(Qt.ItemDataRole.UserRole, k)
            self.lst_tabs.addItem(it)
        self.lst_tabs.blockSignals(False)
        self.lst_tabs.setCurrentRow(0)
        self._pestana_elegida(0)

    def _guardar_lista_actual(self) -> None:
        if 0 <= self._actual < len(self._tabs):
            self._tabs[self._actual][1] = [self.lst_items.item(k).data(Qt.ItemDataRole.UserRole)
                                           for k in range(self.lst_items.count())]

    def _pestana_elegida(self, fila: int) -> None:
        self._guardar_lista_actual()
        self._actual = fila
        self.lst_items.clear()
        if 0 <= fila < len(self._tabs):
            self.lbl_items.setText(f"<b>Botones de «{html.escape(self._tabs[fila][0])}»</b>")
            for rid in self._tabs[fila][1]:
                self.lst_items.addItem(self._item(rid))
        self._llenar_disponibles()

    def _ids_puestos(self) -> set:
        self._guardar_lista_actual()
        return {r for _n, items in self._tabs for r in items if r != self.SEP}

    def _llenar_disponibles(self) -> None:
        puestos = {r for _n, items in self._tabs for r in items if r != self.SEP}
        puestos |= {self.lst_items.item(k).data(Qt.ItemDataRole.UserRole) for k in range(self.lst_items.count())}
        self.lst_disp.clear()
        for rid in self.rb._rb_widgets:
            if rid not in puestos:
                self.lst_disp.addItem(self._item(rid))

    def disposicion(self) -> dict:
        self._guardar_lista_actual()
        pestanas = []
        for nombre, items in self._tabs:
            grupos, g = [], []
            for r in items:
                if r == self.SEP:
                    if g:
                        grupos.append(g)
                    g = []
                else:
                    g.append(r)
            if g:
                grupos.append(g)
            pestanas.append({"nombre": nombre, "grupos": grupos})
        return {"pestanas": pestanas, "conocidos": list(self.rb._rb_widgets)}

    # ── acciones ──
    def orden_pestanas_cambio(self) -> None:
        self._guardar_lista_actual()
        actual = self._tabs[self._actual] if 0 <= self._actual < len(self._tabs) else None
        nuevos = [self._tabs[self.lst_tabs.item(k).data(Qt.ItemDataRole.UserRole)]
                  for k in range(self.lst_tabs.count())]
        self._tabs = nuevos
        self.lst_tabs.blockSignals(True)
        for k in range(self.lst_tabs.count()):
            self.lst_tabs.item(k).setData(Qt.ItemDataRole.UserRole, k)
        self._actual = self._tabs.index(actual) if actual in self._tabs else -1
        self.lst_tabs.setCurrentRow(self._actual)
        self.lst_tabs.blockSignals(False)

    def llevar_a_pestana(self, origen: QListWidget, destino: int) -> None:
        """Botones soltados sobre una pestaña: van al final de ella."""
        ids = [it.data(Qt.ItemDataRole.UserRole) for it in origen.selectedItems()]
        ids = [r for r in ids if r != self.SEP]
        if not ids or not (0 <= destino < len(self._tabs)):
            return
        for it in list(origen.selectedItems()):
            origen.takeItem(origen.row(it))
        self._guardar_lista_actual()
        if destino == self._actual:
            for r in ids:
                self.lst_items.addItem(self._item(r))
            self._guardar_lista_actual()
        else:
            self._tabs[destino][1].extend(ids)
        self._llenar_disponibles()

    def _mover_seleccion(self, de: QListWidget, a: QListWidget) -> None:
        for it in list(de.selectedItems()):
            rid = it.data(Qt.ItemDataRole.UserRole)
            de.takeItem(de.row(it))
            if rid != self.SEP:
                a.addItem(self._item(rid))
        self._guardar_lista_actual()

    def _agregar_separador(self) -> None:
        fila = self.lst_items.currentRow()
        self.lst_items.insertItem(fila + 1 if fila >= 0 else self.lst_items.count(), self._item(self.SEP))
        self._guardar_lista_actual()

    def _nueva_pestana(self) -> None:
        nombre, ok = QInputDialog.getText(self, "Pestaña nueva", "Nombre de la pestaña:")
        nombre = str(nombre or "").strip()
        if not ok or not nombre:
            return
        self._guardar_lista_actual()
        self._tabs.append([nombre, []])
        it = QListWidgetItem(nombre)
        it.setData(Qt.ItemDataRole.UserRole, len(self._tabs) - 1)
        self.lst_tabs.addItem(it)
        self.lst_tabs.setCurrentRow(self.lst_tabs.count() - 1)

    def _renombrar(self) -> None:
        fila = self.lst_tabs.currentRow()
        if not (0 <= fila < len(self._tabs)):
            return
        nombre, ok = QInputDialog.getText(self, "Renombrar pestaña", "Nombre:", text=self._tabs[fila][0])
        nombre = str(nombre or "").strip()
        if ok and nombre:
            self._tabs[fila][0] = nombre
            self.lst_tabs.item(fila).setText(nombre)
            self.lbl_items.setText(f"<b>Botones de «{html.escape(nombre)}»</b>")

    def _quitar_pestana(self) -> None:
        """Sus botones pasan a «No están en el ribbon»."""
        fila = self.lst_tabs.currentRow()
        if not (0 <= fila < len(self._tabs)) or len(self._tabs) <= 1:
            return
        self._actual = -1
        del self._tabs[fila]
        self.lst_tabs.blockSignals(True)
        self.lst_tabs.takeItem(fila)
        for k in range(self.lst_tabs.count()):
            self.lst_tabs.item(k).setData(Qt.ItemDataRole.UserRole, k)
        self.lst_tabs.blockSignals(False)
        self.lst_tabs.setCurrentRow(min(fila, len(self._tabs) - 1))
        self._pestana_elegida(self.lst_tabs.currentRow())

    def _llenar_cfg(self) -> None:
        self.cmb_cfg.clear()
        for nombre in sorted(self.rb.configuraciones(), key=str.lower):
            self.cmb_cfg.addItem(nombre)

    def _cargar_cfg(self) -> None:
        cfg = self.rb.configuraciones()
        nombre = self.cmb_cfg.currentText()
        if nombre in cfg:
            self._cargar_disposicion(cfg[nombre])

    def _guardar_cfg(self) -> None:
        nombre, ok = QInputDialog.getText(self, "Guardar configuración", "Nombre de esta configuración:",
                                          text=self.cmb_cfg.currentText())
        nombre = str(nombre or "").strip()
        if ok and nombre:
            self.rb.guardar_configuracion(nombre, self.disposicion())
            self._llenar_cfg()
            self.cmb_cfg.setCurrentText(nombre)

    def _borrar_cfg(self) -> None:
        nombre = self.cmb_cfg.currentText()
        if nombre:
            self.rb.borrar_configuracion(nombre)
            self._llenar_cfg()

    def _original(self) -> None:
        self._cargar_disposicion(self.rb.disposicion_original())

    def aplicar(self) -> None:
        self.rb.aplicar_disposicion(self.disposicion())

    def aceptar(self) -> None:
        self.aplicar()
        self.accept()


