def _texto_ubicacion(pais: str, region: str, ciudad: str) -> str:
    """«Viña del Mar, Valparaíso (Chile)» para mostrar al usuario."""
    nombre_pais = ""
    try:
        nombre_pais = dict(paises_ordenados()).get(pais, pais or "")
    except Exception:
        nombre_pais = pais or ""
    partes = [p for p in (ciudad, region) if p]
    txt = ", ".join(partes)
    if nombre_pais:
        txt = f"{txt} ({nombre_pais})" if txt else nombre_pais
    return txt or "sin ubicación"


def copiar_ciudad_a_locaciones(origen: dict, destinos: list) -> int:
    """Copia país, región y ciudad de `origen` (dict con pais, region,
    ciudad, gps) a cada Locacion de `destinos`.

    GPS: si la locación cambia de ciudad, su GPS anterior ya no sirve
    y se reemplaza por el de origen (o queda vacío = automático según
    la ciudad). Si ya estaba en esa misma ciudad, conserva su GPS
    propio (puede ser la dirección exacta de ese lugar)."""
    n = 0
    for o in destinos:
        misma_antes = (
            (getattr(o, "ciudad", "") or "") == origen.get("ciudad", "")
            and (getattr(o, "region", "") or "") == origen.get("region", "")
            and (getattr(o, "pais", "") or "") == origen.get("pais", ""))
        o.pais = origen.get("pais", "") or ""
        o.region = origen.get("region", "") or ""
        o.ciudad = origen.get("ciudad", "") or ""
        if not misma_antes or not (getattr(o, "gps", "") or "").strip():
            o.gps = origen.get("gps", "") or ""
        n += 1
    return n


class DialogoMismaCiudad(QDialog):
    """«¿Qué otras locaciones están en esta misma ciudad?»

    Lista de casillas con todas las demás locaciones (y la ciudad que
    tienen hoy). Al aceptar, copia país, región, ciudad y GPS de la
    locación de origen a las marcadas. Se abre desde el botón
    «📍 Misma ciudad en otras locaciones…» de cada ficha de locación,
    y automáticamente la primera vez que se le pone ciudad a una."""

    def __init__(self, nombre_origen: str, origen: dict,
                 todas: dict, intro: str = "",
                 premarcar_sin_ciudad: bool = True, parent=None):
        super().__init__(parent)
        self.setWindowTitle("📍  Misma ciudad")
        self._origen = dict(origen)
        self._nombre_origen = nombre_origen
        self._loc_origen = todas.get(nombre_origen) if isinstance(todas, dict) else None
        self._intro = intro
        self._casillas: list[tuple[QCheckBox, object]] = []
        v = QVBoxLayout(self)
        v.setContentsMargins(px(18), px(16), px(18), px(16))
        v.setSpacing(px(10))

        self._cab = QLabel()
        self._cab.setWordWrap(True)
        v.addWidget(self._cab)
        # Sin ciudad todavía: se elige aquí (va a esta locación y a las marcadas)
        self._cb_pais = self._cb_region = self._cb_ciudad = None
        if not (origen.get("ciudad") or "").strip():
            g = QGridLayout()
            g.setHorizontalSpacing(px(8))
            self._cb_pais, self._cb_region, self._cb_ciudad = QComboBox(), QComboBox(), QComboBox()
            for cod, nom in paises_ordenados():
                self._cb_pais.addItem(nom, cod)
            i_p = self._cb_pais.findData(origen.get("pais") or pais_por_defecto())
            if i_p >= 0:
                self._cb_pais.setCurrentIndex(i_p)
            for k, (etq, cb) in enumerate((("País", self._cb_pais), ("Región", self._cb_region),
                                           ("Ciudad", self._cb_ciudad))):
                g.addWidget(QLabel(etq), 0, k)
                g.addWidget(cb, 1, k)
                g.setColumnStretch(k, 1)
            v.addLayout(g)
            self._cb_pais.currentIndexChanged.connect(lambda *_: self._llenar_regiones())
            self._cb_region.currentIndexChanged.connect(lambda *_: self._llenar_ciudades())
            self._cb_ciudad.currentIndexChanged.connect(lambda *_: (self._poner_cabecera(),
                                                                     self._actualizar_boton()))
            self._llenar_regiones(origen.get("region", ""))

        fila_sel = QHBoxLayout()
        b_todas = QPushButton("Marcar todas")
        b_ninguna = QPushButton("Ninguna")
        b_sin = QPushButton("Solo las sin ciudad")
        for b in (b_todas, b_ninguna, b_sin):
            b.setSizePolicy(QSizePolicy.Policy.Fixed,
                            QSizePolicy.Policy.Fixed)
            fila_sel.addWidget(b)
        fila_sel.addStretch()
        v.addLayout(fila_sel)

        cont = QWidget()
        lv = QVBoxLayout(cont)
        lv.setContentsMargins(px(4), px(4), px(4), px(4))
        lv.setSpacing(px(4))
        for nombre, loc in todas.items():
            if nombre == nombre_origen:
                continue
            actual = (getattr(loc, "ciudad", "") or "").strip()
            misma = (bool(actual) and actual == origen.get("ciudad", "")
                     and (getattr(loc, "region", "") or "")
                     == origen.get("region", ""))
            if misma:
                detalle = "ya está en esta ciudad"
            elif actual:
                detalle = f"hoy: {actual}"
            else:
                detalle = "sin ciudad"
            cb = QCheckBox(f"{nombre}   —   {detalle}")
            cb.setChecked(misma or (premarcar_sin_ciudad and not actual))
            cb.toggled.connect(self._actualizar_boton)
            lv.addWidget(cb)
            self._casillas.append((cb, loc))
        lv.addStretch()
        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setWidget(cont)
        scroll.setMinimumHeight(px(140))
        v.addWidget(scroll, 1)

        b_todas.clicked.connect(lambda: self._marcar(lambda l: True))
        b_ninguna.clicked.connect(lambda: self._marcar(lambda l: False))
        b_sin.clicked.connect(lambda: self._marcar(
            lambda l: not (getattr(l, "ciudad", "") or "").strip()))

        fila = QHBoxLayout()
        fila.addStretch()
        b_c = QPushButton("Cancelar")
        b_c.clicked.connect(self.reject)
        self._b_ok = QPushButton()
        self._b_ok.setDefault(True)
        self._b_ok.setStyleSheet(
            "QPushButton { background: #ff8c1a; color: #241203; "
            "border: none; border-radius: 6px; padding: 8px 16px; "
            "font-weight: 800; } "
            "QPushButton:disabled { background: #3a2410; color: #8a6a4a; }")
        self._b_ok.clicked.connect(self.accept)
        fila.addWidget(b_c)
        fila.addWidget(self._b_ok)
        v.addLayout(fila)
        self._poner_cabecera()
        self._actualizar_boton()
        self.resize(*tam_ventana(560, 500))

    # ── Elegir la ciudad aquí (si la locación todavía no tiene) ──
    def _llenar_regiones(self, seleccionar: str = "") -> None:
        pais = self._cb_pais.currentData() or ""
        self._cb_region.blockSignals(True)
        self._cb_region.clear()
        self._cb_region.addItem("(región)", "")
        for reg in regiones_de_pais(pais).keys():
            self._cb_region.addItem(reg, reg)
        i = self._cb_region.findData(seleccionar) if seleccionar else -1
        if i >= 0:
            self._cb_region.setCurrentIndex(i)
        self._cb_region.blockSignals(False)
        self._llenar_ciudades()

    def _llenar_ciudades(self) -> None:
        pais = self._cb_pais.currentData() or ""
        region = self._cb_region.currentData() or ""
        self._cb_ciudad.blockSignals(True)
        self._cb_ciudad.clear()
        self._cb_ciudad.addItem("(ciudad)", "")
        for nom, _la, _lo in regiones_de_pais(pais).get(region, []):
            self._cb_ciudad.addItem(nom, nom)
        self._cb_ciudad.blockSignals(False)
        self._poner_cabecera()
        self._actualizar_boton()

    def _elegida(self) -> dict:
        """País, región y ciudad que se van a copiar."""
        if self._cb_ciudad is None:
            return dict(self._origen)
        return dict(self._origen, pais=self._cb_pais.currentData() or "",
                    region=self._cb_region.currentData() or "",
                    ciudad=self._cb_ciudad.currentData() or "")

    def _poner_cabecera(self) -> None:
        o = self._elegida()
        intro = f"{self._intro}<br><br>" if self._intro else ""
        if self._cb_ciudad is None:
            ubic = _texto_ubicacion(o.get("pais", ""), o.get("region", ""), o.get("ciudad", ""))
            self._cab.setText(
                intro + f"Se copiará <b>{html.escape(ubic)}</b> "
                f"(de «{html.escape(self._nombre_origen)}») a las locaciones que "
                "marques. Después puedes corregir cualquiera por separado.")
        elif o.get("ciudad"):
            ubic = _texto_ubicacion(o.get("pais", ""), o.get("region", ""), o.get("ciudad", ""))
            self._cab.setText(
                intro + f"Se pondrá <b>{html.escape(ubic)}</b> en «{html.escape(self._nombre_origen)}» "
                "y en las locaciones que marques. Después puedes corregir cualquiera por separado.")
        else:
            self._cab.setText(
                intro + f"«{html.escape(self._nombre_origen)}» todavía no tiene ciudad: elígela aquí "
                "y se pone en esta y en las locaciones que marques.")

    def _marcar(self, criterio) -> None:
        for cb, loc in self._casillas:
            cb.setChecked(bool(criterio(loc)))

    def marcadas(self) -> list:
        return [loc for cb, loc in self._casillas if cb.isChecked()]

    def _actualizar_boton(self, *_):
        if not hasattr(self, "_b_ok"):
            return
        n = len(self.marcadas())
        if self._cb_ciudad is not None:
            hay = bool(self._cb_ciudad.currentData())
            self._b_ok.setText(f"✓  Poner la ciudad en esta y {n} más" if n else
                               "✓  Poner la ciudad en esta")
            self._b_ok.setEnabled(hay)
            return
        self._b_ok.setText(f"✓  Copiar a {n} "
                           f"{'locación' if n == 1 else 'locaciones'}")
        self._b_ok.setEnabled(n > 0)

    def aplicar(self) -> int:
        """Copia a las marcadas (y, si la ciudad se eligió aquí, también a
        esta locación). Devuelve cuántas otras cambiaron."""
        self._origen = self._elegida()
        if self._cb_ciudad is not None and self._loc_origen is not None:
            copiar_ciudad_a_locaciones(self._origen, [self._loc_origen])
        return copiar_ciudad_a_locaciones(self._origen, self.marcadas())


def preguntar_misma_ciudad(parent, nombre_origen: str, origen: dict,
                           todas: dict, intro: str = "",
                           premarcar_sin_ciudad: bool = True) -> int:
    """Abre DialogoMismaCiudad y aplica. Devuelve cuántas locaciones
    se actualizaron (0 si se canceló o no había a quién copiar)."""
    # (si esta locación no tiene ciudad, se elige en el mismo diálogo)
    if not any(n != nombre_origen for n in todas):
        QMessageBox.information(
            parent, "Misma ciudad",
            "No hay otras locaciones todavía. Cuando agregues más, "
            "usa este botón para ponerlas en la misma ciudad.")
        return 0
    dlg = DialogoMismaCiudad(nombre_origen, origen, todas, intro,
                             premarcar_sin_ciudad, parent=parent)
    if dlg.exec() != QDialog.DialogCode.Accepted:
        return 0
    n = dlg.aplicar()
    origen.update(dlg._origen)            # (quien llama ve la ciudad elegida)
    return n


class GaleriaFotos(QWidget):
    """Lista vertical de Foto: miniatura + comentario editable + botones
    Ver grande / Quitar. Botón "+ Agregar foto" arriba.
    """

    def __init__(self, fotos: list, parent=None):
        super().__init__(parent)
        self._fotos: list = fotos      # referencia viva
        self.setStyleSheet("""
            QWidget { background: #131d2b; }
            QLabel#titulo { font-size: 11pt; font-weight: bold; color: #e8edf4; }
            QPushButton {
                padding: 6px 12px;
                border: 1px solid #26344a;
                border-radius: 4px;
                background: #1a2636;
            }
            QPushButton:hover { background: #e7edf5; }
            QPlainTextEdit {
                background: #1a2636; border: 1px solid #26344a;
                border-radius: 4px; padding: 4px; font-size: 9pt;
            }
        """)

        v = QVBoxLayout(self)
        v.setContentsMargins(6, 6, 6, 6)
        v.setSpacing(6)

        barra = QHBoxLayout()
        lbl = QLabel("📷 Fotos")
        lbl.setObjectName("titulo")
        barra.addWidget(lbl)
        barra.addStretch()
        btn_agregar = QPushButton("＋ Agregar foto")
        btn_agregar.setStyleSheet(
            "QPushButton { background: #ff8c1a; color: #241203; "
            "font-weight: 800; border: none; border-radius: 8px; "
            "padding: 8px 16px; font-size: 10pt; } "
            "QPushButton:hover { background: #ffa64d; }")
        btn_agregar.setCursor(Qt.CursorShape.PointingHandCursor)
        btn_agregar.clicked.connect(self._agregar)
        barra.addWidget(btn_agregar)
        v.addLayout(barra)

        # Scroll para las miniaturas
        self._scroll = QScrollArea()
        self._scroll.setWidgetResizable(True)
        self._scroll.setHorizontalScrollBarPolicy(
            Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self._host = QWidget()
        self._host_layout = QVBoxLayout(self._host)
        self._host_layout.setSpacing(8)
        self._host_layout.addStretch()
        self._scroll.setWidget(self._host)
        v.addWidget(self._scroll, 1)

        self._redibujar()

    def _agregar(self) -> None:
        rutas, _ = QFileDialog.getOpenFileNames(
            self, "Elegir foto(s)", carpeta_para_adjuntar(self),
            "Imágenes (*.jpg *.jpeg *.png *.gif *.bmp *.webp);;Todos (*.*)",
        )
        recordar_carpeta_adjuntos(self, rutas)
        for ruta in rutas:
            datos = comprimir_imagen_a_b64(ruta)
            if datos:
                self._fotos.append(Foto(datos=datos, comentario=""))
            else:
                QMessageBox.warning(
                    self, "No se pudo cargar",
                    f"La imagen «{Path(ruta).name}» no se pudo procesar.",
                )
        self._redibujar()

    def _quitar(self, idx: int) -> None:
        if 0 <= idx < len(self._fotos):
            del self._fotos[idx]
            self._redibujar()

    def _ver_grande(self, idx: int) -> None:
        if not (0 <= idx < len(self._fotos)):
            return
        foto = self._fotos[idx]
        dlg = QDialog(self)
        dlg.setWindowTitle(f"Foto {idx + 1}")
        v = QVBoxLayout(dlg)
        lbl_img = QLabel()
        pix = b64_a_qpixmap(foto.datos, max_lado=900)
        if not pix.isNull():
            lbl_img.setPixmap(pix)
        else:
            lbl_img.setText("No se pudo mostrar la imagen")
        v.addWidget(lbl_img, alignment=Qt.AlignmentFlag.AlignCenter)
        if foto.comentario:
            lbl_com = QLabel(foto.comentario)
            lbl_com.setWordWrap(True)
            lbl_com.setStyleSheet("color: #4a5160; padding: 6px;")
            v.addWidget(lbl_com)
        btn = QPushButton("Cerrar")
        btn.clicked.connect(dlg.accept)
        v.addWidget(btn)
        dlg.exec()

    def _guardar_comentario(self, idx: int, texto: str) -> None:
        if 0 <= idx < len(self._fotos):
            self._fotos[idx].comentario = texto

    def _guardar_titulo(self, idx: int, texto: str) -> None:
        if 0 <= idx < len(self._fotos):
            self._fotos[idx].titulo = texto

    def _redibujar(self) -> None:
        # Limpiar host
        while self._host_layout.count() > 1:  # dejar el stretch al final
            item = self._host_layout.takeAt(0)
            w = item.widget()
            if w:
                w.deleteLater()

        if not self._fotos:
            lbl = QLabel("Aún no hay fotos. Usa «＋ Agregar foto».")
            lbl.setStyleSheet("color: #8fa1b8; padding: 20px;")
            self._host_layout.insertWidget(0, lbl)
            return

        for idx, foto in enumerate(self._fotos):
            fila = QFrame()
            fila.setObjectName("filaFoto")
            # Selector con objectName: antes "QFrame {…}" se aplicaba
            # también a cada QLabel interno (QLabel hereda de QFrame) y
            # los dibujaba con borde y relleno, robando espacio.
            fila.setStyleSheet(
                "QFrame#filaFoto { background: #1a2636; "
                "border: 1px solid #26344a; border-radius: 6px; }"
            )
            # Diseño vertical: miniatura + botones arriba, campos abajo.
            # Así cabe completo en la columna angosta de las fichas
            # (antes iba todo en una fila y se recortaba).
            v_fila = QVBoxLayout(fila)
            v_fila.setContentsMargins(8, 8, 8, 8)
            v_fila.setSpacing(6)
            arriba = QHBoxLayout()
            arriba.setSpacing(8)

            # Miniatura (clic = ver grande)
            mini = QLabel()
            pix = b64_a_qpixmap(foto.datos, max_lado=px(120))
            if not pix.isNull():
                mini.setPixmap(pix)
            else:
                mini.setText("(sin imagen)")
            mini.setCursor(Qt.CursorShape.PointingHandCursor)
            mini.mousePressEvent = lambda _e, i=idx: self._ver_grande(i)
            arriba.addWidget(mini, 0, Qt.AlignmentFlag.AlignTop)

            botones = QVBoxLayout()
            botones.setSpacing(4)
            lbl_num = QLabel(f"<b>Foto {idx + 1}</b>")
            botones.addWidget(lbl_num)
            btn_ver = QPushButton("🔍 Ver grande")
            btn_ver.clicked.connect(lambda _, i=idx: self._ver_grande(i))
            btn_quit = QPushButton("🗑 Quitar")
            btn_quit.clicked.connect(lambda _, i=idx: self._quitar(i))
            botones.addWidget(btn_ver)
            botones.addWidget(btn_quit)
            botones.addStretch()
            arriba.addLayout(botones, 1)
            v_fila.addLayout(arriba)

            # Título editable (nombre de la foto)
            v_fila.addWidget(QLabel("Título:"))
            in_titulo = QLineEdit(foto.titulo)
            in_titulo.setPlaceholderText("ej: Carnet de identidad, De perfil, Vestuario…")
            in_titulo.setStyleSheet(
                "QLineEdit { background: #131d2b; border: 1px solid #26344a; "
                "border-radius: 4px; padding: 4px; font-size: 9pt; }")
            in_titulo.textChanged.connect(
                lambda t, i=idx: self._guardar_titulo(i, t)
            )
            v_fila.addWidget(in_titulo)

            v_fila.addWidget(QLabel("Comentario:"))
            txt = QPlainTextEdit(foto.comentario)
            txt.setFixedHeight(px(54))
            txt.textChanged.connect(
                lambda i=idx, t=txt: self._guardar_comentario(i, t.toPlainText())
            )
            v_fila.addWidget(txt)

            self._host_layout.insertWidget(self._host_layout.count() - 1, fila)


class CalendarioDisponibilidad(QWidget):
    """Calendario mensual con toggle de modo:
      • Modo DISPONIBLE: click marca/desmarca día como disponible (verde).
      • Modo NO DISPONIBLE: click marca/desmarca día como NO disponible (rojo).
    Si un día está marcado en el OTRO sentido, cambia al modo actual.
    """

    DIAS_SEM = ["L", "M", "X", "J", "V", "S", "D"]
    MESES = ["Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio",
             "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"]

    def __init__(self, disponibilidad: Disponibilidad, parent=None):
        super().__init__(parent)
        self._disp = disponibilidad
        self._modo_no_disponible: bool = True   # default: marcar NO disponibles
        hoy = date.today()
        self._mes = hoy.month
        self._anio = hoy.year

        self.setStyleSheet("""
            QWidget { background: #131d2b; }
            QLabel#titulo { font-size: 12pt; font-weight: bold; color: #e8edf4; }
            QLabel#diasem { color: #8fa1b8; font-size: 9pt; font-weight: bold; }
            QPushButton#nav { padding: 4px 10px; border: 1px solid #26344a;
                             background: #1a2636; border-radius: 4px; }
            QPushButton#nav:hover { background: #22314a; }
            QToolButton[dia="hábil"] {
                background: #b9e4a4; border: 1px solid #7cb342;
                color: #1d4a12; font-weight: 700;
            }
            QToolButton[dia="inhábil"] {
                background: #f5a3a3; border: 1px solid #e57373;
                color: #5a1010; font-weight: 700;
            }
            QToolButton[dia="sin"] {
                background: #22314a; border: 1px solid #2e3d58; color: #d5deea;
            }
            QToolButton:hover { border: 1px solid #ff8c1a; }
            QToolButton[dia] { padding: 0px; border-radius: 4px; }
        """)

        v = QVBoxLayout(self)
        v.setContentsMargins(6, 6, 6, 6)
        v.setSpacing(8)

        # ── Toggle de modo ────────────────────────────────────────────
        self._btn_modo = QPushButton()
        self._btn_modo.setCheckable(True)
        self._btn_modo.setChecked(True)
        self._btn_modo.clicked.connect(self._cambiar_modo)
        self._actualizar_texto_modo()
        v.addWidget(self._btn_modo)

        # ── Cabecera del mes ──────────────────────────────────────────
        cab = QHBoxLayout()
        btn_prev = QPushButton("◀")
        btn_prev.setObjectName("nav")
        btn_prev.clicked.connect(self._mes_anterior)
        cab.addWidget(btn_prev)
        self._lbl_mes = QLabel()
        self._lbl_mes.setObjectName("titulo")
        self._lbl_mes.setAlignment(Qt.AlignmentFlag.AlignCenter)
        cab.addWidget(self._lbl_mes, 1)
        btn_next = QPushButton("▶")
        btn_next.setObjectName("nav")
        btn_next.clicked.connect(self._mes_siguiente)
        cab.addWidget(btn_next)
        v.addLayout(cab)

        # ── Grid del calendario ───────────────────────────────────────
        self._grid = QGridLayout()
        self._grid.setSpacing(2)
        v.addLayout(self._grid)
        v.addStretch()

        self._dibujar()

    def _actualizar_texto_modo(self) -> None:
        # Texto corto (cabe en la columna angosta de las fichas); la
        # instrucción completa va en el tooltip.
        self._btn_modo.setToolTip(
            "Clic para cambiar entre marcar días DISPONIBLES y "
            "NO disponibles")
        if self._modo_no_disponible:
            self._btn_modo.setText("🔴  Marcando: NO disponibles  ⇄")
            self._btn_modo.setStyleSheet(
                "background: #2a1720; color: #b71c1c; font-weight: 600;"
                "border: 1px solid #e57373; padding: 8px; border-radius: 4px;"
            )
        else:
            self._btn_modo.setText("🟢  Marcando: DISPONIBLES  ⇄")
            self._btn_modo.setStyleSheet(
                "background: #c5e1a5; color: #ff8c1a; font-weight: 600;"
                "border: 1px solid #7cb342; padding: 8px; border-radius: 4px;"
            )

    def _cambiar_modo(self) -> None:
        self._modo_no_disponible = not self._modo_no_disponible
        self._actualizar_texto_modo()

    def _mes_anterior(self) -> None:
        if self._mes == 1:
            self._mes, self._anio = 12, self._anio - 1
        else:
            self._mes -= 1
        self._dibujar()

    def _mes_siguiente(self) -> None:
        if self._mes == 12:
            self._mes, self._anio = 1, self._anio + 1
        else:
            self._mes += 1
        self._dibujar()

    def _estado(self, iso: str) -> str:
        if iso in self._disp.habiles:
            return "hábil"
        if iso in self._disp.inhabiles:
            return "inhábil"
        return "sin"

    def _click_dia(self, iso: str) -> None:
        """Aplica el modo actual: si el día YA estaba en el modo activo, lo
        desmarca; si estaba en el otro modo, lo cambia al actual; si no
        estaba marcado, lo agrega al modo actual.
        """
        est = self._estado(iso)
        if self._modo_no_disponible:
            if est == "inhábil":
                self._disp.inhabiles.remove(iso)
            else:
                if est == "hábil":
                    self._disp.habiles.remove(iso)
                self._disp.inhabiles.append(iso)
        else:
            if est == "hábil":
                self._disp.habiles.remove(iso)
            else:
                if est == "inhábil":
                    self._disp.inhabiles.remove(iso)
                self._disp.habiles.append(iso)
        self._dibujar()

    def _dibujar(self) -> None:
        while self._grid.count():
            item = self._grid.takeAt(0)
            w = item.widget()
            if w:
                w.deleteLater()

        self._lbl_mes.setText(f"{self.MESES[self._mes - 1]} {self._anio}")

        for col, d in enumerate(self.DIAS_SEM):
            lbl = QLabel(d)
            lbl.setObjectName("diasem")
            lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)
            self._grid.addWidget(lbl, 0, col)

        primero = date(self._anio, self._mes, 1)
        dia_inicio = primero.weekday()

        d = primero
        col = dia_inicio
        fila = 1
        while d.month == self._mes:
            iso = d.isoformat()
            est = self._estado(iso)
            btn = QToolButton()
            btn.setText(str(d.day))
            # Los días se estiran para llenar el ancho disponible
            # (antes 44×32 fijos: se cortaban en columnas angostas).
            btn.setMinimumSize(px(30), px(28))
            btn.setMaximumSize(px(56), px(34))
            btn.setSizePolicy(QSizePolicy.Policy.Expanding,
                              QSizePolicy.Policy.Fixed)
            btn.setProperty("dia", est)
            btn.style().unpolish(btn)
            btn.style().polish(btn)
            btn.clicked.connect(lambda _, i=iso: self._click_dia(i))
            self._grid.addWidget(btn, fila, col)
            col += 1
            if col == 7:
                col = 0
                fila += 1
            d += timedelta(days=1)


# ═══════════════════════════════════════════════════════════════════════
