class DialogoVerTagsBloque(QDialog):
    """Muestra todas las notas/tags de un bloque, permite editar/borrar
    y agregar nuevos. La nota incluye autor opcional.
    """

    def __init__(self, bloque: "Bloque", parent=None):
        super().__init__(parent)
        self.bloque = bloque
        self.setWindowTitle("Notas y etiquetas del bloque")
        self.resize(px(560), px(480))
        self.setStyleSheet("""
            QDialog { background: #131d2b; }
            QLineEdit, QPlainTextEdit {
                background: #1a2636; border: 1px solid #b8c2d0;
                border-radius: 4px; padding: 6px 10px;
            }
            QPushButton {
                padding: 6px 12px; border: 1px solid #26344a;
                background: #1a2636; border-radius: 4px;
            }
            QPushButton:hover { background: #e7edf5; }
            QPushButton#peligro { color: #b71c1c; }
            QPushButton#peligro:hover { background: #2a1720; }
        """)

        v = QVBoxLayout(self)
        v.setSpacing(8)

        v.addWidget(QLabel(f"<b>Bloque:</b> {bloque.elem.name} — «{(bloque.texto or '')[:60]}…»"))
        self._scroll = QScrollArea()
        self._scroll.setWidgetResizable(True)
        self._host = QWidget()
        self._host_layout = QVBoxLayout(self._host)
        self._host_layout.setSpacing(6)
        self._scroll.setWidget(self._host)
        v.addWidget(self._scroll, 1)

        botones = QHBoxLayout()
        btn_cerrar = QPushButton("Cerrar")
        btn_cerrar.clicked.connect(self.accept)
        botones.addStretch()
        botones.addWidget(btn_cerrar)
        v.addLayout(botones)

        self._redibujar()

    def _redibujar(self) -> None:
        while self._host_layout.count():
            item = self._host_layout.takeAt(0)
            w = item.widget()
            if w:
                w.deleteLater()

        if not self.bloque.tags:
            l = QLabel("(este bloque no tiene notas ni etiquetas)")
            l.setStyleSheet("color: #8fa1b8; padding: 20px;")
            self._host_layout.addWidget(l)
            return

        for i, tag in enumerate(self.bloque.tags):
            cat = tag.get("categoria", "?")
            contenido = tag.get("contenido", "")
            autor = tag.get("autor", "")
            fecha = tag.get("fecha", "")

            if cat == "nota":
                nombre, emoji = "Nota", EMOJI_NOTA
            else:
                nombre, emoji = CATEGORIAS_DICT.get(cat, (cat, "🏷"))

            tarjeta = QFrame()
            # objectName: el estilo es solo del marco, no de cada
            # QLabel interno (QLabel también es un QFrame).
            tarjeta.setObjectName("tarjetaTag")
            tarjeta.setStyleSheet(
                "QFrame#tarjetaTag { background: #1a2636; "
                "border: 1px solid #26344a; "
                "border-radius: 6px; padding: 8px; }"
            )
            vt = QVBoxLayout(tarjeta)

            cab = QHBoxLayout()
            lbl_tit = QLabel(f"<b>{emoji} {nombre}</b>")
            cab.addWidget(lbl_tit)
            if autor or fecha:
                meta = []
                if autor: meta.append(f"por <b>{html.escape(autor)}</b>")
                if fecha: meta.append(fecha)
                lbl_meta = QLabel(" · ".join(meta))
                lbl_meta.setStyleSheet("color: #8fa1b8; font-size: 9pt;")
                cab.addWidget(lbl_meta)
            cab.addStretch()
            btn_quitar = QPushButton("🗑 Quitar")
            btn_quitar.setObjectName("peligro")
            btn_quitar.clicked.connect(lambda _, idx=i: self._quitar(idx))
            cab.addWidget(btn_quitar)
            vt.addLayout(cab)

            edit = QPlainTextEdit(contenido)
            edit.setFixedHeight(80)
            edit.textChanged.connect(
                lambda idx=i, e=edit: self._actualizar_contenido(idx, e.toPlainText())
            )
            vt.addWidget(edit)

            self._host_layout.addWidget(tarjeta)

        self._host_layout.addStretch()

    def _quitar(self, idx: int) -> None:
        if 0 <= idx < len(self.bloque.tags):
            del self.bloque.tags[idx]
            self._redibujar()

    def _actualizar_contenido(self, idx: int, nuevo: str) -> None:
        if 0 <= idx < len(self.bloque.tags):
            self.bloque.tags[idx]["contenido"] = nuevo


class DialogoPreviewFoto(QDialog):
    """Preview modal de una foto de la Pizarra de beats.
    Muestra la foto grande con su comentario y dos botones:
    - 'Cerrar' → cierra el diálogo.
    - 'Ir a la Pizarra de beats' → cierra y abre la Pizarra de beats centrada
      en esa foto."""

    ir_al_beatboard = Signal(int)  # emite el índice de la foto

    def __init__(self, documento, indice_foto: int, parent=None):
        super().__init__(parent)
        self.documento = documento
        self.indice_foto = indice_foto
        self.setWindowTitle("Vista previa de foto")
        self.setMinimumSize(px(600), px(500))
        self.setStyleSheet("""
            QDialog { background: #131d2b; }
            QLabel { color: #e8edf4; }
            QPushButton { padding: 8px 18px;
                          border: 1px solid #ff8c1a;
                          border-radius: 4px;
                          background: transparent;
                          color: #ff8c1a; font-weight: bold; }
            QPushButton:hover { background: #ff8c1a; color: #241203; }
        """)

        if not (0 <= indice_foto < len(documento.fotos_beatboard)):
            v = QVBoxLayout(self)
            v.addWidget(QLabel(
                f"⚠ La foto {indice_foto + 1} ya no existe en la Pizarra de beats.\n"
                "Puede que haya sido eliminada."))
            b_close = QPushButton("Cerrar")
            b_close.clicked.connect(self.reject)
            v.addWidget(b_close)
            return

        foto = documento.fotos_beatboard[indice_foto]

        v = QVBoxLayout(self)
        v.setContentsMargins(px(20), px(16), px(20), px(16))
        v.setSpacing(px(12))

        # Título
        titulo = QLabel(f"📷 Foto {indice_foto + 1}")
        titulo.setStyleSheet(
            "color: #ff8c1a; font-size: 14pt; font-weight: bold;")
        v.addWidget(titulo)

        # Imagen
        pixmap = QPixmap()
        if getattr(foto, "datos_b64", ""):
            try:
                import base64
                raw = base64.b64decode(foto.datos_b64)
                pixmap.loadFromData(raw)
            except Exception:
                pass
        if pixmap.isNull() and foto.path:
            pixmap = QPixmap(foto.path)

        lbl_img = QLabel()
        lbl_img.setAlignment(Qt.AlignmentFlag.AlignCenter)
        lbl_img.setStyleSheet(
            "background: #131d2b; border: 1px solid #3a4665; "
            "border-radius: 4px; padding: 8px;")
        if pixmap.isNull():
            lbl_img.setText("(no se pudo cargar la imagen)")
            lbl_img.setMinimumHeight(px(200))
        else:
            # Escalar a un máximo razonable
            max_w = px(560)
            max_h = px(400)
            escalada = pixmap.scaled(
                max_w, max_h,
                Qt.AspectRatioMode.KeepAspectRatio,
                Qt.TransformationMode.SmoothTransformation)
            lbl_img.setPixmap(escalada)
        v.addWidget(lbl_img, 1)

        # Comentario de la foto (si existe)
        if foto.comentario:
            lbl_com = QLabel(foto.comentario)
            lbl_com.setWordWrap(True)
            lbl_com.setStyleSheet(
                "color: #dcd8c8; font-size: 10pt; font-style: italic;"
                "padding: 6px 10px; background: #131d2b; "
                "border-radius: 4px;")
            v.addWidget(lbl_com)

        # Botones
        bb = QHBoxLayout()
        bb.addStretch()
        b_bb = QPushButton("📌  Ir a la Pizarra de beats")
        b_bb.setToolTip(
            "Cierra este visor y abre la Pizarra de beats centrada en esta foto")
        b_bb.clicked.connect(self._al_ir_al_bb)
        bb.addWidget(b_bb)
        b_close = QPushButton("Cerrar")
        b_close.setDefault(True)
        b_close.clicked.connect(self.accept)
        bb.addWidget(b_close)
        v.addLayout(bb)

    def _al_ir_al_bb(self) -> None:
        self.ir_al_beatboard.emit(self.indice_foto)
        self.accept()


class DialogoVincularFoto(QDialog):
    """Diálogo modal para vincular una foto de la Pizarra de beats al bloque
    actual del guion. Muestra la lista de fotos con su número y
    comentario, y devuelve (indice, comentario) al aceptar.

    NO inserta imágenes en el guion: solo un marcador de texto
    [📷 Foto N: comentario], para mantener el .accion liviano y el
    formato del guion siempre editable como texto plano.
    """

    def __init__(self, documento: "Documento", parent=None):
        super().__init__(parent)
        self.documento = documento
        self._indice_elegido: int = -1
        self._comentario_elegido: str = ""
        self.setWindowTitle("Vincular foto de la Pizarra de beats")
        self.setMinimumWidth(px(480))
        self.setMinimumHeight(px(420))
        self.setStyleSheet("""
            QDialog { background: #131d2b; }
            QLabel { color: #e8edf4; font-size: 10pt; }
            QListWidget {
                background: #1a2636; border: 1px solid #26344a;
                border-radius: 4px; padding: 4px; font-size: 10pt;
                color: #e8edf4;
            }
            QListWidget::item { padding: 8px 10px; color: #e8edf4; }
            QListWidget::item:hover { background: #131d2b; }
            QListWidget::item:selected { background: #ff8c1a; color: #241203; }
        """)

        v = QVBoxLayout(self)
        v.setContentsMargins(px(18), px(14), px(18), px(14))
        v.setSpacing(px(8))

        titulo = QLabel("🖼  Vincular una foto de la Pizarra de beats")
        titulo.setStyleSheet(
            "color: #ff8c1a; font-size: 13pt; font-weight: bold;")
        v.addWidget(titulo)

        ayuda = QLabel(
            "Selecciona una foto de la Pizarra de beats para vincularla al "
            "bloque actual del guion. Se insertará un marcador de "
            "texto que puedes hacer doble clic para abrir la foto."
        )
        ayuda.setWordWrap(True)
        ayuda.setStyleSheet("color: #8fa1b8; font-size: 9pt;")
        v.addWidget(ayuda)

        self.lista = QListWidget()
        fotos = documento.fotos_beatboard or []
        if not fotos:
            self.lista.addItem(
                "  (No hay fotos en la Pizarra de beats todavía. "
                "Abre la Pizarra de beats y agrega fotos primero.)")
            self.lista.setEnabled(False)
        else:
            for i, foto in enumerate(fotos):
                com = (foto.comentario or "").strip() or "(sin comentario)"
                itm = QListWidgetItem(f"  📷  Foto {i + 1}:  {com}")
                itm.setData(Qt.ItemDataRole.UserRole, (i, com))
                self.lista.addItem(itm)
            self.lista.setCurrentRow(0)
        self.lista.itemDoubleClicked.connect(lambda _: self._aceptar())
        v.addWidget(self.lista, 1)

        botones = QDialogButtonBox(
            QDialogButtonBox.StandardButton.Ok |
            QDialogButtonBox.StandardButton.Cancel
        )
        botones.button(QDialogButtonBox.StandardButton.Ok).setText("Vincular")
        botones.button(QDialogButtonBox.StandardButton.Cancel).setText("Cancelar")
        botones.accepted.connect(self._aceptar)
        botones.rejected.connect(self.reject)
        botones.button(QDialogButtonBox.StandardButton.Ok).setEnabled(bool(fotos))
        v.addWidget(botones)

    def _aceptar(self) -> None:
        item = self.lista.currentItem()
        if item is None:
            return
        datos = item.data(Qt.ItemDataRole.UserRole)
        if datos is None:
            return
        self._indice_elegido, self._comentario_elegido = datos
        self.accept()

    def datos(self) -> tuple[int, str]:
        """Devuelve (índice_foto, comentario) o (-1, '') si se canceló."""
        return self._indice_elegido, self._comentario_elegido


class DialogoEtiquetar(QDialog):
    """Diálogo modal para agregar una etiqueta al bloque actual.

    Permite elegir una de las 18 categorías built-in + custom del
    proyecto (guardadas en el .accion) y opcionalmente agregar un
    detalle (ej: «Reloj de pared antiguo» bajo Utilería).
    """

    def __init__(self, documento=None, parent=None):
        super().__init__(parent)
        self.documento = documento  # para leer/escribir categorias_custom
        self.setWindowTitle("Agregar etiqueta")
        self.setMinimumWidth(px(440))
        self.setStyleSheet("""
            QDialog { background: #131d2b; }
            QLabel { color: #e8edf4; font-size: 10pt; }
            QComboBox, QLineEdit {
                padding: 6px 10px;
                border: 1px solid #26344a;
                border-radius: 4px;
                background: #1a2636;
                font-size: 10pt;
            }
            QComboBox:focus, QLineEdit:focus {
                border: 1px solid #ff8c1a;
            }
        """)

        layout = QVBoxLayout(self)
        layout.setSpacing(8)
        layout.setContentsMargins(20, 18, 20, 18)

        layout.addWidget(QLabel("Categoría:"))
        fila_cat = QHBoxLayout()
        self.combo = QComboBox()
        for cid, nombre, emoji in CATEGORIAS_TAG:
            self.combo.addItem(f"{emoji}   {nombre}", cid)
        # Categorías custom del PROYECTO (guardadas en el .accion)
        try:
            if self.documento is not None:
                custom = getattr(self.documento, "categorias_custom", []) or []
                for c in custom:
                    cid_c = c.get("id", "")
                    nombre_c = c.get("nombre", "")
                    emoji_c = c.get("emoji", "🏷") or "🏷"
                    if cid_c and cid_c not in [x[0] for x in CATEGORIAS_TAG]:
                        self.combo.addItem(f"{emoji_c}   {nombre_c}", cid_c)
        except Exception:
            pass
        fila_cat.addWidget(self.combo, 1)
        btn_nueva_cat = QPushButton("＋ Nueva")
        btn_nueva_cat.setToolTip("Crear una categoría personalizada para este proyecto")
        btn_nueva_cat.setStyleSheet(
            "QPushButton { background: #1a2636; border: 1px solid #26344a; "
            "border-radius: 4px; padding: 6px 12px; font-size: 10pt; }"
            "QPushButton:hover { background: #e7edf5; }")
        btn_nueva_cat.clicked.connect(self._agregar_categoria_custom)
        fila_cat.addWidget(btn_nueva_cat)
        btn_quitar_cat = QPushButton("－ Quitar")
        btn_quitar_cat.setToolTip("Quitar la categoría personalizada seleccionada")
        btn_quitar_cat.setStyleSheet(
            "QPushButton { background: #1a2636; border: 1px solid #26344a; "
            "color: #f87171; "
            "border-radius: 4px; padding: 6px 12px; font-size: 10pt; }"
            "QPushButton:hover { background: #2a1720; border-color: #f87171; }")
        btn_quitar_cat.clicked.connect(self._quitar_categoria_custom)
        fila_cat.addWidget(btn_quitar_cat)
        layout.addLayout(fila_cat)

        layout.addSpacing(6)
        layout.addWidget(QLabel("Detalle (opcional):"))
        self.input_detalle = QLineEdit()
        self.input_detalle.setPlaceholderText("Ej: Reloj de pared antiguo, Sombrero de copa, Volkswagen verde…")
        layout.addWidget(self.input_detalle)

        layout.addSpacing(10)
        botones = QDialogButtonBox(
            QDialogButtonBox.StandardButton.Ok |
            QDialogButtonBox.StandardButton.Cancel
        )
        botones.accepted.connect(self.accept)
        botones.rejected.connect(self.reject)
        layout.addWidget(botones)

    def set_contenido(self, texto: str) -> None:
        """Pre-carga el detalle de la etiqueta (usado por el menú
        contextual del editor cuando se clickea sobre una palabra)."""
        self.input_detalle.setText(texto)

    def _agregar_categoria_custom(self) -> None:
        """Pide nombre y emoji para una nueva categoría personalizada.
        Se guarda en el documento (documento.categorias_custom) para
        que cada proyecto tenga sus propias categorías."""
        if self.documento is None:
            QMessageBox.warning(
                self, "Sin documento",
                "No hay un documento asociado para guardar la categoría.")
            return
        nombre, ok = QInputDialog.getText(
            self, "Nueva categoría",
            "Nombre de la nueva categoría\n"
            "(ej: Musicalización, Locutores, Extras adultos…):",
            QLineEdit.EchoMode.Normal, "")
        if not ok or not nombre.strip():
            return
        nombre = nombre.strip()
        # Elegir emoji para la categoría
        dlg_emoji = DialogoSelectorEmoji(self)
        emoji = "🏷"
        if dlg_emoji.exec() == QDialog.DialogCode.Accepted:
            e = dlg_emoji.emoji_elegido()
            if e:
                emoji = e
        # ID de la categoría: normalizado del nombre (minúsculas, sin acentos)
        import unicodedata
        cid_nuevo = "".join(
            c for c in unicodedata.normalize("NFD", nombre)
            if unicodedata.category(c) != "Mn"
        ).lower().replace(" ", "_")
        cid_nuevo = "".join(c for c in cid_nuevo
                            if c.isalnum() or c == "_")[:32]
        if not cid_nuevo:
            QMessageBox.warning(self, "Nombre inválido",
                                "El nombre no genera un identificador válido.")
            return
        # Verificar que no exista ya (por id o por nombre)
        existentes_ids = [c[0] for c in CATEGORIAS_TAG]
        existentes_ids.extend(c.get("id", "") for c in self.documento.categorias_custom)
        existentes_nombres = [c[1].lower() for c in CATEGORIAS_TAG]
        existentes_nombres.extend(
            c.get("nombre", "").lower()
            for c in self.documento.categorias_custom)
        if cid_nuevo in existentes_ids or nombre.lower() in existentes_nombres:
            QMessageBox.information(
                self, "Ya existe",
                f"La categoría «{nombre}» ya existe en este proyecto.")
            return
        # Agregar al documento
        self.documento.categorias_custom.append({
            "id":     cid_nuevo,
            "nombre": nombre,
            "emoji":  emoji,
        })
        # Agregarla al combo y seleccionarla
        self.combo.addItem(f"{emoji}   {nombre}", cid_nuevo)
        self.combo.setCurrentIndex(self.combo.count() - 1)

    def _quitar_categoria_custom(self) -> None:
        """Quita la categoría personalizada actualmente seleccionada
        del documento. Las categorías built-in no se pueden quitar."""
        if self.documento is None:
            return
        cid = self.combo.currentData()
        if not cid:
            return
        built_in_ids = [c[0] for c in CATEGORIAS_TAG]
        if cid in built_in_ids:
            QMessageBox.information(
                self, "Categoría del sistema",
                "Las categorías predefinidas del sistema no se pueden "
                "quitar. Solo puedes quitar las que creaste tú mismo.")
            return
        # Buscarla en el documento
        custom = self.documento.categorias_custom
        cat_a_quitar = None
        for c in custom:
            if c.get("id") == cid:
                cat_a_quitar = c
                break
        if not cat_a_quitar:
            return
        nombre = cat_a_quitar.get("nombre", cid)
        # Verificar si hay tags usando esta categoría
        n_usos = 0
        for b in self.documento.bloques:
            for t in b.tags:
                if t.get("categoria") == cid:
                    n_usos += 1
        msg = f"¿Quitar la categoría «{nombre}»?"
        if n_usos > 0:
            msg += (f"\n\nHay {n_usos} tag(s) en el guion que usan esta "
                    "categoría. Los tags quedarán huérfanos (mostrados con "
                    "un ícono 🏷 genérico).")
        r = QMessageBox.question(
            self, "Quitar categoría", msg,
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No)
        if r != QMessageBox.StandardButton.Yes:
            return
        self.documento.categorias_custom.remove(cat_a_quitar)
        # Quitarla del combo
        idx_combo = self.combo.currentIndex()
        self.combo.removeItem(idx_combo)

    def datos(self) -> tuple[str, str]:
        """Devuelve (id_categoria, contenido_detalle)."""
        cid = self.combo.currentData()
        return cid, self.input_detalle.text().strip()


# ═══════════════════════════════════════════════════════════════════════
# §8.6  VENTANA GENÉRICA DE GESTIÓN DE FICHAS
# ═══════════════════════════════════════════════════════════════════════

# Cada `campo` para la ventana es (clave_dataclass, etiqueta_visible, tipo).
# tipo ∈ {"linea", "texto"}. "linea" es QLineEdit, "texto" es QPlainTextEdit.
CampoFicha = tuple[str, str, str]


class ListaDocumentosAdjuntos(QWidget):
    """Lista de documentos adjuntos de una ficha (seguro, permisos,
    autorizaciones — sin límite de cantidad). Permite agregar VARIOS
    archivos de una vez (PDF/Word/RTF/JPG/PNG), verlos con la app
    predeterminada, ponerles etiqueta y quitarlos. Trabaja
    directamente sobre la lista `documentos` de la ficha."""

    def __init__(self, documentos: list, parent=None):
        super().__init__(parent)
        self.documentos = documentos  # referencia viva a la lista

        v = QVBoxLayout(self)
        v.setContentsMargins(0, 0, 0, 0)
        v.setSpacing(6)

        self._lista = QListWidget()
        self._lista.setStyleSheet(
            "QListWidget { background: #131d2b; color: #e8edf4; "
            "border: 1px solid #26344a; border-radius: 8px; "
            "padding: 4px; font-size: 9.5pt; } "
            "QListWidget::item { padding: 6px 8px; "
            "border-radius: 5px; } "
            "QListWidget::item:hover { background: #1a2636; } "
            "QListWidget::item:selected { background: #3a2410; "
            "color: #ff8c1a; }")
        self._lista.setMinimumHeight(90)
        self._lista.setMaximumHeight(px(160))
        self._lista.itemDoubleClicked.connect(lambda _: self._ver())
        v.addWidget(self._lista)

        estilo_btn = (
            "QPushButton { background: #3a2410; color: #ff8c1a; "
            "font-weight: 700; border: 1px solid #26344a; "
            "border-radius: 8px; padding: 6px 11px; "
            "font-size: 9pt; } "
            "QPushButton:hover { background: #4d2f12; "
            "border: 1px solid #ff8c1a; } "
            "QPushButton:disabled { background: #131d2b; "
            "color: #4a596e; border: 1px solid #1c2637; }")
        h = QHBoxLayout()
        h.setSpacing(6)
        btn_add = QPushButton("＋ Agregar…")
        btn_add.setToolTip(
            "Adjuntar uno o VARIOS documentos a la vez "
            "(PDF, Word, RTF, JPG, PNG)")
        btn_add.setStyleSheet(estilo_btn)
        btn_add.clicked.connect(self._agregar)
        h.addWidget(btn_add)
        btn_ver = QPushButton("👁 Ver")
        btn_ver.setStyleSheet(estilo_btn)
        btn_ver.clicked.connect(self._ver)
        h.addWidget(btn_ver)
        btn_etq = QPushButton("✏ Etiqueta")
        btn_etq.setToolTip(
            "Ponerle nombre descriptivo al documento "
            "(ej: «Seguro de equipo», «Permiso municipal»)")
        btn_etq.setStyleSheet(estilo_btn)
        btn_etq.clicked.connect(self._etiquetar)
        h.addWidget(btn_etq)
        btn_del = QPushButton("🗑")
        btn_del.setToolTip("Quitar el documento seleccionado")
        btn_del.setStyleSheet(
            estilo_btn.replace("#3a2410", "#2a1720")
                      .replace("#ff8c1a", "#f87171")
                      .replace("#4d2f12", "#3d2430"))
        btn_del.clicked.connect(self._quitar)
        h.addWidget(btn_del)
        h.addStretch()
        v.addLayout(h)

        self._refrescar()

    def _refrescar(self) -> None:
        self._lista.clear()
        if not self.documentos:
            it = QListWidgetItem("   (sin documentos — usa «＋ Agregar…»)")
            it.setFlags(Qt.ItemFlag.NoItemFlags)
            self._lista.addItem(it)
            return
        for d in self.documentos:
            kb = int(len(d.datos or "") * 3 / 4 / 1024)
            etq = f"{d.etiqueta} — " if d.etiqueta else ""
            self._lista.addItem(f"📄 {etq}{d.nombre}  ({kb} KB)")

    def _idx(self) -> int:
        i = self._lista.currentRow()
        return i if (self.documentos and 0 <= i < len(self.documentos)) else -1

    def _agregar(self) -> None:
        rutas, _ = QFileDialog.getOpenFileNames(
            self, "Adjuntar documentos (puedes elegir varios)",
            carpeta_para_adjuntar(self),
            "Documentos (*.pdf *.png *.jpg *.jpeg *.doc *.docx *.rtf);;"
            "PDF (*.pdf);;Word (*.doc *.docx);;RTF (*.rtf);;"
            "Imágenes (*.jpg *.jpeg *.png)")
        if not rutas:
            return
        recordar_carpeta_adjuntos(self, rutas)
        errores = []
        for ruta in rutas:
            try:
                crudo = Path(ruta).read_bytes()
                if len(crudo) > 15 * 1024 * 1024:
                    errores.append(f"{Path(ruta).name} (supera 15 MB)")
                    continue
                self.documentos.append(DocumentoAdjunto(
                    nombre=Path(ruta).name,
                    datos=base64.b64encode(crudo).decode("ascii")))
            except OSError as e:
                errores.append(f"{Path(ruta).name} ({e})")
        self._refrescar()
        if errores:
            QMessageBox.warning(
                self, "Algunos archivos no se adjuntaron",
                "No se pudieron adjuntar:\n• " + "\n• ".join(errores))

    def _ver(self) -> None:
        i = self._idx()
        if i < 0:
            return
        d = self.documentos[i]
        try:
            import tempfile
            from PySide6.QtGui import QDesktopServices
            from PySide6.QtCore import QUrl
            ext = Path(d.nombre).suffix or ".pdf"
            tmp = Path(tempfile.gettempdir()) / f"accion_doc_{i}{ext}"
            tmp.write_bytes(base64.b64decode(d.datos))
            QDesktopServices.openUrl(QUrl.fromLocalFile(str(tmp)))
        except (OSError, ValueError) as e:
            QMessageBox.warning(self, "Error",
                                f"No se pudo abrir el documento:\n{e}")

    def _etiquetar(self) -> None:
        i = self._idx()
        if i < 0:
            return
        d = self.documentos[i]
        etq, ok = QInputDialog.getText(
            self, "Etiqueta del documento",
            f"Descripción para «{d.nombre}»\n"
            "(ej: Seguro de equipo, Permiso municipal):",
            text=d.etiqueta)
        if ok:
            d.etiqueta = etq.strip()
            self._refrescar()

    def _quitar(self) -> None:
        i = self._idx()
        if i < 0:
            return
        d = self.documentos[i]
        r = QMessageBox.question(
            self, "Quitar documento",
            f"¿Quitar «{d.nombre}» de esta ficha?",
            QMessageBox.StandardButton.Yes
            | QMessageBox.StandardButton.No)
        if r == QMessageBox.StandardButton.Yes:
            self.documentos.pop(i)
            self._refrescar()


class CampoArchivoAdjunto(QWidget):
    """Campo para adjuntar un documento (contrato, boleta) a una
    ficha. Acepta PDF, Word (doc/docx), RTF, JPG y PNG. El archivo
    queda en base64 dentro del proyecto .accion, así viaja con el
    guion.

    Botones: 📎 Adjuntar · 👁 Ver · 🗑 Quitar."""

    def __init__(self, nombre_actual: str = "", datos_actual: str = "",
                 parent=None):
        super().__init__(parent)
        self.nombre = nombre_actual or ""
        self.datos = datos_actual or ""

        h = QHBoxLayout(self)
        h.setContentsMargins(0, 0, 0, 0)
        h.setSpacing(6)

        self._lbl = QLabel()
        self._lbl.setStyleSheet(
            "color: #8fa1b8; font-size: 10pt; padding: 5px 10px; "
            "background: #131d2b; border: 1px solid #26344a; "
            "border-radius: 8px;")
        h.addWidget(self._lbl, 1)

        estilo_btn = (
            "QPushButton { background: #3a2410; color: #ff8c1a; "
            "font-weight: 700; border: 1px solid #26344a; "
            "border-radius: 8px; "
            "padding: 6px 12px; font-size: 9pt; } "
            "QPushButton:hover { background: #4d2f12; "
            "border: 1px solid #ff8c1a; } "
            "QPushButton:disabled { background: #131d2b; "
            "color: #4a596e; border: 1px solid #1c2637; }")

        self._btn_adj = QPushButton("📎 Adjuntar")
        self._btn_adj.setStyleSheet(estilo_btn)
        self._btn_adj.clicked.connect(self._adjuntar)
        h.addWidget(self._btn_adj)

        self._btn_ver = QPushButton("👁 Ver")
        self._btn_ver.setStyleSheet(estilo_btn)
        self._btn_ver.clicked.connect(self._ver)
        h.addWidget(self._btn_ver)

        self._btn_quitar = QPushButton("🗑")
        self._btn_quitar.setToolTip("Quitar el documento adjunto")
        self._btn_quitar.setStyleSheet(
            estilo_btn.replace("#3a2410", "#2a1720")
                      .replace("#ff8c1a", "#f87171")
                      .replace("#4d2f12", "#3d2430"))
        self._btn_quitar.clicked.connect(self._quitar)
        h.addWidget(self._btn_quitar)

        self._refrescar()

    def _refrescar(self) -> None:
        if self.nombre and self.datos:
            kb = int(len(self.datos) * 3 / 4 / 1024)
            self._lbl.setText(f"📄 {self.nombre}  ({kb} KB)")
            self._btn_ver.setEnabled(True)
            self._btn_quitar.setEnabled(True)
        else:
            self._lbl.setText("Sin documento adjunto")
            self._btn_ver.setEnabled(False)
            self._btn_quitar.setEnabled(False)

    def _adjuntar(self) -> None:
        ruta, _ = QFileDialog.getOpenFileName(
            self, "Adjuntar documento",
            carpeta_para_adjuntar(self),
            "Documentos (*.pdf *.png *.jpg *.jpeg *.doc *.docx *.rtf);;"
            "PDF (*.pdf);;Word (*.doc *.docx);;RTF (*.rtf);;"
            "Imágenes (*.jpg *.jpeg *.png)")
        if not ruta:
            return
        recordar_carpeta_adjuntos(self, ruta)
        try:
            crudo = Path(ruta).read_bytes()
            if len(crudo) > 15 * 1024 * 1024:
                QMessageBox.warning(
                    self, "Archivo muy grande",
                    "El documento supera los 15 MB. Usa una versión "
                    "más liviana (por ejemplo, un PDF comprimido o "
                    "una foto de menor resolución).")
                return
            self.datos = base64.b64encode(crudo).decode("ascii")
            self.nombre = Path(ruta).name
            self._refrescar()
        except OSError as e:
            QMessageBox.warning(self, "Error",
                                f"No se pudo leer el archivo:\n{e}")

    def _ver(self) -> None:
        if not (self.nombre and self.datos):
            return
        try:
            import tempfile
            from PySide6.QtGui import QDesktopServices
            from PySide6.QtCore import QUrl
            ext = Path(self.nombre).suffix or ".pdf"
            tmp = Path(tempfile.gettempdir()) / f"accion_doc{ext}"
            tmp.write_bytes(base64.b64decode(self.datos))
            QDesktopServices.openUrl(QUrl.fromLocalFile(str(tmp)))
        except (OSError, ValueError) as e:
            QMessageBox.warning(self, "Error",
                                f"No se pudo abrir el documento:\n{e}")

    def _quitar(self) -> None:
        self.nombre = ""
        self.datos = ""
        self._refrescar()


def avisar_guardado(widget, texto: str, ms: int = 6000) -> None:
    """✅ Un aviso breve, sin ventana que confirmar: en la barra de abajo de
    ¡Acción! (y en el Centro de Producción, si la ficha está adentro). En el
    modo por voz, además, se lee."""
    vp = None
    w = widget
    while w is not None:
        if isinstance(w, VentanaPrincipal):
            vp = w
            break
        w = w.parent() if hasattr(w, "parent") else None
    if vp is None:
        vp = next((t for t in QApplication.topLevelWidgets() if isinstance(t, VentanaPrincipal)), None)
    if vp is not None:
        try:
            vp.statusBar().showMessage(texto, ms)
            d = getattr(vp, "_dictado", None)
            if d is not None and getattr(d, "modo_visual", False):
                d.voz.decir(texto_sin_emoji(texto))
        except Exception:
            pass
    w = widget
    while w is not None:
        if isinstance(w, VentanaCentroProduccion):
            w.avisar(texto, ms)
            break
        w = w.parent() if hasattr(w, "parent") else None


def construir_vista_ficha(vp, doc, tipo_clave: str, nombre: str = "",
                          parent=None) -> tuple:
    """La ventana de fichas de un tipo («personaje», «locacion»,
    «tecnico», «equipamiento»): la MISMA en todo el programa. El Centro
    de Producción la incrusta; el presupuesto la abre encima.
    Devuelve (dialogo, titulo), o (None, "") si el tipo no existe."""
    if tipo_clave == "personaje":
        dlg = VentanaFichasPersonaje(
            doc.fichas, nombre_inicial=nombre or None,
            documento=doc, parent=parent)
        return dlg, "🎭  Fichas de personajes"
    if tipo_clave == "locacion":
        fn = getattr(vp, "_auto_crear_locaciones_desde_escenas", None)
        if callable(fn):
            fn()
        dlg = VentanaGestorFichas(
            "Fichas de locaciones", doc.locaciones,
            vp._CAMPOS_LOCACION,
            clave_titulo="nombre",
            factoria=lambda n: Locacion(nombre=n),
            jornadas=doc.jornadas,
            tipo_recurso="locacion", parent=parent)
        return dlg, "📍  Fichas de locaciones"
    if tipo_clave == "tecnico":
        d = {t.nombre or f"Técnico {i + 1}": t
             for i, t in enumerate(doc.tecnicos)}

        def al_cerrar_t(dd: dict) -> None:
            doc.tecnicos = list(dd.values())
        dlg = VentanaGestorFichas(
            "Personal técnico", d, vp._CAMPOS_TECNICO,
            clave_titulo="nombre",
            factoria=lambda n: Tecnico(nombre=n),
            al_cerrar=al_cerrar_t,
            jornadas=doc.jornadas,
            tipo_recurso="tecnico", parent=parent)
        return dlg, "🔧  Personal técnico"
    if tipo_clave == "equipamiento":
        d = {e.nombre or f"Equipo {i + 1}": e
             for i, e in enumerate(doc.equipamiento)}

        def al_cerrar_e(dd: dict) -> None:
            doc.equipamiento = list(dd.values())
        dlg = VentanaGestorFichas(
            "Equipamiento", d, vp._CAMPOS_EQUIPAMIENTO,
            clave_titulo="nombre",
            factoria=lambda n: Equipamiento(nombre=n),
            al_cerrar=al_cerrar_e,
            jornadas=doc.jornadas,
            tipo_recurso="equipamiento", parent=parent)
        return dlg, "🎥  Equipamiento"
    return None, ""


def seleccionar_en_vista_ficha(dlg, nombre: str) -> None:
    """En los gestores de fichas (locaciones, crew, equipamiento),
    deja elegida la ficha `nombre`."""
    lista = getattr(dlg, "_lista", None)
    if not nombre or lista is None or not hasattr(lista, "count"):
        return
    try:
        for i in range(lista.count()):
            if lista.item(i).text().strip() == nombre.strip():
                lista.setCurrentRow(i)
                break
    except Exception:
        pass


def guardar_vista_ficha(dlg) -> None:
    """Guarda lo escrito en una ventana de fichas aunque se cierre con
    Esc o se destruya sin pasar por su «Cerrar»."""
    if dlg is None:
        return
    try:
        fn = getattr(dlg, "_guardar_actual", None)
        if callable(fn):
            fn()
        al = getattr(dlg, "_al_cerrar", None)
        if callable(al):
            al(getattr(dlg, "_datos", {}))
    except Exception:
        pass


def enfocar_campo_ficha(dlg, campo: str, aviso: str = "") -> bool:
    """Lleva el foco al campo `campo` de la ficha abierta (cambiando de
    pestaña y desplazando lo que haga falta) y muestra `aviso` al lado.
    Devuelve False si la ficha no tiene ese campo."""
    w = ((getattr(dlg, "_widgets", None) or {}).get(campo)
         or (getattr(dlg, "_widgets_datos", None) or {}).get(campo))
    if w is None:
        return False
    from PySide6.QtWidgets import QToolTip
    try:
        hijo, p = w, w.parentWidget()
        while p is not None and hijo is not dlg:
            if isinstance(p, QStackedWidget):
                tw = p.parentWidget()
                if isinstance(tw, QTabWidget) and tw.indexOf(hijo) >= 0:
                    tw.setCurrentIndex(tw.indexOf(hijo))
            if isinstance(p, QScrollArea):
                p.ensureWidgetVisible(w)
            hijo, p = p, p.parentWidget()
        w.setFocus(Qt.FocusReason.OtherFocusReason)
        if aviso:
            QToolTip.showText(w.mapToGlobal(QPoint(0, w.height())), aviso, w)
    except Exception:
        return False
    return True


class VentanaGestorFichas(QDialog):
    """Ventana genérica de fichas con la arquitectura del original:
    – Columna izquierda: lista de entradas con + Nueva / 🗑 Quitar.
    – Columna derecha: pestañas Datos / Fotos / Disponibilidad.

    `datos` es un dict {nombre: objeto-dataclass}. Mutado in-place.
    """

    def __init__(self, titulo: str, datos: dict, campos: list[CampoFicha],
                 clave_titulo: str, factoria: Callable[[str], object],
                 al_cerrar: Optional[Callable[[dict], None]] = None,
                 acciones_extra: Optional[list[tuple[str, Callable]]] = None,
                 jornadas: Optional[list["Jornada"]] = None,
                 tipo_recurso: str = "",
                 parent=None):
        super().__init__(parent)
        self.setWindowTitle(titulo)
        self.resize(px(960), px(640))
        self._datos = datos
        self._campos = campos
        self._clave_titulo = clave_titulo
        self._factoria = factoria
        self._al_cerrar = al_cerrar
        self._acciones_extra = acciones_extra or []
        self._jornadas = jornadas or []
        self._tipo_recurso = tipo_recurso  # "locacion" / "tecnico" / "equipamiento"
        self._actual_nombre: Optional[str] = None
        self._widgets_datos: dict[str, QWidget] = {}

        # Estilo con bordes y fondos visibles (campos amarillo crema)
        self.setObjectName("dlgGestor")
        self.setStyleSheet("""
            QDialog#dlgGestor { background: #0d1520; }
            QDialog#dlgGestor QListWidget {
                background: #131d2b; border: 1px solid #26344a;
                border-radius: 10px; padding: 6px; font-size: 10pt;
                color: #e8edf4;
            }
            QDialog#dlgGestor QListWidget::item {
                padding: 7px 10px; border-radius: 6px;
            }
            QDialog#dlgGestor QListWidget::item:hover {
                background: #1a2636;
            }
            QDialog#dlgGestor QListWidget::item:selected {
                background: #3a2410; color: #ff8c1a; font-weight: 700;
            }
            QDialog#dlgGestor QLabel { color: #e8edf4; }
            QDialog#dlgGestor QPushButton {
                padding: 8px 15px;
                border: 1px solid #26344a;
                background: #1a2636;
                color: #e8edf4;
                border-radius: 9px;
                font-size: 10pt;
                font-weight: 600;
            }
            QDialog#dlgGestor QPushButton:hover {
                background: #22314a;
                border: 1px solid #ff8c1a;
            }
            QDialog#dlgGestor QPushButton#primario {
                background: #ff8c1a; color: #241203;
                border: none;
                font-weight: 800;
            }
            QDialog#dlgGestor QPushButton#primario:hover {
                background: #ffa64d;
            }
            QDialog#dlgGestor QLabel#titulo {
                font-size: 13pt; font-weight: 800; color: #241203;
            }
            QDialog#dlgGestor QLabel#campo {
                color: #8fa1b8; font-size: 10pt;
            }
            QDialog#dlgGestor QLabel#costo {
                color: #ff8c1a; font-weight: 800; font-size: 11pt;
            }
            QDialog#dlgGestor QLineEdit,
            QDialog#dlgGestor QPlainTextEdit,
            QDialog#dlgGestor QComboBox {
                background: #1a2636;
                color: #e8edf4;
                border: 1px solid #26344a;
                border-radius: 9px; padding: 7px 11px; font-size: 10pt;
                min-height: 26px;
                selection-background-color: #ff8c1a;
                selection-color: #241203;
            }
            QDialog#dlgGestor QLineEdit:hover,
            QDialog#dlgGestor QPlainTextEdit:hover {
                background: #22314a;
            }
            QDialog#dlgGestor QLineEdit:focus,
            QDialog#dlgGestor QPlainTextEdit:focus,
            QDialog#dlgGestor QComboBox:focus {
                border: 1px solid #ff8c1a;
            }
            QDialog#dlgGestor QPlainTextEdit { min-height: 80px; }
        """)

        # ── Layout principal ──────────────────────────────────────────
        v_root = QVBoxLayout(self)
        v_root.setContentsMargins(12, 12, 12, 12)
        v_root.setSpacing(8)

        splitter = QSplitter(Qt.Orientation.Horizontal)
        v_root.addWidget(splitter, 1)

        # ── Columna izquierda ─────────────────────────────────────────
        izq = QWidget()
        v_izq = QVBoxLayout(izq)
        v_izq.setContentsMargins(0, 0, 0, 0)
        lbl_titulo = QLabel(titulo)
        lbl_titulo.setObjectName("titulo")
        v_izq.addWidget(lbl_titulo)

        self._lista = QListWidget()
        self._lista.currentItemChanged.connect(self._on_seleccion)
        v_izq.addWidget(self._lista, 1)

        botones_izq = QHBoxLayout()
        btn_nueva = QPushButton("＋ Nueva")
        btn_nueva.setObjectName("primario")
        btn_nueva.setToolTip("Crear una nueva ficha")
        btn_nueva.clicked.connect(self._nueva)
        btn_quitar = QPushButton("🗑 Quitar")
        btn_quitar.setToolTip("Eliminar la ficha seleccionada")
        btn_quitar.clicked.connect(self._quitar)
        botones_izq.addWidget(btn_nueva)
        botones_izq.addWidget(btn_quitar)
        botones_izq.addStretch()
        v_izq.addLayout(botones_izq)

        # Acciones extra (ej: Unir locaciones)
        for texto, callback in self._acciones_extra:
            btn = QPushButton(texto)
            btn.clicked.connect(lambda _, cb=callback: cb(self))
            v_izq.addWidget(btn)

        izq.setMinimumWidth(px(240))
        splitter.addWidget(izq)

        # ── Columna derecha (detalle) ─────────────────────────────────
        self._der = QWidget()
        self._der_layout = QVBoxLayout(self._der)
        self._der_layout.setContentsMargins(12, 0, 0, 0)
        self._mostrar_placeholder()
        splitter.addWidget(self._der)
        splitter.setStretchFactor(0, 0)
        splitter.setStretchFactor(1, 1)

        # ── Botones inferiores ────────────────────────────────────────
        botones_inf = QHBoxLayout()
        botones_inf.addStretch()
        btn_cerrar = QPushButton("Guardar y cerrar")
        btn_cerrar.setObjectName("primario")
        btn_cerrar.clicked.connect(self._cerrar)
        botones_inf.addWidget(btn_cerrar)
        v_root.addLayout(botones_inf)

        # ── Inicializar ───────────────────────────────────────────────
        self._refrescar_lista()
        if datos:
            self._lista.setCurrentRow(0)

        # Modo invitado: readonly total
        activo, motivo = modo_readonly_activo(self)
        if activo:
            aplicar_readonly_a_dialogo(self)
            etiqueta = ("👁 Solo lectura (invitado)"
                        if "invitado" in motivo
                        else "🔒 Solo lectura (archivo protegido)")
            self.setWindowTitle(self.windowTitle() + "  —  " + etiqueta)

    # ─── Lista ─────────────────────────────────────────────────────────

    def _refrescar_lista(self, seleccionar: Optional[str] = None) -> None:
        self._lista.clear()
        for nombre in self._datos:
            QListWidgetItem(nombre, self._lista)
        if seleccionar and seleccionar in self._datos:
            for i in range(self._lista.count()):
                if self._lista.item(i).text() == seleccionar:
                    self._lista.setCurrentRow(i)
                    return

    def _nueva(self) -> None:
        nombre, ok = QInputDialog.getText(self, "Nueva ficha", "Nombre:")
        if not ok:
            return
        nombre = nombre.strip()
        if not nombre or nombre in self._datos:
            return
        nueva = self._factoria(nombre)
        # Guardar primero lo que está escrito en la ficha abierta (si
        # no, la ciudad recién elegida aún no «existe» para la pregunta
        # de abajo).
        self._guardar_actual(preguntar=False)

        # Para locaciones: si ya hay al menos una locación con datos
        # geográficos (país, región o ciudad), ofrecer replicarlos a
        # la nueva. Normalmente todas las locaciones de un rodaje
        # están en la misma zona.
        if self._tipo_recurso == "locacion":
            plantilla = None
            for loc_existente in self._datos.values():
                tiene_datos = any([
                    (getattr(loc_existente, "ciudad", "") or "").strip(),
                    (getattr(loc_existente, "region", "") or "").strip(),
                    (getattr(loc_existente, "pais", "") or "").strip(),
                ])
                if tiene_datos:
                    plantilla = loc_existente
                    break
            if plantilla is not None:
                ciudad = getattr(plantilla, "ciudad", "") or ""
                region = getattr(plantilla, "region", "") or ""
                pais = getattr(plantilla, "pais", "") or ""
                partes = [p for p in (ciudad, region, pais) if p]
                ubicacion_txt = ", ".join(partes) or "esa zona"
                r = QMessageBox.question(
                    self, "¿En la misma zona?",
                    f"Ya tienes una locación en <b>{ubicacion_txt}</b>."
                    "<br><br>"
                    "¿La nueva locación también está ahí?<br><br>"
                    "<i>Normalmente todas las locaciones de un rodaje "
                    "están en la misma ciudad/región. Si dices que sí, "
                    "se copian país, región y ciudad "
                    "automáticamente.</i>",
                    QMessageBox.StandardButton.Yes
                    | QMessageBox.StandardButton.No,
                    QMessageBox.StandardButton.Yes)
                if r == QMessageBox.StandardButton.Yes:
                    if ciudad and hasattr(nueva, "ciudad"):
                        nueva.ciudad = ciudad
                    if region and hasattr(nueva, "region"):
                        nueva.region = region
                    if pais and hasattr(nueva, "pais"):
                        nueva.pais = pais
                    # Copiar también GPS aproximado (útil para clima)
                    if (getattr(plantilla, "gps", "")
                            and hasattr(nueva, "gps")):
                        nueva.gps = plantilla.gps
                # Ya se preguntó por la zona: no repetir la pregunta
                # automática de «misma ciudad» en esta ventana.
                self._pregunto_ciudad = True

        self._datos[nombre] = nueva
        self._refrescar_lista(seleccionar=nombre)

    def _quitar(self) -> None:
        item = self._lista.currentItem()
        if not item:
            return
        nombre = item.text()
        confirm = QMessageBox.question(
            self, "Quitar ficha",
            f"¿Quitar «{nombre}»? Esta acción no se puede deshacer.",
        )
        if confirm == QMessageBox.StandardButton.Yes:
            self._guardar_actual()
            self._datos.pop(nombre, None)
            self._actual_nombre = None
            self._refrescar_lista()
            if self._datos:
                self._lista.setCurrentRow(0)
            else:
                self._mostrar_placeholder()

    def _on_seleccion(self, actual: QListWidgetItem, _previo) -> None:
        self._guardar_actual()
        if actual is None:
            self._mostrar_placeholder()
            return
        self._mostrar_detalle(actual.text())

    # ─── Detalle ──────────────────────────────────────────────────────

    def _limpiar_layout(self, layout):
        while layout.count():
            item = layout.takeAt(0)
            w = item.widget()
            if w:
                w.deleteLater()
            elif item.layout():
                self._limpiar_layout(item.layout())

    def _mostrar_placeholder(self) -> None:
        self._limpiar_layout(self._der_layout)
        lbl = QLabel("Selecciona o crea una ficha.")
        lbl.setStyleSheet("color: #8fa1b8; font-size: 11pt; padding: 40px;")
        lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self._der_layout.addWidget(lbl)
        self._der_layout.addStretch()
        self._actual_nombre = None
        self._widgets_datos = {}

    def _mostrar_detalle(self, nombre: str) -> None:
        obj = self._datos.get(nombre)
        if obj is None:
            return
        self._actual_nombre = nombre
        self._widgets_datos = {}

        self._limpiar_layout(self._der_layout)

        tabs = QTabWidget()
        tabs.setStyleSheet("""
            QTabWidget::pane {
                border: 1px solid #26344a;
                background: #131d2b;
                border-radius: 10px;
                top: -1px;
            }
            QTabBar { background: transparent; }
            QTabBar::tab {
                background: #1a2636;
                color: #8fa1b8;
                padding: 9px 22px;
                border: 1px solid #26344a;
                border-bottom: none;
                border-top-left-radius: 9px;
                border-top-right-radius: 9px;
                font-size: 10pt;
                font-weight: 700;
                margin-right: 2px;
            }
            QTabBar::tab:selected {
                background: #3a2410;
                color: #ff8c1a;
                border: 1px solid #ff8c1a;
                border-bottom: none;
                font-weight: 900;
            }
            QTabBar::tab:hover:!selected {
                background: #22314a;
                color: #e8edf4;
            }
        """)

        # ── Pestaña DATOS ─────────────────────────────────────────────
        panel_datos = QWidget()
        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setWidget(panel_datos)
        v_datos = QVBoxLayout(panel_datos)
        v_datos.setContentsMargins(16, 16, 16, 16)
        v_datos.setSpacing(10)

        for clave, etq, tipo in self._campos:
            lbl = QLabel(etq)
            lbl.setObjectName("campo")
            v_datos.addWidget(lbl)
            valor_actual = str(getattr(obj, clave, "") or "")
            if tipo == "texto":
                w = QPlainTextEdit(valor_actual)
                w.setFixedHeight(80)
            elif tipo == "combo_pais":
                # ComboBox de países. Chile primero, resto alfabético.
                w = QComboBox()
                w.setEditable(False)
                for cod, nom in paises_ordenados():
                    w.addItem(nom, cod)
                # Preseleccionar el país actual, o el default global
                pais_actual = valor_actual or pais_por_defecto()
                idx = w.findData(pais_actual)
                if idx >= 0:
                    w.setCurrentIndex(idx)
                # Al cambiar el país, refrescar los combos de región
                # y ciudad
                def _al_cambiar_pais(idx_p, w_ref=w, obj_ref=obj):
                    self._refrescar_regiones_para_pais(w_ref)
                w.currentIndexChanged.connect(_al_cambiar_pais)
            elif tipo == "combo_region":
                # ComboBox de regiones del país actual
                w = QComboBox()
                w.setEditable(False)
                w.addItem("(seleccionar región)", "")
                # Determinar país desde el objeto o el default
                pais_actual = (getattr(obj, "pais", "")
                               or pais_por_defecto())
                for reg in regiones_de_pais(pais_actual).keys():
                    w.addItem(reg, reg)
                idx = w.findData(valor_actual)
                if idx >= 0:
                    w.setCurrentIndex(idx)
                # Al cambiar la región, refrescar el combo de ciudad
                def _al_cambiar_region(idx_r,
                                        w_ref=w,
                                        obj_ref=obj):
                    self._refrescar_ciudades_para_region(w_ref)
                w.currentIndexChanged.connect(_al_cambiar_region)
            elif tipo == "combo_ciudad":
                # ComboBox de ciudades. Se llena dinámicamente según
                # la región seleccionada en el combo hermano.
                w = QComboBox()
                w.setEditable(False)
                w.addItem("(seleccionar ciudad)", "")
                # Rellenar según la región + país actual
                pais_actual = (getattr(obj, "pais", "")
                               or pais_por_defecto())
                reg_actual = str(getattr(obj, "region", "") or "")
                regs = regiones_de_pais(pais_actual)
                if reg_actual in regs:
                    for nom, _, _ in regs[reg_actual]:
                        w.addItem(nom, nom)
                idx = w.findData(valor_actual)
                if idx >= 0:
                    w.setCurrentIndex(idx)
            elif tipo == "archivo":
                # Documento adjunto (contrato / boleta): PDF, Word,
                # RTF, JPG o PNG en base64 dentro del .accion.
                clave_datos = clave.replace("_nombre", "_datos")
                w = CampoArchivoAdjunto(
                    nombre_actual=valor_actual,
                    datos_actual=str(getattr(obj, clave_datos, "") or ""),
                )
            elif tipo == "documentos":
                # Lista abierta de documentos (seguro, permisos,
                # boletas…) — usa la lista indicada por `clave`.
                lst = getattr(obj, clave, None)
                if lst is None:
                    lst = []
                    setattr(obj, clave, lst)
                # Migrar boleta única antigua a la lista de boletas
                if clave == "boletas" and not lst:
                    bn = getattr(obj, "boleta_nombre", "") or ""
                    bd = getattr(obj, "boleta_datos", "") or ""
                    if bn and bd:
                        lst.append(DocumentoAdjunto(
                            nombre=bn, etiqueta="Boleta", datos=bd))
                        obj.boleta_nombre = ""
                        obj.boleta_datos = ""
                w = ListaDocumentosAdjuntos(lst)
            else:
                w = QLineEdit(valor_actual)
            if tipo not in ("archivo", "documentos"):
                aplicar_estilo_input(w)
            self._widgets_datos[clave] = w
            v_datos.addWidget(w)
            if tipo == "combo_ciudad" and self._tipo_recurso == "locacion":
                # Rodajes chicos: casi todo se graba en la misma ciudad.
                b_misma = QPushButton("📍  Misma ciudad en otras locaciones…")
                b_misma.setToolTip(
                    "Elige qué otras locaciones están en esta misma "
                    "ciudad: se les copia país, región, ciudad y GPS.")
                b_misma.setSizePolicy(QSizePolicy.Policy.Fixed,
                                      QSizePolicy.Policy.Fixed)
                b_misma.clicked.connect(self._elegir_misma_ciudad)
                v_datos.addWidget(b_misma)

        # ── Costo total ───────────────────────────────────────────────
        claves = {c[0] for c in self._campos}
        if "precio_dia" in claves and self._tipo_recurso:
            v_datos.addSpacing(8)
            sep = QFrame()
            sep.setFrameShape(QFrame.Shape.HLine)
            sep.setStyleSheet("color: #e8edf4;")
            v_datos.addWidget(sep)
            costo_row = QHBoxLayout()
            l_costo = QLabel("Costo total:")
            l_costo.setObjectName("campo")
            self._lbl_costo_total = QLabel("$0")
            self._lbl_costo_total.setStyleSheet(
                "color: #ff8c1a; font-weight: 700; font-size: 11pt;")
            costo_row.addWidget(l_costo)
            costo_row.addWidget(self._lbl_costo_total)
            costo_row.addStretch()
            v_datos.addLayout(costo_row)

            # Hint: aclarar de dónde vienen los días
            hint = QLabel(
                "💡 Los días se calculan automáticamente desde las jornadas "
                "de la Carta Gantt donde aparece este recurso."
            )
            hint.setStyleSheet("color: #8fa1b8; font-size: 9pt; font-style: italic;")
            hint.setWordWrap(True)
            v_datos.addWidget(hint)

            self._widgets_datos["precio_dia"].textChanged.connect(self._recalcular_total)
            self._recalcular_total()
        else:
            self._lbl_costo_total = None

        v_datos.addStretch()
        tabs.addTab(scroll, "📋 Datos")

        # ── Pestaña FOTOS ─────────────────────────────────────────────
        if not hasattr(obj, "fotos") or obj.fotos is None:
            obj.fotos = []
        galeria = GaleriaFotos(obj.fotos)
        tabs.addTab(galeria, "📷 Fotos")

        # ── Pestaña DISPONIBILIDAD ────────────────────────────────────
        if not hasattr(obj, "disponibilidad") or obj.disponibilidad is None:
            obj.disponibilidad = Disponibilidad()
        calendario = CalendarioDisponibilidad(obj.disponibilidad)
        tabs.addTab(calendario, "📅 Disponibilidad")

        self._der_layout.addWidget(tabs)

    def _recalcular_total(self) -> None:
        if not self._lbl_costo_total:
            return
        try:
            precio = parse_precio(self._widgets_datos["precio_dia"].text())
            dias = dias_de_recurso_en_jornadas(
                self._actual_nombre or "", self._tipo_recurso, self._jornadas)
            total = int(precio * dias)
            if dias > 0:
                self._lbl_costo_total.setText(
                    f"{fmt_clp(total)}  ({dias} día{'s' if dias != 1 else ''} en jornadas)"
                )
            else:
                self._lbl_costo_total.setText(
                    f"{fmt_clp(0)}  (sin jornadas — usar Carta Gantt)"
                )
        except (ValueError, AttributeError):
            self._lbl_costo_total.setText("$—")

    # ─── Guardado ─────────────────────────────────────────────────────

    def _guardar_actual(self, preguntar: bool = True) -> None:
        if self._actual_nombre is None:
            return
        obj = self._datos.get(self._actual_nombre)
        if obj is None:
            return
        ciudad_antes = (getattr(obj, "ciudad", "") or "").strip()
        for clave, w in self._widgets_datos.items():
            if isinstance(w, ListaDocumentosAdjuntos):
                continue  # edita la lista de la ficha en vivo
            elif isinstance(w, QPlainTextEdit):
                setattr(obj, clave, w.toPlainText())
            elif isinstance(w, CampoArchivoAdjunto):
                setattr(obj, clave, w.nombre)
                setattr(obj, clave.replace("_nombre", "_datos"), w.datos)
            elif isinstance(w, QComboBox):
                data = w.currentData()
                setattr(obj, clave, str(data or ""))
            elif isinstance(w, QLineEdit):
                setattr(obj, clave, w.text())
        if preguntar:
            self._ofrecer_propagar_ciudad(obj, ciudad_antes)

    def _ofrecer_propagar_ciudad(self, obj, ciudad_antes: str = "") -> None:
        """La PRIMERA vez que una locación queda con ciudad y hay otras
        sin ciudad, ofrece elegir cuáles están en el mismo lugar (típico:
        todo el corto se graba en la misma comuna). Una sola vez por
        ventana; después se usa el botón «📍 Misma ciudad…»."""
        if self._tipo_recurso != "locacion":
            return
        if getattr(self, "_pregunto_ciudad", False):
            return
        ciudad = (getattr(obj, "ciudad", "") or "").strip()
        # Solo cuando la ciudad se acaba de elegir/cambiar en esta ficha
        # (no al pasar por fichas que ya la tenían).
        if not ciudad or ciudad == (ciudad_antes or "").strip():
            return
        sin_ciudad = [o for o in self._datos.values()
                      if o is not obj
                      and not (getattr(o, "ciudad", "") or "").strip()]
        if not sin_ciudad:
            return
        self._pregunto_ciudad = True
        nombre = next((k for k, v in self._datos.items() if v is obj),
                      getattr(obj, "nombre", "") or "")
        n = preguntar_misma_ciudad(
            self, nombre, self._origen_de(obj), self._datos,
            intro=(f"Pusiste <b>{html.escape(ciudad)}</b> en esta "
                   "locación. ¿Cuáles de las otras están en la misma "
                   "ciudad?<br><i>(También puedes hacerlo cuando "
                   "quieras con el botón «📍 Misma ciudad en otras "
                   "locaciones…» de cada ficha.)</i>"))
        if n:
            self._avisar_misma_ciudad(n, ciudad)

    @staticmethod
    def _origen_de(obj) -> dict:
        return {k: (getattr(obj, k, "") or "")
                for k in ("pais", "region", "ciudad", "gps")}

    def _elegir_misma_ciudad(self) -> None:
        """Botón «📍 Misma ciudad en otras locaciones…»."""
        self._guardar_actual(preguntar=False)
        obj = self._datos.get(self._actual_nombre or "")
        if obj is None:
            return
        self._pregunto_ciudad = True   # ya no hace falta preguntar solo
        ciudad_antes = (getattr(obj, "ciudad", "") or "").strip()
        n = preguntar_misma_ciudad(
            self, self._actual_nombre, self._origen_de(obj), self._datos)
        if (getattr(obj, "ciudad", "") or "").strip() != ciudad_antes:
            self._mostrar_detalle(self._actual_nombre)     # (la ciudad se eligió en el diálogo)
        if n:
            self._avisar_misma_ciudad(n, obj.ciudad)

    def _avisar_misma_ciudad(self, n: int, ciudad: str) -> None:
        QMessageBox.information(
            self, "Misma ciudad",
            f"✅ {html.escape(ciudad)} quedó en {n} "
            f"{'locación' if n == 1 else 'locaciones'} más.")

    def _refrescar_regiones_para_pais(self, combo_pais) -> None:
        """Al cambiar el país en el combo, refrescar el combo de región
        para mostrar solo las regiones de ese país. Y en cadena, el
        combo de ciudad."""
        combo_region = self._widgets_datos.get("region")
        if combo_region is None or not isinstance(combo_region, QComboBox):
            return
        pais = combo_pais.currentData() or "CL"
        combo_region.blockSignals(True)
        combo_region.clear()
        combo_region.addItem("(seleccionar región)", "")
        for reg in regiones_de_pais(pais).keys():
            combo_region.addItem(reg, reg)
        combo_region.blockSignals(False)
        # Refrescar también ciudades
        self._refrescar_ciudades_para_region(combo_region)

    def _refrescar_ciudades_para_region(self, combo_region) -> None:
        """Cuando el usuario cambia la región en el combo, refresca el
        combo de ciudad para mostrar solo las ciudades de esa región
        en el país actualmente seleccionado."""
        combo_ciudad = self._widgets_datos.get("ciudad")
        if combo_ciudad is None or not isinstance(combo_ciudad, QComboBox):
            return
        # Determinar país actual desde el combo hermano
        combo_pais = self._widgets_datos.get("pais")
        pais = "CL"
        if combo_pais is not None and isinstance(combo_pais, QComboBox):
            pais = combo_pais.currentData() or "CL"
        region = combo_region.currentData() or ""
        ciudad_actual = combo_ciudad.currentData() or ""
        combo_ciudad.blockSignals(True)
        combo_ciudad.clear()
        combo_ciudad.addItem("(seleccionar ciudad)", "")
        regs = regiones_de_pais(pais)
        if region in regs:
            for nom, _, _ in regs[region]:
                combo_ciudad.addItem(nom, nom)
        idx = combo_ciudad.findData(ciudad_actual)
        if idx >= 0:
            combo_ciudad.setCurrentIndex(idx)
        combo_ciudad.blockSignals(False)

    def _cerrar(self) -> None:
        self._guardar_actual()
        if self._al_cerrar:
            self._al_cerrar(self._datos)
        self.accept()

    def closeEvent(self, event) -> None:
        self._guardar_actual()
        if self._al_cerrar:
            self._al_cerrar(self._datos)
        super().closeEvent(event)


# ═══════════════════════════════════════════════════════════════════════
# §8.7  VENTANA ESPECÍFICA DE FICHAS DE PERSONAJE
# ═══════════════════════════════════════════════════════════════════════

OPCIONES_ALIMENTACION = [
    "Omnívoro", "Vegetariano", "Vegano",
    "Sin gluten", "Sin lactosa", "Otro",
]


class VentanaFichasPersonaje(QDialog):
    """Ventana de fichas de personaje siguiendo el diseño del original:
      • Izquierda: lista de personajes con +Nueva / Quitar
      • Centro: scroll con campos del PERSONAJE y del ACTOR
                (alergias/movilidad solo se habilitan al marcar el check;
                 costo total se calcula en vivo)
      • Derecha: foto principal (única) + calendario de disponibilidad
    """

    def __init__(self, fichas: dict[str, Ficha],
                 nombre_inicial: Optional[str] = None,
                 documento: Optional["Documento"] = None,
                 parent=None):
        super().__init__(parent)
        self.setWindowTitle("Fichas de personajes")
        habilitar_snap(self, "🎭")
        self.resize(px(1180), px(760))
        self._fichas = fichas
        self._documento = documento     # para calcular días desde Gantt
        self._ficha_actual: Optional[Ficha] = None
        self._nombre_actual: Optional[str] = None
        self._personaje_actual: str = ""
        self._widgets: dict[str, QWidget] = {}

        # Estilo con bordes muy visibles. Forzamos colores explícitos para que
        # se vean siempre, incluso cuando los campos están vacíos. Usamos
        # `QDialog#dlgFicha` como anchor para no chocar con el tema global.
        self.setObjectName("dlgFicha")
        self.setStyleSheet("""
            QDialog#dlgFicha { background: #0d1520; }
            QDialog#dlgFicha QListWidget {
                background: #131d2b; border: 1px solid #26344a;
                border-radius: 10px; padding: 6px;
                font-family: 'Courier New'; font-size: 10pt;
                color: #e8edf4;
            }
            QDialog#dlgFicha QListWidget::item {
                padding: 6px 10px; border-radius: 6px;
            }
            QDialog#dlgFicha QListWidget::item:hover {
                background: #1a2636;
            }
            QDialog#dlgFicha QListWidget::item:selected {
                background: #3a2410; color: #ff8c1a; font-weight: 700;
            }
            QDialog#dlgFicha QLabel { color: #e8edf4; }
            QDialog#dlgFicha QLabel#seccion {
                color: #ff8c1a; font-weight: 800; font-size: 10.5pt;
                letter-spacing: 1px;
                padding-top: 10px; padding-bottom: 4px;
                border-bottom: 1px solid #26344a;
            }
            QDialog#dlgFicha QLabel#campo {
                color: #8fa1b8; font-size: 10pt;
            }
            QDialog#dlgFicha QLineEdit,
            QDialog#dlgFicha QPlainTextEdit,
            QDialog#dlgFicha QComboBox {
                background: #1a2636;
                color: #e8edf4;
                border: 1px solid #26344a;
                border-radius: 9px;
                padding: 7px 11px;
                font-size: 10pt;
                min-height: 26px;
                selection-background-color: #ff8c1a;
                selection-color: #241203;
            }
            QDialog#dlgFicha QLineEdit:hover,
            QDialog#dlgFicha QPlainTextEdit:hover,
            QDialog#dlgFicha QComboBox:hover {
                background: #22314a;
            }
            QDialog#dlgFicha QLineEdit:focus,
            QDialog#dlgFicha QPlainTextEdit:focus,
            QDialog#dlgFicha QComboBox:focus {
                border: 1px solid #ff8c1a;
            }
            QDialog#dlgFicha QLineEdit:disabled {
                background: #131d2b;
                color: #4a596e;
                border: 1px dashed #26344a;
            }
            QDialog#dlgFicha QPlainTextEdit { min-height: 90px; }
            QDialog#dlgFicha QCheckBox {
                font-size: 10pt; color: #e8edf4; padding: 4px 0;
            }
            QDialog#dlgFicha QPushButton {
                padding: 7px 15px; border: 1px solid #26344a;
                background: #1a2636; border-radius: 9px;
                color: #e8edf4;
            }
            QDialog#dlgFicha QPushButton:hover {
                background: #22314a; border: 1px solid #ff8c1a;
            }
            QDialog#dlgFicha QPushButton#primario {
                background: #ff8c1a; color: #241203;
                border: none; font-weight: 800;
            }
            QDialog#dlgFicha QPushButton#primario:hover {
                background: #ffa64d;
            }
            QDialog#dlgFicha QLabel#costo {
                color: #ff8c1a; font-weight: 800; font-size: 11pt;
            }
        """)

        # ── Layout raíz ───────────────────────────────────────────────
        v_root = QVBoxLayout(self)
        v_root.setContentsMargins(10, 10, 10, 10)
        v_root.setSpacing(8)

        h = QHBoxLayout()
        v_root.addLayout(h, 1)

        # ─── IZQUIERDA: lista ────────────────────────────────────────
        izq_box = QVBoxLayout()
        izq_box.setSpacing(4)
        self._lista = QListWidget()
        self._lista.setMinimumWidth(px(220))
        self._lista.setMaximumWidth(px(260))
        self._lista.currentItemChanged.connect(self._on_seleccion)
        izq_box.addWidget(self._lista, 1)
        botones_izq = QHBoxLayout()
        btn_nueva = QPushButton("＋ Nueva")
        btn_nueva.clicked.connect(self._nueva)
        btn_quitar = QPushButton("🗑")
        btn_quitar.setToolTip("Quitar ficha seleccionada")
        btn_quitar.clicked.connect(self._quitar)
        botones_izq.addWidget(btn_nueva)
        botones_izq.addWidget(btn_quitar)
        izq_box.addLayout(botones_izq)
        h.addLayout(izq_box)

        # ─── CENTRO: campos ──────────────────────────────────────────
        scroll_centro = QScrollArea()
        scroll_centro.setWidgetResizable(True)
        scroll_centro.setStyleSheet("background: #0d1520; border: none;")
        self._centro = QWidget()
        self._v_centro = QVBoxLayout(self._centro)
        self._v_centro.setContentsMargins(16, 8, 16, 8)
        self._v_centro.setSpacing(6)
        scroll_centro.setWidget(self._centro)
        h.addWidget(scroll_centro, 1)

        # ─── DERECHA: foto + calendario ──────────────────────────────
        self._der = QVBoxLayout()
        self._der.setSpacing(8)
        der_container = QWidget()
        der_container.setMinimumWidth(px(310))
        der_container.setMaximumWidth(px(340))
        der_container.setLayout(self._der)
        h.addWidget(der_container)

        # ─── Botones inferiores ──────────────────────────────────────
        botones_inf = QHBoxLayout()
        btn_cerrar = QPushButton("Cerrar")
        btn_cerrar.clicked.connect(self._cerrar)
        btn_guardar = QPushButton("💾 Guardar ficha")
        btn_guardar.setObjectName("primario")
        btn_guardar.clicked.connect(self._guardar_y_continuar)
        botones_inf.addWidget(btn_cerrar)
        botones_inf.addStretch()
        botones_inf.addWidget(btn_guardar)
        v_root.addLayout(botones_inf)

        # ─── Construir paneles ───────────────────────────────────────
        self._construir_panel_central()
        self._nombres_para_voz()
        self._construir_panel_derecho()
        self._refrescar_lista()

        if nombre_inicial and nombre_inicial in fichas:
            self._seleccionar(nombre_inicial)
        elif fichas:
            self._lista.setCurrentRow(0)
        else:
            self._mostrar_placeholder()

        # Modo invitado: readonly total
        activo, motivo = modo_readonly_activo(self)
        if activo:
            aplicar_readonly_a_dialogo(self)
            etiqueta = ("👁 Solo lectura (invitado)"
                        if "invitado" in motivo
                        else "🔒 Solo lectura (archivo protegido)")
            self.setWindowTitle(self.windowTitle() + "  —  " + etiqueta)

    # ─── Lista de personajes ──────────────────────────────────────────

    def _refrescar_lista(self, seleccionar: Optional[str] = None) -> None:
        self._lista.blockSignals(True)
        self._lista.clear()
        for nombre in self._fichas:
            QListWidgetItem(nombre, self._lista)
        self._lista.blockSignals(False)
        if seleccionar:
            self._seleccionar(seleccionar)

    def _seleccionar(self, nombre: str) -> None:
        for i in range(self._lista.count()):
            if self._lista.item(i).text() == nombre:
                self._lista.setCurrentRow(i)
                return

    def _nueva(self) -> None:
        nombre, ok = QInputDialog.getText(self, "Nueva ficha", "Nombre del personaje:")
        if not ok:
            return
        nombre = nombre.strip().upper()
        if not nombre or nombre in self._fichas:
            return
        self._fichas[nombre] = Ficha(personaje=nombre)
        self._refrescar_lista(seleccionar=nombre)

    def _quitar(self) -> None:
        item = self._lista.currentItem()
        if not item:
            return
        nombre = item.text()
        confirm = QMessageBox.question(
            self, "Quitar ficha",
            f"¿Quitar la ficha de «{nombre}»? No se puede deshacer.",
        )
        if confirm == QMessageBox.StandardButton.Yes:
            self._guardar_actual()
            self._fichas.pop(nombre, None)
            self._nombre_actual = None
            self._ficha_actual = None
            self._refrescar_lista()
            if self._fichas:
                self._lista.setCurrentRow(0)
            else:
                self._mostrar_placeholder()

    def _on_seleccion(self, actual: QListWidgetItem, _previo) -> None:
        self._guardar_actual()
        if actual is None:
            self._mostrar_placeholder()
            return
        self._cargar_ficha(actual.text())

