def segmentar_actos_y_escenas(doc: "Documento") -> list[dict]:
    """Como segmentar_escenas() pero incluye también los ACTO_INICIO
    y ACTO_FIN como items separadores. Devuelve items del tipo:

      {"tipo": "acto_inicio", "texto": "PRIMER ACTO",
       "idx_bloque": 0, "numero_acto": 1}
      {"tipo": "escena", "numero": 1, "encabezado": "INT...",
       "idx_inicio": 1, "idx_fin": 5, "personajes": [...],
       "n_dialogos": ..., "n_palabras": ...}
      {"tipo": "acto_fin", "texto": "FIN DEL PRIMER ACTO",
       "idx_bloque": 5}

    Los items se devuelven en el orden en que aparecen en el
    documento (los actos no tienen que estar completos: ver
    estado_actos)."""
    items = []
    bloques = doc.bloques or []
    n_bl = len(bloques)
    i = 0
    numero_escena = 0
    numero_acto = 0
    while i < n_bl:
        b = bloques[i]
        if b.elem == Elem.ACTO_INICIO:
            numero_acto += 1
            items.append({
                "tipo": "acto_inicio",
                "texto": (b.texto or "").strip() or f"ACTO {numero_acto}",
                "idx_bloque": i,
                "numero_acto": numero_acto,
            })
            i += 1
            continue
        if b.elem == Elem.ACTO_FIN:
            items.append({
                "tipo": "acto_fin",
                "texto": (b.texto or "").strip() or "FIN DEL ACTO",
                "idx_bloque": i,
            })
            i += 1
            continue
        if b.elem != Elem.ESCENA:
            i += 1
            continue
        # Escena: buscar dónde termina
        numero_escena += 1
        idx_inicio = i
        j = i + 1
        personajes = []
        n_dialogos = 0
        n_palabras = 0
        while j < n_bl:
            bj = bloques[j]
            if bj.elem in (Elem.ESCENA, Elem.ACTO_INICIO,
                            Elem.ACTO_FIN):
                break
            if bj.elem == Elem.PERSONAJE:
                pj = (bj.texto or "").strip().upper().split("(")[0].strip()
                if pj and pj not in personajes:
                    personajes.append(pj)
            elif bj.elem == Elem.DIALOGO:
                n_dialogos += 1
                n_palabras += len((bj.texto or "").split())
            elif bj.elem == Elem.ACCION:
                n_palabras += len((bj.texto or "").split())
            j += 1
        items.append({
            "tipo": "escena",
            "numero": numero_escena,
            "encabezado": (b.texto or "").strip(),
            "idx_inicio": idx_inicio,
            "idx_fin": j,
            "personajes": personajes,
            "n_dialogos": n_dialogos,
            "n_palabras": n_palabras,
        })
        i = j
    return items


def segmentar_escenas(doc: "Documento") -> list[dict]:
    """Recorre los bloques del documento y devuelve una lista con
    metadatos de cada escena y el rango de bloques que la componen.

    Cada dict:
        {
          "numero": int (1-indexed),
          "encabezado": str,
          "idx_inicio": int  (índice del bloque ESCENA),
          "idx_fin":    int  (índice EXCLUSIVE — primer bloque que NO
                              pertenece a esta escena, típicamente la
                              siguiente ESCENA / ACTO_INICIO / ACTO_FIN),
          "personajes": list[str],
          "n_dialogos": int,
          "n_palabras": int,
        }

    Los bloques que están ANTES de la primera ESCENA (por ejemplo, un
    ACTO_INICIO sin escena aún) NO forman parte de ninguna escena.
    """
    escenas = []
    bloques = doc.bloques or []
    n_bl = len(bloques)
    i = 0
    numero = 0
    while i < n_bl:
        b = bloques[i]
        if b.elem != Elem.ESCENA:
            i += 1
            continue
        # Encontramos una ESCENA. Buscar dónde termina.
        numero += 1
        idx_inicio = i
        j = i + 1
        personajes: list[str] = []
        n_dialogos = 0
        n_palabras = 0
        pj_actual = ""
        while j < n_bl:
            bj = bloques[j]
            if bj.elem in (Elem.ESCENA, Elem.ACTO_INICIO, Elem.ACTO_FIN):
                break
            if bj.elem == Elem.PERSONAJE:
                pj_actual = (bj.texto or "").strip().upper().split("(")[0].strip()
                if pj_actual and pj_actual not in personajes:
                    personajes.append(pj_actual)
            elif bj.elem == Elem.DIALOGO:
                n_dialogos += 1
                n_palabras += len((bj.texto or "").split())
            elif bj.elem == Elem.ACCION:
                n_palabras += len((bj.texto or "").split())
            j += 1
        escenas.append({
            "numero": numero,
            "encabezado": b.texto or "(sin encabezado)",
            "idx_inicio": idx_inicio,
            "idx_fin": j,
            "personajes": personajes,
            "n_dialogos": n_dialogos,
            "n_palabras": n_palabras,
        })
        i = j
    return escenas


def _locacion_desde_encabezado(enc: str) -> str:
    """Extrae la locación de un encabezado tipo 'INT. LICEO - DIA'."""
    m = re.match(r"^(?:INT\./?EXT\.|INT\.|EXT\.|I/E\.)\s+(.+)$",
                 enc.upper().lstrip())
    if not m:
        return "SIN LOCACIÓN"
    return m.group(1).split("-", 1)[0].strip(" .,").title()


def _rango_dias(d0: date, d1: date) -> list[str]:
    """Devuelve la lista de fechas ISO entre d0 y d1 (inclusive)."""
    if d1 < d0:
        d0, d1 = d1, d0
    out = []
    f = d0
    while f <= d1:
        out.append(f.isoformat())
        f += timedelta(days=1)
    return out


def _esta_inhabil(disp: "Disponibilidad", fechas_iso: list[str]) -> list[str]:
    """De las fechas dadas, devuelve cuáles caen en disp.inhabiles."""
    if not disp or not disp.inhabiles:
        return []
    inh = set(disp.inhabiles)
    return [f for f in fechas_iso if f in inh]


def _parse_csv_nombres(s: str) -> list[str]:
    """Convierte 'MICHELLE, SOFÍA, LAURA' → ['MICHELLE','SOFÍA','LAURA']."""
    return [x.strip().upper() for x in (s or "").split(",") if x.strip()]


def _csv_de_lista(items: list[str]) -> str:
    """Lista de nombres → 'A, B, C' (sin duplicados, en orden de inserción)."""
    visto = []
    out: list[str] = []
    for x in items:
        x = x.strip()
        if x and x not in visto:
            visto.append(x)
            out.append(x)
    return ", ".join(out)


def hablantes_de_escenas(doc, nums) -> list[str]:
    """Los personajes que HABLAN (tienen diálogo) en esas escenas, con
    los números como en la Carta Gantt (1 = la primera escena), en orden
    de aparición y sin «(V.O.)» ni «(CONT.)»."""
    quiero = {int(str(n).strip().lstrip("#")) for n in nums if str(n).strip().lstrip("#").isdigit()}
    out: list[str] = []
    if not quiero:
        return out
    bloques = getattr(doc, "bloques", []) or []
    for e in segmentar_escenas(doc):
        if e["numero"] not in quiero:
            continue
        pj = ""
        for b in bloques[e["idx_inicio"]:e["idx_fin"]]:
            if b.elem == Elem.PERSONAJE:
                pj = _nombre_personaje(b.texto)
            elif b.elem == Elem.DIALOGO and pj and (b.texto or "").strip():
                if pj not in out:
                    out.append(pj)
            elif b.elem not in (Elem.PARENTESIS, Elem.DIALOGO):
                pj = ""
    return out


def unir_nombres(nombres: list) -> str:
    """«ANA», «ANA y BRUNO», «ANA, BRUNO e INÉS» (con «e» ante «i»)."""
    nombres = [str(n) for n in nombres if str(n).strip()]
    if len(nombres) < 2:
        return "".join(nombres)
    ult = nombres[-1]
    y = "e" if re.match(r"(?i)h?[iíÍ](?![aeoáéó])", ult) else "y"
    return ", ".join(nombres[:-1]) + f" {y} " + ult


def completar_actores_de_jornada(doc, j, nums=None) -> list[str]:
    """Suma a la jornada (sin quitar a nadie) a quienes hablan en sus
    escenas (o en `nums`) y les crea la ficha si no la tienen: así su
    valor por día entra solo al presupuesto. Devuelve los que agregó."""
    nums = _escenas_de_jornada(j) if nums is None else nums
    ya = _parse_csv_nombres(j.actores or "")
    ya_up = {a.upper() for a in ya}
    nuevos = [p for p in hablantes_de_escenas(doc, nums) if p.upper() not in ya_up]
    if nuevos:
        j.actores = _csv_de_lista(ya + nuevos)
    fichas = getattr(doc, "fichas", None)
    if isinstance(fichas, dict):
        claves = {k.upper() for k in fichas}
        for p in nuevos:
            if p.upper() not in claves:
                fichas[p] = Ficha(personaje=p)
    return nuevos


def dias_de_jornada(j: "Jornada") -> int:
    """Cuenta los días que dura la jornada (inclusivo). 0 si sin fechas."""
    d0 = _fecha_iso(j.fecha)
    if not d0:
        return 0
    d1 = _fecha_iso(j.fecha_fin) or d0
    if d1 < d0:
        d0, d1 = d1, d0
    return (d1 - d0).days + 1


def dias_de_recurso_en_jornadas(nombre: str, tipo: str,
                                jornadas: list["Jornada"]) -> int:
    """Suma los días de TODAS las jornadas donde este recurso aparece.
    `tipo` ∈ {"actor", "locacion", "tecnico", "equipamiento"}.
    """
    return sum(dias_de_jornada(jornadas[i])
               for i in jornadas_de_recurso(nombre, tipo, jornadas))


def jornadas_de_recurso(nombre: str, tipo: str,
                        jornadas: list["Jornada"]) -> list[int]:
    """Índices de las jornadas donde aparece este recurso (en el orden
    de la Carta Gantt). `tipo` como en dias_de_recurso_en_jornadas."""
    n = nombre.strip().upper()
    if not n:
        return []
    out: list[int] = []
    for i, j in enumerate(jornadas):
        if tipo == "actor":
            recursos = {x.upper() for x in _parse_csv_nombres(j.actores)}
        elif tipo == "locacion":
            recursos = set()
            if j.lugar:
                recursos.add(j.lugar.strip().upper())
            if j.lugar_2:
                recursos.add(j.lugar_2.strip().upper())
        elif tipo == "tecnico":
            recursos = {x.upper() for x in _parse_csv_nombres(j.tecnicos)}
        elif tipo == "equipamiento":
            recursos = {x.upper() for x in _parse_csv_nombres(j.equipamiento)}
        else:
            recursos = set()
        if n in recursos:
            out.append(i)
    return out


def parse_precio(s: str) -> float:
    """Convierte '$120.000', '120000', '120,000.50' → float."""
    if not s:
        return 0.0
    limpio = re.sub(r"[^\d.,-]", "", str(s))
    # Si hay coma y punto, asumimos formato CL: '.' = miles, ',' = decimal
    if "," in limpio and "." in limpio:
        limpio = limpio.replace(".", "").replace(",", ".")
    elif "," in limpio:
        # Solo coma: si tiene 2+ dígitos después, es decimal (',50'); si no, miles
        partes = limpio.split(",")
        if len(partes[-1]) <= 2:
            limpio = partes[0] + "." + partes[-1]
        else:
            limpio = limpio.replace(",", "")
    elif "." in limpio:
        # Solo punto: si tiene 1-2 dígitos después, decimal; si no, miles CL
        partes = limpio.split(".")
        if len(partes[-1]) > 2:
            limpio = limpio.replace(".", "")
    try:
        return float(limpio)
    except ValueError:
        return 0.0


