class _AvisoPremisa(QObject):
    """🎯 La premisa es una sola: si se escribe en la Escaleta, aparece en
    la Pizarra de beats, y al revés (las dos ventanas escuchan este aviso)."""
    cambio = Signal(object, object)          # (documento, el editor que la cambió)


AVISO_PREMISA: Optional[_AvisoPremisa] = None


def aviso_premisa() -> _AvisoPremisa:
    global AVISO_PREMISA
    if AVISO_PREMISA is None:
        AVISO_PREMISA = _AvisoPremisa()
    return AVISO_PREMISA


def poner_premisa(doc, texto: str, origen=None) -> None:
    """Cambia la premisa del proyecto y avisa a las ventanas abiertas."""
    doc.premisa = texto
    aviso_premisa().cambio.emit(doc, origen)


def editor_premisa(doc, alto_px: int, parent=None) -> QPlainTextEdit:
    """🎯 El campo de la premisa (el mismo en la Escaleta y en la Pizarra de
    beats): lo que se escribe en uno aparece en el otro al tiro."""
    ed = QPlainTextEdit(parent)
    ed.setFixedHeight(alto_px)
    ed.setAccessibleName("Premisa")                 # (♿ «premisa, …» con la ventana abierta)
    ed.setPlaceholderText(
        "Tu historia en 1 o 2 frases: QUIÉN quiere QUÉ, qué se "
        "le OPONE y qué pierde si falla. Ej: «Una alumna tímida "
        "debe llenar el gimnasio con la última función del "
        "taller de cine, o lo cerrarán para siempre».")
    ed.setPlainText(getattr(doc, "premisa", "") or "")
    ed.setStyleSheet(
        "QPlainTextEdit { background: #1a2636; color: #e8edf4; "
        "border: 1px solid #26344a; border-radius: 8px; "
        "padding: 8px 11px; font-size: 10pt; } "
        "QPlainTextEdit:focus { border: 1px solid #ff8c1a; }")
    ed.textChanged.connect(lambda: poner_premisa(doc, ed.toPlainText(), ed))

    def de_afuera(doc_, origen) -> None:
        if doc_ is not doc or origen is ed:
            return
        try:
            texto = getattr(doc, "premisa", "") or ""
            if ed.toPlainText() == texto:
                return
            pos = ed.textCursor().position()
            ed.blockSignals(True)
            ed.setPlainText(texto)
            c = ed.textCursor()
            c.setPosition(min(pos, len(texto)))
            ed.setTextCursor(c)
            ed.blockSignals(False)
        except RuntimeError:                  # (la ventana ya se cerró)
            pass
    aviso_premisa().cambio.connect(de_afuera)
    ed.destroyed.connect(lambda *_: _desconectar_premisa(de_afuera))
    return ed


def _desconectar_premisa(fn) -> None:
    try:
        aviso_premisa().cambio.disconnect(fn)
    except (RuntimeError, TypeError):
        pass


class VentanaEscaleta(QDialog):
    """Diálogo para gestionar la escaleta del guion."""

    # Señal emitida cuando el usuario pide enviar al guion.
    enviar_solicitado = Signal(list)  # list[str] de puntos

    def __init__(self, documento: "Documento", parent=None):
        super().__init__(parent)
        self.documento = documento
        self.setWindowTitle("Escaleta — Estructura narrativa")
        habilitar_snap(self, "📋")
        self.resize(px(720), px(620))

        layout = QVBoxLayout(self)
        layout.setContentsMargins(px(16), px(14), px(16), px(14))
        layout.setSpacing(px(10))

        # Cabezal
        titulo = QLabel("✏  Escaleta del guion")
        titulo.setStyleSheet(
            "color: #ff8c1a; font-size: 18pt; font-weight: bold;")
        layout.addWidget(titulo)

        sub = QLabel(
            "Diseña la estructura narrativa antes de escribir el guion: "
            "cada punto es un momento de la historia, con tus palabras "
            "(todavía no son escenas, así que no llevan INT./EXT.). Cuando "
            "estés conforme, «Enviar al guion» pone cada punto en la hoja "
            "como una guía para escribir debajo sus escenas.")
        sub.setWordWrap(True)
        sub.setStyleSheet("color: #b0bcd2; font-size: 9pt;")
        layout.addWidget(sub)

        # ── PREMISA: la historia en dos frases ──────────────────
        fila_prem = QHBoxLayout()
        lbl_prem = QLabel("🎯  PREMISA")
        lbl_prem.setStyleSheet(
            "color: #ffb066; font-size: 11pt; font-weight: 800;")
        fila_prem.addWidget(lbl_prem)
        fila_prem.addStretch()
        btn_circulo = QPushButton("🧭 El Círculo del Protagonista")
        btn_circulo.setToolTip(
            "Mini-tutorial de estructura narrativa: el recorrido "
            "clásico que siguen casi todas las grandes historias, "
            "con un ejemplo completo para tu primer guion.")
        btn_circulo.clicked.connect(self._tutorial_circulo)
        fila_prem.addWidget(btn_circulo)
        layout.addLayout(fila_prem)

        self._ed_premisa = editor_premisa(self.documento, px(64), self)
        self._ed_premisa.setToolTip("Es la misma premisa de la 🧩 Pizarra de beats: lo que escribas "
                                    "aquí aparece allá, y al revés.")
        layout.addWidget(self._ed_premisa)

        # Lista de puntos
        self.lista = QListWidget()
        self.lista.setStyleSheet(f"""
            QListWidget {{
                background: #131d2b;
                color: #e8edf4;
                border: 1px solid #3a4665;
                border-radius: 4px;
                font-size: 11pt;
                padding: 4px;
            }}
            QListWidget::item {{
                padding: 9px 12px;
                border-bottom: 1px solid #22314a;
                border-radius: 6px;
            }}
            QListWidget::item:hover {{
                background: #1a2636;
            }}
            QListWidget::item:selected {{
                background: #3a2410;
                color: #ffb066;
                border-left: 3px solid #ff8c1a;
            }}
        """)
        self.lista.setSelectionMode(
            QListWidget.SelectionMode.SingleSelection)
        self.lista.itemDoubleClicked.connect(self._editar)
        # Reordenar arrastrando, igual que el Editor de escenas
        self.lista.setDragDropMode(
            QListWidget.DragDropMode.InternalMove)
        self.lista.setDefaultDropAction(Qt.DropAction.MoveAction)
        self.lista.model().rowsMoved.connect(self._tras_arrastre)
        layout.addWidget(self.lista, 1)

        # Toolbar de acciones
        bar = QHBoxLayout()
        bar.setSpacing(px(6))

        def boton(texto: str, slot, color: str = None) -> QPushButton:
            b = QPushButton(texto)
            if color:
                b.setStyleSheet(f"""
                    QPushButton {{
                        background: {color};
                        color: #241203;
                        font-weight: 700;
                        padding: 8px 16px;
                        border-radius: 8px;
                        border: none;
                    }}
                    QPushButton:hover {{
                        background: #ffa64d;
                    }}
                """)
            b.clicked.connect(slot)
            return b

        bar.addWidget(boton("➕  Nuevo punto",  self._nuevo))
        bar.addWidget(boton("✏  Editar",       self._editar))
        bar.addWidget(boton("🗑  Eliminar",    self._eliminar))
        bar.addWidget(boton("⬆",                self._subir))
        bar.addWidget(boton("⬇",                self._bajar))
        bar.addWidget(boton("❓ Tutorial",      self._tutorial))
        bar.addStretch()
        bar.addWidget(boton("👁  Ver escenas del guion", self._ver_escenas))
        bar.addWidget(boton("📜  Enviar al guion →",
                            self._enviar, "#ff8c1a"))
        layout.addLayout(bar)

        # Cerrar
        cerrar = QPushButton("Cerrar")
        cerrar.clicked.connect(self.accept)
        h2 = QHBoxLayout()
        h2.addStretch()
        h2.addWidget(cerrar)
        layout.addLayout(h2)

        # Refrescar
        self._refrescar()

        # Abrir tutorial automáticamente la primera vez que el usuario
        # abre la Escaleta. Después no se abre solo — puede abrirlo con
        # el botón ❓ Tutorial. Se recuerda en QSettings.
        s = settings_app()
        if not s.value("tutorial_escaleta_visto", False, type=bool):
            QTimer.singleShot(400, self._tutorial)
            s.setValue("tutorial_escaleta_visto", True)

    # ─── operaciones ──────────────────────────────────────────────────

    def _premisa_cambio(self) -> None:
        poner_premisa(self.documento, self._ed_premisa.toPlainText(), self._ed_premisa)

    def _tutorial_circulo(self) -> None:
        """Mini-tutorial propio de la Escaleta: el recorrido
        narrativo clásico, contado con un ejemplo completo."""
        pasos = pasos_circulo_protagonista()
        tut = TutorialFlotante("El Círculo del Protagonista",
                               pasos, self)
        tut.show()

    def _tras_arrastre(self, *args) -> None:
        """Tras arrastrar un ítem, reconstruye documento.escaleta en
        el nuevo orden visual (los textos viajan en UserRole)."""
        nuevos = []
        for k in range(self.lista.count()):
            dato = self.lista.item(k).data(Qt.ItemDataRole.UserRole)
            if dato:
                nuevos.append(dato)
        if nuevos:
            self.documento.escaleta = nuevos
            self._refrescar()


    def _refrescar(self) -> None:
        self.lista.clear()
        for n, punto in enumerate(self.documento.escaleta, start=1):
            # (todos son puntos: en la escaleta todavía no hay escenas)
            item = QListWidgetItem(f"📝  {n:02d}.  {punto}")
            item.setForeground(QColor("#d6deea"))
            item.setData(Qt.ItemDataRole.UserRole, punto)
            self.lista.addItem(item)

    def _indice_actual(self) -> int:
        row = self.lista.currentRow()
        return row if row >= 0 else -1

    def _tutorial(self) -> None:
        """Abre el tutorial interactivo de la Escaleta."""
        self._tut = TutorialFlotante(
            "❓ Tutorial de la Escaleta",
            _pasos_tutorial_escaleta(),
            parent=self)
        self._tut.show()

    def _nuevo(self) -> None:
        texto, ok = QInputDialog.getMultiLineText(
            self, "Nuevo punto de la escaleta",
            "Un momento de la historia, con tus palabras (por ejemplo: "
            "«Michelle encuentra la libreta del director»).\n"
            "No hace falta INT./EXT.: las escenas nacen después, al "
            "escribir el guion.")
        if ok and texto.strip():
            self.documento.escaleta.append(texto.strip())
            self._refrescar()
            self.lista.setCurrentRow(len(self.documento.escaleta) - 1)

    def _editar(self) -> None:
        i = self._indice_actual()
        if i < 0:
            return
        texto, ok = QInputDialog.getMultiLineText(
            self, "Editar punto de la escaleta",
            "Edita el contenido:",
            self.documento.escaleta[i])
        if ok and texto.strip():
            self.documento.escaleta[i] = texto.strip()
            self._refrescar()
            self.lista.setCurrentRow(i)

    def _eliminar(self) -> None:
        i = self._indice_actual()
        if i < 0:
            return
        r = QMessageBox.question(
            self, "Eliminar punto",
            f"¿Eliminar el punto {i+1}?\n\n«{self.documento.escaleta[i][:60]}…»",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
        )
        if r == QMessageBox.StandardButton.Yes:
            self.documento.escaleta.pop(i)
            self._refrescar()

    def _subir(self) -> None:
        i = self._indice_actual()
        if i <= 0:
            return
        lst = self.documento.escaleta
        lst[i-1], lst[i] = lst[i], lst[i-1]
        self._refrescar()
        self.lista.setCurrentRow(i - 1)

    def _bajar(self) -> None:
        i = self._indice_actual()
        if i < 0 or i >= len(self.documento.escaleta) - 1:
            return
        lst = self.documento.escaleta
        lst[i+1], lst[i] = lst[i], lst[i+1]
        self._refrescar()
        self.lista.setCurrentRow(i + 1)

    def _enviar(self) -> None:
        if not self.documento.escaleta:
            QMessageBox.information(
                self, "Escaleta vacía",
                "No hay puntos para enviar. Agrega al menos uno primero.")
            return
        r = QMessageBox.question(
            self, "Enviar al guion",
            f"¿Insertar {len(self.documento.escaleta)} punto(s) al final "
            f"del guion?\n\nCada punto queda en la hoja como una guía "
            f"[ESCALETA n] para escribir debajo sus escenas (cuando ya "
            f"no la necesites, la borras).",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
        )
        if r == QMessageBox.StandardButton.Yes:
            self.enviar_solicitado.emit(list(self.documento.escaleta))
            QMessageBox.information(
                self, "✓ Enviado",
                f"{len(self.documento.escaleta)} punto(s) insertados al "
                f"final del guion.")

    def _ver_escenas(self) -> None:
        """Muestra las escenas YA escritas en el guion (read-only)."""
        escenas = _escenas_del_documento(self.documento)
        if not escenas:
            QMessageBox.information(
                self, "Escenas del guion",
                "Aún no hay escenas escritas. Las escenas aparecen "
                "aquí cuando el guion tiene encabezados de escena.")
            return
        texto = "📑  Escenas escritas en el guion:\n\n" + "\n".join(
            f"  #{n:02d}.  {enc[:80]}" for n, enc in escenas
        )
        dlg = QMessageBox(self)
        dlg.setWindowTitle("Escenas del guion")
        dlg.setText(texto)
        dlg.setStandardButtons(QMessageBox.StandardButton.Ok)
        dlg.exec()


# ═══════════════════════════════════════════════════════════════════════
# §8.88  PIZARRA DE BEATS (planificación con tarjetas arrastrables)
# ═══════════════════════════════════════════════════════════════════════
#
# Implementación con QGraphicsScene + QGraphicsView. Cada tarjeta es un
# QGraphicsItem custom que dibuja un rectángulo con cabecera de color,
# título y descripción. Las tarjetas se pueden arrastrar con el mouse,
# y se pueden conectar entre ellas con flechas para mostrar el orden o
# las relaciones entre los beats narrativos.

# Paleta para asignar color por categoría de tag (índice → color)
PALETA_TAGS = [
    "#e8a33d", "#3d6df2", "#2f9e5e", "#d94f72", "#9b59b6",
    "#16a3a3", "#e0673e", "#7e8d3a", "#c0392b", "#2c7fb8",
    "#d4a017", "#5b8c5a", "#a0522d", "#4682b4", "#8b5a8b",
    "#6b8e23", "#cd5c5c", "#4169e1",
]


def color_de_categoria(cid: str) -> str:
    """Color estable por id de categoría (según su orden en CATEGORIAS_TAG)."""
    ids = [c[0] for c in CATEGORIAS_TAG]
    try:
        idx = ids.index(cid)
    except ValueError:
        idx = abs(hash(cid)) % len(PALETA_TAGS)
    return PALETA_TAGS[idx % len(PALETA_TAGS)]


class DialogoEditarTag(QDialog):
    """Diálogo para editar un tag existente:
    - Ícono personalizado (emoji opcional)
    - Detalle (texto)
    - Fotos (múltiples, cada una con su comentario)
    """

    def __init__(self, tag: dict, parent=None):
        super().__init__(parent)
        self._tag = tag
        # Asegurar que existan los campos nuevos en tags viejos
        if "icono" not in tag:
            tag["icono"] = ""
        if "fotos" not in tag:
            tag["fotos"] = []
        self.setWindowTitle("Editar tag")
        self.setMinimumSize(px(560), px(560))
        self.setStyleSheet("""
            QDialog { background: #131d2b; }
            QLabel { color: #e8edf4; font-size: 10pt; }
            QLineEdit, QPlainTextEdit {
                background: #1a2636; border: 1px solid #26344a;
                border-radius: 4px; padding: 6px 10px; font-size: 10pt;
                color: #e8edf4;
            }
            QLineEdit:focus, QPlainTextEdit:focus {
                border: 1px solid #ff8c1a;
            }
            QPushButton {
                padding: 6px 12px; border: 1px solid #26344a;
                border-radius: 4px; background: #1a2636;
            }
            QPushButton:hover { background: #e7edf5; }
        """)

        v = QVBoxLayout(self)
        v.setContentsMargins(px(16), px(14), px(16), px(14))
        v.setSpacing(px(8))

        # Título editable
        v.addWidget(QLabel("<b>Título:</b>"))
        self._in_titulo = QLineEdit(tag.get("contenido", ""))
        self._in_titulo.setPlaceholderText(
            "ej: Reloj de pared antiguo, Sombrero de copa…")
        v.addWidget(self._in_titulo)

        # Ícono (emoji)
        v.addSpacing(px(4))
        v.addWidget(QLabel("<b>Ícono:</b>  <span style='color:#6a7280;font-size:9pt;'>"
                           "(opcional — un emoji para distinguirlo)</span>"))
        fila_icono = QHBoxLayout()
        self._in_icono = QLineEdit(tag.get("icono", ""))
        self._in_icono.setPlaceholderText("ej: 🕰  🎩  🚗")
        self._in_icono.setMaxLength(4)  # 1 emoji típicamente 2-4 bytes
        self._in_icono.setMaximumWidth(px(80))
        fila_icono.addWidget(self._in_icono)
        b_elegir_emoji = QPushButton("😀  Elegir…")
        b_elegir_emoji.clicked.connect(self._elegir_icono)
        fila_icono.addWidget(b_elegir_emoji)
        fila_icono.addStretch()
        v.addLayout(fila_icono)

        # Detalle largo (comentario general)
        v.addSpacing(px(4))
        v.addWidget(QLabel("<b>Detalle:</b>  <span style='color:#6a7280;font-size:9pt;'>"
                           "(observaciones, especificaciones)</span>"))
        self._in_detalle = QPlainTextEdit(tag.get("detalle", ""))
        self._in_detalle.setPlaceholderText(
            "Ej: Debe ser un reloj con péndulo. Época 1900. Comprar en anticuario "
            "o alquilar en utilería Escenografía Chile.")
        self._in_detalle.setFixedHeight(px(80))
        v.addWidget(self._in_detalle)

        # ── Costo y tipo de compra ────────────────────────────
        v.addSpacing(px(4))
        v.addWidget(QLabel(
            "<b>Costo:</b>  <span style='color:#6a7280;font-size:9pt;'>"
            "(en pesos, se suma a los costos de producción)</span>"))
        fila_costo = QHBoxLayout()
        self._in_valor = QLineEdit(str(tag.get("valor", "") or ""))
        self._in_valor.setPlaceholderText("Ej: 50000")
        self._in_valor.setMaximumWidth(px(160))
        # Validator numérico simple: aceptar solo dígitos
        self._in_valor.setInputMask("")
        fila_costo.addWidget(self._in_valor)
        fila_costo.addWidget(QLabel("<span style='color:#6a7280;'>tipo:</span>"))
        self._in_tipo_compra = QComboBox()
        self._in_tipo_compra.addItem("Compra única",           "unica")
        self._in_tipo_compra.addItem("Cantidad específica",    "cantidad")
        self._in_tipo_compra.addItem("Compra diaria (por día de rodaje)",
                                      "diaria")
        tipo_actual = tag.get("tipo_compra", "unica")
        for i in range(self._in_tipo_compra.count()):
            if self._in_tipo_compra.itemData(i) == tipo_actual:
                self._in_tipo_compra.setCurrentIndex(i)
                break
        self._in_tipo_compra.currentIndexChanged.connect(
            self._actualizar_visibilidad_cantidad)
        fila_costo.addWidget(self._in_tipo_compra)
        fila_costo.addStretch()
        v.addLayout(fila_costo)

        # Fila para cantidad (visible solo si tipo == "cantidad")
        fila_cantidad = QHBoxLayout()
        self._lbl_cantidad = QLabel(
            "<span style='color:#6a7280;'>Cantidad:</span>")
        fila_cantidad.addWidget(self._lbl_cantidad)
        self._in_cantidad = QSpinBox()
        self._in_cantidad.setRange(1, 9999)
        self._in_cantidad.setValue(int(tag.get("cantidad", 1) or 1))
        self._in_cantidad.setMaximumWidth(px(100))
        fila_cantidad.addWidget(self._in_cantidad)
        self._lbl_ayuda_cantidad = QLabel(
            "<span style='color:#6a7280;font-size:9pt;'>"
            "El costo total será: costo × cantidad</span>")
        fila_cantidad.addWidget(self._lbl_ayuda_cantidad)
        fila_cantidad.addStretch()
        v.addLayout(fila_cantidad)
        # Aplicar visibilidad inicial
        self._actualizar_visibilidad_cantidad()

        # Fotos (múltiples)
        v.addSpacing(px(4))
        v.addWidget(QLabel("<b>Fotos de referencia:</b>"))
        # Usar la clase GaleriaFotos que ya existe para fichas.
        # Convertir las dicts de fotos guardadas a objetos Foto en memoria.
        self._fotos_objs: list[Foto] = []
        for f in tag.get("fotos", []):
            self._fotos_objs.append(Foto(
                datos=f.get("datos", ""),
                comentario=f.get("comentario", ""),
                titulo=f.get("titulo", ""),
            ))
        self._galeria = GaleriaFotos(self._fotos_objs, parent=self)
        v.addWidget(self._galeria, 1)

        # Botones
        botones = QDialogButtonBox(
            QDialogButtonBox.StandardButton.Save |
            QDialogButtonBox.StandardButton.Cancel
        )
        botones.button(QDialogButtonBox.StandardButton.Save).setText("💾  Guardar")
        botones.accepted.connect(self._guardar_y_cerrar)
        botones.rejected.connect(self.reject)
        v.addWidget(botones)

    def _elegir_icono(self) -> None:
        dlg = DialogoSelectorEmoji(self)
        if dlg.exec() == QDialog.DialogCode.Accepted:
            self._in_icono.setText(dlg.emoji_elegido())

    def _actualizar_visibilidad_cantidad(self) -> None:
        """Muestra/oculta la fila de cantidad según el tipo elegido."""
        tipo = self._in_tipo_compra.currentData()
        visible = (tipo == "cantidad")
        self._lbl_cantidad.setVisible(visible)
        self._in_cantidad.setVisible(visible)
        self._lbl_ayuda_cantidad.setVisible(visible)

    def _guardar_y_cerrar(self) -> None:
        """Copia los valores de los widgets al tag y cierra."""
        self._tag["contenido"] = self._in_titulo.text().strip() or "(sin detalle)"
        self._tag["icono"] = self._in_icono.text().strip()
        self._tag["detalle"] = self._in_detalle.toPlainText().strip()
        # Costo y tipo de compra
        valor_str = self._in_valor.text().strip()
        # Limpiar formato (puntos, comas, símbolos) — dejar solo dígitos
        valor_limpio = "".join(c for c in valor_str if c.isdigit())
        self._tag["valor"] = valor_limpio
        self._tag["tipo_compra"] = self._in_tipo_compra.currentData()
        self._tag["cantidad"] = int(self._in_cantidad.value())
        # Convertir Foto objs a dicts para persistir
        self._tag["fotos"] = [
            {
                "datos":      f.datos,
                "comentario": f.comentario,
                "titulo":     f.titulo,
            }
            for f in self._fotos_objs
        ]
        self.accept()


class VentanaTags(QDialog):
    """Sistema de TAGS estilo estándar de la industria + el original ¡Acción!.

    Panel de dos columnas:
      · Izquierda: lista de ESCENAS del guion (cada encabezado).
      · Derecha: para la escena seleccionada, las tags agrupadas por
        categoría (Actor principal, Extras, Utilería, Vestuario,
        Vehículos, Efectos, Sonido, Música, Locación, etc.), con
        botones para agregar y quitar.

    Las tags se guardan en los bloques que componen la escena (el
    encabezado y todo lo que va hasta el siguiente encabezado), en el
    mismo formato {"cat": id, "texto": str} que ya usa el editor, así
    que son 100% compatibles con el etiquetado por bloque y con el
    informe de desglose.
    """

    def __init__(self, documento: "Documento", parent=None):
        super().__init__(parent)
        self.documento = documento
        self.setWindowTitle("TAGS — Desglose de producción por escena")
        self.resize(px(940), px(640))
        # Índices de bloques que son encabezado de escena
        self._escenas: list[int] = []      # idx del bloque ENCABEZADO
        self._escena_actual: int = -1      # idx en self._escenas

        cont = QHBoxLayout(self)
        cont.setContentsMargins(px(14), px(12), px(14), px(12))
        cont.setSpacing(px(10))

        # ── Columna izquierda: lista de escenas ──
        col_izq = QVBoxLayout()
        col_izq.setSpacing(px(6))
        lbl_esc = QLabel("🎬  Escenas")
        lbl_esc.setStyleSheet(
            "color: #ff8c1a; font-size: 13pt; font-weight: bold;")
        col_izq.addWidget(lbl_esc)

        self.lista_escenas = QListWidget()
        self.lista_escenas.setMinimumWidth(px(300))
        self.lista_escenas.setStyleSheet(f"""
            QListWidget {{ background: #131d2b; color: #e8edf4;
                border: 1px solid #3a4665; border-radius: 4px;
                font-size: 10pt; }}
            QListWidget::item {{ padding: 8px 10px;
                border-bottom: 1px solid #e0ddd0; }}
            QListWidget::item:selected {{ background: #ff8c1a; color: #241203; }}
        """)
        self.lista_escenas.currentRowChanged.connect(self._al_elegir_escena)
        col_izq.addWidget(self.lista_escenas, 1)
        cont.addLayout(col_izq, 0)

        # ── Columna derecha: tags de la escena ──
        col_der = QVBoxLayout()
        col_der.setSpacing(px(6))
        self.lbl_escena_sel = QLabel("Selecciona una escena")
        self.lbl_escena_sel.setStyleSheet(
            "color: #ff8c1a; font-size: 13pt; font-weight: bold;")
        self.lbl_escena_sel.setWordWrap(True)
        col_der.addWidget(self.lbl_escena_sel)

        # Barra de agregar tag
        fila_add = QHBoxLayout()
        self.combo_cat = QComboBox()
        for cid, nombre, emoji in CATEGORIAS_TAG:
            self.combo_cat.addItem(f"{emoji}  {nombre}", cid)
        # Categorías custom del PROYECTO (guardadas en el .accion)
        try:
            for c in getattr(self.documento, "categorias_custom", []) or []:
                cid_c = c.get("id", "")
                nombre_c = c.get("nombre", "")
                emoji_c = c.get("emoji", "🏷") or "🏷"
                if cid_c and cid_c not in [x[0] for x in CATEGORIAS_TAG]:
                    self.combo_cat.addItem(f"{emoji_c}  {nombre_c}", cid_c)
        except Exception:
            pass
        self.combo_cat.setStyleSheet(self._combo_style())
        fila_add.addWidget(self.combo_cat, 0)

        self.input_tag = QLineEdit()
        self.input_tag.setPlaceholderText(
            "Detalle (ej: Michelle, Reloj antiguo, Volkswagen verde…)")
        self.input_tag.setStyleSheet(
            f"QLineEdit {{ background: #1a2636; color: #e8edf4; "
            f"border: 1px solid #3a4665; border-radius: 3px; "
            f"padding: 6px; }}")
        self.input_tag.returnPressed.connect(self._agregar_tag)
        fila_add.addWidget(self.input_tag, 1)

        b_add = QPushButton("➕ Agregar")
        b_add.setStyleSheet(
            "QPushButton { background: #e8760a; color: #e8edf4; "
            f"font-weight: bold; padding: 6px 12px; "
            f"border: none; border-radius: 3px; }}")
        b_add.clicked.connect(self._agregar_tag)
        fila_add.addWidget(b_add, 0)
        col_der.addLayout(fila_add)

        # Área de tags agrupadas por categoría
        self.area_tags = QScrollArea()
        self.area_tags.setWidgetResizable(True)
        self.area_tags.setStyleSheet(
            f"QScrollArea {{ background: #131d2b; "
            f"border: 1px solid #3a4665; border-radius: 4px; }}")
        self._cont_tags = QWidget()
        self._cont_tags.setStyleSheet("background: #131d2b;")
        self._lay_tags = QVBoxLayout(self._cont_tags)
        self._lay_tags.setContentsMargins(px(10), px(10), px(10), px(10))
        self._lay_tags.setSpacing(px(8))
        self._lay_tags.addStretch()
        self.area_tags.setWidget(self._cont_tags)
        col_der.addWidget(self.area_tags, 1)

        cont.addLayout(col_der, 1)

        # Cargar escenas
        self._cargar_escenas()
        # Botón cerrar flotante abajo a la derecha de la columna derecha
        fila_cerrar = QHBoxLayout()
        fila_cerrar.addStretch()
        b_cerrar = QPushButton("Cerrar")
        b_cerrar.clicked.connect(self.accept)
        fila_cerrar.addWidget(b_cerrar)
        col_der.addLayout(fila_cerrar)

        # Modo invitado: readonly total
        activo, motivo = modo_readonly_activo(self)
        if activo:
            aplicar_readonly_a_dialogo(self)
            etiqueta = ("👁 Solo lectura (invitado)"
                        if "invitado" in motivo
                        else "🔒 Solo lectura (archivo protegido)")
            self.setWindowTitle(self.windowTitle() + "  —  " + etiqueta)

    def _combo_style(self) -> str:
        return (
            f"QComboBox {{ background: #1a2636; color: #e8edf4; "
            f"border: 1px solid #3a4665; border-radius: 3px; "
            f"padding: 6px; min-width: 170px; }}"
            "QComboBox QAbstractItemView { background: #1a2636; "
            "color: #241203; selection-background-color: #ff8c1a; "
            "selection-color: #1a2636; }"
        )

    # ── Escenas ───────────────────────────────────────────────────────

    def _cargar_escenas(self) -> None:
        self.lista_escenas.clear()
        self._escenas = []
        n = 0
        for i, b in enumerate(self.documento.bloques):
            if b.elem == Elem.ESCENA and b.texto.strip():
                n += 1
                self._escenas.append(i)
                # Contar tags de esta escena para mostrar en la lista
                n_tags = self._contar_tags_escena(i)
                badge = f"  🏷×{n_tags}" if n_tags else ""
                item = QListWidgetItem(f"{n}. {b.texto.strip()[:40]}{badge}")
                self.lista_escenas.addItem(item)
        if not self._escenas:
            self.lista_escenas.addItem("(no hay escenas en el guion)")

    def _rango_escena(self, idx_en_escenas: int) -> range:
        """Devuelve el rango de índices de bloques que componen una
        escena: desde su encabezado hasta el siguiente encabezado."""
        ini = self._escenas[idx_en_escenas]
        if idx_en_escenas + 1 < len(self._escenas):
            fin = self._escenas[idx_en_escenas + 1]
        else:
            fin = len(self.documento.bloques)
        return range(ini, fin)

    def _contar_tags_escena(self, idx_bloque_ini: int) -> int:
        pos = self._escenas.index(idx_bloque_ini)
        total = 0
        for i in self._rango_escena(pos):
            # Contar solo tags de producción (excluir notas)
            for t in self.documento.bloques[i].tags:
                if t.get("categoria") != "nota":
                    total += 1
        return total

    def _al_elegir_escena(self, row: int) -> None:
        if not (0 <= row < len(self._escenas)):
            return
        self._escena_actual = row
        idx_b = self._escenas[row]
        self.lbl_escena_sel.setText(
            f"🎬 {self.documento.bloques[idx_b].texto.strip()}")
        self._refrescar_tags()

    # ── Tags ──────────────────────────────────────────────────────────

    def _tags_de_escena(self) -> list[tuple[int, int, dict]]:
        """Devuelve [(idx_bloque, idx_tag, tag_dict)] de la escena actual."""
        if self._escena_actual < 0:
            return []
        out = []
        for i in self._rango_escena(self._escena_actual):
            for j, t in enumerate(self.documento.bloques[i].tags):
                out.append((i, j, t))
        return out

    def _refrescar_tags(self) -> None:
        # Limpiar el layout (menos el stretch final)
        while self._lay_tags.count() > 1:
            item = self._lay_tags.takeAt(0)
            w = item.widget()
            if w:
                w.deleteLater()

        # Agrupar por categoría. IMPORTANTE: ignorar las notas
        # (categoria="nota"), que se muestran en el Panel de notas
        # aparte, no en este desglose de producción.
        por_cat: dict[str, list[tuple[int, int, dict]]] = {}
        for (ib, jt, t) in self._tags_de_escena():
            cat = t.get("categoria", "?")
            if cat == "nota":
                continue
            por_cat.setdefault(cat, []).append((ib, jt, t))

        if not por_cat:
            vacio = QLabel("Esta escena no tiene tags todavía.\n"
                           "Agrega arriba lo que necesita: actores, "
                           "utilería, vestuario, vehículos, etc.")
            vacio.setStyleSheet("color: #8a8578; font-size: 10pt; "
                                "padding: 12px;")
            vacio.setWordWrap(True)
            self._lay_tags.insertWidget(0, vacio)
            return

        # Mostrar en el orden de CATEGORIAS_TAG (built-in primero)
        orden = [c[0] for c in CATEGORIAS_TAG]
        # Diccionario merged de built-in + custom del proyecto
        cats_merged: dict[str, tuple[str, str]] = dict(CATEGORIAS_DICT)
        for c in getattr(self.documento, "categorias_custom", []) or []:
            cid_c = c.get("id", "")
            if cid_c:
                cats_merged[cid_c] = (
                    c.get("nombre", cid_c),
                    c.get("emoji", "🏷") or "🏷")
        for cid in sorted(por_cat, key=lambda c: orden.index(c)
                          if c in orden else 999):
            nombre, emoji = cats_merged.get(cid, (cid, "🏷"))
            color = color_de_categoria(cid)
            # Cabecera de categoría
            cab = QLabel(f"{emoji}  {nombre}")
            cab.setStyleSheet(
                f"color: #e8edf4; background: {color}; "
                f"font-weight: bold; font-size: 10pt; "
                f"padding: 4px 10px; "
                f"border-radius: 3px;")
            self._lay_tags.insertWidget(self._lay_tags.count() - 1, cab)
            # Chips de cada tag
            for (ib, jt, t) in por_cat[cid]:
                fila = QWidget()
                fl = QHBoxLayout(fila)
                fl.setContentsMargins(px(16), px(2), px(4), px(2))
                # Ícono personalizado del tag (opcional)
                icono_tag = t.get("icono", "").strip()
                txt = t.get("contenido", "").strip() or "(sin detalle)"
                if icono_tag:
                    lab = QLabel(f"{icono_tag}  {txt}")
                else:
                    lab = QLabel(f"•  {txt}")
                lab.setStyleSheet("color: #e8edf4; font-size: 10pt;")
                fl.addWidget(lab, 1)
                # Cantidad de fotos (indicador)
                n_fotos = len(t.get("fotos", []))
                if n_fotos > 0:
                    lbl_fotos = QLabel(f"📷 {n_fotos}")
                    lbl_fotos.setStyleSheet(
                        "color: #ff8c1a; font-size: 9pt; padding: 0 6px;")
                    fl.addWidget(lbl_fotos)
                # Botón editar (fotos, icono, detalle)
                b_edit = QPushButton()
                b_edit.setText("✎  Editar")
                b_edit.setToolTip("Editar tag: agregar ícono, fotos, comentarios")
                b_edit.setStyleSheet(
                    "QPushButton { background: #1a2636; color: #e8edf4; "
                    "border: 1px solid #26344a; "
                    f"border-radius: 4px; padding: 3px 8px; "
                    "font-size: 9pt; font-weight: bold; }"
                    "QPushButton:hover { background: #e7edf5; "
                    "border-color: #ff8c1a; }")
                b_edit.clicked.connect(
                    lambda _, bi=ib, tj=jt: self._editar_tag(bi, tj))
                fl.addWidget(b_edit, 0)
                # Botón borrar (basurero)
                b_x = QPushButton()
                b_x.setText("🗑  Borrar")
                b_x.setToolTip("Eliminar este tag")
                b_x.setStyleSheet(
                    "QPushButton { background: #1a2636; color: #f87171; "
                    "border: 1px solid #26344a; "
                    f"border-radius: 4px; padding: 3px 8px; "
                    "font-size: 9pt; font-weight: bold; }"
                    "QPushButton:hover { background: #2a1720; "
                    "border-color: #f87171; }")
                b_x.clicked.connect(
                    lambda _, bi=ib, tj=jt: self._quitar_tag(bi, tj))
                fl.addWidget(b_x, 0)
                self._lay_tags.insertWidget(self._lay_tags.count() - 1, fila)

    def _agregar_tag(self) -> None:
        if self._escena_actual < 0:
            QMessageBox.information(
                self, "TAGS", "Selecciona primero una escena de la lista.")
            return
        cid = self.combo_cat.currentData()
        texto = self.input_tag.text().strip()
        # Permitir agregar tag sin detalle (algunos usuarios solo
        # quieren marcar la categoría, ej: "esta escena necesita VFX").
        if not texto:
            texto = "(sin detalle)"
        # Agregar el tag al bloque ENCABEZADO de la escena
        idx_b = self._escenas[self._escena_actual]
        tags = self.documento.bloques[idx_b].tags
        # Formato compatible con el resto del sistema:
        # categoria + contenido (no cat + texto).
        if not any(t.get("categoria") == cid and t.get("contenido") == texto
                   for t in tags):
            from datetime import datetime as _dt
            autor = self.documento.autor_id or ""
            tags.append({
                "categoria": cid,
                "contenido": texto,
                "autor":     autor,
                "fecha":     _dt.now().strftime("%Y-%m-%d"),
                "icono":     "",   # emoji personalizado opcional
                "fotos":     [],   # lista de {datos_b64, comentario}
            })
        self.input_tag.clear()
        self.input_tag.setFocus()
        self._refrescar_tags()
        self._actualizar_badge_escena()
        # Notificar cambio estructural para sincronización
        try:
            wp = self.window()
            if hasattr(wp, "editor"):
                wp.editor.estructura_cambiada.emit()
        except Exception:
            pass

    def _editar_tag(self, idx_bloque: int, idx_tag: int) -> None:
        """Abre un diálogo para editar el tag: ícono, detalle, y fotos."""
        try:
            tag = self.documento.bloques[idx_bloque].tags[idx_tag]
        except (IndexError, KeyError):
            return
        dlg = DialogoEditarTag(tag, parent=self)
        if dlg.exec() == QDialog.DialogCode.Accepted:
            # El diálogo modifica el tag en su lugar
            self._refrescar_tags()
            self._actualizar_badge_escena()
            # Notificar cambio estructural para sincronización
            try:
                wp = self.window()
                if hasattr(wp, "editor"):
                    wp.editor.estructura_cambiada.emit()
            except Exception:
                pass

    def _quitar_tag(self, idx_bloque: int, idx_tag: int) -> None:
        # 👥 Sin permiso de edición en la sesión: no se borran tags.
        if es_modo_invitado(self):
            QMessageBox.information(
                self, "👥 Sesión de colaboración",
                "Con tu permiso en esta sesión no puedes eliminar tags: "
                "pídeselo al host o a alguien que pueda editar.")
            return
        if es_modo_solo_lectura(self):
            QMessageBox.information(
                self, "🔒 Solo lectura",
                "Este archivo está abierto en modo solo lectura.\n\n"
                "No puedes eliminar tags. Vuelve a abrir el archivo "
                "ingresando el PIN para editar.")
            return
        try:
            tag = self.documento.bloques[idx_bloque].tags[idx_tag]
            contenido = tag.get("contenido", "(sin detalle)")
        except (IndexError, KeyError):
            return
        r = QMessageBox.question(
            self, "Eliminar tag",
            f"¿Eliminar el tag «{contenido}»?",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No)
        if r != QMessageBox.StandardButton.Yes:
            return
        try:
            self.documento.bloques[idx_bloque].tags.pop(idx_tag)
        except (IndexError, KeyError):
            pass
        self._refrescar_tags()
        self._actualizar_badge_escena()
        # Notificar cambio estructural para sincronización
        try:
            wp = self.window()
            if hasattr(wp, "editor"):
                wp.editor.estructura_cambiada.emit()
        except Exception:
            pass

    def _actualizar_badge_escena(self) -> None:
        """Refresca el contador 🏷×N en la lista de la izquierda sin
        recargar toda la lista (para no perder la selección)."""
        row = self._escena_actual
        if not (0 <= row < len(self._escenas)):
            return
        idx_b = self._escenas[row]
        n_tags = self._contar_tags_escena(idx_b)
        badge = f"  🏷×{n_tags}" if n_tags else ""
        texto = self.documento.bloques[idx_b].texto.strip()[:40]
        item = self.lista_escenas.item(row)
        if item:
            item.setText(f"{row + 1}. {texto}{badge}")


