class _TarjetaBeat(QGraphicsItem):
    """Tarjeta individual de la Pizarra de beats.

    Mecánica nueva (vs versión anterior):
      · 4 ganchos circulares (top/right/bot/left) en el centro de cada
        lado. Click + arrastrar desde un gancho dibuja una flecha que se
        engancha al gancho de otra tarjeta donde se suelte → crea
        conexión con dirección.
      · Resize manual desde la esquina inferior IZQUIERDA (handle con
        rayitas). El tamaño mínimo lo impone el texto: el ancho mínimo
        es el del título y el alto mínimo es el necesario para que la
        descripción entre completa con word-wrap al ancho actual.
      · Movimiento por click en el cuerpo (NO usamos ItemIsMovable
        porque queremos detectar primero si tocaste un gancho o el
        handle de resize).
      · Doble-click sobre el cuerpo abre el editor de la tarjeta.
    """

    HANDLE_R       = 7    # radio del círculo de gancho
    HANDLE_HOVER_R = 9    # radio al hovering (feedback)
    RESIZE_SZ      = 16   # lado del cuadrante de resize esquina izq-inf

    def __init__(self, beat: Beat, indice: int, ventana):
        super().__init__()
        self._beat = beat
        self._indice = indice
        self._ventana = ventana
        # NO usamos ItemIsMovable: manejo manual de eventos del mouse
        self.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsSelectable, True)
        self.setFlag(QGraphicsItem.GraphicsItemFlag.ItemSendsGeometryChanges, True)
        self.setAcceptHoverEvents(True)
        self.setPos(beat.x, beat.y)
        # Estado de interacción
        self._modo: Optional[str] = None  # None|"move"|"resize"|"arrow"
        self._lado_arrow: Optional[str] = None
        self._lado_hover: Optional[str] = None
        self._inicio_drag: QPointF = QPointF(0, 0)
        self._tam_inicial: tuple[float, float] = (beat.w, beat.h)
        self._pos_inicial: QPointF = QPointF(beat.x, beat.y)

    # ── Geometría ─────────────────────────────────────────────────────

    def boundingRect(self) -> QRectF:
        # Margen para que los ganchos no se corten en los bordes
        m = self.HANDLE_R + 3
        return QRectF(-m, -m, self._beat.w + 2 * m, self._beat.h + 2 * m)

    def shape(self) -> QPainterPath:
        path = QPainterPath()
        path.addRect(QRectF(0, 0, self._beat.w, self._beat.h))
        for lado in ("top", "right", "bot", "left"):
            cx, cy = self._centro_lado(lado)
            path.addEllipse(QPointF(cx, cy), self.HANDLE_R, self.HANDLE_R)
        return path

    def _centro_lado(self, lado: str) -> tuple[float, float]:
        """Devuelve coords locales (x, y) del centro del lado."""
        w, h = self._beat.w, self._beat.h
        return {
            "top":   (w / 2, 0),
            "right": (w,     h / 2),
            "bot":   (w / 2, h),
            "left":  (0,     h / 2),
        }[lado]

    def centro_lado_en_scene(self, lado: str) -> QPointF:
        """Para que VentanaBeatBoard dibuje flechas desde puntos correctos."""
        cx, cy = self._centro_lado(lado)
        return self.mapToScene(QPointF(cx, cy))

    def _zona_en(self, pos: QPointF) -> tuple[str, str]:
        """Detecta qué zona contiene el punto en coords locales.
        Retorna ('gancho', lado) | ('resize', '') | ('body', '') | ('fuera', '')."""
        x, y = pos.x(), pos.y()
        # 1) Ganchos primero (tienen prioridad sobre body)
        for lado in ("top", "right", "bot", "left"):
            cx, cy = self._centro_lado(lado)
            if (x - cx) ** 2 + (y - cy) ** 2 <= (self.HANDLE_R + 2) ** 2:
                return ("gancho", lado)
        # 2) Handle de resize: esquina INFERIOR IZQUIERDA
        rs = self.RESIZE_SZ
        if 0 <= x <= rs and self._beat.h - rs <= y <= self._beat.h:
            return ("resize", "")
        # 3) Cuerpo
        if 0 <= x <= self._beat.w and 0 <= y <= self._beat.h:
            return ("body", "")
        return ("fuera", "")

    # ── Min size según texto ──────────────────────────────────────────

    def _min_w_para_texto(self) -> float:
        fm_tit = QFontMetricsF(QFont("Segoe UI", 10, QFont.Weight.Bold))
        ancho_titulo = fm_tit.horizontalAdvance(self._beat.titulo or " ") + 28
        return max(ancho_titulo, 110.0)

    def _min_h_para_texto(self, w_actual: float) -> float:
        cab_h = 26
        if not self._beat.descripcion:
            return cab_h + 28
        fm = QFontMetricsF(QFont("Segoe UI", 9))
        rect = fm.boundingRect(
            QRectF(0, 0, max(80.0, w_actual - 16), 10_000),
            int(Qt.TextFlag.TextWordWrap),
            self._beat.descripcion)
        return cab_h + rect.height() + 18

    # ── Eventos del mouse ─────────────────────────────────────────────

    def hoverMoveEvent(self, event):
        zona, lado = self._zona_en(event.pos())
        prev_hover = self._lado_hover
        if zona == "gancho":
            self.setCursor(Qt.CursorShape.CrossCursor)
            self._lado_hover = lado
        elif zona == "resize":
            # Cursor diagonal (esquina inferior-izquierda)
            self.setCursor(Qt.CursorShape.SizeBDiagCursor)
            self._lado_hover = None
        elif zona == "body":
            self.setCursor(Qt.CursorShape.OpenHandCursor)
            self._lado_hover = None
        else:
            self.unsetCursor()
            self._lado_hover = None
        if prev_hover != self._lado_hover:
            self.update()
        super().hoverMoveEvent(event)

    def hoverLeaveEvent(self, event):
        if self._lado_hover is not None:
            self._lado_hover = None
            self.update()
        super().hoverLeaveEvent(event)

    def mousePressEvent(self, event):
        if event.button() != Qt.MouseButton.LeftButton:
            return super().mousePressEvent(event)
        zona, lado = self._zona_en(event.pos())
        if zona == "gancho":
            self._modo = "arrow"
            self._lado_arrow = lado
            self._ventana._iniciar_arrow_drag(
                self._indice, lado,
                self.centro_lado_en_scene(lado))
            event.accept()
        elif zona == "resize":
            self._modo = "resize"
            self._tam_inicial = (self._beat.w, self._beat.h)
            self._pos_inicial = QPointF(self.pos())
            self._inicio_drag = event.scenePos()
            event.accept()
        elif zona == "body":
            self._modo = "move"
            self._inicio_drag = event.scenePos() - self.pos()
            self.setSelected(True)
            event.accept()
        else:
            event.ignore()

    def mouseMoveEvent(self, event):
        if self._modo == "arrow":
            self._ventana._actualizar_arrow_drag(event.scenePos())
            event.accept()
        elif self._modo == "resize":
            # Resize desde esquina inferior IZQUIERDA:
            #   · arrastrar hacia la izquierda agranda el ancho y
            #     desplaza la tarjeta a la izquierda
            #   · arrastrar hacia abajo agranda el alto
            delta = event.scenePos() - self._inicio_drag
            w0, h0 = self._tam_inicial
            nuevo_w = w0 - delta.x()
            nuevo_h = h0 + delta.y()
            # Forzar mínimos del texto
            min_w = self._min_w_para_texto()
            if nuevo_w < min_w:
                nuevo_w = min_w
            min_h = self._min_h_para_texto(nuevo_w)
            if nuevo_h < min_h:
                nuevo_h = min_h
            self.prepareGeometryChange()
            # Mover la x para que la esquina inferior-derecha quede fija
            dx = w0 - nuevo_w
            self.setPos(self._pos_inicial.x() + dx, self._pos_inicial.y())
            self._beat.w = float(nuevo_w)
            self._beat.h = float(nuevo_h)
            self._beat.x = float(self.pos().x())
            self._beat.y = float(self.pos().y())
            self.update()
            if self._ventana:
                self._ventana._actualizar_flechas()
            event.accept()
        elif self._modo == "move":
            nueva_pos = event.scenePos() - self._inicio_drag
            self.setPos(nueva_pos)
            self._beat.x = float(nueva_pos.x())
            self._beat.y = float(nueva_pos.y())
            if self._ventana:
                self._ventana._actualizar_flechas()
            event.accept()
        else:
            super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event):
        if self._modo == "arrow" and self._ventana:
            self._ventana._terminar_arrow_drag(
                self._indice, self._lado_arrow or "right",
                event.scenePos())
        self._modo = None
        self._lado_arrow = None
        # Blindar contra objetos C++ ya destruidos (puede pasar si la
        # tarjeta se borró mientras el mouse aún estaba interactuando)
        try:
            super().mouseReleaseEvent(event)
        except RuntimeError:
            pass

    def mouseDoubleClickEvent(self, event):
        zona, _ = self._zona_en(event.pos())
        if zona == "body" and self._ventana:
            self._ventana._editar_tarjeta(self._indice)
        else:
            super().mouseDoubleClickEvent(event)

    # ── Pintado ───────────────────────────────────────────────────────

    def paint(self, p: "QPainter", _option, _widget=None):
        from PySide6.QtGui import QColor, QPen, QFont, QLinearGradient
        rect = QRectF(0, 0, self._beat.w, self._beat.h)

        # Sombra
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(0, 0, 0, 60))
        p.drawRoundedRect(rect.adjusted(2, 2, 2, 2), 6, 6)

        # Cuerpo principal (papel crema)
        p.setBrush(QColor("#fdfbf4"))
        if self.isSelected():
            p.setPen(QPen(QColor("#ff8c1a"), 2.5))
        else:
            p.setPen(QPen(QColor("#3a4665"), 1))
        p.drawRoundedRect(rect, 6, 6)

        # Cabecera de color con esquinas redondeadas SOLO arriba
        cab_h = 26
        grad = QLinearGradient(0, 0, 0, cab_h)
        grad.setColorAt(0.0, QColor(self._beat.color).lighter(115))
        grad.setColorAt(1.0, QColor(self._beat.color))
        r = 6
        path_cab = QPainterPath()
        path_cab.moveTo(0, cab_h)
        path_cab.lineTo(0, r)
        path_cab.quadTo(0, 0, r, 0)
        path_cab.lineTo(self._beat.w - r, 0)
        path_cab.quadTo(self._beat.w, 0, self._beat.w, r)
        path_cab.lineTo(self._beat.w, cab_h)
        path_cab.closeSubpath()
        p.setBrush(grad)
        p.setPen(Qt.PenStyle.NoPen)
        p.drawPath(path_cab)

        # Título sobre la cabecera
        p.setPen(QColor("white"))
        p.setFont(QFont("Segoe UI", 10, QFont.Weight.Bold))
        p.drawText(QRectF(8, 0, self._beat.w - 16, cab_h),
                   Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft,
                   self._beat.titulo[:60])

        # Descripción con word-wrap
        p.setPen(QColor("#1a1f2e"))
        p.setFont(QFont("Segoe UI", 9))
        # Reservar la esquina inferior-izquierda para el handle de resize
        rs = self.RESIZE_SZ
        p.drawText(
            QRectF(8, cab_h + 4,
                   self._beat.w - 16,
                   self._beat.h - cab_h - 8 - rs),  # deja espacio abajo
            Qt.AlignmentFlag.AlignTop | Qt.AlignmentFlag.AlignLeft
            | Qt.TextFlag.TextWordWrap,
            self._beat.descripcion)

        # Ganchos: 4 círculos de color en el centro de cada lado
        for lado in ("top", "right", "bot", "left"):
            cx, cy = self._centro_lado(lado)
            radio = (self.HANDLE_HOVER_R if self._lado_hover == lado
                     else self.HANDLE_R)
            p.setBrush(QColor(self._beat.color))
            p.setPen(QPen(QColor("#fdfbf4"), 2))
            p.drawEllipse(QPointF(cx, cy), radio, radio)

        # Handle de resize en esquina INFERIOR IZQUIERDA: 3 rayitas
        # diagonales que sugieren "agarrar y escalar"
        p.setPen(QPen(QColor("#5a6478"), 1.6))
        h = self._beat.h
        for i in (3, 7, 11):
            p.drawLine(QPointF(i + 1, h - 2),
                       QPointF(2, h - i - 1))


class _FotoBeat(QGraphicsItem):
    """Foto colocada sobre la Pizarra de beats.
    Misma mecánica de resize que las tarjetas (esquina inferior
    izquierda) y doble-click para editar el comentario."""

    RESIZE_SZ      = 16
    HANDLE_R       = 7
    HANDLE_HOVER_R = 9

    def __init__(self, foto: FotoBeat, indice: int, ventana):
        super().__init__()
        self._foto = foto
        self._indice = indice
        self._ventana = ventana
        # Cargar imagen: preferir datos_b64 (embebidos, viajan al invitado)
        # sobre path (que puede no existir en el PC del invitado).
        self._pixmap = QPixmap()
        if getattr(foto, "datos_b64", ""):
            try:
                import base64
                raw = base64.b64decode(foto.datos_b64)
                self._pixmap.loadFromData(raw)
            except Exception:
                pass
        if self._pixmap.isNull() and foto.path:
            self._pixmap = QPixmap(foto.path)
        self.setFlag(QGraphicsItem.GraphicsItemFlag.ItemIsSelectable, True)
        self.setAcceptHoverEvents(True)
        self.setPos(foto.x, foto.y)
        self._modo: Optional[str] = None
        self._lado_arrow: Optional[str] = None
        self._lado_hover: Optional[str] = None
        self._inicio_drag: QPointF = QPointF(0, 0)
        self._tam_inicial: tuple[float, float] = (foto.w, foto.h)
        self._pos_inicial: QPointF = QPointF(foto.x, foto.y)

    def boundingRect(self) -> QRectF:
        h_com = 26 if self._foto.comentario else 0
        m = self.HANDLE_R + 3
        return QRectF(-m, -m, self._foto.w + 2 * m,
                      self._foto.h + h_com + 2 * m)

    def _centro_lado(self, lado: str) -> tuple[float, float]:
        w, h = self._foto.w, self._foto.h
        return {
            "top":   (w / 2, 0),
            "right": (w,     h / 2),
            "bot":   (w / 2, h),
            "left":  (0,     h / 2),
        }[lado]

    def centro_lado_en_scene(self, lado: str) -> QPointF:
        cx, cy = self._centro_lado(lado)
        return self.mapToScene(QPointF(cx, cy))

    def _zona_en(self, pos: QPointF):
        x, y = pos.x(), pos.y()
        for lado in ("top", "right", "bot", "left"):
            cx, cy = self._centro_lado(lado)
            if (x - cx) ** 2 + (y - cy) ** 2 <= (self.HANDLE_R + 2) ** 2:
                return ("gancho", lado)
        rs = self.RESIZE_SZ
        if 0 <= x <= rs and self._foto.h - rs <= y <= self._foto.h:
            return ("resize", "")
        if 0 <= x <= self._foto.w and 0 <= y <= self._foto.h:
            return ("body", "")
        return ("fuera", "")

    def hoverMoveEvent(self, event):
        zona, lado = self._zona_en(event.pos())
        prev = self._lado_hover
        if zona == "gancho":
            self.setCursor(Qt.CursorShape.CrossCursor)
            self._lado_hover = lado
        elif zona == "resize":
            self.setCursor(Qt.CursorShape.SizeBDiagCursor)
            self._lado_hover = None
        elif zona == "body":
            self.setCursor(Qt.CursorShape.OpenHandCursor)
            self._lado_hover = None
        else:
            self.unsetCursor()
            self._lado_hover = None
        if prev != self._lado_hover:
            self.update()
        super().hoverMoveEvent(event)

    def hoverLeaveEvent(self, event):
        if self._lado_hover is not None:
            self._lado_hover = None
            self.update()
        super().hoverLeaveEvent(event)

    def mousePressEvent(self, event):
        if event.button() != Qt.MouseButton.LeftButton:
            return super().mousePressEvent(event)
        zona, lado = self._zona_en(event.pos())
        if zona == "gancho":
            self._modo = "arrow"
            self._lado_arrow = lado
            self._ventana._iniciar_arrow_drag(
                self._indice, lado, self.centro_lado_en_scene(lado),
                origen_tipo="foto")
            event.accept()
        elif zona == "resize":
            self._modo = "resize"
            self._tam_inicial = (self._foto.w, self._foto.h)
            self._pos_inicial = QPointF(self.pos())
            self._inicio_drag = event.scenePos()
            event.accept()
        elif zona == "body":
            self._modo = "move"
            self._inicio_drag = event.scenePos() - self.pos()
            self.setSelected(True)
            event.accept()
        else:
            event.ignore()

    def mouseMoveEvent(self, event):
        if self._modo == "arrow":
            self._ventana._actualizar_arrow_drag(event.scenePos())
            event.accept()
        elif self._modo == "resize":
            delta = event.scenePos() - self._inicio_drag
            w0, h0 = self._tam_inicial
            ratio = (w0 / h0) if h0 > 0 else 1.33
            nuevo_w = max(80.0, w0 - delta.x())
            nuevo_h = max(60.0, nuevo_w / ratio)
            self.prepareGeometryChange()
            dx = w0 - nuevo_w
            self.setPos(self._pos_inicial.x() + dx, self._pos_inicial.y())
            self._foto.w = float(nuevo_w)
            self._foto.h = float(nuevo_h)
            self._foto.x = float(self.pos().x())
            self._foto.y = float(self.pos().y())
            self.update()
            event.accept()
        elif self._modo == "move":
            nueva_pos = event.scenePos() - self._inicio_drag
            self.setPos(nueva_pos)
            self._foto.x = float(nueva_pos.x())
            self._foto.y = float(nueva_pos.y())
            if self._ventana:
                self._ventana._actualizar_flechas()
            event.accept()
        else:
            super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event):
        if self._modo == "arrow" and self._ventana:
            self._ventana._terminar_arrow_drag(
                self._indice, self._lado_arrow or "right",
                event.scenePos(), origen_tipo="foto")
        self._modo = None
        self._lado_arrow = None
        # Blindar contra objetos C++ ya destruidos
        try:
            super().mouseReleaseEvent(event)
        except RuntimeError:
            pass

    def mouseDoubleClickEvent(self, event):
        """Doble-click → editar comentario."""
        zona, _ = self._zona_en(event.pos())
        if zona != "body":
            return super().mouseDoubleClickEvent(event)
        txt, ok = QInputDialog.getText(
            None, "Comentario de la foto",
            "Comentario que aparecerá debajo de la imagen:",
            QLineEdit.EchoMode.Normal, self._foto.comentario)
        if ok:
            self.prepareGeometryChange()
            self._foto.comentario = txt
            self.update()

    def paint(self, p: "QPainter", _option, _widget=None):
        from PySide6.QtGui import QColor, QPen, QFont
        target = QRectF(0, 0, self._foto.w, self._foto.h)
        # Foto o placeholder
        if not self._pixmap.isNull():
            p.drawPixmap(target, self._pixmap, QRectF(self._pixmap.rect()))
        else:
            p.fillRect(target, QColor("#243358"))
            p.setPen(QColor("#fdfbf4"))
            p.setFont(QFont("Segoe UI", 10))
            p.drawText(target,
                       Qt.AlignmentFlag.AlignCenter,
                       "(imagen no encontrada)")
        # Borde
        p.setPen(QPen(QColor("#ff8c1a") if self.isSelected() else QColor("#3a4665"),
                      2 if self.isSelected() else 1))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawRect(target)
        # Handle de resize esquina inferior izquierda
        p.setPen(QPen(QColor("#fdfbf4"), 1.6))
        h = self._foto.h
        for i in (3, 7, 11):
            p.drawLine(QPointF(i + 1, h - 2), QPointF(2, h - i - 1))
        # Ganchos de conexión (4 círculos en los lados)
        for lado in ("top", "right", "bot", "left"):
            cx, cy = self._centro_lado(lado)
            radio = (self.HANDLE_HOVER_R if self._lado_hover == lado
                     else self.HANDLE_R)
            p.setBrush(QColor("#ff8c1a"))
            p.setPen(QPen(QColor("#fdfbf4"), 2))
            p.drawEllipse(QPointF(cx, cy), radio, radio)
        # Banda inferior con el comentario
        if self._foto.comentario:
            p.setBrush(QColor(0, 0, 0, 200))
            p.setPen(Qt.PenStyle.NoPen)
            p.drawRect(QRectF(0, self._foto.h, self._foto.w, 26))
            p.setPen(QColor("#fdfbf4"))
            p.setFont(QFont("Segoe UI", 9, QFont.Weight.Bold))
            p.drawText(QRectF(8, self._foto.h, self._foto.w - 16, 26),
                       Qt.AlignmentFlag.AlignVCenter
                       | Qt.AlignmentFlag.AlignLeft,
                       self._foto.comentario[:80])


class DialogoCorrectorOrtografico(QDialog):
    """Corrector ortográfico interactivo estilo Word / LibreOffice.

    Se abre con F7 y va recorriendo el guion palabra por palabra,
    detectando las que no están en el diccionario español. Para cada
    palabra desconocida ofrece:
      • Lista de sugerencias (top 6) clickeables.
      • Cambiar por una sugerencia.
      • Cambiar todo (cambia todas las apariciones en el guion).
      • Ignorar una vez (avanza a la siguiente).
      • Ignorar todo (agrega la palabra a la sesión y no la vuelve a
        marcar en esta sesión de corrector).
      • Agregar al diccionario personal (persistente entre sesiones).

    Muestra la palabra en contexto (fragmento de la frase alrededor)
    para que el usuario decida bien.
    """

    def __init__(self, editor, parent=None):
        super().__init__(parent)
        self.editor = editor
        self.doc = editor.documento
        self.setWindowTitle("✓ Corrector ortográfico")

        app = QApplication.instance()
        screen = app.primaryScreen() if app else None
        if screen is not None:
            geo = screen.availableGeometry()
            ancho = max(560, min(int(geo.width() * 0.45), 720))
            alto = max(420, min(int(geo.height() * 0.55), 560))
            self.resize(ancho, alto)
        else:
            self.resize(px(640), px(480))

        self.setStyleSheet("""
            QDialog { background: #1e1e28; }
            QLabel { color: #f0f0f5; font-size: 10pt; }
            QLabel#titulo {
                color: #ff8c1a; font-size: 14pt; font-weight: bold;
            }
            QLabel#seccion {
                color: #e8edf4; font-size: 9pt; font-weight: bold;
                margin-top: 4px;
            }
            QLabel#palabra {
                color: #f97316; font-size: 16pt; font-weight: bold;
                background: #0f1421; padding: 12px 18px;
                border: 2px solid #f97316; border-radius: 6px;
            }
            QLabel#contexto {
                color: #e8edf4; background: #0f1421;
                padding: 10px 14px; border: 1px solid #2a3040;
                border-radius: 4px; font-size: 10pt;
            }
            QListWidget {
                background: #0f1421; color: #e8edf4;
                border: 1px solid #2a3040; border-radius: 4px;
                font-size: 11pt; padding: 4px;
            }
            QListWidget::item {
                padding: 8px 12px; margin: 2px 0;
                border-radius: 3px;
            }
            QListWidget::item:selected {
                background: #ff8c1a; color: #241203; font-weight: bold;
            }
            QListWidget::item:hover:!selected {
                background: #2a3548;
            }
            QPushButton {
                background: #2a3548; color: #f0f0f5;
                padding: 8px 16px; border: 1px solid #3d4863;
                border-radius: 4px; font-size: 9pt; font-weight: bold;
                min-height: 26px;
            }
            QPushButton:hover { background: #22314a; border: 1px solid #ff8c1a; }
            QPushButton[primario="true"] {
                background: #ff8c1a; color: #241203; border: none;
            }
            QPushButton[primario="true"]:hover { background: #ea7a0d; }
        """)

        v = QVBoxLayout(self)
        v.setContentsMargins(18, 16, 18, 16)
        v.setSpacing(10)

        titulo = QLabel("✓ Corrector ortográfico")
        titulo.setObjectName("titulo")
        v.addWidget(titulo)

        lbl_seccion = QLabel("Palabra no reconocida:")
        lbl_seccion.setObjectName("seccion")
        v.addWidget(lbl_seccion)

        self._lbl_palabra = QLabel("—")
        self._lbl_palabra.setObjectName("palabra")
        self._lbl_palabra.setAlignment(Qt.AlignmentFlag.AlignCenter)
        v.addWidget(self._lbl_palabra)

        lbl_ctx = QLabel("Contexto:")
        lbl_ctx.setObjectName("seccion")
        v.addWidget(lbl_ctx)

        self._lbl_contexto = QLabel("—")
        self._lbl_contexto.setObjectName("contexto")
        self._lbl_contexto.setWordWrap(True)
        self._lbl_contexto.setTextFormat(Qt.TextFormat.RichText)
        v.addWidget(self._lbl_contexto)

        lbl_sug = QLabel("Sugerencias (doble clic para aplicar):")
        lbl_sug.setObjectName("seccion")
        v.addWidget(lbl_sug)

        self._lst = QListWidget()
        self._lst.itemDoubleClicked.connect(self._cambiar)
        v.addWidget(self._lst, 1)

        # Progreso
        self._lbl_progreso = QLabel("")
        self._lbl_progreso.setStyleSheet(
            "color: #e8edf4; font-size: 9pt;")
        v.addWidget(self._lbl_progreso)

        # Botones
        bb = QHBoxLayout()
        bb.setSpacing(6)

        btn_ignorar = QPushButton("Ignorar una vez")
        btn_ignorar.clicked.connect(self._ignorar_una)
        bb.addWidget(btn_ignorar)

        btn_ignorar_todo = QPushButton("Ignorar todo")
        btn_ignorar_todo.setToolTip(
            "No volver a marcar esta palabra en esta sesión.")
        btn_ignorar_todo.clicked.connect(self._ignorar_todo)
        bb.addWidget(btn_ignorar_todo)

        btn_agregar = QPushButton("Agregar al diccionario")
        btn_agregar.setToolTip(
            "Agregar la palabra al diccionario personal. "
            "Se guarda para siempre.")
        btn_agregar.clicked.connect(self._agregar_diccionario)
        bb.addWidget(btn_agregar)

        bb.addStretch()

        btn_cambiar_todo = QPushButton("Cambiar todo")
        btn_cambiar_todo.setToolTip(
            "Aplica la sugerencia seleccionada a TODAS las "
            "apariciones de la palabra en el guion.")
        btn_cambiar_todo.clicked.connect(self._cambiar_todo)
        bb.addWidget(btn_cambiar_todo)

        btn_cambiar = QPushButton("Cambiar")
        btn_cambiar.setProperty("primario", True)
        btn_cambiar.setStyle(btn_cambiar.style())
        btn_cambiar.clicked.connect(self._cambiar)
        bb.addWidget(btn_cambiar)

        v.addLayout(bb)

        # Botón cerrar independiente
        bb2 = QHBoxLayout()
        bb2.addStretch()
        btn_cerrar = QPushButton("Cerrar")
        btn_cerrar.clicked.connect(self.reject)
        bb2.addWidget(btn_cerrar)
        v.addLayout(bb2)

        # Estado interno
        self._ignoradas_sesion: set[str] = set()
        self._errores_pendientes: list[tuple[int, int, int, str]] = []
        # cada elemento: (idx_bloque, inicio_pal, fin_pal, palabra_lowered)
        self._idx_actual = 0

        # Preparar
        self._buscar_todas_las_erratas()
        if not self._errores_pendientes:
            QMessageBox.information(
                self, "Corrector ortográfico",
                "¡Todo en orden! No se encontraron palabras "
                "desconocidas en el guion.")
            self.close()
            return

        self._mostrar_error_actual()

    # ─── Búsqueda y navegación ───────────────────────────────────

    def _buscar_todas_las_erratas(self) -> None:
        """Recorre TODOS los bloques y arma una lista de todas las
        palabras desconocidas con su ubicación."""
        if not corrector_activo():
            activar_corrector(True)
        if not cargar_diccionario_es():
            QMessageBox.warning(
                self, "Diccionario no disponible",
                "No se encontró el diccionario español. "
                "Colócalo en la carpeta del programa y vuelve a "
                "abrir el corrector.")
            return
        re_pal = re.compile(r"[A-Za-záéíóúüñÁÉÍÓÚÜÑ']{3,}")
        # Diccionario personal (persistente)
        # Palabras aprendidas viven en el DOCUMENTO (viajan con el
        # .accion). También cargamos las globales por retrocompatibilidad.
        personales = _diccionario_personal_cargar()
        aprendidas = _palabras_aprendidas_proyecto(self.doc)
        excluidas = personales | aprendidas
        for idx_b, b in enumerate(self.doc.bloques):
            # Solo bloques con texto natural
            if b.elem in (Elem.PERSONAJE, Elem.TRANSICION, Elem.PLANO,
                           Elem.ACTO_INICIO, Elem.ACTO_FIN, Elem.ESCENA):
                continue
            texto = b.texto or ""
            for m in re_pal.finditer(texto):
                pal = m.group()
                if palabra_correcta(pal):
                    continue
                pal_l = _quitar_acentos(pal.lower())
                if pal_l in excluidas:
                    continue
                self._errores_pendientes.append(
                    (idx_b, m.start(), m.end(), pal))

    def _mostrar_error_actual(self) -> None:
        # Saltar las ignoradas de sesión
        while self._idx_actual < len(self._errores_pendientes):
            _, _, _, pal = self._errores_pendientes[self._idx_actual]
            if pal.lower() in self._ignoradas_sesion:
                self._idx_actual += 1
                continue
            break
        if self._idx_actual >= len(self._errores_pendientes):
            QMessageBox.information(
                self, "Corrector ortográfico",
                "¡Revisión completa! No quedan más palabras que "
                "revisar.")
            self.accept()
            return

        idx_b, ini, fin, pal = self._errores_pendientes[self._idx_actual]
        self._lbl_palabra.setText(pal)
        self._mostrar_contexto(idx_b, ini, fin, pal)
        self._cargar_sugerencias(pal)
        total = len(self._errores_pendientes)
        self._lbl_progreso.setText(
            f"Palabra {self._idx_actual + 1} de {total}")

    def _mostrar_contexto(self, idx_b: int, ini: int, fin: int,
                          pal: str) -> None:
        texto = self.doc.bloques[idx_b].texto or ""
        ctx_ini = max(0, ini - 60)
        ctx_fin = min(len(texto), fin + 60)
        antes = texto[ctx_ini:ini]
        despues = texto[fin:ctx_fin]
        pre = "…" if ctx_ini > 0 else ""
        post = "…" if ctx_fin < len(texto) else ""
        # HTML resaltando la palabra
        html = (f"{pre}{_escapar_html_simple(antes)}"
                f"<span style='color:#f97316;font-weight:bold;"
                f"text-decoration:underline;'>"
                f"{_escapar_html_simple(pal)}</span>"
                f"{_escapar_html_simple(despues)}{post}")
        self._lbl_contexto.setText(html)

    def _cargar_sugerencias(self, pal: str) -> None:
        self._lst.clear()
        sugs = sugerencias_ortografia(pal, limite=6)
        if not sugs:
            item = QListWidgetItem(
                "(no hay sugerencias — puedes editar el texto "
                "manualmente)")
            item.setFlags(Qt.ItemFlag.NoItemFlags)
            self._lst.addItem(item)
        else:
            for s in sugs:
                self._lst.addItem(s)
            self._lst.setCurrentRow(0)

    # ─── Acciones ────────────────────────────────────────────────

    def _cambiar(self, *args) -> None:
        item = self._lst.currentItem()
        if not item or not (item.flags() & Qt.ItemFlag.ItemIsEnabled):
            return
        sugerencia = item.text()
        self._aplicar_cambio(sugerencia, en_todas=False)
        self._idx_actual += 1
        self._mostrar_error_actual()

    def _cambiar_todo(self) -> None:
        item = self._lst.currentItem()
        if not item or not (item.flags() & Qt.ItemFlag.ItemIsEnabled):
            return
        sugerencia = item.text()
        self._aplicar_cambio(sugerencia, en_todas=True)
        self._idx_actual += 1
        self._mostrar_error_actual()

    def _aplicar_cambio(self, sugerencia: str, en_todas: bool) -> None:
        idx_b, ini, fin, pal = self._errores_pendientes[self._idx_actual]
        # Preservar mayúscula/minúscula del original
        sug_final = self._preservar_caso(pal, sugerencia)
        b = self.doc.bloques[idx_b]
        texto = b.texto or ""
        b.texto = texto[:ini] + sug_final + texto[fin:]
        delta = len(sug_final) - (fin - ini)
        # Ajustar posiciones de errores posteriores en el mismo bloque
        for i in range(self._idx_actual + 1,
                       len(self._errores_pendientes)):
            b2, i2, f2, p2 = self._errores_pendientes[i]
            if b2 == idx_b and i2 >= fin:
                self._errores_pendientes[i] = (
                    b2, i2 + delta, f2 + delta, p2)
        # Cambiar todo: reemplazar todas las apariciones en todos los
        # bloques que quedan
        if en_todas:
            self._reemplazar_en_todo_el_doc(pal, sug_final)
        # Sincronizar el editor con el documento modificado
        self.editor.cargar_documento(self.doc)

    def _reemplazar_en_todo_el_doc(self, orig: str, nuevo: str) -> None:
        """Reemplaza TODAS las apariciones de 'orig' por 'nuevo' en
        los bloques con texto natural (no PERSONAJE, no ENCABEZADO)."""
        re_pal = re.compile(
            r"\b" + re.escape(orig) + r"\b", re.IGNORECASE)
        for idx_b, b in enumerate(self.doc.bloques):
            if b.elem in (Elem.PERSONAJE, Elem.TRANSICION, Elem.PLANO,
                           Elem.ACTO_INICIO, Elem.ACTO_FIN,
                           Elem.ESCENA):
                continue
            def _rep(m):
                return self._preservar_caso(m.group(), nuevo)
            b.texto = re_pal.sub(_rep, b.texto or "")
        # Purgar del pendiente las apariciones futuras de 'orig'
        orig_l = orig.lower()
        self._errores_pendientes = [
            e for i, e in enumerate(self._errores_pendientes)
            if i <= self._idx_actual or e[3].lower() != orig_l]

    def _preservar_caso(self, original: str, nuevo: str) -> str:
        if original.isupper():
            return nuevo.upper()
        if original[:1].isupper():
            return nuevo[:1].upper() + nuevo[1:]
        return nuevo

    def _ignorar_una(self) -> None:
        self._idx_actual += 1
        self._mostrar_error_actual()

    def _ignorar_todo(self) -> None:
        pal = self._errores_pendientes[self._idx_actual][3]
        self._ignoradas_sesion.add(pal.lower())
        self._idx_actual += 1
        self._mostrar_error_actual()

    def _agregar_diccionario(self) -> None:
        pal = self._errores_pendientes[self._idx_actual][3]
        # Guardar en el PROYECTO (viaja con el .accion), no en el equipo
        _agregar_palabra_aprendida(self.doc, pal)
        # Marcar el documento como dirty para que se guarde
        try:
            vp = self.parent()
            if hasattr(vp, "_marcar_dirty"):
                vp._marcar_dirty()
        except Exception:
            pass
        # Re-highlight
        if hasattr(self.editor, "_ortografia_hl"):
            self.editor._ortografia_hl.rehighlight()
        # Purgar todas las apariciones futuras de esta palabra
        pal_l = _quitar_acentos(pal.lower())
        self._errores_pendientes = [
            e for i, e in enumerate(self._errores_pendientes)
            if i <= self._idx_actual
            or _quitar_acentos(e[3].lower()) != pal_l]
        self._idx_actual += 1
        self._mostrar_error_actual()


def _escapar_html_simple(s: str) -> str:
    return (s.replace("&", "&amp;")
             .replace("<", "&lt;")
             .replace(">", "&gt;"))


def _diccionario_personal_ruta() -> Path:
    return Path.home() / ".accion_diccionario_personal.txt"


def _diccionario_personal_cargar() -> set[str]:
    """Carga el diccionario personal del usuario (palabras que agregó
    manualmente al corrector). Se guarda en el home del usuario."""
    ruta = _diccionario_personal_ruta()
    if not ruta.exists():
        return set()
    try:
        return {l.strip().lower() for l in
                ruta.read_text(encoding="utf-8").splitlines()
                if l.strip()}
    except Exception:
        return set()


def _diccionario_personal_agregar(palabra: str) -> None:
    """Agrega una palabra al diccionario personal (persistente)."""
    ruta = _diccionario_personal_ruta()
    palabras = _diccionario_personal_cargar()
    palabras.add(palabra.lower())
    try:
        ruta.write_text("\n".join(sorted(palabras)) + "\n",
                         encoding="utf-8")
    except Exception:
        pass
    # También lo agregamos al diccionario en memoria
    dic = cargar_diccionario_es()
    if dic is not None:
        dic.add(palabra.lower())
        dic.add(_quitar_acentos(palabra.lower()))


from PySide6.QtWidgets import QStyledItemDelegate as _QStyledItemDelegate, QStyle as _QStyle


class _DelegadoActosEscenas(_QStyledItemDelegate):
    """Pinta los separadores de acto del editor de escenas con su color
    (naranja, rojo si no tienen su par, gris si se quitan): la hoja de
    estilo de la lista no deja ver el fondo propio de cada fila."""

    def paint(self, painter, option, index):
        d = index.data(Qt.ItemDataRole.UserRole)
        if not (isinstance(d, tuple) and d and d[0] in ("acto_inicio", "acto_fin")):
            return super().paint(painter, option, index)
        painter.save()
        bg = index.data(Qt.ItemDataRole.BackgroundRole)
        col = QColor(bg.color()) if isinstance(bg, QBrush) else QColor("#ff8c1a")
        sel = bool(option.state & _QStyle.StateFlag.State_Selected)
        if option.state & _QStyle.StateFlag.State_MouseOver and not sel:
            col = col.lighter(112)
        r = option.rect
        painter.fillRect(r, col)
        if sel:
            painter.fillRect(QRect(r.left(), r.top(), px(5), r.height()), QColor("#ffffff"))
            painter.setPen(QPen(QColor("#ffffff"), 2))
            painter.drawRect(r.adjusted(1, 1, -2, -2))
        fg = index.data(Qt.ItemDataRole.ForegroundRole)
        painter.setPen(fg.color() if isinstance(fg, QBrush) else QColor("white"))
        f = index.data(Qt.ItemDataRole.FontRole)
        if isinstance(f, QFont):
            painter.setFont(f)
        painter.drawText(r.adjusted(px(14), 0, -px(8), 0),
                         int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft),
                         str(index.data(Qt.ItemDataRole.DisplayRole) or ""))
        painter.restore()


class VentanaEditorEscenas(QDialog):
    """Editor visual de escenas: reordenar y eliminar escenas completas.

    Interfaz:
      • Lista vertical con todas las escenas (drag & drop para reordenar).
      • Panel derecho con preview de la escena seleccionada.
      • Botón "🗑 Eliminar escena" (con confirmación).
      • Botones OK / Cancelar.

    Al aceptar, la ventana devuelve dos cosas:
      • nuevo_orden()  → lista de números originales en el nuevo orden.
      • escenas_eliminadas() → set de números originales a eliminar.

    La aplicación de los cambios la hace VP._accion_editor_escenas()
    llamando a editor.aplicar_reorden_escenas(nuevo_orden, eliminadas).

    Los ACTO_INICIO / ACTO_FIN se ven como separadores naranjas: se
    arrastran, se renombran (doble clic) y se quitan (Suprimir). Como los
    paréntesis de Excel, uno sin su par se ve en rojo, sin impedir nada.
    """

    def __init__(self, documento, parent=None):
        super().__init__(parent)
        self.doc = documento
        self.setWindowTitle("🎬  Editor de escenas")
        habilitar_snap(self, "🎞")
        # Adaptar el tamaño a la pantalla del usuario:
        #   • Tamaño inicial = 80% del área disponible (excluye barra
        #     de tareas).
        #   • Mínimo suficientemente bajo para que corra en HD ready
        #     (1366×768) o notebooks pequeños sin romper.
        #   • Máximo = tamaño total disponible (nunca queda más grande
        #     que la pantalla).
        app = QApplication.instance()
        screen = app.primaryScreen() if app else None
        if screen is not None:
            geo = screen.availableGeometry()
            ancho = int(geo.width() * 0.80)
            alto = int(geo.height() * 0.80)
            # Rango seguro: nunca menor a 720×500 ni mayor a la pantalla
            ancho = max(720, min(ancho, geo.width()))
            alto = max(500, min(alto, geo.height()))
            self.resize(ancho, alto)
        else:
            # Fallback si no hay screen (tests headless)
            self.resize(px(1000), px(700))
        self.setMinimumSize(px(640), px(480))
        self.setStyleSheet("""
            QDialog { background: #0d1520; }
            QLabel {
                color: #e8edf4; font-size: 10pt;
            }
            QLabel#titulo {
                color: #ff8c1a; font-size: 15pt; font-weight: bold;
            }
            QLabel#sub {
                color: #8a96b0; font-size: 9pt;
            }
            QListWidget {
                background: #0f1421; color: #e8edf4;
                border: 1px solid #2a3040; border-radius: 4px;
                font-family: 'Courier New', monospace; font-size: 10pt;
                outline: none;
            }
            QListWidget::item {
                padding: 8px 12px; border-bottom: 1px solid #1e2540;
            }
            QListWidget::item:selected {
                background: #2a3548; color: #ffb968;
                border-left: 3px solid #ff8c1a;
            }
            QListWidget::item:hover {
                background: #1e2540;
            }
            QTextEdit {
                background: #0f1421; color: #e8edf4;
                border: 1px solid #2a3040; border-radius: 4px;
                font-family: 'Courier New', monospace; font-size: 10pt;
                padding: 10px;
            }
            QPushButton {
                background: #ff8c1a; color: #241203;
                padding: 8px 16px; border: none; border-radius: 4px;
                font-size: 10pt; font-weight: bold;
            }
            QPushButton:hover { background: #ea7a0d; }
            QPushButton[destructivo="true"] {
                background: #f87171;
            }
            QPushButton[destructivo="true"]:hover {
                background: #f87171;
            }
            QPushButton[secundario="true"] {
                background: #8fa1b8;
            }
            QPushButton[secundario="true"]:hover { background: #131d2b; }
        """)

        # Segmentar escenas Y actos juntos
        self._items_todos = segmentar_actos_y_escenas(documento)
        # Solo las escenas para el flujo de "aplicar cambios"
        self._escenas = [x for x in self._items_todos
                          if x["tipo"] == "escena"]
        # Estado interno
        self._eliminadas: set[int] = set()

        v_root = QVBoxLayout(self)
        v_root.setContentsMargins(20, 18, 20, 18)
        v_root.setSpacing(12)

        # Header
        titulo = QLabel("🎬  Editor de escenas")
        titulo.setObjectName("titulo")
        v_root.addWidget(titulo)
        n_actos = sum(1 for x in self._items_todos
                       if x["tipo"] == "acto_inicio")
        sub = QLabel(
            f"Total: {len(self._escenas)} escena(s) en "
            f"{n_actos} acto(s). "
            "Arrastra las escenas (y los actos) para reordenar. Doble clic "
            "sobre un acto (línea naranja) para renombrarlo. «Suprimir» quita "
            "una escena completa o solo una marca de acto. Los actos son como "
            "los paréntesis de Excel: uno sin su par se ve en rojo (pasa el "
            "mouse para ver qué le falta), y no impide nada.")
        sub.setObjectName("sub")
        sub.setWordWrap(True)
        v_root.addWidget(sub)

        # Split horizontal: lista | preview
        split = QSplitter(Qt.Orientation.Horizontal)

        # Lista de escenas (con drag & drop interno)
        self._lista = QListWidget()
        self._lista.setDragDropMode(
            QListWidget.DragDropMode.InternalMove)
        self._lista.setDefaultDropAction(Qt.DropAction.MoveAction)
        self._lista.setSelectionMode(
            QListWidget.SelectionMode.SingleSelection)
        self._lista.itemSelectionChanged.connect(self._on_seleccion)
        self._lista.itemDoubleClicked.connect(self._on_doble_click)
        self._lista.setItemDelegate(_DelegadoActosEscenas(self._lista))
        self._lista.setMouseTracking(True)
        for it_data in self._items_todos:
            if it_data["tipo"] == "escena":
                self._lista.addItem(self._crear_item(it_data))
            else:
                # ACTO_INICIO o ACTO_FIN → separador visual
                self._lista.addItem(self._crear_item_acto(it_data))
        # Al arrastrar, los actos vuelven a buscar su par (rojo si no lo tienen)
        _mod = self._lista.model()
        _mod.rowsMoved.connect(self._programar_colores_actos)
        _mod.rowsInserted.connect(self._programar_colores_actos)
        _mod.rowsRemoved.connect(self._programar_colores_actos)
        split.addWidget(self._lista)

        # Panel preview
        self._preview = QTextEdit()
        self._preview.setReadOnly(True)
        split.addWidget(self._preview)

        split.setStretchFactor(0, 3)
        split.setStretchFactor(1, 2)
        v_root.addWidget(split, 1)

        # Botonera inferior
        botonera = QHBoxLayout()
        botonera.setSpacing(8)
        self._btn_eliminar = QPushButton("🗑  Eliminar escena")
        self._btn_eliminar.setProperty("destructivo", True)
        self._btn_eliminar.setStyle(self._btn_eliminar.style())
        self._btn_eliminar.clicked.connect(self._eliminar_seleccionada)
        botonera.addWidget(self._btn_eliminar)

        # Botón para insertar un par de actos alrededor de la selección
        btn_nuevo_acto = QPushButton("🎬  Insertar acto…")
        btn_nuevo_acto.setProperty("secundario", True)
        btn_nuevo_acto.setStyle(btn_nuevo_acto.style())
        btn_nuevo_acto.setToolTip(
            "Envuelve la escena seleccionada en un nuevo par "
            "ACTO_INICIO … ACTO_FIN.")
        btn_nuevo_acto.clicked.connect(self._insertar_acto)
        botonera.addWidget(btn_nuevo_acto)

        botonera.addStretch()

        btn_cancelar = QPushButton("Cancelar")
        btn_cancelar.setProperty("secundario", True)
        btn_cancelar.setStyle(btn_cancelar.style())
        btn_cancelar.clicked.connect(self.reject)
        botonera.addWidget(btn_cancelar)

        btn_ok = QPushButton("✓  Aplicar cambios")
        btn_ok.clicked.connect(self._confirmar)
        botonera.addWidget(btn_ok)
        v_root.addLayout(botonera)

        if self._escenas:
            self._lista.setCurrentRow(0)
        self._colorear_actos()
        self._secuencia_inicial = self.secuencia_completa()

    # ─── Actos: como los paréntesis de Excel ────────────
    _ROL_QUITAR = int(Qt.ItemDataRole.UserRole) + 1

    def _acto_quitado(self, it) -> bool:
        return bool(it is not None and it.data(self._ROL_QUITAR))

    @staticmethod
    def _tipo_item(it) -> str:
        d = it.data(Qt.ItemDataRole.UserRole) if it is not None else None
        return d[0] if isinstance(d, tuple) else "escena"

    def _items_acto(self) -> list:
        return [self._lista.item(i) for i in range(self._lista.count())
                if self._tipo_item(self._lista.item(i)) in ("acto_inicio", "acto_fin")]

    def _programar_colores_actos(self, *_):
        QTimer.singleShot(0, self._colorear_actos)

    def _colorear_actos(self) -> None:
        """Un acto sin su par, en rojo (el globo dice qué le falta); una
        marca que se va a quitar, en gris tachada; las demás, naranjas."""
        try:
            items = self._items_acto()
        except RuntimeError:
            return
        vivos = [it for it in items if not self._acto_quitado(it)]
        bloques = [Bloque(Elem.ACTO_INICIO if self._tipo_item(it) == "acto_inicio" else Elem.ACTO_FIN,
                          it.text().split("  ", 1)[-1].strip()) for it in vivos]
        est = estado_actos(bloques)
        k_de = {id(it): k for k, it in enumerate(vivos)}
        for it in items:
            f = QFont()
            f.setBold(True)
            f.setPointSize(11)
            if self._acto_quitado(it):
                f.setStrikeOut(True)
                it.setBackground(QBrush(QColor("#3a4150")))
                it.setForeground(QBrush(QColor("#9aa5b8")))
                it.setToolTip("Esta marca de acto se quita al aplicar los cambios "
                              "(las escenas no se tocan). «Suprimir» otra vez: la deja.")
            else:
                k = k_de[id(it)]
                rojo = acto_sin_par(est.get(k))
                it.setBackground(QBrush(QColor("#dc2626" if rojo else "#ff8c1a")))
                it.setForeground(QBrush(QColor("white")))
                it.setToolTip(texto_estado_acto(bloques, k, est))
            it.setFont(f)

    # ─── Helpers ────────────────────────────────────────

    def _crear_item(self, esc: dict) -> QListWidgetItem:
        """Crea un QListWidgetItem representando una escena. Guarda el
        número original en UserRole para poder rastrearla tras el
        reordenamiento."""
        num = esc["numero"]
        pjs = ", ".join(esc["personajes"][:3])
        if len(esc["personajes"]) > 3:
            pjs += f" +{len(esc['personajes']) - 3}"
        # Estado de producción (si existe)
        estado_str = ""
        est = (self.doc.estados_produccion or {}).get(str(num))
        if est:
            estado_id = est.get("estado", "")
            estado_str = f"  {self._emoji_estado(estado_id)}"
        etiqueta = (
            f"#{num:>3}  {esc['encabezado']}\n"
            f"      {pjs or '(sin personajes)'}"
            f"  ·  {esc['n_dialogos']} diál. · "
            f"{esc['n_palabras']} pal.{estado_str}")
        it = QListWidgetItem(etiqueta)
        it.setData(Qt.ItemDataRole.UserRole,
                    ("escena", num))
        return it

    def _crear_item_acto(self, acto: dict) -> QListWidgetItem:
        """Crea un item separador para ACTO_INICIO o ACTO_FIN.
        Es visualmente distinto (fondo naranja) y NO se puede
        seleccionar/arrastrar como una escena.
        """
        icono = "🎬" if acto["tipo"] == "acto_inicio" else "🏁"
        etiqueta = f"{icono}  {acto['texto']}"
        it = QListWidgetItem(etiqueta)
        # Marcar el tipo y el índice de bloque en UserRole
        it.setData(Qt.ItemDataRole.UserRole,
                    (acto["tipo"], acto["idx_bloque"]))
        # Estilo visual: fondo naranja, texto blanco bold, no draggable
        from PySide6.QtGui import QColor, QFont, QBrush
        it.setBackground(QBrush(QColor("#ff8c1a")))
        it.setForeground(QBrush(QColor("white")))
        font = QFont()
        font.setBold(True)
        font.setPointSize(11)
        it.setFont(font)
        # Los actos SÍ se arrastran (v2). La regla «cada
        # ACTO_INICIO con su ACTO_FIN, sin solaparse» se valida al
        # aplicar (igual que paréntesis).
        flags = it.flags()
        flags |= Qt.ItemFlag.ItemIsDragEnabled
        flags &= ~Qt.ItemFlag.ItemIsDropEnabled
        it.setFlags(flags)
        return it

    def _on_doble_click(self, item: QListWidgetItem) -> None:
        """Doble clic sobre un separador de acto → renombrar el acto."""
        data = item.data(Qt.ItemDataRole.UserRole)
        if not data or not isinstance(data, tuple):
            return
        tipo, valor = data
        if tipo not in ("acto_inicio", "acto_fin"):
            return
        idx_bloque = valor
        bloque = (self.doc.bloques[idx_bloque]
                  if isinstance(idx_bloque, int) and 0 <= idx_bloque < len(self.doc.bloques)
                  and self.doc.bloques[idx_bloque].elem in (Elem.ACTO_INICIO, Elem.ACTO_FIN)
                  else None)
        texto_actual = (bloque.texto if bloque is not None
                        else item.text().split("  ", 1)[-1]).strip()
        placeholder = ("PRIMER ACTO" if tipo == "acto_inicio"
                        else "FIN DEL PRIMER ACTO")
        nuevo, ok = QInputDialog.getText(
            self,
            "Renombrar " + ("inicio de acto" if tipo == "acto_inicio"
                             else "fin de acto"),
            "Nombre del acto:",
            QLineEdit.EchoMode.Normal,
            texto_actual or placeholder)
        if not ok:
            return
        nuevo = nuevo.strip()
        if not nuevo:
            return
        # Actualizar el bloque directamente en el documento
        if bloque is not None:
            bloque.texto = nuevo
        # Refrescar el texto del item en la lista
        icono = "🎬" if tipo == "acto_inicio" else "🏁"
        item.setText(f"{icono}  {nuevo}")
        self._colorear_actos()

    def _emoji_estado(self, estado_id: str) -> str:
        return {
            "sin_grabar":            "⚪",
            "parcialmente_grabada":  "🟡",
            "grabada":               "🟢",
            "sin_editar":            "🔵",
            "parcialmente_editada":  "🟣",
            "editada":               "🟪",
            "en_post":               "🟠",
            "post_producida":        "🔶",
            "terminada":             "✅",
        }.get(estado_id, "")

    def _on_seleccion(self) -> None:
        """Actualiza el panel de preview con el contenido de la
        escena seleccionada. Los items de acto muestran ayuda."""
        # Sincronizar el texto del botón «Eliminar» con la selección
        # actual (así refleja el estado de esta escena, no la última
        # acción hecha en otra).
        try:
            self._actualizar_texto_boton_eliminar()
        except Exception:
            pass
        item = self._lista.currentItem()
        if item is None:
            self._preview.setPlainText("")
            return
        data = item.data(Qt.ItemDataRole.UserRole)
        # Puede ser una tupla (tipo, valor) — nuevo formato — o un
        # int suelto — formato viejo por compatibilidad.
        if isinstance(data, tuple):
            tipo, valor = data
        else:
            tipo, valor = "escena", data
        if tipo != "escena":
            # Es un separador de acto: mostrar ayuda
            estado = (item.toolTip() or "").replace("\n", "\n     ")
            self._preview.setPlainText(
                f"\n\n     {'🎬' if tipo == 'acto_inicio' else '🏁'}  "
                f"Separador de acto\n\n"
                f"     Este bloque marca "
                + ("el INICIO de un acto." if tipo == "acto_inicio"
                    else "el FIN de un acto.")
                + (f"\n\n     {estado}" if estado else "")
                + "\n\n"
                "     • Haz DOBLE CLIC sobre él para renombrarlo.\n"
                "     • Arrástralo para cambiarlo de lugar.\n"
                "     • «Suprimir» quita esta marca (las escenas quedan).\n"
                "     • Los actos son opcionales: puedes mover las\n"
                "       escenas con actos, sin actos o con un acto\n"
                "       que todavía no cierras. Como los paréntesis de\n"
                "       Excel, uno sin su par se ve en rojo.\n")
            return
        num = valor
        esc = next((e for e in self._escenas if e["numero"] == num), None)
        if esc is None:
            self._preview.setPlainText("")
            return
        # Reconstruir el texto de la escena
        partes = []
        partes.append(esc["encabezado"])
        partes.append("")
        for i_b in range(esc["idx_inicio"] + 1, esc["idx_fin"]):
            b = self.doc.bloques[i_b]
            tx = (b.texto or "").strip()
            if b.elem == Elem.PERSONAJE:
                partes.append("")
                partes.append(f"                    {tx}")
            elif b.elem == Elem.DIALOGO:
                partes.append(f"          {tx}")
            elif b.elem == Elem.PARENTESIS:
                partes.append(f"               ({tx.strip('()')})")
            elif b.elem == Elem.ACCION:
                partes.append(tx)
            elif b.elem == Elem.TRANSICION:
                partes.append(f"                              {tx}")
            elif b.elem == Elem.PLANO:
                partes.append(tx)
        # Marcar si está eliminada
        header = ""
        if num in self._eliminadas:
            header = ("═══ ESTA ESCENA SERÁ ELIMINADA "
                       "AL APLICAR CAMBIOS ═══\n\n")
        self._preview.setPlainText(header + "\n".join(partes))

    def _eliminar_seleccionada(self) -> None:
        """Marca la escena seleccionada para eliminar (o la des-marca)."""
        item = self._lista.currentItem()
        if item is None:
            return
        data = item.data(Qt.ItemDataRole.UserRole)
        if isinstance(data, tuple):
            tipo, valor = data
        else:
            tipo, valor = "escena", data
        if tipo != "escena":
            # Una marca de acto se quita sola (las escenas no se tocan);
            # «Suprimir» otra vez la deja.
            item.setData(self._ROL_QUITAR, not self._acto_quitado(item))
            self._colorear_actos()
            self._actualizar_texto_boton_eliminar()
            self._on_seleccion()
            return
        num = valor
        if num in self._eliminadas:
            # Ya estaba marcada → desmarcar
            self._eliminadas.discard(num)
        else:
            # Confirmar
            esc = next((e for e in self._escenas if e["numero"] == num),
                        None)
            enc = esc["encabezado"] if esc else f"Escena #{num}"
            r = QMessageBox.question(
                self, "Eliminar escena",
                f"¿Marcar para eliminar la escena?\n\n"
                f"  #{num}  {enc}\n\n"
                "Se eliminará el encabezado, todas las acciones, "
                "diálogos, tags y estado de producción. Los "
                "cambios se aplicarán al hacer clic en «Aplicar».",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No)
            if r != QMessageBox.StandardButton.Yes:
                return
            self._eliminadas.add(num)
        # Refrescar visual del ítem: cambiar color si está marcada
        if num in self._eliminadas:
            item.setForeground(QColor("#ef4444"))
            if not item.text().startswith("🗑  "):
                item.setText("🗑  " + item.text())
        else:
            item.setForeground(QColor("#e2e8f0"))
            tx = item.text()
            if tx.startswith("🗑  "):
                item.setText(tx[3:])
        # Actualizar el texto del botón según la selección actual
        self._actualizar_texto_boton_eliminar()
        self._on_seleccion()

    def _actualizar_texto_boton_eliminar(self) -> None:
        """El texto del botón «Eliminar» refleja el estado de la escena
        actualmente seleccionada, no la última acción hecha."""
        item = self._lista.currentItem()
        if item is None:
            self._btn_eliminar.setText("🗑  Eliminar escena")
            return
        data = item.data(Qt.ItemDataRole.UserRole)
        if isinstance(data, tuple) and data[0] == "escena":
            num = data[1]
            if num in self._eliminadas:
                self._btn_eliminar.setText("↩  Deshacer eliminar")
            else:
                self._btn_eliminar.setText("🗑  Eliminar escena")
        elif self._acto_quitado(item):
            self._btn_eliminar.setText("↩  Dejar esta marca de acto")
        else:
            self._btn_eliminar.setText("🗑  Quitar esta marca de acto")

    def keyPressEvent(self, event) -> None:
        """Atajos de teclado del editor de escenas:
          • Delete / Suprimir → eliminar (o deshacer) escena.
          • Ctrl+Z → deshacer todas las marcas de eliminación.
        """
        if event.key() in (Qt.Key.Key_Delete, Qt.Key.Key_Backspace):
            self._eliminar_seleccionada()
            event.accept()
            return
        if (event.key() == Qt.Key.Key_Z
                and event.modifiers() & Qt.KeyboardModifier.ControlModifier):
            # Deshacer TODAS las marcas de eliminación (escenas y actos)
            if not self._eliminadas and not any(self._acto_quitado(x) for x in self._items_acto()):
                event.accept()
                return
            self._eliminadas.clear()
            # Refrescar toda la lista
            for i in range(self._lista.count()):
                it = self._lista.item(i)
                tx = it.text()
                if tx.startswith("🗑  "):
                    it.setText(tx[3:])
                it.setForeground(QColor("#e2e8f0"))
                it.setData(self._ROL_QUITAR, False)
            self._colorear_actos()
            self._actualizar_texto_boton_eliminar()
            self._on_seleccion()
            event.accept()
            return
        super().keyPressEvent(event)

    def _insertar_acto(self) -> None:
        """Pone un INICIO y un FIN DE ACTO alrededor de la escena elegida
        (o de todo, si no hay una elegida). Va a la lista: al guion llega
        con «Aplicar cambios». Como los paréntesis de Excel, no hay nada
        prohibido: si un acto queda sin su par, se ve en rojo."""
        item = self._lista.currentItem()
        n_actos = sum(1 for it in self._items_acto()
                      if self._tipo_item(it) == "acto_inicio" and not self._acto_quitado(it)) + 1
        ordinales = ["PRIMER", "SEGUNDO", "TERCER", "CUARTO", "QUINTO",
                      "SEXTO", "SÉPTIMO", "OCTAVO", "NOVENO", "DÉCIMO"]
        sugerido = (f"{ordinales[n_actos - 1]} ACTO"
                    if n_actos <= len(ordinales)
                    else f"ACTO {n_actos}")
        nombre, ok = QInputDialog.getText(
            self, "Insertar acto",
            "Nombre del acto (se usará para ACTO_INICIO y ACTO_FIN):",
            QLineEdit.EchoMode.Normal, sugerido)
        if not ok or not nombre.strip():
            return
        nombre = nombre.strip().upper()
        fila_ini, fila_fin = 0, self._lista.count()
        if item is not None and self._tipo_item(item) == "escena":
            fila = self._lista.row(item)
            fila_ini, fila_fin = fila, fila + 1
        it_fin = self._crear_item_acto({"tipo": "acto_fin", "texto": f"FIN DEL {nombre}", "idx_bloque": -1})
        it_ini = self._crear_item_acto({"tipo": "acto_inicio", "texto": nombre, "idx_bloque": -1})
        self._lista.insertItem(fila_fin, it_fin)
        self._lista.insertItem(fila_ini, it_ini)
        self._colorear_actos()
        self._lista.setCurrentItem(it_ini)
        QMessageBox.information(
            self, "Acto insertado",
            f"Se marcó «{nombre}». Llega al guion con «✓ Aplicar cambios». "
            "Puedes renombrar el INICIO o el FIN con doble clic, o arrastrarlos.")

    def _validar_actos_balanceados(self) -> tuple[bool, str]:
        """Verifica que los actos queden balanceados tras el
        reordenamiento (regla como paréntesis Excel: cada ACTO_INICIO
        debe tener su ACTO_FIN correspondiente, sin solaparse).

        Devuelve (ok, mensaje_error)."""
        pila = 0
        for i in range(self._lista.count()):
            it = self._lista.item(i)
            data = it.data(Qt.ItemDataRole.UserRole)
            if not isinstance(data, tuple) or self._acto_quitado(it):
                continue
            tipo, _ = data
            if tipo == "acto_inicio":
                pila += 1
            elif tipo == "acto_fin":
                if pila <= 0:
                    return (False,
                            "Hay un ACTO_FIN sin su ACTO_INICIO "
                            "correspondiente (cierra un acto que no "
                            "está abierto).")
                pila -= 1
        if pila > 0:
            return (False,
                    f"Quedan {pila} acto(s) sin cerrar "
                    "(ACTO_INICIO sin su ACTO_FIN).")
        return (True, "")

    def _confirmar(self) -> None:
        """Antes de aceptar, pedir confirmación si hubo cambios. Los actos
        son opcionales (muchas veces se marcan al final): un acto sin
        cerrar, o ninguno, no impide mover ni borrar escenas."""
        ok, err = self._validar_actos_balanceados()
        # Detectar si hubo reordenamiento o eliminación
        nuevo = self.nuevo_orden()
        original = [e["numero"] for e in self._escenas]
        hubo_reorden = (nuevo != original or
                        self.secuencia_completa()
                        != getattr(self, "_secuencia_inicial", None))
        hubo_eliminar = len(self._eliminadas) > 0
        if not hubo_reorden and not hubo_eliminar:
            QMessageBox.information(
                self, "Sin cambios",
                "No se detectaron cambios de orden ni escenas a eliminar.")
            return
        mensaje = []
        n_quitados = sum(1 for x in self._items_acto() if self._acto_quitado(x))
        if nuevo != original:
            mensaje.append(
                "• Se reordenaron una o más escenas. Los bloques "
                "correspondientes se moverán en conjunto.")
        if n_quitados:
            mensaje.append(
                f"• Se quitará{'n' if n_quitados > 1 else ''} {n_quitados} marca(s) de acto "
                "(las escenas no se tocan).")
        elif hubo_reorden and nuevo == original:
            mensaje.append("• Cambian las marcas de acto (de lugar, de nombre o nuevas).")
        if hubo_eliminar:
            mensaje.append(
                f"• Se eliminarán {len(self._eliminadas)} escena(s) "
                "completa(s) con TODOS sus bloques.")
        if not ok:
            mensaje.append(
                f"• Ojo (no impide nada): {err[0].lower() + err[1:]} Los actos "
                "son opcionales: los puedes ordenar cuando quieras.")
        mensaje.append("")
        mensaje.append(
            "Los estados de producción y las jornadas se actualizarán "
            "automáticamente para reflejar los nuevos números de escena. "
            "Esta acción se puede deshacer con Ctrl+Z desde el editor.")
        r = QMessageBox.question(
            self, "Aplicar cambios",
            "¿Aplicar los cambios al guion?\n\n" + "\n".join(mensaje),
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No)
        if r == QMessageBox.StandardButton.Yes:
            self.accept()

    # ─── API pública ──────────────────────────────

    def nuevo_orden(self) -> list[int]:
        """Devuelve la lista de números de escena ORIGINALES en el
        nuevo orden actual (según cómo quedaron reordenados en la
        lista). Ignora los separadores de acto (los actos no se
        reordenan)."""
        out = []
        for i in range(self._lista.count()):
            it = self._lista.item(i)
            data = it.data(Qt.ItemDataRole.UserRole)
            if isinstance(data, tuple):
                tipo, valor = data
            else:
                tipo, valor = "escena", data
            if tipo == "escena":
                out.append(int(valor))
        return out

    def escenas_eliminadas(self) -> set[int]:
        return set(self._eliminadas)

    def secuencia_completa(self) -> list[tuple]:
        """Orden visual completo: [("escena", n_original) |
        ("acto_ini", titulo) | ("acto_fin", titulo)]. Permite
        reposicionar también los actos al aplicar."""
        out = []
        for i in range(self._lista.count()):
            it = self._lista.item(i)
            data = it.data(Qt.ItemDataRole.UserRole)
            if isinstance(data, tuple):
                tipo, _valor = data
                if tipo in ("acto_inicio", "acto_fin") and self._acto_quitado(it):
                    continue                      # (esa marca de acto se quita)
                if tipo in ("acto_inicio", "acto_fin"):
                    # (con su nombre: antes se perdían los actos al aplicar)
                    txt = it.text().split("  ", 1)[-1].strip()
                    out.append(("acto_ini" if tipo == "acto_inicio" else "acto_fin", txt))
                else:
                    out.append(data)
            else:
                out.append(("escena", int(data)))
        return out


def reordenar_actos_segun_secuencia(doc: "Documento",
                                    secuencia: list[tuple]) -> None:
    """Reconstruye doc.bloques colocando los marcadores de acto en
    las posiciones de la secuencia visual del Editor de escenas.
    Las escenas ya vienen reordenadas por aplicar_reorden_escenas;
    aquí solo se re-ubican los ACTO_INICIO / ACTO_FIN."""
    bloques = doc.bloques
    # 1) Separar: prólogo (antes de la 1ª escena), rebanadas por
    #    escena, y quitar todos los bloques de acto existentes.
    sin_actos = [b for b in bloques
                 if b.elem not in (Elem.ACTO_INICIO, Elem.ACTO_FIN)]
    idx_escenas = [i for i, b in enumerate(sin_actos)
                   if b.elem == Elem.ESCENA]
    if not idx_escenas:
        # Sin escenas: las marcas que siguen quedan donde estaban, las
        # quitadas se van y las nuevas van al final.
        from collections import Counter
        quedan = Counter(("acto_ini" if t in ("acto_ini", "acto_inicio") else "acto_fin",
                          str(v).strip()) for t, v in secuencia if t != "escena")
        nuevos: list = []
        for b in bloques:
            if b.elem in (Elem.ACTO_INICIO, Elem.ACTO_FIN):
                k = ("acto_ini" if b.elem == Elem.ACTO_INICIO else "acto_fin", (b.texto or "").strip())
                if quedan.get(k, 0) > 0:
                    quedan[k] -= 1
                    nuevos.append(b)
            else:
                nuevos.append(b)
        for (t, v), n in quedan.items():
            for _ in range(n):
                nuevos.append(Bloque(Elem.ACTO_INICIO if t == "acto_ini" else Elem.ACTO_FIN, v))
        doc.bloques[:] = nuevos
        return
    prologo = sin_actos[:idx_escenas[0]]
    rebanadas = []
    for k, ini in enumerate(idx_escenas):
        fin = (idx_escenas[k + 1] if k + 1 < len(idx_escenas)
               else len(sin_actos))
        rebanadas.append(sin_actos[ini:fin])
    # 2) Reconstruir siguiendo la secuencia (k-ésima escena de la
    #    secuencia = k-ésima rebanada)
    nuevos: list = list(prologo)
    k = 0
    for tipo, valor in secuencia:
        if tipo in ("acto_ini", "acto_inicio"):
            nuevos.append(Bloque(Elem.ACTO_INICIO, str(valor)))
        elif tipo == "acto_fin":
            nuevos.append(Bloque(Elem.ACTO_FIN, str(valor)))
        elif tipo == "escena":
            if k < len(rebanadas):
                nuevos.extend(rebanadas[k])
                k += 1
    # Rebanadas sobrantes (por seguridad) al final
    while k < len(rebanadas):
        nuevos.extend(rebanadas[k])
        k += 1
    doc.bloques[:] = nuevos


class VentanaBeatBoard(QDialog):
    """Pizarra de beats con tarjetas arrastrables y conectores."""

    enviar_solicitado = Signal(list)  # list[Beat] en orden

    def __init__(self, documento: "Documento", parent=None):
        super().__init__(parent)
        self.documento = documento
        self.setWindowTitle("Pizarra de beats — planificación con tarjetas")
        habilitar_snap(self, "🧩")
        self.resize(px(1200), px(780))
        # Items en pantalla
        self._items_tarjetas: list[_TarjetaBeat] = []
        self._items_fotos:    list[_FotoBeat]    = []
        self._items_flechas:  list = []
        # Estado del drag de flechas (arrastrar desde un gancho)
        self._arrow_origen_idx:  Optional[int] = None
        self._arrow_origen_lado: Optional[str] = None
        self._arrow_punto_inicial: QPointF = QPointF(0, 0)
        self._arrow_temp = None  # QGraphicsPathItem temporal mientras arrastra

        layout = QVBoxLayout(self)
        layout.setContentsMargins(px(12), px(10), px(12), px(10))
        layout.setSpacing(px(8))

        # Toolbar
        bar = QHBoxLayout()
        bar.setSpacing(px(6))

        def b(texto: str, slot, color: str = None) -> QPushButton:
            btn = QPushButton(texto)
            if color:
                btn.setStyleSheet(f"""
                    QPushButton {{
                        background: {color}; color: #e8edf4; font-weight: bold;
                        padding: 7px 14px; border: none;
                        border-radius: 2px;
                    }}
                    QPushButton:hover {{ border: 1px solid #1a2636; }}
                """)
            btn.clicked.connect(slot)
            return btn

        bar.addWidget(b("➕  Nueva tarjeta", self._nueva_tarjeta))
        bar.addWidget(b("🎨  Cambiar color", self._cambiar_color))
        bar.addWidget(b("📷  Agregar foto", self._agregar_foto))
        bar.addWidget(b("❌  Quitar todas las flechas", self._quitar_flechas))
        bar.addWidget(b("✂  Borrar flecha…", self._modo_borrar_flecha))
        bar.addWidget(b("🗑  Eliminar selección", self._eliminar_seleccion))
        bar.addWidget(b("❓ Tutorial", self._tutorial))
        b_circ = b("🧭  Círculo del Protagonista ▾", lambda: None)
        m_circ = QMenu(b_circ)
        m_circ.addAction("📖  Ver el tutorial del Círculo del Protagonista", self._tutorial_circulo)
        m_circ.addSeparator()
        m_circ.addAction("🧭  Armar el círculo con preguntas para completar",
                         lambda: self.armar_circulo(con_ejemplo=False))
        m_circ.addAction("🎬  Armar el círculo con el ejemplo «La última función»",
                         lambda: self.armar_circulo(con_ejemplo=True))
        b_circ.setMenu(m_circ)
        b_circ.setToolTip("El recorrido que siguen casi todas las grandes historias: su tutorial, o las 11 "
                          "tarjetas ya armadas en círculo, con flechas, para que solo cambies lo que dicen")
        bar.addWidget(b_circ)
        bar.addStretch()
        bar.addWidget(b("📜  Enviar al guion →",
                        self._enviar_al_guion, "#ff8c1a"))
        layout.addLayout(bar)

        # 🎯 La premisa (la misma de la Escaleta: se escribe en una y aparece en la otra)
        fila_prem = QHBoxLayout()
        fila_prem.setSpacing(px(10))
        lbl_prem = QLabel("🎯  PREMISA")
        lbl_prem.setStyleSheet("color: #ffb066; font-size: 11pt; font-weight: 800;")
        lbl_prem.setToolTip("La misma premisa de la 📋 Escaleta: lo que escribas aquí aparece allá, "
                            "y al revés.")
        fila_prem.addWidget(lbl_prem, 0, Qt.AlignmentFlag.AlignTop)
        self._ed_premisa = editor_premisa(self.documento, px(52), self)
        self._ed_premisa.setToolTip(lbl_prem.toolTip())
        fila_prem.addWidget(self._ed_premisa, 1)
        layout.addLayout(fila_prem)

        # Ayuda visible
        self._lbl_estado = QLabel(
            "💡 Conecta arrastrando desde un gancho (incluso al vacío para "
            "crear tarjeta nueva). Shift+clic selecciona varias; clic "
            "derecho sobre la selección para ordenar/conectar/borrar. "
            "Escala desde la esquina inferior izquierda.<br>"
            "📜 Cuando la estructura esté lista, presiona "
            "<b>«Enviar al guion →»</b> arriba a la derecha: cada "
            "tarjeta se convierte en un bloque del guion "
            "(las que empiezan con INT./EXT. pasan como ENCABEZADO "
            "DE ESCENA, el resto como ACCIÓN).")
        self._lbl_estado.setStyleSheet(
            "color: #b0bcd2; font-size: 9pt; padding: 2px;")
        self._lbl_estado.setTextFormat(Qt.TextFormat.RichText)
        self._lbl_estado.setWordWrap(True)
        layout.addWidget(self._lbl_estado)

        # Estado para el modo "borrar flecha"
        self._borrando_flecha = False

        # Scene + View
        self.scene = QGraphicsScene(0, 0, 3000, 2000, self)
        self.scene.setBackgroundBrush(QColor("#1a1f2e"))
        self.view = QGraphicsView(self.scene)
        self.view.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        self.view.setRenderHint(QPainter.RenderHint.TextAntialiasing, True)
        # Rubber band para seleccionar varias tarjetas arrastrando en vacío
        self.view.setDragMode(QGraphicsView.DragMode.RubberBandDrag)
        # Menú contextual (clic derecho)
        self.view.setContextMenuPolicy(
            Qt.ContextMenuPolicy.CustomContextMenu)
        self.view.customContextMenuRequested.connect(self._menu_contextual)
        # Click para el modo borrar-flecha
        self.scene.installEventFilter(self)
        # Repintado completo del viewport: evita los artefactos de
        # líneas verticales al arrastrar tarjetas (regiones sucias).
        self.view.setViewportUpdateMode(
            QGraphicsView.ViewportUpdateMode.FullViewportUpdate)
        self.view.setStyleSheet(
            f"QGraphicsView {{ background: #0d1520; "
            f"border: 1px solid #26344a; border-radius: 6px; }}")
        layout.addWidget(self.view, 1)

        # Cerrar
        cerrar = QPushButton("Cerrar")
        cerrar.clicked.connect(self.accept)
        h2 = QHBoxLayout()
        h2.addStretch()
        h2.addWidget(cerrar)
        layout.addLayout(h2)

        # Construir items iniciales
        self._reconstruir()

        # Abrir tutorial automáticamente la primera vez que el usuario
        # abre la Pizarra de beats. Después se puede volver a ver con el
        # botón ❓ Tutorial. Se recuerda en QSettings.
        s = settings_app()
        if not s.value("tutorial_beatboard_visto", False, type=bool):
            QTimer.singleShot(400, self._tutorial)
            s.setValue("tutorial_beatboard_visto", True)

    # ─── construcción / refresco ──────────────────────────────────────

    def _reconstruir(self) -> None:
        """Limpia y vuelve a crear todos los items desde el modelo."""
        self.scene.clear()
        self._items_tarjetas = []
        self._items_fotos    = []
        self._items_flechas  = []
        # Fotos primero (van atrás)
        for i, foto in enumerate(self.documento.fotos_beatboard):
            it = _FotoBeat(foto, i, self)
            it.setZValue(-2)
            self.scene.addItem(it)
            self._items_fotos.append(it)
        # Tarjetas
        for i, beat in enumerate(self.documento.beats):
            it = _TarjetaBeat(beat, i, self)
            self.scene.addItem(it)
            self._items_tarjetas.append(it)
        self._actualizar_flechas()

    def _actualizar_flechas(self) -> None:
        """Recalcula todos los conectores: tarjeta→tarjeta, tarjeta→foto,
        foto→tarjeta y foto→foto. Cada flecha guarda metadata para poder
        eliminarla individualmente."""
        for fl in self._items_flechas:
            self.scene.removeItem(fl)
        self._items_flechas = []

        def item_destino(destino_tipo: str, idx: int):
            if destino_tipo == "foto":
                if 0 <= idx < len(self._items_fotos):
                    return self._items_fotos[idx]
            else:
                if 0 <= idx < len(self._items_tarjetas):
                    return self._items_tarjetas[idx]
            return None

        # Conexiones desde tarjetas
        for i, beat in enumerate(self.documento.beats):
            if i >= len(self._items_tarjetas):
                continue
            it_o = self._items_tarjetas[i]
            usados = set()
            for c in beat.conexiones_lados:
                dt = c.get("destino_tipo", "tarjeta")
                j = c.get("destino", -1)
                it_d = item_destino(dt, j)
                if it_d is None:
                    continue
                lo = c.get("lado_origen", "right")
                ld = c.get("lado_destino", "left")
                p0 = it_o.centro_lado_en_scene(lo)
                p1 = it_d.centro_lado_en_scene(ld)
                fl = self._crear_flecha(p0, p1, lo, ld)
                fl._meta = ("tarjeta", i, c)  # origen_tipo, origen_idx, dict
                self.scene.addItem(fl)
                self._items_flechas.append(fl)
                if dt == "tarjeta":
                    usados.add(j)
            # Legacy centro-a-centro
            for j in beat.conexiones:
                if j in usados or not (0 <= j < len(self._items_tarjetas)):
                    continue
                p0 = it_o.centro_lado_en_scene("right")
                p1 = self._items_tarjetas[j].centro_lado_en_scene("left")
                fl = self._crear_flecha(p0, p1, "right", "left")
                fl._meta = ("tarjeta_legacy", i, j)
                self.scene.addItem(fl)
                self._items_flechas.append(fl)

        # Conexiones desde fotos
        for i, foto in enumerate(self.documento.fotos_beatboard):
            if i >= len(self._items_fotos):
                continue
            it_o = self._items_fotos[i]
            for c in foto.conexiones_lados:
                dt = c.get("destino_tipo", "tarjeta")
                j = c.get("destino", -1)
                it_d = item_destino(dt, j)
                if it_d is None:
                    continue
                lo = c.get("lado_origen", "right")
                ld = c.get("lado_destino", "left")
                p0 = it_o.centro_lado_en_scene(lo)
                p1 = it_d.centro_lado_en_scene(ld)
                fl = self._crear_flecha(p0, p1, lo, ld)
                fl._meta = ("foto", i, c)
                self.scene.addItem(fl)
                self._items_flechas.append(fl)

    def _crear_flecha(self, p0: QPointF, p1: QPointF,
                       lado_origen: str = "right",
                       lado_destino: str = "left"):
        """Línea + cabeza de flecha orientada según el lado destino.
        La curva ‘sale’ con la normal del lado origen y ‘entra’ por la
        normal del lado destino, para que se vea natural."""
        from PySide6.QtGui import QPainterPath, QPen
        from PySide6.QtWidgets import QGraphicsPathItem
        import math

        normales = {
            "top":   (0, -1),
            "right": (1,  0),
            "bot":   (0,  1),
            "left":  (-1, 0),
        }
        nox, noy = normales.get(lado_origen, (1, 0))
        ndx, ndy = normales.get(lado_destino, (-1, 0))

        dist = max(60.0, math.hypot(p1.x() - p0.x(), p1.y() - p0.y()) * 0.4)
        c1 = QPointF(p0.x() + nox * dist, p0.y() + noy * dist)
        c2 = QPointF(p1.x() + ndx * dist, p1.y() + ndy * dist)

        path = QPainterPath()
        path.moveTo(p0)
        path.cubicTo(c1, c2, p1)

        # Cabeza de flecha en la dirección de "entrada" del destino
        # (opuesto a la normal del lado destino)
        ang = math.atan2(-ndy, -ndx)
        L = 12
        a1 = ang + math.radians(150)
        a2 = ang - math.radians(150)
        path.moveTo(p1)
        path.lineTo(p1.x() + L * math.cos(a1), p1.y() + L * math.sin(a1))
        path.moveTo(p1)
        path.lineTo(p1.x() + L * math.cos(a2), p1.y() + L * math.sin(a2))

        item = QGraphicsPathItem(path)
        item.setPen(QPen(QColor("#ff8c1a"), 2))
        item.setZValue(-1)
        return item

    # ─── drag-drop de flechas desde ganchos ───────────────────────────

    def _iniciar_arrow_drag(self, idx_origen: int, lado: str,
                             punto_scene: QPointF,
                             origen_tipo: str = "tarjeta") -> None:
        """Llamado por una tarjeta o foto al hacer click en un gancho.
        Crea una línea temporal amarilla discontinua que sigue al cursor."""
        from PySide6.QtGui import QPainterPath, QPen
        from PySide6.QtWidgets import QGraphicsPathItem
        self._arrow_origen_idx  = idx_origen
        self._arrow_origen_lado = lado
        self._arrow_origen_tipo = origen_tipo
        self._arrow_punto_inicial = punto_scene
        if self._arrow_temp is not None:
            try:
                self.scene.removeItem(self._arrow_temp)
            except Exception:
                pass
        path = QPainterPath()
        path.moveTo(punto_scene)
        path.lineTo(punto_scene)
        self._arrow_temp = QGraphicsPathItem(path)
        pen = QPen(QColor("#ffd166"), 2.5)
        pen.setStyle(Qt.PenStyle.DashLine)
        self._arrow_temp.setPen(pen)
        self._arrow_temp.setZValue(10)
        self.scene.addItem(self._arrow_temp)

    def _actualizar_arrow_drag(self, pos_scene: QPointF) -> None:
        if self._arrow_temp is None:
            return
        from PySide6.QtGui import QPainterPath
        path = QPainterPath()
        path.moveTo(self._arrow_punto_inicial)
        path.lineTo(pos_scene)
        self._arrow_temp.setPath(path)

    def _terminar_arrow_drag(self, idx_origen: int, lado_origen: str,
                              pos_release: QPointF,
                              origen_tipo: str = "tarjeta") -> None:
        """Si se soltó sobre una tarjeta o foto, crea la conexión. Si se
        soltó en el vacío, crea una tarjeta nueva ahí y la conecta."""
        if self._arrow_temp is not None:
            try:
                self.scene.removeItem(self._arrow_temp)
            except Exception:
                pass
            self._arrow_temp = None

        # Lista de conexiones del origen (tarjeta o foto)
        if origen_tipo == "foto":
            if not (0 <= idx_origen < len(self.documento.fotos_beatboard)):
                return
            origen_conx = self.documento.fotos_beatboard[idx_origen].conexiones_lados
        else:
            if not (0 <= idx_origen < len(self.documento.beats)):
                return
            origen_conx = self.documento.beats[idx_origen].conexiones_lados

        # Buscar destino (tarjeta o foto) bajo el cursor
        for it in self.scene.items(pos_release):
            if isinstance(it, _TarjetaBeat):
                if origen_tipo == "tarjeta" and it._indice == idx_origen:
                    continue  # no auto-conexión a sí misma
                local = it.mapFromScene(pos_release)
                lado_d = self._lado_mas_cercano_xy(
                    local, it._beat.w, it._beat.h)
                self._agregar_conexion(origen_conx, it._indice, "tarjeta",
                                       lado_origen, lado_d)
                self._actualizar_flechas()
                return
            if isinstance(it, _FotoBeat):
                if origen_tipo == "foto" and it._indice == idx_origen:
                    continue
                local = it.mapFromScene(pos_release)
                lado_d = self._lado_mas_cercano_xy(
                    local, it._foto.w, it._foto.h)
                self._agregar_conexion(origen_conx, it._indice, "foto",
                                       lado_origen, lado_d)
                self._actualizar_flechas()
                return

        # Soltó en el vacío → crear tarjeta nueva conectada
        nueva_idx = len(self.documento.beats)
        beat = Beat(
            titulo=f"Tarjeta {nueva_idx + 1}",
            descripcion="(doble-click para editar)",
            color=COLORES_BEATS[nueva_idx % len(COLORES_BEATS)][1],
            x=pos_release.x() - 90,
            y=pos_release.y() - 20,
        )
        self.documento.beats.append(beat)
        # Conectar el origen a la nueva tarjeta (entrando por el lado izq)
        self._agregar_conexion(origen_conx, nueva_idx, "tarjeta",
                               lado_origen, "left")
        self._reconstruir()

    def _agregar_conexion(self, lista_conx: list, destino: int,
                          destino_tipo: str, lado_o: str, lado_d: str) -> None:
        """Agrega una conexión a la lista si no existe ya."""
        ya = any(
            c.get("destino") == destino
            and c.get("destino_tipo", "tarjeta") == destino_tipo
            and c.get("lado_origen") == lado_o
            and c.get("lado_destino") == lado_d
            for c in lista_conx
        )
        if not ya:
            lista_conx.append({
                "destino": destino,
                "destino_tipo": destino_tipo,
                "lado_origen": lado_o,
                "lado_destino": lado_d,
            })

    def _lado_mas_cercano_xy(self, pos_local: QPointF,
                             w: float, h: float) -> str:
        """Lado más cercano al punto, dadas las dimensiones del item."""
        dx_izq = pos_local.x()
        dx_der = w - pos_local.x()
        dy_top = pos_local.y()
        dy_bot = h - pos_local.y()
        m = min(dx_izq, dx_der, dy_top, dy_bot)
        if m == dx_izq: return "left"
        if m == dx_der: return "right"
        if m == dy_top: return "top"
        return "bot"

    # ─── operaciones ──────────────────────────────────────────────────

    def _nueva_tarjeta(self) -> None:
        centro_vp = self.view.mapToScene(
            self.view.viewport().rect().center())
        beat = Beat(
            titulo=f"Tarjeta {len(self.documento.beats) + 1}",
            descripcion="(doble-click para editar)",
            color=COLORES_BEATS[
                len(self.documento.beats) % len(COLORES_BEATS)][1],
            x=centro_vp.x() - 90,
            y=centro_vp.y() - 60,
        )
        self.documento.beats.append(beat)
        self._reconstruir()

    def _agregar_foto(self) -> None:
        """Pregunta por una imagen y la agrega al board. La foto se
        embebe como base64 en el documento para que viaje al invitado
        en colaboración."""
        ruta, _ = QFileDialog.getOpenFileName(
            self, "Elige una imagen",
            carpeta_para_adjuntar(self),
            "Imágenes (*.png *.jpg *.jpeg *.bmp *.gif *.webp);;Todos (*.*)")
        if not ruta:
            return
        recordar_carpeta_adjuntos(self, ruta)
        # Comprimir y embeber como base64 (viaja al invitado)
        datos_b64 = comprimir_imagen_a_b64(ruta)
        if not datos_b64:
            QMessageBox.warning(
                self, "No se pudo cargar",
                f"La imagen «{Path(ruta).name}» no se pudo procesar.")
            return
        centro_vp = self.view.mapToScene(
            self.view.viewport().rect().center())
        foto = FotoBeat(
            path=ruta,
            datos_b64=datos_b64,
            x=centro_vp.x() - 110,
            y=centro_vp.y() - 80,
        )
        # Si la imagen existe, usar su tamaño nativo proporcional
        pix = QPixmap(ruta)
        if not pix.isNull():
            ancho_max = 280.0
            ratio = pix.height() / pix.width() if pix.width() else 0.66
            foto.w = ancho_max
            foto.h = ancho_max * ratio
        self.documento.fotos_beatboard.append(foto)
        self._reconstruir()

    def _editar_tarjeta(self, indice: int) -> None:
        if not (0 <= indice < len(self.documento.beats)):
            return
        beat = self.documento.beats[indice]
        dlg = QDialog(self)
        dlg.setWindowTitle("Editar tarjeta")
        dlg.resize(px(420), px(320))
        lay = QVBoxLayout(dlg)
        lay.addWidget(QLabel("Título:"))
        ed_tit = QLineEdit(beat.titulo)
        lay.addWidget(ed_tit)
        lay.addWidget(QLabel("Descripción:"))
        ed_desc = QTextEdit()
        ed_desc.setPlainText(beat.descripcion)
        ed_desc.setMinimumHeight(px(140))
        if beat.descripcion.strip() in ("(doble-click para editar)",
                                        "(doble-clic para editar)"):
            ed_desc.selectAll()
        lay.addWidget(ed_desc)
        bb = QHBoxLayout(); bb.addStretch()
        ok = QPushButton("Guardar"); ok.setDefault(True)
        ok.clicked.connect(dlg.accept)
        cancel = QPushButton("Cancelar"); cancel.clicked.connect(dlg.reject)
        bb.addWidget(cancel); bb.addWidget(ok)
        lay.addLayout(bb)
        if dlg.exec() == QDialog.DialogCode.Accepted:
            beat.titulo = ed_tit.text().strip() or beat.titulo
            beat.descripcion = ed_desc.toPlainText().strip()
            self._reconstruir()

    def _eliminar_seleccion(self) -> None:
        """Elimina las tarjetas y/o fotos seleccionadas, reajustando
        todas las conexiones (de tarjetas y de fotos) que las referencien."""
        sel = self.scene.selectedItems()
        if not sel:
            QMessageBox.information(
                self, "Eliminar",
                "Selecciona primero una o más tarjetas o fotos.")
            return
        idx_tarjetas = sorted({
            it._indice for it in sel if isinstance(it, _TarjetaBeat)
        }, reverse=True)
        idx_fotos = sorted({
            it._indice for it in sel if isinstance(it, _FotoBeat)
        }, reverse=True)

        def reindexar(lista_conx, borrado_idx, tipo_borrado):
            """Quita conexiones al item borrado y decrementa índices
            mayores del mismo tipo."""
            nueva = []
            for c in lista_conx:
                dt = c.get("destino_tipo", "tarjeta")
                d = c.get("destino", -1)
                if dt == tipo_borrado and d == borrado_idx:
                    continue  # apuntaba al borrado: se elimina
                if dt == tipo_borrado and d > borrado_idx:
                    c = {**c, "destino": d - 1}
                nueva.append(c)
            return nueva

        # Eliminar tarjetas (de mayor a menor)
        for i in idx_tarjetas:
            for otra in self.documento.beats:
                otra.conexiones = [
                    (c if c < i else c - 1)
                    for c in otra.conexiones if c != i
                ]
                otra.conexiones_lados = reindexar(
                    otra.conexiones_lados, i, "tarjeta")
            for foto in self.documento.fotos_beatboard:
                foto.conexiones_lados = reindexar(
                    foto.conexiones_lados, i, "tarjeta")
            self.documento.beats.pop(i)

        # Eliminar fotos (de mayor a menor)
        for i in idx_fotos:
            if not (0 <= i < len(self.documento.fotos_beatboard)):
                continue
            for beat in self.documento.beats:
                beat.conexiones_lados = reindexar(
                    beat.conexiones_lados, i, "foto")
            for foto in self.documento.fotos_beatboard:
                foto.conexiones_lados = reindexar(
                    foto.conexiones_lados, i, "foto")
            self.documento.fotos_beatboard.pop(i)

        self._reconstruir()

    def _cambiar_color(self) -> None:
        sel = self.scene.selectedItems()
        if not sel:
            QMessageBox.information(
                self, "Cambiar color",
                "Selecciona primero una tarjeta haciendo click sobre ella.")
            return
        menu = QMenu(self)
        menu.setStyleSheet(f"""
            QMenu {{ background: #131d2b; color: #e8edf4;
                     border: 1px solid #ff8c1a; padding: 4px; }}
            QMenu::item {{ padding: 6px 20px;
                           min-width: 120px; }}
            QMenu::item:selected {{ background: #ff8c1a; color: #241203; }}
        """)
        for nombre, color in COLORES_BEATS:
            pix = QPixmap(16, 16)
            pix.fill(Qt.GlobalColor.transparent)
            pp = QPainter(pix)
            pp.fillRect(1, 1, 14, 14, QColor(color))
            pp.setPen(QColor("#222"))
            pp.drawRect(0, 0, 15, 15)
            pp.end()
            act = menu.addAction(QIcon(pix), f"  {nombre}")
            act.triggered.connect(
                lambda _, c=color: self._aplicar_color_a_sel(c))
        menu.exec(QCursor.pos())

    def _aplicar_color_a_sel(self, color: str) -> None:
        for it in self.scene.selectedItems():
            if isinstance(it, _TarjetaBeat):
                self.documento.beats[it._indice].color = color
                it.update()

    def _tutorial(self) -> None:
        """Abre el tutorial interactivo de la Pizarra de beats."""
        self._tut = TutorialFlotante(
            "❓ Tutorial de la Pizarra de beats",
            _pasos_tutorial_beatboard(),
            parent=self)
        self._tut.show()

    def _tutorial_circulo(self) -> None:
        """🧭 El tutorial del Círculo del Protagonista (el mismo de la Escaleta)."""
        self._tut = TutorialFlotante("🧭 El Círculo del Protagonista", pasos_circulo_protagonista(), parent=self)
        self._tut.show()

    def armar_circulo(self, con_ejemplo: bool = False) -> int:
        """🧭 Las 11 estaciones del Círculo del Protagonista como tarjetas en
        círculo, unidas con flechas en orden: el estudiante solo cambia lo
        que dicen (con preguntas guía o con el ejemplo «La última
        función»). Si ya hay tarjetas, el círculo va a su derecha.
        Devuelve el índice de la primera tarjeta."""
        import math as _m
        beats = self.documento.beats
        w_t, h_t, radio = 210.0, 132.0, 470.0
        x_libre = max([b_.x + b_.w for b_ in beats] + [0.0]) + (140.0 if beats else 60.0)
        cx, cy = x_libre + radio + w_t / 2, 60.0 + radio + h_t / 2
        colores = {0: "#5b6ef5", 1: "#ff8c1a", 2: "#e8556d"}       # (acto 1, acto 2, acto 3)
        primero = len(beats)
        n = len(ESTACIONES_CIRCULO)
        for k, (titulo, pregunta, ejemplo) in enumerate(ESTACIONES_CIRCULO):
            ang = -_m.pi / 2 + 2 * _m.pi * k / n               # (empieza arriba y gira como el reloj)
            acto = 0 if k < 5 else (1 if k < 9 else 2)
            beats.append(Beat(titulo=f"{k + 1}. {titulo}", descripcion=ejemplo if con_ejemplo else pregunta,
                              color=colores[acto], x=cx + radio * _m.cos(ang) - w_t / 2,
                              y=cy + radio * _m.sin(ang) - h_t / 2, w=w_t, h=h_t))
        for k in range(n - 1):                                   # (flechas en orden; la última no vuelve a la 1)
            a_, b_ = beats[primero + k], beats[primero + k + 1]
            dx = (b_.x + b_.w / 2) - (a_.x + a_.w / 2)
            dy = (b_.y + b_.h / 2) - (a_.y + a_.h / 2)
            if abs(dx) >= abs(dy):
                lo, ld = ("right", "left") if dx > 0 else ("left", "right")
            else:
                lo, ld = ("bot", "top") if dy > 0 else ("top", "bot")
            self._agregar_conexion(a_.conexiones_lados, primero + k + 1, "tarjeta", lo, ld)
        self._reconstruir()
        self.scene.setSceneRect(self.scene.sceneRect().united(self.scene.itemsBoundingRect().adjusted(0, 0, 200, 200)))
        try:
            self.view.ensureVisible(QRectF(cx - radio - w_t, cy - radio - h_t, 2 * (radio + w_t), 2 * (radio + h_t)))
        except Exception:
            pass
        self._lbl_estado.setText("🧭 <b>Círculo armado.</b> Doble clic en cada tarjeta para cambiar lo que dice "
                                 "con tu historia. Azul: el comienzo · naranja: el medio · rojo: el final. "
                                 "Cuando esté lista, «📜 Enviar al guion →».")
        p_ = self.parent()
        if hasattr(p_, "_marcar_dirty"):
            p_._marcar_dirty()
        return primero

    def _quitar_flechas(self) -> None:
        hay = (any(b.conexiones or b.conexiones_lados
                   for b in self.documento.beats)
               or any(f.conexiones_lados
                      for f in self.documento.fotos_beatboard))
        if not hay:
            return
        r = QMessageBox.question(
            self, "Quitar flechas",
            "¿Eliminar TODAS las flechas del tablero?",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No)
        if r == QMessageBox.StandardButton.Yes:
            for b in self.documento.beats:
                b.conexiones = []
                b.conexiones_lados = []
            for f in self.documento.fotos_beatboard:
                f.conexiones_lados = []
            self._actualizar_flechas()

    def _modo_borrar_flecha(self) -> None:
        """Activa/desactiva el modo en que el próximo clic sobre una
        flecha la elimina."""
        self._borrando_flecha = not self._borrando_flecha
        if self._borrando_flecha:
            self.view.setDragMode(QGraphicsView.DragMode.NoDrag)
            self.view.viewport().setCursor(Qt.CursorShape.ForbiddenCursor)
            self._lbl_estado.setText(
                "✂ Modo borrar flecha ACTIVO: haz clic sobre una flecha "
                "para eliminarla. Vuelve a pulsar «Borrar flecha» para salir.")
        else:
            self.view.setDragMode(QGraphicsView.DragMode.RubberBandDrag)
            self.view.viewport().unsetCursor()
            self._lbl_estado.setText(
                "💡 Conecta arrastrando desde un gancho (incluso al vacío "
                "para crear tarjeta nueva). Shift+clic selecciona varias; "
                "clic derecho sobre la selección para ordenar/conectar/borrar.")

    def eventFilter(self, obj, event):
        """Intercepta eventos de la escena para dos cosas:
          • Doble clic sobre el fondo vacío → crear tarjeta nueva
            en esa posición.
          • Clic en modo «borrar flecha» → detectar si cayó sobre
            una flecha para eliminarla.
        """
        from PySide6.QtCore import QEvent
        # Doble clic para crear tarjeta nueva
        if (obj is self.scene
                and event.type() ==
                    QEvent.Type.GraphicsSceneMouseDoubleClick
                and event.button() == Qt.MouseButton.LeftButton):
            pos = event.scenePos()
            # Solo si NO hay item bajo el cursor (fondo vacío).
            # Si hay una tarjeta o foto, dejar que el doble clic
            # llegue al item (edita la tarjeta).
            item_bajo = self.scene.itemAt(pos, self.view.transform())
            if item_bajo is None:
                # Crear tarjeta centrada en el punto del doble clic
                b = Beat(
                    titulo="Nueva tarjeta",
                    x=pos.x() - 90,   # centrar (ancho por defecto 180)
                    y=pos.y() - 60)   # centrar (alto por defecto 120)
                self.documento.beats.append(b)
                self._reconstruir()
                # Marcar como dirty
                try:
                    self.parent()._marcar_dirty()
                except Exception:
                    pass
                event.accept()
                return True
        # Clic en modo borrar-flecha
        if (obj is self.scene
                and self._borrando_flecha
                and event.type() == QEvent.Type.GraphicsSceneMousePress):
            pos = event.scenePos()
            for fl in list(self._items_flechas):
                if fl.path().intersects(QRectF(
                        pos.x() - 6, pos.y() - 6, 12, 12)):
                    self._borrar_flecha(fl)
                    event.accept()
                    return True
        return super().eventFilter(obj, event)

    def _borrar_flecha(self, fl) -> None:
        """Elimina una flecha concreta del modelo según su metadata."""
        meta = getattr(fl, "_meta", None)
        if meta is None:
            return
        tipo = meta[0]
        if tipo == "tarjeta_legacy":
            _, oi, j = meta
            if 0 <= oi < len(self.documento.beats):
                try:
                    self.documento.beats[oi].conexiones.remove(j)
                except ValueError:
                    pass
        elif tipo in ("tarjeta", "foto"):
            _, oi, cdict = meta
            lista = (self.documento.beats[oi].conexiones_lados
                     if tipo == "tarjeta"
                     else self.documento.fotos_beatboard[oi].conexiones_lados)
            try:
                lista.remove(cdict)
            except ValueError:
                pass
        self._actualizar_flechas()

    # ─── multi-selección: menú contextual (clic derecho) ──────────────

    def _items_sel(self) -> tuple[list, list]:
        """Devuelve (indices_tarjetas, indices_fotos) seleccionados."""
        sel = self.scene.selectedItems()
        it = sorted({i._indice for i in sel if isinstance(i, _TarjetaBeat)})
        fo = sorted({i._indice for i in sel if isinstance(i, _FotoBeat)})
        return it, fo

    def _menu_contextual(self, pos_view) -> None:
        """Clic derecho: si hay selección múltiple, ofrece ordenar,
        conectar y borrar. Si no, ofrece crear tarjeta o foto."""
        idx_t, idx_f = self._items_sel()
        n_sel = len(idx_t) + len(idx_f)

        menu = QMenu(self)
        menu.setStyleSheet(f"""
            QMenu {{ background: #131d2b; color: #e8edf4;
                     border: 1px solid #ff8c1a; padding: 4px; }}
            QMenu::item {{ padding: 7px 22px; }}
            QMenu::item:selected {{ background: #ff8c1a; color: #241203; }}
            QMenu::separator {{ height: 1px; background: #3a4665;
                                margin: 4px 8px; }}
        """)

        if n_sel >= 2:
            cab = menu.addAction(f"📦  {n_sel} elementos seleccionados")
            cab.setEnabled(False)
            menu.addSeparator()
            a_h = menu.addAction("➡  Ordenar en fila horizontal")
            a_h.triggered.connect(lambda: self._ordenar_seleccion("h"))
            a_v = menu.addAction("⬇  Ordenar en columna vertical")
            a_v.triggered.connect(lambda: self._ordenar_seleccion("v"))
            a_g = menu.addAction("▦  Ordenar en grilla")
            a_g.triggered.connect(lambda: self._ordenar_seleccion("g"))
            menu.addSeparator()
            a_ch = menu.addAction("🔗  Conectar todas en cadena (→)")
            a_ch.triggered.connect(lambda: self._conectar_seleccion("cadena"))
            a_es = menu.addAction("✸  Conectar en estrella (1ª → resto)")
            a_es.triggered.connect(lambda: self._conectar_seleccion("estrella"))
            menu.addSeparator()
            a_color = menu.addAction("🎨  Cambiar color…")
            a_color.triggered.connect(self._cambiar_color)
            a_del = menu.addAction("🗑  Eliminar seleccionadas")
            a_del.triggered.connect(self._eliminar_seleccion)
        else:
            escena_pos = self.view.mapToScene(pos_view)
            a_nt = menu.addAction("➕  Nueva tarjeta aquí")
            a_nt.triggered.connect(
                lambda: self._nueva_tarjeta_en(escena_pos))
            a_nf = menu.addAction("📷  Agregar foto…")
            a_nf.triggered.connect(self._agregar_foto)
            if n_sel == 1:
                menu.addSeparator()
                a_color = menu.addAction("🎨  Cambiar color…")
                a_color.triggered.connect(self._cambiar_color)
                a_del = menu.addAction("🗑  Eliminar")
                a_del.triggered.connect(self._eliminar_seleccion)

        menu.exec(self.view.viewport().mapToGlobal(pos_view))

    def _centros_y_tam_sel(self):
        """Devuelve lista de (tipo, idx, x, y, w, h) de la selección,
        ordenada por posición de lectura (y luego x)."""
        items = []
        for i in self._items_sel()[0]:
            b = self.documento.beats[i]
            items.append(("tarjeta", i, b.x, b.y, b.w, b.h))
        for i in self._items_sel()[1]:
            f = self.documento.fotos_beatboard[i]
            items.append(("foto", i, f.x, f.y, f.w, f.h))
        items.sort(key=lambda t: (round(t[3] / 40), t[2]))
        return items

    def _set_pos(self, tipo: str, idx: int, x: float, y: float) -> None:
        if tipo == "tarjeta":
            self.documento.beats[idx].x = x
            self.documento.beats[idx].y = y
        else:
            self.documento.fotos_beatboard[idx].x = x
            self.documento.fotos_beatboard[idx].y = y

    def _ordenar_seleccion(self, modo: str) -> None:
        """Reposiciona los elementos seleccionados en fila, columna o grilla."""
        items = self._centros_y_tam_sel()
        if len(items) < 2:
            return
        GAP = 40
        x0 = min(it[2] for it in items)
        y0 = min(it[3] for it in items)
        if modo == "h":
            x = x0
            for (tipo, idx, _, _, w, h) in items:
                self._set_pos(tipo, idx, x, y0)
                x += w + GAP
        elif modo == "v":
            y = y0
            for (tipo, idx, _, _, w, h) in items:
                self._set_pos(tipo, idx, x0, y)
                y += h + GAP
        else:  # grilla
            import math
            cols = max(1, int(math.ceil(math.sqrt(len(items)))))
            ancho_col = max(it[4] for it in items) + GAP
            alto_fila = max(it[5] for it in items) + GAP
            for k, (tipo, idx, _, _, w, h) in enumerate(items):
                r, c = divmod(k, cols)
                self._set_pos(tipo, idx, x0 + c * ancho_col,
                              y0 + r * alto_fila)
        self._reconstruir()

    def _conectar_seleccion(self, modo: str) -> None:
        """Crea flechas entre los elementos seleccionados.
        · cadena: 1→2→3→…
        · estrella: 1→2, 1→3, 1→4, …"""
        items = self._centros_y_tam_sel()
        if len(items) < 2:
            return

        def conx_de(tipo, idx):
            if tipo == "tarjeta":
                return self.documento.beats[idx].conexiones_lados
            return self.documento.fotos_beatboard[idx].conexiones_lados

        if modo == "cadena":
            for a, b in zip(items, items[1:]):
                self._agregar_conexion(
                    conx_de(a[0], a[1]), b[1], b[0], "right", "left")
        else:  # estrella
            origen = items[0]
            for b in items[1:]:
                self._agregar_conexion(
                    conx_de(origen[0], origen[1]),
                    b[1], b[0], "right", "left")
        self._reconstruir()

    def _nueva_tarjeta_en(self, pos_scene: QPointF) -> None:
        idx = len(self.documento.beats)
        beat = Beat(
            titulo=f"Tarjeta {idx + 1}",
            descripcion="(doble-click para editar)",
            color=COLORES_BEATS[idx % len(COLORES_BEATS)][1],
            x=pos_scene.x() - 90,
            y=pos_scene.y() - 60,
        )
        self.documento.beats.append(beat)
        self._reconstruir()

    def _enviar_al_guion(self) -> None:
        if not self.documento.beats:
            QMessageBox.information(
                self, "Pizarra de beats vacía",
                "Agrega al menos una tarjeta antes de enviar al guion.")
            return
        en_orden = sorted(self.documento.beats,
                          key=lambda b: (round(b.y / 50), b.x))
        r = QMessageBox.question(
            self, "Enviar al guion",
            f"¿Insertar {len(en_orden)} beat(s) al final del guion como "
            f"bloques de ACCIÓN con prefijo [BEAT n]?\n\n"
            f"Se ordenan automáticamente de arriba-abajo, izquierda-derecha.",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
        )
        if r == QMessageBox.StandardButton.Yes:
            self.enviar_solicitado.emit(en_orden)
            QMessageBox.information(
                self, "✓ Enviado",
                f"{len(en_orden)} beat(s) insertados al final del guion.")

    def centrar_en_foto(self, indice: int) -> None:
        """Centra la vista sobre la foto del índice dado y la
        selecciona brevemente. Usado por el guion para «saltar» a la
        foto vinculada cuando se hace doble clic en un marcador."""
        if not (0 <= indice < len(self._items_fotos)):
            return
        item = self._items_fotos[indice]
        # Centrar la vista sobre la foto
        self.view.centerOn(item.sceneBoundingRect().center())
        # Seleccionarla para que se resalte
        for it in self._items_fotos:
            it.setSelected(False)
        item.setSelected(True)


# ═══════════════════════════════════════════════════════════════════════
# §8.9  COLABORACIÓN EN RED LOCAL (puerto del módulo tkinter original)
# ═══════════════════════════════════════════════════════════════════════
#
# Tres diálogos:
#   1) VentanaColaboracion       — panel principal (host + unirse + meta)
#   2) DialogoPermisosInvitados  — checkboxes con permisos por invitado
#   3) DialogoComentarios        — comentarios del equipo, firmados
#
# La conexión en red en vivo aún NO está implementada (igual que en
# el tkinter original): los botones "Iniciar como host" y "Unirse a la
# sesión" muestran el mensaje informativo que explica cómo colaborar
# mientras tanto vía archivo .accion compartido + Comentarios firmados.


def _ip_local() -> str:
    """Devuelve la IP del adaptador de red preferido (no localhost)."""
    import socket
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(("8.8.8.8", 80))
        ip = s.getsockname()[0]
        s.close()
        return ip
    except Exception:
        return "127.0.0.1"


class DialogoComentarios(QDialog):
    """Notas y comentarios del equipo. Se guardan con el archivo en
    `documento.comentarios`. Permite agregar entradas firmadas con
    nombre + fecha automática."""

    def __init__(self, documento: "Documento", parent=None):
        super().__init__(parent)
        self.documento = documento
        self.setWindowTitle("Comentarios del equipo")
        self.resize(px(560), px(480))

        v = QVBoxLayout(self)
        v.setContentsMargins(px(14), px(12), px(14), px(12))
        v.setSpacing(px(8))

        tit = QLabel("💬  Comentarios del equipo")
        tit.setStyleSheet("color: #ff8c1a; font-size: 14pt; font-weight: bold;")
        v.addWidget(tit)

        sub = QLabel(
            "Notas y comentarios entre quienes trabajan este guion.\n"
            "Se guardan dentro del archivo .accion."
        )
        sub.setWordWrap(True)
        sub.setStyleSheet("color: #b0bcd2; font-size: 9pt;")
        v.addWidget(sub)

        self.txt = QTextEdit()
        self.txt.setPlainText(self.documento.comentarios or "")
        self.txt.setStyleSheet(f"""
            QTextEdit {{
                background: #131d2b;
                color: #e8edf4;
                border: 1px solid #3a4665;
                border-radius: 4px;
                padding: 8px;
                font-size: 10pt;
            }}
        """)
        v.addWidget(self.txt, 1)

        # Barra de acciones
        barra = QHBoxLayout()
        b_agregar = QPushButton("＋  Agregar comentario firmado")
        b_agregar.clicked.connect(self._agregar_firmado)
        barra.addWidget(b_agregar)
        barra.addStretch()
        b_guardar = QPushButton("Guardar y cerrar")
        b_guardar.setDefault(True)
        b_guardar.setStyleSheet(
            "QPushButton { background: #ff8c1a; color: #241203; "
            f"font-weight: bold; padding: 7px 14px; "
            f"border: none; border-radius: 2px; }}"
        )
        b_guardar.clicked.connect(self._guardar_y_cerrar)
        barra.addWidget(b_guardar)
        v.addLayout(barra)

    def _agregar_firmado(self) -> None:
        """Pregunta nombre + comentario y los inserta firmados con fecha."""
        nombre, ok1 = QInputDialog.getText(
            self, "Comentario", "Tu nombre:",
            text=self.documento.autor_id or "")
        if not ok1 or not nombre.strip():
            return
        coment, ok2 = QInputDialog.getMultiLineText(
            self, "Comentario", "Tu comentario:")
        if not ok2 or not coment.strip():
            return
        import datetime as _dt
        fecha = _dt.datetime.now().strftime("%d/%m %H:%M")
        linea = f"\n[{nombre.strip()} · {fecha}] {coment.strip()}\n"
        cursor = self.txt.textCursor()
        cursor.movePosition(cursor.MoveOperation.End)
        cursor.insertText(linea)
        # Recordar autor
        self.documento.autor_id = nombre.strip()

    def _guardar_y_cerrar(self) -> None:
        self.documento.comentarios = self.txt.toPlainText()
        self.accept()

    def closeEvent(self, ev) -> None:
        # Guardar también si se cierra con la X (como el original)
        self.documento.comentarios = self.txt.toPlainText()
        super().closeEvent(ev)


class DialogoPermisosInvitados(QDialog):
    """6 checkboxes que definen qué puede hacer cada invitado al unirse
    a tu sesión. Los permisos quedan persistidos en
    `documento.colab_permisos`."""

    # Lista en orden de presentación (clave, etiqueta visible)
    PERMISOS_DEF = [
        ("escribir",  "Escribir en el guion"),
        ("fichas",    "Editar fichas (personajes, locaciones)"),
        ("etiquetar", "Etiquetar (tags) bloques del guion"),
        ("formato",   "Cambiar el formato de los elementos"),
        ("exportar",  "Exportar e imprimir"),
        ("produccion","Modificar la producción (Carta Gantt, jornadas)"),
    ]

    def __init__(self, documento: "Documento", parent=None):
        super().__init__(parent)
        self.documento = documento
        self.setWindowTitle("Permisos de invitados")
        self.resize(px(460), px(420))

        v = QVBoxLayout(self)
        v.setContentsMargins(px(16), px(14), px(16), px(14))
        v.setSpacing(px(8))

        tit = QLabel("🔐  Permisos de invitados")
        tit.setStyleSheet("color: #ff8c1a; font-size: 13pt; font-weight: bold;")
        v.addWidget(tit)

        sub = QLabel(
            "Define qué pueden hacer los compañeros que se conectan "
            "a tu sesión."
        )
        sub.setWordWrap(True)
        sub.setStyleSheet("color: #b0bcd2; font-size: 9pt;")
        v.addWidget(sub)

        v.addSpacing(px(8))

        # Checkboxes
        self._checks: dict[str, QCheckBox] = {}
        for clave, etiqueta in self.PERMISOS_DEF:
            cb = QCheckBox(etiqueta)
            cb.setChecked(self.documento.colab_permisos.get(clave, True))
            cb.setStyleSheet(
                f"QCheckBox {{ color: #e8edf4; font-size: 10pt; "
                f"spacing: 8px; padding: 3px; }}"
            )
            self._checks[clave] = cb
            v.addWidget(cb)

        v.addStretch()

        # Botones
        barra = QHBoxLayout()
        barra.addStretch()
        b_cancel = QPushButton("Cancelar")
        b_cancel.clicked.connect(self.reject)
        b_save = QPushButton("Guardar permisos")
        b_save.setDefault(True)
        b_save.setStyleSheet(
            "QPushButton { background: #ff8c1a; color: #241203; "
            f"font-weight: bold; padding: 7px 14px; "
            f"border: none; border-radius: 2px; }}"
        )
        b_save.clicked.connect(self._guardar)
        barra.addWidget(b_cancel)
        barra.addWidget(b_save)
        v.addLayout(barra)

    def _guardar(self) -> None:
        for clave, cb in self._checks.items():
            self.documento.colab_permisos[clave] = cb.isChecked()
        self.accept()


# ═══════════════════════════════════════════════════════════════════════
# 👥 COLABORACIÓN EN RED (1.9.0): el guion compartido
# ═══════════════════════════════════════════════════════════════════════
# Cada computador tiene una copia del guion en un documento pycrdt (un CRDT,
# el mismo tipo de estructura que usan los editores en línea): una lista de
# bloques, cada uno con un id fijo, su tipo, su texto (las negritas y los
# colores van como atributos del texto, así se mueven con él), sus tags, su
# número fijo y la marca de diálogo doble.
# · Lo que cambia en el editor se compara con la última versión sincronizada
#   («la sombra») y se traduce en operaciones mínimas del CRDT.
# · Lo que llega de otros se aplica al CRDT; sus eventos dicen qué bloques
#   cambiaron, y solo esos se vuelven a leer y se llevan al editor.
# Así dos o más personas escriben a la vez, incluso en el mismo bloque, y
# todas las copias terminan iguales sin importar el orden en que llegan los
# cambios. (Antes: posiciones de texto contadas en caracteres cuando pycrdt
# las cuenta en bytes —una tilde corría todo—, cada copia armaba su propio
# historial del CRDT —duplicados— y la estructura se alineaba por posición.)

_ORIGEN_LOCAL = "accion-local"
_ORIGEN_REMOTO = "accion-remoto"
_UNIDAD_CRDT_CACHE: list = []


def _unidad_texto_crdt() -> str:
    """En qué cuenta pycrdt las posiciones del texto: bytes UTF-8 (lo de
    hoy), UTF-16 o caracteres. Se mide una vez, por si otra versión cambia."""
    if _UNIDAD_CRDT_CACHE:
        return _UNIDAD_CRDT_CACHE[0]
    unidad = "bytes"
    if _CRDT_DISPONIBLE:
        try:
            d = _CRDT_Doc()
            t = d.get("t", type=_CRDT_Text)
            t.insert(0, "é😀")
            unidad = {6: "bytes", 3: "utf16", 2: "cp"}.get(len(t), "bytes")
        except Exception:
            pass
    _UNIDAD_CRDT_CACHE.append(unidad)
    return unidad


def _largo_crdt(s: str) -> int:
    """Largo de s en las unidades de pycrdt."""
    if s.isascii():
        return len(s)
    u = _unidad_texto_crdt()
    if u == "bytes":
        return len(s.encode("utf-8"))
    if u == "utf16":
        return len(s.encode("utf-16-le")) // 2
    return len(s)


def _pos_crdt(s: str, i: int) -> int:
    """La posición i de s (en caracteres de Python) contada como pycrdt."""
    if i <= 0:
        return 0
    return _largo_crdt(s[:i])


def _solo_bmp(s: str) -> bool:
    """Sin emojis ni otros caracteres de dos unidades UTF-16 (en ese caso
    las posiciones de Qt y las de Python coinciden)."""
    return s.isascii() or not s or max(s) < "\U00010000"


def _u16_a_cp(s: str, u: int) -> int:
    """Posición en unidades UTF-16 (las de Qt) → posición en Python."""
    if _solo_bmp(s):
        return u
    n = 0
    for i, c in enumerate(s):
        if n >= u:
            return i
        n += 2 if ord(c) >= 0x10000 else 1
    return len(s)


def _cp_a_u16(s: str, i: int) -> int:
    if _solo_bmp(s):
        return i
    return len(s[:i].encode("utf-16-le")) // 2


def _json_canon(x) -> str:
    return json.dumps(x, sort_keys=True, ensure_ascii=False, default=str)


def _props_formato(f: dict) -> dict:
    """Lo que dice un formato guardado, sin su rango ni lo apagado."""
    return {str(k): v for k, v in f.items()
            if k not in ("desde", "hasta") and v not in (None, False, "")}


def _attrs_por_caracter(texto: str, formatos) -> Optional[list]:
    """Un dict de formato por carácter (o None si el bloque no tiene)."""
    n = len(texto)
    if not formatos or not n:
        return None
    bmp = _solo_bmp(texto)
    attrs: list = [None] * n
    hay = False
    for f in formatos:
        if not isinstance(f, dict):
            continue
        props = _props_formato(f)
        if not props:
            continue
        try:
            d, h = int(f.get("desde", 0)), int(f.get("hasta", 0))
        except (TypeError, ValueError):
            continue
        if not bmp:
            d, h = _u16_a_cp(texto, d), _u16_a_cp(texto, h)
        for i in range(max(0, d), min(n, h)):
            a = attrs[i]
            attrs[i] = {**a, **props} if a else dict(props)
            hay = True
    return attrs if hay else None


def _tramos(attrs: list) -> list:
    """[(desde, hasta, props)] de los tramos con el mismo formato."""
    out: list = []
    i, n = 0, len(attrs)
    while i < n:
        a = attrs[i]
        j = i + 1
        while j < n and attrs[j] == a:
            j += 1
        if a:
            out.append((i, j, a))
        i = j
    return out


def _canon_formatos(texto: str, formatos) -> tuple:
    """Los formatos de un bloque en una forma única: tramos sin cruces, en
    orden, con su formato completo (unidades de Qt, como los guarda el
    editor). Dos listas que se ven igual en la hoja dan lo mismo."""
    attrs = _attrs_por_caracter(texto, formatos)
    if not attrs:
        return ()
    bmp = _solo_bmp(texto)
    out = []
    for d, h, p in _tramos(attrs):
        if not bmp:
            d, h = _cp_a_u16(texto, d), _cp_a_u16(texto, h)
        out.append((d, h, _json_canon(p)))
    return tuple(out)


def _attrs_de_canon(texto: str, fm: tuple) -> Optional[list]:
    if not fm:
        return None
    return _attrs_por_caracter(
        texto, [dict(desde=d, hasta=h, **json.loads(p)) for d, h, p in fm])


def _tag_json(t: dict) -> str:
    # (las claves con «_» son marcas locales, como «_pendiente»)
    return _json_canon({k: v for k, v in t.items() if not str(k).startswith("_")})


def _clave_bloque(b) -> tuple:
    """Todo lo que se sincroniza de un bloque, comparable y con hash."""
    texto = b.texto or ""
    tags = tuple(_tag_json(t) for t in (b.tags or []) if isinstance(t, dict))
    fm = _canon_formatos(texto, b.formatos) if b.formatos else ()
    return (int(b.elem), texto, tags, fm,
            str(getattr(b, "numero", "") or ""),
            bool(getattr(b, "doble", False)))


def _bloque_de_clave(k: tuple) -> "Bloque":
    try:
        elem = Elem(int(k[0]))
    except (ValueError, TypeError):
        elem = Elem.ACCION
    tags = []
    for t in k[2]:
        try:
            v = json.loads(t)
        except ValueError:
            continue
        if isinstance(v, dict):
            tags.append(v)
    formatos = [dict(desde=d, hasta=h, **json.loads(p)) for d, h, p in k[3]]
    return Bloque(elem, k[1], tags, formatos, k[4], k[5])


def _parecido(a: tuple, b: tuple) -> float:
    """Cuánto se parecen dos bloques (para emparejar los que cambiaron)."""
    mismo_tipo = 0.1 if a[0] == b[0] else 0.0
    ta, tb = a[1], b[1]
    if ta == tb:
        return 1.0 + mismo_tipo
    if not ta or not tb:
        return 0.3 + mismo_tipo
    from difflib import SequenceMatcher
    sm = SequenceMatcher(None, ta, tb, autojunk=False)
    r = sm.quick_ratio()
    if r >= 0.3 and len(ta) * len(tb) <= 40000:
        r = sm.ratio()
    return r + mismo_tipo


def _emparejar(viejos: list, nuevos: list) -> list:
    """Alinea dos tramos de bloques distintos: [(i_viejo|None, j_nuevo|None)]
    en orden. Un par es un bloque que cambió; (i, None) uno que se borró;
    (None, j) uno nuevo."""
    n, m = len(viejos), len(nuevos)
    if n == 0:
        return [(None, j) for j in range(m)]
    if m == 0:
        return [(i, None) for i in range(n)]
    if n == m:
        return [(i, i) for i in range(n)]
    if n * m > 400:
        k = min(n, m)
        return ([(i, i) for i in range(k)] + [(i, None) for i in range(k, n)]
                + [(None, j) for j in range(k, m)])
    umbral = 0.35
    sim = [[_parecido(viejos[i], nuevos[j]) for j in range(m)] for i in range(n)]
    S = [[0.0] * (m + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            mejor = max(S[i - 1][j], S[i][j - 1])
            s = sim[i - 1][j - 1]
            if s >= umbral:
                mejor = max(mejor, S[i - 1][j - 1] + s)
            S[i][j] = mejor
    pares: list = []
    i, j = n, m
    while i > 0 and j > 0:
        s = sim[i - 1][j - 1]
        if s >= umbral and abs(S[i][j] - (S[i - 1][j - 1] + s)) < 1e-9:
            pares.append((i - 1, j - 1))
            i, j = i - 1, j - 1
        elif abs(S[i][j] - S[i - 1][j]) < 1e-9:
            pares.append((i - 1, None))
            i -= 1
        else:
            pares.append((None, j - 1))
            j -= 1
    while i > 0:
        pares.append((i - 1, None))
        i -= 1
    while j > 0:
        pares.append((None, j - 1))
        j -= 1
    pares.reverse()
    return pares


def _opcodes_texto(a: str, b: str) -> list:
    """Las diferencias entre dos textos, como opcodes de difflib (sin los
    'equal'): lo común al principio y al final queda fuera; el medio se
    compara en detalle si no es muy largo."""
    n_min = min(len(a), len(b))
    i = 0
    while i < n_min and a[i] == b[i]:
        i += 1
    j = 0
    while j < n_min - i and a[len(a) - 1 - j] == b[len(b) - 1 - j]:
        j += 1
    ma, mb = a[i:len(a) - j], b[i:len(b) - j]
    if not ma and not mb:
        return []
    if ma and mb and len(ma) * len(mb) <= 250_000:
        from difflib import SequenceMatcher
        ops = []
        for tag, i1, i2, j1, j2 in SequenceMatcher(
                None, ma, mb, autojunk=False).get_opcodes():
            ops.append((tag, i + i1, i + i2, i + j1, i + j2))
        return ops
    return [("replace", i, len(a) - j, i, len(b) - j)]


def _rebasar_texto(actual: str, origen: str, destino: str) -> str:
    """Lleva a `actual` el cambio origen→destino, sin tocar lo que otros
    cambiaron después (si un tramo ya no está igual, ese tramo se salta)."""
    from difflib import SequenceMatcher
    iguales = [(a, b, n) for a, b, n in SequenceMatcher(
        None, origen, actual, autojunk=False).get_matching_blocks() if n]

    def mapear(i):
        for a, b, n in iguales:
            if a <= i <= a + n:
                return b + (i - a)
        return None
    res = actual
    for tag, i1, i2, j1, j2 in reversed(_opcodes_texto(origen, destino)):
        if tag == "equal":
            continue
        p1, p2 = mapear(i1), mapear(i2)
        if p1 is None or p2 is None or p2 < p1 or res[p1:p2] != origen[i1:i2]:
            continue
        res = res[:p1] + destino[j1:j2] + res[p2:]
    return res


def _revertir_bloque(actual: tuple, origen: tuple, destino: tuple) -> tuple:
    """Deshace (o rehace) en un bloque lo que pasó de `origen` a `destino`,
    respetando lo que cambiaron los demás después."""
    if actual == origen:
        return destino
    k = list(actual)
    for f in (0, 4, 5):              # tipo, número, diálogo doble
        if actual[f] == origen[f]:
            k[f] = destino[f]
    if actual[2] == origen[2]:
        k[2] = destino[2]
    else:
        tags = [t for t in actual[2] if t not in origen[2] or t in destino[2]]
        for t in destino[2]:
            if t not in origen[2] and t not in tags:
                tags.append(t)
        k[2] = tuple(tags)
    if actual[1] == origen[1]:
        k[1] = destino[1]
        if actual[3] == origen[3]:
            k[3] = destino[3]
    else:
        k[1] = _rebasar_texto(actual[1], origen[1], destino[1])
    # (en su forma única, recortado al texto que quedó)
    k[3] = _canon_formatos(k[1], [dict(desde=d, hasta=h, **json.loads(p))
                                  for d, h, p in k[3]])
    return tuple(k)


def _opcodes_bloques(viejos: list, nuevos: list) -> list:
    """Opcodes de difflib entre dos listas de bloques, rápido en un guion
    largo: lo igual al principio y al final queda fuera (un cambio típico
    toca uno o dos bloques)."""
    n_min = min(len(viejos), len(nuevos))
    i = 0
    while i < n_min and viejos[i] == nuevos[i]:
        i += 1
    j = 0
    while j < n_min - i and viejos[len(viejos) - 1 - j] == nuevos[len(nuevos) - 1 - j]:
        j += 1
    ops = []
    if i:
        ops.append(("equal", 0, i, 0, i))
    mv, mn = viejos[i:len(viejos) - j], nuevos[i:len(nuevos) - j]
    if mv or mn:
        if not mv or not mn:
            ops.append(("delete" if mv else "insert", i, i + len(mv), i, i + len(mn)))
        else:
            from difflib import SequenceMatcher
            for tag, a1, a2, b1, b2 in SequenceMatcher(None, mv, mn, autojunk=False).get_opcodes():
                ops.append((tag, i + a1, i + a2, i + b1, i + b2))
    if j:
        ops.append(("equal", len(viejos) - j, len(viejos), len(nuevos) - j, len(nuevos)))
    return ops


def _nuevo_id_bloque() -> str:
    import uuid
    return uuid.uuid4().hex[:12]


class _GuionCompartido:
    """El guion de una sesión de colaboración, como CRDT (ver arriba).

    · `desde_local(bloques)` → bytes: lleva lo que cambió en el editor al
      CRDT; devuelve la actualización que hay que mandar (b"" si nada).
    · `aplicar_remoto(update)` → bool: aplica lo que mandó otro; True si
      cambió el guion (y `bloques()` trae la versión nueva).
    · `deshacer()` / `rehacer()`: Ctrl+Z / Ctrl+Y de lo propio, sin tocar lo
      que escribieron los demás.
    · `estado()`, `vector()`, `diferencia(vector)`: para entrar o volver a
      una sesión."""

    CAPTURA_MS = 700   # cambios seguidos a menos de esto: un solo Ctrl+Z

    def __init__(self, estado: bytes = b"", bloques: Optional[list] = None):
        if not _CRDT_DISPONIBLE:
            raise RuntimeError("falta pycrdt")
        self.doc = _CRDT_Doc()
        self.arr = self.doc.get("bloques", type=_CRDT_Array)
        self.sombra: list = []      # la clave de cada bloque, como en el CRDT
        self.ids: list = []         # el id de cada bloque
        self._eventos: Optional[list] = None
        self._sub = self.arr.observe_deep(self._al_cambiar)
        self.lecturas_completas = 0
        # Ctrl+Z propio, por id de bloque (el UndoManager de pycrdt se cae con
        # ediciones cruzadas: se probó). Cada paso: {id: (antes, después,
        # id del vecino de arriba, posición)}; antes/después = clave o None.
        self._atras: list = []
        self._adelante: list = []
        self._alias: dict = {}      # id viejo → id con que volvió el bloque
        self._t_ultimo_paso = 0.0
        self._paso_cortado = True
        if estado:
            self.aplicar_remoto(estado)
            self._leer_todo()
        elif bloques is not None:
            self.escribir([_clave_bloque(b) for b in bloques], registrar=False)

    # ── lectura ──
    def cortar_paso(self) -> None:
        """Lo próximo que se escriba es otro paso de Ctrl+Z (Enter, pegar…)."""
        self._paso_cortado = True

    def _al_cambiar(self, eventos) -> None:
        if self._eventos is None:
            return
        for e in eventos:
            try:
                path = list(e.path)
                if not path:
                    ops = []
                    for d in e.delta:
                        if "retain" in d:
                            ops.append(("r", int(d["retain"])))
                        elif "delete" in d:
                            ops.append(("d", int(d["delete"])))
                        elif "insert" in d:
                            ops.append(("i", len(d["insert"])))
                    self._eventos.append(("raiz", ops))
                else:
                    self._eventos.append(("bloque", int(path[0])))
            except Exception:
                self._eventos.append(("?", 0))

    def _leer_bloque(self, m) -> tuple:
        tx = m["texto"]
        texto = str(tx)
        fm: tuple = ()
        try:
            corridas = tx.diff()
        except Exception:
            corridas = []
        if any(a for _, a in corridas):
            attrs: list = []
            for trozo, a in corridas:
                if not isinstance(trozo, str):
                    continue
                p = {str(k): v for k, v in (a or {}).items()
                     if v not in (None, False, "")}
                attrs.extend([p or None] * len(trozo))
            if len(attrs) == len(texto):
                bmp = _solo_bmp(texto)
                out = []
                for d, h, p in _tramos(attrs):
                    if not bmp:
                        d, h = _cp_a_u16(texto, d), _cp_a_u16(texto, h)
                    out.append((d, h, _json_canon(p)))
                fm = tuple(out)
        tags = tuple(str(t) for t in m["tags"]) if "tags" in m else ()
        try:
            elem = int(m.get("elem", 2) or 2)
        except (TypeError, ValueError):
            elem = 2
        clave = (elem, texto, tags, fm, str(m.get("numero", "") or ""),
                 bool(m.get("doble", False)))
        return str(m.get("id", "") or ""), clave

    def _leer_todo(self) -> None:
        self.lecturas_completas += 1
        sombra, ids = [], []
        for m in self.arr:
            i, k = self._leer_bloque(m)
            ids.append(i)
            sombra.append(k)
        self.sombra, self.ids = sombra, ids

    def _procesar_eventos(self, ev: list) -> bool:
        if not ev:
            return False
        if any(e[0] == "?" for e in ev):
            self._leer_todo()
            return True
        sucios: set = set()
        for e in ev:
            if e[0] != "raiz":
                sucios.add(e[1])
                continue
            nueva, nuevos_ids, pos = [], [], 0
            for op, n in e[1]:
                if op == "r":
                    nueva += self.sombra[pos:pos + n]
                    nuevos_ids += self.ids[pos:pos + n]
                    pos += n
                elif op == "d":
                    pos += n
                else:
                    for _ in range(n):
                        sucios.add(len(nueva))
                        nueva.append(None)
                        nuevos_ids.append("")
            nueva += self.sombra[pos:]
            nuevos_ids += self.ids[pos:]
            self.sombra, self.ids = nueva, nuevos_ids
        n = len(self.arr)
        if len(self.sombra) != n:
            self._leer_todo()
            return True
        for i in sorted(sucios):
            if 0 <= i < n:
                self.ids[i], self.sombra[i] = self._leer_bloque(self.arr[i])
        if any(k is None for k in self.sombra):
            self._leer_todo()
        return True

    def verificar(self) -> bool:
        """Red de seguridad (en los ratos sin cambios): ¿la sombra es igual
        al CRDT? Si no, se relee entero. True = estaba bien."""
        sombra, ids = list(self.sombra), list(self.ids)
        self._leer_todo()
        return sombra == self.sombra and ids == self.ids

    def bloques(self) -> list:
        return [_bloque_de_clave(k) for k in self.sombra]

    # ── lo que llega de otros ──
    def _capturando(self, fn) -> tuple:
        sv = self.doc.get_state()
        self._eventos = []
        try:
            resultado = fn()
        finally:
            ev, self._eventos = self._eventos, None
        cambio = self._procesar_eventos(ev)
        return resultado, cambio, sv

    def aplicar_remoto(self, update: bytes) -> bool:
        if not update:
            return False

        def aplicar():
            with self.doc.transaction(origin=_ORIGEN_REMOTO):
                self.doc.apply_update(update)
        return self._capturando(aplicar)[1]

    # ── Ctrl+Z / Ctrl+Y (solo lo propio) ──
    PASOS_MAX = 300

    def puede_deshacer(self) -> bool:
        return bool(self._atras)

    def puede_rehacer(self) -> bool:
        return bool(self._adelante)

    def deshacer(self) -> tuple:
        """(update para mandar, cambió el guion, bloque donde fue)."""
        if not self._atras:
            return b"", False, -1
        paso = self._atras.pop()
        self._adelante.append(paso)
        self._paso_cortado = True
        return self._aplicar_paso(paso, hacia_antes=True)

    def rehacer(self) -> tuple:
        if not self._adelante:
            return b"", False, -1
        paso = self._adelante.pop()
        self._atras.append(paso)
        self._paso_cortado = True
        return self._aplicar_paso(paso, hacia_antes=False)

    def _resolver(self, bid: str) -> str:
        vistos = 0
        while bid in self._alias and vistos < 50:
            bid = self._alias[bid]
            vistos += 1
        return bid

    def _registrar_paso(self, ids_v: list, viejos: list, ids_n: list,
                        nuevos: list) -> None:
        antes = dict(zip(ids_v, viejos))
        despues = dict(zip(ids_n, nuevos))
        cambios: dict = {}
        for i, bid in enumerate(ids_v):
            if bid not in despues:
                cambios[bid] = (antes[bid], None, ids_v[i - 1] if i else "", i)
            elif despues[bid] != antes[bid]:
                cambios[bid] = (antes[bid], despues[bid], "", i)
        for j, bid in enumerate(ids_n):
            if bid not in antes:
                cambios[bid] = (None, despues[bid], ids_n[j - 1] if j else "", j)
        if not cambios:
            return
        self._adelante.clear()
        ahora = time.monotonic()
        juntar = (not self._paso_cortado and self._atras
                  and ahora - self._t_ultimo_paso < self.CAPTURA_MS / 1000)
        self._t_ultimo_paso = ahora
        self._paso_cortado = False
        if not juntar:
            self._atras.append(cambios)
            if len(self._atras) > self.PASOS_MAX:
                del self._atras[0]
            return
        paso = self._atras[-1]
        for bid, (a, d, vec, idx) in cambios.items():
            if bid in paso:
                a0, _d0, vec0, idx0 = paso[bid]
                if a0 is None and d is None:
                    del paso[bid]          # nació y murió en el mismo paso
                else:
                    paso[bid] = (a0, d, vec if d is None else vec0,
                                 idx if d is None else idx0)
            else:
                paso[bid] = (a, d, vec, idx)

    def _aplicar_paso(self, paso: dict, hacia_antes: bool) -> tuple:
        claves, ids = list(self.sombra), list(self.ids)
        pos = {bid: i for i, bid in enumerate(ids)}
        quitar: set = set()
        volver: list = []
        tocados: list = []
        for bid, (a, d, vec, idx) in paso.items():
            origen, destino = (d, a) if hacia_antes else (a, d)
            b = self._resolver(bid)
            if origen is not None and destino is not None:
                if b in pos:
                    claves[pos[b]] = _revertir_bloque(claves[pos[b]], origen,
                                                       destino)
                    tocados.append(b)
            elif origen is not None:
                if b in pos:
                    quitar.add(b)
            elif destino is not None and b not in pos:
                volver.append((idx, bid, vec, destino))
        if quitar:
            dupla = [(bid, k) for bid, k in zip(ids, claves) if bid not in quitar]
            ids, claves = [x[0] for x in dupla], [x[1] for x in dupla]
        marcas: list = []           # (id original, clave) en su lugar nuevo
        for idx, bid, vec, destino in sorted(volver):
            v = self._resolver(vec) if vec else ""
            if v and v in ids:
                donde = ids.index(v) + 1
            elif not vec:
                donde = 0
            else:
                donde = min(idx, len(ids))
            ids.insert(donde, "\0" + bid)
            claves.insert(donde, destino)
        if not claves:
            return b"", False, -1
        update = self.escribir(claves, registrar=False)
        foco = -1
        for i, bid in enumerate(ids):
            if bid.startswith("\0"):
                # (volvió con otro id: los pasos más viejos lo encuentran igual)
                self._alias[bid[1:]] = self.ids[i]
                foco = i if foco < 0 else min(foco, i)
            elif bid in tocados:
                foco = i if foco < 0 else min(foco, i)
        return update, bool(update), foco

    # ── estado, para entrar o volver ──
    def estado(self) -> bytes:
        return self.doc.get_update()

    def vector(self) -> bytes:
        return self.doc.get_state()

    def diferencia(self, vector: bytes) -> bytes:
        try:
            return self.doc.get_update(vector) if vector else self.doc.get_update()
        except Exception:
            return self.doc.get_update()

    # ── lo que cambió aquí ──
    def desde_local(self, bloques: list) -> bytes:
        return self.escribir([_clave_bloque(b) for b in bloques])

    def escribir(self, nuevos: list, registrar: bool = True) -> bytes:
        viejos = self.sombra
        if nuevos == viejos:
            return b""
        from difflib import SequenceMatcher
        sv = self.doc.get_state()
        ids = list(self.ids)
        ops = _opcodes_bloques(viejos, nuevos)
        with self.doc.transaction(origin=_ORIGEN_LOCAL):
            for tag, i1, i2, j1, j2 in reversed(ops):
                if tag == "equal":
                    continue
                pares = _emparejar(viejos[i1:i2], nuevos[j1:j2])
                antes, c = [], 0
                for a, _b in pares:
                    antes.append(c)
                    if a is not None:
                        c += 1
                for (a, b), c in zip(reversed(pares), reversed(antes)):
                    if a is not None and b is not None:
                        self._actualizar_map(self.arr[i1 + a], viejos[i1 + a],
                                             nuevos[j1 + b])
                    elif a is not None:
                        del self.arr[i1 + a]
                        del ids[i1 + a]
                    else:
                        nid = _nuevo_id_bloque()
                        self._insertar_map(i1 + c, nid, nuevos[j1 + b])
                        ids.insert(i1 + c, nid)
        if registrar:
            self._registrar_paso(self.ids, viejos, ids, nuevos)
        self.sombra, self.ids = list(nuevos), ids
        return self.doc.get_update(sv)

    def _insertar_map(self, pos: int, nid: str, k: tuple) -> None:
        elem, texto, tags, fm, numero, doble = k
        self.arr.insert(pos, _CRDT_Map({
            "id": nid, "elem": elem, "texto": _CRDT_Text(),
            "tags": _CRDT_Array(list(tags)), "numero": numero, "doble": doble}))
        if texto:
            self._insertar_texto(self.arr[pos]["texto"], "", 0, texto,
                                 _attrs_de_canon(texto, fm))

    @staticmethod
    def _insertar_texto(tx, base: str, pos: int, nuevo: str,
                        attrs: Optional[list]) -> None:
        """Inserta `nuevo` en la posición `pos` (Python) de un texto que hoy
        dice `base`, con su formato exacto (sin heredar el del vecino)."""
        if not attrs:
            tx.insert(_pos_crdt(base, pos), nuevo, {})
            return
        ini = _pos_crdt(base, pos)
        o = 0
        # tramos con y sin formato, en orden
        i, n = 0, len(nuevo)
        while i < n:
            a = attrs[i]
            j = i + 1
            while j < n and attrs[j] == a:
                j += 1
            tx.insert(ini + o, nuevo[i:j], dict(a) if a else {})
            o += _largo_crdt(nuevo[i:j])
            i = j

    @staticmethod
    def _actualizar_lista(arr, viejos: tuple, nuevos: tuple) -> None:
        from difflib import SequenceMatcher
        ops = SequenceMatcher(None, list(viejos), list(nuevos),
                              autojunk=False).get_opcodes()
        for tag, i1, i2, j1, j2 in reversed(ops):
            if tag == "equal":
                continue
            if i2 > i1:
                del arr[i1:i2]
            for k, v in enumerate(nuevos[j1:j2]):
                arr.insert(i1 + k, v)

    def _actualizar_map(self, m, viejo: tuple, nuevo: tuple) -> None:
        if viejo[0] != nuevo[0]:
            m["elem"] = nuevo[0]
        if viejo[4] != nuevo[4]:
            m["numero"] = nuevo[4]
        if viejo[5] != nuevo[5]:
            m["doble"] = nuevo[5]
        if viejo[2] != nuevo[2]:
            self._actualizar_lista(m["tags"], viejo[2], nuevo[2])
        if viejo[1] != nuevo[1] or viejo[3] != nuevo[3]:
            self._actualizar_texto(m["texto"], viejo[1], viejo[3],
                                   nuevo[1], nuevo[3])

    def _actualizar_texto(self, tx, s_viejo: str, fm_viejo: tuple,
                          s_nuevo: str, fm_nuevo: tuple) -> None:
        a_viejo = _attrs_de_canon(s_viejo, fm_viejo)
        a_nuevo = _attrs_de_canon(s_nuevo, fm_nuevo)
        ops = _opcodes_texto(s_viejo, s_nuevo)
        # 1) el texto, de atrás hacia adelante (lo de la izquierda no se mueve)
        for tag, i1, i2, j1, j2 in reversed(ops):
            if tag == "equal":
                continue
            if i2 > i1:
                del tx[_pos_crdt(s_viejo, i1):_pos_crdt(s_viejo, i2)]
            if j2 > j1:
                self._insertar_texto(tx, s_viejo[:i1], i1, s_nuevo[j1:j2],
                                     a_nuevo[j1:j2] if a_nuevo else None)
        # 2) el formato de lo que no cambió de texto pero sí de formato
        if not a_viejo and not a_nuevo:
            return
        iguales = []
        pos_v = pos_n = 0
        for tag, i1, i2, j1, j2 in ops:
            iguales.append((pos_v, i1, pos_n))
            if tag == "equal":
                iguales.append((i1, i2, j1))
            pos_v, pos_n = i2, j2
        iguales.append((pos_v, len(s_viejo), pos_n))
        for v1, v2, n1 in iguales:
            k = 0
            while k < v2 - v1:
                av = a_viejo[v1 + k] if a_viejo else None
                an = a_nuevo[n1 + k] if a_nuevo else None
                if (av or None) == (an or None):
                    k += 1
                    continue
                k2 = k + 1
                while (k2 < v2 - v1
                       and (a_viejo[v1 + k2] if a_viejo else None) == av
                       and (a_nuevo[n1 + k2] if a_nuevo else None) == an):
                    k2 += 1
                cambio = {c: None for c in (av or {}) if c not in (an or {})}
                cambio.update({c: v for c, v in (an or {}).items()
                               if (av or {}).get(c) != v})
                if cambio:
                    tx.format(_pos_crdt(s_nuevo, n1 + k),
                              _pos_crdt(s_nuevo, n1 + k2), cambio)
                k = k2


# ── El resto del proyecto (fichas, Carta Gantt, storyboard…) ──
# Va en trozos: cada ficha, cada locación, cada planta… y el resto por
# clave. Cada trozo es «el último que guarda gana», en el orden del host.
_DATOS_FUERA = frozenset({
    "version", "bloques", "_tags_presentado", "clima_cache",
    "ruta_guardado_personalizada", "ruta_backups_personalizada",
    "ejemplo_fecha_base", "carpeta_archivos"})
_DATOS_FUERA_SUB = frozenset({
    ("colaboracion", "autor_id"), ("colaboracion", "pin_hash"),
    ("colaboracion", "colab_max_invitados")})
_SEP_DATOS = "\x1f"
# (lo que vive en cada computador: quién soy, el PIN, el cupo…)
_ATTRS_LOCALES = frozenset({
    "bloques", "autor_id", "pin_hash", "colab_max_invitados", "clima_cache",
    "ruta_guardado_personalizada", "ruta_backups_personalizada",
    "ejemplo_fecha_base", "_tags_presentado", "carpeta_archivos"})


def _datos_de_json(d: dict) -> dict:
    """{ruta: valor} de lo que se sincroniza fuera del guion."""
    planos: dict = {}
    for k, v in d.items():
        if k in _DATOS_FUERA:
            continue
        if isinstance(v, dict):
            for sk, sv in v.items():
                if (k, sk) in _DATOS_FUERA_SUB:
                    continue
                planos[k + _SEP_DATOS + str(sk)] = sv
        else:
            planos[k] = v
    return planos


def _datos_cambiados(antes: dict, ahora: dict) -> list:
    """[[ruta, valor|None]] de lo que cambió (None = se borró)."""
    ops = []
    for r, v in ahora.items():
        if r not in antes or antes[r] != v:
            ops.append([r, v])
    for r in antes:
        if r not in ahora:
            ops.append([r, None])
    return ops


def _aplicar_ops_planos(planos: dict, ops: list) -> dict:
    nuevo = dict(planos)
    for r, v in ops:
        if v is None:
            nuevo.pop(r, None)
        else:
            nuevo[r] = v
    return nuevo


def _armar_json_datos(planos: dict) -> dict:
    """Los trozos, de vuelta al JSON del proyecto (sin el guion)."""
    d: dict = {}
    for r, v in planos.items():
        if _SEP_DATOS in r:
            k, sk = r.split(_SEP_DATOS, 1)
            caja = d.get(k)
            if not isinstance(caja, dict):
                caja = d[k] = {}
            caja[sk] = v
        else:
            d[r] = v
    return d


def _por_defecto_json(o):
    if is_dataclass(o):
        return asdict(o)
    if isinstance(o, (set, frozenset, tuple)):
        return list(o)
    return str(o)


def _canon_valor(x) -> str:
    try:
        return json.dumps(x, sort_keys=True, ensure_ascii=False,
                          default=_por_defecto_json)
    except Exception:
        return repr(x)


_NADA = object()


def _fusionar_valores(base, actual, nuevo):
    """Fusión de tres: lleva a `actual` (lo que hay en el host) el cambio
    que hizo alguien de `base` a `nuevo`, sin pisar lo que otros cambiaron
    mientras (dos fichas, dos jornadas nuevas, dos campos distintos de la
    misma ficha: quedan todos). Si los dos cambiaron lo mismo, gana el
    último."""
    if actual == base:
        return nuevo
    if nuevo == base:
        return actual
    if nuevo is None:
        return actual          # (lo borró, pero alguien lo cambió: se queda)
    if isinstance(base, dict) and isinstance(actual, dict) and isinstance(nuevo, dict):
        out = dict(actual)
        for k in set(base) | set(nuevo):
            b, n = base.get(k, _NADA), nuevo.get(k, _NADA)
            if b == n:
                continue
            if n is _NADA:
                out.pop(k, None)
                continue
            a = actual.get(k, _NADA)
            out[k] = (_fusionar_valores(b, a, n)
                      if b is not _NADA and a is not _NADA else n)
        return out
    if isinstance(base, list) and isinstance(actual, list) and isinstance(nuevo, list):
        return _fusionar_listas(base, actual, nuevo)
    return nuevo


def _fusionar_listas(base: list, actual: list, nuevo: list) -> list:
    from collections import Counter
    if len(base) == len(nuevo):
        # (cambió algo de algunos elementos, sin agregar ni quitar)
        if len(actual) == len(base):
            return [_fusionar_valores(b, a, n) for b, a, n in zip(base, actual, nuevo)]
        out = list(actual)
        ca = [_canon_valor(x) for x in out]
        for b, n in zip(base, nuevo):
            if b == n:
                continue
            cb = _canon_valor(b)
            if cb in ca:
                k = ca.index(cb)
                out[k], ca[k] = n, _canon_valor(n)
            else:
                out.append(n)
                ca.append(_canon_valor(n))
        return out
    cb = [_canon_valor(x) for x in base]
    cn = [_canon_valor(x) for x in nuevo]
    quitar = Counter(cb) - Counter(cn)
    out, ca = [], []
    for x in actual:
        c = _canon_valor(x)
        if quitar.get(c, 0) > 0:
            quitar[c] -= 1
            continue
        out.append(x)
        ca.append(c)
    agregar = Counter(cn) - Counter(cb)
    for j, (x, c) in enumerate(zip(nuevo, cn)):
        if agregar.get(c, 0) <= 0:
            continue
        agregar[c] -= 1
        if j == 0:
            pos = 0
        elif cn[j - 1] in ca:
            pos = len(ca) - ca[::-1].index(cn[j - 1])
        else:
            pos = len(out)
        out.insert(pos, x)
        ca.insert(pos, c)
    return out


def _doc_desde_datos(d: dict) -> "Documento":
    return documento_desde_json(json.dumps({**d, "bloques": []},
                                           ensure_ascii=False))


def _copiar_datos_cambiados(vivo, viejo, nuevo) -> list:
    """Pasa al documento abierto (`vivo`) lo que es distinto entre dos
    versiones del resto del proyecto. Solo reemplaza lo que cambió (cada
    ficha, cada locación…), para no soltar lo que tiene abierta una
    ventana. Devuelve los nombres de lo que cambió."""
    cambiados = []
    for attr, v_nuevo in vars(nuevo).items():
        if attr in _ATTRS_LOCALES or attr.startswith("__"):
            continue
        v_viejo = getattr(viejo, attr, None)
        if _canon_valor(v_viejo) == _canon_valor(v_nuevo):
            continue
        cambiados.append(attr)
        actual = getattr(vivo, attr, None)
        if isinstance(actual, dict) and isinstance(v_nuevo, dict) \
                and isinstance(v_viejo, dict):
            for k in list(actual.keys()):
                if k not in v_nuevo and k in v_viejo:
                    del actual[k]
            for k, v in v_nuevo.items():
                if k not in v_viejo or _canon_valor(v_viejo[k]) != _canon_valor(v):
                    actual[k] = v
        else:
            setattr(vivo, attr, v_nuevo)
    return cambiados


PROTOCOLO_COLAB = 2          # sube cuando cambia lo que viaja (1.9.0 = 2)
PUERTO_COLAB = 9999          # TCP (la sesión) y UDP (buscar sesiones)
_BUSCAR_COLAB = b"ACCION?2"  # la pregunta «¿hay sesiones?» por UDP


def _ips_locales() -> list:
    """Las IP de este computador en la red (sin 127.0.0.1), la más probable
    primero: la de la salida a internet, después las de redes privadas."""
    ips: list = []
    principal = _ip_local()
    if principal and not principal.startswith("127."):
        ips.append(principal)
    try:
        from PySide6.QtNetwork import QNetworkInterface, QAbstractSocket
        for itf in QNetworkInterface.allInterfaces():
            fl = itf.flags()
            if not (fl & QNetworkInterface.InterfaceFlag.IsUp) or \
                    (fl & QNetworkInterface.InterfaceFlag.IsLoopBack):
                continue
            for e in itf.addressEntries():
                ip = e.ip()
                if ip.protocol() != QAbstractSocket.NetworkLayerProtocol.IPv4Protocol:
                    continue
                t = ip.toString()
                if t and not t.startswith(("127.", "169.254.")) and t not in ips:
                    ips.append(t)
    except Exception:
        pass
    privadas = [ip for ip in ips[1:] if ip.startswith(("192.168.", "10."))
                or any(ip.startswith(f"172.{n}.") for n in range(16, 32))]
    resto = [ip for ip in ips[1:] if ip not in privadas]
    return ips[:1] + privadas + resto


def _direcciones_difusion() -> list:
    """A dónde preguntar «¿hay sesiones?»: la difusión de cada red."""
    dirs = ["255.255.255.255"]
    try:
        from PySide6.QtNetwork import QNetworkInterface, QAbstractSocket
        for itf in QNetworkInterface.allInterfaces():
            fl = itf.flags()
            if not (fl & QNetworkInterface.InterfaceFlag.IsUp) or \
                    (fl & QNetworkInterface.InterfaceFlag.IsLoopBack):
                continue
            for e in itf.addressEntries():
                b = e.broadcast()
                if (e.ip().protocol() == QAbstractSocket.NetworkLayerProtocol.IPv4Protocol
                        and not b.isNull()):
                    t = b.toString()
                    if t and t not in dirs:
                        dirs.append(t)
    except Exception:
        pass
    return dirs


_TOPE_MENSAJE_COLAB = 0xFFFFFFF       # 256 MB por mensaje


def _cabecera_colab(n: int) -> bytes:
    """Los 8 bytes del largo: en decimal hasta 99.999.999 bytes (como en la
    1.9.0); desde ahí, «H» y siete cifras hexadecimales (hasta 256 MB)."""
    if n < 100_000_000:
        return f"{n:08d}".encode("ascii")
    return ("H" + f"{n:07x}").encode("ascii")


def _largo_de_cabecera(cab: bytes) -> int:
    t = cab.decode("ascii")
    if t[:1] == "H":
        return int(t[1:], 16)
    if not t.isdigit():
        raise ValueError(t)
    return int(t)


def _sin_error(fn, *args) -> None:
    """Llama a fn; si el objeto de Qt ya no existe (un socket que se cerró
    mientras esperaba), no pasa nada."""
    try:
        fn(*args)
    except RuntimeError:
        pass


class _ColabRuntime(QObject):
    """La conexión de una sesión de colaboración en la red local.

    · El host escucha en TCP 9999 (y responde «¿hay sesiones?» por UDP 9999).
    · Cada invitado tiene una sola conexión, con el host; el host reenvía.
      Como TCP entrega en orden y todo pasa por el host, a cada uno le
      llegan los cambios en un orden causal (nunca algo que dependa de otra
      cosa que todavía no tiene).
    · Mensajes: 8 bytes con el largo (en ASCII) + JSON en UTF-8.
    · Entrar: el invitado manda «hola» (versión del protocolo, nombre, PIN,
      y si vuelve a una sesión, cuál y qué tiene); el host revisa (versión,
      PIN, cupo, si lo sacaron) y la app le manda la «bienvenida» con el
      proyecto. Los permisos se revisan en el host: «editar» manda cambios,
      «notas» solo notas, «leer» nada.
    · Latido: un «ping» cada 4 s; 16 s sin nada = la conexión se cortó
      (pasa con el WiFi, sin aviso). El invitado vuelve a conectarse solo
      (cada 3 s, por 10 minutos) y se pone al día sin perder lo que
      escribió mientras tanto."""

    OFF = "off"
    ON = "on"
    PERDIDA = "perdida"
    CONECTANDO = "conectando"
    RECONECTANDO = "reconectando"

    estado_cambiado = Signal(str)
    mensaje_recibido = Signal(dict)
    participantes_cambiaron = Signal()
    mi_nivel_cambio = Signal(str)
    fui_pateado = Signal(str)
    recibiendo = Signal(int, int)           # (recibido, total) de un envío grande
    conexion_fallida = Signal(str)          # al unirse: por qué no se pudo
    rechazado = Signal(dict)                # el host no lo dejó entrar
    invitado_entro = Signal(object, dict)   # host: (socket, «hola») → bienvenida
    sesion_terminada = Signal(str)          # el host cerró la sesión
    sesiones_encontradas = Signal(list)     # respuesta a «buscar»

    _COLORES_PARTICIPANTES = [
        "#e63946", "#2a9d8f", "#f4a261", "#8338ec", "#0077b6", "#e07a5f",
        "#2b9348", "#f72585", "#b5838d", "#4361ee", "#9c6644", "#06d6a0",
    ]
    LATIDO_MS = 4000
    SILENCIO_MAX_S = 16
    REINTENTO_MS = 3000
    REINTENTO_MAX_S = 600
    PREFIJO = 8

    def __init__(self, parent=None):
        super().__init__(parent)
        self._server = None
        self._udp = None
        self._sockets: list = []
        self._buffers: dict = {}            # id(sock) → bytearray
        self._visto: dict = {}              # id(sock) → time.monotonic()
        self._estado: str = self.OFF
        self._es_host: bool = False
        self._ip_host: str = ""
        self._participantes: dict = {}
        self._peer_id_local: str = ""
        self._nombre_local: str = ""
        self._sock_a_peer: dict = {}
        self._esperando_bienvenida: set = set()
        self._pin_hash_sesion: str = ""
        self.sesion_id: str = ""
        self.cupo: int = 8
        self.nivel_por_defecto: str = "editar"
        self._niveles_recordados: dict = {}  # peer_id → nivel (si vuelve)
        self._baneados: set = set()
        self.solo_lectura_para_todos = False
        self.proveedor_info = None   # host: () → dict para «buscar sesiones»
        self.proveedor_hola = None   # invitado: () → dict extra para «hola»
        # (invitado) para reconectarse
        self._destino: tuple = ("", PUERTO_COLAB)
        self._pin_plano: str = ""
        self._sock_cliente = None
        self._intentando_desde = 0.0
        self._fue_aceptado = False
        self._fin_voluntario = False
        self._t_latido = QTimer(self)
        self._t_latido.setInterval(self.LATIDO_MS)
        self._t_latido.timeout.connect(self._latido)
        self._t_reintento = QTimer(self)
        self._t_reintento.setSingleShot(True)
        self._t_reintento.timeout.connect(self._reintentar)
        self._t_conexion = QTimer(self)
        self._t_conexion.setSingleShot(True)
        self._t_conexion.timeout.connect(self._conexion_no_responde)

    # ── estado ──
    def set_pin_sesion(self, pin_hash: str) -> None:
        self._pin_hash_sesion = pin_hash or ""

    def hay_pin_sesion(self) -> bool:
        return bool(self._pin_hash_sesion)

    @property
    def estado(self) -> str:
        return self._estado

    @property
    def conectado(self) -> bool:
        return self._estado == self.ON

    @property
    def en_sesion(self) -> bool:
        """Conectado, o volviendo a conectarse (la sesión sigue)."""
        return self._estado in (self.ON, self.RECONECTANDO)

    @property
    def es_host(self) -> bool:
        return self._es_host

    @property
    def n_pares(self) -> int:
        if self._es_host:
            return len(self._sock_a_peer)
        return len(self._sockets)

    @property
    def ip_host(self) -> str:
        return self._ip_host

    @property
    def peer_id_local(self) -> str:
        return self._peer_id_local

    @property
    def participantes(self) -> dict:
        return dict(self._participantes)

    def mi_nivel(self) -> str:
        info = self._participantes.get(self._peer_id_local)
        return (info or {}).get("nivel", "editar")

    def nivel_de(self, peer_id: str) -> str:
        return (self._participantes.get(peer_id) or {}).get("nivel", "leer")

    def peer_de(self, sock) -> str:
        return self._sock_a_peer.get(id(sock), "")

    def socket_de(self, peer_id: str):
        return (self._participantes.get(peer_id) or {}).get("sock")

    def _color_libre(self) -> str:
        usados = {p["color"] for p in self._participantes.values()}
        for c in self._COLORES_PARTICIPANTES:
            if c not in usados:
                return c
        return self._COLORES_PARTICIPANTES[
            len(self._participantes) % len(self._COLORES_PARTICIPANTES)]

    def _set_estado(self, e: str) -> None:
        if e != self._estado:
            self._estado = e
            self.estado_cambiado.emit(e)

    # ── participantes ──
    def registrar_local(self, nombre: str, peer_id: str = "") -> str:
        import uuid
        self._peer_id_local = peer_id or self._peer_id_local or uuid.uuid4().hex[:8]
        self._nombre_local = nombre or "Anónimo"
        self._participantes[self._peer_id_local] = {
            "nombre": self._nombre_local, "color": self._color_libre(),
            "sock": None, "es_local": True, "es_host": self._es_host,
            "nivel": "leer" if (self._es_host and self.solo_lectura_para_todos)
            else "editar"}
        self.participantes_cambiaron.emit()
        return self._peer_id_local

    def renombrar_participante(self, peer_id: str, nuevo_nombre: str) -> None:
        if peer_id in self._participantes:
            self._participantes[peer_id]["nombre"] = nuevo_nombre or "Anónimo"
            self.participantes_cambiaron.emit()
            if self._es_host:
                self._broadcast_participantes()

    def cambiar_nivel_participante(self, peer_id: str, nivel: str) -> None:
        """El host cambia el permiso de alguien (y avisa a todos)."""
        if nivel not in ("editar", "notas", "leer") or peer_id not in self._participantes:
            return
        if self._es_host and self.solo_lectura_para_todos:
            nivel = "leer"
        self._participantes[peer_id]["nivel"] = nivel
        if self._es_host and peer_id != self._peer_id_local:
            self._niveles_recordados[peer_id] = nivel
        self.participantes_cambiaron.emit()
        if peer_id == self._peer_id_local:
            self.mi_nivel_cambio.emit(nivel)
        if self._es_host:
            self._broadcast_participantes()

    def cambiar_nivel_de_todos(self, nivel: str) -> None:
        for pid, info in list(self._participantes.items()):
            if not info.get("es_local"):
                self.cambiar_nivel_participante(pid, nivel)

    def kick_participante(self, peer_id: str,
                          motivo: str = "El host te desconectó") -> bool:
        """Solo el host. No puede volver a esta sesión (sí a otra)."""
        if not self._es_host or peer_id == self._peer_id_local:
            return False
        sock = self.socket_de(peer_id)
        if sock is None:
            return False
        self._baneados.add(peer_id)
        self.enviar_a(sock, {"tipo": "pateado", "motivo": motivo})
        try:
            sock.flush()
            sock.disconnectFromHost()
        except Exception:
            pass
        return True

    def _broadcast_participantes(self) -> None:
        if not self._es_host:
            return
        lista = [{"peer_id": pid, "nombre": p["nombre"], "color": p["color"],
                  "nivel": p.get("nivel", "editar"),
                  "es_host": pid == self._peer_id_local}
                 for pid, p in self._participantes.items()]
        self.broadcast({"tipo": "participantes", "lista": lista})

    # ── host ──
    def iniciar_host(self, puerto: int = PUERTO_COLAB) -> bool:
        from PySide6.QtNetwork import QTcpServer, QHostAddress
        if self._server is not None:
            return True
        self._server = QTcpServer(self)
        if not self._server.listen(QHostAddress.SpecialAddress.AnyIPv4, puerto):
            self._server = None
            return False
        import uuid
        self.sesion_id = uuid.uuid4().hex[:12]
        self._es_host = True
        self._fin_voluntario = False
        self._baneados.clear()
        self._niveles_recordados.clear()
        ips = _ips_locales()
        self._ip_host = ips[0] if ips else "127.0.0.1"
        self._server.newConnection.connect(self._on_nueva_conexion)
        self._abrir_udp(puerto)
        self._t_latido.start()
        self._set_estado(self.ON)
        return True

    def _abrir_udp(self, puerto: int) -> None:
        try:
            from PySide6.QtNetwork import QUdpSocket, QHostAddress, QAbstractSocket
            u = QUdpSocket(self)
            modo = (QAbstractSocket.BindFlag.ShareAddress
                    | QAbstractSocket.BindFlag.ReuseAddressHint)
            if u.bind(QHostAddress(QHostAddress.SpecialAddress.AnyIPv4), puerto, modo):
                u.readyRead.connect(self._on_udp)
                self._udp = u
            else:
                u.deleteLater()
        except Exception:
            self._udp = None

    def _on_udp(self) -> None:
        import json
        u = self._udp
        while u is not None and u.hasPendingDatagrams():
            try:
                dg = u.receiveDatagram(512)
                if bytes(dg.data()).strip() != _BUSCAR_COLAB:
                    continue
                info = {}
                if callable(self.proveedor_info):
                    try:
                        info = dict(self.proveedor_info() or {})
                    except Exception:
                        info = {}
                info.update({
                    "accion": PROTOCOLO_COLAB, "version": __version__,
                    "puerto": PUERTO_COLAB, "ip": self._ip_host,
                    "pin": bool(self._pin_hash_sesion),
                    "personas": len(self._participantes), "cupo": self.cupo + 1,
                    "sesion": self.sesion_id})
                u.writeDatagram(json.dumps(info, ensure_ascii=False).encode("utf-8"),
                                dg.senderAddress(), dg.senderPort())
            except Exception:
                continue

    def _on_nueva_conexion(self) -> None:
        while self._server and self._server.hasPendingConnections():
            sock = self._server.nextPendingConnection()
            self._registrar_socket(sock)
            # (10 s para presentarse; si no, se corta)
            QTimer.singleShot(10_000, lambda s=sock: _sin_error(self._sin_hola, s))

    def _sin_hola(self, sock) -> None:
        if sock in self._sockets and id(sock) not in self._sock_a_peer:
            try:
                sock.abort()
            except Exception:
                pass

    # ── invitado ──
    def conectar_a(self, ip: str, puerto: int = PUERTO_COLAB, nombre: str = "",
                   pin: str = "") -> None:
        """Se conecta sin congelar la ventana: el resultado llega por
        `estado_cambiado(ON)` (adentro), `conexion_fallida` o `rechazado`."""
        self.detener(silencioso=True)
        if not self._peer_id_local:
            import uuid
            self._peer_id_local = uuid.uuid4().hex[:8]
        self._es_host = False
        self._destino = (ip, puerto)
        self._ip_host = ip
        self._pin_plano = pin or ""
        self._nombre_local = nombre or self._nombre_local or "Anónimo"
        self._fue_aceptado = False
        self._fin_voluntario = False
        self.sesion_id = ""
        self._set_estado(self.CONECTANDO)
        self._abrir_socket_cliente()

    def _abrir_socket_cliente(self) -> None:
        from PySide6.QtNetwork import QTcpSocket
        sock = QTcpSocket(self)
        self._sock_cliente = sock
        sock.connected.connect(lambda s=sock: self._cliente_conectado(s))
        sock.errorOccurred.connect(lambda _e, s=sock: self._cliente_error(s))
        self._t_conexion.start(6000)
        sock.connectToHost(self._destino[0], self._destino[1])

    def _cliente_conectado(self, sock) -> None:
        if sock is not self._sock_cliente:
            return
        self._t_conexion.stop()
        self._registrar_socket(sock)
        # (latido desde ya: si el proyecto es pesado, la bienvenida tarda, y
        # el host no debe creer que se cortó)
        self._t_latido.start()
        import hashlib
        hola = {"tipo": "hola", "proto": PROTOCOLO_COLAB, "app": __version__,
                "peer_id": self._peer_id_local, "nombre": self._nombre_local,
                "pin_hash": (hashlib.sha256(self._pin_plano.encode()).hexdigest()
                             if self._pin_plano else "")}
        if callable(self.proveedor_hola):
            try:
                hola.update(self.proveedor_hola() or {})
            except Exception:
                pass
        self.enviar_a(sock, hola)

    def _cliente_error(self, sock) -> None:
        if sock is not self._sock_cliente or self._estado not in (
                self.CONECTANDO, self.RECONECTANDO):
            return
        from PySide6.QtNetwork import QAbstractSocket
        err = sock.error()
        if sock in self._sockets:
            return          # ya estaba adentro: lo maneja «disconnected»
        self._t_conexion.stop()
        self._soltar_socket_cliente()
        if self._estado == self.RECONECTANDO:
            self._programar_reintento()
            return
        E = QAbstractSocket.SocketError
        if err == E.ConnectionRefusedError:
            motivo = ("El computador {ip} respondió, pero no hay una sesión "
                      "abierta: el host tiene que pulsar «Iniciar como host» "
                      "primero.")
        elif err == E.HostNotFoundError:
            motivo = "La IP «{ip}» no es válida. Revisa que esté bien escrita."
        elif err == E.NetworkError:
            motivo = ("Este computador no tiene red, o {ip} no es de esta red. "
                      "Revisa que los dos estén conectados al mismo WiFi o cable.")
        else:
            motivo = "No se pudo conectar con {ip}: " + (sock.errorString() or "error de red")
        self._set_estado(self.OFF)
        self.conexion_fallida.emit(motivo.format(ip=self._destino[0]))

    def _conexion_no_responde(self) -> None:
        if self._estado == self.RECONECTANDO:
            self._soltar_socket_cliente()
            self._programar_reintento()
            return
        if self._estado != self.CONECTANDO:
            return
        self._soltar_socket_cliente()
        self._set_estado(self.OFF)
        self.conexion_fallida.emit(
            f"{self._destino[0]} no responde.\n\n"
            "Lo más común: el firewall de Windows del computador del host "
            "bloquea la conexión (ver «¿No se conectan?» en el panel). "
            "También puede ser que la IP no sea la del host, o que los dos "
            "computadores no estén en la misma red (el WiFi de invitados de "
            "algunos colegios no deja que los computadores se vean).")

    def _soltar_socket_cliente(self) -> None:
        sock, self._sock_cliente = self._sock_cliente, None
        if sock is None:
            return
        try:
            sock.blockSignals(True)
            sock.abort()
            sock.deleteLater()
        except Exception:
            pass
        if sock in self._sockets:
            self._sockets.remove(sock)
        self._buffers.pop(id(sock), None)
        self._visto.pop(id(sock), None)

    def _programar_reintento(self) -> None:
        if time.monotonic() - self._intentando_desde > self.REINTENTO_MAX_S:
            self._set_estado(self.PERDIDA)
            self.sesion_terminada.emit(
                "No se pudo volver a conectar con el host en 10 minutos.")
            return
        self._t_reintento.start(self.REINTENTO_MS)

    def _reintentar(self) -> None:
        if self._estado != self.RECONECTANDO:
            return
        self._abrir_socket_cliente()

    def reconectar_ahora(self) -> None:
        if self._estado == self.RECONECTANDO:
            self._t_reintento.stop()
            self._soltar_socket_cliente()
            self._abrir_socket_cliente()

    # ── sockets ──
    def _registrar_socket(self, sock) -> None:
        if sock in self._sockets:
            return
        self._sockets.append(sock)
        self._buffers[id(sock)] = bytearray()
        self._visto[id(sock)] = time.monotonic()
        try:
            from PySide6.QtNetwork import QAbstractSocket
            sock.setSocketOption(QAbstractSocket.SocketOption.LowDelayOption, 1)
            sock.setSocketOption(QAbstractSocket.SocketOption.KeepAliveOption, 1)
        except Exception:
            pass
        sock.readyRead.connect(lambda s=sock: self._seguro(self._on_ready_read, s))
        sock.disconnected.connect(lambda s=sock: self._seguro(self._on_disconnected, s))

    def _seguro(self, fn, sock) -> None:
        # (al cerrar el programa, Qt puede avisar de un socket cuando este
        # objeto ya no existe)
        try:
            fn(sock)
        except RuntimeError:
            pass

    def _on_ready_read(self, sock) -> None:
        import json
        buf = self._buffers.get(id(sock))
        if buf is None:
            return
        buf.extend(bytes(sock.readAll()))
        self._visto[id(sock)] = time.monotonic()
        while len(buf) >= self.PREFIJO:
            try:
                n = _largo_de_cabecera(bytes(buf[:self.PREFIJO]))
            except (ValueError, UnicodeDecodeError):
                # (no es ¡Acción!, o se desordenó: cortar es más seguro)
                buf.clear()
                try:
                    sock.abort()
                except Exception:
                    pass
                return
            if len(buf) < self.PREFIJO + n:
                if n > 2_000_000:
                    # (un proyecto pesado: que se vea cuánto va)
                    self.recibiendo.emit(len(buf) - self.PREFIJO, n)
                return
            if n > 2_000_000:
                self.recibiendo.emit(n, n)
            payload = bytes(buf[self.PREFIJO:self.PREFIJO + n])
            del buf[:self.PREFIJO + n]
            try:
                msg = json.loads(payload.decode("utf-8"))
            except Exception:
                continue
            if not isinstance(msg, dict):
                continue
            try:
                self._procesar(msg, sock)
            except Exception:
                import traceback
                traceback.print_exc()
            if sock not in self._sockets:
                return

    def _procesar(self, msg: dict, sock) -> None:
        tipo = msg.get("tipo")
        if tipo == "ping":
            return
        if self._es_host:
            if tipo == "hola":
                self._host_recibe_hola(msg, sock)
                return
            if tipo == "hello":     # ¡Acción! 1.8 o anterior
                self.enviar_a(sock, {
                    "tipo": "pin_rechazado",
                    "motivo": ("Este host tiene ¡Acción! " + __version__ +
                               ". Para colaborar, todos necesitan la misma "
                               "versión: actualiza ¡Acción!.")})
                QTimer.singleShot(300, lambda s=sock: _sin_error(s.disconnectFromHost))
                return
            peer = self._sock_a_peer.get(id(sock), "")
            if not peer:
                return                  # no se ha presentado
            if not self._peer_puede_enviar(msg, peer):
                self._notificar_rechazo(sock, tipo or "?")
                self.mensaje_recibido.emit({"tipo": "_rechazado_interno",
                                            "original": msg,
                                            "_peer_id_origen": peer})
                return
            msg["_peer_id_origen"] = peer
            self.mensaje_recibido.emit(msg)
            return
        # invitado
        if tipo == "bienvenida":
            self._t_conexion.stop()
            self._fue_aceptado = True
            self.sesion_id = str(msg.get("sesion", "") or "")
            if self._peer_id_local not in self._participantes:
                self.registrar_local(self._nombre_local, self._peer_id_local)
            nivel = msg.get("nivel", "editar")
            if nivel in ("editar", "notas", "leer"):
                self._participantes[self._peer_id_local]["nivel"] = nivel
            self._t_latido.start()
            # (adentro ya: así lo que la app mande al recibirla sí sale)
            self._set_estado(self.ON)
            self.mensaje_recibido.emit(msg)
            self.mi_nivel_cambio.emit(self.mi_nivel())
            return
        if tipo in ("rechazado", "pin_rechazado"):
            self._fin_voluntario = True
            self._soltar_socket_cliente()
            self._sockets.clear()
            self._set_estado(self.OFF)
            self.rechazado.emit(msg)
            return
        if tipo == "doc_completo" and not self._fue_aceptado:
            self._fin_voluntario = True
            self._soltar_socket_cliente()
            self._set_estado(self.OFF)
            self.conexion_fallida.emit(
                "El host tiene una versión anterior de ¡Acción! (1.8 o antes). "
                f"Para colaborar, todos necesitan la {__version__}.")
            return
        if tipo == "pateado":
            self._fin_voluntario = True
            motivo = msg.get("motivo", "El host te desconectó")
            self.detener(silencioso=True)
            self.fui_pateado.emit(motivo)
            return
        if tipo == "fin_sesion":
            self._fin_voluntario = True
            self.detener(silencioso=True)
            self.sesion_terminada.emit(msg.get("motivo", "El host terminó la sesión."))
            return
        if tipo == "participantes":
            local = self._participantes.get(self._peer_id_local)
            nivel_antes = (local or {}).get("nivel")
            self._participantes = {}
            for p in msg.get("lista", []):
                pid = p.get("peer_id", "")
                if not pid:
                    continue
                self._participantes[pid] = {
                    "nombre": p.get("nombre", "Anónimo"),
                    "color": p.get("color", "#888888"), "sock": None,
                    "es_local": pid == self._peer_id_local,
                    "es_host": bool(p.get("es_host")),
                    "nivel": p.get("nivel", "editar")}
            if local is not None and self._peer_id_local not in self._participantes:
                self._participantes[self._peer_id_local] = local
            self.participantes_cambiaron.emit()
            nivel = self.mi_nivel()
            if nivel != nivel_antes:
                self.mi_nivel_cambio.emit(nivel)
            return
        if not self._fue_aceptado or self._estado != self.ON:
            return          # (antes de la bienvenida —también al volver— nada)
        self.mensaje_recibido.emit(msg)

    def _host_recibe_hola(self, msg: dict, sock) -> None:
        def rechazar(motivo: str, **extra):
            self.enviar_a(sock, {"tipo": "rechazado", "motivo": motivo, **extra})
            QTimer.singleShot(400, lambda s=sock: _sin_error(s.disconnectFromHost))
        peer_id = str(msg.get("peer_id", "") or "")
        if int(msg.get("proto", 0) or 0) != PROTOCOLO_COLAB:
            rechazar(f"El host tiene ¡Acción! {__version__} y tú la "
                     f"{msg.get('app', 'otra')}. Para colaborar, todos "
                     "necesitan la misma versión.")
            return
        if not peer_id:
            rechazar("Falta tu identificación.")
            return
        if peer_id in self._baneados:
            rechazar("El host te sacó de esta sesión.")
            return
        if self._pin_hash_sesion and msg.get("pin_hash", "") != self._pin_hash_sesion:
            rechazar("Este guion está protegido con un PIN. Escribe el PIN "
                     "del archivo para entrar." if not msg.get("pin_hash")
                     else "El PIN no es correcto.", pin=True)
            return
        otro = self.socket_de(peer_id)
        if otro is not None and otro is not sock:
            # (volvió antes de que se notara que se había ido)
            self._sock_a_peer.pop(id(otro), None)
            try:
                otro.blockSignals(True)
                otro.abort()
            except Exception:
                pass
            if otro in self._sockets:
                self._sockets.remove(otro)
            self._buffers.pop(id(otro), None)
        invitados = [p for p, i in self._participantes.items() if not i.get("es_local")]
        if peer_id not in invitados and len(invitados) >= self.cupo:
            rechazar(f"La sesión está llena ({self.cupo} invitados como máximo).")
            return
        nivel = self._niveles_recordados.get(peer_id, self.nivel_por_defecto)
        if self.solo_lectura_para_todos:
            nivel = "leer"
        info_previa = self._participantes.get(peer_id, {})
        self._participantes[peer_id] = {
            "nombre": str(msg.get("nombre", "") or "Anónimo")[:60],
            "color": info_previa.get("color") or self._color_libre(),
            "sock": sock, "es_local": False, "es_host": False, "nivel": nivel}
        self._sock_a_peer[id(sock)] = peer_id
        # (lo primero que recibe es la bienvenida: mientras la app la arma,
        # lo que se reparte a todos no le llega)
        self._esperando_bienvenida.add(id(sock))
        try:
            self.invitado_entro.emit(sock, msg)
        finally:
            self._esperando_bienvenida.discard(id(sock))
        self.participantes_cambiaron.emit()
        self._broadcast_participantes()
        self.estado_cambiado.emit(self._estado)   # (el contador de la barra)

    def _peer_puede_enviar(self, msg: dict, peer_id: str) -> bool:
        tipo = msg.get("tipo", "")
        if tipo in ("cursor", "ping", "sincronizar", "huella"):
            return True
        nivel = self.nivel_de(peer_id)
        if tipo == "agregar_nota":
            return nivel in ("editar", "notas")
        if tipo in ("crdt", "datos"):
            return nivel == "editar"
        return nivel == "editar"

    def _notificar_rechazo(self, sock, tipo_mensaje: str) -> None:
        self.enviar_a(sock, {"tipo": "rechazo_permiso",
                             "tipo_original": tipo_mensaje})

    def _on_disconnected(self, sock) -> None:
        peer_id = self._sock_a_peer.pop(id(sock), None)
        if sock in self._sockets:
            self._sockets.remove(sock)
        self._buffers.pop(id(sock), None)
        self._visto.pop(id(sock), None)
        try:
            sock.deleteLater()
        except Exception:
            pass
        if self._es_host:
            if peer_id and peer_id in self._participantes:
                del self._participantes[peer_id]
                self.participantes_cambiaron.emit()
                self._broadcast_participantes()
                self.estado_cambiado.emit(self._estado)
            return
        if sock is self._sock_cliente:
            self._sock_cliente = None
        if self._fin_voluntario or self._estado == self.OFF:
            return
        if self._fue_aceptado:
            # (se cortó: volver a conectarse solo, sin perder nada)
            if self._estado != self.RECONECTANDO:
                self._intentando_desde = time.monotonic()
            self._set_estado(self.RECONECTANDO)
            self._programar_reintento()
        else:
            self._set_estado(self.OFF)
            self.conexion_fallida.emit(
                f"{self._destino[0]} cortó la conexión antes de responder.")

    def _latido(self) -> None:
        ahora = time.monotonic()
        for sock in list(self._sockets):
            if ahora - self._visto.get(id(sock), ahora) > self.SILENCIO_MAX_S:
                try:
                    sock.abort()     # (dispara «disconnected»)
                except Exception:
                    pass
                continue
            self.enviar_a(sock, {"tipo": "ping"})

    # ── enviar ──
    def enviar_a(self, sock, msg: dict) -> bool:
        """False si no se pudo (o si pesa más de 256 MB)."""
        import json
        try:
            data = json.dumps(msg, ensure_ascii=False).encode("utf-8")
            if len(data) > _TOPE_MENSAJE_COLAB:
                return False
            sock.write(_cabecera_colab(len(data)) + data)
            return True
        except Exception:
            return False

    def broadcast(self, msg: dict, excepto=None) -> None:
        """A todos (el host: a cada invitado ya presentado; el invitado: al
        host). `excepto`: un socket que no lo recibe (quien lo mandó)."""
        import json
        if not self._sockets:
            return
        try:
            data = json.dumps(msg, ensure_ascii=False).encode("utf-8")
        except Exception:
            return
        if len(data) > _TOPE_MENSAJE_COLAB:
            return
        paquete = _cabecera_colab(len(data)) + data
        for sock in list(self._sockets):
            if sock is excepto:
                continue
            if self._es_host and (id(sock) not in self._sock_a_peer
                                  or id(sock) in self._esperando_bienvenida):
                continue
            try:
                sock.write(paquete)
            except Exception:
                pass

    # ── buscar sesiones (UDP) ──
    def buscar_sesiones(self, espera_ms: int = 1500) -> None:
        """Pregunta en la red quién tiene una sesión abierta; la respuesta
        llega por `sesiones_encontradas([...])`."""
        import json
        try:
            from PySide6.QtNetwork import QUdpSocket, QHostAddress
        except Exception:
            self.sesiones_encontradas.emit([])
            return
        u = QUdpSocket(self)
        if not u.bind(QHostAddress(QHostAddress.SpecialAddress.AnyIPv4), 0):
            u.deleteLater()
            self.sesiones_encontradas.emit([])
            return
        vistas: dict = {}

        def leer():
            while u.hasPendingDatagrams():
                try:
                    dg = u.receiveDatagram(4096)
                    info = json.loads(bytes(dg.data()).decode("utf-8"))
                except Exception:
                    continue
                if not isinstance(info, dict) or "accion" not in info:
                    continue
                ip = dg.senderAddress().toString().replace("::ffff:", "")
                info["ip"] = ip or info.get("ip", "")
                vistas[info.get("sesion") or ip] = info
        u.readyRead.connect(leer)
        for d in _direcciones_difusion() + ["127.0.0.1"]:
            try:
                u.writeDatagram(_BUSCAR_COLAB, QHostAddress(d), PUERTO_COLAB)
            except Exception:
                pass

        def terminar():
            leer()
            u.close()
            u.deleteLater()
            self.sesiones_encontradas.emit(sorted(
                vistas.values(), key=lambda i: (i.get("nombre", ""), i.get("ip", ""))))
        QTimer.singleShot(max(300, espera_ms), terminar)

    # ── terminar ──
    def detener(self, silencioso: bool = False, motivo: str = "") -> None:
        """Termina la sesión. El host avisa a todos («fin_sesion»)."""
        self._fin_voluntario = True
        self._t_latido.stop()
        self._t_reintento.stop()
        self._t_conexion.stop()
        if self._es_host and self._sockets and not silencioso:
            self.broadcast({"tipo": "fin_sesion",
                            "motivo": motivo or "El host terminó la sesión."})
            for s in list(self._sockets):
                try:
                    s.flush()
                    s.waitForBytesWritten(300)
                except Exception:
                    pass
        for sock in list(self._sockets):
            try:
                sock.blockSignals(True)
                sock.disconnectFromHost()
                sock.deleteLater()
            except Exception:
                pass
        self._sockets.clear()
        self._buffers.clear()
        self._visto.clear()
        if self._sock_cliente is not None:
            self._soltar_socket_cliente()
        if self._server is not None:
            try:
                self._server.close()
                self._server.deleteLater()
            except Exception:
                pass
            self._server = None
        if self._udp is not None:
            try:
                self._udp.close()
                self._udp.deleteLater()
            except Exception:
                pass
            self._udp = None
        self._es_host = False
        self._fue_aceptado = False
        self._participantes.clear()
        self._sock_a_peer.clear()
        self.participantes_cambiaron.emit()
        self._set_estado(self.OFF)


def _cifrar_datos_valor(ruta: str, valor, pin: str):
    """Antes de mandar un trozo del proyecto: los datos personales (fichas
    de personaje y equipo técnico) viajan cifrados con el PIN del guion."""
    if not pin or valor is None:
        return valor
    try:
        if ruta.startswith("fichas" + _SEP_DATOS) and isinstance(valor, dict):
            return _cifrar_ficha_para_serializar(dict(valor), pin)
        if ruta == "tecnicos" and isinstance(valor, list):
            out = []
            for t in valor:
                t = dict(t) if isinstance(t, dict) else t
                if isinstance(t, dict):
                    for c in CAMPOS_SENSIBLES_TECNICO:
                        v = t.get(c, "")
                        if v and not esta_cifrado(v):
                            t[c] = cifrar_texto(str(v), pin)
                out.append(t)
            return out
    except Exception:
        pass
    return valor


def _descifrar_profundo(x, pin: str):
    if isinstance(x, str):
        if esta_cifrado(x):
            plano = descifrar_texto(x, pin)
            return x if plano is None else plano
        return x
    if isinstance(x, list):
        return [_descifrar_profundo(v, pin) for v in x]
    if isinstance(x, dict):
        return {k: _descifrar_profundo(v, pin) for k, v in x.items()}
    return x


def _descifrar_datos_valor(ruta: str, valor, pin: str):
    if not pin or valor is None:
        return valor
    if ruta.startswith("fichas" + _SEP_DATOS) or ruta == "tecnicos":
        return _descifrar_profundo(valor, pin)
    return valor


class _SesionColab(QObject):
    """Une el editor de una ventana con la red, durante una sesión.

    · El guion: cada cambio local sale a los 0,12 s (o a los 0,4 s si se
      sigue escribiendo sin parar); lo que llega se aplica bloque a bloque.
    · El resto del proyecto: se revisa cada 1,5 s qué trozo cambió (una
      ficha, una jornada…) y se manda; el host los ordena.
    · Los cursores de los demás se ven en la hoja, con su nombre."""

    huellas_cambiaron = Signal()

    def __init__(self, vp):
        super().__init__(vp)
        self.vp = vp
        self.rt: "_ColabRuntime" = vp._colab_runtime
        # 🧾 La huella de cada copia (para ver que todas son iguales)
        self.huellas: dict = {}
        self._hash_trozos: dict = {}
        self._cambios = 0
        self._huella_cache = ("", -2)
        self._huella_mandada = ""
        self.guion: Optional["_GuionCompartido"] = None
        self.activa = False
        self._datos: dict = {}
        self._doc_datos = None
        self._seq_datos = 0
        self._n_local = 0
        self._pendientes: dict = {}
        self._en_vuelo: dict = {}      # invitado: n → ops mandadas sin confirmar
        self._datos_sucios = True
        self._t_datos_revisados = 0.0
        self._costo_datos = 0.0
        self._ultimo_tecleo = 0.0
        self._por_verificar = False
        self._n_aplicado: dict = {}    # host: peer → último n aplicado
        self._ultimo_remoto = 0.0
        self._cursores: dict = {}
        self._pin = ""
        self.host_nombre = ""
        self.titulo_sesion = ""
        self._t_local = QTimer(self)
        self._t_local.setSingleShot(True)
        self._t_local.setInterval(120)
        self._t_local.timeout.connect(self.enviar_local)
        self._t_local_max = QTimer(self)
        self._t_local_max.setSingleShot(True)
        self._t_local_max.setInterval(400)
        self._t_local_max.timeout.connect(self.enviar_local)
        self._t_datos = QTimer(self)
        self._t_datos.setInterval(1500)
        self._t_datos.timeout.connect(self._revisar)
        self._t_verificar = QTimer(self)
        self._t_verificar.setInterval(10_000)
        self._t_verificar.timeout.connect(self._verificar)
        self._t_cursor = QTimer(self)
        self._t_cursor.setSingleShot(True)
        self._t_cursor.setInterval(200)
        self._t_cursor.timeout.connect(self._enviar_cursor)
        self._t_fade = QTimer(self)
        self._t_fade.setInterval(500)
        self._t_fade.timeout.connect(self._fade_cursores)
        self._t_huella = QTimer(self)
        self._t_huella.setInterval(2000)
        self._t_huella.timeout.connect(self._mandar_huella)
        self.rt.mensaje_recibido.connect(self._on_mensaje)
        self.rt.invitado_entro.connect(self._on_invitado_entro)
        self.rt.participantes_cambiaron.connect(self._limpiar_cursores)
        self.rt.proveedor_info = self._info_publica
        self.rt.proveedor_hola = self._datos_hola
        ed = vp.editor
        ed.document().contentsChanged.connect(self._al_cambiar_local)
        ed.estructura_cambiada.connect(self._al_cambiar_local)
        ed.cursorPositionChanged.connect(self._al_mover_cursor)

    # ── utilidades ──
    @property
    def editor(self):
        return self.vp.editor

    @property
    def doc(self):
        return self.vp.editor.documento

    def puede_editar(self) -> bool:
        return (self.activa and self.rt.mi_nivel() == "editar"
                and not getattr(self.vp, "_modo_solo_lectura", False))

    def _info_publica(self) -> dict:
        d = self.doc
        return {"nombre": self.rt._nombre_local,
                "titulo": (getattr(d, "titulo", "") or "Sin título")[:80]}

    def _datos_hola(self) -> dict:
        if self.guion is None or not self.rt.sesion_id:
            return {}
        return {"sesion": self.rt.sesion_id,
                "sv": base64.b64encode(self.guion.vector()).decode("ascii")}

    def _json_sin_guion(self, pin: str = "") -> dict:
        d = json.loads(documento_a_json(self.doc, pin))
        d.pop("bloques", None)
        return d

    def _estado_datos(self) -> dict:
        return _datos_de_json(self._json_sin_guion())

    # ── empezar / terminar ──
    def iniciar_host(self, nombre: str, nivel_defecto: str, cupo: int) -> bool:
        if not _CRDT_DISPONIBLE:
            return False
        ed = self.editor
        try:
            ed._reconciliar_modelo()
        except Exception:
            pass
        rt = self.rt
        rt.solo_lectura_para_todos = bool(getattr(self.vp, "_modo_solo_lectura", False))
        rt.cupo = max(1, int(cupo))
        rt.nivel_por_defecto = nivel_defecto if nivel_defecto in (
            "editar", "notas", "leer") else "editar"
        if not rt.iniciar_host(PUERTO_COLAB):
            return False
        rt.set_pin_sesion(getattr(self.doc, "pin_hash", "") or "")
        rt.registrar_local(nombre)
        self._pin = ((getattr(self.vp, "_pin_plano_sesion", "") or "")
                     if getattr(self.doc, "pin_hash", "") else "")
        self.guion = _GuionCompartido(bloques=self.doc.bloques)
        self._datos = self._estado_datos()
        self._doc_datos = None
        self._seq_datos = 0
        self._n_aplicado = {}
        self.host_nombre = nombre
        self._activar()
        return True

    def unirse(self, ip: str, nombre: str, pin: str = "") -> None:
        self._pin = pin or ""
        self.guion = None
        self.rt.conectar_a(ip, PUERTO_COLAB, nombre=nombre, pin=pin)

    def _activar(self) -> None:
        self.activa = True
        self._t_datos.start()
        self._t_verificar.start()
        self._t_fade.start()
        self._t_huella.start()
        self.huellas = {}
        self._huella_mandada = ""
        self._cambios += 1
        # (el resto del proyecto se acaba de leer al entrar o al abrir)
        self._datos_sucios = False
        self._t_datos_revisados = time.monotonic()
        self.editor._deshacer_externo = self._deshacer
        self.editor._rehacer_externo = self._rehacer
        app = QApplication.instance()
        if app is not None:
            app.installEventFilter(self)

    def terminar(self) -> None:
        """La sesión terminó (por quien sea): el guion queda como está."""
        if self.activa and self.guion is not None and self.puede_editar():
            try:
                self.editor._reconciliar_modelo()
            except Exception:
                pass
        self.activa = False
        app = QApplication.instance()
        if app is not None:
            app.removeEventFilter(self)
        for t in (self._t_local, self._t_local_max, self._t_datos,
                  self._t_verificar, self._t_cursor, self._t_fade, self._t_huella):
            t.stop()
        self.huellas = {}
        self.huellas_cambiaron.emit()
        self.guion = None
        self._datos = {}
        self._doc_datos = None
        self._pendientes.clear()
        self._en_vuelo.clear()
        self._cursores.clear()
        ed = self.editor
        ed._deshacer_externo = None
        ed._rehacer_externo = None
        ed.set_cursores_remotos({}, {})
        try:
            ed._reiniciar_historial()
        except Exception:
            pass

    # ── lo que cambia aquí ──
    def _al_cambiar_local(self) -> None:
        if not self.activa or getattr(self.editor, "_aplicando_remoto", False):
            return
        self._ultimo_tecleo = time.monotonic()
        self._t_local.start()
        if not self._t_local_max.isActive():
            self._t_local_max.start()

    def enviar_local(self) -> None:
        """Manda lo que cambió en el guion (si se puede editar)."""
        self._t_local.stop()
        self._t_local_max.stop()
        if not self.activa or self.guion is None:
            return
        if not self.puede_editar():
            return
        ed = self.editor
        try:
            ed._reconciliar_modelo()
        except Exception:
            pass
        upd = self.guion.desde_local(self.doc.bloques)
        if upd:
            self._cambios += 1
            self._mandar_crdt(upd)

    def cortar_paso(self) -> None:
        if self.guion is not None:
            self.enviar_local()
            self.guion.cortar_paso()

    def _mandar_crdt(self, upd: bytes, excepto=None) -> None:
        if not self.rt.conectado:
            return       # (al volver, se manda lo que falte)
        self.rt.broadcast({"tipo": "crdt",
                           "u": base64.b64encode(upd).decode("ascii")},
                          excepto=excepto)

    # ── Ctrl+Z / Ctrl+Y en sesión: solo lo propio ──
    def _deshacer(self, rehacer: bool = False) -> bool:
        if not self.puede_editar() or self.guion is None:
            return False
        self.enviar_local()
        upd, cambio, foco = (self.guion.rehacer() if rehacer
                             else self.guion.deshacer())
        if upd:
            self._cambios += 1
            self._mandar_crdt(upd)
        if cambio:
            self._llevar_al_editor(foco=foco)
        return cambio

    def _rehacer(self) -> bool:
        return self._deshacer(rehacer=True)

    # ── lo que llega ──
    def _llevar_al_editor(self, foco: int = -1) -> None:
        if self.guion is None:
            return
        nuevos = self.guion.bloques()
        if not nuevos:
            nuevos = [Bloque(Elem.ACCION, "")]
        self.editor.aplicar_bloques_remotos(nuevos, foco=foco)
        self.vp._refrescar_panel_notas_si_visible()
        self._pintar_cursores()

    def _on_mensaje(self, msg: dict) -> None:
        tipo = msg.get("tipo")
        try:
            if tipo == "bienvenida":
                self._recibir_bienvenida(msg)
            elif tipo == "crdt":
                self._recibir_crdt(msg)
            elif tipo == "datos":
                self._recibir_datos(msg)
            elif tipo == "agregar_nota":
                self._recibir_nota(msg)
            elif tipo == "cursor":
                self._recibir_cursor(msg)
            elif tipo in ("huella", "huellas"):
                self._recibir_huella(msg)
            elif tipo == "_rechazado_interno":
                self._corregir_rechazado(msg)
            elif tipo == "rechazo_permiso":
                self.vp.statusBar().showMessage(
                    "⚠ El host no aceptó tu cambio: tu permiso en esta sesión "
                    "no lo permite.", 4000)
        except Exception:
            import traceback
            traceback.print_exc()

    def _recibir_crdt(self, msg: dict) -> None:
        if self.guion is None:
            return
        try:
            upd = base64.b64decode(msg.get("u", ""))
        except Exception:
            return
        # 1) lo propio primero (así el modelo y la sombra quedan iguales)
        self.enviar_local()
        cambio = self.guion.aplicar_remoto(upd)
        self._ultimo_remoto = time.monotonic()
        self._por_verificar = True
        self._cambios += 1
        # 2) el host lo pasa a los demás
        if self.rt.es_host:
            origen = self.rt.socket_de(msg.get("_peer_id_origen", ""))
            self._mandar_crdt(upd, excepto=origen)
        if cambio:
            self._llevar_al_editor()

    def _recibir_bienvenida(self, msg: dict) -> None:
        """(invitado) Entrar —o volver— a la sesión."""
        vp = self.vp
        try:
            crdt = base64.b64decode(msg.get("crdt", "") or "")
            sv_host = base64.b64decode(msg.get("sv_host", "") or "")
        except Exception:
            crdt, sv_host = b"", b""
        self.host_nombre = msg.get("host", "") or "el host"
        self.titulo_sesion = msg.get("titulo", "") or ""
        vuelve = bool(msg.get("reconexion")) and self.guion is not None
        doc_json = msg.get("doc") or "{}"
        try:
            remoto = json.loads(doc_json)
        except ValueError:
            remoto = {}
        remoto.pop("bloques", None)
        datos_host = {r: _descifrar_datos_valor(r, v, self._pin)
                      for r, v in _datos_de_json(remoto).items()}
        if vuelve:
            # (lo escrito sin conexión se suma; nada se pierde)
            try:
                locales = _datos_cambiados(self._datos, self._estado_datos())
            except Exception:
                locales = []
            bases = {r: self._datos.get(r) for r, _v in locales}
            if self.guion.aplicar_remoto(crdt):
                self._llevar_al_editor()
            # el resto del proyecto, como lo tiene el host…
            vivo = self._estado_datos()
            self._aplicar_ops_vivo(_datos_cambiados(vivo, datos_host), base=vivo)
            self._datos = self._estado_datos()
            self._seq_datos = int(msg.get("seq_datos", 0) or 0)
            self._pendientes.clear()
            if self.puede_editar():
                falta = self.guion.diferencia(sv_host)
                if falta:
                    self._mandar_crdt(falta)
                self.enviar_local()
                # …lo que se mandó y no alcanzó a llegar…
                n_host = int(msg.get("n_datos", 0) or 0)
                for k in sorted(self._en_vuelo):
                    if k <= n_host:
                        del self._en_vuelo[k]
                        continue
                    for op in self._en_vuelo[k]:
                        self._pendientes[op[0]] = k
                    self.rt.broadcast({"tipo": "datos", "n": k, "ops": self._en_vuelo[k]})
                # …y lo de aquí, con cómo estaba antes del corte: el host lo
                # junta con lo que hicieron los demás mientras
                if locales:
                    self._n_local += 1
                    for r, _v in locales:
                        self._pendientes[r] = self._n_local
                    envio = [[r, _cifrar_datos_valor(r, v, self._pin),
                              _cifrar_datos_valor(r, bases.get(r), self._pin)]
                             for r, v in locales]
                    self._en_vuelo[self._n_local] = envio
                    self.rt.broadcast({"tipo": "datos", "n": self._n_local, "ops": envio})
            vp.statusBar().showMessage("🟢 De vuelta en la sesión: todo al día.", 5000)
            return
        # Entrar por primera vez (o a una sesión nueva del host)
        if self.guion is not None:
            # (el host empezó otra sesión: mi copia de la anterior se guarda
            # antes de reemplazarla, por si tenía algo que no alcanzó a llegar)
            ruta = vp._colab_respaldar_copia()
            if ruta:
                QTimer.singleShot(0, lambda r=ruta: QMessageBox.information(
                    vp, "👥 Sesión nueva",
                    "El host empezó una sesión nueva. Tu copia de la anterior "
                    f"quedó guardada en:\n{r}"))
        self.guion = _GuionCompartido(estado=crdt)
        try:
            doc = documento_desde_json(json.dumps({**remoto, "bloques": []},
                                                  ensure_ascii=False))
        except Exception:
            doc = Documento()
        doc.bloques = self.guion.bloques() or [Bloque(Elem.ACCION, "")]
        doc.autor_id = self.rt._nombre_local
        if self._pin:
            try:
                vp._descifrar_datos_sensibles(doc, self._pin)
            except Exception:
                pass
        vp._entrar_a_sesion_como_invitado(doc, msg, self._pin)
        self._datos = self._estado_datos()
        self._doc_datos = None
        self._seq_datos = int(msg.get("seq_datos", 0) or 0)
        self._n_local = 0
        self._en_vuelo = {}
        self._pendientes = {}
        self._activar()

    def _on_invitado_entro(self, sock, hola: dict) -> None:
        """(host) Alguien entró o volvió: mandarle todo."""
        if self.guion is None:
            return
        self.enviar_local()
        if self._datos_sucios:
            self.enviar_datos_locales()
        rt = self.rt
        peer = rt.peer_de(sock)
        vuelve = (hola.get("sesion") == rt.sesion_id and bool(hola.get("sv")))
        crdt = self.guion.estado()
        if vuelve:
            try:
                crdt = self.guion.diferencia(base64.b64decode(hola["sv"]))
            except Exception:
                vuelve, crdt = False, self.guion.estado()
        d = self.doc
        doc_json = documento_a_json(d, self._pin)
        ok = rt.enviar_a(sock, {
            "tipo": "bienvenida", "proto": PROTOCOLO_COLAB, "app": __version__,
            "sesion": rt.sesion_id, "nivel": rt.nivel_de(peer),
            "reconexion": vuelve,
            "doc": doc_json,
            "crdt": base64.b64encode(crdt).decode("ascii"),
            "sv_host": base64.b64encode(self.guion.vector()).decode("ascii"),
            "seq_datos": self._seq_datos,
            "n_datos": self._n_aplicado.get(peer, 0) if vuelve else 0,
            "host": rt._nombre_local,
            "titulo": getattr(d, "titulo", "") or "",
            "host_solo_lectura": bool(getattr(self.vp, "_modo_solo_lectura", False)),
        })
        if not ok:
            mb = len(doc_json.encode("utf-8")) // (1024 * 1024)
            motivo = (f"El proyecto pesa {mb} MB (con sus fotos y documentos): es "
                      "más de lo que se puede compartir en una sesión (256 MB). "
                      "Para colaborar, saquen algunos documentos o fotos pesadas "
                      "a otro archivo.")
            rt.enviar_a(sock, {"tipo": "rechazado", "motivo": motivo})
            QTimer.singleShot(400, lambda s=sock: _sin_error(s.disconnectFromHost))
            self.vp.statusBar().showMessage("⚠ " + motivo, 10000)
            return
        self.vp.statusBar().showMessage(
            f"👥 {(hola.get('nombre') or 'Alguien')} "
            f"{'volvió a' if vuelve else 'entró a'} la sesión.", 4000)
        self._enviar_cursor(forzar=True)

    def _revisar(self) -> None:
        """Cada 1,5 s: lo que cambió sin avisar en el guion (un diálogo que
        tocó un tag, la numeración…) y, si se usó algo fuera de la hoja (una
        ficha, la Carta Gantt, el ribbon…), el resto del proyecto. Revisar el
        resto cuesta en un proyecto con muchas fotos (un tercio de segundo
        cada 100 MB): por eso no se hace mientras solo se escribe el guion;
        igual se revisa de vez en cuando."""
        if getattr(self.editor, "_aplicando_remoto", False):
            return
        self.enviar_local()
        ahora = time.monotonic()
        cada = max(20.0, 120.0 * self._costo_datos)
        if self._datos_sucios or (ahora - self._t_datos_revisados > cada
                                  and ahora - self._ultimo_tecleo > 3):
            self.enviar_datos_locales()

    def eventFilter(self, obj, ev) -> bool:
        # (un clic o una tecla fuera de la hoja: puede haber cambiado algo
        # del resto del proyecto)
        t = ev.type()
        if t in (QEvent.Type.MouseButtonRelease, QEvent.Type.KeyRelease,
                 QEvent.Type.Drop):
            try:
                ed = self.editor
                # (lo que se escribe o se hace clic en la hoja sube hasta la
                # ventana principal: eso no cuenta)
                if (isinstance(obj, QWidget) and obj is not ed
                        and not ed.isAncestorOf(obj) and not obj.isAncestorOf(ed)):
                    self._datos_sucios = True
            except RuntimeError:
                pass
        return False

    # ── el resto del proyecto ──
    def enviar_datos_locales(self) -> None:
        if not self.activa or self.guion is None:
            return
        self._datos_sucios = False
        t0 = time.monotonic()
        try:
            ahora = self._estado_datos()
        except Exception:
            return
        self._t_datos_revisados = time.monotonic()
        self._costo_datos = self._t_datos_revisados - t0
        ops = _datos_cambiados(self._datos, ahora)
        if not ops:
            return
        if not self.puede_editar():
            # (sin permiso: lo local vuelve a como está en la sesión)
            self._volver_datos(ops)
            return
        if not self.rt.conectado:
            return       # (se manda al volver)
        antes = self._datos
        # (solo cambian los trozos que cambiaron: los demás siguen siendo los
        # mismos objetos, y la huella no los vuelve a calcular)
        self._datos = _aplicar_ops_planos(antes, ops)
        self._doc_datos = None
        self._cambios += 1
        if self.rt.es_host:
            envio = [[r, _cifrar_datos_valor(r, v, self._pin)] for r, v in ops]
            self._seq_datos += 1
            self.rt.broadcast({"tipo": "datos", "seq": self._seq_datos,
                               "ops": envio, "de": self.rt.peer_id_local})
        else:
            # (con cómo estaba antes: el host junta este cambio con otros que
            # hayan llegado mientras, en vez de pisarlos)
            envio = []
            for r, v in ops:
                base = antes.get(r)
                if base is not None and len(_canon_valor(base)) > 300_000:
                    base = None
                envio.append([r, _cifrar_datos_valor(r, v, self._pin),
                              _cifrar_datos_valor(r, base, self._pin)])
            self._n_local += 1
            for r, _v in ops:
                self._pendientes[r] = self._n_local
            self._en_vuelo[self._n_local] = envio
            self.rt.broadcast({"tipo": "datos", "ops": envio, "n": self._n_local})

    def _recibir_datos(self, msg: dict) -> None:
        crudas = [op for op in (msg.get("ops") or [])
                  if isinstance(op, list) and len(op) >= 2 and isinstance(op[0], str)]
        ops = [[op[0], _descifrar_datos_valor(op[0], op[1], self._pin)] for op in crudas]
        n_msg = int(msg.get("n", 0) or 0)
        if self.rt.es_host:
            origen = msg.get("_peer_id_origen", "")
            if n_msg and n_msg <= self._n_aplicado.get(origen, 0):
                ops = []          # (ya estaba: lo mandó de nuevo al volver)
            elif n_msg:
                self._n_aplicado[origen] = n_msg
            if not ops:
                if n_msg:
                    sock = self.rt.socket_de(origen)
                    if sock is not None:
                        self.rt.enviar_a(sock, {"tipo": "datos", "seq": self._seq_datos,
                                                "ops": [], "de": origen, "n": n_msg})
                return
        elif msg.get("de") == self.rt.peer_id_local and n_msg:
            for k in [k for k in self._en_vuelo if k <= n_msg]:
                del self._en_vuelo[k]
        if not ops:
            return
        if self.rt.es_host:
            # ordenar: lo propio primero, después lo que llegó; a todos
            if self._datos_sucios:
                self.enviar_datos_locales()
            for op, cruda in zip(ops, crudas):
                if len(cruda) >= 3 and cruda[2] is not None:
                    base = _descifrar_datos_valor(cruda[0], cruda[2], self._pin)
                    op[1] = _fusionar_valores(base, self._datos.get(op[0]), op[1])
            self._seq_datos += 1
            self._datos_remotos(ops)
            self.rt.broadcast({"tipo": "datos", "seq": self._seq_datos,
                               "ops": [[r, _cifrar_datos_valor(r, v, self._pin)]
                                       for r, v in ops],
                               "de": origen, "n": msg.get("n", 0)})
            return
        if self._datos_sucios:
            self.enviar_datos_locales()
        self._seq_datos = max(self._seq_datos, int(msg.get("seq", 0) or 0))
        if msg.get("de") == self.rt.peer_id_local:
            n = int(msg.get("n", 0) or 0)
            propias = []
            for r, v in ops:
                ultimo = self._pendientes.get(r, 0)
                if ultimo > n:
                    continue          # (ya mandé algo más nuevo)
                if ultimo == n:
                    self._pendientes.pop(r, None)
                propias.append([r, v])
            ops = propias
        if ops:
            self._datos_remotos(ops)

    def _datos_remotos(self, ops: list) -> None:
        """Aplica trozos del proyecto que llegaron (ya ordenados). Antes se
        mandó lo propio, así que lo que no está al día aquí es solo esto."""
        if not ops:
            return
        self._aplicar_ops_vivo(ops, base=self._datos)
        self._datos = _aplicar_ops_planos(self._datos, ops)
        self._ultimo_remoto = time.monotonic()

    def _aplicar_ops_vivo(self, ops: list, base: dict) -> None:
        """Lleva trozos al documento abierto, tocando solo lo que cambió.
        (Arma el proyecto solo con las claves que llegaron: en uno con muchas
        fotos, cambiar una jornada no obliga a leer todas las fichas.)"""
        claves = {r.split(_SEP_DATOS, 1)[0] for r, _v in ops}
        base = {r: v for r, v in base.items() if r.split(_SEP_DATOS, 1)[0] in claves}
        try:
            viejo = _doc_desde_datos(_armar_json_datos(base))
            nuevo = _doc_desde_datos(_armar_json_datos(_aplicar_ops_planos(base, ops)))
        except Exception:
            import traceback
            traceback.print_exc()
            return
        cambiados = _copiar_datos_cambiados(self.doc, viejo, nuevo)
        self._cambios += 1
        if cambiados:
            self.vp._colab_datos_cambiaron(cambiados)

    def _volver_datos(self, ops: list) -> None:
        """Deshace en el documento lo que cambió sin permiso."""
        inverso = [[r, self._datos.get(r)] for r, _v in ops]
        self._aplicar_ops_vivo(inverso, base=self._estado_datos())

    def _corregir_rechazado(self, msg: dict) -> None:
        """(host) Alguien sin permiso mandó cambios: le devuelvo lo de la
        sesión, para que su copia no quede distinta."""
        orig = msg.get("original") or {}
        sock = self.rt.socket_de(msg.get("_peer_id_origen", ""))
        if sock is None or self.guion is None:
            return
        if orig.get("tipo") == "crdt":
            # (su copia del CRDT ya tiene el cambio: que vuelva a entrar)
            self.rt.enviar_a(sock, {"tipo": "rechazo_permiso",
                                    "tipo_original": "crdt"})
        elif orig.get("tipo") == "datos":
            ops = [[r, _cifrar_datos_valor(r, self._datos.get(r), self._pin)]
                   for r, _v in (orig.get("ops") or []) if isinstance(r, str)]
            self.rt.enviar_a(sock, {"tipo": "datos", "seq": self._seq_datos,
                                    "ops": ops, "de": ""})

    # ── notas de quien solo puede comentar ──
    def mandar_nota(self, idx: int, nota: dict) -> bool:
        """(invitado con permiso de notas) La nota va al host, que la
        agrega; vuelve a todos como cualquier cambio."""
        if self.guion is None or not (0 <= idx < len(self.guion.ids)):
            return False
        self.rt.broadcast({"tipo": "agregar_nota", "bloque_id": self.guion.ids[idx],
                           "nota": dict(nota)})
        return True

    def _recibir_nota(self, msg: dict) -> None:
        if not self.rt.es_host or self.guion is None:
            return
        nota = msg.get("nota") or {}
        if not isinstance(nota, dict) or nota.get("categoria") != "nota":
            return
        self.enviar_local()
        try:
            idx = self.guion.ids.index(msg.get("bloque_id", ""))
        except ValueError:
            idx = len(self.doc.bloques) - 1
        if not (0 <= idx < len(self.doc.bloques)):
            return
        limpia = {k: v for k, v in nota.items() if not str(k).startswith("_")}
        self.doc.bloques[idx].tags.append(limpia)
        self.enviar_local()
        self.editor.viewport().update()
        self.vp._refrescar_panel_notas_si_visible()
        self.vp.statusBar().showMessage(
            f"📝 Nota de {limpia.get('autor', '?')}", 3000)

    # ── cursores ──
    def _al_mover_cursor(self) -> None:
        if self.activa and not getattr(self.editor, "_aplicando_remoto", False):
            if not self._t_cursor.isActive():
                self._t_cursor.start()

    def _enviar_cursor(self, forzar: bool = False) -> None:
        if not self.activa or self.guion is None or not self.rt.conectado:
            return
        cur = self.editor.textCursor()
        idx = cur.blockNumber()
        if not (0 <= idx < len(self.guion.ids)):
            return
        self.rt.broadcast({"tipo": "cursor", "peer_id": self.rt.peer_id_local,
                           "bloque_id": self.guion.ids[idx],
                           "offset": cur.positionInBlock()})

    def _recibir_cursor(self, msg: dict) -> None:
        pid = msg.get("peer_id") or msg.get("_peer_id_origen")
        if not pid or pid == self.rt.peer_id_local:
            return
        if self.rt.es_host:
            origen = self.rt.socket_de(msg.get("_peer_id_origen", ""))
            self.rt.broadcast(msg, excepto=origen)
        self._cursores[pid] = {"id": str(msg.get("bloque_id", "")),
                               "offset": int(msg.get("offset", 0) or 0),
                               "ts": time.monotonic()}
        self._pintar_cursores()

    def _pintar_cursores(self) -> None:
        if self.guion is None:
            self.editor.set_cursores_remotos({}, {})
            return
        pos = {bid: i for i, bid in enumerate(self.guion.ids)}
        visibles = {}
        for pid, c in self._cursores.items():
            if c["id"] in pos:
                visibles[pid] = {"idx": pos[c["id"]], "offset": c["offset"],
                                 "ts": c["ts"]}
        self.editor.set_cursores_remotos(visibles, self.rt.participantes)

    def _fade_cursores(self) -> None:
        if self._cursores:
            self.editor.viewport().update()

    def _limpiar_cursores(self) -> None:
        activos = set(self.rt.participantes.keys())
        quitar = [p for p in self._cursores if p not in activos]
        for p in quitar:
            del self._cursores[p]
        if quitar:
            self._pintar_cursores()

    # ── 🧾 la huella: ¿todas las copias son iguales? ──
    def huella(self) -> str:
        """Seis letras y números que resumen el guion y el resto del proyecto
        de esta copia: si en todos los computadores sale la misma, las copias
        son idénticas."""
        if self.guion is None:
            return ""
        if self._huella_cache[1] == self._cambios:
            return self._huella_cache[0]
        import hashlib
        h = hashlib.sha1(repr(self.guion.sombra).encode("utf-8"))
        # (el resto del proyecto, trozo por trozo, guardando el resumen de
        # cada uno: en un proyecto con muchas fotos solo se vuelve a calcular
        # el trozo que cambió)
        cache = self._hash_trozos
        for r in sorted(self._datos):
            v = self._datos[r]
            previo = cache.get(r)
            if previo is None or previo[0] is not v:
                previo = (v, hashlib.sha1(_canon_valor(v).encode("utf-8")).digest())
                cache[r] = previo
            h.update(r.encode("utf-8"))
            h.update(previo[1])
        for r in [r for r in cache if r not in self._datos]:
            del cache[r]
        texto = h.hexdigest()[:6].upper()
        self._huella_cache = (texto, self._cambios)
        return texto

    def todas_iguales(self) -> Optional[bool]:
        """True: todas las copias tienen la misma huella; False: alguna es
        distinta (o todavía se está poniendo al día); None: no se sabe."""
        activos = set(self.rt.participantes)
        hs = [h for p, h in self.huellas.items() if p in activos and h]
        if len(activos) < 2 or len(hs) < len(activos):
            return None
        return len(set(hs)) == 1

    def _mandar_huella(self) -> None:
        if not self.activa or not self.rt.conectado:
            return
        if self.puede_editar():
            self.enviar_local()
        h = self.huella()
        yo = self.rt.peer_id_local
        if self.rt.es_host:
            activos = set(self.rt.participantes)
            antes = dict(self.huellas)
            self.huellas = {p: v for p, v in self.huellas.items() if p in activos}
            self.huellas[yo] = h
            if self.huellas != antes or h != self._huella_mandada:
                self._huella_mandada = h
                self.rt.broadcast({"tipo": "huellas", "todas": dict(self.huellas)})
                self.huellas_cambiaron.emit()
        elif h != self._huella_mandada:
            self._huella_mandada = h
            self.huellas[yo] = h
            self.rt.broadcast({"tipo": "huella", "h": h})
            self.huellas_cambiaron.emit()

    def _recibir_huella(self, msg: dict) -> None:
        if msg.get("tipo") == "huella" and self.rt.es_host:
            pid = msg.get("_peer_id_origen", "")
            if pid:
                self.huellas[pid] = str(msg.get("h", ""))[:12]
                self._huella_mandada = ""     # (que salga el resumen)
                self.huellas_cambiaron.emit()
        elif msg.get("tipo") == "huellas" and not self.rt.es_host:
            todas = msg.get("todas") or {}
            if isinstance(todas, dict):
                mia = self.huellas.get(self.rt.peer_id_local, "")
                self.huellas = {str(k): str(v)[:12] for k, v in todas.items()}
                if mia:
                    self.huellas[self.rt.peer_id_local] = mia
                self.huellas_cambiaron.emit()

    # ── red de seguridad ──
    def _verificar(self) -> None:
        """(solo si llegó algo de otros desde la última vez, y después de 3 s
        sin nada nuevo: en un guion de 2.000 bloques toma una décima)"""
        if (self.guion is None or not self._por_verificar
                or time.monotonic() - self._ultimo_remoto < 3):
            return
        self._por_verificar = False
        self.enviar_local()
        if not self.guion.verificar():
            self._llevar_al_editor()


