        self.b_buscar.clicked.connect(self._buscar)
        fila_b.addWidget(self.b_buscar)
        fila_b.addStretch()
        v.addLayout(fila_b)
        self.lista = QListWidget()
        self.lista.setMaximumHeight(px(110))
