    def _tutorial_ia_integrado(self, vp) -> None:
        """Abre el tutorial de la IA (integrado); al cerrarlo, vuelve al final de esta ruta."""
        if vp is None:
            return
        t = vp.abrir_tutorial_ia()
        self.hide()

        def volver(*_):
            if self.isHidden():
                self.iniciar_ruta("ia", len(self._pasos_de("ia")) - 1)
                self.show()
                self.raise_()
        t.finished.connect(volver)

