    def _accion_hoja_limpia(self, vp) -> None:
        """Paso «Inicio de acto»: deja la hoja de PRÁCTICA limpia y
        pone «PRIMER ACTO»."""
        if hasattr(vp, "_colab_ocupado") and vp._colab_ocupado("practicar con el tutorial"):
            return
        if not preparar_guion_practica(vp, self):
            return
        doc = vp.editor.documento
        doc.escaleta = []
        doc.beats = []
        doc.bloques.clear()
        doc.bloques.append(Bloque(Elem.ACTO_INICIO, "PRIMER ACTO"))
        vp.editor.cargar_documento(doc)
        cursor = vp.editor.textCursor()
        cursor.movePosition(QTextCursor.MoveOperation.End)
        vp.editor.setTextCursor(cursor)
        self._pestaña("Inicio")(vp)

