    # ─────────────────────────────────────────────────────────────────
    # 🎥 TUTORIAL 4 · DIRECCIÓN (después de Producción)
    # ─────────────────────────────────────────────────────────────────
    def _storyboard(self, que: str = ""):
        """Abre el storyboard y deja lista la parte que explica el paso. En
        el guion de práctica, además, arma un ejemplo para verlo funcionando
        (en tu guion real no cambia nada)."""
        def _fn(vp):
            if vp is None:
                return
            doc = vp.editor.documento
            if not any(b.elem == Elem.ESCENA for b in doc.bloques):
                if not confirmar_datos_ejemplo(vp, self, "la historia de ejemplo"):
                    return
                vp._tutorial_asegurar_guion_completo()
            sb = VentanaStoryboard(vp, parent=vp)
            QTimer.singleShot(400, sb, lambda: self._preparar_storyboard(vp, sb, que))
            sb.exec()
        return _fn

    def _preparar_storyboard(self, vp, sb, que: str) -> None:
        try:
            doc = vp.editor.documento
            practica = bool(getattr(doc, "_tutorial_practica", False))
            if not sb.cuadros() and escenas_con_bloques(sb.doc.bloques):
                sb._desde_guion()
            if que == "":                          # (🎓 al presentar el storyboard: su tutorial, al lado)
                sb._tutorial_storyboard(practica)
                return
            sb._tut_preparar(que, practica)
        except Exception as e:
            print(f"[Tutorial] Storyboard ({que}): {e}")

    def _planos_con_tutorial(self):
        """🎥 Abre la lista de planos con su tutorial al lado."""
        def _fn(vp):
            if vp is None:
                return
            practica = bool(getattr(vp.editor.documento, "_tutorial_practica", False))
            w = VentanaPlanos(vp, parent=vp)
            QTimer.singleShot(400, w, lambda: w._tutorial_planos(practica))
            w.exec()
        return _fn

