_COLORES_IMPRESION = {"#1a2636": "#ffffff", "#131d2b": "#eef1f6", "#22314a": "#f4f6fa", "#3a2410": "#fff7ed",
                      "#0d1520": "#ffffff", "#0f1722": "#ffffff", "#e8edf4": "#191919", "#8fa1b8": "#5f6670",
                      "#4a5568": "#9aa3b2", "#26344a": "#c8c8c8", "#ff8c1a": "#c2410c", "#f87171": "#b91c1c"}


def html_para_imprimir(html_txt: str, poca_tinta: bool = False) -> str:
    """🖨 Un HTML pensado para la pantalla (fondo oscuro) pasado a papel: fondo
    blanco y letra oscura. Con «poca tinta», además, ningún fondo de color
    (solo texto y líneas)."""
    def fondo(m_):
        if poca_tinta:
            return m_.group(1) + "#ffffff"
        return m_.group(1) + _COLORES_IMPRESION.get(m_.group(2).lower(), m_.group(2))
    t = re.sub(r"(background(?:-color)?\s*:\s*)(#[0-9a-fA-F]{6})", fondo, html_txt or "")
    t = re.sub(r"(bgcolor\s*=\s*['\"])(#[0-9a-fA-F]{6})", fondo, t)
    def color(m_):
        c = m_.group(0).lower()
        if poca_tinta and c in ("#ff8c1a", "#f87171"):
            return "#111111"
        return _COLORES_IMPRESION.get(c, m_.group(0))
    return re.sub(r"#[0-9a-fA-F]{6}\b", color, t)


def completar_ejemplo_call_sheet(doc) -> None:
    """Los datos de ejemplo (ficticios) que muestra la Call Sheet desde la
    1.8.0: vestuario, movilidad, contacto de emergencia y el centro de salud
    de las locaciones de ejemplo. Solo en las fichas de ejemplo (correo
    @correo.example, locación «(ejemplo)») y solo lo que está vacío."""
    extra = {
        "INSPECTORA GENERAL": {"emergencia_telefono": "+56 9 0000 0005 (hermana)",
                               "vestuario": "Traje sastre gris, blusa blanca, credencial del liceo colgando."},
        "MICHELLE": {"vestuario": "Uniforme del liceo y mochila verde con parches: el mismo en todas las "
                                  "escenas (continuidad)."},
        "DIRECTOR (personaje)": {"movilidad_detalle": "Usa bastón: evitar escaleras y dejarle una silla cerca "
                                                      "del set.",
                                 "vestuario": "Chaqueta café gastada; la libreta azul siempre en el bolsillo."},
    }
    for nombre, campos in extra.items():
        f = (doc.fichas or {}).get(nombre)
        if f is None or not str(getattr(f, "actor_correo", "") or "").endswith("@correo.example"):
            continue
        for campo, valor in campos.items():
            if not str(getattr(f, campo, "") or "").strip():
                setattr(f, campo, valor)
                if campo == "movilidad_detalle":
                    f.movilidad_reducida = True
    for nombre, loc in (doc.locaciones or {}).items():
        if "(ejemplo)" in nombre and not (getattr(loc, "hospital", "") or "").strip():
            loc.hospital = "CESFAM de ejemplo · Av. Ejemplo 100 · urgencias +56 9 0000 0009 (a 5 minutos)"


# ── 🎬 Los guiones de ejemplo (1.8.9) ──
# Cinco proyectos completos (terror, comedia, ciencia ficción, drama y
# suspenso) que van con el programa, en la carpeta «Guiones de ejemplo».
# Los arma guiones_ejemplo.py al compilar. Sus fechas están escritas desde
# `ejemplo_fecha_base` y se corren al presente al abrirlos.

_MESES_LARGOS = ("enero", "febrero", "marzo", "abril", "mayo", "junio", "julio",
                 "agosto", "septiembre", "octubre", "noviembre", "diciembre")
GENEROS_EJEMPLO = (("Terror", "🕯"), ("Comedia", "😂"), ("Ciencia ficción", "🛸"),
                   ("Drama", "🎭"), ("Suspenso", "🔍"))


def _correr_fecha_iso(texto, dias: int):
    """«2026-12-05» (o «2026-12-05 10:30») corrida «dias» días; lo que no es
    una fecha queda igual."""
    s_ = str(texto or "")
    m_ = re.fullmatch(r"(\d{4}-\d{2}-\d{2})(.*)", s_.strip())
    if not m_:
        return texto
    f = _fecha_iso(m_.group(1))
    if f is None:
        return texto
    return (f + timedelta(days=dias)).isoformat() + m_.group(2)


def poner_ejemplo_al_dia(doc, hoy: Optional[date] = None) -> int:
    """🎬 Un guion de ejemplo trae sus fechas escritas desde su
    `ejemplo_fecha_base`. Al abrirlo, todas se corren las mismas semanas
    (así no cambia el día de la semana: un rodaje en sábado sigue en sábado),
    hasta que esa fecha cae en la semana de hoy: la Carta Gantt (y con ella
    la Call Sheet y el presupuesto por fechas), los pagos, los gastos, los
    contratos y seguros, la disponibilidad de las fichas, el sol del
    storyboard, las notas y la fecha de la portada. Así nunca queda atrapado
    en una fecha que ya pasó. Devuelve cuántos días se corrió (0: no es un
    ejemplo, o ya estaba al día)."""
    base = _fecha_iso(str(getattr(doc, "ejemplo_fecha_base", "") or ""))
    if base is None:
        return 0
    hoy = hoy or date.today()
    dias = 7 * round((hoy - base).days / 7)
    if dias == 0:
        return 0

    def c(t):
        return _correr_fecha_iso(t, dias)
    for j in getattr(doc, "jornadas", []) or []:
        j.fecha, j.fecha_fin = c(j.fecha), c(j.fecha_fin)
    recursos = (list((doc.fichas or {}).values()) + list((doc.locaciones or {}).values())
                + list(doc.tecnicos or []) + list(doc.equipamiento or []))
    for obj in recursos:
        disp = getattr(obj, "disponibilidad", None)
        if disp is not None:
            disp.habiles = [c(x) for x in (disp.habiles or [])]
            disp.inhabiles = [c(x) for x in (disp.inhabiles or [])]
    for v in (getattr(doc, "pagos", {}) or {}).values():
        if isinstance(v, dict) and v.get("fecha_pago"):
            v["fecha_pago"] = c(v["fecha_pago"])
    for g in getattr(doc, "gastos", []) or []:
        if isinstance(g, dict) and g.get("cuando") not in (None, "", "jornadas"):
            g["cuando"] = c(g["cuando"])
    for d in (list(getattr(doc, "documentos_legales", []) or [])
              + list((getattr(doc, "docs_meta", {}) or {}).values())):
        if isinstance(d, dict):
            for k in ("firma", "vence"):
                if d.get(k):
                    d[k] = c(d[k])
    for pl in (getattr(doc, "storyboard_plantas", {}) or {}).values():
        sol = pl.get("sol") if isinstance(pl, dict) else None
        if isinstance(sol, dict) and sol.get("fecha"):
            sol["fecha"] = c(sol["fecha"])
    for h in (getattr(doc, "storyboard_hojas", {}) or {}).values():
        if isinstance(h, dict) and h.get("fecha"):
            h["fecha"] = c(h["fecha"])
    for b in getattr(doc, "bloques", []) or []:
        for t in b.tags or []:
            if isinstance(t, dict) and t.get("fecha"):
                t["fecha"] = c(t["fecha"])
    doc.clima_cache = {}                       # (era el clima de otras fechas: se vuelve a consultar)
    nueva = base + timedelta(days=dias)
    if re.fullmatch(r"(%s) de \d{4}" % "|".join(_MESES_LARGOS),
                    str(getattr(doc, "fecha_portada", "") or "").strip().lower()):
        doc.fecha_portada = f"{_MESES_LARGOS[nueva.month - 1].capitalize()} de {nueva.year}"
    doc.ejemplo_fecha_base = nueva.isoformat()
    return dias


def carpeta_guiones_ejemplo() -> Optional[Path]:
    """La carpeta de los guiones de ejemplo: «Guiones de ejemplo» junto al
    programa instalado (o «guiones de ejemplo» junto a accion.py)."""
    base = carpeta_programa()
    for nombre in ("Guiones de ejemplo", "guiones de ejemplo"):
        c = base / nombre
        if c.is_dir():
            return c
    return None


def guiones_de_ejemplo(carpeta: Optional[Path] = None) -> list[dict]:
    """Los guiones de ejemplo, en el orden de GENEROS_EJEMPLO:
    [{ruta, genero, icono, titulo, premisa, escenas}]. El género va en el
    nombre del archivo («Terror - La sala 13.accion»)."""
    carpeta = carpeta or carpeta_guiones_ejemplo()
    if carpeta is None or not Path(carpeta).is_dir():
        return []
    orden = {g.casefold(): k for k, (g, _i) in enumerate(GENEROS_EJEMPLO)}
    iconos = {g.casefold(): i for g, i in GENEROS_EJEMPLO}
    out = []
    for f in sorted(Path(carpeta).glob("*.accion")):
        try:
            d = json.loads(f.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue
        genero, _, resto = f.stem.partition(" - ")
        if not resto:
            genero, resto = "", f.stem
        titulo = str((d.get("portada") or {}).get("titulo") or resto).strip()
        escenas = sum(1 for b in d.get("bloques", []) if int(b.get("elem", 0) or 0) == int(Elem.ESCENA))
        out.append({"ruta": f, "genero": genero.strip(), "icono": iconos.get(genero.strip().casefold(), "🎬"),
                    "titulo": titulo, "premisa": str(d.get("premisa") or "").strip(),
                    "escenas": escenas, "ejemplo": bool(d.get("ejemplo_fecha_base"))})
    out.sort(key=lambda e: (orden.get(e["genero"].casefold(), 99), e["titulo"].casefold()))
    return out


class DialogoGuionesEjemplo(QDialog):
    """🎬 Los guiones de ejemplo: cinco proyectos completos para ver (y
    probar) todo el programa. Se abre uno con «Abrir» o con doble clic; la
    ruta elegida queda en `self.ruta`."""

    def __init__(self, parent=None, carpeta: Optional[Path] = None):
        super().__init__(parent)
        self.ruta: Optional[Path] = None
        self.setWindowTitle("🎬  Guiones de ejemplo")
        self.resize(px(620), px(470))
        v = QVBoxLayout(self)
        v.setContentsMargins(px(18), px(14), px(18), px(12))
        v.setSpacing(px(8))
        tit = QLabel("🎬  Guiones de ejemplo")
        tit.setStyleSheet("font-size: 14pt; font-weight: 800; color: #ff8c1a;")
        v.addWidget(tit)
        sub = QLabel(
            "Cinco cortometrajes para grabar en un liceo, con <b>todo</b> el programa usado: el guion "
            "con sus tags, las fichas, el storyboard en 3D, la lista de planos, la Carta Gantt, la "
            "Call Sheet, el presupuesto y los contratos. Las fechas se ponen al día al abrirlos. "
            "Al guardar, eliges dónde: el ejemplo queda como estaba.")
        sub.setWordWrap(True)
        sub.setStyleSheet("color: #b0bcd2;")
        v.addWidget(sub)
        self.ejemplos = guiones_de_ejemplo(carpeta)
        self.lista = QListWidget()
        self.lista.setWordWrap(True)
        self.lista.setSpacing(px(3))
        for e in self.ejemplos:
            linea2 = e["premisa"] or f"{e['escenas']} escenas"
            it = QListWidgetItem(f"{e['icono']}  {e['genero'] or 'Ejemplo'} — {e['titulo']}\n{linea2}")
            it.setToolTip(str(e["ruta"]))
            self.lista.addItem(it)
        self.lista.itemDoubleClicked.connect(lambda _it: self._abrir())
        if self.ejemplos:
            self.lista.setCurrentRow(0)
            v.addWidget(self.lista, 1)
        else:
            no = QLabel("No encontré la carpeta «Guiones de ejemplo» junto al programa. Vuelve a "
                        "instalar ¡Acción! para tenerlos.")
            no.setWordWrap(True)
            v.addWidget(no, 1)
        fila = QHBoxLayout()
        fila.addStretch()
        b_cerrar = QPushButton("Cerrar")
        b_cerrar.clicked.connect(self.reject)
        self.b_abrir = QPushButton("📂  Abrir este ejemplo")
        self.b_abrir.setDefault(True)
        self.b_abrir.setEnabled(bool(self.ejemplos))
        self.b_abrir.clicked.connect(self._abrir)
        fila.addWidget(b_cerrar)
        fila.addWidget(self.b_abrir)
        v.addLayout(fila)

    def _abrir(self) -> None:
        k = self.lista.currentRow()
        if 0 <= k < len(self.ejemplos):
            self.ruta = self.ejemplos[k]["ruta"]
            self.accept()


