# Código telefónico de cada país de la lista (para los teléfonos escritos
# sin «+»: «9 0000 0001» en Chile → 56900000001).
PREFIJO_TELEFONO_PAIS = {
    "CL": "56", "AR": "54", "BO": "591", "BR": "55", "CO": "57", "CR": "506",
    "CU": "53", "DO": "1", "EC": "593", "SV": "503", "ES": "34", "US": "1",
    "GT": "502", "HN": "504", "MX": "52", "NI": "505", "PA": "507",
    "PY": "595", "PE": "51", "PR": "1", "UY": "598", "VE": "58", "GB": "44",
    "FR": "33", "DE": "49", "IT": "39", "PT": "351", "CA": "1", "AU": "61",
    "JP": "81", "CN": "86", "IN": "91",
}


def telefono_para_whatsapp(tel: str, pais: str = "") -> str:
    """El número como lo pide WhatsApp: solo dígitos, con el código del
    país y sin «+» («+56 9 0000 0001 (mamá)» → «56900000001»). Si está
    protegido con PIN o no parece un teléfono, devuelve «»."""
    tel = str(tel or "")
    if not tel.strip() or esta_cifrado(tel) or "🔒" in tel:
        return ""
    m_ = re.search(r"\+?\d[\d\s().\-]{5,}\d", tel)
    if not m_:
        return ""
    trozo = m_.group(0).strip()
    dig = re.sub(r"\D", "", trozo)
    if trozo.startswith("+"):
        pass
    elif dig.startswith("00"):
        dig = dig[2:]
    else:
        cod = PREFIJO_TELEFONO_PAIS.get(pais or pais_por_defecto(), "")
        if cod and not (dig.startswith(cod) and len(dig) >= len(cod) + 8):
            dig = cod + dig.lstrip("0")
    return dig if 8 <= len(dig) <= 15 else ""


def texto_para_whatsapp(texto: str) -> str:
    """La Call Sheet en texto plano, con el formato de WhatsApp: sin las
    rayas de 60 caracteres (en el celular se cortan), los títulos en
    *negrita*, sin los espacios para alinear columnas y sin sangrías
    largas."""
    out: list[str] = []
    tras_raya = False
    for ln in str(texto or "").splitlines():
        crudo = ln.rstrip()
        s = crudo.strip()
        if len(s) >= 10 and set(s) <= set("═-─"):
            tras_raya = "═" in s              # (tras la doble raya va el título)
            continue
        if not s:
            if out and out[-1] != "":
                out.append("")
            tras_raya = False
            continue
        sangria = len(crudo) - len(crudo.lstrip(" "))
        s = re.sub(r"(?<=\S) {2,}", " ", s)            # columnas → un espacio
        s = re.sub(r"^#\s+(\d+)", r"#\1", s)            # «#  1» → «#1»
        letras = [c for c in s if c.isalpha()]
        es_titulo = (sangria == 0 and len(letras) >= 3
                     and all(c.isupper() for c in letras)
                     and not s[0].isalnum())
        if es_titulo or (tras_raya and sangria <= 2 and s and s[0] != "•"):
            s = f"*{s.replace('*', '')}*"
        elif s.startswith("Generado con ¡Acción!"):
            s = f"_{s}_"
        tras_raya = False
        prefijo = "" if sangria <= 2 else ("   " if sangria <= 8 else "      ")
        out.append(prefijo + s)
    while out and out[-1] == "":
        out.pop()
    return "\n".join(out)


def enlace_whatsapp_web(texto: str, telefono: str = "") -> str:
    """Enlace que abre WhatsApp Web con el mensaje escrito: al número
    `telefono` (solo dígitos) o, sin número, para elegir el chat."""
    from urllib.parse import quote
    if telefono:
        return (f"https://web.whatsapp.com/send?phone={telefono}"
                f"&text={quote(texto, safe='')}")
    return f"https://wa.me/?text={quote(texto, safe='')}"


def abrir_enlace_externo(url: str) -> bool:
    """Abre un enlace en el navegador (las pruebas lo reemplazan)."""
    from PySide6.QtGui import QDesktopServices
    from PySide6.QtCore import QUrl
    return bool(QDesktopServices.openUrl(QUrl(url)))


