    # ═══════════════════════════════════════════════════════════
    # Generación de contenido
    # ═══════════════════════════════════════════════════════════

    def _jornada_actual(self):
        idx = self._combo_jornada.currentData()
        if idx is None or idx < 0:
            return None
        try:
            return self.doc.jornadas[idx]
        except (IndexError, TypeError):
            return None

    def _refrescar(self) -> None:
        j = self._jornada_actual()
        if j is None:
            return
        # Asunto por defecto
        titulo_proyecto = getattr(self.doc, "titulo", "") or "Rodaje"
        fecha = j.fecha or "(fecha por definir)"
        self._ed_asunto.setText(
            f"Call Sheet · {titulo_proyecto} · {fecha} · "
            f"{j.nombre or 'Jornada'}")
        # Correos
        correos = self._correos_de_jornada(j)
        self._ed_para.setText(", ".join(correos))
        # Autocompletar día X de Y
        idx = self._combo_jornada.currentData() or 0
        if not self._ed_dia_num.text():
            self._ed_dia_num.setText(str(idx + 1))
        if not self._ed_dia_total.text():
            self._ed_dia_total.setText(
                str(len(self.doc.jornadas or [])) or "1")
        # HTML — en pantalla se muestra en oscuro para no chocar
        # con la interfaz; el export (HTML/PDF/correo) sigue siendo
        # papel blanco profesional.
        html = self._html_call_sheet(j)
        oscuro = ("<style>"
                  "body { background: #131d2b !important; "
                  "color: #e8edf4 !important; } "
                  "table, td, th { border-color: #3a4665 "
                  "!important; } "
                  "</style>")
        if "</head>" in html:
            html_pantalla = html.replace("</head>",
                                         oscuro + "</head>", 1)
        else:
            html_pantalla = oscuro + html
        self._preview_html.setHtml(html_pantalla)
        # Texto plano
        self._preview_txt.setPlainText(self._texto_call_sheet(j))

    def _correos_de_jornada(self, j) -> list[str]:
        """Extrae los correos de los actores y técnicos citados."""
        correos = []
        for nombre in [a.strip() for a in (j.actores or "").split(",")
                        if a.strip()]:
            ficha = (self.doc.fichas or {}).get(nombre.upper())
            if ficha is None:
                for k, v in (self.doc.fichas or {}).items():
                    if k.upper() == nombre.upper():
                        ficha = v
                        break
            if ficha is not None:
                correo = getattr(ficha, "actor_correo", "") or ""
                if correo and not esta_cifrado(correo) and "@" in correo:
                    correos.append(correo.strip())
        for nombre in [t.strip() for t in (j.tecnicos or "").split(",")
                        if t.strip()]:
            for tec in (self.doc.tecnicos or []):
                if (tec.nombre or "").strip().upper() == nombre.upper():
                    _tel, _cor = tel_correo_de_tecnico(tec)
                    if (_cor and not esta_cifrado(_cor)
                            and "@" in _cor):
                        correos.append(_cor.strip())
                    break
        vistos = set()
        out = []
        for c in correos:
            if c.lower() not in vistos:
                out.append(c)
                vistos.add(c.lower())
        return out

    # ─── Datos auxiliares ─────

    def _datos_locacion(self, nombre: str) -> dict:
        if not nombre:
            return {}
        loc = (self.doc.locaciones or {}).get(nombre)
        if loc is None:
            for k, v in (self.doc.locaciones or {}).items():
                if k.upper() == nombre.upper():
                    loc = v
                    break
        if loc is None:
            return {}
        out = {"direccion": (getattr(loc, "ubicacion", "") or "").strip()}
        partes = []
        if getattr(loc, "ciudad", ""):
            partes.append(loc.ciudad)
        if getattr(loc, "region", ""):
            partes.append(loc.region)
        pais_cod = getattr(loc, "pais", "") or ""
        pais_dic = globals().get("PAISES", {})
        nombre_pais = pais_dic.get(pais_cod, {}).get("nombre", "") \
            if isinstance(pais_dic.get(pais_cod), dict) else pais_cod
        if nombre_pais:
            partes.append(nombre_pais)
        if partes:
            out["ubicacion"] = " · ".join(partes)
        if getattr(loc, "gps", ""):
            out["gps"] = loc.gps
        detalles = (getattr(loc, "detalles", "") or "").strip()
        if detalles:
            out["detalles"] = detalles
        hosp = (getattr(loc, "hospital", "") or "").strip()
        if hosp:
            out["hospital"] = hosp
        return out

    def _datos_actor(self, nombre_personaje: str) -> dict:
        if not nombre_personaje:
            return {}
        ficha = (self.doc.fichas or {}).get(nombre_personaje.upper())
        if ficha is None:
            for k, v in (self.doc.fichas or {}).items():
                if k.upper() == nombre_personaje.upper():
                    ficha = v
                    break
        if ficha is None:
            return {}

        def _safe(campo: str) -> str:
            valor = getattr(ficha, campo, "") or ""
            if esta_cifrado(valor):
                return "🔒 Protegido"
            return valor.strip()

        return {
            "actor_nombre": _safe("actor_nombre"),
            "actor_telefono": _safe("actor_telefono"),
            "actor_correo": _safe("actor_correo"),
            "alergias": _safe("alergias_detalle") if getattr(
                ficha, "alergias", False) else "",
            "alimentacion": getattr(ficha, "alimentacion", "") or "",
            "movilidad": (_safe("movilidad_detalle") or "Sí") if getattr(
                ficha, "movilidad_reducida", False) else "",
            "emergencia": _safe("emergencia_telefono"),
            "vestuario": _safe("vestuario"),
        }

    def _datos_tecnico(self, nombre: str) -> dict:
        for tec in (self.doc.tecnicos or []):
            if (tec.nombre or "").strip().upper() == nombre.upper():
                tel, cor = tel_correo_de_tecnico(tec)
                if esta_cifrado(tel):
                    tel = "🔒 Protegido"
                if esta_cifrado(cor):
                    cor = "🔒 Protegido"
                emer = (getattr(tec, "emergencia_telefono", "") or "").strip()
                if esta_cifrado(emer):
                    emer = "🔒 Protegido"
                return {
                    "rol": getattr(tec, "rol", "") or "",
                    "telefono": tel,
                    "correo": cor,
                    "contacto": " · ".join(x for x in (tel, cor) if x),
                    "alimentacion": getattr(tec, "alimentacion", "")
                                     or "",
                    "emergencia": emer,
                }
        return {}

    def _datos_escenas(self, escenas_txt: str) -> list:
        try:
            nums = [int(s.strip()) for s in escenas_txt.split(",")
                    if s.strip().isdigit()]
        except ValueError:
            return []
        escenas = segmentar_escenas(self.doc)
        by_num = {e["numero"]: e for e in escenas}
        salida = []
        for n in nums:
            e = by_num.get(n)
            if not e:
                continue
            resumen = ""
            for i_b in range(e["idx_inicio"] + 1, e["idx_fin"]):
                b = self.doc.bloques[i_b]
                if b.elem == Elem.ACCION and (b.texto or "").strip():
                    resumen = (b.texto or "").strip()[:100]
                    if len(b.texto) > 100:
                        resumen += "…"
                    break
            enc = e["encabezado"] or ""
            # Extraer INT/EXT y momento del día
            ie = ""
            momento = ""
            import re as _re
            m = _re.match(
                r"^(INT\./?EXT\.|INT\.|EXT\.|I/E\.)\s+(.+?)"
                r"(?:\s*-\s*(.+))?$",
                enc.upper().strip())
            if m:
                ie = m.group(1).replace(".", "").replace("/", "/")
                setting = m.group(2).strip()
                momento = (m.group(3) or "").strip()
                dn = "D" if any(w in momento for w in
                                ("DÍA", "DIA", "MAÑANA", "TARDE",
                                 "AMANECER", "MEDIODÍA", "ATARDECER"))\
                    else ("N" if any(w in momento for w in
                                     ("NOCHE",)) else "")
            else:
                setting = enc
                dn = ""
            salida.append({
                "num": n,
                "encabezado": enc,
                "ie": ie,
                "setting": setting,
                "dn": dn,
                "momento": momento,
                "resumen": resumen,
                "personajes": e["personajes"],
                "lineas": lineas_de_bloques(self.doc.bloques[e["idx_inicio"]:e["idx_fin"]]),
                "planos": cuadros_ordenados(self.doc, {n}),
            })
        return salida

    def _clima_de_jornada(self, j) -> dict:
        if not j.fecha or not j.lugar:
            return {}
        cache = getattr(self.doc, "clima_cache", {}) or {}
        loc = (self.doc.locaciones or {}).get(j.lugar)
        if loc is None:
            for k, v in (self.doc.locaciones or {}).items():
                if k.upper() == j.lugar.upper():
                    loc = v
                    break
        if loc is None or not getattr(loc, "gps", ""):
            return {}
        clave = f"{loc.gps}|{j.fecha}"
        return cache.get(clave, {}) or {}

