    def keyPressEvent(self, event) -> None:
        # Suprimir / Backspace elimina la jornada seleccionada
        if event.key() in (Qt.Key.Key_Delete, Qt.Key.Key_Backspace):
            self._eliminar_jornada()
            return
        super().keyPressEvent(event)

    # ─── Helpers de cobertura ───────────────────────────────────────

    def _refrescar(self) -> None:
        self._canvas.set_jornadas(self.documento.jornadas)
        self._actualizar_escenas()
        self._revisar_conflictos(avisar=False)
        self._actualizar_costo_total()

    # ─── Zoom del canvas (NO afecta resto de la UI) ─────────────────

    def _zoom_canvas(self, factor: float) -> None:
        z = self._canvas.get_zoom() * factor
        self._canvas.set_zoom(z)
        self._lbl_zoom.setText(f"{int(self._canvas.get_zoom() * 100)}%")

    def _zoom_reset(self) -> None:
        self._canvas.set_zoom(1.0)
        self._lbl_zoom.setText("100%")

    # ─── Costo total del proyecto ───────────────────────────────────

    def _actualizar_costo_total(self) -> None:
        """Suma precio_dia × días de cada recurso en jornadas.

        Locaciones: cuenta lugar Y lugar_2 (ambos cobran).
        Actores: desde Ficha.actor_valor_dia.
        Técnicos: desde Tecnico.precio_dia.
        Equipamiento: desde Equipamiento.precio_dia.
        """
        jornadas = self.documento.jornadas
        total_loc = 0
        total_act = 0
        total_tec = 0
        total_eq  = 0

        for nombre, loc in self.documento.locaciones.items():
            d = dias_de_recurso_en_jornadas(nombre, "locacion", jornadas)
            total_loc += int(costo_dia_recurso(loc) * d)

        for nombre, ficha in self.documento.fichas.items():
            d = dias_de_recurso_en_jornadas(nombre, "actor", jornadas)
            total_act += int(costo_dia_recurso(
                ficha, "actor_valor_dia") * d)

        for t in self.documento.tecnicos:
            d = dias_de_recurso_en_jornadas(t.nombre, "tecnico", jornadas)
            total_tec += int(costo_dia_recurso(t) * d)

        for e in self.documento.equipamiento:
            d = dias_de_recurso_en_jornadas(e.nombre, "equipamiento", jornadas)
            total_eq += int(costo_dia_recurso(e) * d)

        # ── Costos de TAGS del guion (utilería, vestuario, etc.
        # con valor asignado)
        info_tags = calcular_costo_tags_totales(self.documento)
        total_tags = info_tags["total"]

        total = total_loc + total_act + total_tec + total_eq + total_tags
        self._lbl_costo_total.setText(fmt_clp(total))
        desglose = (
            f"📍 {fmt_clp(total_loc)}   🎭 {fmt_clp(total_act)}   "
            f"🔧 {fmt_clp(total_tec)}   🎥 {fmt_clp(total_eq)}   "
            f"🏷 {fmt_clp(total_tags)}"
        )
        self._lbl_costo_desglose.setText(desglose)
        # El 💰 Presupuesto suma además los gastos a mano y los
        # documentos con monto (seguros, permisos…): se indica aquí.
        try:
            completo = sum(l["total"] for l in lineas_presupuesto(self.documento))
        except Exception:
            completo = total
        con_iva = bool(config_iva(self.documento)[0])
        self._lbl_costo_total.setToolTip(
            "Costo de rodaje: valor por día (+ transporte y alimentación) "
            "× días en la Carta Gantt, más los tags con valor"
            + (", tal como se escribieron (sin sumar ni separar el IVA)." if con_iva else ".")
            + (f"\n\n💰 Presupuesto completo (con gastos y documentos"
               + (" e IVA" if con_iva else "") + f"): {fmt_clp(completo)}"
               if abs(completo - total) > 0.5 else ""))

    def _actualizar_escenas(self) -> None:
        self._lista_escenas.clear()
        escenas = _escenas_del_documento(self.documento)
        asignadas: set[int] = set()
        ubic: dict[int, list[tuple[str, str]]] = {}
        for j in self.documento.jornadas:
            for n in _escenas_de_jornada(j):
                asignadas.add(n)
                ubic.setdefault(n, []).append(
                    (j.fecha or "?", j.lugar or j.nombre or "?"))

        faltan = 0
        for n, enc in escenas:
            corto = enc[:32]
            cubierta = n in asignadas
            if cubierta:
                it = QListWidgetItem(f"✓ #{n} {corto}")
                it.setForeground(QColor("#7ee787"))
                it.setData(Qt.ItemDataRole.UserRole, n)
                self._lista_escenas.addItem(it)
                for f, l in ubic.get(n, []):
                    sub = QListWidgetItem(f"    {f} · {l}")
                    sub.setForeground(QColor("#9ad0ff"))
                    self._lista_escenas.addItem(sub)
            else:
                faltan += 1
                it = QListWidgetItem(f"✗ #{n} {corto}")
                it.setForeground(QColor("#ff9a9a"))
                it.setData(Qt.ItemDataRole.UserRole, n)
                self._lista_escenas.addItem(it)

        total = len(escenas)
        self._lbl_resumen.setText(
            f"{total - faltan}/{total} escenas cubiertas · faltan {faltan}"
        )

    # ─── Conflictos: mismas fechas con misma locación/actor/etc. ────

    def _revisar_conflictos(self, avisar: bool = False) -> None:
        """Detecta:
          (A) Solapamientos cruzados: el mismo actor / locación / técnico /
              equipamiento citado en dos jornadas con fechas que se solapan.
          (B) Disponibilidad declarada: cada recurso vs su calendario
              de inhábiles (días marcados como NO disponibles).
        """
        conflictos: set[int] = set()
        mensajes: list[str] = []
        # Motivos POR JORNADA (para tooltips en el canvas).
        motivos_por_j: dict[int, list[str]] = {}

        def _anota(idx: int, motivo: str) -> None:
            motivos_por_j.setdefault(idx, []).append(motivo)

        # ── (A) Solapamientos cruzados entre jornadas ────────────────
        js = list(enumerate(self.documento.jornadas))
        for i in range(len(js)):
            ai, ja = js[i]
            fa0 = _fecha_iso(ja.fecha)
            fa1 = _fecha_iso(ja.fecha_fin) or fa0
            if not fa0:
                continue
            actores_a = set(_parse_csv_nombres(ja.actores))
            tec_a     = set(_parse_csv_nombres(ja.tecnicos))
            eq_a      = set(_parse_csv_nombres(ja.equipamiento))
            lugar_a   = ja.lugar.strip().upper() if ja.lugar else ""

            for k in range(i + 1, len(js)):
                bi, jb = js[k]
                fb0 = _fecha_iso(jb.fecha)
                fb1 = _fecha_iso(jb.fecha_fin) or fb0
                if not fb0:
                    continue
                if fa1 < fb0 or fb1 < fa0:
                    continue   # no se solapan

                actores_comp = actores_a & set(_parse_csv_nombres(jb.actores))
                tec_comp     = tec_a     & set(_parse_csv_nombres(jb.tecnicos))
                eq_comp      = eq_a      & set(_parse_csv_nombres(jb.equipamiento))
                lugar_b      = jb.lugar.strip().upper() if jb.lugar else ""
                misma_loc    = lugar_a and lugar_a == lugar_b

                if actores_comp or tec_comp or eq_comp or misma_loc:
                    conflictos.add(ai); conflictos.add(bi)
                    razones = []
                    if actores_comp:
                        razones.append(
                            f"🎭 actor(es) {', '.join(sorted(actores_comp))}"
                        )
                    if misma_loc:
                        razones.append(f"📍 locación «{ja.lugar}»")
                    if tec_comp:
                        razones.append(
                            f"🔧 técnico(s) {', '.join(sorted(tec_comp))}"
                        )
                    if eq_comp:
                        razones.append(
                            f"🎥 equipo {', '.join(sorted(eq_comp))}"
                        )
                    mensajes.append(
                        f"⚠ «{ja.nombre or '?'}» y «{jb.nombre or '?'}» "
                        f"se topan en fecha:\n   " + " · ".join(razones)
                    )
                    # Tooltip-friendly: anotar el motivo en cada jornada
                    for raz in razones:
                        _anota(ai, f"{raz} — choque con «{jb.nombre or '?'}»")
                        _anota(bi, f"{raz} — choque con «{ja.nombre or '?'}»")

        # ── (B) Disponibilidad declarada vs fechas de cada jornada ───
        for idx, j in enumerate(self.documento.jornadas):
            f0 = _fecha_iso(j.fecha)
            f1 = _fecha_iso(j.fecha_fin) or f0
            if not f0:
                continue
            fechas_iso = _rango_dias(f0, f1)

            # Actores
            for actor in _parse_csv_nombres(j.actores):
                ficha = self.documento.fichas.get(actor)
                if ficha and ficha.disponibilidad:
                    choque = _esta_inhabil(ficha.disponibilidad, fechas_iso)
                    if choque:
                        conflictos.add(idx)
                        msg = (f"🎭 «{actor}» tiene marcado como NO disponible "
                               f"en «{j.nombre or 'jornada'}»: "
                               f"{', '.join(choque[:3])}"
                               + (" …" if len(choque) > 3 else ""))
                        mensajes.append(msg)
                        _anota(idx, f"🎭 «{actor}» NO disponible "
                                    f"({', '.join(choque[:3])})")

            # Locación
            if j.lugar:
                loc = self.documento.locaciones.get(j.lugar)
                if loc and loc.disponibilidad:
                    choque = _esta_inhabil(loc.disponibilidad, fechas_iso)
                    if choque:
                        conflictos.add(idx)
                        msg = (f"📍 Locación «{j.lugar}» NO disponible "
                               f"en «{j.nombre or 'jornada'}»: "
                               f"{', '.join(choque[:3])}"
                               + (" …" if len(choque) > 3 else ""))
                        mensajes.append(msg)
                        _anota(idx, f"📍 Locación «{j.lugar}» NO disponible "
                                    f"({', '.join(choque[:3])})")

            # Técnicos
            for tec in _parse_csv_nombres(j.tecnicos):
                t_obj = next((t for t in self.documento.tecnicos
                              if t.nombre.strip().upper() == tec), None)
                if t_obj and t_obj.disponibilidad:
                    choque = _esta_inhabil(t_obj.disponibilidad, fechas_iso)
                    if choque:
                        conflictos.add(idx)
                        mensajes.append(
                            f"🔧 Técnico «{tec}» NO disponible "
                            f"en «{j.nombre or 'jornada'}»"
                        )
                        _anota(idx, f"🔧 Técnico «{tec}» NO disponible")

            # Equipamiento
            for eq in _parse_csv_nombres(j.equipamiento):
                e_obj = next((e for e in self.documento.equipamiento
                              if e.nombre.strip().upper() == eq), None)
                if e_obj and e_obj.disponibilidad:
                    choque = _esta_inhabil(e_obj.disponibilidad, fechas_iso)
                    if choque:
                        conflictos.add(idx)
                        mensajes.append(
                            f"🎥 Equipamiento «{eq}» NO disponible "
                            f"en «{j.nombre or 'jornada'}»"
                        )
                        _anota(idx, f"🎥 Equipamiento «{eq}» NO disponible")

        self._canvas.set_conflictos(conflictos, motivos_por_j)
        if avisar:
            if conflictos:
                dlg = QMessageBox(self)
                dlg.setIcon(QMessageBox.Icon.Warning)
                dlg.setWindowTitle("Conflictos detectados")
                dlg.setText(
                    f"Se detectaron {len(mensajes)} problema(s):\n\n"
                    + "\n\n".join(mensajes[:10])
                    + ("\n\n…" if len(mensajes) > 10 else "")
                    + "\n\nLas jornadas afectadas están marcadas en "
                      "rojo en la barra de tiempo.")
                dlg.setStyleSheet("""
                    QMessageBox { background: #1e1e28; }
                    QMessageBox QLabel {
                        color: #f0f0f5;
                        background: transparent;
                        font-size: 10pt;
                    }
                    QMessageBox QPushButton {
                        background: #2a3548; color: #e8edf4;
                        padding: 6px 18px;
                        border: 1px solid #3d4863;
                        border-radius: 4px; min-width: 70px;
                    }
                    QMessageBox QPushButton:hover {
                        background: #3d6df2;
                    }
                """)
                dlg.exec()
            else:
                dlg = QMessageBox(self)
                dlg.setIcon(QMessageBox.Icon.Information)
                dlg.setWindowTitle("Sin conflictos")
                dlg.setText(
                    "¡Todo en orden! 🎬\n\nNingún recurso (actor, "
                    "locación, técnico, equipamiento) está "
                    "sobreasignado ni cae en días marcados como no "
                    "disponibles.")
                dlg.setStyleSheet("""
                    QMessageBox { background: #1e1e28; }
                    QMessageBox QLabel {
                        color: #f0f0f5;
                        background: transparent;
                        font-size: 10pt;
                    }
                    QMessageBox QPushButton {
                        background: #2a3548; color: #e8edf4;
                        padding: 6px 18px;
                        border: 1px solid #3d4863;
                        border-radius: 4px; min-width: 70px;
                    }
                    QMessageBox QPushButton:hover {
                        background: #3d6df2;
                    }
                """)
                dlg.exec()

    # ─── Acciones de jornada ────────────────────────────────────────

    def _nueva_jornada(self) -> None:
        j = Jornada(nombre=f"Jornada {len(self.documento.jornadas) + 1}")
        self.documento.jornadas.append(j)
        self._sel_idx = len(self.documento.jornadas) - 1
        if self._editar_jornada(self._sel_idx):
            self._refrescar()
            self.gantt_cambiada.emit()
        else:
            self.documento.jornadas.pop()  # canceló: deshacer

    def _editar_jornada_seleccionada(self) -> None:
        if self._sel_idx is None:
            QMessageBox.information(self, "Editar",
                                    "Selecciona primero una jornada en la barra.")
            return
        if self._editar_jornada(self._sel_idx):
            self._refrescar()
            self.gantt_cambiada.emit()

    def _editar_jornada(self, idx: int, hablantes: Optional[list] = None) -> bool:
        if not (0 <= idx < len(self.documento.jornadas)):
            return False
        j = self.documento.jornadas[idx]
        dlg = DialogoEditarJornada(j, self.documento, parent=self, hablantes=hablantes)
        return dlg.exec() == QDialog.DialogCode.Accepted

    def _eliminar_jornada(self) -> None:
        if self._sel_idx is None:
            return
        j = self.documento.jornadas[self._sel_idx]
        r = QMessageBox.question(
            self, "Eliminar jornada",
            f"¿Eliminar «{j.nombre or 'jornada sin nombre'}»?",
        )
        if r == QMessageBox.StandardButton.Yes:
            self.documento.jornadas.pop(self._sel_idx)
            self._sel_idx = None
            self._refrescar()
            self.gantt_cambiada.emit()

    def _on_jornada_sel(self, idx: int) -> None:
        self._sel_idx = idx
        self._canvas.set_seleccion(idx)
        self._actualizar_clima_seleccion()

    def _refrescar_clima_forzado(self) -> None:
        """Invalida el cache de clima de la jornada seleccionada y
        vuelve a consultar la API. Útil cuando se acerca el día y
        quieres el pronóstico más actualizado."""
        if (self._sel_idx is None
                or not (0 <= self._sel_idx < len(self.documento.jornadas))):
            self._lbl_clima.setText(
                "Seleccioná primero una jornada para refrescar el clima")
            return
        j = self.documento.jornadas[self._sel_idx]
        if not j.fecha:
            return
        locs = getattr(self.documento, "locaciones", {}) or {}
        loc = locs.get((j.lugar or "").strip())
        if loc is None:
            return
        # Forzar refresh
        self._lbl_clima.setText("🌐 Consultando Open-Meteo…")
        self._lbl_clima_adv.setText("")
        QApplication.processEvents()
        clima = obtener_clima_con_cache(
            self.documento, loc, j.fecha, forzar_refresh=True)
        if clima is None:
            self._lbl_clima.setText(
                "❌ No se pudo consultar el clima. Verifica conexión.")
        else:
            self._actualizar_clima_seleccion()

    def _actualizar_clima_seleccion(self) -> None:
        """Actualiza el footer de clima para la jornada seleccionada.
        Si no hay región/ciudad en la locación o no hay conexión,
        muestra un mensaje informativo. Puede consultar Open-Meteo
        (con timeout corto) — se corre en el hilo principal para
        simplicidad; el timeout de 6s protege contra bloqueos."""
        if (self._sel_idx is None
                or not (0 <= self._sel_idx < len(self.documento.jornadas))):
            self._lbl_clima.setText(
                "Seleccioná una jornada para ver el pronóstico")
            self._lbl_clima_adv.setText("")
            return
        j = self.documento.jornadas[self._sel_idx]
        if not j.fecha:
            self._lbl_clima.setText(
                "La jornada no tiene fecha; no se puede consultar clima")
            self._lbl_clima_adv.setText("")
            return
        locs = getattr(self.documento, "locaciones", {}) or {}
        loc = locs.get((j.lugar or "").strip())
        if loc is None:
            self._lbl_clima.setText(
                "Sin locación asociada; no se puede consultar clima")
            self._lbl_clima_adv.setText("")
            return
        reg = getattr(loc, "region", "") or ""
        ciu = getattr(loc, "ciudad", "") or ""
        if not reg or not ciu:
            self._lbl_clima.setText(
                f"Locación «{loc.nombre}» sin región/ciudad. "
                "Edita la locación y elige una para ver el clima.")
            self._lbl_clima_adv.setText("")
            return
        clima = obtener_clima_con_cache(self.documento, loc, j.fecha)
        if clima is None:
            self._lbl_clima.setText(
                "🌐 No se pudo consultar el clima (sin conexión o "
                "fecha fuera de rango: hasta 16 días adelante)")
            self._lbl_clima_adv.setText("")
            return
        emoji, desc = clima_descripcion(int(clima.get("codigo", 0)))
        tmax = clima.get("temp_max")
        tmin = clima.get("temp_min")
        temp_str = ""
        try:
            if tmax is not None and tmin is not None:
                temp_str = (f"  {int(round(float(tmax)))}°C / "
                           f"{int(round(float(tmin)))}°C")
        except (ValueError, TypeError):
            pass
        prob = clima.get("prob_lluvia", 0)
        try:
            p = int(float(prob or 0))
            if p > 0:
                temp_str += f"  ·  💧 {p}% lluvia"
        except (ValueError, TypeError):
            pass
        self._lbl_clima.setText(
            f"{emoji} {desc}{temp_str}  ·  "
            f"{ciu}, {reg}  ({j.fecha})")

        advs = clima_advertencias(clima)
        if advs:
            # Mostrar advertencias resumidas
            self._lbl_clima_adv.setText(
                "⚠ " + " · ".join(advs)[:200])
        else:
            self._lbl_clima_adv.setText("")

    def _on_jornada_movida(self, _idx: int) -> None:
        self._refrescar()
        self._actualizar_clima_seleccion()

    def _on_jornada_doble(self, idx: int) -> None:
        self._sel_idx = idx
        if self._editar_jornada(idx):
            self._refrescar()

    def _on_doble_click_escena(self, item: QListWidgetItem) -> None:
        n = item.data(Qt.ItemDataRole.UserRole)
        if n is None:
            return
        # Buscar locación de esa escena
        lugar = ""
        for ne, enc in _escenas_del_documento(self.documento):
            if ne == n:
                lugar = _locacion_desde_encabezado(enc)
                break
        j = Jornada(
            nombre=f"Jornada {len(self.documento.jornadas) + 1}",
            lugar=lugar,
            escenas=str(n),
        )
        nuevos_pj = completar_actores_de_jornada(self.documento, j)   # (quienes hablan, de inmediato)
        self.documento.jornadas.append(j)
        self._sel_idx = len(self.documento.jornadas) - 1
        if self._editar_jornada(self._sel_idx, hablantes=nuevos_pj):
            self._refrescar()
            self.gantt_cambiada.emit()
        else:
            self.documento.jornadas.pop()
            for p in nuevos_pj:                    # (canceló: tampoco quedan sus fichas vacías)
                f = self.documento.fichas.get(p)
                if f is not None and not (f.actor_nombre or f.actor_valor_dia or f.biografia):
                    del self.documento.fichas[p]

    # ─── Generación automática de plan ──────────────────────────────

    def _generar_automatico(self) -> None:
        escenas = _escenas_del_documento(self.documento)
        if not escenas:
            # Sin escenas: igual se arma el calendario (jornadas vacías)
            nuevas = preguntar_jornadas_vacias(self, self.documento)
            if nuevas:
                self.documento.jornadas = nuevas
                self._refrescar()
            return
        if self.documento.jornadas:
            r = QMessageBox.question(
                self, "Plan automático",
                "Esto reemplazará las jornadas actuales por un plan "
                "nuevo generado desde las escenas del guion.\n\n¿Continuar?",
            )
            if r != QMessageBox.StandardButton.Yes:
                return

        por_dia, ok = QInputDialog.getInt(
            self, "Plan automático",
            "¿Cuántas escenas filmarás por día (aprox.)?",
            value=4, minValue=1, maxValue=20,
        )
        if not ok:
            return

        hoy = date.today()
        inicio_str, ok = QInputDialog.getText(
            self, "Plan automático",
            "Fecha de inicio del rodaje (YYYY-MM-DD):",
            text=(hoy + timedelta(days=7)).isoformat(),
        )
        if not ok:
            return
        fecha = _fecha_iso(inicio_str.strip())
        if not fecha:
            QMessageBox.warning(self, "Fecha", "Fecha inválida.")
            return

        # Agrupar escenas por locación (cumple regla de rodaje: filmar juntas)
        grupos: dict[str, list[int]] = {}
        orden_loc: list[str] = []
        for num, enc in escenas:
            loc = _locacion_desde_encabezado(enc)
            if loc not in grupos:
                grupos[loc] = []
                orden_loc.append(loc)
            grupos[loc].append(num)

        def sig_habil(f: date) -> date:
            while f.weekday() >= 5:    # 5=sáb, 6=dom
                f += timedelta(days=1)
            return f

        nuevas: list[Jornada] = []
        njornada = 0
        for loc in orden_loc:
            nums = grupos[loc]
            for k in range(0, len(nums), por_dia):
                bloque = nums[k:k + por_dia]
                fecha = sig_habil(fecha)
                njornada += 1
                nuevas.append(Jornada(
                    nombre=f"Jornada {njornada} — {loc.title()[:24]}",
                    fecha=fecha.isoformat(),
                    fecha_fin=fecha.isoformat(),
                    lugar=loc.title(),
                    hora_citacion="08:00",
                    escenas=", ".join(str(n) for n in bloque),
                ))
                completar_actores_de_jornada(self.documento, nuevas[-1])
                fecha += timedelta(days=1)

        self.documento.jornadas = nuevas
        self._refrescar()
        self.gantt_cambiada.emit()
        QMessageBox.information(
            self, "Plan generado",
            f"Se crearon {len(nuevas)} jornadas a partir de {len(escenas)} "
            f"escenas, agrupadas por locación, desde "
            f"{nuevas[0].fecha if nuevas else '—'} (saltando fines de semana).\n\n"
            f"Puedes arrastrar las barras en el timeline para ajustar fechas.",
        )

