    # ⚡ La tarjeta gráfica para el Profesor Claqueta
    def _pintar_gpu_ia(self) -> None:
        try:
            self._pintar_gpu_ia_()
        except RuntimeError:                      # (el diálogo ya se cerró)
            pass

    def _pintar_gpu_ia_(self) -> None:
        est = estado_gpu_ia()
        self._caja_gpu.setVisible(bool(est["hay"]))
        for b_ in (self._b_gpu_bajar, self._b_gpu_pausa, self._b_gpu_usar, self._b_gpu_nvidia, self._b_gpu_probar):
            b_.setVisible(False)
        if not est["hay"]:
            return
        g = getattr(self._vp, "_descarga_ia", None)
        gris = "<span style='color:#94a3b8;font-size:9pt;'>{}</span>"
        nombre = html.escape(est["nombre"])
        vulkan = est["via"] == "vulkan"
        para = "para NVIDIA" if not vulkan else "para tu tarjeta (Vulkan)"
        aviso = ""                                # (una NVIDIA con un controlador antiguo para CUDA)
        if est["fabricante"] == "nvidia" and not est["driver_ok"]:
            aviso = ("<span style='color:#f59e0b;font-weight:bold;'>⚠ El controlador de la tarjeta es antiguo</span>"
                     "<br>" + gris.format(f"Versión {html.escape(est['driver'] or '¿?')}: la parte de NVIDIA de "
                                          f"Ollama (la más rápida) necesita la {est['minimo']} o más nueva. "
                                          "Actualízalo con la aplicación de NVIDIA o en nvidia.com/drivers. "
                                          "Mientras, se prueba con Vulkan.") + "<br>")
            self._b_gpu_nvidia.setVisible(True)
        if not self._chk_gpu_ia.isChecked():
            txt = gris.format(f"Apagado: el Profesor Claqueta usa solo el procesador, y tu {nombre} queda libre "
                              "(para editar video o jugar mientras tanto, por ejemplo).")
            aviso = ""
            self._b_gpu_nvidia.setVisible(False)
        elif g is not None and g.estado_gpu in ("descargando", "pausado"):
            pausa = g.estado_gpu == "pausado"
            txt = (f"<span style='color:#f59e0b;font-weight:bold;'>⬇ {'En pausa' if pausa else 'Preparando'} la "
                   f"parte {para} · {int(g.fraccion_gpu * 100)} %</span><br>"
                   + gris.format("Se baja de a poco, sin ocupar toda tu conexión. Si cierras ¡Acción!, sigue la "
                                 "próxima vez."))
            self._b_gpu_pausa.setText("▶  Seguir" if pausa else "⏸  Pausar")
            self._b_gpu_pausa.setVisible(True)
        elif g is not None and g.hilo_prueba is not None:
            txt = ("<span style='color:#f59e0b;font-weight:bold;'>⏱ Probando si tu tarjeta acelera…</span><br>"
                   + gris.format("Le pide lo mismo a la tarjeta y al procesador, y se queda con el más rápido. "
                                 "Toma un par de minutos."))
        elif runtime_ia_trae_cuda() or ollama_gpu_listo(est["via"]):
            abierta_cpu = bool(_PROCESO_IA) and _PROCESO_IA[0].poll() is None and \
                not (_PROCESO_IA_GPU and _PROCESO_IA_GPU[0])
            p_ = prueba_gpu_ia() if vulkan else {"usar": True}
            if gpu_ia_fallo_vigente():
                txt = ("<span style='color:#f59e0b;font-weight:bold;'>⚠ La última vez, la IA no abrió con la "
                       "tarjeta</span><br>" + gris.format("El Profesor Claqueta siguió con el procesador. Puedes "
                                                          "probar de nuevo (por ejemplo, después de actualizar el "
                                                          "controlador de la tarjeta)."))
                b_ = self._b_gpu_probar if vulkan else self._b_gpu_usar
                b_.setText("⚡  Probar de nuevo")
                b_.setVisible(True)
            elif p_ is None:
                txt = (f"<span style='color:#cbd5e1;font-weight:bold;'>Falta probar si tu {nombre} acelera"
                       "</span><br>" + gris.format("Se prueba sola, en segundo plano, cuando la IA no está "
                                                   "conversando. O ahora, con el botón."))
                self._b_gpu_probar.setText("⏱  Probar ahora")
                self._b_gpu_probar.setVisible(True)
            elif not p_.get("usar"):
                medido = (f" (para una respuesta típica: procesador {_seg(p_.get('cpu_s'))}, tarjeta "
                          f"{_seg(p_.get('gpu_s'))})" if p_.get("cpu_s") else "")
                txt = (f"<span style='color:#cbd5e1;font-weight:bold;'>Tu {nombre} no acelera en este computador"
                       "</span><br>" + gris.format(f"En la prueba, el procesador fue igual de rápido o más{medido}: "
                                                   "el Profesor Claqueta sigue con el procesador."))
                self._b_gpu_probar.setText("⏱  Probar de nuevo")
                self._b_gpu_probar.setVisible(True)
            elif abierta_cpu:
                txt = ("<span style='color:#16a34a;font-weight:bold;'>✓ Lista</span><br>"
                       + gris.format(f"Tu {nombre} se usa desde la próxima vez que se abra la IA (o ahora, con el "
                                     "botón)." + (f" En la prueba fue {_veces(p_)} más rápida que el procesador."
                                                  if vulkan else "")))
                self._b_gpu_usar.setText("⚡  Usar la tarjeta ahora")
                self._b_gpu_usar.setVisible(True)
            else:
                detalle = (f"Con Vulkan: en la prueba, {_veces(p_)} más rápida que el procesador." if vulkan
                           else f"Controlador {html.escape(est['driver'])}.")
                txt = (f"<span style='color:#16a34a;font-weight:bold;'>✓ El Profesor Claqueta usa tu {nombre}</span>"
                       "<br>" + gris.format(detalle + " En su ventana, junto al modelo, dice cuánto queda en la "
                                                      "tarjeta."))
        elif carpeta_ia_incluida() is None:
            txt = gris.format(f"Tu {nombre} puede ayudar. Cuando el Profesor Claqueta tenga su IA, se prepara también "
                              "la parte para ella. Un Ollama instalado aparte ya la trae.")
        else:
            error = (g.error_gpu if g is not None and g.estado_gpu == "error" else "")
            peso = ("unos 12 MB" if vulkan else ("unos 650 MB" if est["cuda"] == "v13" else "unos 950 MB"))
            despues = " Después se prueba si acelera." if vulkan else ""
            txt = (f"<span style='color:#cbd5e1;font-weight:bold;'>Tu {nombre} puede ayudar, pero todavía no se usa"
                   "</span><br>" + gris.format(f"Falta bajar la parte de Ollama {para} ({peso}, una sola vez)."
                                               + despues + (f" No se pudo la última vez: {html.escape(error)}."
                                                            if error else "")))
            self._b_gpu_bajar.setVisible(True)
        self._lbl_gpu_ia.setText(aviso + txt)

    def _cambiar_gpu_ia(self, si: bool) -> None:
        settings_app().setValue(CLAVE_IA_GPU, bool(si))
        g = getattr(self._vp, "_descarga_ia", None)
        abierta = bool(_PROCESO_IA) and _PROCESO_IA[0].poll() is None
        if not si:
            if g is not None and g.hilo_gpu is not None:
                g.pausar_gpu(True)
            if abierta:
                detener_ia_incluida()             # (se vuelve a abrir sola, con el procesador)
        elif g is not None:
            if g.hilo_gpu is not None:
                g.pausar_gpu(False)
            elif ollama_gpu_listo() or runtime_ia_trae_cuda():
                if abierta:
                    g.usar_gpu_ahora()
                g.quizas_probar_gpu()                 # (⏱ con Vulkan, si falta probarla)
            else:
                g.quizas_gpu()
        if abierta and not (bool(_PROCESO_IA) and _PROCESO_IA[0].poll() is None):
            a = getattr(self._vp, "_asesor", None)          # (se cerró: la vuelve a abrir, ya con lo elegido)
            if a is not None:
                QTimer.singleShot(300, a.refrescar)
        self._pintar_gpu_ia()
        self._toast("✓ Usa la tarjeta gráfica" if si else "✓ Usa solo el procesador")

    def _gpu_preparar(self) -> None:
        settings_app().setValue(CLAVE_IA_GPU, True)
        g = getattr(self._vp, "_descarga_ia", None)
        if g is not None and g.quizas_gpu(forzar=True):
            self._toast("⬇ Preparando la tarjeta gráfica en segundo plano")
        else:
            self._toast("No se pudo: " + ((g.error_gpu if g is not None else "") or "inténtalo más tarde"))
        self._pintar_gpu_ia()

    def _gpu_probar(self) -> None:
        g = getattr(self._vp, "_descarga_ia", None)
        if g is not None and g.quizas_probar_gpu(forzar=True):
            self._toast("⏱ Probando la tarjeta en segundo plano")
        self._pintar_gpu_ia()

    def _gpu_pausar(self) -> None:
        g = getattr(self._vp, "_descarga_ia", None)
        if g is not None:
            g.pausar_gpu(g.estado_gpu != "pausado")
        self._pintar_gpu_ia()

    def _gpu_usar_ahora(self) -> None:
        g = getattr(self._vp, "_descarga_ia", None)
        if g is not None and g.usar_gpu_ahora():
            self._toast("⚡ El Profesor Claqueta vuelve a abrir su IA, ya con la tarjeta")
            a = getattr(self._vp, "_asesor", None)
            if a is not None:
                QTimer.singleShot(300, a.refrescar)
        self._pintar_gpu_ia()

    def _gpu_pagina_nvidia(self) -> None:
        from PySide6.QtGui import QDesktopServices
        from PySide6.QtCore import QUrl
        QDesktopServices.openUrl(QUrl(URL_DRIVERS_NVIDIA))

    def _cambiar_preparar_ia(self, si: bool) -> None:
        g = getattr(self._vp, "_descarga_ia", None)
        if si:
            settings_app().setValue(CLAVE_IA_AUTO, True)
            if g is not None:
                g.quizas_empezar()
        elif g is not None:
            g.apagar()
        else:
            settings_app().setValue(CLAVE_IA_AUTO, False)
        self._toast("✓ Se prepara en segundo plano" if si else "✓ No se descarga en segundo plano")

    # ─── Página: Dictado por voz ─────────────────

    def _pagina_voz(self) -> QWidget:
        page, v = self._crear_pagina(
            "🎙  Dictado por voz",
            "Para escribir el guion hablando (pensado para personas ciegas, y útil para cualquiera): mantén "
            "apretada F2 mientras hablas, o tócala una vez y habla. El reconocimiento de voz (Whisper) funciona "
            "en este computador, sin internet: tu voz no sale de él.")
        self._lbl_voz_estado = QLabel("")
        self._lbl_voz_estado.setWordWrap(True)
        v.addWidget(self._lbl_voz_estado)
        fila = QHBoxLayout()
        self._b_voz_bajar = QPushButton("⬇  Descargar ahora")
        self._b_voz_bajar.clicked.connect(self._voz_bajar_ahora)
        self._b_voz_pausa = QPushButton("⏸  Pausar")
        self._b_voz_pausa.setProperty("secundario", True)
        self._b_voz_pausa.clicked.connect(self._voz_pausar)
        b_prueba = QPushButton("🔊  Escuchar las instrucciones")
        b_prueba.setProperty("secundario", True)
        b_prueba.clicked.connect(lambda: self._vp._dictado.voz.decir(AYUDA_DICTADO))
        for b in (self._b_voz_bajar, self._b_voz_pausa, b_prueba):
            fila.addWidget(b)
        fila.addStretch()
        v.addLayout(fila)
        v.addSpacing(px(8))

        def casilla(texto: str, clave: str, defecto: bool, al_cambiar=None, nota: str = "") -> QCheckBox:
            c = QCheckBox(texto)
            c.setChecked(_bool_ajuste(clave, defecto))
            c.toggled.connect(lambda si: (settings_app().setValue(clave, bool(si)),
                                          al_cambiar(si) if al_cambiar else None))
            v.addWidget(c)
            if nota:
                lbl = QLabel(f"<span style='color:#94a3b8;font-size:9pt;'>{nota}</span>")
                lbl.setWordWrap(True)
                v.addWidget(lbl)
            v.addSpacing(px(4))
            return c

        # Calidad: en un computador de liceo (sin tarjeta gráfica), la rápida; con una NVIDIA, la máxima
        fila_c = QHBoxLayout()
        fila_c.addWidget(QLabel("Calidad del reconocimiento de voz:"))
        self._cmb_voz_calidad = QComboBox()
        auto = MODELOS_VOZ[calidad_auto_voz()]
        self._cmb_voz_calidad.addItem(f"Automática para este computador (ahora: {auto['titulo']})", "auto")
        for c in ORDEN_CALIDAD_VOZ:
            d = MODELOS_VOZ[c]
            tam = f"{d['mb']} MB" if d["mb"] < 1000 else f"{d['mb'] / 1000:.1f} GB".replace(".", ",")
            self._cmb_voz_calidad.addItem(f"{d['titulo']} — {d['nombre']}, {tam}: {d['para']}", c)
        actual = str(settings_app().value(CLAVE_VOZ_CALIDAD, "auto") or "auto")
        self._cmb_voz_calidad.setCurrentIndex(max(0, self._cmb_voz_calidad.findData(actual)))
        self._cmb_voz_calidad.setAccessibleName("Calidad del reconocimiento de voz")
        self._cmb_voz_calidad.setSizeAdjustPolicy(QComboBox.SizeAdjustPolicy.AdjustToMinimumContentsLengthWithIcon)
        self._cmb_voz_calidad.setMinimumContentsLength(28)      # (que el texto largo no ensanche la ventana)
        self._cmb_voz_calidad.view().setMinimumWidth(px(640))
        self._cmb_voz_calidad.currentIndexChanged.connect(self._cambiar_calidad_voz)
        fila_c.addWidget(self._cmb_voz_calidad, 1)
        v.addLayout(fila_c)
        lbl_c = QLabel("<span style='color:#94a3b8;font-size:9pt;'>Sin tarjeta gráfica (como en casi todos los "
                       "computadores de un liceo), la rápida entiende una frase en uno o dos segundos; la máxima "
                       "puede tardar diez o más. Con una tarjeta NVIDIA, la máxima es igual de rápida y se "
                       "equivoca menos. Al cambiarla se descarga el modelo nuevo y se borra el anterior.</span>")
        lbl_c.setWordWrap(True)
        v.addWidget(lbl_c)
        v.addSpacing(px(8))
        self._chk_voz_auto = casilla(
            "Preparar el dictado en segundo plano (se descarga una vez: de 250 MB a 1,6 GB, según la calidad)",
            CLAVE_VOZ_AUTO, voz_descarga_permitida(), self._cambiar_preparar_voz,
            "Se descarga de a poco, como el Profesor Claqueta, y sigue la próxima vez si cierras el programa. "
            "Con una tarjeta NVIDIA también baja la versión para ella (dicta más rápido).")
        casilla("Dejar el dictado listo al abrir ¡Acción! (la primera frase sale más rápido)", CLAVE_VOZ_ACTIVA,
                False, lambda si: self._vp._voz.servidor.iniciar() if si and voz_descargada() else
                (None if si else self._vp._voz.servidor.detener()),
                "Whisper queda abierto ocupando memoria (de 0,5 a 2 GB, según la calidad). Se marca solo la "
                "primera vez que dictas.")
        casilla("Leerme en voz alta lo que escribí", CLAVE_VOZ_LEER, True)
        v.addWidget(fila_carpeta_descargas(self._vp, self))
        v.addSpacing(px(6))
        casilla("Las órdenes libres van al Profesor Claqueta (propone, me lo lee y digo «sí» o «no»)",
                CLAVE_VOZ_IA, True, None,
                "Por ejemplo: «profesor, haz que Camila dude y se vaya». Sin esto (o sin IA), lo que no sea una "
                "orden directa se escribe tal cual, como acción. Si la escritura con IA está apagada en la "
                "sección del Profesor Claqueta, solo responde preguntas.")
        v.addSpacing(px(6))
        lbl = QLabel(
            "<b>Qué decir</b><br>"
            "<span style='color:#94a3b8;font-size:9pt;'>"
            "• <b>«Que Camila diga: suelta el arma»</b> · «Camila grita, ¡corre!» (queda con «(gritando)»)<br>"
            "• <b>«Acción, …»</b> · <b>«Escena, interior, bodega, de noche»</b> · <b>«Paréntesis, …»</b> · "
            "<b>«Transición, corte a»</b><br>"
            "• «Léeme la escena» · «lee lo último» · «lee la escena 3» · «dónde estoy» · «ve a la escena 2» · "
            "«ve al final» · «cuántas escenas» · «personajes»<br>"
            "• «Borra eso» · «rehacer» · «guarda» · «título, …» · «premisa, …» · «para» · «repite» · «ayuda»<br>"
            "• <b>«Profesor, …»</b> (te propone y dices «sí» o «no») · <b>«Pregunta, …»</b> (te responde)"
            "</span>")
        lbl.setWordWrap(True)
        v.addWidget(lbl)
        v.addStretch()
        g = getattr(self._vp, "_voz", None)
        if g is not None:
            g.cambio.connect(self._pintar_estado_voz)
        self._pintar_estado_voz()
        return page

    def _pintar_estado_voz(self) -> None:
        try:
            self._pintar_estado_voz_()
        except RuntimeError:                      # (el diálogo ya se cerró)
            pass

    def _pintar_estado_voz_(self) -> None:
        import os
        g = getattr(self._vp, "_voz", None)
        lbl = self._lbl_voz_estado
        estado = g.estado if g is not None else "inactivo"
        if voz_descargada() and estado not in ("descargando", "pausado"):
            gpu = exe_whisper(carpeta_voz() / "whisper_gpu") is not None and not _bool_ajuste(CLAVE_VOZ_SIN_GPU,
                                                                                            False)
            pendiente = not (carpeta_voz() / "modelos" / archivo_modelo_voz()).is_file() and \
                not os.environ.get("ACCION_VOZ_SERVIDOR")
            txt = ("<span style='color:#16a34a;font-size:11pt;font-weight:bold;'>✓ Listo para dictar (F2)</span>"
                   f"<br><span style='color:#94a3b8;font-size:9pt;'>{nombre_modelo_voz()}, "
                   f"{'con la tarjeta gráfica' if gpu else 'con el procesador'}."
                   + (f" Falta bajar {MODELOS_VOZ[calidad_voz()]['nombre']} (la calidad elegida): mientras tanto "
                      "se dicta con el que hay." if pendiente else "") + "</span>")
            self._b_voz_bajar.setVisible(False)
            self._b_voz_pausa.setVisible(False)
        elif estado in ("descargando", "pausado"):
            txt = (f"<span style='color:#f59e0b;font-size:11pt;font-weight:bold;'>⬇ "
                   f"{'Preparando' if estado == 'descargando' else 'En pausa'} · {int(g.fraccion * 100)} %</span>"
                   f"<br><span style='color:#94a3b8;font-size:9pt;'>{g.texto}</span>")
            self._b_voz_bajar.setVisible(False)
            self._b_voz_pausa.setVisible(True)
            self._b_voz_pausa.setText("▶  Seguir" if estado == "pausado" else "⏸  Pausar")
        else:
            por_que = (g.error if g is not None and g.error else "")
            txt = ("<span style='color:#cbd5e1;font-size:11pt;font-weight:bold;'>Todavía no está descargado</span>"
                   + (f"<br><span style='color:#94a3b8;font-size:9pt;'>({por_que})</span>" if por_que else ""))
            self._b_voz_bajar.setVisible(True)
            self._b_voz_pausa.setVisible(False)
        lbl.setText(txt)

    def _voz_bajar_ahora(self) -> None:
        g = getattr(self._vp, "_voz", None)
        if g is None:
            return
        if g.retomar():
            self._toast("⬇ Descargando el dictado en segundo plano")
        else:
            self._toast("No se pudo: " + (g.error or "inténtalo más tarde"))
        self._pintar_estado_voz()

    def _voz_pausar(self) -> None:
        g = getattr(self._vp, "_voz", None)
        if g is not None:
            g.pausar(g.estado != "pausado")
        self._pintar_estado_voz()

    def _cambiar_calidad_voz(self, _i: int = 0) -> None:
        c = self._cmb_voz_calidad.currentData() or "auto"
        settings_app().setValue(CLAVE_VOZ_CALIDAD, c)
        g = getattr(self._vp, "_voz", None)
        nombre = MODELOS_VOZ[calidad_voz()]["nombre"]
        if voz_pendiente() and g is not None and (voz_descargada() or voz_descarga_permitida()):
            if g.reiniciar():
                self._toast(f"⬇ Descargando {nombre} en segundo plano")
            else:
                self._toast("No se pudo: " + (g.error or "inténtalo más tarde"))
        else:
            self._toast(f"✓ Calidad del dictado: {nombre}")
        self._pintar_estado_voz()

    def _cambiar_preparar_voz(self, si: bool) -> None:
        g = getattr(self._vp, "_voz", None)
        if si:
            if g is not None:
                g.quizas_empezar()
        elif g is not None:
            g.apagar()
        self._toast("✓ El dictado se prepara en segundo plano" if si else "✓ El dictado no se descarga")
        self._pintar_estado_voz()

