    def _abrir_carpeta_backup(self) -> None:
        import subprocess
        import sys as _sys
        carpeta = str(self._vp._carpeta_backup())
        try:
            if _sys.platform == "win32":
                subprocess.Popen(["explorer", carpeta])
            elif _sys.platform == "darwin":
                subprocess.Popen(["open", carpeta])
            else:
                subprocess.Popen(["xdg-open", carpeta])
        except Exception as e:
            QMessageBox.warning(
                self, "No se pudo abrir",
                f"Ruta: {carpeta}\n\n{e}")

