    def _elegir_ruta_guardado(self) -> None:
        """Abre un diálogo para elegir la carpeta donde guardar el
        guion de este proyecto."""
        actual = self._ed_ruta_guardado.text().strip()
        inicial = actual if actual and Path(actual).is_dir() else \
                    str(Path.home())
        carpeta = QFileDialog.getExistingDirectory(
            self, "Elegir carpeta para guardar este guion", inicial)
        if carpeta:
            self._ed_ruta_guardado.setText(carpeta)

    def _elegir_ruta_backups(self) -> None:
        """Abre un diálogo para elegir la carpeta de backups del
        proyecto."""
        actual = self._ed_ruta_backups.text().strip()
        inicial = actual if actual and Path(actual).is_dir() else \
                    str(Path.home())
        carpeta = QFileDialog.getExistingDirectory(
            self, "Elegir carpeta para copias de seguridad", inicial)
        if carpeta:
            self._ed_ruta_backups.setText(carpeta)

    def _aplicar_rutas_proyecto(self) -> None:
        """Guarda las rutas personalizadas en el documento del proyecto
        actual. Se persisten al guardar el .accion."""
        doc = self._vp.editor.documento
        nueva_guardado = self._ed_ruta_guardado.text().strip()
        nueva_backups = self._ed_ruta_backups.text().strip()

        # Validar que las carpetas existan (si están definidas)
        errores = []
        if nueva_guardado:
            p = Path(nueva_guardado).expanduser()
            if not p.is_dir():
                errores.append(
                    f"La carpeta de guardado no existe:\n{nueva_guardado}")
        if nueva_backups:
            p = Path(nueva_backups).expanduser()
            if not p.is_dir():
                try:
                    p.mkdir(parents=True, exist_ok=True)
                except Exception as e:
                    errores.append(
                        f"No se pudo crear la carpeta de backups:\n"
                        f"{nueva_backups}\n({e})")

        if errores:
            QMessageBox.warning(
                self, "Rutas inválidas",
                "\n\n".join(errores) +
                "\n\nCorregí las rutas antes de aplicar.")
            return

        doc.ruta_guardado_personalizada = nueva_guardado
        doc.ruta_backups_personalizada = nueva_backups
        try:
            self._vp._marcar_dirty()
        except Exception:
            pass

        QMessageBox.information(
            self, "Rutas aplicadas",
            "Las rutas se guardaron en este proyecto.\n\n"
            "Se aplicarán cuando guardes el archivo (Ctrl+S). "
            "A partir de ahora:\n\n"
            "• Guardar como… abrirá en la carpeta elegida.\n"
            "• Los backups automáticos se harán en la carpeta que "
            "definiste.\n\n"
            "Cada proyecto puede tener sus propias rutas.")

