    def _guardar_paso_actual(self) -> None:
        """Persiste el paso actual para poder continuar después."""
        try:
            s = settings_app()
            s.setValue("wizard_termine_paso", self._paso_actual)
        except Exception:
            pass

    # ═══════════════════════════════════════════════════════════
    # Análisis del estado del proyecto
    # ═══════════════════════════════════════════════════════════

    def _analizar_estado(self) -> dict:
        """Recorre el documento y arma un dict con qué está completo y
        qué falta. Se usa en cada paso para actualizar la UI."""
        doc = self.doc

        # Personajes del guion (nombres únicos, normalizando (V.O.))
        personajes_guion = set()
        for b in doc.bloques:
            if b.elem == Elem.PERSONAJE and (b.texto or "").strip():
                nombre = re.sub(
                    r"\s*\([^)]+\)\s*", " ",
                    b.texto).strip().upper()
                if nombre:
                    personajes_guion.add(nombre)

        # Locaciones del guion (extraídas de encabezados de escena)
        locaciones_guion = set()
        for b in doc.bloques:
            if b.elem == Elem.ESCENA and (b.texto or "").strip():
                m = re.match(
                    r"^(?:INT\./?EXT\.|INT\.|EXT\.|I/E\.)\s+"
                    r"(.+?)(?:\s*-\s*[^-]+)?$",
                    b.texto.upper().strip())
                if m:
                    lugar = m.group(1).strip().rstrip(" .,-")
                    if lugar:
                        locaciones_guion.add(lugar)

        # Fichas configuradas
        fichas_config = set(doc.fichas.keys())
        loc_config = set(doc.locaciones.keys())

        # Personajes / locaciones sin ficha
        personajes_sin_ficha = personajes_guion - {
            k.upper() for k in fichas_config}
        loc_sin_ficha = locaciones_guion - {
            k.upper() for k in loc_config}

        # Contar escenas
        n_escenas = sum(1 for b in doc.bloques
                        if b.elem == Elem.ESCENA)

        # Palabras
        n_palabras = sum(len((b.texto or "").split())
                          for b in doc.bloques)
        n_paginas = max(1, n_palabras // 250) if n_palabras else 0

        # ─── Problemas estructurales ──────────
        problemas = []

        # Actos sin su par (como los paréntesis de Excel: en rojo en el guion)
        est_a = estado_actos(doc.bloques)
        n_sin_abrir = sum(1 for d in est_a.values() if d["estado"] == "sin_abrir")
        n_sin_cerrar = sum(1 for d in est_a.values() if d["estado"] in ("sin_cerrar", "abierto"))
        if n_sin_abrir:
            problemas.append(
                f"{n_sin_abrir} FIN DE ACTO sin su INICIO DE ACTO "
                "(en el guion se ven en rojo).")
        if n_sin_cerrar:
            problemas.append(
                f"{n_sin_cerrar} acto(s) sin cerrar (falta su FIN DE ACTO).")

        # Personajes que hablan solo 1 vez
        conteo_pj: dict[str, int] = {}
        for b in doc.bloques:
            if b.elem == Elem.PERSONAJE and (b.texto or "").strip():
                n = re.sub(r"\s*\([^)]+\)\s*", " ",
                           b.texto).strip().upper()
                if n:
                    conteo_pj[n] = conteo_pj.get(n, 0) + 1
        pj_una_vez = [n for n, c in conteo_pj.items() if c == 1]
        if pj_una_vez:
            problemas.append(
                f"{len(pj_una_vez)} personaje(s) habla(n) solo una "
                f"vez — revisa si son necesarios como personajes "
                f"con nombre.")

        # Escenas sin acción
        n_esc_sin_accion = 0
        n_esc_cortas = 0
        idx_esc = -1
        n_bloques_esc = 0
        tiene_accion = False
        for b in doc.bloques:
            if b.elem == Elem.ESCENA:
                if idx_esc >= 0:
                    if not tiene_accion:
                        n_esc_sin_accion += 1
                    if n_bloques_esc < 3:
                        n_esc_cortas += 1
                idx_esc += 1
                n_bloques_esc = 0
                tiene_accion = False
            elif idx_esc >= 0 and b.elem not in (
                    Elem.ACTO_INICIO, Elem.ACTO_FIN):
                n_bloques_esc += 1
                if b.elem == Elem.ACCION and (b.texto or "").strip():
                    tiene_accion = True
        # Última escena
        if idx_esc >= 0:
            if not tiene_accion:
                n_esc_sin_accion += 1
            if n_bloques_esc < 3:
                n_esc_cortas += 1
        if n_esc_sin_accion > 0:
            problemas.append(
                f"{n_esc_sin_accion} escena(s) sin ACCIÓN — solo "
                f"diálogo puede no dar contexto visual al director.")
        if n_esc_cortas > 0:
            problemas.append(
                f"{n_esc_cortas} escena(s) con menos de 3 bloques "
                f"— ¿son escenas reales o transiciones?")

        # Encabezados duplicados
        encabezados = []
        for b in doc.bloques:
            if b.elem == Elem.ESCENA and (b.texto or "").strip():
                encabezados.append(b.texto.strip().upper())
        duplicados = set()
        vistos = set()
        for e in encabezados:
            if e in vistos:
                duplicados.add(e)
            vistos.add(e)
        if duplicados:
            problemas.append(
                f"{len(duplicados)} encabezado(s) de escena "
                f"aparece(n) más de una vez — considera diferenciarlos "
                f"(ej: agregar «- DÍA 2» al segundo).")

        # Ortografía (rápido: contar palabras rojas en bloques de texto)
        n_erratas = 0
        if corrector_activo() and cargar_diccionario_es():
            aprendidas = _palabras_aprendidas_proyecto(doc)
            re_pal = re.compile(
                r"[A-Za-záéíóúüñÁÉÍÓÚÜÑ']{3,}")
            for b in doc.bloques:
                if b.elem in (Elem.PERSONAJE, Elem.TRANSICION,
                               Elem.PLANO, Elem.ACTO_INICIO,
                               Elem.ACTO_FIN, Elem.ESCENA):
                    continue
                for m in re_pal.finditer(b.texto or ""):
                    pal = m.group()
                    if palabra_correcta(pal):
                        continue
                    if _quitar_acentos(pal.lower()) in aprendidas:
                        continue
                    n_erratas += 1
                    if n_erratas > 200:
                        break
                if n_erratas > 200:
                    break

        # Calidad de fichas existentes
        fichas_sin_actor = 0
        fichas_sin_contacto = 0
        for k, f in doc.fichas.items():
            if not (getattr(f, "actor_nombre", "") or "").strip():
                fichas_sin_actor += 1
            if not (getattr(f, "actor_telefono", "") or "").strip() \
                    and not (getattr(f, "actor_correo", "") or "").strip():
                fichas_sin_contacto += 1

        # Locaciones sin GPS (importante para clima)
        loc_sin_gps = sum(
            1 for l in doc.locaciones.values()
            if not (getattr(l, "gps", "") or "").strip())

        # Ficha del proyecto
        titulo = (getattr(doc, "titulo", "") or "").strip()
        autor = (getattr(doc, "autor_nombre", "") or "").strip()

        return {
            "personajes_guion": personajes_guion,
            "personajes_sin_ficha": personajes_sin_ficha,
            "locaciones_guion": locaciones_guion,
            "locaciones_sin_ficha": loc_sin_ficha,
            "n_escenas": n_escenas,
            "n_palabras": n_palabras,
            "n_paginas": n_paginas,
            "tiene_tecnicos": bool(doc.tecnicos),
            "tiene_equipamiento": bool(doc.equipamiento),
            "n_jornadas": len(doc.jornadas),
            "n_estados_produccion": len(doc.estados_produccion or {}),
            "problemas_estructurales": problemas,
            "n_erratas_aprox": n_erratas,
            "fichas_sin_actor": fichas_sin_actor,
            "fichas_sin_contacto": fichas_sin_contacto,
            "loc_sin_gps": loc_sin_gps,
            "titulo": titulo,
            "autor": autor,
            "tiene_beats": bool(doc.beats),
            "tiene_escaleta": bool(doc.escaleta),
        }

    # ═══════════════════════════════════════════════════════════
    # Construcción de páginas
    # ═══════════════════════════════════════════════════════════

    def _construir_paginas(self) -> None:
        """Las páginas del asistente (una por paso), en dos partes:
        🎥 Dirección (cómo se va a ver) y 🎬 Producción (cómo se consigue).
        Cada página lleva su propio «refrescar»."""
        D, P = "🎥 Parte 1 · Dirección", "🎬 Parte 2 · Producción"
        paginas = [
            (self._pagina_configurar, self._refrescar_configurar, ""),
            (self._pagina_analisis, self._refrescar_analisis, ""),
            (self._pagina_dir_planos, self._refrescar_dir_planos, D),
            (self._pagina_dir_planta, self._refrescar_dir_planta, D),
            (self._pagina_dir_animatic, self._refrescar_dir_animatic, D),
            (self._pagina_personajes, self._refrescar_personajes, P),
            (self._pagina_locaciones, self._refrescar_locaciones, P),
            (self._pagina_tecnicos, self._refrescar_tecnicos, P),
            (self._pagina_equipamiento, self._refrescar_equipamiento, P),
            (self._pagina_jornadas, self._refrescar_jornadas, P),
            (self._pagina_verificar, self._refrescar_verificar, P),
            (self._pagina_estados, self._refrescar_estados, P),
            (self._pagina_informes, self._refrescar_informes, P),
            (self._pagina_call_sheets, self._refrescar_call_sheets, P),
            (self._pagina_checklist, self._refrescar_checklist, P),
            (self._pagina_guardar_compartir, self._refrescar_guardar_compartir, ""),
            (self._pagina_final, lambda: None, ""),
        ]
        self._refrescos: list = []
        self._partes: list[str] = []
        for crear, refrescar, parte in paginas:
            self._stack.addWidget(crear())
            self._refrescos.append(refrescar)
            self._partes.append(parte)
        self._progreso.setMaximum(self._stack.count())

    # ─── 🎥 Dirección ─────────────────────
    def _estado_direccion(self) -> dict:
        doc = self.doc
        cuadros = cuadros_ordenados(doc)
        escenas = [e["n"] for e in escenas_con_bloques(doc.bloques)]
        plantas = getattr(doc, "storyboard_plantas", None) or {}
        con_planta = [n for n in escenas if (plantas.get(str(n)) or {}).get("elementos")]
        camaras = {e.get("plano") for pl in plantas.values() for e in (pl or {}).get("elementos", [])
                   if e.get("tipo") == "camara"}
        try:
            avisos = len(avisos_180_sb(doc, cuadros))
        except Exception:
            avisos = 0
        luces = sum(len(luces_planta(pl or {})) for pl in plantas.values())
        return {
            "n_escenas": len(escenas),
            "n_cuadros": len(cuadros),
            "dibujados": sum(1 for x in cuadros if x.get("id") in camaras or plano_tiene_imagen(x)),
            "animados": sum(1 for x in cuadros if plano_animado_sb(x)),
            "aprobados": sum(1 for x in cuadros if estado_revision_sb(x) == "aprobado"),
            "cambiar": sum(1 for x in cuadros if estado_revision_sb(x) == "cambiar"),
            "comentarios": sum(pendientes_sb(x) for x in cuadros),
            "escenas_sin_cuadros": [n for n in escenas
                                    if not any(int(x.get("escena", 0) or 0) == n for x in cuadros)],
            "con_planta": len(con_planta),
            "con_camara": sum(1 for x in cuadros if x.get("id") in camaras),
            "con_3d": sum(1 for pl in plantas.values() for e in (pl or {}).get("elementos", [])
                          if e.get("tipo") == "camara" and e.get("altura") is not None),
            "avisos": avisos,
            "luces": luces,
            "escenas_con_luces": sum(1 for pl in plantas.values() if luces_planta(pl or {})),
            "duracion": sum(duracion_animatic_sb(x) for x in cuadros),
        }

    def _pagina_direccion_base(self, titulo: str, subtitulo: str, botones: list):
        w, v = self._crear_pagina_base(titulo, subtitulo)
        lbl = QLabel()
        lbl.setObjectName("stat")
        lbl.setWordWrap(True)
        lbl.setTextFormat(Qt.TextFormat.RichText)
        v.addWidget(lbl)
        h = QHBoxLayout()
        for k, (txt, fn, tip) in enumerate(botones):
            b = QPushButton(txt)
            if k == 0:
                b.setProperty("primario", True)
                b.setStyle(b.style())
            b.setToolTip(tip)
            b.clicked.connect(fn)
            h.addWidget(b)
        h.addStretch()
        v.addLayout(h)
        return w, v, lbl

    def _nota_html(self, html_: str) -> QLabel:
        q = QLabel("<div style='color:#94a3b8;font-size:9pt;'>" + html_ + "</div>")
        q.setWordWrap(True)
        q.setTextFormat(Qt.TextFormat.RichText)
        return q

