    def _consultar_clima_ahora(self) -> None:
        """Fuerza la consulta a Open-Meteo para todas las jornadas
        con GPS + fecha definidos. Es la única llamada que hace
        red — el resto de las verificaciones usa cache."""
        doc = self.doc
        n_consultas = 0
        n_fallos = 0
        # UI: indicar carga
        self._lbl_verificar.setText(
            "<div style='color:#94a3b8;'>"
            "🌡  Consultando clima (Open-Meteo) para todas las "
            "jornadas… puede tardar unos segundos."
            "</div>")
        QApplication.processEvents()
        for j in doc.jornadas:
            if not j.fecha or not j.lugar:
                continue
            loc = doc.locaciones.get(j.lugar)
            if loc is None:
                for k, v in doc.locaciones.items():
                    if k.upper() == j.lugar.upper():
                        loc = v
                        break
            if loc is None:
                continue
            try:
                clima = obtener_clima_con_cache(
                    doc, loc, j.fecha, forzar_refresh=False)
                if clima is not None:
                    n_consultas += 1
            except Exception:
                n_fallos += 1
        try:
            self.vp._marcar_dirty()
        except Exception:
            pass
        if n_consultas == 0 and n_fallos == 0:
            QMessageBox.information(
                self, "Sin datos para consultar",
                "Ninguna jornada tiene GPS + fecha definidos. "
                "Agrega el GPS a las locaciones desde «Fichas de "
                "locaciones» y las fechas a las jornadas desde la "
                "Carta Gantt.")
        elif n_fallos > 0:
            QMessageBox.warning(
                self, "Consulta parcial",
                f"Se obtuvieron datos para <b>{n_consultas}</b> "
                f"jornada(s). <b>{n_fallos}</b> fallaron "
                "(¿sin conexión a Internet?).")
        else:
            QMessageBox.information(
                self, "Clima actualizado",
                f"Se obtuvieron datos de <b>{n_consultas}</b> "
                f"jornada(s). Volviendo a verificar…")
        # Re-verificar con los datos frescos
        self._verificar_todo()

    def _refrescar_verificar(self) -> None:
        # Ejecutamos la verificación automáticamente al entrar al paso
        # (antes había que hacer clic en el botón, ahora corre solo).
        if self.doc.jornadas:
            self._verificar_todo()
        else:
            self._lbl_verificar.setText(
                "<div>No hay jornadas planificadas — no hay nada "
                "que verificar. Vuelve al paso anterior si quieres "
                "planificar el rodaje.</div>")

    def _verificar_todo(self) -> None:
        """Ejecuta todos los chequeos y muestra un informe."""
        doc = self.doc
        avisos = []

        # Actualizar UI mientras se consulta clima (puede tardar)
        self._lbl_verificar.setText(
            "<div style='color:#94a3b8;'>"
            "🔍  Verificando conflictos y consultando el clima…"
            "</div>")
        QApplication.processEvents()

        # 1. Conflictos de actores por día
        actores_por_dia: dict[str, dict[str, list[str]]] = {}
        for j in doc.jornadas:
            if not j.fecha:
                continue
            for act in [a.strip() for a in (j.actores or "").split(",")
                         if a.strip()]:
                actores_por_dia.setdefault(j.fecha, {}) \
                    .setdefault(act.upper(), []).append(
                        j.nombre or "Jornada sin nombre")
        for fecha, acts in actores_por_dia.items():
            for act, jornadas in acts.items():
                if len(jornadas) > 1:
                    avisos.append(
                        f"⚠  <b>{_escapar_html_simple(act)}</b> "
                        f"está citado en varias jornadas el "
                        f"<b>{fecha}</b>: "
                        f"{', '.join(_escapar_html_simple(n) for n in jornadas)}")

        # 2. Clima adverso — solo desde cache (no consultar API acá,
        # para no bloquear el wizard). El usuario tiene un botón
        # aparte «Consultar clima ahora» para forzar la consulta.
        cache = getattr(doc, "clima_cache", {}) or {}
        n_sin_clima = 0
        for j in doc.jornadas:
            if not j.fecha or not j.lugar:
                continue
            loc = doc.locaciones.get(j.lugar)
            if loc is None:
                for k, v in doc.locaciones.items():
                    if k.upper() == j.lugar.upper():
                        loc = v
                        break
            if loc is None:
                continue
            gps_raw = (getattr(loc, "gps", "") or "").strip()
            if not gps_raw:
                continue
            clima = cache.get(f"{gps_raw}|{j.fecha}")
            if not clima:
                n_sin_clima += 1
                continue
            prob = clima.get("prob_lluvia") or 0
            if prob >= 50:
                avisos.append(
                    f"🌧  <b>{_escapar_html_simple(j.nombre or 'Jornada')}</b> "
                    f"({j.fecha}): "
                    f"{prob}% de lluvia prevista en "
                    f"{_escapar_html_simple(j.lugar)}.")
            elif prob >= 30:
                avisos.append(
                    f"⛅  <b>{_escapar_html_simple(j.nombre or 'Jornada')}</b> "
                    f"({j.fecha}): "
                    f"{prob}% de lluvia — tener plan B.")
        if n_sin_clima > 0:
            avisos.append(
                f"🌡  <b>{n_sin_clima}</b> jornada(s) sin datos de "
                f"clima consultados. Usa <b>«Consultar clima ahora»</b> "
                f"para actualizarlos.")

        # 3. Actores sin correo (afecta Call Sheet)
        actores_todas_jornadas = set()
        for j in doc.jornadas:
            for act in [a.strip() for a in (j.actores or "").split(",")
                         if a.strip()]:
                actores_todas_jornadas.add(act.upper())
        actores_sin_correo = []
        for act in actores_todas_jornadas:
            ficha = None
            for k, f in doc.fichas.items():
                if k.upper() == act:
                    ficha = f
                    break
            if ficha is None:
                actores_sin_correo.append(act)
            else:
                correo = (getattr(ficha, "actor_correo", "") or "").strip()
                if esta_cifrado(correo):
                    continue
                if "@" not in correo:
                    actores_sin_correo.append(act)
        if actores_sin_correo:
            avisos.append(
                f"📧  <b>{len(actores_sin_correo)}</b> actor(es) sin "
                f"correo: {', '.join(_escapar_html_simple(a) for a in sorted(actores_sin_correo)[:5])}"
                + ("..." if len(actores_sin_correo) > 5 else "")
                + " (la Call Sheet no los va a incluir "
                "automáticamente entre los destinatarios).")

        # 4. Locaciones sin GPS
        loc_usadas = {j.lugar.upper() for j in doc.jornadas
                       if j.lugar}
        for k, loc in doc.locaciones.items():
            if k.upper() not in loc_usadas:
                continue
            if not (getattr(loc, "gps", "") or "").strip():
                avisos.append(
                    f"📍  Locación <b>{_escapar_html_simple(k)}</b> "
                    f"sin GPS: no se puede consultar el clima "
                    f"automáticamente.")

        # Mostrar resumen
        if not avisos:
            html = (
                "<div style='color:#86efac;font-size:12pt;'>"
                "<b>✅ ¡Todo en orden!</b></div>"
                "<div style='margin-top:8px;'>"
                "Ningún conflicto detectado en el plan. Estás listo "
                "para generar las Call Sheets."
                "</div>")
        else:
            html = (
                f"<div style='color:#fca5a5;font-size:12pt;'>"
                f"<b>Se detectaron {len(avisos)} aviso(s):</b>"
                f"</div><ul>")
            for a in avisos[:20]:
                html += f"<li style='margin:4px 0;'>{a}</li>"
            if len(avisos) > 20:
                html += f"<li><i>... y {len(avisos) - 20} más</i></li>"
            html += "</ul>"
            html += (
                "<div style='color:#94a3b8;font-size:9pt;margin-top:8px;'>"
                "Abre la <b>Carta Gantt</b> para revisar y corregir. "
                "Puedes ignorar estos avisos si estás consciente de "
                "ellos."
                "</div>")
        self._lbl_verificar.setText(html)

