    def _refrescar_call_sheets(self) -> None:
        self._lst_jornadas_cs.clear()
        n_j = len(self.doc.jornadas)
        if n_j == 0:
            self._lbl_call_sheets.setText(
                "<div style='color:#fca5a5;'>"
                "⚠ No hay jornadas planificadas — no hay Call Sheets "
                "que generar.</div><div style='margin-top:6px;'>"
                "Vuelve al paso <b>«Planificación»</b> para crear "
                "las jornadas."
                "</div>")
        else:
            # Verificar prerrequisitos rápido
            avisos_prev = []
            actores_sin_correo = 0
            for j in self.doc.jornadas:
                for act in [a.strip() for a in (j.actores or "").split(",")
                             if a.strip()]:
                    ficha = None
                    for k, f in self.doc.fichas.items():
                        if k.upper() == act.upper():
                            ficha = f
                            break
                    if ficha is None:
                        actores_sin_correo += 1
                    else:
                        correo = (getattr(ficha, "actor_correo", "")
                                    or "").strip()
                        if "@" not in correo and \
                                not esta_cifrado(correo):
                            actores_sin_correo += 1
            aviso_html = ""
            if actores_sin_correo:
                aviso_html = (
                    f"<div style='color:#fca5a5;margin-top:6px;'>"
                    f"⚠ Hay <b>{actores_sin_correo}</b> ficha(s) "
                    f"actor sin correo. Puedes generar las Call "
                    f"Sheets igual, pero tendrás que agregar los "
                    f"destinatarios a mano."
                    f"</div>")
            # 🏥 locaciones de las jornadas sin hospital o centro de salud anotado
            sin_hosp = []
            for j in self.doc.jornadas:
                for lugar in (j.lugar, getattr(j, "lugar_2", "")):
                    lugar = (lugar or "").strip()
                    if not lugar or lugar in sin_hosp:
                        continue
                    loc = (self.doc.locaciones or {}).get(lugar) or next(
                        (v for k, v in (self.doc.locaciones or {}).items() if k.upper() == lugar.upper()), None)
                    if loc is None or not (getattr(loc, "hospital", "") or "").strip():
                        sin_hosp.append(lugar)
            if sin_hosp:
                aviso_html += (
                    f"<div style='color:#fcd34d;margin-top:6px;'>"
                    f"🏥 Sin hospital o centro de salud anotado: <b>{_escapar_html_simple(', '.join(sin_hosp[:6]))}"
                    f"</b>{'…' if len(sin_hosp) > 6 else ''}. Agrégalo en la ficha de la locación: va en la "
                    f"Call Sheet.</div>")
            # Timestamp de última exportación para este proyecto
            titulo = (getattr(self.doc, "titulo", "") or
                        "sin_titulo").strip()[:80]
            ts = settings_app().value(
                f"cs_ultima_export::{titulo}", "", type=str)
            carpeta_prev = settings_app().value(
                f"cs_ultima_carpeta::{titulo}", "", type=str)
            ts_html = ""
            if ts:
                ts_html = (
                    f"<div style='color:#86efac;margin-top:6px;"
                    f"font-size:9pt;'>"
                    f"📅 Última exportación: <b>{ts.replace('T', ' ')}</b>"
                    + (f"<br>📁 en <code>{_escapar_html_simple(carpeta_prev)}"
                        f"</code>" if carpeta_prev else "")
                    + "</div>")
            self._lbl_call_sheets.setText(
                f"<div>Tu proyecto tiene <b>{n_j}</b> jornadas. "
                f"Elige una para verla o exporta todas:"
                f"{aviso_html}{ts_html}"
                f"</div>")
            for i, j in enumerate(self.doc.jornadas):
                nombre = j.nombre or f"Jornada {i+1}"
                fecha = j.fecha or "(sin fecha)"
                lugar = j.lugar or "(sin lugar)"
                self._lst_jornadas_cs.addItem(
                    f"{i+1}.  {nombre}  ·  {fecha}  ·  {lugar}")

    def _abrir_call_sheet_seleccionada(self) -> None:
        if not self.doc.jornadas:
            QMessageBox.information(
                self, "Sin jornadas",
                "No hay jornadas para generar Call Sheets.")
            return
        # Delegar al diálogo existente que ya tiene selector
        self._llamar_metodo_vp("_accion_call_list")

    def _exportar_todas_call_sheets(self) -> None:
        """Exporta un HTML por cada jornada en una carpeta."""
        if not self.doc.jornadas:
            return
        carpeta = QFileDialog.getExistingDirectory(
            self, "Elegir carpeta para las Call Sheets",
            ruta_ultima_carpeta())
        if not carpeta:
            return
        try:
            gen = VentanaCallList(self.doc, self.vp, parent=self.vp)
            n_ok = 0
            fallidos = []
            for j in self.doc.jornadas:
                try:
                    html = gen._html_call_sheet(j)
                    nombre = re.sub(
                        r"[^\w\-. ]+", "_",
                        f"call_sheet_{j.fecha or 'sin_fecha'}_"
                        f"{j.nombre or 'jornada'}")
                    ruta = Path(carpeta) / f"{nombre[:80]}.html"
                    ruta.write_text(html, encoding="utf-8")
                    n_ok += 1
                except Exception as e:
                    fallidos.append(
                        f"{j.nombre or 'jornada'}: {e}")
            gen.close()
            # Guardar timestamp de última exportación (por proyecto)
            try:
                titulo = (getattr(self.doc, "titulo", "") or
                            "sin_titulo").strip()[:80]
                settings_app().setValue(
                    f"cs_ultima_export::{titulo}",
                    datetime.now().isoformat(timespec="minutes"))
                settings_app().setValue(
                    f"cs_ultima_carpeta::{titulo}", carpeta)
            except Exception:
                pass
            msg = (f"<b>✅ Se exportaron {n_ok} Call Sheet(s)</b> "
                    f"a:<br><code>{_escapar_html_simple(carpeta)}</code>")
            if fallidos:
                msg += (f"<br><br><b>{len(fallidos)}</b> fallaron:"
                          "<br>" + "<br>".join(
                            _escapar_html_simple(f) for f in fallidos))
            QMessageBox.information(
                self, "Exportación completa", msg)
            # Refrescar para mostrar el timestamp
            self._refrescar_call_sheets()
        except Exception as e:
            QMessageBox.critical(
                self, "Error", f"No se pudieron exportar:\n{e}")

