    def _refrescar_analisis(self) -> None:
        est = self._analizar_estado()
        html = []
        html.append(
            f"<div style='font-size:11pt;'><b>Tu guion tiene:</b></div>"
            f"<ul>"
            f"<li><b>{est['n_escenas']}</b> escenas · "
            f"<b>{est['n_palabras']:,}</b> palabras · "
            f"<b>~{est['n_paginas']}</b> páginas</li>"
            f"<li><b>{len(est['personajes_guion'])}</b> personajes "
            f"detectados en los diálogos</li>"
            f"<li><b>{len(est['locaciones_guion'])}</b> locaciones "
            f"detectadas en los encabezados</li>"
            f"</ul>")

        # Problemas estructurales del guion
        problemas = est.get("problemas_estructurales", [])
        n_erratas = est.get("n_erratas_aprox", 0)
        if problemas or n_erratas > 0:
            html.append(
                f"<div style='font-size:11pt;margin-top:12px;"
                f"color:#fca5a5;'><b>Cosas a revisar en el guion:</b>"
                f"</div><ul>")
            for p in problemas:
                html.append(f"<li>⚠ {_escapar_html_simple(p)}</li>")
            if n_erratas > 0:
                aprox = f"~{n_erratas}" if n_erratas <= 200 \
                    else "más de 200"
                html.append(
                    f"<li>✏ <b>{aprox}</b> palabra(s) marcada(s) "
                    f"por el corrector ortográfico. Usa <b>F7</b> "
                    f"para revisarlas.</li>")
            html.append("</ul>")

        # Estado de dirección
        ed = self._estado_direccion()
        html.append("<div style='font-size:11pt;margin-top:12px;'><b>🎥 Dirección:</b></div><ul>")
        html.append(f"<li>{'✅' if ed['n_cuadros'] else '⚠'} <b>{ed['n_cuadros']}</b> plano(s) · "
                    f"<b>{ed['dibujados']}</b> con su cámara en el storyboard 3D</li>")
        html.append(f"<li>{'✅' if ed['con_planta'] and ed['con_planta'] == ed['n_escenas'] else '⚠'} "
                    f"<b>{ed['con_planta']}</b> de {ed['n_escenas']} escena(s) con planta · "
                    f"<b>{ed['luces']}</b> luz(ces) planificada(s)</li>".replace(
                        "luz(ces) planificada(s)", "luz planificada" if ed["luces"] == 1
                        else "luces planificadas"))
        if ed["avisos"]:
            html.append(f"<li>⚠ <b>{ed['avisos']}</b> aviso(s) de la regla de los 180°</li>")
        html.append("</ul>")

        # Estado de preproducción
        html.append(
            f"<div style='font-size:11pt;margin-top:12px;'>"
            f"<b>🎬 Producción:</b></div><ul>")
        n_falta_pj = len(est["personajes_sin_ficha"])
        if n_falta_pj:
            html.append(
                f"<li>⚠ <b>{n_falta_pj}</b> personaje(s) sin ficha</li>")
        else:
            html.append(
                f"<li>✅ Todas las fichas de personaje están listas</li>")
        n_falta_loc = len(est["locaciones_sin_ficha"])
        if n_falta_loc:
            html.append(
                f"<li>⚠ <b>{n_falta_loc}</b> locación(es) sin ficha</li>")
        else:
            html.append(
                f"<li>✅ Todas las locaciones están fichadas</li>")
        if est.get("loc_sin_gps", 0):
            html.append(
                f"<li>📍 <b>{est['loc_sin_gps']}</b> locación(es) "
                f"sin GPS — no se puede consultar el clima</li>")
        if est["tiene_tecnicos"]:
            html.append(
                f"<li>✅ Crew: <b>{len(self.doc.tecnicos)}</b> personas"
                f"</li>")
        else:
            html.append(f"<li>⚠ Equipo técnico sin configurar</li>")
        if est["tiene_equipamiento"]:
            html.append(
                f"<li>✅ Equipamiento: "
                f"<b>{len(self.doc.equipamiento)}</b> ítems</li>")
        else:
            html.append(f"<li>⚠ Equipamiento sin configurar</li>")
        if est["n_jornadas"]:
            html.append(
                f"<li>✅ <b>{est['n_jornadas']}</b> jornada(s) "
                f"planificadas</li>")
        else:
            html.append(
                f"<li>⚠ Sin jornadas de rodaje planificadas</li>")
        # Calidad de fichas
        if est.get("fichas_sin_actor", 0):
            html.append(
                f"<li>🎭 <b>{est['fichas_sin_actor']}</b> ficha(s) "
                f"sin actor real asignado</li>")
        if est.get("fichas_sin_contacto", 0):
            html.append(
                f"<li>📞 <b>{est['fichas_sin_contacto']}</b> ficha(s) "
                f"sin teléfono ni correo</li>")
        html.append("</ul>")

        html.append(
            f"<div style='color:#94a3b8;margin-top:8px;font-size:9pt;'>"
            f"<i>Puedes saltar cualquier paso que no necesites. "
            f"Todo lo que hagas se guarda automáticamente en el "
            f"proyecto.</i></div>")
        self._lbl_analisis.setText("".join(html))


