    def _refrescar_personajes(self) -> None:
        est = self._analizar_estado()
        html = []
        n_falta = len(est["personajes_sin_ficha"])
        if n_falta == 0 and est["personajes_guion"]:
            html.append(
                "<div style='color:#86efac;font-size:11pt;'>"
                "✅ <b>Todos los personajes tienen ficha.</b></div>"
                "<div style='margin-top:8px;'>"
                "Igual puedes seleccionar cualquiera abajo y "
                "actualizar sus datos rápido."
                "</div>")
        elif not est["personajes_guion"]:
            html.append(
                "<div>Tu guion no tiene personajes hablando "
                "todavía. Este paso no aplica.</div>")
        else:
            html.append(
                f"<div style='color:#fca5a5;font-size:11pt;'>"
                f"⚠ Faltan <b>{n_falta}</b> ficha(s) de personaje:"
                f"</div><ul>")
            for pj in sorted(est["personajes_sin_ficha"])[:20]:
                html.append(f"<li><b>{_escapar_html_simple(pj)}</b></li>")
            if n_falta > 20:
                html.append(f"<li><i>... y {n_falta - 20} más</i></li>")
            html.append("</ul>")
        self._lbl_personajes.setText("".join(html))

        # Poblar combo con todos los personajes
        actual = self._combo_pj.currentText() if \
            self._combo_pj.count() else ""
        self._combo_pj.blockSignals(True)
        self._combo_pj.clear()
        todos = sorted(est["personajes_guion"])
        # Priorizar los que faltan
        faltantes_arriba = [p for p in todos
                              if p in est["personajes_sin_ficha"]]
        con_ficha = [p for p in todos
                       if p not in est["personajes_sin_ficha"]]
        for p in faltantes_arriba:
            self._combo_pj.addItem(f"⚠  {p}", userData=p)
        for p in con_ficha:
            self._combo_pj.addItem(f"✓  {p}", userData=p)
        # Restaurar selección si sigue existiendo
        if actual:
            for i in range(self._combo_pj.count()):
                if self._combo_pj.itemText(i).endswith(actual[-30:]):
                    self._combo_pj.setCurrentIndex(i)
                    break
        self._combo_pj.blockSignals(False)
        self._cargar_ficha_pj_en_form()

    def _cargar_ficha_pj_en_form(self) -> None:
        """Carga la ficha del personaje seleccionado en el mini
        formulario embebido."""
        pj = self._combo_pj.currentData()
        if not pj:
            return
        ficha = self.doc.fichas.get(pj)
        if ficha is None:
            for k, f in self.doc.fichas.items():
                if k.upper() == pj.upper():
                    ficha = f
                    break
        if ficha is None:
            # No hay ficha aún — limpiar campos
            self._ed_pj_actor.setText("")
            self._ed_pj_tel.setText("")
            self._ed_pj_correo.setText("")
            self._ed_pj_alergias.setText("")
            self._combo_pj_dieta.setCurrentIndex(0)
            return
        # Llenar con datos existentes (respetar cifrado)
        def _safe(v):
            if v and esta_cifrado(v):
                return ""
            return v or ""
        self._ed_pj_actor.setText(
            _safe(getattr(ficha, "actor_nombre", "")))
        self._ed_pj_tel.setText(
            _safe(getattr(ficha, "actor_telefono", "")))
        self._ed_pj_correo.setText(
            _safe(getattr(ficha, "actor_correo", "")))
        self._ed_pj_alergias.setText(
            _safe(getattr(ficha, "alergias_detalle", "")))
        dieta = (getattr(ficha, "alimentacion", "") or "Omnívoro")
        idx_d = self._combo_pj_dieta.findText(dieta)
        if idx_d >= 0:
            self._combo_pj_dieta.setCurrentIndex(idx_d)

    def _guardar_ficha_pj_rapida(self) -> None:
        """Guarda la ficha del personaje del mini-formulario."""
        pj = self._combo_pj.currentData()
        if not pj:
            return
        # Buscar o crear ficha
        ficha = self.doc.fichas.get(pj)
        if ficha is None:
            for k, f in self.doc.fichas.items():
                if k.upper() == pj.upper():
                    ficha = f
                    break
        if ficha is None:
            ficha = Ficha(personaje=pj)
            self.doc.fichas[pj] = ficha
        # Solo tocar los campos si no están cifrados en la ficha
        if not esta_cifrado(getattr(ficha, "actor_nombre", "") or ""):
            ficha.actor_nombre = self._ed_pj_actor.text().strip()
        if not esta_cifrado(getattr(ficha, "actor_telefono", "") or ""):
            ficha.actor_telefono = self._ed_pj_tel.text().strip()
        if not esta_cifrado(getattr(ficha, "actor_correo", "") or ""):
            ficha.actor_correo = self._ed_pj_correo.text().strip()
        alergias_txt = self._ed_pj_alergias.text().strip()
        ficha.alergias = bool(alergias_txt)
        ficha.alergias_detalle = alergias_txt
        ficha.alimentacion = self._combo_pj_dieta.currentText()
        try:
            self.vp._marcar_dirty()
        except Exception:
            pass
        avisar_guardado(self, f"✅ Ficha de «{pj}» actualizada.")
        self._refrescar_personajes()

