    def _seleccionar_de_lista(self, titulo: str, subtitulo: str,
                              opciones: list[str],
                              premarcadas: set | None = None):
        """Diálogo con checkboxes: el usuario marca SOLO lo que su
        producción realmente usará. Devuelve lista de índices
        marcados, o None si canceló."""
        dlg = QDialog(self)
        dlg.setWindowTitle(titulo)
        dlg.setMinimumSize(px(460), px(520))
        v = QVBoxLayout(dlg)
        lbl = QLabel(subtitulo)
        lbl.setWordWrap(True)
        lbl.setStyleSheet("color: #8fa1b8;")
        v.addWidget(lbl)
        lista = QListWidget()
        lista.setStyleSheet(ESTILO_LISTA_SELECCION)
        for texto in opciones:
            it = QListWidgetItem(texto)
            it.setFlags(it.flags() | Qt.ItemFlag.ItemIsUserCheckable)
            it.setCheckState(
                Qt.CheckState.Checked
                if premarcadas and texto in premarcadas
                else Qt.CheckState.Unchecked)
            lista.addItem(it)
        v.addWidget(lista, 1)
        hb = QHBoxLayout()
        btn_todo = QPushButton("Marcar todos")
        btn_nada = QPushButton("Ninguno")
        def _set_all(estado):
            for i in range(lista.count()):
                lista.item(i).setCheckState(estado)
        btn_todo.clicked.connect(
            lambda: _set_all(Qt.CheckState.Checked))
        btn_nada.clicked.connect(
            lambda: _set_all(Qt.CheckState.Unchecked))
        hb.addWidget(btn_todo); hb.addWidget(btn_nada); hb.addStretch()
        btn_ok = QPushButton("✓ Crear seleccionados")
        btn_ok.setProperty("primario", True)
        btn_ok.setStyle(btn_ok.style())
        btn_ok.clicked.connect(dlg.accept)
        btn_c = QPushButton("Cancelar")
        btn_c.clicked.connect(dlg.reject)
        hb.addWidget(btn_c); hb.addWidget(btn_ok)
        v.addLayout(hb)
        if dlg.exec() != QDialog.DialogCode.Accepted:
            return None
        return [i for i in range(lista.count())
                if lista.item(i).checkState() == Qt.CheckState.Checked]

    def _cargar_plantilla_tecnicos(self) -> None:
        """Pregunta QUÉ roles usará esta producción (checkboxes) y
        crea solo esos — nada de sets genéricos que no existen."""
        todos = crear_tecnicos_plantilla()
        opciones = [t.rol or t.nombre for t in todos]
        basicos = {"Director / Directora", "Director de fotografía "
                   "(DP)", "Sonidista directo", "Editor / Editora"}
        idx = self._seleccionar_de_lista(
            "Roles de tu crew",
            "Marca los roles que tu producción realmente tendrá. "
            "En un corto escolar, una persona puede cubrir varios "
            "— crea solo los que usarán. Después les pones nombre "
            "y contacto en las fichas.",
            opciones,
            premarcadas={o for o in opciones if o in basicos})
        if idx is None:
            return
        if not idx:
            QMessageBox.information(
                self, "Nada seleccionado",
                "No marcaste ningún rol. No se creó nada.")
            return
        existentes = {(t.rol or t.nombre) for t in self.doc.tecnicos}
        nuevos = [todos[i] for i in idx
                  if (todos[i].rol or todos[i].nombre)
                  not in existentes]
        self.doc.tecnicos.extend(nuevos)
        self.vp._marcar_dirty()
        QMessageBox.information(
            self, "Crew creado",
            f"Se crearon {len(nuevos)} rol(es). Complétalos en "
            "«Fichas de crew».")
        self._refrescar_tecnicos()

