    def _generar_plan_asistido(self) -> None:
        """Pregunta al usuario fecha de inicio y días por locación
        antes de generar el plan."""
        from datetime import date, timedelta
        # Fecha inicio
        default_fecha = date.today() + timedelta(days=14)
        fecha_str, ok = QInputDialog.getText(
            self, "Fecha de inicio",
            "¿Cuándo quieres empezar a grabar? (YYYY-MM-DD)",
            QLineEdit.EchoMode.Normal, default_fecha.isoformat())
        if not ok:
            return
        try:
            fecha_ini = date.fromisoformat(fecha_str.strip())
        except ValueError:
            QMessageBox.warning(
                self, "Fecha inválida",
                "Formato esperado: YYYY-MM-DD (ejemplo: 2026-09-15).")
            return
        # Días por locación
        dias, ok = QInputDialog.getInt(
            self, "Días por locación",
            "¿Cuántos días de rodaje asignar por locación?\n"
            "(Después puedes ajustar cada jornada por separado.)",
            3, 1, 30, 1)
        if not ok:
            return
        # Días de descanso entre locaciones
        gap, ok = QInputDialog.getInt(
            self, "Días entre locaciones",
            "¿Cuántos días de descanso dejar entre una locación "
            "y la siguiente?",
            2, 0, 14, 1)
        if not ok:
            return

        # Delegar la generación al método existente, pero con
        # parámetros personalizados. Vamos a llamar directamente al
        # helper de agrupación.
        doc = self.doc
        escenas = segmentar_escenas(doc)
        if not escenas:
            # Sin escenas: igual se arma el calendario (jornadas vacías)
            nuevas = preguntar_jornadas_vacias(self, doc)
            if nuevas:
                doc.jornadas = nuevas
                self.vp._marcar_dirty()
                try:
                    self._refrescar_jornadas()
                except Exception:
                    pass
            return
        agrupado: dict[str, list[int]] = {}
        actores_por_escena: dict[int, set] = {}
        for e in escenas:
            enc = e["encabezado"]
            m = re.match(
                r"^(?:INT\./?EXT\.|INT\.|EXT\.|I/E\.)\s+"
                r"(.+?)(?:\s*-\s*[^-]+)?$",
                enc.upper().strip())
            lugar = (m.group(1).strip().rstrip(" .,-") if m
                     else "Locación sin nombre")
            agrupado.setdefault(lugar, []).append(e["numero"])
            actores_por_escena[e["numero"]] = set(e["personajes"])

        nuevas = []
        cursor_fecha = fecha_ini
        for i, (lugar, nums) in enumerate(agrupado.items()):
            fecha_fin = cursor_fecha + timedelta(days=dias - 1)
            actores = set()
            for n in nums:
                actores.update(actores_por_escena.get(n, set()))
            nueva = Jornada(
                nombre=f"Jornada {i+1} — {lugar.title()}",
                fecha=cursor_fecha.isoformat(),
                fecha_fin=fecha_fin.isoformat(),
                lugar=lugar.title(),
                hora_citacion="08:00",
                escenas=",".join(str(n) for n in nums),
                actores=", ".join(sorted(actores)),
                notas=(f"Generado por el asistente con "
                       f"{dias} día(s) por locación."))
            nuevas.append(nueva)
            cursor_fecha = fecha_fin + timedelta(days=gap + 1)

        doc.jornadas.extend(nuevas)
        try:
            self.vp._marcar_dirty()
        except Exception:
            pass
        QMessageBox.information(
            self, "Plan generado",
            f"Se crearon <b>{len(nuevas)}</b> jornada(s) desde "
            f"<b>{fecha_ini.isoformat()}</b> hasta "
            f"<b>{cursor_fecha.isoformat()}</b>.<br><br>"
            "Ahora conviene ir al siguiente paso (Verificar plan) "
            "para revisar conflictos y clima.")
        self._refrescar_jornadas()

    def _refrescar_jornadas(self) -> None:
        n = len(self.doc.jornadas)
        html = []
        if n == 0:
            html.append(
                "<div style='color:#fca5a5;font-size:11pt;'>"
                "⚠ Sin jornadas de rodaje planificadas.</div>"
                "<div style='margin-top:8px;'>"
                "Puedes <b>generar un plan automático</b> "
                "(agrupa escenas por locación con 3 días por "
                "cada una), o crearlas manualmente desde la "
                "Carta Gantt."
                "</div>")
        else:
            # Fechas mínima y máxima
            fechas = [j.fecha for j in self.doc.jornadas if j.fecha]
            rango = ""
            if fechas:
                rango = f"del <b>{min(fechas)}</b> al <b>{max(fechas)}</b>"
            html.append(
                f"<div style='color:#86efac;font-size:11pt;'>"
                f"✅ <b>{n}</b> jornada(s) planificadas {rango}.</div>"
                f"<div style='color:#94a3b8;font-size:9pt;margin-top:8px;'>"
                f"Abre la Carta Gantt para revisar. El botón "
                f"<b>«Verificar disponibilidad»</b> te avisa si hay "
                f"conflictos (actores citados en dos lugares el "
                f"mismo día, etc.)."
                f"</div>")
        self._lbl_jornadas.setText("".join(html))

