        vs.addStretch()
        self._aviso = QLabel("")                     # (✅ «Ficha guardada»: sin ventana que confirmar)
        self._aviso.setWordWrap(True)
        self._aviso.setStyleSheet("color: #86efac; font-size: 9pt; font-weight: 700;")
        self._aviso.hide()
        vs.addWidget(self._aviso)
