        self._grilla.setSpacing(px(18))
        self._grilla.setAlignment(Qt.AlignmentFlag.AlignTop
                                  | Qt.AlignmentFlag.AlignLeft)
        self._scroll.setWidget(cont)
        centro.addWidget(self._scroll, 1)

