def apodo_modelo(nombre: str) -> str:
    """El apodo de un modelo («qwen3.5:4b» → «Hitchcock»), o «» si no es de la lista."""
    return next((mo["apodo"] for mo in MODELOS_ASESOR if nombre in (mo["tag"], mo["alt"])), "")


def nombre_modelo_con_apodo(nombre: str) -> str:
    """«Hitchcock (qwen3.5:4b)»; si no tiene apodo, el nombre tal cual."""
    a = apodo_modelo(nombre)
    return f"{a} ({nombre})" if a else nombre


def puntos_modelo(n: int) -> str:
    """●●●○○: de 1 a 5."""
    n = max(0, min(5, int(n or 0)))
    return "●" * n + "○" * (5 - n)


