def personajes_del_documento(doc) -> list:
    """Los nombres de los personajes (de sus fichas y de los diálogos)."""
    nombres = list((getattr(doc, "fichas", None) or {}).keys())
    for b in getattr(doc, "bloques", []) or []:
        if b.elem == Elem.PERSONAJE:
            k = (b.texto or "").strip().upper().split("(")[0].strip()
            if k and k not in nombres:
                nombres.append(k)
    return nombres


