_VERBOS_ESCRIBIR_IA = (r"escribe(?:me|lo|la)?|escribi|redacta(?:me)?|agrega|anade|añade|inserta|pon(?:me|le)?|"
                       r"crea|continua|sigue|desarrolla|termina|completa|reescribe|haz\s+(?:que|una|un)|"
                       r"inventa|arma(?:me)?|dame\s+(?:una|un)\s+(?:escena|dialogo|accion)")
_OBJETOS_ESCRIBIR_IA = r"(?:escena|dialogo|parlamento|accion|guion|encabezado|transicion|final|inicio|comienzo|que\s+\w+\s+diga)"


def es_pedido_de_escritura(texto: str) -> bool:
    """¿Le están pidiendo que escriba en el guion? («escribe la escena 3
    donde…», «agrega un diálogo de Camila», «haz que Tomás se vaya»…).
    Una pregunta («¿cómo escribo…?») no lo es."""
    n = " ".join(str(texto or "").translate(_SIN_TILDE_VOZ).lower().split())
    if not n or n.startswith(("como ", "que opinas", "por que", "cual", "cuando", "donde ")) or n.endswith("?"):
        return False
    previo = r"^(?:por\s+favor[, ]+|profe(?:sor)?[, ]+|ahora[, ]+|y\s+)?"
    if re.match(previo + r"(?:" + _VERBOS_ESCRIBIR_IA + r")\b", n) \
            and re.search(_OBJETOS_ESCRIBIR_IA + r"|\bque\s+\w+\s+(?:diga|grite|entre|salga|se\s+vaya)", n):
        return True
    # «escribe que Camila duda y se va», «agrega que llueve», «haz que Tomás dude»
    if re.match(previo + r"(?:escribe|agrega|anade|inserta|pon(?:me|le)?|haz)\s+que\s+\w+", n):
        return True
    return bool(re.match(r"^(?:por\s+favor[, ]+)?que\s+[a-z]+\s+(?:diga|grite|responda|entre|"
                         r"salga|se\s+vaya|llore|corra)\b", n))


