def enlazar_programa(html_txt: str, personajes: Optional[list] = None) -> str:
    """En lo que dijo la IA, las partes del programa que nombra («ficha de
    CAMILA», «Pizarra de beats», «tags»…) quedan como enlaces que las
    abren. Cada una, una vez por respuesta; nunca dentro de otro enlace."""
    reglas = []
    for nombre in sorted({str(p_).strip().upper() for p_ in personajes or [] if str(p_).strip()}, key=len,
                         reverse=True):
        nom = r"\s+".join(re.escape(w) for w in nombre.split())
        reglas.append(("ficha:" + nombre, r"(?:la\s+)?ficha\s+(?:de(?:l\s+personaje)?\s+)?" + nom + r"\b"))
    reglas.extend(DESTINOS_PROGRAMA)
    reglas = [(d, re.compile(e, re.IGNORECASE)) for d, e in reglas]
    hechos: set = set()

    def enlazar(texto: str) -> str:
        piezas, pos = [], 0
        while True:
            mejor = None
            for destino, rx in reglas:
                if destino in hechos:
                    continue
                m_ = rx.search(texto, pos)
                if m_ and (mejor is None or m_.start() < mejor[1].start()):
                    mejor = (destino, m_)
            if mejor is None:
                break
            destino, m_ = mejor
            hechos.add(destino)
            piezas.append(texto[pos:m_.start()])
            piezas.append(f"<a href='accion:{html.escape(destino, quote=True)}' "
                          f"style='color:#ffb066;text-decoration:underline;'>{m_.group(0)}</a>")
            pos = m_.end()
        piezas.append(texto[pos:])
        return "".join(piezas)

    out, dentro_a = [], False
    for parte in re.split(r"(<[^>]+>)", html_txt or ""):
        if parte.startswith("<"):
            low = parte.lower()
            if low.startswith("<a ") or low == "<a>":
                dentro_a = True
            elif low.startswith("</a"):
                dentro_a = False
            out.append(parte)
        else:
            out.append(parte if dentro_a or not parte.strip() else enlazar(parte))
    return "".join(out)


def selector_injerencia_ia() -> QWidget:
    """🎚 «¿Cuánto puede tocar la IA tu guion?» y «cuando le pido que
    escriba…» (en los modelos y en Configuración: lo mismo en los dos)."""
    w = QWidget()
    v = QVBoxLayout(w)
    v.setContentsMargins(0, 0, 0, 0)
    t = QLabel("<b>🎚 ¿Cuánto puede tocar la IA tu guion?</b>")
    v.addWidget(t)
    grupo = QButtonGroup(w)
    actual = injerencia_ia()
    for clave, texto in NIVELES_INJERENCIA_IA:
        rb = QRadioButton(texto)
        rb.setProperty("clave", clave)
        rb.setChecked(clave == actual)
        rb.toggled.connect(lambda si, c=clave: settings_app().setValue(CLAVE_IA_INJERENCIA, c) if si else None)
        grupo.addButton(rb)
        v.addWidget(rb)
    w._grupo_injerencia = grupo
    fila = QHBoxLayout()
    fila.addWidget(QLabel("Cuando le pido que escriba:"))
    cmb = QComboBox()
    for clave, texto in MODOS_ESCRITURA_IA:
        cmb.addItem(texto, clave)
    cmb.setCurrentIndex(max(0, cmb.findData(modo_escritura_ia())))
    cmb.currentIndexChanged.connect(lambda _i: settings_app().setValue(CLAVE_IA_MODO_ESCRITURA, cmb.currentData()))
    fila.addWidget(cmb, 1)
    v.addLayout(fila)
    w._cmb_modo = cmb
    # ✏ Cuando le pido cambiar mis fichas (personajes, locaciones, crew…)
    fila2 = QHBoxLayout()
    fila2.addWidget(QLabel("Cuando le pido cambiar algo:"))
    cmb2 = QComboBox()
    cmb2.setToolTip("Si le pides al Profesor Claqueta cambiar algo del proyecto (las fichas de personajes, "
                    "locaciones, crew, equipamiento y escenas, la premisa, las jornadas de la Carta Gantt, el "
                    "presupuesto, los contratos y seguros o la lista de planos): si te muestra antes qué va a "
                    "cambiar, si lo hace solo y te avisa (con ↶ Deshacer), o si nunca toca nada")
    for clave, texto in MODOS_CAMBIOS_IA:
        cmb2.addItem(texto.replace("  ", " "), clave)
    cmb2.setCurrentIndex(max(0, cmb2.findData(modo_cambios_ia() or "confirmar")))

    def elegido(_i):
        modo = cmb2.currentData()
        if modo == (modo_cambios_ia() or "confirmar"):
            return
        if not poner_modo_cambios_ia(modo, w.window()):
            cmb2.blockSignals(True)                  # (no aceptó los riesgos: queda como estaba)
            cmb2.setCurrentIndex(max(0, cmb2.findData(modo_cambios_ia() or "confirmar")))
            cmb2.blockSignals(False)
    cmb2.currentIndexChanged.connect(elegido)
    fila2.addWidget(cmb2, 1)
    v.addLayout(fila2)
    w._cmb_cambios = cmb2
    return w


# ── ✏ El Profesor Claqueta cambia tus fichas (solo si se lo pides) ──
# Se le pide en la conversación («cambia la edad de ANA a 17», «agrega al
# crew a Pedro Soto como sonidista»…). La IA responde en JSON qué cambiar;
# ¡Acción! lo revisa (qué ficha, qué dato, que no invente teléfonos ni
# montos), lo muestra y, según lo elegido, espera tu «sí» o lo hace y avisa.
# Todo se puede deshacer, y borrar una ficha siempre se confirma.
