def texto_riesgos_avanzar_solo_ia(html_: bool = True) -> str:
    if html_:
        return "".join(f"• <b>{html.escape(t)}</b>: {html.escape(d)}<br>" for t, d in RIESGOS_AVANZAR_SOLO_IA)
    return "\n".join(f"• {t}: {d}" for t, d in RIESGOS_AVANZAR_SOLO_IA)


def pedir_permiso_avanzar_solo_ia(parent=None) -> bool:
    """⚡ Antes de dejar que el Profesor Claqueta cambie las fichas sin
    preguntar: los riesgos, y la decisión (por defecto, seguir confirmando)."""
    mb = QMessageBox(parent)
    mb.setIcon(QMessageBox.Icon.Warning)
    mb.setWindowTitle("⚡ ¿Avanzar solo?")
    mb.setTextFormat(Qt.TextFormat.RichText)
    mb.setText("<b>Si eliges avanzar solo, el Profesor Claqueta cambia tus fichas, la Carta Gantt, el "
               "presupuesto y lo demás apenas se lo pidas, sin mostrarte antes qué va a cambiar.</b><br><br>"
               "Los riesgos:<br>" + texto_riesgos_avanzar_solo_ia() +
               "<br>Lo que te protege igual: cada cambio queda anotado en la conversación con <b>↶ Deshacer</b>, "
               "borrar (una ficha, una jornada, un gasto…) <b>siempre</b> te lo pregunta, y lo vuelves a cambiar cuando quieras en "
               "🎚 Injerencia o en Configuración → 🤖 Prof. Claqueta.<br><br>"
               "En un curso, o con un modelo chico, conviene seguir confirmando.")
    b_si = mb.addButton("⚡  Entiendo los riesgos: avanzar solo", QMessageBox.ButtonRole.AcceptRole)
    b_no = mb.addButton("🔒  Seguir confirmando", QMessageBox.ButtonRole.RejectRole)
    mb.setDefaultButton(b_no)
    mb.setEscapeButton(b_no)
    mb.exec()
    return mb.clickedButton() is b_si


def poner_modo_cambios_ia(modo: str, parent=None) -> bool:
    """Guarda cómo cambia las fichas la IA. «solo» pasa antes por los
    riesgos (si no se aceptan, queda como estaba). ¿Quedó el pedido?"""
    if modo not in dict(MODOS_CAMBIOS_IA):
        return False
    if modo == "solo" and modo_cambios_ia() != "solo" and not pedir_permiso_avanzar_solo_ia(parent):
        return False
    settings_app().setValue(CLAVE_IA_CAMBIOS, modo)
    return True


