def es_pedido_de_cambio_ia(texto: str) -> bool:
    """¿Le están pidiendo cambiar datos de las fichas? («cambia la edad de ANA
    a 17», «agrega al crew a Pedro Soto, sonidista», «¿puedes poner en la
    ficha de la escena 3 que el tono es tenso?»). Una pregunta sobre cómo
    hacerlo («¿cómo cambio la edad?») no lo es."""
    n = " ".join(str(texto or "").lower().split())
    n = n.translate(str.maketrans("áéíóúü", "aeiouu")).strip(" ¡¿")
    if not n or len(n) > 600:
        return False
    previo = (r"^(?:(?:por\s+favor|porfa|profe(?:sor)?(?:\s+claqueta)?|oye|ahora|y|tambien|ya|ok|ah)[, ]+)*"
              r"(?:(?:puedes|podrias|me\s+ayudas\s+a|quiero\s+que|quisiera\s+que|necesito\s+que|"
              r"me\s+gustaria\s+que|te\s+pido\s+que)\s+)?(?:me\s+|le\s+|lo\s+|la\s+)?")
    if re.match(r"^(?:en\s+)?(?:la\s+)?jornada\s+\d+\b", n) and not n.endswith("?"):
        return True                   # («la jornada 2 empieza a las 9», «jornada 3: agrega a BETO»)
    if re.match(r"^en\s+(?:la|el)\s+(?:ficha|lista\s+de\s+planos|carta\s+gantt|presupuesto|plano)\b", n) \
            and not n.endswith("?") and len(n.split()) >= 5:
        return True                   # («en la lista de planos, el plano 1 de la escena 1 es cenital»)
    if re.match(r"^(?:los\s+fondos(?:\s+disponibles)?|el\s+iva|la\s+tasa\s+de(?:l)?\s+iva)\s+"
                r"(?:son|es|va|van|queda|quedan|esta|estan|seran|sera)\b", n) and not n.endswith("?"):
        return True                   # («los fondos son 3 millones», «el IVA va incluido»)
    if not re.match(previo + _VERBO_CAMBIO_IA + r"\b", n):
        return False
    return bool(re.search(_DATO_CAMBIO_IA, n))


def _norm_ia(s: str) -> str:
    import unicodedata
    s = unicodedata.normalize("NFKD", str(s or "")).encode("ascii", "ignore").decode("ascii")
    return " ".join(re.sub(r"[^a-z0-9]+", " ", s.lower()).split())


def _numeros_ia(s: str, partes: bool = True) -> set:
    """Los números de un texto, como números («50 mil» → 50000; «$1.200.000»
    → 1200000; «+56 9 0000 0022» → 56900000022 y, con «partes», cada parte)."""
    t = str(s or "").lower()
    t = re.sub(r"(\d+(?:[.,]\d+)?)\s*(mill[oó]n(?:es)?|mil|lucas?)\b",
               lambda m_: str(int(round(float(m_.group(1).replace(",", ".")) *
                                        (1_000_000 if m_.group(2).startswith("mill") else 1000)))), t)
    out = set()
    for m_ in re.finditer(r"\+?\d[\d .\-()]*\d|\d", t):
        dig = re.sub(r"\D", "", m_.group(0))
        if dig:
            out.add(dig.lstrip("0") or "0")
            for parte in (re.split(r"[ \-()]+", m_.group(0)) if partes else ()):   # (también cada parte suelta)
                d2 = re.sub(r"\D", "", parte)
                if d2:
                    out.add(d2.lstrip("0") or "0")
    return out


def dato_en_pedido_ia(valor: str, pedido: str) -> bool:
    """¿Este dato real (teléfono, correo, monto, nombre) lo escribió la
    persona? Si no, la IA lo inventó: no se acepta."""
    v = str(valor or "").strip()
    if not v:
        return True                                   # (dejarlo en blanco sí se puede)
    p = str(pedido or "")
    correos = re.findall(r"[\w.+-]+@[\w-]+(?:\.[\w-]+)+", v)
    if correos:
        return all(c.lower() in p.lower() for c in correos)
    nums_v = _numeros_ia(v, partes=False)
    if nums_v:
        nums_p = _numeros_ia(p)
        dig_p = re.sub(r"\D", "", p)
        for d in nums_v:
            if d in nums_p or (len(d) >= 7 and (d in dig_p or any(len(x) >= 7 and d.endswith(x) for x in nums_p))):
                continue
            return False
        return True
    palabras = [w for w in _norm_ia(v).split() if len(w) >= 3 and w not in ("del", "las", "los", "por", "con")]
    np_ = " " + _norm_ia(p) + " "
    return all(f" {w} " in np_ or f" {w}" in np_ for w in palabras)


def _buscar_nombre_ia(cual: str, candidatos: list) -> Optional[str]:
    """El candidato que corresponde a «cual» (sin tildes ni mayúsculas; un
    nombre de pila, un comienzo o algo muy parecido), o None (o si hay dos)."""
    import difflib
    c = _norm_ia(cual)
    if not c:
        return None
    norm = {k: _norm_ia(k) for k in candidatos}
    exactos = [k for k, n_ in norm.items() if n_ == c]
    if exactos:
        return exactos[0]
    for prueba in (lambda n_: n_.startswith(c + " ") or c.startswith(n_ + " "),
                   lambda n_: n_.split()[:1] == c.split()[:1] if n_ else False):
        hay = [k for k, n_ in norm.items() if prueba(n_)]
        if len(hay) == 1:
            return hay[0]
        if len(hay) > 1:
            return None
    cerca = difflib.get_close_matches(c, list(norm.values()), n=2, cutoff=0.84)
    if len(cerca) == 1:
        return next(k for k, n_ in norm.items() if n_ == cerca[0])
    return None


def _leer_dato_ia(obj, campo: str):
    if isinstance(obj, dict):
        return obj.get(campo, "")
    return getattr(obj, campo, "")


def _poner_dato_ia(obj, campo: str, valor) -> None:
    if isinstance(obj, dict):
        obj[campo] = valor
    else:
        setattr(obj, campo, valor)


def _contenedor_cambio_ia(doc, tipo: str):
    return {"personaje": doc.fichas, "locacion": doc.locaciones, "crew": doc.tecnicos,
            "equipamiento": doc.equipamiento, "escena": doc.fichas_escenas,
            "jornada": getattr(doc, "jornadas", None), "gasto": getattr(doc, "gastos", None),
            "documento": getattr(doc, "documentos_legales", None),
            "plano": getattr(doc, "planos", None)}.get(tipo)


