_DIAS_IA = ["lunes", "martes", "miercoles", "jueves", "viernes", "sabado", "domingo"]


def fecha_ia(texto, hoy: Optional[date] = None) -> str:
    """Una fecha dicha de cualquier forma → «AAAA-MM-DD» («» si no lo es):
    «2026-12-05», «5/12/2026», «5 de diciembre», «el lunes», «mañana»."""
    t = str(texto or "").strip()
    if not t:
        return ""
    hoy = hoy or date.today()
    d = _fecha_iso(t[:10])
    if d:
        return d.isoformat()
    f = fecha_desde_texto(t)
    if f:
        return f
    n = _norm_ia(t)
    m_ = re.search(r"\b(\d{1,2})\s+(?:de\s+)?(" + "|".join(_MESES_IA) + r")\b(?:\s+(?:de\s+|del\s+)?(\d{4}))?", n)
    if m_:
        dia, mes = int(m_.group(1)), _MESES_IA[m_.group(2)]
        anio = int(m_.group(3)) if m_.group(3) else hoy.year
        try:
            d = date(anio, mes, dia)
        except ValueError:
            return ""
        if not m_.group(3) and d < hoy:
            try:
                d = date(anio + 1, mes, dia)
            except ValueError:
                return ""
        return d.isoformat()
    if re.search(r"\bpasado\s+manana\b", n):
        return (hoy + timedelta(days=2)).isoformat()
    if re.search(r"\bmanana\b", n):
        return (hoy + timedelta(days=1)).isoformat()
    if re.search(r"\bhoy\b", n):
        return hoy.isoformat()
    for k, nombre in enumerate(_DIAS_IA):
        if re.search(r"\b" + nombre + r"\b", n):
            delta = (k - hoy.weekday()) % 7 or 7
            if re.search(r"\b(?:proximo|siguiente|que\s+viene)\b", n) and delta < 7 and \
                    re.search(r"\bsemana\b", n):
                delta += 7
            return (hoy + timedelta(days=delta)).isoformat()
    return ""


def hora_ia(texto) -> str:
    """«8», «8:30», «08.30 hrs», «2 pm», «9 de la mañana» → «HH:MM» («» si no es una hora)."""
    t = str(texto or "").lower()
    m_ = re.search(r"(\d{1,2})(?:\s*[:.h]\s*(\d{2}))?\s*(?:hrs?|horas)?\s*"
                   r"(a\.?\s?m\.?|p\.?\s?m\.?|de la tarde|de la noche|de la ma[nñ]ana|de la madrugada)?", t)
    if not m_:
        return ""
    h, mi = int(m_.group(1)), int(m_.group(2) or 0)
    suf = (m_.group(3) or "").replace(" ", "").replace(".", "")
    if suf in ("pm", "delatarde", "delanoche") and h < 12:
        h += 12
    elif suf == "am" and h == 12:
        h = 0
    if not (0 <= h <= 23 and 0 <= mi <= 59):
        return ""
    return f"{h:02d}:{mi:02d}"


def _monto_ia(v: str) -> str:
    """«50 mil», «$1.200.000», «45.000 por día» → «50000», «1200000», «45000»."""
    nums = _numeros_ia(v, partes=False)
    return next(iter(nums)) if len(nums) == 1 else str(v or "").strip()


def _si_no_ia(v) -> Optional[bool]:
    if isinstance(v, bool):
        return v
    n = _norm_ia(v)
    if n in ("si", "s", "true", "1", "pagado", "pagada", "hecho", "hecha", "listo", "lista", "exento",
             "sin iva", "verdadero", "yes", "ok"):
        return True
    if n in ("no", "n", "false", "0", "pendiente", "por pagar", "falso", "con iva", ""):
        return False
    return None


def _items_lista_ia(v: str, por_y: bool = False) -> list[str]:
    partes = re.split(r"[,;\n]" + (r"|\s+y\s+|\s+e\s+" if por_y else ""), str(v or ""))
    return [" ".join(x.split()) for x in partes if x.strip()]


def _buscar_jornada_ia(doc, cual: str):
    """La jornada nombrada: por su nombre, su número en la lista, una fecha
    que cae en ella o su locación (si es una sola)."""
    jor = list(getattr(doc, "jornadas", []) or [])
    c = _norm_ia(cual)
    if not c or not jor:
        return None
    nombres = {id(j): _norm_ia(j.nombre) for j in jor}
    hay = [j for j in jor if nombres[id(j)] == c]
    if len(hay) == 1:
        return hay[0]
    hay = [j for j in jor if nombres[id(j)].startswith(c + " ")]
    if len(hay) == 1:
        return hay[0]
    m_ = re.fullmatch(r"(?:la\s+)?(?:jornada\s*)?(?:n(?:umero)?\s*)?(\d+)", c)
    if m_ and 1 <= int(m_.group(1)) <= len(jor):
        return jor[int(m_.group(1)) - 1]
    f = fecha_ia(cual)
    if f:
        hay = [j for j in jor if j.fecha and j.fecha <= f <= (j.fecha_fin or j.fecha)]
        if len(hay) == 1:
            return hay[0]
    hay = [j for j in jor if j.lugar and _norm_ia(j.lugar) == c]
    if len(hay) == 1:
        return hay[0]
    return None


def _buscar_en_lista_ia(lista: list, cual: str, campos: tuple):
    """El dict de la lista cuyo campo (el primero que calce) es «cual»."""
    for campo in campos:
        nombres = [str(x.get(campo, "") or "") for x in lista if isinstance(x, dict)]
        k_ = _buscar_nombre_ia(cual, [n_ for n_ in nombres if n_])
        if k_ is not None:
            hay = [x for x in lista if isinstance(x, dict) and str(x.get(campo, "") or "") == k_]
            if len(hay) == 1:
                return hay[0]
    return None


def _escena_y_plano_ia(cual: str) -> tuple[int, str]:
    """«escena 3 plano 2B», «plano 2 de la escena 3», «3.2» → (3, «2B»)."""
    t = str(cual or "").lower()
    me = re.search(r"esc(?:ena)?\.?\s*(\d+)", t)
    mp = re.search(r"plano\s*(?:n[°º.]?\s*)?(\d+\s*[a-z]?)\b", t)
    if me:
        return int(me.group(1)), (mp.group(1).replace(" ", "").upper() if mp else "")
    nums = re.findall(r"(\d+)\s*([a-z]?)\b", t)
    if len(nums) >= 2:
        return int(nums[0][0]), (nums[1][0] + nums[1][1]).upper()
    if len(nums) == 1:
        return int(nums[0][0]), ""
    return 0, ""


class _LineaPresupuestoIA:
    """Una línea del presupuesto (automática o a mano), para que el
    Profesor marque su pago, sus notas, su categoría o «sin IVA»."""

    def __init__(self, doc, linea: dict):
        object.__setattr__(self, "_doc", doc)
        object.__setattr__(self, "_l", dict(linea))
        object.__setattr__(self, "_fecha_previa", "")

    def _pago(self) -> dict:
        return (getattr(self._doc, "pagos", {}) or {}).get(self._l["clave"]) or {}

    def _gasto(self) -> Optional[dict]:
        if self._l.get("origen") != "manual":
            return None
        return next((g for g in (getattr(self._doc, "gastos", []) or [])
                     if isinstance(g, dict) and str(g.get("id", "")) == str(self._l.get("ref", ""))), None)

    def __getattr__(self, campo):
        if campo.startswith("_"):
            raise AttributeError(campo)
        if campo == "pagado":
            return "sí" if self._pago().get("pagado") else "no"
        if campo == "fecha_pago":
            return str(self._pago().get("fecha_pago", "") or "")
        if campo == "notas_pago":
            return str(self._pago().get("notas", "") or "")
        if campo == "categoria":
            g = self._gasto()
            if g is not None:
                return str(g.get("categoria") or "Otros")
            movida = (getattr(self._doc, "categoria_lineas", {}) or {}).get(self._l["clave"])
            return movida or self._l.get("categoria_auto") or self._l.get("categoria", "")
        if campo == "sin_iva":
            g = self._gasto()
            if g is not None:
                return "sí" if g.get("sin_iva") else "no"
            return "sí" if linea_exenta_iva(self._doc, self._l["clave"], self.categoria) else "no"
        raise AttributeError(campo)

    def __setattr__(self, campo, valor) -> None:
        doc, clave = self._doc, self._l["clave"]
        if campo == "pagado":
            si = valor == "sí"
            if not si:
                object.__setattr__(self, "_fecha_previa", self.fecha_pago)
            marcar_pago(doc, clave, si, (self._fecha_previa or "") if si else "")
        elif campo == "fecha_pago":
            nota_pago(doc, clave, fecha=str(valor or ""))
        elif campo == "notas_pago":
            nota_pago(doc, clave, notas=str(valor or ""))
        elif campo == "categoria":
            l = dict(self._l, categoria=self.categoria)
            if self._gasto() is not None:
                l["origen"], l["ref"] = "manual", self._gasto().get("id", "")
            mover_linea_a_categoria(doc, l, str(valor or "Otros"))
        elif campo == "sin_iva":
            g = self._gasto()
            if g is not None:
                if valor == "sí":
                    g["sin_iva"] = True
                else:
                    g.pop("sin_iva", None)
            else:
                poner_exento_iva(doc, clave, self.categoria, valor == "sí")
        else:
            object.__setattr__(self, campo, valor)


def _normalizar_valor_cambio_ia(doc, tipo: str, campo: str, valor: str, pedido: str):
    """El valor que dio la IA, en la forma que usa el programa. Devuelve
    (valor, aviso): con aviso, el dato no se cambia."""
    v = str(valor if valor is not None else "").strip()
    et = TIPOS_CAMBIO_IA[tipo][2].get(campo, campo)
    if (tipo, campo) in SI_NO_CAMBIO_IA or (tipo == "linea" and campo in ("pagado", "sin_iva")):
        b = _si_no_ia(v)
        if b is None:
            return None, f"No entendí si «{v[:40]}» es sí o no ({et})."
        return (("sí" if b else "no") if tipo == "linea" else b), ""
    if campo in ("fecha", "fecha_fin", "fecha_pago", "firma", "vence") and v:
        f = fecha_ia(v)
        return (f, "") if f else (None, f"No entendí la fecha «{v[:40]}» ({et}).")
    if campo == "hora_citacion" and v:
        h = hora_ia(v)
        return (h, "") if h else (None, f"No entendí la hora «{v[:40]}».")
    if campo in ("valor", "monto", "presupuesto_fondos", "cantidad", "iva_tasa") and v:
        m_ = _monto_ia(v) if campo != "iva_tasa" else (re.search(r"\d+(?:[.,]\d+)?", v) or [v])[0]
        return str(m_).replace(",", "."), ""
    if campo == "iva_modo":
        n = _norm_ia(v)
        modo = ("incluido" if "inclu" in n else "aparte" if ("aparte" in n or "neto" in n or "mas" in n)
                else "" if (not n or "sin" in n or n == "no") else None)
        return (modo, "") if modo is not None else (None, f"No entendí cómo se escriben los valores: «{v[:40]}».")
    if campo == "cuando" and tipo == "gasto":
        n = _norm_ia(v)
        if not n:
            return "", ""
        if "jornada" in n or "rodaje" in n or "cada dia" in n:
            return "jornadas", ""
        f = fecha_ia(v)
        return (f, "") if f else (None, f"No entendí cuándo es el gasto («{v[:40]}»).")
    if campo == "categoria":
        return (nombre_categoria(doc, v) or "Otros"), ""
    if campo == "tipo" and tipo == "documento":
        k_ = _buscar_nombre_ia(v, [t_ for t_, _i in TIPOS_DOC_LEGAL])
        return (k_ or "Otro"), ""
    if campo == "estado" and tipo == "documento":
        k_ = _buscar_nombre_ia(v, ESTADOS_DOC_LEGAL)
        return (k_, "") if k_ else (None, f"«{v[:30]}» no es un estado de documento ("
                                          f"{', '.join(ESTADOS_DOC_LEGAL)}).")
    if tipo == "plano" and campo in ("tamano", "angulo", "movimiento") and v:
        lista = {"tamano": TAMANOS_PLANO, "angulo": ANGULOS_PLANO, "movimiento": MOVIMIENTOS_PLANO}[campo]
        k_ = _buscar_nombre_ia(v, [x for x in lista if x])
        if k_ is None:                                   # («PP», «PG»: la sigla entre paréntesis)
            k_ = next((x for x in lista if x and re.search(r"\(" + re.escape(v.upper()) + r"\)", x)), None)
        return (k_ or v), ""
    if tipo == "jornada" and campo in ("lugar", "lugar_2") and v:
        k_ = _buscar_nombre_ia(v, list((doc.locaciones or {}).keys()))
        return (k_ or v), ""
    return v, ""


def _lista_cambio_ia(doc, campo: str, antes: str, valor: str, agregar: bool, quitar: bool,
                     pedido: str, avisos: list) -> str:
    """Escenas, actores, crew o equipamiento de una jornada: los nombres,
    revisados contra lo que existe, sumados, sacados o reemplazados."""
    if campo == "escenas":
        total = len(_escenas_cambio_ia(doc))
        ya = [str(n_) for n_ in _escenas_de_jornada(Jornada(escenas=antes))]
        nuevos = []
        for x in _items_lista_ia(valor, por_y=True):
            m_ = re.search(r"\d+", x)
            if not m_:
                continue
            n_ = int(m_.group(0))
            if total and not 1 <= n_ <= total:
                avisos.append(f"La escena {n_} no existe (el guion tiene {total}).")
                continue
            nuevos.append(str(n_))
    else:
        ya = [x.strip() for x in str(antes or "").split(",") if x.strip()]
        if campo == "actores":
            cands = list((doc.fichas or {}).keys())
            cands += [n_ for n_ in personajes_del_documento(doc) if n_ not in cands]
        elif campo == "tecnicos":
            cands = [t.nombre for t in (doc.tecnicos or []) if t.nombre]
        else:
            cands = [e_.nombre for e_ in (doc.equipamiento or []) if e_.nombre]
        nuevos = []
        for x in _items_lista_ia(valor, por_y=(campo == "actores")):
            k_ = _buscar_nombre_ia(x, cands)
            if k_ is None and campo == "tecnicos":
                roles = [t for t in (doc.tecnicos or []) if t.nombre and _norm_ia(t.rol) == _norm_ia(x)]
                k_ = roles[0].nombre if len(roles) == 1 else None
            if k_ is None and campo == "equipamiento":
                mods = [e_ for e_ in (doc.equipamiento or []) if e_.nombre and _norm_ia(e_.modelo) == _norm_ia(x)]
                k_ = mods[0].nombre if len(mods) == 1 else None
            if k_ is None and quitar:
                k_ = _buscar_nombre_ia(x, ya)
            if k_ is None:
                if dato_en_pedido_ia(x, pedido):
                    k_ = x.upper() if campo == "actores" else x
                    if campo != "actores":
                        avisos.append(f"«{x}» no está en {'el crew' if campo == 'tecnicos' else 'el equipamiento'}"
                                      ": agrégalo ahí para que su valor entre al presupuesto.")
                else:
                    avisos.append(f"No encontré «{x}» ({TIPOS_CAMBIO_IA['jornada'][2][campo]}).")
                    continue
            nuevos.append(k_)
    if quitar:
        fuera = {x.casefold() for x in nuevos}
        res = [x for x in ya if x.casefold() not in fuera]
    elif agregar:
        res = ya + [x for x in nuevos if x.casefold() not in {y.casefold() for y in ya}]
    else:
        res = nuevos
    if campo == "escenas":
        res = sorted(dict.fromkeys(res), key=lambda x: int(x))
        return ", ".join(res)
    return _csv_de_lista(res)


def _completar_jornadas_plan_ia(doc, plan: dict) -> None:
    """Después de leer los cambios de la Carta Gantt: la fecha de término
    se corre con la de inicio, una jornada nueva recibe su nombre, y
    quienes hablan en las escenas agregadas quedan en la jornada (con su
    ficha, si no la tenían), como al crearla a mano."""
    nuevas = 0
    for e in plan["entradas"]:
        if e["tipo"] != "jornada" or e["accion"] == "borrar":
            continue
        obj = e.get("obj")
        et = TIPOS_CAMBIO_IA["jornada"][2]
        campos = {c[0]: c for c in e["campos"]}

        def poner(campo, valor):
            antes = str(getattr(obj, campo, "") or "") if obj is not None else ""
            previo = campos.get(campo)
            if previo is not None:
                e["campos"].remove(previo)
                antes = previo[2]
            if valor != antes:
                t = (campo, et[campo], antes, valor)
                e["campos"].append(t)
                campos[campo] = t
            else:
                campos.pop(campo, None)
        if e.get("nuevo"):
            nuevas += 1
            if not e["clave"] or e["clave"] == "?":
                lugar = campos.get("lugar", (0, 0, 0, ""))[3]
                e["clave"] = f"Jornada {len(doc.jornadas) + nuevas}" + (f" — {lugar.title()}" if lugar else "")
            if "fecha" not in campos:
                plan["avisos"].append(f"«{e['clave']}» queda sin fecha: dime cuándo para verla en la Carta Gantt.")
        ini = _fecha_iso(campos["fecha"][3]) if "fecha" in campos else None
        if ini and "fecha_fin" not in campos:
            d0 = _fecha_iso(getattr(obj, "fecha", "") or "") if obj is not None else None
            d1 = _fecha_iso(getattr(obj, "fecha_fin", "") or "") if obj is not None else None
            fin = ini + (d1 - d0) if (d0 and d1 and d1 >= d0) else ini
            poner("fecha_fin", fin.isoformat())
        f0 = campos["fecha"][3] if "fecha" in campos else (getattr(obj, "fecha", "") if obj is not None else "")
        f1 = campos["fecha_fin"][3] if "fecha_fin" in campos else (
            getattr(obj, "fecha_fin", "") if obj is not None else "")
        if f0 and f1 and f1 < f0:
            plan["avisos"].append(f"En «{e['clave']}» el término quedaba antes del inicio: la dejé de un día.")
            poner("fecha_fin", f0)
        # quienes hablan en las escenas nuevas
        if "escenas" in campos:
            antes_esc = set(_escenas_de_jornada(obj)) if obj is not None else set()
            ahora = _escenas_de_jornada(Jornada(escenas=campos["escenas"][3]))
            nuevas_esc = [n_ for n_ in ahora if n_ not in antes_esc]
            act = campos["actores"][3] if "actores" in campos else (
                getattr(obj, "actores", "") if obj is not None else "")
            fuera = set(e.get("quitados", set()))
            ya = {x.upper() for x in _parse_csv_nombres(act)}
            sumar = [p_ for p_ in hablantes_de_escenas(doc, nuevas_esc) if p_ not in ya and p_ not in fuera]
            if sumar:
                poner("actores", _csv_de_lista([x.strip() for x in str(act or "").split(",") if x.strip()] + sumar))
                e["hablantes"] = sumar
        if "actores" in campos:
            claves = {k.upper() for k in (doc.fichas or {})}
            hablan = {p_.upper() for p_ in hablantes_de_escenas(doc, _escenas_de_jornada(
                Jornada(escenas=campos["escenas"][3] if "escenas" in campos else getattr(obj, "escenas", "")))) }
            e["fichas_nuevas"] = [p_ for p_ in _parse_csv_nombres(campos["actores"][3])
                                  if p_ not in claves and p_ in hablan]


def _escenas_cambio_ia(doc) -> list:
    try:
        return [(int(e["numero"]), str(e.get("encabezado") or "")) for e in segmentar_escenas(doc)]
    except Exception:
        return []


_TEMAS_CAMBIO_IA = {
    "presupuesto": r"gasto|presupuesto|pag[oa]|categor|\biva\b|fondo|monto|costo|valor|boleta|factur|exent",
    "documentos": r"contrato|seguro|permiso|documento|poliza|autorizaci|licencia|cesion|firma|vence|vencimiento",
    "planos": r"plano|toma|lente|encuadre|movimiento|angulo|shot|cenital|picado|travelling|steadicam",
}


def produccion_para_cambios_ia(doc, pedido: str = "") -> str:
    """La Carta Gantt (siempre) y, si el pedido habla de ellos, el
    presupuesto, los contratos y la lista de planos, resumidos para la IA."""
    def corto(s, n=80):
        s = " ".join(str(s or "").split())
        return s if len(s) <= n else s[:n - 1] + "…"
    n = _norm_ia(pedido)
    lineas = []
    jor = list(getattr(doc, "jornadas", []) or [])
    lineas.append("JORNADAS (Carta Gantt):" if jor else "JORNADAS (Carta Gantt): (ninguna)")
    for k, j in enumerate(jor[:40], 1):
        partes = [f"{j.fecha or 'sin fecha'}" + (f" al {j.fecha_fin}" if j.fecha_fin and j.fecha_fin != j.fecha
                                                 else "")]
        for et, v in (("citación", j.hora_citacion), ("locación", j.lugar), ("2.ª locación", j.lugar_2),
                      ("escenas", j.escenas), ("actores", j.actores), ("crew", j.tecnicos),
                      ("equipamiento", j.equipamiento), ("notas", j.notas)):
            if str(v or "").strip():
                partes.append(f"{et} {corto(v, 120)}")
        lineas.append(f"{k}. «{j.nombre or f'Jornada {k}'}»: " + " · ".join(partes))
    if re.search(_TEMAS_CAMBIO_IA["presupuesto"], n):
        modo, tasa = config_iva(doc)
        lineas.append("PRESUPUESTO: fondos " + (str(getattr(doc, "presupuesto_fondos", "") or "") or "(sin escribir)")
                      + " · IVA: " + ({"incluido": f"incluido ({tasa * 100:g} %)",
                                       "aparte": f"aparte ({tasa * 100:g} %)"}.get(modo, "sin IVA"))
                      + " · categorías: " + ", ".join(c for c, _i in categorias_de_presupuesto(doc)))
        try:
            ls = lineas_presupuesto(doc)
        except Exception:
            ls = []
        for l_ in ls[:50]:
            lineas.append(f"- «{texto_sin_emoji(l_['concepto']).strip()}» [{l_['categoria']}] "
                          f"{fmt_moneda(l_['total'])}" + (" · a mano" if l_["origen"] == "manual" else "")
                          + (" · pagado" if l_["pagado"] else "") + (" · sin IVA" if l_.get("exento") else ""))
    if re.search(_TEMAS_CAMBIO_IA["documentos"], n):
        docs = [d for d in (getattr(doc, "documentos_legales", []) or []) if isinstance(d, dict)]
        lineas.append("CONTRATOS Y SEGUROS:" if docs else "CONTRATOS Y SEGUROS: (ninguno)")
        for d in docs[:30]:
            lineas.append(f"- «{d.get('titulo') or d.get('tipo')}» ({d.get('tipo', '')}, {d.get('estado', '')}"
                          + (f", firma {d['firma']}" if d.get("firma") else "")
                          + (f", vence {d['vence']}" if d.get("vence") else "")
                          + (f", monto {d['monto']}" if d.get("monto") else "") + ")")
    if re.search(_TEMAS_CAMBIO_IA["planos"], n):
        pls = [p_ for p_ in (getattr(doc, "planos", []) or []) if isinstance(p_, dict)]
        lineas.append("LISTA DE PLANOS:" if pls else "LISTA DE PLANOS: (vacía)")
        for p_ in pls[:60]:
            datos = " · ".join(str(p_.get(c) or "") for c in ("tamano", "angulo", "movimiento", "lente")
                               if str(p_.get(c) or "").strip())
            lineas.append(f"- escena {p_.get('escena')} plano {p_.get('numero')}: {datos}"
                          + (f" — {corto(p_.get('descripcion'), 60)}" if p_.get("descripcion") else "")
                          + (" (hecho)" if p_.get("hecho") else ""))
    return "\n".join(lineas)


def fichas_para_cambios_ia(doc, cabe: int = 6000, pedido: str = "") -> str:
    """Lo que hay en las fichas, resumido para la IA (para que sepa qué existe)."""
    def corto(s, n=110):
        s = " ".join(str(s or "").split())
        return s if len(s) <= n else s[:n - 1] + "…"
    produccion = produccion_para_cambios_ia(doc, pedido)
    cabe = max(1200, cabe - len(produccion) - 1)
    lineas = []
    nombres = list((doc.fichas or {}).keys())
    for n_ in personajes_del_documento(doc):
        if n_ not in nombres:
            nombres.append(n_)
    lineas.append("PERSONAJES:" if nombres else "PERSONAJES: (ninguno)")
    for n_ in nombres[:40]:
        f = (doc.fichas or {}).get(n_)
        datos = []
        if f is not None:
            for c, et in TIPOS_CAMBIO_IA["personaje"][2].items():
                v = _leer_dato_ia(f, c)
                if v and isinstance(v, str) and not (c == "alimentacion" and v == "Omnívoro"):
                    datos.append(f"{et}: {corto(v, 70 if c not in ('biografia',) else 110)}")
        lineas.append(f"- {n_}" + (": " + "; ".join(datos[:8]) if datos else " (ficha vacía)"))
    locs = list((doc.locaciones or {}).keys())
    lineas.append("LOCACIONES: " + (", ".join(locs[:30]) if locs else "(ninguna)"))
    crew = [f"{t.nombre or '?'} ({t.rol or 'sin rol'})" for t in (doc.tecnicos or [])]
    lineas.append("CREW: " + (", ".join(crew[:30]) if crew else "(nadie)"))
    eq = [e.nombre or "?" for e in (doc.equipamiento or [])]
    lineas.append("EQUIPAMIENTO: " + (", ".join(eq[:30]) if eq else "(nada)"))
    esc = _escenas_cambio_ia(doc)
    lineas.append("ESCENAS:" if esc else "ESCENAS: (ninguna)")
    for k, enc in esc[:60]:
        lineas.append(f"- {k}. {corto(enc, 60)}")
    lineas.append("PREMISA: " + (corto(doc.premisa, 300) or "(sin premisa)"))
    lineas.append("TÍTULO: " + (corto(getattr(doc, "titulo", ""), 80) or "(sin título)"))
    t = "\n".join(lineas)
    t = t if len(t) <= cabe else t[:cabe - 1] + "…"
    return t + "\n" + produccion


def mensajes_cambios_ia(doc, historial: list, pedido: str, num_ctx: int) -> list:
    cabe = int(num_ctx * 3.0 * 0.55)
    datos = fichas_para_cambios_ia(doc, max(1500, cabe - len(PROMPT_CAMBIOS_IA) - len(pedido) - 900), pedido)
    previo = ""
    for m_ in historial[-4:]:
        quien = "PERSONA" if m_.get("role") == "user" else "PROFESOR"
        previo += f"{quien}: {' '.join(str(m_.get('content', '')).split())[:300]}\n"
    hoy = date.today()
    usuario = (f"HOY: {hoy.isoformat()} ({_DIAS_IA[hoy.weekday()].replace('miercoles', 'miércoles').replace('sabado', 'sábado')})\n\n"
               f"FICHAS Y PRODUCCIÓN ACTUALES:\n{datos}\n\n"
               + (f"CONVERSACIÓN RECIENTE:\n{previo}\n" if previo else "")
               + f"LO QUE PIDE AHORA: {pedido}")
    return [{"role": "system", "content": PROMPT_CAMBIOS_IA}, {"role": "user", "content": usuario}]


def _valor_alimentacion_ia(v: str) -> str:
    n = _norm_ia(v)
    if "vegan" in n:
        return "Vegano"
    if "vegetar" in n:
        return "Vegetariano"
    if "omni" in n or "todo" in n or "normal" in n:
        return "Omnívoro"
    return "Otro"


def planear_cambios_ia(doc, datos, pedido: str) -> dict:
    """Lo que respondió la IA, revisado: qué ficha, qué dato y qué valor
    (sin inventar datos reales ni tocar lo que no existe). Devuelve
    {"entradas": [...], "avisos": [...], "respuesta": str, "doc": doc}."""
    plan = {"entradas": [], "avisos": [], "respuesta": "", "doc": doc}
    if not isinstance(datos, dict):
        plan["avisos"].append("No entendí la respuesta de la IA. ¿Me lo pides de otra forma?")
        return plan
    plan["respuesta"] = " ".join(str(datos.get("respuesta") or "").split())[:400]
    cambios = datos.get("cambios")
    if not isinstance(cambios, list):
        return plan
    por_clave: dict = {}
    escenas = _escenas_cambio_ia(doc)

    def entrada(tipo, accion, clave, obj, nuevo=False):
        k = (tipo, id(obj) if obj is not None else ("nuevo", _norm_ia(clave)))
        e = por_clave.get(k)
        if e is None:
            e = {"tipo": tipo, "accion": accion, "clave": clave, "obj": obj, "nuevo": nuevo, "campos": []}
            por_clave[k] = e
            plan["entradas"].append(e)
        elif accion == "borrar":
            e["accion"] = "borrar"
        return e
    for c in cambios[:40]:
        if not isinstance(c, dict):
            continue
        tipo = _norm_ia(c.get("tipo")).replace(" ", "_")
        tipo = _ALIAS_TIPO_IA.get(tipo, tipo)
        if tipo not in TIPOS_CAMBIO_IA:
            continue
        emoji, nom_tipo, campos, reales = TIPOS_CAMBIO_IA[tipo]
        accion = _norm_ia(c.get("accion")) or "cambiar"
        accion = {"modificar": "cambiar", "agregar": "cambiar", "eliminar": "borrar", "quitar": "borrar",
                  "nuevo": "crear", "nueva": "crear"}.get(accion, accion)
        if accion not in ("cambiar", "crear", "borrar"):
            accion = "cambiar"
        cual = " ".join(str(c.get("cual") or "").split())[:80]
        campo = _norm_ia(c.get("campo")).replace(" ", "_")
        campo = _ALIAS_CAMPO_IA.get(tipo, {}).get(campo, campo)
        valor = str(c.get("valor") if c.get("valor") is not None else "").strip()[:4000]
        agregar = bool(c.get("agregar"))
        quitar = bool(c.get("quitar"))
        crear_ok = accion == "crear" or bool(re.search(
            r"\b(?:agreg|anad|crea|sum|inclu|anot|registr|ingres|nuev)", _norm_ia(pedido)))
        # ── ¿Qué ficha? ──
        obj, clave, nuevo = None, cual, False
        if tipo == "proyecto":
            obj, clave = doc, "proyecto"
            if accion == "borrar":
                continue
        elif tipo == "escena":
            m_ = re.search(r"\d+", cual)
            num = int(m_.group(0)) if m_ else 0
            if not m_:
                k_ = _buscar_nombre_ia(cual, [enc for _n, enc in escenas])
                num = next((n_ for n_, enc in escenas if enc == k_), 0)
            if not any(n_ == num for n_, _e in escenas):
                plan["avisos"].append(f"No encontré la escena «{cual}»." if cual else
                                      "No supe de qué escena se trata: dime su número.")
                continue
            if accion == "borrar":
                plan["avisos"].append("Las fichas de escena no se borran desde aquí (puedes vaciar un dato).")
                continue
            clave = str(num)
            obj = doc.fichas_escenas.get(clave)
            if isinstance(obj, FichaEscena):
                obj = asdict(obj)
                doc.fichas_escenas[clave] = obj
            if not isinstance(obj, dict):
                obj, nuevo = None, True
        elif tipo == "jornada":
            obj = _buscar_jornada_ia(doc, cual) if cual else None
            if obj is not None and accion == "crear" and _norm_ia(obj.nombre) != _norm_ia(cual):
                obj = None                               # (crear «Jornada 3» no es cambiar la tercera)
            if obj is None:
                if accion != "crear":
                    plan["avisos"].append(f"No encontré la jornada «{cual}» en la Carta Gantt." if cual else
                                          "No supe de qué jornada se trata: dime su nombre o su fecha.")
                    continue
                nuevo, clave = True, (cual or "?")
            else:
                clave = obj.nombre or cual
        elif tipo in ("gasto", "documento"):
            lista = list(_contenedor_cambio_ia(doc, tipo) or [])
            obj = _buscar_en_lista_ia(lista, cual, ("concepto",) if tipo == "gasto" else ("titulo", "tipo")) \
                if cual else None
            if obj is None:
                if accion == "borrar" or not crear_ok:
                    plan["avisos"].append(f"No encontré «{cual}» entre {'los gastos ingresados a mano' if tipo == 'gasto' else 'los documentos de Contratos y seguros'}."
                                          if cual else f"No supe de qué {nom_tipo} se trata.")
                    continue
                if not cual:
                    plan["avisos"].append(f"Dime {'el concepto del gasto' if tipo == 'gasto' else 'el nombre del documento'}.")
                    continue
                nuevo, clave = True, cual
            else:
                clave = str(obj.get("concepto" if tipo == "gasto" else "titulo") or cual)
        elif tipo == "linea":
            if accion != "cambiar":
                plan["avisos"].append("Las líneas automáticas del presupuesto se quitan en su ficha, tag o "
                                      "documento; un gasto a mano, como «gasto».")
                continue
            if "_lineas" not in plan:
                plan["_lineas"] = lineas_presupuesto(doc)
            cands = {}
            for l_ in plan["_lineas"]:
                cands.setdefault(texto_sin_emoji(l_["concepto"]).strip(), l_)
                if l_["origen"] == "ficha":
                    cands.setdefault(l_["clave"].partition(":")[2], l_)
            for e_ in plan["entradas"]:                  # (un gasto que se crea en este mismo pedido)
                if e_["tipo"] == "gasto" and e_.get("nuevo"):
                    cands.setdefault(e_["clave"], {"clave": f"gasto:{e_['id']}", "origen": "manual",
                                                   "ref": e_["id"], "categoria": "Otros",
                                                   "concepto": e_["clave"]})
            k_ = _buscar_nombre_ia(cual, list(cands))
            if k_ is None:
                plan["avisos"].append(f"No encontré «{cual}» en el presupuesto." if cual else
                                      "No supe de qué gasto del presupuesto se trata.")
                continue
            l_ = cands[k_]
            obj = plan.setdefault("_adapt", {}).get(l_["clave"])
            if obj is None:
                obj = plan["_adapt"][l_["clave"]] = _LineaPresupuestoIA(doc, l_)
            clave = texto_sin_emoji(l_["concepto"]).strip()
        elif tipo == "plano":
            esc, num = _escena_y_plano_ia(cual)
            if not any(n_ == esc for n_, _e in escenas):
                plan["avisos"].append(f"No encontré la escena del plano «{cual}»." if cual else
                                      "Dime de qué escena es el plano.")
                continue
            obj = next((p_ for p_ in (getattr(doc, "planos", []) or []) if isinstance(p_, dict)
                        and int(p_.get("escena", 0) or 0) == esc
                        and str(p_.get("numero", "")).replace(" ", "").upper() == num), None) if num else None
            if obj is None:
                if accion == "borrar" or not (accion == "crear" or (crear_ok and not num)):
                    plan["avisos"].append(f"No encontré el plano {num} de la escena {esc}." if num else
                                          f"¿Qué plano de la escena {esc}? Dime su número.")
                    continue
                nuevo, clave = True, f"escena {esc} · plano nuevo"
            else:
                clave = f"escena {esc} · plano {obj.get('numero', '')}"
        else:
            cont = _contenedor_cambio_ia(doc, tipo)
            if isinstance(cont, dict):
                cands = list(cont.keys())
                if tipo == "personaje":
                    cands += [n_ for n_ in personajes_del_documento(doc) if n_ not in cands]
                k_ = _buscar_nombre_ia(cual, cands)
                if k_ is not None:
                    clave, obj = k_, cont.get(k_)
                    nuevo = obj is None                       # (está en el guion, todavía sin ficha)
            else:
                lista = list(cont or [])
                k_ = _buscar_nombre_ia(cual, [getattr(x, "nombre", "") or "" for x in lista])
                if k_ is None and tipo == "crew":
                    k_ = _buscar_nombre_ia(cual, [x.rol or "" for x in lista])
                    obj = next((x for x in lista if (x.rol or "") == k_), None) if k_ else None
                elif k_ is None and tipo == "equipamiento":
                    k_ = _buscar_nombre_ia(cual, [x.modelo or "" for x in lista])
                    obj = next((x for x in lista if (x.modelo or "") == k_), None) if k_ else None
                else:
                    obj = next((x for x in lista if (x.nombre or "") == k_), None) if k_ else None
                if obj is not None:
                    clave = obj.nombre or k_ or cual
            if obj is None and not nuevo:
                if accion == "borrar":
                    plan["avisos"].append(f"No encontré «{cual}»: no borré nada.")
                    continue
                if not cual:
                    plan["avisos"].append(f"No supe de qué {nom_tipo} se trata: dime el nombre.")
                    continue
                if tipo == "crew" and not dato_en_pedido_ia(cual, pedido):
                    plan["avisos"].append(f"No agregué a «{cual}» al crew: ese nombre no estaba en tu mensaje "
                                          "(no invento personas reales).")
                    continue
                nuevo = True
                clave = cual.upper() if tipo == "personaje" else cual
            if nuevo and tipo == "personaje":
                clave = clave.upper()
        if accion == "borrar":
            if nuevo or obj is None:
                continue
            entrada(tipo, "borrar", clave, obj)
            continue
        e = entrada(tipo, "crear" if nuevo else "cambiar", clave, obj, nuevo)
        if nuevo and tipo == "gasto":
            e.setdefault("id", nuevo_id_corto())
        if nuevo and tipo == "plano":
            e.setdefault("escena_plano", _escena_y_plano_ia(cual)[0])
        if not campo and not valor:
            continue
        if campo not in campos:
            if campo or valor:
                plan["avisos"].append(f"No sé dónde va «{c.get('campo') or valor[:40]}» en la {nom_tipo}.")
            continue
        if campo in reales and not dato_en_pedido_ia(valor, pedido):
            plan["avisos"].append(f"No puse {campos[campo]} «{valor[:60]}» en {clave}: no estaba en tu mensaje "
                                  "(no invento datos de personas reales ni montos).")
            continue
        if tipo in ("jornada", "gasto", "linea", "documento", "plano", "proyecto"):
            valor, aviso_ = _normalizar_valor_cambio_ia(doc, tipo, campo, valor, pedido)
            if aviso_:
                plan["avisos"].append(aviso_)
                continue
        if isinstance(valor, bool):                      # (sí / no)
            antes_b = bool(_leer_dato_ia(obj, campo)) if obj is not None else False
            e["campos"] = [x for x in e["campos"] if x[0] != campo]
            if antes_b != valor:
                e["campos"].append((campo, campos[campo], antes_b, valor))
            continue
        if campo in LISTAS_CAMBIO_IA.get(tipo, ()):
            antes = "" if obj is None else str(_leer_dato_ia(obj, campo) or "")
            previo = next((x for x in e["campos"] if x[0] == campo), None)
            base = previo[3] if previo is not None else antes
            if previo is not None:
                e["campos"].remove(previo)
            despues = _lista_cambio_ia(doc, campo, base, valor, agregar, quitar, pedido, plan["avisos"])
            if quitar and campo == "actores":
                e.setdefault("quitados", set()).update(x.upper() for x in _items_lista_ia(valor, por_y=True))
            if despues != antes:
                e["campos"].append((campo, campos[campo], antes, despues))
            continue
        if campo == "alimentacion" and tipo == "personaje" and valor:
            valor = _valor_alimentacion_ia(valor)
        if campo in ("edad",):
            m_ = re.search(r"\d+", valor)
            valor = m_.group(0) if m_ and re.fullmatch(r"\s*\d+\s*(?:a[nñ]os)?\s*", valor, re.I) else valor
        antes = "" if obj is None else str(_leer_dato_ia(obj, campo) or "")
        previo = next((x for x in e["campos"] if x[0] == campo), None)
        if previo is not None:
            e["campos"].remove(previo)
            antes = previo[2]
        despues = valor
        if agregar and antes.strip() and valor:
            despues = antes if _norm_ia(valor) in _norm_ia(antes) else antes.rstrip() + "\n" + valor
        if despues == antes:
            continue
        e["campos"].append((campo, campos[campo], antes, despues))
    _completar_jornadas_plan_ia(doc, plan)
    plan["entradas"] = [e for e in plan["entradas"] if e["accion"] == "borrar" or e["campos"] or
                        (e["nuevo"] and e["tipo"] not in ("escena", "proyecto"))]
    plan["entradas"].sort(key=lambda e: e["tipo"] == "linea")     # (los pagos, después de crear el gasto)
    plan.pop("_lineas", None)
    plan.pop("_adapt", None)
    return plan


def aplicar_cambios_ia(doc, entradas: list) -> list:
    """Hace los cambios. Devuelve lo necesario para deshacerlos."""
    registro = []
    for e in entradas:
        tipo = e["tipo"]
        for attr, t_ in (("jornadas", "jornada"), ("gastos", "gasto"), ("documentos_legales", "documento"),
                         ("planos", "plano")):
            if tipo == t_ and not isinstance(getattr(doc, attr, None), list):
                setattr(doc, attr, [])
        cont = _contenedor_cambio_ia(doc, tipo)
        obj = e.get("obj")
        if e["accion"] == "borrar":
            if isinstance(cont, dict):
                k_ = next((k for k, v in cont.items() if v is obj), None)
                if k_ is not None:
                    del cont[k_]
                    registro.append({"op": "borrar", "tipo": tipo, "clave": k_, "obj": obj})
            elif isinstance(cont, list) and any(x is obj for x in cont):
                i = next(i for i, x in enumerate(cont) if x is obj)
                cont.pop(i)
                registro.append({"op": "borrar", "tipo": tipo, "indice": i, "obj": obj})
            continue
        if e.get("nuevo") or obj is None:
            clave = e["clave"]
            if tipo == "personaje":
                obj = cont.get(clave) or Ficha(personaje=clave)
            elif tipo == "locacion":
                obj = cont.get(clave) or Locacion(nombre=clave)
            elif tipo == "crew":
                obj = Tecnico(nombre=clave)
            elif tipo == "equipamiento":
                obj = Equipamiento(nombre=clave)
            elif tipo == "escena":
                num = int(clave)
                enc = next((en for n_, en in _escenas_cambio_ia(doc) if n_ == num), "")
                obj = cont.get(clave) if isinstance(cont.get(clave), dict) else {"numero": num, "encabezado": enc}
            elif tipo == "jornada":
                obj = Jornada(nombre=clave)
            elif tipo == "gasto":
                obj = {"id": e.get("id") or nuevo_id_corto(), "categoria": "Otros", "concepto": clave,
                       "proveedor": "", "cantidad": "1", "valor": ""}
            elif tipo == "documento":
                obj = {"vinculo": "", "tipo": "Otro", "titulo": clave, "contraparte": "", "estado": "Pendiente",
                       "firma": "", "vence": "", "monto": "", "archivo_nombre": "", "archivo_datos": "",
                       "notas": "", "id": nuevo_id_corto()}
            elif tipo == "plano":
                esc = int(e.get("escena_plano") or 0)
                n_ = max([numero_base_plano(p_.get("numero")) for p_ in cont
                          if isinstance(p_, dict) and int(p_.get("escena", 0) or 0) == esc] or [0]) + 1
                obj = {k: "" for k in CAMPOS_PLANO}
                obj.update(hecho=False, escena=esc, numero=str(n_), dialogo="")
                asegurar_id_plano(obj)
                e["clave"] = f"escena {esc} · plano {n_}"
            if isinstance(cont, dict) and cont.get(clave) is not obj:
                cont[clave] = obj
                registro.append({"op": "crear", "tipo": tipo, "clave": clave, "obj": obj})
            elif isinstance(cont, list):
                if tipo == "plano":
                    _insertar_plano_en_orden(doc, obj)
                else:
                    cont.append(obj)
                registro.append({"op": "crear", "tipo": tipo, "obj": obj})
            e["obj"] = obj
        for campo, _et, _antes, despues in e["campos"]:
            antes = _leer_dato_ia(obj, campo)
            _poner_dato_ia(obj, campo, despues)
            registro.append({"op": "dato", "obj": obj, "campo": campo, "antes": antes, "despues": despues})
            for detalle, marca in (("alergias_detalle", "alergias"), ("movilidad_detalle", "movilidad_reducida")):
                if campo == detalle and not isinstance(obj, dict) and hasattr(obj, marca):
                    a_ = getattr(obj, marca)
                    setattr(obj, marca, bool(str(despues).strip()))
                    registro.append({"op": "dato", "obj": obj, "campo": marca, "antes": a_,
                                     "despues": getattr(obj, marca)})
        if tipo == "jornada":                    # (quienes hablan y no tenían ficha)
            claves = {k.upper() for k in (doc.fichas or {})}
            for p_ in e.get("fichas_nuevas", []) or []:
                if p_.upper() not in claves:
                    f_ = Ficha(personaje=p_)
                    doc.fichas[p_] = f_
                    claves.add(p_.upper())
                    registro.append({"op": "crear", "tipo": "personaje", "clave": p_, "obj": f_})
    return registro


def deshacer_cambios_ia(doc, registro: list) -> tuple:
    """Deja todo como estaba (lo que se cambió después a mano no se toca).
    Devuelve (cuántos se deshicieron, qué no se pudo)."""
    hechos, saltados = 0, []
    for r in reversed(registro):
        cont = _contenedor_cambio_ia(doc, r.get("tipo", "")) if r["op"] != "dato" else None
        if r["op"] == "dato":
            if _leer_dato_ia(r["obj"], r["campo"]) == r["despues"]:
                _poner_dato_ia(r["obj"], r["campo"], r["antes"])
                hechos += 1
            elif r["campo"] not in ("alergias", "movilidad_reducida"):
                saltados.append(r["campo"])
        elif r["op"] == "crear":
            if isinstance(cont, dict) and cont.get(r["clave"]) is r["obj"]:
                del cont[r["clave"]]
                hechos += 1
            elif isinstance(cont, list) and any(x is r["obj"] for x in cont):
                cont.pop(next(i for i, x in enumerate(cont) if x is r["obj"]))
                hechos += 1
        elif r["op"] == "borrar":
            if isinstance(cont, dict) and r["clave"] not in cont:
                cont[r["clave"]] = r["obj"]
                hechos += 1
            elif isinstance(cont, list) and not any(x is r["obj"] for x in cont):
                cont.insert(min(r.get("indice", len(cont)), len(cont)), r["obj"])
                hechos += 1
    return hechos, saltados


_MASCULINOS_CAMBIO_IA = {"gasto", "documento", "plano"}
_SIN_FICHA_CAMBIO_IA = {"jornada", "gasto", "linea", "documento", "plano"}   # («borrar la jornada X», no «la ficha de»)


def _mostrar_valor_cambio_ia(tipo: str, campo: str, v) -> str:
    if isinstance(v, bool):
        return "sí" if v else "no"
    if campo == "iva_modo":
        return {"": "sin IVA", "incluido": "con el IVA incluido", "aparte": "netos, con el IVA aparte"}.get(
            str(v or ""), str(v or ""))
    if campo == "cuando" and tipo == "gasto" and str(v or "") == "jornadas":
        return "repartido en los días de rodaje"
    if campo in ("fecha", "fecha_fin", "fecha_pago", "firma", "vence") and _fecha_iso(str(v or "")):
        return fecha_con_dia(str(v))
    return str(v if v is not None else "")


def html_cambios_ia(entradas: list) -> str:
    """Los cambios, para leerlos en la conversación (antes → después)."""
    def corto(s, n=200):
        s = " ".join(str(s or "").split())
        return html.escape(s if len(s) <= n else s[:n - 1] + "…")
    filas = []
    for e in entradas:
        emoji, nom_tipo = TIPOS_CAMBIO_IA[e["tipo"]][:2]
        quien = ("el proyecto" if e["tipo"] == "proyecto" else
                 f"la escena {e['clave']}" if e["tipo"] == "escena" else e["clave"])
        art = "el" if e["tipo"] in _MASCULINOS_CAMBIO_IA else "la"
        if e["accion"] == "borrar":
            txt_b = (f"Borrar {art} {nom_tipo}: {html.escape(str(quien))}" if e["tipo"] in _SIN_FICHA_CAMBIO_IA
                     else f"Borrar la {nom_tipo} de {html.escape(str(quien))}")
            filas.append(f"<tr><td>🗑</td><td><b style='color:#f87171;'>{txt_b}</b></td></tr>")
            continue
        nueva = "Nuevo" if e["tipo"] in _MASCULINOS_CAMBIO_IA else "Nueva"
        cab = (f"＋ {nueva} {nom_tipo}: <b>{html.escape(str(quien))}</b>"
               if e.get("nuevo") and e["tipo"] != "escena"
               else f"<b>{html.escape(str(quien))}</b> <span style='color:#94a3b8;'>({nom_tipo})</span>")
        filas.append(f"<tr><td>{emoji}</td><td>{cab}</td></tr>")
        for _c, et, antes, despues in e["campos"]:
            antes = _mostrar_valor_cambio_ia(e["tipo"], _c, antes)
            despues = _mostrar_valor_cambio_ia(e["tipo"], _c, despues)
            a_ = (f"<span style='color:#94a3b8;'><s>{corto(antes, 90)}</s></span> → " if str(antes).strip()
                  else "<span style='color:#94a3b8;'>(vacío)</span> → ")
            d_ = f"<b style='color:#86efac;'>{corto(despues)}</b>" if str(despues).strip() else \
                "<span style='color:#94a3b8;'>(vacío)</span>"
            filas.append(f"<tr><td></td><td>{html.escape(et)}: {a_}{d_}</td></tr>")
        if e.get("hablantes"):
            filas.append(f"<tr><td></td><td><span style='color:#94a3b8;'>🎭 {html.escape(unir_nombres(e['hablantes']))}"
                         f" {'hablan' if len(e['hablantes']) > 1 else 'habla'} en esas escenas: "
                         f"{'quedan' if len(e['hablantes']) > 1 else 'queda'} en la jornada.</span></td></tr>")
        if e.get("fichas_nuevas"):
            filas.append(f"<tr><td></td><td><span style='color:#94a3b8;'>👤 ficha nueva (vacía) para "
                         f"{html.escape(unir_nombres(e['fichas_nuevas']))}.</span></td></tr>")
    return ("<table cellspacing='0' cellpadding='3' style='margin:4px 0;'>" + "".join(filas) + "</table>")


def resumen_cambios_ia(entradas: list) -> str:
    """En una línea, para el historial de la conversación (la IA sabe qué se hizo)."""
    partes = []
    for e in entradas:
        quien = "el proyecto" if e["tipo"] == "proyecto" else (
            f"la escena {e['clave']}" if e["tipo"] == "escena" else str(e["clave"]))
        nom_tipo = TIPOS_CAMBIO_IA[e["tipo"]][1]
        art = "el" if e["tipo"] in _MASCULINOS_CAMBIO_IA else "la"
        if e["accion"] == "borrar":
            partes.append(f"borrar {art} {nom_tipo} {quien}" if e["tipo"] in _SIN_FICHA_CAMBIO_IA
                          else f"borrar la ficha de {quien}")
        else:
            datos = ", ".join(f"{et} = {' '.join(_mostrar_valor_cambio_ia(e['tipo'], _c, d).split())[:60]}"
                              for _c, et, _a, d in e["campos"])
            crear = ((f"crear {art} {nom_tipo} " if e["tipo"] in _SIN_FICHA_CAMBIO_IA else "crear la ficha de ")
                     if e.get("nuevo") else "")
            partes.append(crear + f"{quien}" + (f": {datos}" if datos else ""))
    return "; ".join(partes)


def refrescar_vistas_tras_cambios_ia(vp=None) -> int:
    """Después de que el Profesor cambia (o deshace) algo: las ventanas
    abiertas que lo muestran se actualizan (Carta Gantt, presupuesto,
    contratos, lista de planos y las tarjetas del Centro)."""
    n = 0
    app = QApplication.instance()
    if app is None:
        return 0
    for w in app.allWidgets():
        try:
            if isinstance(w, VentanaCartaGantt):
                w._refrescar()
            elif isinstance(w, VentanaPresupuesto):
                w.refrescar()
            elif isinstance(w, VentanaContratos):
                w.refrescar()
            elif isinstance(w, VentanaPlanos):
                fila = w._lista.currentRow()
                w._llenar_escenas()
                if 0 <= fila < w._lista.count():
                    w._lista.setCurrentRow(fila)
            elif isinstance(w, VentanaCentroProduccion) and w.isVisible():
                w._refrescar_grilla()
            else:
                continue
            n += 1
        except Exception:
            pass
    return n


def html_de_bloques_propuestos(bloques: list) -> str:
    """Los bloques que propone la IA, como se ven en un guion (para el chat)."""
    filas = []
    for el, tx in bloques:
        t = html.escape(str(tx or ""))
        if el == Elem.ESCENA:
            filas.append(f"<p style='margin:6px 0 2px 0;'><b>{t.upper()}</b></p>")
        elif el == Elem.PERSONAJE:
            filas.append(f"<p style='margin:6px 0 0 120px;'><b>{t.upper()}</b></p>")
        elif el == Elem.PARENTESIS:
            filas.append(f"<p style='margin:0 0 0 95px;'><i>{t}</i></p>")
        elif el == Elem.DIALOGO:
            filas.append(f"<p style='margin:0 60px 0 70px;'>{t}</p>")
        elif el == Elem.TRANSICION:
            filas.append(f"<p align='right' style='margin:6px 0;'><b>{t.upper()}</b></p>")
        else:
            filas.append(f"<p style='margin:4px 0;'>{t}</p>")
    # (una celda de tabla: el fondo de «hoja» queda parejo; en un <div>, Qt lo pinta párrafo por párrafo)
    return ("<table width='100%' cellspacing='0' cellpadding='10' bgcolor='#f8f5ee'><tr>"
            "<td style='color:#1a1a1a;font-family:Courier New,monospace;font-size:10pt;'>" + "".join(filas) +
            "</td></tr></table>")


def mensajes_para_asesor(doc, historial: list, pregunta: str, num_ctx: int) -> list:
    """Los mensajes para Ollama: las reglas, el proyecto resumido, la
    conversación anterior (lo que quepa) y la pregunta."""
    cabe = int(num_ctx * 3.0 * 0.62)                   # (≈3 letras por token; el resto, para la respuesta)
    resto = max(1200, cabe - len(PROMPT_ASESOR) - len(MAPA_ACCION_ASESOR) - len(pregunta) - 200)
    para_proyecto = max(800, int(resto * 0.65))
    sistema = (PROMPT_ASESOR + "\n\n" + MAPA_ACCION_ASESOR + "\n\nPROYECTO (resumen):\n"
               + ficha_proyecto_asesor(doc, para_proyecto))
    queda = max(0, cabe - len(sistema) - len(pregunta))
    previos = []
    for m in reversed(historial):
        if len(m.get("content", "")) + 20 > queda:
            break
        previos.insert(0, {"role": m["role"], "content": m["content"]})
        queda -= len(m["content"]) + 20
    if previos and previos[0]["role"] == "assistant":
        previos = previos[1:]
    return [{"role": "system", "content": sistema}] + previos + [{"role": "user", "content": pregunta}]


def _md_a_html(t: str) -> str:
    """Lo poco de «markdown» que usan los modelos (negritas, viñetas,
    títulos), en HTML para la ventana."""
    out = []
    for linea in (t or "").split("\n"):
        s = html.escape(linea.rstrip())
        s = re.sub(r"\*\*(.+?)\*\*", r"<b>\1</b>", s)
        s = re.sub(r"(?<![\w*])\*(?!\s)(.+?)(?<!\s)\*(?![\w*])", r"<i>\1</i>", s)
        s = re.sub(r"`([^`]+)`", r"<code>\1</code>", s)
        m = re.match(r"^\s*#{1,6}\s+(.*)$", s)
        if m:
            out.append(f"<b>{m.group(1)}</b>")
            continue
        m = re.match(r"^(\s*)[-*•]\s+(.*)$", s)
        if m:
            sangria = "&nbsp;" * (2 + len(m.group(1)))
            out.append(f"{sangria}•&nbsp;{m.group(2)}")
            continue
        out.append(s)
    return "<br>".join(out)


class DialogoModelosAsesor(QDialog):
    """⬇ Los modelos para el Profesor Claqueta: cuál le acomoda a este computador, cómo
    es cada uno (capacidad, velocidad, ventajas y desventajas) y un botón que
    dice «⬇ Descargar» o, si ya está descargado, «✓ Usar este modelo». La
    descarga sigue aunque se cierre esta ventana o el Profesor Claqueta."""

    def __init__(self, instalados: list, parent=None, gestor=None, host: str = "", al_usar=None,
                 actual: Optional[str] = None):
        super().__init__(parent)
        self.setWindowTitle("⬇  Los modelos del Profesor Claqueta")
        self.setMinimumWidth(px(680))                # (las descripciones, sin cortarse)
        self.gestor, self.host, self.al_usar = gestor, host, al_usar
        self.instalados = {str(n) for n in instalados}
        self.usado = ""
        # (el modelo con que conversa ahora: la ventana se abre con ESE marcado, no con el sugerido)
        self.actual = str(settings_app().value("asesor/modelo", "") or "") if actual is None else str(actual)
        rec = recursos_equipo()
        self.sugerido = recomendar_modelo_asesor(rec)
        v = QVBoxLayout(self)
        partes = []
        if rec.get("ram_gb"):
            partes.append(f"{rec['ram_gb']:.0f} GB de memoria")
        partes.append(f"tarjeta gráfica {rec['gpu']} ({rec['vram_gb']:.0f} GB)" if rec.get("vram_gb")
                      else "sin tarjeta gráfica NVIDIA detectada")
        i_actual = self.indice_actual()
        mo_s = MODELOS_ASESOR[self.sugerido["indice"]]
        sug = (f"Para este computador te sugiero a <b>{mo_s['apodo']}</b> ({mo_s['nombre'].lower()}, "
               f"marcado con ★): {html.escape(self.sugerido['motivo'])}.")
        if i_actual is not None and i_actual != self.sugerido["indice"]:
            mo_a = MODELOS_ASESOR[i_actual]
            sug = (f"Usas a <b>{mo_a['apodo']}</b> ({mo_a['nombre'].lower()}, marcado con ●). " + sug +
                   " Puedes seguir con el tuyo.")
        elif i_actual is not None:
            sug = f"Usas a <b>{mo_s['apodo']}</b>, el sugerido para este computador (★): " \
                  f"{html.escape(self.sugerido['motivo'])}."
        t_gpu = texto_gpu_ia()                       # (⚡ si la tarjeta NVIDIA se usa, o qué le falta)
        if t_gpu:
            color = "#86efac" if t_gpu.startswith("⚡") else "#fbbf24"
            sug += f"<br><span style='color:{color};'>{html.escape(t_gpu)}</span>"
        info = QLabel(f"<b>Este computador:</b> {', '.join(partes)}.<br>{sug}")
        info.setWordWrap(True)
        v.addWidget(info)
        # (los modelos y la injerencia van en una zona con desplazamiento: la ventana cabe en
        # cualquier pantalla y los botones de abajo siempre se ven)
        cont = QWidget()
        cont.setObjectName("_contModelos")
        cont.setStyleSheet("QWidget#_contModelos { background: transparent; }")
        vc = QVBoxLayout(cont)
        vc.setContentsMargins(0, 0, px(6), 0)
        self._grupo = QButtonGroup(self)
        self._radios: list = []
        for i, mo in enumerate(MODELOS_ASESOR):
            rb = QRadioButton()
            rb.setToolTip(mo["ideal"])
            self._grupo.addButton(rb, i)
            self._radios.append(rb)
            vc.addWidget(rb)
            lbl = QLabel(descripcion_modelo_html(mo))
            lbl.setWordWrap(True)
            lbl.setContentsMargins(px(24), 0, 0, px(6))
            vc.addWidget(lbl)
        self._grupo.button(i_actual if i_actual is not None else self.sugerido["indice"]).setChecked(True)
        self._grupo.idToggled.connect(lambda *_a: self._pintar())
        self._zona = QScrollArea()
        self._zona.setObjectName("_zonaModelos")
        self._zona.setWidgetResizable(True)
        self._zona.setFrameShape(QFrame.Shape.NoFrame)
        self._zona.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self._zona.setStyleSheet("QScrollArea#_zonaModelos { background: transparent; border: none; }")
        self._zona.viewport().setAutoFillBackground(False)
        self._zona.setWidget(cont)
        v.addWidget(self._zona, 1)
        self._cont_modelos, self._lay_modelos = cont, vc
        self._barra = QProgressBar()
        self._barra.setTextVisible(True)
        self._barra.hide()
        v.addWidget(self._barra)
        self._lbl_sigue = QLabel("<span style='color:#94a3b8;font-size:9pt;'>Puedes cerrar esta ventana, y "
                                 "también la del Profesor Claqueta: la descarga sigue, y la ves abajo, en la barra de "
                                 "estado.</span>")
        self._lbl_sigue.setWordWrap(True)
        self._lbl_sigue.hide()
        v.addWidget(self._lbl_sigue)
        self.selector_injerencia = selector_injerencia_ia()
        self.selector_injerencia.setContentsMargins(0, px(6), 0, px(6))
        self._lay_modelos.addWidget(self.selector_injerencia)
        nota = QLabel("<span style='color:#94a3b8;font-size:9pt;'>Se descarga una sola vez (por internet) y "
                      "después funciona sin conexión. Son modelos Qwen 3.5, con licencia Apache 2.0; todos "
                      "pueden equivocarse o inventar, los más grandes menos. Ollama los guarda en tu "
                      "carpeta de usuario; para borrarlos, en una consola: <code>ollama rm nombre</code>."
                      "</span>")
        nota.setWordWrap(True)
        self._lay_modelos.addWidget(nota)
        self._lay_modelos.addStretch()
        fila = QHBoxLayout()
        self.b_accion = QPushButton("⬇ Descargar")
        self.b_accion.setDefault(True)
        self.b_accion.clicked.connect(self._accion)
        self.b_bajar = self.b_accion
        self.b_cancelar = QPushButton("Cancelar descarga")
        self.b_cancelar.clicked.connect(lambda: self.gestor.cancelar() if self.gestor is not None else None)
        self.b_cancelar.hide()
        b_cerrar = QPushButton("Cerrar")
        b_cerrar.clicked.connect(self.reject)
        fila.addWidget(self.b_cancelar)
        fila.addStretch()
        fila.addWidget(self.b_accion)
        fila.addWidget(b_cerrar)
        v.addLayout(fila)
        if gestor is not None:
            gestor.cambio.connect(self._pintar)
            gestor.terminado.connect(self._bajado)
        self._pintar()
        self._tamano_inicial()

    def indice_actual(self) -> Optional[int]:
        """El modelo con que conversa ahora (por su nombre o su alternativa)."""
        a = self.actual.strip()
        if not a:
            return None
        for i, mo in enumerate(MODELOS_ASESOR):
            if a in (mo["tag"], mo["alt"]) or a.split(":")[0] + ":" + a.split(":")[-1] in (mo["tag"], mo["alt"]):
                return i
        return None

    def _tamano_inicial(self) -> None:
        """Tan alta como su contenido, sin pasar del alto útil de la pantalla."""
        try:
            pant = self.screen() or QApplication.primaryScreen()
            av = pant.availableGeometry()
            ancho = max(self.minimumWidth(), min(px(900), av.width() - 40))
            self._cont_modelos.adjustSize()
            alto_modelos = self._lay_modelos.totalHeightForWidth(ancho - px(40)) \
                if self._lay_modelos.hasHeightForWidth() else self._cont_modelos.sizeHint().height()
            resto = self.sizeHint().height() - self._zona.sizeHint().height()
            alto = min(resto + alto_modelos + px(12), int(av.height() * 0.9) - 40)
            self._zona.setMinimumHeight(min(px(220), alto_modelos))
            self.resize(ancho, max(px(360), alto))
        except Exception:
            pass

    def elegido(self) -> dict:
        return MODELOS_ASESOR[max(0, self._grupo.checkedId())]

    def nombre_instalado(self, mo: dict) -> str:
        """El nombre con que está descargado (la 3.5 o su alternativa), o «»."""
        return next((n for n in (mo["tag"], mo["alt"]) if n in self.instalados), "")

    def _bajado(self, tag: str) -> None:
        self.instalados.add(tag)
        self._pintar()

    def _pintar(self) -> None:
        g = self.gestor
        bajando = g is not None and g.bajando()
        pct = f" {int(g.fraccion * 100)} %" if bajando and g.fraccion >= 0 else ""
        for i, (rb, mo) in enumerate(zip(self._radios, MODELOS_ASESOR)):
            if self.nombre_instalado(mo):
                marca = "   ✓ ya descargado"
            elif bajando and g.bajando(mo["tag"]):
                marca = f"   ⬇ descargando{pct}"
            else:
                marca = ""
            rb.setText(f"{mo['apodo']} — {mo['nombre']} · {mo['tag']} · {mo['gb']:.1f} GB{marca}"
                       + ("   ● en uso" if i == self.indice_actual() else "")
                       + ("   ★ sugerido" if i == self.sugerido["indice"] else ""))
        mo = self.elegido()
        este = bajando and g.bajando(mo["tag"])
        if self.nombre_instalado(mo) and self._grupo.checkedId() == self.indice_actual():
            self.b_accion.setText("✓ Es el que usas")
            self.b_accion.setEnabled(True)
            self.b_accion.setToolTip("El Profesor Claqueta ya conversa con este modelo")
        elif self.nombre_instalado(mo):
            self.b_accion.setText("✓ Usar este modelo")
            self.b_accion.setEnabled(True)
            self.b_accion.setToolTip("Ya está descargado: el Profesor Claqueta conversa con él")
        elif este:
            self.b_accion.setText(f"Descargando…{pct}")
            self.b_accion.setEnabled(False)
            self.b_accion.setToolTip("Cuando termine, este botón dirá «Usar»")
        else:
            self.b_accion.setText("⬇ Descargar")
            self.b_accion.setEnabled(not bajando)
            self.b_accion.setToolTip("Espera que termine la otra descarga" if bajando else
                                     f"Baja {mo['tag']} ({mo['gb']:.1f} GB) una sola vez")
        self._barra.setVisible(bajando)
        self.b_cancelar.setVisible(bajando)
        self._lbl_sigue.setVisible(bajando)
        if bajando:
            if g.fraccion < 0:
                self._barra.setRange(0, 0)
            else:
                self._barra.setRange(0, 1000)
                self._barra.setValue(int(g.fraccion * 1000))
            self._barra.setFormat(g.texto)

    def _accion(self) -> None:
        mo = self.elegido()
        ya = self.nombre_instalado(mo)
        if ya:
            self.usado = ya
            if self.al_usar is not None:
                self.al_usar(ya)
            self.accept()
            return
        if self.gestor is None:
            self.accept()
            return
        self.gestor.bajar(mo, self.host or host_ollama())
        self._pintar()


# ── 🎬 La IA maneja el programa (modo en vivo) ──
# El estudiante ve cómo trabaja: abre la Escaleta y escribe la premisa y los
# momentos, arma la Pizarra de beats, llena las fichas de personajes, escribe
# el guion en la hoja (bloque por bloque), analiza cada escena, describe las
# locaciones en el Centro de Producción, propone los planos y arma el plan de
# rodaje en la Carta Gantt. Un panel flotante dice qué hace y tiene «■ Cancelar».
PROMPT_EQUIPO_IA = """Eres el equipo de un cortometraje (guionista, director y productor) y ayudas a un estudiante de cine de Chile. Respondes en español, en JSON, con frases breves y concretas, coherentes con el guion. No inventas datos de personas reales."""

FASES_GUION_IA = [("escaleta", "💡", "Escaleta: título, premisa y momentos"),
                  ("pizarra", "🧩", "Pizarra de beats"),
                  ("personajes", "🎭", "Fichas de personajes"),
                  ("guion", "✍", "Guion, escena por escena"),
                  ("analisis", "📄", "Fichas de escenas (análisis)"),
                  ("locaciones", "📍", "Locaciones (Centro de Producción)"),
                  ("planos", "🎥", "Lista de planos"),
                  ("storyboard", "🎞", "Storyboard 3D: un cuadro por plano"),
                  ("rodaje", "📊", "Plan de rodaje (Carta Gantt)"),
                  ("informes", "📑", "Informes y PDF, en una carpeta")]
_GUION_IA = ["escaleta", "pizarra", "personajes", "guion"]
ALCANCES_GUION_IA = [("Guion: escaleta, pizarra, personajes y escenas", _GUION_IA + ["informes"]),
                     ("Guion y análisis de cada escena", _GUION_IA + ["analisis", "informes"]),
                     ("Todo: guion, análisis, producción, storyboard 3D e informes",
                      [c for c, _i, _n in FASES_GUION_IA])]


def carpeta_informes_ia(titulo: str, base: Optional[Path] = None) -> Path:
    """Dónde deja la IA los informes: Documentos/¡Acción!/Informes/«título» (fecha)."""
    import datetime as _dt
    if base is None:
        from PySide6.QtCore import QStandardPaths
        docs = QStandardPaths.writableLocation(QStandardPaths.StandardLocation.DocumentsLocation)
        base = Path(docs or Path.home()) / "¡Acción!" / "Informes"
    limpio = re.sub(r'[\\/:*?"<>|]+', "", titulo or "").strip() or "Guion"
    return Path(base) / f"{limpio[:60]} ({_dt.datetime.now().strftime('%d-%m-%Y %H.%M')})"


def pedido_ficha_personaje_ia(plan: dict, p_: dict, hechas: Optional[list] = None, repetida: str = "") -> str:
    """Lo que se le pide a la IA para la ficha de un personaje. «hechas»: las
    fichas ya escritas [(nombre, Ficha)], para que no las repita (los modelos
    chicos tienden a escribir otra vez la del protagonista); «repetida»: el
    personaje cuya ficha copió en el intento anterior."""
    otros = ", ".join(x["nombre"] for x in plan["personajes"] if x["nombre"] != p_["nombre"]) or "(ninguno)"
    ya = ""
    for n_, f_ in hechas or []:
        datos = ", ".join(x for x in (f"{f_.edad} años" if f_.edad else "", f_.profesion) if x)
        ya += f"- {n_}" + (f" ({datos})" if datos else "") + "\n"
    ya = (f"Fichas ya escritas (son OTRAS personas: no las repitas):\n{ya}\n") if ya else ""
    ojo = (f"OJO: la respuesta anterior repitió la ficha de {repetida}. Esta ficha es SOLO de {p_['nombre']}, "
           "otra persona, con su propia edad, historia, aspecto y ropa.\n\n") if repetida else ""
    return (f"Guion: «{plan['titulo']}». Premisa: {plan['premisa']}\n"
            f"Personaje: {p_['nombre']} — {p_['descripcion']}\nOtros personajes: {otros}\n\n{ya}{ojo}"
            f"Completa la ficha de {p_['nombre']} (solo de {p_['nombre']}) en JSON: edad (por ejemplo «17» o "
            "«40 a 45»), genero, nacionalidad (chilena, salvo que la historia diga otra cosa), profesion (u "
            "ocupación), biografia (3 o 4 frases sobre este personaje: quién es, qué quiere, qué teme y cómo "
            "cambia en la historia), descripcion_fisica (1 o 2 frases, para el casting) y vestuario (1 frase).")


def _norm_ficha_ia(x) -> str:
    return " ".join(re.sub(r"[^\w\s]", " ", str(x or "").lower()).split())


def ficha_repetida_ia(d: dict, fichas: dict, nombre: str, otros: list) -> str:
    """🎭 ¿La IA escribió en la ficha de «nombre» la de otro personaje (ya
    escrito)? Los modelos chicos a veces repiten la del protagonista.
    Devuelve el nombre del otro, o «»."""
    import difflib
    if not isinstance(d, dict):
        return ""
    bio = _norm_ficha_ia(d.get("biografia"))
    propio = _norm_ficha_ia(nombre).split()[:1]
    for o in otros:
        f = fichas.get(o)
        if f is None or o == nombre:
            continue
        fb = _norm_ficha_ia(f.biografia)
        r = difflib.SequenceMatcher(None, bio, fb).ratio() if bio and fb else 0.0
        iguales = sum(1 for c in ("edad", "genero", "profesion", "descripcion_fisica", "vestuario")
                      if _norm_ficha_ia(d.get(c)) and _norm_ficha_ia(d.get(c)) == _norm_ficha_ia(getattr(f, c, "")))
        aspecto = all(_norm_ficha_ia(d.get(c)) and _norm_ficha_ia(d.get(c)) == _norm_ficha_ia(getattr(f, c, ""))
                      for c in ("descripcion_fisica", "vestuario"))
        del_otro = _norm_ficha_ia(o).split()[:1]       # (la biografía habla del otro, y nunca de este)
        habla_del_otro = bool(bio and del_otro and del_otro[0] in bio.split()[:3] and
                              not (propio and propio[0] in bio.split()))
        if r >= 0.75 or (r >= 0.6 and iguales >= 3) or iguales >= 5 or aspecto or habla_del_otro:
            return o
    return ""


def ficha_sin_copia_ia(d: dict, otra, descripcion: str) -> dict:
    """Si la IA insiste en repetir otra ficha: se queda solo lo que es distinto
    (lo copiado, en blanco) y la biografía es la descripción de la escaleta."""
    out = {}
    for c, v in (d or {}).items():
        if _norm_ficha_ia(v) and _norm_ficha_ia(v) == _norm_ficha_ia(getattr(otra, c, "")) and \
                c in ("edad", "profesion", "descripcion_fisica", "vestuario"):
            continue
        out[c] = v
    out["biografia"] = descripcion or ""
    return out


def pedido_analisis_escena_ia(plan: dict, i: int, texto: str) -> str:
    e = plan["escenas"][i]
    return (f"Guion: «{plan['titulo']}». Premisa: {plan['premisa']}\n"
            f"ESCENA {i + 1}: {e['encabezado']}\n{texto[:2500]}\n\n"
            "Haz su análisis dramático en JSON, con frases breves: proposito (para qué está esta escena en la "
            "historia), objetivo_protagonista (qué quiere lograr el personaje principal de la escena), obstaculo "
            "(qué se lo impide), subtexto (qué se dice sin decirlo) y tono (2 o 3 palabras).")


def pedido_locaciones_ia(plan: dict, lugares: list) -> str:
    lineas = "\n".join(f"- {n}: {'; '.join(r_ for r_ in res if r_)[:300]}" for n, res in lugares)
    return (f"Guion: «{plan['titulo']}». Estas son sus locaciones y lo que pasa en cada una:\n{lineas}\n\n"
            "Responde en JSON: \"locaciones\", una por cada una de la lista, con \"nombre\" (tal cual) y "
            "\"detalles\": qué tiene que tener el lugar para filmar ahí (espacio, luz, sonido, permisos) y dónde "
            "se podría encontrar uno así en Chile, en 2 o 3 frases.")


def pedido_planos_ia(plan: dict, i: int, texto: str) -> str:
    e = plan["escenas"][i]
    return (f"Guion: «{plan['titulo']}». ESCENA {i + 1}: {e['encabezado']}\n{texto[:2200]}\n\n"
            "Propón entre 3 y 5 planos para filmarla, en orden, en JSON: \"planos\" con tamano, angulo, "
            "movimiento, quien (el personaje que más se ve en ese plano, o «varios» si son varios) y "
            "descripcion (qué se ve, en 1 frase). Varía los planos: generales para ubicar, cercanos para las "
            "emociones.")


def apuntar_camaras_ia(doc, n: int) -> int:
    """🎞 La cámara de cada plano donde la IA dijo quién se ve («ia_quien»):
    frente a ese personaje, a la distancia que pide el tamaño del plano (un
    primer plano, cerca; un plano entero, más lejos), sin cambiar de lado.
    Devuelve cuántas cámaras movió."""
    planta = planta_de_escena(doc, n)
    if not planta:
        return 0
    pers = {clave_nombre(e.get("nombre")): e for e in planta.get("elementos", [])
            if e.get("tipo") == "personaje"}
    movidas = 0
    for pl in cuadros_ordenados(doc, {n}):
        quien = str(pl.get("ia_quien") or "").strip()
        q = pers.get(clave_nombre(quien)) if quien else None
        cam = camara_de_plano_3d(planta, pl["id"])
        if q is None or cam is None:
            continue
        d = _DIST_POR_TAMANO.get(pl.get("tamano", ""), 3.0)
        qx, qy = float(q["x"]), float(q["y"])
        vx, vy = float(cam["x"]) - qx, float(cam["y"]) - qy
        L = _math.hypot(vx, vy)
        if L < 1e-3:
            vx, vy, L = 0.0, 1.0, 1.0
        cam["x"], cam["y"] = round(qx + vx / L * d, 2), round(qy + vy / L * d, 2)
        cam["ang"] = round(_math.degrees(_math.atan2(qy - cam["y"], qx - cam["x"])), 1)
        for k_ in ("altura", "inclinacion", "holandes", "dist"):
            cam.pop(k_, None)                         # (la pose 3D se vuelve a sugerir)
        movidas += 1
    return movidas


def jornadas_propuestas_ia(doc, desde: Optional[date] = None) -> list:
    """El plan de rodaje más simple: una jornada por locación (en el orden en
    que aparecen), con sus escenas y los personajes que actúan en ellas. Las
    fechas son una propuesta (días seguidos, sin domingos, desde dentro de una
    semana) para que se vean en la Carta Gantt; se cambian según el equipo."""
    grupos: dict = {}
    noche: dict = {}
    n_esc, actual, nombres = 0, None, {}
    for b in doc.bloques:
        if b.elem == Elem.ESCENA:
            n_esc += 1
            actual = _locacion_desde_encabezado(b.texto) or "SIN LOCACIÓN"
            grupos.setdefault(actual, []).append(n_esc)
            nombres.setdefault(actual, [])
            noche.setdefault(actual, "NOCHE" in b.texto.upper())
        elif b.elem == Elem.PERSONAJE and actual is not None:
            n = _nombre_personaje(b.texto)
            if n and n not in nombres[actual]:
                nombres[actual].append(n)
    out = []
    dia = (desde or date.today() + timedelta(days=7))
    for k, (lugar, escenas) in enumerate(grupos.items(), start=1):
        while dia.weekday() == 6:                    # (sin domingos)
            dia += timedelta(days=1)
        out.append(Jornada(nombre=f"Jornada {k} — {lugar.title()}", lugar=lugar, fecha=dia.isoformat(),
                           hora_citacion="17:30" if noche.get(lugar) else "08:30",
                           escenas=", ".join(str(x) for x in escenas), actores=", ".join(nombres.get(lugar, [])),
                           notas="Propuesta de la IA: las escenas de una misma locación, juntas. Las fechas y "
                                 "horas son una propuesta: ajústalas según la disponibilidad del equipo."))
        dia += timedelta(days=1)
    return out


class _EscritorIA(QObject):
    """⌨ Escribe de a poco, como alguien tecleando, lo que la IA va mandando:
    un campo a la vez, en orden. Si la IA escribe más rápido, teclea más rápido."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self._items: list = []
        self._por_clave: dict = {}
        self._al_vaciar = None
        self.velocidad = 1.0
        self._t = QTimer(self)
        self._t.setInterval(30)
        self._t.timeout.connect(self._tick)

    def poner(self, clave, texto: str, setter, cerrado: bool = False, al_terminar=None) -> None:
        it = self._por_clave.get(clave)
        if it is None:
            it = {"objetivo": str(texto or ""), "n": 0, "setter": setter, "cerrado": cerrado,
                  "al_terminar": al_terminar, "hecho": False}
            self._items.append(it)
            self._por_clave[clave] = it
        elif not it["hecho"]:
            it["objetivo"] = str(texto or "")
            it["n"] = min(it["n"], len(it["objetivo"]))
            it["cerrado"] = it["cerrado"] or cerrado
        if not self._t.isActive():
            self._t.start()

    def alimentar(self, campos: list, final: bool = False) -> None:
        """campos: [(clave, texto, setter[, al_terminar]), …] en orden; todos
        menos el último ya están completos (o todos, si es el final)."""
        for k, c in enumerate(campos):
            self.poner(c[0], c[1], c[2], cerrado=final or k < len(campos) - 1,
                       al_terminar=c[3] if len(c) > 3 else None)

    def al_vaciar(self, cb) -> None:
        self._al_vaciar = cb
        if not self._t.isActive():
            self._t.start()

    def detener(self) -> None:
        self._t.stop()
        self._items.clear()
        self._por_clave.clear()
        self._al_vaciar = None

    def ocupado(self) -> bool:
        return bool(self._items)

    def _tick(self) -> None:
        if not self._items:
            self._t.stop()
            cb, self._al_vaciar = self._al_vaciar, None
            if cb is not None:
                cb()
            return
        it = self._items[0]
        falta = len(it["objetivo"]) - it["n"]
        if falta > 0:
            paso = max(1, int(max(2, falta // 10) * self.velocidad))
            it["n"] = min(len(it["objetivo"]), it["n"] + paso)
            try:
                it["setter"](it["objetivo"][:it["n"]])
            except Exception:
                pass
            return
        if it["cerrado"]:
            self._items.pop(0)
            it["hecho"] = True
            if it["al_terminar"] is not None:
                try:
                    it["al_terminar"](it["objetivo"])
                except Exception:
                    pass


class PanelIAEnVivo(QDialog):
    """🤖 El panel flotante: qué está haciendo la IA, lo que escribe ahora,
    el avance, «⏩ Más rápido» y «■ Cancelar»."""

    def __init__(self, director, parent=None):
        super().__init__(parent)
        self.director = director
        self.setWindowTitle(f"🤖  {NOMBRE_IA} escribe tu guion")
        self.setWindowFlags(Qt.WindowType.Tool | Qt.WindowType.WindowStaysOnTopHint
                            | Qt.WindowType.WindowTitleHint | Qt.WindowType.WindowCloseButtonHint)
        self.setModal(False)
        self.setMinimumWidth(px(400))
        self.setStyleSheet("QDialog { background: #0d1520; } QLabel { color: #e8edf4; }")
        v = QVBoxLayout(self)
        v.setSpacing(px(6))
        self.lbl_cab = QLabel(f"🤖  El {NOMBRE_IA} está creando tu guion")
        self.lbl_cab.setStyleSheet("color: #ff8c1a; font-size: 13pt; font-weight: 800;")
        v.addWidget(self.lbl_cab)
        self.lbl_titulo = QLabel("")
        self.lbl_titulo.setStyleSheet("color: #ffb366; font-size: 11pt; font-weight: 700;")
        self.lbl_titulo.setWordWrap(True)
        v.addWidget(self.lbl_titulo)
        self._lbl_fases: dict = {}
        for clave, ico, nombre in FASES_GUION_IA:
            if clave not in director.fases:
                continue
            l_ = QLabel(f"○  {ico} {nombre}")
            l_.setStyleSheet("color: #64748b; font-size: 9.5pt;")
            v.addWidget(l_)
            self._lbl_fases[clave] = (l_, ico, nombre)
        self.lbl_ahora = QLabel("Preparando…")
        self.lbl_ahora.setWordWrap(True)
        self.lbl_ahora.setStyleSheet("color: #cbd5e1; font-size: 9.5pt; padding-top: 4px;")
        v.addWidget(self.lbl_ahora)
        self.pizarron = QPlainTextEdit()
        self.pizarron.setReadOnly(True)
        self.pizarron.setFixedHeight(px(96))
        self.pizarron.setStyleSheet("QPlainTextEdit { background: #131d2b; color: #e8edf4; border: 1px solid "
                                    "#26344a; border-radius: 6px; font-family: 'Courier New', monospace; "
                                    "font-size: 9.5pt; }")
        v.addWidget(self.pizarron)
        self.barra = QProgressBar()
        self.barra.setRange(0, 1000)
        self.barra.setTextVisible(False)
        self.barra.setFixedHeight(px(8))
        v.addWidget(self.barra)
        self.consola = ConsolaRecursosIA(self, compacta=True)   # (🖥 en qué trabaja la IA, mientras escribe)
        self.consola.setVisible(_bool_ajuste(CLAVE_CONSOLA_IA, True))
        v.addWidget(self.consola)
        fila = QHBoxLayout()
        self.b_consola = QPushButton("🖥 Recursos")
        self.b_consola.setCheckable(True)
        self.b_consola.setChecked(self.consola.isVisibleTo(self) or _bool_ajuste(CLAVE_CONSOLA_IA, True))
        self.b_consola.setToolTip("Mostrar u ocultar la consola de recursos: tarjeta gráfica, procesador y memoria")
        self.b_consola.toggled.connect(self._ver_consola)
        fila.addWidget(self.b_consola)
        self.b_rapido = QPushButton("⏩ Más rápido")
        self.b_rapido.setCheckable(True)
        self.b_rapido.setToolTip("Teclea más rápido (la IA piensa igual: lo que cambia es cómo se muestra)")
        self.b_rapido.toggled.connect(director.set_rapido)
        self.b_cancelar = QPushButton("■ Cancelar")
        self.b_cancelar.setToolTip("Detiene a la IA: lo escrito hasta aquí queda en el proyecto")
        self.b_cancelar.setStyleSheet("QPushButton { background: #7f1d1d; color: #fee2e2; border-radius: 6px; "
                                      "padding: 6px 14px; font-weight: 700; } QPushButton:hover { background: #991b1b; }")
        self.b_cancelar.clicked.connect(director.cancelar)
        self.b_cerrar = QPushButton("Cerrar")
        self.b_cerrar.clicked.connect(self.close)
        self.b_cerrar.hide()
        self.b_carpeta = QPushButton("📂 Abrir los informes")
        self.b_carpeta.setToolTip("La carpeta con el guion en PDF y los informes")
        self.b_carpeta.clicked.connect(self._abrir_carpeta)
        self.b_carpeta.hide()
        fila.addWidget(self.b_rapido)
        fila.addWidget(self.b_carpeta)
        fila.addStretch()
        fila.addWidget(self.b_cancelar)
        fila.addWidget(self.b_cerrar)
        v.addLayout(fila)

    def _ver_consola(self, si: bool) -> None:
        settings_app().setValue(CLAVE_CONSOLA_IA, bool(si))
        self.consola.setVisible(bool(si))
        self.adjustSize()

    def colocar(self) -> None:
        """Abajo a la derecha de la pantalla del programa (siempre a la vista)."""
        self.adjustSize()
        try:
            pant = (self.parent().screen() if self.parent() is not None else QApplication.primaryScreen())
            g = pant.availableGeometry()
            self.move(g.right() - self.width() - px(24), g.bottom() - self.height() - px(48))
        except Exception:
            pass

    def fase(self, clave: str, estado: str) -> None:
        if clave not in self._lbl_fases:
            return
        l_, ico, nombre = self._lbl_fases[clave]
        marca, color = {"actual": ("▶", "#ffb366"), "hecha": ("✓", "#86efac"),
                        "detenida": ("■", "#f87171")}.get(estado, ("○", "#64748b"))
        l_.setText(f"{marca}  {ico} {nombre}")
        l_.setStyleSheet(f"color: {color}; font-size: 9.5pt;" + (" font-weight: 700;" if estado == "actual" else ""))

    def escribe(self, etiqueta: str, texto: str) -> None:
        self.pizarron.setPlainText(f"{etiqueta}\n{texto}" if etiqueta else texto)
        self.pizarron.verticalScrollBar().setValue(self.pizarron.verticalScrollBar().maximum())

    def _abrir_carpeta(self) -> None:
        c = self.director.carpeta_informes
        if c is not None and Path(c).is_dir():
            from PySide6.QtGui import QDesktopServices
            from PySide6.QtCore import QUrl
            QDesktopServices.openUrl(QUrl.fromLocalFile(str(c)))

    def final(self, ok: bool, texto: str) -> None:
        self.lbl_cab.setText("✓  Listo" if ok else "■  Detenido")
        self.lbl_cab.setStyleSheet(f"color: {'#86efac' if ok else '#f87171'}; font-size: 13pt; font-weight: 800;")
        self.lbl_ahora.setText(texto)
        self.barra.setValue(1000 if ok else self.barra.value())
        self.pizarron.hide()
        c = self.director.carpeta_informes
        self.b_carpeta.setVisible(bool(c is not None and Path(c).is_dir() and self.director.archivos_informes))
        self.adjustSize()
        self.b_cancelar.hide()
        self.b_rapido.hide()
        self.b_cerrar.show()
        self.raise_()

    def closeEvent(self, ev) -> None:
        if self.director.activo():                    # (cerrar el panel también la detiene)
            self.director.cancelar()
        super().closeEvent(ev)


class DirectorGuionIA(QObject):
    """🎬 La IA usa el programa a la vista: abre cada ventana, escribe en ella
    y la cierra, y en el editor escribe el guion bloque por bloque."""
    terminado = Signal(dict)

    def __init__(self, vp, host: str, modelo: str, num_ctx: int, pedido: dict, alcance: int = 2):
        super().__init__(vp)
        self.vp, self.host, self.modelo, self.num_ctx = vp, host, modelo, int(num_ctx)
        self.pedido = dict(pedido)
        self.fases = list(ALCANCES_GUION_IA[max(0, min(len(ALCANCES_GUION_IA) - 1, int(alcance)))][1])
        self.base_informes: Optional[Path] = None    # (las pruebas usan otra carpeta)
        self.carpeta_informes: Optional[Path] = None
        self.archivos_informes: list = []
        self.estado = "inactivo"                     # trabajando · listo · detenido · error
        self.fase_actual = ""
        self.error = ""
        self.plan: Optional[dict] = None
        self.doc = None
        self.hilo: Optional[HiloOllama] = None
        self.ventana = None
        self._texto = ""
        self._cb_trozo = None
        self._cb_listo = None
        self._k = 0
        self._ro_previo = False
        self.velocidad = 1.0
        self.esc = _EscritorIA(self)
        self.panel = PanelIAEnVivo(self, vp)

    # ── estado ──
    def activo(self) -> bool:
        return self.estado == "trabajando"

    def set_rapido(self, si: bool) -> None:
        self.velocidad = 4.0 if si else 1.0
        self.esc.velocidad = self.velocidad

    def _pausa(self, ms: int, cb) -> None:
        QTimer.singleShot(int(ms / self.velocidad), lambda: None if not self.activo() else cb())

    def _avance(self, sub: float = 0.0) -> None:
        if self.fase_actual in self.fases:
            i = self.fases.index(self.fase_actual)
            self.panel.barra.setValue(int((i + max(0.0, min(1.0, sub))) / len(self.fases) * 1000))

    # ── empezar y terminar ──
    def iniciar(self) -> bool:
        import datetime as _dt
        doc = Documento()
        doc.titulo = ""
        if not self.vp.abrir_guion_ia(doc):
            return False
        self.doc = self.vp.editor.documento
        self.doc.borrador = f"Borrador escrito con IA ({self.modelo}), {_dt.date.today().strftime('%d-%m-%Y')}"
        self.doc.comentarios = "🤖 El Profesor Claqueta está escribiendo este guion…"
        self._ro_previo = self.vp.editor.isReadOnly()
        self.vp.editor.setReadOnly(True)              # (mientras la IA escribe, la hoja es suya)
        self.estado = "trabajando"
        self.panel.show()
        self.panel.colocar()
        self._fase_i = -1
        self._siguiente_fase()
        return True

    def _siguiente_fase(self) -> None:
        if not self.activo():
            return
        if self.fase_actual:
            self.panel.fase(self.fase_actual, "hecha")
        self._fase_i += 1
        if self._fase_i >= len(self.fases):
            self._terminar(True)
            return
        self.fase_actual = self.fases[self._fase_i]
        self.panel.fase(self.fase_actual, "actual")
        self._avance()
        getattr(self, "_f_" + self.fase_actual)()

    def cancelar(self) -> None:
        if not self.activo():
            return
        self._terminar(False)

    def _fallar(self, error: str) -> None:
        if not self.activo():
            return
        self.error = error
        self._terminar(False, error)

    def _terminar(self, ok: bool, error: str = "") -> None:
        self.estado = "listo" if ok else ("error" if error else "detenido")
        h, self.hilo = self.hilo, None
        if h is not None:
            h.cancelar()
            h.wait(4000)
        self.esc.detener()
        if not ok and self.fase_actual:
            self.panel.fase(self.fase_actual, "detenida")
        self._cerrar_ventana()
        cp = getattr(self.vp, "_centro_produccion", None)
        if cp is not None and cp.isVisible() and "locaciones" in self.fases:
            cp.close()
        doc = self.doc
        ed = self.vp.editor
        ed.setReadOnly(self._ro_previo)
        n_esc = sum(1 for b in (doc.bloques if doc else []) if b.elem == Elem.ESCENA)
        if doc is not None:
            if not (doc.titulo or "").strip():
                doc.titulo = (self.plan or {}).get("titulo") or "Sin título"
            falta = "" if ok else " Quedó incompleto: se detuvo antes de terminar."
            doc.comentarios = (f"🤖 Este guion lo escribió el Profesor Claqueta, la IA de ¡Acción! (modelo {self.modelo}), a "
                               f"partir de esta idea: «{self.pedido.get('idea', '')}».{falta} Es un punto de "
                               "partida: revísalo, corrígelo y hazlo tuyo.")
            try:
                ed._mover_cursor_a(0, 0)
                ed.verticalScrollBar().setValue(0)
            except Exception:
                pass
        self.vp._doc_dirty = True
        self.vp.raise_()
        resumen = {"ok": ok, "titulo": (doc.titulo if doc else ""), "escenas": n_esc,
                   "personajes": len(doc.fichas) if doc else 0, "error": error,
                   "fases": self.fases[:self._fase_i + (1 if ok else 0)]}
        resumen["carpeta"] = str(self.carpeta_informes or "")
        resumen["archivos"] = list(self.archivos_informes)
        if ok:
            texto = (f"«{resumen['titulo']}»: {n_esc} escenas, {resumen['personajes']} personajes, con su escaleta, "
                     "pizarra y fichas. Quedó como proyecto nuevo, sin guardar (Ctrl+S): revísalo y hazlo tuyo.")
            if self.archivos_informes:
                texto += f"\n📑 {len(self.archivos_informes)} archivos (guion en PDF e informes) en Documentos."
        elif error:
            texto = f"⚠ {error}\nLo escrito hasta aquí quedó en el proyecto (sin guardar)."
        else:
            texto = "Lo escrito hasta aquí quedó en el proyecto (sin guardar): puedes seguir tú."
        self.panel.final(ok, texto)
        self.terminado.emit(resumen)

    # ── ventanas ──
    def _abrir(self, w) -> None:
        self._cerrar_ventana()
        self.ventana = w
        try:
            w.setModal(False)
        except Exception:
            pass
        w.show()
        w.raise_()
        self.panel.raise_()

    def _cerrar_ventana(self) -> None:
        w, self.ventana = self.ventana, None
        if w is not None:
            try:
                w.close()
            except Exception:
                pass

    def _cerrar_y_seguir(self, ms: int = 900) -> None:
        self._pausa(ms, lambda: (self._cerrar_ventana(), self._siguiente_fase()))

    # ── pedirle a la IA (de a trozos) ──
    def _pedir(self, mensajes: list, formato, num_predict: int, temperatura: float, al_trozo, al_listo) -> None:
        self._texto, self._cb_trozo, self._cb_listo = "", al_trozo, al_listo
        h = HiloOllama(self.host, "chat", {"modelo": self.modelo, "mensajes": mensajes, "num_ctx": self.num_ctx,
                                           "format": formato, "num_predict": num_predict,
                                           "temperatura": temperatura}, self)
        h.trozo.connect(self._al_trozo)
        h.listo.connect(self._al_listo)
        h.fallo.connect(self._al_fallo)
        h.finished.connect(h.deleteLater)
        self.hilo = h
        h.start()

    def _al_trozo(self, t: str) -> None:
        if self.sender() is not self.hilo or not self.activo():
            return
        self._texto += t
        if self._cb_trozo is not None:
            d = json_parcial(self._texto)
            if d is not None:
                self._cb_trozo(d)

    def _al_listo(self, txt: str) -> None:
        if self.sender() is not self.hilo or not self.activo():
            return
        self.hilo = None
        self._cb_listo(txt or self._texto)

    def _al_fallo(self, error: str) -> None:
        if self.sender() is not self.hilo:
            return
        self.hilo = None
        self._fallar(error)

    def _msgs(self, sistema: str, pedido: str) -> list:
        return [{"role": "system", "content": sistema}, {"role": "user", "content": pedido}]

    def _panel(self, etiqueta: str):
        return lambda t: self.panel.escribe(etiqueta, t)

    # ── 1. 💡 Escaleta ──
    def _f_escaleta(self) -> None:
        self.panel.lbl_ahora.setText("Pensando la historia: título, premisa, personajes y momentos…")
        w = VentanaEscaleta(self.doc, parent=self.vp)
        self._abrir(w)
        self._intentos_plan = 0
        self._pedir_plan(w)

    def _pedir_plan(self, w) -> None:
        n = int(self.pedido["escenas"])
        self._pedir(self._msgs(PROMPT_GUIONISTA, pedido_escaleta_ia(self.pedido)), ESQUEMA_ESCALETA_IA,
                    500 + 110 * n, 0.9 if self._intentos_plan == 0 else 0.6,
                    lambda d: self.esc.alimentar(self._campos_plan(w, d)), lambda txt: self._plan_listo(w, txt))

    def _campos_plan(self, w, d) -> list:
        if not isinstance(d, dict):
            return []
        cs = []
        if d.get("titulo"):
            cs.append(("titulo", str(d["titulo"]).strip("«»\"' "), self._set_titulo))
        if d.get("premisa"):
            cs.append(("premisa", str(d["premisa"]), lambda t: self._set_premisa(w, t)))
        for i, e in enumerate(d.get("escenas") or []):
            if isinstance(e, dict) and e.get("resumen"):
                cs.append((("punto", i), str(e["resumen"]), lambda t, i=i: self._set_punto(w, i, t)))
        return cs

    def _set_titulo(self, t: str) -> None:
        self.doc.titulo = t
        self.panel.lbl_titulo.setText(f"«{t}»")

    def _set_premisa(self, w, t: str) -> None:
        poner_premisa(self.doc, t, getattr(w, "_ed_premisa", None))
        self.panel.escribe("Premisa", t)
        try:
            w._ed_premisa.blockSignals(True)
            w._ed_premisa.setPlainText(t)
            w._ed_premisa.moveCursor(QTextCursor.MoveOperation.End)
            w._ed_premisa.blockSignals(False)
        except Exception:
            pass

    def _set_punto(self, w, i: int, t: str) -> None:
        while len(self.doc.escaleta) <= i:
            self.doc.escaleta.append("")
        self.doc.escaleta[i] = t
        self.panel.escribe(f"Momento {i + 1}", t)
        try:
            w._refrescar()
            w.lista.setCurrentRow(i)
        except Exception:
            pass

    def _plan_listo(self, w, txt: str) -> None:
        plan = interpretar_escaleta_ia(txt, int(self.pedido["escenas"]))
        if plan is None:
            self._intentos_plan += 1
            if self._intentos_plan >= 2:
                self._fallar("La IA no logró armar la escaleta. Prueba con una idea más concreta o con un "
                             "modelo más grande (⬇ Modelos…).")
                return
            self.panel.lbl_ahora.setText("La escaleta no quedó bien: la IA lo intenta de nuevo…")
            self.esc.detener()
            self.doc.escaleta = []
            self._pedir_plan(w)
            return
        self.plan = plan
        cs = [("titulo", plan["titulo"], self._set_titulo), ("premisa", plan["premisa"],
                                                             lambda t: self._set_premisa(w, t))]
        cs += [(("punto", i), e["resumen"], lambda t, i=i: self._set_punto(w, i, t))
               for i, e in enumerate(plan["escenas"])]
        self.esc.alimentar(cs, final=True)
        self.esc.al_vaciar(lambda: self._fin_escaleta(w))

    def _fin_escaleta(self, w) -> None:
        self.doc.titulo = self.plan["titulo"]
        self.doc.premisa = self.plan["premisa"]
        self.doc.escaleta = [e["resumen"] or e["encabezado"] for e in self.plan["escenas"]]
        try:
            w._refrescar()
        except Exception:
            pass
        self._cerrar_y_seguir(1100)

    # ── 2. 🧩 Pizarra de beats ──
    def _f_pizarra(self) -> None:
        self.panel.lbl_ahora.setText("Armando la Pizarra de beats: una tarjeta por momento, unidas en orden…")
        w = VentanaBeatBoard(self.doc, parent=self.vp)
        self._abrir(w)
        self.doc.beats = []
        self._k = 0
        self._tarjeta_siguiente(w)

    def _tarjeta_siguiente(self, w) -> None:
        if not self.activo():
            return
        esc = self.plan["escenas"]
        i = self._k
        if i >= len(esc):
            self._cerrar_y_seguir(1200)
            return
        e = esc[i]
        fila, col = divmod(i, 4)
        tercio = i / max(1, len(esc))
        color = "#5b6ef5" if tercio < 0.25 else ("#f59e0b" if tercio < 0.75 else "#22c55e")
        lugar = (_locacion_desde_encabezado(e["encabezado"]) or e["encabezado"]).title()
        b = Beat(titulo=f"{i + 1}. {lugar}"[:40], descripcion=e["resumen"], color=color,
                 x=40 + col * 240, y=40 + fila * 180, w=200, h=130)
        if i > 0:
            self.doc.beats[-1].conexiones_lados.append(
                {"destino": i, "lado_origen": "right" if col else "bot", "lado_destino": "left" if col else "top"})
        self.doc.beats.append(b)
        self.panel.escribe(f"Tarjeta {i + 1}: {lugar}", e["resumen"])
        self._avance((i + 1) / len(esc))
        try:
            w._reconstruir()
            w.view.ensureVisible(b.x, b.y, b.w, b.h)
        except Exception:
            pass
        self._k += 1
        self._pausa(550, lambda: self._tarjeta_siguiente(w))

    # ── 3. 🎭 Fichas de personajes ──
    _CAMPOS_FICHA_IA = ("edad", "genero", "nacionalidad", "profesion", "biografia", "descripcion_fisica", "vestuario")

    def _f_personajes(self) -> None:
        for p_ in self.plan["personajes"]:
            self.doc.fichas.setdefault(p_["nombre"], Ficha(personaje=p_["nombre"]))
        if not self.plan["personajes"]:
            self._siguiente_fase()
            return
        w = VentanaFichasPersonaje(self.doc.fichas, documento=self.doc, parent=self.vp)
        self._abrir(w)
        self._k = 0
        self._personaje_siguiente(w)

    def _personaje_siguiente(self, w, intento: int = 0, repetida: str = "") -> None:
        if not self.activo():
            return
        pers = self.plan["personajes"]
        if self._k >= len(pers):
            self._cerrar_y_seguir(900)
            return
        p_ = pers[self._k]
        nombre = p_["nombre"]
        anteriores = [x["nombre"] for x in pers[:self._k]]
        if repetida:
            self.panel.lbl_ahora.setText(f"La ficha de {nombre} salió igual a la de {repetida}: la IA la escribe "
                                         "de nuevo…")
        else:
            self.panel.lbl_ahora.setText(f"Llenando la ficha de {nombre} ({self._k + 1} de {len(pers)})…")
        self._mostrar_ficha_ia(w, nombre)

        def campos(d):
            if not isinstance(d, dict):
                return []
            return [(("ficha", nombre, c, intento), str(d[c]),
                     lambda t, c=c: self._set_campo_ficha(w, nombre, c, t))
                    for c in d if c in self._CAMPOS_FICHA_IA and d.get(c)]

        def listo(txt):
            d = json_parcial(txt) or {}
            if not isinstance(d, dict):
                d = {}
            otro = ficha_repetida_ia(d, self.doc.fichas, nombre, anteriores)
            if otro:                                  # (🎭 copió la ficha de otro personaje)
                self.esc.detener()
                if intento == 0:
                    self._limpiar_ficha_ia(w, nombre)
                    self._personaje_siguiente(w, 1, otro)
                    return
                d = ficha_sin_copia_ia(d, self.doc.fichas[otro], p_["descripcion"])
                self._limpiar_ficha_ia(w, nombre)
            if not str(d.get("biografia") or "").strip():
                d["biografia"] = p_["descripcion"]
            self.esc.alimentar(campos(d), final=True)
            self.esc.al_vaciar(lambda: self._fin_personaje(w, nombre))
        hechas = [(n_, self.doc.fichas[n_]) for n_ in anteriores if n_ in self.doc.fichas]
        self._pedir(self._msgs(PROMPT_EQUIPO_IA, pedido_ficha_personaje_ia(self.plan, p_, hechas, repetida)),
                    ESQUEMA_FICHA_PERSONAJE_IA, 500, 0.8 if not intento else 0.5,
                    lambda d: self.esc.alimentar(campos(d)), listo)

    def _limpiar_ficha_ia(self, w, nombre: str) -> None:
        """Borra lo que la IA había escrito en esa ficha (para escribirla de nuevo)."""
        f = self.doc.fichas.get(nombre)
        self._mostrar_ficha_ia(w, nombre)
        for c in self._CAMPOS_FICHA_IA:
            if f is not None:
                setattr(f, c, "")
            wd = getattr(w, "_widgets", {}).get(c)
            if isinstance(wd, QLineEdit):
                wd.setText("")
            elif isinstance(wd, QPlainTextEdit):
                wd.setPlainText("")

    def _mostrar_ficha_ia(self, w, nombre: str) -> None:
        """La ventana muestra la ficha que la IA está llenando, aunque se haya
        elegido otra en la lista mientras escribía: así lo que escribe nunca
        cae en la ficha de otro personaje (antes, la del primero quedaba
        copiada en la del segundo)."""
        try:
            if w._nombre_actual != nombre:
                w._guardar_actual()                   # (lo que se veía queda en su propia ficha)
            item = w._lista.currentItem()
            if item is None or item.text() != nombre:
                if not w._lista.findItems(nombre, Qt.MatchFlag.MatchExactly):
                    w._refrescar_lista()
                w._lista.blockSignals(True)           # (sin _on_seleccion: se carga aquí mismo)
                w._seleccionar(nombre)
                w._lista.blockSignals(False)
            if w._nombre_actual != nombre:
                w._cargar_ficha(nombre)
        except Exception:
            try:
                w._lista.blockSignals(False)
            except Exception:
                pass

    def _set_campo_ficha(self, w, nombre: str, campo: str, t: str) -> None:
        f = self.doc.fichas.get(nombre)
        if f is not None:
            setattr(f, campo, t)
        self.panel.escribe(f"{nombre} · {campo.replace('_', ' ')}", t)
        self._mostrar_ficha_ia(w, nombre)
        try:
            wd = w._widgets.get(campo)
            if isinstance(wd, QLineEdit):
                wd.setText(t)
            elif isinstance(wd, QPlainTextEdit):
                wd.setPlainText(t)
                wd.moveCursor(QTextCursor.MoveOperation.End)
                wd.ensureCursorVisible()
            padre = wd.parentWidget() if wd is not None else None
            while padre is not None and not isinstance(padre, QScrollArea):
                padre = padre.parentWidget()
            if padre is not None and padre.widget() is not None:
                # (el campo que se escribe, a la vista: solo hacia abajo, sin correr la ficha de lado)
                y = wd.mapTo(padre.widget(), QPoint(0, 0)).y()
                sb = padre.verticalScrollBar()
                alto = padre.viewport().height()
                if y < sb.value() or y + wd.height() > sb.value() + alto:
                    sb.setValue(max(0, y - alto // 3))
                padre.horizontalScrollBar().setValue(0)
        except Exception:
            pass

    def _fin_personaje(self, w, nombre: str = "") -> None:
        if nombre:
            self._mostrar_ficha_ia(w, nombre)
        try:
            if not nombre or w._nombre_actual == nombre:
                w._guardar_actual()
        except Exception:
            pass
        self._k += 1
        self._avance(self._k / max(1, len(self.plan["personajes"])))
        self._pausa(600, lambda: self._personaje_siguiente(w))

    # ── 4. ✍ El guion, escena por escena ──
    def _f_guion(self) -> None:
        self._cerrar_ventana()
        self.vp.raise_()
        self.vp.activateWindow()
        self.panel.raise_()
        self._k = 0
        self._previo = ""
        self._escena_siguiente()

    def _escena_siguiente(self) -> None:
        if not self.activo():
            return
        esc = self.plan["escenas"]
        k = self._k
        if k >= len(esc):
            self._pausa(800, self._siguiente_fase)
            return
        e = esc[k]
        ed = self.vp.editor
        self.panel.lbl_ahora.setText(f"Escribiendo la escena {k + 1} de {len(esc)}: {e['encabezado']}")
        self._creados: dict = {}
        self._escena_bl: list = []
        nombres = [p_["nombre"] for p_ in self.plan["personajes"]]
        enc = normalizar_encabezado_ia(e["encabezado"])

        def set_enc(t):
            if "enc" not in self._creados:
                self._creados["enc"] = ed.ia_bloque_nuevo(Elem.ESCENA)
            ed.ia_texto(self._creados["enc"], t)
        self.esc.poner(("enc", k), enc, set_enc, cerrado=True)

        def campos(d):
            cs = []
            for j, b in enumerate((d.get("bloques") if isinstance(d, dict) else None) or []):
                if not isinstance(b, dict) or "texto" not in b:
                    break                            # (todavía no se sabe qué tipo es)
                tipo = str(b.get("tipo") or "")
                cs.append((("bl", k, j), str(b.get("texto") or ""),
                           lambda t, j=j, tipo=tipo: self._set_bloque(j, tipo, t),
                           lambda t, j=j, tipo=tipo: self._fin_bloque(j, tipo, t, nombres)))
            return cs

        def listo(txt):
            d = json_parcial(txt)
            lista = d.get("bloques") if isinstance(d, dict) else None
            if lista:
                self.esc.alimentar(campos(d), final=True)
            else:                                    # (no llegó JSON: el texto, como antes)
                tipos = {v: k_ for k_, v in _ELEM_IA.items()}
                pz = piezas_desde_texto_guion("\n" + limpiar_escena_ia(txt, nombres) + "\n")
                falsos = {"bloques": [{"tipo": tipos.get(Elem(int(x["elem"])), "accion"), "texto": x["texto"]}
                                      for x in pz if Elem(int(x["elem"])) != Elem.ESCENA]}
                self.esc.alimentar(campos(falsos), final=True)
            self.esc.al_vaciar(lambda: self._fin_escena(e))
        palabras = palabras_por_escena_ia(int(self.pedido.get("minutos", len(esc))), len(esc))
        self._pedir(mensajes_escena_ia(self.plan, k, self._previo, palabras), ESQUEMA_ESCENA_IA,
                    min(1800, int(palabras * 3.4) + 160), 0.85, lambda d: self.esc.alimentar(campos(d)), listo)

    def _set_bloque(self, j: int, tipo: str, t: str) -> None:
        ed = self.vp.editor
        if j not in self._creados:
            self._creados[j] = ed.ia_bloque_nuevo(_ELEM_IA.get(tipo.strip().lower(), Elem.ACCION))
        ed.ia_texto(self._creados[j], t)
        self.panel.escribe(f"Escena {self._k + 1}", t)

    def _fin_bloque(self, j: int, tipo: str, t: str, nombres: list) -> None:
        ed = self.vp.editor
        previo = self._escena_bl[-1][0] if self._escena_bl else None
        r = corregir_bloque_ia(tipo, t, previo, nombres)
        idx = self._creados.get(j)
        if not r:
            if idx is not None and idx == len(self.doc.bloques) - 1 and len(self.doc.bloques) > 1:
                ed.ia_quitar_ultimo()                 # (un bloque vacío: fuera, sin volver a armar la hoja)
                self._creados.pop(j, None)
            return
        if idx is None:
            idx = ed.ia_bloque_nuevo(r[0][0])
        ed.ia_texto(idx, r[0][1], elem=r[0][0])
        for el, tx in r[1:]:
            ed.ia_bloque_nuevo(el, tx)
        self._escena_bl += r

    def _fin_escena(self, e: dict) -> None:
        # (un bloque que quedó vacío, al final: se quita)
        bl = self.doc.bloques
        while len(bl) > 1 and not bl[-1].texto.strip() and bl[-1].elem != Elem.ESCENA:
            self.vp.editor.ia_quitar_ultimo()
        e["bloques"] = list(self._escena_bl)
        e["texto"] = texto_de_bloques_ia(self._escena_bl)
        self._previo = e["texto"][-900:]
        self._k += 1
        self._avance(self._k / len(self.plan["escenas"]))
        self._pausa(500, self._escena_siguiente)

    def _texto_escena(self, i: int) -> str:
        e = self.plan["escenas"][i]
        return e.get("texto") or e.get("resumen", "")

    # ── 5. 📄 Fichas de escenas (análisis dramático) ──
    def _f_analisis(self) -> None:
        w = VentanaFichasEscenas(self.doc, self.vp)
        self._abrir(w)
        self._k = 0
        self._analisis_siguiente(w)

    def _analisis_siguiente(self, w) -> None:
        if not self.activo():
            return
        esc = self.plan["escenas"]
        k = self._k
        if k >= len(esc) or "texto" not in esc[k]:
            self._cerrar_y_seguir(900)
            return
        self.panel.lbl_ahora.setText(f"Analizando la escena {k + 1} de {len(esc)}: propósito, objetivo, "
                                     "obstáculo, subtexto y tono…")
        try:
            num = w._lista.item(k).data(Qt.ItemDataRole.UserRole)
        except Exception:
            num = None
        num = num if num is not None else k + 1
        self._mostrar_escena_ia(w, k, num)
        mapa = {"proposito": "_ed_proposito", "objetivo_protagonista": "_ed_objetivo", "obstaculo": "_ed_obstaculo",
                "subtexto": "_ed_subtexto", "tono": "_ed_tono"}

        def setter(c):
            def _s(t):
                self.panel.escribe(f"Escena {k + 1} · {c.replace('_', ' ')}", t)
                self._ficha_escena_ia(num, k)[c] = t     # (en su escena, aunque se mire otra)
                self._mostrar_escena_ia(w, k, num)
                try:
                    ed_ = getattr(w, mapa[c])
                    ed_.blockSignals(True)               # (sin «cambios sin guardar»: ya quedó en la escena)
                    ed_.setPlainText(t)
                    ed_.blockSignals(False)
                    ed_.moveCursor(QTextCursor.MoveOperation.End)
                except Exception:
                    pass
            return _s

        def campos(d):
            return [(("an", k, c), str(d[c]), setter(c)) for c in (d if isinstance(d, dict) else {})
                    if c in mapa and d.get(c)]

        def listo(txt):
            self.esc.alimentar(campos(json_parcial(txt) or {}), final=True)
            self.esc.al_vaciar(lambda: self._fin_analisis(w, k, num))
        self._pedir(self._msgs(PROMPT_EQUIPO_IA, pedido_analisis_escena_ia(self.plan, k, self._texto_escena(k))),
                    ESQUEMA_ANALISIS_ESCENA_IA, 380, 0.6, lambda d: self.esc.alimentar(campos(d)), listo)

    def _ficha_escena_ia(self, num, k: int) -> dict:
        """La ficha de la escena «num» en el proyecto (un dict), para escribir en ella."""
        v = self.doc.fichas_escenas.get(str(num))
        if isinstance(v, FichaEscena):
            v = asdict(v)
        if not isinstance(v, dict):
            v = {}
        v.setdefault("numero", num)
        try:
            v.setdefault("encabezado", normalizar_encabezado_ia(self.plan["escenas"][k]["encabezado"]))
        except Exception:
            pass
        self.doc.fichas_escenas[str(num)] = v
        return v

    def _mostrar_escena_ia(self, w, k: int, num) -> None:
        """La ventana muestra la escena que la IA está analizando, aunque se haya
        elegido otra mientras escribía (sin preguntar por cambios sin guardar:
        lo escrito ya está en su escena)."""
        try:
            if w._escena_actual != num or w._lista.currentRow() != k:
                w._dirty = False
                w._lista.setCurrentRow(k)
        except Exception:
            pass

    def _fin_analisis(self, w, k: int, num=None) -> None:
        if num is not None:
            self._mostrar_escena_ia(w, k, num)
        try:
            if num is None or w._escena_actual == num:
                w._guardar_ficha()
        except Exception:
            pass
        self._k += 1
        self._avance(self._k / len(self.plan["escenas"]))
        self._pausa(500, lambda: self._analisis_siguiente(w))

    # ── 6. 📍 Locaciones, en el Centro de Producción ──
    def _f_locaciones(self) -> None:
        try:
            self.vp._auto_crear_locaciones_desde_escenas()
        except Exception:
            pass
        self.vp._accion_centro_produccion()
        cp = self.vp._centro_produccion
        self.panel.raise_()
        try:
            cp._filtrar(2)                            # (📍 Locaciones)
        except Exception:
            pass
        lugares = []
        for e in self.plan["escenas"]:
            n = _locacion_desde_encabezado(normalizar_encabezado_ia(e["encabezado"]))
            if not n or n == "SIN LOCACIÓN":
                continue
            fila = next((x for x in lugares if x[0] == n), None)
            if fila is None:
                lugares.append((n, [e["resumen"]]))
            else:
                fila[1].append(e["resumen"])
        if not lugares:
            self._pausa(500, self._siguiente_fase)
            return
        self.panel.lbl_ahora.setText(f"Describiendo {len(lugares)} locación(es): qué necesita cada lugar para filmar…")
        claves = {_clave_nombre(k_): k_ for k_ in self.doc.locaciones}

        def setter(nombre):
            def _s(t):
                k_ = claves.get(_clave_nombre(nombre))
                if k_ is not None:
                    self.doc.locaciones[k_].detalles = t
                self.panel.escribe(f"📍 {nombre}", t)
            return _s

        def al_fin(nombre):
            def _f(_t):
                try:
                    cp._refrescar_grilla()
                    for i_ in range(cp._grilla.count()):
                        wd = cp._grilla.itemAt(i_).widget()
                        if isinstance(wd, TarjetaProduccion) and _clave_nombre(wd.nombre) == _clave_nombre(nombre):
                            cp._al_click_tarjeta(wd)
                            break
                except Exception:
                    pass
            return _f

        def campos(d):
            cs = []
            for i_, x in enumerate((d.get("locaciones") if isinstance(d, dict) else None) or []):
                if isinstance(x, dict) and x.get("nombre") and x.get("detalles"):
                    n = str(x["nombre"])
                    cs.append((("loc", i_), str(x["detalles"]), setter(n), al_fin(n)))
            return cs

        def listo(txt):
            self.esc.alimentar(campos(json_parcial(txt) or {}), final=True)
            self.esc.al_vaciar(lambda: self._pausa(1200, self._siguiente_fase))
        self._pedir(self._msgs(PROMPT_EQUIPO_IA, pedido_locaciones_ia(self.plan, lugares)), ESQUEMA_LOCACIONES_IA,
                    160 + 140 * len(lugares), 0.7, lambda d: self.esc.alimentar(campos(d)), listo)

    # ── 7. 🎥 Lista de planos ──
    def _f_planos(self) -> None:
        cp = getattr(self.vp, "_centro_produccion", None)
        if cp is not None:
            cp.hide()
        w = VentanaPlanos(self.vp, parent=self.vp)
        self._abrir(w)
        self._k = 0
        self._planos_siguiente(w)

    def _planos_siguiente(self, w) -> None:
        if not self.activo():
            return
        esc = self.plan["escenas"]
        k = self._k
        if k >= len(esc) or "texto" not in esc[k]:
            self._cerrar_y_seguir(900)
            return
        self.panel.lbl_ahora.setText(f"Proponiendo los planos de la escena {k + 1} de {len(esc)}…")
        try:
            w._lista.setCurrentRow(k)
        except Exception:
            pass

        def al_fin(x):
            def _f(_t):
                try:
                    q_ = str(x.get("quien") or "").strip()
                    w._agregar({"tamano": x.get("tamano", ""), "angulo": x.get("angulo", ""),
                                "movimiento": x.get("movimiento", ""), "descripcion": x.get("descripcion", ""),
                                "ia_quien": "" if q_.lower() in ("", "varios") else q_})
                except Exception:
                    pass
            return _f

        def campos(d):
            cs = []
            for i_, x in enumerate((d.get("planos") if isinstance(d, dict) else None) or []):
                if isinstance(x, dict) and x.get("descripcion"):
                    etq = " · ".join(str(x.get(c_, "")) for c_ in ("tamano", "angulo", "movimiento") if x.get(c_))
                    cs.append((("pl", k, i_), str(x["descripcion"]), self._panel(f"Plano {i_ + 1}: {etq}"),
                               al_fin(dict(x))))
            return cs

        def listo(txt):
            self.esc.alimentar(campos(json_parcial(txt) or {}), final=True)
            self.esc.al_vaciar(lambda: self._fin_planos(w))
        nombres = [p_["nombre"] for p_ in self.plan["personajes"]]
        self._pedir(self._msgs(PROMPT_EQUIPO_IA, pedido_planos_ia(self.plan, k, self._texto_escena(k))),
                    esquema_planos_ia(nombres), 560, 0.7, lambda d: self.esc.alimentar(campos(d)), listo)

    def _fin_planos(self, w) -> None:
        self._k += 1
        self._avance(self._k / len(self.plan["escenas"]))
        self._pausa(500, lambda: self._planos_siguiente(w))

    # ── 8. 🎞 Storyboard 3D: un cuadro por plano, con la escena armada ──
    def _f_storyboard(self) -> None:
        escenas = sorted({int(x.get("escena", 0) or 0) for x in (getattr(self.doc, "planos", None) or [])
                          if isinstance(x, dict)} - {0})
        if not escenas:
            self._pausa(300, self._siguiente_fase)
            return
        registrar_doc_3d(self.doc)
        w = VentanaStoryboard(self.vp, parent=self.vp, escena_inicial=escenas[0])
        self._abrir(w)
        self._sb_escenas = escenas
        self._k = 0
        self._sb_escena(w)

    def _sb_escena(self, w) -> None:
        if not self.activo():
            return
        if self._k >= len(self._sb_escenas):
            try:
                w._llenar_filtro(0)
                w._cambio_filtro()
            except Exception:
                pass
            self._cerrar_y_seguir(1500)
            return
        n = self._sb_escenas[self._k]
        self.panel.lbl_ahora.setText(f"Storyboard 3D de la escena {n}: los personajes en su lugar y una cámara "
                                     "por plano…")
        try:
            preparar_3d_storyboard(self.doc, {n})
            apuntar_camaras_ia(self.doc, n)
        except Exception:
            pass
        cuadros = cuadros_ordenados(self.doc, {n})
        for pl in cuadros:
            pl["sb_fondo_3d"] = True                  # (el cuadro muestra la escena en 3D)
        try:
            actualizar_fotos_3d(self.doc, n)
        except Exception:
            pass
        try:
            w._llenar_filtro(n)
            w._cambio_filtro()
        except Exception:
            pass
        self._sb_cuadros = cuadros
        self._j = 0
        self._sb_cuadro(w, n)

    def _sb_cuadro(self, w, n: int) -> None:
        if not self.activo():
            return
        if self._j >= len(self._sb_cuadros):
            self._k += 1
            self._avance(self._k / len(self._sb_escenas))
            self._pausa(500, lambda: self._sb_escena(w))
            return
        pl = self._sb_cuadros[self._j]
        tec = " · ".join(str(pl.get(c_, "")) for c_ in ("tamano", "angulo", "movimiento") if pl.get(c_))
        self.panel.escribe(f"🎞 Escena {n} · plano {pl.get('numero', self._j + 1)}",
                           f"{tec}\n{pl.get('descripcion', '')}")
        try:
            w.abrir_editor(pl["id"], vista="camara")
        except Exception:
            pass
        self._j += 1
        self._pausa(1400, lambda: self._sb_cuadro(w, n))

    # ── 10. 📑 Informes y PDF, en una carpeta ──
    def _f_informes(self) -> None:
        self._cerrar_ventana()
        cp = getattr(self.vp, "_centro_produccion", None)
        if cp is not None and cp.isVisible():
            cp.close()
        try:
            for i_ in range(self.vp.ribbon.count()):  # (la pestaña Informes, a la vista)
                if "informes" in self.vp.ribbon.tabText(i_).lower():
                    self.vp.ribbon.setCurrentIndex(i_)
                    break
        except Exception:
            pass
        self.vp.raise_()
        self.panel.raise_()
        try:
            self.carpeta_informes = carpeta_informes_ia(self.doc.titulo, self.base_informes)
            self.carpeta_informes.mkdir(parents=True, exist_ok=True)
        except Exception as ex:
            self.panel.escribe("📑 Informes", f"No pude crear la carpeta: {ex}")
            self._pausa(800, self._siguiente_fase)
            return
        self.panel.lbl_ahora.setText(f"Sacando el guion en PDF y los informes en «{self.carpeta_informes.name}»…")
        tareas = [("📕 El guion", "Guion.pdf", self._pdf_guion),
                  ("📖 Informe narrativo", "Informe narrativo.pdf", lambda r: self._informe("narrativo", r))]
        if self.doc.escaleta or self.doc.beats:
            tareas.append(("🧩 Estructura", "Estructura.pdf", lambda r: self._informe("estructura", r)))
        tareas += [("🎭 Personajes", "Personajes.pdf", lambda r: self._informe("personajes", r)),
                   ("🎬 Escenas", "Escenas.pdf", lambda r: self._informe("escenas", r))]
        if self.doc.locaciones or self.doc.jornadas:
            tareas.append(("💰 Producción", "Producción.pdf", lambda r: self._informe("produccion", r)))
        if self.doc.locaciones:
            tareas.append(("📍 Locaciones", "Locaciones.pdf", lambda r: self._informe("locaciones", r)))
        if any((getattr(f, "actor_nombre", "") or "").strip() for f in (self.doc.fichas or {}).values()):
            tareas.append(("🎭 Actores", "Actores.pdf", lambda r: self._informe("actores", r)))
        if getattr(self.doc, "planos", None):
            tareas.append(("🎥 Lista de planos", "Lista de planos.pdf", self._pdf_planos))
            if any(isinstance(x, dict) and x.get("sb_fondo_3d") for x in self.doc.planos):
                tareas.append(("🎞 Storyboard", "Storyboard.pdf",
                               lambda r: exportar_storyboard_pdf(self.doc, r, cuadros_ordenados(self.doc))))
        if self.doc.jornadas:
            tareas.append(("📅 Carta Gantt", "Carta Gantt.pdf", lambda r: self._informe("gantt_html", r)))
            tareas.append(("📅 Carta Gantt interactiva", "Carta Gantt.html", self._html_gantt))
        self._tareas_inf = tareas
        self._k = 0
        self._lista_inf: list = []
        self._informe_siguiente()

    def _informe_siguiente(self) -> None:
        if not self.activo():
            return
        if self._k >= len(self._tareas_inf):
            self._pausa(1200, self._siguiente_fase)
            return
        etq, nombre, fn = self._tareas_inf[self._k]
        ruta = self.carpeta_informes / nombre
        try:
            fn(ruta)
            if ruta.is_file() and ruta.stat().st_size > 0:
                self.archivos_informes.append(str(ruta))
                self._lista_inf.append(f"✓ {etq}: {nombre}")
            else:
                self._lista_inf.append(f"— {etq}: no salió")
        except Exception as ex:
            self._lista_inf.append(f"⚠ {etq}: {ex}")
        self.panel.escribe(f"📑 {self.carpeta_informes.name}", "\n".join(self._lista_inf))
        self._k += 1
        self._avance(self._k / len(self._tareas_inf))
        self._pausa(500, self._informe_siguiente)

    def _pdf_guion(self, ruta: Path) -> None:
        self.vp._render_pdf_directo(ruta, "", 0, self.vp._opciones_pdf_guardadas())

    def _informe(self, clave: str, ruta: Path) -> None:
        info = self.vp._construir_informe(clave, self.doc)
        if info:
            self.vp._render_uno(info, ruta, "pdf", False, False)

    def _pdf_planos(self, ruta: Path) -> None:
        w = VentanaPlanos(self.vp, parent=self.vp)
        try:
            w.exportar_a(ruta, "pdf")
        finally:
            w.deleteLater()

    def _html_gantt(self, ruta: Path) -> None:
        info = self.vp._construir_informe("gantt_html", self.doc)
        if info and info.get("html_interactivo"):
            ruta.write_text(info["html_interactivo"], encoding="utf-8")

    # ── 9. 📊 Plan de rodaje, en la Carta Gantt ──
    def _f_rodaje(self) -> None:
        self._cerrar_ventana()
        cp = getattr(self.vp, "_centro_produccion", None)
        if cp is None or not cp.isVisible():
            self.vp._accion_centro_produccion()
            cp = self.vp._centro_produccion
        cp.show()
        cp.raise_()
        self.panel.raise_()
        self.panel.lbl_ahora.setText("Armando el plan de rodaje: una jornada por locación…")
        self._jornadas = jornadas_propuestas_ia(self.doc)
        self._k = 0
        self._jornada_siguiente(cp)

    def _jornada_siguiente(self, cp) -> None:
        if not self.activo():
            return
        if self._k >= len(self._jornadas):
            self._pausa(1600, self._siguiente_fase)
            return
        j = self._jornadas[self._k]
        self.doc.jornadas.append(j)
        self.panel.escribe(j.nombre, f"Escenas {j.escenas} · actúan: {j.actores or '—'}\n{j.notas}")
        try:
            cp._abrir_planificacion("gantt")
        except Exception:
            pass
        self._k += 1
        self._avance(self._k / len(self._jornadas))
        self._pausa(900, lambda: self._jornada_siguiente(cp))


class DialogoGuionIA(QDialog):
    """✍ La IA escribe un guion original a partir de una idea: primero la
    escaleta y después escena por escena. Se abre como un proyecto nuevo,
    marcado como escrito con IA."""

    def __init__(self, vp, host: str, modelo: str, num_ctx: int = 8192, parent=None):
        super().__init__(parent)
        self.vp, self.host, self.modelo, self.num_ctx = vp, host, modelo, num_ctx
        self.setWindowTitle("✍  Escribir un guion con IA")
        self.resize(px(620), px(520))
        self._hilo: Optional[HiloGuionIA] = None
        self.resultado: Optional[dict] = None
        self.abierto = False
        v = QVBoxLayout(self)
        mo = next((x for x in MODELOS_ASESOR if modelo in (x["tag"], x["alt"])), None)
        aviso_mo = ""
        if mo is not None and mo["capacidad"] <= 2:
            aviso_mo = (f" Con <b>{html.escape(mo['apodo'])}</b> el resultado es básico: sirve como borrador "
                        "para corregir. Hitchcock y Tarantino escriben mejor.")
        intro = QLabel("La IA escribe un <b>guion original</b> a partir de tu idea: primero la escaleta y después "
                       "una escena a la vez. Se abre como un <b>proyecto nuevo</b>, marcado como escrito con IA, "
                       "para que lo revises, lo corrijas y lo hagas tuyo. Modelo: "
                       f"<b>{html.escape(nombre_modelo_con_apodo(modelo))}</b>.{aviso_mo}")
        intro.setWordWrap(True)
        v.addWidget(intro)
        v.addWidget(QLabel("<b>Tu idea</b> (de qué trata, quién quiere qué, dónde pasa):"))
        self.ed_idea = QPlainTextEdit()
        self.ed_idea.setPlaceholderText("Ej: Una estudiante quiere grabar un documental sobre su liceo antes de "
                                        "que lo cierren, pero el director se lo prohíbe.")
        self.ed_idea.setFixedHeight(px(86))
        v.addWidget(self.ed_idea)
        premisa = str(getattr(vp.editor.documento, "premisa", "") or "").strip()
        if premisa:
            b_prem = QPushButton("↳ Usar la premisa de mi guion")
            b_prem.setFlat(True)
            b_prem.clicked.connect(lambda: self.ed_idea.setPlainText(premisa))
            v.addWidget(b_prem, 0, Qt.AlignmentFlag.AlignLeft)
        form = QFormLayout()
        self.cb_genero = QComboBox()
        self.cb_genero.addItems(GENEROS_GUION_IA)
        form.addRow("Género:", self.cb_genero)
        self.cb_duracion = QComboBox()
        for minutos, escenas in DURACIONES_GUION_IA:
            self.cb_duracion.addItem(f"{minutos} minutos  ({escenas} escenas)", (minutos, escenas))
        self.cb_duracion.setCurrentIndex(1)
        form.addRow("Duración:", self.cb_duracion)
        self.ed_pers = QLineEdit()
        self.ed_pers.setPlaceholderText("Opcional. Ej: ANA, 17, curiosa; BRUNO, su amigo, miedoso")
        form.addRow("Personajes:", self.ed_pers)
        self.cb_alcance = QComboBox()
        for nombre_, _n in ALCANCES_GUION_IA:
            self.cb_alcance.addItem(nombre_)
        self.cb_alcance.setCurrentIndex(len(ALCANCES_GUION_IA) - 1)
        form.addRow("Hasta dónde:", self.cb_alcance)
        v.addLayout(form)
        self.chk_vivo = QCheckBox(f"🎬  Ver cómo el {NOMBRE_IA} usa el programa: abre la Escaleta, la Pizarra, las "
                                  "fichas, el Centro de Producción, el Storyboard 3D… escribe a la vista y al final "
                                  "saca los informes (con «■ Cancelar»)")
        self.chk_vivo.setChecked(True)
        self.chk_vivo.toggled.connect(self.cb_alcance.setEnabled)
        v.addWidget(self.chk_vivo)
        self.pedido_vivo: Optional[dict] = None
        self.lbl_estado = QLabel("<span style='color:#94a3b8;font-size:9pt;'>Puede tardar varios minutos "
                                 "(escribe una escena a la vez). Puedes detenerlo: se abre lo que alcanzó a "
                                 "escribir.</span>")
        self.lbl_estado.setWordWrap(True)
        v.addWidget(self.lbl_estado)
        self.barra = QProgressBar()
        self.barra.setRange(0, 1000)
        self.barra.hide()
        v.addWidget(self.barra)
        v.addStretch()
        fila = QHBoxLayout()
        fila.addStretch()
        self.b_escribir = QPushButton("✍ Escribir el guion")
        self.b_escribir.setDefault(True)
        self.b_escribir.clicked.connect(self.escribir)
        self.b_detener = QPushButton("■ Detener")
        self.b_detener.clicked.connect(self.detener)
        self.b_detener.hide()
        self.b_cerrar = QPushButton("Cerrar")
        self.b_cerrar.clicked.connect(self.close)
        for b_ in (self.b_escribir, self.b_detener, self.b_cerrar):
            fila.addWidget(b_)
        v.addLayout(fila)

    def pedido(self) -> dict:
        minutos, escenas = self.cb_duracion.currentData()
        return {"idea": self.ed_idea.toPlainText().strip(), "genero": self.cb_genero.currentText(),
                "minutos": int(minutos), "escenas": int(escenas), "personajes": self.ed_pers.text().strip()}

    def escribir(self) -> bool:
        if self._hilo is not None:
            return False
        if self.resultado is not None and not self.abierto:
            return self._abrir()                     # (ya está escrito: falta abrirlo)
        p_ = self.pedido()
        if len(p_["idea"]) < 8:
            self.lbl_estado.setText("<span style='color:#fbbf24;'>Escribe tu idea en una o dos frases.</span>")
            self.ed_idea.setFocus()
            return False
        if self.chk_vivo.isChecked():                # (🎬 en vivo: lo hace el director, a la vista)
            self.pedido_vivo = dict(p_, alcance=self.cb_alcance.currentIndex())
            self.accept()
            return True
        self._hilo = HiloGuionIA(self.host, self.modelo, p_, self.num_ctx, self)
        self._hilo.progreso.connect(self._progreso)
        self._hilo.terminado.connect(self._terminado)
        self._hilo.fallo.connect(self._fallo)
        self._hilo.finished.connect(self._fin)
        for w in (self.ed_idea, self.cb_genero, self.cb_duracion, self.ed_pers, self.b_escribir):
            w.setEnabled(False)
        self.b_detener.show()
        self.barra.setValue(0)
        self.barra.show()
        self._hilo.start()
        return True

    def detener(self) -> None:
        if self._hilo is not None:
            self._hilo.cancelar()

    def reject(self) -> None:
        if self._hilo is not None:                   # (Esc mientras escribe: pregunta, como al cerrar)
            self.close()
            return
        super().reject()

    def _progreso(self, texto: str, fr: float) -> None:
        self.lbl_estado.setText(html.escape(texto))
        self.barra.setValue(int(max(0.0, min(1.0, fr)) * 1000))

    def _terminado(self, res: dict) -> None:
        self.resultado = res

    def _fallo(self, error: str) -> None:
        self.lbl_estado.setText(f"<span style='color:#f87171;'>⚠ {html.escape(error)}</span>")

    def _fin(self) -> None:
        hilo, self._hilo = self._hilo, None
        if hilo is not None:
            hilo.deleteLater()
        self.b_detener.hide()
        for w in (self.ed_idea, self.cb_genero, self.cb_duracion, self.ed_pers, self.b_escribir):
            w.setEnabled(True)
        if self.resultado is not None and not self.abierto:
            self._abrir()
        else:
            self.barra.hide()

    def _abrir(self) -> bool:
        res = self.resultado or {}
        doc = documento_desde_guion_ia(res)
        if not self.vp.abrir_guion_ia(doc):
            self.b_escribir.setText("📂 Abrir el guion escrito")
            self.lbl_estado.setText("El guion está escrito, pero no se abrió. Cuando quieras, presiona "
                                    "«📂 Abrir el guion escrito».")
            return False
        self.abierto = True
        self.accept()
        return True

    def closeEvent(self, ev) -> None:
        if self._hilo is not None:
            r = QMessageBox.question(self, "Escribir un guion con IA",
                                     "La IA está escribiendo. ¿Detenerla? Se abre lo que alcanzó a escribir.")
            if r != QMessageBox.StandardButton.Yes:
                ev.ignore()
                return
            self._hilo.cancelar()
            self._hilo.wait(5000)
            QApplication.processEvents()
        super().closeEvent(ev)


