class TutorialIA(TutorialFlotante):
    """🎓 El tutorial de la IA, integrado. Parte al lado de la ventana del
    Profesor Claqueta y después la acompaña por el programa: cuando se
    abre una ventana (una ficha, Configuración, los modelos…), el
    tutorial se pasa a ella para seguir usable, y vuelve al cerrarla."""

    _NO_SEGUIR = ()          # (se llena al crear: QMessageBox, QFileDialog…)

    def __init__(self, vp, asesor):
        super().__init__("🎓  Inteligencia artificial", [{"titulo": "", "cuerpo": ""}], parent=vp)
        self.vp = vp
        self.asesor = asesor
        self._base = vp
        self._lugar = None                       # (la ventana que abrió «👉 Llévame»)
        self._conectadas: list = []
        self._cerrado = False
        from PySide6.QtWidgets import QFileDialog, QInputDialog, QColorDialog, QProgressDialog as _QPD
        TutorialIA._NO_SEGUIR = (QMessageBox, QFileDialog, QInputDialog, QColorDialog, _QPD)
        self._pasos = pasos_tutorial_ia(self)
        self._idx = 0
        self._mostrar()
        self._t_seguir = QTimer(self)
        self._t_seguir.setInterval(250)
        self._t_seguir.timeout.connect(self._seguir)
        self._t_seguir.start()
        self.ubicar_junto(asesor)

    # ── Ir con el usuario por las ventanas ──
    def ubicar_junto(self, w) -> None:
        """Al lado de `w` (a su izquierda si cabe; si no, a su derecha)."""
        if w is None:
            return
        try:
            pant = (w.screen() or QApplication.primaryScreen()).availableGeometry()
        except Exception:
            return
        g = w.frameGeometry()
        x = g.left() - self.width() - 10
        if x < pant.left():
            x = g.right() + 10
        if x + self.width() > pant.right():
            x = pant.right() - self.width()
        y = max(pant.top(), min(g.top() + 30, pant.bottom() - self.height()))
        self.move(max(pant.left(), x), y)

    def _seguir(self) -> None:
        if self._cerrado or (not self.isVisible() and self.parent() is self._base):
            return
        m_ = QApplication.activeModalWidget()
        if (m_ is not None and m_ is not self and m_ is not self.parent() and isinstance(m_, QDialog)
                and not isinstance(m_, TutorialIA._NO_SEGUIR) and m_.isVisible()):
            self.adoptar(m_)
            return
        p = self.parent()
        if p is not self._base and (p is None or not p.isVisible()):
            self.soltar()

    def adoptar(self, ventana) -> None:
        """Se pasa a una ventana modal, para seguir usable encima de ella."""
        self.setParent(ventana, self.windowFlags())
        self.ubicar_junto(ventana)
        self.show()
        self.raise_()
        if not any(c is ventana for c in self._conectadas):
            self._conectadas.append(ventana)
            try:
                ventana.finished.connect(lambda *_: self.soltar())
            except Exception:
                pass

    def soltar(self) -> None:
        """De vuelta a la ventana principal, junto al Profesor Claqueta."""
        if self.parent() is self._base:
            return
        visible = not self._cerrado
        self.setParent(self._base, self.windowFlags())
        self._conectadas = [c for c in self._conectadas if c is not None]
        self.ubicar_junto(self.asesor if self.asesor is not None and self.asesor.isVisible() else self._base)
        if visible:
            self.show()
            self.raise_()

    def _cerrar_lugar(self) -> None:
        """«Siguiente» y «Anterior» cierran el lugar que abrió el recorrido
        (cerrar guarda lo escrito, como siempre)."""
        lugar, self._lugar = self._lugar, None
        if lugar is not None and lugar.isVisible():
            self.soltar()
            lugar.close()

    def _siguiente(self) -> None:
        self._cerrar_lugar()
        super()._siguiente()

    def _anterior(self) -> None:
        self._cerrar_lugar()
        super()._anterior()

    def closeEvent(self, e) -> None:
        self._cerrado = True
        self._t_seguir.stop()
        self._cerrar_lugar()
        super().closeEvent(e)

    # ── Lo que hacen los «👉» ──
    def resaltar(self, w, texto: str = "", ms: int = 2600) -> None:
        """Marca un control con un borde naranjo un momento (y un aviso al lado)."""
        if w is None:
            return
        from PySide6.QtWidgets import QToolTip
        antes = w.styleSheet()
        borde = "border: 2px solid #ff8c1a; border-radius: 4px;"
        if "{" in antes:                     # (una hoja de estilo con selectores: se suma un bloque)
            w.setStyleSheet(f"{antes}\n{w.metaObject().className()} {{ {borde} }}")
        else:
            w.setStyleSheet(f"{antes.rstrip().rstrip(';')}; {borde}" if antes.strip() else borde)
        QTimer.singleShot(ms, lambda: w.setStyleSheet(antes))
        if texto:
            QTimer.singleShot(60, lambda: QToolTip.showText(w.mapToGlobal(QPoint(0, w.height())), texto, w))

    def _doc(self):
        return self.vp.editor.documento

    def _protagonista(self) -> str:
        try:
            self.vp._asegurar_fichas_de_personajes_del_guion()
        except Exception:
            pass
        doc = self._doc()
        try:                                  # (el que más habla: en el ejemplo, MICHELLE)
            stats = estadisticas_personajes(doc)
            if stats:
                return max(stats, key=lambda k: stats[k]["palabras"])
        except Exception:
            pass
        nombres = list((doc.fichas or {}).keys()) or personajes_del_documento(doc)
        return nombres[0] if nombres else "ANA"

    def _sugerir(self, texto: str) -> None:
        a = self.vp._accion_asesor()
        self.asesor = a
        a.sugerir(texto)

    def _abrir_lugar(self, dlg, campo: str = "", aviso: str = "", w_campo=None) -> None:
        """Abre un lugar del recorrido (modal, como siempre); el tutorial se
        pasa a él y marca el campo que la IA puede cambiar."""
        self._lugar = dlg

        def marcar():
            ok = enfocar_campo_ficha(dlg, campo, aviso) if campo else False
            if not ok and w_campo is not None:
                w_campo.setFocus()
                self.resaltar(w_campo, aviso)
            elif ok:
                w = ((getattr(dlg, "_widgets", None) or {}).get(campo)
                     or (getattr(dlg, "_widgets_datos", None) or {}).get(campo))
                self.resaltar(w)
            elif aviso:
                self.resaltar(getattr(dlg, "_lista", None), aviso)
        QTimer.singleShot(350, marcar)
        dlg.exec()
        if self._lugar is dlg:
            self._lugar = None

    def hacer(self, que: str) -> None:
        vp, a = self.vp, self.asesor
        if que == "practica":
            if preparar_guion_practica(vp, self, preguntar=False):
                vp._tutorial_asegurar_guion_completo()
                vp._asegurar_fichas_de_personajes_del_guion()
                vp._auto_crear_locaciones_desde_escenas()
                vp.statusBar().showMessage("🧪 Proyecto de práctica listo: la historia de ejemplo del liceo.", 6000)
            return
        if que in ("modelo", "consola", "pregunta", "pendientes", "modelos"):
            a = vp._accion_asesor()
            self.asesor = a
            self.ubicar_junto(a)
            self.raise_()
        if que == "modelo":
            self.resaltar(a._lbl_estado)
            self.resaltar(a._cb_modelo, "El modelo que responde (los que ya están descargados)")
        elif que == "consola":
            a._b_consola.setChecked(True)
            self.resaltar(a._b_consola, "🖥 La consola de recursos")
        elif que == "pregunta":
            a.sugerir("¿Qué le falta a mi protagonista para que el público la quiera?")
            self.resaltar(a._ed, "Envíala con Enter")
        elif que == "pendientes":
            a.pedir_pendientes()
        elif que == "modelos":
            a._elegir_y_bajar()
        elif que == "config":
            vp._accion_configuracion("asesor")
        elif que == "voz":
            vp._accion_configuracion("voz")
        elif que == "guion_nuevo":
            vp._accion_ia("escribir_nuevo")
        elif que == "guion":
            doc = self._doc()
            ini = [i for i, b in enumerate(doc.bloques) if b.elem == Elem.ESCENA]
            fin = (ini[1] - 1) if len(ini) > 1 else len(doc.bloques) - 1
            try:
                vp.editor._mover_cursor_a(max(0, fin), len(doc.bloques[max(0, fin)].texto or ""))
                vp.editor.ensureCursorVisible()
            except Exception:
                pass
            vp.raise_()
            vp.activateWindow()
            vp.editor.setFocus()
            self.resaltar(vp.editor, "Aquí escribe la IA: debajo del cursor")
            self._sugerir(f"escribe una línea de acción donde {self._protagonista()} duda antes de entrar")
            self.raise_()
        elif que == "personaje":
            nombre = self._protagonista()
            self._sugerir(f"cambia la edad de {nombre} a 17")
            doc = self._doc()
            dlg = VentanaFichasPersonaje(doc.fichas, nombre_inicial=nombre, documento=doc, parent=vp)
            self._abrir_lugar(dlg, "edad", f"La IA puede cambiar: {_campos_cambio_ia('personaje')}.")
        elif que in ("locacion", "crew", "equipamiento"):
            doc = self._doc()
            tipo = {"crew": "tecnico"}.get(que, que)
            if que == "locacion":
                vp._auto_crear_locaciones_desde_escenas()
                nombre = next(iter(doc.locaciones or {}), "")
                self._sugerir(f"anota que el centro de salud de {nombre or 'la locación'} es el CESFAM Norte")
                campo = "hospital"
            elif que == "crew":
                nombre = next((t_.nombre for t_ in doc.tecnicos or [] if t_.nombre), "")
                self._sugerir("agrega al crew a Josefa Díaz como directora de fotografía, "
                              "teléfono +56 9 0000 0021")
                campo = "rol"
            else:
                nombre = next((e.nombre for e in doc.equipamiento or [] if e.nombre), "")
                self._sugerir("agrega al equipamiento un trípode, 15 mil por día")
                campo = "precio_dia"
            dlg, _tit = construir_vista_ficha(vp, doc, tipo, nombre, parent=vp)
            if dlg is None:
                return
            seleccionar_en_vista_ficha(dlg, nombre)
            aviso = (f"La IA puede cambiar: {_campos_cambio_ia({'tecnico': 'crew'}.get(tipo, tipo))}."
                     if nombre else "Aquí aparece lo que agregue la IA cuando confirmes.")
            self._abrir_lugar(dlg, campo if nombre else "", aviso)
        elif que == "escena":
            self._sugerir("en la ficha de la escena 1 pon que el tono es tenso")
            dlg = VentanaFichasEscenas(self._doc(), vp)
            for i in range(dlg._lista.count()):
                if dlg._lista.item(i).data(Qt.ItemDataRole.UserRole) == 1:
                    dlg._lista.setCurrentRow(i)
                    break
            self._abrir_lugar(dlg, w_campo=dlg._ed_tono,
                              aviso=f"La IA puede cambiar: {_campos_cambio_ia('escena')}.")
        elif que == "gantt":
            doc = self._doc()
            vp._auto_crear_locaciones_desde_escenas()
            meses = ["enero", "febrero", "marzo", "abril", "mayo", "junio", "julio", "agosto", "septiembre",
                     "octubre", "noviembre", "diciembre"]
            d = date.today() + timedelta(days=7)
            fecha_txt = f"{d.day} de {meses[d.month - 1]}"
            lugar = next(iter(doc.locaciones or {}), "")
            if doc.jornadas:
                self._sugerir(f"mueve la {doc.jornadas[0].nombre or 'jornada 1'} al {fecha_txt}")
            else:
                self._sugerir(f"crea una jornada el {fecha_txt}" + (f" en {lugar}" if lugar else "")
                              + " con la escena 1")
            dlg = VentanaCartaGantt(doc, vp)
            self._abrir_lugar(dlg, w_campo=dlg._lista_escenas,
                              aviso="La IA puede crear, mover y borrar jornadas, y cambiar: "
                                    f"{_campos_cambio_ia('jornada')}.")
        elif que == "presupuesto":
            self._sugerir("agrega un gasto de catering de 120 mil para las jornadas")
            dlg = VentanaPresupuesto(vp, parent=vp)
            self._abrir_lugar(dlg, w_campo=dlg._tabla,
                              aviso="La IA puede agregar gastos y marcar pagos, notas, categorías y «sin IVA» "
                                    "(también de lo automático), los fondos y el IVA.")
        elif que == "contratos":
            self._sugerir("agrega un seguro de responsabilidad civil por 350 mil que vence el 31 de diciembre")
            dlg = VentanaContratos(vp, parent=vp)
            self._abrir_lugar(dlg, w_campo=getattr(dlg, "_tabla", None),
                              aviso=f"La IA puede crear y cambiar documentos: {_campos_cambio_ia('documento')}.")
        elif que == "planos":
            self._sugerir("en la lista de planos, crea en la escena 1 un primer plano con cámara en mano")
            dlg = VentanaPlanos(vp, parent=vp)
            self._abrir_lugar(dlg, w_campo=getattr(dlg, "_tabla", None),
                              aviso=f"La IA puede crear planos y cambiar: {_campos_cambio_ia('plano')}.")
        elif que == "premisa":
            self._sugerir("cambia la premisa a: una alumna tímida debe llenar el gimnasio con la última "
                          "función del taller de cine, o lo cerrarán para siempre")
            dlg = VentanaEscaleta(self._doc(), parent=vp)
            dlg.enviar_solicitado.connect(vp._insertar_escaleta_en_guion)
            self._abrir_lugar(dlg, w_campo=dlg._ed_premisa,
                              aviso="La premisa: la misma de la Pizarra de beats. La IA también puede "
                                    "cambiar el título del proyecto.")


class LectorVozAlta(QDialog):
    """🔊 Lee el guion en voz alta: cada personaje con la voz de su
    ficha (Femenina / Masculina / una voz concreta / Automática, que
    alterna voces para distinguirlos) y las acciones con la del
    narrador. Va marcando en el editor el bloque que está leyendo."""

    def __init__(self, vp, parent=None):
        super().__init__(parent)
        self._vp = vp
        self.listo = False
        self._cola: list[tuple] = []
        self._pos = 0
        self._leyendo = False
        self.setWindowTitle("🔊  Leer en voz alta")
        self.setModal(False)
        self.setWindowFlags(Qt.WindowType.Window
                            | Qt.WindowType.WindowStaysOnTopHint
                            | Qt.WindowType.WindowCloseButtonHint)
        self._tts = _motor_voz()
        if self._tts is None or not self._voces():
            QMessageBox.information(
                parent, "Voz alta",
                "Este computador no tiene voces instaladas para leer en "
                "voz alta.<br><br>En Windows: <b>Configuración → Hora e "
                "idioma → Voz → Agregar voces</b> (elige una voz en "
                "español). Después vuelve a abrir ¡Acción!.")
            return
        self.listo = True
        from PySide6.QtTextToSpeech import QTextToSpeech
        self._Estado = QTextToSpeech.State
        self._tts.stateChanged.connect(self._al_cambiar_estado)

        v = QVBoxLayout(self)
        v.setContentsMargins(px(14), px(12), px(14), px(12))
        v.setSpacing(px(8))
        fila = QHBoxLayout()
        fila.addWidget(QLabel("Leer:"))
        self._cb_rango = QComboBox()
        self._cb_rango.addItems(["Desde la escena del cursor",
                                 "Solo la escena del cursor",
                                 "Todo el guion"])
        fila.addWidget(self._cb_rango, 1)
        v.addLayout(fila)
        self._chk_narrador = QCheckBox(
            "Leer también encabezados y acciones (narrador)")
        self._chk_narrador.setChecked(True)
        v.addWidget(self._chk_narrador)
        fila = QHBoxLayout()
        fila.addWidget(QLabel("Voz del narrador:"))
        self._cb_narrador = QComboBox()
        self._cb_narrador.addItems(["Automática"] + [x.name() for x in self._voces()])
        fila.addWidget(self._cb_narrador, 1)
        v.addLayout(fila)
        fila = QHBoxLayout()
        fila.addWidget(QLabel("Velocidad:"))
        from PySide6.QtWidgets import QSlider
        self._vel = QSlider(Qt.Orientation.Horizontal)
        self._vel.setRange(-5, 5)
        self._vel.setValue(0)
        self._vel.valueChanged.connect(
            lambda val: self._tts.setRate(val / 10.0))
        fila.addWidget(self._vel, 1)
        v.addLayout(fila)
        self._lbl_quien = QLabel("—")
        self._lbl_quien.setStyleSheet(
            "color: #ff8c1a; font-size: 13pt; font-weight: 800;")
        v.addWidget(self._lbl_quien)
        self._lbl_texto = QLabel("")
        self._lbl_texto.setWordWrap(True)
        self._lbl_texto.setMinimumHeight(px(60))
        self._lbl_texto.setStyleSheet(
            "background: #131d2b; border: 1px solid #26344a; "
            "border-radius: 6px; padding: 8px;")
        v.addWidget(self._lbl_texto)
        fila = QHBoxLayout()
        self._b_play = QPushButton("▶  Leer")
        self._b_play.clicked.connect(self._play_pausa)
        b_sig = QPushButton("⏭")
        b_sig.setToolTip("Saltar al siguiente")
        b_sig.clicked.connect(self._siguiente)
        b_stop = QPushButton("⏹  Detener")
        b_stop.clicked.connect(self.detener)
        for b in (self._b_play, b_sig, b_stop):
            fila.addWidget(b)
        v.addLayout(fila)
        self.resize(*tam_ventana(460, 380))

    # ── Voces ──
    def _voces(self) -> list:
        try:
            return list(self._tts.availableVoices())
        except Exception:
            return []

    def _voz_por_nombre(self, nombre: str):
        for vz in self._voces():
            if vz.name() == nombre:
                return vz
        return None

    def _voz_de_personaje(self, personaje: str):
        voces = self._voces()
        if not voces:
            return None
        ficha = self._vp.editor.documento.fichas.get(personaje)
        pref = (getattr(ficha, "voz_tts", "") or "").strip().lower() \
            if ficha else ""
        try:
            from PySide6.QtTextToSpeech import QVoice
            fem = [vz for vz in voces if vz.gender() == QVoice.Gender.Female]
            mas = [vz for vz in voces if vz.gender() == QVoice.Gender.Male]
        except Exception:
            fem, mas = [], []
        if pref in ("femenina", "female") and fem:
            return fem[0]
        if pref in ("masculina", "male") and mas:
            return mas[0]
        if pref and pref not in ("auto", "automática", "automatica",
                                 "femenina", "masculina"):
            vz = self._voz_por_nombre(ficha.voz_tts)
            if vz is not None:
                return vz
        # Automática: misma voz siempre para el mismo personaje
        k = sum(ord(c) for c in personaje)
        return voces[k % len(voces)]

    def _voz_narrador(self):
        nombre = self._cb_narrador.currentText()
        if nombre != "Automática":
            vz = self._voz_por_nombre(nombre)
            if vz is not None:
                return vz
        try:
            return self._tts.voice()
        except Exception:
            return None

    # ── Cola de lectura ──
    def _armar_cola(self) -> None:
        bl = self._vp.editor.documento.bloques
        try:
            idx, _ = self._vp.editor._posicion_logica()
        except Exception:
            idx = 0
        modo = self._cb_rango.currentIndex()
        ini, fin = 0, len(bl)
        if modo in (0, 1):
            # Escena que contiene el cursor (si está antes de la primera
            # escena: desde el principio, o la primera escena)
            s = min(idx, len(bl) - 1)
            while s >= 0 and bl[s].elem != Elem.ESCENA:
                s -= 1
            if s < 0:
                s = 0 if modo == 0 else next(
                    (k for k in range(len(bl)) if bl[k].elem == Elem.ESCENA), 0)
            ini = s
            if modo == 1:
                fin = ini + 1
                while fin < len(bl) and bl[fin].elem != Elem.ESCENA:
                    fin += 1
        narr = self._chk_narrador.isChecked()
        cola = []
        personaje = ""
        for i in range(ini, fin):
            b = bl[i]
            t = (b.texto or "").strip()
            if not t:
                continue
            if b.elem == Elem.PERSONAJE:
                personaje = _nombre_personaje(t)
            elif b.elem == Elem.DIALOGO:
                cola.append((i, personaje or "?", t,
                             self._voz_de_personaje(personaje)))
            elif narr and b.elem in (Elem.ESCENA, Elem.ACCION,
                                     Elem.ACTO_INICIO, Elem.ACTO_FIN):
                txt = t
                if b.elem == Elem.ESCENA:
                    txt = (t.replace("INT.", "Interior.")
                           .replace("EXT.", "Exterior.")
                           .replace("I/E.", "Interior, exterior.")
                           .replace(" - ", ". "))
                cola.append((i, "Narrador", txt.capitalize()
                             if b.elem != Elem.ACCION else txt,
                             self._voz_narrador()))
        self._cola = cola
        self._pos = 0

    def _decir_actual(self) -> None:
        if self._pos >= len(self._cola):
            self._leyendo = False
            self._b_play.setText("▶  Leer")
            self._lbl_quien.setText("✓ Fin")
            return
        idx, quien, texto, voz = self._cola[self._pos]
        self._lbl_quien.setText(quien)
        self._lbl_texto.setText(texto)
        try:
            self._vp.editor._mover_cursor_a(idx, 0)
            self._vp.editor.ensureCursorVisible()
        except Exception:
            pass
        if voz is not None:
            try:
                self._tts.setVoice(voz)
            except Exception:
                pass
        self._tts.say(texto)

    def _al_cambiar_estado(self, estado) -> None:
        if not self._leyendo:
            return
        if estado == self._Estado.Ready:
            self._pos += 1
            QTimer.singleShot(150, self._decir_actual)

    def _play_pausa(self) -> None:
        estado = self._tts.state()
        if estado == self._Estado.Speaking:
            self._tts.pause()
            self._b_play.setText("▶  Seguir")
            return
        if estado == self._Estado.Paused:
            self._tts.resume()
            self._b_play.setText("⏸  Pausa")
            return
        self._armar_cola()
        if not self._cola:
            self._lbl_quien.setText("No hay diálogos para leer aquí.")
            return
        self._leyendo = True
        self._b_play.setText("⏸  Pausa")
        self._decir_actual()

    def _siguiente(self) -> None:
        if not self._cola:
            return
        self._leyendo = False
        self._tts.stop()
        self._pos += 1
        self._leyendo = True
        self._decir_actual()

    def detener(self) -> None:
        self._leyendo = False
        try:
            self._tts.stop()
        except Exception:
            pass
        if hasattr(self, "_b_play"):
            self._b_play.setText("▶  Leer")

    def closeEvent(self, ev) -> None:
        self.detener()
        super().closeEvent(ev)


class VentanaPlanos(QDialog):
    """🎥 LISTA DE PLANOS (shot list) por escena.

    Cada plano: número, tamaño, ángulo, movimiento, lente, descripción,
    duración, notas y ✓ hecho. Se pueden crear automáticamente desde
    los bloques PLANO del guion. Conectada a la Carta Gantt: se puede
    filtrar por jornada de rodaje y exportar la lista de esa jornada
    (PDF horizontal, Excel de una página de ancho o CSV)."""

    COLS = ["✓", "N°", "Tamaño", "Ángulo", "Movimiento", "Lente",
            "Descripción", "Duración", "Notas"]
    CLAVES = ["hecho", "numero", "tamano", "angulo", "movimiento", "lente",
              "descripcion", "duracion", "notas"]

    def __init__(self, vp, parent=None):
        super().__init__(parent)
        self._vp = vp
        self.doc = vp.editor.documento
        registrar_doc_3d(self.doc)
        if not isinstance(getattr(self.doc, "planos", None), list):
            self.doc.planos = []
        self.setWindowTitle("🎥  Lista de planos")
        habilitar_snap(self, "🎥")
        # Las del guion y las propias del storyboard (sin guion también hay lista)
        self._escenas = escenas_storyboard(self.doc)
        self._nums = numeros_de_escena(
            self.doc.bloques, getattr(self.doc, "numeracion_bloqueada", False))
        self._etq = _etiquetas_escenas(self.doc)
        self._n_actual: Optional[int] = None
        self._llenando = False

        v = QVBoxLayout(self)
        v.setContentsMargins(px(12), px(10), px(12), px(10))
        v.setSpacing(px(8))
        fila = QHBoxLayout()
        fila.addWidget(QLabel("<b>Mostrar:</b>"))
        self._cb_jornada = QComboBox()
        self._cb_jornada.addItem("Todas las escenas", None)
        for k, j in enumerate(getattr(self.doc, "jornadas", []) or []):
            fecha = j.fecha or "sin fecha"
            self._cb_jornada.addItem(
                f"📅 {j.nombre or f'Jornada {k + 1}'} · {fecha} · escenas "
                f"{j.escenas or '—'}", k)
        self._cb_jornada.currentIndexChanged.connect(self._llenar_escenas)
        fila.addWidget(self._cb_jornada, 1)
        self._lbl_total = QLabel("")
        self._lbl_total.setStyleSheet("color: #8fa1b8;")
        fila.addWidget(self._lbl_total)
        v.addLayout(fila)

        split = QSplitter(Qt.Orientation.Horizontal)
        self._lista = QListWidget()
        self._lista.currentRowChanged.connect(self._al_elegir_escena)
        split.addWidget(self._lista)
        der = QWidget()
        vd = QVBoxLayout(der)
        vd.setContentsMargins(0, 0, 0, 0)
        self._lbl_escena = QLabel("")
        self._lbl_escena.setWordWrap(True)
        self._lbl_escena.setStyleSheet(
            "color: #ff8c1a; font-weight: 800; font-size: 11pt;")
        vd.addWidget(self._lbl_escena)
        from PySide6.QtWidgets import QTableWidget, QHeaderView
        self._tabla = QTableWidget(0, len(self.COLS))
        self._tabla.setHorizontalHeaderLabels(self.COLS)
        self._tabla.verticalHeader().setVisible(False)
        self._tabla.setWordWrap(True)
        hh = self._tabla.horizontalHeader()
        anchos = {"hecho": 30, "numero": 36, "tamano": 160, "angulo": 110,
                  "movimiento": 120, "lente": 66, "duracion": 82}
        for c, clave in enumerate(self.CLAVES):
            if clave in ("descripcion", "notas"):
                hh.setSectionResizeMode(c, QHeaderView.ResizeMode.Stretch)
            else:
                hh.setSectionResizeMode(c, QHeaderView.ResizeMode.Interactive)
                self._tabla.setColumnWidth(c, px(anchos.get(clave, 80)))
        hh.setMinimumSectionSize(px(28))
        self._tabla.itemChanged.connect(self._al_editar)
        vd.addWidget(self._tabla, 1)
        fb = QHBoxLayout()
        for txt, fn, tip in (
                ("＋ Plano", self._agregar, "Agregar un plano a esta escena"),
                ("－ Quitar", self._quitar, "Quitar el plano seleccionado"),
                ("↑", lambda: self._mover(-1), "Subir"),
                ("↓", lambda: self._mover(1), "Bajar"),
                ("✨ Desde el guion", self._desde_guion,
                 "Crea un plano por cada bloque PLANO de esta escena "
                 "(deduce tamaño, ángulo y movimiento)")):
            b = QPushButton(txt)
            b.setToolTip(tip)
            b.clicked.connect(fn)
            fb.addWidget(b)
        fb.addStretch()
        vd.addLayout(fb)
        split.addWidget(der)
        split.setStretchFactor(0, 1)
        split.setStretchFactor(1, 3)
        split.setSizes([px(280), px(900)])
        v.addWidget(split, 1)

        fila2 = QHBoxLayout()
        b_esc = QPushButton("＋ Escena")
        b_esc.setToolTip("Una escena propia del storyboard y de esta lista (no hace falta "
                         "que esté en el guion)")
        b_esc.clicked.connect(self._nueva_escena)
        fila2.addWidget(b_esc)
        b_sb = QPushButton("🎞 Storyboard")
        b_sb.setToolTip("Dibujar estos planos (los mismos datos, vistos como "
                        "cuadros de storyboard)")
        b_sb.clicked.connect(self._abrir_storyboard)
        fila2.addWidget(b_sb)
        b_todo = QPushButton("✨ Crear desde todo el guion")
        b_todo.setToolTip("Lo mismo que «Desde el guion», en todas las "
                          "escenas a la vez")
        b_todo.clicked.connect(self._desde_guion_todo)
        fila2.addWidget(b_todo)
        b_tut = QPushButton("🎓 Tutorial")
        b_tut.setToolTip("El tutorial de la lista de planos, paso a paso, al lado de la ventana: qué es, "
                         "tamaños, ángulos, movimientos y lentes, crearlos desde el guion, por jornada, el "
                         "storyboard y exportar")
        b_tut.clicked.connect(lambda: self._tutorial_planos())
        fila2.addWidget(b_tut)
        self._b_tutorial = b_tut
        fila2.addStretch()
        for txt, fmt in (("📄 PDF", "pdf"), ("📊 Excel", "xlsx"),
                         ("🧾 CSV", "csv")):
            b = QPushButton(txt)
            b.setToolTip("Exportar la lista de lo que se muestra "
                         "(todas las escenas o la jornada elegida)")
            b.clicked.connect(lambda _=None, f=fmt: self._exportar(f))
            fila2.addWidget(b)
        b_c = QPushButton("Cerrar")
        b_c.clicked.connect(self.accept)
        fila2.addWidget(b_c)
        v.addLayout(fila2)
        self.resize(*tam_ventana(1200, 720))
        self._llenar_escenas()

    # ── 🎓 El tutorial de la lista de planos (al lado de la ventana) ──
    def _tutorial_planos(self, practica: Optional[bool] = None) -> "TutorialFlotante":
        if practica is None:
            practica = bool(getattr(self.doc, "_tutorial_practica", False))
        tut = getattr(self, "_tut_planos", None)
        if tut is not None:
            try:
                tut.close()
            except RuntimeError:
                pass
        self._tut_planos = TutorialFlotante("🎓 Lista de planos", pasos_tutorial_planos(self, practica), self)
        self._tut_planos.show()
        return self._tut_planos

    def _tut_elegir_escena_con_planos(self) -> None:
        """Elige la primera escena que tiene planos (o la primera)."""
        for k, e in enumerate(getattr(self, "_vis", []) or []):
            if self._planos_de(e["n"]):
                self._lista.setCurrentRow(k)
                return
        if self._lista.count():
            self._lista.setCurrentRow(0)

    def _tut_jornada(self) -> None:
        if self._cb_jornada.count() > 1:
            self._cb_jornada.setCurrentIndex(1)
        else:
            QMessageBox.information(self, "Planos", "Todavía no hay jornadas de rodaje: se crean en la "
                                    "Carta Gantt (Producción). Entonces aquí aparece cada una.")

    def _abrir_storyboard(self) -> None:
        VentanaStoryboard(self._vp, parent=self,
                          escena_inicial=self._n_actual or 0).exec()
        fila = self._lista.currentRow()
        self._escenas = escenas_storyboard(self.doc)       # (pudo crear escenas propias)
        self._etq = _etiquetas_escenas(self.doc)
        self._llenar_escenas()
        if 0 <= fila < self._lista.count():
            self._lista.setCurrentRow(fila)

    # ── Datos ──
    def _num_de(self, e: dict) -> str:
        return self._etq.get(e["n"], (str(e["n"]), ""))[0]

    def _recargar_escenas(self, elegir: Optional[int] = None) -> None:
        self._escenas = escenas_storyboard(self.doc)
        self._etq = _etiquetas_escenas(self.doc)
        self._llenar_escenas()
        if elegir is not None:
            fila = next((k for k, e in enumerate(self._vis) if e["n"] == elegir), -1)
            if fila >= 0:
                self._lista.setCurrentRow(fila)

    def _nueva_escena(self) -> None:
        """＋ Escena: una escena propia del storyboard (no hace falta guion)."""
        n_sig = len(escenas_libres_sb(self.doc)) + 1
        nombre, ok = QInputDialog.getText(
            self, "Nueva escena", "¿Dónde pasa? (por ejemplo: PARQUE - DÍA). No hace falta que "
            "esté en el guion.", QLineEdit.EchoMode.Normal, f"ESCENA {n_sig}")
        if not ok:
            return
        e = nueva_escena_libre_sb(self.doc, nombre)
        self._marcar()
        if self._cb_jornada.currentData() is not None:
            self._cb_jornada.setCurrentIndex(0)
        self._recargar_escenas(elegir=e["n"])

    def _planos_de(self, n: int) -> list[dict]:
        return [p for p in self.doc.planos if int(p.get("escena", 0) or 0) == n]

    def _escenas_visibles(self) -> list[dict]:
        k = self._cb_jornada.currentData()
        if k is None:
            return list(self._escenas)
        j = self.doc.jornadas[k]
        nums = {x.strip() for x in (j.escenas or "").split(",") if x.strip()}
        return [e for e in self._escenas if str(e["n"]) in nums]

    def _texto_jornadas(self, n: int) -> str:
        js = jornadas_de_escena(self.doc, n)
        return ", ".join(f"{j.nombre or 'jornada'} ({j.fecha or 'sin fecha'})"
                         for j in js)

    def _marcar(self) -> None:
        if hasattr(self._vp, "_marcar_dirty"):
            self._vp._marcar_dirty()

    # ── Lista de escenas ──
    def _llenar_escenas(self, *_):
        self._lista.blockSignals(True)
        self._lista.clear()
        self._vis = self._escenas_visibles()
        for e in self._vis:
            n_pl = len(self._planos_de(e["n"]))
            hechos = sum(1 for p in self._planos_de(e["n"]) if p.get("hecho"))
            num = self._num_de(e)
            marca = f"  ·  {hechos}/{n_pl} ✓" if n_pl else ""
            self._lista.addItem(f"{num}. {e['encabezado']}{marca}")
            self._lista.item(self._lista.count() - 1).setToolTip(
                f"{num}. {e['encabezado']}")
        self._lista.blockSignals(False)
        total = sum(len(self._planos_de(e["n"])) for e in self._vis)
        self._lbl_total.setText(f"{total} planos")
        if self._vis:
            self._lista.setCurrentRow(0)
        else:
            self._n_actual = None
            self._tabla.setRowCount(0)
            self._lbl_escena.setText(
                "No hay escenas en esta selección." if self._escenas else
                "Todavía no hay escenas: «＋ Escena» crea una (no hace falta guion).")

    def _al_elegir_escena(self, fila: int) -> None:
        if not (0 <= fila < len(getattr(self, "_vis", []))):
            return
        e = self._vis[fila]
        self._n_actual = e["n"]
        num = self._num_de(e)
        jt = self._texto_jornadas(e["n"])
        self._lbl_escena.setText(
            f"{num}. {e['encabezado']}"
            + (f"   <span style='color:#8fa1b8;font-weight:400;'>📅 {html.escape(jt)}"
               "</span>" if jt else ""))
        self._llenar_tabla()

    # ── Tabla ──
    def _llenar_tabla(self) -> None:
        from PySide6.QtWidgets import QTableWidgetItem
        self._llenando = True
        planos = self._planos_de(self._n_actual or 0)
        self._tabla.setRowCount(len(planos))
        for r, pl in enumerate(planos):
            for c, clave in enumerate(self.CLAVES):
                if clave == "hecho":
                    it = QTableWidgetItem()
                    it.setFlags(Qt.ItemFlag.ItemIsUserCheckable
                                | Qt.ItemFlag.ItemIsEnabled
                                | Qt.ItemFlag.ItemIsSelectable)
                    it.setCheckState(Qt.CheckState.Checked if pl.get("hecho")
                                     else Qt.CheckState.Unchecked)
                    self._tabla.setItem(r, c, it)
                elif clave in ("tamano", "angulo", "movimiento"):
                    opciones = {"tamano": TAMANOS_PLANO, "angulo": ANGULOS_PLANO,
                                "movimiento": MOVIMIENTOS_PLANO}[clave]
                    cb = QComboBox()
                    cb.setEditable(True)
                    cb.addItems(opciones)
                    cb.setStyleSheet(
                        "QComboBox { padding: 2px 6px; min-height: 0px; "
                        "border-radius: 4px; margin: 1px; }")
                    cb.setCurrentText(str(pl.get(clave, "") or ""))
                    if cb.lineEdit() is not None:
                        cb.lineEdit().setCursorPosition(0)
                    cb.setToolTip(cb.currentText())
                    cb.currentTextChanged.connect(
                        lambda t, d=pl, k=clave: self._set(d, k, t))
                    self._tabla.setCellWidget(r, c, cb)
                else:
                    self._tabla.setItem(r, c, QTableWidgetItem(
                        str(pl.get(clave, "") or "")))
        self._tabla.resizeRowsToContents()
        self._llenando = False

    def _set(self, d: dict, k: str, valor) -> None:
        if self._llenando:
            return
        d[k] = valor
        self._marcar()

    def _al_editar(self, it) -> None:
        if self._llenando:
            return
        planos = self._planos_de(self._n_actual or 0)
        r, c = it.row(), it.column()
        if not (0 <= r < len(planos)):
            return
        clave = self.CLAVES[c]
        if clave == "hecho":
            planos[r]["hecho"] = it.checkState() == Qt.CheckState.Checked
            fila = self._lista.currentRow()
            self._refrescar_item_lista(fila)
        else:
            planos[r][clave] = it.text()
        self._marcar()

    def _refrescar_item_lista(self, fila: int) -> None:
        if 0 <= fila < len(self._vis):
            e = self._vis[fila]
            pls = self._planos_de(e["n"])
            num = self._num_de(e)
            marca = (f"  ·  {sum(1 for p in pls if p.get('hecho'))}/"
                     f"{len(pls)} ✓") if pls else ""
            self._lista.item(fila).setText(f"{num}. {e['encabezado']}{marca}")
        self._lbl_total.setText(
            f"{sum(len(self._planos_de(x['n'])) for x in self._vis)} planos")

    def _nuevo_numero(self) -> str:
        nums = [numero_base_plano(p.get("numero")) for p in self._planos_de(self._n_actual or 0)]
        return str(max(nums, default=0) + 1)

    def _agregar(self, plano: Optional[dict] = None) -> None:
        if self._n_actual is None:
            return
        pl = {k: "" for k in CAMPOS_PLANO}
        pl["hecho"] = False
        if isinstance(plano, dict):
            pl.update(plano)
        pl["escena"] = self._n_actual
        pl["numero"] = pl.get("numero") or self._nuevo_numero()
        # Insertar después del último plano de esta escena (orden global)
        pos = max((k for k, p in enumerate(self.doc.planos)
                   if int(p.get("escena", 0) or 0) == self._n_actual),
                  default=len(self.doc.planos) - 1) + 1
        self.doc.planos.insert(pos, pl)
        self._marcar()
        self._llenar_tabla()
        self._refrescar_item_lista(self._lista.currentRow())

    def _quitar(self) -> None:
        r = self._tabla.currentRow()
        planos = self._planos_de(self._n_actual or 0)
        if 0 <= r < len(planos):
            self.doc.planos.remove(planos[r])
            self._marcar()
            self._llenar_tabla()
            self._refrescar_item_lista(self._lista.currentRow())

    def _mover(self, d: int) -> None:
        r = self._tabla.currentRow()
        planos = self._planos_de(self._n_actual or 0)
        if not (0 <= r < len(planos) and 0 <= r + d < len(planos)):
            return
        a, b = self.doc.planos.index(planos[r]), self.doc.planos.index(planos[r + d])
        self.doc.planos[a], self.doc.planos[b] = self.doc.planos[b], self.doc.planos[a]
        self._marcar()
        self._llenar_tabla()
        self._tabla.selectRow(r + d)

    def _planos_desde_bloques(self, e: dict) -> list[dict]:
        existentes = {(p.get("descripcion") or "").strip().upper()
                      for p in self._planos_de(e["n"])}
        nuevos = []
        for i in range(e["desde"], e["hasta"]):
            b = self.doc.bloques[i]
            if b.elem == Elem.PLANO and (b.texto or "").strip():
                if (b.texto or "").strip().upper() not in existentes:
                    nuevos.append(plano_desde_texto(b.texto))
        return nuevos

    def _desde_guion(self) -> None:
        if self._n_actual is None:
            return
        e = next(x for x in self._escenas if x["n"] == self._n_actual)
        if e.get("libre"):
            QMessageBox.information(
                self, "Planos", "Esta escena es del storyboard (no está en el guion): agrega "
                "sus planos con «＋ Plano» o dibújalos en «🎞 Storyboard».")
            return
        nuevos = self._planos_desde_bloques(e)
        if not nuevos:
            QMessageBox.information(
                self, "Planos", "Esta escena no tiene bloques PLANO nuevos "
                "(Ctrl+7 en el editor crea un bloque Plano).")
            return
        for pl in nuevos:
            self._agregar(pl)

    def _desde_guion_todo(self) -> None:
        total = 0
        actual = self._n_actual
        for e in self._escenas:
            nuevos = self._planos_desde_bloques(e)
            self._n_actual = e["n"]
            for pl in nuevos:
                pl["escena"] = e["n"]
                pl["numero"] = self._nuevo_numero()
                pos = max((k for k, p in enumerate(self.doc.planos)
                           if int(p.get("escena", 0) or 0) == e["n"]),
                          default=len(self.doc.planos) - 1) + 1
                self.doc.planos.insert(pos, pl)
                total += 1
        self._n_actual = actual
        if total:
            self._marcar()
        fila = self._lista.currentRow()
        self._llenar_escenas()
        if 0 <= fila < self._lista.count():
            self._lista.setCurrentRow(fila)
        QMessageBox.information(
            self, "Planos",
            f"✨ {total} plano(s) creados desde los bloques PLANO del guion."
            if total else "No se encontraron bloques PLANO nuevos en el guion.")

    # ── Exportar ──
    def filas_exportar(self) -> list[list]:
        filas = [["Escena", "N°", "Tamaño", "Ángulo", "Movimiento", "Lente",
                  "Descripción", "Duración", "Notas", "Hecho", "Jornada"]]
        for e in self._escenas_visibles():
            num = self._num_de(e)
            jt = self._texto_jornadas(e["n"])
            for pl in self._planos_de(e["n"]):
                filas.append([f"{num}. {e['encabezado']}", pl.get("numero", ""),
                              pl.get("tamano", ""), pl.get("angulo", ""),
                              pl.get("movimiento", ""), pl.get("lente", ""),
                              pl.get("descripcion", ""), pl.get("duracion", ""),
                              pl.get("notas", ""), "✓" if pl.get("hecho") else "",
                              jt])
        return filas

    def _exportar(self, fmt: str) -> None:
        filas = self.filas_exportar()
        if len(filas) <= 1:
            QMessageBox.information(self, "Planos",
                                    "No hay planos para exportar en esta selección.")
            return
        base = (getattr(self.doc, "titulo", "") or "guion").strip() or "guion"
        ext = {"pdf": "pdf", "xlsx": "xlsx", "csv": "csv"}[fmt]
        sugerido = str(Path(ruta_ultima_carpeta()) / f"{base} - lista de planos.{ext}")
        if fmt == "pdf":
            ruta, self._poca_tinta = pedir_ruta_pdf(self, "Exportar lista de planos", sugerido)
        else:
            ruta, _ = QFileDialog.getSaveFileName(self, "Exportar lista de planos", sugerido, f"*.{ext}")
        if not ruta:
            return
        if not ruta.lower().endswith("." + ext):
            ruta += "." + ext
        try:
            self.exportar_a(Path(ruta), fmt, filas)
            QMessageBox.information(self, "Planos",
                                    f"✅ Lista de planos guardada: {Path(ruta).name}")
        except Exception as e:
            QMessageBox.critical(self, "Planos", f"No se pudo exportar:\n{e}")

    def exportar_a(self, ruta: Path, fmt: str, filas: Optional[list] = None) -> None:
        filas = filas or self.filas_exportar()
        titulo = (getattr(self.doc, "titulo", "") or "Guion").strip() or "Guion"
        jornada = self._cb_jornada.currentText() \
            if self._cb_jornada.currentData() is not None else ""
        if fmt == "csv":
            import csv as _csv
            with open(ruta, "w", newline="", encoding="utf-8-sig") as f:
                _csv.writer(f, delimiter=";").writerows(filas)
            return
        if fmt == "xlsx":
            escribir_xlsx_simple(ruta, [("Lista de planos", filas,
                                         [30, 5, 18, 14, 14, 8, 40, 9, 28, 7, 22])])
            return
        # PDF horizontal con el diseño de los informes: una franja por
        # escena (con su jornada) y la tabla de sus planos
        informes_a_pdf([info_lista_planos(filas, jornada)], ruta, bool(getattr(self, "_poca_tinta", False)),
                       self._vp._proyecto_informe() if hasattr(self._vp, "_proyecto_informe") else titulo,
                       horizontal=True)


