def nuevo_id_corto() -> str:
    import uuid
    return uuid.uuid4().hex[:10]


def fecha_desde_texto(txt: str) -> str:
    """'15/03/2026', '15-3-26' o '2026-03-15' → '2026-03-15'.
    Devuelve '' si el texto no es una fecha válida."""
    t = (txt or "").strip()
    if not t:
        return ""
    try:
        m = re.fullmatch(r"(\d{4})-(\d{1,2})-(\d{1,2})", t)
        if m:
            return date(int(m[1]), int(m[2]), int(m[3])).isoformat()
        m = re.fullmatch(r"(\d{1,2})[/.\-](\d{1,2})[/.\-](\d{2,4})", t)
        if m:
            a = int(m[3])
            if a < 100:
                a += 2000
            return date(a, int(m[2]), int(m[1])).isoformat()
    except ValueError:
        return ""
    return ""


def fecha_visible(iso: str) -> str:
    """'2026-03-15' → '15/03/2026' (deja el texto tal cual si no es ISO)."""
    try:
        return date.fromisoformat(str(iso)).strftime("%d/%m/%Y")
    except (TypeError, ValueError):
        return str(iso or "")


def _texto_seguro(v) -> tuple[str, bool]:
    """(texto, protegido): un campo cifrado con PIN no se muestra."""
    if esta_cifrado(v):
        return "", True
    return str(v or ""), False


def _a_float(v, defecto: float = 0.0) -> float:
    try:
        return float(str(v).strip().replace(",", "."))
    except (TypeError, ValueError):
        return defecto


def _fmt_cantidad(c: float) -> str:
    if abs(c - round(c)) < 1e-9:
        return str(int(round(c)))
    return f"{c:g}".replace(".", ",")


def _color_tema(hex_nova: str) -> str:
    """Color semántico (escrito en paleta Nova) en el tema activo."""
    try:
        return traducir_qss(hex_nova, TEMA_ACTUAL)
    except Exception:
        return hex_nova


def _iter_recursos(doc):
    """(kind, nombre, objeto) de todas las fichas de producción."""
    for nom, f in (getattr(doc, "fichas", {}) or {}).items():
        yield "actor", nom, f
    for nom, l in (getattr(doc, "locaciones", {}) or {}).items():
        yield "locacion", nom, l
    for t in getattr(doc, "tecnicos", []) or []:
        nom = (getattr(t, "nombre", "") or "").strip()
        if nom:
            yield "tecnico", nom, t
    for e in getattr(doc, "equipamiento", []) or []:
        nom = (getattr(e, "nombre", "") or "").strip()
        if nom:
            yield "equipamiento", nom, e


def recurso_por_vinculo(doc, vinculo: str):
    """'actor:ANA' → la ficha de ANA (o None)."""
    kind, _, nombre = (vinculo or "").partition(":")
    for k, n, o in _iter_recursos(doc):
        if k == kind and n == nombre:
            return o
    return None


def costo_dia_detallado(obj, kind: str) -> tuple[float, str, bool]:
    """(costo por día, desglose 'valor + transp. + alim.', protegido).
    Igual que costo_dia_recurso() pero sin leer valores cifrados."""
    campo = "actor_valor_dia" if kind == "actor" else "precio_dia"
    partes, total, prot = [], 0.0, False
    for c, etq in ((campo, "valor"), ("transporte_dia", "transp."),
                   ("alimentacion_dia", "alim.")):
        txt, p = _texto_seguro(getattr(obj, c, ""))
        prot = prot or p
        v = parse_precio(txt)
        if v:
            partes.append((etq, v))
            total += v
    det = (" + ".join(f"{e} {fmt_moneda(v)}" for e, v in partes)
           if len(partes) > 1 else "")
    return total, det, prot


def nombre_visible_recurso(kind: str, nombre: str, obj) -> str:
    if kind == "actor":
        actor, _ = _texto_seguro(getattr(obj, "actor_nombre", ""))
        return f"{nombre} ({actor.strip()})" if actor.strip() else nombre
    if kind == "tecnico":
        rol = (getattr(obj, "rol", "") or "").strip()
        if rol and rol.lower() not in nombre.lower():
            return f"{nombre} — {rol}"
        return nombre
    if kind == "equipamiento":
        mod = (getattr(obj, "modelo", "") or "").strip()
        return f"{nombre} {mod}" if mod else nombre
    return nombre


# ── 💲 IVA: los valores con el IVA incluido o netos, como prefieras ──

MODOS_IVA: list[tuple[str, str, str]] = [
    ("", "Sin IVA",
     "Los montos se suman tal como los escribes (como hasta ahora)."),
    ("incluido", "Con el IVA incluido",
     "Escribes lo que pagas: el precio final de la boleta o la factura. "
     "El presupuesto separa cuánto es neto y cuánto es IVA."),
    ("aparte", "Netos, con el IVA aparte",
     "Escribes el valor neto (como en una cotización «+ IVA»). El "
     "presupuesto suma el IVA encima."),
]

# Tasa general de IVA (o su equivalente) sugerida según el país de
# Configuración. Es solo una sugerencia: se cambia en «💲 IVA». Donde no
# hay una tasa nacional única (EE. UU., Brasil, Canadá…), queda vacía.
TASA_IVA_PAIS: dict[str, float] = {
    "CL": 19, "AR": 21, "BO": 13, "CO": 19, "CR": 13, "DO": 18, "EC": 15,
    "SV": 13, "ES": 21, "GT": 12, "HN": 15, "MX": 16, "NI": 15, "PA": 7,
    "PY": 10, "PE": 18, "UY": 22, "VE": 16, "GB": 20, "FR": 20, "DE": 19,
    "IT": 22, "PT": 23, "AU": 10, "JP": 10,
}


def tasa_iva_sugerida(pais: str = "") -> float:
    """La tasa (en %) que se propone para el país (0 si no hay una)."""
    try:
        pais = pais or pais_por_defecto()
    except Exception:
        pais = ""
    return float(TASA_IVA_PAIS.get(pais, 0))


def config_iva(doc) -> tuple[str, float]:
    """(modo, tasa en fracción) del IVA del proyecto. Sin modo, o con
    tasa 0, es («», 0.0): los montos se suman tal cual."""
    modo = str(getattr(doc, "iva_modo", "") or "")
    if modo not in ("incluido", "aparte"):
        return "", 0.0
    txt = str(getattr(doc, "iva_tasa", "") or "").replace(",", ".").replace("%", "").strip()
    try:
        tasa = float(txt) if txt else tasa_iva_sugerida()
    except ValueError:
        tasa = tasa_iva_sugerida()
    if tasa <= 0:
        return "", 0.0
    return modo, tasa / 100.0


def separar_iva(monto: float, modo: str, tasa: float,
                exento: bool = False) -> tuple[float, float, float]:
    """(neto, iva, total a pagar) de un monto escrito según el modo:
    «incluido» → el monto ya trae el IVA; «aparte» → es neto y el IVA
    va encima. Exento o sin modo: todo es neto, sin IVA."""
    monto = float(monto or 0)
    if not modo or tasa <= 0 or exento or monto <= 0:
        return monto, 0.0, monto
    if modo == "incluido":
        neto = monto / (1 + tasa)
        return neto, monto - neto, monto
    iva = monto * tasa
    return monto, iva, monto + iva


def linea_exenta_iva(doc, clave: str, categoria: str,
                     gasto_sin_iva: bool = False) -> bool:
    """¿Esta línea va sin IVA? Por ella misma («actor:ANA»), por su
    categoría entera («cat:Elenco», salvo la excepción «+actor:ANA») o,
    en un gasto a mano, por su casilla «Sin IVA»."""
    ex = set(getattr(doc, "iva_exentos", []) or [])
    if f"+{clave}" in ex:
        return False
    return gasto_sin_iva or clave in ex or f"cat:{categoria}" in ex


def poner_exento_iva(doc, clave: str, categoria: str, exento: bool) -> None:
    """Deja una línea con o sin IVA (respetando su categoría)."""
    ex = [x for x in (getattr(doc, "iva_exentos", []) or [])
          if x not in (clave, f"+{clave}")]
    por_cat = f"cat:{categoria}" in ex
    if exento and not por_cat:
        ex.append(clave)
    elif not exento and por_cat:
        ex.append(f"+{clave}")
    doc.iva_exentos = ex


# ── 🗂 Categorías propias y grupos del presupuesto ──
#   · doc.categorias_propias → [{"nombre": "Difusión", "icono": "📣"}]
#   · doc.grupos_categorias  → [{"nombre": "Preproducción", "categorias": [...]}],
#                              en orden; una categoría va a lo más en un grupo
#   · doc.categoria_lineas   → {"actor:ANA": "Elenco principal"}: una línea
#                              automática movida a otra categoría (un gasto a
#                              mano guarda la suya en g["categoria"])

ICONO_CATEGORIA_PROPIA = "🏷"
SIN_GRUPO = "Sin grupo"
ICONOS_PARA_CATEGORIAS = ["🏷", "📣", "🎬", "🎤", "💡", "🎨", "🏠", "🧾", "💻", "📦", "🧰", "🍿",
                          "🎟", "🎓", "🚗", "✈", "🏨", "📷", "🎙", "🎼", "🧪", "🐾", "🌱", "⭐"]
GRUPOS_DE_EJEMPLO: dict = {
    "etapas": ("🎬 Por etapa: preproducción, rodaje y postproducción", [
        ("Preproducción", ["Permisos", "Seguros"]),
        ("Rodaje", ["Elenco", "Crew", "Locaciones", "Equipamiento", "Arte y vestuario",
                    "Efectos especiales", "Catering", "Transporte"]),
        ("Postproducción", ["Postproducción", "Música y derechos"]),
        ("Imprevistos y otros", ["Imprevistos", "Otros"])]),
    "linea": ("📏 Sobre la línea y bajo la línea", [
        ("Sobre la línea", ["Elenco", "Música y derechos"]),
        ("Bajo la línea", ["Crew", "Locaciones", "Equipamiento", "Arte y vestuario",
                           "Efectos especiales", "Catering", "Transporte", "Permisos",
                           "Seguros", "Postproducción"]),
        ("Imprevistos y otros", ["Imprevistos", "Otros"])]),
}


def _nombre_cat(x) -> str:
    return re.sub(r"\s+", " ", str(x or "")).strip()


def es_categoria_propia(cat: str) -> bool:
    """¿No es una de las categorías de siempre?"""
    return _nombre_cat(cat).casefold() not in {c.casefold() for c, _ in CATEGORIAS_GASTO}


def categorias_de_presupuesto(doc=None) -> list[tuple[str, str]]:
    """Todas las categorías (nombre, ícono): las de siempre, las propias
    del proyecto y las que ya se usan (un gasto con una categoría escrita
    a mano)."""
    out = list(CATEGORIAS_GASTO)
    vistos = {c.casefold() for c, _ in out}

    def sumar(n, ico) -> None:
        n = _nombre_cat(n)
        if n and n.casefold() not in vistos:
            vistos.add(n.casefold())
            out.append((n, ico))
    for c in getattr(doc, "categorias_propias", None) or []:
        if isinstance(c, dict):
            sumar(c.get("nombre"), str(c.get("icono") or "").strip() or ICONO_CATEGORIA_PROPIA)
    for g in getattr(doc, "gastos", None) or []:
        if isinstance(g, dict):
            sumar(g.get("categoria"), "📦")
    for c in (getattr(doc, "categoria_lineas", None) or {}).values():
        sumar(c, ICONO_CATEGORIA_PROPIA)
    return out


def nombre_categoria(doc, txt: str) -> str:
    """El nombre como está registrado (sin importar mayúsculas), o el
    texto limpio si es nueva."""
    t = _nombre_cat(txt)
    return next((c for c, _ in categorias_de_presupuesto(doc) if c.casefold() == t.casefold()), t)


def icono_categoria(doc, cat: str) -> str:
    cf = _nombre_cat(cat).casefold()
    return next((ico for c, ico in categorias_de_presupuesto(doc) if c.casefold() == cf), "📦")


def grupos_de_presupuesto(doc) -> list[dict]:
    """Los grupos de categorías, en orden y limpios (sin repetir)."""
    out, ya_cat, ya_g = [], set(), set()
    for g in getattr(doc, "grupos_categorias", None) or []:
        if not isinstance(g, dict):
            continue
        n = _nombre_cat(g.get("nombre"))
        if not n or n.casefold() in ya_g or n.casefold() == SIN_GRUPO.casefold():
            continue
        ya_g.add(n.casefold())
        cats = []
        for c in g.get("categorias") or []:
            c = _nombre_cat(c)
            if c and c.casefold() not in ya_cat:
                ya_cat.add(c.casefold())
                cats.append(c)
        out.append({"nombre": n, "categorias": cats})
    return out


def grupo_de_categoria(doc, cat: str) -> str:
    """El grupo de la categoría («» si no tiene)."""
    cf = _nombre_cat(cat).casefold()
    for g in grupos_de_presupuesto(doc):
        if any(c.casefold() == cf for c in g["categorias"]):
            return g["nombre"]
    return ""


def orden_categorias(doc) -> list[str]:
    """Las categorías en el orden del presupuesto: primero las de cada
    grupo (en el orden de los grupos y dentro de cada uno), después las
    que no tienen grupo."""
    todas = [c for c, _ in categorias_de_presupuesto(doc)]
    por_cf = {c.casefold(): c for c in todas}
    out, ya = [], set()
    for g in grupos_de_presupuesto(doc):
        for c in g["categorias"]:
            if c.casefold() not in ya:
                ya.add(c.casefold())
                out.append(por_cf.get(c.casefold(), c))
    return out + [c for c in todas if c.casefold() not in ya]


def _registro_categoria(doc, nombre: str) -> Optional[dict]:
    cf = _nombre_cat(nombre).casefold()
    return next((c for c in (getattr(doc, "categorias_propias", None) or [])
                 if isinstance(c, dict) and _nombre_cat(c.get("nombre")).casefold() == cf), None)


def crear_categoria_propia(doc, nombre: str, icono: str = "", grupo: str = "") -> str:
    """Agrega una categoría propia (si ya existe, la devuelve; con `icono`
    se lo cambia). Con `grupo`, la deja en ese grupo (lo crea si hace
    falta). Devuelve el nombre."""
    n = nombre_categoria(doc, nombre)
    if not n:
        return ""
    if not isinstance(getattr(doc, "categorias_propias", None), list):
        doc.categorias_propias = []
    icono = str(icono or "").strip()
    if es_categoria_propia(n):
        reg = _registro_categoria(doc, n)
        if reg is None:
            doc.categorias_propias.append({"nombre": n, "icono": icono or ICONO_CATEGORIA_PROPIA})
        elif icono:
            reg["icono"] = icono
    if grupo:
        poner_grupo_de_categoria(doc, n, grupo)
    return n


def poner_grupo_de_categoria(doc, cat: str, grupo: str, posicion: Optional[int] = None) -> None:
    """Pasa la categoría al grupo (lo crea si no existe); «» o «Sin grupo»
    la deja sin grupo."""
    cat, grupo = _nombre_cat(cat), _nombre_cat(grupo)
    gs = grupos_de_presupuesto(doc)
    for g in gs:
        g["categorias"] = [c for c in g["categorias"] if c.casefold() != cat.casefold()]
    if grupo and grupo.casefold() != SIN_GRUPO.casefold():
        g = next((g for g in gs if g["nombre"].casefold() == grupo.casefold()), None)
        if g is None:
            g = {"nombre": grupo, "categorias": []}
            gs.append(g)
        if posicion is None:
            g["categorias"].append(cat)
        else:
            g["categorias"].insert(max(0, posicion), cat)
    doc.grupos_categorias = gs


def crear_grupo_categorias(doc, nombre: str) -> str:
    n = _nombre_cat(nombre)
    if not n or n.casefold() == SIN_GRUPO.casefold():
        return ""
    gs = grupos_de_presupuesto(doc)
    g = next((g for g in gs if g["nombre"].casefold() == n.casefold()), None)
    if g is None:
        gs.append({"nombre": n, "categorias": []})
        doc.grupos_categorias = gs
        return n
    return g["nombre"]


def renombrar_grupo_categorias(doc, viejo: str, nuevo: str) -> str:
    nuevo = _nombre_cat(nuevo)
    gs = grupos_de_presupuesto(doc)
    g = next((g for g in gs if g["nombre"].casefold() == _nombre_cat(viejo).casefold()), None)
    if g is None or not nuevo or nuevo.casefold() == SIN_GRUPO.casefold():
        return ""
    otro = next((x for x in gs if x is not g and x["nombre"].casefold() == nuevo.casefold()), None)
    if otro is not None:                       # (mismo nombre que otro: se juntan)
        otro["categorias"] += [c for c in g["categorias"] if c not in otro["categorias"]]
        gs.remove(g)
        nuevo = otro["nombre"]
    else:
        g["nombre"] = nuevo
    doc.grupos_categorias = gs
    return nuevo


def eliminar_grupo_categorias(doc, nombre: str) -> None:
    """Quita el grupo: sus categorías quedan sin grupo (no se borra nada)."""
    doc.grupos_categorias = [g for g in grupos_de_presupuesto(doc)
                             if g["nombre"].casefold() != _nombre_cat(nombre).casefold()]


def mover_en_orden_categorias(doc, nombre: str, delta: int, es_grupo: bool = False) -> bool:
    """Sube (delta −1) o baja (+1) un grupo, o una categoría dentro de su grupo."""
    gs = grupos_de_presupuesto(doc)
    cf = _nombre_cat(nombre).casefold()
    if es_grupo:
        lista = gs
        i = next((k for k, g in enumerate(gs) if g["nombre"].casefold() == cf), -1)
    else:
        lista = next((g["categorias"] for g in gs
                      if any(c.casefold() == cf for c in g["categorias"])), None)
        if lista is None:
            return False
        i = next(k for k, c in enumerate(lista) if c.casefold() == cf)
    j = i + delta
    if i < 0 or not 0 <= j < len(lista):
        return False
    lista[i], lista[j] = lista[j], lista[i]
    doc.grupos_categorias = gs
    return True


def aplicar_grupos_de_ejemplo(doc, clave: str) -> None:
    """Arma los grupos con un ejemplo (por etapa o sobre/bajo la línea).
    Las categorías propias quedan en su grupo si ese grupo existe en el
    ejemplo; si no, sin grupo."""
    _titulo, plantilla = GRUPOS_DE_EJEMPLO[clave]
    antes = {c.casefold(): g["nombre"] for g in grupos_de_presupuesto(doc) for c in g["categorias"]}
    gs = [{"nombre": n, "categorias": list(cs)} for n, cs in plantilla]
    for c, _ico in categorias_de_presupuesto(doc):
        if es_categoria_propia(c):
            g = next((g for g in gs if g["nombre"].casefold() == antes.get(c.casefold(), "").casefold()),
                     None)
            if g is not None:
                g["categorias"].append(c)
    doc.grupos_categorias = gs


def renombrar_categoria_propia(doc, viejo: str, nuevo: str, icono: str = "") -> str:
    """Cambia el nombre (y el ícono) de una categoría propia: sus gastos,
    sus líneas movidas, su grupo y su «sin IVA» la siguen. Las de siempre
    no se renombran. Devuelve el nombre nuevo («» si no se pudo)."""
    viejo = nombre_categoria(doc, viejo)
    nuevo = _nombre_cat(nuevo)
    if not viejo or not nuevo or not es_categoria_propia(viejo):
        return ""
    existente = next((c for c, _ in categorias_de_presupuesto(doc)
                      if c.casefold() == nuevo.casefold() and c.casefold() != viejo.casefold()), "")
    if not isinstance(getattr(doc, "categorias_propias", None), list):
        doc.categorias_propias = []
    reg = _registro_categoria(doc, viejo)
    if existente:                              # (ya existe: se juntan)
        nuevo = existente
        if reg is not None:
            doc.categorias_propias.remove(reg)
        if icono and es_categoria_propia(existente):
            crear_categoria_propia(doc, existente, icono)
    else:
        if reg is None:
            reg = {"nombre": viejo, "icono": ICONO_CATEGORIA_PROPIA}
            doc.categorias_propias.append(reg)
        reg["nombre"] = nuevo
        if icono:
            reg["icono"] = icono
    for g in getattr(doc, "gastos", None) or []:
        if isinstance(g, dict) and _nombre_cat(g.get("categoria")).casefold() == viejo.casefold():
            g["categoria"] = nuevo
    cl = getattr(doc, "categoria_lineas", None) or {}
    for k in list(cl):
        if _nombre_cat(cl[k]).casefold() == viejo.casefold():
            cl[k] = nuevo
    doc.categoria_lineas = cl
    gs = grupos_de_presupuesto(doc)
    for g in gs:
        g["categorias"] = [nuevo if c.casefold() == viejo.casefold() else c for c in g["categorias"]]
    doc.grupos_categorias = gs
    doc.grupos_categorias = grupos_de_presupuesto(doc)      # (sin repetidas, si se juntaron)
    ex = []
    for x in getattr(doc, "iva_exentos", None) or []:
        x = f"cat:{nuevo}" if x == f"cat:{viejo}" else x
        if x not in ex:
            ex.append(x)
    doc.iva_exentos = ex
    return nuevo


def eliminar_categoria_propia(doc, nombre: str) -> int:
    """Quita una categoría propia: las líneas movidas a ella vuelven a su
    categoría de siempre y los gastos a mano pasan a «Otros». Devuelve
    cuántas líneas cambiaron de categoría."""
    n = nombre_categoria(doc, nombre)
    if not n or not es_categoria_propia(n):
        return 0
    cf = n.casefold()
    cambiadas = 0
    doc.categorias_propias = [c for c in (getattr(doc, "categorias_propias", None) or [])
                              if not (isinstance(c, dict) and _nombre_cat(c.get("nombre")).casefold() == cf)]
    for g in getattr(doc, "gastos", None) or []:
        if isinstance(g, dict) and _nombre_cat(g.get("categoria")).casefold() == cf:
            g["categoria"] = "Otros"
            cambiadas += 1
    cl = getattr(doc, "categoria_lineas", None) or {}
    for k in [k for k, v in cl.items() if _nombre_cat(v).casefold() == cf]:
        del cl[k]
        cambiadas += 1
    doc.categoria_lineas = cl
    poner_grupo_de_categoria(doc, n, "")
    doc.iva_exentos = [x for x in (getattr(doc, "iva_exentos", None) or []) if x != f"cat:{n}"]
    return cambiadas


def mover_linea_a_categoria(doc, linea: dict, cat: str) -> str:
    """Pasa una línea del presupuesto a otra categoría (la crea si es
    nueva). Un gasto a mano cambia su categoría; una línea automática
    (ficha, tag, documento) queda anotada en doc.categoria_lineas, y al
    volver a la suya se borra la nota. Devuelve la categoría."""
    cat = crear_categoria_propia(doc, cat) if es_categoria_propia(cat) else nombre_categoria(doc, cat)
    if not cat:
        return ""
    if linea.get("origen") == "manual":
        for g in getattr(doc, "gastos", None) or []:
            if isinstance(g, dict) and str(g.get("id", "")) == str(linea.get("ref", "")):
                g["categoria"] = cat
        return cat
    if not isinstance(getattr(doc, "categoria_lineas", None), dict):
        doc.categoria_lineas = {}
    auto = linea.get("categoria_auto") or linea.get("categoria", "")
    if cat.casefold() == _nombre_cat(auto).casefold():
        doc.categoria_lineas.pop(linea["clave"], None)
    else:
        doc.categoria_lineas[linea["clave"]] = cat
    return cat


def presupuesto_por_grupo(doc, lineas: list) -> list[dict]:
    """Las líneas ordenadas por grupo y categoría, con sus subtotales:
    [{nombre (grupo, «» si no hay grupos), total, pagado, n, categorias:
    [{nombre, icono, total, pagado, lineas}]}]. Los grupos y categorías
    sin líneas no van."""
    hay_grupos = bool(grupos_de_presupuesto(doc))
    orden = orden_categorias(doc)
    idx = {c.casefold(): i for i, c in enumerate(orden)}
    por_cat: dict = {}
    for l in lineas:
        por_cat.setdefault(l["categoria"], []).append(l)
    cats = sorted(por_cat, key=lambda c: (idx.get(c.casefold(), len(idx)), c.casefold()))
    out: list[dict] = []
    for c in cats:
        gnom = (grupo_de_categoria(doc, c) or SIN_GRUPO) if hay_grupos else ""
        g = next((x for x in out if x["nombre"] == gnom), None)
        if g is None:
            g = {"nombre": gnom, "total": 0.0, "pagado": 0.0, "n": 0, "categorias": []}
            out.append(g)
        ls = por_cat[c]
        tot = sum(l["total"] for l in ls)
        pag = sum(l["total"] for l in ls if l["pagado"])
        g["categorias"].append({"nombre": c, "icono": icono_categoria(doc, c), "total": tot,
                                "pagado": pag, "lineas": ls})
        g["total"] += tot
        g["pagado"] += pag
        g["n"] += len(ls)
    if hay_grupos:                             # «Sin grupo», al final
        out.sort(key=lambda g: g["nombre"] == SIN_GRUPO)
    return out


def lineas_presupuesto(doc) -> list[dict]:
    """Todas las líneas del presupuesto del proyecto:

      · Fichas (elenco, locaciones, crew, equipamiento): costo por día
        (valor + transporte + alimentación) × días en la Carta Gantt.
      · Tags del guion con valor (utilería, vestuario, vehículos…).
      · Documentos de «Contratos y seguros» que traen monto.
      · Gastos ingresados a mano.

    Cada línea: {clave, origen, categoria, concepto, detalle, proveedor,
    cantidad, unitario, total, aviso, protegido, ref, pagado,
    fecha_pago, notas}. La `clave` es estable y sirve para guardar el
    ✓ pagado en doc.pagos."""
    jor = getattr(doc, "jornadas", []) or []
    pagos = getattr(doc, "pagos", {}) or {}
    out: list[dict] = []

    def agregar(clave, origen, categoria, concepto, total, *,
                detalle="", proveedor="", cantidad=1.0, unitario=None,
                aviso="", protegido=False, ref="", **extra):
        p = pagos.get(clave) or {}
        out.append({**extra,
            "clave": clave, "origen": origen, "categoria": categoria,
            "concepto": concepto, "detalle": detalle,
            "proveedor": proveedor or "", "cantidad": float(cantidad),
            "unitario": float(total if unitario is None else unitario),
            "total": float(total), "aviso": aviso, "protegido": protegido,
            "ref": ref, "pagado": bool(p.get("pagado")),
            "fecha_pago": str(p.get("fecha_pago", "") or ""),
            "notas": str(p.get("notas", "") or ""),
        })

    cat_kind = {"actor": "Elenco", "locacion": "Locaciones",
                "tecnico": "Crew", "equipamiento": "Equipamiento"}
    for kind, nombre, obj in _iter_recursos(doc):
        dias = dias_de_recurso_en_jornadas(nombre, kind, jor)
        cd, desg, prot = costo_dia_detallado(obj, kind)
        if cd <= 0 and dias <= 0 and not prot:
            continue                # ficha sin costo ni días: no es gasto
        # Precio escrito como 0 → es gratis (ej: el liceo del curso),
        # no un dato que falta.
        campo = "actor_valor_dia" if kind == "actor" else "precio_dia"
        gratis = (cd <= 0 and not prot
                  and str(getattr(obj, campo, "") or "").strip() != "")
        if prot:
            aviso = "🔒 valor protegido con PIN"
        elif cd <= 0 and not gratis:
            aviso = "⚠ falta el valor por día en la ficha"
        elif dias <= 0:
            aviso = "⚠ sin días en la Carta Gantt"
        else:
            aviso = ""
        det = (f"{dias} día{'s' if dias != 1 else ''} · sin costo" if gratis
               else f"{dias} día{'s' if dias != 1 else ''} × {fmt_moneda(cd)}")
        if desg:
            det += f"  ({desg})"
        if kind == "equipamiento":
            prov = getattr(obj, "proveedor", "") or ""
        elif kind == "actor":
            prov = _texto_seguro(getattr(obj, "actor_nombre", ""))[0]
        elif kind == "locacion":
            prov = (getattr(obj, "ciudad", "") or
                    getattr(obj, "ubicacion", "") or "")
        else:
            prov = getattr(obj, "nombre", "") or ""
        agregar(f"{kind}:{nombre}", "ficha", cat_kind[kind],
                nombre_visible_recurso(kind, nombre, obj), cd * dias,
                detalle=det, proveedor=prov, cantidad=dias, unitario=cd,
                aviso=aviso, protegido=prot, ref=f"{kind}:{nombre}")

    # ── Tags del guion con valor ──
    try:
        info = calcular_costo_tags_totales(doc)
    except Exception:
        info = {"desglose": []}
    bloques = getattr(doc, "bloques", []) or []
    ords = [i for i, b in enumerate(bloques) if b.elem == Elem.ESCENA]
    nums = numeros_de_escena(bloques,
                             getattr(doc, "numeracion_bloqueada", False))
    vistos: dict[str, int] = {}
    for d in info.get("desglose", []):
        cid = d.get("categoria", "")
        cont = (d.get("contenido", "") or "").strip()
        base = f"tag:{cid}:{cont.lower()}"
        k = vistos.get(base, 0)
        vistos[base] = k + 1
        clave = base if k == 0 else f"{base}#{k}"
        n = int(d.get("escena", 0) or 0)
        num = nums.get(ords[n - 1], str(n)) if 0 < n <= len(ords) else ""
        vu = d.get("valor_unitario", 0) or 0
        tc = d.get("tipo_compra", "unica")
        if tc == "cantidad":
            det, cant = f"{d.get('cantidad', 1)} × {fmt_moneda(vu)}", d.get("cantidad", 1)
        elif tc == "diaria":
            dd = d.get("dias_uso", 1)
            det, cant = f"{dd} día{'s' if dd != 1 else ''} × {fmt_moneda(vu)}", dd
        else:
            det, cant = "compra única", 1
        det = (f"Tag esc. {num} · " if num else "Tag · ") + det
        nombre_cat, emoji = CATEGORIAS_DICT.get(cid, (cid, "🏷"))
        agregar(clave, "tag", _CAT_TAG_A_GASTO.get(cid, "Otros"),
                f"{d.get('icono') or emoji} {cont or nombre_cat}",
                d.get("costo_total", 0), detalle=det, cantidad=cant,
                unitario=vu, escena=n, tipo_compra=tc,
                ref=f"{d.get('idx_bloque', -1)}:{d.get('idx_tag', -1)}")

    # ── Documentos del proyecto con monto (seguros, permisos…) ──
    for d in getattr(doc, "documentos_legales", []) or []:
        m = parse_precio(str(d.get("monto", "") or ""))
        if m <= 0:
            continue
        tipo = d.get("tipo") or "Otro"
        agregar(f"doc:{d.get('id', '')}", "doc",
                _TIPO_DOC_A_GASTO.get(tipo, "Otros"),
                d.get("titulo") or tipo, m,
                detalle=f"📜 {tipo} (Contratos y seguros)",
                proveedor=d.get("contraparte", ""), ref=d.get("id", ""),
                firma=str(d.get("firma", "") or ""))

    # ── Gastos ingresados a mano ──
    for g in getattr(doc, "gastos", []) or []:
        cant = _a_float(g.get("cantidad", 1), 1.0)
        val = parse_precio(str(g.get("valor", "") or ""))
        det = (f"{_fmt_cantidad(cant)} × {fmt_moneda(val)}"
               if abs(cant - 1) > 1e-9 else "Gasto ingresado a mano")
        agregar(f"gasto:{g.get('id', '')}", "manual",
                g.get("categoria") or "Otros",
                g.get("concepto") or "(sin concepto)", cant * val,
                detalle=det, proveedor=g.get("proveedor", ""),
                cantidad=cant, unitario=val,
                aviso="" if val > 0 else "⚠ falta el valor",
                ref=g.get("id", ""), cuando=str(g.get("cuando", "") or ""),
                sin_iva=bool(g.get("sin_iva")))
    # ── 🗂 Líneas automáticas movidas a otra categoría ──
    movidas = getattr(doc, "categoria_lineas", None) or {}
    for l in out:
        l["categoria_auto"] = l["categoria"]
        nueva = _nombre_cat(movidas.get(l["clave"], "")) if l["origen"] != "manual" else ""
        if nueva:
            l["categoria"] = nueva
    # ── 💲 IVA: «total» es lo que se paga; «neto» e «iva», su desglose ──
    modo, tasa = config_iva(doc)
    for l in out:
        exento = bool(modo) and linea_exenta_iva(doc, l["clave"], l["categoria"],
                                                 bool(l.get("sin_iva")))
        base = l["total"]
        neto, iva, tot = separar_iva(base, modo, tasa, exento)
        l.update(base=base, neto=neto, iva=iva, total=tot, exento=exento)
        if modo == "aparte" and iva > 0:
            l["detalle"] += " + IVA"
        elif modo and exento:
            l["detalle"] += " · sin IVA"
    return out


def resumen_presupuesto(lineas: list[dict], fondos: float = 0.0,
                        iva: tuple = ("", 0.0), doc=None) -> dict:
    """Totales del presupuesto y resumen por categoría (en el orden
    de CATEGORIAS_GASTO o, con `doc`, en el de sus grupos y categorías
    propias, y con «por_grupo»). `iva` es config_iva(doc): con él, el
    resumen trae también el neto y el IVA."""
    total = sum(l["total"] for l in lineas)
    neto = sum(l.get("neto", l["total"]) for l in lineas)
    monto_iva = sum(l.get("iva", 0.0) for l in lineas)
    pagado = sum(l["total"] for l in lineas if l["pagado"])
    por_cat: dict[str, dict] = {}
    for l in lineas:
        c = por_cat.setdefault(l["categoria"],
                               {"total": 0.0, "pagado": 0.0, "n": 0})
        c["total"] += l["total"]
        c["n"] += 1
        if l["pagado"]:
            c["pagado"] += l["total"]
    orden = (orden_categorias(doc) if doc is not None
             else [c for c, _ in CATEGORIAS_GASTO])
    idx = {c.casefold(): i for i, c in enumerate(orden)}
    por_cat = dict(sorted(
        por_cat.items(),
        key=lambda kv: (idx.get(kv[0].casefold(), len(orden)), kv[0])))
    por_grupo: dict = {}
    if doc is not None and grupos_de_presupuesto(doc):
        for g in presupuesto_por_grupo(doc, lineas):
            por_grupo[g["nombre"]] = {"total": g["total"], "pagado": g["pagado"], "n": g["n"],
                                      "categorias": [c["nombre"] for c in g["categorias"]]}
            for c in g["categorias"]:
                por_cat[c["nombre"]]["grupo"] = g["nombre"]
    return {"total": total, "pagado": pagado, "pendiente": total - pagado,
            "fondos": float(fondos or 0), "saldo": float(fondos or 0) - total,
            "por_categoria": por_cat, "por_grupo": por_grupo,
            "avisos": sum(1 for l in lineas if l["aviso"]),
            "neto": neto, "iva": monto_iva,
            "iva_modo": (iva or ("", 0.0))[0], "iva_tasa": (iva or ("", 0.0))[1]}


def marcar_pago(doc, clave: str, pagado: bool, fecha: str = "") -> None:
    """✓ pagado de una línea del presupuesto (con la fecha de hoy si no
    se indica otra)."""
    if not isinstance(getattr(doc, "pagos", None), dict):
        doc.pagos = {}
    p = dict(doc.pagos.get(clave) or {})
    p["pagado"] = bool(pagado)
    p["fecha_pago"] = (fecha or date.today().isoformat()) if pagado else ""
    if not p["pagado"] and not p.get("notas"):
        doc.pagos.pop(clave, None)
    else:
        doc.pagos[clave] = p


def nota_pago(doc, clave: str, notas: str = None, fecha: str = None) -> None:
    if not isinstance(getattr(doc, "pagos", None), dict):
        doc.pagos = {}
    p = dict(doc.pagos.get(clave) or {})
    if notas is not None:
        p["notas"] = notas
    if fecha is not None:
        p["fecha_pago"] = fecha
    if not p.get("pagado") and not p.get("notas"):
        doc.pagos.pop(clave, None)
    else:
        doc.pagos[clave] = p

# ── El presupuesto en el calendario: financiar el rodaje por fechas ──

ORDENES_PRESUPUESTO = [
    ("cat", "📂 Por categoría"),
    ("grupo", "🗂 Por grupo y categoría, con subtotales"),
    ("rodaje", "🎬 Por orden de rodaje"),
    ("fecha", "📅 Agrupado por fecha de rodaje"),
]

_DIAS_SEM_CORTOS = ["lun", "mar", "mié", "jue", "vie", "sáb", "dom"]


def fecha_con_dia(iso: str) -> str:
    """'2026-05-12' → 'mar 12/05/2026' (o el texto tal cual)."""
    d = _fecha_iso(str(iso or ""))
    if d is None:
        return fecha_visible(iso)
    return f"{_DIAS_SEM_CORTOS[d.weekday()]} {d.strftime('%d/%m/%Y')}"


def nombre_jornada(doc, i: int) -> str:
    """El nombre de la jornada i como se ve en la Carta Gantt."""
    jor = getattr(doc, "jornadas", []) or []
    if not 0 <= i < len(jor):
        return ""
    j = jor[i]
    nom = (j.nombre or "").strip()
    if not nom:
        lugar = (j.lugar or "").strip()
        nom = f"Jornada {i + 1}" + (f" — {lugar}" if lugar else "")
    return nom


def _mas_iva(l: dict) -> str:
    """« + IVA» si a esta línea se le suma el IVA encima (valores netos)."""
    return " + IVA" if l.get("total", 0) - l.get("base", l.get("total", 0)) > 0.5 else ""


def tramos_presupuesto(doc, lineas: list[dict]) -> list[dict]:
    """Ubica cada línea del presupuesto en el calendario del rodaje,
    para saber cuánta plata hace falta en cada fecha.

    Devuelve tramos {clave, monto, detalle, jornada, fecha, parte}:
      · jornada: índice en doc.jornadas, o -1 si no es de una jornada;
      · fecha: ISO de inicio (de la jornada o del gasto), o «»;
      · parte: True si la línea se reparte en varios tramos.
    Reglas:
      · fichas: su total se reparte según los días de CADA jornada
        donde aparecen (una actriz en 3 jornadas → 3 tramos);
      · tags: «por día» se reparte en las jornadas que graban su
        escena; la compra única o por cantidad va a la primera;
      · contratos y seguros: en su fecha de firma / emisión;
      · gastos a mano: en su fecha, repartidos en los días de rodaje
        (catering, transporte…) o sin fecha.
    La suma de los tramos de una línea es siempre su total."""
    jor = list(getattr(doc, "jornadas", []) or [])
    fechas = []
    for j in jor:
        d = _fecha_iso(j.fecha or "")
        fechas.append(d.isoformat() if d else "")
    dias = [dias_de_jornada(j) for j in jor]
    escenas = [set(_escenas_de_jornada(j)) for j in jor]

    def cronologico(idxs):
        return sorted(idxs, key=lambda i: (fechas[i] or "9999-12-31", i))

    out: list[dict] = []

    def tramo(l, monto, detalle, jornada=-1, fecha="", parte=False):
        out.append({"clave": l["clave"], "monto": float(monto),
                    "detalle": detalle, "jornada": jornada,
                    "fecha": fechas[jornada] if jornada >= 0 else fecha,
                    "parte": parte})

    def repartir(l, pesos: dict, como: str) -> None:
        """El total de la línea, proporcional a los días de cada jornada."""
        tot = sum(pesos.values()) or 1
        for i in cronologico(pesos):
            w = pesos[i]
            tramo(l, l["total"] * w / tot,
                  f"{w} de {tot} día{'s' if tot != 1 else ''} · {como}",
                  i, parte=True)

    for l in lineas:
        o = l["origen"]
        if o == "ficha":
            kind, _, nombre = l["clave"].partition(":")
            idxs = jornadas_de_recurso(nombre, kind, jor)
            con_dias = {i: dias[i] for i in idxs if dias[i] > 0}
            if len(con_dias) > 1 and l["total"] > 0:
                repartir(l, con_dias, f"{fmt_moneda(l['unitario'])} por día{_mas_iva(l)}")
                continue
            if idxs:
                tramo(l, l["total"], l["detalle"],
                      cronologico(con_dias or idxs)[0])
                continue
        elif o == "tag":
            n = int(l.get("escena", 0) or 0)
            idxs = [i for i, e in enumerate(escenas) if n and n in e]
            if idxs:
                if (l.get("tipo_compra") == "diaria" and len(idxs) > 1
                        and l["total"] > 0):
                    repartir(l, {i: (dias[i] or 1) for i in idxs},
                             f"{fmt_moneda(l['unitario'])} por día{_mas_iva(l)}")
                    continue
                tramo(l, l["total"], l["detalle"], cronologico(idxs)[0])
                continue
        elif o == "doc":
            f = _fecha_iso(l.get("firma", "") or "")
            if f:
                tramo(l, l["total"], l["detalle"], fecha=f.isoformat())
                continue
        elif o == "manual":
            cuando = l.get("cuando", "") or ""
            if cuando == "jornadas" and jor:
                pesos = ({i: dias[i] for i in range(len(jor)) if dias[i] > 0}
                         or {i: 1 for i in range(len(jor))})
                if len(pesos) == 1 or l["total"] <= 0:
                    tramo(l, l["total"], l["detalle"], cronologico(pesos)[0])
                else:
                    repartir(l, pesos, "repartido en el rodaje")
                continue
            f = _fecha_iso(cuando)
            if f:
                tramo(l, l["total"], l["detalle"], fecha=f.isoformat())
                continue
        tramo(l, l["total"], l["detalle"])
    return out


def grupos_presupuesto_por_fecha(doc, lineas: list[dict],
                                 tramos: Optional[list] = None) -> list[dict]:
    """Los tramos del presupuesto agrupados por jornada (o por fecha,
    si un gasto cae fuera de las jornadas), en orden cronológico.

    Cada grupo: {clave, tipo ("j" jornada, "f" fecha, "s" sin fecha),
    jornada, fecha, titulo, filas [(linea, tramo)], total, pagado,
    acumulado, pendiente_acumulado}. El ACUMULADO es lo que hay que
    tener juntado para llegar a esa fecha; lo «sin fecha» va al final."""
    jor = list(getattr(doc, "jornadas", []) or [])
    if tramos is None:
        tramos = tramos_presupuesto(doc, lineas)
    por_clave = {l["clave"]: l for l in lineas}
    rangos = []
    for i, j in enumerate(jor):
        d0 = _fecha_iso(j.fecha or "")
        if d0:
            d1 = _fecha_iso(j.fecha_fin or "") or d0
            rangos.append((min(d0, d1), max(d0, d1), i))
    grupos: dict = {}
    for t in tramos:
        l = por_clave.get(t["clave"])
        if l is None:
            continue
        if t["jornada"] >= 0:
            k = ("j", t["jornada"])
        elif t["fecha"]:
            d = _fecha_iso(t["fecha"])
            dentro = [i for a, b, i in rangos if d and a <= d <= b]
            k = ("j", dentro[0]) if dentro else ("f", t["fecha"])
        else:
            k = ("s", "")
        g = grupos.get(k)
        if g is None:
            g = grupos[k] = {"clave": f"{k[0]}:{k[1]}", "tipo": k[0],
                             "jornada": k[1] if k[0] == "j" else -1,
                             "fecha": "", "titulo": "", "filas": [],
                             "total": 0.0, "pagado": 0.0}
            if k[0] == "j":
                j = jor[k[1]]
                d0 = _fecha_iso(j.fecha or "")
                d1 = _fecha_iso(j.fecha_fin or "")
                g["fecha"] = d0.isoformat() if d0 else ""
                if d0:
                    rango = fecha_con_dia(g["fecha"])
                    if d1 and d1 != d0:
                        rango += f" al {fecha_con_dia(d1.isoformat())}"
                    g["titulo"] = f"📅 {rango} · {nombre_jornada(doc, k[1])}"
                else:
                    g["titulo"] = (f"📅 Sin fecha todavía · "
                                   f"{nombre_jornada(doc, k[1])}")
            elif k[0] == "f":
                g["fecha"] = k[1]
                g["titulo"] = f"📅 {fecha_con_dia(k[1])} · Otros gastos de ese día"
            else:
                g["titulo"] = ("🗂 Sin fecha (antes o después del rodaje: "
                               "seguros, permisos, postproducción…)")
        g["filas"].append((l, t))
        g["total"] += t["monto"]
        if l["pagado"]:
            g["pagado"] += t["monto"]

    def orden(g):
        if g["tipo"] == "s":
            return ("9999-12-31", 2, 0)
        if g["tipo"] == "j":
            return (g["fecha"] or "9999-12-30", 0, g["jornada"])
        return (g["fecha"], 1, 0)

    out = sorted(grupos.values(), key=orden)
    acum = pend = 0.0
    for g in out:
        acum += g["total"]
        pend += g["total"] - g["pagado"]
        g["acumulado"], g["pendiente_acumulado"] = acum, pend
    return out


def lineas_en_orden_de_rodaje(doc, lineas: list[dict],
                              grupos: Optional[list] = None
                              ) -> list[tuple[dict, str]]:
    """Las líneas (sin repartir) ordenadas por la PRIMERA fecha en que
    se necesitan, con una etiqueta corta: «📅 12/05 · Jornada 1 — Liceo
    (+2)». Lo que no tiene fecha va al final, sin etiqueta."""
    if grupos is None:
        grupos = grupos_presupuesto_por_fecha(doc, lineas)
    n_grupos: dict[str, int] = {}
    for g in grupos:
        for l, _t in g["filas"]:
            n_grupos[l["clave"]] = n_grupos.get(l["clave"], 0) + 1
    out: list[tuple[dict, str]] = []
    vistos: set = set()
    for g in grupos:
        for l, _t in g["filas"]:
            if l["clave"] in vistos:
                continue
            vistos.add(l["clave"])
            if g["tipo"] == "s":
                etq = ""
            else:
                d = _fecha_iso(g["fecha"])
                etq = "📅 " + (d.strftime("%d/%m") if d else "sin fecha")
                if g["tipo"] == "j":
                    etq += f" · {nombre_jornada(doc, g['jornada'])}"
                mas = n_grupos.get(l["clave"], 1) - 1
                if mas > 0:
                    etq += f" (+{mas})"
            out.append((l, etq))
    return out


def _tipo_doc_desde_texto(txt: str, defecto: str = "Otro") -> str:
    """Adivina el tipo de un documento por su etiqueta/nombre."""
    t = (txt or "").lower()
    reglas = [
        (r"seguro|p[óo]liza", "Seguro"),
        (r"permiso|municip", "Permiso municipal"),
        (r"menor(es)?\b", "Autorización de menores"),
        (r"cesi[óo]n|derechos? de imagen|\bimagen\b", "Cesión de derechos / imagen"),
        (r"confidencial|\bnda\b", "Acuerdo de confidencialidad"),
        (r"catering", "Catering"),
        (r"transporte|traslado", "Transporte"),
        (r"m[úu]sica|licencia", "Música / licencia"),
        (r"boleta|factura|recibo", "Boleta / factura"),
        (r"arriendo|alquiler", "Arriendo de equipo"),
    ]
    for patron, tipo in reglas:
        if re.search(patron, t):
            return tipo
    return defecto


def es_tipo_contrato(tipo: str) -> bool:
    return (tipo or "").startswith(("Contrato", "Arriendo"))


def _recurso_contratado(kind: str, nombre: str, obj, jornadas) -> bool:
    """¿Este recurso necesita contrato? (tiene días, costo o actor)."""
    if dias_de_recurso_en_jornadas(nombre, kind, jornadas) > 0:
        return True
    cd, _, prot = costo_dia_detallado(obj, kind)
    if cd > 0 or prot:
        return True
    if kind == "actor":
        return bool((getattr(obj, "actor_nombre", "") or "").strip())
    return False


def estado_documento(estado: str, tiene_archivo: bool, vence: str,
                     es_contrato: bool = False,
                     hoy: Optional[date] = None) -> tuple[str, str]:
    """(texto visible, nivel) — nivel ∈ ok · pend · falta · pronto ·
    vencido · na. Los vencimientos mandan sobre el estado escrito."""
    hoy = hoy or date.today()
    if estado == "No aplica":
        return "— No aplica", "na"
    try:
        dv = date.fromisoformat(vence) if vence else None
    except ValueError:
        dv = None
    if dv is not None:
        dd = (dv - hoy).days
        if dd < 0:
            return f"⛔ Vencido ({fecha_visible(vence)})", "vencido"
        if dd <= DIAS_AVISO_VENCIMIENTO:
            return ("⏰ Vence hoy" if dd == 0 else
                    f"⏰ Vence en {dd} día{'s' if dd != 1 else ''}"), "pronto"
    if estado == "Vencido":
        return "⛔ Vencido", "vencido"
    if es_contrato and not tiene_archivo and estado in ("", "Pendiente"):
        return "⚠ Falta contrato", "falta"
    if estado in ("Firmado", "Vigente"):
        return f"✅ {estado}", "ok"
    if estado == "Recibido":
        return "📥 Recibido", "ok"
    if estado == "Enviado":
        return "📤 Enviado", "pend"
    return "⏳ Pendiente", "pend"


def documentos_contratos(doc, hoy: Optional[date] = None) -> list[dict]:
    """Vista central de TODOS los documentos legales del proyecto:

      · de las fichas: contrato, otros documentos y boletas de cada
        actor, locación, integrante del crew y equipo;
      · «⚠ Falta contrato» para los recursos contratados (con días,
        costo o actor asignado) que aún no tienen contrato;
      · los documentos del proyecto (permisos, seguros, catering…).

    Cada fila: {clave, origen ("ficha"|"proyecto"), slot, indice,
    vinculo, grupo, tipo, titulo, contraparte, archivo_nombre,
    tiene_archivo, estado, firma, vence, monto, notas, estado_vis,
    nivel, id}."""
    hoy = hoy or date.today()
    meta_all = getattr(doc, "docs_meta", {}) or {}
    legales = getattr(doc, "documentos_legales", []) or []
    jor = getattr(doc, "jornadas", []) or []
    filas: list[dict] = []
    con_contrato_proyecto = {
        d.get("vinculo") for d in legales
        if d.get("vinculo") and es_tipo_contrato(d.get("tipo", ""))}

    def fila(**kw):
        m = kw.pop("meta", {}) or {}
        tiene = bool(kw.get("tiene_archivo"))
        estado = (m.get("estado") or
                  ("Recibido" if tiene else "Pendiente"))
        r = {"clave": "", "origen": "ficha", "slot": "", "indice": -1,
             "vinculo": "", "grupo": "Proyecto", "tipo": "Otro",
             "titulo": "", "contraparte": "", "archivo_nombre": "",
             "tiene_archivo": tiene, "estado": estado,
             "firma": str(m.get("firma", "") or ""),
             "vence": str(m.get("vence", "") or ""),
             "monto": str(m.get("monto", "") or ""),
             "notas": str(m.get("notas", "") or ""), "id": ""}
        r.update(kw)
        r["estado_vis"], r["nivel"] = estado_documento(
            estado, tiene, r["vence"], r["slot"] == "contrato", hoy)
        filas.append(r)

    for kind, nombre, obj in _iter_recursos(doc):
        grupo, tipo_contrato = _KIND_INFO[kind]
        vinc = f"{kind}:{nombre}"
        contraparte = nombre_visible_recurso(kind, nombre, obj)
        clave = f"{vinc}:contrato"
        m = meta_all.get(clave) or {}
        tiene = bool(getattr(obj, "contrato_nombre", "")
                     and getattr(obj, "contrato_datos", ""))
        if tiene or m or (vinc not in con_contrato_proyecto
                          and _recurso_contratado(kind, nombre, obj, jor)):
            fila(clave=clave, slot="contrato", vinculo=vinc, grupo=grupo,
                 tipo=m.get("tipo") or tipo_contrato,
                 titulo=f"Contrato — {nombre}", contraparte=contraparte,
                 archivo_nombre=obj.contrato_nombre if tiene else "",
                 tiene_archivo=tiene, meta=m)
        cont: dict[tuple, int] = {}
        for slot, lista, defecto in (
                ("doc", getattr(obj, "documentos", []) or [], "Otro"),
                ("boleta", getattr(obj, "boletas", []) or [],
                 "Boleta / factura")):
            for i, d in enumerate(lista):
                n = getattr(d, "nombre", "") or "documento"
                c = cont.get((slot, n), 0)
                cont[(slot, n)] = c + 1
                clave = f"{vinc}:{slot}:{n}" + (f"#{c}" if c else "")
                m = meta_all.get(clave) or {}
                etq = getattr(d, "etiqueta", "") or ""
                fila(clave=clave, slot=slot, indice=i, vinculo=vinc,
                     grupo=grupo,
                     tipo=m.get("tipo") or (
                         defecto if slot == "boleta" else
                         _tipo_doc_desde_texto(f"{etq} {n}", defecto)),
                     titulo=etq or n, contraparte=contraparte,
                     archivo_nombre=n,
                     tiene_archivo=bool(getattr(d, "datos", "")), meta=m)
        if (getattr(obj, "boleta_nombre", "")
                and getattr(obj, "boleta_datos", "")):
            clave = f"{vinc}:boleta_unica"
            m = meta_all.get(clave) or {}
            fila(clave=clave, slot="boleta_unica", vinculo=vinc,
                 grupo=grupo, tipo=m.get("tipo") or "Boleta / factura",
                 titulo=obj.boleta_nombre, contraparte=contraparte,
                 archivo_nombre=obj.boleta_nombre, tiene_archivo=True,
                 meta=m)

    for d in legales:
        vinc = d.get("vinculo", "") or ""
        grupo = "Proyecto"
        if vinc:
            kind = vinc.partition(":")[0]
            if kind in _KIND_INFO and recurso_por_vinculo(doc, vinc) is not None:
                grupo = _KIND_INFO[kind][0]
        tiene = bool(d.get("archivo_datos"))
        fila(clave=f"doc:{d.get('id', '')}", origen="proyecto",
             vinculo=vinc, grupo=grupo, tipo=d.get("tipo") or "Otro",
             titulo=d.get("titulo") or d.get("tipo") or "Documento",
             contraparte=d.get("contraparte", "") or "",
             archivo_nombre=d.get("archivo_nombre", "") if tiene else "",
             tiene_archivo=tiene, meta=d, id=d.get("id", ""))

    orden = [g for g, _ in GRUPOS_DOC]
    filas.sort(key=lambda r: (orden.index(r["grupo"]) if r["grupo"] in orden
                              else 99, r["contraparte"].lower(),
                              0 if r["slot"] == "contrato" else 1,
                              r["titulo"].lower()))
    return filas


def resumen_contratos(filas: list[dict]) -> dict:
    out = {"total": len(filas), "ok": 0, "pend": 0, "falta": 0,
           "pronto": 0, "vencido": 0, "na": 0,
           "archivos": sum(1 for f in filas if f["tiene_archivo"])}
    for f in filas:
        out[f["nivel"]] = out.get(f["nivel"], 0) + 1
    return out


def abrir_adjunto_b64(nombre: str, datos_b64: str, parent=None) -> bool:
    """Abre un adjunto (base64) con la app predeterminada del sistema."""
    if not datos_b64:
        return False
    try:
        import tempfile
        from PySide6.QtGui import QDesktopServices
        from PySide6.QtCore import QUrl
        ext = Path(nombre or "").suffix or ".pdf"
        base = re.sub(r"[^\w\-]+", "_", Path(nombre or "doc").stem)[:40]
        tmp = Path(tempfile.gettempdir()) / f"accion_{base}{ext}"
        tmp.write_bytes(base64.b64decode(datos_b64))
        QDesktopServices.openUrl(QUrl.fromLocalFile(str(tmp)))
        return True
    except (OSError, ValueError) as e:
        if parent is not None:
            QMessageBox.warning(parent, "Documento",
                                f"No se pudo abrir el documento:\n{e}")
        return False


def _nombre_archivo_seguro(txt: str, maximo: int = 80) -> str:
    t = re.sub(r'[\\/:*?"<>|\n\r\t]+', " ", txt or "").strip(" .")
    return re.sub(r"\s+", " ", t)[:maximo] or "documento"


# ── 📄 Los informes en PDF, con el diseño de antes ──
# (el de la versión con ReportLab: título azul con el logo, el nombre del
#  proyecto y la fecha, franjas azules por sección y filas con el valor a la
#  derecha). Se dibuja con QPainter a 72 puntos por pulgada: un punto del
#  dibujo es un punto de la hoja, y las letras salen del tamaño que dicen.
COLOR_INFORME_AZUL = "#2b4c9c"
CLAVE_POCA_TINTA = "informes/poca_tinta"       # 🖨 lo último elegido (vale para todos los informes)


def poca_tinta_por_defecto() -> bool:
    v = settings_app().value(CLAVE_POCA_TINTA, False)
    return str(v).lower() in ("true", "1", "si", "yes")


def recordar_poca_tinta(si: bool) -> None:
    settings_app().setValue(CLAVE_POCA_TINTA, bool(si))


FILTRO_PDF_NORMAL = "PDF (*.pdf)"
FILTRO_PDF_POCA_TINTA = "PDF · poca tinta: solo texto y líneas (*.pdf)"


def pedir_ruta_pdf(parent, titulo: str, sugerido: str) -> tuple:
    """El «Guardar como» de un PDF, con dos tipos para elegir: normal o con
    poca tinta. → (ruta o «», poca_tinta). Recuerda lo elegido."""
    elegido = FILTRO_PDF_POCA_TINTA if poca_tinta_por_defecto() else FILTRO_PDF_NORMAL
    if sugerido and Path(sugerido).parent == Path("."):
        sugerido = str(Path(ruta_ultima_carpeta()) / sugerido)
    ruta, filtro = QFileDialog.getSaveFileName(parent, titulo, sugerido,
                                               FILTRO_PDF_NORMAL + ";;" + FILTRO_PDF_POCA_TINTA, elegido)
    if not ruta:
        return "", False
    poca = filtro == FILTRO_PDF_POCA_TINTA
    recordar_poca_tinta(poca)
    if not ruta.lower().endswith(".pdf"):
        ruta += ".pdf"
    return ruta, poca
_RE_EMOJI_INF = re.compile("[\U0001F000-\U0001FAFF☀-⛿✀-➿⬀-⯿⌀-⏿"
                           "️‍⃣←-⇿]")
_EMOJI_INF_OK = set("✓✔✗★•·→")


def texto_sin_emoji(s) -> str:
    """El texto sin emojis (en el PDF salen como cuadritos o desalineados)."""
    s = "".join(c for c in str(s or "") if c in _EMOJI_INF_OK or not _RE_EMOJI_INF.match(c))
    return re.sub(r"[ \t]{2,}", " ", s).strip()


def estilo_fila_informe(f: dict) -> str:
    """normal · detalle · subtitulo · subtotal · total (lo dice la fila, o se deduce)."""
    e = f.get("estilo")
    if e:
        return e
    t = texto_sin_emoji(f.get("texto", ""))
    if re.match(r"^[─—\-=]{2,}.*[─—\-=]{2,}$", t):
        return "subtitulo"
    if re.match(r"^TOTAL\b", t):
        return "total"
    if re.match(r"^(SUBTOTAL|Subtotal)\b", t):
        return "subtotal"
    return "detalle" if int(f.get("sangria", 0) or 0) >= 1 else "normal"


def _dato_visible(v) -> str:
    """Un dato de una ficha para un informe: '' si está vacío y
    'protegido con PIN' si está cifrado."""
    if not v:
        return ""
    if esta_cifrado(v):
        return "protegido con PIN"
    return str(v).strip()


def _une(*partes, sep: str = " · ") -> str:
    return sep.join(str(x).strip() for x in partes if x and str(x).strip())


def _plural(n: int, uno: str, varios: str) -> str:
    return f"{n} {uno if n == 1 else varios}"


def _fechas_cortas(fechas: list) -> str:
    """['2026-07-20', '2026-07-21'] → '20/07, 21/07' (con el año si cambia)."""
    out = []
    for f in fechas:
        try:
            d = date.fromisoformat(str(f))
            out.append(d.strftime("%d/%m"))
        except (TypeError, ValueError):
            if f:
                out.append(str(f))
    return ", ".join(out)


def escenas_por_lugar_del_guion(doc) -> dict:
    """{'OBSERVATORIO': [2, 3, 4], …}: los lugares de los encabezados (en
    mayúsculas) y en qué escenas aparecen (numeradas desde 1, como en la
    Carta Gantt)."""
    out: dict = {}
    n = 0
    for b in getattr(doc, "bloques", []) or []:
        if b.elem == Elem.ESCENA:
            n += 1
            lugar = _locacion_desde_encabezado(b.texto or "")
            if lugar and lugar != "SIN LOCACIÓN":
                out.setdefault(lugar.upper(), []).append(n)
    return out


def _numeros_de_texto(s: str) -> list:
    return [int(x) for x in re.findall(r"\d+", str(s or ""))]


class InformePDF:
    """📄 Uno o varios informes de ¡Acción! en un PDF tamaño carta."""
    MX, MS, MI = 54.0, 46.0, 50.0                  # márgenes (puntos)

    def __init__(self, ruta=None, ahorro: bool = False, proyecto: str = "",
                 horizontal: bool = False):
        """Con `ruta`, escribe un PDF; sin ella, solo arma las páginas
        (para verlas en pantalla o imprimirlas con imagenes())."""
        from PySide6.QtGui import QPdfWriter
        from PySide6.QtCore import QMarginsF
        self.ruta, self.ahorro = (str(ruta) if ruta else ""), bool(ahorro)
        self.proyecto = texto_sin_emoji(proyecto)
        if self.ruta:
            self.pdf = QPdfWriter(self.ruta)
            self.pdf.setPageSize(QPageSize(QPageSize.PageSizeId.Letter))
            if horizontal:
                self.pdf.setPageOrientation(QPageLayout.Orientation.Landscape)
            self.pdf.setPageMargins(QMarginsF(0, 0, 0, 0), QPageLayout.Unit.Point)
            self.pdf.setResolution(72)
            self.pdf.setTitle(self.proyecto or "Informe")
            self.pdf.setCreator("¡Acción! Software Audiovisual")
            self.W, self.H = float(self.pdf.width()), float(self.pdf.height())
        else:
            # una imagen chica a 72 ppp: solo sirve para medir las letras
            self.pdf = QImage(8, 8, QImage.Format.Format_ARGB32)
            self.pdf.setDotsPerMeterX(2835)
            self.pdf.setDotsPerMeterY(2835)
            self.W, self.H = (792.0, 612.0) if horizontal else (612.0, 792.0)   # carta, en puntos
        self.x0, self.x1 = self.MX, self.W - self.MX
        self.azul = QColor("#111111" if ahorro else COLOR_INFORME_AZUL)
        self.tinta = QColor("#191919")
        self.gris = QColor("#5f6670")
        self.gris_claro = QColor("#a3a9b2")
        self.paginas: list = []
        self.y = self.MS
        self.titulo_actual = ""
        self._generado = datetime.now().strftime("%d-%m-%Y %H:%M")
        try:
            import base64 as _b64
            self.logo = QImage.fromData(_b64.b64decode(LOGO_ACCION_B64))
            if ahorro and not self.logo.isNull():          # sin tinta de color
                alfa = self.logo.convertToFormat(QImage.Format.Format_Alpha8)
                gris = self.logo.convertToFormat(QImage.Format.Format_Grayscale8)
                self.logo = gris.convertToFormat(QImage.Format.Format_ARGB32)
                self.logo.setAlphaChannel(alfa)
        except Exception:
            self.logo = None

    # ── letras ──
    def fuente(self, pt: float, negrita: bool = False, cursiva: bool = False) -> QFont:
        f = QFont("Helvetica")
        f.setStyleHint(QFont.StyleHint.SansSerif)
        f.setFamilies(["Helvetica", "Arial", "Liberation Sans", "DejaVu Sans"])
        f.setPointSizeF(pt)
        f.setBold(negrita)
        f.setItalic(cursiva)
        f.setHintingPreference(QFont.HintingPreference.PreferNoHinting)
        return f

    def _fm(self, f: QFont) -> QFontMetricsF:
        return QFontMetricsF(f, self.pdf)

    def envolver(self, texto: str, f: QFont, ancho: float) -> list:
        fm = self._fm(f)
        out = []
        for parrafo in str(texto or "").split("\n"):
            linea = ""
            for palabra in parrafo.split(" "):
                prueba = (linea + " " + palabra).strip() if linea else palabra
                if fm.horizontalAdvance(prueba) <= ancho or not linea:
                    linea = prueba
                else:
                    out.append(linea)
                    linea = palabra
            out.append(linea)
        return out or [""]

    # ── páginas ──
    def _op(self, fn) -> None:
        self.paginas[-1].append(fn)

    def nueva_pagina(self, continuacion: bool = True) -> None:
        self.paginas.append([])
        self.y = self.MS
        if continuacion and self.titulo_actual:
            tit, f = self.titulo_actual, self.fuente(8, cursiva=True)

            def cab(p, tit=tit, f=f, y=self.y):
                p.setFont(f)
                p.setPen(self.gris)
                p.drawText(QPointF(self.x0, y + 8), f"{tit} (continuación)")
                p.setPen(QPen(QColor("#d5d9df"), 0.6))
                p.drawLine(QPointF(self.x0, y + 13), QPointF(self.x1, y + 13))
            self._op(cab)
            self.y += 24

    def libre(self) -> float:
        return self.H - self.MI - self.y

    def asegurar(self, alto: float) -> None:
        if alto > self.libre():
            self.nueva_pagina()

    # ── un informe ──
    def informe(self, info: dict) -> None:
        self.titulo_actual = texto_sin_emoji(info.get("titulo", "Informe"))
        self.nueva_pagina(continuacion=False)
        y = self.y
        f_tit, f_sub, f_gen = self.fuente(20, True), self.fuente(11, cursiva=True), self.fuente(8.5, cursiva=True)
        logo = self.logo

        def cabecera(p, y=y, tit=self.titulo_actual):
            p.setFont(f_tit)
            p.setPen(self.azul)
            p.drawText(QPointF(self.x0, y + 20), tit)
            if logo is not None and not logo.isNull():
                h = 34.0
                w = h * logo.width() / max(1, logo.height())
                p.drawImage(QRectF(self.x1 - w, y - 2, w, h), logo)
            if self.proyecto:
                p.setFont(f_sub)
                p.setPen(QColor("#3c4043"))
                p.drawText(QPointF(self.x0, y + 38), self.proyecto)
            p.setFont(f_gen)
            p.setPen(self.gris)
            p.drawText(QPointF(self.x0, y + (52 if self.proyecto else 38)), f"Generado el {self._generado}")
        self._op(cabecera)
        self.y += 66 if self.proyecto else 52
        if info.get("graficos"):
            self.graficos(info["graficos"])
        if info.get("gantt"):
            self.gantt(info["gantt"])
        for sec in info.get("secciones") or []:
            self.seccion(sec)

    # ── la carta Gantt: una barra por jornada sobre los días ──
    _MESES = ["enero", "febrero", "marzo", "abril", "mayo", "junio", "julio",
              "agosto", "septiembre", "octubre", "noviembre", "diciembre"]
    _PALETA_GANTT = ["#2b4c9c", "#10b981", "#f59e0b", "#ec4899", "#8b5cf6",
                     "#06b6d4", "#ef4444", "#84cc16", "#64748b"]

    def gantt(self, filas: list) -> None:
        con_fecha = [f for f in filas if f.get("inicio")]
        if not con_fecha:
            return
        from datetime import timedelta
        d0 = min(f["inicio"] for f in con_fecha)
        d1 = max(f.get("fin") or f["inicio"] for f in con_fecha)
        dias = (d1 - d0).days + 1
        paso = 1 if dias <= 62 else 7                      # días o semanas
        if paso == 7:
            d0 = d0 - timedelta(days=d0.weekday())          # desde el lunes
            dias = (d1 - d0).days + 1
        cols = -(-dias // paso)
        x_lab, ancho_lab = self.x0, 150.0
        xt = self.x0 + ancho_lab
        colw = (self.x1 - xt) / cols
        alto_fila, alto_cab = 16.0, 26.0
        lugares = []
        for f in con_fecha:
            if (f.get("lugar") or "") not in lugares:
                lugares.append(f.get("lugar") or "")
        grises = ["#1a1a1a", "#4d4d4d", "#7a7a7a", "#a3a3a3", "#c4c4c4"]
        color_de = {l: (grises[i % 5] if self.ahorro else self._PALETA_GANTT[i % 9])
                    for i, l in enumerate(lugares)}
        f_mes, f_dia, f_lab, f_bar = (self.fuente(7.5, True), self.fuente(6.5),
                                      self.fuente(8), self.fuente(6.8, True))
        dia_de = lambda c: d0 + timedelta(days=c * paso)

        def cabecera():
            y = self.y

            def dib(p, y=y):
                # meses
                p.setFont(f_mes)
                p.setPen(self.azul)
                c = 0
                while c < cols:
                    mes = (dia_de(c).year, dia_de(c).month)
                    k = c
                    while k < cols and (dia_de(k).year, dia_de(k).month) == mes:
                        k += 1
                    fm_m = QFontMetricsF(f_mes, p.device())
                    for txt in (f"{self._MESES[mes[1] - 1]} {mes[0]}", self._MESES[mes[1] - 1][:3]):
                        if (k - c) * colw - 3 >= fm_m.horizontalAdvance(txt):
                            p.drawText(QPointF(xt + c * colw + 2, y + 9), txt)
                            break
                    if c:
                        p.setPen(QPen(self.azul, 0.6))
                        p.drawLine(QPointF(xt + c * colw, y + 1), QPointF(xt + c * colw, y + alto_cab))
                        p.setPen(self.azul)
                    c = k
                # días (o semanas)
                p.setFont(f_dia)
                cada = max(1, int(-(-12 // max(1.0, colw))))   # que no se encimen
                for c in range(cols):
                    d = dia_de(c)
                    if paso == 1 and d.weekday() >= 5:
                        p.fillRect(QRectF(xt + c * colw, y + 13, colw, alto_cab - 13), QColor("#e8ebf0"))
                    if c % cada == 0:
                        txt = str(d.day)
                        w = QFontMetricsF(f_dia, p.device()).horizontalAdvance(txt)
                        p.setPen(self.gris)
                        p.drawText(QPointF(xt + c * colw + (colw - w) / 2, y + 22), txt)
                p.setFont(f_mes)
                p.setPen(self.tinta)
                p.drawText(QPointF(x_lab, y + 22), "Jornada")
                p.setPen(QPen(QColor("#9aa3ae"), 0.8))
                p.drawLine(QPointF(x_lab, y + alto_cab), QPointF(self.x1, y + alto_cab))
            self._op(dib)
            self.y += alto_cab + 2

        self.asegurar(alto_cab + 2 + alto_fila * min(3, len(con_fecha)) + 20)
        cabecera()
        for f in con_fecha:
            pag = len(self.paginas)
            self.asegurar(alto_fila)
            if len(self.paginas) != pag:
                cabecera()
            y = self.y
            c_ini = (f["inicio"] - d0).days / paso
            c_fin = ((f.get("fin") or f["inicio"]) - d0).days / paso + (1 if paso == 1 else 1 / 7)
            color = QColor(color_de[f.get("lugar") or ""])

            def dib(p, y=y, f=f, c_ini=c_ini, c_fin=c_fin, color=color):
                # fines de semana y semanas (líneas suaves)
                for c in range(cols):
                    d = dia_de(c)
                    if paso == 1 and d.weekday() >= 5:
                        p.fillRect(QRectF(xt + c * colw, y, colw, alto_fila), QColor("#f1f3f6"))
                    if paso == 1 and d.weekday() == 0 and c:
                        p.setPen(QPen(QColor("#d5d9df"), 0.5))
                        p.drawLine(QPointF(xt + c * colw, y), QPointF(xt + c * colw, y + alto_fila))
                p.setFont(f_lab)
                p.setPen(self.tinta)
                fm = QFontMetricsF(f_lab, p.device())
                p.drawText(QPointF(x_lab, y + 11),
                           fm.elidedText(texto_sin_emoji(f.get("nombre", "")), Qt.TextElideMode.ElideRight,
                                         ancho_lab - 8))
                r = QRectF(xt + c_ini * colw + 0.5, y + 3, max(3.0, (c_fin - c_ini) * colw - 1), alto_fila - 6)
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(color)
                p.drawRoundedRect(r, 2, 2)
                p.setBrush(Qt.BrushStyle.NoBrush)
                txt = texto_sin_emoji(f.get("lugar") or "")
                fb = QFontMetricsF(f_bar, p.device())
                if txt and fb.horizontalAdvance(txt) + 6 <= r.width():
                    p.setFont(f_bar)
                    p.setPen(QColor("#1a1a1a" if color.lightness() > 165 else "#ffffff"))
                    p.drawText(QPointF(r.x() + 3, r.y() + r.height() - 2.6), txt)
                p.setPen(QPen(QColor("#e3e6eb"), 0.5))
                p.drawLine(QPointF(x_lab, y + alto_fila), QPointF(self.x1, y + alto_fila))
            self._op(dib)
            self.y += alto_fila
        # leyenda de las locaciones
        con_nombre = [l for l in lugares if l]
        if con_nombre:
            self.y += 6
            self.asegurar(12)
            y = self.y

            def ley(p, y=y):
                x = self.x0
                p.setFont(self.fuente(7.5))
                for l in con_nombre:
                    txt = texto_sin_emoji(l)
                    w = QFontMetricsF(p.font(), p.device()).horizontalAdvance(txt)
                    if x + 12 + w > self.x1:
                        break
                    p.fillRect(QRectF(x, y + 1, 8, 8), QColor(color_de[l]))
                    p.setPen(self.gris)
                    p.drawText(QPointF(x + 11, y + 8.5), txt)
                    x += 11 + w + 14
            self._op(ley)
            self.y += 12
        self.y += 12

    def capitulo(self, titulo: str) -> None:
        """Una sección sin filas es el título de una parte del informe
        (por ejemplo «Análisis por actos» en el informe narrativo)."""
        titulo = texto_sin_emoji(titulo)
        self.asegurar(26 + 18 + 5 + 2 * 12.6)        # junto con lo que sigue
        y = self.y + 4
        f = self.fuente(13, True)

        def cap(p, y=y, titulo=titulo):
            p.setFont(f)
            p.setPen(self.azul)
            p.drawText(QPointF(self.x0, y + 13), titulo)
            p.setPen(QPen(self.azul, 0.8))
            p.drawLine(QPointF(self.x0, y + 18), QPointF(self.x1, y + 18))
        self._op(cap)
        self.y += 30

    def _banda(self, titulo: str, valor: str = "") -> None:
        alto_banda = 18.0
        y = self.y
        f_b, f_v = self.fuente(9.5, True), self.fuente(8.5)

        def banda(p, y=y, titulo=titulo, valor=valor):
            if self.ahorro:
                p.setFont(f_b)
                p.setPen(self.azul)
                p.drawText(QPointF(self.x0, y + 12.5), titulo)
                p.setPen(QPen(self.azul, 0.9))
                p.drawLine(QPointF(self.x0, y + 16.5), QPointF(self.x1, y + 16.5))
            else:
                p.fillRect(QRectF(self.x0, y, self.x1 - self.x0, alto_banda), self.azul)
                p.setFont(f_b)
                p.setPen(QColor("#ffffff"))
                p.drawText(QPointF(self.x0 + 7, y + 12.6), titulo)
            if valor:
                p.setFont(f_v)
                w = QFontMetricsF(f_v, p.device()).horizontalAdvance(valor)
                p.drawText(QPointF(self.x1 - 7 - w, y + 12.4), valor)
        self._op(banda)
        self.y += alto_banda + 5

    # ── tablas (lista de planos, presupuesto, contratos) ──
    # tabla = {"columnas": [{"t": "N°", "w": 4, "al": "c"|"d"|"i"}, …],
    #          "filas": [[celda, …] | {"celdas": […], "estilo": "grupo"|"subtotal"|"total"}]}
    # Una celda es texto, o {"casilla": True/False} (un cuadrito para marcar).
    def _cols_tabla(self, tabla: dict) -> list:
        cols = tabla.get("columnas") or []
        tot = sum(float(c.get("w", 1)) for c in cols) or 1.0
        ancho = self.x1 - self.x0
        out, x = [], self.x0
        for c in cols:
            w = ancho * float(c.get("w", 1)) / tot
            out.append((x, w, c.get("al", "i")))
            x += w
        return out

    @staticmethod
    def _fila_tabla(r) -> tuple:
        if isinstance(r, dict):
            return list(r.get("celdas") or []), r.get("estilo", "")
        return list(r), ""

    def _f_tabla(self, estilo: str) -> QFont:
        return self.fuente(9.5 if estilo == "total" else 8,
                           estilo in ("grupo", "subtotal", "total"))

    def _lineas_celda(self, celda, w: float, f: QFont) -> list:
        if isinstance(celda, dict):
            return [""]
        return self.envolver(texto_sin_emoji(celda if celda is not None else ""), f, max(10.0, w - 6))

    def _alto_fila_tabla(self, tabla: dict, r) -> float:
        celdas, estilo = self._fila_tabla(r)
        f = self._f_tabla(estilo)
        if estilo == "grupo":
            return 15.0
        cols = self._cols_tabla(tabla)
        n = max([len(self._lineas_celda(c, w, f)) for c, (_x, w, _a) in zip(celdas, cols)] or [1])
        return n * (12.0 if estilo == "total" else 10.0) + 5.0

    def tabla(self, tabla: dict) -> None:
        cols = self._cols_tabla(tabla)
        titulos = [texto_sin_emoji(c.get("t", "")) for c in tabla.get("columnas") or []]
        f_cab = self.fuente(7.2, True)

        def cabecera():
            y = self.y

            def dib(p, y=y):
                p.fillRect(QRectF(self.x0, y, self.x1 - self.x0, 14), QColor("#eef1f6"))
                p.setFont(f_cab)
                p.setPen(QColor("#3c4043"))
                fm = QFontMetricsF(f_cab, p.device())
                for (x, w, al), tt in zip(cols, titulos):
                    tt = fm.elidedText(tt.upper(), Qt.TextElideMode.ElideRight, w - 4)
                    tw = fm.horizontalAdvance(tt)
                    xx = x + 3 if al == "i" else (x + w - 3 - tw if al == "d" else x + (w - tw) / 2)
                    p.drawText(QPointF(xx, y + 9.8), tt)
                p.setPen(QPen(self.azul, 0.8))
                p.drawLine(QPointF(self.x0, y + 14), QPointF(self.x1, y + 14))
            self._op(dib)
            self.y += 15

        cabecera()
        par = False
        for r in tabla.get("filas") or []:
            celdas, estilo = self._fila_tabla(r)
            alto = self._alto_fila_tabla(tabla, r)
            pag = len(self.paginas)
            self.asegurar(alto)
            if len(self.paginas) != pag:
                cabecera()
            y = self.y
            f = self._f_tabla(estilo)
            lh = 12.0 if estilo == "total" else 10.0
            if estilo == "grupo":
                par = False
                txt = texto_sin_emoji(" · ".join(str(c) for c in celdas if c))

                def dib(p, y=y, txt=txt):
                    p.fillRect(QRectF(self.x0, y + 1, self.x1 - self.x0, 13),
                               QColor("#f0f0f0" if self.ahorro else "#e6ecf7"))
                    p.setFont(f)
                    p.setPen(self.azul)
                    p.drawText(QPointF(self.x0 + 4, y + 10.6),
                               QFontMetricsF(f, p.device()).elidedText(
                                   txt, Qt.TextElideMode.ElideRight, self.x1 - self.x0 - 8))
                self._op(dib)
                self.y += alto
                continue
            lineas = [self._lineas_celda(c, w, f) for c, (_x, w, _a) in zip(celdas, cols)]
            fondo = par and estilo == ""
            par = not par
            color = self.azul if estilo in ("subtotal", "total") else self.tinta

            def dib(p, y=y, celdas=celdas, lineas=lineas, alto=alto, fondo=fondo, color=color,
                    estilo=estilo, f=f, lh=lh):
                if fondo:
                    p.fillRect(QRectF(self.x0, y, self.x1 - self.x0, alto), QColor("#f7f8fa"))
                if estilo in ("subtotal", "total"):
                    p.setPen(QPen(self.azul, 0.9 if estilo == "total" else 0.5))
                    p.drawLine(QPointF(self.x0, y), QPointF(self.x1, y))
                p.setFont(f)
                fm = QFontMetricsF(f, p.device())
                for c, ls, (x, w, al) in zip(celdas, lineas, cols):
                    if isinstance(c, dict) and "casilla" in c:
                        lado = 7.0
                        r = QRectF(x + (w - lado) / 2, y + 3.2, lado, lado)
                        p.setPen(QPen(QColor("#6b7280"), 0.6))
                        p.setBrush(Qt.BrushStyle.NoBrush)
                        p.drawRect(r)
                        if c["casilla"]:
                            p.setPen(QPen(self.azul, 1.2))
                            p.drawLine(QPointF(r.left() + 1.3, r.center().y()),
                                       QPointF(r.left() + 3, r.bottom() - 1.3))
                            p.drawLine(QPointF(r.left() + 3, r.bottom() - 1.3),
                                       QPointF(r.right() - 1.0, r.top() + 1.2))
                        continue
                    p.setPen(color if not (str(c).strip() in ("—", "-")) else self.gris_claro)
                    for k, ln in enumerate(ls):
                        tw = fm.horizontalAdvance(ln)
                        xx = x + 3 if al == "i" else (x + w - 3 - tw if al == "d" else x + (w - tw) / 2)
                        p.drawText(QPointF(xx, y + 3 + fm.ascent() + k * lh), ln)
                p.setPen(QPen(QColor("#e3e6eb"), 0.5))
                p.drawLine(QPointF(self.x0, y + alto), QPointF(self.x1, y + alto))
            self._op(dib)
            self.y += alto

    def seccion(self, sec: dict) -> None:
        filas = [f for f in (sec.get("filas") or []) if isinstance(f, dict)]
        if not filas and not sec.get("tabla"):
            self.capitulo(sec.get("titulo", ""))
            return
        titulo = texto_sin_emoji(sec.get("titulo", "")).upper()
        alto_banda = 18.0
        tabla = sec.get("tabla")
        if tabla:
            primeras = 16 + sum(self._alto_fila_tabla(tabla, r) for r in (tabla.get("filas") or [])[:2])
        else:
            primeras = sum(self.alto_fila(f) for f in filas[:2])
        self.asegurar(alto_banda + 6 + primeras)
        self._banda(titulo, texto_sin_emoji(sec.get("valor", "") or ""))
        if tabla:
            self.tabla(tabla)
            self.y += 10
            return
        # (un grupo —un personaje, una locación— no se corta entre dos páginas si cabe en una)
        k = 0
        while k < len(filas):
            if filas[k].get("grupo"):
                if k:
                    self.y += 5                       # aire entre grupos
                j = k + 1
                while j < len(filas) and not filas[j].get("grupo"):
                    j += 1
                alto = sum(self.alto_fila(f) for f in filas[k:j])
                if alto <= self.H - self.MS - self.MI - 40:
                    self.asegurar(alto)
            if self._es_foto(filas[k]):
                j = k
                while j < len(filas) and self._es_foto(filas[j]):
                    j += 1
                self._fotos(filas[k:j])
                k = j
                continue
            self.fila(filas[k])
            k += 1
        self.y += 10

    @staticmethod
    def _es_foto(f: dict) -> bool:
        return bool(f.get("foto_bytes") or f.get("foto_base64"))

    # ── filas ──
    def _partes_fila(self, f: dict):
        estilo = estilo_fila_informe(f)
        texto = texto_sin_emoji(f.get("texto", ""))
        valor = texto_sin_emoji(f.get("valor", "") if f.get("valor") is not None else "")
        sang = int(f.get("sangria", 0) or 0)
        if estilo == "subtitulo":
            texto = re.sub(r"^[─—\-=\s]+|[─—\-=\s]+$", "", texto).upper()
            return estilo, texto, valor, self.fuente(7.5, True), self.fuente(7.5, True), 11.5, 5.0, sang
        if estilo == "total":
            return estilo, texto, valor, self.fuente(12.5, True), self.fuente(12.5, True), 17.0, 6.0, 0
        if estilo == "subtotal":
            return estilo, texto, valor, self.fuente(9, True), self.fuente(9, True), 13.0, 1.0, 0
        if estilo == "detalle":
            return estilo, texto, valor, self.fuente(8), self.fuente(8), 10.6, 0.0, max(1, sang)
        if estilo == "parrafo":
            return estilo, texto, valor, self.fuente(8.5), self.fuente(8.5), 11.2, 1.0, max(1, sang)
        neg = bool(f.get("negrita"))
        return "normal", texto, valor, self.fuente(9, neg), self.fuente(9, neg), 12.6, 0.0, sang

    def _cajas(self, f: dict):
        estilo, texto, valor, ft, fv, lh, extra, sang = self._partes_fila(f)
        x_t = self.x0 + 6 + (14.0 * sang if estilo in ("detalle", "subtitulo", "parrafo") else 0)
        if f.get("marca"):
            x_t += 12
        ancho_v = self._fm(fv).horizontalAdvance(valor) + 10 if valor else 0.0
        lineas = self.envolver(texto, ft, max(60.0, self.x1 - 6 - x_t - ancho_v))
        return estilo, lineas, valor, ft, fv, lh, extra, x_t

    def alto_fila(self, f: dict) -> float:
        if self._es_foto(f):
            return 96.0
        estilo, lineas, _v, _ft, _fv, lh, extra, _x = self._cajas(f)
        return extra + lh * len(lineas)

    def fila(self, f: dict) -> None:
        if self._es_foto(f):
            self._fotos([f])
            return
        estilo, lineas, valor, ft, fv, lh, extra, x_t = self._cajas(f)
        alto = extra + lh * len(lineas)
        self.asegurar(alto)
        y = self.y + extra
        if estilo == "total":
            c_t = c_v = self.azul
        elif estilo == "subtotal":
            c_t = c_v = self.azul
        elif estilo == "subtitulo":
            c_t = c_v = self.azul
        elif estilo == "detalle":
            c_t = c_v = self.gris
        elif estilo == "parrafo":
            c_t = c_v = QColor("#3c4043")
        else:
            c_t = c_v = self.tinta
        if valor.strip() in ("—", "-", "–"):
            c_v = self.gris_claro
        asc = self._fm(ft).ascent()

        marca = None if not f.get("marca") else QColor("#555555" if self.ahorro else f["marca"])

        def dibujo(p, y=y, lineas=list(lineas), valor=valor, estilo=estilo, ft=ft, fv=fv, c_t=c_t, c_v=c_v,
                   x_t=x_t, lh=lh, asc=asc, marca=marca):
            if marca is not None:
                p.fillRect(QRectF(x_t - 11, y + asc - 7.5, 8, 8), marca)
            if estilo in ("total", "subtotal"):
                p.setPen(QPen(self.azul, 0.9 if estilo == "total" else 0.5))
                p.drawLine(QPointF(self.x0, y - (3 if estilo == "total" else 1)),
                           QPointF(self.x1, y - (3 if estilo == "total" else 1)))
            p.setFont(ft)
            p.setPen(c_t)
            if estilo == "subtitulo":
                f2 = QFont(ft)
                f2.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, 0.7)
                p.setFont(f2)
            for k, ln in enumerate(lineas):
                p.drawText(QPointF(x_t, y + asc + k * lh), ln)
            if valor:
                p.setFont(fv)
                p.setPen(c_v)
                w = QFontMetricsF(fv, p.device()).horizontalAdvance(valor)
                p.drawText(QPointF(self.x1 - 6 - w, y + asc), valor)
        self._op(dibujo)
        self.y += alto

    def _fotos(self, filas: list) -> None:
        """Fotos en miniatura, una al lado de la otra (de a 4 por fila)."""
        import base64 as _b64
        imgs = []
        for f in filas:
            try:
                img = QImage.fromData(f.get("foto_bytes") or _b64.b64decode(f.get("foto_base64") or ""))
            except Exception:
                img = None
            if img is not None and not img.isNull():
                imgs.append(img)
        x0 = self.x0 + 20
        for i in range(0, len(imgs), 4):
            fila = imgs[i:i + 4]
            medidas = []
            for img in fila:
                h = 86.0
                w = h * img.width() / max(1, img.height())
                if w > 118.0:
                    w, h = 118.0, 118.0 * img.height() / max(1, img.width())
                medidas.append((w, h))
            alto = max(h for _w, h in medidas)
            self.asegurar(alto + 8)
            y, x = self.y + 2, x0
            for img, (w, h) in zip(fila, medidas):
                def dib(p, img=img, x=x, y=y, w=w, h=h):
                    p.drawImage(QRectF(x, y, w, h), img)
                    p.setPen(QPen(QColor("#c9ced6"), 0.6))
                    p.drawRect(QRectF(x, y, w, h))
                self._op(dib)
                x += w + 8
            self.y += alto + 8

    # ── gráficos: barras apiladas al 100 %, de a dos por fila ──
    def graficos(self, graficos: list) -> None:
        validos = [g for g in graficos if sum(max(0, v) for _l, v, _c in g.get("datos") or []) > 0]
        if not validos:
            return
        ancho = (self.x1 - self.x0 - 18) / 2
        f_t, f_l = self.fuente(8.5, True), self.fuente(7.5)
        grises = ["#1a1a1a", "#555555", "#8a8a8a", "#b5b5b5", "#d6d6d6"]
        for i in range(0, len(validos), 2):
            par = validos[i:i + 2]
            alto = 16 + 12 + 6 + 10.5 * max(len(g["datos"]) for g in par) + 8
            self.asegurar(alto)
            y = self.y
            for k, g in enumerate(par):
                x = self.x0 + k * (ancho + 18)
                datos = [(texto_sin_emoji(l), max(0, v), (grises[n % len(grises)] if self.ahorro else c))
                         for n, (l, v, c) in enumerate(g["datos"])]
                total = sum(v for _l, v, _c in datos) or 1

                def dib(p, x=x, y=y, datos=datos, total=total, tit=texto_sin_emoji(g.get("titulo", "")),
                        mon=g.get("moneda")):
                    p.setFont(f_t)
                    p.setPen(self.tinta)
                    p.drawText(QPointF(x, y + 9), tit)
                    xx = x
                    for _l, v, c in datos:
                        w = ancho * v / total
                        if w > 0:
                            p.fillRect(QRectF(xx, y + 15, w, 11), QColor(c))
                            xx += w
                    p.setFont(f_l)
                    for n, (l, v, c) in enumerate(datos):
                        yy = y + 15 + 11 + 6 + n * 10.5
                        p.fillRect(QRectF(x, yy, 7, 7), QColor(c))
                        p.setPen(self.gris)
                        vv = fmt_moneda(v, mon) if mon is not None else v
                        p.drawText(QPointF(x + 11, yy + 6.5), f"{l}: {vv}  ({round(100 * v / total)} %)")
                self._op(dib)
            self.y += alto

    # ── el final: dibujar todo, con «Página n de N» ──
    def _pintar_pagina(self, p: QPainter, i: int) -> None:
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform, True)
        for fn in self.paginas[i]:
            fn(p)
        n = len(self.paginas)
        f_pie = self.fuente(7.5)
        yp = self.H - self.MI + 22
        p.setPen(QPen(QColor("#d5d9df"), 0.6))
        p.drawLine(QPointF(self.x0, yp - 10), QPointF(self.x1, yp - 10))
        p.setFont(f_pie)
        p.setPen(self.gris)
        izq = "¡Acción! Software Audiovisual" + (f" · {self.proyecto}" if self.proyecto else "")
        p.drawText(QPointF(self.x0, yp), izq)
        der = f"Página {i + 1} de {n}"
        p.drawText(QPointF(self.x1 - QFontMetricsF(f_pie, p.device()).horizontalAdvance(der), yp), der)

    def terminar(self) -> int:
        """Escribe el PDF. Devuelve el número de páginas."""
        if not self.paginas:
            self.nueva_pagina(continuacion=False)
        p = QPainter(self.pdf)
        try:
            for i in range(len(self.paginas)):
                if i:
                    self.pdf.newPage()
                self._pintar_pagina(p, i)
        finally:
            p.end()
        return len(self.paginas)

    def imagenes(self, ppp: float = 110.0) -> list:
        """Las páginas como imágenes (para verlas en pantalla o mandarlas
        a la impresora), a `ppp` puntos por pulgada."""
        if not self.paginas:
            self.nueva_pagina(continuacion=False)
        k = ppp / 72.0
        out = []
        for i in range(len(self.paginas)):
            img = QImage(int(self.W * k), int(self.H * k), QImage.Format.Format_RGB32)
            img.setDotsPerMeterX(2835)            # 72 ppp: un punto = un punto
            img.setDotsPerMeterY(2835)
            img.fill(QColor("#ffffff"))
            p = QPainter(img)
            try:
                p.scale(k, k)
                self._pintar_pagina(p, i)
            finally:
                p.end()
            img.setDotsPerMeterX(int(round(ppp / 0.0254)))
            img.setDotsPerMeterY(int(round(ppp / 0.0254)))
            out.append(img)
        return out


def armar_informes(informes: list, ahorro: bool = False, proyecto: str = "",
                   ruta=None, horizontal: bool = False) -> "InformePDF":
    """Arma las páginas de uno o varios informes (dicts con título,
    secciones y filas) con el diseño de ¡Acción!."""
    pdf = InformePDF(ruta, ahorro, proyecto, horizontal)
    for info in informes:
        if info:
            pdf.informe(info)
    return pdf


def info_lista_planos(filas: list, jornada: str = "") -> dict:
    """La lista de planos (filas de VentanaPlanos.filas_exportar) como
    informe: un resumen y, por escena, la tabla de sus planos."""
    cuerpo = filas[1:]
    escenas: dict = {}
    for f in cuerpo:
        escenas.setdefault(f[0], []).append(f)
    hechos = sum(1 for f in cuerpo if f[9])
    seg = sum(segundos_de_duracion(f[7], 0.0) for f in cuerpo if str(f[7] or "").strip())
    res = [{"texto": "Escenas", "valor": str(len(escenas))},
           {"texto": "Planos", "valor": str(len(cuerpo))},
           {"texto": "Planos hechos", "valor": f"{hechos} de {len(cuerpo)}"}]
    if seg > 0:
        res.append({"texto": "Duración anotada", "valor": f"{int(seg // 60)} min {int(round(seg % 60))} s"
                    if seg >= 60 else f"{int(round(seg))} s"})
    if jornada:
        res.insert(0, {"texto": "Jornada", "valor": texto_sin_emoji(jornada), "negrita": True})
    columnas = [{"t": "N°", "w": 4, "al": "c"}, {"t": "Tamaño", "w": 12}, {"t": "Ángulo", "w": 10},
                {"t": "Movimiento", "w": 10}, {"t": "Lente", "w": 6, "al": "c"},
                {"t": "Descripción", "w": 31}, {"t": "Dur.", "w": 6, "al": "c"},
                {"t": "Notas", "w": 16}, {"t": "Hecho", "w": 5, "al": "c"}]
    secciones = [{"titulo": "Resumen", "filas": res}]
    for esc, fs in escenas.items():
        secciones.append({
            "titulo": esc, "valor": re.sub(r"\d{4}-\d{2}-\d{2}", lambda m_: fecha_visible(m_[0]),
                                           texto_sin_emoji(fs[0][10] or "")),
            "tabla": {"columnas": columnas, "filas": [
                [f[1], f[2], f[3], f[4], f[5], f[6], f[7], f[8], {"casilla": bool(f[9])}]
                for f in fs]}})
    return {"titulo": "Lista de planos", "secciones": secciones}


def info_presupuesto(lineas: list, r: dict, moneda: str = "",
                     grupos: Optional[list] = None) -> dict:
    """El presupuesto (ventana Presupuesto) como informe: resumen, totales
    por categoría y el detalle de cada categoría con su subtotal.
    Con `grupos` (grupos_presupuesto_por_fecha), el detalle va por
    fecha de rodaje, con el acumulado para financiar."""
    mon = moneda
    res = [{"texto": "Presupuesto total", "valor": fmt_moneda(r["total"], mon), "negrita": True},
           {"texto": "Pagado", "valor": fmt_moneda(r["pagado"], mon)},
           {"texto": "Por pagar", "valor": fmt_moneda(r["pendiente"], mon)}]
    modo_iva, tasa_iva = r.get("iva_modo", ""), r.get("iva_tasa", 0.0)
    if modo_iva:
        res[0]["texto"] = "Presupuesto total (con IVA)"
        res[1:1] = [{"texto": "Neto", "valor": fmt_moneda(r["neto"], mon), "sangria": 1},
                    {"texto": f"IVA {tasa_iva * 100:g} %", "valor": fmt_moneda(r["iva"], mon), "sangria": 1}]
    if r.get("fondos", 0) > 0:
        res += [{"texto": "Fondos disponibles", "valor": fmt_moneda(r["fondos"], mon)},
                {"texto": "Saldo" if r["saldo"] >= 0 else "Faltan",
                 "valor": fmt_moneda(abs(r["saldo"]), mon), "negrita": True}]
    res.append({"texto": f"{len(lineas)} líneas · " + (
        "valores tal como se escribieron (sin calcular IVA)" if not modo_iva else
        f"valores escritos con el IVA incluido ({tasa_iva * 100:g} %)" if modo_iva == "incluido" else
        f"valores escritos netos; el IVA ({tasa_iva * 100:g} %) se suma aparte"), "sangria": 1})
    secciones = [{"titulo": "Resumen", "filas": res}]
    filas_cat = []
    por_grupo = r.get("por_grupo") or {}

    def fila_cat(nombre, d):
        pct = f"{100 * d['total'] / r['total']:.1f} %" if r["total"] else ""
        return [nombre, str(d["n"]), fmt_moneda(d["total"], mon), fmt_moneda(d["pagado"], mon),
                fmt_moneda(d["total"] - d["pagado"], mon), pct]
    if por_grupo:                                  # 🗂 cada grupo con su subtotal
        for gnom, dg in por_grupo.items():
            filas_cat.append({"celdas": fila_cat(gnom.upper(), dg), "estilo": "subtotal"})
            for cat in dg["categorias"]:
                filas_cat.append(fila_cat(cat, r["por_categoria"][cat]))
    else:
        for cat, d in r["por_categoria"].items():
            filas_cat.append(fila_cat(cat, d))
    filas_cat.append({"celdas": ["TOTAL", str(len(lineas)), fmt_moneda(r["total"], mon),
                                 fmt_moneda(r["pagado"], mon), fmt_moneda(r["pendiente"], mon), ""],
                      "estilo": "total"})
    secciones.append({"titulo": "Por grupo y categoría" if por_grupo else "Por categoría", "tabla": {
        "columnas": [{"t": "Grupo / categoría" if por_grupo else "Categoría", "w": 30}, {"t": "Líneas", "w": 8, "al": "c"},
                     {"t": "Total", "w": 16, "al": "d"}, {"t": "Pagado", "w": 16, "al": "d"},
                     {"t": "Por pagar", "w": 16, "al": "d"}, {"t": "%", "w": 10, "al": "d"}],
        "filas": filas_cat}})
    columnas = [{"t": "Pagado", "w": 6, "al": "c"}, {"t": "Concepto", "w": 24}, {"t": "Detalle", "w": 32},
                {"t": "Total", "w": 13, "al": "d"}, {"t": "Pagado el", "w": 10, "al": "c"},
                {"t": "Notas", "w": 18}]
    if grupos:
        filas_g = []
        for g in grupos:
            con_fecha = g["tipo"] != "s"
            filas_g.append([g["titulo"].lstrip("📅🗂 ").strip(), fmt_moneda(g["total"], mon),
                            fmt_moneda(g["pagado"], mon),
                            fmt_moneda(g["acumulado"], mon) if con_fecha else "—",
                            fmt_moneda(g["pendiente_acumulado"], mon) if con_fecha else "—"])
        secciones.append({"titulo": "Por fecha de rodaje (para financiar)", "tabla": {
            "columnas": [{"t": "Fecha y jornada", "w": 46}, {"t": "Total", "w": 14, "al": "d"},
                         {"t": "Pagado", "w": 13, "al": "d"}, {"t": "Acumulado", "w": 14, "al": "d"},
                         {"t": "Por pagar acum.", "w": 13, "al": "d"}],
            "filas": filas_g}})
        for g in grupos:
            filas = []
            for l, t in g["filas"]:
                filas.append([{"casilla": bool(l["pagado"])}, l["concepto"],
                              _une(t["detalle"], l["aviso"]),
                              fmt_moneda(t["monto"], mon) if t["monto"] else "—",
                              fecha_visible(l["fecha_pago"]) if l["pagado"] and l.get("fecha_pago") else "",
                              l.get("notas", "")])
            filas.append({"celdas": ["", "Subtotal", "", fmt_moneda(g["total"], mon), "", ""],
                          "estilo": "subtotal"})
            secciones.append({"titulo": g["titulo"].lstrip("📅🗂 ").strip(),
                              "valor": fmt_moneda(g["total"], mon),
                              "tabla": {"columnas": columnas, "filas": filas}})
        secciones.append({"titulo": "Total", "filas": [
            {"texto": "TOTAL", "valor": fmt_moneda(r["total"], mon), "estilo": "total"}]})
        return {"titulo": "Presupuesto por fecha de rodaje", "secciones": secciones}
    for cat, d in r["por_categoria"].items():
        filas = []
        for l in lineas:
            if l["categoria"] != cat:
                continue
            filas.append([{"casilla": bool(l["pagado"])}, l["concepto"],
                          _une(l["detalle"], l["aviso"]), fmt_moneda(l["total"], mon) if l["total"] else "—",
                          fecha_visible(l["fecha_pago"]) if l["pagado"] and l.get("fecha_pago") else "",
                          l.get("notas", "")])
        filas.append({"celdas": ["", f"Subtotal {cat.lower()}", "", fmt_moneda(d["total"], mon), "", ""],
                      "estilo": "subtotal"})
        gnom = d.get("grupo", "") if por_grupo else ""
        secciones.append({"titulo": f"{gnom} · {cat}" if gnom else cat,
                          "valor": fmt_moneda(d["total"], mon),
                          "tabla": {"columnas": columnas, "filas": filas}})
    secciones.append({"titulo": "Total", "filas": [
        {"texto": "TOTAL", "valor": fmt_moneda(r["total"], mon), "estilo": "total"}]})
    return {"titulo": "Presupuesto", "secciones": secciones}


def info_contratos(filas_doc: list, rs: dict) -> dict:
    """Contratos y seguros como informe: el resumen y una tabla por grupo
    (proyecto, elenco, locaciones, crew, equipamiento)."""
    res = [{"texto": "Documentos", "valor": str(rs["total"]), "negrita": True},
           {"texto": "Al día", "valor": str(rs["ok"])},
           {"texto": "Pendientes", "valor": str(rs["pend"])},
           {"texto": "Faltan", "valor": str(rs["falta"])},
           {"texto": "Por vencer", "valor": str(rs["pronto"])},
           {"texto": "Vencidos", "valor": str(rs["vencido"])}]
    secciones = [{"titulo": "Resumen", "filas": res}]
    columnas = [{"t": "Estado", "w": 13}, {"t": "Tipo", "w": 15}, {"t": "Documento", "w": 27},
                {"t": "Contraparte", "w": 18}, {"t": "Firma", "w": 9, "al": "c"},
                {"t": "Vence", "w": 9, "al": "c"}, {"t": "Monto", "w": 9, "al": "d"}]
    grupos: dict = {}
    for f in filas_doc:
        grupos.setdefault(f["grupo"], []).append(f)
    for g, fs in grupos.items():
        filas = []
        for f in fs:
            m = parse_precio(f["monto"]) if f["monto"] else 0
            doc_txt = f["titulo"] + (f" (archivo: {f['archivo_nombre']})" if f["tiene_archivo"] else "")
            filas.append([f["estado_vis"], f["tipo"], doc_txt, f["contraparte"],
                          fecha_visible(f["firma"]), fecha_visible(f["vence"]),
                          fmt_moneda(m) if m else ""])
        secciones.append({"titulo": g, "valor": _plural(len(fs), "documento", "documentos"),
                          "tabla": {"columnas": columnas, "filas": filas}})
    return {"titulo": "Contratos y seguros", "secciones": secciones}


def informes_a_pdf(informes: list, ruta, ahorro: bool = False, proyecto: str = "",
                   horizontal: bool = False) -> int:
    """Uno o varios informes (dicts con título, secciones y filas) a un PDF
    con el diseño de ¡Acción!. Devuelve el número de páginas."""
    return armar_informes(informes, ahorro, proyecto, ruta, horizontal).terminar()


def html_a_pdf(ruta, cuerpo_html: str, horizontal: bool = True) -> None:
    """Imprime HTML simple a PDF tamaño Carta (márgenes 12 mm)."""
    from PySide6.QtGui import QPdfWriter
    from PySide6.QtCore import QMarginsF
    qd = QTextDocument()
    qd.setHtml(cuerpo_html)
    pdf = QPdfWriter(str(ruta))
    pdf.setPageSize(QPageSize(QPageSize.PageSizeId.Letter))
    pdf.setPageOrientation(QPageLayout.Orientation.Landscape if horizontal
                           else QPageLayout.Orientation.Portrait)
    pdf.setPageMargins(QMarginsF(12, 12, 12, 12), QPageLayout.Unit.Millimeter)
    qd.print_(pdf)


