from PySide6.QtWidgets import QTableWidgetItem as _QTWI


class _ItemOrdenable(_QTWI):
    """Celda que se ordena por un valor propio (número o fecha ISO)
    al hacer clic en el encabezado, no por el texto mostrado."""

    def __lt__(self, otro):
        a = self.data(Qt.ItemDataRole.UserRole + 1)
        b = otro.data(Qt.ItemDataRole.UserRole + 1)
        if a is not None and b is not None:
            try:
                return a < b
            except TypeError:
                pass
        return super().__lt__(otro)


def _item_tabla(texto: str, orden=None, alinear_derecha: bool = False):
    it = _ItemOrdenable(texto)
    if orden is not None:
        it.setData(Qt.ItemDataRole.UserRole + 1, orden)
    if alinear_derecha:
        it.setTextAlignment(int(Qt.AlignmentFlag.AlignRight
                                | Qt.AlignmentFlag.AlignVCenter))
    return it


class CampoFecha(QWidget):
    """Fecha opcional: se escribe (dd/mm/aaaa) o se elige en el
    calendario 📅. Vacía = sin fecha."""

    def __init__(self, iso: str = "", parent=None):
        super().__init__(parent)
        h = QHBoxLayout(self)
        h.setContentsMargins(0, 0, 0, 0)
        h.setSpacing(px(4))
        self._ed = QLineEdit()
        self._ed.setPlaceholderText("dd/mm/aaaa")
        self._ed.setMaximumWidth(px(130))
        h.addWidget(self._ed)
        btn = QToolButton()
        btn.setText("📅")
        btn.setToolTip("Elegir en el calendario")
        btn.setPopupMode(QToolButton.ToolButtonPopupMode.InstantPopup)
        from PySide6.QtWidgets import QCalendarWidget, QWidgetAction
        menu = QMenu(btn)
        self._cal = QCalendarWidget()
        self._cal.setGridVisible(True)
        acc = QWidgetAction(menu)
        acc.setDefaultWidget(self._cal)
        menu.addAction(acc)
        menu.aboutToShow.connect(self._preparar_calendario)
        self._cal.clicked.connect(
            lambda d: (self.set_iso(d.toString("yyyy-MM-dd")), menu.close()))
        btn.setMenu(menu)
        h.addWidget(btn)
        b_x = QToolButton()
        b_x.setText("✕")
        b_x.setToolTip("Sin fecha")
        b_x.clicked.connect(lambda: self._ed.clear())
        h.addWidget(b_x)
        h.addStretch()
        self.set_iso(iso)

    def _preparar_calendario(self) -> None:
        iso = self.iso()
        d = QDate.fromString(iso, "yyyy-MM-dd") if iso else QDate.currentDate()
        self._cal.setSelectedDate(d)

    def set_iso(self, iso: str) -> None:
        self._ed.setText(fecha_visible(iso) if iso else "")

    def iso(self) -> str:
        return fecha_desde_texto(self._ed.text())

    def texto_invalido(self) -> bool:
        return bool(self._ed.text().strip()) and not self.iso()


