class _RepartoColumnas(QObject):
    """Anchos de columna adaptables: cada columna parte de su ancho
    base; si sobra espacio (pantallas grandes) se reparte entre las
    columnas de texto (concepto, detalle, notas…) en vez de dejarlo
    todo en la última; si falta (pantallas HD) la tabla se desplaza a
    lo ancho y nada se aprieta."""

    def __init__(self, tabla, bases: dict, flexibles: dict):
        super().__init__(tabla)
        self._t, self._bases, self._flex = tabla, bases, flexibles
        tabla.horizontalHeader().setStretchLastSection(False)
        tabla.installEventFilter(self)
        QTimer.singleShot(0, self.repartir)

    def repartir(self) -> None:
        try:
            disponible = self._t.viewport().width()
            base_total = sum(self._bases.values())
            extra = max(0, disponible - base_total)
            peso = sum(self._flex.values()) or 1
            for c, w in self._bases.items():
                self._t.setColumnWidth(
                    c, w + int(extra * self._flex.get(c, 0) / peso))
        except RuntimeError:
            pass

    def eventFilter(self, obj, ev) -> bool:
        if ev.type() in (QEvent.Type.Resize, QEvent.Type.Show):
            QTimer.singleShot(0, self.repartir)
        return False


class _FilaTarjetas(QWidget):
    """Tarjetas de KPI en UNA fila; si la ventana es angosta (pantalla
    HD, Centro de Producción achicado) pasan a DOS filas en vez de
    cortar los textos."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self._g = QGridLayout(self)
        self._g.setContentsMargins(0, 0, 0, 0)
        self._g.setSpacing(px(8))
        self._items: list[QWidget] = []
        self._filas = 0

    def agregar(self, w: QWidget) -> None:
        self._items.append(w)
        self._filas = 0
        self._ordenar(1)

    def _ancho(self, filas: int) -> int:
        if not self._items:
            return 0
        por_fila = -(-len(self._items) // filas)
        esp = self._g.horizontalSpacing()
        anchos = []
        for k in range(0, len(self._items), por_fila):
            grupo = self._items[k:k + por_fila]
            anchos.append(sum(w.sizeHint().width() for w in grupo)
                          + esp * (len(grupo) - 1))
        return max(anchos)

    def _ordenar(self, filas: int) -> None:
        if filas == self._filas:
            return
        self._filas = filas
        for w in self._items:
            self._g.removeWidget(w)
        por_fila = -(-len(self._items) // filas)
        for c in range(len(self._items)):
            self._g.setColumnStretch(c, 1 if c < por_fila else 0)
        for i, w in enumerate(self._items):
            self._g.addWidget(w, i // por_fila, i % por_fila)
        self.updateGeometry()

    def minimumSizeHint(self):
        from PySide6.QtCore import QSize
        return QSize(self._ancho(2), super().minimumSizeHint().height())

    def revisar(self) -> None:
        """Volver a decidir 1 o 2 filas (p. ej. si cambió un monto)."""
        if self.width() > 1:
            self._ordenar(1 if self._ancho(1) <= self.width() else 2)

    def resizeEvent(self, e) -> None:
        super().resizeEvent(e)
        filas = 1 if self._ancho(1) <= self.width() else 2
        if filas != self._filas:
            QTimer.singleShot(0, lambda f=filas: self._ordenar(f))


class _TarjetaFiltro(QFrame):
    """Tarjeta de KPI que también funciona como filtro (clic)."""
