        v.setContentsMargins(px(10), px(6), px(10), px(7))
        v.setSpacing(0)
        t = QLabel(titulo)
        t.setObjectName("pp_kpi_tit")
        self.valor = QLabel("0")
        self.valor.setObjectName("pp_kpi_val")
        v.addWidget(t)
        v.addWidget(self.valor)
