class DialogoCategoriasPresupuesto(QDialog):
    """🗂 Las categorías del presupuesto y sus grupos: crear categorías
    propias (con ícono), cambiarles el nombre o quitarlas, armar grupos
    (Preproducción / Rodaje / Postproducción, sobre y bajo la línea, o
    los que quieras) y ordenarlos, con botones o arrastrando."""

    ROL = Qt.ItemDataRole.UserRole

    def __init__(self, doc, lineas: Optional[list] = None, parent=None, seleccionar: str = ""):
        super().__init__(parent)
        import copy as _copy
        self.doc = doc
        self._lineas = lineas
        self._antes = {k: _copy.deepcopy(getattr(doc, k, None)) for k in (
            "categorias_propias", "grupos_categorias", "categoria_lineas", "gastos", "iva_exentos")}
        self.setWindowTitle("🗂  Categorías y grupos del presupuesto")
        habilitar_snap(self, "🗂")
        v = QVBoxLayout(self)
        v.setContentsMargins(px(18), px(14), px(18), px(12))
        v.setSpacing(px(8))
        tit = QLabel("Tus categorías y cómo se agrupan")
        tit.setStyleSheet("font-size: 13pt; font-weight: 800; color: #ff8c1a;")
        v.addWidget(tit)
        sub = QLabel(
            "Crea las categorías que necesites (Difusión, Viajes, Elenco principal…) y "
            "júntalas en <b>grupos</b>: por etapa (preproducción, rodaje, postproducción), "
            "sobre y bajo la línea, o como te sirva. El presupuesto, el Excel y el PDF "
            "muestran el subtotal de cada grupo. <b>Arrastra</b> para ordenar o cambiar de "
            "grupo. Un gasto se cambia de categoría con clic derecho en el presupuesto.")
        sub.setWordWrap(True)
        sub.setStyleSheet("color: #8fa1b8;")
        v.addWidget(sub)
        cuerpo = QHBoxLayout()
        self._arbol = _ArbolCategorias()
        self._arbol.setColumnCount(2)
        self._arbol.setHeaderLabels(["Grupo / categoría", "En el presupuesto"])
        self._arbol.setRootIsDecorated(True)
        self._arbol.setDragDropMode(QAbstractItemView.DragDropMode.InternalMove)
        self._arbol.setDefaultDropAction(Qt.DropAction.MoveAction)
        self._arbol.setSelectionMode(QAbstractItemView.SelectionMode.SingleSelection)
        self._arbol.header().setStretchLastSection(False)
        self._arbol.header().setSectionResizeMode(0, QHeaderView.ResizeMode.Stretch)
        self._arbol.header().setSectionResizeMode(1, QHeaderView.ResizeMode.ResizeToContents)
        self._arbol.soltado.connect(lambda: QTimer.singleShot(0, self._tras_soltar))
        self._arbol.itemSelectionChanged.connect(self._actualizar_botones)
        self._arbol.itemDoubleClicked.connect(lambda *_: self._editar())
        cuerpo.addWidget(self._arbol, 1)
        col = QVBoxLayout()
        col.setSpacing(px(5))

        def boton(txt, fn, tip=""):
            b = QPushButton(txt)
            b.setToolTip(tip)
            b.clicked.connect(fn)
            col.addWidget(b)
            return b
        self._b_nueva = boton("➕  Nueva categoría…", lambda: self.nueva_categoria(),
                              "Una categoría propia, con su ícono y su grupo")
        self._b_grupo = boton("📁  Nuevo grupo…", lambda: self.nuevo_grupo(),
                              "Por ejemplo: Preproducción, Rodaje, Postproducción")
        self._b_editar = boton("✏  Cambiar nombre…", lambda: self._editar())
        self._b_quitar = boton("🗑  Quitar", lambda: self.quitar())
        col.addSpacing(px(6))
        self._b_subir = boton("↑  Subir", lambda: self.mover(-1))
        self._b_bajar = boton("↓  Bajar", lambda: self.mover(+1))
        col.addSpacing(px(6))
        col.addWidget(QLabel("Grupo de la categoría:"))
        self._cb_grupo = QComboBox()
        self._cb_grupo.setToolTip("Pasa la categoría elegida a otro grupo")
        self._cb_grupo.activated.connect(self._cambio_grupo)
        col.addWidget(self._cb_grupo)
        col.addSpacing(px(6))
        b_ej = QPushButton("✨  Grupos de ejemplo")
        m_ej = QMenu(b_ej)
        for clave, (txt, _p) in GRUPOS_DE_EJEMPLO.items():
            m_ej.addAction(txt, lambda c=clave: self.usar_ejemplo(c))
        m_ej.addSeparator()
        m_ej.addAction("✖  Sin grupos", self.sin_grupos)
        b_ej.setMenu(m_ej)
        col.addWidget(b_ej)
        col.addStretch()
        cuerpo.addLayout(col)
        v.addLayout(cuerpo, 1)
        self._lbl_info = QLabel("")
        self._lbl_info.setWordWrap(True)
        self._lbl_info.setStyleSheet("color: #8fa1b8;")
        v.addWidget(self._lbl_info)
        bb = QDialogButtonBox(QDialogButtonBox.StandardButton.Ok
                              | QDialogButtonBox.StandardButton.Cancel)
        bb.button(QDialogButtonBox.StandardButton.Ok).setText("Guardar")
        bb.button(QDialogButtonBox.StandardButton.Cancel).setText("Cancelar")
        bb.accepted.connect(self.accept)
        bb.rejected.connect(self.reject)
        v.addWidget(bb)
        self.llenar(seleccionar)
        self.resize(*tam_ventana(760, 600))

    # ── el árbol ──
    def _montos(self) -> dict:
        out: dict = {}
        for l in (self._lineas if self._lineas is not None else lineas_presupuesto(self.doc)):
            d = out.setdefault(l["categoria"].casefold(), [0.0, 0])
            d[0] += l["total"]
            d[1] += 1
        return out

    def llenar(self, seleccionar: str = "") -> None:
        """Arma el árbol. `seleccionar`: «cat:Nombre» o «grupo:Nombre»."""
        if not seleccionar:
            seleccionar = self.seleccion()
        self._arbol.clear()
        montos = self._montos()
        grupos = grupos_de_presupuesto(self.doc)
        en_grupo = {c.casefold() for g in grupos for c in g["categorias"]}
        todas = categorias_de_presupuesto(self.doc)
        flags_cat = (Qt.ItemFlag.ItemIsEnabled | Qt.ItemFlag.ItemIsSelectable
                     | Qt.ItemFlag.ItemIsDragEnabled)
        elegido = None

        def item_cat(padre, nombre):
            nonlocal elegido
            ico = icono_categoria(self.doc, nombre)
            propia = es_categoria_propia(nombre)
            tot, n = montos.get(nombre.casefold(), [0.0, 0])
            it = QTreeWidgetItem(padre, [f"{ico}  {nombre}" + ("   (propia)" if propia else ""),
                                         f"{fmt_moneda(tot)} · {n} línea{'s' if n != 1 else ''}"
                                         if n else "—"])
            it.setData(0, self.ROL, ("cat", nombre))
            it.setFlags(flags_cat)
            it.setToolTip(0, "Categoría propia: se puede cambiar o quitar." if propia else
                          "Categoría de siempre: se puede mover a un grupo (no se renombra).")
            if seleccionar == f"cat:{nombre}":
                elegido = it
            return it
        for g in grupos:
            tot = sum(montos.get(c.casefold(), [0.0, 0])[0] for c in g["categorias"])
            ig = QTreeWidgetItem(self._arbol, [f"📁  {g['nombre']}",
                                               fmt_moneda(tot) if tot else "—"])
            ig.setData(0, self.ROL, ("grupo", g["nombre"]))
            ig.setFlags(flags_cat | Qt.ItemFlag.ItemIsDropEnabled)
            f = ig.font(0)
            f.setBold(True)
            ig.setFont(0, f)
            ig.setFont(1, f)
            if seleccionar == f"grupo:{g['nombre']}":
                elegido = ig
            nombres = {c.casefold(): c for c, _ in todas}
            for c in g["categorias"]:
                item_cat(ig, nombres.get(c.casefold(), c))
            ig.setExpanded(True)
        libres = [c for c, _ in todas if c.casefold() not in en_grupo]
        if grupos:
            isg = QTreeWidgetItem(self._arbol, [f"▫  {SIN_GRUPO}", ""])
            isg.setData(0, self.ROL, ("grupo", ""))
            isg.setFlags(Qt.ItemFlag.ItemIsEnabled | Qt.ItemFlag.ItemIsSelectable
                         | Qt.ItemFlag.ItemIsDropEnabled)
            isg.setToolTip(0, "Las categorías que no están en ningún grupo")
            for c in libres:
                item_cat(isg, c)
            isg.setExpanded(True)
        else:
            for c in libres:
                item_cat(self._arbol, c)
        self._arbol.invisibleRootItem().setFlags(Qt.ItemFlag.ItemIsDropEnabled)
        self._cb_grupo.clear()
        self._cb_grupo.addItem(SIN_GRUPO, "")
        for g in grupos:
            self._cb_grupo.addItem(f"📁 {g['nombre']}", g["nombre"])
        self._cb_grupo.addItem("📁 Nuevo grupo…", "__nuevo__")
        if elegido is not None:
            self._arbol.setCurrentItem(elegido)
        self._actualizar_botones()
        propias = sum(1 for c, _ in todas if es_categoria_propia(c))
        self._lbl_info.setText(
            f"{len(todas)} categorías ({propias} propias) · "
            + (f"{len(grupos)} grupo{'s' if len(grupos) != 1 else ''}" if grupos else "sin grupos")
            + ". Las categorías de siempre no se renombran ni se quitan: crea una propia y "
              "mueve ahí lo que quieras.")

    def seleccion(self) -> str:
        it = self._arbol.currentItem()
        if it is None:
            return ""
        tipo, nombre = it.data(0, self.ROL) or ("", "")
        return f"{tipo}:{nombre}" if tipo else ""

    def _actualizar_botones(self) -> None:
        sel = self.seleccion()
        tipo, _, nombre = sel.partition(":")
        es_cat, es_grupo = tipo == "cat", tipo == "grupo" and bool(nombre)
        self._b_editar.setEnabled(es_grupo or (es_cat and es_categoria_propia(nombre)))
        self._b_quitar.setEnabled(es_grupo or (es_cat and es_categoria_propia(nombre)))
        en_grupo = es_cat and bool(grupo_de_categoria(self.doc, nombre))
        self._b_subir.setEnabled(es_grupo or en_grupo)
        self._b_bajar.setEnabled(es_grupo or en_grupo)
        self._cb_grupo.setEnabled(es_cat)
        if es_cat:
            i = self._cb_grupo.findData(grupo_de_categoria(self.doc, nombre))
            self._cb_grupo.setCurrentIndex(max(0, i))

    def _tras_soltar(self) -> None:
        """Lee el árbol después de arrastrar: el orden de los grupos y de
        sus categorías (una categoría suelta afuera queda sin grupo)."""
        gs: list[dict] = []
        actual: Optional[dict] = None

        def recorrer(it, grupo: Optional[dict]) -> None:
            nonlocal actual
            tipo, nombre = it.data(0, self.ROL) or ("", "")
            if tipo == "grupo":
                g = {"nombre": nombre, "categorias": []} if nombre else None
                if g is not None:
                    gs.append(g)
                for k in range(it.childCount()):
                    recorrer(it.child(k), g)
            elif tipo == "cat":
                if grupo is not None:
                    grupo["categorias"].append(nombre)
                for k in range(it.childCount()):       # (algo soltado encima de una categoría)
                    recorrer(it.child(k), grupo)
        for i in range(self._arbol.topLevelItemCount()):
            recorrer(self._arbol.topLevelItem(i), None)
        self.doc.grupos_categorias = gs
        self.doc.grupos_categorias = grupos_de_presupuesto(self.doc)
        self.llenar()

    # ── acciones ──
    def nueva_categoria(self, nombre: str = "", icono: str = "", grupo: Optional[str] = None,
                        pedir: bool = True) -> str:
        if grupo is None:
            tipo, _, n = self.seleccion().partition(":")
            grupo = n if tipo == "grupo" else (grupo_de_categoria(self.doc, n) if tipo == "cat" else "")
        if pedir:
            d = DialogoNuevaCategoria(self.doc, nombre, icono, grupo, parent=self)
            if d.exec() != QDialog.DialogCode.Accepted:
                return ""
            nombre, icono, grupo = d.valores()
        n = crear_categoria_propia(self.doc, nombre, icono)
        if n:
            poner_grupo_de_categoria(self.doc, n, grupo)
            self.llenar(f"cat:{n}")
        return n

    def nuevo_grupo(self, nombre: str = "", pedir: bool = True) -> str:
        if pedir:
            nombre, ok = QInputDialog.getText(self, "Nuevo grupo", "Nombre del grupo:",
                                              text=nombre or "")
            if not ok:
                return ""
        n = crear_grupo_categorias(self.doc, nombre)
        tipo, _, cat = self.seleccion().partition(":")
        if n and tipo == "cat" and pedir:                   # (la categoría elegida pasa a él)
            poner_grupo_de_categoria(self.doc, cat, n)
        if n:
            self.llenar(f"grupo:{n}")
        return n

    def _editar(self) -> None:
        tipo, _, nombre = self.seleccion().partition(":")
        if tipo == "grupo" and nombre:
            nuevo, ok = QInputDialog.getText(self, "Grupo", "Nombre del grupo:", text=nombre)
            if ok:
                self.renombrar_grupo(nombre, nuevo)
        elif tipo == "cat" and es_categoria_propia(nombre):
            d = DialogoNuevaCategoria(self.doc, nombre, icono_categoria(self.doc, nombre),
                                      grupo_de_categoria(self.doc, nombre), parent=self,
                                      titulo="Categoría")
            if d.exec() == QDialog.DialogCode.Accepted:
                n, ico, g = d.valores()
                self.renombrar_categoria(nombre, n, ico, g)

    def renombrar_categoria(self, viejo: str, nuevo: str, icono: str = "",
                            grupo: Optional[str] = None) -> str:
        n = renombrar_categoria_propia(self.doc, viejo, nuevo, icono)
        if n and grupo is not None:
            poner_grupo_de_categoria(self.doc, n, grupo)
        if n:
            self.llenar(f"cat:{n}")
        return n

    def renombrar_grupo(self, viejo: str, nuevo: str) -> str:
        n = renombrar_grupo_categorias(self.doc, viejo, nuevo)
        if n:
            self.llenar(f"grupo:{n}")
        return n

    def quitar(self, confirmar: bool = True) -> bool:
        tipo, _, nombre = self.seleccion().partition(":")
        if tipo == "grupo" and nombre:
            eliminar_grupo_categorias(self.doc, nombre)
            self.llenar()
            return True
        if tipo != "cat" or not es_categoria_propia(nombre):
            return False
        n = self._montos().get(nombre.casefold(), [0.0, 0])[1]
        if confirmar and n:
            r = QMessageBox.question(
                self, "Quitar categoría",
                f"«{nombre}» tiene {n} línea{'s' if n != 1 else ''} del presupuesto. "
                "Si la quitas, vuelven a su categoría de siempre (los gastos a mano, a "
                "«Otros»). No se borra ningún gasto.\n\n¿Quitarla?")
            if r != QMessageBox.StandardButton.Yes:
                return False
        eliminar_categoria_propia(self.doc, nombre)
        self.llenar()
        return True

    def mover(self, delta: int) -> bool:
        tipo, _, nombre = self.seleccion().partition(":")
        ok = mover_en_orden_categorias(self.doc, nombre, delta, es_grupo=(tipo == "grupo"))
        if ok:
            self.llenar(f"{tipo}:{nombre}")
        return ok

    def _cambio_grupo(self, *_) -> None:
        tipo, _, nombre = self.seleccion().partition(":")
        if tipo != "cat":
            return
        g = self._cb_grupo.currentData()
        if g == "__nuevo__":
            self.nuevo_grupo()
            return
        self.poner_grupo(nombre, g or "")

    def poner_grupo(self, cat: str, grupo: str) -> None:
        if grupo:
            crear_grupo_categorias(self.doc, grupo)
        poner_grupo_de_categoria(self.doc, cat, grupo)
        self.llenar(f"cat:{cat}")

    def usar_ejemplo(self, clave: str) -> None:
        aplicar_grupos_de_ejemplo(self.doc, clave)
        self.llenar()

    def sin_grupos(self) -> None:
        self.doc.grupos_categorias = []
        self.llenar()

    def cambio(self) -> bool:
        return any(getattr(self.doc, k, None) != v for k, v in self._antes.items())

    def reject(self) -> None:
        for k, v in self._antes.items():          # (cancelar: todo queda como estaba)
            setattr(self.doc, k, v)
        super().reject()


class VentanaPresupuesto(QDialog):
    """💰 PRESUPUESTO del proyecto: todo lo que se va a gastar y lo que
    ya se gastó, en una sola tabla.

    Las líneas automáticas salen de las fichas (valor por día +
    transporte + alimentación) × días en la Carta Gantt, de los tags
    del guion con valor y de los documentos con monto de «Contratos y
    seguros»; además se agregan gastos a mano (catering, bencina,
    permisos…). Un clic en ✓ marca la línea como PAGADA (con la fecha
    de hoy). Arriba: total, pagado, por pagar, fondos y saldo; abajo,
    el resumen por categoría (que también filtra)."""

    COLS = ["✓", "Categoría", "Concepto", "Detalle", "Total", "Pagado el", "Notas"]
    C_OK, C_CAT, C_CON, C_DET, C_TOT, C_FEC, C_NOT = range(7)

    PLANTILLAS = [
        ("🍽", "Catering de rodaje", "Catering", "jornadas"),
        ("🚐", "Transporte / combustible", "Transporte", "jornadas"),
        ("🏛", "Permiso municipal de filmación", "Permisos", ""),
        ("🛡", "Seguro de rodaje", "Seguros", ""),
        ("💾", "Discos duros / almacenamiento", "Equipamiento", ""),
        ("🎞", "Postproducción (edición, color, sonido)", "Postproducción", ""),
        ("🎵", "Música / derechos", "Música y derechos", ""),
        ("⚠", "Imprevistos (10 % del total)", "Imprevistos", "imprevistos"),
    ]

    def __init__(self, vp, parent=None):
        super().__init__(parent)
        self._vp = vp
        self.doc = vp.editor.documento
        for campo, tipo in (("gastos", list), ("pagos", dict)):
            if not isinstance(getattr(self.doc, campo, None), tipo):
                setattr(self.doc, campo, tipo())
        self.setWindowTitle("💰  Presupuesto")
        habilitar_snap(self, "💰")
        aplicar_qss_tematizado(self, _QSS_PLANIF)
        self._llenando = False
        self._cat_filtro = ""
        self._lineas: list[dict] = []
        self._ultimo_toggle = ("", 0.0)

        v = QVBoxLayout(self)
        v.setContentsMargins(px(14), px(12), px(14), px(10))
        v.setSpacing(px(8))

        # ── KPIs ──
        fila_kpi = self._fila_kpi = _FilaTarjetas()
        self._kpi: dict[str, QLabel] = {}
        for clave, titulo in (("total", "PRESUPUESTO"), ("pagado", "PAGADO ✓"),
                              ("pendiente", "POR PAGAR")):
            lbl = QLabel("—")
            lbl.setObjectName("pp_kpi_val")
            self._kpi[clave] = lbl
            fila_kpi.agregar(_tarjeta_kpi(titulo, lbl))
        self._fondos = QLineEdit(str(getattr(self.doc, "presupuesto_fondos", "") or ""))
        self._fondos.setPlaceholderText("$ fondos")
        self._fondos.setToolTip(
            "Dinero disponible para la producción (fondo concursable, "
            "aporte propio, auspicios…). Se usa para calcular el saldo.")
        self._fondos.setStyleSheet(
            "QLineEdit { font-size: 12pt; font-weight: 800; "
            "padding: 2px 6px; border-radius: 6px; }")
        self._fondos.editingFinished.connect(self._cambio_fondos)
        fila_kpi.agregar(_tarjeta_kpi("FONDOS", self._fondos))
        lbl = QLabel("—")
        lbl.setObjectName("pp_kpi_val")
        self._kpi["saldo"] = lbl
        fila_kpi.agregar(_tarjeta_kpi("SALDO", lbl))
        v.addWidget(fila_kpi)
        self._barra = QProgressBar()
        self._barra.setRange(0, 1000)
        self._barra.setTextVisible(False)
        self._barra.setFixedHeight(px(6))
        self._barra.setStyleSheet(
            "QProgressBar { background: #1a2636; border: none; "
            "border-radius: 3px; } QProgressBar::chunk { "
            "background: #36b46a; border-radius: 3px; }")
        v.addWidget(self._barra)

        # ── Acciones ──
        fila = QHBoxLayout()
        fila.setSpacing(px(6))
        self._btn_add = QPushButton("＋  Agregar gasto")
        self._btn_add.setObjectName("pp_primario")
        menu = QMenu(self._btn_add)
        menu.addAction("✍  Gasto en blanco…", lambda: self._agregar())
        menu.addSeparator()
        for ico, concepto, cat, modo in self.PLANTILLAS:
            menu.addAction(f"{ico}  {concepto}",
                           lambda c=concepto, k=cat, m=modo: self._agregar(c, k, m))
        self._btn_add.setMenu(menu)
        fila.addWidget(self._btn_add)
        self._btn_edit = QPushButton("✏ Editar")
        self._btn_edit.clicked.connect(self._editar)
        self._btn_del = QPushButton("🗑 Quitar")
        self._btn_del.clicked.connect(self._quitar)
        fila.addWidget(self._btn_edit)
        fila.addWidget(self._btn_del)
        self._btn_iva = QPushButton("💲 IVA")
        self._btn_iva.setToolTip(
            "Cómo escribes los valores: sin IVA, con el IVA incluido o netos "
            "con el IVA aparte; la tasa, y lo que no lleva IVA (boletas de "
            "honorarios, exentos)")
        self._btn_iva.clicked.connect(lambda: self.abrir_iva())
        fila.addWidget(self._btn_iva)
        self._btn_cats = QPushButton("🗂 Categorías")
        self._btn_cats.setToolTip(
            "Crea tus propias categorías (con su ícono) y júntalas en grupos: por etapa, "
            "sobre y bajo la línea, o como te sirva")
        self._btn_cats.clicked.connect(lambda: self.abrir_categorias())
        fila.addWidget(self._btn_cats)
        b_ayuda = QToolButton()
        b_ayuda.setText("❓")
        b_ayuda.setToolTip("¿De dónde salen los montos?")
        b_ayuda.clicked.connect(self._ayuda)
        fila.addWidget(b_ayuda)
        fila.addStretch()
        b_exp = QPushButton("⬇ Exportar")
        m_exp = QMenu(b_exp)
        m_exp.addAction("📄  PDF (resumen + detalle)", lambda: self._exportar("pdf"))
        m_exp.addAction("📊  Excel (detalle + resumen)", lambda: self._exportar("xlsx"))
        b_exp.setMenu(m_exp)
        fila.addWidget(b_exp)
        v.addLayout(fila)

        # ── Filtros ──
        fil = QHBoxLayout()
        fil.setSpacing(px(6))
        self._buscar = QLineEdit()
        self._buscar.setPlaceholderText("🔍 Buscar…")
        self._buscar.setClearButtonEnabled(True)
        self._buscar.textChanged.connect(self._llenar_tabla)
        fil.addWidget(self._buscar, 2)
        self._cb_estado = QComboBox()
        for txt, val in (("Todos los gastos", ""), ("⏳ Por pagar", "pend"),
                         ("✓ Pagados", "pag"), ("⚠ Con avisos", "aviso")):
            self._cb_estado.addItem(txt, val)
        self._cb_estado.currentIndexChanged.connect(self._llenar_tabla)
        fil.addWidget(self._cb_estado, 1)
        self._chk_cero = QCheckBox("Ocultar $0")
        self._chk_cero.setToolTip("Oculta las líneas que todavía no tienen monto")
        self._chk_cero.toggled.connect(self._llenar_tabla)
        fil.addWidget(self._chk_cero)
        self._cb_orden = QComboBox()
        for val, txt in ORDENES_PRESUPUESTO:
            self._cb_orden.addItem(txt, val)
        self._cb_orden.setToolTip(
            "📂 Por categoría: elenco, locaciones, crew…\n"
            "🗂 Por grupo y categoría: el subtotal de cada grupo (preproducción, "
            "rodaje…) y de cada categoría. Los grupos se arman en «🗂 Categorías».\n"
            "🎬 Por orden de rodaje: primero lo que se necesita antes, "
            "según la Carta Gantt.\n"
            "📅 Agrupado por fecha de rodaje: cuánto cuesta cada jornada y "
            "el ACUMULADO, para ir financiando a medida que avanzan las "
            "fechas. Lo de varias jornadas (una actriz que graba 3 días) "
            "se reparte en cada una.")
        try:
            i = self._cb_orden.findData(str(settings_app().value(
                "presupuesto/orden", "cat") or "cat"))
        except Exception:
            i = 0
        self._cb_orden.setCurrentIndex(max(0, i))
        self._cb_orden.currentIndexChanged.connect(self._cambio_orden)
        fil.addWidget(self._cb_orden, 1)
        v.addLayout(fil)

        # ── Tabla ──
        from PySide6.QtWidgets import QTableWidget, QHeaderView
        self._tabla = QTableWidget(0, len(self.COLS))
        self._tabla.setHorizontalHeaderLabels(self.COLS)
        self._tabla.verticalHeader().setVisible(False)
        self._tabla.setSelectionBehavior(QTableWidget.SelectionBehavior.SelectRows)
        self._tabla.setSelectionMode(QTableWidget.SelectionMode.SingleSelection)
        self._tabla.setEditTriggers(QTableWidget.EditTrigger.DoubleClicked
                                    | QTableWidget.EditTrigger.EditKeyPressed)
        self._tabla.setWordWrap(False)
        hh = self._tabla.horizontalHeader()
        hh.setMinimumSectionSize(px(30))
        bases = {self.C_OK: px(34), self.C_CAT: px(140), self.C_CON: px(240),
                 self.C_DET: px(220), self.C_TOT: px(110), self.C_FEC: px(92),
                 self.C_NOT: px(150)}
        for c, w in bases.items():
            hh.setSectionResizeMode(c, QHeaderView.ResizeMode.Interactive)
            self._tabla.setColumnWidth(c, w)
        self._reparto = _RepartoColumnas(
            self._tabla, bases, {self.C_CON: 4, self.C_DET: 3, self.C_NOT: 3})
        self._tabla.setColumnWidth(self.C_OK, px(34))
        hh.setSectionResizeMode(self.C_OK, QHeaderView.ResizeMode.Fixed)
        hh.setSortIndicator(-1, Qt.SortOrder.AscendingOrder)
        self._tabla.cellClicked.connect(self._clic_celda)
        self._tabla.cellDoubleClicked.connect(self._doble_clic)
        self._tabla.itemChanged.connect(self._al_editar_celda)
        self._tabla.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        self._tabla.customContextMenuRequested.connect(self._menu_fila)
        self._tabla.itemSelectionChanged.connect(self._actualizar_botones)
        v.addWidget(self._tabla, 1)

        # ── Resumen por categoría (chips que filtran) ──
        self._chips_scroll = QScrollArea()
        self._chips_scroll.setWidgetResizable(True)
        self._chips_scroll.setFrameShape(QFrame.Shape.NoFrame)
        self._chips_scroll.setVerticalScrollBarPolicy(
            Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self._chips_scroll.setFixedHeight(px(46))
        self._chips_w = QWidget()
        self._chips_w.setStyleSheet("background: transparent;")
        self._chips_lay = QHBoxLayout(self._chips_w)
        self._chips_lay.setContentsMargins(0, 0, 0, 0)
        self._chips_lay.setSpacing(px(6))
        self._chips_scroll.setWidget(self._chips_w)
        v.addWidget(self._chips_scroll)
        self._lbl_estado = QLabel("")
        self._lbl_estado.setObjectName("pp_ayuda")
        v.addWidget(self._lbl_estado)

        self.resize(*tam_ventana(1100, 720))
        self.refrescar()
        self._tabla.setFocus()

    # ── Datos ──
    def _marcar(self) -> None:
        if hasattr(self._vp, "_marcar_dirty"):
            self._vp._marcar_dirty()

    def _fondos_valor(self) -> float:
        return parse_precio(str(getattr(self.doc, "presupuesto_fondos", "") or ""))

    def refrescar(self) -> None:
        self._lineas = lineas_presupuesto(self.doc)
        self._actualizar_kpis()
        self._llenar_chips()
        self._llenar_tabla()

    def _actualizar_kpis(self) -> None:
        r = resumen_presupuesto(self._lineas, self._fondos_valor(), config_iva(self.doc),
                                doc=self.doc)
        self._resumen = r
        if r["iva_modo"]:
            pct = f"{r['iva_tasa'] * 100:g} %"
            self._kpi["total"].setText(
                f"{fmt_moneda(r['total'])}<br><span style='font-size:8pt; font-weight:600;'>"
                f"neto {fmt_moneda(r['neto'])} + IVA {fmt_moneda(r['iva'])}</span>")
            self._kpi["total"].setToolTip(
                f"Total a pagar, con IVA ({pct}).\nNeto: {fmt_moneda(r['neto'])}\n"
                f"IVA: {fmt_moneda(r['iva'])}\n"
                + ("Los valores se escribieron con el IVA incluido."
                   if r["iva_modo"] == "incluido" else
                   "Los valores se escribieron netos: el IVA se sumó aparte."))
        else:
            self._kpi["total"].setText(fmt_moneda(r["total"]))
            self._kpi["total"].setToolTip("")
        self._actualizar_boton_iva()
        self._kpi["pagado"].setText(fmt_moneda(r["pagado"]))
        self._kpi["pendiente"].setText(fmt_moneda(r["pendiente"]))
        verde, rojo = _color_tema("#36b46a"), _color_tema("#f87171")
        self._kpi["pagado"].setStyleSheet(f"color: {verde};")
        self._kpi["pendiente"].setStyleSheet(
            f"color: {_color_tema('#ffb43a')};" if r["pendiente"] > 0 else "")
        if r["fondos"] > 0:
            self._kpi["saldo"].setText(fmt_moneda(r["saldo"]))
            self._kpi["saldo"].setStyleSheet(
                f"color: {verde if r['saldo'] >= 0 else rojo};")
            self._kpi["saldo"].setToolTip(
                "Fondos − presupuesto total. En rojo: el presupuesto "
                "supera los fondos disponibles.")
        else:
            self._kpi["saldo"].setText("—")
            self._kpi["saldo"].setStyleSheet("")
            self._kpi["saldo"].setToolTip("Escribe tus fondos disponibles para ver el saldo.")
        self._barra.setValue(int(1000 * r["pagado"] / r["total"]) if r["total"] > 0 else 0)
        self._fila_kpi.revisar()
        self._barra.setToolTip(
            f"{(100 * r['pagado'] / r['total']):.0f} % pagado" if r["total"] > 0 else "")

    def _llenar_chips(self) -> None:
        while self._chips_lay.count():
            it = self._chips_lay.takeAt(0)
            if it.widget():
                it.widget().deleteLater()
        r = self._resumen
        cats = list(r["por_categoria"].items())
        if self._cat_filtro and self._cat_filtro not in r["por_categoria"]:
            self._cat_filtro = ""
        b = QPushButton(f"Todas · {fmt_moneda(r['total'])}")
        b.setObjectName("pp_chip")
        b.setCheckable(True)
        b.setChecked(not self._cat_filtro)
        b.clicked.connect(lambda: self._filtrar_categoria(""))
        self._chips_lay.addWidget(b)
        grupo_ant = None
        for cat, d in cats:
            if r.get("por_grupo") and d.get("grupo") != grupo_ant:     # 🗂 el nombre del grupo
                grupo_ant = d.get("grupo")
                dg = r["por_grupo"].get(grupo_ant, {})
                lg = QLabel(f"📁 {grupo_ant}")
                lg.setObjectName("pp_ayuda")
                lg.setStyleSheet("font-weight: 800; padding-left: 6px;")
                lg.setToolTip(f"Grupo «{grupo_ant}»: {fmt_moneda(dg.get('total', 0))} en "
                              f"{dg.get('n', 0)} línea(s)")
                self._chips_lay.addWidget(lg)
            pct = int(round(100 * d["pagado"] / d["total"])) if d["total"] > 0 else 0
            ico = icono_categoria(self.doc, cat)
            b = QPushButton(f"{ico} {cat} · {fmt_moneda(d['total'])}"
                            + (f" · {pct}% ✓" if d["pagado"] > 0 else ""))
            b.setObjectName("pp_chip")
            b.setCheckable(True)
            b.setChecked(cat == self._cat_filtro)
            b.setToolTip(f"{d['n']} línea(s) · pagado {fmt_moneda(d['pagado'])} "
                         f"· por pagar {fmt_moneda(d['total'] - d['pagado'])}\n"
                         "Clic para ver solo esta categoría.")
            b.clicked.connect(lambda _=False, c=cat: self._filtrar_categoria(c))
            self._chips_lay.addWidget(b)
        self._chips_lay.addStretch()

    def _filtrar_categoria(self, cat: str) -> None:
        self._cat_filtro = "" if cat == self._cat_filtro and cat else cat
        for i in range(self._chips_lay.count()):
            w = self._chips_lay.itemAt(i).widget()
            if isinstance(w, QPushButton):
                es_todas = w.text().startswith("Todas")
                w.setChecked(es_todas if not self._cat_filtro else
                             f" {self._cat_filtro} · " in w.text())
        self._llenar_tabla()

    def lineas_visibles(self) -> list[dict]:
        txt = self._buscar.text().strip().lower()
        est = self._cb_estado.currentData()
        out = []
        for l in self._lineas:
            if self._cat_filtro and l["categoria"] != self._cat_filtro:
                continue
            if est == "pend" and l["pagado"]:
                continue
            if est == "pag" and not l["pagado"]:
                continue
            if est == "aviso" and not l["aviso"]:
                continue
            if self._chk_cero.isChecked() and l["total"] <= 0:
                continue
            if txt and txt not in " ".join(
                    (l["concepto"], l["detalle"], l["proveedor"],
                     l["categoria"], l["notas"])).lower():
                continue
            out.append(l)
        return out

    def orden(self) -> str:
        """«cat», «rodaje» o «fecha» (ver ORDENES_PRESUPUESTO)."""
        return self._cb_orden.currentData() or "cat"

    def poner_orden(self, orden: str) -> None:
        i = self._cb_orden.findData(orden)
        if i >= 0:
            self._cb_orden.setCurrentIndex(i)

    def _cambio_orden(self, *_) -> None:
        try:
            settings_app().setValue("presupuesto/orden", self.orden())
        except Exception:
            pass
        self._llenar_tabla()

    def grupos_por_fecha(self, lineas: Optional[list] = None) -> list[dict]:
        """Los grupos por jornada/fecha de las líneas dadas (por defecto,
        las visibles con los filtros de arriba)."""
        return grupos_presupuesto_por_fecha(
            self.doc, self.lineas_visibles() if lineas is None else lineas)

    def _poner_fila(self, r: int, l: dict, total: Optional[float] = None,
                    detalle: Optional[str] = None, tip_extra: str = "") -> None:
        """Una fila de la tabla para la línea `l` (en la vista por fecha,
        `total` y `detalle` son los de su tramo)."""
        from PySide6.QtWidgets import QTableWidgetItem
        verde = QColor(_color_tema("#36b46a"))
        naranja = QColor(_color_tema("#ffb43a"))
        gris = QColor(_color_tema("#8fa1b8"))
        monto = l["total"] if total is None else total
        ok = QTableWidgetItem("")
        ok.setFlags(Qt.ItemFlag.ItemIsEnabled | Qt.ItemFlag.ItemIsSelectable)
        ok.setCheckState(Qt.CheckState.Checked if l["pagado"]
                         else Qt.CheckState.Unchecked)
        ok.setData(Qt.ItemDataRole.UserRole, l["clave"])
        ok.setData(Qt.ItemDataRole.UserRole + 1, 1 if l["pagado"] else 0)
        ok.setToolTip("Clic para marcar / desmarcar como pagado"
                      + (f"\n(marca todo «{l['concepto']}», en todas sus "
                         "fechas)" if total is not None and abs(monto - l["total"]) > 0.5
                         else ""))
        self._tabla.setItem(r, self.C_OK, ok)
        cat = _item_tabla(f"{icono_categoria(self.doc, l['categoria'])} {l['categoria']}")
        auto = l.get("categoria_auto", l["categoria"])
        cat.setToolTip((f"Movida aquí desde «{auto}». " if auto != l["categoria"] else "")
                       + "Clic derecho → «Mover a la categoría» para cambiarla.")
        con = _item_tabla(l["concepto"])
        origen = {"ficha": "De la ficha (valor por día × días en la Carta Gantt)."
                           "\nDoble clic: abre su ficha para corregirla.",
                  "tag": "Tag del guion con valor.\nDoble clic: abre el tag.",
                  "doc": "Documento de Contratos y seguros con monto."
                         "\nDoble clic: abre el documento.",
                  "manual": "Gasto ingresado a mano.\nDoble clic para editarlo."}
        con.setToolTip(f"{l['concepto']}\n{origen.get(l['origen'], '')}"
                       + (f"\nProveedor: {l['proveedor']}" if l["proveedor"] else "")
                       + (f"\n{tip_extra}" if tip_extra else ""))
        det_txt = (l["detalle"] if detalle is None else detalle) + (
            f"   {l['aviso']}" if l["aviso"] else "")
        det = _item_tabla(det_txt)
        det.setToolTip(det_txt + (f"\n{tip_extra}" if tip_extra else ""))
        if l["aviso"]:
            det.setForeground(QBrush(naranja))
        tot = _item_tabla("🔒" if l["protegido"] and monto <= 0
                          else fmt_moneda(monto), monto, True)
        if l.get("iva", 0) > 0 and monto > 0:
            k = monto / l["total"] if l["total"] else 1.0     # (una parte, en la vista por fecha)
            tot.setToolTip(f"Neto {fmt_moneda(l['neto'] * k)} + IVA {fmt_moneda(l['iva'] * k)}"
                           f" = {fmt_moneda(monto)}")
        elif l.get("exento") and monto > 0:
            tot.setToolTip("Sin IVA (exento o boleta de honorarios). Clic derecho para cambiarlo.")
        fec = _item_tabla(fecha_visible(l["fecha_pago"]) if l["pagado"] else "",
                          l["fecha_pago"] or "")
        fec.setToolTip("Doble clic para cambiar la fecha de pago"
                       if l["pagado"] else "")
        nota = _item_tabla(l["notas"])
        nota.setToolTip("Doble clic para escribir una nota "
                        "(n° de boleta, forma de pago…)")
        for it in (cat, con, det, tot):
            it.setFlags(Qt.ItemFlag.ItemIsEnabled | Qt.ItemFlag.ItemIsSelectable)
        fec.setFlags(Qt.ItemFlag.ItemIsEnabled | Qt.ItemFlag.ItemIsSelectable
                     | (Qt.ItemFlag.ItemIsEditable if l["pagado"]
                        else Qt.ItemFlag.NoItemFlags))
        nota.setFlags(Qt.ItemFlag.ItemIsEnabled | Qt.ItemFlag.ItemIsSelectable
                      | Qt.ItemFlag.ItemIsEditable)
        if l["pagado"]:
            tot.setForeground(QBrush(verde))
            fec.setForeground(QBrush(verde))
            f = tot.font()
            f.setBold(True)
            tot.setFont(f)
        elif monto <= 0:
            tot.setForeground(QBrush(gris))
        if l["origen"] != "manual" and l.get("categoria_auto", l["categoria"]) == l["categoria"]:
            cat.setForeground(QBrush(gris))
        for c, it in ((self.C_CAT, cat), (self.C_CON, con), (self.C_DET, det),
                      (self.C_TOT, tot), (self.C_FEC, fec), (self.C_NOT, nota)):
            self._tabla.setItem(r, c, it)

    def _poner_cabecera(self, r: int, g: dict, total: float, pagado: float,
                        acumulado: float) -> None:
        """La fila de título de una jornada/fecha (vista por fecha)."""
        from PySide6.QtWidgets import QTableWidgetItem
        txt = f"{g['titulo']}   ·   {fmt_moneda(total)}"
        if pagado > 0:
            txt += f"  (pagado {fmt_moneda(pagado)})"
        if g["tipo"] != "s":
            txt += f"   ·   acumulado {fmt_moneda(acumulado)}"
        it = QTableWidgetItem(txt)
        it.setFlags(Qt.ItemFlag.ItemIsEnabled)
        f = it.font()
        f.setBold(True)
        it.setFont(f)
        it.setBackground(QBrush(QColor(_color_tema("#22314a"))))
        it.setForeground(QBrush(QColor(_color_tema("#ffb43a"))))
        it.setData(Qt.ItemDataRole.UserRole + 2, g["clave"])
        it.setToolTip(
            "Lo que cuesta esta fecha de rodaje. El ACUMULADO es todo lo "
            "que hay que tener juntado para llegar hasta aquí."
            if g["tipo"] != "s" else
            "Gastos sin fecha. A un gasto ingresado a mano se le puede dar "
            "fecha (doble clic → ¿Cuándo?); a un contrato o seguro, con su "
            "fecha de firma.")
        self._tabla.setItem(r, self.C_OK, it)
        self._tabla.setSpan(r, 0, 1, len(self.COLS))

    def _poner_titulo(self, r: int, texto: str, total: float, pagado: float, clave: str,
                      nivel: int = 0, n: int = 0) -> None:
        """La fila de título de un grupo (nivel 0) o de una categoría (1),
        con su subtotal (vista por grupo y categoría)."""
        from PySide6.QtWidgets import QTableWidgetItem
        txt = f"{texto}   ·   {fmt_moneda(total)}"
        if pagado > 0:
            txt += f"  (pagado {fmt_moneda(pagado)})"
        if self._resumen.get("total", 0) > 0 and nivel == 0:
            txt += f"   ·   {100 * total / self._resumen['total']:.0f} % del total"
        it = QTableWidgetItem(("" if nivel == 0 else "      ") + txt)
        it.setFlags(Qt.ItemFlag.ItemIsEnabled)
        f = it.font()
        f.setBold(True)
        it.setFont(f)
        it.setBackground(QBrush(QColor(_color_tema("#22314a" if nivel == 0 else "#18233a"))))
        it.setForeground(QBrush(QColor(_color_tema("#ffb43a" if nivel == 0 else "#9cc3ff"))))
        it.setData(Qt.ItemDataRole.UserRole + 2, clave)
        it.setToolTip(f"{'Grupo' if nivel == 0 else 'Categoría'}: {n} línea(s). "
                      "Doble clic: 🗂 Categorías y grupos.")
        self._tabla.setItem(r, self.C_OK, it)
        self._tabla.setSpan(r, 0, 1, len(self.COLS))

    def _llenar_tabla(self, *_):
        self._llenando = True
        sel = self._clave_seleccionada()
        self._tabla.setSortingEnabled(False)
        self._tabla.clearSpans()
        vis = self.lineas_visibles()
        modo = self.orden()
        fila_sel = -1
        self._filas_cabecera: list[int] = []
        if modo == "fecha":
            grupos = self.grupos_por_fecha(vis)
            n_filas = sum(1 + len(g["filas"]) for g in grupos)
            self._tabla.setRowCount(n_filas)
            r = 0
            acum = 0.0
            for g in grupos:
                acum += g["total"]
                self._poner_cabecera(r, g, g["total"], g["pagado"], acum)
                self._filas_cabecera.append(r)
                r += 1
                for l, t in g["filas"]:
                    tip = ""
                    if t["parte"]:
                        tip = (f"Parte de «{l['concepto']}»: en total "
                               f"{fmt_moneda(l['total'])} ({l['detalle']}).")
                    self._poner_fila(r, l, t["monto"], t["detalle"], tip)
                    if l["clave"] == sel and fila_sel < 0:
                        fila_sel = r
                    r += 1
        elif modo == "grupo":
            grupos = presupuesto_por_grupo(self.doc, vis)
            n_filas = sum((1 if g["nombre"] else 0) + sum(1 + len(c["lineas"]) for c in g["categorias"])
                          for g in grupos)
            self._tabla.setRowCount(n_filas)
            r = 0
            for g in grupos:
                if g["nombre"]:
                    self._poner_titulo(r, f"📁  {g['nombre'].upper()}", g["total"], g["pagado"],
                                       f"grupo:{g['nombre'] if g['nombre'] != SIN_GRUPO else ''}",
                                       nivel=0, n=g["n"])
                    self._filas_cabecera.append(r)
                    r += 1
                for c in g["categorias"]:
                    self._poner_titulo(r, f"{c['icono']}  {c['nombre']}", c["total"], c["pagado"],
                                       f"cat:{c['nombre']}", nivel=1, n=len(c["lineas"]))
                    self._filas_cabecera.append(r)
                    r += 1
                    for l in c["lineas"]:
                        self._poner_fila(r, l)
                        if l["clave"] == sel and fila_sel < 0:
                            fila_sel = r
                        r += 1
        else:
            if modo == "rodaje":
                pares = lineas_en_orden_de_rodaje(self.doc, vis)
            else:                                   # (por categoría: en su orden)
                idx = {c.casefold(): i for i, c in enumerate(orden_categorias(self.doc))}
                pares = [(l, "") for l in sorted(
                    vis, key=lambda l: idx.get(l["categoria"].casefold(), len(idx)))]
            self._tabla.setRowCount(len(pares))
            for r, (l, etq) in enumerate(pares):
                self._poner_fila(r, l, None,
                                 (f"{etq} — {l['detalle']}" if etq else None))
                if l["clave"] == sel:
                    fila_sel = r
            self._tabla.setSortingEnabled(modo == "cat")
        if fila_sel >= 0:
            self._tabla.selectRow(fila_sel)
        self._llenando = False
        tot_vis = sum(l["total"] for l in vis)
        pag_vis = sum(l["total"] for l in vis if l["pagado"])
        avisos = self._resumen.get("avisos", 0)
        txt = (f"{len(vis)} de {len(self._lineas)} líneas · mostrado "
               f"{fmt_moneda(tot_vis)} · pagado {fmt_moneda(pag_vis)}")
        if modo == "fecha":
            prox = self.proxima_fecha(vis)
            if prox:
                txt += (f"   ·   📅 Para llegar a la próxima jornada "
                        f"({fecha_visible(prox['fecha'])}) hay que tener "
                        f"{fmt_moneda(prox['acumulado'])} en total; por pagar "
                        f"hasta esa fecha: {fmt_moneda(prox['pendiente_acumulado'])}")
        if avisos:
            txt += f"   ·   ⚠ {avisos} línea(s) con avisos (falta precio o días)"
        self._lbl_estado.setText(txt)
        self._actualizar_botones()

    def proxima_fecha(self, lineas: Optional[list] = None,
                      hoy: Optional[date] = None) -> Optional[dict]:
        """El primer grupo con fecha de hoy en adelante (para financiar:
        cuánto hay que tener juntado para llegar a esa fecha)."""
        hoy = hoy or date.today()
        for g in self.grupos_por_fecha(lineas):
            d = _fecha_iso(g["fecha"])
            if g["tipo"] != "s" and d and d >= hoy:
                return g
        return None

    # ── Selección ──
    def _clave_de_fila(self, r: int) -> str:
        it = self._tabla.item(r, self.C_OK)
        return (it.data(Qt.ItemDataRole.UserRole) or "") if it else ""

    def _clave_seleccionada(self) -> str:
        r = self._tabla.currentRow()
        return self._clave_de_fila(r) if r >= 0 else ""

    def _linea(self, clave: str) -> Optional[dict]:
        return next((l for l in self._lineas if l["clave"] == clave), None)

    def _actualizar_botones(self) -> None:
        l = self._linea(self._clave_seleccionada())
        manual = bool(l and l["origen"] == "manual")
        self._btn_edit.setEnabled(manual)
        self._btn_del.setEnabled(manual)

    # ── ✓ Pagado con UN clic ──
    def _clic_celda(self, r: int, c: int) -> None:
        if c != self.C_OK:
            return
        clave = self._clave_de_fila(r)
        l = self._linea(clave)
        if l is None:
            return
        self.alternar_pago(clave)

    def alternar_pago(self, clave: str) -> None:
        l = self._linea(clave)
        if l is None:
            return
        import time as _t
        ahora = _t.monotonic()
        # Un doble clic rápido sobre ✓ no debe marcar y desmarcar.
        ultimo, cuando = self._ultimo_toggle
        if ultimo == clave and ahora - cuando < 0.35:
            return
        self._ultimo_toggle = (clave, ahora)
        marcar_pago(self.doc, clave, not l["pagado"])
        self._marcar()
        self.refrescar()

    def _doble_clic(self, r: int, c: int) -> None:
        it0 = self._tabla.item(r, self.C_OK)
        cab = str(it0.data(Qt.ItemDataRole.UserRole + 2) or "") if it0 is not None else ""
        if cab.startswith(("cat:", "grupo:")):            # (título de grupo o categoría)
            self.abrir_categorias(seleccionar=cab)
            return
        if c in (self.C_OK, self.C_NOT, self.C_FEC):
            return
        clave = self._clave_de_fila(r)
        if clave:
            self.abrir_origen(clave)

    # Lo que le falta a una ficha, según el aviso de su línea
    _CAMPO_PRECIO = {"actor": "actor_valor_dia", "locacion": "precio_dia",
                     "tecnico": "precio_dia", "equipamiento": "precio_dia"}
    _TIPO_VISTA = {"actor": "personaje", "locacion": "locacion",
                   "tecnico": "tecnico", "equipamiento": "equipamiento"}

    def abrir_origen(self, clave: str, modal: bool = True):
        """Doble clic en una línea: abre lo que la produce para corregirlo
        (la ficha con su valor por día, el tag, el documento o el gasto),
        y al volver el presupuesto se recalcula solo.
        Con modal=False devuelve el diálogo sin abrirlo (para pruebas)."""
        l = self._linea(clave)
        if l is None:
            return None
        if l["origen"] == "manual":
            self._seleccionar(clave)
            return self._editar(modal=modal)
        if l["origen"] == "ficha":
            return self._abrir_ficha(l, modal)
        if l["origen"] == "tag":
            return self._abrir_tag(l, modal)
        if l["origen"] == "doc":
            return self._abrir_documento(l, modal)
        return None

    def _abrir_ficha(self, l: dict, modal: bool = True):
        kind, _, nombre = l["clave"].partition(":")
        dlg, _titulo = construir_vista_ficha(
            self._vp, self.doc, self._TIPO_VISTA.get(kind, ""), nombre,
            parent=self)
        if dlg is None:
            return None
        seleccionar_en_vista_ficha(dlg, nombre)
        if "falta el valor" in l["aviso"]:
            aviso = "💰 Falta el valor por día: escríbelo aquí."
        elif "sin días" in l["aviso"]:
            aviso = ("📅 Esta ficha no está en ninguna jornada con fecha: "
                     "agrégala en la Carta Gantt para que se cuenten sus días.")
        else:
            aviso = ""
        campo = self._CAMPO_PRECIO.get(kind, "precio_dia")
        QTimer.singleShot(250, lambda: enfocar_campo_ficha(dlg, campo, aviso))
        dlg._presupuesto_aviso = aviso
        if not modal:
            return dlg
        dlg.exec()
        self._despues_de_ficha(dlg, l)
        return dlg

    def _despues_de_ficha(self, dlg, l: dict) -> None:
        guardar_vista_ficha(dlg)
        self._marcar()
        antes = l["total"]
        self.refrescar()
        self._seleccionar(l["clave"])
        nueva = self._linea(l["clave"])
        txt = f"✅ Ficha de «{l['concepto']}» guardada"
        if nueva is not None and abs(nueva["total"] - antes) > 0.5:
            txt += (f": ahora suma {fmt_moneda(nueva['total'])} "
                    f"(antes {fmt_moneda(antes)})")
        avisar_guardado(self, txt + ".")

    def _abrir_tag(self, l: dict, modal: bool = True):
        try:
            ib, it = (int(x) for x in str(l.get("ref", "")).split(":"))
            tag = self.doc.bloques[ib].tags[it]
        except (ValueError, IndexError, AttributeError, TypeError):
            QMessageBox.information(
                self, "Presupuesto",
                "No encontré ese tag en el guion. Ábrelo en Tags → desglose.")
            return None
        dlg = DialogoEditarTag(tag, parent=self)
        if not modal:
            return dlg
        if dlg.exec() == QDialog.DialogCode.Accepted:
            self._marcar()
            try:
                self._vp.editor.estructura_cambiada.emit()
            except Exception:
                pass
            self.refrescar()
            self._seleccionar(l["clave"])
            avisar_guardado(self, f"✅ Tag «{l['concepto'].strip()}» guardado.")
        return dlg

    def _abrir_documento(self, l: dict, modal: bool = True):
        d = next((x for x in getattr(self.doc, "documentos_legales", []) or []
                  if x.get("id", "") == l.get("ref", "")), None)
        if d is None:
            return None
        dlg = DialogoDocumentoLegal(self.doc, d, "proyecto", parent=self)
        if not modal:
            return dlg
        if dlg.exec() == QDialog.DialogCode.Accepted:
            d.update({k: dlg.datos.get(k, "") for k in (
                "vinculo", "tipo", "titulo", "contraparte", "estado", "firma",
                "vence", "monto", "archivo_nombre", "archivo_datos", "notas")})
            self._marcar()
            self.refrescar()
            self._seleccionar(l["clave"])
            avisar_guardado(self, f"✅ Documento «{l['concepto']}» guardado.")
        return dlg

    def _al_editar_celda(self, item) -> None:
        if self._llenando:
            return
        r, c = item.row(), item.column()
        clave = self._clave_de_fila(r)
        if not clave:
            return
        if c == self.C_NOT:
            nota_pago(self.doc, clave, notas=item.text().strip())
            self._marcar()
            l = self._linea(clave)
            if l:
                l["notas"] = item.text().strip()
            if self.orden() == "fecha":       # (la misma línea, en otras fechas)
                QTimer.singleShot(0, self._llenar_tabla)
        elif c == self.C_FEC:
            iso = fecha_desde_texto(item.text())
            if iso:
                nota_pago(self.doc, clave, fecha=iso)
                self._marcar()
            QTimer.singleShot(0, self.refrescar)

    # ── Gastos manuales ──
    def _gasto(self, gid: str) -> Optional[dict]:
        return next((g for g in self.doc.gastos if g.get("id") == gid), None)

    def _agregar(self, concepto: str = "", categoria: str = "Otros",
                 modo: str = "") -> None:
        g = {"categoria": categoria, "concepto": concepto, "cantidad": "1",
             "valor": ""}
        if modo == "jornadas":
            dias = sum(dias_de_jornada(j) for j in self.doc.jornadas or [])
            if dias:
                g["cantidad"] = str(dias)
            if self.doc.jornadas:
                g["cuando"] = "jornadas"
        elif modo == "imprevistos":
            base = sum(l["total"] for l in self._lineas
                       if l["categoria"] != "Imprevistos")
            g["valor"] = str(int(round(base * 0.10)))
        dlg = DialogoGasto(g, parent=self, titulo="Nuevo gasto", doc=self.doc)
        if dlg.exec() != QDialog.DialogCode.Accepted:
            return
        self.doc.gastos.append(dlg.gasto)
        clave = f"gasto:{dlg.gasto['id']}"
        if dlg.pagado():
            marcar_pago(self.doc, clave, True)
        if dlg.notas():
            nota_pago(self.doc, clave, notas=dlg.notas())
        self._marcar()
        self.refrescar()
        self._seleccionar(clave)

    def _seleccionar(self, clave: str) -> None:
        for r in range(self._tabla.rowCount()):
            if self._clave_de_fila(r) == clave:
                self._tabla.selectRow(r)
                self._tabla.scrollToItem(self._tabla.item(r, 0))
                return

    def _editar(self, *_, modal: bool = True):
        l = self._linea(self._clave_seleccionada())
        if not l or l["origen"] != "manual":
            return None
        g = self._gasto(l["ref"])
        if g is None:
            return None
        dlg = DialogoGasto(g, l["pagado"], l["notas"], parent=self,
                           titulo="Editar gasto", doc=self.doc)
        if not modal:
            return dlg
        if dlg.exec() != QDialog.DialogCode.Accepted:
            return dlg
        g.clear()
        g.update(dlg.gasto)
        clave = l["clave"]
        if dlg.pagado() != l["pagado"]:
            marcar_pago(self.doc, clave, dlg.pagado())
        nota_pago(self.doc, clave, notas=dlg.notas())
        self._marcar()
        self.refrescar()
        self._seleccionar(clave)
        avisar_guardado(self, f"✅ Gasto «{g.get('concepto', '')}» guardado.")
        return dlg

    def _quitar(self) -> None:
        l = self._linea(self._clave_seleccionada())
        if not l or l["origen"] != "manual":
            return
        r = QMessageBox.question(
            self, "Quitar gasto", f"¿Quitar «{l['concepto']}» del presupuesto?",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No)
        if r != QMessageBox.StandardButton.Yes:
            return
        self.doc.gastos = [g for g in self.doc.gastos if g.get("id") != l["ref"]]
        self.doc.pagos.pop(l["clave"], None)
        self._marcar()
        self.refrescar()

    def _guardar_actual(self) -> None:
        """Lo llama el Centro de Producción al volver a la grilla."""
        self._cambio_fondos()

    def _cambio_fondos(self) -> None:
        txt = self._fondos.text().strip()
        v = parse_precio(txt)
        nuevo = fmt_moneda(v) if v > 0 else ""
        if nuevo != (getattr(self.doc, "presupuesto_fondos", "") or ""):
            self.doc.presupuesto_fondos = nuevo
            self._marcar()
        self._fondos.setText(nuevo)
        self._actualizar_kpis()

    def _ayuda(self) -> None:
        QMessageBox.information(
            self, "¿De dónde salen los montos?",
            "<b>Automático</b> (se actualiza solo):<br>"
            "• 🎭 Elenco, 📍 Locaciones, 🔧 Crew y 🎥 Equipamiento: "
            "<i>valor por día + transporte + alimentación</i> de cada "
            "ficha × los <b>días que aparece en la Carta Gantt</b>.<br>"
            "• 🏷 Tags del guion con valor (utilería, vestuario, "
            "vehículos…), según su tipo de compra.<br>"
            "• 📜 Documentos de <b>Contratos y seguros</b> con monto "
            "(seguros, permisos, catering…).<br><br>"
            "<b>A mano</b>: «＋ Agregar gasto» (bencina, catering, "
            "imprevistos…).<br><br>"
            "Haz <b>un clic en ✓</b> para marcar un gasto como pagado "
            "(queda con la fecha de hoy; doble clic en la fecha para "
            "cambiarla). Doble clic en <b>Notas</b> para anotar el n° "
            "de boleta o la forma de pago.<br><br>"
            "<b>Doble clic en un gasto</b> abre lo que lo produce para "
            "corregirlo: la <b>ficha</b> (con el cursor en el valor por "
            "día, si falta), el tag, el documento o el gasto a mano. Al "
            "cerrarla, el presupuesto se recalcula solo.<br><br>"
            "<b>Ver:</b> 📂 por categoría, 🎬 por orden de rodaje (primero "
            "lo que se necesita antes) o 📅 <b>agrupado por fecha de "
            "rodaje</b>: cada jornada con lo que cuesta y el "
            "<b>acumulado</b>, para ir financiando a medida que avanzan las "
            "fechas. Lo que está en varias jornadas se reparte según sus "
            "días; a un gasto a mano se le da fecha en «¿Cuándo?».<br><br>"
            "<b>💲 IVA:</b> elige cómo escribes los valores: sin IVA (se suman "
            "tal cual), <b>con el IVA incluido</b> (lo que pagas) o <b>netos</b> "
            "(el IVA se suma aparte). Lo que no lleva IVA (boletas de "
            "honorarios, exentos): categorías completas en «💲 IVA», o un "
            "gasto suelto con clic derecho → «Sin IVA».<br><br>"
            "<b>🗂 Categorías:</b> crea las tuyas (con ícono) y júntalas en "
            "<b>grupos</b> (por etapa, sobre y bajo la línea…). Clic derecho en "
            "un gasto → «Mover a la categoría». La vista «🗂 Por grupo y "
            "categoría» muestra el subtotal de cada uno.")

    # ── 💲 IVA ──
    def _actualizar_boton_iva(self) -> None:
        modo, tasa = config_iva(self.doc)
        pct = f"{tasa * 100:g} %"
        self._btn_iva.setText({"incluido": f"💲 IVA {pct} incluido",
                               "aparte": f"💲 Netos + IVA {pct}"}.get(modo, "💲 IVA: no"))
        it = self._tabla.horizontalHeaderItem(self.C_TOT)
        if it is not None:
            it.setText("Total c/IVA" if modo else "Total")

    def abrir_iva(self, modal: bool = True):
        """💲 Cómo se escriben los valores (sin IVA, incluido o aparte)."""
        dlg = DialogoIVA(self.doc, parent=self)
        if not modal:
            return dlg
        antes = (self.doc.iva_modo, self.doc.iva_tasa, list(self.doc.iva_exentos or []))
        if dlg.exec() == QDialog.DialogCode.Accepted:
            if (self.doc.iva_modo, self.doc.iva_tasa, list(self.doc.iva_exentos or [])) != antes:
                self._marcar()
            self.refrescar()
            avisar_guardado(self, f"✅ IVA: {self._btn_iva.text().replace('💲 ', '')}.")
        return dlg

    # ── 🗂 Categorías propias y grupos ──
    def abrir_categorias(self, modal: bool = True, seleccionar: str = ""):
        """🗂 Crear categorías, armar grupos y ordenarlos."""
        dlg = DialogoCategoriasPresupuesto(self.doc, self._lineas, parent=self,
                                           seleccionar=seleccionar)
        if not modal:
            return dlg
        if dlg.exec() == QDialog.DialogCode.Accepted:
            self.tras_categorias(dlg)
        return dlg

    def tras_categorias(self, dlg) -> None:
        if dlg.cambio():
            self._marcar()
        if grupos_de_presupuesto(self.doc) and self.orden() == "cat":
            self.poner_orden("grupo")                  # (para ver los grupos con su subtotal)
        self.refrescar()

    def mover_a_categoria(self, clave: str, cat: str) -> str:
        """Pasa una línea a otra categoría (una de siempre, propia o nueva)."""
        l = self._linea(clave)
        if l is None or not _nombre_cat(cat):
            return ""
        n = mover_linea_a_categoria(self.doc, l, cat)
        self._marcar()
        self.refrescar()
        self._seleccionar(clave)
        avisar_guardado(self, f"🏷 «{texto_sin_emoji(l['concepto']).strip()}» → {n}")
        return n

    def nueva_categoria_para(self, clave: str, nombre: str = "", icono: str = "",
                             grupo: Optional[str] = None, pedir: bool = True) -> str:
        """➕ Una categoría nueva y la línea pasa a ella."""
        l = self._linea(clave)
        if l is None:
            return ""
        if pedir:
            d = DialogoNuevaCategoria(self.doc, nombre, icono,
                                      grupo if grupo is not None
                                      else grupo_de_categoria(self.doc, l["categoria"]), parent=self)
            if d.exec() != QDialog.DialogCode.Accepted:
                return ""
            nombre, icono, grupo = d.valores()
        n = crear_categoria_propia(self.doc, nombre, icono)
        if not n:
            return ""
        if grupo is not None:
            poner_grupo_de_categoria(self.doc, n, grupo)
        return self.mover_a_categoria(clave, n)

    def poner_exento(self, clave: str, exento: bool) -> None:
        l = self._linea(clave)
        if l is None:
            return
        if l["origen"] == "manual":
            g = self._gasto(l["ref"])
            if g is not None:
                if exento:
                    g["sin_iva"] = True
                else:
                    g.pop("sin_iva", None)
            if not exento:
                poner_exento_iva(self.doc, clave, l["categoria"], False)
        else:
            poner_exento_iva(self.doc, clave, l["categoria"], exento)
        self._marcar()
        self.refrescar()
        self._seleccionar(clave)

    def _menu_fila(self, pos) -> None:
        r = self._tabla.rowAt(pos.y())
        clave = self._clave_de_fila(r) if r >= 0 else ""
        l = self._linea(clave)
        if l is None:
            return
        self._seleccionar(clave)
        m = QMenu(self)
        a_abrir = m.addAction("✏  Abrir para corregir (doble clic)")
        a_pago = m.addAction("✓  Pagado" if not l["pagado"] else "↶  Marcar como no pagado")
        m.addSeparator()
        modo, _t = config_iva(self.doc)
        a_iva = m.addAction("Sin IVA (exento / boleta de honorarios)")
        a_iva.setCheckable(True)
        a_iva.setChecked(bool(l.get("exento")))
        a_iva.setEnabled(bool(modo))
        if not modo:
            a_iva.setText("Sin IVA (primero activa el IVA en «💲 IVA»)")
        a_cat = m.addAction(f"Toda la categoría «{l['categoria']}» sin IVA…")
        a_cat.setEnabled(bool(modo))
        a_cfg = m.addAction("💲  IVA del presupuesto…")
        m.addSeparator()
        m_mover = m.addMenu("🏷  Mover a la categoría")
        acc_cat = {}
        grupo_ant = None
        for cat in orden_categorias(self.doc):
            g = grupo_de_categoria(self.doc, cat) if self._resumen.get("por_grupo") else None
            if g != grupo_ant:
                grupo_ant = g
                m_mover.addSection(g or SIN_GRUPO)
            a = m_mover.addAction(f"{icono_categoria(self.doc, cat)}  {cat}")
            a.setCheckable(True)
            a.setChecked(cat == l["categoria"])
            acc_cat[a] = cat
        auto = l.get("categoria_auto", l["categoria"])
        a_volver = None
        if auto != l["categoria"]:
            m_mover.addSeparator()
            a_volver = m_mover.addAction(f"↶  Volver a «{auto}»")
        m_mover.addSeparator()
        a_nueva = m_mover.addAction("➕  Nueva categoría…")
        a_admin = m.addAction("🗂  Categorías y grupos…")
        elegida = m.exec(self._tabla.viewport().mapToGlobal(pos))
        if elegida in acc_cat:
            self.mover_a_categoria(clave, acc_cat[elegida])
        elif elegida is not None and elegida is a_volver:
            self.mover_a_categoria(clave, auto)
        elif elegida is a_nueva:
            self.nueva_categoria_para(clave)
        elif elegida is a_admin:
            self.abrir_categorias(seleccionar=f"cat:{l['categoria']}")
        elif elegida is a_abrir:
            self.abrir_origen(clave)
        elif elegida is a_pago:
            self.alternar_pago(clave)
        elif elegida is a_iva:
            self.poner_exento(clave, a_iva.isChecked())
        elif elegida in (a_cat, a_cfg):
            self.abrir_iva()

    # ── Exportar ──
    def filas_excel(self) -> tuple[list, list, set, set]:
        modo, tasa = config_iva(self.doc)
        con_iva = bool(modo)
        det = [["Categoría", "Concepto", "Detalle", "Proveedor", "Cantidad",
                "Valor unitario"] + (["Neto", f"IVA {tasa * 100:g} %", "Total c/IVA"] if con_iva
                                     else ["Total"]) + ["Pagado", "Fecha de pago", "Notas"]]
        r = resumen_presupuesto(self._lineas, self._fondos_valor(), (modo, tasa), doc=self.doc)
        con_grupos = bool(r.get("por_grupo"))
        if con_grupos:                                   # 🗂 el grupo, primera columna
            det[0].insert(0, "Grupo")
        neg_det: set = set()
        for g in presupuesto_por_grupo(self.doc, self._lineas):
            for c in g["categorias"]:
                for l in c["lineas"]:
                    det.append(([g["nombre"]] if con_grupos else [])
                               + [l["categoria"], l["concepto"],
                                  (l["detalle"] + (f" — {l['aviso']}" if l["aviso"] else "")),
                                  l["proveedor"], l["cantidad"], round(l["unitario"])]
                               + ([round(l["neto"]), round(l["iva"]), round(l["total"])] if con_iva
                                  else [round(l["total"])])
                               + ["✓" if l["pagado"] else "",
                                  fecha_visible(l["fecha_pago"]) if l["pagado"] else "",
                                  l["notas"]])
        det.append((["TOTAL", ""] if con_grupos else ["TOTAL"]) + ["", "", "", "", ""]
                   + ([round(r["neto"]), round(r["iva"]), round(r["total"])] if con_iva
                      else [round(r["total"])])
                   + ["", "", f"Pagado {fmt_moneda(r['pagado'])}"])
        neg_det.add(len(det) - 1)
        res = [["Categoría", "Líneas", "Total", "Pagado", "Por pagar", "% del total"]]
        neg_res: set = set()

        def fila_res(nombre, d):
            return [nombre, d["n"], round(d["total"]), round(d["pagado"]),
                    round(d["total"] - d["pagado"]),
                    f"{(100 * d['total'] / r['total']):.1f} %" if r["total"] else ""]
        if con_grupos:
            res[0][0] = "Grupo / categoría"
            for gnom, dg in r["por_grupo"].items():
                res.append(fila_res(f"📁 {gnom}", dg))
                neg_res.add(len(res) - 1)
                for cat in dg["categorias"]:
                    res.append(fila_res(f"   {cat}", r["por_categoria"][cat]))
        else:
            for cat, d in r["por_categoria"].items():
                res.append(fila_res(cat, d))
        res.append(["TOTAL", len(self._lineas), round(r["total"]), round(r["pagado"]),
                    round(r["pendiente"]), "100 %" if r["total"] else ""])
        neg_res.add(len(res) - 1)
        if con_iva:
            res.append(["   Neto", "", round(r["neto"]), "", "", ""])
            res.append([f"   IVA {tasa * 100:g} % ("
                        + ("incluido en los valores)" if modo == "incluido" else "sumado aparte)"),
                        "", round(r["iva"]), "", "", ""])
        if r["fondos"] > 0:
            res.append(["Fondos disponibles", "", round(r["fondos"]), "", "", ""])
            res.append(["Saldo (fondos − total)", "", round(r["saldo"]), "", "", ""])
            neg_res |= {len(res) - 1}
        return det, res, neg_det, neg_res

    def filas_por_fecha(self) -> tuple[list, set]:
        """La hoja «Por fecha de rodaje»: cada jornada con sus gastos, su
        subtotal y el acumulado (para financiar por fechas)."""
        filas = [["Fecha", "Jornada / gasto", "Categoría", "Detalle",
                  "Monto", "Pagado", "Acumulado", "Por pagar acumulado"]]
        negrita: set = set()
        for g in grupos_presupuesto_por_fecha(self.doc, self._lineas):
            d = _fecha_iso(g["fecha"])
            nombre = (nombre_jornada(self.doc, g["jornada"]) if g["tipo"] == "j"
                      else "Otros gastos de ese día" if g["tipo"] == "f"
                      else "Sin fecha (antes o después del rodaje)")
            filas.append([fecha_visible(g["fecha"]) if d else "", nombre, "", "",
                          round(g["total"]), round(g["pagado"]),
                          round(g["acumulado"]) if g["tipo"] != "s" else "",
                          round(g["pendiente_acumulado"]) if g["tipo"] != "s" else ""])
            negrita.add(len(filas) - 1)
            for l, t in g["filas"]:
                filas.append(["", "   " + l["concepto"], l["categoria"],
                              t["detalle"] + (f" — {l['aviso']}" if l["aviso"] else ""),
                              round(t["monto"]), "✓" if l["pagado"] else "", "", ""])
        return filas, negrita

    def _exportar(self, fmt: str) -> None:
        if not self._lineas:
            QMessageBox.information(self, "Presupuesto", "Todavía no hay gastos.")
            return
        base = (getattr(self.doc, "titulo", "") or "guion").strip() or "guion"
        sugerido = str(Path(ruta_ultima_carpeta()) / f"{base} - presupuesto.{fmt}")
        if fmt == "pdf":
            ruta, self._poca_tinta = pedir_ruta_pdf(self, "Exportar presupuesto", sugerido)
        else:
            ruta, _ = QFileDialog.getSaveFileName(self, "Exportar presupuesto", sugerido, f"*.{fmt}")
        if not ruta:
            return
        if not ruta.lower().endswith("." + fmt):
            ruta += "." + fmt
        try:
            self.exportar_a(Path(ruta), fmt)
            QMessageBox.information(self, "Presupuesto",
                                    f"✅ Presupuesto guardado: {Path(ruta).name}")
        except Exception as e:
            QMessageBox.critical(self, "Presupuesto", f"No se pudo exportar:\n{e}")

    def exportar_a(self, ruta: Path, fmt: str) -> None:
        det, res, neg_det, neg_res = self.filas_excel()
        if fmt == "xlsx":
            ancho_col = {"Grupo": 18, "Categoría": 18, "Concepto": 34, "Detalle": 40,
                         "Proveedor": 20, "Cantidad": 9, "Valor unitario": 13, "Neto": 14,
                         "Total c/IVA": 14, "Total": 14, "Pagado": 8, "Fecha de pago": 12,
                         "Notas": 26}
            anchos = [ancho_col.get(h, 12) for h in det[0]]
            hojas = [
                ("Presupuesto", det, anchos,
                 {"miles": True, "negrita": neg_det}),
                ("Resumen", res, [30, 8, 15, 15, 15, 11],
                 {"miles": True, "negrita": neg_res})]
            if getattr(self.doc, "jornadas", None):
                pf, neg_pf = self.filas_por_fecha()
                hojas.append(("Por fecha de rodaje", pf,
                              [13, 38, 16, 40, 14, 12, 14, 14],
                              {"miles": True, "negrita": neg_pf}))
            escribir_xlsx_simple(ruta, hojas)
            return
        r = resumen_presupuesto(self._lineas, self._fondos_valor(), config_iva(self.doc),
                                doc=self.doc)
        grupos = (grupos_presupuesto_por_fecha(self.doc, self._lineas)
                  if self.orden() in ("rodaje", "fecha") else None)
        informes_a_pdf([info_presupuesto(self._lineas, r, getattr(self.doc, "moneda", "") or "",
                                         grupos=grupos)],
                       ruta, bool(getattr(self, "_poca_tinta", False)), self._vp._proyecto_informe(), horizontal=True)


class DialogoDocumentoLegal(QDialog):
    """Nuevo / editar un documento de «Contratos y seguros».

    modo: "nuevo" (se puede asociar a una ficha o al proyecto),
          "proyecto" (documento del proyecto existente) o
          "ficha" (documento que vive en una ficha: se editan su
          estado, fechas, notas y el archivo)."""

    def __init__(self, doc, datos: dict, modo: str = "nuevo", parent=None):
        super().__init__(parent)
        self.doc = doc
        self.modo = modo
        self.datos = dict(datos)
        self.setWindowTitle("📜  " + ("Nuevo documento" if modo == "nuevo"
                                     else "Documento"))
        g = QGridLayout(self)
        g.setContentsMargins(px(18), px(16), px(18), px(14))
        g.setHorizontalSpacing(px(10))
        g.setVerticalSpacing(px(8))
        r = 0

        self._vinc = QComboBox()
        self._vinc.addItem("📁  Proyecto (general)", "")
        etiquetas = {"actor": "🎭", "locacion": "📍", "tecnico": "🔧",
                     "equipamiento": "🎥"}
        for kind, nombre, obj in _iter_recursos(doc):
            self._vinc.addItem(f"{etiquetas[kind]}  "
                               f"{nombre_visible_recurso(kind, nombre, obj)}",
                               f"{kind}:{nombre}")
        i = self._vinc.findData(self.datos.get("vinculo", ""))
        self._vinc.setCurrentIndex(max(0, i))
        self._vinc.setEnabled(modo != "ficha")
        self._vinc.setToolTip(
            "Si eliges una ficha y adjuntas el archivo, el documento se "
            "guarda EN esa ficha (lo verás también al abrirla).")
        self._vinc.currentIndexChanged.connect(self._cambio_vinculo)
        g.addWidget(QLabel("Asociar a"), r, 0)
        g.addWidget(self._vinc, r, 1, 1, 3)
        r += 1

        self._tipo = QComboBox()
        self._tipo.setEditable(True)
        for t, ico in TIPOS_DOC_LEGAL:
            self._tipo.addItem(f"{ico}  {t}", t)
        tipo = self.datos.get("tipo") or "Otro"
        i = self._tipo.findData(tipo)
        if i >= 0:
            self._tipo.setCurrentIndex(i)
        else:
            self._tipo.setEditText(tipo)
        g.addWidget(QLabel("Tipo"), r, 0)
        g.addWidget(self._tipo, r, 1, 1, 3)
        r += 1

        self._titulo = QLineEdit(self.datos.get("titulo", ""))
        self._titulo.setPlaceholderText("Ej: Póliza de responsabilidad civil, Permiso Municipalidad de Valparaíso…")
        self._titulo.setEnabled(not (modo == "ficha" and self.datos.get("slot") in ("contrato", "boleta_unica")))
        g.addWidget(QLabel("Documento"), r, 0)
        g.addWidget(self._titulo, r, 1, 1, 3)
        r += 1

        self._contra = QLineEdit(self.datos.get("contraparte", ""))
        self._contra.setPlaceholderText("Empresa, persona o institución")
        self._contra.setEnabled(modo != "ficha")
        g.addWidget(QLabel("Contraparte"), r, 0)
        g.addWidget(self._contra, r, 1, 1, 3)
        r += 1

        self._estado = QComboBox()
        self._estado.addItems(ESTADOS_DOC_LEGAL)
        est = self.datos.get("estado") or "Pendiente"
        self._estado.setCurrentText(est if est in ESTADOS_DOC_LEGAL else "Pendiente")
        g.addWidget(QLabel("Estado"), r, 0)
        g.addWidget(self._estado, r, 1, 1, 3)
        r += 1

        self._firma = CampoFecha(self.datos.get("firma", ""))
        self._vence = CampoFecha(self.datos.get("vence", ""))
        g.addWidget(QLabel("Firma / emisión"), r, 0)
        g.addWidget(self._firma, r, 1)
        g.addWidget(QLabel("Vence"), r, 2)
        g.addWidget(self._vence, r, 3)
        r += 1

        self._monto = QLineEdit(str(self.datos.get("monto", "") or ""))
        self._monto.setPlaceholderText("Ej: 350.000 (opcional)")
        self._lbl_monto = QLabel("Monto")
        self._ayuda_monto = QLabel("Se suma al 💰 Presupuesto")
        self._ayuda_monto.setStyleSheet("color: #8fa1b8; font-size: 8.5pt;")
        g.addWidget(self._lbl_monto, r, 0)
        g.addWidget(self._monto, r, 1)
        g.addWidget(self._ayuda_monto, r, 2, 1, 2)
        r += 1

        self._archivo = CampoArchivoAdjunto(self.datos.get("archivo_nombre", ""),
                                            self.datos.get("archivo_datos", ""))
        g.addWidget(QLabel("Archivo"), r, 0)
        g.addWidget(self._archivo, r, 1, 1, 3)
        r += 1

        self._notas = QPlainTextEdit(self.datos.get("notas", ""))
        self._notas.setPlaceholderText("Condiciones, n° de póliza, contacto…")
        self._notas.setFixedHeight(px(64))
        g.addWidget(QLabel("Notas"), r, 0, Qt.AlignmentFlag.AlignTop)
        g.addWidget(self._notas, r, 1, 1, 3)
        r += 1

        bb = QDialogButtonBox(QDialogButtonBox.StandardButton.Ok
                              | QDialogButtonBox.StandardButton.Cancel)
        bb.button(QDialogButtonBox.StandardButton.Ok).setText("Guardar")
        bb.button(QDialogButtonBox.StandardButton.Cancel).setText("Cancelar")
        bb.accepted.connect(self._aceptar)
        bb.rejected.connect(self.reject)
        g.addWidget(bb, r, 0, 1, 4)
        g.setColumnStretch(1, 1)
        g.setColumnStretch(3, 1)
        self._cambio_vinculo()
        self.resize(*tam_ventana(620, 470))

    def _cambio_vinculo(self, *_):
        vinc = self._vinc.currentData() or ""
        en_ficha = self.modo == "ficha" or bool(vinc)
        for w in (self._monto, self._lbl_monto, self._ayuda_monto):
            w.setVisible(not en_ficha)
        if self.modo == "nuevo" and vinc:
            obj = recurso_por_vinculo(self.doc, vinc)
            kind, _, nombre = vinc.partition(":")
            if obj is not None:
                self._contra.setText(nombre_visible_recurso(kind, nombre, obj))
                # «Contrato de actor» elegido y luego una locación →
                # pasa a «Contrato de locación» (los demás tipos se
                # respetan tal cual los eligió la persona).
                if es_tipo_contrato(self._tipo_elegido()):
                    i = self._tipo.findData(_KIND_INFO[kind][1])
                    if i >= 0:
                        self._tipo.setCurrentIndex(i)

    def _tipo_elegido(self) -> str:
        txt = self._tipo.currentText().strip()
        for t, ico in TIPOS_DOC_LEGAL:
            if txt in (t, f"{ico}  {t}"):
                return t
        return re.sub(r"^\W+\s*", "", txt) or "Otro"

    def _aceptar(self) -> None:
        for campo, nombre in ((self._firma, "firma"), (self._vence, "vencimiento")):
            if campo.texto_invalido():
                QMessageBox.warning(self, "Fecha",
                                    f"La fecha de {nombre} no es válida. "
                                    "Escríbela como dd/mm/aaaa o usa 📅.")
                return
        if (self.modo != "ficha" and not self._titulo.text().strip()
                and not self._archivo.nombre):
            QMessageBox.information(self, "Documento",
                                    "Escribe el nombre del documento o adjunta el archivo.")
            return
        self.datos.update({
            "vinculo": self._vinc.currentData() or "",
            "tipo": self._tipo_elegido(),
            "titulo": self._titulo.text().strip() or (
                Path(self._archivo.nombre).stem if self._archivo.nombre else ""),
            "contraparte": self._contra.text().strip(),
            "estado": self._estado.currentText(),
            "firma": self._firma.iso(),
            "vence": self._vence.iso(),
            "monto": "" if (self.modo == "ficha" or self._vinc.currentData())
                     else self._monto.text().strip(),
            "archivo_nombre": self._archivo.nombre if self._archivo.datos else "",
            "archivo_datos": self._archivo.datos or "",
            "notas": self._notas.toPlainText().strip(),
        })
        self.accept()


class VentanaContratos(QDialog):
    """📜 CONTRATOS Y SEGUROS — todos los documentos legales del
    proyecto en un solo lugar: contratos de actores, locaciones, crew
    y arriendo de equipos (los que están adjuntos en cada ficha),
    permisos municipales, seguros, catering, autorizaciones…

    Muestra estado, fechas de firma y vencimiento (avisa lo que vence
    en 15 días o ya venció) y marca «⚠ Falta contrato» para quien
    trabaja en el rodaje y aún no tiene contrato. Se pueden agregar
    documentos del proyecto o adjuntarlos directo a una ficha, abrirlos,
    guardar una copia y exportar TODOS los archivos a una carpeta."""

    COLS = ["Estado", "Tipo", "Documento", "Contraparte", "Archivo",
            "Firma", "Vence", "Monto", "Notas"]
    C_EST, C_TIPO, C_DOC, C_CON, C_ARCH, C_FIR, C_VEN, C_MON, C_NOT = range(9)
    TARJETAS = [
        ("TOTAL", "", "Todos los documentos del proyecto"),
        ("✅ AL DÍA", "ok", "Firmados, vigentes o recibidos"),
        ("⏳ PENDIENTES", "pend", "Pendientes o enviados, esperando firma"),
        ("⚠ FALTAN", "falta", "Personas, locaciones o equipos del rodaje "
                              "que todavía no tienen contrato"),
        ("⏰ POR VENCER", "pronto",
         f"Vencen en los próximos {DIAS_AVISO_VENCIMIENTO} días"),
        ("⛔ VENCIDOS", "vencido", "Ya vencieron: hay que renovarlos"),
    ]

    def __init__(self, vp, parent=None):
        super().__init__(parent)
        self._vp = vp
        self.doc = vp.editor.documento
        for campo, tipo in (("documentos_legales", list), ("docs_meta", dict)):
            if not isinstance(getattr(self.doc, campo, None), tipo):
                setattr(self.doc, campo, tipo())
        self.setWindowTitle("📜  Contratos y seguros")
        habilitar_snap(self, "📜")
        aplicar_qss_tematizado(self, _QSS_PLANIF)
        self._filas: list[dict] = []
        self._nivel = ""

        v = QVBoxLayout(self)
        v.setContentsMargins(px(14), px(12), px(14), px(10))
        v.setSpacing(px(8))

        # ── KPIs (también filtran) ──
        fk = self._fila_kpi = _FilaTarjetas()
        self._kpis: dict[str, _TarjetaFiltro] = {}
        for titulo, nivel, ayuda in self.TARJETAS:
            b = _TarjetaFiltro(titulo, ayuda + "\nClic para filtrar.")
            b.clicked.connect(lambda n=nivel: self._filtrar_nivel(n))
            fk.agregar(b)
            self._kpis[nivel] = b
        v.addWidget(fk)

        # ── Acciones ──
        fila = QHBoxLayout()
        fila.setSpacing(px(6))
        b_nuevo = QPushButton("＋  Nuevo")
        b_nuevo.setToolTip("Agregar un documento: permiso, seguro, contrato…")
        b_nuevo.setObjectName("pp_primario")
        menu = QMenu(b_nuevo)
        for t, ico in TIPOS_DOC_LEGAL:
            menu.addAction(f"{ico}  {t}", lambda tt=t: self._nuevo(tt))
        b_nuevo.setMenu(menu)
        fila.addWidget(b_nuevo)
        self._b_edit = QPushButton("✏ Editar")
        self._b_edit.clicked.connect(self._editar)
        self._b_abrir = QPushButton("👁 Abrir")
        self._b_abrir.clicked.connect(self._abrir)
        self._b_copia = QPushButton("💾 Copia")
        self._b_copia.setToolTip("Guardar una copia del archivo en tu computador")
        self._b_copia.clicked.connect(self._guardar_copia)
        self._b_del = QPushButton("🗑")
        self._b_del.setToolTip("Quitar el documento")
        self._b_del.clicked.connect(self._quitar)
        for b in (self._b_edit, self._b_abrir, self._b_copia, self._b_del):
            fila.addWidget(b)
        fila.addStretch()
        b_exp = QPushButton("⬇ Exportar")
        m_exp = QMenu(b_exp)
        m_exp.addAction("📦  Todos los archivos a una carpeta…",
                        self._exportar_archivos)
        m_exp.addSeparator()
        m_exp.addAction("📄  Listado a PDF", lambda: self._exportar("pdf"))
        m_exp.addAction("📊  Listado a Excel", lambda: self._exportar("xlsx"))
        b_exp.setMenu(m_exp)
        fila.addWidget(b_exp)
        v.addLayout(fila)

        # ── Filtros ──
        fil = QHBoxLayout()
        fil.setSpacing(px(6))
        self._buscar = QLineEdit()
        self._buscar.setPlaceholderText("🔍 Buscar documento, persona, empresa…")
        self._buscar.setClearButtonEnabled(True)
        self._buscar.textChanged.connect(self._llenar_tabla)
        fil.addWidget(self._buscar, 2)
        self._cb_grupo = QComboBox()
        self._cb_grupo.addItem("Todos los grupos", "")
        for gname, ico in GRUPOS_DOC:
            self._cb_grupo.addItem(f"{ico}  {gname}", gname)
        self._cb_grupo.currentIndexChanged.connect(self._llenar_tabla)
        fil.addWidget(self._cb_grupo, 1)
        v.addLayout(fil)

        from PySide6.QtWidgets import QTableWidget, QHeaderView
        self._tabla = QTableWidget(0, len(self.COLS))
        self._tabla.setHorizontalHeaderLabels(self.COLS)
        self._tabla.verticalHeader().setVisible(False)
        self._tabla.setSelectionBehavior(QTableWidget.SelectionBehavior.SelectRows)
        self._tabla.setSelectionMode(QTableWidget.SelectionMode.SingleSelection)
        self._tabla.setEditTriggers(QTableWidget.EditTrigger.NoEditTriggers)
        self._tabla.setWordWrap(False)
        hh = self._tabla.horizontalHeader()
        hh.setMinimumSectionSize(px(40))
        bases = {self.C_EST: px(150), self.C_TIPO: px(170), self.C_DOC: px(220),
                 self.C_CON: px(170), self.C_ARCH: px(150), self.C_FIR: px(86),
                 self.C_VEN: px(86), self.C_MON: px(96), self.C_NOT: px(150)}
        for c, w in bases.items():
            hh.setSectionResizeMode(c, QHeaderView.ResizeMode.Interactive)
            self._tabla.setColumnWidth(c, w)
        self._reparto = _RepartoColumnas(
            self._tabla, bases, {self.C_DOC: 4, self.C_CON: 2, self.C_ARCH: 1,
                                 self.C_NOT: 3})
        hh.setSortIndicator(-1, Qt.SortOrder.AscendingOrder)
        self._tabla.cellDoubleClicked.connect(lambda *_: self._editar())
        self._tabla.itemSelectionChanged.connect(self._actualizar_botones)
        v.addWidget(self._tabla, 1)
        self._lbl_estado = QLabel("")
        self._lbl_estado.setObjectName("pp_ayuda")
        self._lbl_estado.setWordWrap(True)
        v.addWidget(self._lbl_estado)
        self.resize(*tam_ventana(1100, 700))
        self.refrescar()

    def _marcar(self) -> None:
        if hasattr(self._vp, "_marcar_dirty"):
            self._vp._marcar_dirty()

    def refrescar(self) -> None:
        self._filas = documentos_contratos(self.doc)
        r = resumen_contratos(self._filas)
        colores = {"ok": "#36b46a", "pend": "#ffb43a", "falta": "#ff8c1a",
                   "pronto": "#ffb43a", "vencido": "#f87171"}
        for nivel, b in self._kpis.items():
            n = r["total"] if not nivel else r.get(nivel, 0)
            b.valor.setText(str(n))
            col = _color_tema(colores[nivel]) if n and nivel in colores else ""
            b.valor.setStyleSheet(f"color: {col};" if col else "")
            b.set_activo(nivel == self._nivel)
        self._fila_kpi.revisar()
        self._llenar_tabla()

    def _filtrar_nivel(self, nivel: str) -> None:
        self._nivel = "" if nivel == self._nivel else nivel
        for n, b in self._kpis.items():
            b.set_activo(n == self._nivel)
        self._llenar_tabla()

    def filas_visibles(self) -> list[dict]:
        txt = self._buscar.text().strip().lower()
        grupo = self._cb_grupo.currentData() or ""
        out = []
        for f in self._filas:
            if grupo and f["grupo"] != grupo:
                continue
            if self._nivel and f["nivel"] != self._nivel:
                continue
            if txt and txt not in " ".join(
                    (f["tipo"], f["titulo"], f["contraparte"], f["archivo_nombre"],
                     f["notas"], f["grupo"], f["estado_vis"])).lower():
                continue
            out.append(f)
        return out

    def _llenar_tabla(self, *_):
        sel = self._clave_seleccionada()
        self._tabla.setSortingEnabled(False)
        vis = self.filas_visibles()
        self._tabla.setRowCount(len(vis))
        colores = {"ok": "#36b46a", "pend": "#ffb43a", "falta": "#ff8c1a",
                   "pronto": "#ffb43a", "vencido": "#f87171", "na": "#8fa1b8"}
        gris = QColor(_color_tema("#8fa1b8"))
        fila_sel = -1
        orden_nivel = {"vencido": 0, "falta": 1, "pronto": 2, "pend": 3, "ok": 4, "na": 5}
        for r, f in enumerate(vis):
            est = _item_tabla(f["estado_vis"], orden_nivel.get(f["nivel"], 9))
            est.setData(Qt.ItemDataRole.UserRole, f["clave"])
            est.setForeground(QBrush(QColor(_color_tema(colores.get(f["nivel"], "#e8edf4")))))
            fb = est.font()
            fb.setBold(True)
            est.setFont(fb)
            tipo = _item_tabla(f"{ICONO_TIPO_DOC.get(f['tipo'], '📄')} {f['tipo']}")
            docu = _item_tabla(f["titulo"])
            docu.setToolTip(f"{f['titulo']}\n{ICONO_GRUPO_DOC.get(f['grupo'], '')} "
                            f"{f['grupo']}"
                            + ("\n(adjunto en la ficha)" if f["origen"] == "ficha"
                               else "\n(documento del proyecto)"))
            con = _item_tabla(f["contraparte"])
            arch = _item_tabla(f"📎 {f['archivo_nombre']}" if f["tiene_archivo"]
                               else "— sin archivo")
            if not f["tiene_archivo"]:
                arch.setForeground(QBrush(gris))
            fir = _item_tabla(fecha_visible(f["firma"]), f["firma"] or "")
            ven = _item_tabla(fecha_visible(f["vence"]), f["vence"] or "9999")
            if f["nivel"] in ("pronto", "vencido"):
                ven.setForeground(QBrush(QColor(_color_tema(colores[f["nivel"]]))))
            m = parse_precio(f["monto"]) if f["monto"] else 0
            mon = _item_tabla(fmt_moneda(m) if m else "", m, True)
            nota = _item_tabla(f["notas"].replace("\n", " · "))
            nota.setToolTip(f["notas"])
            for c, it in ((self.C_EST, est), (self.C_TIPO, tipo), (self.C_DOC, docu),
                          (self.C_CON, con), (self.C_ARCH, arch), (self.C_FIR, fir),
                          (self.C_VEN, ven), (self.C_MON, mon), (self.C_NOT, nota)):
                self._tabla.setItem(r, c, it)
            if f["clave"] == sel:
                fila_sel = r
        self._tabla.setSortingEnabled(True)
        if fila_sel >= 0:
            self._tabla.selectRow(fila_sel)
        rs = resumen_contratos(self._filas)
        partes = [f"{len(vis)} de {len(self._filas)} documentos",
                  f"{rs['archivos']} con archivo adjunto"]
        if rs["falta"]:
            partes.append(f"⚠ {rs['falta']} recurso(s) trabajan en el rodaje sin contrato")
        if rs["pronto"] or rs["vencido"]:
            partes.append(f"⏰ {rs['pronto']} por vencer · ⛔ {rs['vencido']} vencido(s)")
        self._lbl_estado.setText("  ·  ".join(partes)
                                 + "   —   Doble clic para editar o adjuntar.")
        self._actualizar_botones()

    # ── Selección ──
    def _clave_seleccionada(self) -> str:
        r = self._tabla.currentRow()
        it = self._tabla.item(r, self.C_EST) if r >= 0 else None
        return it.data(Qt.ItemDataRole.UserRole) if it else ""

    def _fila(self, clave: str = None) -> Optional[dict]:
        clave = self._clave_seleccionada() if clave is None else clave
        return next((f for f in self._filas if f["clave"] == clave), None)

    def _actualizar_botones(self) -> None:
        f = self._fila()
        self._b_edit.setEnabled(f is not None)
        self._b_edit.setText("📎 Adjuntar" if f and f["nivel"] == "falta" else "✏ Editar")
        tiene = bool(f and f["tiene_archivo"])
        self._b_abrir.setEnabled(tiene)
        self._b_copia.setEnabled(tiene)
        self._b_del.setEnabled(bool(f and (f["origen"] == "proyecto" or tiene)))

    def _seleccionar(self, clave: str) -> None:
        for r in range(self._tabla.rowCount()):
            it = self._tabla.item(r, self.C_EST)
            if it and it.data(Qt.ItemDataRole.UserRole) == clave:
                self._tabla.selectRow(r)
                self._tabla.scrollToItem(it)
                return

    # ── Acceso a los datos reales ──
    def _legal(self, did: str) -> Optional[dict]:
        return next((d for d in self.doc.documentos_legales if d.get("id") == did), None)

    def _datos_archivo(self, f: dict) -> tuple[str, str]:
        """(nombre, base64) del archivo de una fila."""
        if f["origen"] == "proyecto":
            d = self._legal(f["id"]) or {}
            return d.get("archivo_nombre", ""), d.get("archivo_datos", "")
        obj = recurso_por_vinculo(self.doc, f["vinculo"])
        if obj is None:
            return "", ""
        if f["slot"] == "contrato":
            return obj.contrato_nombre, obj.contrato_datos
        if f["slot"] == "boleta_unica":
            return obj.boleta_nombre, obj.boleta_datos
        lista = obj.documentos if f["slot"] == "doc" else obj.boletas
        if 0 <= f["indice"] < len(lista):
            return lista[f["indice"]].nombre, lista[f["indice"]].datos
        return "", ""

    def _escribir_archivo_ficha(self, f: dict, nombre: str, datos: str,
                                titulo: str = None) -> None:
        obj = recurso_por_vinculo(self.doc, f["vinculo"])
        if obj is None:
            return
        if f["slot"] == "contrato":
            obj.contrato_nombre, obj.contrato_datos = (nombre, datos) if datos else ("", "")
        elif f["slot"] == "boleta_unica":
            obj.boleta_nombre, obj.boleta_datos = (nombre, datos) if datos else ("", "")
        else:
            lista = obj.documentos if f["slot"] == "doc" else obj.boletas
            if 0 <= f["indice"] < len(lista):
                if datos:
                    lista[f["indice"]].nombre = nombre
                    lista[f["indice"]].datos = datos
                    if titulo is not None:
                        lista[f["indice"]].etiqueta = titulo
                else:
                    lista.pop(f["indice"])

    def _guardar_meta(self, clave: str, datos: dict, tipo_defecto: str = "") -> None:
        meta = {k: datos.get(k, "") for k in ("estado", "firma", "vence", "notas")}
        if datos.get("tipo") and datos.get("tipo") != tipo_defecto:
            meta["tipo"] = datos["tipo"]
        meta = {k: v for k, v in meta.items() if v}
        if meta:
            self.doc.docs_meta[clave] = meta
        else:
            self.doc.docs_meta.pop(clave, None)

    # ── Acciones ──
    def _nuevo(self, tipo: str = "Otro") -> None:
        dlg = DialogoDocumentoLegal(self.doc, {"tipo": tipo, "estado": "Pendiente"},
                                    "nuevo", parent=self)
        if dlg.exec() != QDialog.DialogCode.Accepted:
            return
        clave = self.agregar_documento(dlg.datos)
        self._marcar()
        self.refrescar()
        self._seleccionar(clave)

    def agregar_documento(self, d: dict) -> str:
        """Guarda un documento nuevo. Con ficha + archivo → queda EN la
        ficha; si no, como documento del proyecto. Devuelve su clave."""
        vinc = d.get("vinculo", "")
        obj = recurso_por_vinculo(self.doc, vinc) if vinc else None
        if obj is not None and d.get("archivo_datos"):
            tipo = d.get("tipo", "Otro")
            kind = vinc.partition(":")[0]
            if es_tipo_contrato(tipo) and not obj.contrato_datos:
                obj.contrato_nombre = d["archivo_nombre"]
                obj.contrato_datos = d["archivo_datos"]
                clave = f"{vinc}:contrato"
                self._guardar_meta(clave, d, _KIND_INFO[kind][1])
                return clave
            boleta = tipo == "Boleta / factura"
            lista = obj.boletas if boleta else obj.documentos
            lista.append(DocumentoAdjunto(nombre=d["archivo_nombre"],
                                          etiqueta=d.get("titulo", ""),
                                          datos=d["archivo_datos"]))
            slot = "boleta" if boleta else "doc"
            n_igual = sum(1 for x in lista if x.nombre == d["archivo_nombre"]) - 1
            clave = (f"{vinc}:{slot}:{d['archivo_nombre']}"
                     + (f"#{n_igual}" if n_igual else ""))
            defecto = "Boleta / factura" if boleta else _tipo_doc_desde_texto(
                f"{d.get('titulo', '')} {d['archivo_nombre']}", "Otro")
            self._guardar_meta(clave, d, defecto)
            return clave
        nuevo = {k: d.get(k, "") for k in (
            "vinculo", "tipo", "titulo", "contraparte", "estado", "firma",
            "vence", "monto", "archivo_nombre", "archivo_datos", "notas")}
        nuevo["id"] = nuevo_id_corto()
        self.doc.documentos_legales.append(nuevo)
        return f"doc:{nuevo['id']}"

    def _editar(self) -> None:
        f = self._fila()
        if f is None:
            return
        nombre, datos = self._datos_archivo(f)
        if f["origen"] == "proyecto":
            d = self._legal(f["id"])
            if d is None:
                return
            dlg = DialogoDocumentoLegal(self.doc, d, "proyecto", parent=self)
            if dlg.exec() != QDialog.DialogCode.Accepted:
                return
            d.update({k: dlg.datos.get(k, "") for k in (
                "vinculo", "tipo", "titulo", "contraparte", "estado", "firma",
                "vence", "monto", "archivo_nombre", "archivo_datos", "notas")})
        else:
            base = dict(f)
            base["archivo_nombre"], base["archivo_datos"] = nombre, datos
            if f["nivel"] == "falta":
                base["estado"] = "Pendiente"
            dlg = DialogoDocumentoLegal(self.doc, base, "ficha", parent=self)
            if dlg.exec() != QDialog.DialogCode.Accepted:
                return
            nd = dlg.datos
            if (nd.get("archivo_datos") != datos or nd.get("archivo_nombre") != nombre
                    or (f["slot"] in ("doc", "boleta") and nd.get("titulo") != f["titulo"])):
                if not nd.get("archivo_datos") and datos:
                    r = QMessageBox.question(
                        self, "Quitar archivo",
                        f"¿Quitar «{nombre}» de la ficha de {f['contraparte']}?",
                        QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No)
                    if r != QMessageBox.StandardButton.Yes:
                        return
                self._escribir_archivo_ficha(
                    f, nd.get("archivo_nombre", ""), nd.get("archivo_datos", ""),
                    nd.get("titulo") if f["slot"] in ("doc", "boleta") else None)
            if f["slot"] == "contrato" or nd.get("archivo_datos"):
                kind = f["vinculo"].partition(":")[0]
                defecto = (_KIND_INFO.get(kind, ("", ""))[1] if f["slot"] == "contrato"
                           else ("Boleta / factura" if f["slot"].startswith("boleta")
                                 else _tipo_doc_desde_texto(
                                     f"{nd.get('titulo', '')} {nd.get('archivo_nombre', '')}")))
                clave = f["clave"]
                if f["slot"] in ("doc", "boleta") and nd.get("archivo_nombre") != nombre:
                    self.doc.docs_meta.pop(clave, None)
                    clave = (f"{f['vinculo']}:{f['slot']}:{nd.get('archivo_nombre')}")
                self._guardar_meta(clave, nd, defecto)
            else:
                self.doc.docs_meta.pop(f["clave"], None)
        self._marcar()
        self.refrescar()
        self._seleccionar(f["clave"])

    def _abrir(self) -> None:
        f = self._fila()
        if f is None or not f["tiene_archivo"]:
            return
        nombre, datos = self._datos_archivo(f)
        abrir_adjunto_b64(nombre, datos, self)

    def _guardar_copia(self) -> None:
        f = self._fila()
        if f is None or not f["tiene_archivo"]:
            return
        nombre, datos = self._datos_archivo(f)
        ruta, _ = QFileDialog.getSaveFileName(
            self, "Guardar copia del documento",
            str(Path(ruta_ultima_carpeta()) / _nombre_archivo_seguro(nombre)))
        if not ruta:
            return
        try:
            Path(ruta).write_bytes(base64.b64decode(datos))
            QMessageBox.information(self, "Documento", f"✅ Guardado: {Path(ruta).name}")
        except (OSError, ValueError) as e:
            QMessageBox.warning(self, "Documento", f"No se pudo guardar:\n{e}")

    def _quitar(self) -> None:
        f = self._fila()
        if f is None:
            return
        if f["origen"] == "proyecto":
            r = QMessageBox.question(
                self, "Quitar documento", f"¿Quitar «{f['titulo']}» del proyecto?",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No)
            if r != QMessageBox.StandardButton.Yes:
                return
            self.doc.documentos_legales = [
                d for d in self.doc.documentos_legales if d.get("id") != f["id"]]
            if isinstance(getattr(self.doc, "pagos", None), dict):
                self.doc.pagos.pop(f"doc:{f['id']}", None)
        elif f["tiene_archivo"]:
            r = QMessageBox.question(
                self, "Quitar documento",
                f"¿Quitar «{f['archivo_nombre']}» de la ficha de {f['contraparte']}?",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No)
            if r != QMessageBox.StandardButton.Yes:
                return
            self._escribir_archivo_ficha(f, "", "")
            self.doc.docs_meta.pop(f["clave"], None)
        else:
            return
        self._marcar()
        self.refrescar()

    # ── Exportar ──
    def filas_excel(self) -> list[list]:
        out = [["Grupo", "Tipo", "Documento", "Contraparte", "Estado", "Firma",
                "Vence", "Monto", "Archivo", "Notas"]]
        for f in self._filas:
            m = parse_precio(f["monto"]) if f["monto"] else 0
            out.append([f["grupo"], f["tipo"], f["titulo"], f["contraparte"],
                        re.sub(r"^\W+\s*", "", f["estado_vis"]),
                        fecha_visible(f["firma"]), fecha_visible(f["vence"]),
                        round(m) if m else "", f["archivo_nombre"] or "(sin archivo)",
                        f["notas"]])
        return out

    def _exportar(self, fmt: str) -> None:
        if not self._filas:
            QMessageBox.information(self, "Contratos y seguros",
                                    "Todavía no hay documentos.")
            return
        base = (getattr(self.doc, "titulo", "") or "guion").strip() or "guion"
        sugerido = str(Path(ruta_ultima_carpeta()) / f"{base} - contratos y seguros.{fmt}")
        if fmt == "pdf":
            ruta, self._poca_tinta = pedir_ruta_pdf(self, "Exportar contratos y seguros", sugerido)
        else:
            ruta, _ = QFileDialog.getSaveFileName(self, "Exportar contratos y seguros", sugerido, f"*.{fmt}")
        if not ruta:
            return
        if not ruta.lower().endswith("." + fmt):
            ruta += "." + fmt
        try:
            self.exportar_a(Path(ruta), fmt)
            QMessageBox.information(self, "Contratos y seguros",
                                    f"✅ Guardado: {Path(ruta).name}")
        except Exception as e:
            QMessageBox.critical(self, "Contratos y seguros",
                                 f"No se pudo exportar:\n{e}")

    def exportar_a(self, ruta: Path, fmt: str) -> None:
        if fmt == "xlsx":
            escribir_xlsx_simple(ruta, [("Contratos y seguros", self.filas_excel(),
                                         [13, 22, 32, 26, 18, 11, 11, 12, 26, 30],
                                         {"miles": True})])
            return
        informes_a_pdf([info_contratos(self._filas, resumen_contratos(self._filas))],
                       ruta, bool(getattr(self, "_poca_tinta", False)), self._vp._proyecto_informe(), horizontal=True)

    def _exportar_archivos(self) -> None:
        if not any(f["tiene_archivo"] for f in self._filas):
            QMessageBox.information(self, "Exportar archivos",
                                    "No hay archivos adjuntos todavía.")
            return
        carpeta = QFileDialog.getExistingDirectory(
            self, "Elegir carpeta para exportar los documentos",
            ruta_ultima_carpeta())
        if not carpeta:
            return
        try:
            destino, n = self.exportar_archivos_a(Path(carpeta))
            QMessageBox.information(
                self, "Exportar archivos",
                f"✅ {n} archivo(s) copiados en:<br><b>{html.escape(str(destino))}</b>"
                "<br><br>Ordenados en carpetas por grupo, con un índice en Excel.")
        except OSError as e:
            QMessageBox.critical(self, "Exportar archivos", f"No se pudo exportar:\n{e}")

    def exportar_archivos_a(self, carpeta: Path) -> tuple[Path, int]:
        titulo = (getattr(self.doc, "titulo", "") or "Proyecto").strip() or "Proyecto"
        destino = carpeta / _nombre_archivo_seguro(f"Contratos y seguros - {titulo}")
        destino.mkdir(parents=True, exist_ok=True)
        n = 0
        usados: set[str] = set()
        for f in self._filas:
            if not f["tiene_archivo"]:
                continue
            nombre, datos = self._datos_archivo(f)
            if not datos:
                continue
            sub = destino / _nombre_archivo_seguro(f["grupo"])
            sub.mkdir(exist_ok=True)
            quien = f["contraparte"] or f["titulo"]
            base = _nombre_archivo_seguro(f"{f['tipo']} - {quien} - {Path(nombre).stem}", 110)
            ext = Path(nombre).suffix or ".pdf"
            cand = sub / f"{base}{ext}"
            k = 2
            # Re-exportar a la misma carpeta actualiza los archivos (no
            # los duplica); solo se numeran los que se repiten ahora.
            while str(cand).lower() in usados:
                cand = sub / f"{base} ({k}){ext}"
                k += 1
            usados.add(str(cand).lower())
            cand.write_bytes(base64.b64decode(datos))
            n += 1
        escribir_xlsx_simple(destino / "Índice de documentos.xlsx",
                             [("Contratos y seguros", self.filas_excel(),
                               [13, 22, 32, 26, 18, 11, 11, 12, 26, 30],
                               {"miles": True})])
        return destino, n


# ═══════════════════════════════════════════════════════════════════════
# 🎞 STORYBOARD
# ═══════════════════════════════════════════════════════════════════════
# Mecánicas tomadas de los programas de storyboard más usados:
#   · Storyboarder: lienzo grande con 6 herramientas simples, capa de
#     referencia atenuable, papel cebolla, tira de cuadros, atajos
#     (N nuevo, D duplicar, flechas), hoja impresa para dibujar a mano.
#   · Boords: cuadrícula, campos Acción y Diálogo, storyboard desde el
#     guion, animatic con duración por cuadro, PDF con varias
#     distribuciones y portada.
#   · Celtx: cuadros agrupados por escena, arrastrar para reordenar,
#     tamaño de plano por cuadro, 16:9 / 4:3 / 1:1 / 9:16,
#     presentación, flechas/marcos/texto sobre la imagen.
#   · StudioBinder: cada cuadro ES un plano de la lista de planos (los
#     mismos datos, dos vistas) y formatos de cine (1.85, 2.39).
# Cada cuadro vive en doc.planos con estas claves extra:
#   id, dialogo, sb_foto (JPEG b64), sb_guia (PNG b64, siluetas),
#   sb_dibujo (PNG b64 con transparencia), sb_anot (lista de flechas,
#   marcos y textos en coordenadas 0–1), sb_ref_opacidad (0–1),
#   sb_capas (capas de atrás hacia adelante: personas articuladas,
#   objetos del decorado y dibujos), sb_foto_oculta, sb_anot_oculto.
#   (Los archivos anteriores usaban sb_dibujo + sb_obj; se leen igual.)

