def formato_storyboard(doc) -> str:
    f = str(getattr(doc, "storyboard_formato", "") or "16:9")
    return f if f in {x[0] for x in FORMATOS_STORYBOARD} else "16:9"


def proporcion_storyboard(formato: str) -> float:
    for k, r, _ in FORMATOS_STORYBOARD:
        if k == formato:
            return r
    return 16 / 9


def tamano_lienzo_sb(formato: str, lado: int = LADO_LARGO_SB) -> tuple[int, int]:
    r = proporcion_storyboard(formato)
    return (lado, max(1, int(round(lado / r)))) if r >= 1 else \
        (max(1, int(round(lado * r))), lado)


def asegurar_id_plano(pl: dict) -> str:
    if not pl.get("id"):
        pl["id"] = nuevo_id_corto()
    return pl["id"]


def plano_tiene_imagen(pl: dict) -> bool:
    if pl.get("sb_foto") or pl.get("sb_guia") or pl.get("sb_dibujo") \
            or pl.get("sb_anot") or pl.get("sb_obj"):
        return True
    return any(c.get("tipo") != "dibujo" or c.get("png")
               for c in (pl.get("sb_capas") or []) if isinstance(c, dict))


def qimage_desde_b64(b64: str) -> Optional[QImage]:
    if not b64:
        return None
    try:
        img = QImage.fromData(base64.b64decode(b64.encode("ascii")))
    except Exception:
        return None
    return None if img.isNull() else img


def b64_desde_qimage(img: QImage, formato: str = "PNG", calidad: int = -1) -> str:
    buf = QByteArray()
    qb = QBuffer(buf)
    qb.open(QBuffer.OpenModeFlag.WriteOnly)
    img.save(qb, formato, calidad)
    return base64.b64encode(buf.data()).decode("ascii")


def _rect_contenido(iw: int, ih: int, w: float, h: float) -> QRectF:
    """Rectángulo para dibujar una imagen iw×ih DENTRO de w×h sin
    deformarla (con bandas si la proporción cambió)."""
    if iw <= 0 or ih <= 0:
        return QRectF(0, 0, w, h)
    s = min(w / iw, h / ih)
    dw, dh = iw * s, ih * s
    return QRectF((w - dw) / 2, (h - dh) / 2, dw, dh)


def recortar_cubriendo(img: QImage, w: int, h: int) -> QImage:
    """Escala y recorta al centro para llenar w×h (como «cubrir»)."""
    esc = img.scaled(w, h, Qt.AspectRatioMode.KeepAspectRatioByExpanding,
                     Qt.TransformationMode.SmoothTransformation)
    x = max(0, (esc.width() - w) // 2)
    y = max(0, (esc.height() - h) // 2)
    return esc.copy(x, y, w, h)


def dibujar_anotaciones_sb(p: QPainter, anot: list, w: float, h: float) -> None:
    """Flechas, marcos y textos del cuadro (coordenadas 0–1)."""
    escala = max(w, h) / LADO_LARGO_SB
    for a in anot or []:
        try:
            tipo = a.get("tipo", "")
            col = QColor(a.get("color", "#d32f2f"))
            g = max(1.0, float(a.get("grosor", 4)) * escala)
            x1, y1 = float(a.get("x1", 0)) * w, float(a.get("y1", 0)) * h
            x2, y2 = float(a.get("x2", 0)) * w, float(a.get("y2", 0)) * h
        except (TypeError, ValueError):
            continue
        p.save()
        if tipo == "flecha":
            import math
            pen = QPen(col, g, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap,
                       Qt.PenJoinStyle.RoundJoin)
            p.setPen(pen)
            ang = math.atan2(y2 - y1, x2 - x1)
            tam = max(12 * escala, g * 3.4)
            # Línea hasta la base de la punta
            bx, by = x2 - math.cos(ang) * tam * 0.8, y2 - math.sin(ang) * tam * 0.8
            p.drawLine(QPointF(x1, y1), QPointF(bx, by))
            punta = QPainterPath()
            punta.moveTo(x2, y2)
            punta.lineTo(x2 - math.cos(ang - 0.45) * tam, y2 - math.sin(ang - 0.45) * tam)
            punta.lineTo(x2 - math.cos(ang + 0.45) * tam, y2 - math.sin(ang + 0.45) * tam)
            punta.closeSubpath()
            p.setBrush(col)
            p.setPen(Qt.PenStyle.NoPen)
            p.drawPath(punta)
        elif tipo == "marco":
            pen = QPen(col, g, Qt.PenStyle.DashLine)
            p.setPen(pen)
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawRect(QRectF(QPointF(min(x1, x2), min(y1, y2)),
                              QPointF(max(x1, x2), max(y1, y2))))
        elif tipo == "texto":
            txt = str(a.get("texto", ""))
            f = QFont("Arial")
            f.setBold(True)
            f.setPixelSize(max(8, int(float(a.get("tam", 30)) * escala)))
            camino = QPainterPath()
            camino.addText(QPointF(x1, y1), f, txt)
            p.setPen(QPen(QColor(255, 255, 255, 230), max(2.0, 4 * escala),
                          Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap,
                          Qt.PenJoinStyle.RoundJoin))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawPath(camino)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(col)
            p.drawPath(camino)
        p.restore()


def componer_cuadro_sb(pl: dict, w: int, h: int, opacidad: Optional[float] = None,
                       fondo: QColor = None, anotaciones: bool = True,
                       t: Optional[float] = None) -> QImage:
    """Imagen final de un cuadro: lo que ve su cámara en 3D (todo cuadro con
    escena); si no se puede, lo que se dibujó en 2D en versiones anteriores
    (foto + guía + dibujo + anotaciones)."""
    if cuadro_en_3d(pl) is not None:
        try:
            img3d = imagen_cuadro_3d(pl, max(1, int(w)), max(1, int(h)), t)
        except Exception:
            import traceback as _tb
            _tb.print_exc()
            img3d = None
        if img3d is not None:
            return img3d
    img = QImage(max(1, w), max(1, h), QImage.Format.Format_RGB32)
    img.fill(fondo or QColor("#ffffff"))
    p = QPainter(img)
    p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
    p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform, True)
    op = pl.get("sb_ref_opacidad", 1.0) if opacidad is None else opacidad
    try:
        op = max(0.0, min(1.0, float(op)))
    except (TypeError, ValueError):
        op = 1.0
    fondo3d = None
    if pl.get("sb_fondo_3d"):              # el 3D de fondo (en ese instante de su animación)
        try:
            fondo3d = imagen_fondo_3d(pl, w, h, t)
        except Exception:
            fondo3d = None
    for clave in ("sb_foto", "sb_guia"):
        if clave == "sb_foto" and pl.get("sb_foto_oculta"):
            continue
        if clave == "sb_foto" and fondo3d is not None:
            if op > 0:
                p.setOpacity(op)
                p.drawImage(QRectF(0, 0, w, h), fondo3d)
            continue
        q = qimage_desde_b64(pl.get(clave, ""))
        if q is not None and op > 0:
            p.setOpacity(op)
            p.drawImage(_rect_contenido(q.width(), q.height(), w, h), q)
    p.setOpacity(1.0)
    capas = capas_de_plano(pl)
    if pl.get("sb_fondo_3d"):                # las personas y objetos que están en el 3D
        ocultas = set(pl.get("sb_3d_capas") or [])
        capas = [c for c in capas if c.get("id") not in ocultas]
    if t is not None:                        # animación: cómo se ve en ese instante
        capas = capas_en_tiempo_sb(capas, t)
    dibujar_capas_sb(p, capas, w, h, op)
    p.setOpacity(1.0)
    dibujar_rotulos_sb(p, capas, w, h)
    p.setOpacity(1.0)
    if anotaciones and not pl.get("sb_anot_oculto"):
        dibujar_anotaciones_sb(p, pl.get("sb_anot") or [], w, h)
    p.end()
    return img


# Encuadre de la silueta según el tamaño de plano:
# (altura del cuerpo completo en «altos de cuadro», margen sobre la cabeza)
_ENCUADRE_SILUETA = {
    "Gran plano general (GPG)": (0.2, 0.62),
    "Plano general (PG)": (0.55, 0.36),
    "Plano conjunto": (0.62, 0.3),
    "Plano entero (PE)": (0.86, 0.07),
    "Plano americano (PA)": (1.3, 0.07),
    "Plano medio (PM)": (1.85, 0.08),
    "Plano medio corto (PMC)": (2.75, 0.1),
    "Sobre hombro": (2.75, 0.1),
    "Primer plano (PP)": (4.1, 0.12),
    "Primerísimo primer plano (PPP)": (8.0, -0.05),
}


# ── Siluetas guía: varios estilos para elegir ────────────────────────
# Todas se dibujan con vectores (sin imágenes externas) y en el mismo
# encuadre según el tamaño de plano. Coordenadas del cuerpo en
# «altos de figura»: x desde el centro, y desde la coronilla (0) a los
# pies (1); proporción realista de ~8 cabezas.
ESTILOS_SILUETA: list[tuple[str, str, str]] = [
    ("maniqui", "Maniquí de artista", "Muñeco articulado de madera: se ve muy clara la pose "
                                      "(recomendado)"),
    ("suave", "Silueta suave", "Silueta gris claro, para dibujar encima"),
    ("sombra", "Sombra sólida", "Silueta oscura, como un recorte"),
    ("contorno", "Contorno azul", "Solo el borde, en azul de boceto (se repasa con tinta)"),
    ("construccion", "Líneas de construcción", "Guías de dibujo: cabeza, torso, cadera y articulaciones"),
    ("pictograma", "Pictograma", "Figura simple y redondeada, tipo señalética"),
    ("palitos", "Figura de palitos", "La más rápida: cabeza y líneas"),
]
_CLAVES_ESTILO_SILUETA = [e[0] for e in ESTILOS_SILUETA]


def estilo_silueta_actual() -> str:
    try:
        e = str(settings_app().value("sb_estilo_silueta", "suave") or "suave")
    except Exception:
        e = "suave"
    return e if e in _CLAVES_ESTILO_SILUETA else "suave"


def _suavizar_cerrado(puntos: list[tuple[float, float]]) -> QPainterPath:
    """Curva cerrada suave (Catmull-Rom → Bézier) que pasa por los puntos."""
    n = len(puntos)
    camino = QPainterPath()
    if n < 3:
        return camino
    P = [QPointF(x, y) for x, y in puntos]
    camino.moveTo(P[0])
    for i in range(n):
        p0, p1, p2, p3 = P[i - 1], P[i], P[(i + 1) % n], P[(i + 2) % n]
        c1 = p1 + (p2 - p0) / 6.0
        c2 = p2 - (p3 - p1) / 6.0
        camino.cubicTo(c1, c2, p2)
    camino.closeSubpath()
    return camino


# Contorno del lado derecho (cuello → pierna → entrepierna), en unidades
# de figura; el izquierdo es su espejo.
_CONTORNO_TRONCO = [
    (0.021, 0.110), (0.024, 0.150), (0.070, 0.166), (0.104, 0.182),
    (0.101, 0.235), (0.084, 0.330), (0.078, 0.395), (0.089, 0.465),
    (0.093, 0.510), (0.088, 0.580), (0.075, 0.675), (0.064, 0.740),
    (0.066, 0.820), (0.046, 0.930), (0.056, 0.982), (0.050, 0.998),
    (0.014, 0.998), (0.016, 0.930), (0.022, 0.830), (0.020, 0.740),
    (0.022, 0.640), (0.010, 0.552),
]
_CONTORNO_BRAZO = [
    (0.103, 0.180), (0.126, 0.212), (0.131, 0.300), (0.127, 0.355),
    (0.119, 0.430), (0.109, 0.485), (0.113, 0.512), (0.106, 0.556),
    (0.090, 0.552), (0.074, 0.506), (0.064, 0.470), (0.060, 0.420),
    (0.062, 0.350), (0.068, 0.270), (0.078, 0.215),
]
# Articulaciones (lado derecho) para maniquí, construcción y palitos
_ART = {"hombro": (0.105, 0.190), "codo": (0.118, 0.345), "muneca": (0.106, 0.490),
        "cadera": (0.050, 0.525), "rodilla": (0.052, 0.740), "tobillo": (0.040, 0.935)}


def _camino_figura_realista(cx: float, top: float, H: float) -> QPainterPath:
    def a(pts, s=1):
        return [(cx + s * x * H, top + y * H) for x, y in pts]
    der = _CONTORNO_TRONCO
    izq = [(-x, y) for x, y in reversed(_CONTORNO_TRONCO)]
    # Unión booleana de las partes: sin «agujeros» donde se superponen
    # (los brazos espejados tienen el sentido de giro contrario).
    camino = _suavizar_cerrado(a(der) + [(cx, top + 0.545 * H)] + a(izq))
    cabeza = QPainterPath()
    cabeza.addEllipse(QPointF(cx, top + 0.066 * H), 0.046 * H, 0.062 * H)
    camino = camino.united(cabeza)
    for s in (1, -1):
        camino = camino.united(_suavizar_cerrado(a(_CONTORNO_BRAZO, s)))
    return camino.simplified()


def _camino_pictograma(cx: float, top: float, H: float) -> QPainterPath:
    def pieza(r: QRectF, radio: float) -> QPainterPath:
        q = QPainterPath()
        q.addRoundedRect(r, radio, radio)
        return q
    c = QPainterPath()
    c.addEllipse(QPointF(cx, top + 0.072 * H), 0.068 * H, 0.068 * H)
    c = c.united(pieza(QRectF(cx - 0.098 * H, top + 0.165 * H, 0.196 * H, 0.37 * H),
                       0.05 * H))
    for s in (1, -1):
        c = c.united(pieza(QRectF(cx + s * 0.128 * H - 0.026 * H, top + 0.172 * H,
                                  0.052 * H, 0.33 * H), 0.026 * H))
        c = c.united(pieza(QRectF(cx + s * 0.050 * H - 0.038 * H, top + 0.48 * H,
                                  0.076 * H, 0.52 * H), 0.038 * H))
    return c


def _dibujar_figura(p: QPainter, estilo: str, cx: float, top: float, H: float,
                    alto_cuadro: float, mira: int = 0, primer_termino: bool = False) -> None:
    """Dibuja UNA figura. mira: -1 izquierda, 0 frente, 1 derecha."""
    def pt(x, y, s=1):
        return QPointF(cx + s * x * H, top + y * H)
    # Grosor de línea: proporcional a la figura, pero legible en cualquier plano
    linea = max(alto_cuadro * 0.0025, min(H * 0.006, alto_cuadro * 0.012))
    oscuro = 1.6 if primer_termino else 1.0
    if estilo in ("suave", "sombra", "contorno"):
        camino = _camino_figura_realista(cx, top, H)
        if estilo == "suave":
            p.setPen(QPen(QColor(90, 100, 125, int(min(255, 170 * oscuro))), linea * 0.8))
            p.setBrush(QColor(120, 132, 155, int(min(230, 95 * oscuro))))
        elif estilo == "sombra":
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor(45, 52, 68, 225 if primer_termino else 205))
        else:
            p.setPen(QPen(QColor(66, 133, 244, 220), linea * (1.4 if primer_termino else 1.0),
                          Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap,
                          Qt.PenJoinStyle.RoundJoin))
            p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawPath(camino)
        return
    if estilo == "pictograma":
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(52, 73, 94, 225 if primer_termino else 200))
        p.drawPath(_camino_pictograma(cx, top, H))
        return
    if estilo == "palitos":
        col = QColor(40, 40, 46, 235)
        g = max(alto_cuadro * 0.004, min(H * 0.014, alto_cuadro * 0.02))
        p.setPen(QPen(col, g, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap,
                      Qt.PenJoinStyle.RoundJoin))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawEllipse(pt(0, 0.07), 0.058 * H, 0.066 * H)
        cuello, pelvis = pt(0, 0.138), pt(0, 0.52)
        p.drawLine(cuello, pelvis)
        hombros = pt(0, 0.19)
        for s in (1, -1):
            p.drawPolyline([hombros, pt(0.12, 0.34, s), pt(0.10, 0.50, s)])
            p.drawPolyline([pelvis, pt(0.055, 0.75, s), pt(0.05, 0.98, s), pt(0.085, 0.99, s)])
        if mira:
            p.drawLine(pt(0.058 * mira, 0.075), pt(0.085 * mira, 0.085))
        return
    # Maniquí de artista y líneas de construcción
    mani = estilo == "maniqui"
    relleno = QColor(214, 190, 150, 215) if mani else Qt.BrushStyle.NoBrush
    borde = QColor(120, 90, 55, 230) if mani else QColor(80, 130, 210, 210)
    pluma = QPen(borde, linea * (1.0 if mani else 0.9), Qt.PenStyle.SolidLine,
                 Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin)
    p.setPen(pluma)

    def capsula(a: QPointF, b: QPointF, ancho: float) -> None:
        import math
        L = math.hypot(b.x() - a.x(), b.y() - a.y())
        ang = math.degrees(math.atan2(b.y() - a.y(), b.x() - a.x()))
        p.save()
        p.translate(a)
        p.rotate(ang)
        p.setBrush(relleno)
        p.drawRoundedRect(QRectF(0, -ancho / 2, L, ancho), ancho / 2, ancho / 2)
        p.restore()

    def articulacion(c: QPointF, r: float) -> None:
        p.setBrush(QColor(196, 168, 124, 230) if mani else Qt.BrushStyle.NoBrush)
        p.drawEllipse(c, r, r)

    A = {k: (v[0], v[1]) for k, v in _ART.items()}
    if mani:
        # Extremidades (atrás), tronco y cabeza (adelante)
        for s in (1, -1):
            capsula(pt(*A["cadera"], s), pt(*A["rodilla"], s), 0.07 * H)
            capsula(pt(*A["rodilla"], s), pt(*A["tobillo"], s), 0.055 * H)
            p.setBrush(relleno)
            p.drawEllipse(QRectF(cx + s * 0.040 * H - 0.035 * H, top + 0.95 * H,
                                 0.07 * H, 0.05 * H))
            capsula(pt(*A["hombro"], s), pt(*A["codo"], s), 0.055 * H)
            capsula(pt(*A["codo"], s), pt(*A["muneca"], s), 0.045 * H)
            p.setBrush(relleno)
            p.drawEllipse(pt(0.106, 0.525, s), 0.024 * H, 0.034 * H)
        p.setBrush(relleno)
        p.drawEllipse(pt(0, 0.27), 0.098 * H, 0.105 * H)       # pecho
        p.drawEllipse(pt(0, 0.40), 0.06 * H, 0.05 * H)          # abdomen
        p.drawEllipse(pt(0, 0.50), 0.088 * H, 0.055 * H)        # cadera
        capsula(pt(0, 0.12), pt(0, 0.175), 0.04 * H)            # cuello
        for s in (1, -1):
            for k in ("hombro", "codo", "muneca", "cadera", "rodilla", "tobillo"):
                articulacion(pt(*A[k], s), 0.022 * H)
        p.setBrush(relleno)
        p.drawEllipse(pt(0, 0.066), 0.05 * H, 0.064 * H)        # cabeza
    else:
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawEllipse(pt(0, 0.062), 0.05 * H, 0.056 * H)        # cráneo
        mand = QPainterPath()                                    # mandíbula
        mand.moveTo(pt(-0.045, 0.08))
        mand.quadTo(pt(0, 0.15), pt(0.045, 0.08))
        p.drawPath(mand)
        p.drawLine(pt(-0.03, 0.135), pt(-0.06, 0.175))          # cuello / trapecio
        p.drawLine(pt(0.03, 0.135), pt(0.06, 0.175))
        p.drawLine(pt(-0.105, 0.19), pt(0.105, 0.19))           # hombros
        p.drawEllipse(pt(0, 0.27), 0.085 * H, 0.1 * H)          # caja torácica
        espina = QPainterPath()
        espina.moveTo(pt(0, 0.17))
        espina.quadTo(pt(0.012, 0.36), pt(0, 0.48))
        p.drawPath(espina)
        pel = QPainterPath()                                     # pelvis
        pel.moveTo(pt(-0.085, 0.46))
        pel.lineTo(pt(0.085, 0.46))
        pel.lineTo(pt(0.06, 0.545))
        pel.lineTo(pt(-0.06, 0.545))
        pel.closeSubpath()
        p.drawPath(pel)
        for s in (1, -1):
            p.drawPolyline([pt(*A["hombro"], s), pt(*A["codo"], s), pt(*A["muneca"], s)])
            p.drawPolyline([pt(*A["cadera"], s), pt(*A["rodilla"], s), pt(*A["tobillo"], s)])
            p.drawLine(pt(*A["tobillo"], s), pt(0.075, 0.99, s))
            p.drawEllipse(pt(0.106, 0.525, s), 0.02 * H, 0.03 * H)
            for k in ("hombro", "codo", "muneca", "cadera", "rodilla", "tobillo"):
                articulacion(pt(*A[k], s), 0.012 * H)
    # Hacia dónde mira: línea central y línea de los ojos de la cabeza
    p.setBrush(Qt.BrushStyle.NoBrush)
    guia = QPen(QColor(150, 110, 70, 220) if mani else QColor(80, 130, 210, 210),
                max(1.0, linea * 0.7))
    p.setPen(guia)
    rx = 0.05 * H
    centro = QPainterPath()
    desplaz = mira * rx * 0.55
    centro.moveTo(pt(0, 0.006))
    centro.quadTo(QPointF(cx + desplaz * 1.6, top + 0.066 * H), pt(0, 0.128))
    p.drawPath(centro)
    p.drawLine(pt(-0.05, 0.07), pt(0.05, 0.07))


def dibujar_silueta_guia(img: QImage, tamano: str, personas: int = 1,
                         lado: str = "centro", estilo: str = "") -> bool:
    """Dibuja figuras guía (como el «Shot Generator» de Storyboarder, en
    simple) encuadradas según el tamaño de plano, en el estilo elegido.
    Devuelve False si el tamaño no lleva figura (plano detalle, inserto)."""
    if tamano in ("Plano detalle (PD)", "Inserto"):
        return False
    estilo = estilo if estilo in _CLAVES_ESTILO_SILUETA else estilo_silueta_actual()
    alto_rel, margen = _ENCUADRE_SILUETA.get(tamano, _ENCUADRE_SILUETA["Plano medio (PM)"])
    w, h = img.width(), img.height()
    H = alto_rel * h
    top = margen * h
    if tamano == "Plano conjunto":
        personas = max(3, personas)
    if personas <= 1:
        xs = {"izquierda": [w / 3], "derecha": [2 * w / 3]}.get(lado, [w / 2])
        miradas = {"izquierda": [1], "derecha": [-1]}.get(lado, [0])
    elif personas == 2:
        xs, miradas = [w / 3, 2 * w / 3], [1, -1]
    else:
        xs = [w * (i + 1) / (personas + 1) for i in range(personas)]
        miradas = [1 if i < personas // 2 else (-1 if i > (personas - 1) // 2 else 0)
                   for i in range(personas)]
    p = QPainter(img)
    p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
    for cx, mira in zip(xs, miradas):
        _dibujar_figura(p, estilo, cx, top, H, h, mira)
    if tamano == "Sobre hombro":
        # Hombro y nuca del otro personaje en primer término
        _dibujar_figura(p, estilo, w * 0.93, -0.06 * h, H * 1.3, h, -1, primer_termino=True)
    p.end()
    return True


def icono_estilo_silueta(estilo: str, ancho: int = 96) -> QIcon:
    """Miniatura del estilo: dos personas que conversan y una planta."""
    alto = int(ancho * 9 / 16)
    img = QImage(ancho, alto, QImage.Format.Format_ARGB32_Premultiplied)
    img.fill(QColor("#ffffff"))
    p = QPainter(img)
    p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
    figs = figuras_para_plano("Plano entero (PE)", 2, "centro", estilo)
    if figs:
        aplicar_pose_figura(figs[0], "senalando")
        figs[0]["pose"]["brazo_d"] = 60.0
    alto_p, suelo = 0.86, 0.07 + 1.013 * 0.86
    planta = nuevo_objeto_sb("planta", 0.88, suelo, 0.6 * alto_p, estilo)
    dibujar_objetos_sb(p, [planta] + figs, ancho, alto)
    p.end()
    return QIcon(QPixmap.fromImage(img))


# ── Figuras articuladas (maniquí posable) y objetos del decorado ─────
# Como el «Shot Generator» de Storyboarder, pero en 2D y dentro del
# cuadro: cada figura es un muñeco con articulaciones (cabeza, torso,
# brazos, antebrazos, muslos y piernas) que se posa arrastrando puntos;
# los objetos (escritorio, auto, casa, árbol, escalera…) se mueven,
# escalan, giran y voltean. Se guardan como datos (no como imagen) en
# plano["sb_obj"], así que siempre se pueden volver a posar.
#
# Figura: {"id", "tipo": "figura", "x", "y" (pelvis, 0–1 del cuadro),
#          "alto" (altura de la persona / alto del cuadro), "rot" (°),
#          "espejo", "vista" (frente|tres_cuartos|perfil|espalda),
#          "estilo", "pose": {torso, cabeza, brazo_d, antebrazo_d, …,
#          "escorzo": {segmento: factor de largo}}}
# Objeto: {"id", "tipo": "objeto", "clase", "x", "y" (base, 0–1),
#          "alto", "rot", "espejo", "estilo"}
# Ángulos: 0 = hacia abajo, positivo = hacia +x (el frente de la
# figura cuando mira a la derecha). «_d» es el lado derecho de la
# pantalla (de frente) o el lado cercano a la cámara (de perfil).
