_POSES_FIG = {p[0]: p for p in POSES_FIGURA}


def _dir(a: float) -> tuple[float, float]:
    r = _math.radians(a)
    return (_math.sin(r), _math.cos(r))


def _angulo(dx: float, dy: float) -> float:
    return _math.degrees(_math.atan2(dx, dy))


def _norm180(a: float) -> float:
    return (a + 180.0) % 360.0 - 180.0


def _mas(p: tuple, v: tuple, k: float = 1.0) -> tuple[float, float]:
    return (p[0] + v[0] * k, p[1] + v[1] * k)


def estilo_figuras_actual() -> str:
    """Estilo de las figuras y objetos nuevos (por defecto, el maniquí)."""
    try:
        e = str(settings_app().value("sb_estilo_figuras", "maniqui") or "maniqui")
    except Exception:
        e = "maniqui"
    return e if e in _CLAVES_ESTILO_SILUETA else "maniqui"


def nueva_figura(x: float, y: float, alto: float, vista: str = "frente",
                 espejo: bool = False, estilo: str = "", pose: str = "de_pie") -> dict:
    f = {"id": nuevo_id_corto(), "tipo": "figura", "x": round(x, 4), "y": round(y, 4),
         "alto": round(alto, 4), "rot": 0.0, "espejo": bool(espejo),
         "vista": vista if vista in _VISTA_FIG else "frente",
         "estilo": estilo if estilo in _CLAVES_ESTILO_SILUETA else estilo_figuras_actual(),
         "pose": {}}
    aplicar_pose_figura(f, pose, mantener_suelo=False)
    return f


def esqueleto_figura(fig: dict) -> dict:
    """Puntos de la figura en coordenadas locales: pelvis en (0, 0),
    y hacia abajo, unidad = altura de la persona."""
    pose = fig.get("pose") or {}
    esc = pose.get("escorzo") or {}

    def g(k: str) -> float:
        try:
            return float(pose.get(k, 0) or 0)
        except (TypeError, ValueError):
            return 0.0

    def largo(seg: str, lado: str) -> float:
        try:
            return _MF[seg] * float(esc.get(f"{seg}_{lado}", 1.0) or 1.0)
        except (TypeError, ValueError):
            return _MF[seg]
    vh, vp, vc, vcs, _cara = _VISTA_FIG.get(fig.get("vista"), _VISTA_FIG["frente"])
    t, c = g("torso"), g("cabeza")
    arriba = (_math.sin(_math.radians(t)), -_math.cos(_math.radians(t)))
    lado_v = (_math.cos(_math.radians(t)), _math.sin(_math.radians(t)))
    J: dict[str, tuple[float, float]] = {"pelvis": (0.0, 0.0)}
    cin = (0.0, -_MF["cintura"])
    cue = _mas(cin, arriba, _MF["espalda"])
    nuca = _mas(cue, arriba, _MF["cuello"])
    arr_c = (_math.sin(_math.radians(t + c)), -_math.cos(_math.radians(t + c)))
    J.update(cintura=cin, cuello=cue, nuca=nuca, cabeza=_mas(nuca, arr_c, _MF["cabeza_c"]))
    A: dict[str, float] = {}
    for lado, s in _LADOS_FIG:
        hom = _mas(_mas(cue, arriba, -_MF["hombro_y"]), lado_v, s * _MF["hombro_x"] * vh)
        a1 = -t + g(f"brazo_{lado}")
        a2 = a1 + g(f"antebrazo_{lado}")
        codo = _mas(hom, _dir(a1), largo("brazo", lado))
        mun = _mas(codo, _dir(a2), largo("antebrazo", lado))
        cad = (s * _MF["cadera_x"] * vcs, _MF["cadera_y"])
        l1 = g(f"muslo_{lado}")
        l2 = l1 + g(f"pierna_{lado}")
        rod = _mas(cad, _dir(l1), largo("muslo", lado))
        tob = _mas(rod, _dir(l2), largo("pierna", lado))
        J.update({f"hombro_{lado}": hom, f"codo_{lado}": codo, f"muneca_{lado}": mun,
                  f"mano_{lado}": _mas(mun, _dir(a2), _MF["mano"] * 0.5),
                  f"cadera_{lado}": cad, f"rodilla_{lado}": rod, f"tobillo_{lado}": tob})
        A.update({f"a1_{lado}": a1, f"a2_{lado}": a2, f"l1_{lado}": l1, f"l2_{lado}": l2})
    return {"J": J, "A": A, "t": t, "c": c, "vista": fig.get("vista", "frente"),
            "pecho": vp, "cadera": vc, "cara": _cara}


# ── Piezas del cuerpo (para dibujar en cualquier estilo) ──
def _huso(a: tuple, b: tuple, ancho: float) -> QPainterPath:
    """Segmento del maniquí: elipse alargada entre dos articulaciones."""
    L = _math.hypot(b[0] - a[0], b[1] - a[1])
    q = QPainterPath()
    q.addEllipse(QPointF(0, 0), L / 2 + ancho * 0.18, ancho / 2)
    tr = QTransform()
    tr.translate((a[0] + b[0]) / 2, (a[1] + b[1]) / 2)
    tr.rotate(_math.degrees(_math.atan2(b[1] - a[1], b[0] - a[0])))
    return tr.map(q)


def _elipse_rot(c: tuple, rx: float, ry: float, ang: float) -> QPainterPath:
    q = QPainterPath()
    q.addEllipse(QPointF(0, 0), rx, ry)
    tr = QTransform()
    tr.translate(c[0], c[1])
    tr.rotate(ang)
    return tr.map(q)


def _circulo(c: tuple, r: float) -> QPainterPath:
    q = QPainterPath()
    q.addEllipse(QPointF(c[0], c[1]), r, r)
    return q


# ── Maniquí de perfil: piezas con su volumen real visto de lado ──
# Puntos en coordenadas de la pieza: x = hacia adelante (hacia donde mira),
# y = hacia abajo, en «altos de figura». Se giran con el torso o la cabeza.
_PERFIL_PECHO = [(0.0, -0.116), (0.042, -0.104), (0.07, -0.062), (0.076, -0.01), (0.066, 0.042),
                 (0.04, 0.088), (0.004, 0.11), (-0.034, 0.096), (-0.052, 0.05), (-0.058, -0.012),
                 (-0.054, -0.07), (-0.034, -0.104)]
_PERFIL_PELVIS = [(0.004, -0.054), (0.046, -0.046), (0.064, -0.01), (0.056, 0.03), (0.026, 0.058),
                  (-0.012, 0.066), (-0.05, 0.054), (-0.074, 0.02), (-0.07, -0.022), (-0.042, -0.05)]
_PERFIL_CABEZA = [(-0.002, -0.067), (0.03, -0.062), (0.05, -0.042), (0.057, -0.012),
                  (0.056, 0.016), (0.05, 0.04), (0.036, 0.06), (0.016, 0.068), (-0.006, 0.058),
                  (-0.022, 0.04), (-0.044, 0.028), (-0.056, 0.0), (-0.054, -0.03), (-0.036, -0.056)]
_PERFIL_PIE = [(-0.018, -0.006), (0.012, -0.006), (0.032, 0.006), (0.07, 0.02), (0.09, 0.032),
               (0.086, 0.044), (0.02, 0.046), (-0.024, 0.044), (-0.032, 0.026)]


def _forma_perfil(centro: tuple, puntos: list, ang: float) -> QPainterPath:
    """Forma curva de una pieza de perfil, en su lugar y girada."""
    tr = QTransform()
    tr.translate(centro[0], centro[1])
    tr.rotate(ang)
    return tr.map(_suavizar_cerrado(puntos))


def _pie_perfil(tob: tuple, l2: float) -> QPainterPath:
    """Pie visto de lado (talón, planta y punta), según el ángulo de la pierna."""
    abajo, adelante = _dir(l2), _dir(l2 + 90)
    pts = [(tob[0] + adelante[0] * x + abajo[0] * y, tob[1] + adelante[1] * x + abajo[1] * y)
           for x, y in _PERFIL_PIE]
    return _suavizar_cerrado(pts)


def _centro_cabeza_perfil(sk: dict) -> tuple:
    J, ang = sk["J"], _math.radians(sk["t"] + sk["c"])
    return _mas(J["cabeza"], (_math.cos(ang), _math.sin(ang)), 0.01)


def piezas_figura(sk: dict) -> list[tuple[str, QPainterPath, str, str]]:
    """Lista ordenada (de atrás hacia adelante) de piezas:
    (nombre, camino local, capa, tipo) — tipo: "seg", "art", "tronco", "cabeza"."""
    J, A, t, c = sk["J"], sk["A"], sk["t"], sk["c"]
    vista = sk["vista"]
    perfil = vista in ("perfil", "tres_cuartos")

    def pierna(lado: str) -> list:
        tob, l2 = J[f"tobillo_{lado}"], A[f"l2_{lado}"]
        if vista == "perfil":
            pie = _pie_perfil(tob, l2)
        elif perfil:
            base = _mas(tob, _dir(l2), 0.016)
            punta = _mas(base, _dir(l2 + 90), 0.085 if vista == "perfil" else 0.062)
            pie = _huso(base, punta, 0.042)
        else:
            pie = _elipse_rot(_mas(tob, _dir(l2), 0.03), 0.03, 0.022, -l2)
        return [(f"muslo_{lado}", _huso(J[f"cadera_{lado}"], J[f"rodilla_{lado}"], 0.074), "seg"),
                (f"pierna_{lado}", _huso(J[f"rodilla_{lado}"], J[f"tobillo_{lado}"], 0.056), "seg"),
                (f"pie_{lado}", pie, "seg"),
                (f"a_cadera_{lado}", _circulo(J[f"cadera_{lado}"], 0.029), "art"),
                (f"a_rodilla_{lado}", _circulo(J[f"rodilla_{lado}"], 0.024), "art"),
                (f"a_tobillo_{lado}", _circulo(J[f"tobillo_{lado}"], 0.018), "art")]

    def brazo(lado: str) -> list:
        mun, a2 = J[f"muneca_{lado}"], A[f"a2_{lado}"]
        return [(f"brazo_{lado}", _huso(J[f"hombro_{lado}"], J[f"codo_{lado}"], 0.052), "seg"),
                (f"antebrazo_{lado}", _huso(J[f"codo_{lado}"], mun, 0.043), "seg"),
                (f"mano_{lado}", _huso(mun, _mas(mun, _dir(a2), _MF["mano"]), 0.036), "seg"),
                (f"a_hombro_{lado}", _circulo(J[f"hombro_{lado}"], 0.027), "art"),
                (f"a_codo_{lado}", _circulo(J[f"codo_{lado}"], 0.021), "art"),
                (f"a_muneca_{lado}", _circulo(mun, 0.015), "art")]
    arriba = (_math.sin(_math.radians(t)), -_math.cos(_math.radians(t)))
    tronco = [
        ("pelvis", _elipse_rot((0.0, 0.006), 0.088 * sk["cadera"], 0.058, t * 0.25), "tronco"),
        ("abdomen", _elipse_rot(_mas(J["cintura"], arriba, 0.03), 0.062 * sk["pecho"], 0.047, t),
         "tronco"),
        ("pecho", _elipse_rot(_mas(J["cintura"], arriba, 0.155), 0.098 * sk["pecho"], 0.112, t),
         "tronco"),
        ("cuello", _huso(_mas(J["cuello"], arriba, -0.012), J["nuca"], 0.036), "seg"),
        ("cabeza", _elipse_rot(J["cabeza"], _MF["cabeza_rx"], _MF["cabeza_ry"], t + c), "cabeza"),
    ]
    if vista == "perfil":
        # De lado: el pecho sobresale hacia adelante, la pelvis se inclina,
        # el cuello va un poco hacia adelante y la cabeza tiene mandíbula
        adelante = (_math.cos(_math.radians(t)), _math.sin(_math.radians(t)))
        ang_c = _math.radians(t + c)
        adel_c = (_math.cos(ang_c), _math.sin(ang_c))
        pelvis_c = _mas((0.0, 0.006), adelante, -0.004)
        tronco = [
            ("pelvis", _forma_perfil(pelvis_c, _PERFIL_PELVIS, t * 0.25 + 10), "tronco"),
            ("abdomen", _elipse_rot(_mas(_mas(J["cintura"], arriba, 0.034), adelante, 0.008),
                                    0.058, 0.054, t), "tronco"),
            ("pecho", _forma_perfil(_mas(_mas(J["cintura"], arriba, 0.158), adelante, 0.008),
                                    _PERFIL_PECHO, t - 5), "tronco"),
            ("cuello", _huso(_mas(_mas(J["cuello"], arriba, -0.014), adelante, -0.004),
                             _mas(J["nuca"], adel_c, -0.01), 0.04), "seg"),
            ("cabeza", _forma_perfil(_centro_cabeza_perfil(sk), _PERFIL_CABEZA, t + c), "cabeza"),
        ]
    out: list = []
    if vista == "perfil":
        out += [(n, q, "atras", k) for n, q, k in brazo("i") + pierna("i")]
        out += [(n, q, "cuerpo", k) for n, q, k in tronco]
        out += [(n, q, "frente", k) for n, q, k in pierna("d") + brazo("d")]
    else:
        out += [(n, q, "cuerpo", k) for n, q, k in pierna("i") + pierna("d")]
        out += [(n, q, "cuerpo", k) for n, q, k in tronco]
        out += [(n, q, "frente", k) for n, q, k in brazo("i") + brazo("d")]
    return out


def camino_local_figura(fig: dict) -> QPainterPath:
    """Contorno de toda la figura (para tocarla con el mouse)."""
    if fig.get("vista") == "arriba":
        return _camino_figura_arriba(fig)
    q = QPainterPath()
    q.setFillRule(Qt.FillRule.WindingFill)
    for _n, pz, _c, _k in piezas_figura(esqueleto_figura(fig)):
        q.addPath(pz)
    return q


def transformada_objeto(obj: dict, W: float, H: float) -> QTransform:
    """De coordenadas locales de la figura u objeto al cuadro (W×H)."""
    try:
        x, y = float(obj.get("x", 0.5)) * W, float(obj.get("y", 0.8)) * H
        S = max(1e-3, float(obj.get("alto", 0.5))) * H
        rot = float(obj.get("rot", 0) or 0)
    except (TypeError, ValueError):
        x, y, S, rot = W / 2, H * 0.8, H / 2, 0.0
    tr = QTransform()
    tr.translate(x, y)
    tr.rotate(rot)
    tr.scale(-S if obj.get("espejo") else S, S)
    return tr


def _grosor_linea(S: float, H: float, k: float = 0.006, lo: float = 0.0025,
                  hi: float = 0.012) -> float:
    """Grosor (en px del cuadro) proporcional a la figura pero legible."""
    return max(H * lo, min(S * k, H * hi))


_ESCALA_BOOL = 1000.0     # las operaciones de caminos aproximan las curvas con
                          # segmentos de tamaño fijo: se hacen en una escala
                          # grande para que los contornos queden suaves


def _a_escala(q: QPainterPath, k: float) -> QPainterPath:
    return QTransform.fromScale(k, k).map(q)


def _union_piezas(piezas: list[QPainterPath]) -> QPainterPath:
    q = QPainterPath()
    q.setFillRule(Qt.FillRule.WindingFill)
    for pz in piezas:
        q.addPath(pz)
    return _a_escala(_a_escala(q, _ESCALA_BOOL).simplified(), 1 / _ESCALA_BOOL)


def _op_caminos(a: QPainterPath, b: QPainterPath, op: str) -> QPainterPath:
    """Unión / intersección / resta de caminos, con curvas suaves."""
    A, B = _a_escala(a, _ESCALA_BOOL), _a_escala(b, _ESCALA_BOOL)
    r = {"union": A.united, "interseccion": A.intersected, "resta": A.subtracted}[op](B)
    return _a_escala(r, 1 / _ESCALA_BOOL)


def _trazo_grueso(puntos: list[tuple], ancho: float, curvo: bool = False) -> QPainterPath:
    if curvo:
        q = _suavizar_abierto(puntos)
    else:
        q = QPainterPath()
        q.moveTo(QPointF(*puntos[0]))
        for pt in puntos[1:]:
            q.lineTo(QPointF(*pt))
    st = QPainterPathStroker()
    st.setWidth(ancho * _ESCALA_BOOL)
    st.setCapStyle(Qt.PenCapStyle.RoundCap)
    st.setJoinStyle(Qt.PenJoinStyle.RoundJoin)
    return _a_escala(st.createStroke(_a_escala(q, _ESCALA_BOOL)), 1 / _ESCALA_BOOL)


def _sin_huecos_chicos(q: QPainterPath, area_min: float = 0.0008) -> QPainterPath:
    """Quita los huequitos que deja la unión de piezas que casi se tocan
    (se verían como puntos o rayitas dentro de la silueta)."""
    out = QPainterPath()
    out.setFillRule(Qt.FillRule.OddEvenFill)
    for pol in q.toSubpathPolygons():
        n = pol.count()
        if n < 3:
            continue
        area = 0.0
        for i in range(n):
            a, b = pol.at(i), pol.at((i + 1) % n)
            area += a.x() * b.y() - b.x() * a.y()
        if abs(area) / 2 >= area_min:
            out.addPolygon(pol)
            out.closeSubpath()
    return out


def _lineas_cara(p: QPainter, sk: dict, lw: float, col: QColor) -> None:
    """Línea central y de los ojos: muestra hacia dónde mira la cabeza."""
    cara = sk["cara"]
    if cara is None:
        return
    J = sk["J"]
    rx, ry = _MF["cabeza_rx"], _MF["cabeza_ry"]
    p.save()
    p.translate(*J["cabeza"])
    p.rotate(sk["t"] + sk["c"])
    p.setBrush(Qt.BrushStyle.NoBrush)
    p.setPen(QPen(col, lw * 0.8, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
    if sk["vista"] == "perfil":
        # De lado: la línea de los ojos rodea la cabeza hasta la oreja,
        # la oreja y la línea de la mandíbula
        p.restore()
        p.save()
        p.translate(*_centro_cabeza_perfil(sk))
        p.rotate(sk["t"] + sk["c"])
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.setPen(QPen(col, lw * 0.8, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
        ojos = QPainterPath()
        ojos.moveTo(QPointF(0.056, -0.008))
        ojos.quadTo(QPointF(0.02, -0.002), QPointF(-0.004, -0.004))
        p.drawPath(ojos)
        p.drawEllipse(QPointF(-0.012, 0.006), 0.011, 0.017)
        mand = QPainterPath()
        mand.moveTo(QPointF(-0.014, 0.026))
        mand.quadTo(QPointF(0.0, 0.05), QPointF(0.034, 0.057))
        p.drawPath(mand)
        p.restore()
        return
    d = cara * rx
    q = QPainterPath()
    q.moveTo(QPointF(d * 0.35, -ry * 0.97))
    q.quadTo(QPointF(d * 1.55, 0), QPointF(d * 0.35, ry * 0.97))
    p.drawPath(q)
    if cara >= 0.9:          # de perfil: ojo y nariz
        p.drawLine(QPointF(rx * 0.25, -ry * 0.05), QPointF(rx * 0.98, -ry * 0.05))
        p.drawLine(QPointF(rx * 0.98, ry * 0.05), QPointF(rx * 1.22, ry * 0.2))
    else:
        p.drawLine(QPointF(-rx * (1 - cara * 0.6), -ry * 0.05), QPointF(rx, -ry * 0.05))
    p.restore()


def dibujar_figura_sb(p: QPainter, fig: dict, W: float, H: float) -> None:
    """Dibuja una figura articulada en su pose, en su estilo."""
    if fig.get("vista") == "arriba":
        dibujar_figura_arriba_sb(p, fig, W, H)
        return
    estilo = fig.get("estilo") if fig.get("estilo") in _CLAVES_ESTILO_SILUETA else "maniqui"
    sk = esqueleto_figura(fig)
    piezas = piezas_figura(sk)
    S = max(1e-3, float(fig.get("alto", 0.5) or 0.5)) * H
    p.save()
    p.setTransform(transformada_objeto(fig, W, H), True)
    lw = _grosor_linea(S, H) / S
    J = sk["J"]
    if estilo in ("suave", "sombra", "contorno"):
        camino = _sin_huecos_chicos(_union_piezas([q for _n, q, _c, _k in piezas]))
        if estilo == "suave":
            p.setPen(QPen(QColor(90, 100, 125, 170), lw * 0.8))
            p.setBrush(QColor(120, 132, 155, 95))
        elif estilo == "sombra":
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor(45, 52, 68, 205))
        else:
            p.setPen(QPen(QColor(66, 133, 244, 220), lw, Qt.PenStyle.SolidLine,
                          Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
            p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawPath(camino)
    elif estilo == "pictograma":
        trazos = [_circulo(J["cabeza"], 0.064),
                  _trazo_grueso([_mas(J["cintura"], (0, 1), 0.04), J["cuello"]], 0.15)]
        for lado, _s in _LADOS_FIG:
            trazos.append(_trazo_grueso([J[f"hombro_{lado}"], J[f"codo_{lado}"],
                                         J[f"mano_{lado}"]], 0.058))
            trazos.append(_trazo_grueso([J[f"cadera_{lado}"], J[f"rodilla_{lado}"],
                                         J[f"tobillo_{lado}"]], 0.072))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(52, 73, 94, 200))
        p.drawPath(_sin_huecos_chicos(_union_piezas(trazos)))
    elif estilo == "palitos":
        g = _grosor_linea(S, H, 0.014, 0.004, 0.02) / S
        p.setPen(QPen(QColor(40, 40, 46, 235), g, Qt.PenStyle.SolidLine,
                      Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawPath(_circulo(J["cabeza"], 0.056))
        pt = lambda k: QPointF(*J[k])  # noqa: E731
        p.drawPolyline([pt("nuca"), pt("cuello"), pt("cintura"), pt("pelvis")])
        for lado, _s in _LADOS_FIG:
            p.drawPolyline([pt("cuello"), pt(f"codo_{lado}"), pt(f"mano_{lado}")])
            p.drawPolyline([pt("pelvis"), pt(f"rodilla_{lado}"), pt(f"tobillo_{lado}")])
            if sk["vista"] in ("perfil", "tres_cuartos"):
                tob = J[f"tobillo_{lado}"]
                p.drawLine(pt(f"tobillo_{lado}"),
                           QPointF(*_mas(tob, _dir(sk["A"][f"l2_{lado}"] + 90), 0.05)))
        if sk["cara"]:
            cab = J["cabeza"]
            ang = sk["t"] + sk["c"]
            ojo = _mas(cab, (_math.cos(_math.radians(ang)), _math.sin(_math.radians(ang))), 0.056)
            p.drawLine(QPointF(*ojo), QPointF(*_mas(ojo, (_math.cos(_math.radians(ang - 15)),
                                                         _math.sin(_math.radians(ang - 15))),
                                                   0.03 * sk["cara"])))
    else:
        mani = estilo == "maniqui"
        borde = QColor(120, 90, 55, 230) if mani else QColor(80, 130, 210, 210)
        pluma = QPen(borde, lw * (1.0 if mani else 0.9), Qt.PenStyle.SolidLine,
                     Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin)
        for _n, q, capa, tipo in piezas:
            p.setPen(pluma)
            if mani:
                base = QColor(218, 194, 154) if tipo != "art" else QColor(198, 170, 126)
                if capa == "atras":
                    base = base.darker(118)
                p.setBrush(base)
            else:
                p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawPath(q)
        if not mani:      # líneas de construcción: eje de la espalda
            p.setPen(QPen(borde, lw * 0.6, Qt.PenStyle.DashLine))
            p.drawPolyline([QPointF(*J["pelvis"]), QPointF(*J["cintura"]),
                            QPointF(*J["cuello"]), QPointF(*J["nuca"])])
        _lineas_cara(p, sk, lw, QColor(150, 110, 70, 220) if mani else borde)
    p.restore()


def aplicar_angulo_figura(fig: dict, clave: str, valor: float) -> None:
    lo, hi = _LIMITES_FIG.get(clave, (-180, 180))
    fig.setdefault("pose", {})[clave] = round(max(lo, min(hi, _norm180(valor))), 2)


def _ik_dos_huesos(o: tuple, objetivo: tuple, L1: float, L2: float,
                   preferido: tuple) -> tuple[float, float]:
    """Cinemática inversa de 2 huesos (hombro→codo→mano). Devuelve los
    ángulos absolutos de los dos huesos; de las dos soluciones elige la
    que deja el codo (o la rodilla) más cerca de donde estaba, para que
    la pose cambie de a poco y no «salte» al otro lado."""
    dx, dy = objetivo[0] - o[0], objetivo[1] - o[1]
    d = max(abs(L1 - L2) + 1e-4, min(L1 + L2 - 1e-4, _math.hypot(dx, dy)))
    base = _angulo(dx, dy)
    cos_a = (L1 * L1 + d * d - L2 * L2) / (2 * L1 * d)
    alfa = _math.degrees(_math.acos(max(-1.0, min(1.0, cos_a))))
    mejor, dist = None, 1e9
    for a1 in (base - alfa, base + alfa):
        ex, ey = o[0] + L1 * _math.sin(_math.radians(a1)), o[1] + L1 * _math.cos(_math.radians(a1))
        a2 = _angulo(objetivo[0] - ex, objetivo[1] - ey)
        dd = _math.hypot(ex - preferido[0], ey - preferido[1])
        if dd < dist:
            mejor, dist = (a1, a2), dd
    return mejor


def _codo_preferido(J: dict, lado: str, perfil: bool, s: int) -> tuple:
    """Dónde «quiere» quedar el codo: donde está, pero si el brazo está
    casi estirado, hacia abajo y afuera (como un brazo real)."""
    h, c, m = J[f"hombro_{lado}"], J[f"codo_{lado}"], J[f"muneca_{lado}"]
    recto = abs(_norm180(_angulo(c[0] - h[0], c[1] - h[1]) - _angulo(m[0] - c[0], m[1] - c[1]))) < 12
    if recto:
        return (h[0] + (0.0 if perfil else s * 0.08), h[1] + 0.2)
    return c


def _rodilla_preferida(J: dict, lado: str, perfil: bool, s: int) -> tuple:
    """La rodilla se dobla hacia adelante (de perfil) o hacia afuera."""
    c, r, t = J[f"cadera_{lado}"], J[f"rodilla_{lado}"], J[f"tobillo_{lado}"]
    recto = abs(_norm180(_angulo(r[0] - c[0], r[1] - c[1]) - _angulo(t[0] - r[0], t[1] - r[1]))) < 12
    if recto:
        return (c[0] + (0.15 if perfil else s * 0.08), c[1] + 0.2)
    return r


def mover_articulacion_figura(fig: dict, nombre: str, x: float, y: float) -> None:
    """Posa la figura llevando una articulación al punto local (x, y).
    Codo, rodilla, cabeza y pecho giran su hueso; mano y pie arrastran
    todo el brazo o la pierna (cinemática inversa)."""
    pose = fig.setdefault("pose", {})
    sk = esqueleto_figura(fig)
    J, A, t = sk["J"], sk["A"], sk["t"]
    esc = pose.get("escorzo") or {}
    perfil = fig.get("vista") in ("perfil", "tres_cuartos")

    def largo(seg: str, lado: str) -> float:
        return _MF[seg] * float(esc.get(f"{seg}_{lado}", 1.0) or 1.0)
    if nombre == "cabeza":
        n = J["nuca"]
        aplicar_angulo_figura(fig, "cabeza", 180 - _angulo(x - n[0], y - n[1]) - t)
    elif nombre == "torso":
        ci = J["cintura"]
        aplicar_angulo_figura(fig, "torso", 180 - _angulo(x - ci[0], y - ci[1]))
    elif nombre.startswith(("codo_", "mano_", "rodilla_", "pie_")):
        parte, lado = nombre.split("_", 1)
        s = 1 if lado == "d" else -1
        if parte == "codo":
            h = J[f"hombro_{lado}"]
            aplicar_angulo_figura(fig, f"brazo_{lado}", _angulo(x - h[0], y - h[1]) + t)
        elif parte == "rodilla":
            c = J[f"cadera_{lado}"]
            aplicar_angulo_figura(fig, f"muslo_{lado}", _angulo(x - c[0], y - c[1]))
        elif parte == "mano":
            a1, a2 = _ik_dos_huesos(J[f"hombro_{lado}"], (x, y), largo("brazo", lado),
                                    largo("antebrazo", lado) + _MF["mano"] * 0.5,
                                    _codo_preferido(J, lado, perfil, s))
            aplicar_angulo_figura(fig, f"brazo_{lado}", a1 + t)
            aplicar_angulo_figura(fig, f"antebrazo_{lado}", a2 - a1)
        else:
            a1, a2 = _ik_dos_huesos(J[f"cadera_{lado}"], (x, y), largo("muslo", lado),
                                    largo("pierna", lado), _rodilla_preferida(J, lado, perfil, s))
            aplicar_angulo_figura(fig, f"muslo_{lado}", a1)
            aplicar_angulo_figura(fig, f"pierna_{lado}", a2 - a1)


# Puntos para posar: (nombre de la articulación, punto del esqueleto)
PUNTOS_POSE = (("cabeza", "cabeza"), ("torso", "cuello"),
               ("codo_d", "codo_d"), ("mano_d", "mano_d"),
               ("codo_i", "codo_i"), ("mano_i", "mano_i"),
               ("rodilla_d", "rodilla_d"), ("pie_d", "tobillo_d"),
               ("rodilla_i", "rodilla_i"), ("pie_i", "tobillo_i"))


# Esquinas para cambiar el tamaño: (nombre, esquina, esquina opuesta que queda fija)
ESQUINAS_ESCALA = (("escala_si", "topLeft", "bottomRight"), ("escala_sd", "topRight", "bottomLeft"),
                   ("escala_ii", "bottomLeft", "topRight"), ("escala", "bottomRight", "topLeft"))
_ESQUINA_OPUESTA = {n: op for n, _e, op in ESQUINAS_ESCALA}


def _base_local(obj: dict) -> float:
    """Punto más bajo de la figura u objeto (ya girado), en altos de
    figura desde su ancla: sirve para que no «flote» al cambiar de pose."""
    tr = QTransform()
    tr.rotate(float(obj.get("rot", 0) or 0))
    if obj.get("tipo") == "figura":
        return tr.map(camino_local_figura(obj)).boundingRect().bottom()
    asp = _aspecto_capa(obj)
    return tr.mapRect(QRectF(-asp / 2, -1, asp, 1)).bottom()


def aplicar_pose_figura(fig: dict, clave: str, mantener_suelo: bool = True) -> None:
    """Aplica una pose rápida. Mantiene los pies en el mismo suelo."""
    info = _POSES_FIG.get(clave)
    if info is None:
        return
    _k, _nombre, angulos, vista, extra = info
    antes = _base_local(fig) if mantener_suelo else None
    if fig.get("vista") == "arriba":
        antes = None
    elif vista == "perfil":
        fig["vista"] = "perfil"
    elif vista == "frontal" and fig.get("vista") == "perfil":
        fig["vista"] = "frente"
    fig["pose"] = {k: float(angulos.get(k, 0)) for k in ANGULOS_FIGURA}
    fig["pose_nombre"] = clave
    if extra.get("escorzo"):
        fig["pose"]["escorzo"] = dict(extra["escorzo"])
    if fig.get("vista") != "arriba":        # (desde arriba, el giro es hacia dónde mira)
        fig["rot"] = float(extra.get("rot", 0))
    ik = extra.get("ik_perfil") if fig.get("vista") == "perfil" and extra.get("ik_perfil") \
        else extra.get("ik")
    for nombre, (x, y) in (ik or {}).items():
        mover_articulacion_figura(fig, nombre, x, y)
    if antes is not None:
        try:
            fig["y"] = round(float(fig.get("y", 0.6)) + (antes - _base_local(fig))
                             * float(fig.get("alto", 0.5)), 4)
        except (TypeError, ValueError):
            pass


def cambiar_vista_figura(fig: dict, vista: str) -> None:
    if vista not in _VISTA_FIG:
        return
    if "arriba" in (vista, fig.get("vista")) and vista != fig.get("vista"):
        tr = QTransform()
        tr.rotate(float(fig.get("rot", 0) or 0))
        c0 = tr.map(camino_local_figura(fig)).boundingRect().center()
        try:
            rot = float(fig.get("rot", 0) or 0)
        except (TypeError, ValueError):
            rot = 0.0
        if vista == "arriba":
            # De frente → mira hacia abajo del cuadro; de espalda, hacia arriba
            giro = {"frente": 90.0, "tres_cuartos": 45.0, "espalda": -90.0}.get(
                fig.get("vista", "frente"), 0.0)
            giro = -giro if fig.get("espejo") else giro
            fig["giro_cenital"] = giro
            fig["rot"] = round(_norm180(rot + giro), 1)
        else:
            fig["rot"] = round(_norm180(rot - float(fig.pop("giro_cenital", 0) or 0)), 1)
        fig["vista"] = vista
        tr = QTransform()
        tr.rotate(float(fig.get("rot", 0) or 0))
        c1 = tr.map(camino_local_figura(fig)).boundingRect().center()
        try:
            a = float(fig.get("alto", 0.5))
            fig["y"] = round(float(fig.get("y", 0.6)) + (c0.y() - c1.y()) * a, 4)
            fig["x"] = round(float(fig.get("x", 0.5)) + (c0.x() - c1.x()) * a * 0.0, 4)
        except (TypeError, ValueError):
            pass
        return
    antes = _base_local(fig)
    fig["vista"] = vista
    try:
        fig["y"] = round(float(fig.get("y", 0.6)) + (antes - _base_local(fig))
                         * float(fig.get("alto", 0.5)), 4)
    except (TypeError, ValueError):
        pass


def figuras_para_plano(tamano: str, personas: int = 1, lado: str = "centro",
                       estilo: str = "", W: float = 16, H: float = 9,
                       vista: str = "", mira: int = 1) -> list[dict]:
    """Figuras encuadradas según el tamaño de plano (como las siluetas
    guía): una al centro o en un tercio, dos que se miran, tres…
    Con vista="perfil" quedan de lado («mira»: 1 a la derecha, −1 a la
    izquierda, para una sola persona al centro)."""
    if tamano in ("Plano detalle (PD)", "Inserto"):
        return []
    alto_rel, margen = _ENCUADRE_SILUETA.get(tamano, _ENCUADRE_SILUETA["Plano medio (PM)"])
    y_pelvis = margen + 0.478 * alto_rel
    if tamano == "Plano conjunto":
        personas = max(3, personas)
    if personas <= 1:
        xs = {"izquierda": [1 / 3], "derecha": [2 / 3]}.get(lado, [0.5])
        miradas = {"izquierda": [1], "derecha": [-1]}.get(lado, [0])
    elif personas == 2:
        xs, miradas = [1 / 3, 2 / 3], [1, -1]
    else:
        xs = [(i + 1) / (personas + 1) for i in range(personas)]
        miradas = [1 if i < personas // 2 else (-1 if i > (personas - 1) // 2 else 0)
                   for i in range(personas)]
    figs = []
    for x, m in zip(xs, miradas):
        if vista == "perfil":
            m = m or (1 if mira >= 0 else -1)
            figs.append(nueva_figura(x, y_pelvis, alto_rel, "perfil", m < 0, estilo))
            continue
        figs.append(nueva_figura(x, y_pelvis, alto_rel, "frente" if m == 0 else "tres_cuartos",
                                 m < 0, estilo))
    if tamano == "Sobre hombro":
        # El otro personaje de espalda, en primer término
        figs.append(nueva_figura(0.93, -0.06 + 0.478 * alto_rel * 1.3, alto_rel * 1.3,
                                 "espalda", False, estilo))
    return figs


# ── Objetos del decorado (dibujos vectoriales simples) ──
# Paleta por estilo: (relleno, línea, detalle)
_PALETA_OBJ = {
    "maniqui": ("#efe7d8", "#8a7355", "#a8916f"),
    "suave": ("#e1e5ec", "#8b93a3", "#a3aab8"),
    "sombra": ("#878e9b", "#4b5260", "#646b78"),
    "contorno": ("#ffffff", "#4f86ec", "#8fb0f0"),
    "construccion": (None, "#7aa0e0", "#a9c1ec"),
    "pictograma": ("#8e9bb0", None, "#eef1f5"),
    "palitos": ("#ffffff", "#3a3a40", "#6a6a70"),
}


def _suavizar_abierto(puntos: list) -> QPainterPath:
    """Curva abierta (Catmull-Rom) que pasa por todos los puntos."""
    q = QPainterPath()
    n = len(puntos)
    if n == 0:
        return q
    q.moveTo(*puntos[0])
    if n == 2:
        q.lineTo(*puntos[1])
        return q
    pts = [puntos[0]] + list(puntos) + [puntos[-1]]
    for i in range(1, n):
        p0, p1, p2, p3 = pts[i - 1], pts[i], pts[i + 1], pts[i + 2]
        c1 = (p1[0] + (p2[0] - p0[0]) / 6, p1[1] + (p2[1] - p0[1]) / 6)
        c2 = (p2[0] - (p3[0] - p1[0]) / 6, p2[1] - (p3[1] - p1[1]) / 6)
        q.cubicTo(c1[0], c1[1], c2[0], c2[1], p2[0], p2[1])
    return q


def _rect_rot(cx: float, cy: float, w: float, h: float, ang: float,
              r: float = 0.0) -> QPainterPath:
    q = QPainterPath()
    if r > 0:
        q.addRoundedRect(QRectF(-w / 2, -h / 2, w, h), r, r)
    else:
        q.addRect(QRectF(-w / 2, -h / 2, w, h))
    tr = QTransform()
    tr.translate(cx, cy)
    tr.rotate(ang)
    return tr.map(q)


def _union_circulos(circs: list, recorte: Optional[QRectF] = None) -> QPainterPath:
    q = _union_piezas([_circulo((x, y), r) for x, y, r in circs])
    if recorte is not None:
        caja = QPainterPath()
        caja.addRect(recorte)
        q = _op_caminos(q, caja, "interseccion")
    return q


def _tono(col: QColor, f: int) -> QColor:
    if f == 100:
        return QColor(col)
    return col.darker(f) if f > 100 else col.lighter(int(10000 / max(1, f)))


class _PintorObjeto:
    """Dibuja piezas de un objeto con la paleta del estilo, en
    coordenadas locales (x de −ancho/2 a +ancho/2, y de −1 a 0)."""

    def __init__(self, p: QPainter, estilo: str, lw: float):
        rel, lin, det = _PALETA_OBJ.get(estilo, _PALETA_OBJ["maniqui"])
        self.p = p
        self.rel = QColor(rel) if rel else None
        if self.rel is not None and estilo in ("contorno", "palitos"):
            self.rel.setAlpha(235)
        self.lin = QColor(lin) if lin else None
        self.det = QColor(det)
        self.lw = lw
        self.transparente = False        # True: los vidrios dejan ver lo de atrás
        self.ventanas: Optional[list] = None   # (al recolectar: los vidrios, en coord. locales)

    def _pluma(self, col: QColor, k: float = 1.0) -> QPen:
        return QPen(col, self.lw * k, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap,
                    Qt.PenJoinStyle.RoundJoin)

    def forma(self, q: QPainterPath, tono: int = 100) -> None:
        self.p.setBrush(_tono(self.rel, tono) if self.rel is not None else Qt.BrushStyle.NoBrush)
        self.p.setPen(self._pluma(self.lin) if self.lin is not None else Qt.PenStyle.NoPen)
        self.p.drawPath(q)

    def rect(self, x0, y0, x1, y1, r: float = 0.0, tono: int = 100) -> None:
        q = QPainterPath()
        rr = QRectF(QPointF(min(x0, x1), min(y0, y1)), QPointF(max(x0, x1), max(y0, y1)))
        if r > 0:
            q.addRoundedRect(rr, r, r)
        else:
            q.addRect(rr)
        self.forma(q, tono)

    def elipse(self, cx, cy, rx, ry, tono: int = 100, ang: float = 0.0) -> None:
        self.forma(_elipse_rot((cx, cy), rx, ry, ang), tono)

    def poli(self, pts, tono: int = 100) -> None:
        q = QPainterPath()
        q.moveTo(QPointF(*pts[0]))
        for pt in pts[1:]:
            q.lineTo(QPointF(*pt))
        q.closeSubpath()
        self.forma(q, tono)

    def linea(self, pts, k: float = 1.0) -> None:
        """Detalle (vetas, divisiones) en el color de detalle."""
        self.p.setPen(self._pluma(self.det, k * 0.8))
        self.p.setBrush(Qt.BrushStyle.NoBrush)
        self.p.drawPolyline([QPointF(*pt) for pt in pts])

    def trazo(self, pts, k: float = 1.0) -> None:
        """Línea estructural (marco de bicicleta, baranda)."""
        col = self.lin if self.lin is not None else _tono(self.rel, 115)
        self.p.setPen(self._pluma(col, k))
        self.p.setBrush(Qt.BrushStyle.NoBrush)
        self.p.drawPolyline([QPointF(*pt) for pt in pts])

    def anillo(self, cx, cy, r, k: float = 2.0) -> None:
        col = self.lin if self.lin is not None else _tono(self.rel, 115)
        self.p.setPen(self._pluma(col, k))
        self.p.setBrush(Qt.BrushStyle.NoBrush)
        self.p.drawEllipse(QPointF(cx, cy), r, r)

    def suave(self, pts, tono: int = 100) -> None:
        """Forma cerrada de contorno curvo que pasa por los puntos."""
        self.forma(_suavizar_cerrado(pts), tono)

    def curva(self, pts, k: float = 1.0, detalle: bool = False) -> None:
        """Línea curva abierta que pasa por los puntos."""
        if detalle or self.lin is None:
            col = self.det if detalle else _tono(self.rel, 115)
        else:
            col = self.lin
        self.p.setPen(self._pluma(col, k))
        self.p.setBrush(Qt.BrushStyle.NoBrush)
        self.p.drawPath(_suavizar_abierto(pts))

    def aro(self, cx, cy, r_ext, r_int, tono: int = 100) -> None:
        """Anillo relleno (asa de taza, neumático visto de lado…)."""
        q = QPainterPath()
        q.setFillRule(Qt.FillRule.OddEvenFill)
        q.addEllipse(QPointF(cx, cy), r_ext, r_ext)
        q.addEllipse(QPointF(cx, cy), r_int, r_int)
        self.forma(q, tono)

    def rueda(self, cx, cy, r) -> None:
        self.elipse(cx, cy, r, r, tono=175)
        self.elipse(cx, cy, r * 0.45, r * 0.45, tono=88)

    def grueso(self, pts, ancho: float, tono: int = 100, curvo: bool = True) -> None:
        """Trazo grueso con relleno (cola, tronco curvo, tobogán…)."""
        self.forma(_trazo_grueso(pts, ancho, curvo), tono)

    def contorno(self, cx, cy, rx, ry, k: float = 1.0, detalle: bool = True) -> None:
        col = self.det if detalle or self.lin is None else self.lin
        self.p.setPen(self._pluma(col, k))
        self.p.setBrush(Qt.BrushStyle.NoBrush)
        self.p.drawEllipse(QPointF(cx, cy), rx, ry)

    def linea_clara(self, pts, k: float = 1.0) -> None:
        """Trazo claro (tiza sobre pizarra, luz sobre pantalla)."""
        self.p.setPen(self._pluma(QColor(255, 255, 255, 230), k))
        self.p.setBrush(Qt.BrushStyle.NoBrush)
        self.p.drawPolyline([QPointF(*pt) for pt in pts])

    # ── Vidrios (ventanas de autos, casas, kioscos…) ──
    def ventana(self, q: QPainterPath, tono: int = 78) -> None:
        """Un vidrio. Normalmente se pinta como antes; con «transparente»
        (el objeto se dibuja en una capa propia) borra lo del objeto que
        quedó debajo y deja un vidrio suave: se ve lo que está detrás,
        como una persona sentada dentro del auto."""
        if self.ventanas is not None:
            self.ventanas.append(self.p.worldTransform().map(q))
        if not self.transparente:
            self.forma(q, tono)
            return
        self.p.save()
        self.p.setCompositionMode(QPainter.CompositionMode.CompositionMode_Clear)
        self.p.setPen(Qt.PenStyle.NoPen)
        self.p.setBrush(QColor(0, 0, 0, 255))
        self.p.drawPath(q)
        self.p.restore()
        vidrio = _tono(self.rel, tono) if self.rel is not None else QColor(190, 210, 228)
        vidrio.setAlpha(52)
        self.p.setBrush(vidrio)
        self.p.setPen(self._pluma(self.lin) if self.lin is not None else Qt.PenStyle.NoPen)
        self.p.drawPath(q)

    def ventana_rect(self, x0, y0, x1, y1, r: float = 0.0, tono: int = 78) -> None:
        q = QPainterPath()
        rr = QRectF(QPointF(min(x0, x1), min(y0, y1)), QPointF(max(x0, x1), max(y0, y1)))
        if r > 0:
            q.addRoundedRect(rr, r, r)
        else:
            q.addRect(rr)
        self.ventana(q, tono)

    def ventana_poli(self, pts, tono: int = 78) -> None:
        q = QPainterPath()
        q.moveTo(QPointF(*pts[0]))
        for pt in pts[1:]:
            q.lineTo(QPointF(*pt))
        q.closeSubpath()
        self.ventana(q, tono)

    def ventana_elipse(self, cx, cy, rx, ry, tono: int = 78) -> None:
        self.ventana(_elipse_rot((cx, cy), rx, ry, 0.0), tono)

    def ventana_suave(self, pts, tono: int = 78) -> None:
        self.ventana(_suavizar_cerrado(pts), tono)

    def texto(self, txt: str, cx: float, cy: float, alto: float,
              sobre_tono: Optional[int] = None, ancho_max: Optional[float] = None) -> None:
        """Texto centrado (letreros). Si va sobre una forma oscura, en blanco."""
        f = QFont("Arial")
        f.setBold(True)
        f.setPixelSize(100)
        q = QPainterPath()
        q.addText(0, 0, f, txt)
        br = q.boundingRect()
        if br.height() <= 0:
            return
        k = alto / br.height()
        if ancho_max is not None and br.width() * k > ancho_max:
            k = ancho_max / br.width()
        tr = QTransform()
        tr.translate(cx - br.center().x() * k, cy - br.center().y() * k)
        tr.scale(k, k)
        col = self.lin if self.lin is not None else self.det
        if sobre_tono is not None and self.rel is not None \
                and _tono(self.rel, sobre_tono).lightness() < 150:
            col = QColor("#ffffff")
        self.p.setPen(Qt.PenStyle.NoPen)
        self.p.setBrush(col)
        self.p.drawPath(tr.map(q))


