def _o_librero(d, A):
    x0, x1 = -A / 2, A / 2
    d.rect(x0, -1.0, x1, 0, tono=108)
    estantes = (-0.96, -0.73, -0.5, -0.27, -0.04)
    libros = ((0.06, 0.92), (0.05, 0.8), (0.07, 0.95), (0.04, 0.7), (0.06, 0.88),
              (0.05, 0.75), (0.08, 0.9))
    for k in range(4):
        y_top, y_bot = estantes[k], estantes[k + 1] - 0.02
        d.rect(x0 + 0.04, y_top, x1 - 0.04, y_bot, tono=125)
        x = x0 + 0.06
        j = k * 2
        while True:
            w, h = libros[j % len(libros)]
            if x + w > x1 - 0.06:
                break
            alto = (y_bot - y_top) * h
            d.rect(x, y_bot - alto, x + w, y_bot, tono=92 + (j * 13) % 28)
            x += w + 0.004
            j += 1


