def _o_auto(d, A):
    x0, x1 = -A / 2, A / 2
    c = QPainterPath()
    c.moveTo(x0 + 0.04, -0.2)
    c.lineTo(x0, -0.3)
    c.lineTo(x0 + 0.02, -0.5)
    c.quadTo(x0 + 0.05, -0.58, x0 + 0.35, -0.6)
    c.lineTo(x0 + 0.62, -0.62)
    c.quadTo(x0 + 0.8, -0.97, x0 + 1.05, -0.98)
    c.lineTo(x0 + 1.6, -0.98)
    c.quadTo(x0 + 1.75, -0.97, x0 + 2.05, -0.64)
    c.quadTo(x1 - 0.15, -0.6, x1 - 0.05, -0.52)
    c.quadTo(x1, -0.48, x1, -0.36)
    c.lineTo(x1 - 0.02, -0.2)
    c.closeSubpath()
    for cx in (x0 + 0.55, x1 - 0.55):
        d.elipse(cx, -0.2, 0.22, 0.22, tono=135)
    d.forma(c)
    v1 = QPainterPath()
    v1.moveTo(x0 + 0.72, -0.64)
    v1.quadTo(x0 + 0.86, -0.92, x0 + 1.06, -0.92)
    v1.lineTo(x0 + 1.24, -0.92)
    v1.lineTo(x0 + 1.24, -0.64)
    v1.closeSubpath()
    v2 = QPainterPath()
    v2.moveTo(x0 + 1.3, -0.64)
    v2.lineTo(x0 + 1.3, -0.92)
    v2.lineTo(x0 + 1.58, -0.92)
    v2.quadTo(x0 + 1.7, -0.9, x0 + 1.95, -0.64)
    v2.closeSubpath()
    d.ventana(v1)
    d.ventana(v2)
    d.linea([(x0 + 1.27, -0.6), (x0 + 1.27, -0.24)])
    d.linea([(x0 + 0.66, -0.58), (x0 + 0.7, -0.3)])
    d.linea([(x0 + 1.06, -0.52), (x0 + 1.16, -0.52)], k=1.8)
    d.linea([(x0 + 1.62, -0.52), (x0 + 1.72, -0.52)], k=1.8)
    d.elipse(x1 - 0.07, -0.44, 0.045, 0.035, tono=72)
    d.elipse(x0 + 0.04, -0.44, 0.03, 0.035, tono=140)
    for cx in (x0 + 0.55, x1 - 0.55):
        d.elipse(cx, -0.18, 0.18, 0.18, tono=175)
        d.elipse(cx, -0.18, 0.085, 0.085, tono=88)


def _o_bicicleta(d, A):
    R, B, S, Hd, F = (-0.55, -0.3), (-0.05, -0.3), (-0.18, -0.72), (0.38, -0.74), (0.55, -0.3)
    for cx in (R[0], F[0]):
        d.anillo(cx, -0.3, 0.29, k=2.4)
        d.anillo(cx, -0.3, 0.03, k=1.4)
    d.trazo([R, B, S, R], k=1.8)
    d.trazo([S, Hd, B], k=1.8)
    d.trazo([Hd, F], k=1.8)
    d.trazo([S, (-0.2, -0.8)], k=1.6)
    d.rect(-0.3, -0.84, -0.1, -0.79, r=0.02, tono=120)
    d.trazo([Hd, (0.34, -0.88), (0.47, -0.9)], k=1.8)
    d.anillo(B[0], B[1], 0.05, k=1.4)


