def _o_escalera(d, A):
    x0, x1 = -A / 2, A / 2
    n = 8
    alto_esc = 0.78
    pw, ph = A / n, alto_esc / n
    pts = [(x0, 0)]
    for i in range(n):
        x = x0 + i * pw
        pts += [(x, -(i + 1) * ph), (x + pw, -(i + 1) * ph)]
    pts += [(x1, 0)]
    d.poli(pts)
    for i in range(1, n):
        x = x0 + i * pw
        d.linea([(x, -i * ph), (x, 0)], k=0.6)
    d.trazo([(x0 + 0.05, -ph - 0.32), (x1 - pw * 0.5, -alto_esc - 0.22)], k=2.0)
    d.trazo([(x0 + 0.05, -ph), (x0 + 0.05, -ph - 0.32)], k=1.6)
    d.trazo([(x1 - pw * 0.5, -alto_esc), (x1 - pw * 0.5, -alto_esc - 0.22)], k=1.6)


