    for s in (1, -1):
        e = x0 if s == 1 else x1
        q = QPainterPath()
        q.moveTo(e, -0.97)
        q.lineTo(e + s * 0.38, -0.97)
        q.quadTo(e + s * 0.36, -0.68, e + s * 0.17, -0.5)
        q.quadTo(e + s * 0.2, -0.22, e + s * 0.34, -0.02)
        q.lineTo(e, -0.02)
        q.closeSubpath()
        d.forma(q, 100)
        for k in (0.08, 0.15):
            d.linea([(e + s * k, -0.92), (e + s * (k - 0.01), -0.55)])
            d.linea([(e + s * (k - 0.01), -0.45), (e + s * (k + 0.06), -0.06)])
        d.rect(min(e + s * 0.02, e + s * 0.2), -0.53, max(e + s * 0.02, e + s * 0.2), -0.47,
               r=0.02, tono=125)
    d.trazo([(x0, -0.98), (x1, -0.98)], k=1.8)


