def _o_tienda(d, A):
    x0, x1 = -A / 2, A / 2
    d.rect(x0, -1.0, x1, 0, tono=104)
    d.rect(x0, -1.0, x1, -0.82, tono=120)
    d.texto("TIENDA", 0, -0.91, 0.08, sobre_tono=120, ancho_max=A - 0.3)
    n = 7
    w = A / n
    for i in range(n):
        xa = x0 + i * w
        q = QPainterPath()
        q.moveTo(xa, -0.82)
        q.lineTo(xa + w, -0.82)
        q.lineTo(xa + w, -0.68)
        q.quadTo(xa + w / 2, -0.6, xa, -0.68)
        q.closeSubpath()
        d.forma(q, 92 if i % 2 else 126)
    d.ventana_rect(x0 + 0.08, -0.56, 0.16, -0.08)
    for x, h in ((-0.5, 0.12), (-0.35, 0.18), (-0.18, 0.1), (0.02, 0.15)):
        d.rect(x, -0.14 - h, x + 0.1, -0.14, r=0.01, tono=104)
    d.rect(x0 + 0.08, -0.15, 0.16, -0.12, tono=112)
    d.rect(0.28, -0.6, x1 - 0.08, 0, tono=112)
    d.ventana_rect(0.33, -0.54, x1 - 0.13, -0.2, tono=80)
    d.elipse(0.33, -0.3, 0.015, 0.015, tono=140)


