def _o_metro(d, A):
    x0, x1 = -A / 2, A / 2
    d.rect(x0, -1.0, x1, -0.12, r=0.08, tono=102)
    d.linea([(x0, -0.36), (x1, -0.36)], k=1.6)
    x = x0 + 0.25
    i = 0
    while x < x1 - 0.3:
        if i % 3 == 1:
            d.rect(x, -0.88, x + 0.42, -0.16, r=0.01, tono=110)
            d.ventana_rect(x + 0.04, -0.84, x + 0.19, -0.42)
            d.ventana_rect(x + 0.23, -0.84, x + 0.38, -0.42)
        else:
            d.ventana_rect(x, -0.84, x + 0.42, -0.5, r=0.02)
        x += 0.56
        i += 1
    for x in (x0 + 0.5, x0 + 0.85, x1 - 0.85, x1 - 0.5):
        d.rueda(x, -0.08, 0.08)


