def _o_agua(d, A):
    x0, x1 = -A / 2, A / 2
    pts = [(x0, 0)]
    n = 24
    for i in range(n + 1):
        x = x0 + A * i / n
        pts.append((x, -0.8 + 0.08 * _math.sin(i * 1.3)))
    pts.append((x1, 0))
    d.poli(pts, tono=88)
    for y, fase in ((-0.52, 0.5), (-0.26, 1.2)):
        x = x0 + 0.2
        while x < x1 - 0.3:
            d.curva([(x, y), (x + 0.1, y - 0.06), (x + 0.2, y), (x + 0.3, y - 0.06)], k=0.8,
                    detalle=True)
            x += 0.6 + fase * 0.1


