def _o_telon(d, A):
    x0, x1 = -A / 2, A / 2
    d.rect(x0, -0.12, x1, 0, tono=118)
    for k in range(1, 6):
        x = x0 + k * A / 6
        d.linea([(x, -0.12), (x, 0)], k=0.6)
    d.trazo([(x0, -0.12), (x1, -0.12)], k=1.4)
    for s in (1, -1):
        e = x0 if s == 1 else x1
        q = QPainterPath()
        q.moveTo(e, -0.9)
        q.lineTo(e + s * 0.62, -0.9)
        q.quadTo(e + s * 0.5, -0.55, e + s * 0.3, -0.48)
        q.quadTo(e + s * 0.38, -0.3, e + s * 0.46, -0.12)
        q.lineTo(e, -0.12)
        q.closeSubpath()
        d.forma(q, 118)
        for k in (0.1, 0.22, 0.34):
            d.linea([(e + s * k, -0.88), (e + s * (k - 0.02), -0.55)])
            d.linea([(e + s * (k - 0.02), -0.45), (e + s * (k + 0.05), -0.14)])
        d.rect(min(e + s * 0.02, e + s * 0.32), -0.5, max(e + s * 0.02, e + s * 0.32), -0.46,
               r=0.02, tono=140)
    d.rect(x0, -1.0, x1, -0.88, tono=126)
    n = 8
    for i in range(n):
        xa = x0 + i * A / n
        d.elipse(xa + A / n / 2, -0.88, A / n / 2, 0.04, tono=126)


def _o_butacas(d, A):
    x0 = -A / 2
    n = 4
    w = A / n
    for i in range(n):
        c = x0 + w / 2 + i * w
        d.rect(c - w * 0.42, -1.0, c + w * 0.42, -0.42, r=0.1, tono=108)
        d.rect(c - w * 0.4, -0.5, c + w * 0.4, -0.34, r=0.05, tono=100)
        d.rect(c - 0.04, -0.34, c + 0.04, 0, tono=130)
    for i in range(n + 1):
        x = x0 + i * w
        d.rect(x - 0.06, -0.62, x + 0.06, -0.3, r=0.03, tono=125)


