    pts = [(x0, -0.76), (x1 - 0.05, -1.0), (x1, -0.88), (x0 + 0.02, -0.66)]
    q.moveTo(*pts[0])
    for pt in pts[1:]:
        q.lineTo(*pt)
    q.closeSubpath()
    d.forma(q, 140)
    for k in range(5):
        t0, t1 = k / 5 + 0.03, k / 5 + 0.12
        a0 = (x0 + (x1 - 0.05 - x0) * t0, -0.76 - 0.24 * t0)
        a1 = (x0 + (x1 - 0.05 - x0) * t1, -0.76 - 0.24 * t1)
        d.poli([a0, a1, (a1[0] + 0.03, a1[1] + 0.11), (a0[0] + 0.03, a0[1] + 0.11)], tono=74)


