def _o_pelota(d, A):
    d.elipse(0, -0.5, 0.48, 0.48, tono=80)
    c = (0, -0.5)
    r = 0.15
    pts = [(c[0] + r * _math.sin(_math.radians(k * 72)), c[1] - r * _math.cos(_math.radians(k * 72)))
           for k in range(5)]
    d.poli(pts, tono=150)
    for k in range(5):
        a = _math.radians(k * 72)
        d.linea([pts[k], (c[0] + 0.33 * _math.sin(a), c[1] - 0.33 * _math.cos(a))], k=1.0)
        a2 = _math.radians(k * 72 + 36)
        q = QPainterPath()
        q.addEllipse(QPointF(c[0] + 0.47 * _math.sin(a2), c[1] - 0.47 * _math.cos(a2)), 0.11, 0.11)
        q = _op_caminos(q, _circulo(c, 0.48), "interseccion")
        d.forma(q, 150)


