    for k in range(1, 8):
        y = -0.95 + k * 0.95 / 8
        d.linea([(x0 + 0.05, y), (x1 - 0.05, y)], k=0.5)
    d.trazo([(x0 + 0.05, 0), (x0 + 0.05, -0.95), (x1 - 0.05, -0.95), (x1 - 0.05, 0)], k=3.0)


