def _o_paraguas(d, A):
    x0, x1 = -A / 2, A / 2
    d.trazo([(0, -0.95), (0, -0.1)], k=1.8)
    d.curva([(0, -0.12), (0.0, -0.03), (-0.07, 0.0), (-0.12, -0.06)], k=2.0)
    q = QPainterPath()
    q.moveTo(x0, -0.55)
    q.cubicTo(x0 + 0.1, -1.05, x1 - 0.1, -1.05, x1, -0.55)
    n = 4
    for i in range(n):
        xa = x1 - i * A / n
        xb = xa - A / n
        q.quadTo((xa + xb) / 2, -0.66, xb, -0.55)
    q.closeSubpath()
    d.forma(q, 112)
    for i in range(1, n):
        xb = x1 - i * A / n
        d.curva([(0, -0.92), (xb * 0.6, -0.82), (xb, -0.55)], k=0.8, detalle=True)


