def _o_revolver(d, A):
    x0, x1 = -A / 2, A / 2
    # Empuñadura inclinada hacia atrás
    d.suave([(x0 + 0.42, -0.6), (x0 + 0.64, -0.6), (x0 + 0.6, -0.3), (x0 + 0.46, -0.02),
             (x0 + 0.2, 0.0), (x0 + 0.12, -0.12), (x0 + 0.28, -0.42)], tono=112)
    d.linea([(x0 + 0.3, -0.42), (x0 + 0.22, -0.12)], k=0.8)
    d.linea([(x0 + 0.42, -0.45), (x0 + 0.34, -0.12)], k=0.8)
    # Armazón y tambor
    d.rect(x0 + 0.42, -0.92, x0 + 0.78, -0.58, r=0.04, tono=104)
    d.rect(x0 + 0.66, -1.0, x0 + 1.06, -0.56, r=0.08, tono=96)
    for y in (-0.88, -0.78, -0.68):
        d.linea([(x0 + 0.7, y), (x0 + 1.02, y)], k=0.7)
    # Cañón y mira
    d.rect(x0 + 1.02, -0.96, x1, -0.78, r=0.03, tono=104)
    d.rect(x1 - 0.1, -1.0, x1 - 0.04, -0.95, tono=120)
    # Martillo, guardamonte y gatillo
    d.poli([(x0 + 0.42, -0.9), (x0 + 0.3, -1.0), (x0 + 0.38, -1.0), (x0 + 0.5, -0.92)], tono=120)
    d.curva([(x0 + 0.62, -0.6), (x0 + 0.64, -0.42), (x0 + 0.8, -0.4), (x0 + 0.86, -0.58)], k=1.4)
    d.linea([(x0 + 0.74, -0.58), (x0 + 0.7, -0.46)], k=1.4)


