def _sin_tildes(txt: str) -> str:
    import unicodedata
    return "".join(c for c in unicodedata.normalize("NFKD", txt.lower())
                   if not unicodedata.combining(c))


def buscar_objetos_sb(texto: str) -> list[str]:
    """Claves de los objetos cuyo nombre, palabras o categoría contienen
    todas las palabras buscadas (sin importar tildes ni mayúsculas)."""
    partes = [p for p in _sin_tildes(texto).split() if p]
    if not partes:
        return []
    out = []
    for o in CATALOGO_OBJETOS_SB:
        hay = _sin_tildes(" ".join([o[1], o[7] if len(o) > 7 else "",
                                    _NOMBRE_CATEGORIA_SB.get(o[2], "")]))
        if all(p in hay for p in partes):
            out.append(o[0])
    return out


def objetos_de_categoria_sb(cat: str) -> list[str]:
    return [o[0] for o in CATALOGO_OBJETOS_SB if o[2] == cat]


def nuevo_objeto_sb(clase: str, x: float, y: float, alto: float, estilo: str = "") -> dict:
    return {"id": nuevo_id_corto(), "tipo": "objeto", "clase": clase,
            "x": round(x, 4), "y": round(y, 4), "alto": round(alto, 4), "rot": 0.0,
            "espejo": False,
            "estilo": estilo if estilo in _CLAVES_ESTILO_SILUETA else estilo_figuras_actual()}


def _aspecto_capa(obj: dict) -> float:
    if obj.get("tipo") == "imagen":
        try:
            return max(0.02, float(obj.get("aspecto", 1.0) or 1.0))
        except (TypeError, ValueError):
            return 1.0
    info = _OBJ_SB.get(obj.get("clase"))
    if info is not None and obj.get("vista") == "arriba" and obj.get("clase") in _ARRIBA_SB:
        return aspecto_arriba_sb(obj["clase"])
    return info[3] if info else 1.0


def camino_local_objeto(obj: dict) -> QPainterPath:
    q = QPainterPath()
    if obj.get("tipo") == "figura":
        return camino_local_figura(obj)
    asp = _aspecto_capa(obj)
    q.addRect(QRectF(-asp / 2, -1.0, asp, 1.0))
    return q


def dibujar_objeto_sb(p: QPainter, obj: dict, W: float, H: float) -> None:
    if obj.get("tipo") == "figura":
        dibujar_figura_sb(p, obj, W, H)
        return
    if obj.get("tipo") == "imagen":
        img = imagen_de_capa_sb(obj)
        if img is None:
            return
        asp = _aspecto_capa(obj)
        p.save()
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform, True)
        p.setTransform(transformada_objeto(obj, W, H), True)
        p.drawImage(QRectF(-asp / 2, -1.0, asp, 1.0), img)
        p.restore()
        return
    info = _OBJ_SB.get(obj.get("clase"))
    if info is None:
        return
    S = max(1e-3, float(obj.get("alto", 0.5) or 0.5)) * H
    p.save()
    p.setTransform(transformada_objeto(obj, W, H), True)
    lw = _grosor_linea(S, H, 0.0065, 0.0028, 0.01) / S
    if ventanas_transparentes_sb(obj):
        p.restore()
        _dibujar_con_vidrios_sb(p, obj, W, H, info, lw)
        return
    d = _PintorObjeto(p, obj.get("estilo") or "maniqui", lw)
    if not (obj.get("vista") == "arriba" and dibujar_arriba_sb(d, obj.get("clase"), _aspecto_capa(obj))):
        info[6](d, info[3])
    p.restore()


# ── Ventanas que dejan ver lo de atrás (autos, casas, kioscos…) ──
# El objeto se dibuja en una capa propia; sus vidrios borran lo del mismo
# objeto que quedó debajo, así se ve la persona (u otra capa) que está
# detrás: alguien sentado en el auto, asomado a la ventana de la casa.
_CACHE_VENTANAS_SB: dict = {}


def ventanas_objeto_sb(obj: dict) -> list:
    """Los vidrios del objeto (caminos en sus coordenadas locales)."""
    if obj.get("tipo") != "objeto" or obj.get("vista") == "arriba":
        return []
    clase = obj.get("clase")
    if clase in _CACHE_VENTANAS_SB:
        return _CACHE_VENTANAS_SB[clase]
    info = _OBJ_SB.get(clase)
    out: list = []
    if info is not None:
        img = QImage(4, 4, QImage.Format.Format_ARGB32_Premultiplied)
        img.fill(Qt.GlobalColor.transparent)
        q = QPainter(img)
        d = _PintorObjeto(q, "maniqui", 0.01)
        d.ventanas = out
        try:
            info[6](d, info[3])
        except Exception:
            out = []
        q.end()
    _CACHE_VENTANAS_SB[clase] = out
    return out


def ventanas_transparentes_sb(obj: dict) -> bool:
    return (obj.get("tipo") == "objeto" and not obj.get("ventanas_opacas")
            and obj.get("vista") != "arriba" and bool(ventanas_objeto_sb(obj)))


def punto_en_ventana_sb(obj: dict, x: float, y: float, W: float, H: float) -> bool:
    """¿El punto (px del cuadro) cae en un vidrio transparente del objeto?"""
    if not ventanas_transparentes_sb(obj):
        return False
    inv, ok = transformada_objeto(obj, W, H).inverted()
    if not ok:
        return False
    local = inv.map(QPointF(x, y))
    return any(v.contains(local) for v in ventanas_objeto_sb(obj))


def _dibujar_con_vidrios_sb(p: QPainter, obj: dict, W: float, H: float, info: tuple,
                            lw: float) -> None:
    A = info[3]
    total = transformada_objeto(obj, W, H) * p.worldTransform()
    m = 0.08
    caja = total.mapRect(QRectF(-A / 2 - m, -1.0 - m, A + 2 * m, 1.0 + 2 * m))
    dev = p.device()
    if dev is not None and dev.width() > 0 and dev.height() > 0:
        caja = caja.intersected(QRectF(0, 0, dev.width(), dev.height()))
    r = caja.toAlignedRect()
    if r.width() <= 0 or r.height() <= 0:
        return
    try:
        dpr = float(dev.devicePixelRatioF()) if dev is not None else 1.0
    except Exception:
        dpr = 1.0
    dpr = max(1.0, min(4.0, dpr))
    capa = QImage(max(1, int(r.width() * dpr) + 1), max(1, int(r.height() * dpr) + 1),
                  QImage.Format.Format_ARGB32_Premultiplied)
    capa.setDevicePixelRatio(dpr)
    capa.fill(Qt.GlobalColor.transparent)
    q = QPainter(capa)
    q.setRenderHint(QPainter.RenderHint.Antialiasing, True)
    q.translate(-r.x(), -r.y())
    q.setTransform(total, True)
    d = _PintorObjeto(q, obj.get("estilo") or "maniqui", lw)
    d.transparente = True
    try:
        info[6](d, A)
    finally:
        q.end()
    p.save()
    p.resetTransform()
    p.drawImage(QPointF(r.topLeft()), capa)
    p.restore()


def recorte_dentro_sb(c: dict, capas: list, W: float, H: float) -> Optional[QPainterPath]:
    """Si la persona está dentro de un auto, casa o kiosco del cuadro, la
    zona (en px del cuadro) donde se ve: sus vidrios."""
    cid = c.get("dentro_de")
    if not cid or c.get("tipo") != "figura":
        return None
    cont = next((x for x in capas or [] if x.get("id") == cid), None)
    if cont is None or not capa_visible(cont) or not ventanas_transparentes_sb(cont):
        return None
    q = QPainterPath()
    q.setFillRule(Qt.FillRule.WindingFill)
    for v in ventanas_objeto_sb(cont):
        q.addPath(v)
    return transformada_objeto(cont, W, H).map(q)


def puestos_ventanas_sb(obj: dict) -> list[tuple[float, float, float]]:
    """Lugares para poner personas dentro (x, y, alto del vidrio), en
    coordenadas locales: un vidrio ancho tiene dos o tres puestos. En los
    vehículos va primero el de adelante (el del conductor)."""
    info = _OBJ_SB.get(obj.get("clase"))
    de_lado = info is not None and info[2] == "vehiculos" and obj.get("clase") != "auto_frente"
    out = []
    for v in ventanas_objeto_sb(obj):
        b = v.boundingRect()
        if b.height() <= 0:
            continue
        # (de lado, cada ventana es una fila de asientos: una persona)
        n = 1 if de_lado else max(1, min(3, int(b.width() / (b.height() * 0.95))))
        for k in range(n):
            out.append((b.left() + b.width() * (k + 0.5) / n, b.center().y(), b.height(),
                        b.width() * b.height() / n))
    if info is not None and info[2] == "vehiculos":
        out.sort(key=lambda t: -t[0])
    else:                                     # las ventanas grandes primero
        out.sort(key=lambda t: (-round(t[3], 3), t[0]))
    return [t[:3] for t in out]


def dibujar_objetos_sb(p: QPainter, objs: list, W: float, H: float) -> None:
    """Figuras y objetos del cuadro, en orden (los últimos, adelante)."""
    for o in objs or []:
        try:
            dibujar_objeto_sb(p, o, W, H)
        except Exception:
            continue


