def medidas_arriba_sb(clase: str) -> tuple[float, float]:
    """(ancho, fondo) del objeto visto desde arriba, en metros."""
    info = _OBJ_SB.get(clase)
    ancho_frente = (info[3] * info[4] * 1.7) if info else 1.0
    forma = _ARRIBA_SB.get(clase)
    if forma is None:
        return max(0.05, ancho_frente), max(0.03, ancho_frente / max(0.2, info[3] if info else 1.0))
    _f, fondo, ancho = forma
    return max(0.05, ancho or ancho_frente), max(0.03, fondo)


def aspecto_arriba_sb(clase: str) -> float:
    if clase not in _ARRIBA_SB:
        info = _OBJ_SB.get(clase)
        return info[3] if info else 1.0
    w, d = medidas_arriba_sb(clase)
    return max(0.05, w / d)


def tiene_vista_arriba_sb(clase: str) -> bool:
    return clase in _OBJ_SB


# ── Dibujos desde arriba (d = _PintorObjeto, A = ancho / fondo) ──
def _ar_caja(d, A, k=""):
    L, R = -A / 2, A / 2
    d.rect(L, -1, R, 0, r=0.04)
    m_ = min(0.12, A * 0.12)
    d.rect(L + m_, -1 + 0.12, R - m_, -0.12, r=0.03, tono=108)


def _ar_caja_cinta(d, A, k=""):
    _ar_caja(d, A)
    d.linea([(0, -1), (0, 0)], k=2.2)


def _ar_regalo(d, A, k=""):
    L, R = -A / 2, A / 2
    d.rect(L, -1, R, 0, r=0.04)
    d.linea([(0, -1), (0, 0)], k=3.0)
    d.linea([(L, -0.5), (R, -0.5)], k=3.0)
    d.elipse(-0.12, -0.5, 0.12, 0.08, tono=86)
    d.elipse(0.12, -0.5, 0.12, 0.08, tono=86)


def _ar_mueble(d, A, k=""):
    L, R = -A / 2, A / 2
    d.rect(L, -1, R, 0, r=0.02)
    d.rect(L, -0.16, R, 0, tono=112)
    n = max(1, int(round(A / 1.2)))
    for i in range(1, n):
        x = L + A * i / n
        d.linea([(x, -1), (x, -0.16)])


def _ar_redondo(d, A, k=""):
    r = min(A, 1) / 2
    d.elipse(0, -0.5, A / 2, 0.5)
    d.contorno(0, -0.5, A * 0.32, 0.32, k=1.0)


def _ar_lampara(d, A, k=""):
    d.elipse(0, -0.5, A / 2, 0.5, tono=92)
    d.contorno(0, -0.5, A * 0.36, 0.36, k=0.8)
    d.elipse(0, -0.5, A * 0.14, 0.14, tono=80)
    d.contorno(0, -0.5, A * 0.06, 0.06, k=1.2, detalle=False)


def _ar_lampara_esc(d, A, k=""):
    d.elipse(-A * 0.25, -0.3, A * 0.22, 0.22, tono=110)
    d.trazo([(-A * 0.25, -0.3), (A * 0.1, -0.62)], k=2.2)
    d.elipse(A * 0.2, -0.66, A * 0.26, 0.3, tono=92)
    d.elipse(A * 0.2, -0.66, A * 0.1, 0.1, tono=80)


def _ar_vaso(d, A, k=""):
    d.elipse(0, -0.5, A * 0.48, 0.48, tono=96)
    d.contorno(0, -0.5, A * 0.4, 0.4, k=0.9, detalle=False)
    if k == "copa":
        d.contorno(0, -0.5, A * 0.12, 0.12, k=0.8)


def _ar_botella(d, A, k=""):
    d.elipse(0, -0.5, A * 0.48, 0.48, tono=108)
    d.elipse(0, -0.5, A * 0.2, 0.2, tono=125)
    d.contorno(0, -0.5, A * 0.34, 0.34, k=0.7)


def _ar_pelota(d, A, k=""):
    d.elipse(0, -0.5, A * 0.48, 0.48, tono=88)
    pts = [(_math.cos(_math.radians(-90 + i * 72)) * A * 0.17,
            -0.5 + _math.sin(_math.radians(-90 + i * 72)) * 0.17) for i in range(5)]
    d.poli(pts, tono=170)
    for x, y in pts:
        d.linea([(x, y), (x * 2.5, -0.5 + (y + 0.5) * 2.5)], k=0.9)


def _ar_globo(d, A, k=""):
    d.elipse(0, -0.5, A * 0.48, 0.48, tono=100)
    for rx in (0.16, 0.32):
        d.contorno(0, -0.5, A * rx, 0.46, k=0.7)
    d.linea([(-A * 0.47, -0.5), (A * 0.47, -0.5)], k=0.7)
    d.elipse(-A * 0.12, -0.6, A * 0.12, 0.08, tono=118)
    d.elipse(A * 0.16, -0.36, A * 0.1, 0.12, tono=118)


def _ar_escudo(d, A, k=""):
    d.elipse(0, -0.5, A * 0.48, 0.48, tono=108)
    d.contorno(0, -0.5, A * 0.38, 0.38, k=1.0)
    d.elipse(0, -0.5, A * 0.14, 0.14, tono=88)


def _ar_licuadora(d, A, k=""):
    d.rect(-A * 0.46, -0.96, A * 0.46, -0.04, r=0.12, tono=120)
