def _ar_florero(d, A, k=""):
    d.elipse(0, -0.5, A * 0.48, 0.48, tono=104)
    for i, (x, y) in enumerate(((0, -0.5), (-0.22, -0.4), (0.2, -0.62), (0.18, -0.32), (-0.16, -0.7))):
        d.elipse(x * A, y, A * 0.14, 0.14, tono=125 if i % 2 else 84)


def _ar_planta(d, A, k=""):
    d.elipse(0, -0.5, A * 0.3, 0.3, tono=90)
    for i in range(8):
        a = i * _math.pi / 4
        d.elipse(_math.cos(a) * A * 0.27, -0.5 + _math.sin(a) * 0.27, A * 0.2, 0.2, tono=104,
                 ang=_math.degrees(a))


def _ar_sofa(d, A, k=""):
    L, R = -A / 2, A / 2
    d.rect(L, -1, R, 0, r=0.12)
    d.rect(L, -1, R, -0.7, r=0.1, tono=110)
    brazo = min(0.26, A * 0.12)
    d.rect(L, -1, L + brazo, 0, r=0.08, tono=110)
    d.rect(R - brazo, -1, R, 0, r=0.08, tono=110)
    n = 3 if A > 1.6 else (2 if A > 1.1 else 1)
    for i in range(1, n):
        x = L + brazo + (A - 2 * brazo) * i / n
        d.linea([(x, -0.7), (x, -0.06)])


def _ar_sillon(d, A, k=""):
    _ar_sofa(d, A)


def _ar_silla(d, A, k=""):
    L, R = -A / 2, A / 2
    d.rect(L + 0.04, -0.82, R - 0.04, 0, r=0.06)
