def _ar_comedor(d, A, k=""):
    L, R = -A / 2, A / 2
    n = max(2, int(round(A / 0.45)) - 1)
    for i in range(n):
        x = L + 0.25 + (A - 0.5) * (i + 0.5) / n
        for y0, y1 in ((-1, -0.82), (-0.18, 0)):
            d.rect(x - 0.13, y0, x + 0.13, y1, r=0.03, tono=110)
    d.rect(L + 0.12, -0.8, R - 0.12, -0.2, r=0.03)


