def _ar_puerta(d, A, k=""):
    L, R = -A / 2, A / 2
    d.p.save()
    d.p.setBrush(Qt.BrushStyle.NoBrush)
    col = d.lin if d.lin is not None else _tono(d.rel, 115)
    d.p.setPen(QPen(col, d.lw * 0.8, Qt.PenStyle.DashLine))
    d.p.drawArc(QRectF(L - A, -1, 2 * A, 2), 0, 90 * 16)
    d.p.restore()
    d.rect(L, -1, L + 0.06, 0, tono=110)
    d.rect(L, -0.05, R, 0.04, tono=80)


def _ar_escalera_sube(d, A, k=""):
    """Desde arriba: los peldaños y la flecha hacia donde sube (+x)."""
    L, R = -A / 2, A / 2
    d.rect(L, -1, R, 0, tono=100)
    n = 15
    for i in range(1, n):
        x = L + (R - L) * i / n
        d.linea([(x, -1), (x, 0)], k=0.7)
    d.linea([(L + 0.15, -0.5), (R - 0.25, -0.5)], k=1.6)
    d.poli([(R - 0.08, -0.5), (R - 0.4, -0.72), (R - 0.4, -0.28)], tono=190)


def _ar_escalera_baja(d, A, k=""):
    """Desde arriba: el hueco (oscuro), los peldaños y la flecha hacia donde
    baja (+x)."""
    L, R = -A / 2, A / 2
    d.rect(L, -1, R, 0, tono=260)
    n = 15
    for i in range(1, n):
        x = L + (R - L) * i / n
        d.linea([(x, -0.92), (x, -0.08)], k=0.6)
    d.linea([(L + 0.15, -0.5), (R - 0.25, -0.5)], k=1.6)
    d.poli([(R - 0.08, -0.5), (R - 0.4, -0.72), (R - 0.4, -0.28)], tono=55)


def _ar_escalera(d, A, k=""):
    L, R = -A / 2, A / 2
    d.rect(L, -1, R, 0)
    n = 14
    for i in range(1, n):
        d.linea([(L, -1 + i / n), (R, -1 + i / n)])
    d.trazo([(0, -0.1), (0, -0.85)], k=1.2)
    d.poli([(0, -0.95), (-0.05 * A, -0.85), (0.05 * A, -0.85)], tono=80)


def _ar_alfombra(d, A, k=""):
    L, R = -A / 2, A / 2
    d.rect(L, -1, R, 0, r=0.04, tono=94)
    d.rect(L + 0.1, -0.88, R - 0.1, -0.12, r=0.03, tono=108)
    for i in range(int(A * 8)):
        x = L + 0.06 + i / 8
        d.linea([(x, 0), (x, 0.04)], k=0.6)
        d.linea([(x, -1), (x, -1.04)], k=0.6)


def _ar_ventilador(d, A, k=""):
    for i in range(4):
        a = i * 90 + 20
        d.elipse(_math.cos(_math.radians(a)) * A * 0.27, -0.5 + _math.sin(_math.radians(a)) * 0.27,
                 A * 0.22, 0.08, tono=106, ang=a)
    d.elipse(0, -0.5, A * 0.09, 0.09, tono=86)


def _ar_perchero(d, A, k=""):
    d.elipse(0, -0.5, A * 0.42, 0.42, tono=112)
    d.elipse(0, -0.5, A * 0.1, 0.1, tono=86)
    for i in range(6):
        a = _math.radians(i * 60)
        d.trazo([(0, -0.5), (_math.cos(a) * A * 0.32, -0.5 + _math.sin(a) * 0.32)], k=1.4)


def _ar_chimenea(d, A, k=""):
    L, R = -A / 2, A / 2
    d.rect(L, -1, R, 0, r=0.02, tono=96)
    d.rect(L + A * 0.2, -0.75, R - A * 0.2, -0.05, r=0.02, tono=70)
    d.rect(L - 0.06, -0.08, R + 0.06, 0.05, tono=112)


def _ar_olla(d, A, k=""):
    d.elipse(0, -0.5, A * 0.38, 0.38)
    d.contorno(0, -0.5, A * 0.3, 0.3)
    d.rect(-A * 0.5, -0.56, -A * 0.38, -0.44, r=0.03, tono=86)
    d.rect(A * 0.38, -0.56, A * 0.5, -0.44, r=0.03, tono=86)


def _ar_sarten(d, A, k=""):
    r = min(0.5, A * 0.3)
    d.elipse(-A / 2 + r, -0.5, r, 0.5 * (r / 0.5))
    d.contorno(-A / 2 + r, -0.5, r * 0.8, 0.4 * (r / 0.5))
    d.rect(-A / 2 + 2 * r, -0.56, A / 2, -0.44, r=0.04, tono=80)


def _ar_tetera(d, A, k=""):
    d.elipse(0, -0.5, A * 0.36, 0.36)
    d.elipse(0, -0.5, A * 0.1, 0.1, tono=86)
