def _ar_casa(d, A, k=""):
    L, R = -A / 2, A / 2
    d.poli([(L, -1), (R, -1), (R - 0.12, -0.5), (L + 0.12, -0.5)], tono=92)
    d.poli([(L, 0), (R, 0), (R - 0.12, -0.5), (L + 0.12, -0.5)], tono=106)
    d.poli([(L, -1), (L + 0.12, -0.5), (L, 0)], tono=99)
    d.poli([(R, -1), (R - 0.12, -0.5), (R, 0)], tono=99)
    d.trazo([(L + 0.12, -0.5), (R - 0.12, -0.5)], k=1.8)
    for i in range(1, 8):
        x = L + A * i / 8
        d.linea([(x, -0.97), (x, -0.53)], k=0.5)
        d.linea([(x, -0.03), (x, -0.47)], k=0.5)
    d.rect(R - A * 0.25, -0.86, R - A * 0.18, -0.72, tono=80)


