    d.rect(L, -0.95, R, -0.05, r=0.08)
    d.rect(L + A * 0.04, -0.82, R - A * 0.04, -0.18, r=0.04, tono=108)
    for i in range(1, 6):
        d.rect(L + A * i / 6 - 0.15, -0.62, L + A * i / 6 + 0.15, -0.38, r=0.03, tono=94)


