        mc.addAction("🔽  Bajar una capa\tCtrl+[", lambda: self.mover_capa(o["id"], -1))
        mc.addAction("⏬  Enviar al fondo\tCtrl+Mayús+[", lambda: self.mover_capa(o["id"], -999))
