    def _titulo_tab_capas(self) -> None:
        if hasattr(self, "_tabs_der") and self._tabs_der.widget(0) is self.panel_capas:
            self._tabs_der.setTabText(0, f"🗂 Capas ({len(self.lienzo.capas)})")

    def _elegir_herramienta(self, clave: str) -> None:
        self.lienzo.herramienta = clave
        self._marcar_herramienta(clave)
        self.lienzo.setFocus()

    def _marcar_herramienta(self, clave: str) -> None:
        b = self._botones_herr.get(clave)
        if b is not None:
            b.setChecked(True)
        self._actualizar_color()

    def _actualizar_color(self) -> None:
        b = getattr(self, "_b_color", None)
        if b is None:
            return
        clave = self.lienzo.herramienta
        nombre = _HERR_SB.get(clave, ("", "", ""))[2].split(" (")[0]
        if clave in _SIN_COLOR_SB:
            b.setEnabled(False)
            b.setIcon(icono_muestra_color(QColor(0, 0, 0, 0), px(72) * 2, px(22) * 2, "—"))
            b.setToolTip(f"«{nombre}» no usa color")
            return
        b.setEnabled(True)
        col = self.lienzo.color_herramienta()
        k = col.alphaF()                   # como se ve sobre el papel blanco
        visto = QColor(int(col.red() * k + 255 * (1 - k)), int(col.green() * k + 255 * (1 - k)),
                       int(col.blue() * k + 255 * (1 - k)))
        b.setIcon(icono_muestra_color(visto, px(72) * 2, px(22) * 2,
                                      nombre_color_sb(col.name()) if clave in
                                      ("marcador", "balde") else ""))
        b.setToolTip(f"Color de «{nombre}»: {nombre_color_sb(col.name())}. Clic para elegir "
                     "otro · Alt+clic en el cuadro toma un color del dibujo")

    def _menu_colores(self) -> None:
        """Grises de marcador y colores para la herramienta elegida."""
        lz = self.lienzo
        clave = lz.herramienta
        if clave in _SIN_COLOR_SB:
            return
        m = QMenu(self)
        cont = QWidget()
        g = QGridLayout(cont)
        g.setContentsMargins(px(8), px(6), px(8), px(6))
        g.setHorizontalSpacing(px(4))
        g.setVerticalSpacing(px(4))
        actual = lz.color_herramienta().name()

        def boton(hexa: str, nombre: str) -> QToolButton:
            b = QToolButton()
            b.setObjectName("sb_muestra")
            b.setIcon(icono_muestra_color(QColor(hexa), px(26) * 2, px(26) * 2))
            b.setIconSize(QSize(px(26), px(26)))
            b.setFixedSize(px(32), px(32))
            b.setToolTip(nombre)
            b.setCheckable(True)
            b.setChecked(QColor(hexa).name() == actual)
            b.clicked.connect(lambda _=False, h=hexa: (m.close(), lz.poner_color(h)))
            return b
        t1 = QLabel("Grises de marcador (al repasar se oscurecen)")
        t1.setStyleSheet("color: #8fa1b8; font-size: 8.5pt;")
        g.addWidget(t1, 0, 0, 1, 6)
        for i, (h, n) in enumerate(PALETA_GRISES_SB):
            g.addWidget(boton(h, n), 1, i)
        t2 = QLabel("Colores")
        t2.setStyleSheet("color: #8fa1b8; font-size: 8.5pt;")
        g.addWidget(t2, 2, 0, 1, 6)
        for i, (h, n) in enumerate(PALETA_COLORES_SB):
            g.addWidget(boton(h, n), 3 + i // 6, i % 6)
        cont.setStyleSheet(escalar_qss(
            "QToolButton#sb_muestra { background: transparent; border: 2px solid transparent; "
            "border-radius: 7px; padding: 0px; }"
            "QToolButton#sb_muestra:hover { border-color: #4a596e; }"
            "QToolButton#sb_muestra:checked { border-color: #ff8c1a; }"))
        acc = QWidgetAction(m)
        acc.setDefaultWidget(cont)
        m.addAction(acc)
        m.addSeparator()
        m.addAction("🎨  Otro color…", self._otro_color)
        m.addAction("↺  Color original de la herramienta", lambda: lz.poner_color(None))
        lz._exec_menu(m, self._b_color.mapToGlobal(QPoint(self._b_color.width() + px(4), 0)))

    def _otro_color(self) -> None:
        from PySide6.QtWidgets import QColorDialog
        col = QColorDialog.getColor(self.lienzo.color_herramienta(), self, "Color")
        if col.isValid():
            self.lienzo.poner_color(col)

    def _toggle_guias(self, *_):
        self.lienzo.ver_cebolla = self._chk_cebolla.isChecked()
        self.lienzo.ver_tercios = self._acc_tercios.isChecked()
        self.lienzo.ver_zona_segura = self._acc_segura.isChecked()
        self.lienzo.ver_lentes = self._acc_lentes.isChecked()
        self.lienzo.update()

    def _alternar_animacion(self, si: bool) -> None:
        """Muestra u oculta la línea de tiempo de la animación."""
        lz = self.lienzo
        lz.animando = bool(si)
        if not si:
            self.panel_anim.detener()
            lz.elegir_camara(False)
            lz.poner_tiempo(0.0)
        self.panel_anim.setVisible(bool(si))
        if si:
            if lz.herramienta not in ("posar",):
                self._elegir_herramienta("posar")
            self.panel_anim.refrescar()
        lz.update()

    def _ver_cuadro_animado(self) -> None:
        self._guardar_cuadro_actual()
        pl = self._plano(self._id_editando)
        if pl is not None:
            PresentacionStoryboard(self.doc, [pl], 0, parent=self).exec()

    def _poner_perspectiva(self, tipo: int) -> None:
        self.lienzo.poner_perspectiva(tipo)
        if tipo:
            self._elegir_herramienta("posar")

    def _cambio_opacidad(self, v_: int) -> None:
        self.lienzo.opacidad_ref = v_ / 100
        self.lienzo.modificado = True
        self.lienzo.update()

    def _alternar_vista(self) -> None:
        if self._stack.currentIndex() == 0:
            lista = self.cuadros()
            if not lista:
                pl = self.nuevo_cuadro()
                if pl is None:
                    return
                lista = self.cuadros()
            pid = self._sel_id if self._plano(self._sel_id) else lista[0]["id"]
            self.abrir_editor(pid)
        else:
            self._mostrar_cuadricula()

    def _mostrar_cuadricula(self) -> None:
        if self._stack.currentIndex() == 1:
            self._dejar_3d()
        self._guardar_cuadro_actual()
        self._id_editando = ""
        self._stack.setCurrentIndex(0)
        self._politica_stack()
        self._b_vista.setText(TEXTO_ABRIR_CUADRO_SB)
        self._refrescar_cuadricula()
        t = getattr(self, "_tarjetas", {}).get(self._sel_id)
        if t is not None:
            QTimer.singleShot(0, lambda: self._scroll.ensureWidgetVisible(t))

    def abrir_editor(self, pid: str, guardar: bool = True, vista: str = "") -> None:
        """El cuadro «pid», en 3D (por su cámara o como se miraba el anterior;
        «vista»: «camara», «arriba» o «maqueta»)."""
        if self._stack.currentIndex() == 1 and self._id_editando:
            self._dejar_3d()           # el cuadro que se deja queda como estaba
        if guardar:
            self._guardar_cuadro_actual()
        pl = self._plano(pid)
        if pl is None:
            return
        self._sel_id = self._id_editando = pid
        self._stack.setCurrentIndex(1)
        self._politica_stack()
        self._b_vista.setText("▦ Cuadrícula")
        w, h = tamano_lienzo_sb(formato_storyboard(self.doc))
        self.lienzo.cargar(w, h, qimage_desde_b64(pl.get("sb_foto", "")),
                           qimage_desde_b64(pl.get("sb_guia", "")), None,
                           pl.get("sb_anot") or [], pl.get("sb_guia_conf"),
                           capas=capas_de_plano(pl),
                           foto_visible=not pl.get("sb_foto_oculta"),
                           anot_visible=not pl.get("sb_anot_oculto"),
                           cam_claves=pl.get("sb_camara_claves"))
        self.lienzo.duracion = duracion_animatic_sb(pl)
        if hasattr(self, "panel_anim"):
            self.panel_anim.detener()
            self.panel_anim.refrescar()
        self.lienzo.tamano_plano = str(pl.get("tamano", "") or "")
        self.lienzo.persp = perspectiva_valida(pl.get("sb_persp"))
        self.lienzo.lente_mm = mm_de_lente(pl.get("lente", ""))
        if hasattr(self, "_acc_persp"):
            self._acc_persp[self.lienzo.persp["tipo"] if self.lienzo.persp else 0].setChecked(True)
        self.lienzo.sugerencias_nombres = personajes_sugeridos_sb(
            self.doc, int(pl.get("escena", 0) or 0))
        try:
            op = float(pl.get("sb_ref_opacidad", 1.0))
        except (TypeError, ValueError):
            op = 1.0
        self._sl_ref.blockSignals(True)
        self._sl_ref.setValue(int(op * 100))
        self._sl_ref.blockSignals(False)
        self.lienzo.opacidad_ref = op
        lista = self.cuadros()
        i = next((k for k, p in enumerate(lista) if p is pl), -1)
        self.lienzo.cebolla = None
        self.lienzo.ocultas_3d = set()
        self._cargar_datos(pl)
        self._entrar_3d(pl, vista)
        self._llenar_tira()
        self._actualizar_estado()

    def _cargar_datos(self, pl: dict) -> None:
        self._llenando = True
        self._cb_escena.clear()
        for e in self._escenas:
            num, enc = self._etiquetas.get(e["n"], (str(e["n"]), e["encabezado"]))
            self._cb_escena.addItem(f"{num}. {enc}", e["n"])
        i = self._cb_escena.findData(int(pl.get("escena", 0) or 0))
        self._cb_escena.setCurrentIndex(max(0, i))
        self._ed_num.setText(str(pl.get("numero", "") or ""))
        self._ed_dur.setText(str(pl.get("duracion", "") or ""))
        self._ed_dur.poner_sugerida(duracion_sugerida_sb(pl))
        self._ed_lente.setText(str(pl.get("lente", "") or ""))
        self._cb_tam.setCurrentText(str(pl.get("tamano", "") or ""))
        self._cb_ang.setCurrentText(str(pl.get("angulo", "") or ""))
        self._cb_mov.setCurrentText(str(pl.get("movimiento", "") or ""))
        self._cb_anim.setCurrentIndex(max(0, self._cb_anim.findData(str(pl.get("sb_anim") or ""))))
        if hasattr(self, "panel_anim"):
            self.panel_anim.mostrar_duracion(self._ed_dur.value(), duracion_sugerida_sb(pl))
        self._tx_accion.setPlainText(str(pl.get("descripcion", "") or ""))
        self._tx_dialogo.setPlainText(str(pl.get("dialogo", "") or ""))
        self._tx_notas.setPlainText(str(pl.get("notas", "") or ""))
        self._chk_hecho.setChecked(bool(pl.get("hecho")))
        self._llenar_revision(pl)
        self._tx_guion.setPlainText(self._texto_guion_escena(int(pl.get("escena", 0) or 0)))
        self._actualizar_titulo_cuadro(pl)
        self._llenando = False

    def _actualizar_titulo_cuadro(self, pl: dict) -> None:
        lista = self.cuadros()
        i = next((k for k, p in enumerate(lista) if p is pl), -1)
        self._lbl_cuadro.setText(f"{self._etiqueta_cuadro(pl)}\n"
                                 f"Cuadro {i + 1} de {len(lista)}")
        avisos = self._avisos_de(pl.get("id", ""))
        self._lbl_aviso.setText("\n\n".join("⚠ " + a for a in avisos))
        self._lbl_aviso.setVisible(bool(avisos))

    def _texto_guion_escena(self, n: int) -> str:
        e = next((x for x in self._escenas if x["n"] == n), None)
        if e is None:
            return ""
        out = []
        for b in self.doc.bloques[e["desde"]:e["hasta"]]:
            t = (b.texto or "").strip()
            if not t:
                continue
            if b.elem == Elem.PERSONAJE:
                out.append("          " + t.upper())
            elif b.elem in (Elem.DIALOGO, Elem.PARENTESIS):
                out.append("     " + t)
            else:
                out.append(t)
        return "\n".join(out)

    def _duracion_editada(self, *_):
        """Cambió la duración (en la pestaña Plano, en la barra de animación
        o arrastrando el final de la línea de tiempo)."""
        if self._llenando:
            return
        self._estirar_al_cambiar = True
        try:
            self._datos_cambiados()
        finally:
            self._estirar_al_cambiar = False

    def _duracion_desde_panel(self, v: float) -> None:
        self._ed_dur.setValue(max(0.0, float(v)))

    def _datos_cambiados(self, *_):
        if self._llenando:
            return
        pl = self._plano(self._id_editando)
        if pl is None:
            return
        if getattr(self, "_modo", "2d") == "3d":
            QTimer.singleShot(0, self.editor3d.reconstruir)
        d0 = float(self.lienzo.duracion or 0)
        pl.update({
            "numero": self._ed_num.text().strip(),
            "duracion": self._ed_dur.valor_texto(),
            "lente": self._ed_lente.text().strip(),
            "tamano": self._cb_tam.currentText().strip(),
            "angulo": self._cb_ang.currentText().strip(),
            "movimiento": self._cb_mov.currentText().strip(),
            "descripcion": self._tx_accion.toPlainText().strip(),
            "dialogo": self._tx_dialogo.toPlainText().strip(),
            "notas": self._tx_notas.toPlainText().strip(),
            "hecho": self._chk_hecho.isChecked(),
        })
        anim = self._cb_anim.currentData() or ""
        if anim:
            pl["sb_anim"] = anim
        else:
            pl.pop("sb_anim", None)
        sug = duracion_sugerida_sb(pl)
        self._ed_dur.poner_sugerida(sug)
        self._actualizar_titulo_cuadro(pl)
        self.lienzo.tamano_plano = pl.get("tamano", "")
        self.lienzo.lente_mm = mm_de_lente(pl.get("lente", ""))
        self.lienzo.duracion = duracion_animatic_sb(pl)
        if getattr(self, "_estirar_al_cambiar", False) and d0 > 0 \
                and abs(self.lienzo.duracion - d0) > 1e-3 and plano_animado_3d(pl):
            escalar_claves_3d(pl, self.lienzo.duracion / d0)     # (la animación 3D dura lo mismo que el plano)
        if self.lienzo.tiempo > self.lienzo.duracion:
            self.lienzo.poner_tiempo(self.lienzo.duracion)
        ed = self.editor3d
        if ed.n and ed.t > self.lienzo.duracion:
            ed.poner_tiempo(self.lienzo.duracion)
        if ed.n:
            ed._refrescar_linea()
        self.panel_anim.mostrar_duracion(self._ed_dur.value(), sug)
        self.panel_anim.refrescar()
        self._actualizar_estado()
        self.lienzo.update()
        self._marcar()

    # ── Revisión en equipo ──
    def _llenar_revision(self, pl: dict) -> None:
        b = self._b_rev.get(estado_revision_sb(pl))
        if b is not None:
            b.setChecked(True)
        self._lista_com.clear()
        coms = comentarios_sb(pl)
        for c in coms:
            hecho = bool(c.get("resuelto"))
            it = QListWidgetItem(f"{'✓ ' if hecho else ''}{c.get('autor', '')} · "
                                 f"{_fecha_corta(c.get('fecha', ''))}\n{c.get('texto', '')}")
            it.setData(Qt.ItemDataRole.UserRole, c.get("id"))
            if hecho:
                it.setForeground(QColor("#6c7a8f"))
            it.setToolTip("Doble clic: marcar como resuelto o pendiente · clic derecho: más")
            self._lista_com.addItem(it)
        if not coms:
            it = QListWidgetItem("Sin comentarios. Escribe abajo lo que hay que cambiar o "
                                 "lo que está bien.")
            it.setFlags(Qt.ItemFlag.NoItemFlags)
            it.setForeground(QColor("#5d6c82"))
            self._lista_com.addItem(it)
        self._lbl_autor.setText(f"Comentas como <a href='#' style='color:#ffb43a'>"
                                f"{html.escape(autor_revision_sb())}</a> (clic para cambiarlo)")

    def _poner_revision(self, clave: str) -> None:
        pl = self._plano(self._id_editando)
        if pl is None:
            return
        if clave:
            pl["sb_revision"] = clave
        else:
            pl.pop("sb_revision", None)
        self._marcar()

    def _agregar_comentario(self) -> None:
        pl = self._plano(self._id_editando)
        txt = self._ed_com.text().strip()
        if pl is None or not txt:
            return
        pl.setdefault("sb_comentarios", []).append({
            "id": nuevo_id_corto(), "autor": autor_revision_sb(), "texto": txt[:1000],
            "fecha": datetime.now().strftime("%Y-%m-%d %H:%M"), "resuelto": False})
        self._ed_com.clear()
        self._llenar_revision(pl)
        self._lista_com.scrollToBottom()
        self._marcar()

    def _comentario_de_fila(self, fila: int) -> tuple[Optional[dict], Optional[dict]]:
        pl = self._plano(self._id_editando)
        it = self._lista_com.item(fila) if fila >= 0 else None
        if pl is None or it is None:
            return pl, None
        cid = it.data(Qt.ItemDataRole.UserRole)
        return pl, next((c for c in pl.get("sb_comentarios") or [] if c.get("id") == cid), None)

    def _alternar_resuelto(self, fila: int) -> None:
        pl, c = self._comentario_de_fila(fila)
        if c is None:
            return
        c["resuelto"] = not c.get("resuelto")
        self._llenar_revision(pl)
        self._marcar()

    def _menu_comentario(self, pos) -> None:
        fila = self._lista_com.indexAt(pos).row()
        pl, c = self._comentario_de_fila(fila)
        if c is None:
            return
        m = QMenu(self)
        m.addAction("↺  Volver a pendiente" if c.get("resuelto") else "✓  Marcar como resuelto",
                    lambda: self._alternar_resuelto(fila))
        m.addAction("✎  Editar…", lambda: self._editar_comentario(fila))
        m.addAction("🗑  Eliminar", lambda: self._borrar_comentario(fila))
        self.lienzo._exec_menu(m, self._lista_com.viewport().mapToGlobal(pos))

    def _editar_comentario(self, fila: int) -> None:
        pl, c = self._comentario_de_fila(fila)
        if c is None:
            return
        txt, ok = QInputDialog.getMultiLineText(self, "Comentario", "Comentario:",
                                                str(c.get("texto", "")))
        if ok and txt.strip():
            c["texto"] = txt.strip()[:1000]
            self._llenar_revision(pl)
            self._marcar()

    def _borrar_comentario(self, fila: int) -> None:
        pl, c = self._comentario_de_fila(fila)
        if c is None:
            return
        pl["sb_comentarios"] = [x for x in pl.get("sb_comentarios") or [] if x is not c]
        if not pl["sb_comentarios"]:
            pl.pop("sb_comentarios")
        self._llenar_revision(pl)
        self._marcar()

    def _cambiar_autor(self) -> None:
        txt, ok = QInputDialog.getText(self, "Firmar los comentarios",
                                       "Tu nombre (así aparecen tus comentarios):",
                                       QLineEdit.EchoMode.Normal, autor_revision_sb())
        if ok and txt.strip():
            settings_app().setValue("sb_autor_revision", txt.strip()[:40])
            pl = self._plano(self._id_editando)
            if pl is not None:
                self._llenar_revision(pl)

    def _ver_revision(self, clave: str) -> None:
        i = self._cb_rev.findData(clave)
        if i >= 0:
            self._cb_rev.setCurrentIndex(i)
        if self._stack.currentIndex() != 0:
            self._mostrar_cuadricula()

    def _limpiar_revision(self) -> None:
        self._guardar_cuadro_actual()
        lista = self.cuadros()
        if not any(estado_revision_sb(x) or comentarios_sb(x) for x in lista):
            QMessageBox.information(self, "Revisión", "Estos cuadros no tienen marcas de revisión.")
            return
        r = QMessageBox.question(
            self, "Revisión", f"¿Quitar los estados y comentarios de {len(lista)} cuadro(s)?",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No)
        if r != QMessageBox.StandardButton.Yes:
            return
        for x in lista:
            x.pop("sb_revision", None)
            x.pop("sb_comentarios", None)
        self._marcar()
        pl = self._plano(self._id_editando)
        if pl is not None and self._stack.currentIndex() == 1:
            self._llenar_revision(pl)
        else:
            self._refrescar_cuadricula()

    def _exportar_revision(self) -> None:
        self._guardar_cuadro_actual()
        lista = self.cuadros()
        if not lista:
            QMessageBox.information(self, "Storyboard", "Todavía no hay cuadros.")
            return
        base = (getattr(self.doc, "titulo", "") or "guion").strip() or "guion"
        ruta, _ = QFileDialog.getSaveFileName(
            self, "PDF de revisión",
            str(Path(ruta_ultima_carpeta()) / _nombre_archivo_seguro(f"{base} - revisión storyboard.pdf")),
            "PDF (*.pdf)")
        if not ruta:
            return
        if not ruta.lower().endswith(".pdf"):
            ruta += ".pdf"
        try:
            n = exportar_revision_pdf(self.doc, ruta, lista, self.avisos_180())
            QMessageBox.information(self, "Revisión",
                                    f"✅ PDF de revisión guardado ({n} páginas): {Path(ruta).name}")
        except Exception as e:
            QMessageBox.critical(self, "Revisión", f"No se pudo exportar:\n{e}")

    def _duracion_auto(self, que: str) -> int:
        """Pone la duración calculada según el diálogo y la acción."""
        self._guardar_cuadro_actual()
        if que == "este":
            pls = [x for x in [self._plano(self._id_editando)] if x is not None]
        elif que == "faltan":
            pls = [x for x in self.cuadros() if not str(x.get("duracion") or "").strip()]
        else:
            pls = self.cuadros()
        for x in pls:
            x["duracion"] = texto_duracion(duracion_sugerida_sb(x))
        if pls:
            self._marcar()
        pl = self._plano(self._id_editando)
        if pl is not None:
            self._llenando = True
            self._ed_dur.setText(str(pl.get("duracion", "") or ""))
            self._llenando = False
            self._actualizar_titulo_cuadro(pl)
        self._actualizar_estado()
        if que != "este":
            QMessageBox.information(self, "Duraciones",
                                    f"⏱ {len(pls)} cuadro(s) con su duración calculada."
                                    if pls else "Todos los cuadros ya tenían duración.")
        return len(pls)

    def _cambio_escena_cuadro(self, *_):
        if self._llenando:
            return
        pl = self._plano(self._id_editando)
        n = self._cb_escena.currentData()
        if pl is None or n is None or int(pl.get("escena", 0) or 0) == n:
            return
        self._guardar_cuadro_actual()
        self._dejar_3d()
        vieja = int(pl.get("escena", 0) or 0)
        quitar_camara_3d(self.doc, pl)                # (en la escena nueva tendrá otra)
        self.doc.planos.remove(pl)
        pl["escena"] = n
        _insertar_plano_en_orden(self.doc, pl)
        for x in (vieja, n):
            renumerar_escena_sb(self.doc, x)
        self._marcar()
        self.abrir_editor(pl["id"], guardar=False)

    def _lienzo_cambiado(self) -> None:
        self._marcar()

    def _guardar_cuadro_actual(self) -> None:
        """Pasa el lienzo al plano (solo si cambió algo)."""
        pl = self._plano(self._id_editando)
        if pl is None or not getattr(self, "lienzo", None) or not self.lienzo.modificado:
            return
        lz = self.lienzo
        if lz.foto is not None:
            plano_blanco = QImage(lz.foto.size(), QImage.Format.Format_RGB32)
            plano_blanco.fill(QColor("#ffffff"))
            pp = QPainter(plano_blanco)
            pp.drawImage(0, 0, lz.foto)
            pp.end()
            pl["sb_foto"] = b64_desde_qimage(plano_blanco, "JPEG", 85)
        else:
            pl.pop("sb_foto", None)
        if lz.guia is not None and not lz._esta_vacia(lz.guia):
            pl["sb_guia"] = b64_desde_qimage(lz.guia, "PNG")
            if lz.guia_conf:
                pl["sb_guia_conf"] = dict(lz.guia_conf)
            else:
                pl.pop("sb_guia_conf", None)
        else:
            pl.pop("sb_guia", None)
            pl.pop("sb_guia_conf", None)
        pl.pop("sb_dibujo", None)          # (formato anterior: ahora todo va en capas)
        pl.pop("sb_obj", None)
        if lz.capas_con_contenido():
            pl["sb_capas"] = lz.capas_serializadas()
        else:
            pl.pop("sb_capas", None)
        if lz.anot:
            pl["sb_anot"] = [dict(a) for a in lz.anot]
        else:
            pl.pop("sb_anot", None)
        for clave, oculto in (("sb_foto_oculta", not lz.foto_visible),
                              ("sb_anot_oculto", not lz.anot_visible)):
            if oculto:
                pl[clave] = True
            else:
                pl.pop(clave, None)
        pl["sb_ref_opacidad"] = round(lz.opacidad_ref, 2)
        if lz.persp:
            pl["sb_persp"] = {"tipo": lz.persp["tipo"], "pf": [list(q) for q in lz.persp["pf"]]}
        else:
            pl.pop("sb_persp", None)
        if lz.cam_claves:
            pl["sb_camara_claves"] = _copy.deepcopy(lz.cam_claves)
        else:
            pl.pop("sb_camara_claves", None)
        lz.modificado = False
        self._cache.pop(pl.get("id"), None)
        self._marcar()
        if self._stack.currentIndex() == 1 and pl.get("id") == self._id_editando:
            self._actualizar_titulo_cuadro(pl)
        # Actualizar su miniatura en la tira
        for k in range(self._tira.count()):
            it = self._tira.item(k)
            if it.data(Qt.ItemDataRole.UserRole) == pl["id"]:
                it.setIcon(QIcon(self.miniatura(pl, px(110))))

    def _llenar_tira(self) -> None:
        self._tira.blockSignals(True)
        self._tira.clear()
        actual = None
        for pl in self.cuadros():
            n = int(pl.get("escena", 0) or 0)
            num = self._etiquetas.get(n, (str(n), ""))[0]
            it = QListWidgetItem(QIcon(self.miniatura(pl, px(110))),
                                 f"{num}·{pl.get('numero', '') or '?'}")
            it.setData(Qt.ItemDataRole.UserRole, pl["id"])
            self._tira.addItem(it)
            if pl["id"] == self._id_editando:
                actual = it
        if actual is not None:
            self._tira.setCurrentItem(actual)
            self._tira.scrollToItem(actual)
        self._tira.blockSignals(False)

    def navegar(self, paso: int) -> None:
        lista = self.cuadros()
        if not lista:
            return
        i = next((k for k, p in enumerate(lista) if p["id"] == self._id_editando), 0)
        j = max(0, min(len(lista) - 1, i + paso))
        if j != i:
            self.abrir_editor(lista[j]["id"])

    def _importar_foto(self) -> None:
        ruta, _ = QFileDialog.getOpenFileName(
            self, "Foto o imagen de referencia", carpeta_para_adjuntar(self),
            "Imágenes (*.png *.jpg *.jpeg *.bmp *.webp)")
        if not ruta:
            return
        recordar_carpeta_adjuntos(self, ruta)
        img = QImage(ruta)
        if img.isNull():
            QMessageBox.warning(self, "Storyboard", "No se pudo leer la imagen.")
            return
        self.lienzo.poner_foto(img)

    def _importar_imagen_capa(self, quitar_blanco: bool = False) -> None:
        rutas, _ = QFileDialog.getOpenFileNames(
            self, "Dibujo en papel" if quitar_blanco else "Imagen como capa",
            carpeta_para_adjuntar(self),
            "Imágenes (" + " ".join("*" + e for e in EXT_IMAGENES_SB) + ")")
        recordar_carpeta_adjuntos(self, rutas)
        hechas = 0
        for ruta in rutas or []:
            img = QImage(ruta)
            if img.isNull():
                QMessageBox.warning(self, "Storyboard", f"No se pudo leer «{Path(ruta).name}».")
                continue
            if self.lienzo.agregar_imagen(img, Path(ruta).stem, quitar_blanco) is not None:
                hechas += 1
        if hechas:
            self._elegir_herramienta("posar")

    def _pegar_imagen(self) -> None:
        if self.lienzo.pegar_imagen() is not None:
            self._elegir_herramienta("posar")
        else:
            QMessageBox.information(self, "Storyboard",
                                    "No hay una imagen copiada. Copia una imagen (o un archivo "
                                    "de imagen) y vuelve a intentarlo.")

    def _silueta(self, personas: int, lado: str, tamano: str = "", vista: str = "",
                 mira: int = 1) -> None:
        tam = tamano or self._cb_tam.currentText().strip() or "Plano medio (PM)"
        if not self.lienzo.poner_figuras(tam, personas, lado, vista, mira):
            QMessageBox.information(
                self, "Personas",
                f"«{tam}» muestra un objeto, no una persona: usa «🪑 Objetos», "
                "dibújalo o usa «🖼 Foto…» con una foto del objeto.")
            return
        self._elegir_herramienta("posar")

    def _agregar_persona(self) -> None:
        self.lienzo.agregar_persona()
        self._elegir_herramienta("posar")

    def _persona_cenital(self) -> None:
        fig = self.lienzo.agregar_persona()
        cambiar_vista_figura(fig, "arriba")
        fig["y"] = 0.5
        fig["alto"] = round(max(0.6, float(fig.get("alto", 0.6) or 0.6)), 4)
        self.lienzo.update()
        self._elegir_herramienta("posar")

    def _persona_dentro(self) -> None:
        o = self.lienzo.seleccionado()
        if o is None or o.get("tipo") != "objeto" or not ventanas_objeto_sb(o):
            conts = [c for c in self.lienzo.capas if c.get("tipo") == "objeto"
                     and capa_visible(c) and ventanas_transparentes_sb(c)]
            if len(conts) == 1:
                o = conts[0]
            else:
                QMessageBox.information(
                    self, "Persona dentro",
                    "Elige primero (con ✋) el auto, la casa, el kiosco o la ventana donde va la "
                    "persona. Se ve por sus vidrios: también puedes hacer clic derecho sobre él → "
                    "«Poner una persona dentro»." if not conts else
                    "Hay varios con vidrios en el cuadro: elige con ✋ en cuál va la persona.")
                return
        if o.get("ventanas_opacas"):
            self.lienzo.alternar_vidrios(o["id"])
        if self.lienzo.meter_persona(o["id"]) is not None:
            self._elegir_herramienta("posar")

    def _vista_cenital(self, arriba: bool) -> None:
        n = self.lienzo.vista_cenital(arriba)
        if not n:
            QMessageBox.information(self, "Plano cenital",
                                    "No hay personas ni objetos que cambiar en este cuadro."
                                    if arriba else "Nada está visto desde arriba en este cuadro.")
            return
        self._elegir_herramienta("posar")

    def _agregar_objeto(self, clase: str) -> None:
        if self.lienzo.agregar_objeto_clase(clase) is not None:
            self._elegir_herramienta("posar")

    def _abrir_galeria(self, ancla_widget=None, punto: Optional[QPointF] = None,
                       pos_global=None) -> GaleriaObjetosSB:
        """Abre la biblioteca de objetos. «punto»: dónde ponerlo (clic
        derecho en el cuadro); si no, va a escala junto a las personas."""
        if self._galeria is None:
            self._galeria = GaleriaObjetosSB(self)
            self._galeria.elegido.connect(self._objeto_elegido)
        self._punto_galeria = punto
        if ancla_widget is not None:
            pos = ancla_widget.mapToGlobal(QPoint(0, 0))
            ancla = QRect(pos, ancla_widget.size())
        else:
            g = pos_global if pos_global is not None else QCursor.pos()
            ancla = QRect(g, QSize(1, 1))
        self._galeria.abrir(ancla, estilo_figuras_actual(), self._objetos_recientes())
        return self._galeria

    def _objetos_recientes(self) -> list[str]:
        try:
            txt = str(settings_app().value("sb_objetos_recientes", "") or "")
        except Exception:
            txt = ""
        return [c for c in txt.split(",") if c in _OBJ_SB]

    def _objeto_elegido(self, clase: str) -> None:
        rec = [clase] + [c for c in self._objetos_recientes() if c != clase]
        settings_app().setValue("sb_objetos_recientes", ",".join(rec[:12]))
        punto, self._punto_galeria = self._punto_galeria, None
        o = self.lienzo.agregar_objeto_clase(clase, punto)
        if o is not None:
            if self._galeria is not None and self._galeria.b_arriba.isChecked():
                cambiar_vista_objeto_sb(o, "arriba")
                self.lienzo.update()
            self._elegir_herramienta("posar")

    def _nombrar_personajes(self) -> None:
        """Pone sobre las personas del cuadro los nombres de los personajes
        que hablan en la escena (de izquierda a derecha)."""
        pl = self._plano(self._id_editando)
        escena = int(pl.get("escena", 0) or 0) if pl else 0
        en_escena = []
        for e in escenas_con_bloques(self.doc.bloques):
            if int(e.get("n", 0)) == escena:
                for b in self.doc.bloques[e["desde"]:e["hasta"]]:
                    if b.elem == Elem.PERSONAJE:
                        n = _nombre_personaje(b.texto)
                        if n and n not in en_escena:
                            en_escena.append(n)
        nombres = [x for x in personajes_sugeridos_sb(self.doc, escena)
                   if _nombre_personaje(x) in en_escena]
        if not any(c.get("tipo") == "figura" for c in self.lienzo.capas):
            QMessageBox.information(self, "Personas",
                                    "Primero agrega personas con «🧍 Personas».")
            return
        if not nombres:
            QMessageBox.information(
                self, "Personas", "En esta escena no habla ningún personaje. Ponles nombre "
                "con doble clic (herramienta ✋) o con clic derecho → «Es el personaje…».")
            return
        self.lienzo.nombrar_con_personajes(nombres)
        self._elegir_herramienta("posar")

    def _copiar_del_anterior(self) -> None:
        lista = self.cuadros()
        i = next((k for k, p in enumerate(lista) if p["id"] == self._id_editando), -1)
        if i <= 0:
            QMessageBox.information(self, "Personas", "Este es el primer cuadro.")
            return
        objs = objetos_de_plano(lista[i - 1])
        if not objs:
            QMessageBox.information(self, "Personas",
                                    "El cuadro anterior no tiene personas ni objetos.")
            return
        self.lienzo.reemplazar_objetos(objs)
        self._elegir_herramienta("posar")

    def _elegir_estilo_silueta(self) -> None:
        dlg = DialogoEstiloSilueta(self)
        if dlg.exec() != QDialog.DialogCode.Accepted:
            return
        self._cambiar_estilo_silueta(dlg.estilo())
        if dlg.aplicar_a_todos():
            self._reestilar_todo(avisar=False)

    def _cambiar_estilo_silueta(self, clave: str) -> None:
        """Elige el estilo de las personas y objetos nuevos (queda
        guardado) y lo aplica a los del cuadro abierto."""
        settings_app().setValue("sb_estilo_figuras", clave)
        conf = getattr(self.lienzo, "guia_conf", None)
        if conf:      # silueta antigua (imagen) → personas articuladas
            self.lienzo.poner_figuras(conf.get("tamano", "Plano medio (PM)"),
                                      int(conf.get("personas", 1) or 1),
                                      conf.get("lado", "centro"))
        self.lienzo.cambiar_estilo_objetos(clave)

    def _reestilar_todo(self, avisar: bool = True) -> int:
        """Pasa al estilo actual las personas y objetos de todos los
        cuadros. Las siluetas antiguas (imagen) se cambian por personas
        articuladas."""
        self._guardar_cuadro_actual()
        estilo = estilo_figuras_actual()
        n = 0
        for pl in self.doc.planos:
            cambio = False
            conf = pl.get("sb_guia_conf")
            if conf and pl.get("sb_guia"):
                figs = figuras_para_plano(conf.get("tamano", "Plano medio (PM)"),
                                          int(conf.get("personas", 1) or 1),
                                          conf.get("lado", "centro"), estilo)
                if figs:
                    capas = migrar_capas_plano(pl)
                    for k, f in enumerate(figs, 1):
                        f["nombre"] = f"Persona {k}"
                    capas[0:0] = figs
                    pl.pop("sb_guia", None)
                    pl.pop("sb_guia_conf", None)
                    cambio = True
            for o in objetos_de_plano(pl):
                if o.get("tipo") != "imagen" and o.get("estilo") != estilo:
                    o["estilo"] = estilo
                    cambio = True
            n += cambio
        if n:
            self._cache.clear()
            self._marcar()
        if n and self._stack.currentIndex() == 1 and self._plano(self._id_editando):
            self.abrir_editor(self._id_editando, guardar=False)
        if avisar:
            QMessageBox.information(self, "Estilo de las figuras",
                                    f"✅ {n} cuadro(s) actualizados con el estilo nuevo."
                                    if n else "Ningún cuadro tiene personas ni objetos todavía.")
        return n

    def _flechas_auto(self) -> None:
        clave = clave_movimiento_de_plano(self._cb_mov.currentText())
        if not clave:
            QMessageBox.information(
                self, "Flechas de cámara",
                "Elige primero el movimiento del plano (Paneo, Tilt, Travelling, "
                "Dolly, Zoom, Grúa…) o una flecha del menú.")
            return
        self.lienzo.agregar_anotaciones(flechas_camara_sb(clave))

    # ══ Presentación, exportar, ayuda ═══════════════════════════════
    def _menu_tarjeta(self, pid: str, pos) -> None:
        pl = self._plano(pid)
        if pl is None:
            return
        m = QMenu(self)
        m.addAction("🧊  Abrir este cuadro en 3D", lambda: self.abrir_editor(pid))
        md = m.addMenu(f"⏱  Duración: {texto_duracion(duracion_animatic_sb(pl))}"
                       + ("" if duracion_fija_sb(pl) else " (auto)"))
        fija = duracion_fija_sb(pl)
        actual = duracion_animatic_sb(pl)
        a = md.addAction(f"Automática (≈ {texto_duracion(duracion_sugerida_sb(pl))}, según el diálogo)")
        a.setCheckable(True)
        a.setChecked(not fija)
        a.triggered.connect(lambda _=False: self.poner_duracion(pid, 0.0))
        md.addSeparator()
        for seg in (1, 1.5, 2, 3, 4, 5, 6, 8, 10, 12, 15, 20):
            a = md.addAction(texto_duracion(seg))
            a.setCheckable(True)
            a.setChecked(fija and abs(actual - seg) < 1e-3)
            a.triggered.connect(lambda _=False, ss=seg: self.poner_duracion(pid, float(ss)))
        md.addSeparator()
        md.addAction("Otra…", lambda: self._pedir_duracion(pid))
        m.addAction("⏱  Tiempos de todos los planos…", self._abrir_tiempos)
        m.addSeparator()
        m.addAction("⬇  Dónde está su cámara (la escena desde arriba)…",
                    lambda: self._abrir_3d(pid, vista="arriba"))
        m.exec(pos)

    def _pedir_duracion(self, pid: str) -> None:
        pl = self._plano(pid)
        if pl is None:
            return
        v, ok = QInputDialog.getDouble(self, "Duración del plano", "Segundos:",
                                       round(duracion_animatic_sb(pl), 1), 0.1, 600.0, 1)
        if ok:
            self.poner_duracion(pid, v)

    def poner_duracion(self, pid: str, seg: float) -> None:
        """Fija la duración de un plano (0 = automática)."""
        pl = self._plano(pid)
        if pl is None:
            return
        if self._stack.currentIndex() == 1 and pid == self._id_editando:
            self._ed_dur.setValue(max(0.0, seg))
            return
        d0 = duracion_animatic_sb(pl)
        pl["duracion"] = texto_duracion(round(seg, 1)) if seg > 0 else ""
        if hasattr(self, "panel_anim") and self.panel_anim.estirar() and plano_animado_sb(pl):
            escalar_animacion_plano(pl, duracion_animatic_sb(pl) / max(0.1, d0))
        self._cache.pop(pid, None)
        self._marcar()
        self._refrescar_cuadricula()

    def _abrir_tiempos(self) -> None:
        self._guardar_cuadro_actual()
        if not cuadros_ordenados(self.doc):
            QMessageBox.information(self, "Tiempos", "Todavía no hay cuadros: agrégalos con «＋ Cuadro»"
                                    + (" o «✨ Del guion»." if escenas_con_bloques(self.doc.bloques) else "."))
            return
        dlg = DialogoTiemposSB(self)
        ok = dlg.exec() == QDialog.DialogCode.Accepted
        destino = dlg.abrir_id if ok else ""
        if not dlg.hubo_cambios() and not destino:
            return
        self._cache.clear()
        if destino and self._plano(destino):
            self.abrir_editor(destino, guardar=False)
        elif self._stack.currentIndex() == 1 and self._plano(self._id_editando):
            self.abrir_editor(self._id_editando, guardar=False)
        else:
            self._refrescar_cuadricula()
        self._actualizar_estado()

    def presentar(self) -> None:
        self._guardar_cuadro_actual()
        lista = self.cuadros()
        if not lista:
            QMessageBox.information(self, "Storyboard", "Todavía no hay cuadros: agrégalos con «＋ Cuadro».")
            return
        inicio = next((k for k, p in enumerate(lista) if p["id"] == self._sel_id), 0)
        PresentacionStoryboard(self.doc, lista, inicio, parent=self).exec()

    def _exportar_pdf(self, hoja: bool = False) -> None:
        self._guardar_cuadro_actual()
        dlg = DialogoExportarStoryboard(hoja, parent=self)
        if dlg.exec() != QDialog.DialogCode.Accepted:
            return
        lista = self.cuadros()
        if not lista and not hoja:
            QMessageBox.information(self, "Storyboard", "Todavía no hay cuadros.")
            return
        base = (getattr(self.doc, "titulo", "") or "guion").strip() or "guion"
        nombre = f"{base} - {'hoja para dibujar' if hoja else 'storyboard'}.pdf"
        ruta, _ = QFileDialog.getSaveFileName(
            self, "Guardar PDF", str(Path(ruta_ultima_carpeta()) / nombre), "PDF (*.pdf)")
        if not ruta:
            return
        if not ruta.lower().endswith(".pdf"):
            ruta += ".pdf"
        try:
            n = exportar_storyboard_pdf(self.doc, ruta, lista, **dlg.opciones(),
                                        hoja_para_dibujar=hoja)
            QMessageBox.information(self, "Storyboard",
                                    f"✅ PDF guardado ({n} páginas): {Path(ruta).name}")
        except Exception as e:
            QMessageBox.critical(self, "Storyboard", f"No se pudo exportar:\n{e}")

    def _exportar_animatic(self) -> None:
        self._guardar_cuadro_actual()
        lista = self.cuadros()
        if not lista:
            QMessageBox.information(self, "Storyboard", "Todavía no hay cuadros.")
            return
        dlg = DialogoExportarAnimatic(self)
        if dlg.exec() != QDialog.DialogCode.Accepted:
            return
        gif = dlg.es_gif()
        base = (getattr(self.doc, "titulo", "") or "guion").strip() or "guion"
        ext = "gif" if gif else "html"
        ruta, _ = QFileDialog.getSaveFileName(
            self, "Guardar el animatic",
            str(Path(ruta_ultima_carpeta()) / _nombre_archivo_seguro(f"{base} - animatic.{ext}")),
            "GIF animado (*.gif)" if gif else "Página web (*.html)")
        if not ruta:
            return
        if not ruta.lower().endswith("." + ext):
            ruta += "." + ext
        prog = QProgressDialog("Armando el animatic…", "Cancelar", 0, len(lista), self)
        prog.setWindowTitle("🎬  Animatic")
        prog.setMinimumDuration(300)

        def avance(k: int, n: int) -> bool:
            prog.setMaximum(n)
            prog.setValue(k)
            QApplication.processEvents()
            return not prog.wasCanceled()
        try:
            fn = exportar_animatic_gif if gif else exportar_animatic_html
            n = fn(self.doc, ruta, lista, progreso=avance, **dlg.opciones())
        except Exception as e:
            prog.close()
            QMessageBox.critical(self, "Animatic", f"No se pudo guardar:\n{e}")
            return
        prog.close()
        if not n:
            return
        total = sum(duracion_animatic_sb(p) for p in lista)
        QMessageBox.information(
            self, "Animatic",
            f"✅ Animatic guardado: <b>{html.escape(Path(ruta).name)}</b> "
            f"({len(lista)} cuadros · {_fmt_mmss(total)}).<br><br>" +
            ("Se ve en cualquier navegador, en el celular y en los chats (sin sonido)."
             if gif else
             "Ábrelo con doble clic: se reproduce en el navegador, con la cámara en "
             "movimiento, subtítulos y los diálogos en voz alta (botón 🔊). Es un solo "
             "archivo: lo puedes mandar por correo o WhatsApp."))

    def _exportar_png(self) -> None:
        self._guardar_cuadro_actual()
        lista = self.cuadros()
        if not lista:
            QMessageBox.information(self, "Storyboard", "Todavía no hay cuadros.")
            return
        carpeta = QFileDialog.getExistingDirectory(
            self, "Carpeta para las imágenes", ruta_ultima_carpeta())
        if not carpeta:
            return
        try:
            destino = exportar_storyboard_png(self.doc, carpeta, lista)
            QMessageBox.information(
                self, "Storyboard",
                f"✅ {len(lista)} imágenes en:<br><b>{html.escape(str(destino))}</b>"
                "<br><br>Arrástralas a tu editor de video (en orden) y usa "
                "<b>duraciones.txt</b> para el largo de cada una: así armas "
                "el animatic.")
        except OSError as e:
            QMessageBox.critical(self, "Storyboard", f"No se pudo exportar:\n{e}")

    def _abrir_lista_planos(self) -> None:
        self._guardar_cuadro_actual()
        VentanaPlanos(self._vp, parent=self).exec()
        self._cache.clear()
        self._recargar_escenas()             # (la lista pudo crear escenas propias)
        if self._stack.currentIndex() == 1 and self._plano(self._id_editando):
            self.abrir_editor(self._id_editando, guardar=False)
        else:
            self._mostrar_cuadricula()

    # ── 🎓 El tutorial del storyboard (al lado de la ventana; se prueba mientras se lee) ──
    def _tutorial_storyboard(self, practica: Optional[bool] = None) -> "TutorialFlotante":
        if practica is None:
            practica = bool(getattr(self.doc, "_tutorial_practica", False))
        tut = getattr(self, "_tut_sb", None)
        if tut is not None:
            try:
                tut.close()
            except RuntimeError:
                pass
        self._tut_sb = TutorialFlotante("🎓 Storyboard", pasos_tutorial_storyboard(self, practica), self)
        self._tut_sb.show()
        return self._tut_sb

    def _tut_primer_cuadro(self, vista: str = "camara") -> Optional[dict]:
        """El primer cuadro, abierto en 3D (si no hay cuadros y hay guion, los crea)."""
        if not self.cuadros() and escenas_con_bloques(self.doc.bloques):
            self._desde_guion()
        cs = self.cuadros()
        if not cs:
            QMessageBox.information(self, "Storyboard", "Todavía no hay cuadros: «＋ Nuevo cuadro» crea el primero.")
            return None
        self.abrir_editor(cs[0]["id"], vista=vista)
        return cs[0]

    def _tut_preparar(self, que: str, practica: Optional[bool] = None) -> None:
        """Deja lista la parte del storyboard que explica un paso del tutorial
        (en el guion de práctica, además, arma un ejemplo para verlo
        funcionando; en tu guion no cambia nada)."""
        if practica is None:
            practica = bool(getattr(self.doc, "_tutorial_practica", False))
        try:
            if not self.cuadros() and escenas_con_bloques(self.doc.bloques):
                self._desde_guion()
            if que in ("personas", "sentar", "acciones"):
                self._tut_ejemplo(que, practica)
                return
            if que in ("3d", "3d_ver", "3d_ubicar", "objetos", "losas", "animar", "laminas", "camara", "sol"):
                cuadros = self.cuadros()
                if not cuadros:
                    QMessageBox.information(self, "Storyboard",
                                            "Todavía no hay cuadros: «＋ Cuadro» o «✨ Del guion» los crea.")
                    return
                pl = cuadros[0]
                if practica:
                    armar_ejemplo_3d_sb(self.doc, self._plano(pl["id"]) or pl, losas=que == "losas")
                self.abrir_editor(pl["id"], vista="maqueta" if que in ("losas", "3d_ver", "laminas") else "camara")
                ed = self.editor3d
                els = ed.datos.get("elementos", [])
                if ed.modo_vista == "maqueta":
                    ed.ver_todo()
                if que in ("3d", "camara") and practica:
                    ed.angulo_rapido("picado")
                if que == "camara":
                    ed.ir_a_pestana("camara")
                elif que == "sol":
                    ed.ir_a_pestana("escena")
                elif que in ("objetos", "losas"):
                    tipos = {"objetos": ("mueble",), "losas": ("suelo", "techo")}[que]
                    e = next((x for t in tipos for x in els if x.get("tipo") == t), None)
                    if e is not None:
                        ed.elegir(e["id"])
                        ed.ir_a_pestana("camara")
                elif que == "laminas":
                    if practica:
                        armar_ejemplo_laminas_sb(ed)
                    e = next((x for x in reversed(ed.datos.get("elementos", []))
                              if x.get("clase") in ("texto", "imagen")), None)
                    if e is not None:
                        ed.elegir(e["id"])
                elif que == "animar":
                    ed.b_animar.setChecked(True)
                    if practica and not plano_animado_3d(self._plano(pl["id"])):
                        ed.animar_movimiento("dolly_in")
            elif que == "tiempos":
                self._abrir_tiempos()
            elif que == "planta":
                self._abrir_planta()
            elif que == "luces":
                self._abrir_planta(pestana=1, al_abrir=((lambda d: d._tres_luces()) if practica else None))
            elif que == "revision":
                self._revisar_180()
        except Exception as e:
            print(f"[Tutorial] Storyboard ({que}): {e}")

    def _tut_ejemplo(self, que: str, practica: bool) -> None:
        """Abre el primer cuadro y lo muestra funcionando: en el guion de práctica arma un ejemplo
        (personas, una silla, una cama…); en tu guion, solo elige lo que hay."""
        vista = "maqueta" if que in ("sentar", "acciones") else "camara"   # (de afuera se ve mejor)
        pl = self._tut_primer_cuadro(vista)
        if pl is None:
            return
        ed = self.editor3d
        els = ed.datos.get("elementos", [])
        pers = [x for x in els if x.get("tipo") == "personaje"]
        if practica and len(pers) < 2:
            armar_ejemplo_3d_sb(self.doc, self._plano(pl["id"]) or pl)
            self.abrir_editor(pl["id"], vista=vista)
            ed = self.editor3d
            els = ed.datos.get("elementos", [])
            pers = [x for x in els if x.get("tipo") == "personaje"]
        if que == "personas":
            if pers:
                ed.elegir(pers[0]["id"])
                ed.ir_a_pestana("camara")
        elif que == "sentar":
            sillas = [x for x in els if "sentar" in usos_mueble_3d(x)]
            if practica and pers and not sillas:
                p0 = pers[0]
                ed.planta.agregar({"tipo": "mueble", "sb": True, "clase": "silla", "ang": 0.0},
                                  QPointF(float(p0.get("x", 0) or 0) + 0.9, float(p0.get("y", 0) or 0)))
                sillas = [x for x in ed.datos.get("elementos", []) if "sentar" in usos_mueble_3d(x)]
            if practica and pers and sillas:
                ed.sentar_en(sillas[0]["id"], pers[0]["id"], "sentar")
            elif sillas:
                ed.elegir(sillas[0]["id"])
            ed.ir_a_pestana("camara")
            ed._ver_elegido()
        elif que == "acciones":
            asientos = [x for x in els if usos_mueble_3d(x)]
            pers.sort(key=lambda x: any(_math.hypot(float(x.get("x", 0) or 0) - float(s_.get("x", 0) or 0),
                                                    float(x.get("y", 0) or 0) - float(s_.get("y", 0) or 0)) < 0.5
                                        for s_ in asientos))      # (se queda quieta la que no está sentada)
            if practica and len(pers) >= 2:
                ed.accion_dos(pers[0]["id"], pers[1]["id"], "abrazo")
            elif len(pers) >= 2:
                ed.elegir(pers[0]["id"])
                ed._elegir_mas(pers[1]["id"])
            ed.ir_a_pestana("camara")
            ed._ver_elegido()

    def _ayuda(self) -> None:
        from PySide6.QtWidgets import QTextBrowser
        d = QDialog(self)
        d.setWindowTitle("❓  Storyboard — cómo se usa")
        v = QVBoxLayout(d)
        v.setContentsMargins(px(12), px(10), px(12), px(10))
        t = QTextBrowser()
        t.setOpenLinks(False)
        t.setHtml(AYUDA_STORYBOARD_HTML)
        v.addWidget(t, 1)
        bb = QDialogButtonBox(QDialogButtonBox.StandardButton.Close)
        bb.button(QDialogButtonBox.StandardButton.Close).setText("Cerrar")
        bb.rejected.connect(d.reject)
        v.addWidget(bb)
        d.resize(*tam_ventana(760, 640))
        ajustar_ventana_a_pantalla(d)
        d.exec()

    # ── Teclado en la cuadrícula ──
    def keyPressEvent(self, e) -> None:
        foco = QApplication.focusWidget()
        escribiendo = isinstance(foco, (QLineEdit, QPlainTextEdit, QTextEdit, QComboBox))
        sin_mod = not (e.modifiers() & (Qt.KeyboardModifier.ControlModifier | Qt.KeyboardModifier.AltModifier
                                        | Qt.KeyboardModifier.ShiftModifier))
        if self._stack.currentIndex() == 1 and not escribiendo and sin_mod:
            k = e.key()
            if k in (Qt.Key.Key_PageDown, Qt.Key.Key_PageUp):
                self.navegar(1 if k == Qt.Key.Key_PageDown else -1)
                return
            if k == Qt.Key.Key_N:
                self.nuevo_cuadro()
                return
            if k == Qt.Key.Key_D:
                self.duplicar()
                return
        if self._stack.currentIndex() == 0 and not escribiendo:
            k = e.key()
            lista = self.cuadros()
            i = next((n for n, p in enumerate(lista) if p["id"] == self._sel_id), -1)
            if k == Qt.Key.Key_N:
                self.nuevo_cuadro()
                return
            if k == Qt.Key.Key_D:
                self.duplicar()
                return
            if k == Qt.Key.Key_Delete:
                self.quitar()
                return
            if k in (Qt.Key.Key_Return, Qt.Key.Key_Enter):
                if self._sel_id:
                    self.abrir_editor(self._sel_id)
                return
            if k in (Qt.Key.Key_Right, Qt.Key.Key_Left) and lista:
                j = max(0, min(len(lista) - 1, i + (1 if k == Qt.Key.Key_Right else -1)))
                self.seleccionar(lista[j]["id"])
                t = self._tarjetas.get(lista[j]["id"])
                if t is not None:
                    self._scroll.ensureWidgetVisible(t)
                return
        super().keyPressEvent(e)

    def exec(self) -> int:
        """Se abre ocupando toda la pantalla (maximizada)."""
        if self.isWindow():
            self.setWindowState(self.windowState() | Qt.WindowState.WindowMaximized)
        return super().exec()

    # ── Cierre ──
    def done(self, r: int) -> None:
        if self._stack.currentIndex() == 1:
            self._dejar_3d()
        self._guardar_cuadro_actual()
        super().done(r)

    def _al_cerrar(self, *_):
        """Lo llama el Centro de Producción al volver a la grilla."""
        if getattr(self, "_modo", "2d") == "3d":
            self._poner_modo("2d")
        self._guardar_cuadro_actual()


