    _caja3(c, -w / 2, w / 2, -d / 2 + 0.06, d / 2, ha - 0.05, ha, col)
    _caja3(c, -w / 2, w / 2, -d / 2, -d / 2 + 0.05, ha + 0.08, h, col)
