def _f3_butacas(c, w, d, h, k=""):
    n = max(1, int(w / 0.55))
    a = w / n
    for i in range(n):
        x = -w / 2 + a * (i + 0.5)
        _caja3(c, x - a * 0.42, x + a * 0.42, -d * 0.2, d / 2, 0.38, 0.46, _C3["rojo"])
        _caja3(c, x - a * 0.42, x + a * 0.42, -d / 2, -d * 0.2, 0.1, h, _C3["rojo"])
        _caja3(c, x + a * 0.42, x + a * 0.5, -d / 2, d / 2, 0, 0.62, _C3["oscuro"])
    _caja3(c, -w / 2, -w / 2 + a * 0.08, -d / 2, d / 2, 0, 0.62, _C3["oscuro"])


def _f3_cama(c, w, d, h, k=""):
    if k == "camarote":
        for z in (0.18, h * 0.6):
            _caja3(c, -w / 2, w / 2, -d / 2, d / 2, z, z + 0.18, _C3["cama"])
        for sx in (-1, 1):
            for sy in (-1, 1):
                _caja3(c, sx * w / 2 - 0.03, sx * w / 2 + 0.03, sy * d / 2 - 0.03, sy * d / 2 + 0.03, 0, h,
                       _C3["madera"])
        return
    _caja3(c, -w / 2, w / 2, -d / 2, d / 2, 0.08, 0.32, _C3["madera"])
    _caja3(c, -w / 2 + 0.03, w / 2 - 0.03, -d / 2 + 0.05, d / 2 - 0.02, 0.32, 0.52, _C3["blanco"])
    _caja3(c, -w / 2, w / 2, -d / 2 - 0.05, -d / 2, 0, h, _C3["madera"])
    if w > 1.0:
        for sx in (-1, 1):
            _caja3(c, sx * w * 0.05, sx * (w / 2 - 0.1), -d / 2 + 0.08, -d / 2 + 0.42, 0.52, 0.62,
                   _C3["papel"])
    else:
        _caja3(c, -w / 2 + 0.1, w / 2 - 0.1, -d / 2 + 0.08, -d / 2 + 0.42, 0.52, 0.62, _C3["papel"])
    _caja3(c, -w / 2 + 0.01, w / 2 - 0.01, -d * 0.12, d / 2 - 0.01, 0.52, 0.56, _C3["cama"])


def _f3_cuna(c, w, d, h, k=""):
    _caja3(c, -w / 2, w / 2, -d / 2, d / 2, 0.3, 0.45, _C3["blanco"])
    for sy in (-1, 1):
        _caja3(c, -w / 2, w / 2, sy * d / 2 - 0.02, sy * d / 2 + 0.02, h - 0.04, h, _C3["madera"])
    for sx in (-1, 1):
        _caja3(c, sx * w / 2 - 0.02, sx * w / 2 + 0.02, -d / 2, d / 2, 0, h, _C3["madera"])
    for i in range(1, 8):
        y = -d / 2 + d * i / 8
        for sx in (-1, 1):
            _caja3(c, sx * w / 2 - 0.012, sx * w / 2 + 0.012, y - 0.012, y + 0.012, 0.45, h, _C3["madera"])


def _f3_camilla(c, w, d, h, k=""):
    _caja3(c, -w / 2, w / 2, -d / 2, d / 2, h - 0.14, h - 0.02, _C3["blanco"])
