def _f3_palmera(c, w, d, h, k=""):
    p0 = (0, 0, 0)
    pts = [p0, (w * 0.04, 0, h * 0.35), (w * 0.1, 0, h * 0.7), (w * 0.12, 0, h * 0.93)]
    for a, b in zip(pts, pts[1:]):
        _tubo3(c, a, b, 0.14, 0.11, _C3["tronco"], n=8)
    top = pts[-1]
    for i in range(7):
        a = 2 * _math.pi * i / 7
        ux, uy = _math.cos(a), _math.sin(a)
        L = w * 0.5
        p1 = (top[0] + ux * L * 0.5, top[1] + uy * L * 0.5, top[2] + h * 0.05)
        p2 = (top[0] + ux * L, top[1] + uy * L, top[2] - h * 0.12)
        px_, py = -uy * 0.25, ux * 0.25
        _poli3(c, [top, (p1[0] + px_, p1[1] + py, p1[2]), p2, (p1[0] - px_, p1[1] - py, p1[2])],
               _C3["verde"] if i % 2 else _C3["verde2"], None, borde=True)


def _f3_arbusto(c, w, d, h, k=""):
    _elips3(c, (0, 0, h * 0.45), w * 0.5, d * 0.5, h * 0.5, _C3["verde"], n=9, m=5, z_min=0.0)
    _elips3(c, (w * 0.22, -d * 0.1, h * 0.6), w * 0.26, d * 0.3, h * 0.38, _C3["verde2"], n=7, m=5)


def _f3_flores(c, w, d, h, k=""):
    _elips3(c, (0, 0, h * 0.3), w * 0.5, d * 0.5, h * 0.35, _C3["verde"], n=8, m=4, z_min=0.0)
    for i in range(6):
        a = 2 * _math.pi * i / 6
