    if k == "patrulla":
        _caja3(c, -0.3, 0.0, -0.35, 0.35, h, h + 0.1, _C3["azul"])
        _caja3(c, 0.0, 0.3, -0.35, 0.35, h, h + 0.1, _C3["rojo"])
