    for x in (-w / 2 + r, w / 2 - r):
        _rueda3(c, x, 0, r, r, 0.1)
    _tubo3(c, (-w / 2 + r, 0, r), (0.05, 0, h * 0.62), 0.05, 0.05, _C3["oscuro"], n=6)
    _tubo3(c, (w / 2 - r, 0, r), (w / 2 - r - 0.15, 0, h * 0.95), 0.04, 0.04, _C3["metal"], n=6)
    _caja3(c, -w * 0.25, w * 0.15, -0.14, 0.14, h * 0.45, h * 0.66, _C3["rojo"] if k == "moto" else _C3["azul"])
