    _caja3(c, -0.13, 0.03, -0.05, 0.05, h * 0.82, h * 0.86, _C3["oscuro"])
    _tubo3(c, (w / 2 - r - 0.12, -0.25, h * 0.92), (w / 2 - r - 0.12, 0.25, h * 0.92), 0.015, 0.015,
           _C3["oscuro"], n=5)


