def _cuatro_muros3(c, w, d, hw, col, frente=(), atras=(), der=(), izq=(), lado=1.5):
    """Las cuatro paredes de una casa o local (de los dos lados, para que por
    las ventanas se vea adentro), con sus ventanas recortadas."""
    _muro_huecos3(c, (-w / 2, d / 2, 0), (1, 0, 0), (0, 0, 1), (0, 1, 0), w, hw, frente, col, lado)
    _muro_huecos3(c, (w / 2, -d / 2, 0), (-1, 0, 0), (0, 0, 1), (0, -1, 0), w, hw, atras, col, lado)
    _muro_huecos3(c, (w / 2, d / 2, 0), (0, -1, 0), (0, 0, 1), (1, 0, 0), d, hw, der, col, lado)
    _muro_huecos3(c, (-w / 2, -d / 2, 0), (0, 1, 0), (0, 0, 1), (-1, 0, 0), d, hw, izq, col, lado)


def _f3_casa(c, w, d, h, k=""):
    dos = k == "casa_dos_pisos"
    hw = h * (0.78 if dos else 0.56)
    pisos = [(0.95, min(2.2, hw - 0.3))] + ([(hw * 0.55, hw - 0.4)] if dos else [])
    fr, la = [], []
    for z0, z1 in pisos:
        for x0, x1 in ((-w * 0.32, -w * 0.12), (w * 0.12, w * 0.32)):
            fr.append((x0 + w / 2, z0, x1 + w / 2, z1))
        for y0, y1 in ((-d * 0.3, -d * 0.1), (d * 0.1, d * 0.3)):
            la.append((y0 + d / 2, z0, y1 + d / 2, z1))
    if dos:
        fr.append((w / 2 - 0.5, hw * 0.55, w / 2 + 0.5, hw - 0.4))
    _cuatro_muros3(c, w, d, hw, _C3["muro"], fr, fr, la, la)
    _techo3(c, -w / 2 - 0.3, w / 2 + 0.3, -d / 2 - 0.3, d / 2 + 0.3, hw, h, _C3["techo"], doble=True)
    _caja3(c, w * 0.22, w * 0.22 + 0.6, -d * 0.2, d * 0.0, hw, h * 0.98, (176, 160, 146))
    _calco_frente(c, -0.5, 0.5, 0, 2.1, d / 2, _C3["madera"], borde=True)
    if dos:
        _caja3(c, -w / 2 + 0.05, w / 2 - 0.05, -d / 2 + 0.05, d / 2 - 0.05, hw * 0.5 - 0.1, hw * 0.5,
               (200, 194, 184), borde=False, sesgo=0.6)


def _f3_edificio(c, w, d, h, k=""):
    col = (210, 206, 198) if k == "edificio" else (184, 196, 206)
    vid = (112, 142, 170)
    pisos = max(2, int(h / 3.0))
    if k == "rascacielos":
        _caja3(c, -w / 2, w / 2, -d / 2, d / 2, 0, h, col)
        for s_ in (1, -1):
            for i in range(pisos):
                z0 = 0.9 + i * (h - 1.2) / pisos
                z1 = z0 + (h - 1.2) / pisos * 0.55
                _calco_frente(c, -w / 2 + 0.2, w / 2 - 0.2, z0, z1, s_ * d / 2, vid, n=(0, s_, 0))
                _calco_lado(c, -d / 2 + 0.2, d / 2 - 0.2, z0, z1, s_ * w / 2, vid, n=(s_, 0, 0))
        return
    fr, la = [], []
    for i in range(pisos):
        z0 = 0.9 + i * (h - 1.2) / pisos
        z1 = z0 + (h - 1.2) / pisos * 0.55
        nx = max(2, int(w / 2.0))
        for j in range(nx):
            u0 = 0.4 + (w - 0.8) * j / nx
            fr.append((u0 + 0.15, z0, u0 + (w - 0.8) / nx - 0.15, z1))
        ny = max(2, int(d / 2.0))
        for j in range(ny):
            u0 = 0.4 + (d - 0.8) * j / ny
            la.append((u0 + 0.15, z0, u0 + (d - 0.8) / ny - 0.15, z1))
    _cuatro_muros3(c, w, d, h, col, fr, fr, la, la, lado=3.0)
    _caja3(c, -w / 2, w / 2, -d / 2, d / 2, h, h + 0.05, col)
    for i in range(1, pisos):
        z = 0.9 + i * (h - 1.2) / pisos - 0.35
        _caja3(c, -w / 2 + 0.05, w / 2 - 0.05, -d / 2 + 0.05, d / 2 - 0.05, z - 0.1, z, (196, 192, 186),
               borde=False, sesgo=0.6)


