def _f3_escalera_sube(c, w, d, h, k="", lado_pared: int = 0):
    """🪜 Un tramo recto que sube hacia +x (peldaños de unos 18 cm), con
    baranda en los lados libres («lado_pared»: −1 o +1 = la pared está a
    ese lado en y; 0 = suelta, baranda a los dos lados)."""
    n = max(4, int(round(h / 0.18)))
    paso = w / n
    for i in range(n):
        x0 = -w / 2 + i * paso
        _caja3(c, x0, x0 + paso, -d / 2, d / 2, 0, h * (i + 1) / n,
               _C3["madera"] if i % 2 == 0 else (186, 160, 128))
    for s_ in (-1, 1):
        if lado_pared and s_ == lado_pared:
            continue
        y = s_ * (d / 2 - 0.04)
        _tubo3(c, (-w / 2 + paso / 2, y, h / n + 0.9), (w / 2 - paso / 2, y, h + 0.9), 0.025, 0.025,
               _C3["oscuro"], n=5)
        for j in range(0, n, 3):
            xj = -w / 2 + (j + 0.5) * paso
            _tubo3(c, (xj, y, h * (j + 1) / n), (xj, y, h * (j + 1) / n + 0.9), 0.015, 0.015,
                   _C3["oscuro"], n=4)


def _f3_escalera_baja(c, w, d, h, k="", lado_pared: int = 0):
    """🪜 Un tramo recto que baja hacia +x: abre un hueco en el suelo (lo de
    abajo se ve solo por el hueco), con baranda alrededor."""
    n = max(4, int(round(h / 0.18)))
    paso = w / n
    clip = [(-w / 2, -d / 2, 0.0), (w / 2, -d / 2, 0.0), (w / 2, d / 2, 0.0), (-w / 2, d / 2, 0.0)]
    hueco: list = []
    fondo = -h - 0.02
    muro = (96, 92, 86)
    hueco.append(_Cara3D([(-w / 2, -d / 2, fondo), (w / 2, -d / 2, fondo), (w / 2, -d / 2, 0), (-w / 2, -d / 2, 0)],
                         muro, (0, 1, 0), False))
    hueco.append(_Cara3D([(w / 2, d / 2, fondo), (-w / 2, d / 2, fondo), (-w / 2, d / 2, 0), (w / 2, d / 2, 0)],
                         muro, (0, -1, 0), False))
    hueco.append(_Cara3D([(-w / 2, d / 2, fondo), (-w / 2, -d / 2, fondo), (-w / 2, -d / 2, 0), (-w / 2, d / 2, 0)],
                         (84, 80, 76), (1, 0, 0), False))
    hueco.append(_Cara3D([(w / 2, -d / 2, fondo), (w / 2, d / 2, fondo), (w / 2, d / 2, 0), (w / 2, -d / 2, 0)],
                         (84, 80, 76), (-1, 0, 0), False))
    hueco.append(_Cara3D([(-w / 2, -d / 2, fondo), (w / 2, -d / 2, fondo), (w / 2, d / 2, fondo),
                          (-w / 2, d / 2, fondo)], (70, 66, 62), (0, 0, 1), False))
    for i in range(n):
        x0 = -w / 2 + i * paso
        _caja3(hueco, x0, x0 + paso, -d / 2 + 0.01, d / 2 - 0.01, fondo, -h * (i + 1) / n,
               _C3["madera"] if i % 2 == 0 else (186, 160, 128))
    for f in hueco:
        f.clip = list(clip)
    c.extend(hueco)
    # La baranda alrededor del hueco (menos por donde se entra, en −x)
    tramos = [((-w / 2, s_ * d / 2), (w / 2, s_ * d / 2)) for s_ in (-1, 1) if s_ != lado_pared]
    tramos.append(((w / 2, -d / 2), (w / 2, d / 2)))
    for (xa, ya), (xb, yb) in tramos:
        _tubo3(c, (xa, ya, 0.9), (xb, yb, 0.9), 0.025, 0.025, _C3["oscuro"], n=5)
        largo = _math.hypot(xb - xa, yb - ya)
        m_ = max(1, int(largo / 0.9))
        for j in range(m_ + 1):
            t = j / m_
            px_, py_ = xa + (xb - xa) * t, ya + (yb - ya) * t
            _tubo3(c, (px_, py_, 0.0), (px_, py_, 0.9), 0.015, 0.015, _C3["oscuro"], n=4)


