        for s_ in (1, -1):
            _caja3(c, -w / 2, w / 2, 0.05 * s_, d / 2 * s_, z, z + 0.03, _C3["metal"])
            for j in range(max(2, int(w / 0.25))):
                x = -w / 2 + 0.05 + j * 0.25
                if x + 0.2 > w / 2:
                    break
                _caja3(c, x, x + 0.2, 0.06 * s_, (d / 2 - 0.05) * s_, z + 0.03, z + 0.03 + (h - 0.2) / 4 * 0.6,
                       cols[(i + j) % 4], borde=False)


