# ── Lo que se lleva en la mano (armas y utilería): el largo va en x, el frente hacia +x ──
def _f3_arma_corta(c, w, d, h, k=""):
    """Pistola o revólver: el cañón hacia +x, la empuñadura abajo, atrás."""
    L, g = w, 0.016
    col, col2 = (62, 64, 70), (44, 44, 48)
    zc = h * 0.64
    _caja3(c, -L / 2, L / 2, -g, g, zc, h, col, base=True)
    _caja3(c, -L / 2, -L / 2 + L * 0.3, -g * 0.9, g * 0.9, 0.0, zc, col2, base=True)
    _caja3(c, -L / 2 + L * 0.3, -L / 2 + L * 0.47, -g * 0.45, g * 0.45, zc - h * 0.2, zc, col, base=True)
    if k == "revolver":
        r_ = (h - zc) * 0.8
        _tubo3(c, (-L * 0.12, 0.0, zc + (h - zc) / 2), (L * 0.1, 0.0, zc + (h - zc) / 2), r_, r_, col2, n=8)


def _f3_arma_larga(c, w, d, h, k=""):
    """Rifle o escopeta: la culata atrás, el cañón hacia +x."""
    L = w
    madera, osc = (132, 92, 60), (62, 64, 70)
    _caja3(c, -L / 2, -L / 2 + L * 0.34, -0.02, 0.02, h * 0.08, h * 0.72, madera, base=True)
    _caja3(c, -L / 2 + L * 0.34, -L / 2 + L * 0.58, -0.022, 0.022, h * 0.42, h * 0.92, osc, base=True)
    _tubo3(c, (-L / 2 + L * 0.58, 0.0, h * 0.78), (L / 2, 0.0, h * 0.78), 0.012, 0.011, osc, n=6)
    if k == "rifle":
        _tubo3(c, (-L / 2 + L * 0.36, 0.0, h * 1.05), (-L / 2 + L * 0.56, 0.0, h * 1.05), 0.016, 0.016, osc, n=6)


def _f3_hoja(c, w, d, h, k=""):
    """Cuchillo, daga, machete o espada: el mango atrás, la hoja hacia +x."""
    L = w
    mango = L * (0.2 if k == "espada" else 0.36)
    _caja3(c, -L / 2, -L / 2 + mango, -0.012, 0.012, h * 0.15, h * 0.85, (70, 56, 46), base=True)
    _caja3(c, -L / 2 + mango, L / 2, -0.003, 0.003, h * 0.08, h * 0.95, _C3["metal"], base=True)
    if k in ("espada", "daga"):
        _caja3(c, -L / 2 + mango - 0.01, -L / 2 + mango + 0.01, -0.05, 0.05, 0.0, h, (150, 130, 70), base=True)


