def _art(**kw) -> dict:
    """{"brazo_d": {"adel": 30, …}, …} a partir de brazo_d_adel=30, …"""
    out: dict = {}
    for k, v in kw.items():
        j, eje = k.rsplit("_", 1)
        out.setdefault(j, {})[eje] = float(v)
    return out


