def art_de_pose_3d(clave: str) -> dict:
    """Los ángulos de una pose (una copia, para cambiarla)."""
    base = POSES_ARTICULADAS.get(clave) or POSES_ARTICULADAS["de_pie"]
    return {j: dict(v) for j, v in base.items()}


def art_de_personaje_3d(e: dict, pl: Optional[dict]) -> Optional[dict]:
    """Cómo está articulado el actor en este plano: lo articulado a mano
    (en este plano, o en la escena) o su pose. None = sin pose (se usa la
    del cuadro dibujado, si hay, o de pie)."""
    arts = (pl or {}).get("sb_3d_art") if isinstance((pl or {}).get("sb_3d_art"), dict) else {}
    a = arts.get(e.get("id", "")) if arts else None
    if isinstance(a, dict):
        return a
    poses = (pl or {}).get("sb_3d_poses") if isinstance((pl or {}).get("sb_3d_poses"), dict) else {}
    clave = str(poses.get(e.get("id", "")) or "")
    if clave in POSES_ARTICULADAS:
        return art_de_pose_3d(clave)
    if isinstance(e.get("art"), dict):
        return e["art"]
    clave = str(e.get("pose") or "")
    if clave in POSES_ARTICULADAS:
        return art_de_pose_3d(clave)
    return None


def _rx3(a: float) -> tuple:
    r = _math.radians(a)
    c_, s_ = _math.cos(r), _math.sin(r)
    return ((1.0, 0.0, 0.0), (0.0, c_, -s_), (0.0, s_, c_))


def _ry3(a: float) -> tuple:
    r = _math.radians(a)
    c_, s_ = _math.cos(r), _math.sin(r)
    return ((c_, 0.0, s_), (0.0, 1.0, 0.0), (-s_, 0.0, c_))


def _rz3(a: float) -> tuple:
    r = _math.radians(a)
    c_, s_ = _math.cos(r), _math.sin(r)
    return ((c_, -s_, 0.0), (s_, c_, 0.0), (0.0, 0.0, 1.0))


def _mm3(*ms) -> tuple:
    """Producto de matrices 3×3 (de izquierda a derecha)."""
    out = ms[0]
    for b in ms[1:]:
        out = tuple(tuple(sum(out[i][k] * b[k][j] for k in range(3)) for j in range(3)) for i in range(3))
    return out


def _ap3(m_: tuple, v: tuple) -> tuple:
    return (m_[0][0] * v[0] + m_[0][1] * v[1] + m_[0][2] * v[2],
            m_[1][0] * v[0] + m_[1][1] * v[1] + m_[1][2] * v[2],
            m_[2][0] * v[0] + m_[2][1] * v[1] + m_[2][2] * v[2])


