        self.vista.elegido.connect(self._elegido)
        self.vista.elegido_mas.connect(self._elegir_mas)
        self.vista.mover.connect(self._mover_elemento)
        self.vista.girar.connect(self._girar_elemento)
        self.vista.soltado.connect(self._soltado)
        self.vista.centrar.connect(self._centrar)
        self.vista.menu.connect(self._menu_3d)
        self.vista.suelo.connect(self._suelo_3d)
        self.vista.borrar.connect(self._borrar)
        self.vista.atajo.connect(self._atajo)
        self.vista.transformar.connect(self._transformar)
        self.vista.hueso_elegido.connect(self._elegir_hueso)
        self.vista.girar_hueso.connect(self._girar_hueso)
        self.vista.girar_campo.connect(self._girar_campo)
        self.vista.vuelo.connect(self._vuelo_vista)
        self._grab: Optional[dict] = None
        self._t_grab = QTimer(self)
        self._t_grab.setInterval(40)
        self._t_grab.timeout.connect(self._paso_grabar)
        self._cuenta_grab: Optional[dict] = None   # ⏺ 3, 2, 1 antes de grabar
        self._t_cuenta = QTimer(self)
        self._t_cuenta.setInterval(1000)
