        self._b_lugar.setMenu(self._m_lugar)
        self._b_acciones = QToolButton()            # (🎭 de a dos)
        self._b_acciones.setText("🎭 Con otra persona ▾")
        self._b_acciones.setToolTip("Darse la mano, abrazarse, besarse, pelear, llevar en brazos… Con dos personas "
                                    "elegidas (Mayús+clic en la segunda), las acciones son entre ellas")
        self._b_acciones.setPopupMode(QToolButton.ToolButtonPopupMode.InstantPopup)
        self._m_acciones = QMenu(self._b_acciones)
        self._m_acciones.aboutToShow.connect(lambda: self._menu_acciones(self.sel, self._m_acciones))
        self._b_acciones.setMenu(self._m_acciones)
        self._b_texto = QPushButton("🔤 Cambiar el texto…")
        self._b_texto.setToolTip("Las letras, la tipografía, el estilo y los colores (también con doble clic "
                                 "sobre el texto)")
        self._b_texto.clicked.connect(lambda: self.editar_texto(self.sel))
        self.planta.al_editar_texto = self.editar_texto
        self._b_rec: dict = {}                       # (➰ un recorrido: color, de quién y sus puntas)
        for clave_, tip_ in (("color", "El color de la flecha (o el de su dueño)"),
                             ("quien", "De quién es este recorrido: una persona o un objeto"),
                             ("ini", "A quién sigue el comienzo: si esa persona u objeto se mueve, la flecha "
                                     "va con él"),
                             ("fin", "A quién sigue la punta: si esa persona u objeto se mueve, la flecha va "
                                     "con él")):
            b_ = QToolButton()
            b_.setToolTip(tip_)
            b_.setPopupMode(QToolButton.ToolButtonPopupMode.InstantPopup)
            b_.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
            m_ = QMenu(b_)
            m_.aboutToShow.connect(lambda mm=m_, c=clave_: (
                mm.clear(), self.planta.llenar_menu_recorrido(self._obj(self.sel) or {}, mm, (c,))
                if (self._obj(self.sel) or {}).get("tipo") == "recorrido" else None))
            b_.setMenu(m_)
            self._b_rec[clave_] = b_
        self._filas_sel = {}
        for clave_, etq, w_ in (("nombre", "Nombre", self._ed_nombre), ("texto", "", self._b_texto),
                                ("x", "X (→)", self._n_px), ("y", "Y (↑)", self._n_py), ("z", "Z (altura)", self._n_pz),
                                ("giro", "Giro", self._n_giro), ("esc", "Tamaño", self._n_esc),
                                ("ancho", "Ancho", self._n_ancho), ("fondo", "Fondo", self._n_fondo),
                                ("abre", "Abierta", self._n_abre),
                                ("pose", "Pose", self._cb_pose), ("pose_plano", "", self._chk_pose_plano),
                                ("articular", "", self._b_articular), ("poses", "", self._b_poses),
                                ("lugar", "", self._b_lugar), ("acciones", "", self._b_acciones),
                                ("modelo", "Modelo", self._cb_modelo),
                                ("cuerpo", "Cuerpo", self._cb_cuerpo),
                                ("rec_color", "Color", self._b_rec["color"]),
                                ("rec_quien", "De quién", self._b_rec["quien"]),
                                ("rec_ini", "Comienzo", self._b_rec["ini"]),
                                ("rec_fin", "Punta", self._b_rec["fin"])):
            lbl = QLabel(etq)
            form_sel.addRow(lbl, w_)
            self._filas_sel[clave_] = (lbl, w_)
        for clave_, w_ in (("x", self._n_px), ("y", self._n_py), ("z", self._n_pz), ("giro", self._n_giro),
                           ("esc", self._n_esc), ("ancho", self._n_ancho), ("fondo", self._n_fondo)):
            w_.valueChanged.connect(lambda v_, c=clave_: self._numero_elegido(c, float(v_)))
        self._n_abre.valueChanged.connect(lambda v_: None if self._llenando or not self.sel
                                          else self.poner_apertura(self.sel, float(v_) / 100.0))
        self._cb_pose.activated.connect(lambda _i: self._cambio_pose())
        self._chk_pose_plano.toggled.connect(lambda _on: self._cambio_pose())
        dv.addLayout(form_sel)
        self._lbl_dist = QLabel("")
        self._lbl_dist.setWordWrap(True)
        self._lbl_dist.setStyleSheet("color: #9be3a4; font-size: 8.5pt;")
        dv.addWidget(self._lbl_dist)
