        self._b_mirar_sel.clicked.connect(lambda: self.mirar_a_elemento(self.sel))
        dv.addWidget(self._b_mirar_sel)
        self._lbl_ayuda = self._ayuda(dv, "")
        if self.en_editor:
            self._ayuda(dv, "El cuadro es lo que ve esta cámara. Lo que mueves aquí se mueve en toda la "
                            "escena (y en sus otros cuadros); la pose «Solo en este plano», no. Ctrl+Z "
                            "deshace.")
        dv.addStretch()
        return pag

