            fila = QHBoxLayout()
            fila.addWidget(QLabel(f"Marca de agua «{html.escape(marca)}» "
                                  "cada"))
            self._spin_marca = QSpinBox()
            self._spin_marca.setRange(0, 100)
            self._spin_marca.setValue(1)
