def hay_version_nueva(info: dict, actual: str = "") -> bool:
    return version_tupla(info.get("version", "")) > version_tupla(actual or __version__)


def instalar_actualizacion(info: dict, programa: Path, progreso=None, timeout: float = 30.0) -> Path:
    """Baja la versión nueva, la verifica y reemplaza «programa» (el
    accion.py). La actual queda en la carpeta «historico» (al lado). Devuelve
    dónde quedó la copia de la versión anterior. Si algo falla, no cambia
    nada."""
    import hashlib
    import urllib.request
    if not info.get("sha256"):
        raise ValueError("El version.json no trae el «sha256» del archivo: sin él no se puede verificar.")
    programa = Path(programa)
    nuevo = programa.with_name(programa.stem + ".descarga.tmp")
    req = urllib.request.Request(info["url"], headers={"User-Agent": f"Accion/{__version__}"})
    h = hashlib.sha256()
    with urllib.request.urlopen(req, timeout=timeout) as r, open(nuevo, "wb") as f:
        total = int(r.headers.get("Content-Length") or 0)
        bajado = 0
        while True:
            trozo = r.read(65536)
            if not trozo:
                break
            f.write(trozo)
            h.update(trozo)
            bajado += len(trozo)
            if callable(progreso):
                progreso(bajado, total)
    try:
        if h.hexdigest() != info["sha256"]:
            raise ValueError("El archivo bajado no es idéntico al publicado (SHA-256 distinto). No se instaló.")
        fuente = nuevo.read_text(encoding="utf-8")
        compile(fuente, programa.name, "exec")             # (que sea Python de verdad, no una página de error)
        if "__version__" not in fuente:
            raise ValueError("El archivo bajado no parece ser ¡Acción!.")
        historico = programa.parent / "historico"
        historico.mkdir(exist_ok=True)
        copia = historico / f"{programa.stem}_v{__version__}_{datetime.now():%Y%m%d_%H%M}.py"
        copia.write_bytes(programa.read_bytes())
        import os as _os
        _os.replace(nuevo, programa)
        return copia
    finally:
        if nuevo.exists():
            try:
                nuevo.unlink()
            except OSError:
                pass


def reiniciar_programa(programa: Path) -> bool:
    """Abre de nuevo el programa (la versión recién instalada)."""
    from PySide6.QtCore import QProcess
    return bool(QProcess.startDetached(sys.executable, [str(programa)] + sys.argv[1:]))


class _TrabajoEnHilo(QObject):
    """Corre algo lento (la red) sin congelar la ventana; avisa al terminar."""
    listo = Signal(object, object)       # (resultado, error)
    avance = Signal(int, int)

    def __init__(self, fn, parent=None):
        super().__init__(parent)
        self.fn = fn

    def empezar(self) -> None:
        import threading

        def correr():
            try:
                res = self.fn(self)
                self.listo.emit(res, None)
            except Exception as ex:          # (la red, un archivo malo…)
                self.listo.emit(None, ex)
        threading.Thread(target=correr, daemon=True).start()


def leer_documento_de_ruta(path: Path) -> tuple:
    """(documento, solo_lectura) de un .accion, .fdx, .fountain o .celtx
    (para abrirlo al lado del principal). Un .accion con PIN se abre solo
    para leer (y copiar de él)."""
    suf = path.suffix.lower()
    if suf == ".accion":
        doc = documento_desde_json(path.read_text(encoding="utf-8"))
        return doc, bool(getattr(doc, "pin_hash", ""))
    if suf in (".fountain", ".spmd"):
        bloques, portada = leer_fountain(path)
    elif suf == ".fdx":
        bloques, portada = leer_fdx(str(path)), leer_fdx_portada(str(path))
    elif suf == ".celtx":
        bloques, portada = leer_celtx(str(path)), {}
    else:
        muestra = path.read_text(encoding="utf-8", errors="replace")[:500]
        if muestra.startswith("<?xml") and "FinalDraft" in muestra:
            bloques, portada = leer_fdx(str(path)), leer_fdx_portada(str(path))
        else:
            bloques, portada = leer_fountain(path)
    if not bloques:
        raise ValueError("El archivo no tiene un guion.")
    doc = Documento()
    doc.bloques = bloques
    doc.titulo = path.stem
    for k, v in (portada or {}).items():
        setattr(doc, k, v)
    return doc, False


class PanelSegundoGuion(QWidget):
    """📖📖 Otro guion al lado del principal (o en otra pantalla): se lee,
    se edita y se guarda aparte; «⬅ Al principal» lleva lo seleccionado
    (con sus tipos: escenas, personajes, diálogos…) al cursor del guion
    principal, y «Traer ➜» al revés. También se copia y pega, o se arrastra,
    de uno al otro."""
    cerrar_pedido = Signal()
    pantalla_pedida = Signal()

