class HiloDescargaVoz(QThread):
    """⬇ Baja whisper.cpp (unos MB) y el modelo Whisper de la calidad elegida
    (de 250 MB a 1,6 GB) a %LOCALAPPDATA%\\Accion\\voz, de a poco y sin molestar. Se puede
    pausar o cancelar (queda lo bajado) y sigue la próxima vez."""
    progreso = Signal(float, str)
    listo = Signal()
    fallo = Signal(str)

    def __init__(self, url_zip: Optional[str] = None, url_modelo: Optional[str] = None,
                 urls_gpu: Optional[list] = None, parent=None):
        import threading
        super().__init__(parent)
        self.url_zip = url_zip
        self.url_modelo = url_modelo                 # (None: el de la calidad elegida)
        self.modelo: Optional[Path] = None
        self.urls_gpu = None if urls_gpu is None else list(urls_gpu)
        self._cancelar = threading.Event()
        self._pausa = threading.Event()

    def cancelar(self) -> None:
        self._cancelar.set()
        self._pausa.clear()

    def pausar(self, si: bool = True) -> None:
        if si:
            self._pausa.set()
        else:
            self._pausa.clear()

    def _bajar_zip(self, urls: list, carpeta: str, lim, a: float, b: float, texto: str) -> None:
        """Baja un zip de whisper.cpp (probando las direcciones en orden) y
        lo deja abierto en voz\\<carpeta>."""
        import shutil
        import zipfile
        base = carpeta_voz()
        zp = base / (carpeta + ".zip")
        error = None
        for url in urls:
            try:
                _bajar_con_avance(url, zp, lim, lambda h, t: self.progreso.emit(
                    a + (b - a) * (h / t if t else 0), texto))
                error = None
                break
            except _Cancelado:
                raise
            except Exception as ex:
                error = ex
                zp.with_name(zp.name + ".parcial").unlink(missing_ok=True)
        if error is not None:
            raise error
        nueva = base / (carpeta + "_nuevo")
        shutil.rmtree(nueva, ignore_errors=True)
        try:
            with zipfile.ZipFile(zp) as z:
                z.extractall(nueva)
        except zipfile.BadZipFile:
            zp.unlink(missing_ok=True)
            raise RuntimeError("el zip de whisper.cpp llegó dañado (se vuelve a bajar la próxima vez)")
        exe = exe_whisper(nueva)
        if exe is None:
            shutil.rmtree(nueva, ignore_errors=True)
            zp.unlink(missing_ok=True)
            raise RuntimeError("el zip de whisper.cpp no trae whisper-server")
        if not sys.platform.startswith("win"):
            exe.chmod(0o755)
        shutil.rmtree(base / carpeta, ignore_errors=True)
        nueva.rename(base / carpeta)
        zp.unlink(missing_ok=True)

    def run(self) -> None:
        try:
            base = carpeta_voz()
            base.mkdir(parents=True, exist_ok=True)
            lim = _Limitador(self._cancelar, self._pausa)
            if self.urls_gpu is None:
                self.urls_gpu = urls_whisper_gpu()
            gpu = bool(self.urls_gpu) and exe_whisper(base / "whisper_gpu") is None
            fin_modelo = 0.82 if gpu else 1.0
            # 1) whisper.cpp para Windows (el que trabaja con el procesador: sirve en todos)
            if exe_whisper() is None:
                self._bajar_zip([u for u in (self.url_zip, URL_WHISPER_ZIP, URL_WHISPER_ZIP_RESPALDO) if u],
                                "whisper", lim, 0.0, 0.02, "Preparando el dictado (programa)…")
            # 2) el modelo de la calidad elegida (lo más pesado)
            url = self.url_modelo or URL_MODELOS_WHISPER + archivo_modelo_voz()
            destino = base / "modelos" / url.rsplit("/", 1)[-1]
            if not destino.is_file():
                self.progreso.emit(0.02, "Preparando el dictado (modelo de voz)…")
                sha = _sha256_publicado(url)
                _bajar_con_avance(url, destino, lim, lambda h, t: self.progreso.emit(
                    0.02 + (fin_modelo - 0.02) * (h / t if t else 0), "Preparando el dictado (modelo de voz)…"), sha)
            for otro in list((base / "modelos").glob("ggml-*.bin")) + list((base / "modelos").glob("*.parcial")):
                if otro.name != destino.name:             # (el de otra calidad ya no hace falta)
                    try:
                        otro.unlink()
                    except OSError:
                        pass                          # (si Whisper lo tiene abierto, se borra la próxima vez)
            self.modelo = destino
            self._licencias_y_listo()
            # 3) con una NVIDIA: whisper.cpp para la tarjeta (si falla, se dicta igual con el procesador)
            if gpu:
                try:
                    self._bajar_zip(self.urls_gpu, "whisper_gpu", lim, fin_modelo, 1.0,
                                    "Preparando el dictado (para la tarjeta gráfica)…")
                except _Cancelado:
                    raise
                except Exception:
                    settings_app().setValue(CLAVE_VOZ_SIN_GPU, True)
            self.listo.emit()
        except _Cancelado:
            pass
        except Exception as ex:
            self.fallo.emit(str(ex) or ex.__class__.__name__)

    def _licencias_y_listo(self) -> None:
        base = carpeta_voz()
        # (sus licencias, junto a ellos)
        lic = base / "licencias"
        lic.mkdir(parents=True, exist_ok=True)
        (lic / "whisper.cpp - LICENSE.txt").write_text(_MIT_WHISPER_CPP + _TEXTO_MIT, encoding="utf-8")
        (lic / "Whisper (modelo) - LICENSE.txt").write_text(_MIT_WHISPER_OPENAI + _TEXTO_MIT, encoding="utf-8")
        (lic / "LEEME.txt").write_text(
            "\ufeffDICTADO POR VOZ DE ¡ACCIÓN!\r\n\r\n"
            "whisper.cpp — licencia MIT (© The ggml authors). https://github.com/ggml-org/whisper.cpp\r\n"
            f"Modelo {nombre_modelo_voz(self.modelo)} ({self.modelo.name if self.modelo else ''}) — licencia MIT "
            "(© OpenAI), en el formato de "
            "whisper.cpp. https://github.com/openai/whisper\r\n\r\n"
            "Funciona solo en este computador: la voz no sale de él.\r\n", encoding="utf-8")
        (base / "LISTO").write_text(json.dumps({"modelo": self.modelo.name if self.modelo else "",
                                                "fecha": datetime.now().isoformat(
            timespec="seconds")}), encoding="utf-8")


def _ruta_corta(p: Path) -> str:
    """En Windows, la ruta «corta» (8.3, sin tildes ni eñes): whisper.cpp no
    abre bien un modelo si el nombre del usuario tiene, por ejemplo, «José»."""
    if not sys.platform.startswith("win"):
        return str(p)
    try:
        import ctypes
        n = ctypes.windll.kernel32.GetShortPathNameW(str(p), None, 0)
        if n:
            buf = ctypes.create_unicode_buffer(n)
            if ctypes.windll.kernel32.GetShortPathNameW(str(p), buf, n) and buf.value.isascii():
                return buf.value
    except Exception:
        pass
    return str(p)


def _hilos_whisper() -> int:
    import os
    n = os.cpu_count() or 4
    return max(2, min(8, n // 2 + 2))


def salud_whisper(url: str, timeout: float = 1.0) -> str:
    """«ok», «cargando» o «» (no responde)."""
    import urllib.error
    import urllib.request
    try:
        with _abrir_url_local(urllib.request.Request(url + "/health"), timeout) as r:
            d = json.loads(r.read().decode("utf-8") or "{}")
        return "ok" if str(d.get("status", "")).lower() == "ok" else "cargando"
    except urllib.error.HTTPError as ex:
        return "cargando" if ex.code == 503 else ""
    except Exception:
        return ""


def limpiar_texto_whisper(t: str) -> str:
    """Lo que dijo, sin las marcas de Whisper ([BLANK_AUDIO], (música)…) ni lo
    que «oye» en el silencio."""
    t = re.sub(r"\[[^\]]*\]|\([^)]*\)|\*[^*]*\*|♪+", " ", str(t or ""))
    t = " ".join(t.replace("\n", " ").split()).strip()
    n = re.sub(r"[^a-z0-9. ]", "", t.translate(_SIN_TILDE_VOZ).lower()).strip(" .")
    if not n or any(n == a or n.startswith(a) for a in _ALUCINACIONES_VOZ if len(a) > 12) or n in _ALUCINACIONES_VOZ:
        return ""
    return t


def transcribir_whisper(url: str, wav: bytes, prompt: str = "", audio_ctx: int = 0, timeout: float = 120.0) -> str:
    """Le manda el audio a whisper-server y devuelve lo que se dijo."""
    import urllib.request
    import uuid
    limite = "----accion" + uuid.uuid4().hex
    campos = {"response_format": "json", "language": "es", "temperature": "0.0", "no_timestamps": "true"}
    if prompt:
        campos["prompt"] = prompt
    if audio_ctx:
        campos["audio_ctx"] = str(int(audio_ctx))
    partes = []
    for k, v in campos.items():
        partes.append(f"--{limite}\r\nContent-Disposition: form-data; name=\"{k}\"\r\n\r\n{v}\r\n".encode("utf-8"))
    partes.append(f"--{limite}\r\nContent-Disposition: form-data; name=\"file\"; filename=\"voz.wav\"\r\n"
                  "Content-Type: audio/wav\r\n\r\n".encode("utf-8") + wav + b"\r\n")
    partes.append(f"--{limite}--\r\n".encode("utf-8"))
    req = urllib.request.Request(url + "/inference", data=b"".join(partes), method="POST",
                                 headers={"Content-Type": f"multipart/form-data; boundary={limite}"})
    with _abrir_url_local(req, timeout) as r:
        cuerpo = r.read().decode("utf-8", "replace")
    try:
        d = json.loads(cuerpo)
        texto = d.get("text", "") if isinstance(d, dict) else ""
        if not texto and isinstance(d, dict) and d.get("transcription"):
            texto = " ".join(str(s.get("text", "")) for s in d["transcription"])
    except ValueError:
        texto = cuerpo
    return limpiar_texto_whisper(texto)


def wav_de_pcm(pcm: bytes, tasa: int = TASA_VOZ) -> bytes:
    import io
    import wave
    b = io.BytesIO()
    with wave.open(b, "wb") as w:
        w.setnchannels(1)
        w.setsampwidth(2)
        w.setframerate(tasa)
        w.writeframes(pcm)
    return b.getvalue()


def nivel_pcm(pcm: bytes) -> float:
    """Qué tan fuerte suena (RMS de 0 a 32768)."""
    from array import array
    if len(pcm) < 2:
        return 0.0
    a = array("h")
    a.frombytes(pcm[: len(pcm) - len(pcm) % 2])
    if sys.byteorder != "little":
        a.byteswap()
    paso = max(1, len(a) // 400)
    m = a[::paso]
    return (sum(x * x for x in m) / max(1, len(m))) ** 0.5


def recortar_silencio(pcm: bytes, umbral: float, margen_s: float = 0.25, tasa: int = TASA_VOZ) -> bytes:
    """Saca el silencio del comienzo y del final (deja un poco de aire)."""
    trozo = int(tasa * 0.05) * 2
    n = len(pcm) // trozo
    con_voz = [i for i in range(n) if nivel_pcm(pcm[i * trozo:(i + 1) * trozo]) > umbral]
    if not con_voz:
        return b""
    m = int(margen_s / 0.05)
    a, b = max(0, con_voz[0] - m), min(n, con_voz[-1] + 1 + m)
    return pcm[a * trozo:b * trozo]


class ServidorVoz(QObject):
    """whisper-server, abierto una vez y con el modelo cargado (cargarlo tarda
    unos segundos; transcribir una frase, poco). Se cierra con ¡Acción!."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.proc = None
        self._url = ""
        self.modelo: Optional[Path] = None
        self.con_gpu = False
        self._t_inicio = 0.0
        app = QApplication.instance()
        if app is not None:
            app.aboutToQuit.connect(self.detener)

    def externo(self) -> str:
        """(un whisper-server que ya está abierto: ACCION_VOZ_SERVIDOR)"""
        import os
        return str(os.environ.get("ACCION_VOZ_SERVIDOR", "") or "").rstrip("/")

    @property
    def url(self) -> str:
        return self.externo() or self._url

    def iniciar(self, sin_gpu: bool = False) -> bool:
        """Lo abre (si no estaba): True si está abierto o abriéndose. Con una
        NVIDIA usa la versión para la tarjeta; si esa no abre, la del
        procesador."""
        import os
        import socket
        import subprocess
        import time
        if self.externo():
            return True
        if self.proc is not None and self.proc.poll() is None:
            return True
        mod = modelo_whisper()
        exe_gpu = None if (sin_gpu or _bool_ajuste(CLAVE_VOZ_SIN_GPU, False)) else exe_whisper(
            carpeta_voz() / "whisper_gpu")
        exe = exe_gpu or exe_whisper()
        self.con_gpu = exe_gpu is not None
        self._t_inicio = time.monotonic()
        if exe is None or not mod.is_file():
            return False
        self.modelo = mod
        puerto = PUERTO_WHISPER
        for p_ in range(PUERTO_WHISPER, PUERTO_WHISPER + 20):
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                if s.connect_ex(("127.0.0.1", p_)) != 0:
                    puerto = p_
                    break
        log = carpeta_voz() / "whisper_server.log"
        try:
            f = open(log, "ab")
            self.proc = subprocess.Popen(
                [str(exe), "-m", _ruta_corta(mod), "-l", "es", "-t", str(_hilos_whisper()), "-nt",
                 "--host", "127.0.0.1", "--port", str(puerto)],
                cwd=str(exe.parent), stdin=subprocess.DEVNULL, stdout=f, stderr=f,
                creationflags=0x08000000 if sys.platform.startswith("win") else 0,
                env=dict(os.environ))
        except Exception:
            self.proc = None
            return False
        self._url = f"http://127.0.0.1:{puerto}"
        return True

    def vivo(self) -> bool:
        """¿Sigue abierto? Si la versión para la tarjeta gráfica se cerró al
        abrir (un controlador antiguo, por ejemplo), se abre la del
        procesador y no se vuelve a probar la otra."""
        import time
        if self.externo():
            return True
        if self.proc is not None and self.proc.poll() is None:
            return True
        if self.proc is not None and getattr(self, "con_gpu", False) and \
                time.monotonic() - getattr(self, "_t_inicio", 0.0) < 120:
            settings_app().setValue(CLAVE_VOZ_SIN_GPU, True)
            self.proc = None
            return self.iniciar(sin_gpu=True)
        return False

    def detener(self) -> None:
        p, self.proc = self.proc, None
        if p is None or p.poll() is not None:
            return
        try:
            p.terminate()
            p.wait(5)
        except Exception:
            try:
                p.kill()
            except Exception:
                pass


class HiloTranscribirVoz(QThread):
    """Espera que Whisper esté listo (la primera vez carga el modelo) y le
    pide el texto de lo que se dijo."""
    listo = Signal(str, float)               # (texto, segundos que tardó)
    fallo = Signal(str)

    def __init__(self, url, wav: bytes, prompt: str, audio_ctx: int, vivo, parent=None):
        super().__init__(parent)
        self._url, self.wav, self.prompt, self.audio_ctx, self.vivo = url, wav, prompt, audio_ctx, vivo

    @property
    def url(self) -> str:
        """(puede cambiar: si la versión para la tarjeta no abre, se abre la otra)"""
        return self._url() if callable(self._url) else self._url

    def run(self) -> None:
        import time
        t0 = time.monotonic()
        try:
            for _ in range(600):                  # (hasta 5 minutos: un computador lento cargando el modelo)
                s = salud_whisper(self.url, 1.0)
                if s == "ok":
                    break
                if not s and not self.vivo():
                    raise RuntimeError("El reconocimiento de voz no pudo abrir en este computador (los detalles "
                                       "quedan en voz\\whisper_server.log).")
                time.sleep(0.5)
            else:
                raise RuntimeError("Whisper no terminó de cargar")
            t1 = time.monotonic()
            texto = transcribir_whisper(self.url, self.wav, self.prompt, self.audio_ctx)
            if not texto and self.audio_ctx:      # (por si la ventana corta le hizo mal)
                texto = transcribir_whisper(self.url, self.wav, self.prompt, 0)
            self.listo.emit(texto, time.monotonic() - t1 if t1 - t0 < 2 else -1.0)
        except Exception as ex:
            self.fallo.emit(str(ex) or ex.__class__.__name__)


class GrabadoraMicrofono(QObject):
    """🎤 Graba del micrófono (16 kHz, mono): con el waveIn de Windows (no
    necesita nada más) o, en otros sistemas, con Qt Multimedia. Con
    «hasta_silencio», termina sola cuando la persona deja de hablar."""
    nivel = Signal(float)
    listo = Signal(bytes)
    fallo = Signal(str)
    simulada: Optional[bytes] = None         # (pruebas: el audio que «se dijo»)

    def __init__(self, parent=None):
        import threading
        super().__init__(parent)
        self._parar = threading.Event()
        self._hilo = None
        self._datos = bytearray()
        self._qt = None
        self._estado: dict = {}
        self.umbral = 700.0

    def grabando(self) -> bool:
        return (self._hilo is not None and self._hilo.is_alive()) or self._qt is not None

    def empezar(self, hasta_silencio: bool = False) -> bool:
        import threading
        if self.grabando():
            return True
        self._parar.clear()
        self._datos = bytearray()
        self._estado = {"hasta_silencio": hasta_silencio}
        if GrabadoraMicrofono.simulada is not None:
            datos = bytes(GrabadoraMicrofono.simulada)
            self._datos = bytearray(datos)
            if hasta_silencio:
                QTimer.singleShot(30, lambda: self.listo.emit(bytes(self._datos)))
            else:
                self._qt = "simulada"
            return True
        if sys.platform.startswith("win"):
            self._hilo = threading.Thread(target=self._grabar_winmm, args=(hasta_silencio,), daemon=True)
            self._hilo.start()
            return True
        return self._empezar_qt(hasta_silencio)

    def hasta_silencio(self) -> None:
        """Se soltó F2 enseguida (un toque): sigue escuchando hasta que la
        persona deje de hablar."""
        self._estado["hasta_silencio"] = True
        if self._qt == "simulada":
            self._qt = None
            QTimer.singleShot(30, lambda: self.listo.emit(bytes(self._datos)))

    def terminar(self) -> None:
        if self._qt == "simulada":
            self._qt = None
            self.listo.emit(bytes(self._datos))
            return
        if self._qt is not None:
            self._terminar_qt()
            return
        self._parar.set()

    # (lo que llega del micrófono: el nivel y, si es «hasta silencio», cuándo terminar)
    def _vigilar(self, trozo: bytes, estado: dict) -> bool:
        """True = ya se puede terminar."""
        estado["t"] = seg = estado.get("t", 0.0) + len(trozo) / (2 * TASA_VOZ)
        if seg <= 0.2:                               # (el pitido de «te escucho»: no se graba)
            return False
        self._datos.extend(trozo)
        nv = nivel_pcm(trozo)
        try:
            self.nivel.emit(min(1.0, nv / 6000.0))
        except RuntimeError:
            return True
        if seg < 0.7:                                # (el ruido de la sala: lo más bajo del comienzo)
            estado.setdefault("niveles", []).append(nv)
            estado["piso"] = min(estado["niveles"])
        umbral = max(500.0, min(1500.0, estado.get("piso", 0.0)) * 3.0)
        self.umbral = umbral
        if nv > umbral:
            estado["voz"] = True
            estado["silencio"] = 0.0
        elif estado.get("voz"):
            estado["silencio"] = estado.get("silencio", 0.0) + len(trozo) / (2 * TASA_VOZ)
        if seg >= SEGUNDOS_MAX_VOZ:
            return True
        if estado.get("hasta_silencio"):
            if estado.get("voz") and estado.get("silencio", 0.0) >= 1.1:
                return True
            if not estado.get("voz") and seg >= 8.0:
                return True
        return False

    def _grabar_winmm(self, hasta_silencio: bool) -> None:
        import ctypes
        import time
        from ctypes import wintypes
        estado = self._estado
        try:
            winmm = ctypes.WinDLL("winmm")

            class WAVEFORMATEX(ctypes.Structure):
                _pack_ = 1
                _fields_ = [("wFormatTag", wintypes.WORD), ("nChannels", wintypes.WORD),
                            ("nSamplesPerSec", wintypes.DWORD), ("nAvgBytesPerSec", wintypes.DWORD),
                            ("nBlockAlign", wintypes.WORD), ("wBitsPerSample", wintypes.WORD),
                            ("cbSize", wintypes.WORD)]

            class WAVEHDR(ctypes.Structure):
                _fields_ = [("lpData", ctypes.c_void_p), ("dwBufferLength", wintypes.DWORD),
                            ("dwBytesRecorded", wintypes.DWORD), ("dwUser", ctypes.c_size_t),
                            ("dwFlags", wintypes.DWORD), ("dwLoops", wintypes.DWORD),
                            ("lpNext", ctypes.c_void_p), ("reserved", ctypes.c_size_t)]
            HWAVEIN = wintypes.HANDLE
            P_HDR = ctypes.POINTER(WAVEHDR)
            winmm.waveInOpen.argtypes = [ctypes.POINTER(HWAVEIN), wintypes.UINT, ctypes.POINTER(WAVEFORMATEX),
                                         ctypes.c_size_t, ctypes.c_size_t, wintypes.DWORD]
            for nombre in ("waveInPrepareHeader", "waveInUnprepareHeader", "waveInAddBuffer"):
                getattr(winmm, nombre).argtypes = [HWAVEIN, P_HDR, wintypes.UINT]
                getattr(winmm, nombre).restype = wintypes.UINT
            for nombre in ("waveInStart", "waveInStop", "waveInReset", "waveInClose"):
                getattr(winmm, nombre).argtypes = [HWAVEIN]
                getattr(winmm, nombre).restype = wintypes.UINT
            winmm.waveInOpen.restype = wintypes.UINT
            fmt = WAVEFORMATEX(1, 1, TASA_VOZ, TASA_VOZ * 2, 2, 16, 0)
            hwi = HWAVEIN()
            r = winmm.waveInOpen(ctypes.byref(hwi), 0xFFFFFFFF, ctypes.byref(fmt), 0, 0, 0)
            if r != 0:
                self.fallo.emit("No encontré un micrófono (o Windows no deja usarlo: Configuración → Privacidad → "
                                "Micrófono → permitir a las aplicaciones de escritorio).")
                return
            n_buf, tam = 8, int(TASA_VOZ * 2 * 0.1)          # 8 trozos de 100 ms
            bufs = [ctypes.create_string_buffer(tam) for _ in range(n_buf)]
            hdrs = [WAVEHDR(ctypes.cast(b, ctypes.c_void_p), tam, 0, 0, 0, 0, None, 0) for b in bufs]
            tam_h = ctypes.sizeof(WAVEHDR)
            for h in hdrs:
                winmm.waveInPrepareHeader(hwi, ctypes.byref(h), tam_h)
                winmm.waveInAddBuffer(hwi, ctypes.byref(h), tam_h)
            winmm.waveInStart(hwi)
            i = 0
            try:
                while not self._parar.is_set():
                    h = hdrs[i]
                    if h.dwFlags & 1:                        # WHDR_DONE: ese trozo ya llegó
                        trozo = ctypes.string_at(bufs[i], h.dwBytesRecorded)
                        h.dwBytesRecorded = 0
                        h.dwFlags &= ~1
                        winmm.waveInAddBuffer(hwi, ctypes.byref(h), tam_h)
                        i = (i + 1) % n_buf
                        if self._vigilar(trozo, estado):
                            break
                    else:
                        time.sleep(0.01)
            finally:
                winmm.waveInStop(hwi)
                winmm.waveInReset(hwi)
                for k in range(n_buf):                        # (lo último que alcanzó a grabar)
                    h = hdrs[(i + k) % n_buf]
                    if h.dwFlags & 1 and h.dwBytesRecorded:
                        self._datos.extend(ctypes.string_at(bufs[(i + k) % n_buf], h.dwBytesRecorded))
                for h in hdrs:
                    winmm.waveInUnprepareHeader(hwi, ctypes.byref(h), tam_h)
                winmm.waveInClose(hwi)
            self.listo.emit(bytes(self._datos))
        except Exception as ex:
            try:
                self.fallo.emit(f"No se pudo usar el micrófono: {ex}")
            except RuntimeError:
                pass

    def _empezar_qt(self, hasta_silencio: bool) -> bool:
        try:                                      # (sin «import» directo: así PyInstaller no suma Qt Multimedia
            import importlib                      #  al instalador de Windows, que graba con waveIn)
            _qm = importlib.import_module("PySide6.QtMultimedia")
            QAudioFormat, QAudioSource, QMediaDevices = _qm.QAudioFormat, _qm.QAudioSource, _qm.QMediaDevices
        except Exception:
            self.fallo.emit("No encontré cómo usar el micrófono en este sistema.")
            return False
        dev = QMediaDevices.defaultAudioInput()
        if dev.isNull():
            self.fallo.emit("No encontré un micrófono.")
            return False
        fmt = QAudioFormat()
        fmt.setSampleRate(TASA_VOZ)
        fmt.setChannelCount(1)
        fmt.setSampleFormat(QAudioFormat.SampleFormat.Int16)
        src = QAudioSource(dev, fmt, self)
        io_ = src.start()
        estado = self._estado
        self._qt = (src, io_, estado)

        def leer():
            if self._qt is None:
                return
            datos = bytes(io_.readAll())
            if datos and self._vigilar(datos, estado):
                self._terminar_qt()
        io_.readyRead.connect(leer)
        return True

    def _terminar_qt(self) -> None:
        if self._qt is None or self._qt == "simulada":
            return
        src, io_, _e = self._qt
        self._qt = None
        try:
            self._datos.extend(bytes(io_.readAll()))
            src.stop()
        except Exception:
            pass
        self.listo.emit(bytes(self._datos))


def _sonido_voz(tipo: str) -> None:
    """Un tono corto: «inicio» (escucho), «fin» (dejé de escuchar), «error»."""
    if not sys.platform.startswith("win"):
        return
    try:
        import math
        import struct
        import winsound
        ruta = carpeta_voz() / "sonidos" / f"{tipo}.wav"
        if not ruta.is_file():
            ruta.parent.mkdir(parents=True, exist_ok=True)
            notas = {"inicio": [(660, 0.07), (990, 0.09)], "fin": [(990, 0.07), (660, 0.09)],
                     "error": [(330, 0.12), (0, 0.05), (330, 0.12)]}.get(tipo, [(800, 0.1)])
            tasa = 22050
            muestras = bytearray()
            for f, d in notas:
                n = int(tasa * d)
                for k in range(n):
                    env = min(1.0, k / (tasa * 0.008), (n - k) / (tasa * 0.012))
                    v = int(9000 * env * math.sin(2 * math.pi * f * k / tasa)) if f else 0
                    muestras += struct.pack("<h", v)
            ruta.write_bytes(wav_de_pcm(bytes(muestras), tasa))
        winsound.PlaySound(str(ruta), winsound.SND_FILENAME | winsound.SND_ASYNC | winsound.SND_NODEFAULT)
    except Exception:
        pass


class VozGuia(QObject):
    """🔊 Lo que el programa le dice a la persona (con las voces de Windows,
    en español): qué escribió, dónde está, qué propone la IA."""
    hablo = Signal(str)                        # (también queda escrito: para pruebas y lectores de pantalla)

    def __init__(self, parent=None):
        super().__init__(parent)
        self.tts = None
        self.ultimo = ""
        self.n = 0                                 # (cuántas cosas lleva dichas)
        self._iniciado = False

    def _motor(self):
        if not self._iniciado:
            self._iniciado = True
            self.tts = _motor_voz()
            if self.tts is not None:
                try:
                    from PySide6.QtCore import QLocale
                    locs = [l for l in self.tts.availableLocales() if l.language() == QLocale.Language.Spanish]
                    pref = [l for l in locs if l.territory() in (QLocale.Territory.Chile, QLocale.Territory.Mexico)]
                    if pref or locs:
                        self.tts.setLocale((pref or locs)[0])
                    self.tts.setRate(0.1)
                except Exception:
                    pass
        return self.tts

    def decir(self, texto: str) -> None:
        texto = " ".join(str(texto or "").split())
        if not texto:
            return
        self.ultimo = texto
        self.n += 1
        self.hablo.emit(texto)
        t = self._motor()
        if t is None:
            return
        try:
            t.stop()
            t.say(texto)
        except Exception:
            pass

    def callar(self) -> None:
        if self.tts is not None:
            try:
                self.tts.stop()
            except Exception:
                pass

    def hablando(self) -> bool:
        t = self.tts
        if t is None:
            return False
        try:
            return t.state() == type(t).State.Speaking
        except Exception:
            return False

    def despues(self, cb) -> None:
        """Hace «cb» cuando termine de hablar (sin cortar lo que está diciendo)."""
        intentos = [0]

        def intentar():
            if self.hablando() and intentos[0] < 600:          # (hasta unos 3 minutos)
                intentos[0] += 1
                QTimer.singleShot(300, intentar)
                return
            cb()
        QTimer.singleShot(300, intentar)


# ── Lo que se dijo → qué hacer (sin IA) ──
_SIN_TILDE_VOZ = str.maketrans("áéíóúüÁÉÍÓÚÜñÑ", "aeiouuAEIOUUnN")   # (el mismo largo: las posiciones sirven)
_NUMEROS_VOZ = {"uno": 1, "una": 1, "primera": 1, "primero": 1, "dos": 2, "segunda": 2, "segundo": 2,
                "tres": 3, "tercera": 3, "tercero": 3, "cuatro": 4, "cuarta": 4, "cinco": 5, "quinta": 5,
                "seis": 6, "sexta": 6, "siete": 7, "septima": 7, "ocho": 8, "octava": 8, "nueve": 9, "novena": 9,
                "diez": 10, "decima": 10, "once": 11, "doce": 12, "trece": 13, "catorce": 14, "quince": 15,
                "dieciseis": 16, "diecisiete": 17, "dieciocho": 18, "diecinueve": 19, "veinte": 20,
                "ultima": -1, "ultimo": -1}
_VERBOS_DIALOGO = {"diga": "", "dice": "", "dijo": "", "dira": "", "responda": "", "responde": "",
                   "conteste": "", "contesta": "", "pregunte": "", "pregunta": "", "agregue": "", "agrega": "",
                   "exclame": "", "exclama": "", "conteste,": "", "hable": "", "habla": "",
                   "grite": "gritando", "grita": "gritando", "susurre": "susurrando", "susurra": "susurrando",
                   "murmure": "murmurando", "murmura": "murmurando", "llore": "llorando", "llora": "llorando"}
_MOMENTOS_VOZ = {"dia": "DÍA", "de dia": "DÍA", "noche": "NOCHE", "de noche": "NOCHE", "tarde": "TARDE",
                 "manana": "MAÑANA", "amanecer": "AMANECER", "atardecer": "ATARDECER", "anochecer": "ANOCHECER",
                 "madrugada": "MADRUGADA", "mediodia": "MEDIODÍA", "continuo": "CONTINUO", "continua": "CONTINUO",
                 "mas tarde": "MÁS TARDE", "momentos despues": "MOMENTOS DESPUÉS"}
_RESERVADAS_VOZ = {"accion", "escena", "parentesis", "transicion", "titulo", "premisa", "nota", "profesor",
                   "claqueta", "pregunta", "acotacion", "encabezado", "descripcion", "interior", "exterior",
                   "escaleta", "ficha", "tag", "etiqueta", "informe", "personaje", "dialogo", "guion"}
_SEP_VOZ = r"[\s,:;.\-–—]*"


def _norm_voz(s: str) -> str:
    return str(s or "").translate(_SIN_TILDE_VOZ).lower()


_UNIDADES_VOZ = {"un": 1, "uno": 1, "una": 1, "dos": 2, "tres": 3, "cuatro": 4, "cinco": 5, "seis": 6,
                 "siete": 7, "ocho": 8, "nueve": 9}
_DECENAS_VOZ = {"treinta": 30, "cuarenta": 40, "cincuenta": 50, "sesenta": 60, "setenta": 70, "ochenta": 80,
                "noventa": 90}


def _numero_voz(s: str) -> Optional[int]:
    """«3», «tres», «tercera», «veintiuno», «treinta y dos», «ciento cinco»…"""
    s = " ".join(_norm_voz(s).strip(" .").split())
    if s.isdigit():
        return int(s)
    if s in _NUMEROS_VOZ:
        return _NUMEROS_VOZ[s]
    total = 0
    m_ = re.match(r"^(?:cien|ciento)(?:\s+|$)", s)
    if m_:
        total, s = 100, s[m_.end():]
        if not s:
            return total
    if s.startswith("veinti") and s[6:] in _UNIDADES_VOZ:
        return total + 20 + _UNIDADES_VOZ[s[6:]]
    m_ = re.fullmatch(r"(\w+)(?:\s+y\s+(\w+))?", s)
    if m_ and m_.group(1) in _DECENAS_VOZ and (not m_.group(2) or m_.group(2) in _UNIDADES_VOZ):
        return total + _DECENAS_VOZ[m_.group(1)] + (_UNIDADES_VOZ[m_.group(2)] if m_.group(2) else 0)
    if total and s in _NUMEROS_VOZ and _NUMEROS_VOZ[s] > 0:
        return total + _NUMEROS_VOZ[s]
    return None


def _frase_voz(t: str) -> str:
    """El texto dictado, como va en el guion: sin comillas y con mayúscula
    (también después de «¡» o «¿»)."""
    t = " ".join(str(t or "").split()).strip(" \"'«»“”‘’")
    t = t.lstrip(",:;.-–— ")
    m_ = re.match(r"^([¡¿\"'«“(]*)(.)", t)
    return (t[:m_.end(1)] + m_.group(2).upper() + t[m_.end():]) if m_ else t


def encabezado_de_voz(resto: str) -> str:
    """«interior, bodega, de noche» → «INT. BODEGA - NOCHE»."""
    r = " ".join(str(resto or "").split()).strip(" .,:;")
    n = _norm_voz(r)
    pref = ""
    m_ = re.match(r"^(interior\s*(?:y|/|-)?\s*exterior|exterior\s*(?:y|/|-)?\s*interior|interior|exterior|"
                  r"int\.?|ext\.?)(?=[\s,.:;\-]|$)" + _SEP_VOZ, n)
    if m_:
        g = m_.group(1)
        pref = "INT./EXT." if ("interior" in g and "exterior" in g) else ("EXT." if g.startswith("ext") else "INT.")
        r, n = r[m_.end():], n[m_.end():]
    momento = ""
    for k in sorted(_MOMENTOS_VOZ, key=len, reverse=True):
        mm = re.search(r"(?:^|[\s,.:;\-]+)(?:(?:en|por|de|a|durante|hacia)\s+(?:la|el)\s+|al\s+|del\s+|"
                       r"(?:en|de)\s+)?" + re.escape(k) + r"$", n)
        if mm:
            momento = _MOMENTOS_VOZ[k]
            r, n = r[:mm.start()], n[:mm.start()]
            break
    lugar = re.sub(r"^(?:en\s+)?(?:la|el|los|las|un|una)\s+", "", r.strip(" .,:;-"), flags=re.I) or "LUGAR"
    return f"{pref or 'INT.'} {lugar.upper()}" + (f" - {momento}" if momento else "")


def interpretar_orden_voz(texto: str, personajes: list) -> dict:
    """Lo que se dijo → {"tipo": "bloques", "bloques": [(Elem, texto)]} ·
    {"tipo": "orden", "orden": …} · {"tipo": "libre", "texto": …} ·
    {"tipo": "pregunta", "texto": …} · {"tipo": "si"} · {"tipo": "no"} ·
    {"tipo": "vacio"}. No usa IA."""
    t = " ".join(str(texto or "").split()).strip()
    if not t:
        return {"tipo": "vacio"}
    n = _norm_voz(t)
    nc = n.strip(" .,!¡?¿")                      # (para las órdenes cortas)

    def orden(o: str, **kw) -> dict:
        return dict({"tipo": "orden", "orden": o}, **kw)

    # sí / no (para confirmar lo que propone el Profesor Claqueta)
    if re.fullmatch(r"(?:si|dale|ok|okey|de acuerdo|dejalo|acepto|perfecto|esta bien|bien|confirmo|si,? dejalo|"
                    r"si,? por favor)", nc):
        return {"tipo": "si"}
    if re.fullmatch(r"(?:no|no,? gracias|borralo|descartalo|cancela|cancelar|no lo dejes|mejor no)", nc):
        return {"tipo": "no"}
    # para revisar, moverse y corregir
    if re.fullmatch(r"(?:para|detente|silencio|callate|basta|stop|alto|ya)", nc):
        return orden("parar")
    if re.fullmatch(r"(?:ayuda|que puedo decir|que ordenes hay|comandos|instrucciones|ordenes)", nc):
        return orden("ayuda")
    if re.fullmatch(r"(?:repite|repitelo|repite eso|otra vez|que dijiste)", nc):
        return orden("repetir")
    if re.fullmatch(r"(?:borra|borrar|elimina|eliminar|quita|quitar|deshace|deshacer|deshaz)(?:\s+(?:eso|esto|"
                    r"lo ultimo|la ultima linea|el ultimo bloque|lo que escribi|lo ultimo que escribi|lo anterior))?",
                    nc):
        return orden("deshacer")
    if re.fullmatch(r"(?:rehace|rehacer|rehaz)(?:\s+eso)?", nc):
        return orden("rehacer")
    m_ = re.fullmatch(r"(?:lee|leeme|lea|leer|repite|repiteme)\s+(?:la\s+)?escena\s+(?:numero\s+)?(\w+(?:\s+\w+){0,3})",
                      nc)
    if m_ and m_.group(1) not in ("actual",):
        return orden("leer_escena", n=_numero_voz(m_.group(1)))
    if re.fullmatch(r"(?:lee|leeme|lea|leer|repite|repiteme)\s+(?:la|esta|mi)\s+escena(?:\s+actual)?", nc):
        return orden("leer_escena", n=0)
    if re.fullmatch(r"(?:lee|leeme|lea|leer)\s+(?:lo\s+ultimo|la\s+ultima\s+linea|lo\s+que\s+escribi|"
                    r"lo\s+ultimo\s+que\s+escribi)", nc):
        return orden("leer_ultimo")
    if re.fullmatch(r"(?:lee|leeme|lea|leer)\s+(?:todo|el\s+guion|todo\s+el\s+guion|desde\s+el\s+principio)", nc):
        return orden("leer_todo")
    if re.fullmatch(r"(?:donde\s+estoy|en\s+que\s+parte\s+estoy|en\s+que\s+escena\s+estoy|donde\s+voy)", nc):
        return orden("donde")
    m_ = re.fullmatch(r"(?:ve|ir|anda|vamos|salta|llevame|vuelve)\s+a(?:\s+la)?\s+escena\s+(?:numero\s+)?"
                      r"(\w+(?:\s+\w+){0,3})", nc)
    if m_:
        return orden("ir_escena", n=_numero_voz(m_.group(1)))
    if re.fullmatch(r"(?:ve|ir|anda|vamos|salta|llevame|vuelve)\s+al\s+(?:final|fin)(?:\s+del\s+guion)?", nc):
        return orden("ir_final")
    if re.fullmatch(r"(?:cuantas\s+escenas(?:\s+hay|\s+llevo|\s+tiene)?|resumen|como\s+va\s+el\s+guion|"
                    r"cuanto\s+llevo)", nc):
        return orden("resumen")
    if re.fullmatch(r"(?:personajes|que\s+personajes\s+hay|quienes\s+estan|lista\s+de\s+personajes|"
                    r"cuales\s+son\s+los\s+personajes)", nc):
        return orden("personajes")
    if re.fullmatch(r"(?:guarda|guardar|guardalo|guarda\s+el\s+guion|graba\s+el\s+guion|guardar\s+el\s+guion)", nc):
        return orden("guardar")
    m_ = re.match(r"^(?:el\s+)?titulo(?:\s+del\s+guion)?(?:\s+es)?" + _SEP_VOZ, n)
    if m_ and n[m_.end():].strip():
        return orden("titulo", texto=_frase_voz(t[m_.end():]).rstrip("."))
    m_ = re.match(r"^(?:la\s+)?premisa(?:\s+es)?" + _SEP_VOZ, n)
    if m_ and n[m_.end():].strip():
        return orden("premisa", texto=_frase_voz(t[m_.end():]))
    # al Profesor Claqueta
    m_ = re.match(r"^(?:pregunta(?:le)?(?:\s+al\s+profesor(?:\s+claqueta)?)?|consulta|tengo\s+una\s+pregunta)"
                  + _SEP_VOZ, n)
    if m_ and n[m_.end():].strip():
        return {"tipo": "pregunta", "texto": _frase_voz(t[m_.end():])}
    m_ = re.match(r"^(?:profesor(?:\s+claqueta)?|claqueta|profe)" + _SEP_VOZ, n)
    if m_ and n[m_.end():].strip():
        return {"tipo": "libre", "texto": _frase_voz(t[m_.end():]), "pedido": True}
    # bloques con su tipo dicho
    m_ = re.match(r"^(?:accion|descripcion|narracion|narra|describe)" + _SEP_VOZ, n)
    if m_ and n[m_.end():].strip():
        return {"tipo": "bloques", "bloques": [(Elem.ACCION, _frase_voz(t[m_.end():]))]}
    m_ = re.match(r"^(?:nueva\s+escena|escena|encabezado(?:\s+de\s+escena)?)" + _SEP_VOZ, n)
    if m_ and n[m_.end():].strip():
        return {"tipo": "bloques", "bloques": [(Elem.ESCENA, encabezado_de_voz(t[m_.end():]))]}
    if re.match(r"^(?:interior|exterior)(?=[\s,.:;\-]|$)", n):
        return {"tipo": "bloques", "bloques": [(Elem.ESCENA, encabezado_de_voz(t))]}
    m_ = re.match(r"^dialogo" + _SEP_VOZ, n)
    if m_ and n[m_.end():].strip():
        return {"tipo": "bloques", "bloques": [(Elem.DIALOGO, _frase_voz(t[m_.end():]))]}
    m_ = re.match(r"^personaje" + _SEP_VOZ, n)
    if m_ and n[m_.end():].strip() and len(n[m_.end():].split()) <= 4:
        return {"tipo": "bloques", "bloques": [(Elem.PERSONAJE, nombre_canonico_ia(
            t[m_.end():].strip(" .,"), personajes or []))]}
    m_ = re.match(r"^(?:entre\s+parentesis|parentesis|acotacion)" + _SEP_VOZ, n)
    if m_ and n[m_.end():].strip():
        p_ = _frase_voz(t[m_.end():]).rstrip(".")
        return {"tipo": "bloques", "bloques": [(Elem.PARENTESIS, "(" + p_[:1].lower() + p_[1:] + ")")]}
    m_ = re.match(r"^transicion" + _SEP_VOZ, n)
    if m_ and n[m_.end():].strip():
        tr = _frase_voz(t[m_.end():]).rstrip(".").upper()
        return {"tipo": "bloques", "bloques": [(Elem.TRANSICION, tr if tr.endswith(":") else tr + ":")]}
    if re.fullmatch(r"(?:corte\s+a(?:\s+negro)?|fundido\s+a\s+negro|fundido\s+(?:de\s+)?(?:entrada|salida)|"
                    r"disolvencia(?:\s+a)?|corte\s+directo(?:\s+a)?)", nc):
        tr = t.strip(" .").upper()
        return {"tipo": "bloques", "bloques": [(Elem.TRANSICION, tr if tr.endswith(":") else tr + ":")]}
    # diálogo: «que Camila diga: …», «Camila dice, …», «Camila: …»
    verbos = "|".join(sorted({v.rstrip(",") for v in _VERBOS_DIALOGO}, key=len, reverse=True))
    m_ = re.match(r"^(?P<y>y\s+)?(?P<que>que\s+)?(?:(?:el|la|los|las)\s+)?(?P<quien>[a-z][a-z ]{0,38}?)\s+"
                  r"(?P<verbo>" + verbos + r")(?=[\s,:;.\-–—]|$)(?P<sep>" + _SEP_VOZ + r")(?P<texto>.+)$", n)
    claves = {_clave_nombre(x) for x in personajes or []}
    if m_:
        quien = t[m_.start("quien"):m_.end("quien")].strip()
        conocido = _clave_nombre(quien) in claves
        corto = len(quien.split()) <= 4 and _norm_voz(quien.split()[0]) not in _RESERVADAS_VOZ
        con_pausa = bool(re.search(r"[,:;.\-–—]", m_.group("sep")))
        if corto and (m_.group("que") or conocido or con_pausa):
            nombre = nombre_canonico_ia(quien, personajes or [])
            dice = _frase_voz(t[m_.start("texto"):])
            if dice:
                out = [(Elem.PERSONAJE, nombre)]
                modo = _VERBOS_DIALOGO.get(m_.group("verbo"), "")
                if modo:
                    out.append((Elem.PARENTESIS, f"({modo})"))
                out.append((Elem.DIALOGO, dice))
                return {"tipo": "bloques", "bloques": out}
    m_ = re.match(r"^(?P<quien>[a-z][a-z]{1,20}(?:\s[a-z]{2,20})?)\s*:\s*(?P<texto>.+)$", n)
    if m_ and _norm_voz(m_.group("quien").split()[0]) not in _RESERVADAS_VOZ:
        quien = t[m_.start("quien"):m_.end("quien")]
        dice = _frase_voz(t[m_.start("texto"):])
        if dice:
            return {"tipo": "bloques", "bloques": [(Elem.PERSONAJE, nombre_canonico_ia(quien, personajes or [])),
                                                    (Elem.DIALOGO, dice)]}
    return {"tipo": "libre", "texto": _frase_voz(t)}


