def categoria_tag_de_voz(texto: str) -> str:
    """«utilería» → «utileria»; «sonido» → «sfx_sonido»…; «» si no se sabe."""
    n = _norm_voz(texto).strip(" .")
    alias = {"sonido": "sfx_sonido", "efectos de sonido": "sfx_sonido", "efectos especiales": "sfx_especiales",
             "decoracion": "set_dressing", "decorado": "set_dressing", "maquillaje": "maquillaje",
             "peinado": "maquillaje", "comida": "comida", "bebida": "comida", "auto": "vehiculos",
             "vehiculo": "vehiculos", "animal": "animales", "extra": "extras", "doble": "dobles",
             "luz": "iluminacion", "luces": "iluminacion", "props": "utileria", "objeto": "utileria"}
    if n in alias:
        return alias[n]
    for cid, nombre, _e in CATEGORIAS_TAG:
        nn = _norm_voz(nombre)
        if n == nn or n == cid or nn.startswith(n) or n in nn.split(" "):
            return cid
    return ""


def destino_de_voz(texto: str, personajes: list) -> str:
    """«las fichas de personajes» → «fichas_personajes»; «la ficha de
    Camila» → «ficha:CAMILA»; «el informe narrativo» → …; «» si no."""
    t = " ".join(str(texto or "").split()).strip(" .")
    n = _norm_voz(t)
    m_ = re.match(r"^(?:la\s+)?ficha\s+de(?:l\s+personaje)?\s+(.+)$", n)
    if m_ and not re.match(r"^(?:esta|la)\s+escena", m_.group(1)) and not m_.group(1).startswith(
            ("los ", "las ", "personajes", "escenas", "locaciones")):
        return "ficha:" + nombre_canonico_ia(t[m_.start(1):], personajes)
    m_ = re.match(r"^(?:el\s+)?informe\s+(?:de\s+|del\s+)?(?:los\s+|las\s+|la\s+|el\s+)?(\w+)", n)
    if m_ and m_.group(1) in _TIPOS_INFORME_VOZ:
        return "informe:" + _TIPOS_INFORME_VOZ[m_.group(1)]
    for destino, expr in DESTINOS_PROGRAMA:
        if re.search(expr, t, flags=re.IGNORECASE) or re.search(expr, n, flags=re.IGNORECASE):
            return destino
    return ""


def interpretar_orden_programa(texto: str, personajes: list) -> Optional[dict]:
    """Lo dicho, como orden para el programa (abrir, leer, exportar, fichas,
    escaleta, tags…), o None si no es una."""
    t = " ".join(str(texto or "").split()).strip()
    n = _norm_voz(t)
    nc = n.strip(" .,!¡?¿")
    tc = t.strip(" .,!¡?¿")                       # (alineado con «nc»: mismas posiciones)
    S = _SEP_VOZ

    def o(orden: str, **kw) -> dict:
        return dict({"tipo": "programa", "orden": orden}, **kw)
    if re.fullmatch(r"(?:desactiva|desactivar|apaga|apagar|sal|salir|termina|terminar)\s+(?:del?\s+)?(?:el\s+)?modo"
                    r"\s+(?:de\s+)?(?:discapacidad\s+visual|ciego|voz|accesible)", nc):
        return o("modo_visual_off")
    if re.fullmatch(r"(?:activa|activar|enciende|prende)\s+(?:el\s+)?modo\s+(?:de\s+)?(?:discapacidad\s+visual|ciego|"
                    r"voz|accesible)", nc):
        return o("modo_visual_on")
    m_ = re.match(r"^(?:lee|leeme|lea|leer)\s+(?:el\s+)?informe\s+(?:de\s+|del\s+)?(?:los\s+|las\s+|la\s+|el\s+)?(\w+)", nc)
    if m_:
        return o("leer_informe", informe=_TIPOS_INFORME_VOZ.get(m_.group(1), ""), dicho=m_.group(1))
    m_ = re.match(r"^(?:exporta|exportar|guarda|guardar|saca|sacar)\s+(?:el\s+)?informe\s+(?:de\s+|del\s+)?"
                  r"(?:los\s+|las\s+|la\s+|el\s+)?(\w+)", nc)
    if m_:
        return o("exportar_informe", informe=_TIPOS_INFORME_VOZ.get(m_.group(1), ""), dicho=m_.group(1))
    if re.fullmatch(r"(?:exporta|exportar|guarda|guardar|pasa|pasar|saca|sacar)\s+(?:el\s+guion\s+)?(?:a|en|como)\s+pdf|"
                    r"(?:exporta|exportar)\s+(?:el\s+)?guion|(?:haz|hazme|saca)\s+(?:el\s+|un\s+)?pdf(?:\s+del\s+guion)?",
                    nc):
        return o("exportar_pdf")
    if re.fullmatch(r"(?:imprime|imprimir|imprimelo)(?:\s+el\s+guion)?", nc):
        return o("imprimir")
    if re.fullmatch(r"(?:nuevo|crea|crear|empieza|empezar)\s+(?:un\s+)?(?:nuevo\s+)?guion(?:\s+nuevo)?", nc):
        return o("nuevo_guion")
    if re.fullmatch(r"(?:que|cuales)\s+guiones\s+(?:hay|tengo)|(?:mis|lista\s+de(?:\s+los)?)\s+guiones", nc):
        return o("listar_guiones")
    if re.fullmatch(r"(?:que|cuales)\s+ventanas\s+(?:hay|puedo\s+abrir|tiene(?:\s+el\s+programa)?|se\s+pueden\s+abrir)|"
                    r"(?:lista\s+de(?:\s+las)?\s+)?ventanas", nc):
        return o("listar_ventanas")
    m_ = re.match(r"^(?:abre|abrir|carga|cargar)\s+(?:el\s+)?guion\s+(.+)$", nc)
    if m_:
        return o("abrir_guion", nombre=tc[m_.start(1):m_.end(1)].strip(" ."))
    # fichas de personaje
    m_ = re.match(r"^(?:lee|leeme|lea)\s+(?:la\s+)?ficha\s+de\s+(?:esta|la)\s+escena$", nc)
    if m_:
        return o("leer_ficha_escena")
    m_ = re.match(r"^(?:lee|leeme|lea)\s+(?:la\s+)?ficha\s+de(?:l\s+personaje)?\s+(.+)$", nc)
    if m_:
        return o("leer_ficha", nombre=nombre_canonico_ia(tc[m_.start(1):m_.end(1)].strip(" ."), personajes))
    campos_e = "|".join(sorted(CAMPOS_FICHA_ESCENA_VOZ, key=len, reverse=True))
    m_ = re.match(r"^(?:la\s+)?ficha\s+de\s+(?:esta|la)\s+escena" + S + r"(" + campos_e + r")(?:\s+es)?" + S + r"(.+)$", n)
    if m_:
        return o("ficha_escena", campo=CAMPOS_FICHA_ESCENA_VOZ[m_.group(1)], valor=_frase_voz(t[m_.start(2):]))
    campos = "|".join(sorted(CAMPOS_FICHA_VOZ, key=len, reverse=True))
    m_ = re.match(r"^(?:la\s+)?ficha\s+de(?:l\s+personaje)?\s+(.+?)" + S + r"(" + campos + r")(?:\s+es)?" + S + r"(.+)$", n)
    if m_:
        return o("ficha_campo", nombre=nombre_canonico_ia(t[m_.start(1):m_.end(1)], personajes),
                 campo=CAMPOS_FICHA_VOZ[m_.group(2)], valor=_frase_voz(t[m_.start(3):]).rstrip("."))
    m_ = re.match(r"^(?:nuevo\s+personaje|crea(?:r)?\s+(?:un\s+)?(?:nuevo\s+)?personaje|agrega\s+(?:un\s+)?personaje)"
                  + S + r"(.+)$", n)
    if m_:
        return o("nuevo_personaje", nombre=t[m_.start(1):].strip(" .").upper())
    # escaleta
    if re.fullmatch(r"(?:lee|leeme|lea)\s+la\s+escaleta", nc):
        return o("leer_escaleta")
    m_ = re.match(r"^(?:escaleta,?\s+)?(?:borra|elimina|quita)\s+(?:el\s+)?punto\s+(\w+(?:\s+\w+){0,2}?)(?:\s+de\s+la\s+escaleta)?$",
                  nc)
    if m_:
        return o("borrar_escaleta", n=_numero_voz(m_.group(1)))
    m_ = re.match(r"^(?:en\s+la\s+)?escaleta" + S + r"(?:agrega|anade|añade|nuevo\s+punto|punto)?" + S + r"(.+)$", n)
    if m_ and n[m_.end(0) - len(m_.group(1)):].strip():
        return o("agregar_escaleta", texto=_frase_voz(t[m_.start(1):]))
    # tags
    if re.fullmatch(r"(?:lee|leeme|lea|que)\s+(?:los\s+)?(?:tags|etiquetas)(?:\s+(?:de|hay\s+en)\s+(?:esta|la)\s+escena)?"
                    r"(?:\s+hay)?", nc):
        return o("leer_tags")
    m_ = re.match(r"^(?:tag|etiqueta|agrega\s+(?:el\s+)?tag|marca)" + S + r"(.+?)\s*(?:,|:|\s+como|\s+en)\s+"
                  r"(?:categoria\s+)?(?:de\s+)?(\w+(?:\s+\w+){0,2})$", n)
    if m_:
        cat = categoria_tag_de_voz(m_.group(2))
        if cat:
            return o("agregar_tag", contenido=_frase_voz(t[m_.start(1):m_.end(1)]).rstrip("."), categoria=cat)
    # abrir / ir a una parte del programa
    m_ = re.match(r"^(?:abre|abrir|abreme|muestra(?:me)?|ve\s+a|anda\s+a|llevame\s+a|quiero\s+ver)\s+(.+)$", nc)
    if m_:
        destino = destino_de_voz(tc[m_.start(1):m_.end(1)], personajes)
        if destino:
            return o("abrir", destino=destino)
    return None


def texto_para_voz(t: str) -> str:
    """Un texto de informe, para leerlo en voz alta (sin las líneas de
    adorno y con los nombres en mayúsculas dichos bien)."""
    lineas = []
    for ln in str(t or "").splitlines():
        ln = re.sub(r"[═=─━_*•·▸►]{2,}", " ", ln).strip(" ─=═-·")
        if not ln.strip():
            continue
        lineas.append(_palabra_hablada(" ".join(ln.split())))
    return ". ".join(x.rstrip(".") for x in lineas) + ("." if lineas else "")


def _palabra_hablada(s: str) -> str:
    """«CAMILA» → «Camila» (si no, la voz lo deletrea)."""
    return " ".join(w.capitalize() if w.isupper() and len(w) > 1 else w for w in str(s or "").split())


def hablado_de_bloques(bloques: list) -> str:
    """Los bloques como se leen en voz alta."""
    partes = []
    i = 0
    while i < len(bloques):
        el, tx = bloques[i]
        tx = str(tx or "").strip()
        if el == Elem.ESCENA:
            e = tx.upper()
            e = re.sub(r"^INT\./EXT\.?|^EXT\./INT\.?|^I/E\.?", "Interior y exterior.", e)
            e = re.sub(r"^INT\.?\s", "Interior. ", e)
            e = re.sub(r"^EXT\.?\s", "Exterior. ", e)
            e = e.replace(" - ", ". ")
            partes.append("Escena. " + _palabra_hablada(e).rstrip(".") + ".")
        elif el == Elem.PERSONAJE:
            quien = _palabra_hablada(re.sub(r"\s*\(.*?\)\s*", " ", tx).strip())
            modo, dice = "", ""
            j = i + 1
            if j < len(bloques) and bloques[j][0] == Elem.PARENTESIS:
                modo = str(bloques[j][1]).strip("() ")
                j += 1
            if j < len(bloques) and bloques[j][0] == Elem.DIALOGO:
                dice = str(bloques[j][1]).strip()
                j += 1
            partes.append(f"{quien}{', ' + modo if modo else ''}: {dice}" if dice else f"{quien}.")
            i = j
            continue
        elif el == Elem.PARENTESIS:
            partes.append(tx.strip("() ") + ".")
        elif el == Elem.TRANSICION:
            partes.append("Transición: " + _palabra_hablada(tx).rstrip(":").lower() + ".")
        elif el == Elem.DIALOGO:
            partes.append(tx)
        elif el == Elem.PLANO and tx:
            partes.append("Plano: " + _palabra_hablada(tx).lower() + ".")
        elif el in (Elem.ACTO_INICIO, Elem.ACTO_FIN) and tx:
            partes.append(_palabra_hablada(tx).rstrip(".") + ".")
        elif tx:
            partes.append(tx)
        i += 1
    return " ".join(p_ for p_ in partes if p_)


