TEXTO_FIN_TUTORIAL_VOZ = ("Terminaste el tutorial. ¡Felicitaciones! El guion de práctica quedó abierto: di nuevo "
                          "guion para empezar el tuyo. Que escribas una gran película.")


def es_orden_tutorial_voz(texto: str) -> str:
    """«tutorial», «empieza el tutorial», «enséñame a usar el programa» →
    «empezar»; «tutorial desde el principio» → «principio»; «» si no."""
    n = " ".join(_norm_voz(texto).strip(" .,!¡?¿").split())
    if re.fullmatch(r"(?:(?:empieza|empezar|inicia|iniciar|abre|abrir|comienza|comenzar|quiero|haz|hacer|"
                    r"repite|repetir|vuelve\s+a\s+hacer)\s+)?(?:el\s+)?tutorial(?:\s+(?:por|de)\s+voz)?\s+"
                    r"(?:desde\s+(?:el\s+)?(?:principio|comienzo|inicio|cero)|de\s+nuevo|otra\s+vez)", n):
        return "principio"
    if re.fullmatch(r"(?:(?:empieza|empezar|inicia|iniciar|abre|abrir|comienza|comenzar|quiero|haz|hacer|"
                    r"continua|continuar|sigue|seguir)\s+)?(?:con\s+)?(?:el\s+)?tutorial(?:\s+(?:por|de)\s+voz)?|"
                    r"ensename(?:\s+a\s+usar(?:\s+el\s+programa)?)?", n):
        return "empezar"
    return ""


def navegacion_tutorial_voz(texto: str) -> tuple:
    """Lo que se dice para moverse en el tutorial → (qué, número)."""
    n = " ".join(_norm_voz(texto).strip(" .,!¡?¿").split())
    if re.fullmatch(r"(?:sal|salir|salgamos|termina|terminar|cierra|cerrar|deja|dejar)\s+(?:del?\s+)?"
                    r"(?:el\s+)?tutorial", n):
        return ("salir", 0)
    if re.fullmatch(r"(?:siguiente(?:\s+paso)?|sigue|seguir|sigamos|continua|continuar|avanza|adelante|"
                    r"listo|ya|proximo(?:\s+paso)?)", n):
        return ("siguiente", 0)
    if re.fullmatch(r"(?:anterior|paso\s+anterior|atras|vuelve|volver|retrocede)", n):
        return ("anterior", 0)
    if re.fullmatch(r"(?:repite(?:lo|me)?|repetir|otra\s+vez|de\s+nuevo|que\s+dijiste|no\s+entendi|"
                    r"repite\s+el\s+paso)", n):
        return ("repite", 0)
    if re.fullmatch(r"(?:que\s+lecciones\s+hay|lecciones|cuales\s+son\s+las\s+lecciones|indice|"
                    r"(?:en\s+)?que\s+leccion\s+(?:estoy|voy|vamos))", n):
        return ("lecciones", 0)
    if re.fullmatch(r"ayuda|ayuda\s+del\s+tutorial", n):
        return ("ayuda", 0)
    m_ = re.fullmatch(r"(?:ve\s+a\s+la\s+|ir\s+a\s+la\s+|la\s+)?leccion\s+(\w+)", n)
    if m_:
        k = _NUMEROS_VOZ.get(m_.group(1)) or (int(m_.group(1)) if m_.group(1).isdigit() else 0)
        return ("leccion", k) if k else ("", 0)
    return ("", 0)


class TutorialVoz(QObject):
    """♿ El tutorial por voz: guía con la voz, espera que la persona diga
    cada orden con F2, la ejecuta de verdad en un guion de práctica y sigue."""

    def __init__(self, dictado):
        super().__init__(dictado)
        self.d = dictado
        self.vp = dictado.vp
        self.activo = False
        self.leccion = 0
        self.paso = 0
        self.fallos = 0
        self.base: dict = {}
        self.esperando_ia = ""                       # «escribir» o «pregunta»: esperando al Profesor
        self._t0_ia = 0.0
        self._doc_practica = None
        self._lecciones = lecciones_tutorial_voz()
        self._t_ia = QTimer(self)
        self._t_ia.setInterval(300)
        self._t_ia.timeout.connect(self._revisar_ia)

    # ── dónde va ──
    def lecciones(self) -> list:
        return self._lecciones

    def paso_actual(self) -> dict:
        return self._lecciones[self.leccion]["pasos"][self.paso]

    def _guardar_avance(self) -> None:
        try:
            settings_app().setValue(CLAVE_TUTORIAL_VOZ, f"{self.leccion}.{self.paso}")
        except Exception:
            pass

    def _doc(self):
        return self.vp.editor.documento

    def _foto(self) -> None:
        doc = self._doc()
        self.base = {"bloques": len(doc.bloques), "voz": self.d.voz.n, "propuesta": self.d.propuesta is not None}
        self.fallos = 0

    # ── empezar y terminar ──
    def empezar(self, desde_el_principio: bool = False) -> bool:
        import os
        vp = self.vp
        if not voz_descargada() and not os.environ.get("ACCION_VOZ_SERVIDOR"):
            self.d.voz.decir("El tutorial por voz necesita el reconocimiento de voz, que todavía se está "
                             "preparando. Cuando esté listo, activa el modo con Control más F2 y di: tutorial.")
            try:
                vp.statusBar().showMessage("♿ El tutorial por voz necesita el dictado: Configuración → 🎙 Dictado "
                                           "por voz → ⬇ Descargar ahora", 9000)
            except Exception:
                pass
            return False
        if not self.d.modo_visual:
            vp.poner_modo_visual(True, anunciar=False)
        lec, paso = 0, 0
        guardado = str(settings_app().value(CLAVE_TUTORIAL_VOZ, "") or "")
        terminado = _bool_ajuste(CLAVE_TUTORIAL_VOZ_FIN, False)
        if guardado and not desde_el_principio and not terminado:
            try:
                lec, paso = (int(x) for x in guardado.split(".", 1))
            except ValueError:
                lec, paso = 0, 0
            if not (0 <= lec < len(self._lecciones)) or not (0 <= paso < len(self._lecciones[lec]["pasos"])):
                lec, paso = 0, 0
        settings_app().setValue(CLAVE_TUTORIAL_VOZ_FIN, False)
        self.activo = True
        previo = ""
        if (lec, paso) != (0, 0):
            previo = (f"Seguimos donde quedaste, en la lección {lec + 1}: {self._lecciones[lec]['titulo']}. "
                      "Si prefieres empezar de cero, di: tutorial desde el principio. ")
        self._ir(lec, paso, previo=previo)
        try:
            vp.statusBar().showMessage("♿ Tutorial por voz: F2 y di lo que te pide («repite», «siguiente», "
                                       "«salir del tutorial»)", 10000)
        except Exception:
            pass
        return True

    def salir(self, decir: bool = True) -> None:
        self.activo = False
        self.esperando_ia = ""
        self._t_ia.stop()
        if decir:
            self.d.voz.decir("Salí del tutorial. Para volver, di: tutorial, y seguimos donde quedaste.")

    def _terminar(self, previo: str = "") -> None:
        self.activo = False
        self.esperando_ia = ""
        self._t_ia.stop()
        settings_app().setValue(CLAVE_TUTORIAL_VOZ_FIN, True)
        settings_app().setValue(CLAVE_TUTORIAL_VOZ, "")
        self.d.voz.decir((previo + " " if previo else "") + TEXTO_FIN_TUTORIAL_VOZ)

    # ── moverse ──
    def _ir(self, lec: int, paso: int, previo: str = "") -> None:
        """Va a un paso y lo dice (antes, lo que haya que decir primero)."""
        self.esperando_ia = ""
        self._t_ia.stop()
        if lec >= len(self._lecciones):
            self._terminar(previo)
            return
        nueva = lec != self.leccion or paso == 0
        self.leccion, self.paso = lec, paso
        texto = previo
        if nueva and self._lecciones[lec].get("practica"):
            texto += self._preparar_practica(lec)
        if nueva and self._lecciones[lec].get("ia") and not self.d._ia_permitida_router():
            texto += self._sin_ia_texto()
            self._ir(lec + 1, 0, previo=texto)
            return
        p = self.paso_actual()
        if p.get("si_propuesta") and self.d.propuesta is None:
            self._ir(*self._siguiente_de(lec, paso), previo=texto)    # (no hubo propuesta: no hay qué confirmar)
            return
        self._foto()
        self._guardar_avance()
        self.d.voz.decir((texto + " " if texto else "") + p["texto"])
        QTimer.singleShot(450, self._ventana_del_paso)

    def _ventana_del_paso(self) -> None:
        """Los pasos de las ventanas necesitan la de fichas abierta (si alguien
        se saltó el paso de abrirla, se abre); los demás, ninguna ventana
        encima del guion (si quedó una, se cierra guardando)."""
        if not self.activo:
            return
        p = self.paso_actual()
        w = ventana_para_voz(self.vp)
        if p.get("ventana") and w is None:
            nombre = next((k for k in self._doc().fichas if _clave_nombre(k) == "ana"), "")
            self.vp.ir_a_destino("ficha:" + nombre if nombre else "fichas_personajes")
        elif not p.get("ventana") and w is not None and not isinstance(w, QMessageBox) and \
                self.leccion < len(self._lecciones) and self.d.estado != "escuchando":
            self.d._cerrar_ventana(w, mapa_de_ventana(w), guardar=True)

    def _siguiente_de(self, lec: int, paso: int) -> tuple:
        if paso + 1 < len(self._lecciones[lec]["pasos"]):
            return lec, paso + 1
        return lec + 1, 0

    def _anterior_de(self, lec: int, paso: int) -> tuple:
        if paso > 0:
            return lec, paso - 1
        if lec > 0:
            return lec - 1, len(self._lecciones[lec - 1]["pasos"]) - 1
        return 0, 0

    @staticmethod
    def _sin_ia_texto() -> str:
        return ("En este computador el Profesor Claqueta no está disponible, así que saltamos su lección. Cuando "
                "esté listo, se le pide con la palabra profesor: por ejemplo, profesor, haz que Ana dude y se vaya. ")

    def _preparar_practica(self, lec: int) -> str:
        """Las lecciones de práctica escriben en un guion aparte (nunca en el
        tuyo): si hace falta, se abre uno nuevo y se le pone algo para practicar."""
        vp = self.vp
        aviso = ""
        if self._doc_practica is None or vp.editor.documento is not self._doc_practica:
            sucio = getattr(vp, "_doc_dirty", False) and any((b.texto or "").strip()
                                                              for b in vp.editor.documento.bloques)
            self.d._antes_de_cambiar_guion()
            vp._accion_nuevo(confirmar=False)
            self._doc_practica = vp.editor.documento
            aviso = ("Para practicar abrí un guion nuevo, en blanco" +
                     (": el que tenías quedó guardado. " if sucio else ". "))
        doc = vp.editor.documento
        if lec >= 2 and not any(b.elem == Elem.ESCENA for b in doc.bloques):
            if not (doc.titulo or "").strip():
                doc.titulo = "La última función"
            vp.editor.insertar_bloques_dictados([
                (Elem.ESCENA, "INT. SALA DE CLASES - DÍA"), (Elem.ACCION, "Ana entra corriendo a la sala vacía."),
                (Elem.PERSONAJE, "ANA"), (Elem.DIALOGO, "¿Dónde están todos?")])
            aviso += "Le puse una escena con Ana para practicar. "
        return aviso

    # ── lo que dice la persona ──
    def navegar(self, texto: str) -> bool:
        """Las órdenes del tutorial. True: ya se respondió."""
        que, k = navegacion_tutorial_voz(texto)
        if not que:
            return False
        if que == "salir":
            self.salir()
        elif que == "siguiente":
            if self.esperando_ia:
                self.esperando_ia = ""
                self._t_ia.stop()
            self._ir(*self._siguiente_de(self.leccion, self.paso))
        elif que == "anterior":
            lec, paso = self._anterior_de(self.leccion, self.paso)
            if self._lecciones[lec]["pasos"][paso].get("si_propuesta"):
                lec, paso = self._anterior_de(lec, paso)
            self._ir(lec, paso)
        elif que == "repite":
            self.d.voz.decir(self.paso_actual()["texto"])
        elif que == "lecciones":
            nombres = " ".join(f"{i + 1}, {l_['titulo']}." for i, l_ in enumerate(self._lecciones))
            self.d.voz.decir(f"Estás en la lección {self.leccion + 1}. Las lecciones son: {nombres} Para ir a una, "
                             "di lección y su número.")
        elif que == "ayuda":
            self.d.voz.decir(f"Estás en el tutorial por voz, lección {self.leccion + 1}: "
                             f"{self._lecciones[self.leccion]['titulo']}. Puedes decir: repite, siguiente, anterior, "
                             "qué lecciones hay, lección y un número, o salir del tutorial.")
        elif que == "leccion":
            if 1 <= k <= len(self._lecciones):
                self._ir(k - 1, 0)
            else:
                self.d.voz.decir(f"Hay {len(self._lecciones)} lecciones. Di lección y un número del 1 al "
                                 f"{len(self._lecciones)}.")
        return True

    def antes(self, texto: str) -> bool:
        """Antes de ejecutar lo dicho: True si el tutorial ya se hizo cargo
        (sus órdenes, la prueba del micrófono, o algo que no es una orden)."""
        if self.navegar(texto):
            return True
        p = self.paso_actual()
        if p.get("escuchar"):
            dicho = " ".join(str(texto or "").split()).strip(" .") or "algo"
            self._avanzar(p["bien"].replace("{dicho}", dicho))
            return True
        if self.esperando_ia:
            self.d.voz.decir("Espera un poco: el Profesor Claqueta está pensando. Si no quieres esperar, di: "
                             "siguiente.")
            return True
        if "ok" not in p:
            return False                              # (un paso que solo explica: lo dicho se hace igual)
        if not p.get("ia"):
            if ventana_para_voz(self.vp) is not None:
                return False                          # (hay una ventana abierta: lo dicho va a ella)
            # (en la práctica, lo que no es una orden no se escribe ni se le pasa a la IA: se explica)
            res = interpretar_orden_voz(texto, self.d._personajes())
            if res["tipo"] in ("libre", "vacio") and not res.get("pedido") and \
                    interpretar_orden_programa(texto, self.d._personajes()) is None:
                self._fallo(f"No reconocí una orden en lo que dijiste: {' '.join(str(texto).split())}. ")
                return True
        return False

    def despues(self, texto: str, res: dict, n_voz: int, desde_ia: bool = False) -> None:
        """Después de ejecutar lo dicho: ¿era lo que pedía el paso?"""
        if not self.activo or self.esperando_ia:
            return
        p = self.paso_actual()
        ok = p.get("ok")
        if ok is None:
            if not desde_ia and res.get("tipo") not in ("tutorial",):
                self.d.voz.decir((self._respuesta(n_voz) + " " if self._respuesta(n_voz) else "") +
                                 "Cuando quieras seguir con el tutorial, di: siguiente.")
            return
        try:
            bien = bool(ok(self, res))
        except Exception:
            bien = False
        if not bien:
            if not desde_ia:
                self._fallo(self._respuesta(n_voz) + " " if self._respuesta(n_voz) else "")
            return
        if p.get("ia"):
            import time
            self.esperando_ia = p["ia"]
            self._t0_ia = time.monotonic()
            self.base["voz_ia"] = self.d.voz.n
            self._t_ia.start()
            return
        self._avanzar(self._respuesta(n_voz) + " " + p.get("bien", "") if self._respuesta(n_voz)
                      else p.get("bien", ""))

    def _respuesta(self, n_voz: int) -> str:
        """Lo que respondió el programa a la orden (para decirlo junto con lo del tutorial)."""
        return self.d.voz.ultimo if self.d.voz.n > n_voz else ""

    def _avanzar(self, previo: str) -> None:
        self._ir(*self._siguiente_de(self.leccion, self.paso), previo=(previo.strip() + " ") if previo else "")

    def _fallo(self, previo: str) -> None:
        self.fallos += 1
        p = self.paso_actual()
        extra = " Si prefieres saltarte este paso, di: siguiente." if self.fallos >= 2 else ""
        self.d.voz.decir(f"{previo}En este paso, di: {p['ejemplo']}.{extra}")

    # ── esperando al Profesor Claqueta ──
    def _revisar_ia(self) -> None:
        if not self.activo or not self.esperando_ia:
            self._t_ia.stop()
            return
        d = self.d
        ultimo = _norm_voz(d.voz.ultimo)
        sin_ia = any(x in ultimo for x in ("no esta listo", "no pudo responder", "esta apagada",
                                           "no puede escribir"))
        if sin_ia:
            self.esperando_ia = ""
            self._t_ia.stop()
            self._despues_de_hablar(lambda: self._ir(self.leccion + 1, 0, previo=self._sin_ia_texto()))
            return
        if self.esperando_ia == "escribir":
            if d.propuesta is not None:
                self.esperando_ia = ""
                self._t_ia.stop()
                self.leccion, self.paso = self._siguiente_de(self.leccion, self.paso)
                self._foto()                              # (el Profesor ya pidió «di sí o no»)
                self._guardar_avance()
                return
            hecho = len(self._doc().bloques) > self.base["bloques"] or "solo aconseja" in ultimo or \
                "no propuso nada" in ultimo
        else:
            hecho = d.estado == "inactivo" and d.voz.n > self.base.get("voz_ia", 0) and \
                "le pregunto al profesor" not in ultimo
        if hecho:
            self.esperando_ia = ""
            self._t_ia.stop()
            self._despues_de_hablar(lambda: self._avanzar(self.paso_actual().get("bien", "")))
        elif __import__("time").monotonic() - self._t0_ia > 120:
            self.esperando_ia = ""
            self._t_ia.stop()
            self._ir(*self._siguiente_de(self.leccion, self.paso),
                     previo="El Profesor Claqueta está tardando mucho. Sigamos; puedes volver a esta lección "
                            "más tarde. ")

    def _despues_de_hablar(self, cb) -> None:
        """Cuando termine de leer la respuesta del Profesor (sin interrumpirla)."""
        def hacer():
            if not self.activo or self.d.estado == "escuchando":
                return
            cb()
        self.d.voz.despues(hacer)


class DictadoVoz(QObject):
    """🎙 F2: escuchar → Whisper → la orden → el guion (y lo dice en voz alta)."""
    cambio = Signal()

    def __init__(self, vp):
        super().__init__(vp)
        self.vp = vp
        self.estado = "inactivo"                 # escuchando · transcribiendo · pensando · inactivo
        self.voz = VozGuia(self)
        self.grab = GrabadoraMicrofono(self)
        self.grab.listo.connect(self._audio_listo)
        self.grab.fallo.connect(self._fallo_micro)
        self.grab.nivel.connect(self._nivel)
        self.propuesta: Optional[list] = None    # (lo que propuso el Profesor Claqueta, esperando sí o no)
        self.ultimo_texto = ""
        self.ultimo_resultado: dict = {}
        self._t_presion = 0.0
        self._manos_libres = False
        self._lento = False
        self._hilo = None
        self._hilo_ia = None
        self._turno_ia = 0
        self._avisado_lento = False
        self.modo_visual = False                 # (♿ todo el programa por voz)
        self._nv = 0.0
        self.lbl = QLabel("")
        self.lbl.setStyleSheet("color: #fbbf24; font-family: 'Segoe UI', sans-serif; font-size: 9pt; "
                               "font-weight: 600;")
        self.lbl.hide()
        try:
            vp.statusBar().addPermanentWidget(self.lbl)
        except Exception:
            pass
        # (F2 se escucha en la ventana principal: las teclas que nadie usa suben hasta ella. Un filtro
        # en todo el programa revisaría cada evento de cada ventana y hacía más lento, por ejemplo,
        # cambiar de tema; solo en el modo ♿, donde F2 sirve en cualquier ventana, se pone en todo)
        vp.installEventFilter(self)
        self._filtro_global = False
        self._anunciadas: set = set()               # (♿ las ventanas abiertas que ya se dijeron)
        self._campo_voz = None                      # (el campo al que se fue con «ve a…»)
        self._deshacer_ventana = None
        self._cerrada_por_voz = None
        self._msj_cierre = ""
        self.tutorial = TutorialVoz(self)          # (♿ el tutorial por voz)

    def escuchar_en_todo(self, si: bool) -> None:
        app = QApplication.instance()
        if app is None or si == self._filtro_global:
            return
        if si:
            app.installEventFilter(self)
        else:
            app.removeEventFilter(self)
        self._filtro_global = si

    # ── F2 (mantener: hablar mientras está apretada; tocar: hasta el silencio) ──
    def eventFilter(self, obj, ev) -> bool:
        t = ev.type()
        if t in (QEvent.Type.Show, QEvent.Type.Hide) and self.modo_visual and isinstance(obj, QWidget) and \
                obj.isWindow() and obj is not self.vp:
            if t == QEvent.Type.Show and id(obj) not in self._anunciadas and es_ventana_para_anunciar(obj, self.vp):
                self._anunciadas.add(id(obj))
                QTimer.singleShot(300, obj, lambda o=obj: self._ventana_se_abrio(o))
            elif t == QEvent.Type.Hide and id(obj) in self._anunciadas:
                self._anunciadas.discard(id(obj))
                if getattr(self, "_cerrada_por_voz", None) is not obj and not isinstance(obj, QMessageBox):
                    QTimer.singleShot(250, self._volver_de_ventana)
            return False
        if t == QEvent.Type.KeyPress and getattr(ev, "key", None) and ev.key() == Qt.Key.Key_F2 and \
                (ev.modifiers() & (Qt.KeyboardModifier.ControlModifier | Qt.KeyboardModifier.AltModifier |
                                   Qt.KeyboardModifier.ShiftModifier)) == Qt.KeyboardModifier.ControlModifier:
            # ♿ Ctrl+F2: activa o desactiva el modo discapacidad visual (sin tener que ver el botón)
            if ev.isAutoRepeat():
                return True
            if QApplication.activeWindow() is self.vp or (self.modo_visual and QApplication.activeWindow()):
                self.vp.poner_modo_visual(not self.modo_visual)
                return True
            return False
        if t in (QEvent.Type.KeyPress, QEvent.Type.KeyRelease) and getattr(ev, "key", None) and \
                ev.key() == Qt.Key.Key_F2 and not ev.modifiers() & (Qt.KeyboardModifier.ControlModifier |
                                                                      Qt.KeyboardModifier.AltModifier):
            activa = QApplication.activeWindow()
            if self.modo_visual:
                if activa is None:
                    return False                  # (♿ en cualquier ventana de ¡Acción!)
            elif activa is not self.vp or QApplication.activeModalWidget() is not None:
                return False
            if ev.isAutoRepeat():
                return True
            if t == QEvent.Type.KeyPress:
                self.f2_presionada()
            else:
                self.f2_soltada()
            return True
        return False

    def f2_presionada(self) -> None:
        import time
        self.voz.callar()
        if self.estado == "escuchando":            # (estaba escuchando con «tocar»: F2 otra vez = listo)
            self._manos_libres = False
            self.grab.terminar()
            return
        self._t_presion = time.monotonic()
        self.escuchar(hasta_silencio=False)

    def f2_soltada(self) -> None:
        import time
        if self.estado != "escuchando" or self._manos_libres:
            return
        if time.monotonic() - self._t_presion < 0.4:   # un toque: escucha hasta que la persona calle
            self._manos_libres = True
            self._pintar("🎙 Te escucho… (cuando calles, escribo; F2: listo)")
            self.grab.hasta_silencio()
            return
        self.grab.terminar()

    def escuchar(self, hasta_silencio: bool = True) -> None:
        """Empieza a escuchar (F2, o el botón «🎙 Dictar»)."""
        if self.estado == "pensando":                # (no esperar al Profesor Claqueta: se cancela)
            self._cancelar_ia()
        if self.estado == "transcribiendo":
            self.voz.decir("Espera, todavía estoy escribiendo lo anterior.")
            return
        if self.estado == "escuchando":
            self.grab.terminar()
            return
        if not voz_descargada():
            g = getattr(self.vp, "_voz", None)
            if g is not None and g.estado in ("descargando", "pausado"):
                self.voz.decir(f"El dictado se está preparando: va en el {int(g.fraccion * 100)} por ciento.")
            else:
                self.voz.decir("El dictado por voz todavía no está descargado. Se prepara en Configuración, "
                               "dictado por voz.")
            _sonido_voz("error")
            return
        g = getattr(self.vp, "_voz", None)
        if g is not None and not g.servidor.vivo():
            g.servidor.iniciar()
        if not dictado_activo():
            settings_app().setValue(CLAVE_VOZ_ACTIVA, True)
        self._manos_libres = hasta_silencio
        if not self.grab.empezar(hasta_silencio=hasta_silencio):
            return
        self.estado = "escuchando"
        _sonido_voz("inicio")
        self._pintar("🎙 Te escucho…" + (" (cuando calles, escribo)" if hasta_silencio else " (suelta F2: listo)"))

    def _nivel(self, v: float) -> None:
        self._nv = v
        if self.estado == "escuchando":
            barras = "▮" * max(1, int(v * 8)) + "▯" * (8 - max(1, int(v * 8)))
            self.lbl.setText(f"🎙 Te escucho {barras}")

    def _fallo_micro(self, error: str) -> None:
        self.estado = "inactivo"
        _sonido_voz("error")
        self._pintar("🎙 " + error)
        self.voz.decir(error)

    def _audio_listo(self, pcm: bytes) -> None:
        self.estado = "inactivo"
        _sonido_voz("fin")
        recorte = recortar_silencio(pcm, max(450.0, self.grab.umbral * 0.8)) \
            if GrabadoraMicrofono.simulada is None else pcm
        if len(recorte) < int(TASA_VOZ * 2 * 0.25):
            self._pintar("🎙 No te escuché.")
            self.voz.decir("No te escuché. Prueba otra vez, más cerca del micrófono.")
            return
        g = getattr(self.vp, "_voz", None)
        url = g.servidor.url if g is not None else ""
        if not url and g is not None and g.servidor.iniciar():
            url = g.servidor.url
        if not url:
            _sonido_voz("error")
            self._pintar("🎙 No pude abrir el reconocimiento de voz.")
            self.voz.decir("No pude abrir el reconocimiento de voz. Revisa Configuración, dictado por voz.")
            return
        seg = len(recorte) / (2 * TASA_VOZ)
        # (con el procesador, o si una frase tardó: escucha 15 s en vez de 30, la mitad del trabajo)
        sin_gpu = g is not None and not g.servidor.con_gpu
        ctx = AUDIO_CTX_PROCESADOR if ((sin_gpu or self._lento) and seg <= 14.0) else 0
        self.estado = "transcribiendo"
        self._pintar("🎙 Escribiendo lo que dijiste…")
        self._hilo = HiloTranscribirVoz((lambda: g.servidor.url) if g is not None else url, wav_de_pcm(recorte),
                                        self._prompt(), ctx, g.servidor.vivo if g is not None else (lambda: True),
                                        self)
        self._hilo.listo.connect(self._texto_listo)
        self._hilo.fallo.connect(self._fallo_transcribir)
        self._hilo.finished.connect(self._hilo.deleteLater)
        self._hilo.start()

    def _prompt(self) -> str:
        nombres = [_palabra_hablada(n) for n in self._personajes()[:20]]
        return ("Dictado de un guion de cine en español de Chile. "
                + (f"Personajes: {', '.join(nombres)}. " if nombres else "")
                + "Acción. Escena, interior, exterior, día, noche. Paréntesis. Transición, corte a. Que Camila diga.")

    def _fallo_transcribir(self, error: str) -> None:
        self.estado = "inactivo"
        _sonido_voz("error")
        self._pintar("🎙 " + error)
        self.voz.decir("No pude entender el audio. " + error)

    def _texto_listo(self, texto: str, seg: float) -> None:
        self.estado = "inactivo"
        if seg > 4.0:
            self._lento = True
        self.ultimo_texto = texto
        if not texto:
            self._pintar("🎙 No te entendí.")
            self.voz.decir("No te entendí. Prueba otra vez.")
            return
        self.procesar(texto)
        if seg > 6.0 and not self._avisado_lento and calidad_voz() != "rapido":
            self._avisado_lento = True            # (una vez: en un computador lento, sugerir la calidad rápida)
            aviso = ("Este computador tarda en entender la voz. En Configuración, dictado por voz, puedes elegir la "
                     "calidad rápida.")
            self._pintar("🎙 " + aviso)
            self.voz.decir(self.voz.ultimo + " " + aviso)
        g = getattr(self.vp, "_voz", None)
        if g is not None and g.hilo is None and voz_pendiente() and voz_descarga_permitida():
            g.quizas_empezar()                    # (p. ej., la tarjeta gráfica no sirvió: baja el modelo rápido)

    # ── lo que se dijo → lo que se hace ──
    def _personajes(self) -> list:
        return personajes_del_documento(self.vp.editor.documento)

    def procesar(self, texto: str, desde_ia: bool = False) -> dict:
        """Ejecuta lo que se dijo (también sirve para probar sin micrófono).
        Con el ♿ tutorial por voz andando, él ve primero lo dicho (sus
        órdenes) y después si era lo que pedía el paso."""
        tut = self.tutorial
        if not desde_ia:
            pedido = es_orden_tutorial_voz(texto)
            if pedido:
                if tut.activo and pedido == "empezar":
                    self.voz.decir("Ya estás en el tutorial. " + tut.paso_actual()["texto"])
                else:
                    tut.empezar(desde_el_principio=pedido == "principio")
                return {"tipo": "tutorial"}
            if tut.activo and tut.antes(texto):
                return {"tipo": "tutorial"}
        n_voz = self.voz.n
        res = self._procesar(texto, desde_ia)
        if tut.activo:
            tut.despues(texto, res, n_voz, desde_ia=desde_ia)
        return res

    def _procesar(self, texto: str, desde_ia: bool = False) -> dict:
        if self.modo_visual:
            ventana = ventana_para_voz(self.vp)
            if ventana is not None:                   # (♿ hay una ventana abierta: lo dicho va a ella)
                r = self._en_ventana(texto, ventana, desde_ia)
                if r is not None:
                    return r
        res = interpretar_orden_voz(texto, self._personajes())
        if res["tipo"] == "libre" and not res.get("pedido"):
            prog = interpretar_orden_programa(texto, self._personajes())
            if prog is not None:
                res = prog
            elif self.modo_visual and not desde_ia and self._ia_permitida_router():
                res = {"tipo": "ruta", "texto": res["texto"]}
        self.ultimo_resultado = res
        if self.propuesta is not None:
            if res["tipo"] == "si":
                self._aceptar_propuesta()
                return res
            self.propuesta = None
            if res["tipo"] == "no":
                self._pintar("🎙 Descartado.")
                self.voz.decir("Descartado. No escribí nada.")
                return res
        tipo = res["tipo"]
        if tipo == "programa":
            self._orden_programa(res)
            return res
        if tipo == "ruta":
            self._a_la_ia(res["texto"], "router")
            return res
        if tipo == "libre" and desde_ia:
            self.voz.decir("No entendí qué hacer. Di «ayuda» para escuchar lo que puedes pedir.")
            return res
        if tipo in ("si", "no"):
            self.voz.decir("No hay nada que confirmar.")
        elif tipo == "bloques":
            self._escribir(res["bloques"])
        elif tipo == "orden":
            self._orden(res)
        elif tipo == "pregunta":
            self._a_la_ia(res["texto"], "pregunta")
        elif tipo == "libre":
            if self._ia_permitida():
                self._a_la_ia(res["texto"], "libre")
            elif res.get("pedido"):
                self.voz.decir("El Profesor Claqueta no puede escribir por ti en este computador. Dime la orden "
                               "directa, por ejemplo: acción, y lo que pasa.")
            else:
                self._escribir([(Elem.ACCION, res["texto"])], como="acción")
        return res

    # ── ♿ las ventanas por voz ──
    def _en_ventana(self, texto: str, ventana, desde_ia: bool = False) -> Optional[dict]:
        """Con una ventana abierta, lo dicho va a ella. None: no era para la
        ventana (callar, repetir, leer la escaleta…) y se hace lo de siempre."""
        try:
            mapa = mapa_de_ventana(ventana)
        except RuntimeError:
            return None
        res = interpretar_orden_ventana(texto, mapa)
        if res is None:
            base = interpretar_orden_voz(texto, self._personajes())
            tb, ob = base["tipo"], base.get("orden")
            prog = interpretar_orden_programa(texto, self._personajes())
            if tb == "orden" and ob in ("parar", "repetir"):
                return None
            if prog is not None and prog["orden"] in ("modo_visual_off", "modo_visual_on"):
                return None
            if tb in ("si", "no"):
                res = {"tipo": "ventana", "orden": "boton", "nombre": "si" if tb == "si" else "no", "confirmar": True}
            elif tb == "orden" and ob == "ayuda":
                res = {"tipo": "ventana", "orden": "ayuda"}
            elif tb == "orden" and ob == "deshacer":
                res = {"tipo": "ventana", "orden": "deshacer"}
            elif tb == "orden" and ob == "guardar":
                res = {"tipo": "ventana", "orden": "boton", "nombre": "guardar", "guardar": True}
            elif prog is not None:
                return self._programa_en_ventana(prog, ventana, mapa)
            else:
                foco = self._campo_con_foco(mapa)
                if foco is not None and foco["tipo"] in ("linea", "texto") and not desde_ia:
                    res = {"tipo": "ventana", "orden": "dictar", "texto": _frase_voz(texto)}
                else:
                    res = {"tipo": "ventana", "orden": "no_entendi", "texto": " ".join(str(texto).split())}
        self.ultimo_resultado = res
        self._hacer_en_ventana(res, ventana, mapa)
        return res

    def _programa_en_ventana(self, prog: dict, ventana, mapa: dict) -> Optional[dict]:
        """Una orden del programa dicha con una ventana abierta."""
        o = prog["orden"]
        if isinstance(ventana, VentanaFichasPersonaje) and o in ("ficha_campo", "nuevo_personaje", "leer_ficha"):
            self._fichas_en_ventana(prog, ventana)
            r = dict(prog, en_ventana=True)
            self.ultimo_resultado = r
            return r
        if o in ("leer_escaleta", "leer_tags", "leer_informe", "leer_ficha", "leer_ficha_escena", "listar_guiones",
                 "listar_ventanas", "abrir", "exportar_informe"):
            return None                               # (no choca con la ventana: se hace lo de siempre)
        self.voz.decir(f"Estás en la ventana {mapa['titulo']}. Para eso, primero ciérrala: di cerrar.")
        r = {"tipo": "ventana", "orden": "fuera"}
        self.ultimo_resultado = r
        return r

    def _fichas_en_ventana(self, prog: dict, w) -> None:
        """«ficha de Ana, edad 17» con la ventana de fichas abierta: se llena
        en la ventana (si no, al cerrarla se perdería)."""
        o = prog["orden"]
        nombre = str(prog.get("nombre", "")).strip()
        if o == "nuevo_personaje":
            nombre = nombre.upper()
            if nombre and nombre not in w._fichas:
                w._fichas[nombre] = Ficha(personaje=nombre)
                w._refrescar_lista(seleccionar=nombre)
                self._marcar_cambio()
                self.voz.decir(f"Creé la ficha de {_palabra_hablada(nombre)} y la elegí. Di el campo y lo que va: "
                               "por ejemplo, edad, 17.")
            else:
                self.voz.decir(f"{_palabra_hablada(nombre)} ya tiene ficha." if nombre else "¿Cómo se llama?")
            return
        clave = next((k for k in w._fichas if _clave_nombre(k) == _clave_nombre(nombre)), None)
        if clave is None:
            self.voz.decir(f"No hay ficha de {_palabra_hablada(nombre)}. Di nuevo personaje, y su nombre.")
            return
        if w._nombre_actual != clave:
            w._seleccionar(clave)
        if o == "leer_ficha":
            self.voz.decir(f"Ficha de {_palabra_hablada(clave)}. " + self._leer_todo(mapa_de_ventana(w), solo_llenos=True))
            return
        campo = prog.get("campo", "")
        ww = w._widgets.get(campo)
        if ww is None:
            self.voz.decir(f"Esa ficha no tiene el campo {NOMBRES_CAMPO_FICHA.get(campo, campo)}.")
            return
        c = next((x for x in mapa_de_ventana(w)["campos"] if x["w"] is ww), None) or \
            {"w": ww, "tipo": _tipo_campo_voz(ww), "nombre": NOMBRES_CAMPO_FICHA.get(campo, campo)}
        self._recordar_para_deshacer(c)
        nuevo = poner_valor_campo(c, prog.get("valor", ""))
        self._marcar_cambio()
        self.voz.decir(f"Ficha de {_palabra_hablada(clave)}: {NOMBRES_CAMPO_FICHA.get(campo, c['nombre'])}, {nuevo}.")

    def _campo_con_foco(self, mapa: dict) -> Optional[dict]:
        fw = QApplication.focusWidget()
        elegido = getattr(self, "_campo_voz", None)
        for c in mapa["campos"]:
            try:
                if c["w"] is elegido or (fw is not None and (c["w"] is fw or c["w"].isAncestorOf(fw))):
                    return c
            except RuntimeError:
                continue
        return None

    def _recordar_para_deshacer(self, c: dict) -> None:
        w, tipo = c["w"], c["tipo"]
        try:
            antes = {"linea": lambda: w.text(), "texto": lambda: w.toPlainText(), "opciones": lambda: w.currentText(),
                     "numero": lambda: w.value(), "fecha": lambda: w.date(), "casilla": lambda: w.isChecked(),
                     "opcion": lambda: w.isChecked()}.get(tipo, lambda: None)()
        except RuntimeError:
            return
        self._deshacer_ventana = (w, tipo, antes, c["nombre"])

    def _deshacer_en_ventana(self) -> str:
        d = getattr(self, "_deshacer_ventana", None)
        self._deshacer_ventana = None
        if not d:
            return "No hay nada que deshacer aquí."
        w, tipo, antes, nombre = d
        try:
            if tipo == "linea":
                w.setText(antes)
                w.editingFinished.emit()
            elif tipo == "texto":
                w.setPlainText(antes)
            elif tipo == "opciones":
                i = w.findText(antes)
                w.setCurrentIndex(i) if i >= 0 else w.setEditText(antes)
            elif tipo == "numero":
                w.setValue(antes)
            elif tipo == "fecha":
                w.setDate(antes)
            elif tipo in ("casilla", "opcion") and w.isChecked() != antes:
                w.click()
        except RuntimeError:
            return "Ese campo ya no está."
        return f"Deshice: {nombre} quedó como estaba."

    def _nombres_campos(self, mapa: dict, n: int = 30) -> str:
        nombres = [_palabra_hablada(c["nombre"]) for c in mapa["campos"][:n]]
        extra = f", y {len(mapa['campos']) - n} más" if len(mapa["campos"]) > n else ""
        return ("Sus campos son: " + ", ".join(nombres) + extra + ".") if nombres else "No tiene campos para llenar."

    def _describir_ventana(self, mapa: dict, corto: bool = False) -> str:
        """Lo que hay en una ventana, para decirlo."""
        partes = [f"Ventana {_palabra_hablada(mapa['titulo'])}."]
        if mapa["mensaje"]:
            partes.append(_palabra_hablada(mapa["mensaje"]))
        for tw in mapa["pestanas"][:2]:
            nombres = [_limpio_voz(tw.tabText(i)) for i in range(tw.count()) if tw.isTabEnabled(i)]
            partes.append(f"Tiene {len(nombres)} pestañas: " + ", ".join(nombres) +
                          f". Estás en {_limpio_voz(tw.tabText(tw.currentIndex()))}.")
        for k_, lst in enumerate(mapa["listas"]):
            if k_ > 0 and not lst.accessibleName():
                continue
            items = [_palabra_hablada(_limpio_voz(lst.item(i).text())) for i in range(lst.count())]
            actual = lst.currentItem()
            nom = f"La lista de {_limpio_voz(lst.accessibleName()).lower()}" if lst.accessibleName() else "Una lista"
            partes.append((f"{nom} tiene {len(items)}: " + ", ".join(items[:15]) +
                           ("…" if len(items) > 15 else "") + ".") if items else f"{nom} está vacía.")
            if actual is not None:
                partes.append(f"Elegido: {_palabra_hablada(_limpio_voz(actual.text()))}.")
        if mapa["campos"]:
            if corto:
                nombres = [_palabra_hablada(c["nombre"]) for c in mapa["campos"][:8]]
                mas = len(mapa["campos"]) - len(nombres)
                partes.append(f"Tiene {len(mapa['campos'])} campos: " + ", ".join(nombres) +
                              (f", y {mas} más." if mas > 0 else "."))
            else:
                trozos = []
                for c in mapa["campos"]:
                    v = valor_de_campo(c)
                    trozos.append(_palabra_hablada(c["nombre"]) + (f", {v}" if v and c["tipo"] not in (
                        "casilla", "opcion") else (f", {v}" if c["tipo"] in ("casilla", "opcion") else ", vacío")))
                partes.append("Campos: " + ". ".join(trozos) + ".")
        botones = [b["nombre"] for b in mapa["botones"]]
        if botones and not corto:
            partes.append("Botones: " + ", ".join(botones[:14]) + ".")
        if not corto:
            partes.append("Di el nombre de un campo y lo que va, o cerrar." if mapa["campos"] else
                          "Di aprieta, y el nombre de un botón, o cerrar.")
        return " ".join(partes)

    def _leer_todo(self, mapa: dict, solo_llenos: bool = False) -> str:
        trozos = []
        for c in mapa["campos"]:
            v = valor_de_campo(c, completo=True)
            if solo_llenos and (not v or (c["tipo"] in ("casilla", "opcion") and v in ("sin marcar", "no elegida"))):
                continue
            trozos.append(f"{_palabra_hablada(c['nombre'])}: {_con_punto(v or 'vacío')}")
        return " ".join(trozos) if trozos else "Todos los campos están vacíos."

    def _hacer_en_ventana(self, res: dict, ventana, mapa: dict) -> None:
        o = res["orden"]
        campos = mapa["campos"]
        decir = self.voz.decir

        def campo(nombre: str) -> Optional[dict]:
            c = buscar_por_nombre(nombre, campos)
            if c is None:
                decir(f"No encontré el campo {nombre}. {self._nombres_campos(mapa)}")
            return c
        try:
            if o == "describir":
                decir(self._describir_ventana(mapa))
            elif o == "leer_todo":
                decir(self._leer_todo(mapa))
            elif o == "ayuda":
                decir(AYUDA_VENTANA_VOZ)
            elif o == "pestanas":
                if not mapa["pestanas"]:
                    decir("Esta ventana no tiene pestañas.")
                else:
                    tw = mapa["pestanas"][0]
                    decir("Pestañas: " + ", ".join(_limpio_voz(tw.tabText(i)) for i in range(tw.count())) +
                          f". Estás en {_limpio_voz(tw.tabText(tw.currentIndex()))}. Di pestaña, y su nombre.")
            elif o == "pestana":
                hecho = False
                for tw in mapa["pestanas"]:
                    items = [{"clave": _clave_voz(tw.tabText(i)), "i": i} for i in range(tw.count())
                             if tw.isTabEnabled(i)]
                    p_ = buscar_por_nombre(res["nombre"], items)
                    if p_ is not None:
                        tw.setCurrentIndex(p_["i"])
                        self._campo_voz = None
                        decir(f"Pestaña {_limpio_voz(tw.tabText(p_['i']))}. " +
                              self._describir_ventana(mapa_de_ventana(ventana), corto=True))
                        hecho = True
                        break
                if not hecho:
                    decir(f"No encontré la pestaña {res['nombre']}.")
            elif o == "botones":
                decir(("Botones: " + ", ".join(b["nombre"] for b in mapa["botones"]) +
                       ". Di aprieta, y el nombre.") if mapa["botones"] else "Esta ventana no tiene botones.")
            elif o == "boton":
                b = buscar_por_nombre(res["nombre"], mapa["botones"], minimo=40)
                if b is None:
                    if res.get("confirmar"):
                        decir("Aquí no hay nada que confirmar. Di qué hay aquí, o cerrar.")
                    elif res.get("guardar"):
                        self._cerrar_ventana(ventana, mapa, guardar=True)
                    else:
                        decir(f"No encontré el botón {res['nombre']}. " + ("Botones: " + ", ".join(
                            x["nombre"] for x in mapa["botones"]) + "." if mapa["botones"] else ""))
                else:
                    self._apretar(b)
            elif o == "lista":
                if not mapa["listas"]:
                    decir("Esta ventana no tiene listas.")
                else:
                    lst = mapa["listas"][0]
                    items = [_palabra_hablada(_limpio_voz(lst.item(i).text())) for i in range(lst.count())]
                    actual = lst.currentItem()
                    decir((f"La lista tiene {len(items)}: " + ", ".join(items) + "." +
                           (f" Elegido: {_palabra_hablada(_limpio_voz(actual.text()))}." if actual else "") +
                           " Di elige, y un nombre.") if items else "La lista está vacía.")
            elif o == "elegir":
                self._elegir(res["nombre"], ventana, mapa)
            elif o == "opciones":
                c = buscar_por_nombre(res["campo"], campos) if res.get("campo") else self._campo_con_foco(mapa)
                if c is None or c["tipo"] != "opciones":
                    c = next((x for x in campos if x["tipo"] == "opciones"), None) if not res.get("campo") else None
                if c is None:
                    decir("No hay un campo para elegir opciones. Di ve a, y el nombre del campo.")
                else:
                    w = c["w"]
                    decir(f"En {c['nombre']} se puede elegir: " + ", ".join(
                        _limpio_voz(w.itemText(i)) for i in range(w.count()) if _limpio_voz(w.itemText(i))) +
                          f". Ahora: {w.currentText() or 'nada'}. Di {c['nombre']}, y la opción.")
            elif o in ("cerrar", "cancelar"):
                self._cerrar_ventana(ventana, mapa, guardar=o == "cerrar")
            elif o == "mover":
                if not campos:
                    decir("Esta ventana no tiene campos.")
                else:
                    actual = self._campo_con_foco(mapa)
                    i = campos.index(actual) if actual in campos else -1
                    c = campos[(i + res["paso"]) % len(campos)]
                    self._enfocar(c)
            elif o == "ir":
                c = campo(res["campo"])
                if c is not None:
                    self._enfocar(c)
            elif o == "leer":
                c = campo(res["campo"])
                if c is not None:
                    decir(f"{_palabra_hablada(c['nombre'])}: {_con_punto(valor_de_campo(c, completo=True) or 'vacío')}")
            elif o == "vaciar":
                c = campo(res["campo"])
                if c is not None and c["tipo"] in ("linea", "texto"):
                    self._recordar_para_deshacer(c)
                    (c["w"].setText if c["tipo"] == "linea" else c["w"].setPlainText)("")
                    decir(f"Borré {_palabra_hablada(c['nombre'])}. Si fue un error, di: borra eso.")
                elif c is not None:
                    decir(f"{c['nombre']} no se borra: di {c['nombre']}, y lo que va.")
            elif o == "casilla":
                c = campo(res["campo"])
                if c is not None and c["tipo"] in ("casilla", "opcion"):
                    self._recordar_para_deshacer(c)
                    estado = poner_valor_campo(c, "si" if res["valor"] else "no")
                    decir(f"{_palabra_hablada(c['nombre'])}: {estado}.")
                elif c is not None:
                    decir(f"{c['nombre']} no es una casilla.")
            elif o == "poner":
                c = campo(res["campo"])
                if c is not None:
                    self._recordar_para_deshacer(c)
                    nuevo = poner_valor_campo(c, res["valor"], agregar=bool(res.get("agregar")))
                    self._campo_voz = c["w"]
                    self._marcar_cambio()
                    corto = nuevo if len(nuevo) <= 140 else "…" + nuevo[-120:]
                    decir(f"{_palabra_hablada(c['nombre'])}: {corto or 'vacío'}.")
            elif o == "dictar":
                c = self._campo_con_foco(mapa)
                if c is not None:
                    self._recordar_para_deshacer(c)
                    poner_valor_campo(c, res["texto"], agregar=True)
                    self._marcar_cambio()
                    decir(f"Escrito en {_palabra_hablada(c['nombre'])}: {res['texto']}" if self._leer_lo_escrito()
                          else "Escrito.")
            elif o == "deshacer":
                decir(self._deshacer_en_ventana())
            elif o == "no_entendi":
                decir(f"No entendí, en esta ventana: {res.get('texto', '')}. Di qué hay aquí para escuchar sus campos, "
                      "ve a, y un campo, para dictarle, o ayuda.")
        except ValueError as ex:
            decir(str(ex))
        except RuntimeError:
            decir("Esa ventana ya se cerró.")

    def _enfocar(self, c: dict) -> None:
        w = c["w"]
        try:
            w.setFocus(Qt.FocusReason.OtherFocusReason)
            if c["tipo"] == "texto":
                cur = w.textCursor()
                cur.movePosition(cur.MoveOperation.End)
                w.setTextCursor(cur)
            elif c["tipo"] == "linea":
                w.end(False)
        except RuntimeError:
            return
        self._campo_voz = w
        v = valor_de_campo(c)
        que = {"linea": "Dicta lo que va: cada frase se agrega.", "texto": "Dicta lo que va: cada frase se agrega.",
               "opciones": "Di elige, y una opción; o opciones, para escucharlas.",
               "numero": f"Di {c['nombre']}, y el número.", "fecha": f"Di {c['nombre']}, y la fecha.",
               "casilla": "Di marca o desmarca.", "opcion": "Di elige, para marcarla."}.get(c["tipo"], "")
        self.voz.decir(f"{_palabra_hablada(c['nombre'])}: {v or 'vacío'}. {que}")

    def _elegir(self, nombre: str, ventana, mapa: dict) -> None:
        """«elige Ana»: en una lista, en las opciones del campo donde estás, o una casilla."""
        for lst in mapa["listas"]:
            items = [{"clave": _clave_voz(lst.item(i).text()), "i": i} for i in range(lst.count())]
            it = buscar_por_nombre(nombre, items, minimo=40)
            if it is not None:
                lst.setCurrentRow(it["i"])
                lst.setFocus(Qt.FocusReason.OtherFocusReason)
                txt = _palabra_hablada(_limpio_voz(lst.item(it["i"]).text()))
                self._campo_voz = None
                if isinstance(ventana, VentanaFichasPersonaje):
                    llenos = self._leer_todo(mapa_de_ventana(ventana), solo_llenos=True)
                    self.voz.decir(f"Elegí {txt}. " + ("Su ficha tiene: " + llenos if not llenos.startswith("Todos")
                                                        else "Su ficha está vacía."))
                else:
                    self.voz.decir(f"Elegí {txt}.")
                return
        foco = self._campo_con_foco(mapa)
        candidatos = ([foco] if foco is not None and foco["tipo"] == "opciones" else []) + \
            [c for c in mapa["campos"] if c["tipo"] == "opciones" and c is not foco]
        for c in candidatos:
            w = c["w"]
            items = [{"clave": _clave_voz(w.itemText(i)), "i": i} for i in range(w.count())]
            if buscar_por_nombre(nombre, items, minimo=60) is not None:
                self._recordar_para_deshacer(c)
                nuevo = poner_valor_campo(c, nombre)
                self.voz.decir(f"{_palabra_hablada(c['nombre'])}: {nuevo}.")
                return
        c = buscar_por_nombre(nombre, [x for x in mapa["campos"] if x["tipo"] in ("casilla", "opcion")], minimo=40)
        if c is not None:
            self._recordar_para_deshacer(c)
            self.voz.decir(f"{_palabra_hablada(c['nombre'])}: {poner_valor_campo(c, 'si')}.")
            return
        self.voz.decir(f"No encontré {nombre} para elegir.")

    def _apretar(self, b: dict) -> None:
        """Aprieta un botón (después de responder: puede abrir otra ventana)."""
        w = b["w"]
        self._campo_voz = None
        self.voz.decir(f"Apreté {b['nombre']}.")
        QTimer.singleShot(0, w, w.click)

    def _cerrar_ventana(self, ventana, mapa: dict, guardar: bool = True) -> None:
        """«cerrar»: con su botón de cerrar o aceptar (lo llenado queda); «cancelar»: sin guardar."""
        titulo = mapa["titulo"]
        nombres = (("cerrar", "listo", "aceptar", "ok", "guardar y cerrar", "terminar", "hecho", "guardar") if guardar
                   else ("cancelar", "cancel", "descartar", "no guardar", "cerrar sin guardar"))
        boton = None
        for nom in nombres:
            boton = next((b for b in mapa["botones"] if b["clave"] == nom or nom in b.get("alias", [])), None)
            if boton is not None:
                break
        self._campo_voz = None
        self._cerrada_por_voz = ventana
        if guardar:
            msj = f"Cerré la ventana {titulo}; lo que llenaste quedó guardado."
        else:
            msj = f"Cerré la ventana {titulo} sin guardar."
        self._msj_cierre = msj
        if boton is not None:
            QTimer.singleShot(0, boton["w"], boton["w"].click)
        elif isinstance(ventana, QDialog) and guardar and isinstance(ventana, QMessageBox):
            QTimer.singleShot(0, ventana, ventana.accept)
        elif isinstance(ventana, QDialog) and not guardar:
            QTimer.singleShot(0, ventana, ventana.reject)
        else:
            QTimer.singleShot(0, ventana, ventana.close)
        QTimer.singleShot(250, self._despues_de_cerrar)

    def _despues_de_cerrar(self) -> None:
        msj, self._msj_cierre = getattr(self, "_msj_cierre", ""), ""
        cerrada, self._cerrada_por_voz = getattr(self, "_cerrada_por_voz", None), None
        try:
            sigue = cerrada is not None and cerrada.isVisible()
        except RuntimeError:
            sigue = False
        if sigue:
            self.voz.decir("La ventana no se cerró: puede que falte algo. Di qué hay aquí.")
            return
        if self.tutorial.activo:
            return                                    # (el tutorial sigue con su paso)
        otra = ventana_para_voz(self.vp)
        donde_ = (f"Volviste a la ventana {_limpio_voz(otra.windowTitle())}." if otra is not None
                  else "Volviste al guion.")
        self.voz.decir(f"{msj} {donde_}".strip())

    def _volver_de_ventana(self) -> None:
        """Una ventana se cerró sola (con su botón): se dice dónde quedaste."""
        if self.tutorial.activo or not self.modo_visual:
            return
        otra = ventana_para_voz(self.vp)
        self.voz.despues(lambda: self.voz.decir(
            f"Volviste a la ventana {_limpio_voz(otra.windowTitle())}." if otra is not None else "Volviste al guion."))

    def _ventana_se_abrio(self, w) -> None:
        """♿ Una ventana nueva: se dice qué es y qué tiene (un aviso de un solo
        botón se lee y se cierra solo)."""
        try:
            if not w.isVisible():
                return
        except RuntimeError:
            return
        self._campo_voz = None
        mapa = mapa_de_ventana(w)
        if isinstance(w, QMessageBox):
            botones = mapa["botones"]
            texto = _palabra_hablada(mapa["mensaje"]) or _palabra_hablada(mapa["titulo"])
            if len(botones) <= 1:
                self.voz.decir(f"Aviso: {texto}")
                QTimer.singleShot(150, w, w.accept)
            else:
                self.voz.decir(f"La ventana {mapa['titulo']} pregunta: {texto} Botones: " +
                               ", ".join(b["nombre"] for b in botones) + ". Di aprieta, y el botón.")
            return
        if self.tutorial.activo:
            return                                    # (el tutorial explica la ventana a su manera)
        texto = ("Se abrió la " + self._describir_ventana(mapa, corto=True).replace("Ventana ", "ventana ", 1) +
                 (" Di qué hay aquí para escucharla entera, el nombre de un campo y lo que va, o cerrar."
                  if mapa["campos"] else " Di qué hay aquí, aprieta y un botón, o cerrar."))
        self.voz.despues(lambda: self.voz.decir(texto))

    def _ia_permitida(self) -> bool:
        return _bool_ajuste(CLAVE_VOZ_IA, True) and escritura_ia_permitida()

    def _ia_permitida_router(self) -> bool:
        return _bool_ajuste(CLAVE_VOZ_IA, True)

    def _leer_lo_escrito(self) -> bool:
        return _bool_ajuste(CLAVE_VOZ_LEER, True)

    def _escribir(self, bloques: list, como: str = "") -> None:
        ed = self.vp.editor
        if ed.isReadOnly():
            self.voz.decir("El guion está en solo lectura: no puedo escribir.")
            return
        ed.insertar_bloques_dictados(bloques)
        self._marcar_cambio()
        hablado = hablado_de_bloques(bloques)
        self._pintar("🎙 Escrito: " + hablado[:90])
        if self._leer_lo_escrito():
            self.voz.decir((f"Escrito como {como}: " if como else "Escrito. ") + hablado)
        else:
            self.voz.decir("Escrito.")

    def _marcar_cambio(self) -> None:
        try:
            self.vp._marcar_dirty()
        except Exception:
            try:
                self.vp._doc_dirty = True
            except Exception:
                pass

    def _aceptar_propuesta(self) -> None:
        bloques, self.propuesta = self.propuesta or [], None
        if bloques:
            self._escribir(bloques)

    def _contexto(self, n: int = 14) -> str:
        ed = self.vp.editor
        try:
            idx, _o = ed._posicion_logica()
        except Exception:
            idx = len(ed.documento.bloques) - 1
        bl = ed.documento.bloques[max(0, idx - n + 1): idx + 1]
        return texto_de_bloques_ia([(b.elem, b.texto) for b in bl if (b.texto or "").strip()])

    def _cancelar_ia(self) -> None:
        self._turno_ia += 1
        h = self._hilo_ia
        self._hilo_ia = None
        if h is not None:
            try:
                h.cancelar()
            except RuntimeError:
                pass
        self.estado = "inactivo"
        self.propuesta = None
        self._pintar("🎙 Cancelé lo que le pedí al Profesor Claqueta.")

    def _a_la_ia(self, texto: str, modo: str) -> None:
        self._turno_ia += 1
        turno = self._turno_ia
        self.estado = "pensando"
        self._pintar("🤖 El Profesor Claqueta está pensando…")
        self.voz.decir({"pregunta": "Le pregunto al Profesor Claqueta.",
                        "router": "Déjame entender qué necesitas."}.get(
            modo, "Se lo pido al Profesor Claqueta. Te leo lo que propone."))
        hilo_ia = _HiloElegirIA(self)
        hilo_ia.elegido.connect(lambda host, mo: self._con_ia(host, mo, texto, modo)
                                if turno == self._turno_ia else None)
        hilo_ia.finished.connect(hilo_ia.deleteLater)
        hilo_ia.start()

    def _con_ia(self, host: str, modelo: str, texto: str, modo: str) -> None:
        if not host or not modelo:
            self.estado = "inactivo"
            if modo == "router":
                self.voz.decir("No entendí qué hacer, y el Profesor Claqueta no está listo en este computador. "
                               "Di «ayuda» para escuchar lo que puedes pedir.")
                return
            if modo == "libre":
                self._escribir([(Elem.ACCION, texto)], como="acción, porque el Profesor Claqueta no está listo")
            else:
                self.voz.decir("El Profesor Claqueta no está listo en este computador.")
            return
        datos = {"modo": modo, "texto": texto, "contexto": self._contexto(), "personajes": self._personajes()}
        turno = self._turno_ia
        h = HiloOrdenVozIA(host, modelo, datos, num_ctx=num_ctx_para_modelo(modelo, recursos_equipo()), parent=self)
        h.propuesta.connect(lambda b, r: self._propuesta_ia(b, r) if turno == self._turno_ia else None)
        h.ruta.connect(lambda t_, x_: self._ruta_ia(t_, x_) if turno == self._turno_ia else None)
        h.fallo.connect(lambda e: self._fallo_ia(e) if turno == self._turno_ia else None)
        h.finished.connect(h.deleteLater)
        self._hilo_ia = h
        h.start()

    def _propuesta_ia(self, bloques: list, respuesta: str) -> None:
        self.estado = "inactivo"
        self._hilo_ia = None
        if respuesta:
            self._pintar("🤖 " + respuesta[:90])
            self.voz.decir(respuesta)
            return
        if not bloques:
            self.voz.decir("El Profesor Claqueta no propuso nada. Prueba decirlo de otra forma.")
            return
        inj = injerencia_ia()
        if inj == "directo":                      # (🎚 la IA puede escribir directo)
            self._escribir(bloques)
            return
        if inj == "aconsejar":
            self._pintar("🤖 Propuesta (solo para escucharla)")
            self.voz.decir("Así lo escribiría: " + hablado_de_bloques(bloques) + " No lo escribí: tu configuración "
                           "dice que la IA solo aconseja. Si te sirve, díctalo tú.")
            return
        self.propuesta = list(bloques)
        self._pintar("🤖 Propuesta: ¿la dejo? (di sí o no)")
        self.voz.decir("Propone: " + hablado_de_bloques(bloques) + " ¿Lo dejo? Di sí o no.")

    def _ruta_ia(self, tipo: str, texto: str) -> None:
        """♿ Lo que entendió el Profesor Claqueta: una orden, algo que
        escribir o una pregunta."""
        self.estado = "inactivo"
        self._hilo_ia = None
        if tipo == "orden" and texto:
            self.procesar(texto, desde_ia=True)
        elif tipo == "escribir" and texto:
            if self._ia_permitida():
                self._a_la_ia(texto, "libre")
            else:
                self.voz.decir("La escritura con IA está apagada en este computador. Díctalo tú: por ejemplo, "
                               "acción, y lo que pasa.")
        elif tipo == "pregunta" and texto:
            self._a_la_ia(texto, "pregunta")
        else:
            self.voz.decir("No entendí qué hacer. Di «ayuda» para escuchar lo que puedes pedir.")

    def _fallo_ia(self, error: str) -> None:
        self.estado = "inactivo"
        self._hilo_ia = None
        self.voz.decir("El Profesor Claqueta no pudo responder. " + error)

    # ── órdenes para revisar, moverse, corregir y guardar ──
    def _orden(self, res: dict) -> None:
        o = res["orden"]
        ed = self.vp.editor
        doc = ed.documento
        if o == "parar":
            self.voz.callar()
            self._pintar("🎙 —")
        elif o == "ayuda":
            self.voz.decir(AYUDA_MODO_VISUAL if self.modo_visual else AYUDA_DICTADO)
        elif o == "repetir":
            self.voz.decir(self.voz.ultimo or "Todavía no he dicho nada.")
        elif o == "deshacer":
            if ed.deshacer():
                self.voz.decir("Borrado. " + (("Ahora lo último es: " + self._hablar_bloque_actual())
                                              if doc.bloques else ""))
            else:
                self.voz.decir("No hay nada que borrar.")
        elif o == "rehacer":
            self.voz.decir("Listo." if ed.rehacer() else "No hay nada que rehacer.")
        elif o in ("leer_escena", "ir_escena"):
            rangos = self._escenas()
            if not rangos:
                self.voz.decir("Todavía no hay escenas.")
                return
            k = res.get("n", 0)
            if k is None:
                self.voz.decir("No entendí el número de la escena. Dilo otra vez, por ejemplo: ve a la escena 4.")
                return
            if k == 0:
                k = self._escena_actual()
            if k == -1:
                k = len(rangos)
            if not (1 <= k <= len(rangos)):
                self.voz.decir(f"No hay escena {k}. Hay {len(rangos)}.")
                return
            a, b = rangos[k - 1]
            if o == "ir_escena":
                ed._mover_cursor_a(b, len(doc.bloques[b].texto))
                ed.ensureCursorVisible()
                self.voz.decir(f"Estás al final de la escena {k}: " + hablado_de_bloques(
                    [(doc.bloques[a].elem, doc.bloques[a].texto)]))
            else:
                self.voz.decir(f"Escena {k}. " + hablado_de_bloques(
                    [(x.elem, x.texto) for x in doc.bloques[a:b + 1] if (x.texto or "").strip()]))
        elif o == "leer_ultimo":
            self.voz.decir(self._hablar_bloque_actual() or "La hoja está vacía.")
        elif o == "leer_todo":
            self.voz.decir(hablado_de_bloques([(x.elem, x.texto) for x in doc.bloques if (x.texto or "").strip()])
                           or "La hoja está vacía.")
        elif o == "ir_final":
            i = len(doc.bloques) - 1
            ed._mover_cursor_a(i, len(doc.bloques[i].texto))
            ed.ensureCursorVisible()
            self.voz.decir("Estás al final del guion. " + self._hablar_bloque_actual())
        elif o == "donde":
            k = self._escena_actual()
            self.voz.decir((f"Estás en la escena {k} de {len(self._escenas())}. " if k else
                            "Estás antes de la primera escena. ") + "Lo último es: " + self._hablar_bloque_actual())
        elif o == "resumen":
            esc = len(self._escenas())
            pal = sum(len((b.texto or "").split()) for b in doc.bloques)
            self.voz.decir(f"Llevas {esc} escena{'s' if esc != 1 else ''}, {len(self._personajes())} personajes y "
                           f"unas {pal} palabras: más o menos {max(1, round(pal / 180))} minuto"
                           f"{'s' if round(pal / 180) > 1 else ''} de película.")
        elif o == "personajes":
            ps = [_palabra_hablada(p_) for p_ in self._personajes()]
            self.voz.decir(("Los personajes son: " + ", ".join(ps) + ".") if ps else "Todavía no hay personajes.")
        elif o == "guardar":
            self._guardar()
        elif o == "titulo":
            doc.titulo = res["texto"]
            self._marcar_cambio()
            self.voz.decir(f"El título es: {res['texto']}.")
        elif o == "premisa":
            poner_premisa(doc, res["texto"])
            self._marcar_cambio()
            self.voz.decir("Anoté la premisa: " + res["texto"])

    # ── ♿ el programa por voz ──
    def _orden_programa(self, res: dict) -> None:
        o = res["orden"]
        vp = self.vp
        doc = vp.editor.documento
        try:
            if o == "modo_visual_off":
                vp.poner_modo_visual(False)
            elif o == "modo_visual_on":
                vp.poner_modo_visual(True)
            elif o == "abrir":
                self._abrir_destino(res["destino"])
            elif o == "leer_informe":
                self._leer_informe(res.get("informe", ""), res.get("dicho", ""))
            elif o == "exportar_informe":
                self._exportar_informe(res.get("informe", ""), res.get("dicho", ""))
            elif o == "exportar_pdf":
                self._exportar_pdf()
            elif o == "imprimir":
                vp._accion_imprimir()
                self.voz.decir("Se abrió la ventana para imprimir: Enter imprime en la impresora de siempre.")
            elif o == "nuevo_guion":
                self._antes_de_cambiar_guion()
                vp._accion_nuevo(confirmar=False)
                self.voz.decir("Guion nuevo, en blanco. Empieza con F2: por ejemplo, escena, interior, y el lugar.")
            elif o == "listar_guiones":
                gs = self._guiones()
                self.voz.decir(("Tus guiones son: " + ", ".join(p_.stem for p_ in gs[:15]) + ". Di «abre el guion» "
                                "y su nombre.") if gs else "No encontré guiones en tu carpeta.")
            elif o == "abrir_guion":
                self._abrir_guion(res.get("nombre", ""))
            elif o == "listar_ventanas":
                nombres = [nom for dest, (_fn, nom) in vp.destinos_programa().items()
                           if dest not in DESTINOS_VISUALES and dest not in ("voz_alta", "tags", "pizarra")]
                self.voz.decir("Puedes abrir: " + ", ".join(nombres) + ". También la ficha de un personaje: abre la "
                               "ficha de, y su nombre. Di abre, y lo que quieres. En una ventana, di qué hay aquí, el "
                               "nombre de un campo y lo que va, y cerrar.")
            elif o == "leer_ficha":
                self.voz.decir(self._texto_ficha(res.get("nombre", "")))
            elif o == "ficha_campo":
                self._poner_campo_ficha(res["nombre"], res["campo"], res["valor"])
            elif o == "nuevo_personaje":
                nombre = res.get("nombre", "").strip()
                if nombre and nombre not in doc.fichas:
                    doc.fichas[nombre] = Ficha(personaje=nombre)
                    self._marcar_cambio()
                    self.voz.decir(f"Creé la ficha de {_palabra_hablada(nombre)}. Puedes decir, por ejemplo: ficha "
                                   f"de {_palabra_hablada(nombre)}, edad 17.")
                else:
                    self.voz.decir(f"{_palabra_hablada(nombre)} ya tiene ficha." if nombre else "¿Cómo se llama?")
            elif o == "leer_ficha_escena":
                self.voz.decir(self._texto_ficha_escena())
            elif o == "ficha_escena":
                self._poner_campo_escena(res["campo"], res["valor"])
            elif o == "leer_escaleta":
                esc = [x for x in (doc.escaleta or []) if str(x).strip()]
                self.voz.decir(("La escaleta tiene " + str(len(esc)) + (" punto. " if len(esc) == 1 else " puntos. ") + " ".join(
                    f"{k}. {_palabra_hablada(x)}." for k, x in enumerate(esc, 1))) if esc else
                               "La escaleta está vacía. Di «escaleta, agrega» y el primer punto.")
            elif o == "agregar_escaleta":
                doc.escaleta = list(doc.escaleta or []) + [res["texto"]]
                self._marcar_cambio()
                self.voz.decir(f"Agregué el punto {len(doc.escaleta)} a la escaleta: {res['texto']}")
            elif o == "borrar_escaleta":
                k = res.get("n")
                esc = list(doc.escaleta or [])
                if k is None or not (1 <= k <= len(esc)):
                    self.voz.decir(f"La escaleta tiene {len(esc)} puntos: dime cuál borro.")
                else:
                    quitado = esc.pop(k - 1)
                    doc.escaleta = esc
                    self._marcar_cambio()
                    self.voz.decir(f"Borré el punto {k}: {quitado}")
            elif o == "leer_tags":
                self.voz.decir(self._texto_tags())
            elif o == "agregar_tag":
                if vp.editor.isReadOnly():
                    self.voz.decir("El guion está en solo lectura.")
                    return
                vp.editor.agregar_etiqueta(res["categoria"], res["contenido"])
                self._marcar_cambio()
                self.voz.decir(f"Marqué {res['contenido']} como {CATEGORIAS_DICT.get(res['categoria'], ('', ''))[0]} "
                               "en esta parte del guion.")
        except Exception as ex:
            self.voz.decir(f"No pude hacerlo: {ex}")

    def _abrir_destino(self, destino: str) -> None:
        """Sin el modo, abre la ventana. En el modo discapacidad visual, lo
        que se puede decir se lee en voz alta; lo demás se abre (y lo lee el
        lector de pantalla); lo visual, se avisa."""
        vp = self.vp
        if not self.modo_visual:
            if destino in DESTINOS_VISUALES or vp.ir_a_destino(destino):
                self.voz.decir("Listo." if destino not in DESTINOS_VISUALES else DESTINOS_VISUALES[destino])
                if destino in DESTINOS_VISUALES:
                    vp.ir_a_destino(destino)
            else:
                self.voz.decir("No encontré esa parte del programa.")
            return
        if destino in DESTINOS_VISUALES:
            self.voz.decir(DESTINOS_VISUALES[destino])
        elif destino.startswith("informe:"):
            self._leer_informe(destino[8:], destino[8:])
        elif destino == "tags":
            self.voz.decir(self._texto_tags())
        elif destino == "pizarra":
            info = vp._construir_informe("estructura", vp.editor.documento)
            sec = next((x for x in (info or {}).get("secciones", []) if "pizarra" in _norm_voz(x["titulo"])), None)
            texto = texto_para_voz(vp._informe_a_txt({"titulo": "", "secciones": [sec]}, 400)) if sec else ""
            self.voz.decir("La Pizarra de beats es visual; te leo sus tarjetas en orden. " + texto if texto else
                           "La Pizarra de beats todavía no tiene tarjetas.")
        else:
            # (la ventana se abre de verdad; al abrirse se dice qué tiene, y se llena hablando)
            if destino.startswith("ficha:"):
                nombre = destino[6:]
                if _clave_nombre(nombre) not in {_clave_nombre(k) for k in list(vp.editor.documento.fichas) +
                                                 self._personajes()}:
                    self.voz.decir(f"No hay ficha de {_palabra_hablada(nombre)}. Di nuevo personaje, y su nombre.")
                    return
                nombre = f"la ficha de {_palabra_hablada(nombre)}"
            else:
                nombre = vp.destinos_programa().get(destino, (None, "esa parte"))[1]
            QTimer.singleShot(0, lambda: vp.ir_a_destino(destino) or self.voz.decir(f"No pude abrir {nombre}."))

    def _leer_informe(self, tipo: str, dicho: str = "") -> None:
        if not tipo:
            self.voz.decir(f"No conozco el informe {dicho}. Hay de personajes, narrativo, estructura, tags, "
                           "producción, actores, locaciones y estado.")
            return
        info = self.vp._construir_informe(tipo, self.vp.editor.documento)
        if not info:
            self.voz.decir("Ese informe todavía no tiene datos.")
            return
        self.voz.decir(texto_para_voz(self.vp._informe_a_txt(info, 400)))

    def _carpeta(self, sub: str = "") -> Path:
        base = Path(self.vp._carpeta_guardado())
        if sub:
            base = base / sub
        base.mkdir(parents=True, exist_ok=True)
        return base

    def _exportar_informe(self, tipo: str, dicho: str = "") -> None:
        if not tipo:
            self._leer_informe("", dicho)
            return
        info = self.vp._construir_informe(tipo, self.vp.editor.documento)
        if not info:
            self.voz.decir("Ese informe todavía no tiene datos.")
            return
        ruta = self._carpeta("Informes") / (self.vp._safe_filename(info["titulo"]) + ".pdf")
        self.vp._render_uno(info, ruta, "pdf", ahorro=poca_tinta_por_defecto(), fotos=False)
        self.voz.decir(f"Guardé el informe como {ruta.stem}, en la carpeta Informes, dentro de "
                       f"{ruta.parent.parent.name}.")

    def _exportar_pdf(self) -> None:
        vp = self.vp
        titulo = re.sub(r'[\\/:*?"<>|]+', "", (vp.editor.documento.titulo or "").strip()).strip() or "Guion"
        ruta = self._carpeta() / f"{titulo[:60]}.pdf"
        vp._render_pdf_directo(ruta, "", 0, vp._opciones_pdf_guardadas())
        self.voz.decir(f"Guardé el guion en PDF como {ruta.stem}, en la carpeta {ruta.parent.name}.")

    def _guiones(self) -> list:
        try:
            base = Path(self.vp._carpeta_guardado())
            return sorted(base.glob("*.accion"), key=lambda p_: -p_.stat().st_mtime)
        except Exception:
            return []

    def _antes_de_cambiar_guion(self) -> None:
        """(lo que no esté guardado, se guarda antes: sin ventanas de «¿guardar?»)"""
        if getattr(self.vp, "_doc_dirty", False) and any((b.texto or "").strip() for b in
                                                        self.vp.editor.documento.bloques):
            self._guardar()
            self.vp._doc_dirty = False

    def _abrir_guion(self, nombre: str) -> None:
        clave = _norm_voz(nombre).strip(" .")
        hallados = [p_ for p_ in self._guiones() if clave and clave in _norm_voz(p_.stem)]
        if not hallados:
            self.voz.decir(f"No encontré un guion que se llame {nombre}. Di «qué guiones hay» para escucharlos.")
            return
        self._antes_de_cambiar_guion()
        self.vp._accion_abrir(str(hallados[0]), confirmar=False)
        n_esc = sum(1 for b in self.vp.editor.documento.bloques if b.elem == Elem.ESCENA)
        self.voz.decir(f"Abrí {hallados[0].stem}: tiene {n_esc} escena{'s' if n_esc != 1 else ''}.")

    def _texto_ficha(self, nombre: str) -> str:
        doc = self.vp.editor.documento
        f = doc.fichas.get(nombre) or doc.fichas.get(str(nombre).upper())
        if f is None:
            return f"No hay ficha de {_palabra_hablada(nombre)}. Di «nuevo personaje {_palabra_hablada(nombre)}»."
        partes = []
        for campo, etq in NOMBRES_CAMPO_FICHA.items():
            v = str(getattr(f, campo, "") or "").strip()
            if v and not esta_cifrado(v):
                partes.append(f"{etq}: {v}")
        return (f"Ficha de {_palabra_hablada(nombre)}. " + ". ".join(partes) + ".") if partes else \
            f"La ficha de {_palabra_hablada(nombre)} está vacía. Di, por ejemplo: ficha de {_palabra_hablada(nombre)}, edad 17."

    def _poner_campo_ficha(self, nombre: str, campo: str, valor: str) -> None:
        doc = self.vp.editor.documento
        f = doc.fichas.get(nombre)
        if f is None:
            f = doc.fichas[nombre] = Ficha(personaje=nombre)
        setattr(f, campo, valor)
        self._marcar_cambio()
        self.voz.decir(f"Anoté en la ficha de {_palabra_hablada(nombre)}: {NOMBRES_CAMPO_FICHA.get(campo, campo)}, "
                       f"{valor}.")

    def _texto_ficha_escena(self) -> str:
        k = self._escena_actual()
        if not k:
            return "Estás antes de la primera escena."
        d = self.vp.editor.documento.fichas_escenas.get(str(k)) or {}
        if not isinstance(d, dict):
            d = asdict(d)
        partes = [f"{etq}: {d.get(c)}" for c, etq in NOMBRES_CAMPO_ESCENA.items() if str(d.get(c) or "").strip()]
        return (f"Ficha de la escena {k}. " + ". ".join(partes) + ".") if partes else \
            f"La ficha de la escena {k} está vacía. Di, por ejemplo: ficha de esta escena, objetivo, y lo que quiere."

    def _poner_campo_escena(self, campo: str, valor: str) -> None:
        k = self._escena_actual()
        if not k:
            self.voz.decir("Primero ve a una escena: por ejemplo, ve a la escena 1.")
            return
        doc = self.vp.editor.documento
        d = doc.fichas_escenas.get(str(k)) or {}
        if not isinstance(d, dict):
            d = asdict(d)
        d = dict(d)
        d.setdefault("numero", k)
        a, _b = self._escenas()[k - 1]
        d.setdefault("encabezado", doc.bloques[a].texto)
        d[campo] = valor
        doc.fichas_escenas[str(k)] = d
        self._marcar_cambio()
        self.voz.decir(f"Anoté en la ficha de la escena {k}: {NOMBRES_CAMPO_ESCENA.get(campo, campo)}, {valor}.")

    def _texto_tags(self) -> str:
        k = self._escena_actual()
        rangos = self._escenas()
        bl = self.vp.editor.documento.bloques
        if k:
            a, b = rangos[k - 1]
            tags = [t for x in bl[a:b + 1] for t in (x.tags or []) if t.get("categoria") != "nota"]
            donde = f"la escena {k}"
        else:
            tags = [t for x in bl for t in (x.tags or []) if t.get("categoria") != "nota"]
            donde = "el guion"
        if not tags:
            return f"No hay tags en {donde}. Di, por ejemplo: tag radio, utilería."
        por_cat: dict = {}
        for t in tags:
            por_cat.setdefault(CATEGORIAS_DICT.get(t.get("categoria", ""), (t.get("categoria", "otros"), ""))[0],
                               []).append(str(t.get("contenido", "")).strip())
        return f"Tags de {donde}: " + ". ".join(f"{c}: {', '.join(x for x in v if x)}" for c, v in por_cat.items()) + "."

    def _escenas(self) -> list:
        """[(primer bloque, último bloque)] de cada escena."""
        bl = self.vp.editor.documento.bloques
        ini = [i for i, b in enumerate(bl) if b.elem == Elem.ESCENA]
        return [(a, (ini[k + 1] - 1) if k + 1 < len(ini) else len(bl) - 1) for k, a in enumerate(ini)]

    def _escena_actual(self) -> int:
        try:
            idx, _o = self.vp.editor._posicion_logica()
        except Exception:
            idx = len(self.vp.editor.documento.bloques) - 1
        k = 0
        for n_, (a, _b) in enumerate(self._escenas(), 1):
            if a <= idx:
                k = n_
        return k

    def _hablar_bloque_actual(self) -> str:
        ed = self.vp.editor
        bl = ed.documento.bloques
        try:
            idx, _o = ed._posicion_logica()
        except Exception:
            idx = len(bl) - 1
        while idx > 0 and not (bl[idx].texto or "").strip():
            idx -= 1
        a = idx
        if bl and bl[a].elem == Elem.DIALOGO:               # (el diálogo, con quién lo dice)
            while a > 0 and bl[a - 1].elem in (Elem.PERSONAJE, Elem.PARENTESIS) and a > idx - 2:
                a -= 1
        return hablado_de_bloques([(b.elem, b.texto) for b in bl[a:idx + 1] if (b.texto or "").strip()])

    def _guardar(self) -> None:
        vp = self.vp
        if getattr(vp, "_modo_solo_lectura", False) or (getattr(vp.editor.documento, "pin_hash", "") and
                                                        not getattr(vp, "_pin_desbloqueado", False)):
            self.voz.decir("Este guion tiene PIN o está en solo lectura: guárdalo con el teclado, con Control S.")
            return
        ruta = getattr(vp, "_archivo_actual", None)
        if not ruta:
            base = vp._carpeta_guardado()
            limpio = re.sub(r'[\\/:*?"<>|]+', "", (vp.editor.documento.titulo or "").strip()).strip() or \
                "Guion dictado"
            ruta = Path(base) / f"{limpio[:60]}.accion"
            k = 2
            while ruta.exists():
                ruta = Path(base) / f"{limpio[:60]} ({k}).accion"
                k += 1
        try:
            vp._flush_buffer_colab()
        except Exception:
            pass
        vp._guardar_en(Path(ruta))
        if getattr(vp, "_archivo_actual", None):
            self.voz.decir(f"Guardado como {Path(ruta).stem}, en la carpeta {Path(ruta).parent.name}.")

    def _pintar(self, texto: str) -> None:
        self.lbl.setText(texto)
        self.lbl.setVisible(bool(texto))
        self.cambio.emit()


class _HiloElegirIA(QThread):
    """Busca qué Ollama y qué modelo usar (sin congelar la ventana)."""
    elegido = Signal(str, str)

    def run(self) -> None:
        try:
            h, mo = ia_para_voz()
        except Exception:
            h, mo = "", ""
        self.elegido.emit(h, mo)


class VentanaPrincipal(QMainWindow):
    def __init__(self):
        super().__init__()
        self.setWindowTitle("¡Acción! Software Audiovisual")
        self.resize(px(1280), px(880))

        # ── Widgets ────────────────────────────────────────────────────
        self.ribbon    = Ribbon()
        self.indicador = IndicadorElemento()
        # NOTA: La claqueta horizontal se OCULTA — el tipo actual ya
        # se muestra en el botón naranjo del ribbon (texto dinámico)
        # y en la status bar (▸ ACCIÓN abajo a la derecha). Se mantiene
        # el objeto vivo para no romper conexiones de señales, pero
        # nunca se inserta al layout y se fuerza setVisible(False).
        self.indicador.setVisible(False)
        self.editor    = EditorGuion()

        # Precargar plantillas en el documento vacío inicial
        if not self.editor.documento.tecnicos:
            self.editor.documento.tecnicos = crear_tecnicos_plantilla()
        if not self.editor.documento.equipamiento:
            self.editor.documento.equipamiento = crear_equipamiento_plantilla()

        # ── Contenedor centrado del editor (con fondo gris a los lados) ─
        contenedor_editor = QWidget()
        contenedor_editor.setStyleSheet(
            f"background: {COLOR_FONDO.name()};"
        )
        h = QHBoxLayout(contenedor_editor)
        h.setContentsMargins(0, 16, 0, 16)
        h.setSpacing(0)
        h.addStretch()
        h.addWidget(self.editor)
        h.addStretch()
        # ↕ La barra para recorrer el guion, a la vista en el borde derecho
        # (la del editor queda escondida: estaba pegada a la hoja y casi no
        # se veía)
        self.editor.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.barra_guion = BarraRecorrerGuion(self.editor, contenedor_editor)
        h.addWidget(self.barra_guion)
        self._rueda_guion = _RuedaAlEditor(self.editor, contenedor_editor)
        contenedor_editor.installEventFilter(self._rueda_guion)

        # Barra flotante de buscar/reemplazar (hija del contenedor)
        # Se posiciona con setGeometry sobre el editor cuando se abre.
        self._barra_buscar = BarraBuscarReemplazar(
            self.editor, parent=contenedor_editor)
        self._barra_buscar.raise_()
        # Cuando el contenido del editor cambia (por ejemplo cuando el
        # invitado recibe un snapshot del host), actualizar el
        # contador de la barra de búsqueda si está visible.
        self.editor.document().contentsChanged.connect(
            self._barra_buscar.refrescar_si_visible)

        # ── Layout vertical ────────────────────────────────────────────
        # NOTA: El IndicadorElemento (la barra claqueta horizontal) se
        # quitó del layout porque el tipo actual ya se muestra en:
        #   1. El botón naranjo del ribbon (texto dinámico)
        #   2. La status bar (▸ {ELEMENTO} a la derecha)
        # El objeto `self.indicador` se mantiene para no romper las
        # conexiones de señales, pero NO se agrega al layout (invisible).
        central = QWidget()
        v = QVBoxLayout(central)
        v.setContentsMargins(0, 0, 0, 0)
        v.setSpacing(0)
        v.addWidget(self.ribbon)
        # QSplitter horizontal: editor (izquierda) + panel notas (derecha)
        self._splitter_editor = QSplitter(Qt.Orientation.Horizontal)
        self._splitter_editor.addWidget(contenedor_editor)
        self._panel_notas = PanelNotas(self, parent=self._splitter_editor)
        self._panel_notas.setMinimumWidth(px(240))
        self._panel_notas.setMaximumWidth(px(400))
        self._splitter_editor.addWidget(self._panel_notas)
        # Empezar con el panel oculto; se muestra con el botón del ribbon
        self._panel_notas.hide()
        # Proporción inicial cuando se muestre: 75/25
        self._splitter_editor.setStretchFactor(0, 3)
        self._splitter_editor.setStretchFactor(1, 1)
        v.addWidget(self._splitter_editor, 1)
        self.setCentralWidget(central)

        # ── Status bar + atajos ────────────────────────────────────────
        self._build_statusbar()
        QTimer.singleShot(6000, self._buscar_actualizacion_al_abrir)      # 🔄 (si está configurado)
        self._descarga_ia = GestorDescargaIA(self)                         # 🤖 (en segundo plano, si hace falta)
        self._voz = GestorVoz(self)                                        # 🎙 Whisper (en segundo plano, si hace falta)
        self._dictado = DictadoVoz(self)                                   # 🎙 F2: escribir hablando
        if _bool_ajuste(CLAVE_MODO_VISUAL, False):                         # ♿ (si quedó activado)
            QTimer.singleShot(1500, lambda: self.poner_modo_visual(True))
