    def _auto_crear_locaciones_desde_escenas(self) -> int:
        """Recorre las escenas del guion, extrae el nombre de locación
        de cada encabezado, y crea una `Locacion` por cada nombre único
        que NO esté ya en `documento.locaciones`.

        Retorna la cantidad de locaciones creadas.
        """
        existentes = {k.upper() for k in self.editor.documento.locaciones.keys()}
        creadas = 0
        for b in self.editor.documento.bloques:
            if b.elem != Elem.ESCENA:
                continue
            nombre = _locacion_desde_encabezado(b.texto)
            if not nombre or nombre == "SIN LOCACIÓN":
                continue
            if nombre.upper() in existentes:
                continue
            self.editor.documento.locaciones[nombre] = Locacion(nombre=nombre)
            existentes.add(nombre.upper())
            creadas += 1
        return creadas

    def _asegurar_fichas_de_personajes_del_guion(self) -> list[str]:
        """Crea una Ficha para cada PERSONAJE del guion que no tenga ya.
        Devuelve la lista de nombres NUEVOS (los que se crearon ahora).
        """
        doc = self.editor.documento
        encontrados: list[str] = []
        for b in doc.bloques:
            if b.elem == Elem.PERSONAJE:
                nom = b.texto.strip().upper().split("(")[0].strip()
                if nom and nom not in encontrados:
                    encontrados.append(nom)
        nuevos: list[str] = []
        for nom in encontrados:
            if nom not in doc.fichas:
                doc.fichas[nom] = Ficha(personaje=nom)
                nuevos.append(nom)
        return nuevos

    def _accion_centro_produccion(self) -> None:
        """Abre (o trae al frente) el Centro de Producción — la
        ventana única estilo Nova con toda la producción."""
        cp = getattr(self, "_centro_produccion", None)
        if cp is not None and cp.isVisible():
            cp._refrescar_grilla()
            cp.raise_()
            cp.activateWindow()
            return
        self._centro_produccion = VentanaCentroProduccion(self, self)
        self._centro_produccion.show()

    def _accion_fichas_personaje(self, nombre: str = "") -> None:
        self._asegurar_fichas_de_personajes_del_guion()
