    def _auto_crear_fichas_desde_guion(self) -> None:
        """Crea fichas de personajes y locaciones detectadas en el
        guion (sin duplicar). Así la Gantt, el Centro y las call
        sheets siempre ven el elenco completo, aunque nunca se
        hayan abierto las ventanas de fichas."""
        doc = self.editor.documento
        try:
            self._auto_crear_locaciones_desde_escenas()
        except Exception:
            pass
        for b in doc.bloques:
            if b.elem == Elem.PERSONAJE:
                nombre = (b.texto or "").strip().upper()
                nombre = nombre.split("(")[0].strip()
                if nombre and nombre not in doc.fichas:
                    doc.fichas[nombre] = Ficha(personaje=nombre)

    def _accion_carta_gantt(self, mostrar_tutorial: bool = False
                            ) -> None:
        # El elenco y las locaciones del guion aparecen en la Gantt
        # sin necesidad de abrir antes las fichas.
        self._auto_crear_fichas_desde_guion()
        dlg = VentanaCartaGantt(self.editor.documento, parent=self)
        # Sincronizar cambios de la Gantt con los pares conectados
        dlg.gantt_cambiada.connect(self._colab_emitir_gantt)
        if mostrar_tutorial:
            QTimer.singleShot(350, dlg, dlg._tutorial_gantt)
        dlg.exec()

    def _accion_call_list(self) -> None:
        """Abre el diálogo de Call List: correo listo para enviar al
        equipo con toda la información de una jornada."""
        VentanaCallList(self.editor.documento, self, parent=self).exec()

    def _accion_auto_tag_actores(self) -> None:
        """Recorre todos los bloques PERSONAJE y agrega automáticamente
        un tag de «Actor principal» (⭐) o «Actor secundario» (🎭)
        según cuántas veces aparece hablando cada personaje.

        Regla:
          • Si un personaje habla en >= umbral bloques distintos
            de PERSONAJE → actor_principal (⭐).
          • Si habla en menos → actor_secundario (🎭).

        El usuario elige el umbral (por defecto: 3).
        """
        doc = self.editor.documento

        # Contar apariciones únicas por personaje
        conteo: dict[str, int] = {}
        bloques_personaje: dict[str, list[int]] = {}
        for i, b in enumerate(doc.bloques):
            if b.elem == Elem.PERSONAJE and (b.texto or "").strip():
                # Normalizar: quitar (V.O.), (O.S.), (CONT'D) para
                # que el mismo actor con distintas acotaciones cuente
                # como uno solo.
                nombre_base = re.sub(
                    r"\s*\([^)]+\)\s*", " ",
                    b.texto).strip().upper()
                if not nombre_base:
                    continue
                conteo[nombre_base] = conteo.get(nombre_base, 0) + 1
                bloques_personaje.setdefault(nombre_base, []).append(i)

        if not conteo:
            # (no hay a quién etiquetar todavía: se avisa sin una ventana)
            self.statusBar().showMessage(
                "🎭 Auto-etiquetar actores: todavía no hay personajes que hablen en el guion. "
                "Cuando los escribas, esto los etiqueta solo.", 6000)
            return

        # Diálogo: umbral configurable
        n_personajes = len(conteo)
        max_apariciones = max(conteo.values())
        umbral, ok = QInputDialog.getInt(
            self, "Auto-etiquetar actores",
            f"Se encontraron <b>{n_personajes} personaje(s)</b> en el "
            f"guion.<br>"
            f"El que más habla tiene <b>{max_apariciones} "
            f"aparición(es)</b>.<br><br>"
            "Umbral para considerar un actor como <b>principal</b> "
            "(mínimo de veces que debe hablar):",
            3, 1, 100, 1)
        if not ok:
            return

        # Clasificar
        principales = {n for n, c in conteo.items() if c >= umbral}
        secundarios = {n for n, c in conteo.items() if c < umbral}

        # Agregar tags a los bloques PERSONAJE
        n_agregados = 0
        n_actualizados = 0
        for nombre, idxs in bloques_personaje.items():
            categoria = ("actor_principal" if nombre in principales
                          else "actor_secundario")
            for idx in idxs:
                b = doc.bloques[idx]
                texto = b.texto or ""
                # ¿Ya tiene un tag de actor? Si sí, actualizamos su
                # categoría. Si no, agregamos uno nuevo.
                tag_existente = None
                for t in b.tags:
                    if t.get("categoria") in ("actor_principal",
                                                "actor_secundario"):
                        tag_existente = t
                        break
                if tag_existente is not None:
                    if tag_existente["categoria"] != categoria:
                        tag_existente["categoria"] = categoria
                        n_actualizados += 1
                else:
                    # Tagear el nombre entero (o hasta el paréntesis)
                    m = re.match(r"^([^(]+)", texto)
                    if m:
                        nombre_texto = m.group(1).rstrip()
                        b.tags.append({
                            "categoria": categoria,
                            "contenido": nombre_texto,
                            "desde": 0,
                            "hasta": len(nombre_texto),
                        })
                        n_agregados += 1

        # Refrescar editor y marcar dirty
        self.editor.cargar_documento(doc)
        try:
            self._marcar_dirty()
        except Exception:
            pass

        # Resumen
        QMessageBox.information(
            self, "Auto-etiquetado completo",
            f"✅  Se procesaron <b>{n_personajes} personaje(s)</b>:"
            f"<br><br>"
            f"⭐  Actores principales: <b>{len(principales)}</b><br>"
            f"🎭  Actores secundarios: <b>{len(secundarios)}</b>"
            f"<br><br>"
            f"Se agregaron <b>{n_agregados}</b> tag(s) nuevo(s) "
            f"y se actualizaron <b>{n_actualizados}</b>.<br><br>"
            "Puedes ver los tags en el guion o en el informe de "
            "producción.")

