    def _tutorial_generar_gantt_ejemplo(self) -> None:
        """Método usado por el tutorial: puebla el proyecto con datos
        completos (locaciones con clima, fichas con actores, técnicos,
        equipamiento), crea 4 jornadas RICAS con múltiples locaciones,
        escenas, actores, y luego EXPORTA el HTML interactivo y lo abre
        directamente en el navegador para mostrar la Gantt en todo su
        esplendor."""
        doc = self.editor.documento

        # Poblar todos los datos igual que en Call Sheet
        self._tutorial_poblar_datos_ejemplo()

        escenas = segmentar_escenas(doc)
        if not escenas:
            QMessageBox.information(
                self, "No hay escenas",
                "Todavía no hay escenas en el guion. Escribe algunas "
                "escenas antes de generar el plan de rodaje.")
            return

        # Detectar locaciones en el guion agrupando escenas por lugar
        import re as _re
        agrupado: dict[str, list[int]] = {}
        actores_por_escena: dict[int, set] = {}
        for e in escenas:
            actores_por_escena[e["numero"]] = set(e["personajes"])
            enc = e["encabezado"]
            m = _re.match(
                r"^(?:INT\./?EXT\.|INT\.|EXT\.|I/E\.)\s+"
                r"(.+?)(?:\s*-\s*[^-]+)?$",
                enc.upper().strip())
            if m:
                lugar = m.group(1).strip().rstrip(" .,-").title()
            else:
                lugar = "Liceo Bicentenario (ejemplo)"
            agrupado.setdefault(lugar, []).append(e["numero"])

        # Si no había escenas suficientes, crear locaciones de ejemplo
        # variadas para mostrar una Gantt rica
        locaciones_fallback = [
            "Liceo Bicentenario (ejemplo)",
            "Sala de Profesores",
            "Patio del Colegio",
            "Casa de Michelle (interior)",
        ]
        while len(agrupado) < 3:
            for loc in locaciones_fallback:
                if loc not in agrupado:
                    agrupado[loc] = []
                    break
            if len(agrupado) >= 4:
                break

        # Asegurar que cada locación agrupada exista en doc.locaciones
        gps_por_locacion = {
            "Liceo Bicentenario (ejemplo)": "-33.0245,-71.5518",
            "Sala De Profesores": "-33.0245,-71.5518",
            "Patio Del Colegio": "-33.0250,-71.5520",
            "Pasillo Del Colegio": "-33.0245,-71.5518",
            "Casa De Michelle (Interior)": "-33.0280,-71.5600",
        }
        detalles_por_locacion = {
            "Liceo Bicentenario (ejemplo)":
                "Entrada por portón lateral. Estacionamiento en calle.",
            "Sala De Profesores":
                "Segundo piso, pasando por la biblioteca.",
            "Patio Del Colegio":
                "Grande, con árboles y bancas. Necesita permiso "
                "municipal por horario extendido.",
            "Pasillo Del Colegio":
                "Angosto, ruidoso en recreo. Prever cortes de sonido.",
            "Casa De Michelle (Interior)":
                "Casa particular. Contacto: Sra. Jiménez (dueña).",
        }
        # Precios simbólicos por locación:
        #   • Institucionales (dentro del liceo): $0 — préstamo.
        #   • Privadas (casa arrendada, comercios): aporte por
        #     electricidad, agua y molestias.
        precio_por_locacion = {
            "Liceo Bicentenario (ejemplo)": "0",
            "Sala De Profesores": "0",
            "Patio Del Colegio": "0",
            "Pasillo Del Colegio": "0",
            "Casa De Michelle (Interior)": "15000",
        }
        for lugar in agrupado.keys():
            if lugar not in (doc.locaciones or {}):
                doc.locaciones[lugar] = Locacion(
                    nombre=lugar,
                    ubicacion=f"Dirección de ejemplo — {lugar}",
                    pais="CL", region="Valparaíso",
                    ciudad="Viña del Mar",
                    gps=gps_por_locacion.get(
                        lugar, "-33.0245,-71.5518"),
                    detalles=detalles_por_locacion.get(
                        lugar, "Detalles logísticos por definir."),
                    precio_dia=precio_por_locacion.get(lugar, "0"),
                )

        # Crear jornadas: una por locación, 2-3 días cada una,
        # espaciadas correctamente
        from datetime import date, timedelta
        hoy = date.today()
        fecha_cursor = hoy + timedelta(days=14)
        nuevas_jornadas = []

        # Roles de crew para variar
        crew_variado = [
            "Carlos Ríos, Andrea Morales, Fernanda Soto, Diego Vera",
            "Andrea Morales, Fernanda Soto, Diego Vera, Cristián Rojas",
            "Carlos Ríos, Andrea Morales, Diego Vera, "
                "Cristián Rojas, Valentina Núñez",
            "Carlos Ríos, Fernanda Soto, Cristián Rojas, "
                "Valentina Núñez",
        ]
        equipo_variado = [
            "Celular del director (Samsung S22), Lente clip-on gran "
                "angular, Micrófono lavalier BOYA, Kit luces LED "
                "básico (2 paneles), Trípode para celular",
            "Celular del director (Samsung S22), Micrófono lavalier "
                "BOYA, Grabadora Zoom H1n (prestada), Kit luces LED "
                "básico (2 paneles)",
            "Celular del director (Samsung S22), Lente clip-on gran "
                "angular, Micrófono lavalier BOYA, Kit luces LED "
                "básico (2 paneles), Reflector plegable (rebote de "
                "luz), Trípode para celular",
            "Celular del director (Samsung S22), Micrófono lavalier "
                "BOYA, Trípode para celular",
        ]

        for i, (lugar, nums) in enumerate(agrupado.items()):
            dias = 3 if i % 2 == 0 else 2
            fecha_j_inicio = fecha_cursor
            fecha_j_fin = fecha_cursor + timedelta(days=dias - 1)

            actores = set()
            for n in nums:
                actores.update(actores_por_escena.get(n, set()))
            if not actores:
                actores = {"INSPECTORA GENERAL", "MICHELLE"}

            nueva = Jornada(
                nombre=f"Jornada {i+1} — {lugar}",
                fecha=fecha_j_inicio.isoformat(),
                fecha_fin=fecha_j_fin.isoformat(),
                lugar=lugar,
                hora_citacion="08:00" if i % 2 == 0 else "09:00",
                escenas=",".join(str(n) for n in nums) if nums
                    else str(i + 1),
                actores=", ".join(sorted(actores)),
                tecnicos=crew_variado[i % len(crew_variado)],
                equipamiento=equipo_variado[i % len(equipo_variado)],
                transporte="Van de producción (retiro 07:00)"
                    if i % 2 == 0 else "Vehículos propios",
                alimentacion="Coffee break 10:00 · Almuerzo 13:00"
                    if i < 2 else
                    "Catering completo (desayuno + almuerzo + once)",
                permisos=(f"Permiso municipal N° {4520 + i}-2026" if
                          "patio" in lugar.lower() or
                          "colegio" in lugar.lower() else ""),
                notas=(
                    f"Ejemplo de tutorial — {dias} días asignados. "
                    "AJUSTA a la realidad de tu producción."),
            )
            nuevas_jornadas.append(nueva)
            # Espaciar 2 días entre jornadas (para permitir descanso)
            fecha_cursor = fecha_j_fin + timedelta(days=3)

        doc.jornadas.extend(nuevas_jornadas)
        try:
            self._marcar_dirty()
        except Exception:
            pass

        # EXPORTAR HTML AUTOMÁTICAMENTE Y ABRIR EN NAVEGADOR
        try:
            gantt_temp = VentanaCartaGantt(doc, parent=self)
            html = gantt_temp._render_html()
            gantt_temp.close()
            gantt_temp.deleteLater()

            import tempfile
            from PySide6.QtGui import QDesktopServices
            from PySide6.QtCore import QUrl
            tmp = Path(tempfile.gettempdir()) / "gantt_ejemplo_tutorial.html"
            tmp.write_text(html, encoding="utf-8")
            QDesktopServices.openUrl(
                QUrl.fromLocalFile(str(tmp.absolute())))

            QMessageBox.information(
                self,
                "Carta Gantt de ejemplo — HTML interactivo",
                f"Se crearon {len(nuevas_jornadas)} jornadas de ejemplo "
                "con locaciones, cast, crew, equipamiento y logística "
                "completa.\n\n"
                "🌐 Se abrió en tu navegador el HTML INTERACTIVO de la "
                "Gantt. Puedes:\n"
                "• Filtrar por lugar, escena o actor.\n"
                "• Ver tooltips con todos los datos al pasar el mouse.\n"
                "• Ver costos por jornada y total.\n"
                "• Compartir el archivo por correo con tu equipo.\n\n"
                "⚠ Los días asignados son SOLO estimación (2-3 por "
                "locación). Ajusta a la realidad de tu producción.\n\n"
                "También puedes abrir la Gantt normal desde el botón "
                "«Carta Gantt» en la pestaña Producción.")
        except Exception as e:
            # Si falla el HTML, al menos abrir la Gantt normal
            dlg = VentanaCartaGantt(doc, parent=self)
            dlg.gantt_cambiada.connect(self._colab_emitir_gantt)
            QMessageBox.warning(
                self, "No se pudo generar el HTML",
                f"Se creó la Gantt pero no se pudo abrir el HTML "
                f"interactivo:\n{e}\n\n"
                "Puedes exportarlo desde la Gantt con el botón "
                "«Exportar HTML».")
            dlg.exec()

