    def _accion_escaleta(self) -> None:
        """Abre la ventana de escaleta y conecta el envío al guion."""
        dlg = VentanaEscaleta(self.editor.documento, parent=self)
        dlg.enviar_solicitado.connect(self._insertar_escaleta_en_guion)
        dlg.exec()

    def _insertar_escaleta_en_guion(self, puntos: list) -> None:
        """Pone cada punto de la escaleta al final del guion como una guía
        para escribir: ACCIÓN con prefijo [ESCALETA n]. (Un punto escrito
        como encabezado, «INT. …», pasa como encabezado; no se pide.)
        """
        if not puntos:
            return
        doc = self.editor.documento
        # ¿documento vacío? (un solo bloque sin texto)
        vacio = (len(doc.bloques) == 1 and not doc.bloques[0].texto.strip())
        n_guia = 0
        for punto in puntos:
            mayus = punto.upper().lstrip()
            es_escena = mayus.startswith(
                ("INT.", "EXT.", "INT/EXT", "I/E.", "INT./EXT"))
            if es_escena:
                contenido = aplicar_caso_a_texto(Elem.ESCENA, mayus)
                elem = Elem.ESCENA
            else:
                n_guia += 1
                contenido = f"[ESCALETA {n_guia}] {punto}"
                elem = Elem.ACCION
            nb = Bloque(elem=elem, texto=contenido)
            if vacio:
                doc.bloques[0] = nb
                vacio = False
            else:
                doc.bloques.append(nb)
        self.editor._rerender_completo()
        self.statusBar().showMessage(
            f"✓ {len(puntos)} punto(s) de escaleta insertados al final "
            f"del guion", 5000)

    def _accion_beatboard(self) -> None:
        """Abre la Pizarra de beats y conecta el envío al guion."""
        dlg = VentanaBeatBoard(self.editor.documento, parent=self)
        dlg.enviar_solicitado.connect(self._insertar_beats_en_guion)
        dlg.exec()

    def _tutorial_abrir_beatboard_con_ayuda(self) -> None:
        """Abre la Pizarra de beats y también su tutorial flotante. Usado
        desde el tutorial principal para asegurar que el usuario vea
        la ayuda contextual sin tener que abrirla a mano."""
        dlg = VentanaBeatBoard(self.editor.documento, parent=self)
        dlg.enviar_solicitado.connect(self._insertar_beats_en_guion)
        # Abrir tutorial flotante de la Pizarra de beats por encima
        try:
            tut = TutorialFlotante(
                "Tutorial: Pizarra de beats",
                _pasos_tutorial_beatboard(),
                parent=dlg)
            tut.show()
        except Exception:
            pass
        dlg.exec()

    def _tutorial_abrir_escaleta_con_ayuda(self) -> None:
        """Abre la Escaleta y también su tutorial flotante."""
        dlg = VentanaEscaleta(self.editor.documento, parent=self)
        dlg.enviar_solicitado.connect(
            self._insertar_escaleta_en_guion)
        try:
            tut = TutorialFlotante(
                "Tutorial: Escaleta",
                _pasos_tutorial_escaleta(),
                parent=dlg)
            tut.show()
        except Exception:
            pass
        dlg.exec()

    def _accion_editor_escenas(self) -> None:
        """Abre el editor de escenas (reordenar y borrar). Si el usuario
        confirma cambios, se reorganiza el documento entero: los bloques
        de cada escena se mueven juntos, los estados de producción se
        remapean a los nuevos números, y las jornadas actualizan sus
        listas de escenas."""
        self.editor._hist_flush()
        try:
            antes_json = documento_a_json(self.editor.documento)
        except Exception:
            antes_json = ""
        dlg = VentanaEditorEscenas(self.editor.documento, parent=self)
        if dlg.exec() == QDialog.DialogCode.Accepted:
            # Aplicar el nuevo orden al documento
            self.editor.aplicar_reorden_escenas(
                dlg.nuevo_orden(), dlg.escenas_eliminadas())
            # Reposicionar los actos según el orden visual
            secuencia = [s for s in dlg.secuencia_completa()
                         if not (s[0] == "escena"
                                 and int(s[1]) in
                                 dlg.escenas_eliminadas())]
            reordenar_actos_segun_secuencia(
                self.editor.documento, secuencia)
            self.editor._rerender_completo()
            if antes_json:
                self.editor.registrar_paso_documento(antes_json)
            self.statusBar().showMessage(
                "✓ Escenas reordenadas. Guion actualizado (Ctrl+Z lo deshace).", 5000)
        elif antes_json:
            # Cancelar no deja nada a medias (un acto insertado o renombrado)
            try:
                if documento_a_json(self.editor.documento) != antes_json:
                    viejo = documento_desde_json(antes_json)
                    for k_, v_ in vars(viejo).items():
                        setattr(self.editor.documento, k_, v_)
                    self.editor._rerender_completo()
            except Exception:
                pass

    # ── 🔄 Actualizaciones ──
    def _programa_actual(self) -> Path:
        return Path(sys.argv[0] if sys.argv and sys.argv[0].endswith(".py") else __file__).resolve()

    def _buscar_actualizacion(self, silencioso: bool = True) -> None:
        """Pregunta al servidor si hay una versión nueva (sin congelar la
        ventana). «silencioso»: al abrir el programa, solo avisa si hay."""
        if not ACTUALIZACIONES_ACTIVAS:
            return
        url = url_actualizaciones()
        if not url:
            if not silencioso:
                QMessageBox.information(self, "Actualizaciones",
                                        "Todavía no hay una dirección de actualizaciones: ponla en "
                                        "⚙ Configuración → Versión.")
            return
        trabajo = _TrabajoEnHilo(lambda _t: leer_info_actualizacion(url), self)
        self._trabajo_act = trabajo
        trabajo.listo.connect(lambda info, err: self._al_saber_actualizacion(info, err, silencioso))
        trabajo.empezar()
        if not silencioso:
            self.statusBar().showMessage("🔄 Buscando una versión nueva…", 4000)

    def _al_saber_actualizacion(self, info, err, silencioso: bool) -> None:
        settings_app().setValue(CLAVE_ULTIMA_ACTUALIZAR, date.today().isoformat())
        if err is not None:
            if not silencioso:
                QMessageBox.warning(self, "Actualizaciones", f"No se pudo revisar si hay una versión nueva:\n{err}")
            return
        if not hay_version_nueva(info):
            if not silencioso:
                QMessageBox.information(self, "Actualizaciones",
                                        f"Tienes la versión más nueva ({__version__}).")
            return
        notas = f"\n\nQué trae:\n{info['notas']}" if info.get("notas") else ""
        if getattr(sys, "frozen", False):
            # (instalado con el instalador: se baja el instalador nuevo y se instala encima)
            if info.get("instalador"):
                r = QMessageBox.question(
                    self, "Hay una versión nueva",
                    f"Hay una versión nueva de ¡Acción!: {info['version']} (tienes {__version__}).{notas}\n\n"
                    "¿Actualizar ahora? Se baja la versión nueva, se instala sola y ¡Acción! se vuelve a abrir. "
                    "Tus proyectos y tu configuración no se tocan.",
                    QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No, QMessageBox.StandardButton.Yes)
                if r == QMessageBox.StandardButton.Yes:
                    self._actualizar_instalado(info)
                return
            QMessageBox.information(self, "Hay una versión nueva",
                                    f"Hay una versión nueva: {info['version']} (tienes {__version__}).{notas}\n\n"
                                    f"Bájala de: {info['url']}")
            return
        r = QMessageBox.question(
            self, "Hay una versión nueva",
            f"Hay una versión nueva de ¡Acción!: {info['version']} (tienes {__version__}).{notas}\n\n"
            "¿Actualizar ahora? Se guarda una copia de la versión actual en la carpeta «historico» y el "
            "programa se vuelve a abrir.",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No, QMessageBox.StandardButton.Yes)
        if r == QMessageBox.StandardButton.Yes:
            self._instalar_actualizacion(info)

    def _actualizar_instalado(self, info: dict) -> None:
        """🔄 El programa instalado: baja el instalador nuevo (verificado),
        cierra ¡Acción!, lo instala en silencio y se vuelve a abrir."""
        dlg = QProgressDialog("Bajando la versión nueva…", "", 0, 100, self)
        dlg.setWindowTitle("Actualizando ¡Acción!")
        dlg.setCancelButton(None)
        dlg.setMinimumDuration(0)
        dlg.setValue(0)
        trabajo = _TrabajoEnHilo(lambda t: bajar_instalador(
            info, progreso=lambda b, tot: t.avance.emit(b, tot)), self)
        self._trabajo_act = trabajo
        trabajo.avance.connect(lambda b, tot: dlg.setValue(int(100 * b / tot)) if tot else None)

        def listo(ruta, err):
            dlg.close()
            if err is not None:
                r = QMessageBox.question(
                    self, "Actualizaciones",
                    f"No se pudo bajar la versión nueva (no cambió nada):\n{err}\n\n"
                    "¿Abrir la descarga en el navegador, para instalarla a mano?",
                    QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No, QMessageBox.StandardButton.No)
                if r == QMessageBox.StandardButton.Yes:
                    from PySide6.QtGui import QDesktopServices
                    from PySide6.QtCore import QUrl
                    QDesktopServices.openUrl(QUrl(info["instalador"]))
                return
            self._lanzar_instalador(ruta)
        trabajo.listo.connect(listo)
        trabajo.empezar()

    def _lanzar_instalador(self, ruta) -> bool:
        """Cierra ¡Acción! (si hay cambios sin guardar, primero pregunta) y
        corre el instalador nuevo en silencio; al terminar lo vuelve a abrir."""
        QMessageBox.information(
            self, "Actualizaciones",
            "✓ Se bajó la versión nueva.\n\nAhora ¡Acción! se cierra, se instala (verás una ventanita con el "
            "avance) y se vuelve a abrir sola.")
        if not self.close():
            QMessageBox.information(
                self, "Actualizaciones",
                f"No se instaló todavía. El instalador quedó en:\n{ruta}\n\nÁbrelo cuando quieras, o vuelve a "
                "⚙ Configuración → Versión → 🔄 Buscar ahora.")
            return False
        from PySide6.QtCore import QProcess
        res = QProcess.startDetached(str(ruta), ["/SILENT", "/SUPPRESSMSGBOXES", "/NORESTART",
                                                 "/CLOSEAPPLICATIONS", "/ABRIR=1"])
        ok = bool(res[0]) if isinstance(res, tuple) else bool(res)
        if not ok:
            self.show()
            QMessageBox.warning(self, "Actualizaciones", f"No se pudo abrir el instalador:\n{ruta}\n\n"
                                                         "Ábrelo con doble clic para instalar la versión nueva.")
            return False
        QApplication.quit()
        return True

    def _instalar_actualizacion(self, info: dict) -> None:
        programa = self._programa_actual()
        dlg = QProgressDialog("Bajando la versión nueva…", "", 0, 100, self)
        dlg.setWindowTitle("Actualizando ¡Acción!")
        dlg.setCancelButton(None)
        dlg.setMinimumDuration(0)
        dlg.setValue(0)
        trabajo = _TrabajoEnHilo(lambda t: instalar_actualizacion(
            info, programa, progreso=lambda b, tot: t.avance.emit(b, tot)), self)
        self._trabajo_act = trabajo
        trabajo.avance.connect(lambda b, tot: dlg.setValue(int(100 * b / tot)) if tot else None)

        def listo(copia, err):
            dlg.close()
            if err is not None:
                QMessageBox.warning(self, "Actualizaciones", f"No se instaló la versión nueva (no cambió "
                                    f"nada):\n{err}")
                return
            QMessageBox.information(self, "Actualizaciones",
                                    f"✓ Quedó instalada la versión {info['version']}.\nLa anterior está en "
                                    f"«{copia.parent.name}/{copia.name}».\n\nAhora el programa se vuelve a abrir.")
            if self.close():
                reiniciar_programa(programa)
                QApplication.quit()
        trabajo.listo.connect(listo)
        trabajo.empezar()

    def _buscar_actualizacion_al_abrir(self) -> None:
        """Una vez al día, al abrir (si hay dirección y está activado)."""
        if not ACTUALIZACIONES_ACTIVAS:
            return
        s_ = settings_app()
        if not url_actualizaciones():
            return
        if str(s_.value(CLAVE_AUTO_ACTUALIZAR, "true")).lower() in ("false", "0", "no"):
            return
        if str(s_.value(CLAVE_ULTIMA_ACTUALIZAR, "") or "") == date.today().isoformat():
            return
        self._buscar_actualizacion(silencioso=True)

    # ── 📖📖 Comparar guiones (lado a lado o en dos pantallas) ──
    def _accion_dos_guiones(self, ruta: str = "", otra_pantalla: bool = False) -> Optional["PanelSegundoGuion"]:
        """Abre otro guion al lado del principal (la pantalla se divide en
        dos), para leerlos juntos y pasar escenas o diálogos de uno al
        otro. «⧉ Otra pantalla» lo lleva a su propia ventana."""
        panel = getattr(self, "_panel2", None)
        if panel is not None:
            if not ruta:
                panel.abrir_dialogo()
                return panel
            if not panel.preguntar_guardar():
                return panel
            panel.abrir(Path(ruta))
            return panel
        if not ruta:
            ruta, _ = QFileDialog.getOpenFileName(
                self, "Comparar guiones: el otro guion", ruta_ultima_carpeta(),
                "Guiones (*.accion *.fdx *.fountain *.celtx);;Todos (*.*)")
            if not ruta:
                return None
        panel = PanelSegundoGuion(self)
        if not panel.abrir(Path(ruta)):
            panel.deleteLater()
            return None
        self._panel2 = panel
        self._zoom_antes_dos = self.editor.get_zoom_hoja()
        panel.cerrar_pedido.connect(self._cerrar_dos_guiones)
        panel.pantalla_pedida.connect(self._alternar_pantalla_dos)
        self._splitter_editor.insertWidget(1, panel)
        self._splitter_editor.setStretchFactor(1, 3)
        total = max(2, self._splitter_editor.width())
        tamanos = self._splitter_editor.sizes()
        tamanos[0] = tamanos[1] = total // 2
        self._splitter_editor.setSizes(tamanos)
        if not hasattr(self, "_t_zoom_dos"):
            self._t_zoom_dos = QTimer(self)
            self._t_zoom_dos.setSingleShot(True)
            self._t_zoom_dos.setInterval(120)
            self._t_zoom_dos.timeout.connect(self._ajustar_zoom_dos)
            self._splitter_editor.splitterMoved.connect(lambda *_a: self._t_zoom_dos.start())
        QTimer.singleShot(0, self._ajustar_zoom_dos)
        if otra_pantalla:
            QTimer.singleShot(0, self._alternar_pantalla_dos)
        self.statusBar().showMessage("📖📖 Dos guiones: selecciona en uno y «⬅ Al principal» / «Traer ➜» "
                                     "(o copia y pega, o arrastra). ⧉ Otra pantalla: en su ventana.", 6000)
        return panel

    def _ajustar_zoom_dos(self) -> None:
        """En la pantalla dividida, cada hoja cabe en su mitad."""
        panel = getattr(self, "_panel2", None)
        if panel is None:
            return
        base = float(getattr(self, "_zoom_antes_dos", 1.0) or 1.0)
        separado = panel.window() is not self
        for ed, w_ in ((self.editor, self._splitter_editor.widget(0)), (panel.editor, panel)):
            if ed is self.editor and separado:
                ed.set_zoom_hoja(base, guardar=False)
                continue
            ancho = max(px(200), w_.width() - px(40))
            z = ed.get_zoom_hoja()
            ancho_1 = ed._page_w / max(0.01, z)               # (la hoja al 100 %)
            ed.set_zoom_hoja(max(0.5, min(base, ancho / max(1.0, ancho_1))), guardar=False)

    def _alternar_pantalla_dos(self) -> None:
        """⧉ El otro guion a su propia ventana (en la segunda pantalla, si
        hay), o ⧈ de vuelta al lado del principal."""
        panel = getattr(self, "_panel2", None)
        if panel is None:
            return
        ven = getattr(self, "_ventana2", None)
        if ven is not None and ven.centralWidget() is panel:
            ven.takeCentralWidget()
            ven.hide()
            ven.deleteLater()
            self._ventana2 = None
            panel.b_pantalla.setText("⧉ Otra pantalla")
            panel.b_pantalla.setToolTip("Llevar este guion a una ventana aparte (a la segunda pantalla, si hay)")
            self._splitter_editor.insertWidget(1, panel)
            panel.show()
            total = max(2, self._splitter_editor.width())
            tamanos = self._splitter_editor.sizes()
            tamanos[0] = tamanos[1] = total // 2
            self._splitter_editor.setSizes(tamanos)
            panel._titulo()
            QTimer.singleShot(0, self._ajustar_zoom_dos)
            return
        panel.setParent(None)
        ven = VentanaSegundoGuion(panel)
        ven.juntar_pedido.connect(self._cerrar_dos_guiones_sin_preguntar)
        self._ventana2 = ven
        from PySide6.QtGui import QGuiApplication
        pantallas = QGuiApplication.screens()
        mia = self.screen()
        otra = next((sc for sc in pantallas if sc is not mia), None)
        if otra is not None:
            ven.setGeometry(otra.availableGeometry())
            ven.show()
            ven.showMaximized()
        else:
            g = (mia or QGuiApplication.primaryScreen()).availableGeometry()
            ven.setGeometry(g.x() + g.width() // 2, g.y(), g.width() // 2, g.height())
            ven.show()
        panel.show()
        panel._titulo()
        self._ajustar_zoom_dos()
        self.statusBar().showMessage("⧉ El otro guion quedó en su ventana" + (" (en la otra pantalla)" if otra
                                     else ": arrástrala a la otra pantalla") + ". «⧈ Volver al lado» lo junta.", 6000)

    def _cerrar_dos_guiones(self) -> None:
        panel = getattr(self, "_panel2", None)
        if panel is None or not panel.preguntar_guardar():
            return
        self._cerrar_dos_guiones_sin_preguntar()

    def _cerrar_dos_guiones_sin_preguntar(self) -> None:
        panel = getattr(self, "_panel2", None)
        if panel is None:
            return
        self._panel2 = None
        ven = getattr(self, "_ventana2", None)
        self._ventana2 = None
        if ven is not None:
            try:
                ven.takeCentralWidget()
                ven.hide()
                ven.deleteLater()
            except RuntimeError:
                pass
        panel.setParent(None)
        panel.deleteLater()
        self.editor.set_zoom_hoja(float(getattr(self, "_zoom_antes_dos", 1.0) or 1.0), guardar=False)

    def _accion_colaboracion(self) -> None:
        """Abre el panel de Colaboración SIN bloquear la edición (la
        conexión vive en la ventana: cerrar el panel no corta la sesión)."""
        panel = getattr(self, "_panel_colab", None)
        if panel is not None and panel.isVisible():
            panel.raise_()
            panel.activateWindow()
            return
        self._panel_colab = VentanaColaboracion(
            self.editor.documento, parent=self,
            runtime=self._colab_runtime)
        self._panel_colab.setWindowModality(Qt.WindowModality.NonModal)
        self._panel_colab.show()

    # ── 👥 La sesión: estado, menú de la luz, avisos ─────────────────

    def _texto_estado_colab(self) -> str:
        rt = self._colab_runtime
        e = rt.estado
        if e == _ColabRuntime.ON and rt.es_host:
            n = rt.n_pares
            return (f"🟢 Eres el host · IP {rt.ip_host} · "
                    f"{n} invitado{'s' if n != 1 else ''}")
        if e == _ColabRuntime.ON:
            quien = self._colab.host_nombre or rt.ip_host
            nivel = {"editar": "puedes editar", "notas": "puedes comentar",
                     "leer": "solo ver"}.get(rt.mi_nivel(), "")
            return f"🟢 En la sesión de {quien} · {nivel}"
        if e == _ColabRuntime.CONECTANDO:
            return f"🟡 Conectando con {rt.ip_host}…"
        if e == _ColabRuntime.RECONECTANDO:
            return "🟠 Se cortó la conexión: reconectando… (sigue escribiendo)"
        if e == _ColabRuntime.PERDIDA:
            return "🔴 Sin conexión con el host"
        return "⚫ Sin sesión de colaboración"

    def _menu_conexion(self) -> None:
        """Menú de la luz de conexión: estado, copiar IP, salir."""
        rt = self._colab_runtime
        menu = QMenu(self)
        menu.setStyleSheet("""
            QMenu { background: #131d2b; color: #e8edf4;
                    border: 1px solid #ff8c1a; padding: 4px; }
            QMenu::item { padding: 7px 20px; }
            QMenu::item:selected { background: #ff8c1a; color: #241203; }
            QMenu::item:disabled { color: #b0bcd2; }
            QMenu::separator { height: 1px; background: #3a4665;
                               margin: 4px 8px; }
        """)
        menu.addAction(self._texto_estado_colab()).setEnabled(False)
        menu.addSeparator()
        if rt.estado in (_ColabRuntime.ON, _ColabRuntime.RECONECTANDO,
                         _ColabRuntime.CONECTANDO):
            if rt.es_host:
                menu.addAction(f"📋  Copiar la IP ({rt.ip_host})").triggered.connect(
                    lambda: QApplication.clipboard().setText(rt.ip_host))
            menu.addAction("👥  Participantes…").triggered.connect(self._abrir_invitados)
            if rt.estado == _ColabRuntime.RECONECTANDO:
                menu.addAction("🔄  Reintentar ahora").triggered.connect(
                    rt.reconectar_ahora)
            menu.addAction("⏹  Terminar la sesión" if rt.es_host
                           else "🚪  Salir de la sesión").triggered.connect(
                self._desconectar_colab)
        else:
            menu.addAction("👥  Abrir el panel de colaboración…").triggered.connect(
                self._accion_colaboracion)
        menu.exec(self._luz_conexion.mapToGlobal(
            self._luz_conexion.rect().bottomLeft()))

    def _desconectar_colab(self, preguntar: bool = True) -> None:
        rt = self._colab_runtime
        if preguntar and rt.es_host and rt.n_pares > 0:
            r = QMessageBox.question(
                self, "Terminar la sesión",
                f"Hay {rt.n_pares} invitado(s) conectado(s). Si terminas la "
                "sesión, cada uno se queda con su copia del guion (sin "
                "título), pero ya no se sincroniza.\n\n¿Terminar la sesión?",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                QMessageBox.StandardButton.No)
            if r != QMessageBox.StandardButton.Yes:
                return
        self._colab.enviar_local()
        rt.detener()
        self.statusBar().showMessage(
            "Sesión de colaboración terminada" if rt.es_host
            else "Saliste de la sesión: el guion queda abierto aquí.", 4000)

    def _colab_ocupado(self, que: str = "abrir otro guion") -> bool:
        """Antes de cambiar de guion: en una sesión, hay que salir primero.
        True = no seguir (el usuario prefirió quedarse en la sesión)."""
        rt = self._colab_runtime
        if rt.estado == _ColabRuntime.OFF:
            return False
        r = QMessageBox.question(
            self, "👥 Estás en una sesión",
            f"Para {que} hay que "
            + ("terminar la sesión de colaboración (los invitados se quedan "
               "con su copia)." if rt.es_host else
               "salir de la sesión de colaboración (tu copia del guion de la "
               "sesión queda abierta hasta que la reemplaces).")
            + "\n\n¿" + ("Terminar" if rt.es_host else "Salir") + " y seguir?",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No)
        if r != QMessageBox.StandardButton.Yes:
            return True
        self._desconectar_colab(preguntar=False)
        return False

    def _set_luz_color(self, estado: str) -> None:
        color = {
            _ColabRuntime.OFF: "#3a4665",
            _ColabRuntime.ON: "#2bb673",
            _ColabRuntime.CONECTANDO: "#f2c94c",
            _ColabRuntime.RECONECTANDO: "#ff8c1a",
            _ColabRuntime.PERDIDA: "#c43d3d",
        }.get(estado, "#3a4665")
        self._luz_conexion.setStyleSheet(
            f"background-color: {color}; border: 1px solid #e8edf4; "
            f"border-radius: 2px;")

    def _colab_on_estado(self, estado: str) -> None:
        self._set_luz_color(estado)
        rt = self._colab_runtime
        try:
            self.lbl_conexion.setText(
                "" if estado == _ColabRuntime.OFF else self._texto_estado_colab())
            color = {"on": "#2bb673", "conectando": "#f2c94c",
                     "reconectando": "#ff8c1a"}.get(estado, "#f87171")
            self.lbl_conexion.setStyleSheet(
                f"color: {color}; font-weight: bold; font-size: 9pt; "
                "padding: 0 12px;")
        except Exception:
            pass
        if estado in (_ColabRuntime.OFF, _ColabRuntime.PERDIDA):
            if self._colab.activa:
                self._colab.terminar()
            self._aplicar_modo_invitado(False)
            try:
                self.editor.setReadOnly(bool(getattr(self, "_modo_solo_lectura", False)))
            except Exception:
                pass
            self._actualizar_titulo()
        elif estado == _ColabRuntime.ON and rt.es_host:
            self._aplicar_modo_invitado(False)
            self._actualizar_titulo()

    def _colab_on_mi_nivel_cambio(self, nivel: str) -> None:
        """El host cambió mi permiso (o lo supe al entrar)."""
        if self._colab_runtime.es_host:
            return
        self._aplicar_modo_invitado(nivel != "editar")
        texto = {
            "editar": "✎ Puedes editar todo: tus cambios llegan a todos.",
            "notas": "📝 Puedes leer y dejar notas (clic derecho en un bloque).",
            "leer": "👁 Solo puedes ver el guion.",
        }.get(nivel, "")
        if texto:
            self.statusBar().showMessage(texto, 6000)
        self._colab_on_estado(self._colab_runtime.estado)

    def _colab_on_fui_pateado(self, motivo: str) -> None:
        QMessageBox.warning(
            self, "🚪 Fuera de la sesión",
            f"{motivo}.\n\nEl guion queda abierto en tu computador (sin "
            "título): si quieres conservar tu copia, guárdala.")

    def _colab_on_fallo(self, motivo: str) -> None:
        QMessageBox.warning(self, "👥 No se pudo entrar a la sesión", motivo)

    def _colab_on_rechazado(self, msg: dict) -> None:
        motivo = str(msg.get("motivo", "") or "El host no aceptó la conexión.")
        if msg.get("pin"):
            pin, ok = QInputDialog.getText(
                self, "🔒 Guion con PIN", motivo + "\n\nPIN del archivo:",
                QLineEdit.EchoMode.Password)
            if ok and pin:
                rt = self._colab_runtime
                self._colab.unirse(rt._destino[0], rt._nombre_local, pin)
            return
        QMessageBox.warning(self, "👥 No se pudo entrar a la sesión", motivo)

    def _colab_on_sesion_terminada(self, motivo: str) -> None:
        QMessageBox.information(
            self, "👥 La sesión terminó",
            f"{motivo}\n\nEl guion queda abierto aquí, sin título: si quieres "
            "conservar tu copia, guárdala (Archivo → Guardar).")

    def _entrar_a_sesion_como_invitado(self, doc, msg: dict, pin: str) -> None:
        """(lo llama la sesión) El guion del host reemplaza al de aquí."""
        self.editor.cargar_documento(doc)
        self._archivo_actual = None
        self._ejemplo_abierto = ""
        self._pin_plano_sesion = pin or ""
        self._modo_solo_lectura = bool(msg.get("host_solo_lectura", False))
        self._aplicar_modo_solo_lectura()
        self._doc_dirty = False
        self._actualizar_titulo()
        host = msg.get("host") or "el host"
        self.statusBar().showMessage(
            f"👥 Entraste a la sesión de {host}: lo que escriban todos se ve "
            "al instante.", 6000)

    def _colab_respaldar_copia(self) -> str:
        """Guarda una copia del guion de aquí (antes de que el de la sesión
        lo reemplace). Devuelve la ruta, o "" si no se pudo."""
        try:
            from datetime import datetime as _dt
            base = re.sub(r'[\\/:*?"<>|]+', "", (self.editor.documento.titulo or "").strip())
            ruta = self._carpeta_backup() / (
                f"{(base or 'guion')[:50]} - mi copia de la sesion "
                f"{_dt.now().strftime('%Y-%m-%d_%H-%M-%S')}.accion")
            ruta.write_text(documento_a_json(self.editor.documento,
                                             self._pin_plano_sesion), encoding="utf-8")
            return str(ruta)
        except Exception:
            return ""

    def _colab_datos_cambiaron(self, cambiados: list) -> None:
        """Llegaron cambios del resto del proyecto (fichas, Carta Gantt…)."""
        nombres = {
            "fichas": "fichas de personajes", "locaciones": "locaciones",
            "jornadas": "Carta Gantt", "tecnicos": "equipo técnico",
            "equipamiento": "equipamiento", "planos": "planos",
            "storyboard_plantas": "storyboard", "storyboard_hojas": "storyboard",
            "gastos": "presupuesto", "pagos": "presupuesto",
            "presupuesto_fondos": "presupuesto", "beats": "Pizarra de beats",
            "escaleta": "escaleta", "premisa": "premisa",
            "documentos_legales": "contratos", "fichas_escenas": "fichas de escenas",
            "titulo": "portada"}
        vistos = []
        for c in cambiados:
            n = nombres.get(c, "")
            if n and n not in vistos:
                vistos.append(n)
        if vistos:
            self.statusBar().showMessage(
                "📡 Cambios de la sesión en: " + ", ".join(vistos[:4]), 3500)
        self.editor.viewport().update()
        self._refrescar_panel_notas_si_visible()

    def _flush_buffer_colab(self) -> None:
        """Enter, un formato, guardar: lo pendiente sale ya (y en el guion,
        lo próximo es otro paso de Ctrl+Z)."""
        if getattr(self, "_colab", None) is not None and self._colab.activa:
            self._colab.cortar_paso()
            self._colab.enviar_datos_locales()

    def _colab_emitir_gantt(self) -> None:
        """La Carta Gantt cambió: que salga ya (no esperar la revisión)."""
        if getattr(self, "_colab", None) is not None and self._colab.activa:
            self._colab.enviar_datos_locales()

    def _aplicar_modo_invitado(self, activar: bool) -> None:
        """Sin permiso de edición: la hoja en solo lectura; el ribbon sigue
        habilitado para abrir y VER todo (cada diálogo entra en solo
        lectura). Con permiso de notas: clic derecho → nota."""
        self._modo_invitado = activar
        try:
            self.editor.setReadOnly(
                activar or bool(getattr(self, "_modo_solo_lectura", False)))
        except Exception:
            pass
        try:
            if hasattr(self, "ribbon"):
                self.ribbon.setEnabled(True)
        except Exception:
            pass
        try:
            if (activar and self._colab_runtime.mi_nivel() == "notas"
                    and hasattr(self, "_panel_notas")):
                self._panel_notas.show()
                self._panel_notas.refrescar()
        except Exception:
            pass

    def _toggle_panel_notas(self) -> None:
        """Muestra/oculta el panel lateral de notas."""
        if self._panel_notas.isVisible():
            self._panel_notas.hide()
        else:
            self._panel_notas.refrescar()
            self._panel_notas.show()

    def _abrir_invitados(self) -> None:
        """Abre la ventana de administración de invitados
        (VentanaSesionActual). Si no hay sesión activa, avisa."""
        rt = self._colab_runtime
        if rt.estado == _ColabRuntime.OFF:
            QMessageBox.information(
                self, "Participantes",
                "No estás en ninguna sesión: abre el panel de Colaboración "
                "para iniciar una como host o unirte a otra.")
            return
        # Reusar si ya está abierta
        vent = getattr(self, "_vent_invitados", None)
        if vent is not None:
            try:
                vent.raise_()
                vent.activateWindow()
                return
            except Exception:
                pass
        self._vent_invitados = VentanaSesionActual(rt, parent=self)
        self._vent_invitados.setAttribute(
            Qt.WidgetAttribute.WA_DeleteOnClose)
        self._vent_invitados.destroyed.connect(
            lambda: setattr(self, "_vent_invitados", None))
        self._vent_invitados.show()

    def _refrescar_panel_notas_si_visible(self) -> None:
        """Se llama cuando cambia el documento para mantener el panel
        de notas al día. Solo refresca si está visible (ahorra trabajo)."""
        if hasattr(self, "_panel_notas") and self._panel_notas.isVisible():
            self._panel_notas.refrescar()

    def _accion_comentarios(self) -> None:
        """Atajo directo: abre los Comentarios del equipo sin pasar por
        el panel principal de Colaboración."""
        DialogoComentarios(self.editor.documento, parent=self).exec()

    # ── Handlers de los botones del ribbon (pestañas restantes) ────────

    def _accion_portada(self) -> None:
        """Abre el diálogo de Portada con título/autor/contacto/fecha."""
        DialogoPortada(self.editor.documento, parent=self).exec()

    def _accion_fuente(self) -> None:
        """Cambia la fuente de la hoja. Muestra TODAS las fuentes
        instaladas; avisa si la elegida no es monoespaciada
        (Qt lo dice con fixedPitch(), sin cargar la fuente de
        prueba — evita los errores de fuentes bitmap heredadas
        como Fixedsys / 8514oem). Persiste entre sesiones."""
        actual = QFont(fuente_editor_familia(), FONT_SIZE_PT)
        ok, fuente = QFontDialog.getFont(
            actual, self, "Fuente de la hoja")
        if not ok:
            return
        if not fuente.fixedPitch():
            r = QMessageBox.question(
                self, "Fuente no monoespaciada",
                f"«{fuente.family()}» no es monoespaciada. El "
                "formato de guion profesional usa fuentes de "
                "ancho fijo (Courier, Consolas, Cascadia, etc.). "
                "Con esta fuente la paginación puede "
                "desalinearse.\n\n¿Aplicarla igual?")
            if r != QMessageBox.StandardButton.Yes:
                return
        settings_app().setValue("fuente_editor", fuente.family())
        self.editor.refrescar_fuente()
        self.statusBar().showMessage(
            f"🅰 Fuente de la hoja: {fuente.family()}", 4000)

    def _accion_max_paginas(self) -> None:
        """Define el número máximo de páginas estimadas del guion."""
        actual = int(getattr(self.editor.documento, "max_paginas", 120))
        valor, ok = QInputDialog.getInt(
            self, "Máximo de páginas",
            "Límite estimado de páginas del guion:",
            actual, 1, 999)
        if ok:
            self.editor.documento.max_paginas = valor
            self.statusBar().showMessage(
                f"Máximo de páginas: {valor}", 3000)

    def _accion_numeracion(self, modo: str) -> None:
        """Cambia el modo de numeración del guion, o bloquea/desbloquea
        los números de escena (guion de rodaje)."""
        doc = self.editor.documento
        if modo == "bloquear":
            self._bloquear_numeracion()
            return
        if modo == "desbloquear":
            self._desbloquear_numeracion()
            return
        doc.numeracion = modo
        etiquetas = {"escena": "por escena", "bloque": "por bloque",
                     "ninguna": "desactivada"}
        self.statusBar().showMessage(
            f"Numeración {etiquetas.get(modo, modo)}", 3000)
        self._marcar_dirty()
        self.editor.viewport().update()

    def _accion_dictar(self) -> None:
        """🎙 El botón «Dictar»: escucha hasta que la persona calla (igual
        que tocar F2 una vez)."""
        d = getattr(self, "_dictado", None)
        if d is None:
            return
        if not voz_descargada():
            self._abrir_configuracion_voz()
            return
        d.escuchar(hasta_silencio=True)

    def _abrir_configuracion_voz(self) -> None:
        self._accion_configuracion("voz")

    # ── ♿ Modo discapacidad visual ──
    def _accion_tutorial_voz(self) -> bool:
        """♿ El tutorial por voz (activa el modo discapacidad visual)."""
        d = getattr(self, "_dictado", None)
        return bool(d is not None and d.tutorial.empezar())

    def _accion_modo_visual(self) -> None:
        d = getattr(self, "_dictado", None)
        self.poner_modo_visual(not (d is not None and d.modo_visual))

    def poner_modo_visual(self, si: bool, anunciar: bool = True) -> None:
        """Todo el programa por voz (menos lo visual): F2 funciona en
        cualquier ventana, lo que se pide se lee en voz alta y lo que no es
        una orden directa lo interpreta el Profesor Claqueta."""
        d = getattr(self, "_dictado", None)
        if d is None:
            return
        d.modo_visual = bool(si)
        d.escuchar_en_todo(bool(si))
        settings_app().setValue(CLAVE_MODO_VISUAL, bool(si))
        self.ribbon.marcar_modo_visual(si)
        if not si:
            d.voz.decir("Modo discapacidad visual desactivado.")
            self.statusBar().showMessage("♿ Modo discapacidad visual: desactivado", 4000)
            return
        self.statusBar().showMessage("♿ Modo discapacidad visual: F2 y dices qué hacer («ayuda» para escuchar "
                                     "las órdenes)", 8000)
        g = getattr(self, "_voz", None)
        if not voz_descargada():
            if g is not None and g.estado not in ("descargando", "pausado"):
                g.retomar()
            d.voz.decir("Modo discapacidad visual activado. Necesita el reconocimiento de voz, que se está "
                        "preparando en segundo plano: te aviso con un sonido cuando F2 ya funcione.")
            return
        settings_app().setValue(CLAVE_VOZ_ACTIVA, True)
        if g is not None:
            g.servidor.iniciar()
        if anunciar:
            d.voz.decir("Modo discapacidad visual activado. Aprieta F2, habla y suelta. Di «ayuda» para "
                        "escuchar todo lo que puedes pedir" + (", o «tutorial» para aprender paso a paso." if not
                                                                _bool_ajuste(CLAVE_TUTORIAL_VOZ_FIN, False)
                                                                else "."))

    def _accion_leer_voz_alta(self) -> None:
        """🔊 Abre el lector en voz alta (no modal: se puede seguir
        mirando el guion mientras lee)."""
        if not any((b.texto or "").strip()
                   for b in self.editor.documento.bloques):
            QMessageBox.information(self, "Voz alta", "No hay nada para leer.")
            return
        ant = getattr(self, "_lector_voz", None)
        if ant is not None:
            try:
                ant.detener()
                ant.close()
            except Exception:
                pass
        self._lector_voz = LectorVozAlta(self, parent=self)
        if self._lector_voz.listo:
            self._lector_voz.show()

    def iniciar_director_ia(self, host: str, modelo: str, num_ctx: int, pedido: dict,
                            alcance: int = 2) -> Optional["DirectorGuionIA"]:
        """🎬 La IA escribe un guion usando el programa a la vista."""
        d_ = getattr(self, "_director_ia", None)
        if d_ is not None and d_.activo():
            return None
        d_ = DirectorGuionIA(self, host, modelo, num_ctx, pedido, alcance)
        d_.terminado.connect(self._director_ia_termino)
        if not d_.iniciar():
            d_.panel.deleteLater()
            d_.deleteLater()
            return None
        self._director_ia = d_
        return d_

    def _director_ia_termino(self, res: dict) -> None:
        a = getattr(self, "_asesor", None)
        if a is None:
            return
        if res.get("ok"):
            inf = ""
            if res.get("archivos"):
                c_ = Path(res.get("carpeta", ""))
                inf = (f"<br>📑 El guion en PDF y los informes ({len(res['archivos'])} archivos) quedaron en "
                       f"<a href='{html.escape(c_.as_uri())}'>Documentos → ¡Acción! → Informes → "
                       f"{html.escape(c_.name)}</a>.")
            a._agregar("asesor", f"✍ Listo: <b>«{html.escape(str(res.get('titulo', '')))}»</b>, con "
                                 f"{res.get('escenas', 0)} escenas y {res.get('personajes', 0)} personajes. Está "
                                 "marcado como escrito con IA: revísalo, corrígelo y hazlo tuyo. ¿Lo revisamos "
                                 f"juntos con «📖 ¿Cómo va mi historia?»?{inf}", es_html=True)
        else:
            a._agregar("asesor", "■ Me detuve" + (f" ({html.escape(res['error'])})" if res.get("error") else "")
                       + ". Lo que alcancé a escribir quedó en el proyecto: puedes seguir tú.", es_html=True)

    def abrir_guion_ia(self, doc) -> bool:
        """✍ Abre el guion que escribió la IA como un proyecto nuevo, sin
        guardar (si el guion actual tiene cambios, pregunta antes)."""
        if self._colab_ocupado(): return False
        actual = self.editor.documento
        tiene = len(actual) > 1 or (len(actual) == 1 and actual[0].texto.strip())
        if tiene and self._doc_dirty:
            r = QMessageBox.question(
                self, "Guion escrito con IA",
                "El guion que escribió la IA se abre como un proyecto nuevo.\n\n"
                "¿Guardar antes los cambios del guion actual?",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No
                | QMessageBox.StandardButton.Cancel, QMessageBox.StandardButton.Yes)
            if r == QMessageBox.StandardButton.Cancel:
                return False
            if r == QMessageBox.StandardButton.Yes:
                self._accion_guardar()
                if self._doc_dirty:
                    return False
        if not doc.tecnicos:
            doc.tecnicos = crear_tecnicos_plantilla()
        if not doc.equipamiento:
            doc.equipamiento = crear_equipamiento_plantilla()
        self.editor.cargar_documento(doc)
        self._pin_plano_sesion = ""
        self._pin_desbloqueado = True
        self._modo_solo_lectura = False
        self._archivo_actual = None
        self._doc_dirty = True
        self._actualizar_titulo()
        self._aplicar_modo_solo_lectura()
        self.statusBar().showMessage("✍ Guion escrito con IA: proyecto nuevo, sin guardar (Ctrl+S)", 8000)
        return True

    # ── 🔗 Ir a una parte del programa (enlaces de la IA, voz) ──
    def destinos_programa(self) -> dict:
        """destino → (qué hace, nombre para decirlo)."""
        return {
            "fichas_personajes": (self._accion_fichas_personaje, "las fichas de personajes"),
            "fichas_escenas": (self._accion_fichas_escenas, "las fichas de escenas"),
            "fichas_locaciones": (self._accion_fichas_locacion, "las fichas de locaciones"),
            "fichas_tecnicos": (self._accion_fichas_tecnico, "las fichas del equipo técnico"),
            "fichas_equipamiento": (self._accion_fichas_equipamiento, "las fichas de equipamiento"),
            "pizarra": (self._accion_beatboard, "la Pizarra de beats"),
            "escaleta": (self._accion_escaleta, "la Escaleta"),
            "editor_escenas": (self._accion_editor_escenas, "el Editor de escenas"),
            "tags": (self._accion_abrir_menu_tags, "el gestor de tags"),
            "centro_produccion": (self._accion_centro_produccion, "el Centro de Producción"),
            "gantt": (self._accion_carta_gantt, "la Carta Gantt"),
            "call_sheet": (self._accion_call_list, "la hoja de citación"),
            "planos": (self._accion_planos, "la lista de planos"),
            "storyboard": (self._accion_storyboard, "el storyboard"),
            "presupuesto": (self._accion_presupuesto, "el presupuesto"),
            "contratos": (self._accion_contratos, "los contratos y seguros"),
            "portada": (self._accion_portada, "la portada"),
            "duracion": (self._accion_duracion, "la duración y versión corta"),
            "corrector": (self._accion_corrector, "el corrector ortográfico"),
            "voz_alta": (self._accion_leer_voz_alta, "la lectura en voz alta"),
            "estado_produccion": (self._accion_estado_produccion, "el estado de producción"),
            "versiones": (self._accion_versiones, "las versiones guardadas"),
            "configuracion": (self._accion_configuracion, "la configuración"),
        }

    def ir_a_destino(self, destino: str) -> bool:
        """Abre la parte del programa nombrada: «fichas_personajes»,
        «ficha:CAMILA», «informe:narrativo», «escena:3»…"""
        destino = str(destino or "")
        try:
            if destino.startswith("ficha:"):
                self._accion_fichas_personaje(destino[6:])
                return True
            if destino.startswith("informe:"):
                self._accion_informe(destino[8:])
                return True
            if destino.startswith("escena:"):
                n = int(destino[7:])
                ini = [i for i, b in enumerate(self.editor.documento.bloques) if b.elem == Elem.ESCENA]
                if 1 <= n <= len(ini):
                    self.editor._mover_cursor_a(ini[n - 1], 0)
                    self.editor.ensureCursorVisible()
                    self.activateWindow()
                    self.editor.setFocus()
                    return True
                return False
            fn = self.destinos_programa().get(destino, (None, ""))[0]
            if fn is None:
                return False
            fn()
            return True
        except Exception as ex:
            self.statusBar().showMessage(f"No se pudo abrir: {ex}", 5000)
            return False

    def _accion_ia(self, clave: str) -> None:
        """✨ Los botones de la pestaña IA."""
        clave = str(clave or "")
        if clave in ("historia", "escena", "pendientes"):
            self._accion_asesor(clave)
        elif clave.startswith("personaje:"):
            a = self._accion_asesor()
            QTimer.singleShot(50, lambda: a.pedir_personaje(clave[10:]))
        elif clave == "escribir_aqui":
            a = self._accion_asesor()
            QTimer.singleShot(50, a.escribir_aqui)
        elif clave == "escribir_nuevo":
            a = self._accion_asesor()
            QTimer.singleShot(50, a.escribir_guion)
        elif clave == "modelos":
            a = self._accion_asesor()
            QTimer.singleShot(50, a._elegir_y_bajar)
        elif clave.startswith("injerencia:"):
            settings_app().setValue(CLAVE_IA_INJERENCIA, clave[11:])
            self.statusBar().showMessage("🎚 Injerencia de la IA: " + dict(NIVELES_INJERENCIA_IA).get(
                clave[11:], "").split(":")[0].strip(), 5000)
        elif clave.startswith("cambios:"):
            if poner_modo_cambios_ia(clave[8:], self):
                self.statusBar().showMessage("✏ Fichas: " + dict(MODOS_CAMBIOS_IA).get(clave[8:], "").split(":")[0]
                                             .strip(), 5000)
        elif clave == "tutorial":
            self.abrir_tutorial_ia()
        elif clave == "config_ia":
            self._accion_configuracion("asesor")
        elif clave == "config_voz":
            self._accion_configuracion("voz")

    def abrir_tutorial_ia(self) -> "TutorialIA":
        """🎓 El tutorial de la IA, integrado: al lado del Profesor
        Claqueta, y después por cada lugar donde la IA cambia cosas."""
        a = self._accion_asesor()
        t = getattr(self, "_tutorial_ia", None)
        if t is not None and t.isVisible():
            t.raise_()
            t.activateWindow()
            return t
        t = TutorialIA(self, a)
        self._tutorial_ia = t
        t.show()
        t.raise_()
        return t

    def _accion_asesor(self, pregunta: str = "") -> "VentanaAsesor":
        """🤖 Abre el Profesor Claqueta (una sola ventana, no modal). «pregunta»:
        «pendientes», «historia» o «escena» la hace de inmediato."""
        a = getattr(self, "_asesor", None)
        if a is None:
            a = VentanaAsesor(self, parent=self)
            self._asesor = a
        a.show()
        a.raise_()
        a.activateWindow()
        accion = {"pendientes": a.pedir_pendientes, "historia": a.pedir_historia,
                  "escena": a.pedir_escena}.get(pregunta)
        if accion is not None:
            QTimer.singleShot(50, accion)
        return a

    def _accion_planos(self) -> None:
        """🎥 Lista de planos (shot list). Sin guion también: con las
        escenas propias del storyboard («＋ Escena»)."""
        VentanaPlanos(self, parent=self).exec()

    def _accion_luces_a_equipamiento(self) -> int:
        """💡 Las luces de las plantas de luces pasan al equipamiento."""
        doc = self.editor.documento
        pedidos = equipos_de_luces_sb(doc)
        if not pedidos:
            QMessageBox.information(
                self, "Luces", "Todavía no hay luces en las plantas de las escenas. Se ponen "
                "en 🎞 Storyboard → un cuadro → pestaña 💡 Luces (es trabajo de dirección y "
                "fotografía).")
            return 0
        nuevos, act = agregar_luces_a_equipamiento(doc, pedidos)
        if nuevos or act:
            self._marcar_dirty()
        lineas = "<br>".join(f"• {html.escape(x['nombre'])} × {x['cantidad']} "
                             f"<span style='color:#8fa1b8'>(escena {', '.join(x['escenas'])})</span>"
                             for x in pedidos[:14])
        QMessageBox.information(
            self, "Luces al equipamiento",
            f"Las plantas de luces piden:<br>{lineas}<br><br>"
            + (f"Se agregaron <b>{nuevos}</b> ítem(s) al equipamiento"
               + (f" y se actualizaron {act}" if act else "") + ". Ahora puedes ponerles "
               "proveedor y valor de arriendo en sus fichas." if nuevos or act else
               "Ya estaban todas en el equipamiento."))
        return nuevos + act

