    def _accion_storyboard(self) -> None:
        """🎞 Storyboard (los planos, en 3D). No hace falta un guion: sin
        escenas escritas, el storyboard tiene las suyas («＋ Escena»)."""
        VentanaStoryboard(self, parent=self).exec()

    def abrir_storyboard_de_escena(self, n: int, mostrar: bool = True):
        """🎞 Clic derecho en un encabezado → el storyboard de esa escena, listo
        para armarlo: si aún no tiene cuadros, se crean desde el guion (uno por
        cada PLANO escrito, o uno para la escena), cada uno con su cámara en
        3D; se abre en su primer cuadro."""
        doc = self.editor.documento
        if not isinstance(getattr(doc, "planos", None), list):
            doc.planos = []
        nuevos = 0
        if not any(isinstance(p, dict) and int(p.get("escena", 0) or 0) == n for p in doc.planos):
            nuevos = crear_cuadros_desde_guion(doc, {n})
            if nuevos:
                try:
                    preparar_3d_storyboard(doc, {n})
                except Exception:
                    pass
                self._marcar_dirty()
        w = VentanaStoryboard(self, parent=self, escena_inicial=n)
        cuadros = cuadros_ordenados(doc, {n})
        if cuadros:
            w.abrir_editor(cuadros[0]["id"])
            ed3 = getattr(w, "editor3d", None)
            if nuevos and ed3 is not None and hasattr(ed3, "avisar"):
                ed3.avisar(f"✨ {nuevos} cuadro(s) desde el guion para esta escena, cada uno con su cámara. "
                           "RePág / AvPág: el anterior y el siguiente.", 7000)
        if mostrar:
            w.exec()
        return w

