    def _accion_dialogo_doble(self) -> None:
        ok, msg = self.editor.alternar_dialogo_doble()
        if ok:
            self._marcar_dirty()
            self.statusBar().showMessage(msg, 4000)
        else:
            QMessageBox.information(self, "Diálogo doble", msg)

    def _bloquear_numeracion(self) -> None:
        doc = self.editor.documento
        if getattr(doc, "numeracion_bloqueada", False):
            r = QMessageBox.question(
                self, "Numeración bloqueada",
                "La numeración ya está bloqueada. ¿Fijar también los "
                "números de las escenas nuevas (12A, 12B…) tal como "
                "están ahora?")
            if r != QMessageBox.StandardButton.Yes:
                return
        else:
            r = QMessageBox.question(
                self, "Bloquear numeración",
                "Cada escena conservará su número aunque agregues o "
                "borres escenas.<br><br>Las escenas nuevas se numerarán "
                "con letra según la anterior (<b>12A</b>, <b>12B</b>…), "
                "como en un guion de rodaje: así el plan de rodaje y "
                "los planos siguen calzando.<br><br>¿Bloquear ahora?")
            if r != QMessageBox.StandardButton.Yes:
                return
        nums = numeros_de_escena(doc.bloques,
                                 getattr(doc, "numeracion_bloqueada", False))
        for i, n in nums.items():
            doc.bloques[i].numero = n
        doc.numeracion_bloqueada = True
        self._marcar_dirty()
        self.editor.viewport().update()
        self.statusBar().showMessage(
            f"🔒 Numeración bloqueada ({len(nums)} escenas)", 4000)

    def _desbloquear_numeracion(self) -> None:
        doc = self.editor.documento
        if not getattr(doc, "numeracion_bloqueada", False):
            self.statusBar().showMessage(
                "La numeración no estaba bloqueada", 3000)
            return
        r = QMessageBox.question(
            self, "Desbloquear numeración",
            "Las escenas se volverán a numerar 1, 2, 3… en orden. Los "
            "números con letra (12A…) desaparecen.<br><br>¿Continuar?")
        if r != QMessageBox.StandardButton.Yes:
            return
        for b in doc.bloques:
            b.numero = ""
        doc.numeracion_bloqueada = False
        self._marcar_dirty()
        self.editor.viewport().update()
        self.statusBar().showMessage("🔓 Numeración en orden 1, 2, 3…", 4000)

    def _accion_parrafo(self, modo: str) -> None:
        """Aplica alineación o restablece el formato del bloque
        actual. Modos: 'izq', 'centro', 'der', 'reset'."""
        cursor = self.editor.textCursor()
        qblock = cursor.block()
        if not qblock.isValid():
            return
        if modo == "reset":
            # Restablecer: re-aplicar el formato canónico del tipo
            idx, _ = self.editor._posicion_logica()
            if 0 <= idx < len(self.editor.documento):
                self.editor._reformatear_bloque(idx)
                self.statusBar().showMessage(
                    "Formato del bloque restaurado", 3000)
            return
        # Alineación
        from PySide6.QtGui import QTextBlockFormat
        alineaciones = {
            "izq":    Qt.AlignmentFlag.AlignLeft,
            "centro": Qt.AlignmentFlag.AlignHCenter,
            "der":    Qt.AlignmentFlag.AlignRight,
        }
        bf = qblock.blockFormat()
        bf.setAlignment(alineaciones.get(modo, Qt.AlignmentFlag.AlignLeft))
        c2 = QTextCursor(qblock)
        c2.setBlockFormat(bf)
        etiqueta = {
            "izq": "izquierda", "centro": "centrado", "der": "derecha"
        }.get(modo, modo)
        self.statusBar().showMessage(
            f"Bloque alineado a la {etiqueta}", 3000)

    def _accion_copiar_bloque(self) -> None:
        """Copia el texto del bloque actual al portapapeles."""
        cursor = self.editor.textCursor()
        if cursor.hasSelection():
            texto = cursor.selectedText().replace("\u2029", "\n")
        else:
            cursor.select(cursor.SelectionType.BlockUnderCursor)
            texto = cursor.selectedText().replace("\u2029", "\n").strip()
        QApplication.clipboard().setText(texto)
        self.statusBar().showMessage(
            f"Copiado: {len(texto)} caracteres", 2500)

    def _accion_pegar_bloque(self) -> None:
        """Pega el contenido del portapapeles como texto plano en la
        posición actual del cursor."""
        texto = QApplication.clipboard().text()
        if not texto:
            self.statusBar().showMessage(
                "El portapapeles está vacío", 2500)
            return
        cursor = self.editor.textCursor()
        cursor.insertText(texto)
        self.statusBar().showMessage(
            f"Pegado: {len(texto)} caracteres", 2500)

