    def _accion_imprimir(self) -> None:
        """Muestra una VISTA PREVIA de impresión con zoom, navegación
        por páginas y botón «Imprimir» integrado. El usuario puede
        revisar cómo va a quedar antes de mandarlo a la impresora."""
        qdoc = guardar_documento_qt_para_export(
            self.editor.documento,
            self.editor._margen_izq_chars,
            self.editor._margen_der_chars,
        )
        printer = QPrinter(QPrinter.PrinterMode.HighResolution)
        tam_map = {
            TamañoHoja.CARTA:  QPageSize.PageSizeId.Letter,
            TamañoHoja.A4:     QPageSize.PageSizeId.A4,
            TamañoHoja.OFICIO: QPageSize.PageSizeId.Legal,
        }
        printer.setPageSize(QPageSize(tam_map.get(self.editor.tamaño_hoja(),
                                                  QPageSize.PageSizeId.Letter)))
        # Orientación general elegida en Formato → Orientación. (Las
        # páginas sueltas en horizontal solo se aplican al exportar PDF:
        # la impresora recibe un único formato para todo el documento.)
        if getattr(self.editor.documento, "orientacion_general",
                   "vertical") == "horizontal":
            printer.setPageOrientation(QPageLayout.Orientation.Landscape)

        # Diálogo de impresión NATIVO de Windows: impresora,
        # páginas, copias y orientación con la vista del sistema.
        dlg = QPrintDialog(printer, self)
        dlg.setWindowTitle("Imprimir guion")
        try:
            if dlg.exec() == QPrintDialog.DialogCode.Accepted:
                qdoc.print_(printer)
                self.statusBar().showMessage(
                    "🖨 Guion enviado a la impresora", 3000)
        except Exception as e:
            QMessageBox.critical(self, "Imprimir", f"Error:\n{e}")

    # ─── Marca de agua / corrector / autor ────────────────────────────

    def _accion_orientacion(self) -> None:
        """Configura la orientación del PDF/impresión: todo el
        documento en horizontal, o solo páginas específicas."""
        doc = self.editor.documento
        actual_gen = getattr(doc, "orientacion_general", "vertical")
        actual_esp = getattr(doc, "paginas_horizontales", []) or []
        dlg = QDialog(self)
        dlg.setWindowTitle("📐  Orientación del papel")
        dlg.setMinimumWidth(px(460))
        v = QVBoxLayout(dlg)
        expl = QLabel(
            "Elige cómo se exportará e imprimirá tu guion. La "
            "hoja del editor sigue siendo vertical — esto solo "
            "afecta al PDF y a la impresión. Las páginas sueltas en "
            "horizontal se aplican al exportar PDF (la impresora usa "
            "una sola orientación para todo). Los números de página "
            "son los que se imprimen en la esquina; la portada no "
            "cuenta.")
        expl.setWordWrap(True)
        expl.setStyleSheet("color: #8fa1b8;")
        # (con escalas fraccionarias, el alto calculado podía quedar corto)
        expl.setMinimumHeight(expl.heightForWidth(px(430)) + px(6))
        v.addWidget(expl)
        rb_v = QRadioButton("📄  Todas las páginas VERTICALES "
                            "(estándar de guion)")
        rb_h = QRadioButton("📃  Todas las páginas HORIZONTALES")
        rb_m = QRadioButton("🔀  Vertical, con páginas específicas "
                            "en horizontal:")
        rb_v.setChecked(actual_gen == "vertical" and not actual_esp)
        rb_h.setChecked(actual_gen == "horizontal")
        rb_m.setChecked(bool(actual_esp) and actual_gen == "vertical")
        v.addWidget(rb_v); v.addWidget(rb_h); v.addWidget(rb_m)
        ed = QLineEdit()
        ed.setPlaceholderText("Ej: 3, 7, 12-14")
        ed.setText(", ".join(str(p) for p in actual_esp))
        v.addWidget(ed)
        ayuda = QLabel(
            "💡 Útil para storyboards, plantas de cámara o "
            "tablas anchas en medio del guion.")
        ayuda.setStyleSheet("color: #8fa1b8; font-size: 9pt;")
        ayuda.setWordWrap(True)
        v.addWidget(ayuda)
        hb = QHBoxLayout(); hb.addStretch()
        cancel = QPushButton("Cancelar")
        ok = QPushButton("✓ Aplicar")
        ok.setProperty("primario", True); ok.setStyle(ok.style())
        cancel.clicked.connect(dlg.reject)
        ok.clicked.connect(dlg.accept)
        hb.addWidget(cancel); hb.addWidget(ok)
        v.addLayout(hb)
        if dlg.exec() != QDialog.DialogCode.Accepted:
            return
        if rb_h.isChecked():
            doc.orientacion_general = "horizontal"
            doc.paginas_horizontales = []
        elif rb_m.isChecked():
            doc.orientacion_general = "vertical"
            doc.paginas_horizontales = self._parsear_paginas(
                ed.text())
        else:
            doc.orientacion_general = "vertical"
            doc.paginas_horizontales = []
        self._marcar_dirty()
        n = len(doc.paginas_horizontales)
        if doc.orientacion_general == "horizontal":
            msg = "Todo el documento en horizontal"
        elif n:
            msg = f"Vertical, con {n} página(s) en horizontal"
        else:
            msg = "Todas las páginas verticales"
        self.statusBar().showMessage(f"📐 {msg}", 4000)

    def _parsear_paginas(self, texto: str) -> list[int]:
        """Convierte '3, 7, 12-14' en [3, 7, 12, 13, 14]."""
        out: set[int] = set()
        for parte in (texto or "").replace(";", ",").split(","):
            parte = parte.strip()
            if not parte:
                continue
            if "-" in parte:
                try:
                    a, b = parte.split("-", 1)
                    a, b = int(a.strip()), int(b.strip())
                    for k in range(min(a, b), max(a, b) + 1):
                        if k > 0:
                            out.add(k)
                except ValueError:
                    continue
            else:
                try:
                    k = int(parte)
                    if k > 0:
                        out.add(k)
                except ValueError:
                    continue
        return sorted(out)

