    def _accion_corrector_ortografia_dialog(self) -> None:
        """Abre el corrector ortográfico interactivo (F7) — estilo Word."""
        # Asegurarnos de que el corrector esté activo
        if not corrector_activo():
            activar_corrector(True)
            if hasattr(self.editor, "_ortografia_hl"):
                self.editor._ortografia_hl.rehighlight()
        # Verificar diccionario
        if not cargar_diccionario_es():
            ruta = ruta_diccionario()
            QMessageBox.warning(
                self, "Diccionario no disponible",
                "No se encontró el diccionario español.\n\n"
                "Coloca «es_palabras.txt.gz» en:\n"
                f"  {ruta.parent}\n\n"
                "También se busca en las subcarpetas: sistema/, "
                "diccionarios/, recursos/, data/, resources/.")
            return
        DialogoCorrectorOrtografico(self.editor, parent=self).exec()

    def _accion_corrector(self) -> None:
        # Toggle del corrector
        activar_corrector(not corrector_activo())
        if corrector_activo():
            cargar_diccionario_es()  # forzar carga (puede tardar 1-2 seg)
            n = len(cargar_diccionario_es())
            if n == 0:
                # Mostrar la ruta esperada real para que el usuario sepa
                # dónde poner el archivo.
                ruta = ruta_diccionario()
                QMessageBox.warning(
                    self, "Corrector ortográfico",
                    "No se encontró el diccionario español.\n\n"
                    f"Colocá el archivo «es_palabras.txt.gz» en:\n"
                    f"  {ruta.parent}\n\n"
                    "También busca en las subcarpetas: "
                    "sistema/, diccionarios/, recursos/, data/, "
                    "resources/.",
                )
                activar_corrector(False)
                return
            # Forzar re-highlight de todo el documento
            if hasattr(self.editor, "_ortografia_hl"):
                self.editor._ortografia_hl.rehighlight()
            self.statusBar().showMessage(
                f"✓ Corrector activado ({n:,} palabras)".replace(",", "."),
                4000,
            )
        else:
            # Limpiar los subrayados al desactivar
            if hasattr(self.editor, "_ortografia_hl"):
                self.editor._ortografia_hl.rehighlight()
            self.statusBar().showMessage("Corrector desactivado", 3000)

