    def _al_clickear_icono(self, idx_bloque: int, _categoria: str) -> None:
        if not (0 <= idx_bloque < len(self.editor.documento)):
            return
        bloque = self.editor.documento[idx_bloque]
        dlg = DialogoVerTagsBloque(bloque, parent=self)
        dlg.exec()
        self.editor.viewport().update()

    def _accion_guia(self) -> None:
        """Muestra una guía rápida con atajos y comandos básicos.
        El manual completo se distribuye como PDF aparte junto con
        el programa."""
        # Antes era un QMessageBox: con tanto texto quedaba más alto
        # que una pantalla HD. Ahora es un diálogo con scroll.
        from PySide6.QtWidgets import QTextBrowser
        dlg = QDialog(self)
        dlg.setWindowTitle("📖 Guía rápida de ¡Acción!")
        v = QVBoxLayout(dlg)
        v.setContentsMargins(px(14), px(14), px(14), px(14))
        visor = QTextBrowser()
        visor.setOpenExternalLinks(True)
        visor.setStyleSheet(
            "QTextBrowser { background: #131d2b; color: #e8edf4; "
            "border: 1px solid #26344a; border-radius: 8px; "
            "padding: 10px; font-size: 10pt; }")
        visor.setHtml(self._html_guia_rapida())
        v.addWidget(visor, 1)
        fila = QHBoxLayout()
        fila.addStretch()
        b_ok = QPushButton("Entendido")
        b_ok.setDefault(True)
        b_ok.clicked.connect(dlg.accept)
        fila.addWidget(b_ok)
        v.addLayout(fila)
        dlg.resize(*tam_ventana(520, 680))
        dlg.exec()

