# ═══════════════════════════════════════════════════════════════════════
# §10  ENTRY POINT
# ═══════════════════════════════════════════════════════════════════════

# ── 🩹 Registro de errores: si algo falla, el programa sigue abierto y
#    el detalle queda anotado en %LOCALAPPDATA%\Accion\registro_de_errores.txt ──

_REGISTRO_ERRORES: dict = {"archivo": None, "ruta": None, "ultimo_aviso": 0.0}


def ruta_registro_errores() -> Path:
    return carpeta_datos_ia_de_siempre() / "registro_de_errores.txt"


def instalar_registro_de_errores(ruta: Optional[Path] = None, mostrar: bool = True) -> Path:
    """Anota los errores (con su detalle técnico) en un archivo de texto y
    avisa sin cerrar el programa. También deja anotado un cierre brusco
    (faulthandler), para poder encontrar su causa."""
    import faulthandler
    import platform
    import threading
    import traceback
    ruta = Path(ruta) if ruta else ruta_registro_errores()
    try:
        ruta.parent.mkdir(parents=True, exist_ok=True)
        if ruta.exists() and ruta.stat().st_size > 1_000_000:      # (solo lo último)
            ruta.write_text(ruta.read_text(encoding="utf-8", errors="ignore")[-200_000:],
                            encoding="utf-8")
        f = open(ruta, "a", encoding="utf-8", buffering=1)
    except OSError:
        return ruta
    try:
        import PySide6
        v_qt = PySide6.__version__
    except Exception:
        v_qt = "?"
    f.write(f"\n=== ¡Acción! {__version__} · {datetime.now():%Y-%m-%d %H:%M:%S} · "
            f"{platform.platform()} · Python {platform.python_version()} · PySide6 {v_qt}\n")
    _REGISTRO_ERRORES.update(archivo=f, ruta=ruta)
    try:
        faulthandler.enable(file=f, all_threads=True)
    except Exception:
        pass

    def gancho(tipo, valor, tb) -> None:
        if issubclass(tipo, KeyboardInterrupt):
            sys.__excepthook__(tipo, valor, tb)
            return
        texto = "".join(traceback.format_exception(tipo, valor, tb))
        try:
            f.write(f"\n--- {datetime.now():%H:%M:%S} error ---\n{texto}")
            f.flush()
        except Exception:
            pass
        try:
            if sys.__stderr__ is not None:
                sys.__stderr__.write(texto)
        except Exception:
            pass
        if mostrar:
            avisar_error_registrado(texto)
    sys.excepthook = gancho
    threading.excepthook = lambda a: gancho(a.exc_type, a.exc_value, a.exc_traceback)
    return ruta


def avisar_error_registrado(texto: str) -> None:
    """Un aviso que NO cierra el programa (a lo más uno cada 30 s)."""
    import time as _t
    app = QApplication.instance()
    if app is None or _t.time() - _REGISTRO_ERRORES["ultimo_aviso"] < 30:
        return
    _REGISTRO_ERRORES["ultimo_aviso"] = _t.time()
    ruta = _REGISTRO_ERRORES.get("ruta") or ruta_registro_errores()
    ultima = (texto.strip().splitlines() or [""])[-1][:200]
    try:
        mb = QMessageBox(app.activeWindow())
        mb.setWindowTitle("¡Acción! — algo falló")
        mb.setIcon(QMessageBox.Icon.Warning)
        mb.setText("<b>Algo falló, pero ¡Acción! sigue abierto.</b> Conviene guardar tu "
                   "trabajo ahora (Ctrl+S).")
        mb.setInformativeText(
            f"El detalle quedó anotado en:<br><code>{html.escape(str(ruta))}</code><br><br>"
            "Si se repite, guarda ese archivo (o una captura de este aviso) y anota qué estabas "
            "haciendo: con eso se encuentra la causa y se arregla.<br><br>"
            f"<small>{html.escape(ultima)}</small>")
        b_carpeta = mb.addButton("📂 Abrir la carpeta", QMessageBox.ButtonRole.ActionRole)
        b_seguir = mb.addButton("Seguir", QMessageBox.ButtonRole.AcceptRole)
        mb.setEscapeButton(b_seguir)              # (la X y Esc la cierran; no frena el salir)
        mb.setModal(False)
        mb.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose, True)
        b_carpeta.clicked.connect(lambda: abrir_enlace_externo(Path(ruta).parent.as_uri()))
        mb.show()
        _REGISTRO_ERRORES["aviso"] = mb
    except Exception:
        pass


def main() -> None:
    instalar_registro_de_errores()
    app = QApplication(sys.argv)
    app.setApplicationName("¡Acción!")
    app.setOrganizationName("Gabriel González Vilches")
    # Perfil de pantalla (§0.5): densidad según el monitor + filtro que
    # adapta hojas de estilo y tamaños de ventana. Debe ir ANTES de
    # crear cualquier ventana.
    app._ajuste_pantalla = preparar_app_para_pantalla(app)
    # 🎨 Recién instalado: tema Nova con hoja blanca
    aplicar_tema_de_instalacion()
    # Cargar el último skin que el usuario eligió (default: claro)
    tema_guardado = settings_app().value("tema_visual", "nova")
    app.setStyleSheet(escalar_qss(
        TEMAS_DISPONIBLES.get(tema_guardado, TEMA_NOVA)))

    # Rueda del mouse: no cambia combos sin foco (clic primero).
    _filtro_rueda = FiltroRuedaCombos(app)
    app.installEventFilter(_filtro_rueda)
    # Temas reales: ventanas creadas tras un cambio de tema se
    # traducen al vuelo desde su estilo Nova canónico.
    _traductor_temas = TraductorTemas(app)
    app.installEventFilter(_traductor_temas)
    global TEMA_ACTUAL
    TEMA_ACTUAL = str(settings_app().value("tema_visual", "nova"))
    if TEMA_ACTUAL not in PALETAS:
        TEMA_ACTUAL = "nova"

    # Botones estándar de Qt en español («Sí», «No», «Cancelar»,
    # «Aceptar»…): sin esto los cuadros de pregunta decían «Yes / No».
    try:
        from PySide6.QtCore import QTranslator, QLibraryInfo, QLocale
        _trad_qt = QTranslator(app)
        if _trad_qt.load(QLocale(QLocale.Language.Spanish), "qtbase", "_",
                         QLibraryInfo.path(
                             QLibraryInfo.LibraryPath.TranslationsPath)):
            app.installTranslator(_trad_qt)
            app._trad_qt = _trad_qt
    except Exception:
        pass

    app.setWindowIcon(icono_app())
    ventana = VentanaPrincipal()
    ventana.setWindowIcon(icono_app())
    if TEMA_ACTUAL != "nova":
        ventana._aplicar_tema(TEMA_ACTUAL)
    elif hoja_oscura_activa():
        ventana._aplicar_hoja_configurada()
    ventana.showMaximized()
    # 🎨 ¿Cambiar el tono visual? Se ofrece la primera vez y una vez cada 15 aperturas
    n_inicio = contar_inicio()
    preguntar_tema = debe_preguntar_tema(n_inicio)

    # Doble clic en un .accion (o «Abrir con» ¡Acción!): se abre ese archivo
    archivo_inicial = next((a for a in sys.argv[1:] if not a.startswith("-") and Path(a).is_file()), "")
    if archivo_inicial:
        ventana._accion_abrir(archivo_inicial)
    # Pantalla de inicio (a menos que el usuario la haya ocultado). Trae el
    # 🎨 tema: cuando toca ofrecerlo, ahí se resalta (sin otra ventana); si la
    # pantalla de inicio no se muestra, se ofrece con su aviso chico.
    con_inicio = not archivo_inicial and not settings_app().value("bienvenida_oculta", False, type=bool)
    if preguntar_tema and not con_inicio:
        ventana.preguntar_tema_inicio(n_inicio)
    if con_inicio:
        if preguntar_tema:
            settings_app().setValue(CLAVE_TEMA_PREGUNTADO, int(n_inicio))
        ventana.mostrar_pantalla_inicio(destacar_tema=preguntar_tema)
    sys.exit(app.exec())


if __name__ == "__main__":
    main()
